-- VFX (ModuleScript) — ReplicatedStorage.Shared.VFX
-- Client-only effects library. Every client renders every move locally, so
-- the server only ever sends "who cast what, aimed where". No asset IDs are
-- needed: everything is built from parts, Highlights (for the toon outline),
-- ParticleEmitters with built-in textures, and Motor6D poses.

local Players = game:GetService("Players")
local RunService = game:GetService("RunService")
local TweenService = game:GetService("TweenService")
local Debris = game:GetService("Debris")
local SoundService = game:GetService("SoundService")

local Config = require(script.Parent:WaitForChild("QuirkConfig"))
local SpikeLayouts = require(script.Parent:WaitForChild("SpikeLayouts"))

local VFX = {}
local Effects = {}

---------------------------------------------------------------------------
-- Custom animations (Config.Animations). Your own character plays them (and
-- Roblox replicates that to everyone); every client skips the built-in pose
-- for that move so the two never fight.
---------------------------------------------------------------------------

local Anim = Config.Animations or {}
local trackCache = setmetatable({}, { __mode = "k" }) -- [Animator] = { [id] = AnimationTrack }
local poseBlockedUntil = setmetatable({}, { __mode = "k" }) -- [character] = os.clock()
local playCounts = setmetatable({}, { __mode = "k" }) -- [AnimationTrack] = plays so far

-- A slot is "rbxassetid://123" or { Id, Start, Length, Speed }. Returns a
-- normalised table, or nil when the slot is empty.
local function slotInfo(slot)
	if type(slot) == "string" then
		return slot ~= "" and { Id = slot } or nil
	elseif type(slot) == "table" and type(slot.Id) == "string" and slot.Id ~= "" then
		return slot
	end
	return nil
end

-- Configured clips are made for one rig type (Config.Animations.Rig); other
-- rigs keep the procedural motion instead of freezing in place.
local function rigMatches(char)
	local hum = char and char:FindFirstChildOfClass("Humanoid")
	if not hum then
		return false
	end
	local want = Anim.Rig
	return not want or want == "" or hum.RigType.Name == want
end

-- Which configured animation (if any) belongs to this effect, and how long
-- the procedural motion should stay out of its way
local function animationFor(effectId, data)
	if effectId == "Punch" then
		return slotInfo(Anim.M1 and Anim.M1[data.Count or 1]), 0.45
	elseif effectId == "Dash" then
		local kind = data.Kind == "Side" and "Right" or data.Kind or "Front"
		return slotInfo(Anim.Dash and Anim.Dash[kind]), 0.4
	elseif effectId == "SuperLeap" then
		return slotInfo(Anim.Leap), 1.2
	elseif effectId == "SuperLand" or effectId == "ColoradoLand" then
		return slotInfo(Anim.Land), 0.6
	elseif effectId == "UltActivate" then
		return slotInfo(Anim.Ult and Anim.Ult[data.Quirk or ""]), 1.2
	elseif effectId == "Hit" then
		return slotInfo(Anim.Hit), 0.4
	elseif effectId == "Guard" then
		return nil, 0 -- held for as long as the guard is up (Effects.Guard)
	elseif effectId == "Parry" or effectId == "GuardBreak" then
		return slotInfo(Anim[effectId]), 0.6
	elseif effectId == "MuscleForm" and not data.Alt then
		return nil, 0 -- powering down isn't the flex
	end
	return slotInfo(Anim.Moves and Anim.Moves[effectId]), 1.6
end

-- Play an animation on a character (cached per Animator). `id` may be a slot
-- table (Start / Length / Speed are honoured). Returns the track.
function VFX.PlayAnimation(char, id, opts)
	opts = opts or {}
	local info = slotInfo(id)
	local hum = char and char:FindFirstChildOfClass("Humanoid")
	local animator = hum and hum:FindFirstChildOfClass("Animator")
	if not animator or not info then
		return nil
	end
	local cache = trackCache[animator] or {}
	trackCache[animator] = cache
	local track = cache[info.Id]
	if not track then
		local animation = Instance.new("Animation")
		animation.AnimationId = info.Id
		local ok, loaded = pcall(function()
			return animator:LoadAnimation(animation)
		end)
		if not ok or not loaded then
			warn("[VFX] couldn't load animation " .. tostring(info.Id))
			return nil
		end
		track = loaded
		track.Priority = opts.Priority or Enum.AnimationPriority.Action
		track.Looped = opts.Looped == true
		cache[info.Id] = track
	end
	track:Play(opts.Fade or 0.08, 1, info.Speed or opts.Speed or 1)
	if info.Start and info.Start > 0 then
		track.TimePosition = info.Start
	end
	-- slots can share a clip (Bodybuilder is both Muscle Form and Plus Ultra),
	-- so only the latest play's timer may stop it
	playCounts[track] = (playCounts[track] or 0) + 1
	if info.Length then
		local playing, count = track, playCounts[track]
		task.delay(info.Length, function()
			if playCounts[playing] == count and playing.IsPlaying then
				playing:Stop(0.25)
			end
		end)
	end
	return track
end

function VFX.StopAnimation(char, id)
	local info = slotInfo(id)
	local hum = char and char:FindFirstChildOfClass("Humanoid")
	local animator = hum and hum:FindFirstChildOfClass("Animator")
	local cache = animator and trackCache[animator]
	local track = cache and info and cache[info.Id]
	if track and track.IsPlaying then
		track:Stop(0.2)
	end
end

local folder = Instance.new("Folder")
folder.Name = "LocalVFX"
folder.Parent = workspace
VFX.Folder = folder

-- Screen hooks (set by QuirkClient to the HUD functions)
VFX.Hooks = {
	Flash = function(_color, _time) end,
	Dim = function(_amount, _time) end,
	SpeedLines = function(_time) end,
	Letterbox = function(_on, _title, _subtitle, _color) end,
	Callout = function(_text, _color) end,
}

local rng = Random.new()
local UP = Vector3.new(0, 1, 0)

local FIRE = {
	Color3.fromRGB(255, 246, 180),
	Color3.fromRGB(255, 210, 60),
	Color3.fromRGB(255, 152, 30),
	Color3.fromRGB(255, 96, 24),
}
local ICE_TIP = Color3.fromRGB(222, 244, 255)
-- (round 81) the anime's ice palette (sampled from the Sports Festival
-- frames): near-white lit faces, a desaturated steel-blue shadow half and a
-- dark teal ink line. Opaque ice: the cel shading is painted on, not glass.
-- (more tones - deep crevice, fresh break, frost, the spine's glow - are on
-- IceKit.PAL)
local ICE_BASE = Color3.fromRGB(112, 148, 178) -- (the shadow half)
local ICE_MID = Color3.fromRGB(198, 224, 242) -- (sheets, blocks: the lit body)
local ICE_TOP = Color3.fromRGB(226, 242, 252) -- (the lit half)
local ICE_OUTLINE = Color3.fromRGB(36, 84, 116)
local WIND = Color3.fromRGB(245, 250, 255)
local EXHAUST = Color3.fromRGB(110, 180, 255)
local EXHAUST_CORE = Color3.fromRGB(232, 244, 255)
local FLAME_OUTLINE = Color3.fromRGB(196, 64, 8)
local GOLD = Color3.fromRGB(255, 212, 64)
local STEAM = Color3.fromRGB(236, 236, 240)

---------------------------------------------------------------------------
-- Utilities
---------------------------------------------------------------------------

local function rand(a, b)
	return rng:NextNumber(a, b)
end

local function newPart(size, cf, color, material, shape, parent)
	local p = Instance.new("Part")
	p.Anchored = true
	p.CanCollide = false
	p.CanQuery = false
	p.CanTouch = false
	p.CastShadow = false
	p.TopSurface = Enum.SurfaceType.Smooth
	p.BottomSurface = Enum.SurfaceType.Smooth
	if shape then
		p.Shape = shape
	end
	p.Size = size
	p.CFrame = cf
	p.Color = color
	p.Material = material or Enum.Material.SmoothPlastic
	p.Parent = parent or folder
	return p
end

local function tween(obj, t, props, style, dir, delayTime)
	-- (round 87) the director camera's slow motion (VFX.Director, set while
	-- it's on): an effect started in it plays that much slower, and holds
	-- still in its freeze frame
	local slow = VFX.Slow
	if slow then
		t, delayTime = slow.stretch(t, delayTime)
	end
	local tw = TweenService:Create(
		obj,
		TweenInfo.new(t, style or Enum.EasingStyle.Quad, dir or Enum.EasingDirection.Out, 0, false, delayTime or 0),
		props
	)
	tw:Play()
	if slow then
		slow.track(tw, obj)
	end
	return tw
end

local function cleanup(obj, t)
	-- (round 87) ...and lingers as long as its slowed tweens
	local slow = VFX.Slow
	if slow and slow.cleanup(obj, t) then
		return
	end
	Debris:AddItem(obj, t)
end

-- A Model with a Highlight gives every part inside a cel-shaded outline.
local function outlineModel(outlineColor)
	local m = Instance.new("Model")
	m.Name = "FX"
	m.Parent = folder
	local h = Instance.new("Highlight")
	h.FillTransparency = 1
	h.OutlineTransparency = 0
	h.OutlineColor = outlineColor or Color3.fromRGB(30, 16, 8)
	h.DepthMode = Enum.HighlightDepthMode.Occluded
	h.Adornee = m
	h.Parent = m
	return m, h
end

local function charParts(char)
	if not char or not char.Parent then
		return nil, nil
	end
	return char:FindFirstChild("HumanoidRootPart"), char:FindFirstChildOfClass("Humanoid")
end

local function flatten(v, root)
	local f = typeof(v) == "Vector3" and Vector3.new(v.X, 0, v.Z) or Vector3.zero
	if f.Magnitude < 0.05 then
		f = root and Vector3.new(root.CFrame.LookVector.X, 0, root.CFrame.LookVector.Z) or Vector3.new(0, 0, -1)
	end
	return f.Unit
end

local function characterList()
	local list = { folder }
	for _, plr in Players:GetPlayers() do
		if plr.Character then
			table.insert(list, plr.Character)
		end
	end
	local dummies = workspace:FindFirstChild("Dummies")
	if dummies then
		table.insert(list, dummies)
	end
	local doubles = workspace:FindFirstChild("TwiceClones") -- (round 69)
	if doubles then
		table.insert(list, doubles)
	end
	local raid = workspace:FindFirstChild("NomuRaid") -- (round 71)
	if raid then
		table.insert(list, raid)
	end
	local debris = workspace:FindFirstChild("MapDebris")
	if debris then
		table.insert(list, debris)
	end
	return list
end

local rayParams = RaycastParams.new()
rayParams.FilterType = Enum.RaycastFilterType.Exclude

local function groundRay(pos, depth)
	rayParams.FilterDescendantsInstances = characterList()
	return workspace:Raycast(pos + Vector3.new(0, 3, 0), Vector3.new(0, -(depth or 60), 0), rayParams)
end

local function groundPoint(pos)
	local hit = groundRay(pos, 40)
	return hit and hit.Position or (pos - Vector3.new(0, 3, 0))
end

local function isGrounded(root)
	rayParams.FilterDescendantsInstances = characterList()
	return workspace:Raycast(root.Position, Vector3.new(0, -7, 0), rayParams) ~= nil
end

local function face(root, dir)
	local flat = Vector3.new(dir.X, 0, dir.Z)
	if flat.Magnitude < 0.05 then
		return
	end
	root.CFrame = CFrame.lookAt(root.Position, root.Position + flat)
end

-- Local-only movement helpers (the caster owns their own physics).
-- Forces are strong but finite: an unlimited push into another body (or a
-- wall) is what flings characters across the map.
local function moverForce(root, perMass)
	local ok, mass = pcall(function()
		return root.AssemblyMass
	end)
	return math.max(ok and mass or 0, 1) * perMass
end

local function dash(root, velocity, duration)
	local att = Instance.new("Attachment")
	att.Name = "DashAttachment"
	att.Parent = root
	local lv = Instance.new("LinearVelocity")
	lv.Attachment0 = att
	lv.MaxForce = moverForce(root, 6000)
	lv.RelativeTo = Enum.ActuatorRelativeTo.World
	lv.VectorVelocity = velocity
	lv.Parent = root
	cleanup(lv, duration)
	cleanup(att, duration)
	return function()
		lv:Destroy()
		att:Destroy()
	end
end

-- A short, infinitely strong LinearVelocity beats the Humanoid's ground
-- controller; once it is removed the character keeps the momentum.
local function launch(root, _hum, velocity)
	dash(root, velocity, 0.12)
	task.delay(0.12, function()
		if root.Parent then
			root.AssemblyLinearVelocity = velocity
		end
	end)
end

local function limb(char, r15Name, r6Name)
	return char:FindFirstChild(r15Name) or char:FindFirstChild(r6Name)
end

local function handPos(char, right)
	local hand = limb(char, right and "RightHand" or "LeftHand", right and "Right Arm" or "Left Arm")
	if hand then
		return (hand.CFrame * CFrame.new(0, -hand.Size.Y / 2, 0)).Position
	end
	local root = char:FindFirstChild("HumanoidRootPart")
	return root and root.Position or Vector3.zero
end

local function addTrail(part, color, lifetime, width)
	local a0 = Instance.new("Attachment")
	a0.Position = Vector3.new(0, width / 2, 0)
	a0.Parent = part
	local a1 = Instance.new("Attachment")
	a1.Position = Vector3.new(0, -width / 2, 0)
	a1.Parent = part
	local trail = Instance.new("Trail")
	trail.Attachment0 = a0
	trail.Attachment1 = a1
	trail.Color = ColorSequence.new(color, Color3.new(1, 1, 1))
	trail.Transparency = NumberSequence.new(0.1, 1)
	trail.LightEmission = 1
	trail.Lifetime = lifetime
	trail.FaceCamera = true
	trail.Parent = part
	return function(after)
		task.delay(after or 0, function()
			-- the part may already be gone (e.g. a thrown projectile)
			pcall(function()
				trail.Enabled = false
			end)
			task.wait(lifetime)
			for _, obj in { trail, a0, a1 } do
				pcall(obj.Destroy, obj)
			end
		end)
	end
end

---------------------------------------------------------------------------
-- Sound: layered cues from Config.Sounds (see the notes there)
---------------------------------------------------------------------------

do -- Sound: its helpers stay local to this block (Luau allows 200 locals per scope)
	local Audio = Config.Audio or {}
	local sfxGroup = SoundService:FindFirstChild("QuirkSFX")
	if not sfxGroup then
		sfxGroup = Instance.new("SoundGroup")
		sfxGroup.Name = "QuirkSFX"
		sfxGroup.Parent = SoundService
	end
	sfxGroup.Volume = Audio.Volume or 1

	local voices = 0
	local lastPlayed = {}

	local function pickNumber(v, default)
		if type(v) == "table" then
			local a, b = v[1] or default, v[2] or v[1] or default
			return a + (b - a) * rng:NextNumber()
		end
		return type(v) == "number" and v or default
	end

	-- a cue is a plain id string, a single layer table, or a list of layers
	local function cueLayers(cue)
		if type(cue) == "string" then
			return cue ~= "" and { { Id = cue } } or nil
		elseif type(cue) == "table" then
			if cue.Id ~= nil then
				return { cue }
			end
			return #cue > 0 and cue or nil
		end
		return nil
	end

	-- Id can be a list of takes; each play picks one at random. A take is an id
	-- string, or { Id = "...", Start = n } when takes start at different points.
	local function pickTake(layer)
		local id, start = layer.Id, layer.Start
		if type(id) == "table" then
			local take = id[rng:NextInteger(1, math.max(#id, 1))]
			if type(take) == "table" then
				id, start = take.Id, take.Start or start
			else
				id = take
			end
		end
		return id, start
	end

	local function layerIds(layer)
		if type(layer.Id) ~= "table" then
			return { layer.Id }
		end
		local ids = {}
		for _, take in ipairs(layer.Id) do
			table.insert(ids, type(take) == "table" and take.Id or take)
		end
		return ids
	end

	local function playLayer(layer, parent, gain, range)
		local id, start = pickTake(layer)
		if type(id) ~= "string" or id == "" then
			return
		end
		if voices >= (Audio.MaxVoices or 48) then
			return
		end
		local sound = Instance.new("Sound")
		sound.SoundId = id
		sound.Volume = math.clamp(pickNumber(layer.Volume, 0.6) * gain, 0, 8)
		sound.PlaybackSpeed = math.max(pickNumber(layer.Speed, 1), 0.05)
		sound.RollOffMode = Enum.RollOffMode.InverseTapered
		sound.RollOffMinDistance = layer.Near or 14
		sound.RollOffMaxDistance = range
		sound.SoundGroup = sfxGroup
		if layer.Distort then
			local fx = Instance.new("DistortionSoundEffect")
			fx.Level = layer.Distort
			fx.Parent = sound
		end
		-- (round 77) Eq = { low, mid, high } in dB: Roblox's equaliser on the layer
		if type(layer.Eq) == "table" then
			local eq = Instance.new("EqualizerSoundEffect")
			eq.LowGain = layer.Eq[1] or 0
			eq.MidGain = layer.Eq[2] or 0
			eq.HighGain = layer.Eq[3] or 0
			eq.Parent = sound
		end
		-- (round 77) Peak: start just before the file's loudest moment - each
		-- machine measures where that is (the take's Start until it has)
		if layer.Peak and VFX.VC then
			local shape = VFX.VC.shapes[id]
			if shape and shape.Peak then
				start = math.max(shape.Peak - (layer.PreRoll or 0.06), 0)
			else
				VFX.VC.measure(id)
			end
		end
		if start then
			sound.TimePosition = start
		end
		sound.Parent = parent
		voices += 1
		local done = false
		local function finish()
			if not done then
				done = true
				voices -= 1
				sound:Destroy()
			end
		end
		sound.Ended:Connect(finish)
		-- (round 81) FadeIn: it rises out of silence over its first FadeIn
		-- seconds (a bed looping in under the last play dying away)
		if layer.FadeIn and layer.FadeIn > 0 then
			local full = sound.Volume
			sound.Volume = 0
			tween(sound, layer.FadeIn, { Volume = full }, Enum.EasingStyle.Sine, Enum.EasingDirection.InOut)
		end
		sound:Play()
		if start and not sound.IsLoaded then
			-- a file that's still downloading restarts from 0 once it loads
			sound.Loaded:Once(function()
				if not done then
					sound.TimePosition = start
				end
			end)
		end
		if layer.Length and layer.Fade then
			-- (round 78) Fade: its last Fade seconds die away (Sine), so a long
			-- tail sinks under the music instead of stopping
			local fade = math.clamp(layer.Fade, 0.05, layer.Length)
			task.delay(layer.Length - fade, function()
				if not done then
					tween(sound, fade, { Volume = 0 }, Enum.EasingStyle.Sine, Enum.EasingDirection.Out)
					task.wait(fade + 0.02)
					finish()
				end
			end)
		elseif layer.Length then
			task.delay(layer.Length, function()
				if not done then
					tween(sound, 0.15, { Volume = 0 })
					task.wait(0.16)
					finish()
				end
			end)
		end
		task.delay(12, finish) -- never leak a voice if Ended doesn't fire
	end

	-- Download every configured sound up front so the first punch isn't silent
	task.spawn(function()
		local seen, list = {}, {}
		for _, cue in Config.Sounds or {} do
			for _, layer in ipairs(cueLayers(cue) or {}) do
				for _, id in ipairs(layerIds(layer)) do
					if type(id) == "string" and id ~= "" and not seen[id] then
						seen[id] = true
						local sound = Instance.new("Sound")
						sound.SoundId = id
						table.insert(list, sound)
					end
				end
			end
		end
		pcall(function()
			game:GetService("ContentProvider"):PreloadAsync(list)
		end)
	end)

	-- name: a key of Config.Sounds. pos: world position (nil = flat, for UI).
	-- volume: gain on top of the cue's own layer volumes (1 = as configured).
	function VFX.PlaySound(name, pos, volume)
		local cue = Config.Sounds and Config.Sounds[name]
		local layers = cueLayers(cue)
		if not layers then
			return
		end
		local now = os.clock()
		local gap = type(cue) == "table" and cue.Gap or 0.02
		if lastPlayed[name] and now - lastPlayed[name] < gap then
			return -- a dozen hits in one frame shouldn't stack a dozen sounds
		end
		lastPlayed[name] = now
		local range = type(cue) == "table" and cue.Range or 400
		local parent = SoundService
		if typeof(pos) == "Vector3" then
			local att = Instance.new("Attachment")
			att.Name = "Sound_" .. name
			att.WorldPosition = pos
			att.Parent = workspace.Terrain
			cleanup(att, 12)
			parent = att
		end
		local gain = volume or 1
		for _, layer in ipairs(layers) do
			if layer.Delay and layer.Delay > 0 then
				task.delay(layer.Delay, playLayer, layer, parent, gain, range)
			else
				playLayer(layer, parent, gain, range)
			end
		end
	end
end

---------------------------------------------------------------------------
-- Camera shake + screen hooks
---------------------------------------------------------------------------

local shakeAmount, shakeUntil, shakeLength = 0, 0, 1

RunService:BindToRenderStep("QuirkCameraShake", Enum.RenderPriority.Camera.Value + 1, function()
	local now = os.clock()
	if now >= shakeUntil then
		return
	end
	local k = shakeAmount * ((shakeUntil - now) / shakeLength)
	local cam = workspace.CurrentCamera
	cam.CFrame = cam.CFrame
		* CFrame.new(rand(-k, k) * 0.12, rand(-k, k) * 0.12, 0)
		* CFrame.Angles(rand(-k, k) * 0.012, rand(-k, k) * 0.012, rand(-k, k) * 0.008)
end)

function VFX.Shake(intensity, duration)
	local now = os.clock()
	local remaining = math.max(shakeUntil - now, 0)
	if intensity >= shakeAmount * (remaining / shakeLength) then
		shakeAmount = intensity
		shakeLength = duration
		shakeUntil = now + duration
	end
end

function VFX.ShakeAt(pos, intensity, radius, duration)
	local cam = workspace.CurrentCamera
	local focus = cam and cam.Focus.Position or pos
	local dist = (focus - pos).Magnitude
	if dist < radius then
		VFX.Shake(intensity * (1 - dist / radius), duration)
	end
end

local function nearCamera(pos, radius)
	local cam = workspace.CurrentCamera
	return cam and (cam.Focus.Position - pos).Magnitude < radius
end

---------------------------------------------------------------------------
-- Cinematics: scripted camera shots for the biggest moves
---------------------------------------------------------------------------
-- A shot eases the camera from `From` to `To` over T seconds. Each end is
-- { position, lookAt } in the subject's space when the cutscene started:
-- X = right, Y = up, -Z = forward. lookAt may be "root" to track the subject.
-- Follow = true moves the whole shot with the subject (leaps, dives).
-- Cut = true plays a camera-cut whoosh. Fov = { from, to }.
-- (round 81) A shot's CutGain sets its whoosh's volume (0.7); Quiet = true
-- cuts without one - where the move's own sound carries the cut.

local Cine = Config.Cinematics or {}
local cineToken = 0
local cineActive, cineOwn = false, false
local cineRestore

function VFX.InCinematic()
	return cineActive
end

-- true while YOUR move's cutscene plays (the client holds your inputs)
function VFX.InOwnCinematic()
	return cineActive and cineOwn
end

function VFX.CancelCinematic()
	if cineRestore then
		cineRestore()
	end
end

-- (round 101) which cutscene is up (each VFX.Cinematic bumps it): a caller
-- that started one only takes back its own (VFX.AK - never a kill cam that
-- started after it)
function VFX.CinematicToken()
	return cineToken
end

local function shotCFrame(spec, basis, root)
	local pos = basis * spec[1]
	local target = spec[2] == "root" and root.Position or basis * spec[2]
	if (target - pos).Magnitude < 0.01 then
		target = pos + basis.LookVector
	end
	return CFrame.lookAt(pos, target)
end

-- subject: the character the shots are framed around.
-- opts: { Title, Subtitle, Color, Own = true for the caster, Face = Vector3,
-- (round 81) CutGain = the opening whoosh's volume (1), Quiet = true: none,
-- (round 101) NoBars = true: no letterbox (an awakening: the cut-in's bars
-- are its only bars) }
-- (round 101) a shot's Dir: its ease's direction (InOut); Kick = { Fov, Time,
-- Shake, ShakeTime }: on its cut the FOV jumps by Fov and eases back over Time
-- (Quad Out) while the camera shakes Shake studs, dying away over ShakeTime
-- (no roll) - an awakening's cut onto its pose
function VFX.Cinematic(subject, shots, opts)
	opts = opts or {}
	local cam = workspace.CurrentCamera
	local root = subject and subject:FindFirstChild("HumanoidRootPart")
	if not Cine.Enabled or not cam or not root or not shots or #shots == 0 then
		return false
	end
	if cineActive and (cineOwn or not opts.Own) then
		return false -- your own cutscene is never interrupted by someone else's
	end
	if cineRestore then
		cineRestore()
	end
	cineToken += 1
	local token = cineToken
	cineActive, cineOwn = true, opts.Own == true
	local saved = { Type = cam.CameraType, Fov = cam.FieldOfView, Subject = cam.CameraSubject }
	-- (round 82) no name tag floating over him in the cutscene (a silhouette
	-- frame would carry it); put back as it was after
	local subHum = subject:FindFirstChildOfClass("Humanoid")
	pcall(function()
		saved.Names = subHum and subHum.DisplayDistanceType
		if subHum then
			subHum.DisplayDistanceType = Enum.HumanoidDisplayDistanceType.None
		end
	end)
	local start = root.Position
	local look = opts.Face and (opts.Face - start) or root.CFrame.LookVector
	look = Vector3.new(look.X, 0, look.Z)
	if look.Magnitude < 0.05 then
		look = Vector3.new(0, 0, -1)
	end
	local facing = CFrame.lookAt(start, start + look.Unit)
	local bars = Cine.Letterbox ~= false and opts.NoBars ~= true
	local restored = false
	local function restore()
		if restored then
			return
		end
		restored = true
		if cineToken == token then
			cineActive, cineOwn = false, false
			cineRestore = nil
		end
		RunService:UnbindFromRenderStep("QuirkCinematic")
		if saved.Names and subHum and subHum.Parent then
			pcall(function()
				subHum.DisplayDistanceType = saved.Names
			end)
		end
		cam.CameraType = saved.Type ~= Enum.CameraType.Scriptable and saved.Type or Enum.CameraType.Custom
		cam.FieldOfView = saved.Fov
		-- back to your own body (the one you have now: it may have been
		-- swapped or respawned while the shot played)
		local me = Players.LocalPlayer and Players.LocalPlayer.Character
		local myHum = me and me:FindFirstChildOfClass("Humanoid")
		if myHum then
			cam.CameraSubject = myHum
		elseif saved.Subject and saved.Subject.Parent then
			cam.CameraSubject = saved.Subject
		end
		if bars then
			VFX.Hooks.Letterbox(false)
		end
	end
	cineRestore = restore
	cam.CameraType = Enum.CameraType.Scriptable
	if bars then
		VFX.Hooks.Letterbox(true, opts.Title, opts.Subtitle, opts.Color)
	end
	if not opts.Quiet then
		VFX.PlaySound("CineCut", nil, opts.CutGain or 1)
	end
	local index, shotStart = 1, os.clock()
	RunService:BindToRenderStep("QuirkCinematic", Enum.RenderPriority.Camera.Value, function()
		if cineToken ~= token then
			return
		end
		local shot = shots[index]
		if not root.Parent or not subject.Parent then
			restore()
			return
		end
		local elapsed = os.clock() - shotStart
		while shot and elapsed >= shot.T do
			index += 1
			shotStart += shot.T
			elapsed = os.clock() - shotStart
			shot = shots[index]
			if shot and shot.Cut and not shot.Quiet then
				VFX.PlaySound("CineCut", nil, shot.CutGain or 0.7)
			end
		end
		if not shot then
			restore()
			return
		end
		local a = TweenService:GetValue(math.clamp(elapsed / shot.T, 0, 1), shot.Style or Enum.EasingStyle.Sine, shot.Dir or Enum.EasingDirection.InOut)
		local basis = shot.Follow and (facing.Rotation + root.Position) or facing
		local cf = shotCFrame(shot.From, basis, root):Lerp(shotCFrame(shot.To or shot.From, basis, root), a)
		-- (round 101) the kick on the cut: the FOV snapping back, a shake dying away
		local kick, kickFov = shot.Kick, 0
		if type(kick) == "table" then
			local kt = math.max(tonumber(kick.Time) or 0.1, 0.01)
			kickFov = (tonumber(kick.Fov) or 0) * (1 - TweenService:GetValue(math.clamp(elapsed / kt, 0, 1), Enum.EasingStyle.Quad, Enum.EasingDirection.Out))
			local st = math.max(tonumber(kick.ShakeTime) or 0.2, 0.01)
			local k = (tonumber(kick.Shake) or 0) * math.clamp(1 - elapsed / st, 0, 1)
			if k > 0 then
				cf = cf * CFrame.new(rand(-k, k), rand(-k, k), 0)
			end
		end
		cam.CFrame = cf
		if shot.Fov then
			local f0 = shot.Fov[1]
			cam.FieldOfView = f0 + ((shot.Fov[2] or f0) - f0) * a + kickFov
		end
	end)
	-- safety net: whatever happens, the camera comes back
	local total = 0
	for _, shot in shots do
		total += shot.T
	end
	task.delay(total + 1, function()
		if cineToken == token then
			restore()
		end
	end)
	return true
end

