				{ color = { Color3.fromRGB(200, 235, 255), PAL.EXHAUST }, transp = { { 0, 0.15 }, { 0.7, 0.45 }, { 1, 1 } }, w0 = 0.26, w1 = 0.08, jitter = 0.12, tex = TEX.fire, texMode = "Wrap", texLen = 1.6, texSpeed = 6, light = 1, bright = 2.2, detail = true },
