				{ color = { PAL.TURBO_WHITE, Color3.fromRGB(255, 205, 240) }, transp = { { 0, 0 }, { 0.16, 0.04 }, { 0.24, 0.4 }, { 0.32, 0.06 }, { 0.46, 0.45 }, { 0.56, 0.18 }, { 0.8, 0.6 }, { 1, 1 } }, w0 = 0.15, w1 = 0.04, jitter = 0.14, len = 0.65, core = true },
