	-- (round 85 review) MAXIMUM BURST's: burst-shaped jets with a white core
	-- whose colour goes round the charge's crimson -> orange -> yellow ->
	-- cyan (EK.PAL.MAX), one step a second (cyclePeriod)
	EK.JET.max = {
		len = 5,
		emit = EK.JET.burst.emit,
		beams = {
			{ color = PAL.MAX[1], transp = { { 0, 0 }, { 0.7, 0.3 }, { 1, 1 } }, w0 = 0.34, w1 = 0.1, jitter = 0.14, light = 0.4, bright = 1.4, cycled = true },
			EK.JET.burst.beams[2],
			EK.JET.burst.beams[3],
		},
		cycle = PAL.MAX,
		cyclePeriod = 1,
		light = { color = PAL.MAX[1], range = 9, bright = 2.4 },
		lick = { PAL.TURBO_WHITE, PAL.MAX[2], PAL.MAX[1] },
	}
	-- the flames licking out along the street where a jet hits it (its
	-- colours: the mode's lick)
	EK.LICK = {
		tex = TEX.fire, size = { { 0, 0.5 }, { 0.4, 0.9 }, { 1, 0.15 } }, transp = { { 0, 0.1 }, { 0.6, 0.35 }, { 1, 1 } },
		life = { 0.12, 0.22 }, speed = { 5, 9 }, spread = 75, dir = "Top", drag = 3, light = 0.8, bright = 1.8, spin = { -90, 90 }, rate = 40,
	}

	-- is a move's jet running on him (not the idle / run ones)? The
	-- always-on exhaust goes quiet while one is
	function EK.busy(char)
		for _, mode in EK.live[char] or {} do
			if mode ~= "idle" and mode ~= "run" then
				return true
			end
		end
		return false
	end

	-- EK.jets(char, mode, dur, opts) -> stop(fade): his pipes fire in a mode
	-- ("idle", "run", "ignite", "burst", "turbo") for dur seconds (nil: until
	-- stopped). opts: leg ("Right" / "Left", nil = both), len (studs: the
	-- mode's own by default), dir (a world direction for every jet, e.g.
	-- straight down; they follow it as he moves), intensity (sizes, rates
	-- and the default length), rate (rates only), fade (at the end of dur).
	-- (round 85 review) A jet never goes into the street: one that would
	-- (a leg swung forward tips the pipes down; dir pointing down) is cut
	-- short where it meets it, and its flames lick out along the street
	-- there. Burst, turbo, ignite and max light the street and his legs
	-- (a PointLight a calf). The jets stop when he dies. A second result,
	-- the handle: handle.pulse(len, t) (the jets jump to len and ease back
	-- over t, 0.12 - a kick or a hit, without building new jets),
	-- handle.setLen(len) (held jets longer or shorter from now on),
	-- handle.color(c) (the outer jets and flames recoloured), handle.stop
	function EK.jets(char, mode, dur, opts)
		opts = type(opts) == "table" and opts or {}
		local style = EK.JET[mode] or EK.JET.burst
		local k = opts.intensity or 1
		local low = EK.lowEnd()
		local len = opts.len or style.len * k
		local speedK = style.len > 0 and len / style.len or 1
		local rateK = (low and 0.5 or 1) * k * (opts.rate or 1)
		local all = EK.alive(char) and EK.mouths(char) or {}
		local list = (opts.leg and all[opts.leg]) or (not opts.leg and all.all) or {}
		local made, jets, sides = {}, {}, {}
		for _, m in list do
			local a0 = Instance.new("Attachment")
			a0.Name = "EngineJet"
			a0.CFrame = m.cf
			a0.Parent = m.leg
			table.insert(made, a0)
			local j = { m = m, a0 = a0, beams = {}, seed = rand(0, 100) }
			if style.emit then
				j.pe = EK.emitter(a0, style.emit, k, speedK)
				j.pe.Rate = style.emit.rate * rateK
			end
			for i, bs in style.beams or {} do
				if not ((bs.core or bs.detail) and low) then
					local tip = Instance.new("Attachment")
					tip.Name = "EngineJetTip"
					tip.CFrame = CFrame.new(m.at + m.dirL * len * (bs.len or 1))
					tip.Parent = m.leg
					table.insert(made, tip)
					local b = EK.beam(a0, tip, bs, k, m.leg)
					table.insert(made, b)
					table.insert(j.beams, { b = b, tip = tip, st = bs, outer = i == 1 })
				end
			end
			table.insert(jets, j)
		end
		-- each calf: its embers, its light, where its jets hit the street
		for _, s in opts.leg and { opts.leg } or { "Right", "Left" } do
			if all[s] and #list > 0 then
				local leg = all[s][1].leg
				local side = { leg = leg }
				sides[leg] = side
				if style.embers or (style.light and not low) then
					local p, d = EK.centre(all[s])
					local a = Instance.new("Attachment")
					a.Name = "EngineJet"
					a.CFrame = CFrame.lookAt(p, p + d)
					a.Parent = leg
					table.insert(made, a)
					if style.embers then
						side.embers = EK.emitter(a, style.embers, k)
						side.embers.Rate = style.embers.rate * rateK
					end
					if style.light and not low then
						side.light = Instance.new("PointLight")
						side.light.Color = style.light.color
						side.light.Range = style.light.range * math.sqrt(k)
						side.light.Brightness = style.light.bright
						side.light.Shadows = false
						side.light.Parent = a
					end
				end
			end
		end
		local beamy = style.beams ~= nil and #style.beams > 0
		local handle = { mode = mode }
		if #jets > 0 then -- (no legs, or a corpse: nothing to run, he's not busy)
			EK.live[char] = EK.live[char] or {}
			EK.live[char][handle] = mode
		end
		local pulse, lastRay, lastTint = nil, -1, -1
		local function tint(c)
			for _, j in jets do
				for _, bm in j.beams do
					if not bm.st.core then
						bm.b.Color = CS({ CK(0, c:Lerp(Color3.new(1, 1, 1), 0.3)), CK(0.5, c), CK(1, c:Lerp(Color3.new(0, 0, 0), 0.25)) })
					end
				end
				if j.pe then
					j.pe.Color = CS(c:Lerp(Color3.new(1, 1, 1), 0.35), c)
				end
			end
			for _, side in sides do
				if side.light then
					side.light.Color = c
				end
			end
		end
		-- every frame: the jets flicker (and follow opts.dir as he moves),
		-- cut short by the street, licking along it where they are
		local function frame()
			local now = os.clock()
			if beamy and now - lastRay >= 0.05 then
				lastRay = now
				for leg, side in sides do
					local hit = groundRay(leg.CFrame.Position, 14)
					side.gy = hit and hit.Position.Y or nil
				end
			end
			local L0 = len
			if pulse then
				local a = (now - pulse.t0) / pulse.dur
				if a >= 1 then
					pulse = nil
				else
					L0 = len + (pulse.to - len) * (1 - a) * (1 - a)
				end
			end
			if style.cycle and now - lastTint >= 1 / 15 then
				lastTint = now
				local n = #style.cycle
				local f = (now / (style.cyclePeriod or 1)) % n
				local i = math.floor(f)
				tint(style.cycle[i + 1]:Lerp(style.cycle[(i + 1) % n + 1], f - i))
			end
			for _, side in sides do
				side.cut, side.hits, side.at, side.flat = 0, 0, Vector3.zero, Vector3.zero
			end
			for _, j in jets do
				local leg = j.m.leg
				local cf = leg.CFrame
				local dirL = j.m.dirL
				if opts.dir then
					dirL = cf:VectorToObjectSpace(opts.dir)
					dirL = dirL.Magnitude > 0.01 and dirL.Unit or j.m.dirL
					j.a0.CFrame = CFrame.lookAt(j.m.at, j.m.at + dirL)
				end
				local side = sides[leg]
				local room, wdir = math.huge, nil
				if side and side.gy then
					wdir = cf:VectorToWorldSpace(dirL)
					if wdir.Y < -0.02 then
						room = math.max(((cf * j.m.at).Y - side.gy - 0.1) / -wdir.Y, 0.05)
					end
				end
				for _, bm in j.beams do
					local n = math.noise(now * 9, j.seed, bm.st.w0 * 7)
					local want = L0 * (bm.st.len or 1) * (1 + (bm.st.jitter or 0) * n * 2)
					local l = math.min(want, room)
					bm.tip.CFrame = CFrame.new(j.m.at + dirL * l)
					bm.b.Width0 = bm.st.w0 * k * (1 + n * 0.6)
					if bm.outer and want - l > 0.3 then
						side.cut += want - l
						side.hits += 1
						side.at += cf * (j.m.at + dirL * l)
						side.flat += Vector3.new(wdir.X, 0, wdir.Z)
					end
				end
			end
			for _, side in sides do
				if side.light then
					side.light.Brightness = style.light.bright * (pulse and 1.5 or 1) * (0.85 + math.noise(now * 11, side.leg.Size.Y) * 0.5)
				end
				if style.lick and side.hits > 0 then
					if not side.lick then
						side.lickPart = EK.holder(CFrame.new(side.at / side.hits), nil)
						table.insert(made, side.lickPart)
						local st = table.clone(EK.LICK)
						st.color = style.lick
						side.lick = EK.emitter(side.lickPart, st, k)
					end
					local at = side.at / side.hits
					side.lickPart.CFrame = CFrame.new(at.X, side.gy + 0.15, at.Z)
					local flat = side.flat.Magnitude > 0.05 and side.flat.Unit or Vector3.zero
					side.lick.Acceleration = flat * 30 + UP * 3
					side.lick.Rate = EK.LICK.rate * rateK * math.clamp(side.cut / (L0 * 3), 0.3, 1)
				elseif side.lick then
					side.lick.Rate = 0
				end
			end
		end
		local alive, conn = true, nil
		local function stop(fade)
			if not alive then
				return
			end
			alive = false
			if conn then
				conn:Disconnect()
			end
			if EK.live[char] then
				EK.live[char][handle] = nil
			end
			fade = fade or 0.1
			for _, j in jets do
				if j.pe then
					j.pe.Enabled = false
				end
				for _, bm in j.beams do
					tween(bm.b, fade, { Width0 = 0, Width1 = 0 })
				end
			end
			for _, side in sides do
				for _, pe in { side.embers or false, side.lick or false } do
					if pe then
						pe.Enabled = false
					end
				end
				if side.light then
					tween(side.light, fade, { Brightness = 0 })
				end
			end
			local tail = math.max(style.emit and style.emit.life[2] or 0, style.embers and style.embers.life[2] or 0, style.lick and EK.LICK.life[2] or 0)
			task.delay(fade + tail + 0.05, function()
				for _, x in made do
					pcall(x.Destroy, x)
				end
			end)
		end
		if #jets > 0 then
			frame()
			conn = RunService.RenderStepped:Connect(function()
				if not (pcall(frame) and EK.alive(char)) then
					-- (his body's gone, or he's dead; round 85: a body destroyed
					-- mid-move took the jets' emitters with it - nothing to switch off)
					pcall(stop, 0)
				end
			end)
		end
		handle.stop = stop
		function handle.pulse(to, t)
			pulse = { to = to or len * 1.5, t0 = os.clock(), dur = t or 0.12 }
		end
		function handle.setLen(l)
			len = l
		end
		handle.color = tint
		if dur and dur < math.huge then
			task.delay(dur, stop, opts.fade)
		end
		return stop, handle
	end

	-- EK.ignite(char, opts) -> stop(fade): THE SIGNATURE SWITCH, in about
	-- 0.3 s: the bores flash white, the pipes cough yellow-orange fire and
	-- embers, then snap to long cyan jets (opts.mode "turbo": the ult's)
	-- that run opts.dur. opts: len (the jets, 5), dur (0.6), snap (when the
	-- fire turns to jets, 0.28), boreFlash (his own screen too), sound (false
	-- = silent, or another cue), volume, leg, dir, intensity, mode
	function EK.ignite(char, opts)
		opts = type(opts) == "table" and opts or {}
		local root = char and char:FindFirstChild("HumanoidRootPart")
		if not root or not EK.alive(char) then
			return function() end
		end
		local live, stops = true, {}
		local snap = opts.snap or 0.28
		if opts.sound ~= false then
			VFX.PlaySound(type(opts.sound) == "string" and opts.sound or "EngineIgnite", root.Position, opts.volume or 1)
		end
		EK.flash(char, opts.leg, Color3.new(1, 1, 1), 1)
		if opts.boreFlash and EK.isMine(char) then
			EK.boreFlash()
		end
		-- (round 85 review: the fire half the jets' length, a cone of tongues)
		table.insert(stops, (EK.jets(char, "ignite", snap + 0.06, { leg = opts.leg, dir = opts.dir, intensity = opts.intensity, len = (opts.len or 5) * 0.5 })))
		task.delay(snap, function()
			if not live or not EK.alive(char) then
				return -- (stopped, or he died in the meantime)
			end
			EK.flash(char, opts.leg, opts.mode == "turbo" and PAL.TURBO_WHITE or PAL.EXHAUST_CORE, 1.3)
			table.insert(stops, (EK.jets(char, opts.mode or "burst", opts.dur or 0.6, { leg = opts.leg, dir = opts.dir, intensity = opts.intensity, len = opts.len or 5 })))
		end)
		return function(fade)
			live = false
			for _, s in stops do
				s(fade)
			end
		end
	end

	-- EK.backfire(char, leg, opts): a pop out of a calf's pipes (both: leg
	-- nil) for gear shifts and kicks: a white-orange flash, a cough of fire,
	-- a dark smoke ring blown off them, sparks, the pop. opts: scale (1),
	-- sound (false = silent, or another cue), volume
	function EK.backfire(char, leg, opts)
		opts = type(opts) == "table" and opts or {}
		local k = opts.scale or 1
		local root = char and char:FindFirstChild("HumanoidRootPart")
		if not root or not EK.alive(char) then
			return
		end
		local st = table.clone(EK.PUFF.flash)
		st.color = { PAL.IGNITE_CORE, PAL.IGNITE_DEEP }
		EK.pop(char, leg, st, 1, k, PAL.IGNITE)
		EK.pop(char, leg, EK.PUFF.fire, 10, k)
		EK.pop(char, leg, EK.PUFF.ring, 2, k)
		EK.pop(char, leg, EK.PUFF.smoke, 6, k)
		EK.pop(char, leg, EK.PUFF.sparks, 5, k)
		if opts.sound ~= false then
			VFX.PlaySound(type(opts.sound) == "string" and opts.sound or "EngineBackfire", root.Position, opts.volume or 1)
		end
	end

	-- EK.hotPipes(char, dur, opts) -> stop(fade): the mouths glow red-hot and
	-- cool to grey over dur (1.5). opts.leg
	function EK.hotPipes(char, dur, opts)
		opts = type(opts) == "table" and opts or {}
		dur = dur or 1.5
		local all = EK.alive(char) and EK.mouths(char) or {}
		local list = (opts.leg and all[opts.leg]) or (not opts.leg and all.all) or {}
		local made, glows = {}, {}
		for _, m in list do
			local d = (LOOK.StubWidth or 0.16) * math.min(m.leg.Size.X, m.leg.Size.Z)
			local disc = newPart(Vector3.new(0.04, d, d), CFrame.new(), PAL.HOT_PIPE, Enum.Material.Neon, Enum.PartType.Cylinder)
			disc.Name = "EngineHot"
			-- (round 85 review) its face 0.015 proud of the dark bore's (the
			-- mouth is 0.01 past the bore's face), so the two don't z-fight
			EK.weld(disc, m.leg, m.cf * CFrame.new(0, 0, 0.015) * CFrame.Angles(0, math.pi / 2, 0))
			tween(disc, dur * 0.85, { Color = PAL.COOL_PIPE }, Enum.EasingStyle.Sine, Enum.EasingDirection.In)
			tween(disc, dur * 0.25, { Transparency = 1 }, nil, nil, dur * 0.75)
			table.insert(made, disc)
		end
		-- a red haze round each calf's pipes, and a little light
		for _, s in opts.leg and { opts.leg } or { "Right", "Left" } do
			if all[s] then
				local p, d = EK.centre(all[s])
				local a = Instance.new("Attachment")
				a.Name = "EngineFX"
				a.CFrame = CFrame.lookAt(p, p + d)
				a.Parent = all[s][1].leg
				table.insert(made, a)
				local pe = EK.emitter(a, {
					tex = TEX.glow, color = PAL.HOT_PIPE, size = { { 0, 0.9 }, { 1, 1.2 } }, transp = { { 0, 1 }, { 0.3, 0.55 }, { 1, 1 } },
					life = { 0.25, 0.35 }, speed = { 0.2, 0.5 }, light = 1, rot = { 0, 0 },
				})
				pe.Rate = EK.count(14)
				table.insert(glows, pe)
				if not EK.lowEnd() then
					local pl = Instance.new("PointLight")
					pl.Color = PAL.HOT_PIPE
					pl.Range = 5
					pl.Brightness = 2
					pl.Parent = a
					tween(pl, dur, { Brightness = 0 }, Enum.EasingStyle.Sine, Enum.EasingDirection.In)
				end
			end
		end
		-- the haze cools with the metal, then stops
		task.spawn(function()
			local t0 = os.clock()
			while os.clock() - t0 < dur * 0.7 do
				local c = PAL.HOT_PIPE:Lerp(PAL.COOL_PIPE, (os.clock() - t0) / (dur * 0.7))
				for _, pe in glows do
					pe.Color = CS(c)
				end
				task.wait(0.1)
			end
			for _, pe in glows do
				pe.Enabled = false
			end
		end)
		local alive = true
		local function stop(fade)
			if not alive then
				return
			end
			alive = false
			fade = fade or 0.15
			for _, x in made do
				if x:IsA("BasePart") then
					tween(x, fade, { Transparency = 1 })
				end
			end
			for _, pe in glows do
				pe.Enabled = false
			end
			task.delay(fade + 0.4, function()
				for _, x in made do
					pcall(x.Destroy, x)
				end
			end)
		end
		task.delay(dur, stop, 0.05)
		return stop
	end

	-- EK.stall(char, dur, opts) -> stop(fade): the canon drawback after
	-- Burst / Extend (dur 2.4): red-hot mouths cooling to grey, charcoal
	-- smoke out of the pipes and a tan dust cloud round his legs, two or
	-- three sputters (a cough and a puff each), then grey wisps and the hiss
	-- of them cooling. opts.sound (false = silent)
	function EK.stall(char, dur, opts)
		opts = type(opts) == "table" and opts or {}
		dur = dur or 2.4
		local root = char and char:FindFirstChild("HumanoidRootPart")
		if not root or not EK.alive(char) then
			return function() end
		end
		-- (round 88) the stall fogs his glasses over (VFX.CosA)
		if VFX.CosA then
			pcall(VFX.CosA.fog, char, dur)
		end
		local live, stops = true, {}
		table.insert(stops, EK.hotPipes(char, dur))
		local big = table.clone(EK.PUFF.smoke)
		big.size = { { 0, 0.8 }, { 1, 2.8 } }
		big.life = { 0.9, 1.4 }
		big.speed = { 2, 5 }
		EK.pop(char, nil, big, 7, 1)
		-- (round 85 review: no solid cel puffs hugging his calves, the smoke sells it)
		EK.cloud(groundPoint(root.Position), 0.8, PAL.DUST, 0.55, false)
		local small = table.clone(EK.PUFF.smoke)
		small.size = { { 0, 0.3 }, { 1, 1.1 } }
		for i, t in { 0.2, 0.48, 0.82 } do
			if t < dur - 0.3 then
				task.delay(t, function()
					if not live or not EK.alive(char) then
						return
					end
					local side = i % 2 == 1 and "Right" or "Left"
					if opts.sound ~= false then
						VFX.PlaySound("EngineStall", root.Position, 1)
					end
					EK.pop(char, side, small, 4, 1)
					EK.pop(char, side, EK.PUFF.sparks, 3, 0.6)
				end)
			end
		end
		local calm = math.min(0.95, dur * 0.5)
		task.delay(calm, function()
			if not live or not EK.alive(char) then
				return
			end
			if opts.sound ~= false then
				VFX.PlaySound("EngineCool", root.Position, 0.9)
			end
			table.insert(stops, (EK.jets(char, "idle", dur - calm, { intensity = 1.5, rate = 2.5, fade = 0.3 })))
		end)
		return function(fade)
			live = false
			for _, s in stops do
				s(fade)
			end
		end
	end

	---------------------------------------------------------------------------
	-- THE SPEED SHORTHAND
	---------------------------------------------------------------------------
	-- EK.kickSmear(cf, opts): the anime's kick smear: a cyan flame crescent
	-- along the leg's arc inside a dark grey-brown motion band, drawn on as
	-- the leg sweeps (opts.draw) and fading from its tail (opts.life).
	-- cf: the middle of the arc (his hip); the arc goes round cf's Y axis
	-- (opts.plane "horizontal", the default), round its X axis ("vertical":
	-- up his front), or round any world axis (plane = a Vector3), from
	-- opts.from degrees off cf's front (default: centred on the front),
	-- sweeping opts.arc degrees (200) to his left / upward (opts.spin 1) or
	-- the other way (-1). opts: radius (4: where the foot runs), width (the
	-- band, radius * 0.42), color (EXHAUST), core (EXHAUST_CORE), band
	-- (SMEAR_BAND; false = none), life (0.45), draw (0.07).
	-- (round 85 review) Curved Beams, not a chain of boxes: each layer is a
	-- few Bezier arcs of up to 90 degrees (smooth at any size), facing the
	-- camera like a drawn smear so it reads from any side, the flame strokes
	-- streaky with a scrolling flame texture, the band a soft see-through
	-- blur. About 12-16 beams on one holder (low end: the band and one
	-- stroke). Returns the holder
	function EK.kickSmear(cf, opts)
		opts = type(opts) == "table" and opts or {}
		local r = opts.radius or 4
		local arc = math.rad(math.clamp(opts.arc or 200, 10, 360))
		local from = opts.from and math.rad(opts.from) or -arc / 2
		local width = opts.width or r * 0.42
		local life = opts.life or 0.45
		local draw = opts.draw or 0.07
		local low = EK.lowEnd()
		local axis, fwd
		if typeof(opts.plane) == "Vector3" and opts.plane.Magnitude > 0.01 then
			axis = opts.plane.Unit
			fwd = cf.LookVector - axis * cf.LookVector:Dot(axis)
			if fwd.Magnitude < 0.05 then
				fwd = cf.UpVector - axis * cf.UpVector:Dot(axis)
			end
			fwd = fwd.Unit
		elseif opts.plane == "vertical" then
			axis, fwd = cf.RightVector, cf.LookVector
		else
			axis, fwd = cf.UpVector, cf.LookVector
		end
		local side = axis:Cross(fwd) * (opts.spin or 1)
		local holder = EK.holder(CFrame.new(cf.Position), nil, "EngineSmear")
		-- the layers: the dark band, then streaky flame strokes along it (a
		-- white core on the outer one). w: a share of the band's width; at:
		-- how far in from the foot's path; from: where along the arc it
		-- starts (0 the tail, 1 the head: where the foot is)
		local color = opts.color or EXHAUST
		local layers = {}
		if opts.band ~= false then
			table.insert(layers, { color = opts.band or PAL.SMEAR_BAND, w = 1, at = -0.38, transp = 0.5, light = 0, influence = 0.4, from = 0 })
		end
		-- (the main stroke solid: fire_main is mostly see-through, so only the
		-- inner stroke is streaky)
		table.insert(layers, { color = { color:Lerp(Color3.new(1, 1, 1), 0.15), color, color:Lerp(Color3.new(0, 0, 0), 0.1) }, w = 0.28, at = -0.08, transp = 0, light = 0.3, bright = 1.3, from = 0.04 })
		if not low then
			table.insert(layers, { color = color:Lerp(Color3.new(1, 1, 1), 0.15), w = 0.22, at = -0.42, transp = 0, light = 1, bright = 2.5, from = 0.16, tex = true })
			table.insert(layers, { color = opts.core or EXHAUST_CORE, w = 0.09, at = -0.08, transp = 0, light = 1, bright = 1.5, from = 0.1, z = 0.2 })
		end
		local fade = draw + life * 0.25 -- (when the tail starts thinning away)
		for _, L in layers do
			local a0 = from + arc * L.from
			local span = arc * (1 - L.from)
			local n = math.max(math.ceil(math.deg(span) / 90 - 1e-6), 1)
			local rr = r + width * L.at
			local th = span / n
			local curve = 4 / 3 * math.tan(th / 4) * rr -- (a Bezier that's a true circle's arc)
			local atts = {}
			for i = 0, n do
				local a = a0 + th * i
				local att = Instance.new("Attachment")
				att.Name = "EngineSmear"
				att.CFrame = EK.axisCF((fwd * math.cos(a) + side * math.sin(a)) * rr, side * math.cos(a) - fwd * math.sin(a))
				att.Parent = holder
				atts[i] = att
			end
			for i = 1, n do
				-- along the whole arc: g0 at this piece's tail end, g1 at its head
				local g0 = L.from + (1 - L.from) * (i - 1) / n
				local g1 = L.from + (1 - L.from) * i / n
				local function taper(g)
					return 0.3 + 0.7 * (g - L.from) / (1 - L.from)
				end
				local function see(g)
					return L.transp + (1 - L.transp) * (1 - g) * 0.55
				end
				local st = {
					color = L.color, transp = { { 0, see(g0) }, { 1, see(g1) } }, w0 = width * L.w * taper(g0), w1 = width * L.w * taper(g1),
					light = L.light, bright = L.bright, influence = L.influence, segments = 12, z = L.z,
				}
				if L.tex then
					st.tex, st.texMode, st.texLen, st.texSpeed = TEX.fire, "Wrap", r * 0.9, -2
				end
				local b = EK.beam(atts[i - 1], atts[i], st, 1, holder)
				b.Name = "EngineSmear"
				b.CurveSize0, b.CurveSize1 = curve, curve
				-- drawn on along the sweep, then thinning away from the tail
				b.Enabled = false
				task.delay(draw * g0, function()
					b.Enabled = true
				end)
				tween(b, life * 0.3, { Width0 = 0, Width1 = 0 }, Enum.EasingStyle.Quad, Enum.EasingDirection.In, fade + life * 0.45 * g0)
			end
		end
		EK.gone(holder, fade + life * 0.75 + 0.1)
		return holder
	end

	-- EK.vaporRings(pos, dir, n, opts): 1-3 white vapor rings hanging in the
	-- air across his path (their axis along dir), opts.gap studs apart (4),
	-- each opening from opts.from (1.4) to opts.size (radius 3.5, the later
	-- ones a little smaller) in 0.22 s and thinning away over opts.life
	-- (0.65). opts: color (VAPOR), stagger (0.035 s between rings).
	-- (round 85 review) Each crisp ring is a true circle: 4 curved Beams
	-- (Bezier quarter-circles) facing the camera, so it's a clean ring head
	-- on and still a thin ellipse side on; one little loop opens and thins
	-- it (no tweens, no parts)
	function EK.vaporRings(pos, dir, n, opts)
		opts = type(opts) == "table" and opts or {}
		if typeof(pos) ~= "Vector3" or typeof(dir) ~= "Vector3" or dir.Magnitude < 0.01 then
			return
		end
		local d = dir.Unit
		local gap, size, from = opts.gap or 4, opts.size or 3.5, opts.from or 1.4
		local life, color = opts.life or 0.65, opts.color or PAL.VAPOR
		local K = 4 / 3 * math.tan(math.pi / 8) -- (a Bezier quarter of a circle: its curve size over its radius)
		for i = 1, math.clamp(n or 1, 1, 5) do
			task.delay((i - 1) * (opts.stagger or 0.035), function()
				local c = pos + d * gap * (i - 1)
				local R = size * (1 - 0.1 * (i - 1))
				-- (the holder looks down the path: the ring is in its X-Y plane)
				local ringHolder = EK.holder(CFrame.lookAt(c, c + d), 0.22 + life + 0.2, "EngineVapor")
				local atts, beams = {}, {}
				for q = 0, 3 do
					local att = Instance.new("Attachment")
					att.Name = "EngineVapor"
					att.Parent = ringHolder
					atts[q] = att
				end
				for q = 0, 3 do
					local b = EK.beam(atts[q], atts[(q + 1) % 4], { color = color, transp = 0.15, w0 = 0.36, w1 = 0.36, light = 0.35, bright = 1.2, influence = 0.3, segments = 10 }, 1, ringHolder)
					b.Name = "EngineVapor"
					beams[q] = b
				end
				local function place(rad, w, tr)
					for q = 0, 3 do
						local a = q * math.pi / 2
						atts[q].CFrame = CFrame.fromMatrix(Vector3.new(math.cos(a), math.sin(a), 0) * rad, Vector3.new(-math.sin(a), math.cos(a), 0), Vector3.new(0, 0, 1))
						local b = beams[q]
						b.CurveSize0, b.CurveSize1 = K * rad, K * rad
						b.Width0, b.Width1 = w, w
						b.Transparency = NS(tr)
					end
				end
				place(from, 0.36, 0.15)
				task.spawn(function()
					local t0 = os.clock()
					while ringHolder.Parent do
						local t = os.clock() - t0
						if t > 0.22 + life then
							break
						end
						local a = math.min(t / 0.22, 1)
						local f = math.clamp((t - 0.22) / life, 0, 1)
						place(from + (R - from) * (1 - (1 - a) * (1 - a)), 0.04 + 0.32 * (1 - f * f), 0.15 + 0.85 * f * f)
						task.wait()
					end
					pcall(ringHolder.Destroy, ringHolder)
				end)
				-- a soft ring behind the crisp one
				local h = EK.holder(CFrame.lookAt(c, c + d), 1.2)
				local pe = EK.emitter(h, {
					tex = TEX.ring, color = color, size = { { 0, from * 2.4 }, { 0.3, R * 2.6 }, { 1, R * 3 } }, transp = { { 0, 0 }, { 0.5, 0.3 }, { 1, 1 } },
					life = { 0.7, 0.7 }, speed = { 0.5, 0.5 }, face = "VelocityPerpendicular", light = 0.4, influence = 0.6, rot = { 0, 360 },
				})
				pe:Emit(EK.lowEnd() and 1 or 2)
			end)
		end
	end

	-- EK.machCone(root, dur, opts) -> stop(fade): a white bow-wave flaring
	-- back from his shoulders while he's fast, following him: its two edges
	-- as this machine's camera sees them (a parabola each side, the way the
	-- anime draws it), rings round it, and soft rings of air streaming back
	-- off a point ahead of his chest. opts: size (1), color (VAPOR), ahead
	-- (studs ahead of his chest, 2.2).
	-- (round 85 review) Each edge is ONE curved Beam that is exactly the
	-- parabola (a crisp white line and, off a low-end machine, a wider soft
	-- glow on it), its ends on his root, re-aimed at the camera every frame;
	-- the soft rings streaming back give the cone its volume. 2-4 beams and
	-- one emitter, nothing moved but 4 attachments
	function EK.machCone(root, dur, opts)
		opts = type(opts) == "table" and opts or {}
		if not (root and root:IsA("BasePart")) then
			return function() end
		end
		local k = opts.size or 1
		local ahead = opts.ahead or 2.2
		local color = opts.color or PAL.VAPOR
		local low = EK.lowEnd()
		local att = Instance.new("Attachment")
		att.Name = "EngineFX"
		att.CFrame = CFrame.new(0, 0.6, -ahead) * CFrame.Angles(0, math.pi, 0) -- (looking back down him)
		att.Parent = root
		local pe = EK.emitter(att, {
			tex = TEX.ring, color = color, size = { { 0, 1.2 }, { 1, 6.5 } }, transp = { { 0, 0.1 }, { 0.7, 0.45 }, { 1, 1 } },
			life = { 0.14, 0.18 }, speed = { 22, 26 }, face = "VelocityPerpendicular", locked = true, light = 0.7, influence = 0.5, rot = { 0, 360 },
		}, k)
		pe.Rate = EK.count(45)
		local LEN, RAD = 6 * k, 2.8 * k
		local made, edges = { att }, {}
		for e = 1, 2 do
			local a0 = Instance.new("Attachment")
			a0.Name = "EngineMach"
			a0.Parent = root
			local a1 = Instance.new("Attachment")
			a1.Name = "EngineMach"
			a1.Parent = root
			table.insert(made, a0)
			table.insert(made, a1)
			local edge = { a0 = a0, a1 = a1, beams = {} }
			for _, st in {
				{ color = color, transp = { { 0, 0.1 }, { 0.55, 0.4 }, { 1, 1 } }, w0 = 0.26, w1 = 0.05, light = 0.6, bright = 1.3, segments = 14 },
				not low and { color = color, transp = { { 0, 0.6 }, { 0.5, 0.8 }, { 1, 1 } }, w0 = 0.9, w1 = 0.2, light = 1, bright = 1, segments = 14 } or nil,
			} do
				local b = EK.beam(a0, a1, st, k, root)
				b.Name = "EngineMach"
				table.insert(made, b)
				table.insert(edge.beams, b)
			end
			edges[e] = edge
		end
		-- a crisp ring round the cone just behind his back (u = 0.8 on the
		-- edges): 4 Bezier quarter-circles in his root's space, so it rides
		-- with him for free - the cone seen head on, from his own camera
		do
			local u = 0.8
			local c, R = Vector3.new(0, 0.6, -ahead + LEN * u * u), RAD * u
			local K = 4 / 3 * math.tan(math.pi / 8) * R
			local atts = {}
			for q = 0, 3 do
				local a = q * math.pi / 2
				local att = Instance.new("Attachment")
				att.Name = "EngineMach"
				att.CFrame = CFrame.fromMatrix(c + Vector3.new(math.cos(a), math.sin(a), 0) * R, Vector3.new(-math.sin(a), math.cos(a), 0), Vector3.new(0, 0, 1))
				att.Parent = root
				atts[q] = att
				table.insert(made, att)
			end
			for q = 0, 3 do
				local b = EK.beam(atts[q], atts[(q + 1) % 4], { color = color, transp = 0.45, w0 = 0.16, w1 = 0.16, light = 0.6, bright = 1.2, segments = 10 }, k, root)
				b.Name = "EngineMach"
				b.CurveSize0, b.CurveSize1 = K, K
				table.insert(made, b)
				table.insert(edges, { ring = b, beams = { b } })
			end
		end
		-- the edge: q(u) = apex + axis*LEN*u^2 + out*RAD*u (u 0..1), a
		-- parabola, which is a quadratic Bezier, so a cubic one exactly.
		-- Seen straight down the cone (from right behind him) the edges
		-- thin out and the ring carries it
		local base = {}
		for _, edge in edges do
			for _, b in edge.beams do
				base[b] = { b.Width0, b.Width1 }
			end
		end
		local function place()
			local cf = root.CFrame
			local apex = cf * Vector3.new(0, 0.6, -ahead)
			local axis = -cf.LookVector
			local cam = workspace.CurrentCamera
			local view = cam and (apex - cam.CFrame.Position) or cf.LookVector
			local out = axis:Cross(view)
			out = out.Magnitude > 0.1 * view.Magnitude and out.Unit or cf.RightVector
			local side = math.clamp((1 - math.abs(axis:Dot(view.Magnitude > 0.01 and view.Unit or axis))) * 4, 0.2, 1)
			for e, sign in { 1, -1 } do
				local o = out * sign
				local tail = apex + axis * LEN + o * RAD
				local back = axis * LEN * 2 / 3 + o * RAD / 3
				local edge = edges[e]
				edge.a0.CFrame = cf:ToObjectSpace(EK.axisCF(apex, o))
				edge.a1.CFrame = cf:ToObjectSpace(EK.axisCF(tail, back))
				for _, b in edge.beams do
					b.CurveSize0, b.CurveSize1 = RAD / 3, back.Magnitude
					b.Width0, b.Width1 = base[b][1] * side, base[b][2] * side
				end
			end
		end
		place()
		local alive, conn = true, nil
		local function stop(fade)
			if not alive then
				return
			end
			alive = false
			conn:Disconnect()
			fade = fade or 0.12
			pe.Enabled = false
			for _, edge in edges do
				for _, b in edge.beams do
					tween(b, fade, { Width0 = 0, Width1 = 0 })
				end
			end
			task.delay(math.max(fade, 0.2) + 0.05, function()
				for _, x in made do
					pcall(x.Destroy, x)
				end
			end)
		end
		conn = RunService.RenderStepped:Connect(function()
			if not (pcall(place) and root.Parent) then
				stop(0) -- (his body's gone)
			end
		end)
		if dur and dur < math.huge then
			task.delay(dur, stop)
		end
		return stop
	end

	-- EK.dustWall(fromPos, toPos, opts): a low tan dust wake torn up along
	-- the street from fromPos to toPos (on the ground under them) over
	-- opts.time (the path at 200 studs/s), opts.height (1) high and growing
	-- toward the end, a tan-and-charcoal cloud where it stops (opts.cloud ~=
	-- false), 2.5 studs behind that point so it doesn't swallow him.
	-- opts.color (DUST). (round 85 review: at most 60 puffs however long
	-- the path, 30 on a low-end machine, more see-through, and no solid cel
	-- puffs along it)
	function EK.dustWall(fromPos, toPos, opts)
		opts = type(opts) == "table" and opts or {}
		if typeof(fromPos) ~= "Vector3" or typeof(toPos) ~= "Vector3" then
			return
		end
		local g0, g1 = groundPoint(fromPos), groundPoint(toPos)
		local path = g1 - g0
		local length = path.Magnitude
		local h = opts.height or 1
		local color = opts.color or PAL.DUST
		local time = opts.time or math.max(length / 200, 0.05)
		local holder = EK.holder(CFrame.new(g0 + UP * 0.6), time + 2.2)
		holder.Size = Vector3.new(2.5, 0.6, 2.5)
		local style = {
			tex = TEX.smoke, color = { color, Color3.fromRGB(170, 140, 108) }, size = { { 0, 1.6 }, { 0.4, 3.6 }, { 1, 5 } },
			transp = { { 0, 0.3 }, { 0.5, 0.45 }, { 1, 1 } }, life = { 1, 1.8 }, speed = { 1.5, 4.5 }, spread = 70, dir = "Top",
			accel = Vector3.new(0, 1.2, 0), drag = 2.5, influence = 0.9, spin = { -30, 30 },
		}
		local pe = EK.emitter(holder, style, h * 0.8)
		pe.Shape = Enum.ParticleEmitterShape.Box
		-- (about 1.6 puffs a stud of path, at most 60 in all; half on a low-end machine)
		local total = EK.lowEnd() and math.min(0.8 * length, 30) or math.min(1.6 * length, 60)
		pe.Rate = math.max(total / time, 10)
		tween(holder, time, { CFrame = CFrame.new(g1 + UP * 0.6) }, Enum.EasingStyle.Linear)
		-- taller toward the end
		for s = 1, 3 do
			task.delay(time * s / 4, function()
				pe.Size = EK.ns(style.size, h * (0.8 + 0.15 * s))
			end)
		end
		task.delay(time, function()
			pe.Enabled = false
		end)
		if opts.cloud ~= false then
			local back = length > 0.1 and path.Unit * math.min(2.5, length) or Vector3.zero
			task.delay(time, function()
				EK.cloud(g1 - back, h, color)
			end)
		end
	end

	-- EK.cloud(ground, h, color, smoke, puffs): a low cloud of dust rolling
	-- out along the street round a point (where a dash stops, round a
	-- stalled engine), h high (1), smoke: how much charcoal is in it
	-- (0.35), puffs (false: no cel-shaded puffs in it, just the smoke)
	function EK.cloud(ground, h, color, smoke, puffs)
		h, color = h or 1, color or PAL.DUST
		local holder = EK.holder(CFrame.new(ground + UP * 0.4), 2.4)
		holder.Size = Vector3.new(3 * h, 0.4, 3 * h)
		local pe = EK.emitter(holder, {
			tex = TEX.smoke, color = { color, color:Lerp(PAL.SMOKE, smoke or 0.35) }, size = { { 0, 1.5 * h }, { 0.5, 3.6 * h }, { 1, 4.6 * h } },
			transp = { { 0, 0.25 }, { 0.5, 0.42 }, { 1, 1 } }, life = { 1, 1.6 }, speed = { 4 * h, 9 * h }, spread = 80, dir = "Top",
			accel = Vector3.new(0, 1.5, 0), drag = 3, influence = 0.9, spin = { -30, 30 },
		})
		pe.Shape = Enum.ParticleEmitterShape.Box
		pe:Emit(EK.count(18))
		if puffs ~= false then
			dustPuffs(ground + UP * 0.3, 0.3 * h, EK.count(3), color, 0.9, Color3.fromRGB(120, 96, 70))
		end
	end

	-- EK.starSpark(pos, opts): a star hit-spark, flat to the camera: opts.spikes
	-- (8, 4-8) spikes, long ones (opts.color, EXHAUST, with white cores)
	-- between short ones (opts.color2: TURBO_GOLD; or white), opts.size
	-- (3: the long ones' length), gone in opts.life (0.1).
	-- (round 85 review) Each spike is one tapered Beam from a single holder
	-- (wide at the middle, a point at the tip), not wedge parts: 8 spikes + 4
	-- white cores, a glow and a sparkle - 12 beams, 2 particles
	function EK.starSpark(pos, opts)
		opts = type(opts) == "table" and opts or {}
		if typeof(pos) ~= "Vector3" then
			return
		end
		local cam = workspace.CurrentCamera
		local look = cam and (pos - cam.CFrame.Position) or Vector3.new(0, 0, -1)
		look = look.Magnitude > 0.01 and look.Unit or Vector3.new(0, 0, -1)
		local right = look:Cross(math.abs(look.Y) > 0.95 and Vector3.new(1, 0, 0) or UP).Unit
		local up = right:Cross(look)
		local n = math.clamp(opts.spikes or 8, 4, 8)
		local size, life = opts.size or 3, opts.life or 0.1
		local c1, c2 = opts.color or EXHAUST, opts.color2 or PAL.TURBO_GOLD
		local spin = rand(0, math.pi * 2)
		local h = EK.holder(CFrame.new(pos), life + 0.5, "EngineStar")
		local mid = Instance.new("Attachment")
		mid.Name = "EngineStar"
		mid.Parent = h
		-- a spike: wide at the middle, sharp at the tip, shrinking in to a
		-- third of its length and thinning away over life
		local function spike(a, len, base, color, z)
			local dir = right * math.cos(a) + up * math.sin(a)
			local tip = Instance.new("Attachment")
			tip.Name = "EngineStar"
			tip.CFrame = CFrame.new(dir * len)
			tip.Parent = h
			local b = EK.beam(mid, tip, { color = color, w0 = base, w1 = 0, light = 0.6, bright = 1.6, z = z }, 1, h)
			b.Name = "EngineStar"
			tween(tip, life, { CFrame = CFrame.new(dir * len * 0.35) }, Enum.EasingStyle.Quad, Enum.EasingDirection.In)
			tween(b, life, { Width0 = base * 0.3 }, Enum.EasingStyle.Quad, Enum.EasingDirection.In)
		end
		for i = 1, n do
			local a = spin + (i - 1) / n * math.pi * 2
			if i % 2 == 1 then
				local len = size * rand(0.9, 1.15)
				spike(a, len, 0.55 * size / 3, c1, 0)
				spike(a, len * 0.7, 0.25 * size / 3, Color3.new(1, 1, 1), 0.3)
			else
				spike(a, size * rand(0.5, 0.65), 0.4 * size / 3, c2, 0.15)
			end
		end
		-- the white-hot middle, and a sparkle on it
		local glow = EK.emitter(h, { tex = TEX.glow, color = Color3.new(1, 1, 1), size = { { 0, size * 0.8 }, { 1, size * 0.2 } }, transp = { { 0, 0 }, { 1, 1 } }, life = { life, life }, speed = { 0, 0 }, light = 1, bright = 3, rot = { 0, 0 }, z = 0.5 })
		glow:Emit(1)
		local pe = EK.emitter(h, { tex = TEX.spark, color = c1, size = { { 0, size * 1.2 }, { 1, size * 0.4 } }, transp = { { 0, 0.1 }, { 1, 1 } }, life = { life * 1.4, life * 1.4 }, speed = { 0, 0 }, light = 1, bright = 2 })
		pe:Emit(1)
		task.delay(life + 0.02, function()
			for _, d in h:GetChildren() do
				if d:IsA("Beam") then
					d.Enabled = false
				end
			end
		end)
		return h -- (round 85, iida_burst: its holder, so a move can carry it along with someone moving fast)
	end

	-- EK.afterimage(char, color, life, opts): a tinted ghost of his body
	-- (EXHAUST, fading over life, 0.3), or of one leg (opts.leg "Right" /
	-- "Left"). opts: transparency (0.45 to start), material (Neon), cframes
	-- ({ [part name] = CFrame }: draw a part somewhere else - e.g. a ghost
	-- leg swung up high), offset (a CFrame on top of the body's)
	function EK.afterimage(char, color, life, opts)
		opts = type(opts) == "table" and opts or {}
		if typeof(char) ~= "Instance" then
			return {}
		end
		color, life = color or EXHAUST, life or 0.3
		local only
		if opts.leg then
			only = { [opts.leg .. " Leg"] = true, [opts.leg .. "UpperLeg"] = true, [opts.leg .. "LowerLeg"] = true, [opts.leg .. "Foot"] = true }
		end
		local ghosts = {}
		for _, part in char:GetChildren() do
			if part:IsA("BasePart") and part.Name ~= "HumanoidRootPart" and part.Transparency < 1 and (not only or only[part.Name]) then
				local ghost = newPart(part.Size, (opts.cframes and opts.cframes[part.Name]) or part.CFrame, color, opts.material or Enum.Material.Neon)
				ghost.Name = "EngineGhost"
				if opts.offset then
					ghost.CFrame = opts.offset * ghost.CFrame
				end
				local mesh = part:FindFirstChildOfClass("SpecialMesh")
				if mesh and part.Name == "Head" then
					local m = Instance.new("SpecialMesh")
					m.MeshType = mesh.MeshType
					m.Scale = mesh.Scale
					m.Parent = ghost
				end
				ghost.Transparency = opts.transparency or 0.45
				tween(ghost, life, { Transparency = 1 })
				EK.gone(ghost, life + 0.05)
				table.insert(ghosts, ghost)
			end
		end
		return ghosts
	end

	-- EK.lightBar(a, b, opts) -> stop(fade), flash(time): a glowing straight
	-- bar from a to b, a white core in a coloured middle with a violet edge
	-- (Turbo's paths). opts: width (2.5), life (0.5: it holds 40% of it,
	-- then thins away), color (TURBO_CYAN), edge (TURBO_VIOLET), core
	-- (white). flash(): every colour white for a moment (the last leg)
	function EK.lightBar(a, b, opts)
		opts = type(opts) == "table" and opts or {}
		local width, life = opts.width or 2.5, opts.life or 0.5
		local h = EK.holder(CFrame.new(a), life + 0.5, "EngineBar")
		local a0 = Instance.new("Attachment")
		a0.Parent = h
		local a1 = Instance.new("Attachment")
		a1.CFrame = CFrame.new(b - a)
		a1.Parent = h
		local beams = {}
		for _, L in {
			{ c = opts.edge or PAL.TURBO_VIOLET, w = 1, t = 0.45, light = 0.25 },
			{ c = opts.color or PAL.TURBO_CYAN, w = 0.6, t = 0, light = 0.15 },
			{ c = opts.core or Color3.new(1, 1, 1), w = 0.18, t = 0, light = 1 },
		} do
			local bm = EK.beam(a0, a1, { color = L.c, transp = L.t, w0 = width * L.w, w1 = width * L.w, light = L.light }, 1, h)
			table.insert(beams, { b = bm, w = width * L.w })
		end
		local alive = true
		local function stop(fade)
			if not alive then
				return
			end
			alive = false
			fade = fade or life * 0.6
			for _, x in beams do
				tween(x.b, fade, { Width0 = 0, Width1 = 0 }, Enum.EasingStyle.Quad, Enum.EasingDirection.In)
			end
			task.delay(fade + 0.05, function()
				pcall(h.Destroy, h)
			end)
		end
		local function flash(time)
			if not alive then
				return
			end
			for _, x in beams do
				x.b.Color = CS(Color3.new(1, 1, 1))
				x.b.Width0, x.b.Width1 = x.w * 1.4, x.w * 1.4
			end
			stop(time or 0.15)
		end
		task.delay(life * 0.4, stop)
		return stop, flash
	end

	-- EK.contrail(part, dur, opts) -> stop(): a white contrail streaming off
	-- a part (his root, a foot) for dur seconds (nil: until stopped). opts:
	-- width (1.2), life (how long it hangs, 0.7), color (VAPOR), offset (a
	-- Vector3 on the part)
	function EK.contrail(part, dur, opts)
		opts = type(opts) == "table" and opts or {}
		local w = opts.width or 1.2
		local off = opts.offset or Vector3.zero
		local a0 = Instance.new("Attachment")
		a0.Name = "EngineFX"
		a0.CFrame = CFrame.new(off + Vector3.new(0, w / 2, 0))
		a0.Parent = part
		local a1 = Instance.new("Attachment")
		a1.Name = "EngineFX"
		a1.CFrame = CFrame.new(off - Vector3.new(0, w / 2, 0))
		a1.Parent = part
		local trail = Instance.new("Trail")
		trail.Name = "EngineFX"
		trail.Attachment0 = a0
		trail.Attachment1 = a1
		trail.Color = CS(opts.color or PAL.VAPOR, WIND)
		trail.Transparency = EK.ns({ { 0, 0.2 }, { 0.5, 0.5 }, { 1, 1 } })
		trail.WidthScale = EK.ns({ { 0, 1 }, { 1, 0.35 } })
		trail.LightEmission = 0.4
		trail.Lifetime = opts.life or 0.7
		trail.FaceCamera = true
		trail.Parent = part
		local alive = true
		local function stop()
			if not alive then
				return
			end
			alive = false
			pcall(function()
				trail.Enabled = false
			end)
			task.delay(trail.Lifetime + 0.05, function()
				for _, x in { trail, a0, a1 } do
					pcall(x.Destroy, x)
				end
			end)
		end
		if dur and dur < math.huge then
			task.delay(dur, stop)
		end
		return stop
	end

	-- (round 85 review) EK.contrailLine(a, b, opts) -> stop(fade): a white
	-- contrail hanging along a straight path from a to b at once - where he
	-- went in a blink (Turbo Kick, Max's run), which a trail on a part can't
	-- draw. Wide and bright at b (where he got to), thinning toward a; the
	-- a end goes first, all of it over opts.life (0.8). opts: width (1.2),
	-- life, color (VAPOR), core (false: no thin bright core)
	function EK.contrailLine(a, b, opts)
		opts = type(opts) == "table" and opts or {}
		if typeof(a) ~= "Vector3" or typeof(b) ~= "Vector3" or (b - a).Magnitude < 0.05 then
			return function() end
		end
		local w, life = opts.width or 1.2, opts.life or 0.8
		local h = EK.holder(CFrame.new(a), life + 0.3, "EngineContrail")
		local a0 = Instance.new("Attachment")
		a0.Parent = h
		local a1 = Instance.new("Attachment")
		a1.CFrame = CFrame.new(b - a)
		a1.Parent = h
		local color = opts.color or PAL.VAPOR
		local beams = { EK.beam(a0, a1, { color = { color:Lerp(Color3.fromRGB(190, 200, 215), 0.4), color }, transp = { { 0, 0.85 }, { 0.6, 0.45 }, { 1, 0.2 } }, w0 = w * 0.2, w1 = w, light = 0.4, influence = 0.3 }, 1, h) }
		if opts.core ~= false then
			table.insert(beams, EK.beam(a0, a1, { color = Color3.new(1, 1, 1), transp = { { 0, 0.9 }, { 0.7, 0.4 }, { 1, 0.1 } }, w0 = w * 0.05, w1 = w * 0.22, light = 1, z = 0.1 }, 1, h))
		end
		for _, bm in beams do
			tween(bm, life * 0.6, { Width0 = 0 }, Enum.EasingStyle.Quad, Enum.EasingDirection.In)
			tween(bm, life, { Width1 = 0 }, Enum.EasingStyle.Quad, Enum.EasingDirection.In)
		end
		return function(fade)
			for _, bm in beams do
				tween(bm, fade or 0.1, { Width0 = 0, Width1 = 0 })
			end
			EK.gone(h, (fade or 0.1) + 0.05)
		end
	end

	-- EK.legTrails(char, dur, opts) -> stop(): flame ribbons off his calves
	-- (from the pipes), two-tone: a wide outer colour round a thin bright
	-- core. While he spins they draw a disc of flame; while he runs, two
	-- streaks. opts: color (EXHAUST), core (EXHAUST_CORE), width (1.2), life
	-- (how long a ribbon hangs, 0.25), leg ("Right" / "Left", nil = both)
	function EK.legTrails(char, dur, opts)
		opts = type(opts) == "table" and opts or {}
		local all = EK.alive(char) and EK.mouths(char) or {}
		local made = {}
		local w = opts.width or 1.2
		for _, sname in opts.leg and { opts.leg } or { "Right", "Left" } do
			local list = all[sname]
			if list then
				local p, d = EK.centre(list)
				local leg = list[1].leg
				for _, L in { { c = opts.color or EXHAUST, w = w, t = 0.15, light = 0.45 }, { c = opts.core or EXHAUST_CORE, w = w * 0.35, t = 0, light = 1 } } do
					local a0 = Instance.new("Attachment")
					a0.Name = "EngineFX"
					a0.CFrame = CFrame.new(p + d * 0.2 + Vector3.new(0, L.w / 2, 0))
					a0.Parent = leg
					local a1 = Instance.new("Attachment")
					a1.Name = "EngineFX"
					a1.CFrame = CFrame.new(p + d * 0.2 - Vector3.new(0, L.w / 2, 0))
					a1.Parent = leg
					local trail = Instance.new("Trail")
					trail.Name = "EngineFX"
					trail.Attachment0 = a0
					trail.Attachment1 = a1
					trail.Color = CS(L.c)
					trail.Transparency = EK.ns({ { 0, L.t }, { 0.6, 0.55 }, { 1, 1 } })
					trail.WidthScale = EK.ns({ { 0, 1 }, { 1, 0.3 } })
					trail.LightEmission = L.light
					trail.Lifetime = opts.life or 0.25
					trail.FaceCamera = true
					trail.Parent = leg
					table.insert(made, { trail = trail, a0 = a0, a1 = a1 })
				end
			end
		end
		local alive = true
		local function stop()
			if not alive then
				return
			end
			alive = false
			for _, x in made do
				pcall(function()
					x.trail.Enabled = false
				end)
			end
			task.delay((opts.life or 0.25) + 0.05, function()
				for _, x in made do
					for _, o in { x.trail, x.a0, x.a1 } do
						pcall(o.Destroy, o)
					end
				end
			end)
		end
		if dur and dur < math.huge then
			task.delay(dur, stop)
		end
		return stop
	end

	-- EK.cracks(pos, radius, n, opts): the street splitting where he lands:
	-- n (8) dark jagged cracks radiating out to radius (8) and a crater ring
	-- round the middle (a scorch, a lip of chips in the street's colour).
	-- opts: grow (0.12 s), life (2.5 s, then they fade), glow (a Color3: a
	-- seam glowing in each crack, e.g. EXHAUST), rocks (debris thrown up: a
	-- count), crater (false = cracks only)
	function EK.cracks(pos, radius, n, opts)
		opts = type(opts) == "table" and opts or {}
		local hit = groundRay(pos, 40)
		local g = hit and hit.Position or (pos - UP * 3)
		radius = radius or 8
		n = EK.count(n or 8)
		local grow, life = opts.grow or 0.12, opts.life or 2.5
		local base = rand(0, math.pi * 2)
		for i = 1, n do
			local a = base + (i - 1) / n * math.pi * 2 + rand(-0.25, 0.25)
			local dir = Vector3.new(math.cos(a), 0, math.sin(a))
			local side = Vector3.new(-dir.Z, 0, dir.X)
			local reach = radius * rand(0.65, 1.05)
			local points = { g + dir * radius * 0.18 }
			for s = 1, 3 do
				table.insert(points, g + dir * (radius * 0.18 + (reach - radius * 0.18) * s / 3) + side * rand(-0.5, 0.5) * radius * 0.1)
			end
			for s = 1, #points - 1 do
				local p1, p2 = points[s] + UP * (0.04 + i * 0.002), points[s + 1] + UP * (0.04 + i * 0.002)
				local w = (0.5 * (1 - (s - 1) / 3) + 0.1) * math.min(radius / 8, 1.6)
				local seg = newPart(Vector3.new(w, 0.05, 0.05), CFrame.lookAt(p1, p2), PAL.CRACK, Enum.Material.SmoothPlastic)
				seg.Name = "EngineCrack"
				local t0 = grow * (s - 1) / 3
				local len = (p2 - p1).Magnitude + w * 0.5
				tween(seg, grow / 3, { Size = Vector3.new(w, 0.05, len), CFrame = CFrame.lookAt((p1 + p2) / 2, p2) }, Enum.EasingStyle.Linear, nil, t0)
				tween(seg, 0.6, { Transparency = 1 }, nil, nil, life)
				EK.gone(seg, life + 0.65)
				if opts.glow then
					local seam = newPart(Vector3.new(w * 0.35, 0.06, len * 0.9), CFrame.lookAt((p1 + p2) / 2 + UP * 0.01, p2 + UP * 0.01), opts.glow, Enum.Material.Neon)
					seam.Name = "EngineCrack"
					seam.Transparency = 1
					tween(seam, 0.03, { Transparency = 0 }, nil, nil, t0)
					tween(seam, 0.5, { Transparency = 1 }, nil, nil, t0 + 0.25)
					EK.gone(seam, t0 + 0.8)
				end
			end
		end
		if opts.crater ~= false then
			groundMark(g, radius * 0.32, Color3.fromRGB(40, 34, 32), life)
			local street = hit and hit.Instance and hit.Instance:IsA("BasePart") and hit.Instance.Color or Color3.fromRGB(110, 106, 104)
			local chips = EK.count(10)
			for i = 1, chips do
				local a = base + (i - 0.5) / chips * math.pi * 2
				local at = g + Vector3.new(math.cos(a), 0, math.sin(a)) * radius * 0.36 + UP * 0.12
				local s = rand(0.35, 0.7) * math.min(radius / 8, 1.5)
				local chip = newPart(Vector3.new(s * 1.4, s * 0.5, s), CFrame.lookAt(at, g) * CFrame.Angles(math.rad(rand(15, 40)), 0, rand(-0.3, 0.3)), street:Lerp(Color3.new(0, 0, 0), rand(0.1, 0.3)), Enum.Material.Slate)
				chip.Name = "EngineCrack"
				tween(chip, 0.6, { Transparency = 1 }, nil, nil, life)
				EK.gone(chip, life + 0.65)
			end
		end
		if opts.rocks and opts.rocks > 0 then
			rocks(g, math.min(radius / 6, 2), EK.count(opts.rocks))
		end
	end

	-- EK.boreFlash(opts): HIS OWN SCREEN ONLY (call it when isLocal): the
	-- anime's look down a pipe as it lights, in 0.18 s: the screen goes dark
	-- round a circle in the middle (the bore) that opens up while its centre
	-- goes white, then a white flash. opts.color (white)
	function EK.boreFlash(opts)
		opts = type(opts) == "table" and opts or {}
		local lp = Players.LocalPlayer
		local pg = lp and lp:FindFirstChildOfClass("PlayerGui")
		if not pg then
			return nil
		end
		local gui = Instance.new("ScreenGui")
		gui.Name = "EngineBoreFlash"
		gui.IgnoreGuiInset = true
		gui.ResetOnSpawn = false
		gui.DisplayOrder = 11
		local bore = Instance.new("Frame")
		bore.AnchorPoint = Vector2.new(0.5, 0.5)
		bore.Position = UDim2.fromScale(0.5, 0.5)
		bore.Size = UDim2.fromScale(0.6, 0.6)
		bore.SizeConstraint = Enum.SizeConstraint.RelativeYY
		bore.BackgroundColor3 = opts.color or Color3.new(1, 1, 1)
		bore.BackgroundTransparency = 1
		bore.BorderSizePixel = 0
		bore.Parent = gui
		local corner = Instance.new("UICorner")
		corner.CornerRadius = UDim.new(0.5, 0)
		corner.Parent = bore
		local rim = Instance.new("UIStroke")
		rim.Color = Color3.fromRGB(18, 18, 24)
		-- (dark all round the bore, to the corners of any screen: round 85
		-- review, the screen's diagonal, so an ultrawide or 4K is covered too)
		local vs = workspace.CurrentCamera and workspace.CurrentCamera.ViewportSize
		rim.Thickness = math.max(900, typeof(vs) == "Vector2" and vs.Magnitude or 0)
		rim.Transparency = 0.35
		rim.Parent = bore
		local white = Instance.new("Frame")
		white.Size = UDim2.fromScale(1, 1)
		white.BackgroundColor3 = opts.color or Color3.new(1, 1, 1)
		white.BackgroundTransparency = 1
		white.BorderSizePixel = 0
		white.Parent = gui
		gui.Parent = pg
		tween(bore, 0.1, { Size = UDim2.fromScale(1.6, 1.6), BackgroundTransparency = 0 }, Enum.EasingStyle.Quad, Enum.EasingDirection.In)
		tween(rim, 0.1, { Transparency = 1 }, Enum.EasingStyle.Quad, Enum.EasingDirection.In)
		task.delay(0.1, function()
			white.BackgroundTransparency = 0.3
			bore.Visible = false
			tween(white, 0.08, { BackgroundTransparency = 1 })
		end)
		EK.gone(gui, 0.25)
		task.delay(0.25, function()
			pcall(gui.Destroy, gui)
		end)
		return gui
	end

	-- EK.fovPunch(amount, tIn, tOut, hold): HIS OWN CAMERA: the field of view
	-- kicks out by amount (in, if negative) over tIn (0.06), holds (0.04),
	-- and eases back over tOut (0.3). None during a cutscene.
	-- (round 85 review) The punch is an OFFSET on top of whatever the game
	-- sets the view to (the sprint's FOV tween, the scope): every frame,
	-- after the camera, it adds its offset to the base, and a value someone
	-- else wrote since its last frame becomes the new base. So it never
	-- cancels the sprint's tween or leaves the view stuck mid-way: when it
	-- ends the view is exactly where the game put it. A newer punch takes
	-- over from where the last one is. A cutscene starting mid-punch gets
	-- the view put back right after it (it saved the punched one)
	EK.fov = { offset = 0 }
	local function ease(a, out)
		return out and 1 - (1 - a) * (1 - a) or (1 - math.cos(a * math.pi)) / 2
	end
	function EK.fovStep()
		local F = EK.fov
		local cam = workspace.CurrentCamera
		local p = F.punch
		local function done()
			F.punch, F.offset, F.written = nil, 0, nil
			F.bound = false
			pcall(function()
				RunService:UnbindFromRenderStep("EngineFovPunch")
			end)
		end
		if not cam or not p then
			return done()
		end
		if VFX.InCinematic() then
			-- a cutscene has the camera (and saved the punched view to put
			-- back after): once it has, back to the base
			local base, punched = F.base, F.written
			done()
			task.spawn(function()
				while VFX.InCinematic() do
					task.wait(0.1)
				end
				if base and punched and math.abs(cam.FieldOfView - punched) < 0.01 then
					cam.FieldOfView = base
				end
			end)
			return
		end
		-- someone else set the view since our last frame: that's the base now
		if F.written == nil or math.abs(cam.FieldOfView - F.written) > 1e-3 then
			F.base = cam.FieldOfView
		end
		local t = os.clock() - p.t0
		local off
		if t < p.tIn then
			off = p.from + (p.amount - p.from) * ease(t / p.tIn, true)
		elseif t < p.tIn + p.hold then
			off = p.amount
		elseif t < p.tIn + p.hold + p.tOut then
			off = p.amount * (1 - ease((t - p.tIn - p.hold) / p.tOut))
		else
			cam.FieldOfView = F.base -- (exactly where the game had it)
			return done()
		end
		F.offset = off
		cam.FieldOfView = math.clamp(F.base + off, 20, 110)
		F.written = cam.FieldOfView
	end
	function EK.fovPunch(amount, tIn, tOut, hold)
		local cam = workspace.CurrentCamera
		if not cam or VFX.InCinematic() or type(amount) ~= "number" then
			return
		end
		local F = EK.fov
		F.punch = { t0 = os.clock(), from = F.offset or 0, amount = amount, tIn = math.max(tIn or 0.06, 0.01), hold = hold or 0.04, tOut = math.max(tOut or 0.3, 0.01) }
		if not F.bound then
			F.bound = true
			F.written = nil
			RunService:BindToRenderStep("EngineFovPunch", Enum.RenderPriority.Camera.Value + 2, EK.fovStep)
		end
		EK.fovStep()
	end

	---------------------------------------------------------------------------
	-- THE DRIVER: every Engine body this machine renders gets its always-on
	-- exhaust (made here, not on the server, so it can follow his speed):
	-- thin grey wisps standing, a cyan flicker running that grows with his
	-- speed, the ult's flicker in magenta and violet. It goes quiet while
	-- one of his moves' jets runs, and comes off when he dies, on a new body
	-- or when he's someone else.
	---------------------------------------------------------------------------
	EK.DRIVER = {
		Every = 0.1, -- (s: how often the rates follow his speed)
		Scan = 0.5, -- (s: how often new Engine bodies are looked for)
		RunFrom = 3, -- (studs/s: slower than this is standing)
		FullAt = 23, -- (studs/s: the flicker's full rate - his WalkSpeed)
		Flame = 1.3, -- (studs: how long the running flicker's tongues get at full rate)
		Cull = 180, -- (studs: farther from this camera than this, his exhaust rests)
		-- the ult's flicker
		turbo = {
			tex = TEX.fire, color = { PAL.TURBO_WHITE, PAL.TURBO_MAGENTA, PAL.TURBO_VIOLET }, size = { { 0, 0.6 }, { 0.5, 0.42 }, { 1, 0.08 } },
			transp = { { 0, 0 }, { 0.6, 0.3 }, { 1, 1 } }, life = { 0.08, 0.16 }, speed = { 9, 15 }, spread = 7, light = 0.6, bright = 1.6,
			spin = { -90, 90 }, locked = true, rate = 18,
		},
		-- the flicker's tongue at every mouth (a beam, its length jumping
		-- about at every update)
		beam = { color = { Color3.fromRGB(170, 225, 255), PAL.EXHAUST, PAL.EXHAUST_DEEP }, transp = { { 0, 0.05 }, { 0.6, 0.35 }, { 1, 1 } }, w0 = 0.2, w1 = 0.05, light = 0.4, bright = 1.3 },
		turboBeam = { PAL.TURBO_WHITE, PAL.TURBO_MAGENTA, PAL.TURBO_VIOLET },
	}
	function EK.drive(char)
		if EK.driving[char] then
			return EK.driving[char]
		end
		local hum = char and char:FindFirstChildOfClass("Humanoid")
		local root = char and char:FindFirstChild("HumanoidRootPart")
		if not (hum and root) or hum.Health <= 0 then
			return nil
		end
		local all = EK.mouths(char)
		if #all.all == 0 then
			return nil
		end
		local st = { char = char, root = root, hum = hum, emitters = {}, conns = {}, legs = {} }
		for _, side in { "Right", "Left" } do
			if all[side] then
				table.insert(st.legs, all[side][1].leg)
			end
		end
		local low = EK.lowEnd()
		for _, m in all.all do
			local e = {
				m = m,
				idle = EK.emitter(m.att, EK.JET.idle.emit),
				run = EK.emitter(m.att, EK.JET.run.emit),
				turbo = EK.emitter(m.att, EK.DRIVER.turbo),
			}
			if not (low and m.col == 2) then -- (a low-end machine: the outer column's only)
				e.tip = Instance.new("Attachment")
				e.tip.Name = "EngineMouthTip"
				e.tip.CFrame = CFrame.new(m.at)
				e.tip.Parent = m.leg
				e.beam = EK.beam(m.att, e.tip, EK.DRIVER.beam, 1, m.leg)
				e.beam.Width0, e.beam.Width1 = 0, 0
			end
			table.insert(st.emitters, e)
		end
		EK.driving[char] = st
		table.insert(st.conns, hum.Died:Connect(function()
			EK.undrive(char)
		end))
		table.insert(st.conns, char:GetAttributeChangedSignal("Quirk"):Connect(function()
			if char:GetAttribute("Quirk") ~= "Engine" then
				EK.undrive(char)
			end
		end))
		EK.update(st)
		return st
	end
	-- his exhaust off (and the mouths' attachments with it)
	function EK.undrive(char)
		local st = EK.driving[char]
		if not st then
			return
		end
		EK.driving[char] = nil
		for _, c in st.conns do
			c:Disconnect()
		end
		for _, e in st.emitters do
			for _, x in { e.idle, e.run, e.turbo, e.beam or false, e.tip or false } do
				if x then
					pcall(x.Destroy, x)
				end
			end
		end
		for _, leg in st.legs do
			local list = EK.mouthCache[leg]
			EK.mouthCache[leg] = nil
			for _, m in list or {} do
				pcall(m.att.Destroy, m.att)
			end
		end
	end
	-- the rates, from his speed (on the street; up in the air it keeps the
	-- last). (round 85 review) Not while he's thrown: knocked flying,
	-- ragdolled, stunned or carried, his speed isn't his - wisps only. Far
	-- from this camera (DRIVER.Cull) it all rests
	local THROWN = { Physics = true, FallingDown = true, Ragdoll = true, PlatformStanding = true }
	function EK.update(st)
		local ok, v = pcall(function()
			return st.root.AssemblyLinearVelocity
		end)
		v = ok and typeof(v) == "Vector3" and v or Vector3.zero
		local speed = Vector3.new(v.X, 0, v.Z).Magnitude
		local D = EK.DRIVER
		local low = EK.lowEnd() and 0.5 or 1
		local busy = EK.busy(st.char)
		local ult = st.char:GetAttribute("UltActive") == true
		local c = st.char
		local thrown = (c:GetAttribute("Ragdolled") or c:GetAttribute("Stunned") or c:GetAttribute("Grabbed")) and true or false
		if not thrown and EK.isMine(c) then -- (only this machine's own body has a state it can trust; the attributes replicate for all)
			local okState, state = pcall(function()
				return st.hum:GetState()
			end)
			thrown = okState and typeof(state) == "EnumItem" and THROWN[state.Name] == true
		end
		local cam = workspace.CurrentCamera
		local far = cam ~= nil and (st.root.CFrame.Position - cam.CFrame.Position).Magnitude > (D.Cull or 180)
		local run = thrown and 0 or math.clamp((speed - D.RunFrom) / (D.FullAt - D.RunFrom), 0, 1.8)
		local recolour = st.ultLook ~= ult
		st.speed, st.run, st.ult, st.busy, st.ultLook, st.thrown, st.far = speed, run, ult, busy, ult, thrown, far
		local flame = (busy or far) and 0 or math.min(run, 1.6)
		st.flame = flame
		-- the street under him, for the tongues (one ray, 10 times a second)
		if flame > 0.05 then
			local hit = groundRay(st.root.CFrame.Position, 12)
			st.gy = hit and hit.Position.Y or nil
		end
		for _, e in st.emitters do
			local flicker = 0.5 + rng:NextNumber()
			e.idle.Rate = (busy or far) and 0 or EK.JET.idle.emit.rate * math.max(1 - run * 1.5, 0) * low
			e.run.Rate = (busy or ult or far) and 0 or EK.JET.run.emit.rate * run * flicker * low
			e.turbo.Rate = (busy or not ult or far) and 0 or D.turbo.rate * math.max(run, 0.15) * flicker * low
			if e.beam then
				if recolour then
					e.beam.Color = EK.cs(ult and D.turboBeam or D.beam.color)
				end
				if flame > 0.05 then
					e.len = D.Flame * flame * (0.5 + rng:NextNumber() * 0.8)
					e.w0 = D.beam.w0 * (0.6 + 0.4 * math.min(flame, 1)) * (0.8 + rng:NextNumber() * 0.4)
					e.beam.Width1 = D.beam.w1
				else
					e.len = nil
					e.beam.Width0, e.beam.Width1 = 0, 0
				end
			end
		end
		if flame > 0.05 then
			EK.tongues(st)
		end
	end
	-- (round 85 review) the running tongues, every frame: out of the
	-- pipes, but never into the street (a leg swung forward tips them down)
	function EK.tongues(st)
		local gy = st.gy
		for _, e in st.emitters do
			if e.beam and e.len then
				local cf = e.m.leg.CFrame
				local l = e.len
				if gy then
					local w = cf:VectorToWorldSpace(e.m.dirL)
					if w.Y < -0.02 then
						l = math.min(l, math.max(((cf * e.m.at).Y - gy - 0.1) / -w.Y, 0))
					end
				end
				e.tip.CFrame = CFrame.new(e.m.at + e.m.dirL * math.max(l, 0.02))
				e.beam.Width0 = l > 0.12 and e.w0 or 0
				e.beam.Width1 = l > 0.12 and EK.DRIVER.beam.w1 or 0
			end
		end
	end
	-- who's Engine now: player bodies and the dummies get the exhaust; a
	-- body that's dead, gone or someone else loses it
	function EK.scan()
		local bodies = {}
		for _, plr in Players:GetPlayers() do
			if plr.Character then
				table.insert(bodies, plr.Character)
			end
		end
		local dummies = workspace:FindFirstChild("Dummies")
		for _, d in dummies and dummies:GetChildren() or {} do
			if d:IsA("Model") then
				table.insert(bodies, d)
			end
		end
		local now = os.clock()
		for _, c in bodies do
			if not EK.driving[c] and c:GetAttribute("Quirk") == "Engine" and c.Parent and not (EK.held[c] and now < EK.held[c]) then
				EK.drive(c)
			end
		end
		for c, st in EK.driving do
			local ok, keep = pcall(function()
				return c.Parent ~= nil and st.hum.Health > 0 and c:GetAttribute("Quirk") == "Engine"
			end)
			if not (ok and keep) then
				EK.undrive(c)
			end
		end
		-- (round 85 review) a leg that's gone (a body destroyed, a corpse
		-- cleared away) lets go of its mouths: the cached mouths hold their
		-- leg, so the weak key alone would never free them
		for leg, list in EK.mouthCache do
			local ok, inWorld = pcall(function()
				return leg:IsDescendantOf(workspace)
			end)
			if not (ok and inWorld) then
				EK.mouthCache[leg] = nil
				for _, m in list do
					pcall(m.att.Destroy, m.att)
				end
			end
		end
	end
	-- the running tongues follow his legs every frame (see EK.tongues)
	RunService.RenderStepped:Connect(function()
		for _, st in EK.driving do
			if st.flame and st.flame > 0.05 then
				pcall(EK.tongues, st)
			end
		end
	end)
	task.spawn(function()
		local last = -100
		while true do
			local ok, err = pcall(function()
				if os.clock() - last >= EK.DRIVER.Scan then
					last = os.clock()
					EK.scan()
				end
				for c, st in EK.driving do
					if not pcall(EK.update, st) then
						EK.undrive(c) -- (a body gone from under it)
					end
				end
			end)
			if not ok then
				warn("[VFX] engine exhaust: " .. tostring(err))
				task.wait(1)
			end
			task.wait(EK.DRIVER.Every)
		end
	end)

	-- everything of the kit on him off at once (his jets, his exhaust). The
	-- scan puts his exhaust back within half a second: EK.hold keeps it off
	function EK.clear(char)
		EK.undrive(char)
		for handle in EK.live[char] or {} do
			handle.stop(0)
		end
		EK.live[char] = nil
	end
	-- (round 85 review) EK.hold(char, t): everything of the kit on him off
	-- now (EK.clear) and his always-on exhaust kept off for t seconds (a
	-- cutscene that wants clean calves, Max's tubes); EK.hold(char, 0)
	-- lets it come back at the next scan
	function EK.hold(char, t)
		if not char then
			return
		end
		if t and t > 0 then
			EK.held[char] = os.clock() + t
			EK.clear(char)
		else
			EK.held[char] = nil
		end
	end
end

do -- IIDA's kicks (one table: the local limit)
	local IR = { charging = setmetatable({}, { __mode = "k" }) } -- [char] = the rev-up running

	-- a dash that follows where YOUR camera looks the whole way (your own
	-- machine flies you): turn the camera mid-dash and the dash turns with it
	function IR.steer(root, speed, duration, fallback)
		local att = Instance.new("Attachment")
		att.Parent = root
		local lv = Instance.new("LinearVelocity")
		lv.Attachment0 = att
		lv.MaxForce = moverForce(root, 6000)
		lv.RelativeTo = Enum.ActuatorRelativeTo.World
		local function heading()
			local cam = workspace.CurrentCamera
			local look = cam and Vector3.new(cam.CFrame.LookVector.X, 0, cam.CFrame.LookVector.Z)
			if look and look.Magnitude > 0.05 then
				return look.Unit
			end
			return fallback
		end
		lv.VectorVelocity = heading() * speed
		lv.Parent = root
		local t0 = os.clock()
		local conn
		conn = RunService.RenderStepped:Connect(function()
			if os.clock() - t0 > duration or not lv.Parent then
				conn:Disconnect()
				return
			end
			local h = heading()
			lv.VectorVelocity = h * speed
			face(root, h)
		end)
		cleanup(lv, duration)
		cleanup(att, duration)
	end

	-- (round 85) IIDA'S KICKS, REMADE (VFX.IidaKicks: one table, the local
	-- limit): his own M1 set (Config.M1.Styles.Engine = "Engine": the clips
	-- M1Engine1-4) and RECIPRO SPIN, ENGINE GATLING and SKYWARD KICK, played
	-- off his own clips (anim/moves_iida_k.py) and drawn with the Engine kit
	-- (VFX.EngineKit). Every effect lands on a key of the clip it goes with:
	-- the jets push a kick as it lands, the smear trails the leg that has
	-- just got there, the sparks and the broken street come on the contact
	-- frame, never ahead of it - and they wait out a hitstop with the body
	-- (IK.at: the pose clock; the Gatling's jabs and the Skyward hop keep the
	-- server's real time). Everything cleans itself up, and a low-end machine
	-- gets half (the kit's EK.count / EK.lowEnd).
	do
		local EK = VFX.EngineKit
		local IK = {
			-- each clip's named keys (seconds), as the clips are written: the
			-- server's beats. IK.mark reads them off the clip in the place, so
			-- the effects follow the clip; these if it isn't there
			MARKS = {
				MoveIidaSpin = { Hit = 0.1, Hit2 = 0.32 },
				MoveIidaGatling = { Jab = 1 / 12, Axe = 0.62 },
				MoveIidaAxe = { Top = 0.1, Hit = 0.18 },
				MoveIidaSkyward = { Push = 0.07, Hit = 0.14 },
			},
			read = {}, -- [clip name] = its named keys read off it (false: not in the place)
			-- each kick's smear by the shape of its swing (a set's own Kick wins):
			-- the plane (level round his hip, or vertical through it), the way
			-- it sweeps (1: to his left / up, -1: to his right / down), degrees
			SWING = {
				Straight = { plane = "vertical", spin = 1, arc = 130, tilt = 18 },
				Rise = { plane = "vertical", spin = 1, arc = 160, tilt = 18 },
				Drop = { plane = "vertical", spin = -1, arc = 150, tilt = 18 },
				HookRight = { spin = 1, arc = 150 },
				HookLeft = { spin = -1, arc = 150 },
			},
			-- the Gatling's ghost legs, { raise, across } in degrees: heights
			-- the real leg isn't at, so a few at once read as a hundred kicks
			-- (round 85 review: all of them into them - thigh to head, fanned
			-- either side of the real one and pushed on toward them, so the
			-- feet spread out past him - not up over his shoulder, where they
			-- read as a peacock's tail)
			GHOSTS = { { 78, -30 }, { 124, 10 }, { 96, -14 }, { 132, 26 }, { 86, -4 }, { 116, -32 }, { 104, 20 }, { 128, -18 }, { 74, 6 }, { 110, 30 }, { 90, -24 }, { 120, -2 } },
			-- dust kicked out along the street
			DUST = {
				tex = EK.TEX.smoke, color = { Color3.fromRGB(208, 190, 164), Color3.fromRGB(168, 148, 126) },
				size = { { 0, 0.9 }, { 0.4, 2 }, { 1, 2.8 } }, transp = { { 0, 0.25 }, { 0.6, 0.55 }, { 1, 1 } }, life = { 0.5, 0.8 },
				speed = { 14, 20 }, spread = 8, drag = 5, accel = Vector3.new(0, 2, 0), influence = 0.9, spin = { -40, 40 },
			},
			-- embers thrown off as the engines catch
			EMBERS = {
				tex = EK.TEX.spark, color = { EK.PAL.IGNITE, EK.PAL.EMBER }, size = { { 0, 0.32 }, { 1, 0 } }, transp = 0,
				life = { 0.3, 0.5 }, speed = { 10, 16 }, spread = 14, drag = 2, accel = Vector3.new(0, -24, 0), light = 1,
			},
		}
		VFX.IidaKicks = IK
		-- (an R15 body plays the round-79 motions; the barrage gets a simple one)
		MOTIONS.IidaSpin = MOTIONS.SpinKick
		MOTIONS.IidaAxe = MOTIONS.AxeKick
		MOTIONS.IidaSkyward = MOTIONS.Skyward
		MOTIONS.IidaGatling = {
			{ pose = { RightLeg = 70, RightKnee = 80, LeftKnee = 14, Waist = { 4, 0, 0 }, RightArm = { 20, 0, 22 }, LeftArm = { 60, 0, -10 }, LeftElbow = 100 }, t = 0.06 },
			{ pose = { RightLeg = 100, RightKnee = 4, LeftKnee = 16, Waist = { -8, 0, 0 }, RightArm = { -10, 0, 24 }, LeftArm = { 62, 0, -10 }, LeftElbow = 100 }, t = 0.04, hold = 0.42 },
			recover = 0.2,
		}

		-- a clip's named key (seconds): read off the clip in the place, else IK.MARKS
		function IK.mark(name, key)
			local m = IK.read[name]
			if m == nil then
				m = false
				local folder = game:GetService("ReplicatedStorage"):FindFirstChild("Animations")
				local ks = folder and folder:FindFirstChild(name)
				if ks and ks:IsA("KeyframeSequence") then
					m = {}
					for _, kf in ks:GetChildren() do
						if kf:IsA("Keyframe") and kf.Name ~= "Keyframe" then
							m[kf.Name] = kf.Time
						end
					end
				end
				IK.read[name] = m
			end
			return (m and m[key]) or (IK.MARKS[name] or {})[key] or 0
		end

		-- the server's task.wait(t) as it really runs: it ends on the server's
		-- next 60 Hz frame, so ENGINE GATLING's eight waits (Handlers.EngineGatling)
		-- add up to about 0.11 s more than their sum - its beats are counted the
		-- server's way (the barrage clip is written to them: a jab every 1/12 s)
		function IK.tick(t)
			return math.ceil(t * 60 - 1e-3) / 60
		end

		-- wait until `due` seconds of his pose clock have gone by since `from`
		-- (poseTime when his clip started): a hitstop's frozen time doesn't
		-- count, so the clip and its effects stay together, and one clock means
		-- the waits never add up their frames' rounding
		function IK.at(char, from, due)
			while char.Parent do
				local left = due - (poseTime(char, os.clock()) - from)
				if left <= 0 then
					return
				end
				task.wait(math.min(left, 0.05))
			end
		end

		-- his foot (the sole) and hip on one side, the leg as posed right now
		function IK.leg(char, side)
			local leg = char:FindFirstChild(side .. " Leg")
			if leg and leg:IsA("BasePart") then
				local h = leg.Size.Y / 2
				return leg.CFrame * Vector3.new(0, -h, 0), leg.CFrame * Vector3.new(0, h, 0)
			end
			local foot, upper = char:FindFirstChild(side .. "Foot"), char:FindFirstChild(side .. "UpperLeg")
			if foot and upper and foot:IsA("BasePart") and upper:IsA("BasePart") then
				return foot.Position, upper.CFrame * Vector3.new(0, upper.Size.Y / 2, 0)
			end
			return nil, nil
		end

		-- the kick smear trailing a leg that has just got where it is: an arc
		-- of opts.arc degrees round his hip (level with the foot, or on the
		-- upright plane through his hip: opts.plane = "vertical", its top
		-- leaning opts.tilt degrees out to his right - the leg's own lean out,
		-- and his own camera, behind him, sees it beside him rather than edge
		-- on) that ENDS where the foot is, having swept opts.spin's way (1: to
		-- his left or up, -1: to his right or down). The rest: EK.kickSmear's
		function IK.smear(root, foot, hip, opts)
			local look = Vector3.new(root.CFrame.LookVector.X, 0, root.CFrame.LookVector.Z)
			look = look.Magnitude > 0.01 and look.Unit or Vector3.new(0, 0, -1)
			local vertical = opts.plane == "vertical"
			local centre = vertical and hip or Vector3.new(hip.X, foot.Y, hip.Z)
			local cf = CFrame.lookAt(centre, centre + look)
			local tilt = math.rad(opts.tilt or 0)
			local axis = vertical and (cf.RightVector * math.cos(tilt) - UP * math.sin(tilt)) or UP
			local spin = opts.spin or 1
			local side = axis:Cross(look) * spin
			local v = foot - centre
			v -= axis * v:Dot(axis)
			local o = table.clone(opts)
			o.radius = math.clamp(v.Magnitude, opts.minRadius or 1.4, 4.5) + 0.2
			o.from = math.deg(math.atan2(v:Dot(side), v:Dot(look))) - (opts.arc or 120)
			o.spin = spin
			o.plane = vertical and axis or nil
			o.tilt = nil
			return EK.kickSmear(cf, o)
		end

		-- one-shot particles thrown out from a ring round pos, along the street
		-- (a dust ring, embers round his ankles): n points round a circle of
		-- `radius`, `per` from each, out (and `rise` up). One emitter, moved
		-- round the ring between its Emits
		function IK.ring(pos, radius, n, per, style, rise)
			local h = EK.holder(CFrame.new(pos), style.life[2] + 0.3, "EngineRing")
			local att = Instance.new("Attachment")
			att.Name = "EngineRing"
			att.Parent = h
			local pe = EK.emitter(att, style)
			local base = rand(0, math.pi * 2)
			n = EK.count(n)
			for i = 1, n do
				local a = base + (i - 1) / n * math.pi * 2
				local out = Vector3.new(math.cos(a), 0, math.sin(a))
				att.CFrame = CFrame.lookAt(out * radius, out * (radius + 1) + UP * (rise or 0))
				pe:Emit(per)
			end
			return h
		end

		-- a ghost of his right leg swung `raise` degrees up in front of him
		-- (and `across` toward his middle) about the hip, `push` studs on
		-- toward them: one of the Gatling's other kicks (R6 legs; an R15 body
		-- gets none). (round 85 review) Slimmer than the leg and see-through,
		-- with a streak behind the foot along the way it snapped up, so each
		-- one reads as a kick of its own rather than a glowing heap
		function IK.ghostLeg(char, raise, across, life, color, push)
			local torso, leg, root = char:FindFirstChild("Torso"), char:FindFirstChild("Right Leg"), char:FindFirstChild("HumanoidRootPart")
			if not (torso and leg and root) then
				return {}
			end
			local pivot = torso.CFrame * Vector3.new(torso.Size.X / 2, -torso.Size.Y / 2, 0)
			local swing = CFrame.new(pivot + root.CFrame.LookVector * (push or 0)) * (root.CFrame - root.CFrame.Position)
				* CFrame.Angles(0, math.rad(across), 0) * CFrame.Angles(math.rad(raise), 0, 0)
			local ghosts = EK.afterimage(char, color, life, { leg = "Right", cframes = { ["Right Leg"] = swing * CFrame.new(-leg.Size.X / 2, -leg.Size.Y / 2, 0) }, transparency = 0.4 })
			for _, g in ghosts do
				g.Size = Vector3.new(g.Size.X * 0.6, g.Size.Y, g.Size.Z * 0.6)
			end
			local foot = swing * Vector3.new(-leg.Size.X / 2, -leg.Size.Y, 0)
			local travel = swing:VectorToWorldSpace(Vector3.new(0, 0, 1)) -- (the way the foot came: back down its arc)
			EK.contrailLine(foot + travel * 1.7, foot, { width = 0.5, life = life * 0.7, color = color, core = not EK.lowEnd() })
			return ghosts
		end

		-- is anyone (alive, not him) standing in the box?
		function IK.near(char, cf, size)
			local half = size / 2
			for _, m in VFX.M1Kit.bodies() do
				local r = m ~= char and m:FindFirstChild("HumanoidRootPart")
				local hum = m:FindFirstChildOfClass("Humanoid")
				if r and hum and hum.Health > 0 then
					local p = cf:PointToObjectSpace(r.Position)
					if math.abs(p.X) <= half.X and math.abs(p.Y) <= half.Y and math.abs(p.Z) <= half.Z then
						return true
					end
				end
			end
			return false
		end

		-- a shock wave racing out across `dir` (UP: flat along the street):
		-- the kit's crisp ring of air opening to `size` studs across and
		-- thinning away over `life` (curved beams, not a part)
		function IK.shock(pos, dir, size, color, life)
			EK.vaporRings(pos, dir, 1, { size = size / 2, from = size * 0.08, life = life or 0.35, color = color or Color3.fromRGB(168, 214, 255) })
		end

		-- a column of dust blown up out of the street where the heel landed
		function IK.geyser(g)
			local h = EK.holder(CFrame.new(g + UP * 0.3), 2.4, "EngineGeyser")
			h.Size = Vector3.new(2, 0.4, 2)
			local pe = EK.emitter(h, {
				tex = EK.TEX.smoke, color = { Color3.fromRGB(212, 194, 168), Color3.fromRGB(150, 132, 112) },
				size = { { 0, 1.4 }, { 0.4, 3.2 }, { 1, 4.4 } }, transp = { { 0, 0.15 }, { 0.6, 0.45 }, { 1, 1 } }, life = { 0.9, 1.4 },
				speed = { 18, 30 }, spread = 16, dir = "Top", drag = 3.5, accel = Vector3.new(0, -4, 0), influence = 0.9, spin = { -30, 30 },
			})
			pe.Shape = Enum.ParticleEmitterShape.Box
			pe:Emit(EK.count(16))
			return h
		end

		-- (round 85 review) SKYWARD's vapor rising with them: the server
		-- launches them up at about 84 studs/s (95 x Knockback.MoveLift) for
		-- 0.2 s, so a ring of air is left round their legs every five or six
		-- studs on their way up (each a little smaller), and a soft ring rides
		-- up with them, slowing as they do
		function IK.lift(p)
			local base = p - UP * 1.5
			for i, step in { { 0.13, 8.5, 2.8 }, { 0.19, 14, 2.4 }, { 0.25, 19.5, 2 } } do
				if i <= EK.count(3) then
					task.delay(step[1], EK.vaporRings, base + UP * step[2], UP, 1, { size = step[3], from = 1, life = 0.32 })
				end
			end
			local h = EK.holder(CFrame.lookAt(base, base + UP), 0.8, "EngineVapor")
			local pe = EK.emitter(h, {
				tex = EK.TEX.ring, color = EK.PAL.VAPOR, size = { { 0, 4 }, { 0.3, 5.5 }, { 1, 6.5 } }, transp = { { 0, 0.1 }, { 0.5, 0.35 }, { 1, 1 } },
				life = { 0.45, 0.45 }, speed = { 120, 120 }, drag = 3, face = "VelocityPerpendicular", light = 0.4, influence = 0.6, rot = { 0, 360 },
			})
			pe:Emit(1)
		end

		-- (Effects.Punch, on every screen, at each M1's contact) the engines
		-- push the kick home: a short jet out of that calf's pipes, the bores
		-- flashing white-hot, and the smear its leg has just drawn (the set's
		-- Kick, or by its swing); the 4th - and its uppercut and downslam -
		-- with a backfire. In the ult, Turbo's colours. A punch: nothing
		-- (round 85 review) ...and it has to read from his own camera, right
		-- behind him: on hits 1-3 the jets blow out past his side, beside him
		-- on his camera (pointing with the leg they went down and under him,
		-- or straight at the camera), the smear is wider - the front kick's
		-- leaning well out to his right, past his body - and the air pops
		-- where the foot lands - a small flash and a tight ring of air, round
		-- on to his camera - landed or not; the 4th's camera kicks out a little
		function IK.punch(char, _count, finisher, _fist, _look, hit)
			local root = char:FindFirstChild("HumanoidRootPart")
			local limb = hit and hit.Limb
			if not root or (limb ~= "RightFoot" and limb ~= "LeftFoot") then
				return
			end
			local side = limb == "LeftFoot" and "Left" or "Right"
			local ult = char:GetAttribute("UltActive") == true
			local P = EK.PAL
			local look = Vector3.new(root.CFrame.LookVector.X, 0, root.CFrame.LookVector.Z)
			look = look.Magnitude > 0.01 and look.Unit or Vector3.new(0, 0, -1)
			local out = root.CFrame.RightVector * (side == "Right" and 1 or -1)
			EK.jets(char, ult and "turbo" or "burst", finisher and 0.2 or 0.16, {
				leg = side, len = finisher and 5 or 4.5, fade = 0.08,
				dir = not finisher and (out * 0.85 - look * 0.4 + UP * 0.2).Unit or nil,
			})
			EK.flash(char, side, ult and P.TURBO_WHITE or P.EXHAUST_CORE, finisher and 1.3 or 1.1)
			local foot, hip = IK.leg(char, side)
			if foot then
				-- (his clip drew the kick - its Kick arc; a body with no clip, an
				-- R15 one, plays the fallback motion: its swing)
				local clipped = hit.Kick ~= nil and char:FindFirstChild("Right Leg") ~= nil and IK.mark(hit.Motion, "Hit") > 0
				local k = (clipped and hit.Kick) or IK.SWING[(not clipped and hit.FallbackSwing) or hit.Swing or ""] or IK.SWING.Straight
				local r = finisher and 3.2 or 2.7
				IK.smear(root, foot, hip, {
					plane = k.plane, tilt = k.tilt, spin = k.spin, arc = k.arc, life = finisher and 0.55 or 0.4, draw = 0.03, minRadius = r, width = r * 0.8,
					color = ult and P.TURBO_SMEAR or nil, core = ult and P.TURBO_WHITE or Color3.new(1, 1, 1),
				})
				local pop = foot + look * 0.5
				EK.starSpark(pop, { size = finisher and 2.6 or 2, spikes = EK.lowEnd() and 4 or 6, life = 0.07, color = ult and P.TURBO_SMEAR or nil, color2 = Color3.new(1, 1, 1) })
				if not EK.lowEnd() then
					EK.vaporRings(pop, look, 1, { size = finisher and 2.2 or 1.7, from = 0.5, life = 0.22 })
				end
			end
			-- (the 4th's backfire is a full one, with its pop; the rest a puff)
			EK.backfire(char, side, finisher and { scale = 1, volume = 0.8 } or { scale = 0.55, sound = false })
			if finisher and EK.isMine(char) then
				EK.fovPunch(3, 0.04, 0.22)
			end
		end

		-- (Effects.Hit, on every screen) his 4th kick landing - its uppercut and
		-- downslam too: a star spark on it (the server's FinisherHitstop holds
		-- it there); hits 1-3 have the hit star (and IK.punch's small pop at
		-- the foot, landed or not)
		function IK.hitSpark(pos, data, attackerChar)
			local kind = data.M1
			if kind == 4 or kind == "Up" or kind == "Down" then
				local ult = attackerChar ~= nil and attackerChar:GetAttribute("UltActive") == true
				EK.starSpark(pos, { size = 4.2, life = 0.12, color = ult and EK.PAL.TURBO_SMEAR or nil })
			end
		end

		-- RECIPRO SPIN: two whirling turns, the server's hits at 0.10 and 0.32
		-- (the clip's Hit and Hit2). The engines catch as he starts - a cough
		-- of fire, embers thrown out round his ankles - and the jets run
		-- through the spin: his turning body swings the 12 of them round in a
		-- spiral of cyan flame, his calves trailing ribbons that draw it as a
		-- disc. Each turn's lash: a 330-degree smear behind the heel, a flat
		-- shock disc, dust kicked out in a ring; the finisher's also a white
		-- vapor ring round him, a backfire and a scorched ring on the street
		function IK.spinLash(char, root, finisher)
			local p = root.Position - UP * 0.4
			local g = groundPoint(root.Position)
			local foot, hip = IK.leg(char, "Right")
			IK.smear(root, foot or (p + root.CFrame.RightVector * 3), hip or p, { arc = 330, spin = -1, life = finisher and 0.55 or 0.4, draw = 0.05, minRadius = 3.4 })
			IK.shock(p, UP, finisher and 22 or 16)
			IK.ring(g + UP * 0.35, 1.6, 12, 2, IK.DUST, 0.08)
			VFX.PlaySound("Kick", p, finisher and 1.2 or 0.8)
			VFX.ShakeAt(p, finisher and 1.6 or 0.8, 50, 0.15)
			if finisher then
				EK.vaporRings(p, UP, 1, { size = 5.5, from = 2, life = 0.6 })
				EK.backfire(char, nil, { scale = 0.8, volume = 0.7 })
				groundMark(g, 2.8, Color3.fromRGB(62, 54, 52), 1.6)
			end
		end

		function Effects.SpinKick(char, data, isLocal)
			local root = charParts(char)
			if not root then
				return
			end
			local d = flatten(data.Dir, root)
			VFX.Motion(char, "IidaSpin")
			local from = poseTime(char, os.clock())
			EK.ignite(char, { len = 3.2, dur = 0.42, snap = 0.06, volume = 0.75 })
			IK.ring(groundPoint(root.Position) + UP * 0.45, 0.9, 10, 2, IK.EMBERS, 0.3)
			EK.legTrails(char, 0.46, { width = 1.3, life = 0.3 })
			VFX.PlaySound("Engine", root.Position, 0.8)
			if isLocal then
				-- his root turns twice at 28 rad/s (his own machine: it
				-- replicates), then faces the aim; a hitstop holds it with his body
				task.spawn(function()
					local turned, last, t0 = 0, os.clock(), os.clock()
					while turned < 0.44 * 28 and root.Parent and os.clock() - t0 < 1.5 do
						task.wait()
						local now = os.clock()
						if not stopped(char) then
							local step = math.min((now - last) * 28, 0.44 * 28 - turned)
							root.CFrame = root.CFrame * CFrame.Angles(0, -step, 0)
							turned += step
						end
						last = now
					end
					if root.Parent then
						face(root, d)
					end
				end)
			end
			for i, key in { "Hit", "Hit2" } do
				IK.at(char, from, IK.mark("MoveIidaSpin", key))
				if not root.Parent or not EK.alive(char) then
					return
				end
				IK.spinLash(char, root, i == 2)
			end
		end

		-- ENGINE GATLING: a kick on each of the server's jabs (the first at
		-- 1/12 s, then every 1/12: IK.tick, on real time like the server's),
		-- then the axe kick on its beat (the heel lands 0.18 s into
		-- MoveIidaAxe, on the server's 0.80). Each kick, as the clip's leg
		-- reaches full stretch: the held jets pulse, a small star spark where
		-- the foot is, three ghost legs into them at other heights (with the
		-- real one, a fan of kicks at once) and a short streak; the rev climbs
		-- the whole way through
		function IK.jab(char, root, d, i, isLocal)
			local foot = IK.leg(char, "Right")
			-- (where it lands: just past the foot, out toward them - and no
			-- lower than their stomach, should a hitstop have held the leg
			-- back in its chamber on the beat)
			local rel = foot and root.CFrame:PointToObjectSpace(foot) or Vector3.new(0.5, 0, -2.4)
			local at = root.Position + d * (math.max(-rel.Z, 2) + 1.2) + UP * math.max(rel.Y, -1.2)
			if i % 2 == 1 or not EK.lowEnd() then
				EK.starSpark(at, { size = 2.6, spikes = 6, life = 0.08, color2 = Color3.new(1, 1, 1) })
			end
			EK.contrailLine(at - d * 2.2 + UP * rand(-0.3, 0.3), at, { width = 0.55, life = 0.16, color = EXHAUST })
			for k = 1, EK.count(3) do
				local gh = IK.GHOSTS[(i * 3 + k) % #IK.GHOSTS + 1]
				IK.ghostLeg(char, gh[1], gh[2], 0.2, EXHAUST, 0.7 + 0.35 * (k - 1))
			end
			if isLocal then
				VFX.Shake(0.3, 0.06) -- (his own screen feels each one)
			end
		end

		-- the axe: as the heel reaches the top a crescent trails it up and the
		-- jets fire straight up to drive it down (the clip's Top); as it
		-- lands (Hit) a crescent down, a crater with radial cracks and rocks, a
		-- dust geyser, a shock disc and a star, a held impact frame on his own
		-- screen if it caught someone; then his pipes glow red-hot
		function IK.heel(char, root, d, isLocal)
			local foot, hip = IK.leg(char, "Right")
			local g = groundPoint(root.Position + d * 3.4)
			if foot then
				IK.smear(root, foot, hip, { plane = "vertical", tilt = 20, spin = -1, arc = 120, life = 0.4, draw = 0.03 })
			end
			EK.cracks(g, 9, 8, { rocks = 8, glow = EXHAUST })
			IK.geyser(g)
			EK.cloud(g, 1.3)
			IK.shock(g + UP * 0.4, UP, 26, nil, 0.4)
			EK.starSpark(g + UP * 1.4, { size = 4.6, life = 0.12 })
			VFX.PlaySound("Downslam", g, 1)
			VFX.ShakeAt(g, 1.8, 70, 0.3)
			EK.hotPipes(char, 1)
			if isLocal and IK.near(char, CFrame.lookAt(root.Position, root.Position + d) * CFrame.new(0, 0, -4), Vector3.new(11, 14, 11)) then
				VFX.ImpactFrame(0.09)
			end
		end

		function Effects.EngineGatling(char, data, isLocal, ability)
			local root = charParts(char)
			if not root then
				return
			end
			ability = ability or {}
			local d = flatten(data.Dir, root)
			if isLocal then
				face(root, d)
			end
			local t0 = os.clock()
			local hits, interval = ability.Hits or 7, ability.Interval or 0.07
			local first, beat = IK.mark("MoveIidaGatling", "Jab"), IK.tick(interval)
			-- (the axe comes on the server's beat - its task.wait(0.08), a jab and
			-- a task.wait(Interval) each, task.wait(0.12), the heel - however long
			-- hitstops held the barrage back)
			local axeAt = IK.tick(0.08) + hits * beat + IK.tick(0.12) - IK.mark("MoveIidaAxe", "Hit")
			VFX.Motion(char, "IidaGatling")
			local stopJets, jets
			for i = 1, hits do
				-- (round 85 review) the jabs on the server's clock, as its jabs
				-- are: each landed one puts a 0.02 s hitstop on him, which holds
				-- his leg a moment - not the beat, or a landed barrage drifts late
				-- and loses its last kicks to the axe
				local left = first + (i - 1) * beat - (os.clock() - t0)
				if left > 0 then
					task.wait(left)
				end
				if not root.Parent or not EK.alive(char) or os.clock() - t0 > axeAt then
					break
				end
				if not jets then
					-- (held to the axe at most: a backstop should anything break)
					stopJets, jets = EK.jets(char, "burst", axeAt + 0.1, { leg = "Right", len = 2.2 })
					VFX.PlaySound("EngineGatling", root.Position, 1)
				end
				jets.pulse(4.6, 0.06)
				IK.jab(char, root, d, i, isLocal)
			end
			if stopJets then
				stopJets(0.06)
			end
			local left = axeAt - (os.clock() - t0)
			if left > 0 then
				task.wait(left)
			end
			if not root.Parent or not EK.alive(char) then
				return
			end
			VFX.Motion(char, "IidaAxe")
			local from = poseTime(char, os.clock())
			local top, hit = IK.mark("MoveIidaAxe", "Top"), IK.mark("MoveIidaAxe", "Hit")
			IK.at(char, from, top)
			if not root.Parent or not EK.alive(char) then
				return
			end
			local foot, hip = IK.leg(char, "Right")
			if foot then
				IK.smear(root, foot, hip, { plane = "vertical", tilt = 24, spin = 1, arc = 140, life = 0.32, draw = 0.04 })
			end
			-- (the leg hangs at the top from Top to the chop: the jets fire up
			-- the whole while, long, the bores flaring)
			EK.jets(char, "burst", hit - top + 0.05, { leg = "Right", dir = UP, len = 6, fade = 0.05 })
			EK.flash(char, "Right", EK.PAL.EXHAUST_CORE, 1.7)
			EK.backfire(char, "Right", { scale = 0.7, sound = false })
			VFX.PlaySound("EngineBackfire", root.Position, 0.7)
			IK.at(char, from, hit)
			if not root.Parent or not EK.alive(char) then
				return
			end
			IK.heel(char, root, d, isLocal)
		end
	end

	-- (round 85) RECIPRO BURST and RECIPRO EXTEND, remade on the Engine kit
	-- (VFX.EngineKit) with Iida's own clips (anim/moves_iida_b.py): the gear
	-- set, the flying side kick, the stall, the sprinter's start, the rocket
	-- kick and its carry, his re-fire kick, the whiff's skid. Every strike's
	-- effects wait for its clip's contact frame; everything cleans itself up
	-- (EK.gone); a low-end machine gets half (EK.count / EK.lowEnd).
	do
		local EK = VFX.EngineKit
		local PAL = EK.PAL
		IR.releasing = setmetatable({}, { __mode = "k" }) -- [char] = his Burst was let go (not cancelled)
		IR.bursting = setmetatable({}, { __mode = "k" }) -- [char] = the Burst dashes running
		IR.extending = setmetatable({}, { __mode = "k" }) -- [char] = the Extend running: { token, the held jets }
		VFX.HitHooks = VFX.HitHooks or setmetatable({}, { __mode = "k" })
		-- each clip's contact (its "Hit" key), for a place or body without the clip
		IR.HIT = {
			MoveIidaBurstKick = 0.07, MoveIidaBurstKickL = 0.07, PoseIidaExtendKick = 0.075,
			PoseIidaExtendCarry = 0.03, MoveIidaRefire = 0.07,
		}
		-- the clips' other beats (their named keys; the client test pins them):
		-- the start's slam (the frost shatters), the jets' snap to cyan in the
		-- set, the re-fire's and the whiff's landings, when the whiff folds over
		IR.BEAT = { ExtendSlam = 0.2, ExtendSnap = 0.34, RefireLand = 0.28, SkidLand = 0.1, SkidStall = 0.55 }
		-- (round 85 review) where his back foot is planted in the gear-3 set
		-- (studs behind his root: PoseIidaSet's REAR[3]) - the street splits there
		IR.REAR3 = 1.9
		function IR.contact(name)
			local clip = VFX.GetClip and VFX.GetClip(name)
			return (clip and clip.hit) or IR.HIT[name] or 0
		end
		-- (round 85 review) his clip's own clock: a hit's freeze (VFX.Hitstop)
		-- holds his pose, so it holds a beat of the clip too - a contact
		-- frame is waited for on this clock, not the wall clock (a watcher
		-- gets the release and a close hit's freeze in the same frame: the
		-- leg comes out that much later, and so must its effects)
		function IR.poseAt(char)
			return poseTime(char, os.clock())
		end
		function IR.poseWait(char, p0, t)
			while poseTime(char, os.clock()) - p0 < t - 1e-3 and char.Parent do
				task.wait()
			end
		end
		-- (round 85 review) a piece of a strike carried along with someone
		-- moving fast (the carry runs at 120 studs/s, a Burst at 160: left
		-- where it was made it'd hang in the air behind them in a frame or
		-- two). obj: a part (a holder, a disc), kept at its offset from `on`
		function IR.ride(obj, on, life)
			if not (obj and on and obj.Parent) then
				return
			end
			local off = obj.CFrame - on.Position
			for _, pe in obj:GetChildren() do
				if pe:IsA("ParticleEmitter") then
					pe.LockedToPart = true
				end
			end
			task.spawn(function()
				local t0 = os.clock()
				while os.clock() - t0 < life and obj.Parent and on.Parent do
					obj.CFrame = off + on.Position
					task.wait()
				end
			end)
		end
		-- the rev climbing a gear at a time
		IR.REV = { "ReciproRev", "ReciproRev2", "ReciproRev3" }

		-- R15 bodies (no clips): the procedural poses and motions
		POSES.IidaSet = {
			Crouch = 0.5, Waist = { -26, 0, 0 }, Neck = { 18, 0, 0 },
			RightArm = { 70, 0, 6 }, LeftArm = { -50, 0, 10 }, RightElbow = 10,
			RightLeg = { -28, 0, 6 }, LeftLeg = { 36, 0, 4 }, RightKnee = 20, LeftKnee = 60,
		}
		POSES.IidaStall = {
			Crouch = 0.3, Waist = { -42, 0, 0 }, Neck = { -10, 0, 0 },
			RightArm = { 32, 0, -10 }, LeftArm = { 32, 0, -10 }, RightKnee = 30, LeftKnee = 30,
		}
		POSES.IidaExtendCarry = {
			Waist = { 14, 0, -10 }, Neck = { -10, 0, 8 }, RightLeg = { 104, 0, 6 }, LeftLeg = { -24, 0, 4 }, LeftKnee = 70,
			RightArm = { -40, 0, 30 }, LeftArm = { -40, 0, 30 },
		}
		MOTIONS.IidaBurstKick = { { pose = "Kick", t = 0.06, hold = 0.16 }, recover = 0.18 }
		MOTIONS.IidaBurstKickL = { { pose = "KickLeft", t = 0.06, hold = 0.16 }, recover = 0.18 }
		MOTIONS.IidaRefire = {
			{ pose = { RightLeg = 60, RightKnee = 50, Waist = { 6, 0, 0 }, RightArm = { -20, 0, 30 }, LeftArm = { -20, 0, 30 } }, t = 0.04 },
			{ pose = { RightLeg = 150, RightKnee = 0, LeftKnee = 20, Waist = { 25, 0, 0 }, RightArm = { -40, 0, 50 }, LeftArm = { -40, 0, 50 } }, t = 0.04, hold = 0.18, style = Enum.EasingStyle.Back },
			{ pose = "Land", t = 0.08, hold = 0.25 },
			recover = 0.25,
		}
		MOTIONS.IidaExtendSkid = { { pose = "Land", t = 0.08, hold = 0.4 }, recover = 0.25 }

		-- the stall's bent-double pose lets go the moment he walks off (or
		-- anything else takes his body)
		function IR.walkOut(char, dur)
			local root, hum = charParts(char)
			local mine = VFX.PoseToken and VFX.PoseToken(char)
			if not (root and hum and mine) then
				return
			end
			task.spawn(function()
				local t0 = os.clock()
				task.wait(0.15)
				while os.clock() - t0 < dur and char.Parent and VFX.PoseToken(char) == mine do
					local v = root.AssemblyLinearVelocity
					if (EK.isMine(char) and hum.MoveDirection.Magnitude > 0.1) or (os.clock() - t0 > 0.3 and Vector3.new(v.X, 0, v.Z).Magnitude > 9) then
						-- (round 85 review) his legs are the walk's again at once
						-- (no end-lag), but he stays slumped over them, heaving,
						-- for the rest of the stall (an R15 body straightens up)
						local left = math.clamp(dur - 0.25 - (os.clock() - t0), 0.3, 0.8)
						if not VFX.Clip(char, "PoseIidaStallWalk", { legs = false, holdFor = left, recover = 0.3 }) then
							VFX.ReleasePose(char, 0.2)
						end
						return
					end
					task.wait(1 / 20)
				end
			end)
		end

		-- a side kick's crescent: the foot's arc from low on the kicking side up
		-- to dead ahead, in a plane tipped 30 degrees off the upright, so it
		-- reads as a curve from behind him too (not a line seen edge on)
		function IR.sideArc(cf, right, opts)
			opts.plane = (cf.RightVector * (right and 1 or -1) + cf.UpVector * 0.6).Unit
			opts.spin = right and 1 or -1
			return opts
		end

		-- (the jets as thrust: straight back off him and a touch up, whatever
		-- angle his calves are at in the clip - a deep set tips the back of the
		-- rear calf toward the sky. EK.jets reads opts.dir every frame, so the
		-- move keeps it pointing behind him as he turns)
		function IR.thrust(root, up)
			return (-flatten(root.CFrame.LookVector, root) + UP * (up or 0.15)).Unit
		end

		-- the cyan ghosts he leaves while he's fast: for everyone watching him
		-- (on his own screen they'd fill the view from behind him, and his
		-- body would be lost under the newest one)
		function IR.ghost(char, mine, life)
			if not mine then
				EK.afterimage(char, PAL.EXHAUST, life, { transparency = 0.6 })
			end
		end

		-- a flat ring of dust blown out along the street from his feet, and a
		-- low cloud (a gear shift; (round 85 review) color: PAL.FROST for the
		-- Extend's slam - a pale ring of cold mist)
		function IR.dustRing(g, size, color)
			color = color or PAL.DUST
			local h = EK.holder(CFrame.new(g + UP * 0.25), 1.4, "EngineDust")
			local pe = EK.emitter(h, {
				tex = EK.TEX.ring, color = color, size = { { 0, 1.5 }, { 1, size * 2.2 } }, transp = { { 0, 0.15 }, { 0.6, 0.5 }, { 1, 1 } },
				life = { 0.55, 0.65 }, speed = { 0.2, 0.2 }, dir = "Top", face = "VelocityPerpendicular", influence = 0.8, rot = { 0, 360 },
			})
			pe:Emit(EK.lowEnd() and 1 or 2)
			EK.cloud(g, 0.45 + size * 0.03, color, 0.2, false)
		end

		-- dust torn up off the street behind him while the engines scream
		-- (held: returns stop). (round 85 review) It stops by itself after
		-- life (6) seconds whatever happens: the Extend's start is played
		-- ahead of the server on his own screen, and if the go never comes
		-- (stunned, grabbed, a desync) nothing else would stop it
		function IR.groundDust(root, rate, life)
			local h = EK.holder(root.CFrame, nil, "EngineDust")
			h.Size = Vector3.new(2, 0.4, 1)
			local pe = EK.emitter(h, {
				tex = EK.TEX.smoke, color = { PAL.DUST, Color3.fromRGB(170, 140, 108) }, size = { { 0, 0.9 }, { 0.5, 2 }, { 1, 2.8 } },
				transp = { { 0, 0.3 }, { 0.6, 0.55 }, { 1, 1 } }, life = { 0.5, 0.9 }, speed = { 6, 11 }, spread = 28, drag = 3,
				accel = Vector3.new(0, 2, 0), influence = 0.9, spin = { -30, 30 },
			})
			pe.Shape = Enum.ParticleEmitterShape.Box
			pe.Rate = EK.count(rate or 18)
			local alive = true
			local function stop()
				if alive then
					alive = false
					pe.Enabled = false
					EK.gone(h, 1)
				end
			end
			local t0 = os.clock()
			task.spawn(function()
				while alive and root.Parent and h.Parent and os.clock() - t0 < (life or 6) do
					local back = flatten(-root.CFrame.LookVector, root)
					local g = groundPoint(root.Position) + UP * 0.3 + back * 1.6
					h.CFrame = CFrame.lookAt(g, g + back) -- (blowing back off his heels)
					task.wait(0.1)
				end
				stop()
			end)
			return stop
		end

		-- a gear shift: the gearbox kicks (the clip jolts him down a notch on
		-- the same frame), a backfire off both calves, a dust ring; gear 2
		-- switches the coughing fire to held cyan jets, gear 3 stretches them,
		-- turns the mouths red-hot, splits the street under his back foot and
		-- (his own screen) tightens the camera. Returns the held jets' handle
		function IR.gearShift(char, root, level, isLocal, stops, jets, left, jopts)
			VFX.PlaySound("EngineGear", root.Position, 1)
			VFX.PlaySound(IR.REV[level] or "ReciproRev", root.Position, 0.9)
			EK.backfire(char, nil, { scale = 0.9 + 0.25 * level, sound = false })
			local g = groundPoint(root.Position)
			IR.dustRing(g, 4 + level * 2)
			VFX.ShakeAt(root.Position, 0.4 + 0.3 * level, 40, 0.15)
			if not jets then
				-- the coughing fire turns to held cyan jets
				EK.flash(char, nil, PAL.EXHAUST_CORE, 1.3)
				jopts.len, jopts.dir = 3, IR.thrust(root, 0.25)
				local stop, h = EK.jets(char, "burst", nil, jopts)
				jets = h
				table.insert(stops, stop)
				table.insert(stops, IR.groundDust(root, 14, left + 1))
			end
			if level >= 3 then
				jets.setLen(6)
				jets.pulse(8.5, 0.2)
				EK.flash(char, nil, Color3.new(1, 1, 1), 1.6)
				table.insert(stops, EK.hotPipes(char, math.max(left, 0.2) + 0.8))
				-- the street splits under his back (right) foot, the seams glowing
				EK.cracks(root.CFrame * Vector3.new(0.6, -3, IR.REAR3), 4.5, 6, { crater = false, glow = PAL.EXHAUST, life = 1.8 })
				if not isLocal then
					-- (round 85 review: not on his own screen - round his legs, under
					-- the jets coming at the lens, it turned his lower body into a
					-- white blob; he has the dust ring)
					EK.vaporRings(groundPoint(root.Position) + UP * 0.6, UP, 1, { size = 4.5, from = 1.5, life = 0.45 })
				end
				if isLocal then
					-- the tension: the view narrows while he holds it
					EK.fovPunch(-6, 0.22, 0.2, math.max(left, 0.1))
					VFX.Hooks.Dim(0.32, math.max(left, 0.1))
				end
			end
			return jets
		end

		-- RECIPRO BURST (held): the engines rev harder the longer it's held, a
		-- gear at a time (Hold.Levels): a shallow sprinter's set with the
		-- pipes coughing yellow-orange fire; gear 2 jolts him down and the
		-- flames turn to cyan jets; gear 3 again, deeper, long white-cored
		-- jets, red-hot mouths, the street splitting, his view tightening -
		-- until he lets go
		function Effects.ReciproBurst(char, _data, isLocal, ability)
			local root = charParts(char)
			if not root then
				return
			end
			ability = ability or Config.FindAbilityById("ReciproBurst") or {}
			local spec = ability.Hold or {}
			local max = spec.Max or 1.6
			local token = {}
			IR.charging[char] = token
			IR.releasing[char] = nil
			VFX.Pose(char, "IidaSet", max + 0.5)
			VFX.PlaySound("ReciproRev", root.Position, 0.8)
			if isLocal then
				VFX.Hooks.Dim(0.2, max)
			end
			-- the engines catching: a cough of fire and embers off both calves
			EK.jets(char, "ignite", 0.16, { len = 1.6 })
			local stops = {}
			local jets
			local jopts = {} -- (the held jets' options: their aim follows him)
			local t0 = os.clock()
			local level, nextCough, nextRev = 1, 0.18, 0.45
			while IR.charging[char] == token and root.Parent and EK.alive(char) and os.clock() - t0 < max + 0.5 do
				local now = os.clock() - t0
				local reached = 1
				for i, t in spec.Levels or {} do
					if now >= t then
						reached = i + 1
					end
				end
				if reached > level then
					level = reached
					jets = IR.gearShift(char, root, level, isLocal, stops, jets, max - now, jopts)
				end
				if jopts.dir then
					jopts.dir = IR.thrust(root, 0.25)
				end
				if level == 1 and now >= nextCough then
					-- gear 1: the pipes sputtering - yellow-orange coughs and embers
					nextCough = now + rand(0.1, 0.17)
					local side = rng:NextNumber() < 0.5 and "Right" or "Left"
					EK.pop(char, side, EK.PUFF.fire, 4, 0.8)
					EK.pop(char, side, EK.PUFF.sparks, 2, 0.6)
				end
				if now >= nextRev then
					nextRev = now + 0.42
					VFX.PlaySound(IR.REV[level] or "ReciproRev", root.Position, 0.45 + 0.15 * level)
				end
				task.wait(1 / 30)
			end
			-- let go (the dashes take over), cancelled, or knocked out: the
			-- held jets, dust and glow end; a cancel gives his view back
			-- (a quick fade into the dashes: a stopped jet stays put on his calf
			-- as the kick swings it round)
			for _, s in stops do
				s(IR.releasing[char] and 0.03 or 0.15)
			end
			if isLocal and not IR.releasing[char] then
				EK.fovPunch(0, 0.12, 0.01, 0)
			end
			if isLocal then
				-- (round 85 review) the hold's dim lifts the moment it ends (it
				-- was timed to the longest hold: a tap left the dashes dimmed)
				VFX.Hooks.Dim(0, 0.05)
			end
			if IR.charging[char] == token then
				IR.charging[char] = nil
			end
		end

		-- a hit of a Burst dash, where it lands (Effects.Hit -> VFX.HitHooks):
		-- a star and a cyan shock disc through them, and on the last strike the
		-- big crescent across them - on the kick's contact frame, never before it.
		-- (round 85 review) Which strike it is comes from the server (Heavy: the
		-- last one), not from the dash this screen is on. On his own screen the
		-- dashes run ahead of the server, so its hits come in a round trip late
		-- (dash 1's can land during dash 2): the leg's out already, it's drawn
		-- at once. Anyone else can get a hit before the leg's out (a close
		-- target: in the same frame as the release, its freeze holding his
		-- clip): it waits for the contact on his clip's own clock. It all rides
		-- along with them (the last strike knocks them flying)
		function IR.burstHit(char, target, hit, dash, level, mine)
			local troot = target and target:FindFirstChild("HumanoidRootPart")
			local root = charParts(char)
			if not (troot and root) then
				return
			end
			local last = hit.Heavy == true
			if not mine then
				IR.poseWait(char, dash.p0, dash.contact)
			end
			if not (troot.Parent and root.Parent) then
				return
			end
			local pos = troot.Position
			local d = flatten(pos - root.Position, root)
			IR.ride(EK.starSpark(pos - d * 0.6, { size = (last and 3.6 or 2.6) + 0.4 * level, life = last and 0.12 or 0.1 }), troot, 0.15)
			local disc = shockDisc(pos, d, 2, last and 12 + level * 3 or 9, 0.25, PAL.EXHAUST)
			disc.Name = "EngineShock"
			EK.gone(disc, 0.3)
			IR.ride(disc, troot, 0.25)
			if last then
				-- (the last strike is always off his right leg)
				local smear = EK.kickSmear(CFrame.lookAt(pos - d * 1.5, pos + d), IR.sideArc(CFrame.lookAt(pos, pos + d), true, { arc = 150, from = -70, radius = 3.4, life = 0.55 }))
				IR.ride(smear, troot, 0.4)
				local me = Players.LocalPlayer and Players.LocalPlayer.Character
				if me == target or (mine and level < 3) then
					VFX.ImpactFrame(0.045) -- (gear 3's own: the sound barrier's)
				end
			end
		end

		-- gear 3's last strike breaks the sound barrier: a white flash, a big
		-- white ring and a bigger one a beat behind it, the contrail along the
		-- whole run, the boom
		function IR.soundBarrier(char, root, d, runStart, mine)
			local p = root.Position + d * 2
			if mine then
				VFX.ImpactFrame(0.08)
				task.delay(0.08, VFX.Hooks.Flash, Color3.new(1, 1, 1), 0.16)
			elseif nearCamera(p, 90) then
				VFX.Hooks.Flash(Color3.fromRGB(235, 245, 255), 0.12)
			end
			EK.vaporRings(p, d, 1, { size = 4.5, from = 2, life = 0.5 })
			task.delay(0.08, EK.vaporRings, p + d * 3, d, 1, { size = 7.5, from = 3, life = 0.6 })
			local disc = shockDisc(p, d, 6, 30, 0.35, WIND, 14)
			disc.Name = "EngineShock"
			EK.gone(disc, 0.5)
			EK.contrailLine(runStart + UP * 0.6, p, { width = 1.2, life = 1.1 })
			VFX.PlaySound("ReciproBarrier", p, 1.2)
			VFX.PlaySound("ReciproBoom", p, 1)
			VFX.ShakeAt(p, 2.4, 90, 0.35)
		end

		-- ...he let go: one dash strike per gear (a flying side kick, legs
		-- alternating, the last off the right), each following where he looks
		-- (on his own screen). Each launch: the bores flash and cough, the
		-- jets roar, vapor rings hang where he was, the mach cone, the dust
		-- wake, cyan ghosts; each contact: the kick's crescent and a backfire
		-- off the kicking calf (each hit: Effects.Hit's hook above). Gear 3's
		-- last breaks the sound barrier. Then the engines stall
		function Effects.ReciproBurstRelease(char, data, isLocal, ability)
			local root = charParts(char)
			if not root then
				return
			end
			IR.releasing[char] = true
			IR.charging[char] = nil
			ability = ability or Config.FindAbilityById("ReciproBurst") or {}
			local level = math.clamp(tonumber(data.Level) or 1, 1, 3)
			local dashTime = ability.DashTime or 0.18
			local speed = ability.DashSpeed or 160
			local fallback = flatten(typeof(data.Dir) == "Vector3" and data.Dir or root.CFrame.LookVector, root)
			local mine = isLocal or EK.isMine(char)
			local token = {}
			IR.bursting[char] = token
			local runStart = root.Position
			local dash = { p0 = IR.poseAt(char), contact = 0.07 }
			-- (round 85 review) the hook claims each hit's look (Effects.Hit
			-- draws no generic star of its own: it would come before the contact)
			local hook = function(target, hit)
				if IR.bursting[char] ~= token then
					return false
				end
				task.spawn(IR.burstHit, char, target, type(hit) == "table" and hit or {}, { p0 = dash.p0, contact = dash.contact }, level, mine)
				return true
			end
			VFX.HitHooks[char] = hook
			-- (round 85 review) one set of jets for the whole release: each
			-- launch jumps them out, each pivot pulls them in (a set a dash cost
			-- three times the instances, and a stopped set swung round with his leg)
			local jlen = 3.5 + level
			local jopts = { len = 1.5, dir = IR.thrust(root) }
			local stopJets, jets = EK.jets(char, "burst", nil, jopts)
			for i = 1, level do
				if not root.Parent or not EK.alive(char) or IR.bursting[char] ~= token then
					break
				end
				local last = i == level
				local right = (level - i) % 2 == 0
				local clip = right and "IidaBurstKick" or "IidaBurstKickL"
				-- (this dash's clock first: a hit that comes in from here on
				-- belongs to it)
				local p0, contact = IR.poseAt(char), IR.contact("Move" .. clip)
				dash.p0, dash.contact = p0, contact
				VFX.Motion(char, clip)
				if isLocal then
					IR.steer(root, speed, dashTime, fallback)
					EK.fovPunch(({ 10, 12, 16 })[level] + (last and 2 or 0), 0.06, 0.3, dashTime - 0.06)
				end
				local d = flatten(root.CFrame.LookVector, root)
				local from = root.Position
				-- the launch
				EK.flash(char, nil, Color3.new(1, 1, 1), 1.2)
				EK.pop(char, nil, EK.PUFF.fire, 6, 1)
				jopts.dir = IR.thrust(root)
				jets.setLen(jlen)
				jets.pulse(jlen * 1.6, 0.12)
				EK.machCone(root, dashTime + 0.02, { size = 0.75 + 0.15 * level })
				if not mine then
					-- (rings hanging where he was: his own camera would fly through them)
					EK.vaporRings(from + d * 1.5, d, last and level or math.min(level, 2), { size = 2.8 + 0.4 * level })
				end
				EK.dustWall(from, from + d * speed * dashTime, { time = dashTime, height = 0.7 + 0.2 * level, cloud = false })
				VFX.PlaySound("Engine", root.Position, 0.8)
				-- the contact, on his clip's own clock (a hit's freeze holds it):
				-- the kick's crescent, riding with him to the dash's end, and the
				-- kicking calf backfiring
				task.spawn(function()
					IR.poseWait(char, p0, contact)
					if IR.bursting[char] ~= token or not root.Parent then
						return
					end
					local cf = root.CFrame
					local smear = EK.kickSmear(cf * CFrame.new(right and 0.6 or -0.6, -0.4, 0), IR.sideArc(cf, right, { arc = 110, from = -78, radius = 3.2, life = 0.4, draw = 0.05 }))
					IR.ride(smear, root, math.max(dashTime - contact, 0.05))
					EK.backfire(char, right and "Right" or "Left", { scale = 0.8, sound = false })
					VFX.PlaySound("Kick", cf.Position, last and 1.1 or 0.8)
					if last and level == 3 then
						IR.soundBarrier(char, root, flatten(cf.LookVector, root), runStart, mine)
					end
				end)
				-- the flight: a cyan ghost every few frames
				local t1 = os.clock() + dashTime
				while os.clock() < t1 and root.Parent do
					IR.ghost(char, mine, 0.22)
					jopts.dir = IR.thrust(root)
					task.wait(EK.lowEnd() and 0.09 or 0.045)
				end
				if not last and root.Parent and IR.bursting[char] == token then
					-- the pivot into the next one: the blow-off, the jets pulled in
					jets.setLen(1.5)
					EK.backfire(char, nil, { scale = 0.6, volume = 0.6 })
					task.wait(0.08)
					jopts.dir = IR.thrust(root)
				end
			end
			stopJets(0.12)
			-- (round 85 review) his own screen gets the server's hits a round
			-- trip late: the hook stays that much longer there
			local linger = 0.35
			if mine then
				local ok, ping = pcall(function()
					return Players.LocalPlayer:GetNetworkPing()
				end)
				linger += (ok and type(ping) == "number") and math.clamp(ping * 2, 0, 0.8) or 0.3
			end
			task.delay(linger, function()
				if IR.bursting[char] == token then
					IR.bursting[char] = nil
				end
				if VFX.HitHooks[char] == hook then
					VFX.HitHooks[char] = nil
				end
			end)
			if not root.Parent or not EK.alive(char) or IR.bursting[char] ~= token then
				return
			end
			-- the stall: bent double, the engines choking
			EK.cloud(groundPoint(root.Position), 0.8 + 0.1 * level, nil, nil, false)
			VFX.Pose(char, "IidaStall", 0.95)
			IR.walkOut(char, 1.2)
			EK.stall(char, 2 + 0.2 * level)
		end

		-- (round 75) R: RECIPRO EXTEND - (round 85, canon) the engines cooled
		-- by ice: a frost crust on his calves, an anticipation hop, and he
		-- slams down into the blocks: the frost shatters off in a burst of
		-- steam, the mufflers slide out (three a calf, white-hot), the pipes
		-- catch - orange fire and embers - and snap to straight cyan jets
		-- licking the street, the street splitting under his back foot; then
		-- GO: one rocket of a kick down the aim; the one he meets rides his
		-- leg along, then the engines fire again
		POSES.SprinterStart = {
			Crouch = 0.8, Waist = { -38, 0, 0 }, Neck = { 26, 0, 0 },
			RightArm = { -45, 0, 12 }, LeftArm = { 55, 0, -8 }, RightElbow = 30, LeftElbow = 40,
			RightLeg = { -38, 0, 6 }, LeftLeg = { 48, 0, 4 }, RightKnee = 30, LeftKnee = 90,
		}
		POSES.ExtendKick = {
			Waist = { 8, 0, -10 }, Neck = { -6, 0, 8 }, RightLeg = { 92, 0, 6 }, LeftLeg = { -24, 0, 4 }, LeftKnee = 60,
			RightArm = { -30, 0, 30 }, LeftArm = { 40, 0, 20 },
		}
		POSES.IidaExtendSet = POSES.SprinterStart
		POSES.IidaExtendKick = POSES.ExtendKick
		IR.pipes = setmetatable({}, { __mode = "k" })
		-- the mufflers: three long silver tubes a calf, out of the outer
		-- column of pipe mouths, sliding out at `at` (0.18 s), their tips
		-- white-hot cooling to red; they slide back in when the move's over
		-- (IR.pipes[char] changes) or after life
		function IR.extendPipes(char, life, at)
			local token = {}
			IR.pipes[char] = token
			at = at or 0
			local list = {}
			for _, m in EK.mouths(char).all do
				if m.col == 1 then
					local w = 0.24 * math.min(m.leg.Size.X, 1)
					local tube = newPart(Vector3.new(w, w, 0.1), m.leg.CFrame * m.cf, Color3.fromRGB(200, 206, 216), Enum.Material.Metal)
					tube.Name = "EngineMuffler"
					local tip = newPart(Vector3.new(w * 1.25, w * 1.25, 0.12), m.leg.CFrame * m.cf, Color3.new(1, 1, 1), Enum.Material.Neon)
					tip.Name = "EngineMuffler"
					table.insert(list, { m = m, tube = tube, tip = tip })
				end
			end
			local t0 = os.clock()
			task.spawn(function()
				local out = 0
				while os.clock() - t0 < life and IR.pipes[char] == token and EK.alive(char) do
					local t = os.clock() - t0
					out = math.clamp((t - at) / 0.18, 0, 1)
					out = 1 - (1 - out) * (1 - out)
					local hot = math.clamp((t - at - 0.4) / 0.8, 0, 1)
					for _, e in list do
						if e.m.leg.Parent then
							local len = 0.1 + 1.15 * out
							local base = e.m.leg.CFrame * e.m.cf
							e.tube.Size = Vector3.new(e.tube.Size.X, e.tube.Size.Y, len)
							e.tube.CFrame = base * CFrame.new(0, 0, -len / 2 + 0.06)
							e.tip.CFrame = base * CFrame.new(0, 0, -len + 0.02)
							e.tip.Color = Color3.new(1, 1, 1):Lerp(PAL.HOT_PIPE, hot)
						end
					end
					task.wait()
				end
				-- back in
				local b0 = os.clock()
				while os.clock() - b0 < 0.15 and EK.alive(char) do
					local len = 0.1 + 1.15 * out * (1 - (os.clock() - b0) / 0.15)
					for _, e in list do
						if e.m.leg.Parent then
							local base = e.m.leg.CFrame * e.m.cf
							e.tube.Size = Vector3.new(e.tube.Size.X, e.tube.Size.Y, len)
							e.tube.CFrame = base * CFrame.new(0, 0, -len / 2 + 0.06)
							e.tip.CFrame = base * CFrame.new(0, 0, -len + 0.02)
						end
					end
					task.wait()
				end
				for _, e in list do
					e.tube:Destroy()
					e.tip:Destroy()
				end
			end)
			-- (the harness's Debris never runs; EK.gone is the safety net)
			for _, e in list do
				EK.gone(e.tube, life + 0.5)
				EK.gone(e.tip, life + 0.5)
			end
			return list
		end

		-- the frost Todoroki put on his calves: a crust of ice shards round each
		-- calf, a cold mist off it; at `at` it shatters off - the shards
		-- flung out spinning, a burst of steam out of the pipes, the hiss
		function IR.frost(char, at)
			local made = {}
			for _, L in EK.legs(char) do
				local leg = L.leg
				local sz = leg.Size
				-- a see-through shell of ice round the calf (the engine shows through)...
				local off = CFrame.new(0, -sz.Y * 0.2, 0)
				local shell = newPart(Vector3.new(sz.X + 0.2, sz.Y * 0.6, sz.Z + 0.2), leg.CFrame * off, PAL.FROST, Enum.Material.Ice)
				shell.Name = "EngineFrost"
				shell.Transparency = 0.4
				EK.weld(shell, leg, off)
				table.insert(made, { part = shell, leg = leg, dir = Vector3.zero, shell = true })
				-- ...and jagged shards sticking out of it
				local n = EK.count(7) -- (round 85 review: spaced round the whole calf, however many)
				for i = 1, n do
					local a = (i - 1) / n * math.pi * 2 + rand(-0.3, 0.3)
					local o = CFrame.new(math.cos(a) * (sz.X * 0.5 + 0.12), -sz.Y * rand(0.02, 0.42), math.sin(a) * (sz.Z * 0.5 + 0.12))
						* CFrame.Angles(rand(-0.7, 0.7), a, rand(-0.7, 0.7))
					local shard = newPart(Vector3.new(rand(0.3, 0.45), rand(0.45, 0.8), rand(0.14, 0.24)), leg.CFrame * o, PAL.FROST:Lerp(Color3.new(1, 1, 1), rand(0, 0.4)), Enum.Material.Ice)
					shard.Name = "EngineFrost"
					shard.Transparency = 0.1
					EK.weld(shard, leg, o)
					table.insert(made, { part = shard, leg = leg, dir = (leg.CFrame * o).Position - leg.Position })
				end
			end
			-- a cold mist rolling off the ice
			local mist = {}
			for _, L in EK.legs(char) do
				local a = Instance.new("Attachment")
				a.Name = "EngineFX"
				a.Position = Vector3.new(0, -L.leg.Size.Y * 0.25, 0)
				a.Parent = L.leg
				local pe = EK.emitter(a, {
					tex = EK.TEX.smoke, color = PAL.FROST, size = { { 0, 0.4 }, { 1, 1.4 } }, transp = { { 0, 0.5 }, { 1, 1 } },
					life = { 0.5, 0.8 }, speed = { 0.5, 1.5 }, spread = 180, accel = Vector3.new(0, -1.5, 0), influence = 0.8, dir = "Top",
				})
				pe.Rate = EK.count(14)
				table.insert(mist, a)
				EK.gone(a, at + 1)
			end
			task.delay(at, function()
				for _, a in mist do
					for _, pe in a:GetChildren() do
						if pe:IsA("ParticleEmitter") then
							pe.Enabled = false
						end
					end
				end
				local root = char:FindFirstChild("HumanoidRootPart")
				for _, f in made do
					local p = f.part
					if p.Parent then
						local cf = p.CFrame
						for _, w in p:GetChildren() do
							if w:IsA("Weld") then
								w:Destroy()
							end
						end
						p.Anchored = true
						p.CFrame = cf
						if f.shell then
							tween(p, 0.08, { Transparency = 1, Size = p.Size * 1.15 })
						else
							local out = (f.dir.Magnitude > 0.01 and f.dir.Unit or UP) + UP * 0.6
							tween(p, 0.4, { CFrame = (cf + out * rand(2, 3.5)) * CFrame.Angles(rand(-3, 3), rand(-3, 3), rand(-3, 3)), Transparency = 1 }, Enum.EasingStyle.Quad, Enum.EasingDirection.Out)
						end
					end
					EK.gone(p, 0.45)
				end
				if root and EK.alive(char) then
					-- the steam: a white burst out of the pipes and round his calves
					-- (round 85 review: big enough to read from across the street)
					EK.pop(char, nil, {
						tex = EK.TEX.smoke, color = { Color3.new(1, 1, 1), STEAM }, size = { { 0, 1.2 }, { 0.4, 4 }, { 1, 5.5 } }, transp = { { 0, 0.05 }, { 0.6, 0.4 }, { 1, 1 } },
						life = { 0.6, 1 }, speed = { 8, 15 }, spread = 75, drag = 4, accel = Vector3.new(0, 6, 0), influence = 0.5, spin = { -60, 60 },
					}, 16, 1)
					-- ...and the shattered frost spraying off them, glinting
					EK.pop(char, nil, { tex = EK.TEX.spark, color = { Color3.new(1, 1, 1), PAL.FROST }, size = { { 0, 0.5 }, { 1, 0 } }, transp = 0, life = { 0.3, 0.5 },
						speed = { 14, 26 }, spread = 85, accel = Vector3.new(0, -40, 0), light = 1 }, 14, 1)
					VFX.PlaySound("ExtendFrost", root.Position, 1)
				end
			end)
			return made
		end

		-- his own camera drops low behind his calves through the start (the
		-- anime's shot of the pipes lighting) and comes back up as he goes
		IR.cam = setmetatable({}, { __mode = "k" })
		function IR.camLow(char, on)
			local hum = char:FindFirstChildOfClass("Humanoid")
			if not hum or not EK.isMine(char) then
				return
			end
			local saved = IR.cam[char]
			if on and not saved then
				IR.cam[char] = { offset = hum.CameraOffset }
				pcall(tween, hum, 0.22, { CameraOffset = hum.CameraOffset + Vector3.new(0, -2.4, 1.2) }, Enum.EasingStyle.Sine) -- (round 85 review: lower, nearer his calves)
			elseif not on and saved then
				IR.cam[char] = nil
				pcall(tween, hum, 0.18, { CameraOffset = saved.offset }, Enum.EasingStyle.Sine)
			end
		end

		-- the violet radial speed-line burst behind someone he's just hit (the
		-- Stain double-kick frame): thin lines flat to the camera, thick at
		-- the rim and sharp toward the middle, shooting outward and gone.
		-- (round 85 review) opts.follow (their root part): it frames them for
		-- its whole life - the carry moves them both at 120 studs/s, and a
		-- burst left where it was made hung in the air behind them
		function IR.radialBurst(pos, opts)
			opts = opts or {}
			-- (its plane flat to this camera, 2.5 studs behind them: the lines
			-- lie in the holder's X-Y plane)
			local function frameAt(p)
				local cam = workspace.CurrentCamera
				local look = cam and (p - cam.CFrame.Position) or Vector3.new(0, 0, -1)
				look = look.Magnitude > 0.01 and look.Unit or Vector3.new(0, 0, -1)
				local right = look:Cross(math.abs(look.Y) > 0.95 and Vector3.new(1, 0, 0) or UP).Unit
				return CFrame.fromMatrix(p + look * 2.5, right, right:Cross(look))
			end
			local life = opts.life or 0.28
			local r0, r1 = opts.inner or 2, opts.outer or 7.5
			local h = EK.holder(frameAt(pos), life + 0.3, "EngineRadial")
			local n = EK.count(opts.lines or 18)
			local colors = { PAL.TURBO_VIOLET, Color3.new(1, 1, 1), PAL.TURBO_SMEAR, PAL.TURBO_VIOLET }
			for i = 1, n do
				local a = (i - 1) / n * math.pi * 2 + rand(-0.08, 0.08)
				local dir = Vector3.new(math.cos(a), math.sin(a), 0)
				local inner = r0 * rand(0.8, 1.3)
				local outer = r1 * rand(0.7, 1.1)
				local a0 = Instance.new("Attachment")
				a0.Name = "EngineRadial"
				a0.CFrame = CFrame.new(dir * inner)
				a0.Parent = h
				local a1 = Instance.new("Attachment")
				a1.Name = "EngineRadial"
				a1.CFrame = CFrame.new(dir * inner * 1.1)
				a1.Parent = h
				local color = colors[i % #colors + 1]
				local w = (color == colors[2] and 0.22 or 0.42) * rand(0.7, 1.2)
				local b = EK.beam(a0, a1, { color = color, transp = { { 0, 0.7 }, { 0.4, 0.15 }, { 1, 0 } }, w0 = 0.02, w1 = w, light = 0.5, bright = 1.4 }, 1, h)
				b.Name = "EngineRadial"
				-- shoots outward, then thins away from the middle out
				tween(a1, 0.06, { CFrame = CFrame.new(dir * outer) }, Enum.EasingStyle.Quad, Enum.EasingDirection.Out)
				tween(a0, life, { CFrame = CFrame.new(dir * outer * 0.85) }, Enum.EasingStyle.Quad, Enum.EasingDirection.In, 0.04)
				tween(b, life * 0.5, { Width1 = 0 }, Enum.EasingStyle.Quad, Enum.EasingDirection.In, life * 0.5)
			end
			-- a violet glow behind it all
			local glow = EK.emitter(h, { tex = EK.TEX.glow, color = PAL.TURBO_VIOLET, size = { { 0, r1 * 0.6 }, { 1, r1 * 1.1 } }, transp = { { 0, 0.35 }, { 1, 1 } },
				life = { life, life }, speed = { 0, 0 }, light = 0.6, rot = { 0, 0 }, z = -1, locked = true })
			glow:Emit(1)
			local follow = opts.follow
			if follow then
				task.spawn(function()
					local t0 = os.clock()
					while os.clock() - t0 < life + 0.1 and h.Parent and follow.Parent do
						h.CFrame = frameAt(follow.Position)
						task.wait()
					end
				end)
			end
			return h
		end

		-- a heel skidding along the street: sparks spraying off it, a dust
		-- wake, the scrape (the clip plants the right heel ahead of him)
		function IR.heelSkid(char, d, dur)
			local root = charParts(char)
			local leg = char:FindFirstChild("Right Leg") or char:FindFirstChild("RightFoot") or char:FindFirstChild("RightLowerLeg")
			if not (root and leg) or not EK.alive(char) then
				return
			end
			local h = EK.holder(leg.CFrame, dur + 0.5, "EngineFX")
			local pe = EK.emitter(h, {
				tex = EK.TEX.spark, color = { PAL.IGNITE_CORE, PAL.IGNITE, PAL.EMBER }, size = { { 0, 0.32 }, { 1, 0 } }, transp = 0,
				life = { 0.18, 0.35 }, speed = { 12, 24 }, spread = 32, accel = Vector3.new(0, -35, 0), drag = 1, light = 1,
			})
			pe.Rate = EK.count(70)
			local t0 = os.clock()
			task.spawn(function()
				-- (riding his heel, spraying back and up off the street)
				while os.clock() - t0 < dur and leg.Parent and h.Parent do
					local heel = leg.CFrame * Vector3.new(0, -leg.Size.Y / 2, 0)
					h.CFrame = CFrame.lookAt(heel, heel - d + UP * 0.45)
					task.wait()
				end
				pe.Enabled = false
			end)
			local g = groundPoint(root.Position)
			EK.dustWall(g + UP * 3, g + UP * 3 + d * (6 + dur * 10), { time = dur, height = 0.8, cloud = false })
			VFX.PlaySound("Skid", g, 1)
		end

		function Effects.ReciproExtend(char, data, isLocal, ability)
			local root = charParts(char)
			if not root then
				return
			end
			ability = ability or Config.FindAbilityById("ReciproExtend") or {}
			local startup = ability.Startup or 0.45
			local d = flatten(typeof(data.Dir) == "Vector3" and data.Dir or root.CFrame.LookVector, root)
			local token = {}
			IR.extending[char] = { token = token }
			if isLocal then
				face(root, d)
				VFX.Hooks.Callout("RECIPRO... EXTEND!!", Color3.fromRGB(150, 215, 255))
				IR.camLow(char, true)
				EK.fovPunch(-12, 0.25, 0.3, startup) -- (round 85 review: tighter - a closer look at the pipes)
				-- (the camera comes back up by itself if the go never comes)
				task.delay(startup + 0.9, function()
					if IR.extending[char] and IR.extending[char].token == token then
						IR.camLow(char, false)
					end
				end)
			end
			local slam = IR.BEAT.ExtendSlam
			IR.extendPipes(char, startup + (ability.Range or 95) / (ability.Speed or 175) + (ability.Carry or 0.4) + 1, slam + 0.04)
			VFX.Pose(char, "IidaExtendSet", startup + 0.35)
			IR.frost(char, slam)
			VFX.PlaySound("ReciproRev", root.Position, 0.7)
			task.delay(slam, function()
				local x = IR.extending[char]
				if not (x and x.token == token and not x.went) or not EK.alive(char) then
					return -- (gone already, cancelled, or knocked out)
				end
				-- the slam into the blocks: the pipes catch (orange fire and
				-- embers) and snap to long cyan jets, held till he goes
				local g = groundPoint(root.Position)
				IR.dustRing(g, 5)
				IR.dustRing(g, 8, PAL.FROST) -- (round 85 review: a pale ring of cold mist rolling out - the start reads from afar)
				VFX.ShakeAt(root.Position, 0.8, 40, 0.15)
				x.ignite = EK.ignite(char, { len = 5.5, snap = IR.BEAT.ExtendSnap - slam, dur = startup + 1.2, dir = IR.thrust(root, 0.05) })
				x.hot = EK.hotPipes(char, startup + 1.4)
				task.delay(IR.BEAT.ExtendSnap - slam, function()
					if not (IR.extending[char] and IR.extending[char].token == token and not x.went) or not EK.alive(char) then
						return
					end
					-- the street splits under his back foot; dust rolls off the jets
					EK.cracks(root.CFrame * Vector3.new(0.6, -3, 2.3), 4, 6, { crater = false, glow = PAL.EXHAUST, life = 1.6 })
					x.dust = IR.groundDust(root, 16, startup + 0.8) -- (round 85 review: it stops by itself if the go never comes)
					VFX.PlaySound("EngineGear", root.Position, 0.8)
				end)
			end)
		end

		-- GO: out of the blocks - the bore flash, three vapor rings hanging
		-- where he was, his view punched wide; the contrail, the mach cone, the
		-- dust wall and cyan ghosts the whole way
		function Effects.ReciproExtendGo(char, data, isLocal)
			local root = charParts(char)
			if not root then
				return
			end
			local d = flatten(typeof(data.Dir) == "Vector3" and data.Dir or root.CFrame.LookVector, root)
			local time = tonumber(data.Time) or 0.5
			local speed = tonumber(data.Speed) or 175
			local mine = isLocal or EK.isMine(char)
			local x = IR.extending[char] or { token = {} }
			IR.extending[char] = x
			x.went = true
			-- (round 85 review) the hit he's about to land is drawn on the carry
			-- clip's contact frame (Effects.ReciproExtendHit): the server's Hit,
			-- which comes in just before it (its freeze holding his clip),
			-- claims its look, so no generic star comes first
			local hook = function(_, hit)
				return IR.extending[char] == x and type(hit) == "table" and hit.Heavy == true
			end
			VFX.HitHooks[char] = hook
			task.delay(time + 2, function()
				if VFX.HitHooks[char] == hook then
					VFX.HitHooks[char] = nil
				end
			end)
			for _, k in { "ignite", "dust" } do
				if x[k] then
					x[k](0.05)
					x[k] = nil
				end
			end
			if mine then
				IR.steer(root, speed, time, d)
				VFX.Hooks.SpeedLines(time + 0.3)
				IR.camLow(char, false)
				EK.boreFlash()
				EK.fovPunch(16, 0.06, 0.4, 0.12)
			end
			VFX.Pose(char, "IidaExtendKick", time + 0.1)
			local start = root.Position
			EK.flash(char, nil, Color3.new(1, 1, 1), 1.6)
			if not mine then
				-- (rings hanging where he was; his own camera would fly through them)
				EK.vaporRings(start + d * 1.5, d, 3, { size = 4 })
			end
			EK.cloud(groundPoint(start), 1.2, nil, nil, false)
			local disc = shockDisc(start - d * 2, -d, 2, 16, 0.3, PAL.EXHAUST, 4)
			disc.Name = "EngineShock"
			EK.gone(disc, 0.35)
			VFX.PlaySound("ReciproBoom", start, 1)
			x.jopts = { len = 6.5, dir = IR.thrust(root, 0.1) }
			x.stopJets, x.jets = EK.jets(char, "burst", time + 0.6, x.jopts)
			EK.machCone(root, time, { size = 1.25 })
			if not mine then
				EK.contrail(root, time + 0.4, { width = 1.4, life = 0.9 })
			end
			EK.legTrails(char, time + 0.4)
			EK.dustWall(start, start + d * speed * time, { time = time, height = 1.3, cloud = false })
			local t0 = os.clock()
			while os.clock() - t0 < time and root.Parent and IR.extending[char] == x do
				IR.ghost(char, mine, 0.25)
				x.jopts.dir = IR.thrust(root, 0.1)
				task.wait(EK.lowEnd() and 0.08 or 0.04)
			end
		end

		-- the kick lands: he carries them along on it. On the carry clip's
		-- contact: the impact frame (his screen and theirs), the violet radial
		-- burst behind them, the crescent up through them, a star, the jets
		-- jumping; then streaks peel off both of them
		function Effects.ReciproExtendHit(char, data, isLocal)
			local root = charParts(char)
			local target = typeof(data.Target) == "Instance" and data.Target
			local troot = target and target:FindFirstChild("HumanoidRootPart")
			if not root then
				return
			end
			local d = flatten(typeof(data.Dir) == "Vector3" and data.Dir or root.CFrame.LookVector, root)
			local carry = tonumber(data.Carry) or 0.4
			local mine = isLocal or EK.isMine(char)
			if mine then
				IR.steer(root, tonumber(data.Speed) or 120, carry, d)
			end
			VFX.Pose(char, "IidaExtendCarry", carry + 0.1)
			local x = IR.extending[char]
			-- (round 85 review) on his clip's own clock: the hit's freeze holds
			-- the clip (and so its contact) a beat; every piece rides along with
			-- them through the carry
			local p0 = IR.poseAt(char)
			task.spawn(function()
				IR.poseWait(char, p0, IR.contact("PoseIidaExtendCarry"))
				if not root.Parent then
					return
				end
				local on = (troot and troot.Parent) and troot or root
				local pos = on == troot and troot.Position or root.Position + d * 3
				local me = Players.LocalPlayer and Players.LocalPlayer.Character
				if mine or (me and me == target) then
					VFX.ImpactFrame(0.08)
				end
				IR.radialBurst(pos, { follow = on })
				IR.ride(EK.kickSmear(CFrame.lookAt(root.Position, root.Position + d) * CFrame.new(0.5, -0.5, 0), { plane = "vertical", arc = 120, from = -70, radius = 3.4, life = 0.5 }), root, 0.5)
				IR.ride(EK.starSpark(pos - d * 0.8, { size = 4.5, life = 0.12 }), on, 0.15)
				local disc = shockDisc(pos, d, 2, 14, 0.25, Color3.new(1, 1, 1))
				disc.Name = "EngineShock"
				EK.gone(disc, 0.3)
				IR.ride(disc, on, 0.25)
				if x and x.jets then
					x.jets.pulse(9, 0.2)
				end
				VFX.PlaySound("ReciproBoom", pos, 0.7)
				VFX.ShakeAt(pos, 1.6, 70, 0.3)
			end)
			if troot and not mine then
				-- (a streak peeling off them; on his own screen it would run
				-- back through him into the camera)
				EK.contrail(troot, math.max(carry - 0.05, 0.1), { width = 0.8, life = 0.35 }) -- (round 85 review: off before they're flung - on, it drew a rope from the carry up to them)
			end
			local t0 = os.clock()
			while os.clock() - t0 < carry and root.Parent do
				IR.ghost(char, mine, 0.2)
				if x and x.jopts then
					x.jopts.dir = IR.thrust(root, 0.1)
				end
				task.wait(EK.lowEnd() and 0.1 or 0.05)
			end
		end

		-- the engines fire again: off they go. His own kick (the re-fire: the
		-- leg re-chambers and drives up through them); on its contact a second
		-- ignition at the calves, a white ring and a cyan shock disc where they
		-- leave him, them flung away trailing white; he drops onto his heel and
		-- skids
		function Effects.ReciproExtendLaunch(char, data)
			local root = charParts(char)
			local d = (typeof(data.Dir) == "Vector3" and data.Dir.Magnitude > 0.01) and data.Dir.Unit or (root and root.CFrame.LookVector) or Vector3.new(0, 0, -1)
			local pos = typeof(data.Pos) == "Vector3" and data.Pos or (root and root.Position)
			if not pos then
				return
			end
			local target = typeof(data.Target) == "Instance" and data.Target
			local troot = target and target:FindFirstChild("HumanoidRootPart")
			local x = root and IR.extending[char]
			local p0
			if root then
				VFX.Motion(char, "IidaRefire")
				p0 = IR.poseAt(char)
			end
			task.spawn(function()
				if root then
					IR.poseWait(char, p0, IR.contact("MoveIidaRefire")) -- (on his clip's own clock)
				end
				if root and EK.alive(char) then
					EK.flash(char, nil, Color3.new(1, 1, 1), 1.8)
					EK.backfire(char, nil, { scale = 1.5, sound = false })
					if x and x.jets then
						x.jets.setLen(8)
						x.jets.pulse(11, 0.25)
					else
						EK.jets(char, "burst", 0.35, { len = 8 })
					end
				end
				EK.vaporRings(pos, d, 1, { size = 5, from = 2 })
				local disc = shockDisc(pos, d, 3, 22, 0.35, PAL.EXHAUST, 8)
				disc.Name = "EngineShock"
				EK.gone(disc, 0.45)
				EK.starSpark(pos, { size = 5, life = 0.12, color2 = Color3.new(1, 1, 1) })
				if troot then
					EK.contrail(troot, 0.6, { width = 0.45, life = 0.28 }) -- (round 85 review: a short streak behind them, not a rope back to him)
				end
				VFX.PlaySound("ReciproBoom", pos, 1.2)
				VFX.PlaySound("SonicBoom", pos, 0.8)
				VFX.ShakeAt(pos, 2.4, 110, 0.4)
				if nearCamera(pos, 80) then
					VFX.Hooks.Flash(Color3.fromRGB(210, 235, 255), 0.2)
				end
			end)
			if not root then
				return
			end
			-- down onto his heel: the skid, then the jets and mufflers go
			task.delay(IR.BEAT.RefireLand, function()
				if x and x.stopJets and IR.extending[char] == x then
					x.stopJets(0.15)
				end
				IR.heelSkid(char, flatten(d, root), 0.3)
			end)
			task.delay(0.65, function()
				if IR.extending[char] == x then
					IR.extending[char] = nil
					IR.pipes[char] = nil
				end
			end)
		end

		-- nobody there: down onto his heel in a long skid, sparks spraying off
		-- it, and the engines - spent - stall
		function Effects.ReciproExtendWhiff(char, data)
			local root = charParts(char)
			if not root then
				return
			end
			local x = IR.extending[char]
			local d = flatten(typeof(data) == "table" and typeof(data.Dir) == "Vector3" and data.Dir or root.CFrame.LookVector, root)
			VFX.Motion(char, "IidaExtendSkid")
			task.delay(IR.BEAT.SkidLand, function()
				if x and x.stopJets then
					x.stopJets(0.2)
				end
				IR.heelSkid(char, d, 0.45)
			end)
			task.delay(IR.BEAT.SkidStall, function()
				if not EK.alive(char) or IR.extending[char] ~= x then
					return
				end
				IR.extending[char] = nil
				IR.pipes[char] = nil
				VFX.Pose(char, "IidaStall", 0.9)
				IR.walkOut(char, 1.1)
				EK.stall(char, 2.2)
			end)
		end
	end

	-- a held move that never went: the rev-up just stops
	function Effects.HoldCancel(char)
		IR.charging[char] = nil
		VFX.coloradoCharge[char] = nil -- (round 75: Colorado's crouch)
		VFX.ReleasePose(char)
		if VFX.NukeDrop then
			VFX.NukeDrop(char) -- (the NUKE too: knocked out holding it)
		end
		if VFX.SEDrop then
			VFX.SEDrop(char) -- (and Suneater's Plasma Cannon)
		end
		if VFX.FaJinDrop then
			VFX.FaJinDrop(char) -- (and Deku's Fa Jin wind-up)
		end
	end

	-- SKYWARD KICK: a leg straight up, and he hops up after them. (round 85)
	-- On his own clip (MoveIidaSkyward) and its keys: as the back foot
	-- pushes off (Push) its pipes fire straight down into the street - a
	-- dust ring, a small crater; on the kick (Hit, 0.14 - the server's hit;
	-- the round-79 effects fired 0.04 s before the old clip's) a crescent
	-- trails the leg up past his face, its jets fire straight down as a cyan
	-- pillar, a star on them, white vapor rings left up the way they're
	-- launched (IK.lift), and his own camera widens; a contrail on his hop
	function Effects.SkywardKick(char, data, isLocal)
		local root, hum = charParts(char)
		if not root then
			return
		end
		local EK, IK = VFX.EngineKit, VFX.IidaKicks
		local d = flatten(data.Dir, root)
		if isLocal then
			face(root, d)
		end
		local ult = char:GetAttribute("UltActive") == true
		local mode = ult and "turbo" or "burst"
		VFX.Motion(char, "IidaSkyward")
		-- (round 85 review) the hop keeps the round-79 schedule, on real time
		-- (0.14 s, then 0.08 s), whatever the effects wait on: a hitstop still
		-- running on him when he casts holds his clip and its effects back,
		-- never the hop - the server launches them on its own 0.14. Its
		-- contrail rides it, on every screen
		task.delay(0.14, function()
			if root.Parent then
				task.delay(0.08, function()
					if not root.Parent then
						return
					end
					if isLocal and hum then
						launch(root, hum, UP * 85 + d * 6)
					end
					if EK.alive(char) then
						EK.contrail(root, 0.5, { width = 1, life = 0.55 })
					end
				end)
			end
		end)
		local from = poseTime(char, os.clock())
		local push, hit = IK.mark("MoveIidaSkyward", "Push"), IK.mark("MoveIidaSkyward", "Hit")
		IK.at(char, from, push)
		if not root.Parent or not EK.alive(char) then
			return
		end
		EK.jets(char, mode, 0.12, { leg = "Right", dir = -UP, len = 3 })
		local g = groundPoint(root.Position + root.CFrame.RightVector * 0.5)
		IK.ring(g + UP * 0.3, 0.6, 10, 2, IK.DUST, 0.12)
		-- (a few short cracks round the push-off - no crater: it's a step)
		EK.cracks(g, 2.2, 3, { life = 1.4, grow = 0.08, crater = false })
		groundMark(g, 1.4, Color3.fromRGB(70, 62, 58), 1.2)
		VFX.PlaySound("EngineBackfire", g, 0.55)
		IK.at(char, from, hit)
		if not root.Parent or not EK.alive(char) then
			return
		end
		local foot, hip = IK.leg(char, "Right")
		local p = root.Position + d * 3 + UP * 2
		if foot then
			IK.smear(root, foot, hip, {
				plane = "vertical", tilt = 26, spin = 1, arc = 160, life = 0.45, draw = 0.05,
				color = ult and EK.PAL.TURBO_SMEAR or nil, core = ult and EK.PAL.TURBO_WHITE or nil,
			})
		end
		EK.jets(char, mode, 0.32, { leg = "Right", dir = -UP, len = 5.5 })
		-- (the star on them, where the foot met the chin - by the Hit the
		-- leg's already swept on up past his own face)
		EK.starSpark(root.Position + d * 2.4 + UP * 1.8, { size = 3.4, color = ult and EK.PAL.TURBO_SMEAR or nil })
		EK.vaporRings(p - UP * 1.5, UP, 2, { gap = 4, stagger = 0.08, size = 3.2, from = 1.2 })
		IK.lift(p)
		IK.shock(p, UP, 12)
		VFX.PlaySound("Uppercut", p, 1)
		VFX.ShakeAt(p, 1, 50, 0.2)
		if isLocal then
			EK.fovPunch(8, 0.05, 0.3)
		end
	end
end

function Effects.ReciproTurbo(char, data, isLocal)
	-- (round 85) TURBO RUSH is drawn in the ENGINE block (VFX.IidaTurbo.rush)
	return VFX.IidaTurbo.rush(char, data, isLocal)
end

---------------------------------------------------------------------------
-- Shared helpers for the new moves
---------------------------------------------------------------------------

-- (one palette table for the beam / Limitless colours: Luau's local limit)
local PAL = {
	AP_CORE = Color3.fromRGB(255, 252, 226),
	PHOSPHOR_CORE = Color3.fromRGB(255, 255, 255),
	PHOSPHOR_GLOW = Color3.fromRGB(160, 170, 255),
}

-- 3D aim (beams can shoot up at rooftops)
local function aimDir(data, root)
	local v = data.Dir
	if typeof(v) ~= "Vector3" or v.Magnitude < 0.05 then
		return root.CFrame.LookVector
	end
	return v.Unit
end

-- Aim point snapped to the ground within range (same maths as the server)
local function aimGround(root, data, range)
	local d = flatten(data.Dir, root)
	local aim = typeof(data.Pos) == "Vector3" and data.Pos or root.Position + d * 30
	local flat = Vector3.new(aim.X - root.Position.X, 0, aim.Z - root.Position.Z)
	if flat.Magnitude > range then
		flat = flat.Unit * range
	end
	local xz = root.Position + flat
	local hit = groundRay(Vector3.new(xz.X, root.Position.Y + 22, xz.Z), 90)
	return hit and hit.Position or Vector3.new(xz.X, root.Position.Y - 3, xz.Z)
end

-- NUKE (the PLUS ULTRA dev kit's V)
do
	-- NUKE: he summons a sun-sized bomb over his head. It keeps growing while
	-- he holds it (the street around him is pulled up toward it), then he
	-- throws it at wherever he's aiming and it goes off like a small sun.
	-- (packed into one table: this block is close to Luau's local limit)
	local NK = { ROCK = Color3.fromRGB(96, 88, 84), holds = {} } -- holds: [char] = the bomb over their head

	-- the blast itself, where it lands. Everything scales with ability.Radius;
	-- the ground wave rolls out at WaveSpeed so what you see reach you is
	-- what hits you.
	function NK.detonate(center, lifted, ability)
		local R = ability.Radius or 200
		local wave = math.max(ability.WaveSpeed or 420, 1)
		local S = R / 72 -- (the old blast was 72 studs)
		local ground = groundPoint(center)
		local cam = workspace.CurrentCamera
		local myDist = cam and (cam.Focus.Position - center).Magnitude or math.huge
		if myDist < R * 4.5 then
			VFX.ImpactFrame(0.3)
		end
		if myDist < R * 6 then
			VFX.Hooks.Flash(Color3.new(1, 1, 1), myDist < R and 1.6 or 1)
			-- the whole sky burns orange for a while after the flash
			local lighting = game:GetService("Lighting")
			local tint = Instance.new("ColorCorrectionEffect")
			tint.Name = "NukeTint"
			tint.TintColor = Color3.fromRGB(255, 186, 130)
			tint.Brightness = 0.15
			tint.Contrast = 0.15
			tint.Parent = lighting
			tween(tint, 6, { TintColor = Color3.new(1, 1, 1), Brightness = 0, Contrast = 0 }, Enum.EasingStyle.Quad, Enum.EasingDirection.In, 0.6)
			cleanup(tint, 6.8)
		end
		-- the fireball: a white-hot core inside yellow and red shells
		for i, spec in {
			{ Color3.new(1, 1, 1), 0, 120 * S, 0.3, 1.1 },
			{ BLAST_YELLOW, 0.3, 150 * S, 0.42, 1.5 },
			{ FIRE[4], 0.5, 185 * S, 0.55, 1.7 },
		} do
			local ball = newPart(Vector3.one * 8, CFrame.new(center), spec[1], Enum.Material.Neon, Enum.PartType.Ball)
			ball.Transparency = spec[2]
			tween(ball, spec[4], { Size = Vector3.one * spec[3] })
			tween(ball, spec[5], { Size = Vector3.one * spec[3] * 1.1, Transparency = 1 }, nil, nil, spec[4])
			cleanup(ball, spec[4] + spec[5] + 0.1)
			if i == 1 then
				local light = Instance.new("PointLight")
				light.Range = 60
				light.Brightness = 20
				light.Color = Color3.fromRGB(255, 226, 150)
				light.Parent = ball
			end
		end
		billboardRing(center, 10, 170 * S, Color3.new(1, 1, 1), 0, 0.35, true)
		billboardRing(center, 20, 360 * S, BLAST_YELLOW, 26, 1.1)
		billboardRing(center, 30, 460 * S, FIRE[4], 18, 1.4)
		toonExplosion(center, 10 * math.sqrt(S), { SmokeLife = 7 })
		-- everything it pulled in gets thrown back out
		for _, p in lifted do
			if p.Parent then
				local out = p.Position - center
				out = Vector3.new(out.X, 0, out.Z)
				out = (out.Magnitude > 0.1 and out.Unit or rng:NextUnitVector()) * rand(70, 140) + UP * rand(15, 50)
				tween(p, 0.9, { CFrame = CFrame.new(p.Position + out) * CFrame.Angles(rand(0, 6), rand(0, 6), 0), Transparency = 1 })
				cleanup(p, 0.95)
			end
		end
		-- THE BLAST WAVE, along the ground at WaveSpeed: a ring of air you can
		-- see, a wall of dust riding it, and the shake arrives with it
		local reach = R * 1.15
		for i = 1, 3 do
			task.delay((i - 1) * 0.08, function()
				local disc = newPart(Vector3.new(0.6, 30, 30), CFrame.new(ground + UP * (1 + i * 2)) * CFrame.Angles(0, 0, math.rad(90)), i == 2 and FIRE[2] or WIND, Enum.Material.ForceField, Enum.PartType.Cylinder)
				tween(disc, reach / wave, { Size = Vector3.new(0.6, reach * 2, reach * 2) }, Enum.EasingStyle.Linear)
				tween(disc, 0.5, { Transparency = 1 }, nil, nil, reach / wave - 0.2)
				cleanup(disc, reach / wave + 0.4)
			end)
		end
		for _, r in { 0.12, 0.25, 0.4, 0.57, 0.76, 0.95 } do
			local rad = r * R
			local count = math.clamp(math.floor(rad / 9), 10, 26)
			for k = 1, count do
				local a = k / count * math.pi * 2 + r * 3
				local at = ground + Vector3.new(math.cos(a), 0, math.sin(a)) * rad
				task.delay(rad / wave + rand(0, 0.05), function()
					dustPuffs(at, 2.2 + S, 2, Color3.fromRGB(206, 196, 186), 2.6, false)
				end)
			end
		end
		if cam then
			local d = (cam.Focus.Position - ground).Magnitude
			task.delay(math.min(d, reach) / wave, function()
				VFX.Shake(math.clamp(9 * (1 - d / (R * 6)), 1.2, 9), 2)
			end)
			-- the sound gets to you a moment after the light does
			task.delay(math.min(d / 1100, 2), function()
				VFX.PlaySound("NukeBoom", center, 1.7)
			end)
		end
		-- the condensation ring, high up around the stem
		task.delay(0.3, function()
			shockDisc(ground + UP * 45 * S, UP, 30 * S, 220 * S, 2.4, WIND)
		end)
		-- secondary blasts ringing the crater, then an outer ring of whoomps
		for i = 1, 10 do
			local a = i / 10 * math.pi * 2
			local rad = 0.5 * R
			task.delay(rad / wave + i * 0.03, function()
				toonExplosion(ground + Vector3.new(math.cos(a) * rad, 3, math.sin(a) * rad), 2.6 * math.sqrt(S), { NoScorch = true })
			end)
		end
		for i = 1, 12 do
			local a = i / 12 * math.pi * 2 + 0.3
			local rad = 0.8 * R
			task.delay(rad / wave + i * 0.03, function()
				Flame.burst(ground + Vector3.new(math.cos(a) * rad, 2, math.sin(a) * rad), 6 * math.sqrt(S), 12)
			end)
		end
		-- the column: real fire roaring up the middle while the smoke stem and
		-- the mushroom cap build over it
		Flame.column(ground, 70 * S, 9 * S, 3)
		local cloud = outlineModel(Color3.fromRGB(58, 50, 46))
		local stemTop = 110 * S
		for i = 1, 18 do
			local jitter = Vector3.new(rand(-3, 3), 0, rand(-3, 3)) * S
			celPuff(cloud, ground, ground + UP * (i / 18 * stemTop) + jitter, rand(14, 20) * S * (1 - i / 40), SMOKE_DARK, SMOKE_LIGHT, 1, 8, i * 0.05)
		end
		for k = 1, 24 do
			local a = k / 24 * math.pi * 2
			local out = Vector3.new(math.cos(a), 0, math.sin(a))
			local at = ground + UP * (stemTop + rand(-6, 8) * S) + out * rand(18, 42) * S
			celPuff(cloud, ground + UP * stemTop * 0.9, at, rand(18, 28) * S, SMOKE_DARK, SMOKE_LIGHT, 1.3, 8, 0.6 + k * 0.02)
			if k % 3 == 0 then
				-- the cap still glowing from inside before it cools to smoke
				celPuff(cloud, ground + UP * stemTop * 0.9, at - out * 6 * S, rand(12, 18) * S, FIRE[4], FIRE[2], 0.9, 1.2, 0.6 + k * 0.02)
			end
		end
		cleanup(cloud, 11)
		-- embers raining back down, fires left burning across the crater
		emberCloud(ground + UP * 50 * S, 70 * S, 7, 400)
		for _ = 1, 18 do
			local a, r = rand(0, math.pi * 2), rand(8, 0.6 * R)
			local spot = groundPoint(ground + Vector3.new(math.cos(a) * r, 6, math.sin(a) * r))
			task.delay(r / wave + rand(0.2, 0.8), function()
				Flame.spot(spot, rand(3, 5), rand(4, 7))
			end)
		end
		rocks(ground, 4 * math.sqrt(S), 60)
		groundMark(ground, 0.62 * R, Color3.fromRGB(30, 24, 22), 20)
	end

	-- let go of a bomb that was never thrown (he was knocked out holding it)
	function NK.drop(char)
		local hold = NK.holds[char]
		if not hold then
			return
		end
		NK.holds[char] = nil
		hold.over = true
		VFX.ReleasePose(char) -- (arms down)
		for _, p in { hold.core, hold.shell, hold.halo } do
			if p.Parent then
				tween(p, 0.35, { Size = Vector3.one * 0.5, Transparency = 1 }, Enum.EasingStyle.Quad, Enum.EasingDirection.In)
				cleanup(p, 0.4)
			end
		end
		for _, p in hold.lifted do
			if p.Parent then
				p.Anchored = false
				p.CanCollide = false
				tween(p, 0.6, { Transparency = 1 })
				cleanup(p, 0.7)
			end
		end
		if hold.core.Parent then
			smokeBurst(hold.core.Position, SMOKE_LIGHT, 6, 8, 1, 14)
		end
	end

	-- G / the key: SUMMON. The bomb forms over his head and grows for as long
	-- as he holds it (MaxCharge at most)
	function Effects.Nuke(char, data, isLocal, ability)
		local root = charParts(char)
		if not root then
			return
		end
		ability = ability or {}
		local maxCharge = (ability.Hold and ability.Hold.Max) or ability.MaxCharge or 3
		local size = ability.BombSize or 40
		NK.drop(char)
		local d = flatten(data.Dir, root)
		if isLocal then
			face(root, d)
			VFX.Hooks.Dim(0.35, 0.8)
		end
		VFX.Pose(char, "ArmsUp", maxCharge + 1.5)
		VFX.PlaySound("NukeCharge", root.Position, 1.2)
		local base = groundPoint(root.Position)
		toonExplosion(base, 1.6, { NoDebris = true })
		shockDisc(base + UP * 0.4, UP, 4, 40, 0.5, WIND)
		-- a white-hot core inside a yellow shell, a red glow round it
		local at = CFrame.new(root.Position + UP * 8)
		local hold = {
			start = os.clock(),
			core = newPart(Vector3.one, at, Color3.new(1, 1, 1), Enum.Material.Neon, Enum.PartType.Ball),
			shell = newPart(Vector3.one, at, BLAST_YELLOW, Enum.Material.Neon, Enum.PartType.Ball),
			halo = newPart(Vector3.one, at, FIRE[4], Enum.Material.Neon, Enum.PartType.Ball),
			lifted = {},
			pos = at.Position,
			diameter = 1,
		}
		hold.core.Name = "NukeCore"
		hold.shell.Transparency = 0.25
		hold.halo.Transparency = 0.6
		local light = Instance.new("PointLight")
		light.Range = 60
		light.Brightness = 10
		light.Color = Color3.fromRGB(255, 214, 130)
		light.Parent = hold.core
		NK.holds[char] = hold
		local lastPulse, lastRock = 0, 0
		while not hold.over and root.Parent and os.clock() - hold.start < maxCharge + 1.5 do
			local now = os.clock()
			local k = math.min((now - hold.start) / maxCharge, 1)
			local diameter = size * (0.12 + 0.88 * k)
			local pos = root.Position + UP * (5 + diameter * 0.55)
			hold.pos, hold.diameter = pos, diameter
			hold.core.Size = Vector3.one * diameter * 0.55
			hold.shell.Size = Vector3.one * diameter
			hold.halo.Size = Vector3.one * diameter * 1.35
			hold.core.CFrame = CFrame.new(pos)
			hold.shell.CFrame = CFrame.new(pos)
			hold.halo.CFrame = CFrame.new(pos)
			if rng:NextNumber() < 0.6 then
				bolt(pos, diameter * 0.6, FIRE[1])
			end
			-- energy sucked in from all around
			for _ = 1, 1 + math.floor(k * 3) do
				local from = pos + rng:NextUnitVector() * rand(diameter, diameter * 2.5)
				local seg = newPart(Vector3.new(0.5, 0.5, 6), CFrame.lookAt(from, pos), FIRE[rng:NextInteger(1, 3)], Enum.Material.Neon)
				tween(seg, 0.25, { CFrame = CFrame.lookAt(pos, pos + (pos - from)), Size = Vector3.new(0.1, 0.1, 2), Transparency = 0.6 })
				cleanup(seg, 0.3)
			end
			-- pulses that come faster as it grows
			if now - lastPulse > 0.3 - 0.2 * k then
				lastPulse = now
				billboardRing(pos, diameter * 2.2, diameter * 0.6, BLAST_YELLOW, 8, 0.22)
				VFX.PlaySound("NukePulse", pos, 0.5 + k * 0.5)
				VFX.ShakeAt(pos, 0.5 + k * 2.2, 120 + diameter * 4, 0.14)
			end
			-- the street tears loose and floats up toward it
			if now - lastRock > 0.06 and #hold.lifted < 30 then
				lastRock = now
				local a, r = rand(0, math.pi * 2), rand(6, 14 + diameter * 0.5)
				local spot = groundPoint(root.Position + Vector3.new(math.cos(a) * r, 0, math.sin(a) * r))
				local s = rand(0.8, 2.2)
				local chunk = newPart(Vector3.new(s, s * 0.6, s * rand(0.8, 1.3)), CFrame.new(spot) * CFrame.Angles(rand(0, 6), rand(0, 6), 0), NK.ROCK:Lerp(Color3.new(), rand(0, 0.3)), Enum.Material.Slate)
				tween(chunk, 1.6, { CFrame = CFrame.new(spot + UP * rand(6, 16)) * CFrame.Angles(rand(0, 6), rand(0, 6), rand(0, 6)) }, Enum.EasingStyle.Sine)
				cleanup(chunk, maxCharge + 4)
				table.insert(hold.lifted, chunk)
			end
			task.wait(0.03)
		end
		if not hold.over then
			NK.drop(char) -- (never thrown: it fizzles)
		end
	end

	-- the throw: the bomb arcs to where he aimed and goes off there. His own
	-- screen plays it the moment he throws (data.Pos = his aim); everyone
	-- else gets the server's landing spot (data.Target)
	function Effects.NukeThrow(char, data, _isLocal, ability)
		local root = charParts(char)
		ability = ability or Config.FindAbilityById("Nuke") or {}
		local hold = NK.holds[char]
		local target = typeof(data.Target) == "Vector3" and data.Target or (root and aimGround(root, data, ability.Range or 300))
		if not target then
			NK.drop(char)
			return
		end
		if hold then
			NK.holds[char] = nil
			hold.over = true
		end
		local scale = tonumber(data.Scale) or 1
		local diameter = (ability.BombSize or 40) * scale
		local from = typeof(data.From) == "Vector3" and data.From or (hold and hold.pos) or (root and root.Position + UP * (5 + diameter * 0.55)) or target + UP * 60
		if hold then
			from = hold.pos
		end
		local core = hold and hold.core or newPart(Vector3.one * diameter * 0.55, CFrame.new(from), Color3.new(1, 1, 1), Enum.Material.Neon, Enum.PartType.Ball)
		local shell = hold and hold.shell or newPart(Vector3.one * diameter, CFrame.new(from), BLAST_YELLOW, Enum.Material.Neon, Enum.PartType.Ball)
		local halo = hold and hold.halo or newPart(Vector3.one * diameter * 1.35, CFrame.new(from), FIRE[4], Enum.Material.Neon, Enum.PartType.Ball)
		if hold then
			-- (it swells to its full thrown size as it leaves his hands)
			tween(core, 0.3, { Size = Vector3.one * diameter * 0.55 })
			tween(shell, 0.3, { Size = Vector3.one * diameter })
			tween(halo, 0.3, { Size = Vector3.one * diameter * 1.35 })
			for _, p in hold.lifted do
				if p.Parent then
					p.Anchored = false -- (what it was holding up falls)
					p.CanCollide = false
					tween(p, 1, { Transparency = 1 }, nil, nil, 0.4)
					cleanup(p, 1.5)
				end
			end
		end
		if char.Parent then
			VFX.Pose(char, "Throw", 0.6)
		end
		VFX.PlaySound("BombThrow", from, 1.2)
		VFX.PlaySound("Leap", from, 1)
		local stopTrail = addTrail(shell, FIRE[3], 0.5, math.min(diameter * 0.5, 20))
		local flight = math.clamp((target - from).Magnitude / 200, 0.5, 1.6)
		local lift = math.min((target - from).Magnitude * 0.25, 90)
		local t0 = os.clock()
		while os.clock() - t0 < flight do
			local t = (os.clock() - t0) / flight
			local p = from:Lerp(target + UP * 6, t) + UP * lift * 4 * t * (1 - t)
			core.CFrame, shell.CFrame, halo.CFrame = CFrame.new(p), CFrame.new(p), CFrame.new(p)
			task.wait()
		end
		stopTrail(0)
		core:Destroy()
		shell:Destroy()
		halo:Destroy()
		NK.detonate(target + UP * 6, {}, {
			Radius = (ability.Radius or 260) * scale,
			WaveSpeed = ability.WaveSpeed or 480,
		})
	end

	VFX.NukeDetonate = NK.detonate -- (Iida's prank goes off the same way)

	-- the server: he was knocked out holding it
	function Effects.NukeFizzle(char)
		NK.drop(char)
	end
	VFX.NukeDrop = NK.drop

	-- his own key came up: the throw, sized by how long he held it (the same
	-- maths as the server)
	function Effects.NukeRelease(char, data, isLocal, ability)
		ability = ability or Config.FindAbilityById("Nuke") or {}
		local hold = NK.holds[char]
		local maxCharge = (ability.Hold and ability.Hold.Max) or ability.MaxCharge or 3
		local minCharge = ability.MinCharge or 0.6
		local held = hold and (os.clock() - hold.start) or 0
		local k = math.clamp((held - minCharge) / math.max(maxCharge - minCharge, 0.1), 0, 1)
		local minScale = ability.MinScale or 0.7
		Effects.NukeThrow(char, { Dir = data.Dir, Pos = data.Pos, Scale = minScale + (1 - minScale) * k }, isLocal, ability)
	end

end

-- Straight glowing beam: flares out, then thins away
local function beam(a, b, radius, core, glow, life)
	local len = math.max((b - a).Magnitude, 0.1)
	local cf = CFrame.lookAt((a + b) / 2, b) * CFrame.Angles(0, math.rad(90), 0)
	local outer = newPart(Vector3.new(len, radius * 0.6, radius * 0.6), cf, glow, Enum.Material.Neon, Enum.PartType.Cylinder)
	outer.Transparency = 0.4
	local inner = newPart(Vector3.new(len, radius * 0.3, radius * 0.3), cf, core, Enum.Material.Neon, Enum.PartType.Cylinder)
	tween(outer, 0.05, { Size = Vector3.new(len, radius * 2.6, radius * 2.6) })
	tween(inner, 0.05, { Size = Vector3.new(len, radius, radius) })
	tween(outer, life, { Size = Vector3.new(len, 0.05, 0.05), Transparency = 1 }, Enum.EasingStyle.Quad, Enum.EasingDirection.In, 0.05)
	tween(inner, life, { Size = Vector3.new(len, 0.05, 0.05) }, Enum.EasingStyle.Quad, Enum.EasingDirection.In, 0.05)
	cleanup(outer, life + 0.1)
	cleanup(inner, life + 0.1)
end

local function firstHit(from, dir, maxLen)
	rayParams.FilterDescendantsInstances = characterList()
	local hit = workspace:Raycast(from, dir * maxLen, rayParams)
	return hit and hit.Position or nil
end

local function fireball(from, to, time, size)
	local p = newPart(Vector3.one * size, CFrame.new(from), FIRE[2], Enum.Material.Neon, Enum.PartType.Ball)
	local stop = addTrail(p, FIRE[3], 0.2, size)
	tween(p, time, { CFrame = CFrame.new(to) }, Enum.EasingStyle.Linear)
	task.delay(time, function()
		stop(0)
		p.Transparency = 1
	end)
	cleanup(p, time + 0.5)
end

---------------------------------------------------------------------------
-- EXPLOSION (later seasons)
---------------------------------------------------------------------------

-- AP Shot: pinpoint, armour-piercing explosion beam from the palm
do -- EXPLOSION: its helpers stay local to this block (Luau allows 200 locals per scope)
	local function apShot(char, dir, right, scale)
		local from = handPos(char, right) + dir
		local to = from + dir * 160
		beam(from, to, 0.9 * scale, PAL.AP_CORE, FIRE[2], 0.3)
		billboardRing(from, 2 * scale, 12 * scale, Color3.fromRGB(255, 238, 60), 8, 0.25)
		for i = 1, 5 do
			task.delay(i * 0.015, function()
				shockDisc(from + dir * (i * 7), dir, 3 * scale, 0.4, 0.22, FIRE[1], 8)
			end)
		end
		toonExplosion(from, 0.5 * scale, { NoDebris = true, NoScorch = true, NoEmbers = true })
		local hitPos = firstHit(from, dir, 160)
		if hitPos then
			toonExplosion(hitPos, 1.2 * scale, { NoScorch = true })
		end
		VFX.PlaySound("Beam", from, 0.9)
		VFX.ShakeAt(from, 0.9 * scale, 60, 0.2)
	end

	function Effects.APShot(char, data, isLocal, ability)
		local root, hum = charParts(char)
		if not root then
			return
		end
		-- straight out on the ground; anywhere below him in the air
		ability = ability or {}
		local dir = Config.AimedDirection(aimDir(data, root), root.CFrame.LookVector, data.Air and ability.AirAim or ability.Aim)
		if isLocal then
			face(root, dir)
			if data.Air and hum then
				-- the recoil kicks him up and back
				task.delay(0.18, function()
					if root.Parent then
						launch(root, hum, -dir * 55 + UP * 35)
					end
				end)
			end
		end
		VFX.Pose(char, "APShot", 0.5)
		local hand = handPos(char, true)
		shockDisc(hand + dir, dir, 5, 0.6, 0.18, FIRE[2])
		local glow = newPart(Vector3.one * 0.3, CFrame.new(hand), PAL.AP_CORE, Enum.Material.Neon, Enum.PartType.Ball)
		tween(glow, 0.18, { Size = Vector3.one * 1.8 })
		cleanup(glow, 0.2)
		sparks(hand, 0.5)
		task.wait(0.18)
		if root.Parent then
			apShot(char, dir, true, 1.9)
		end
	end

	function Effects.AutoCannon(char, data, isLocal, ability)
		local root = charParts(char)
		if not root then
			return
		end
		local dir = aimDir(data, root)
		if isLocal then
			face(root, dir)
		end
		if not isLocal then
			return -- (everyone else sees each shot as the server fires it: AutoCannonShot)
		end
		task.wait(0.12)
		for i = 1, (ability and ability.Shots) or 6 do
			if not root.Parent then
				return
			end
			-- he keeps aiming while he fires: each shot goes where you aim now
			local live = VFX.Hooks.Aim and VFX.Hooks.Aim()
			if typeof(live) == "Vector3" and live.Magnitude > 0.01 then
				dir = live.Unit
				face(root, dir)
			end
			local right = i % 2 == 1
			VFX.Pose(char, right and "PunchR" or "PunchL", 0.12)
			apShot(char, dir, right, 1.3)
			task.wait(0.15)
		end
	end

	-- (one shot of someone else's Auto-Cannon, wherever they aimed it)
	function Effects.AutoCannonShot(char, data)
		local root = charParts(char)
		if not root then
			return
		end
		local dir = aimDir(data, root)
		local right = (tonumber(data.Index) or 1) % 2 == 1
		VFX.Pose(char, right and "PunchR" or "PunchL", 0.12)
		apShot(char, dir, right, 1.3)
	end

	function Effects.StunGrenade(char, _data, isLocal)
		local root = charParts(char)
		if not root then
			return
		end
		VFX.Pose(char, "Clap", 0.45)
		sparks(handPos(char, true), 0.6, Color3.new(1, 1, 1), FIRE[1], 12)
		task.wait(0.25)
		if not root.Parent then
			return
		end
		local pos = root.Position
		local ball = newPart(Vector3.one * 2, CFrame.new(pos), Color3.new(1, 1, 1), Enum.Material.Neon, Enum.PartType.Ball)
		tween(ball, 0.12, { Size = Vector3.one * 68 })
		tween(ball, 0.4, { Transparency = 1, Size = Vector3.one * 76 }, nil, nil, 0.12)
		cleanup(ball, 0.6)
		local light = Instance.new("PointLight")
		light.Range = 60
		light.Brightness = 10
		light.Parent = ball
		shockDisc(pos, UP, 8, 92, 0.45, Color3.new(1, 1, 1))
		billboardRing(pos, 6, 70, Color3.new(1, 1, 1), 10, 0.4)
		sparks(pos, 2.5, Color3.new(1, 1, 1), FIRE[1], 70)
		toonExplosion(pos, 1, { NoDebris = true, NoScorch = true })
		if not isLocal and nearCamera(pos, 30) then
			VFX.Hooks.Flash(Color3.new(1, 1, 1), 0.5)
		end
		VFX.PlaySound("Grenade", pos, 1)
		VFX.ShakeAt(pos, 1.5, 70, 0.3)
	end

	-- Server tells a player they were caught in a Stun Grenade without their
	-- guard up: white-out, a ringing in the ears, and it only slowly clears
	function Effects.Blind(_, data)
		local duration = data.Duration or 2.6
		if VFX.Hooks.Blind then
			VFX.Hooks.Blind(duration)
		else
			VFX.Hooks.Flash(Color3.new(1, 1, 1), duration)
		end
		local cam = workspace.CurrentCamera
		VFX.PlaySound("Ringing", cam and cam.Focus.Position or Vector3.zero, 1)
	end

	function Effects.Cluster(char, data, isLocal, ability)
		local root, hum = charParts(char)
		if not root then
			return
		end
		local d = flatten(data.Dir, root)
		local target = aimGround(root, data, (ability and ability.Range) or 90)
		if isLocal then
			face(root, d)
			VFX.Hooks.Dim(0.5, 1.9)
			launch(root, hum, d * 25 + Vector3.new(0, 105, 0))
		end
		VFX.Pose(char, "ArmsUp", 0.35)
		toonExplosion(groundPoint(root.Position), 1.3, { NoDebris = true })
		task.wait(0.35)
		-- rain a cluster of explosive shots around the target (same seeded ring as the server)
		local ring = Random.new(typeof(data.Seed) == "number" and data.Seed or 1)
		local offset = ring:NextNumber(0, math.pi * 2)
		for i = 1, 8 do
			if not root.Parent then
				return
			end
			local a = offset + i / 8 * math.pi * 2
			local r = 11 + (i % 2) * 12
			local p = target + Vector3.new(math.cos(a) * r, 2, math.sin(a) * r)
			local right = i % 2 == 0
			VFX.Pose(char, right and "PunchR" or "PunchL", 0.1)
			fireball(handPos(char, right), p, 0.15, 2.2)
			task.delay(0.15, function()
				toonExplosion(p, 2.2, { SmokeLife = 1.8 })
			end)
			task.wait(0.075)
		end
		task.wait(0.1)
		if not root.Parent then
			return
		end
		-- dive in with a Howitzer spin
		VFX.Pose(char, "ArmsUp", 1)
		local cancelDive
		if isLocal then
			local dv = (target + UP * 2) - root.Position
			cancelDive = dash(root, (dv.Magnitude > 1 and dv.Unit or -UP) * 190, 0.7)
		end
		local model = outlineModel(FLAME_OUTLINE)
		local t0 = os.clock()
		repeat
			local t = os.clock() - t0
			for k = 0, 1 do
				local a = t * 30 + k * math.pi
				local p = root.Position + Vector3.new(math.cos(a) * 3.5, 0, math.sin(a) * 3.5)
				local puff = newPart(Vector3.one * 2.6, CFrame.new(p), FIRE[rng:NextInteger(2, 4)], Enum.Material.Neon, Enum.PartType.Ball, model)
				tween(puff, 0.25, { Size = Vector3.one * 0.1 })
			end
			task.wait(0.03)
		until not root.Parent or os.clock() - t0 > 0.65 or (os.clock() - t0 > 0.05 and isGrounded(root))
		cleanup(model, 0.4)
		if cancelDive then
			cancelDive()
		end
		if not root.Parent then
			return
		end
		local center = groundPoint(root.Position) + UP * 3
		toonExplosion(center, 6.6, { SmokeLife = 4.5 })
		shockDisc(center, UP, 12, 170, 0.65, FIRE[2])
		shockDisc(center + UP * 2, UP, 10, 120, 0.5, Color3.new(1, 1, 1))
		for i = 1, 8 do
			local a = i / 8 * math.pi * 2
			task.delay(0.1 + i * 0.04, function()
				toonExplosion(center + Vector3.new(math.cos(a) * 30, 0, math.sin(a) * 30), 2.4, { NoScorch = true })
			end)
		end
		if nearCamera(center, 140) then
			VFX.Hooks.Flash(Color3.fromRGB(255, 236, 200), 0.4)
		end
		VFX.ShakeAt(center, 5, 260, 1)
	end

	-- (Bakugo's newer moves share one table: this block is close to Luau's
	-- local limit)
	local BK = {}

	-- a blast right off the palm: the flash, the fire, a puff of smoke, sparks
	function BK.palm(pos, dir, scale)
		toonExplosion(pos + dir * 0.8 * scale, 0.7 * scale, { NoDebris = true, NoScorch = true, NoEmbers = scale < 1.2, SmokeLife = 0.7 })
		sparks(pos, 0.5 * scale, Color3.new(1, 1, 1), FIRE[1], math.floor(8 * scale))
		shockDisc(pos + dir * 0.5, dir, 0.6 * scale, 5 * scale, 0.14, FIRE[2], 2 * scale)
	end
	VFX.PalmBlast = BK.palm

	-- his own machine flies his body along a path (path(a) -> CFrame, a from
	-- 0 to 1); returns a stop function
	function BK.fly(char, root, hum, duration, path)
		local t0 = os.clock()
		local last = root.CFrame
		local conn
		local function stop()
			if conn then
				conn:Disconnect()
				conn = nil
				if hum and hum.Parent then
					hum.PlatformStand = false
					hum.AutoRotate = true
				end
			end
		end
		if hum then
			hum.PlatformStand = true
			hum.AutoRotate = false
		end
		conn = RunService.RenderStepped:Connect(function(dt)
			local a = math.clamp((os.clock() - t0) / duration, 0, 1)
			if not root.Parent or (hum and hum.Health <= 0) or char:GetAttribute("Ragdolled") then
				stop()
				return
			end
			local cf = path(a)
			root.CFrame = cf
			root.AssemblyLinearVelocity = (cf.Position - last.Position) / math.max(tonumber(dt) or 1 / 60, 1 / 240)
			last = cf
			if a >= 1 then
				stop()
			end
		end)
		return stop
	end
	VFX.Fly = BK.fly

	-- ERUPTION ORBIT, part 1: palm to the street, it erupts in front of him,
	-- and he blasts off after whoever it threw up (in the air: just the
	-- palms flaring - he goes straight for them)
	function Effects.BlastOrbit(char, data, isLocal, ability)
		local root, hum = charParts(char)
		if not root then
			return
		end
		local d = flatten(data.Dir, root)
		if isLocal then
			face(root, d)
		end
		if data.Air then
			VFX.Pose(char, "Blast", 0.3)
			BK.palm(handPos(char, true), d, 1.2)
			BK.palm(handPos(char, false), d, 1.2)
			VFX.PlaySound("Explosion", root.Position, 0.8)
			return
		end
		VFX.Motion(char, "EruptionSlam")
		sparks(handPos(char, true), 0.6, Color3.new(1, 1, 1), FIRE[1], 10)
		task.wait(0.28)
		if not root.Parent then
			return
		end
		local center = groundPoint(root.Position + d * (((ability and ability.Range) or 16) * 0.55))
		-- the street erupts: a column of fire out of the ground
		toonExplosion(center + UP * 2, 2.6, { SmokeLife = 2 })
		for i = 1, 5 do
			task.delay(i * 0.04, function()
				toonExplosion(center + UP * (3 + i * 4) + Vector3.new(rand(-1.5, 1.5), 0, rand(-1.5, 1.5)), 1.5 - i * 0.14, { NoDebris = true, NoScorch = true })
			end)
		end
		shockDisc(center + UP * 0.5, UP, 4, 40, 0.4, FIRE[2])
		rocks(center, 1.4, 14)
		groundMark(center, 8, Color3.fromRGB(40, 32, 30), 10)
		VFX.PlaySound("BigExplosion", center, 0.9)
		VFX.ShakeAt(center, 2.5, 90, 0.35)
		-- and he blasts off the street after them
		BK.palm(handPos(char, true), -UP, 1.4)
		BK.palm(handPos(char, false), -UP, 1.4)
		VFX.Pose(char, "BlastUp", 0.45)
		if isLocal and hum then
			launch(root, hum, UP * 105 + d * 12)
		end
	end

	-- ERUPTION ORBIT, part 2 (the server caught someone): he circles them,
	-- blasting from every side, then the last blast from above drives them
	-- into the street
	function Effects.BlastOrbitCatch(char, data)
		local root, hum = charParts(char)
		local targets = data.Targets or {}
		if not root or #targets == 0 or typeof(data.Center) ~= "Vector3" then
			return
		end
		local center = data.Center
		local d = typeof(data.Dir) == "Vector3" and data.Dir or flatten(root.CFrame.LookVector, root)
		local me = Players.LocalPlayer
		local radius = 9
		local circle, total = 0.62, 0.88
		local rel = Vector3.new(root.Position.X - center.X, 0, root.Position.Z - center.Z)
		local start = rel.Magnitude > 0.5 and math.atan2(rel.Z, rel.X) or math.atan2(-d.Z, -d.X)
		local function around(k)
			local ang = start + k * math.pi * 3
			return center + Vector3.new(math.cos(ang) * radius, math.sin(k * math.pi) * 3, math.sin(ang) * radius)
		end
		if me and me.Character == char then
			BK.fly(char, root, hum, total, function(a)
				if a < circle / total then
					local p = around(a / (circle / total))
					return CFrame.lookAt(p, Vector3.new(center.X, p.Y, center.Z))
				end
				-- up over them, looking down
				local k = (a - circle / total) / (1 - circle / total)
				local from = around(1)
				local p = from:Lerp(center + UP * 9 - d * 0.5, 1 - (1 - k) ^ 2)
				return CFrame.lookAt(p, center + d * 0.5)
			end)
		end
		local stopTrail = addTrail(root, FIRE[3], 0.3, 2.4)
		for i = 1, 3 do
			task.delay(0.2 * i, function()
				if not root.Parent then
					return
				end
				local p = root.Position
				local toward = (center - p).Magnitude > 0.5 and (center - p).Unit or d
				VFX.Pose(char, i % 2 == 1 and "PunchR" or "PunchL", 0.15)
				BK.palm(handPos(char, i % 2 == 1), toward, 1.4)
				toonExplosion(center - toward * 1.5, 1.7, { NoDebris = true, NoScorch = true })
				VFX.PlaySound("Explosion", center, 0.9)
				VFX.ShakeAt(center, 1.2, 60, 0.15)
			end)
		end
		task.delay(total, function()
			stopTrail(0)
			if not root.Parent then
				return
			end
			-- the last one, from above, straight down
			VFX.Pose(char, "Blast", 0.45)
			BK.palm(handPos(char, true), -UP, 2)
			BK.palm(handPos(char, false), -UP, 2)
			toonExplosion(center + UP * 2, 3, { NoDebris = true })
			shockDisc(center, -UP, 3, 26, 0.3, FIRE[2], 6)
			streaks(center + UP * 3, -UP, 10, 2, 8, 14, FIRE[1], 0.3)
			VFX.PlaySound("BigExplosion", center, 1)
			VFX.ShakeAt(center, 2.5, 100, 0.3)
			-- ...and they hit the street
			task.delay(0.22, function()
				local g = groundPoint(center)
				shockDisc(g + UP * 0.4, UP, 3, 34, 0.4, WIND)
				dustPuffs(g, 1.6, 8, Color3.fromRGB(205, 196, 190), 1.1, true)
				rocks(g, 1.3, 12)
				groundMark(g, 7, Color3.fromRGB(46, 40, 38), 12)
				VFX.PlaySound("Downslam", g, 1)
			end)
		end)
	end

