	-- one bead of sweat popping somewhere on him: a tiny star of light
	function BK.bead(char)
		local limbs = {}
		for _, p in char:GetChildren() do
			if p:IsA("BasePart") and p.Name ~= "HumanoidRootPart" and p.Transparency < 1 then
				table.insert(limbs, p)
			end
		end
		local limb = limbs[rng:NextInteger(1, math.max(#limbs, 1))]
		if not limb then
			return
		end
		local off = Vector3.new(rand(-0.5, 0.5) * limb.Size.X, rand(-0.5, 0.5) * limb.Size.Y, rand(-0.5, 0.5) * limb.Size.Z)
		local pos = limb.CFrame:PointToWorldSpace(off)
		local c = ({ Color3.new(1, 1, 1), FIRE[1], FIRE[2] })[rng:NextInteger(1, 3)]
		local star = newPart(Vector3.one * 0.12, CFrame.new(pos) * CFrame.Angles(rand(0, 6), rand(0, 6), rand(0, 6)), c, Enum.Material.Neon)
		local s = rand(0.35, 0.7)
		tween(star, 0.05, { Size = Vector3.new(s, s * 0.25, s) })
		task.delay(0.05, function()
			tween(star, 0.1, { Size = Vector3.one * 0.05, Transparency = 1 })
		end)
		cleanup(star, 0.18)
	end

	-- slow motion for everyone near it: the colour drains, the world blurs and
	-- the camera leans in - snapped back by the blast
	function BK.slowMo(pos, time)
		if not nearCamera(pos, 90) then
			return nil
		end
		local lighting = game:GetService("Lighting")
		local cc = Instance.new("ColorCorrectionEffect")
		cc.Name = "BlitzSlowMo"
		cc.Parent = lighting
		local blur = Instance.new("BlurEffect")
		blur.Name = "BlitzSlowMo"
		blur.Size = 0
		blur.Parent = lighting
		tween(cc, 0.2, { Saturation = -0.65, Contrast = 0.25, TintColor = Color3.fromRGB(255, 238, 214) })
		tween(blur, 0.2, { Size = 5 })
		local cam = workspace.CurrentCamera
		local fov = cam and cam.FieldOfView
		if cam and not VFX.InOwnCinematic() then
			tween(cam, time, { FieldOfView = fov - 12 }, Enum.EasingStyle.Sine)
		end
		local done = false
		return function()
			if done then
				return
			end
			done = true
			cc:Destroy()
			blur:Destroy()
			if cam and fov and not VFX.InOwnCinematic() then
				tween(cam, 0.25, { FieldOfView = fov }, Enum.EasingStyle.Quad)
			end
		end
	end

	VFX.SlowMoScreen = BK.slowMo

	-- one of the little explosions off him in the slow motion: a bead of nitro
	-- going pop - slowly, with time all but stopped
	function BK.pop(pos, size, slow)
		local life = 0.3 + (slow or 0) * 0.3
		local outer = newPart(Vector3.one * size * 0.3, CFrame.new(pos), FIRE[3], Enum.Material.Neon, Enum.PartType.Ball)
		outer.Transparency = 0.1
		local core = newPart(Vector3.one * size * 0.2, CFrame.new(pos), FIRE[1], Enum.Material.Neon, Enum.PartType.Ball)
		tween(outer, life, { Size = Vector3.one * size * 1.5, Transparency = 1 })
		tween(core, life * 0.7, { Size = Vector3.one * size * 0.9, Transparency = 1 })
		cleanup(outer, life + 0.05)
		cleanup(core, life + 0.05)
		for _ = 1, 3 do
			local dir = rng:NextUnitVector()
			local shard = newPart(Vector3.new(0.08, 0.08, rand(0.3, 0.6)), CFrame.lookAt(pos, pos + dir), FIRE[2], Enum.Material.Neon)
			tween(shard, life, { CFrame = CFrame.lookAt(pos + dir * size * 1.6, pos + dir * size * 3), Transparency = 1 })
			cleanup(shard, life + 0.05)
		end
	end

	-- a star of light twinkling in the air (the panels are full of them)
	function BK.star(pos, size, slow)
		local anchor = newPart(Vector3.one * 0.1, CFrame.new(pos), FIRE[1])
		anchor.Transparency = 1
		anchor.Name = "Star"
		local bb = Instance.new("BillboardGui")
		bb.Size = UDim2.fromScale(size, size) -- (studs)
		bb.LightInfluence = 0
		bb.Adornee = anchor
		bb.Parent = anchor
		local label = Instance.new("TextLabel")
		label.Size = UDim2.fromScale(1, 1)
		label.BackgroundTransparency = 1
		label.Font = Enum.Font.GothamBlack
		label.TextScaled = true
		label.Text = "★"
		label.TextColor3 = rng:NextNumber() < 0.7 and Color3.fromRGB(255, 228, 90) or Color3.new(1, 1, 1)
		label.TextTransparency = 1
		label.Parent = bb
		local life = 0.35 + (slow or 0) * 0.35
		tween(label, life * 0.3, { TextTransparency = 0 })
		tween(label, life * 0.5, { TextTransparency = 1 }, nil, nil, life * 0.5)
		tween(anchor, life, { CFrame = CFrame.new(pos + UP * rand(0.2, 0.8)) }, Enum.EasingStyle.Linear)
		cleanup(anchor, life + 0.05)
	end

	-- EXPLOSIVE SPEED (round 64: back, as Dynamight's R, and better looking).
	-- The crouch: the street cracking under his feet and grit lifting off it
	-- while the beads pop and both palms swell white-hot; the launch: both
	-- palms blasting behind him, a sonic boom and the street going off down
	-- the lane behind him; the catch: time crawling, a flare swelling in his
	-- palm and heat rippling off it; then the Explosion, layered, and the
	-- one it hits trailing fire.
	-- the street splitting under him as the pressure builds (grows over time)
	function BK.cracks(pos, d, time)
		local g = groundPoint(pos)
		for i = 1, 7 do
			local a = (i / 7) * math.pi * 2 + rand(-0.3, 0.3)
			local dir = (CFrame.fromAxisAngle(UP, a):VectorToWorldSpace(d) * Vector3.new(1, 0, 1))
			dir = dir.Magnitude > 0.1 and dir.Unit or d
			local len = rand(2.4, 4.6)
			local crack = newPart(Vector3.new(rand(0.12, 0.22), 0.06, 0.1), CFrame.lookAt(g + UP * 0.04, g + UP * 0.04 + dir), Color3.fromRGB(34, 26, 24), Enum.Material.SmoothPlastic)
			crack.Name = "BlitzCrack"
			tween(crack, time, { Size = Vector3.new(crack.Size.X, 0.06, len), CFrame = CFrame.lookAt(g + UP * 0.04 + dir * len / 2, g + UP * 0.04 + dir * (len / 2 + 1)) }, Enum.EasingStyle.Quad)
			tween(crack, 0.6, { Transparency = 1 }, nil, nil, time + 1.4)
			cleanup(crack, time + 2.1)
			-- (glowing in the seam as it opens)
			local seam = newPart(Vector3.new(0.05, 0.07, 0.1), crack.CFrame, FIRE[1], Enum.Material.Neon)
			tween(seam, time, { Size = Vector3.new(0.05, 0.07, len * 0.8), CFrame = CFrame.lookAt(g + UP * 0.05 + dir * len * 0.4, g + UP * 0.05 + dir * (len * 0.4 + 1)) }, Enum.EasingStyle.Quad)
			tween(seam, 0.4, { Transparency = 1 }, nil, nil, time)
			cleanup(seam, time + 0.45)
		end
		-- grit lifting off the street round his feet, hanging in the air
		for _ = 1, 9 do
			local at = g + Vector3.new(rand(-2.6, 2.6), 0.15, rand(-2.6, 2.6))
			local chip = newPart(Vector3.one * rand(0.16, 0.34), CFrame.new(at) * CFrame.Angles(rand(0, 6), rand(0, 6), rand(0, 6)), Color3.fromRGB(96, 90, 86), Enum.Material.Slate)
			chip.Name = "BlitzGrit"
			tween(chip, time, { CFrame = CFrame.new(at + UP * rand(0.6, 1.6)) * CFrame.Angles(rand(0, 6), rand(0, 6), rand(0, 6)) }, Enum.EasingStyle.Sine)
			tween(chip, 0.25, { Transparency = 1 }, nil, nil, time)
			cleanup(chip, time + 0.3)
		end
	end

	-- the launch: both palms blasting behind him, a sonic boom off the front
	-- of him, the street torn up where he stood
	function BK.launch(char, from, d)
		for _, right in { true, false } do
			local hp = handPos(char, right)
			toonExplosion(hp - d * 1.1, 1.1, { NoDebris = true, NoScorch = true, SmokeLife = 0.8 })
		end
		for i = 0, 2 do
			task.delay(i * 0.035, function()
				shockDisc(from + UP * 1.2 + d * (2 + i * 3), d, 2 + i, 9 + i * 4, 0.22, Color3.new(1, 1, 1))
			end)
		end
		local g = groundPoint(from)
		groundMark(g, 3, Color3.fromRGB(38, 30, 28), 8)
		rocks(g, 1, 7)
		local right = d:Cross(UP)
		right = right.Magnitude > 0.1 and right.Unit or Vector3.new(1, 0, 0)
		dustPuffs(g + right * 2, 1, 4, Color3.fromRGB(200, 190, 175), 0.8, true)
		dustPuffs(g - right * 2, 1, 4, Color3.fromRGB(200, 190, 175), 0.8, true)
	end

	-- the lane: a burning streak along it, and the street going off behind
	-- him, blast after blast, chasing him down it
	function BK.lane(from, d, length, speed)
		local mid = from + d * length / 2 + UP * 0.9
		local streak = newPart(Vector3.new(0.9, 0.9, math.max(length, 1)), CFrame.lookAt(mid, mid + d), FIRE[1]:Lerp(Color3.new(1, 1, 1), 0.45), Enum.Material.Neon)
		streak.Name = "BlitzStreak"
		streak.Transparency = 0.15
		tween(streak, 0.4, { Size = Vector3.new(0.05, 0.05, math.max(length, 1)), Transparency = 1 }, Enum.EasingStyle.Quad, nil, 0.05)
		cleanup(streak, 0.5)
		local time = length / math.max(speed or 300, 1)
		for s = 3, length, 4 do
			local at = from + d * s
			task.delay(time * (s / math.max(length, 1)) + 0.05 + s * 0.004, function()
				local g = groundPoint(at)
				toonExplosion(g + UP * 0.7 + Vector3.new(rand(-0.5, 0.5), 0, rand(-0.5, 0.5)), rand(0.55, 0.85), { NoDebris = true, NoScorch = true, NoEmbers = true, SmokeLife = 0.7 })
				groundMark(g, 1.4, Color3.fromRGB(40, 32, 30), 6)
			end)
		end
	end

	-- a flare in his palm, swelling as time crawls (a four-point star of
	-- light and a hot core); follows the hand; returns a stop function
	function BK.flare(char, time)
		local anchor = newPart(Vector3.one * 0.1, CFrame.new(handPos(char, true)), FIRE[1])
		anchor.Transparency = 1
		anchor.Name = "BlitzFlare"
		local bb = Instance.new("BillboardGui")
		bb.Size = UDim2.fromScale(1, 1)
		bb.LightInfluence = 0
		bb.Adornee = anchor
		bb.Parent = anchor
		local bars = {}
		for k = 1, 4 do
			local bar = Instance.new("Frame")
			bar.AnchorPoint = Vector2.new(0.5, 0.5)
			bar.Position = UDim2.fromScale(0.5, 0.5)
			bar.Size = UDim2.fromScale(k <= 2 and 1 or 0.6, k <= 2 and 0.06 or 0.04)
			bar.Rotation = ({ 0, 90, 45, 135 })[k]
			bar.BackgroundColor3 = k <= 2 and Color3.new(1, 1, 1) or Color3.fromRGB(255, 214, 120)
			bar.BorderSizePixel = 0
			bar.Parent = bb
			local g = Instance.new("UIGradient")
			g.Transparency = NumberSequence.new({ NumberSequenceKeypoint.new(0, 1), NumberSequenceKeypoint.new(0.5, 0), NumberSequenceKeypoint.new(1, 1) })
			g.Parent = bar
			table.insert(bars, bar)
		end
		local core = Instance.new("Frame")
		core.AnchorPoint = Vector2.new(0.5, 0.5)
		core.Position = UDim2.fromScale(0.5, 0.5)
		core.Size = UDim2.fromScale(0.28, 0.28)
		core.BackgroundColor3 = Color3.fromRGB(255, 248, 225)
		core.BorderSizePixel = 0
		core.Parent = bb
		local round = Instance.new("UICorner")
		round.CornerRadius = UDim.new(0.5, 0)
		round.Parent = core
		local t0 = os.clock()
		local alive = true
		task.spawn(function()
			while alive and char.Parent and os.clock() - t0 < time + 0.2 do
				local k = math.clamp((os.clock() - t0) / time, 0, 1)
				anchor.CFrame = CFrame.new(handPos(char, true))
				local size = 1 + 7 * k * k
				bb.Size = UDim2.fromScale(size, size)
				for i, bar in bars do
					bar.Rotation = ({ 0, 90, 45, 135 })[i] + k * 25
				end
				task.wait()
			end
			pcall(function()
				anchor:Destroy()
			end)
		end)
		return function()
			alive = false
		end
	end

	-- (round 83) THE BLITZ'S PIECES. A ghost of his body at `at`, posed the
	-- way he is right now (a frame of him left behind: the afterimages of
	-- the blink and of every overtake) - neon, fading
	function BK.ghost(char, at, color, life, alpha)
		local root = char:FindFirstChild("HumanoidRootPart")
		if not root then
			return
		end
		local rel = root.CFrame:Inverse()
		for _, part in char:GetChildren() do
			if part:IsA("BasePart") and part ~= root and part.Transparency < 1 then
				local g = part:Clone()
				if g then
					g:ClearAllChildren()
					if g:IsA("MeshPart") then
						g.TextureID = ""
					end
					g.Anchored, g.CanCollide, g.CanQuery, g.CanTouch, g.CastShadow, g.Massless = true, false, false, false, false, true
					g.LocalTransparencyModifier = 0 -- (his own body is hidden mid-blur)
					g.Material = Enum.Material.Neon
					g.Color = color
					g.Transparency = alpha or 0.35
					g.CFrame = at * (rel * part.CFrame)
					g.Name = "BlitzGhost"
					g.Parent = folder
					tween(g, life, { Transparency = 1 })
					cleanup(g, life + 0.05)
				end
			end
		end
	end

	-- his body shown or hidden on this screen (hidden while he's a blur)
	function BK.shown(char, shown)
		if VFX.PV and VFX.PV.setShown then
			VFX.PV.setShown(char, shown)
		end
	end

	-- an R6 body's clip, its "Hit" landing `lead` seconds from now (held on
	-- its Hold key till then); an R15 body plays the motion
	function BK.play(char, clipName, lead, motion)
		local c = Anim.MoveClips ~= false and VFX.GetClip(clipName)
		if not (c and VFX.Clip(char, clipName, { holdFor = math.max(lead - (c.hit or 0), 0), recover = 0.2 })) then
			VFX.Motion(char, motion)
		end
	end

	-- his blur round them on a leg of the plan (a from 0 to 1) - the same
	-- curve the server carries him along (Kit.blitzCurve)
	function BK.curve(leg, a)
		return (1 - a) ^ 2 * leg.Was + 2 * a * (1 - a) * leg.Via + a * a * leg.Him
	end
	function BK.tangent(leg, a, fallback)
		local v = BK.curve(leg, math.min(a + 0.05, 1)) - BK.curve(leg, math.max(a - 0.05, 0))
		return v.Magnitude > 0.05 and v.Unit or fallback
	end

	-- the opener, on "GOT": his palm goes off in their face (an impact
	-- frame for anyone close) and throws them down the lane
	function BK.opener(char, at, d, gain)
		local face = at + UP * 1.2
		BK.palm(handPos(char, true), d, 1.6)
		toonExplosion(face - d * 0.3, 1.5, { NoDebris = true, NoScorch = true, SmokeLife = 1 })
		shockDisc(face, d, 2, 16, 0.25, Color3.new(1, 1, 1), 4)
		billboardRing(face, 2, 16, FIRE[1], 6, 0.25)
		streaks(face, d, 12, 1, 6, 18, FIRE[1], 0.3)
		VFX.HitStar(face, 9, FIRE[1])
		local MG = VFX.MANGA
		if MG then
			MG.flare(face, Color3.new(1, 1, 1), 3, 0.3)
			MG.impact(face, 0.06, { Radius = 90 })
		end
		VFX.PlaySound("BlitzOpen", face, 0.9 * gain)
		VFX.ShakeAt(face, 1.6, 100, 0.25)
	end

	-- one overtake (leg k of n): the jets that throw him, a burning streak
	-- along his line round them, a row of ghosts of him on it, the
	-- propulsion pops, his body gone for the blur, and the street scorched
	-- under him
	function BK.overtake(char, leg, k, gain)
		local dur = math.max(leg.Arrive - leg.Go, 0.03)
		local first = BK.tangent(leg, 0.05, leg.Way)
		BK.shown(char, false)
		BK.palm(leg.Was - first * 0.6 + UP * 0.3, -first, 1 + 0.15 * k)
		VFX.PlaySound("BlitzPass", leg.Was, (0.8 + 0.1 * k) * gain)
		for i = 1, 6 do
			local a0, a1 = (i - 1) / 6, i / 6
			task.delay(dur * a0, function()
				local p0, p1 = BK.curve(leg, a0), BK.curve(leg, a1)
				local seg = newPart(Vector3.new(0.8, 0.8, (p1 - p0).Magnitude + 0.4), CFrame.lookAt((p0 + p1) / 2, p1), FIRE[1]:Lerp(Color3.new(1, 1, 1), a1 * 0.6), Enum.Material.Neon)
				seg.Name = "BlitzDash"
				seg.Transparency = 0.1
				tween(seg, 0.3, { Size = Vector3.new(0.05, 0.05, seg.Size.Z), Transparency = 1 }, Enum.EasingStyle.Quad, nil, 0.04)
				cleanup(seg, 0.4)
				-- (the burn it leaves on the street under it)
				local hit = groundRay(p0, 40)
				local hit1 = groundRay(p1, 40)
				if hit and hit1 then
					local g0, g1 = hit.Position + UP * 0.05, hit1.Position + UP * 0.05
					local burn = newPart(Vector3.new(0.7 + 0.08 * k, 0.05, (g1 - g0).Magnitude + 0.3), CFrame.lookAt((g0 + g1) / 2, g1), Color3.fromRGB(36, 28, 26), Enum.Material.SmoothPlastic)
					burn.Name = "BlitzScorch"
					burn.Transparency = 0.2
					tween(burn, 1.5, { Transparency = 1 }, Enum.EasingStyle.Linear, nil, 5)
					cleanup(burn, 6.6)
					groundMark(g0, 0.8 + 0.1 * k, Color3.fromRGB(40, 32, 30), 5)
				end
			end)
		end
		for i = 1, 5 do
			local a = (i - 0.5) / 5
			task.delay(dur * a, function()
				local p = BK.curve(leg, a)
				BK.ghost(char, CFrame.lookAt(p, p + BK.tangent(leg, a, leg.Way)) * CFrame.Angles(math.rad(-80), 0, 0),
					FIRE[3]:Lerp(Color3.new(1, 1, 1), i / 6), 0.2 + i * 0.03, 0.2 + i * 0.06)
			end)
		end
		for _, a in { 0.15, 0.35, 0.6 } do
			task.delay(dur * a, function()
				BK.pop(BK.curve(leg, a) - BK.tangent(leg, a, leg.Way) * 0.8, 0.8 + 0.15 * k, 0)
			end)
		end
	end

	-- the sonic boom as he goes past them (rings off him; from the 2nd
	-- overtake on, it hits them too)
	function BK.boom(leg, k, troot, gain)
		local p = typeof(leg.PassAt) == "Vector3" and leg.PassAt or leg.To
		for i = 0, 2 do
			task.delay(i * 0.03, function()
				local disc = shockDisc(p + leg.Way * (i * 1.2), leg.Way, 1.5 + i, 10 + i * 4 + 2 * k, 0.22, Color3.new(1, 1, 1))
				disc.Name = "BlitzBoom"
			end)
		end
		billboardRing(p, 1, 10 + 2 * k, Color3.new(1, 1, 1), 4, 0.2)
		if leg.Boom then
			local at = (troot and troot.Parent and troot.Position or leg.To) + UP * 0.6
			VFX.HitStar(at, 4 + k, Color3.new(1, 1, 1))
			sparks(at, 0.6, Color3.new(1, 1, 1), FIRE[1], 6)
		end
		VFX.PlaySound("BlitzBoom", p, (0.7 + 0.1 * k) * gain)
		VFX.ShakeAt(p, 0.8 + 0.2 * k, 70, 0.15)
	end

	-- the blast from in front at the end of overtake k (of n): it throws them
	-- back the other way, higher - bigger every time, and an impact frame
	-- on the last one before the flip
	function BK.blast(char, leg, k, n, gain)
		local face = leg.To + UP * 1.2
		local back = -leg.Way
		BK.palm(handPos(char, k % 2 == 1), back, 1.3 + 0.2 * k)
		toonExplosion(face + leg.Way * 0.5, 1.1 + 0.25 * k, { NoDebris = true, NoScorch = true, SmokeLife = 0.8 })
		shockDisc(face, back, 2, 12 + 3 * k, 0.25, FIRE[2], 3)
		streaks(face, back, 8 + 2 * k, 0.8, 6, 14 + 3 * k, FIRE[1], 0.28)
		VFX.HitStar(face, 6 + k, FIRE[1])
		local MG = VFX.MANGA
		if MG then
			MG.flare(face, FIRE[1], 1.6 + 0.4 * k, 0.2)
			if k == n - 1 then
				MG.impact(face, 0.06, { Radius = 90 })
			end
		end
		VFX.PlaySound("BlitzHit", face, (0.8 + 0.1 * k) * gain)
		VFX.ShakeAt(face, 1 + 0.4 * k, 90, 0.2)
	end

	-- his cutscene, from the plan (the USS way: SHOTS built at the event),
	-- framed on the plan's own heights. In his facing as VFX.Cinematic frames
	-- it (his root right now), so a body that replicated late doesn't throw
	-- the shots off. The camera keeps to one side of the lane (his right -
	-- the palm - unless the other side has more room; a wall pulls it in):
	-- the two of them face to face, low; cut on "GOT" to a worm's-eye view
	-- tracking them down the lane; cut on each blast, tracking them back up
	-- it and down again, higher and closer every time; the two heads in
	-- profile for the flip and the crawl; behind him and to the side, down
	-- the street, for the Explosion (BlastShot). One soft whoosh, into the
	-- crawl: the blasts carry the other cuts (tools/r83 render_plan.py)
	function BK.blitzShots(data, d, root, ability)
		local look = Vector3.new(root.CFrame.LookVector.X, 0, root.CFrame.LookVector.Z)
		if look.Magnitude < 0.05 then
			look = Vector3.new(0, 0, -1)
		end
		local basis = CFrame.lookAt(root.Position, root.Position + look.Unit)
		-- (round 83 review) a shot's eye is pulled in short of anything between
		-- it and what it's on (`on`: the subject nearest it; the look-at if
		-- nil) - a wall, an awning: the camera's never inside a building
		local function S(eye, at, on)
			on = on or at
			pcall(function()
				local gap = eye - on
				if gap.Magnitude > 0.5 then
					local hit = workspace:Raycast(on, gap, rayParams)
					if hit then
						eye = on + gap.Unit * math.max(hit.Distance - 0.8, math.min(1, hit.Distance * 0.5))
					end
				end
			end)
			return { basis:PointToObjectSpace(eye), basis:PointToObjectSpace(at) }
		end
		local legs = data.Legs
		local at, from = data.At, typeof(data.From) == "Vector3" and data.From or data.At - d * 2.6
		local right = d:Cross(UP)
		right = right.Magnitude > 0.1 and right.Unit or Vector3.new(1, 0, 0)
		local mid = at
		for _, leg in legs do
			mid += leg.To
		end
		mid /= (#legs + 1)
		-- (round 83 review) and out to the side no further than the street's
		-- walls (clear: the room on the open side; it used to put the camera
		-- 6 out however close they were)
		local side, clear = right, 15
		pcall(function()
			rayParams.FilterDescendantsInstances = characterList()
			local a = workspace:Raycast(mid + UP, right * 15, rayParams)
			local b = workspace:Raycast(mid + UP, -right * 15, rayParams)
			local ra, rb = a and a.Distance or 15, b and b.Distance or 15
			side = rb > ra + 0.5 and -right or right
			clear = math.max(ra, rb)
		end)
		local cap = math.max(clear - 1.5, clear * 0.6)
		local dist = math.min(math.clamp(clear - 1.5, 6, 11), cap)
		local street = at.Y - 2.4
		local function flat(p, y)
			return Vector3.new(p.X, y, p.Z)
		end
		-- 1: face to face, low from the side, his palm coming up to their face
		local pair = (at + from) / 2
		local near = math.min(9, dist)
		local shots = {
			{ T = math.max(tonumber(data.Open) or 0.2, 0.05), From = S(pair + side * near + d * 1.5 + UP * 0.4, pair + UP * 1.1),
				To = S(pair + side * (near - 1) + d * 1.3 + UP * 0.4, pair + UP * 1.1), Fov = { 42, 36 } },
		}
		for k, leg in legs do
			if k == 1 then
				-- 2: "GOT" - a worm's-eye view tracking them down the lane
				table.insert(shots, { T = leg.T1 - leg.T0, Cut = true, Quiet = true, Fov = { 60, 66 },
					From = S(flat(leg.From, street) + side * dist - leg.Way * 2, leg.From + UP * 0.5), To = S(flat(leg.To, street + 0.6) + side * dist + leg.Way, leg.To + UP * 0.4) })
			else
				-- 3...: tracking them back up the lane and down again, higher and closer
				local r, h = math.min(math.max(dist + 1 - 1.5 * (k - 2), 5), cap), 1.5 - 0.4 * (k - 2)
				table.insert(shots, { T = leg.T1 - leg.T0, Cut = true, Quiet = true, Fov = { 58, 62 },
					From = S(leg.From + side * r + UP * h - leg.Way * 1.5, leg.From + UP * 0.4), To = S(leg.To + side * r + UP * (h - 0.2) + leg.Way * 1.5, leg.To + UP * 0.4) })
			end
		end
		local last = legs[#legs]
		-- the two heads in profile for the flip and the crawl
		local heads = (last.To + last.Him) / 2 + UP * 1.5
		table.insert(shots, { T = tonumber(data.Time) or ability.SlowMo or 0.5, Cut = true, CutGain = 0.35, Fov = { 50, 40 },
			From = S(heads + side * math.min(9, cap) + UP * 0.4, heads), To = S(heads + side * math.min(7, cap) + UP * 0.2, heads) })
		-- behind him and to the side, down the street, as the fireball drives them off
		local dF = -last.Way
		local hang = last.Him + UP * (tonumber(data.FlipRise) or ability.FlipRise or 3) -- (round 83 review: less under a ceiling)
		table.insert(shots, { T = ability.BlastShot or 0.8, Cut = true, Quiet = true, Style = Enum.EasingStyle.Quad, Fov = { 70, 80 },
			From = S(hang - dF * 5 + side * math.min(4, cap) + UP, last.To + dF * 25 + UP, hang), To = S(hang - dF * 8 + side * math.min(5, cap) + UP * 3, last.To + dF * 35 + UP * 2, hang) })
		return shots
	end

	function Effects.ExplosiveSpeed(char, data, isLocal, ability)
		local root = charParts(char)
		if not root then
			return
		end
		ability = ability or Config.FindAbilityById("ExplosiveSpeed") or {}
		local d = flatten(data.Dir, root)
		if isLocal then
			face(root, d)
		end
		local st = { dead = false }
		BK.blitz[char] = st
		local windUp = ability.WindUp or 0.6
		VFX.MuteGait(char, windUp + 1.2) -- (nothing fighting the crouch or the flight)
		-- (round 79) an R6 body's clip is held on its coil (Hold..HoldEnd, slowed
		-- down to fill it) through the whole wind-up - it used to run out 0.4s
		-- early, stand him up, then snap into the flight
		local crouch = Anim.MoveClips ~= false and VFX.GetClip("MoveBlitzCrouch")
		if not (crouch and crouch.holdAt and VFX.Clip(char, "MoveBlitzCrouch", { holdFor = math.max(windUp - crouch.length, 0), recover = 0.125 })) then
			VFX.Motion(char, "BlitzCrouch")
		end
		-- (round 76) "I'M THE FINAL BOSS, GOT IT?" - (round 83) "GOT" lined up
		-- on the blitz's opener (OpenAt; on his own screen a round trip later,
		-- when the server's opener gets back to him) and out right after
		-- "IT?" (Config.Voice FinalBoss Fixed). Kept, so a cancel can stop it
		-- and the blitz can keep its own sounds under it till then
		local openAt = ability.OpenAt or 1.5
		if isLocal then
			local okPing, ping = pcall(function()
				return Players.LocalPlayer:GetNetworkPing()
			end)
			openAt += (okPing and type(ping) == "number") and math.clamp(ping, 0, 0.3) or 0
		end
		st.voice = VFX.Voice("FinalBoss", root, openAt)
		local line = Config.Voice and Config.Voice.FinalBoss
		if line and VFX.VC then
			local s0, w0, stop = VFX.VC.plan(line, nil, openAt)
			if stop then
				st.quietUntil = os.clock() + w0 + (stop - s0) + 0.06
			end
		end
		VFX.PlaySound("BlitzCharge", root.Position, 1)
		dustPuffs(groundPoint(root.Position), 0.6, 3, Color3.fromRGB(200, 190, 175), 0.6, false)
		BK.cracks(root.Position, d, windUp)
		if isLocal then
			VFX.ShakeAt(root.Position, 0.8, 40, windUp)
		end
		-- the beads popping all over him, quicker and quicker, and both palms
		-- swelling white-hot
		local glows = {}
		for _, right in { true, false } do
			local glow = newPart(Vector3.one * 0.3, CFrame.new(handPos(char, right)), Color3.fromRGB(255, 236, 190), Enum.Material.Neon, Enum.PartType.Ball)
			glow.Name = "BlitzPalmGlow"
			glow.Transparency = 0.25
			glows[right] = glow
		end
		task.spawn(function()
			local t0 = os.clock()
			while not st.dead and char.Parent and os.clock() - t0 < windUp do
				local k = (os.clock() - t0) / windUp
				for _ = 1, 1 + math.floor(k * 4) do
					BK.bead(char)
				end
				if rng:NextNumber() < 0.25 + k * 0.5 then
					sparks(handPos(char, rng:NextNumber() < 0.5), 0.3 + 0.3 * k, Color3.new(1, 1, 1), FIRE[1], 3)
				end
				for right, glow in glows do
					glow.CFrame = CFrame.new(handPos(char, right))
					glow.Size = Vector3.one * (0.3 + 1.1 * k)
				end
				task.wait(0.035)
			end
			for _, glow in glows do
				glow:Destroy()
			end
			if not st.dead and char.Parent then
				-- (the last crackle: both palms blaze)
				BK.palm(handPos(char, true), -d, 0.8)
				BK.palm(handPos(char, false), -d, 0.8)
			end
		end)
	end

	-- the blitz: gone in a crack of blasts, down the street
	function Effects.ExplosiveSpeedGo(char, data, isLocal)
		local root = charParts(char)
		local st = BK.blitz[char] or { dead = false }
		BK.blitz[char] = st
		if not root or st.dead then
			return
		end
		local from = typeof(data.From) == "Vector3" and data.From or root.Position
		local d = typeof(data.Dir) == "Vector3" and data.Dir or flatten(root.CFrame.LookVector, root)
		local length = tonumber(data.Length) or 60
		local speed = math.max(tonumber(data.Speed) or 230, 1)
		local time = length / speed
		VFX.PlaySound("BlitzGo", from, 1.1)
		BK.launch(char, from, d)
		toonExplosion(from - d * 1.5, 1.6, { NoDebris = true, SmokeLife = 1.2 })
		billboardRing(from + UP, 2, 14, FIRE[2], 5, 0.25)
		BK.lane(from, d, length, data.Blink and 1e6 or speed)
		if data.Blink then
			-- someone was in the lane: he's simply THERE - a line of afterimages
			-- where he was, the street going off under it
			VFX.MuteGait(char, 1.4)
			-- (round 83) ghosts of his body down the lane (they were flat neon
			-- slabs), out of the set and leaning into the run, fire to white
			for s = 0, length, math.max(5, length / 10) do
				local k = s / math.max(length, 1)
				local at = from + d * s
				BK.ghost(char, CFrame.lookAt(at, at + d) * CFrame.Angles(math.rad(-20 - 30 * k), 0, 0), FIRE[2]:Lerp(Color3.new(1, 1, 1), k * 0.7), 0.2 + k * 0.15, 0.3 + k * 0.3)
			end
			VFX.Pose(char, "BlitzFly", 0.08) -- (the frame he arrives in: still flying)
			streaks(from + UP * 1.5, d, 14, 1.4, 10, length, Color3.new(1, 1, 1), 0.3)
			if isLocal then
				VFX.Hooks.SpeedLines(0.3)
			end
			if nearCamera(from + d * length, 60) then
				VFX.ImpactFrame(0.06)
			end
			return
		end
		VFX.MuteGait(char, time + 0.4)
		-- (round 79) held so the flight ends as the server sets him upright at
		-- the end of the lane (an R6 clip's Hold..HoldEnd stretch counted)
		local fly = Anim.MoveClips ~= false and VFX.GetClip("PoseBlitzFly")
		local flyHold = time + 0.1
		if fly and fly.holdAt and fly.holdEnd then
			flyHold = math.max(time - (fly.holdEnd - fly.holdAt), 0.05)
		end
		VFX.Pose(char, "BlitzFly", flyHold)
		streaks(from + UP * 1.5, d, 10, 1.2, 8, length, Color3.new(1, 1, 1), time + 0.2)
		if isLocal then
			VFX.Hooks.SpeedLines(time + 0.2)
		end
		st.stopTrail = addTrail(root, FIRE[2], 0.35, 3)
		task.spawn(function()
			local t0 = os.clock()
			local flip = false
			while not st.dead and root.Parent and os.clock() - t0 < time + 0.15 do
				-- (the palms blasting behind him, left and right in turn)
				flip = not flip
				local hp = handPos(char, flip)
				toonExplosion(hp - d * 1.2 + Vector3.new(rand(-0.3, 0.3), rand(-0.3, 0.3), rand(-0.3, 0.3)), 0.6, { NoDebris = true, NoScorch = true, NoEmbers = true, SmokeLife = 0.5 })
				BK.bead(char)
				afterimage(char, FIRE[1], 0.22)
				task.wait(0.04)
			end
			if st.stopTrail then
				st.stopTrail(0.15)
				st.stopTrail = nil
			end
		end)
	end

	-- (round 83) THE BLITZ, a leapfrog down the lane, drawn from the server's
	-- plan (Kit.blitzPlan - the server runs the same clock, so the bodies it
	-- moves land on these beats): the face-off, the opener on "GOT", then
	-- each overtake - the blur past them, the boom, the blast from in front
	-- - till the last one ends in the flip (ExplosiveSpeedCatch). Its own
	-- clock (st.blitz): the flight's flag (st.dead) only stops the flight's
	-- palms and trail, which stop here.
	function Effects.ExplosiveSpeedBlitz(char, data, _isLocal, ability)
		local root = charParts(char)
		local legs = type(data.Legs) == "table" and data.Legs or {}
		if not root or typeof(data.At) ~= "Vector3" or #legs == 0 then
			return
		end
		for _, leg in legs do
			for _, key in { "From", "To", "Way", "Was", "Via", "Him" } do
				if typeof(leg[key]) ~= "Vector3" then
					return
				end
			end
			for _, key in { "T0", "T1", "Go", "Arrive" } do
				if type(leg[key]) ~= "number" then
					return
				end
			end
		end
		ability = ability or Config.FindAbilityById("ExplosiveSpeed") or {}
		local st = BK.blitz[char] or { dead = false }
		BK.blitz[char] = st
		st.dead = true
		if st.stopTrail then
			st.stopTrail(0)
			st.stopTrail = nil
		end
		local token = {}
		st.blitz = token
		local d = typeof(data.Dir) == "Vector3" and flatten(data.Dir, root) or flatten(root.CFrame.LookVector, root)
		local target = typeof(data.Target) == "Instance" and data.Target or nil
		local troot = target and target:FindFirstChild("HumanoidRootPart")
		local t0 = os.clock()
		local open = math.max(tonumber(data.Open) or 0.2, 0)
		local flip = tonumber(data.Flip) or legs[#legs].T1
		VFX.MuteGait(char, flip + 1)
		-- the camera: his cutscene, built from the plan; a short cut for
		-- anyone else near - not the one he's caught (their own camera
		-- follows them down the lane)
		local me = Players.LocalPlayer
		local mine = me ~= nil and me.Character == char
		if not (me and target and me.Character == target) then
			if mine then
				SHOTS.ExplosiveSpeedBlitz = BK.blitzShots(data, d, root, ability)
			end
			cinematicFor(char, "ExplosiveSpeedBlitz", mine, ability.Name or "EXPLOSIVE SPEED", FIRE[2], { Quiet = true })
		end
		local MG = VFX.MANGA
		local function going()
			return BK.blitz[char] == st and st.blitz == token and char.Parent ~= nil
		end
		-- (under "GOT IT?": half as loud, so the line stays on top)
		local function gain()
			return (st.quietUntil and os.clock() < st.quietUntil) and 0.5 or 1
		end
		local events = {}
		local function at(t, fn)
			table.insert(events, { T = t, Do = fn })
		end
		-- the face-off: his palm coming up to their face; it goes off on "GOT"
		BK.play(char, "MoveBlitzOpen", open, "BlitzOpen")
		at(open, function()
			BK.opener(char, data.At, d, gain())
			if troot and troot.Parent then
				st.stopVictim = addTrail(troot, FIRE[2], 0.3, 2)
			end
			-- colour streaming past, for anyone close (RushBlitz's bands, in fire)
			if MG and nearCamera(data.At, 120) then
				MG.lines(math.max(flip - open, 0.2), { Kind = "stream", Colors = { FIRE[1], FIRE[2], FIRE[3], Color3.new(1, 1, 1) }, Angle = -18, Alpha = 0.35 })
			end
		end)
		for k, leg in legs do
			local last = k == #legs
			-- flat out for the blur (a moment before it, so the ghosts catch it)
			at(math.max(leg.Go - 0.03, leg.T0 + 0.04), function()
				VFX.Pose(char, "BlitzFly", leg.Arrive - leg.Go + 0.08)
			end)
			at(leg.Go, function()
				BK.overtake(char, leg, k, gain())
			end)
			if type(leg.Pass) == "number" then
				at(leg.Pass, function()
					BK.boom(leg, k, troot, gain())
				end)
			end
			at(leg.Arrive, function()
				BK.shown(char, true)
				if not last then
					BK.play(char, k % 2 == 1 and "MoveBlitzBlast" or "MoveBlitzBlastL", leg.T1 - leg.Arrive, k % 2 == 1 and "BlitzBlast" or "BlitzBlastL")
				end
			end)
			if not last then
				at(leg.T1, function()
					BK.blast(char, leg, k, #legs, gain())
				end)
			end
		end
		table.sort(events, function(a, b)
			return a.T < b.T
		end)
		task.spawn(function()
			for _, ev in events do
				while going() and os.clock() - t0 < ev.T do
					task.wait()
				end
				if not going() then
					break
				end
				ev.Do()
			end
			-- (whatever happened: his body back, their trail out)
			BK.shown(char, true)
			if st.stopVictim then
				st.stopVictim(0.1)
				st.stopVictim = nil
			end
		end)
	end

	-- caught face to face: time crawls while his palm comes up to their face
	function Effects.ExplosiveSpeedCatch(char, data)
		local root = charParts(char)
		local st = BK.blitz[char] or { dead = false }
		BK.blitz[char] = st
		if not root then
			return
		end
		local face = typeof(data.Pos) == "Vector3" and data.Pos or root.Position
		local d = typeof(data.Dir) == "Vector3" and data.Dir or flatten(root.CFrame.LookVector, root)
		local time = tonumber(data.Time) or 0.75
		if st.stopTrail then
			st.stopTrail(0)
			st.stopTrail = nil
		end
		st.dead = true -- (the blitz is over)
		VFX.MuteGait(char, time + 0.6)
		VFX.Motion(char, "BlitzFlip")
		VFX.PlaySound("BlitzSlow", face, 1)
		st.endSlow = BK.slowMo(face, time)
		st.endFlare = BK.flare(char, time)
		local lp = Players.LocalPlayer
		local me = lp and lp.Character
		if me and (me == char or me == data.Target) then
			VFX.Hooks.SpeedLines(time) -- (the panel's focus lines, on the two of them)
		end
		-- the little explosions popping all round him as time crawls, the
		-- stars of light thrown off them, heat rippling off his palm
		task.spawn(function()
			local t0 = os.clock()
			local nextRipple = 0
			while os.clock() - t0 < time and char.Parent and BK.blitz[char] == st do
				local k = (os.clock() - t0) / time
				local near = rng:NextNumber() < 0.55 and handPos(char, rng:NextNumber() < 0.7) or root.Position
				BK.pop(near + rng:NextUnitVector() * rand(0.8, 3.2), rand(0.4, 0.9) * (0.8 + k * 0.6), time)
				if rng:NextNumber() < 0.8 then
					BK.star(face + Vector3.new(rand(-6, 6), rand(-2.5, 5), rand(-6, 6)), rand(0.5, 1.4), time)
				end
				if os.clock() - t0 >= nextRipple then
					nextRipple = os.clock() - t0 + 0.26
					local hp = handPos(char, true)
					local ring = shockDisc(hp, d, 0.6, 3.4 + 2 * k, 0.55, FIRE[1]:Lerp(Color3.new(1, 1, 1), 0.5))
					ring.Name = "BlitzRipple"
				end
				task.wait(0.045)
			end
		end)
		-- the sparks off his run, drifting as if time had all but stopped
		for _ = 1, 26 do
			local p = face + Vector3.new(rand(-4, 4), rand(-2.5, 3), rand(-4, 4))
			local c = ({ Color3.new(1, 1, 1), FIRE[1], FIRE[2] })[rng:NextInteger(1, 3)]
			local mote = newPart(Vector3.one * rand(0.12, 0.3), CFrame.new(p) * CFrame.Angles(rand(0, 6), rand(0, 6), rand(0, 6)), c, Enum.Material.Neon)
			tween(mote, time + 0.1, { CFrame = mote.CFrame + Vector3.new(rand(-0.4, 0.4), rand(0.1, 0.6), rand(-0.4, 0.4)) }, Enum.EasingStyle.Linear)
			cleanup(mote, time + 0.12)
		end
		-- the palm heating up: a white-hot glow swelling at his hand
		local glow = newPart(Vector3.one * 0.3, CFrame.new(handPos(char, true)), Color3.fromRGB(255, 244, 214), Enum.Material.Neon, Enum.PartType.Ball)
		glow.Transparency = 0.2
		local t0 = os.clock()
		local conn
		conn = RunService.RenderStepped:Connect(function()
			local k = math.clamp((os.clock() - t0) / time, 0, 1)
			if not char.Parent or k >= 1 then
				conn:Disconnect()
				glow:Destroy()
				return
			end
			glow.Size = Vector3.one * (0.3 + 1.8 * k * k)
			glow.CFrame = CFrame.new(handPos(char, true))
		end)
	end

	-- the Explosion, point blank: a white flash, a star of light, the
	-- fireball driven through them and on down the street, the ground ring,
	-- a column of smoke - and the one it hits goes flying trailing fire
	function Effects.ExplosiveSpeedBlast(char, data)
		local st = BK.blitz[char]
		if st then
			if st.endSlow then
				st.endSlow()
			end
			if st.endFlare then
				st.endFlare()
			end
			if st.stopVictim then
				st.stopVictim(0)
				st.stopVictim = nil
			end
			BK.blitz[char] = nil
		end
		BK.shown(char, true)
		-- (round 83 review) the Explosion's the knockout: his cutscene's last
		-- shot makes way for the KO's kill cam, which comes right after it
		local me = Players.LocalPlayer
		if data.KO == true and me and me.Character == char and VFX.InOwnCinematic() then
			VFX.CancelCinematic()
		end
		local at = typeof(data.Pos) == "Vector3" and data.Pos
		if not at then
			return
		end
		local d = typeof(data.Dir) == "Vector3" and data.Dir or UP
		VFX.Pose(char, "Blast", 0.45)
		local flash = newPart(Vector3.one * 2, CFrame.new(at + d * 1.5), Color3.new(1, 1, 1), Enum.Material.Neon, Enum.PartType.Ball)
		flash.Name = "BlitzFlash"
		tween(flash, 0.1, { Size = Vector3.one * 15 }, Enum.EasingStyle.Quad)
		tween(flash, 0.18, { Transparency = 1, Size = Vector3.one * 18 }, nil, nil, 0.1)
		cleanup(flash, 0.3)
		VFX.HitStar(at + d * 1.2, 14, FIRE[1])
		toonExplosion(at + d * 1.5, 4.6, { SmokeLife = 2.8 })
		for i, far in { 7, 12, 17 } do
			task.delay(0.05 * i, function()
				toonExplosion(at + d * far + UP * (i * 0.4), 3.2 - i * 0.5, { NoDebris = true, SmokeLife = 1.9 - i * 0.2 })
			end)
		end
		shockDisc(at, d, 4, 48, 0.35, FIRE[2], 8)
		shockDisc(groundPoint(at) + UP * 0.3, UP, 4, 40, 0.45, Color3.new(1, 1, 1))
		billboardRing(at, 4, 42, FIRE[1], 10, 0.35)
		streaks(at, d, 16, 0.5, 11, 34, FIRE[1], 0.32)
		sparks(at + d * 2, 1.6, Color3.new(1, 1, 1), FIRE[1], 16)
		rocks(groundPoint(at + d * 3), 1.4, 14)
		groundMark(groundPoint(at + d * 3), 7, Color3.fromRGB(40, 32, 30), 10)
		task.delay(0.2, function()
			smokeBurst(at + UP * 2.5, SMOKE_LIGHT, 4, 3, 2.2, 4)
		end)
		VFX.PlaySound("BigExplosion", at, 1.15)
		if nearCamera(at, 60) then
			VFX.ImpactFrame(0.1)
			VFX.Hooks.Flash(Color3.fromRGB(255, 236, 200), 0.25)
			-- (round 83) the panel's focus lines on it too
			if VFX.MANGA then
				VFX.MANGA.lines(0.3, { Kind = "focus" })
			end
		end
		-- (round 83) the music ducks under it (as United States of Smash does)
		if nearCamera(at, 260) and VFX.Hooks.DuckMusic then
			VFX.Hooks.DuckMusic(0.2, 0.04, 0.35, 2)
		end
		VFX.ShakeAt(at, 4.5, 170, 0.55)
		-- the one it hit: flying off trailing fire, popping as they go
		local target = typeof(data.Target) == "Instance" and data.Target
		local troot = target and target:FindFirstChild("HumanoidRootPart")
		if troot then
			local stop = addTrail(troot, FIRE[2], 0.35, 2.2)
			stop(0.9)
			task.spawn(function()
				local t0 = os.clock()
				while troot.Parent and os.clock() - t0 < 0.6 do
					toonExplosion(troot.Position + rng:NextUnitVector() * 0.8, 0.5, { NoDebris = true, NoScorch = true, NoEmbers = true, SmokeLife = 0.5 })
					task.wait(0.08)
				end
			end)
		end
	end

	-- nobody in the lane: he skids to a stop at the end of it
	function Effects.ExplosiveSpeedWhiff(char, data)
		local st = BK.blitz[char]
		if st then
			st.dead = true
			if st.stopTrail then
				st.stopTrail(0.1)
			end
			BK.blitz[char] = nil
		end
		local at = typeof(data.Pos) == "Vector3" and data.Pos
		if not at then
			return
		end
		local d = typeof(data.Dir) == "Vector3" and data.Dir or UP
		local g = groundPoint(at)
		local right = d:Cross(UP)
		right = right.Magnitude > 0.1 and right.Unit or Vector3.new(1, 0, 0)
		-- (two skid marks behind his feet, sparks off the soles)
		for _, side in { 0.5, -0.5 } do
			local mid = g + right * side - d * 2.5 + UP * 0.04
			local skid = newPart(Vector3.new(0.35, 0.05, 5), CFrame.lookAt(mid, mid + d), Color3.fromRGB(34, 28, 26), Enum.Material.SmoothPlastic)
			skid.Name = "BlitzSkid"
			tween(skid, 0.8, { Transparency = 1 }, nil, nil, 3)
			cleanup(skid, 3.9)
		end
		sparks(g + UP * 0.3, 0.8, Color3.new(1, 1, 1), FIRE[1], 8)
		dustPuffs(g, 1, 5, Color3.fromRGB(200, 190, 175), 0.9, true)
		smokeBurst(at, SMOKE_LIGHT, 3, 3, 0.6, 3)
		VFX.Pose(char, "Land", 0.35)
	end

	-- (round 83 review) data.KO: it ended in a knockout - his cutscene makes
	-- way for the KO's kill cam, and his KO pose and the line are left be
	function Effects.ExplosiveSpeedCancel(char, data)
		local ko = type(data) == "table" and data.KO == true
		local st = BK.blitz[char]
		if st then
			st.dead = true
			st.blitz = nil
			if st.stopTrail then
				st.stopTrail(0)
			end
			if st.endSlow then
				st.endSlow()
			end
			if st.endFlare then
				st.endFlare()
			end
			if st.stopVictim then
				st.stopVictim(0)
				st.stopVictim = nil
			end
			-- (round 83) his line stops with it (it used to talk on after a cancel)
			local voice = st.voice
			if not ko and typeof(voice) == "Instance" and voice:IsA("Sound") and voice.Parent then
				tween(voice, 0.12, { Volume = 0 })
				task.delay(0.13, function()
					pcall(function()
						voice:Stop()
						voice:Destroy()
					end)
				end)
			end
			BK.blitz[char] = nil
		end
		-- (round 83) called off mid-blitz: his body back, his cutscene over
		BK.shown(char, true)
		local me = Players.LocalPlayer
		if me and me.Character == char and VFX.InOwnCinematic() then
			VFX.CancelCinematic()
		end
		if not ko then
			VFX.ReleasePose(char, 0.2)
		end
	end

	-- FULL-BODY CLUSTER (round 63): his last stand against Shigaraki
	-- (chapter 362). The beads of sweat he's stored can't stay in his palms
	-- any more and burst out all over him: explosions off every limb, bigger
	-- and bigger. (BK.cluster[char]: where he last was - the afterimage trail)
	BK.cluster = setmetatable({}, { __mode = "k" })
	-- an explosion off every limb, scaled
	function BK.fullBody(char, scale)
		for _, name in { "Right Arm", "Left Arm", "Right Leg", "Left Leg", "Torso", "RightUpperArm", "LeftUpperArm", "RightUpperLeg", "LeftUpperLeg", "UpperTorso" } do
			local p = char:FindFirstChild(name)
			if p and p:IsA("BasePart") then
				local off = name:find("Torso") and -p.CFrame.LookVector * 0.8 or -p.CFrame.UpVector * 0.6
				toonExplosion(p.Position + off, scale * (name:find("Torso") and 1.25 or 0.8), { NoDebris = true, NoScorch = true, NoEmbers = scale < 0.9, SmokeLife = 0.5 })
			end
		end
	end
	-- the white void (his own screen): All Might's vestige, and the card he
	-- always wanted signed
	function BK.whiteVoid(time)
		local lp = game:GetService("Players").LocalPlayer
		local pg = lp and lp:FindFirstChildOfClass("PlayerGui")
		if not pg then
			return
		end
		local gui = Instance.new("ScreenGui")
		gui.Name = "WhiteVoid"
		gui.IgnoreGuiInset = true
		gui.ResetOnSpawn = false
		gui.DisplayOrder = 12
		local white = Instance.new("Frame")
		white.Size = UDim2.fromScale(1, 1)
		white.BackgroundColor3 = Color3.fromRGB(252, 250, 244)
		white.BackgroundTransparency = 1
		white.BorderSizePixel = 0
		white.Parent = gui
		-- his silhouette far off in the white, and the words
		local figure = Instance.new("TextLabel")
		figure.AnchorPoint = Vector2.new(0.5, 1)
		figure.Position = UDim2.fromScale(0.5, 0.62)
		figure.Size = UDim2.fromScale(0.2, 0.34)
		figure.BackgroundTransparency = 1
		figure.Font = Enum.Font.GothamBlack
		figure.TextScaled = true
		figure.Text = "V"
		figure.TextColor3 = Color3.fromRGB(214, 196, 140)
		figure.TextTransparency = 1
		figure.Parent = white
		local line = Instance.new("TextLabel")
		line.AnchorPoint = Vector2.new(0.5, 0)
		line.Position = UDim2.fromScale(0.5, 0.7)
		line.Size = UDim2.fromScale(0.8, 0.06)
		line.BackgroundTransparency = 1
		line.Font = Enum.Font.GothamMedium
		line.TextScaled = true
		line.Text = "...I always wanted you to sign my card."
		line.TextColor3 = Color3.fromRGB(70, 66, 60)
		line.TextTransparency = 1
		line.Parent = white
		gui.Parent = pg
		tween(white, math.min(0.2, time * 0.3), { BackgroundTransparency = 0.04 })
		tween(figure, time * 0.5, { TextTransparency = 0.55 }, Enum.EasingStyle.Sine, nil, time * 0.15)
		tween(line, time * 0.4, { TextTransparency = 0 }, Enum.EasingStyle.Sine, nil, time * 0.25)
		-- (cut back to the fight on the blast)
		task.delay(time, function()
			tween(white, 0.35, { BackgroundTransparency = 1 })
			tween(figure, 0.2, { TextTransparency = 1 })
			tween(line, 0.3, { TextTransparency = 1 })
			task.delay(0.4, function()
				gui:Destroy()
			end)
		end)
	end
	-- the All Might card: it slips out of his pocket and flutters down
	function BK.card(pos)
		local g = groundPoint(pos)
		local card = newPart(Vector3.new(0.9, 1.3, 0.04), CFrame.new(pos) * CFrame.Angles(rand(-0.4, 0.4), rand(0, 6), rand(-0.4, 0.4)),
			Color3.fromRGB(230, 206, 120), Enum.Material.SmoothPlastic)
		card.Name = "AllMightCard"
		for _, faceId in { Enum.NormalId.Front, Enum.NormalId.Back } do
			local sg = Instance.new("SurfaceGui")
			sg.Face = faceId
			sg.CanvasSize = Vector2.new(90, 130)
			sg.LightInfluence = 0.4
			sg.Parent = card
			local art = Instance.new("Frame")
			art.Position = UDim2.fromOffset(6, 6)
			art.Size = UDim2.new(1, -12, 1, -12)
			art.BackgroundColor3 = Color3.fromRGB(40, 70, 170)
			art.BorderSizePixel = 0
			art.Parent = sg
			local grad = Instance.new("UIGradient")
			grad.Color = ColorSequence.new(Color3.fromRGB(255, 255, 255), Color3.fromRGB(150, 150, 150))
			grad.Rotation = 90
			grad.Parent = art
			local label = Instance.new("TextLabel")
			label.Size = UDim2.fromScale(1, 0.3)
			label.Position = UDim2.fromScale(0, 0.68)
			label.BackgroundTransparency = 1
			label.Font = Enum.Font.GothamBlack
			label.TextScaled = true
			label.Text = faceId == Enum.NormalId.Front and "ALL MIGHT" or "PLUS ULTRA"
			label.TextColor3 = Color3.fromRGB(255, 226, 90)
			label.Parent = art
			local smile = Instance.new("TextLabel")
			smile.Size = UDim2.fromScale(1, 0.6)
			smile.Position = UDim2.fromScale(0, 0.06)
			smile.BackgroundTransparency = 1
			smile.Font = Enum.Font.GothamBlack
			smile.TextScaled = true
			smile.Text = faceId == Enum.NormalId.Front and "V" or "★"
			smile.TextColor3 = Color3.fromRGB(255, 244, 200)
			smile.Parent = art
		end
		-- down it drifts, rocking from side to side
		local steps = 8
		local fall = math.max(pos.Y - g.Y - 0.1, 0.5)
		for i = 1, steps do
			local k = i / steps
			local at = Vector3.new(pos.X + math.sin(k * 7) * 0.9, pos.Y - fall * k, pos.Z + math.cos(k * 5) * 0.5)
			local rot = i == steps and CFrame.Angles(0, rand(0, 6), 0) * CFrame.Angles(math.rad(90), 0, 0) or CFrame.Angles(math.sin(k * 9) * 0.7, k * 3, math.cos(k * 7) * 0.6)
			tween(card, 0.2, { CFrame = CFrame.new(at) * rot }, Enum.EasingStyle.Sine, nil, (i - 1) * 0.2)
		end
		tween(card, 0.6, { Transparency = 1 }, nil, nil, steps * 0.2 + 4)
		cleanup(card, steps * 0.2 + 4.7)
	end

	-- his walk at them: beaten half to death and calm, the beads popping off
	-- him all the way, steam coming off him
	function Effects.FullBodyCluster(char, data, isLocal, ability)
		local root = charParts(char)
		if not root then
			return
		end
		ability = ability or Config.FindAbilityById("FullBodyCluster") or {}
		local d = flatten(data.Dir, root)
		if isLocal then
			face(root, d)
		end
		local walk = ability.WalkTime or 0.9
		local st = { dead = false }
		BK.cluster[char] = st
		VFX.MuteGait(char, walk + 0.2)
		if not VFX.Clip(char, "LastStandWalk") then
			VFX.Motion(char, "Awaken")
		end
		VFX.SpeechBubble(char, ability.Say or "IZUKU... YOU'VE GOTTA WIN.", walk + 0.5)
		VFX.PlaySound("BlitzCharge", root.Position, 0.8)
		task.spawn(function()
			local t0 = os.clock()
			while not st.dead and char.Parent and os.clock() - t0 < walk do
				local k = (os.clock() - t0) / walk
				for _ = 1, 1 + math.floor(k * 3) do
					BK.bead(char)
				end
				if rng:NextNumber() < 0.3 + 0.4 * k then
					BK.pop(root.Position + rng:NextUnitVector() * rand(0.8, 1.8), rand(0.3, 0.6) * (0.7 + k), 0)
				end
				if rng:NextNumber() < 0.25 then
					smokeBurst(root.Position + UP * rand(0, 1.5), SMOKE_LIGHT, 0.6, 0.8, 0.5, 1)
				end
				task.wait(0.05)
			end
		end)
	end

	-- gone - and in their face: the palm lets off a mass of stored Cluster
	function Effects.FullBodyClusterBlink(char, data)
		local root = charParts(char)
		local st = BK.cluster[char] or { dead = false }
		BK.cluster[char] = st
		if not root then
			return
		end
		st.dead = true
		local from = typeof(data.From) == "Vector3" and data.From or root.Position
		local to = typeof(data.To) == "Vector3" and data.To or root.Position
		local d = typeof(data.Dir) == "Vector3" and data.Dir or flatten(root.CFrame.LookVector, root)
		st.last = to
		VFX.MuteGait(char, 3)
		afterimage(char, FIRE[1], 0.3)
		toonExplosion(from - d * 1.2, 1.1, { NoDebris = true, SmokeLife = 0.8 })
		streaks(from + UP, (to - from).Magnitude > 0.1 and (to - from).Unit or d, 12, 1.2, 8, (to - from).Magnitude, Color3.new(1, 1, 1), 0.25)
		VFX.PlaySound("BlitzGo", from, 1)
		if not VFX.Clip(char, "ClusterPalm") then
			VFX.Pose(char, "Blast", 0.3)
		end
		local faceAt = to + d * 2.6 + UP * 1.3
		task.delay(0.06, function()
			for i = 1, 7 do
				task.delay(i * 0.022, function()
					toonExplosion(faceAt + Vector3.new(rand(-1, 1), rand(-0.8, 1), rand(-1, 1)), rand(0.5, 0.8), { NoDebris = true, NoScorch = true, NoEmbers = true, SmokeLife = 0.6 })
				end)
			end
			BK.palm(handPos(char, true), d, 1.4)
			VFX.PlaySound("PalmPop", faceAt, 1.1)
			VFX.PlaySound("Explosion", faceAt, 0.9)
			if nearCamera(faceAt, 60) then
				VFX.ImpactFrame(0.05)
			end
			VFX.ShakeAt(faceAt, 2, 90, 0.25)
		end)
	end

	-- all round them: from every side, explosions off his whole body, each
	-- bigger and quicker than the last
	function Effects.FullBodyClusterHit(char, data)
		local root = charParts(char)
		local st = BK.cluster[char] or { dead = true }
		BK.cluster[char] = st
		if not root then
			return
		end
		local spot = typeof(data.Pos) == "Vector3" and data.Pos or root.Position
		local at = typeof(data.At) == "Vector3" and data.At or spot
		local level = tonumber(data.Level) or 1
		local k = level / math.max(tonumber(data.Of) or 5, 1)
		if st.last then
			local v = spot - st.last
			if v.Magnitude > 0.5 then
				streaks(st.last + UP * 0.5, v.Unit, 6, 0.8, 5, v.Magnitude, FIRE[1]:Lerp(Color3.new(1, 1, 1), 0.5), 0.18)
			end
		end
		st.last = spot
		afterimage(char, FIRE[1]:Lerp(Color3.new(1, 1, 1), k * 0.5), 0.2)
		local clips = { "ClusterStrikeA", "ClusterStrikeB", "ClusterStrikeC" }
		if not VFX.Clip(char, clips[(level - 1) % 3 + 1]) then
			VFX.Pose(char, "Blast", 0.2)
		end
		BK.fullBody(char, 0.45 + 0.4 * k)
		task.delay(0.03, function()
			local toward = (at - spot).Magnitude > 0.1 and (at - spot).Unit or UP
			toonExplosion(at - toward * 0.6, 1 + 1.3 * k, { NoDebris = k < 0.6, SmokeLife = 0.9 + k })
			shockDisc(at, toward, 1, 10 + 12 * k, 0.2, FIRE[2], 2)
			for _ = 1, 2 + level do
				BK.star(at + Vector3.new(rand(-4, 4), rand(-2, 4), rand(-4, 4)), rand(0.5, 1.2), 0)
			end
			VFX.PlaySound(k > 0.7 and "BigExplosion" or "Explosion", at, 0.8 + 0.3 * k)
			VFX.ShakeAt(at, 1.5 + 2 * k, 100, 0.2)
			if k > 0.75 and nearCamera(at, 60) then
				VFX.ImpactFrame(0.04)
			end
		end)
	end

	-- the white void (his own screen) as both palms fill with all he has
	function Effects.FullBodyClusterVoid(char, data)
		local root = charParts(char)
		if not root then
			return
		end
		local time = tonumber(data.Time) or 0.7
		if not VFX.Clip(char, "ClusterCharge") then
			VFX.Pose(char, "PunchCharge", time)
		end
		VFX.PlaySound("BlastCharge", root.Position, 1)
		local lp = game:GetService("Players").LocalPlayer
		if lp and lp.Character == char then
			BK.whiteVoid(time)
		end
		-- (everyone else: the beads going off all over him, the palms blazing)
		task.spawn(function()
			local t0 = os.clock()
			while char.Parent and os.clock() - t0 < time do
				BK.bead(char)
				BK.bead(char)
				if rng:NextNumber() < 0.5 then
					sparks(handPos(char, rng:NextNumber() < 0.5), 0.5, Color3.new(1, 1, 1), FIRE[1], 4)
				end
				task.wait(0.04)
			end
		end)
	end

	-- everything he has left, point blank - and the card floats down
	function Effects.FullBodyClusterFinal(char, data)
		local root = charParts(char)
		BK.cluster[char] = nil
		if not root then
			return
		end
		local at = typeof(data.Pos) == "Vector3" and data.Pos or root.Position
		local d = typeof(data.Dir) == "Vector3" and data.Dir or flatten(root.CFrame.LookVector, root)
		if not VFX.Clip(char, "ClusterFinal") then
			VFX.Pose(char, "Blast", 0.45)
		end
		BK.fullBody(char, 1.1)
		toonExplosion(at + d * 1.5, 5, { SmokeLife = 2.8 })
		task.delay(0.07, function()
			toonExplosion(at + d * 8, 3.4, { NoDebris = true, SmokeLife = 2 })
		end)
		task.delay(0.14, function()
			toonExplosion(at + d * 13 + UP * 2, 2.4, { NoDebris = true, SmokeLife = 1.6 })
		end)
		shockDisc(at, d, 4, 54, 0.4, FIRE[2], 8)
		shockDisc(groundPoint(at) + UP * 0.3, UP, 4, 40, 0.45, Color3.new(1, 1, 1))
		billboardRing(at, 4, 46, FIRE[1], 12, 0.4)
		streaks(at, d, 18, 0.6, 12, 36, FIRE[1], 0.35)
		rocks(groundPoint(at + d * 3), 1.4, 14)
		groundMark(groundPoint(at + d * 3), 8, Color3.fromRGB(40, 32, 30), 10)
		VFX.PlaySound("BigExplosion", at, 1.2)
		VFX.PlaySound("MegaBoom", at, 0.7)
		if nearCamera(at, 70) then
			VFX.ImpactFrame(0.12)
			VFX.Hooks.Flash(Color3.fromRGB(255, 236, 200), 0.3)
		end
		VFX.ShakeAt(at, 5, 180, 0.6)
		task.delay(0.35, function()
			if root.Parent then
				BK.card(root.Position + UP * 1.2)
			end
		end)
	end

	-- nobody in reach: he blasts off down the aim into one explosion
	function Effects.FullBodyClusterWhiff(char, data)
		local root = charParts(char)
		local st = BK.cluster[char]
		if st then
			st.dead = true
		end
		BK.cluster[char] = nil
		if not root then
			return
		end
		local from = typeof(data.From) == "Vector3" and data.From or root.Position
		local d = typeof(data.Dir) == "Vector3" and data.Dir or flatten(root.CFrame.LookVector, root)
		local len = tonumber(data.Length) or 16
		afterimage(char, FIRE[1], 0.3)
		toonExplosion(from - d * 1.2, 1.2, { NoDebris = true, SmokeLife = 0.9 })
		streaks(from + UP, d, 10, 1.2, 8, len, Color3.new(1, 1, 1), 0.25)
		VFX.PlaySound("BlitzGo", from, 1)
		task.delay(0.08, function()
			if not VFX.Clip(char, "ClusterPalm") then
				VFX.Pose(char, "Blast", 0.35)
			end
			BK.fullBody(char, 0.7)
			toonExplosion(from + d * (len + 2.5), 2.4, { SmokeLife = 1.4 })
			VFX.PlaySound("Explosion", from + d * len, 1)
			VFX.ShakeAt(from + d * len, 2.5, 110, 0.3)
		end)
	end

	function Effects.FullBodyClusterCancel(char)
		local st = BK.cluster[char]
		if st then
			st.dead = true
		end
		BK.cluster[char] = nil
		VFX.ReleasePose(char, 0.2)
	end

	-- HOWITZER IMPACT (ult): up into the sky on a column of blasts, then he
	-- spins into a tornado of explosions and crashes down on the aim point -
	-- one enormous blast, a ring of explosions round the crater
	function Effects.Howitzer(char, data, isLocal, ability)
		local root, hum = charParts(char)
		if not root then
			return
		end
		ability = ability or {}
		local target = aimGround(root, data, ability.Range or 120)
		local d = flatten(target - root.Position, root)
		if isLocal then
			face(root, d)
			VFX.Hooks.Dim(0.35, 1.4)
			launch(root, hum, UP * 120 + d * 20)
		end
		cinematicFor(char, "Howitzer", isLocal, ability.Name or "HOWITZER IMPACT", FIRE[2])
		VFX.Motion(char, "Howitzer")
		VFX.PlaySound("HowitzerSpin", root.Position, 1.2)
		VFX.PlaySound("BlastCharge", root.Position, 0.9)
		BK.palm(handPos(char, true), -UP, 1.6)
		BK.palm(handPos(char, false), -UP, 1.6)
		-- the climb, then the spin: a two-tone fire tornado round him
		local model = outlineModel(FLAME_OUTLINE)
		local function spin(t)
			for k = 0, 2 do
				local a = t * 26 + k * (math.pi * 2 / 3)
				local r = 3.5 + math.min(t, 1) * 4
				local p = root.Position + Vector3.new(math.cos(a) * r, -2 + math.sin(t * 9) * 1.5 + k, math.sin(a) * r)
				local puff = newPart(Vector3.one * 3.4, CFrame.new(p), FIRE[rng:NextInteger(1, 4)], Enum.Material.Neon, Enum.PartType.Ball, model)
				tween(puff, 0.3, { Size = Vector3.one * 0.1 })
			end
		end
		local t0 = os.clock()
		while os.clock() - t0 < 0.95 and root.Parent do
			spin(os.clock() - t0)
			task.wait(0.03)
		end
		if not root.Parent then
			cleanup(model, 0.3)
			return
		end
		-- the dive
		local v = target - root.Position
		local flight = math.clamp(v.Magnitude / 220, 0.25, 0.7)
		if isLocal then
			dash(root, (v.Magnitude > 1 and v.Unit or -UP) * math.max(v.Magnitude / flight, 60), flight)
		end
		t0 = os.clock()
		while os.clock() - t0 < flight and root.Parent do
			spin(1 + os.clock() - t0)
			task.wait(0.03)
		end
		cleanup(model, 0.5)
		if not root.Parent then
			return
		end
		local center = groundPoint(root.Position) + UP * 3
		local R = ability.Radius or 44
		VFX.ImpactFrame(0.12)
		toonExplosion(center, 7.5, { SmokeLife = 5 })
		task.delay(0.08, function()
			toonExplosion(center + UP * 8, 5, { NoDebris = true, SmokeLife = 4 })
		end)
		shockDisc(center, UP, 12, R * 4.2, 0.6, FIRE[2])
		shockDisc(center + UP * 2, UP, 10, R * 3, 0.5, Color3.new(1, 1, 1))
		billboardRing(center + UP * 4, 8, R * 3.4, BLAST_YELLOW, 14, 0.5)
		for i = 1, 8 do
			local a = i / 8 * math.pi * 2
			task.delay(0.1 + i * 0.05, function()
				toonExplosion(center + Vector3.new(math.cos(a) * R * 0.8, 0, math.sin(a) * R * 0.8), 2.8, { NoScorch = true })
			end)
		end
		rocks(center, 3, 40)
		groundMark(center, R * 0.8, Color3.fromRGB(34, 28, 26), 20)
		emberCloud(center + UP * 10, R * 0.8, 3, 120)
		VFX.PlaySound("MegaBoom", center, 1.3)
		if nearCamera(center, R * 3) then
			VFX.Hooks.Flash(Color3.fromRGB(255, 236, 200), 0.5)
		end
		VFX.ShakeAt(center, 6, R * 7, 1.1)
	end

end

---------------------------------------------------------------------------
-- ONE FOR ALL
---------------------------------------------------------------------------

do -- ALL MIGHT's grapples, counter and weather (one table: the local limit)
	local AM = {}

	-- a golden ghost of him in his prime, flaring over his body
	function AM.ghost(char, life)
		local model = outlineModel(Color3.fromRGB(120, 70, 10))
		for _, part in char:GetChildren() do
			if part:IsA("BasePart") and part.Name ~= "HumanoidRootPart" and part.Transparency < 1 then
				local g = newPart(part.Size * 1.35, part.CFrame, GOLD, Enum.Material.Neon, nil, model)
				g.Transparency = 0.35
				tween(g, life, { Size = part.Size * 1.8, Transparency = 1 })
			end
		end
		cleanup(model, life + 0.1)
	end

	-- HERO'S COUNTER: the stance - planted, arms crossed, waiting for it
	function Effects.HeroCounter(char, _data, isLocal, ability)
		local root = charParts(char)
		if not root then
			return
		end
		local window = (ability and ability.Window) or 0.9
		VFX.Pose(char, "CounterStance", window)
		billboardRing(root.Position, 2, 10, GOLD, 4, 0.3)
		VFX.PlaySound("GuardUp", root.Position, 1)
		if isLocal then
			VFX.Hooks.Dim(0.2, window)
		end
		local t0 = os.clock()
		while os.clock() - t0 < window and root.Parent and char:GetAttribute("Countering") ~= false do
			if rng:NextNumber() < 0.4 then
				sparks(root.Position + Vector3.new(rand(-1.5, 1.5), rand(-1, 2), rand(-1.5, 1.5)), 0.3, Color3.new(1, 1, 1), GOLD, 2)
			end
			task.wait(0.06)
		end
	end

	-- ...and it caught something: the Symbol of Peace, for one punch
	function Effects.HeroCounterHit(char, data)
		local root = charParts(char)
		if not root then
			return
		end
		local target = typeof(data.Target) == "Instance" and data.Target or nil
		local tr = target and target:FindFirstChild("HumanoidRootPart")
		local d = flatten(tr and (tr.Position - root.Position) or root.CFrame.LookVector, root)
		local me = Players.LocalPlayer
		if me and me.Character == char then
			face(root, d)
			VFX.ImpactFrame(0.1)
		end
		AM.ghost(char, 0.5)
		VFX.Motion(char, "DetroitSmash")
		VFX.PlaySound("Parry", root.Position, 1)
		sparks(root.Position + d * 2, 1, Color3.new(1, 1, 1), GOLD, 20)
		task.wait(0.14)
		if not root.Parent then
			return
		end
		local origin = root.Position + d * 3 + UP
		windBlast(origin, d, 1.3)
		for i = 1, 4 do
			task.delay(i * 0.03, function()
				shockDisc(origin, d, 7, 32, 0.45, WIND, 60)
			end)
		end
		billboardRing(origin, 3, 26, GOLD, 8, 0.3)
		VFX.PlaySound("MightImpact", origin, 1)
		VFX.ShakeAt(origin, 3, 150, 0.5)
		if nearCamera(origin, 60) then
			VFX.Hooks.Flash(Color3.new(1, 1, 1), 0.2)
		end
	end

	-- BACKDROP DRIVER, part 1: he lunges to wrap them up
	function Effects.BackdropDriver(char, data, isLocal)
		local root = charParts(char)
		if not root then
			return
		end
		local d = flatten(data.Dir, root)
		if isLocal then
			face(root, d)
			dash(root, d * 45, 0.12)
		end
		VFX.Pose(char, "BearHug", 0.3)
		VFX.PlaySound("Swing", root.Position, 1)
	end

	-- BACKDROP DRIVER, part 2 (the server says he caught them): the arch, the
	-- leap back, and the street behind him caves in
	function Effects.BackdropCatch(char, data, _isLocal, ability)
		local root, hum = charParts(char)
		if not root then
			return
		end
		ability = ability or Config.FindAbilityById("BackdropDriver") or {}
		local target = typeof(data.Target) == "Instance" and data.Target or nil
		if not target then
			VFX.Pose(char, "Stagger", 0.3) -- (grabbed thin air)
			return
		end
		local d = typeof(data.Dir) == "Vector3" and data.Dir or flatten(root.CFrame.LookVector, root)
		local me = Players.LocalPlayer
		local over = ability.OverTime or 0.55
		VFX.Motion(char, "Suplex")
		VFX.PlaySound("Leap", root.Position, 1)
		if me and me.Character == char and hum then
			launch(root, hum, -d * 10 + UP * 22)
		end
		local stopTrail = addTrail(root, GOLD, 0.3, 2.4)
		task.wait(over)
		stopTrail(0)
		if not root.Parent then
			return
		end
		local impact = groundPoint(root.Position - d * 3.5)
		local R = ability.Crater or 16
		VFX.ImpactFrame(0.08)
		shockDisc(impact + UP * 0.4, UP, 6, R * 4, 0.5, WIND)
		shockDisc(impact + UP * 0.6, UP, 4, R * 2.6, 0.4, GOLD)
		billboardRing(impact + UP, 3, R * 2.5, Color3.new(1, 1, 1), 8, 0.3)
		dustPuffs(impact, 2.4, 12, Color3.fromRGB(206, 196, 186), 1.4, true)
		rocks(impact, 2.4, 22)
		groundMark(impact, R * 0.7, Color3.fromRGB(52, 46, 44), 14)
		VFX.PlaySound("MightImpact", impact, 1)
		VFX.PlaySound("Downslam", impact, 1)
		VFX.ShakeAt(impact, 4, 160, 0.6)
	end

	-- WEATHER CHANGER (ult V): the uppercut at the sky, the updraft that
	-- sucks everyone up, the clouds torn open overhead, then the rain of it
	function Effects.WeatherChanger(char, _data, isLocal, ability)
		local root = charParts(char)
		if not root then
			return
		end
		ability = ability or {}
		local R = ability.Radius or 45
		local hang = ability.HangTime or 1.1
		if isLocal then
			VFX.Hooks.Dim(0.3, 1.2)
		end
		VFX.Motion(char, "SkyUppercut")
		VFX.PlaySound("DetroitCharge", root.Position, 1.2)
		chargeFist(char, root, 0.45, 1.3)
		if not root.Parent then
			return
		end
		local g = groundPoint(root.Position)
		AM.ghost(char, 0.4)
		VFX.PlaySound("MightImpact", root.Position, 1.2)
		VFX.PlaySound("Wind", root.Position, 1.2)
		if nearCamera(root.Position, 90) then
			VFX.Hooks.Flash(Color3.new(1, 1, 1), 0.25)
		end
		-- the updraft: a column of wind roaring up off the street
		for i = 1, 6 do
			task.delay(i * 0.05, function()
				shockDisc(g + UP * (i * 6), UP, R * 0.6, R * 1.6, 0.5, WIND, 40)
			end)
		end
		for _ = 1, 3 do
			streaks(g + UP * 2, UP, 24, R * 0.5, 16, 140, WIND, 0.6)
		end
		dustPuffs(g, 2.6, 14, Color3.fromRGB(206, 196, 186), 1.5, true)
		rocks(g, 2.6, 24)
		-- the clouds split open overhead
		local sky = g + UP * 110
		for i = 1, 14 do
			local a = i / 14 * math.pi * 2
			local out = Vector3.new(math.cos(a), 0, math.sin(a))
			local puff = newPart(Vector3.one * 26, CFrame.new(sky + out * 10), Color3.fromRGB(236, 238, 244), Enum.Material.SmoothPlastic, Enum.PartType.Ball)
			puff.Transparency = 0.25
			tween(puff, 1.2, { CFrame = CFrame.new(sky + out * (R * 2.2)), Size = Vector3.one * 44 }, Enum.EasingStyle.Quad)
			tween(puff, 1.6, { Transparency = 1 }, nil, nil, hang + 0.8)
			cleanup(puff, hang + 2.6)
		end
		billboardRing(sky, 10, R * 4, Color3.new(1, 1, 1), 10, 0.8)
		VFX.ShakeAt(g, 4, 200, 0.8)
		-- ...then it all comes back down: rain, and the crash
		task.delay(hang, function()
			local t0 = os.clock()
			while os.clock() - t0 < 1.6 do
				for _ = 1, 6 do
					local from = g + Vector3.new(rand(-R, R), rand(60, 90), rand(-R, R))
					local drop = newPart(Vector3.new(0.15, 4, 0.15), CFrame.new(from), Color3.fromRGB(190, 210, 240), Enum.Material.Glass)
					drop.Transparency = 0.4
					tween(drop, 0.5, { CFrame = CFrame.new(from - UP * 70) }, Enum.EasingStyle.Linear)
					cleanup(drop, 0.55)
				end
				task.wait(0.05)
			end
		end)
		task.delay(hang + 0.35, function()
			shockDisc(g + UP * 0.5, UP, 6, R * 3, 0.5, WIND)
			VFX.PlaySound("Downslam", g, 1.2)
			VFX.ShakeAt(g, 3.5, 200, 0.6)
		end)
	end
end

function Effects.PlusUltraRush(char, data, isLocal, ability)
	local root = charParts(char)
	if not root then
		return
	end
	local d = flatten(data.Dir, root)
	local right = d:Cross(UP)
	if isLocal then
		face(root, d)
		dash(root, d * 80, 0.15)
	end
	task.wait(0.2)
	local hits = (ability and ability.Hits) or 12
	for k = 1, hits do
		if not root.Parent then
			return
		end
		VFX.Pose(char, k % 2 == 0 and "PunchL" or "PunchR", 0.08)
		local p = root.Position + d * 4.5 + right * rand(-2.2, 2.2) + UP * rand(-1, 2)
		local fist = newPart(Vector3.one * 1.5, CFrame.new(p), k % 3 == 0 and GOLD or Color3.new(1, 1, 1), Enum.Material.Neon, Enum.PartType.Ball)
		tween(fist, 0.06, { Size = Vector3.one * 4.5 })
		tween(fist, 0.1, { Size = Vector3.one * 5, Transparency = 1 }, nil, nil, 0.06)
		cleanup(fist, 0.2)
		shockDisc(p, d, 2, 9, 0.16, WIND, 10)
		streaks(p, d, 3, 1, 4, 10, WIND, 0.12)
		VFX.ShakeAt(p, 0.6, 50, 0.08)
		task.wait(0.1)
	end
	task.wait(0.05)
	if not root.Parent then
		return
	end
	-- final PLUS ULTRA punch
	VFX.Pose(char, "PunchR", 0.5)
	local origin = root.Position + d * 4 + UP
	if nearCamera(origin, 90) then
		VFX.Hooks.Flash(Color3.new(1, 1, 1), 0.25)
	end
	for i = 1, 6 do
		task.delay(i * 0.03, function()
			shockDisc(origin, d, 8, 34, 0.45, WIND, 60)
		end)
	end
	shockDisc(origin, d, 4, 26, 0.25, GOLD)
	windBlast(origin, d, 1.8)
	VFX.PlaySound("MightSmash", origin, 1.2)
	VFX.ShakeAt(origin, 3, 160, 0.5)
end

function Effects.TexasSmashMax(char, data, isLocal)
	local root = charParts(char)
	if not root then
		return
	end
	local d = flatten(data.Dir, root)
	if isLocal then
		face(root, d)
		VFX.Hooks.Dim(0.5, 0.6)
	end
	VFX.Pose(char, "Kneel", 0.35)
	task.spawn(function()
		local t0 = os.clock()
		while os.clock() - t0 < 0.35 and root.Parent do
			local hand = handPos(char, true)
			bolt(hand, 2, GOLD)
			shockDisc(hand, d, 9, 1, 0.12, WIND)
			task.wait(0.05)
		end
	end)
	chargeFist(char, root, 0.35, 1.6)
	if not root.Parent then
		return
	end
	VFX.Pose(char, "PunchR", 0.6)
	local origin = root.Position + d * 4 + UP
	if nearCamera(origin, 140) then
		VFX.ImpactFrame(0.1)
		VFX.Hooks.Flash(Color3.new(1, 1, 1), 0.35)
	end
	windBlast(origin, d, 2.6)
	for i = 1, 10 do
		task.delay(i * 0.03, function()
			shockDisc(origin, d, 16, 62, 0.6, WIND, 135)
		end)
	end
	shockDisc(origin, d, 6, 40, 0.28, GOLD)
	streaks(origin, d, 70, 15, 22, 230, WIND, 0.5)
	-- corkscrew of wind around the blast
	for i = 1, 40 do
		task.delay(i * 0.012, function()
			local a = i * 0.55
			local basis = CFrame.lookAt(origin, origin + d)
			local p = origin + d * (i * 3) + basis.RightVector * math.cos(a) * 9 + basis.UpVector * math.sin(a) * 9
			local seg = newPart(Vector3.new(0.45, 0.45, 8), CFrame.lookAt(p, p + d), WIND, Enum.Material.Neon)
			tween(seg, 0.4, { Transparency = 1, CFrame = CFrame.lookAt(p + d * 20, p + d * 21) })
			cleanup(seg, 0.45)
		end)
	end
	for s = 12, 130, 12 do
		task.delay(s / 260, function()
			local p = groundPoint(origin + d * s + d:Cross(UP) * rand(-8, 8))
			dustPuffs(p, 2 + s / 60, 4, Color3.fromRGB(206, 196, 186), 1.4, true)
			if s % 36 == 0 then
				rocks(p, 1.6, 6)
			end
		end)
	end
	VFX.PlaySound("MightSmash", origin, 1.2)
	VFX.ShakeAt(origin, 4.5, 240, 0.8)
end

---------------------------------------------------------------------------
-- HALF-COLD HALF-HOT: Phosphor
---------------------------------------------------------------------------

function Effects.Phosphor(char, data, isLocal)
	local root = charParts(char)
	if not root then
		return
	end
	local dir = aimDir(data, root)
	if isLocal then
		face(root, dir)
		VFX.Hooks.Dim(0.4, 0.8)
	end
	VFX.Pose(char, "PunchL", 0.8)
	local glow = newPart(Vector3.one * 0.4, CFrame.new(handPos(char, false)), PAL.PHOSPHOR_CORE, Enum.Material.Neon, Enum.PartType.Ball)
	tween(glow, 0.3, { Size = Vector3.one * 3 })
	cleanup(glow, 0.32)
	local t0 = os.clock()
	while os.clock() - t0 < 0.3 and root.Parent do
		local hand = handPos(char, false)
		glow.CFrame = CFrame.new(hand)
		shockDisc(hand, dir, 7, 1, 0.12, PAL.PHOSPHOR_GLOW)
		sparks(hand, 0.4, PAL.PHOSPHOR_CORE, PAL.PHOSPHOR_GLOW, 5)
		task.wait(0.05)
	end
	if not root.Parent then
		return
	end
	local from = handPos(char, false) + dir
	local to = from + dir * 110
	beam(from, to, 2.2, PAL.PHOSPHOR_CORE, PAL.PHOSPHOR_GLOW, 0.5)
	beam(from, to, 3.4, FIRE[2], FIRE[4], 0.4)
	for i = 1, 9 do
		local p = from + dir * (i * 12)
		task.delay(i * 0.012, function()
			Flame.burst(p, rand(4, 6), 8)
		end)
	end
	for i = 1, 6 do
		task.delay(i * 0.02, function()
			shockDisc(from + dir * (i * 16), dir, 9, 3, 0.25, PAL.PHOSPHOR_GLOW)
		end)
	end
	local hitPos = firstHit(from, dir, 110)
	if hitPos then
		toonExplosion(hitPos, 1.8)
	end
	if nearCamera(from, 60) then
		VFX.Hooks.Flash(Color3.fromRGB(235, 230, 255), 0.25)
	end
	VFX.PlaySound("Fire", from, 1.2)
	VFX.ShakeAt(from, 2.2, 120, 0.4)
end

function Effects.GlacialField(char, data, isLocal, ability)
	local root = charParts(char)
	if not root then
		return
	end
	if isLocal then
		VFX.Hooks.Dim(0.35, 0.7)
	end
	VFX.Pose(char, "Ground", 0.8)
	task.wait(0.2)
	if not root.Parent then
		return
	end
	local g = groundPoint(root.Position)
	-- (round 81) ice floods the ground in a huge circle (the sheet: solid Ice,
	-- with ragged frost crust past its rim - the see-through Glass floor that
	-- fought it for the same plane is gone), clusters of crystals erupt
	-- across it in a wave out from him, cold mist rolls out over it and the
	-- air goes cold
	local model = spikeLayout("GlacialField", data, root, flatten(data.Dir, root))
	IceKit.particles(g + UP * 0.5, "puff", 16, 2.4)
	for r = 10, 40, 10 do
		task.delay(r / 90, function()
			local a0 = rand(0, math.pi * 2)
			for i = 1, 3 do
				local a = a0 + i / 3 * math.pi * 2
				frostMist(g + Vector3.new(math.cos(a) * r, 1, math.sin(a) * r), 1.6, 3)
			end
		end)
	end
	shockDisc(g + UP * 0.5, UP, 6, 86, 0.5, ICE_TIP)
	shockDisc(g + UP * 1.5, UP, 4, 60, 0.7, IceKit.PAL.MIST2)
	sparks(g + UP * 2, 2.5, ICE_TIP, Color3.fromRGB(120, 200, 255), 70)
	IceKit.light(g + UP * 8, 50, 1.6, (ability and ability.IceDuration) or 5)
	IceKit.snow(CFrame.new(g + UP * 30), Vector3.new(70, 2, 70), (ability and ability.IceDuration) or 5, 40, 1.4)
	if nearCamera(g, 80) then
		IceKit.coldTint(0.9, 0.6, 2.2)
	end
	VFX.PlaySound("Ice", g, 1.2)
	VFX.PlaySound("IceRumble", g, 1)
	VFX.ShakeAt(g, 2.8, 160, 0.5)
	task.wait((ability and ability.IceDuration) or 5)
	shatter(model, 120, { from = g })
end

function Effects.HeatwaveMax(char, data, isLocal, ability)
	cinematicFor(char, "HeatwaveMax", isLocal, ability and ability.Name or "FLASHFREEZE HEATWAVE", Color3.fromRGB(255, 150, 90))
	heatwaveCore(char, data, isLocal, {
		Layout = "HeatwaveMax", IceWait = 0.45, StreamTime = 0.45, StreamLength = 42,
		BlastOffset = 30, BlastScale = 5.2, Scale = 1.6, DimTime = 1.4, SteamScale = 2.3,
	})
end

---------------------------------------------------------------------------
-- ENGINE
---------------------------------------------------------------------------

do -- ENGINE: its helpers stay local to this block (Luau allows 200 locals per scope)
	---------------------------------------------------------------------------
	-- (round 85) RECIPRO TURBO, rebuilt on the engine kit (VFX.EngineKit) as
	-- VFX.IidaTurbo (TT here). THE LONG TUBES: the awakening tears his old
	-- mufflers out and three long ringed grey tubes a calf grow in, heating
	-- magenta -> orange -> white along their length; they stay on through the
	-- ult (every screen draws them for every Iida in it: the tips pulsing
	-- magenta and white, his exhaust coming out of their mouths), with the
	-- ult's look - two-tone trails off his calves, gold ghosts of him and a
	-- vapor ring every 1.2 s while he's flat out, heat haze standing - and at
	-- the end they glow red, cool grey and slide back into his calves (his
	-- engines stall). Then the moves: TURBO KICK (a bar of light: he's never
	-- seen going), TURBO RUSH (a bar of light a leg, crisscrossing round
	-- them) and RECIPRO: MAXIMUM BURST (its cutscene ends on the hit). His
	-- clips are anim/moves_iida_t.py.
	---------------------------------------------------------------------------
	local EK = VFX.EngineKit
	local TP = EK.PAL
	local TT = {
		state = setmetatable({}, { __mode = "k" }), -- [char] = his tubes and the ult's look
		orig = setmetatable({}, { __mode = "k" }), -- [a kit mouth] = where it was before the tubes moved it
		hidden = setmetatable({}, { __mode = "k" }), -- [char] = until when he's blinked out of sight
		maxRuns = setmetatable({}, { __mode = "k" }), -- [char] = his MAXIMUM BURST's plan
		-- the tubes, in Look's studs on a stock R6 leg (scaled by the leg's
		-- width): side by side across the back of the calf (X: out from its
		-- middle, times the side's sign - the outer first; Y: their height;
		-- Z: where they leave the plate), Length full grown (Max stretched
		-- out for MAXIMUM BURST), Width, ring joints at a third and two
		-- thirds (Ring, RingLength), pointing back like the kit's mouths
		-- (Splay degrees out - fanned 4 more for the outer, 4 less for the
		-- inner - and Droop down, so the jets out of them read from his own
		-- camera). (round 85 review) Long and thick enough to change his
		-- silhouette from 40 studs; Tip: the neon mouth's length
		TUBE = { X = { 0.33, 0, -0.33 }, Y = -0.3, Z = 0.74, Length = 1.8, Max = 2.6, Width = 0.3, Ring = 0.4, RingLength = 0.08, Tip = 0.14, Splay = 8, Droop = 6 },
		METAL = Color3.fromRGB(125, 130, 140),
		RING = Color3.fromRGB(70, 72, 80),
		BORE = Color3.fromRGB(26, 26, 32),
		-- heated along their length (research 2.2): magenta at the base,
		-- orange in the middle, white-hot at the mouth
		HEAT = { Color3.fromRGB(240, 50, 180), Color3.fromRGB(255, 170, 50), Color3.fromRGB(255, 250, 240) },
		PINK = Color3.fromRGB(255, 90, 200),
		-- TURBO RUSH's bars, leg by leg: cyan, green-cyan, blue, violet, white
		BARS = { Color3.fromRGB(110, 220, 255), Color3.fromRGB(120, 255, 200), Color3.fromRGB(80, 140, 255), Color3.fromRGB(200, 70, 255), Color3.fromRGB(255, 255, 255) },
		-- the in-ult look: how often it updates and scans for bodies, how
		-- fast is "flat out" (studs/s; his ult WalkSpeed is 38), a gold ghost
		-- every Ghost s then, a vapor ring every Ring s of it; Grace: how
		-- long the awakening's tubes wait for the server's UltActive
		DRIVE = { Every = 0.1, Scan = 0.5, Fast = 30, Ghost = 0.15, Ring = 1.2, Grace = 2.5, Cull = 180 },
		STUBS = { Pipe = true, PipeInner = true, PipeBore = true },
	}
	VFX.IidaTurbo = TT
	-- the heat haze off the tubes standing, an ember now and then, and the
	-- charcoal smoke pouring off his calves when they blow (MAXIMUM BURST)
	TT.HAZE = {
		tex = EK.TEX.smoke, color = { Color3.fromRGB(236, 232, 244), Color3.fromRGB(214, 206, 230) }, size = { { 0, 0.3 }, { 1, 1.3 } },
		transp = { { 0, 1 }, { 0.2, 0.86 }, { 1, 1 } }, life = { 0.8, 1.2 }, speed = { 1, 2 }, spread = 25, dir = "Top", accel = Vector3.new(0, 2.5, 0),
		influence = 0.6, spin = { -30, 30 },
	}
	TT.EMBER = {
		tex = EK.TEX.spark, color = { TP.TURBO_WHITE, TP.TURBO_MAGENTA }, size = { { 0, 0.18 }, { 1, 0 } }, transp = 0, life = { 0.4, 0.7 },
		speed = { 2, 4 }, spread = 40, dir = "Top", accel = Vector3.new(0, 3, 0), light = 1,
	}
	TT.SMOKE = {
		tex = EK.TEX.smoke, color = { TP.SMOKE, Color3.fromRGB(96, 90, 90) }, size = { { 0, 0.6 }, { 1, 2.6 } }, transp = { { 0, 0.15 }, { 0.7, 0.5 }, { 1, 1 } },
		life = { 0.9, 1.4 }, speed = { 2, 4 }, spread = 40, accel = Vector3.new(0, 3, 0), drag = 2, influence = 1, spin = { -40, 40 },
	}
	-- (round 85) the glow over each calf's tube mouths (its colour follows
	-- their pulse); a sprite locked to the leg
	TT.GLOW = {
		tex = EK.TEX.glow, color = { TP.TURBO_MAGENTA }, size = { { 0, 1.5 }, { 1, 1.5 } }, transp = { { 0, 0.62 }, { 0.5, 0.52 }, { 1, 1 } },
		life = { 0.2, 0.24 }, speed = { 0, 0 }, light = 1, bright = 1.4, locked = true, rot = { 0, 0 }, z = 0.4,
	}

	-- a vector turned deg degrees round the vertical
	function TT.rotY(v, deg)
		return CFrame.Angles(0, math.rad(deg), 0):VectorToWorldSpace(v)
	end
	function TT.flat(v)
		local f = Vector3.new(v.X, 0, v.Z)
		return f.Magnitude > 0.01 and f.Unit or Vector3.new(0, 0, -1)
	end
	-- every body that can be hit (players, the training dummies), but his
	function TT.foes(char)
		local out = {}
		for _, plr in Players:GetPlayers() do
			if plr.Character and plr.Character ~= char then
				table.insert(out, plr.Character)
			end
		end
		local dummies = workspace:FindFirstChild("Dummies")
		for _, m in dummies and dummies:GetChildren() or {} do
			if m ~= char then
				table.insert(out, m)
			end
		end
		return out
	end
	-- every body the look is drawn for: players and the dummies
	function TT.bodies()
		local out = TT.foes(nil)
		return out
	end

	-- his clip (R6), its "Hit" lead seconds from now (held on its Hold key
	-- till then) or held holdFor; an R15 body plays the motion
	function TT.clip(char, clipName, motionName, opts)
		opts = opts or {}
		local c = Anim.MoveClips ~= false and VFX.GetClip(clipName)
		if c then
			local hold = opts.holdFor or (opts.lead and math.max(opts.lead - (c.hit or 0), 0)) or 0
			if VFX.Clip(char, clipName, { holdFor = hold, recover = opts.recover or 0.2 }) then
				return c
			end
		end
		VFX.Motion(char, motionName)
		return nil
	end

	---------------------------------------------------------------------------
	-- THE LONG TUBES
	---------------------------------------------------------------------------
	-- one piece of a tube (key: s1-s3 the thirds, r1 / r2 the ring joints,
	-- tip the neon mouth, bore its dark hole): made welded to the leg where it
	-- belongs the first time, and after that only its size and weld change
	-- (setting a welded part's CFrame would drag his whole body there)
	function TT.put(st, tube, key, cf, size, name, color, material)
		local p = tube.parts[key]
		if not p then
			p = newPart(size, tube.leg.CFrame * cf, color, material, Enum.PartType.Cylinder, st.folder)
			p.Name = name
			EK.weld(p, tube.leg, cf)
			tube.parts[key] = p
			tube.welds[key] = p:FindFirstChildOfClass("Weld")
		else
			p.Size = size
			local wd = tube.welds[key]
			if wd then
				wd.C0 = cf
			end
		end
		return p
	end
	-- every tube at st.len (the share of TUBE.Length grown, in studs before
	-- the leg's scale), and his exhaust's mouths moved to their ends
	function TT.place(st)
		local T = TT.TUBE
		local low = EK.lowEnd()
		for _, tube in st.tubes do
			local w = tube.w
			local L = math.max(st.len, 0.02) * w
			local W = T.Width * w
			local function piece(a, b)
				local c = tube.base + tube.dir * (a + b) / 2
				return CFrame.lookAt(c, c + tube.dir) * CFrame.Angles(0, math.pi / 2, 0), math.max(b - a, 0.01)
			end
			for j = 1, 3 do
				local cf, n = piece(L * (j - 1) / 3, L * j / 3)
				TT.put(st, tube, "s" .. j, cf, Vector3.new(n, W, W), "TurboTube", TT.METAL, Enum.Material.Metal)
			end
			if not low then
				for j = 1, 2 do
					local m = L * j / 3
					local cf = piece(m - T.RingLength * w / 2, m + T.RingLength * w / 2)
					TT.put(st, tube, "r" .. j, cf, Vector3.new(T.RingLength * w, T.Ring * w, T.Ring * w), "TurboTubeRing", TT.RING, Enum.Material.Metal)
				end
			end
			local cft = piece(L - T.Tip * w, L + 0.01 * w)
			TT.put(st, tube, "tip", cft, Vector3.new(T.Tip * w, T.Ring * w * 0.95, T.Ring * w * 0.95), "TurboTubeTip", TP.TURBO_MAGENTA, Enum.Material.Neon)
			local cfb = piece(L + 0.005 * w, L + 0.025 * w)
			TT.put(st, tube, "bore", cfb, Vector3.new(0.02 * w, W * 0.62, W * 0.62), "TurboTubeBore", TT.BORE, Enum.Material.SmoothPlastic)
		end
		-- (the glow sits over each calf's middle mouth)
		for _, g in st.glows or {} do
			local mid = st.bySide[g.side] and st.bySide[g.side][2]
			if mid then
				g.att.CFrame = CFrame.new(mid.base + mid.dir * (math.max(st.len, 0.02) * mid.w + 0.05))
			end
		end
		TT.remouth(st)
	end
	-- the heat along them (st.heat 0-1): "turbo" magenta -> orange -> white
	-- from base to mouth, "white" white-hot, "red" red-hot (cooling)
	function TT.paint(st)
		local k = math.clamp(st.heat, 0, 1)
		local hot = (st.mode == "red" and { TP.HOT_PIPE, TP.HOT_PIPE, Color3.fromRGB(255, 165, 125) })
			or (st.mode == "white" and { TT.HEAT[2], TP.TURBO_WHITE, Color3.new(1, 1, 1) })
			or TT.HEAT
		for _, tube in st.tubes do
			for j = 1, 3 do
				local p = tube.parts["s" .. j]
				if p then
					p.Color = TT.METAL:Lerp(hot[j], k)
					p.Material = k > 0.12 and Enum.Material.Neon or Enum.Material.Metal
				end
			end
			-- (red-hot: the mouths too; otherwise they keep their pulse)
			if st.mode == "red" and tube.parts.tip then
				tube.parts.tip.Color = TT.METAL:Lerp(TP.HOT_PIPE, k)
			end
		end
		for _, pl in st.lights do
			pl.Brightness = 3 * k
			pl.Color = st.mode == "red" and TP.HOT_PIPE or TP.TURBO_VIOLET
		end
	end
	-- his exhaust out of the tubes' mouths: the kit's 12 mouths (2 columns of
	-- 3 a calf) moved to the ends of the 3 tubes, two to a tube (one a touch
	-- above the other in its bore). Every kit effect - the always-on
	-- exhaust, a move's jets, the hot pipes - comes out of them then. Done
	-- again whenever the kit makes its mouths anew (EK.hold, a new driver)
	function TT.remouth(st)
		if st.unmouthed then
			return
		end
		local all = EK.mouths(st.char)
		for side, tubes in st.bySide do
			for _, m in all[side] or {} do
				if not TT.orig[m] then
					TT.orig[m] = { at = m.at, cf = m.cf, dirL = m.dirL }
				end
				local i = m.col == 1 and (m.row <= 2 and 1 or 2) or (m.row == 1 and 2 or 3)
				local tube = tubes[i]
				if tube then
					local up = ((m.col == 1 and m.row ~= 2) or (m.col == 2 and m.row == 2)) and 1 or -1
					local at = tube.base + tube.dir * (math.max(st.len, 0.02) * tube.w + 0.02) + Vector3.new(0, 0.035 * up * tube.w, 0)
					m.at, m.dirL = at, tube.dir
					m.cf = CFrame.lookAt(at, at + tube.dir)
					m.att.CFrame = m.cf
				end
			end
		end
	end
	-- ...and back where the kit had them
	function TT.unmouth(st)
		st.unmouthed = true
		for _, L in EK.legs(st.char) do
			for _, m in EK.mouthCache[L.leg] or {} do
				local o = TT.orig[m]
				if o then
					m.at, m.cf, m.dirL = o.at, o.cf, o.dirL
					pcall(function()
						m.att.CFrame = o.cf
					end)
					TT.orig[m] = nil
				end
			end
		end
	end
	-- the server's old stubs on his calves hidden (the tubes replace them)
	-- or shown again
	function TT.stubs(st, hide)
		local list = st.stubList
		-- (looked for again when his gear's rebuilt - the server does it as the ult starts)
		if #list == 0 or not list[1]:IsDescendantOf(st.char) then
			table.clear(list)
			local gear = st.char:FindFirstChild("QuirkGear")
			for _, d in gear and gear:GetDescendants() or {} do
				if d:IsA("BasePart") and TT.STUBS[d.Name] then
					table.insert(list, d)
				end
			end
		end
		for _, p in list do
			p.LocalTransparencyModifier = hide and 1 or 0
		end
		st.stubsHidden = hide
	end

	-- their length and heat ease (one RenderStepped while any does)
	function TT.ease(st, key, to, time)
		st.goals[key] = { from = st[key], to = to, t0 = os.clock(), time = math.max(time or 0, 1e-3) }
		TT.wake()
	end
	function TT.step(st)
		local now = os.clock()
		local len, heat = false, false
		for key, g in st.goals do
			local a = math.clamp((now - g.t0) / g.time, 0, 1)
			st[key] = g.from + (g.to - g.from) * (1 - (1 - a) * (1 - a))
			if a >= 1 then
				st.goals[key] = nil
			end
			if key == "len" then
				len = true
			else
				heat = true
			end
		end
		if len then
			TT.place(st)
		end
		if heat then
			TT.paint(st)
		end
	end
	function TT.wake()
		if TT.conn then
			return
		end
		TT.conn = RunService.RenderStepped:Connect(function()
			local busy = false
			for _, st in TT.state do
				if next(st.goals) then
					busy = true
					if not pcall(TT.step, st) then
						st.goals = {}
					end
				end
			end
			if not busy and TT.conn then
				TT.conn:Disconnect()
				TT.conn = nil
			end
		end)
	end

	-- his tubes on (grow: from nothing, the awakening grows them; else full
	-- length at once - he was already in the ult when this machine saw him)
	function TT.on(char, grow)
		if TT.state[char] then
			return TT.state[char]
		end
		local legs = EK.legs(char)
		if not EK.alive(char) or #legs == 0 then
			return nil
		end
		local folder = Instance.new("Folder")
		folder.Name = "TurboTubes"
		folder.Parent = char
		local st = {
			char = char, folder = folder, tubes = {}, bySide = {}, len = grow and 0.02 or TT.TUBE.Length, heat = 0, mode = "turbo",
			goals = {}, since = os.clock(), stubList = {}, lights = {}, haze = {}, glows = {}, legFx = {}, sprint = 0, ghostAt = 0, tickAt = os.clock(),
		}
		TT.state[char] = st
		local T = TT.TUBE
		local low = EK.lowEnd()
		for _, L in legs do
			st.bySide[L.side] = {}
			local w = math.min(L.leg.Size.X, L.leg.Size.Z)
			for i, x in T.X do
				local sp, dr = math.rad(T.Splay + (2 - i) * 4), math.rad(T.Droop)
				local tube = {
					leg = L.leg, w = w, i = i, parts = {}, welds = {},
					base = EK.legPoint(L.leg, L.isR15, x * L.sign, T.Y, T.Z),
					dir = Vector3.new(math.sin(sp) * L.sign * math.cos(dr), -math.sin(dr), math.cos(sp) * math.cos(dr)),
				}
				table.insert(st.tubes, tube)
				st.bySide[L.side][i] = tube
			end
		end
		TT.place(st)
		for _, L in legs do
			local mid = st.bySide[L.side][2]
			-- a violet rim light off each calf's tubes as they heat (none on a
			-- low-end machine)
			if not low then
				local pl = Instance.new("PointLight")
				pl.Color = TP.TURBO_VIOLET
				pl.Range = 6
				pl.Brightness = 0
				pl.Parent = mid.parts.s2
				table.insert(st.lights, pl)
			end
			-- the heat haze and embers off them, standing
			local a = Instance.new("Attachment")
			a.Name = "TurboHaze"
			a.CFrame = CFrame.new(mid.base + mid.dir * T.Length * mid.w * 0.6)
			a.Parent = L.leg
			table.insert(st.haze, { att = a, smoke = EK.emitter(a, TT.HAZE), ember = EK.emitter(a, TT.EMBER) })
			-- (round 85) a soft glow over the calf's mouths, pulsing with them:
			-- what still reads of the tubes from 40-60 studs (a sprite locked to
			-- the leg, so it faces every camera)
			local ga = Instance.new("Attachment")
			ga.Name = "TurboTipGlow"
			ga.CFrame = CFrame.new(mid.base + mid.dir * (math.max(st.len, 0.02) * mid.w + 0.05))
			ga.Parent = L.leg
			local glow = EK.emitter(ga, TT.GLOW)
			glow.Rate = low and 6 or 12
			table.insert(st.glows, { side = L.side, att = ga, pe = glow, rate = glow.Rate })
		end
		TT.paint(st)
		TT.stubs(st, true)
		-- (round 85 review) dead, or someone else: gone that moment, not at the
		-- next update (like the kit's exhaust)
		st.conns = {}
		local hum = char:FindFirstChildOfClass("Humanoid")
		if hum then
			table.insert(st.conns, hum.Died:Connect(function()
				TT.drop(char, true)
			end))
		end
		table.insert(st.conns, char:GetAttributeChangedSignal("Quirk"):Connect(function()
			if char:GetAttribute("Quirk") ~= "Engine" then
				TT.drop(char, true)
			end
		end))
		return st
	end
	-- off at once: nothing of it left. hard (dead, gone, someone else): its
	-- puffs and smoke still on his legs go too
	function TT.drop(char, hard)
		local st = TT.state[char]
		if not st then
			return
		end
		TT.state[char] = nil
		for _, c in st.conns or {} do
			pcall(c.Disconnect, c)
		end
		if hard then
			for _, a in st.legFx do
				pcall(a.Destroy, a)
			end
		end
		st.goals = {}
		if st.trails then
			pcall(st.trails)
		end
		for _, h in st.haze do
			pcall(h.att.Destroy, h.att)
		end
		for _, g in st.glows do
			pcall(g.att.Destroy, g.att)
		end
		pcall(TT.unmouth, st)
		pcall(TT.stubs, st, false)
		pcall(st.folder.Destroy, st.folder)
	end
	-- the ult's over: red-hot, cooling grey, then they slide back into his
	-- calves and his engines stall
	function TT.off(char)
		local st = TT.state[char]
		if not st or st.ending then
			return
		end
		st.ending = true
		if st.trails then
			st.trails()
			st.trails = nil
		end
		for _, h in st.haze do
			h.smoke.Rate, h.ember.Rate = 0, 0
		end
		-- (the mouths' glow turns red-hot with them, then goes)
		for _, g in st.glows do
			g.pe.Color = ColorSequence.new(TP.HOT_PIPE)
			task.delay(0.6, function()
				g.pe.Rate = 0
			end)
		end
		local root = char:FindFirstChild("HumanoidRootPart")
		st.mode = "red"
		TT.ease(st, "heat", 1, 0.12)
		if root then
			VFX.PlaySound("EngineCool", root.Position, 1)
		end
		TT.pop(char, EK.PUFF.smoke, 4, 0.8)
		task.delay(0.15, function()
			if TT.state[char] == st then
				TT.ease(st, "heat", 0, 0.75)
			end
		end)
		task.delay(0.85, function()
			if TT.state[char] == st then
				TT.ease(st, "len", 0.02, 0.35)
				if root then
					VFX.PlaySound("TurboRetract", root.Position, 1)
				end
			end
		end)
		task.delay(1.22, function()
			if TT.state[char] == st then
				TT.drop(char)
				if EK.alive(char) then
					EK.stall(char, 1.4)
				end
			end
		end)
	end
	-- the kit's one-shot puff out of each calf's mouths (EK.pop), kept on
	-- his tubes' list so it goes with them if he dies or turns into someone
	-- else meanwhile
	function TT.pop(char, style, n, k)
		local st = TT.state[char]
		if not EK.alive(char) then
			return
		end
		for _, list in { EK.mouths(char).Right, EK.mouths(char).Left } do
			if list and #list > 0 then
				local p, d = EK.centre(list)
				local att = Instance.new("Attachment")
				att.Name = "EngineFX"
				att.CFrame = CFrame.lookAt(p, p + d)
				att.Parent = list[1].leg
				EK.emitter(att, style, k):Emit(EK.count(n))
				EK.gone(att, style.life[2] + 0.1)
				if st then
					table.insert(st.legFx, att)
				end
			end
		end
	end
	-- his exhaust out of the tube mouths again before a move uses it (the
	-- kit may have made its mouths anew since the last update)
	function TT.ready(char)
		local st = char and TT.state[char]
		if st and not st.ending then
			TT.remouth(st)
		end
	end
	-- the tubes flared hot for a beat (a move's rev), then cooled
	function TT.flare(char, mode, hold)
		local st = char and TT.state[char]
		if not st or st.ending then
			return
		end
		st.mode = mode or "white"
		TT.ease(st, "heat", 1, 0.1)
		task.delay(hold or 0.4, function()
			if TT.state[char] == st and not st.ending then
				TT.ease(st, "heat", 0, 0.5)
			end
		end)
	end

	-- the in-ult look, ten times a second
	function TT.update(st, now)
		local c = st.char
		if not (EK.alive(c) and c:IsDescendantOf(workspace) and c:GetAttribute("Quirk") == "Engine") then
			TT.drop(c, true)
			return
		end
		local dt = math.min(now - (st.tickAt or now), 0.5)
		st.tickAt = now
		if st.ending then
			return
		end
		if c:GetAttribute("UltActive") == true then
			st.seen = true
		elseif st.seen or now - st.since > TT.DRIVE.Grace then
			TT.off(c)
			return
		end
		local hiddenNow = TT.hidden[c] ~= nil and now < TT.hidden[c]
		-- (blown out, his old stubs are what's left on his calves)
		if not st.keepStubs and not st.blown and not hiddenNow then
			TT.stubs(st, true)
		end
		TT.remouth(st)
		local root = c:FindFirstChild("HumanoidRootPart")
		if not root then
			return
		end
		-- blown out (MAXIMUM BURST): his exhaust out of the old stubs, and new
		-- tubes grow back in a moment later
		if st.blown then
			if now >= (st.regrowAt or 0) then
				st.blown = false
				st.unmouthed = false
				TT.stubs(st, true)
				for _, tube in st.tubes do
					for _, p in tube.parts do
						p.LocalTransparencyModifier = 0
					end
				end
				st.len = 0.02
				TT.place(st)
				TT.ease(st, "len", TT.TUBE.Length, 0.3)
				TT.flare(c, "turbo", 0.25)
				TT.pop(c, EK.PUFF.sparks, 5, 0.7)
				VFX.PlaySound("TurboGrow", root.Position, 0.7)
			end
			return
		end
		local ok, v = pcall(function()
			return root.AssemblyLinearVelocity
		end)
		v = ok and typeof(v) == "Vector3" and v or Vector3.zero
		local speed = Vector3.new(v.X, 0, v.Z).Magnitude
		local cam = workspace.CurrentCamera
		local far = cam ~= nil and (root.CFrame.Position - cam.CFrame.Position).Magnitude > TT.DRIVE.Cull
		-- the tips pulse magenta and white (not while a move has them hot) -
		-- slow enough to read smooth at ten updates a second
		if st.heat < 0.05 and not st.awakening then
			for _, tube in st.tubes do
				local tip = tube.parts.tip
				if tip then
					tip.Color = TP.TURBO_MAGENTA:Lerp(TP.TURBO_WHITE, 0.5 + 0.5 * math.sin(now * 4.5 + tube.i * 0.9))
				end
			end
		end
		-- the glow over them: with the middle one's pulse; none far off, on
		-- the blink, in the awakening or while a move has them hot (their own
		-- heat carries it then, and the glow would only wash it out)
		local pulse = TP.TURBO_MAGENTA:Lerp(TP.TURBO_WHITE, 0.5 + 0.5 * math.sin(now * 4.5 + 1.8))
		for _, g in st.glows do
			g.pe.Rate = (far or hiddenNow or st.awakening or st.heat >= 0.05) and 0 or g.rate
			g.pe.Color = ColorSequence.new(pulse)
		end
		-- the two-tone trails off his calves, once the tubes are grown
		if not st.trails and not st.awakening and st.len >= TT.TUBE.Length * 0.9 then
			st.trails = EK.legTrails(c, nil, { color = TP.TURBO_SMEAR, core = TP.TURBO_CYAN, width = 1.1, life = 0.3 })
		end
		-- standing: the heat haze off the tubes, an ember now and then
		local standing = speed < 3 and not far and not st.awakening
		for _, h in st.haze do
			h.smoke.Rate = standing and EK.count(6) or 0
			h.ember.Rate = standing and 0.7 or 0
		end
		-- flat out: a gold ghost of him every Ghost s, a vapor ring every Ring s
		if speed > TT.DRIVE.Fast and not far and not (TT.hidden[c] and now < TT.hidden[c]) then
			if now - st.ghostAt >= (EK.lowEnd() and TT.DRIVE.Ghost * 2 or TT.DRIVE.Ghost) then
				st.ghostAt = now
				EK.afterimage(c, TP.TURBO_GOLD, 0.28, { transparency = 0.6 })
			end
			st.sprint += dt
			if st.sprint >= TT.DRIVE.Ring then
				st.sprint -= TT.DRIVE.Ring
				local dir = TT.flat(v)
				EK.vaporRings(root.Position + dir * 2, dir, 1, { size = 2.6, life = 0.5 })
			end
		else
			st.sprint = 0
		end
	end
	function TT.tick()
		local now = os.clock()
		if now - (TT.scanAt or -1e9) >= TT.DRIVE.Scan then
			TT.scanAt = now
			for _, c in TT.bodies() do
				if not TT.state[c] and c:GetAttribute("Quirk") == "Engine" and c:GetAttribute("UltActive") == true and EK.alive(c) then
					local st = TT.on(c, false)
					if st then
						st.seen = true
					end
				end
			end
		end
		for c, st in TT.state do
			if not pcall(TT.update, st, now) then
				pcall(TT.drop, c)
			end
		end
	end

	---------------------------------------------------------------------------
	-- PIECES FOR THE MOVES
	---------------------------------------------------------------------------
	-- out of sight on every screen for t seconds (or till show() - his
	-- exhaust held off too): Turbo Kick's blink
	function TT.hide(char, t)
		TT.hidden[char] = os.clock() + t
		local hidden = {}
		for _, d in char:GetDescendants() do
			-- (one already hidden - his old stubs under the tubes - stays so)
			local ok, was = pcall(function()
				return d.LocalTransparencyModifier
			end)
			if (d:IsA("BasePart") or d:IsA("Decal")) and d.Name ~= "HumanoidRootPart" and not (ok and was >= 1) then
				d.LocalTransparencyModifier = 1
				table.insert(hidden, d)
			end
		end
		EK.hold(char, t + 0.05)
		-- (the tubes' glow too, at once: the update puts it back after)
		local st = TT.state[char]
		for _, g in st and st.glows or {} do
			g.pe.Rate = 0
			pcall(g.pe.Clear, g.pe)
		end
		local function show()
			if not hidden then
				return
			end
			for _, d in hidden do
				if d.Parent then
					d.LocalTransparencyModifier = 0
				end
			end
			hidden = nil
			TT.hidden[char] = nil
			EK.hold(char, 0)
		end
		task.delay(t, show)
		return show
	end
	-- a bar of light from a, its far end set as he goes (bar.set): white
	-- core, a coloured middle, a violet edge, wider at the far end. Held
	-- till bar.stop(fade); bar.flash(t): every colour white for a moment,
	-- then gone (TURBO RUSH's last leg)
	function TT.bar(a, opts)
		opts = opts or {}
		local width = opts.width or 2.4
		local h = EK.holder(CFrame.new(a), nil, "TurboBar")
		EK.gone(h, opts.maxLife or 4)
		local a0 = Instance.new("Attachment")
		a0.Parent = h
		local a1 = Instance.new("Attachment")
		a1.CFrame = CFrame.new(0, 0, -0.1)
		a1.Parent = h
		local beams = {}
		for _, L in {
			{ c = opts.edge or TP.TURBO_VIOLET, w = 1, t = 0.6, light = 0.3 },
			{ c = opts.color or TP.TURBO_CYAN, w = 0.66, t = 0.05, light = 0.25 },
			{ c = Color3.new(1, 1, 1), w = 0.12, t = 0, light = 1 },
		} do
			local bm = EK.beam(a0, a1, { color = L.c, transp = L.t, w0 = width * L.w * 0.6, w1 = width * L.w, light = L.light }, 1, h)
			bm.Name = "TurboBar"
			table.insert(beams, { b = bm, w = width * L.w })
		end
		local bar = { holder = h, alive = true, from = a }
		function bar.set(b)
			if bar.alive and typeof(b) == "Vector3" and (b - a).Magnitude > 0.05 then
				a1.CFrame = CFrame.new(b - a)
				bar.to = b
			end
		end
		function bar.stop(fade)
			if not bar.alive then
				return
			end
			bar.alive = false
			fade = fade or 0.25
			for _, x in beams do
				tween(x.b, fade, { Width0 = 0, Width1 = 0 }, Enum.EasingStyle.Quad, Enum.EasingDirection.In)
			end
			EK.gone(h, fade + 0.05)
		end
		-- thinned to k of its width over t, still up (TURBO RUSH keeps every
		-- leg's bar up, thin, till its finisher flashes them all)
		function bar.dim(k, t)
			if not bar.alive then
				return
			end
			for _, x in beams do
				tween(x.b, t or 0.3, { Width0 = x.w * 0.6 * k, Width1 = x.w * k }, Enum.EasingStyle.Quad)
			end
		end
		function bar.flash(time)
			if not bar.alive then
				return
			end
			for _, x in beams do
				x.b.Color = ColorSequence.new(Color3.new(1, 1, 1))
				x.b.Width0, x.b.Width1 = x.w * 1.4, x.w * 1.4
			end
			bar.stop(time or 0.18)
		end
		return bar
	end
	-- (round 85) every per-frame job of the moves on one RenderStepped: fn(t)
	-- each frame (t: seconds since it was added) till it returns true (or
	-- errors); the connection goes when there's nothing left
	TT.jobs = {}
	function TT.run(fn)
		table.insert(TT.jobs, { fn = fn, t0 = os.clock() })
		if TT.jobConn then
			return
		end
		TT.jobConn = RunService.RenderStepped:Connect(function()
			local now = os.clock()
			for i = #TT.jobs, 1, -1 do
				local job = TT.jobs[i]
				local ok, done = pcall(job.fn, now - job.t0)
				if not ok or done then
					table.remove(TT.jobs, i)
				end
			end
			if #TT.jobs == 0 and TT.jobConn then
				TT.jobConn:Disconnect()
				TT.jobConn = nil
			end
		end)
	end
	-- parts thrown: tumbling along vel (spin: radians a second about each
	-- axis), falling, faded in their last 40%, gone after life
	function TT.fling(list, life)
		for _, f in list do
			f.cf0 = f.part.CFrame
			EK.gone(f.part, life + 0.3)
		end
		TT.run(function(t)
			if t >= life then
				for _, f in list do
					pcall(f.part.Destroy, f.part)
				end
				return true
			end
			for _, f in list do
				if f.part.Parent then
					local pos = f.cf0.Position + f.vel * t + Vector3.new(0, -50 * t * t / 2, 0)
					f.part.CFrame = CFrame.new(pos) * f.cf0.Rotation * CFrame.Angles(f.spin.X * t, f.spin.Y * t, f.spin.Z * t)
					f.part.Transparency = math.max(f.part.Transparency, math.clamp((t / life - 0.6) / 0.4, 0, 1))
				end
			end
			return false
		end)
	end
	-- a flat shock disc that opens slowly to d1 over t1 (a slow-motion beat)
	-- and then blows out to d2 over t2
	function TT.disc(pos, dir, d0, d1, d2, t1, t2, color)
		local disc = newPart(Vector3.new(0.2, d0, d0), CFrame.lookAt(pos, pos + dir) * CFrame.Angles(0, math.pi / 2, 0), color, Enum.Material.ForceField, Enum.PartType.Cylinder)
		disc.Name = "TurboDisc"
		tween(disc, t1, { Size = Vector3.new(0.2, d1, d1) }, Enum.EasingStyle.Quad)
		tween(disc, t2, { Size = Vector3.new(0.2, d2, d2), Transparency = 1 }, Enum.EasingStyle.Quad, Enum.EasingDirection.Out, t1)
		EK.gone(disc, t1 + t2 + 0.05)
		return disc
	end
	---------------------------------------------------------------------------
	-- THE AWAKENING ((round 101) VFX.AK.FX.Engine plays it on the kit's
	-- beats; his clip is MoveAwakenEngine, anim/moves_awaken_e.py): the press
	-- puts his tubes on him (the old mufflers still showing); on the clip's
	-- Gather - bent double, hands at his calves - the old mufflers are ripped
	-- out of both calves in a bang of exhaust (TT.yank) and the long tubes
	-- grow in, heating along their length - magenta, orange, white at the
	-- mouths, a violet glow off them - as he drops into the set; on the Hit
	-- the engines catch: the eruption (TT.erupt) - a yellow-white starburst
	-- behind him, a pink shock disc, rocks, a white spray wall, the turbo jets
	-- out of the tubes - and the tubes cool to their in-ult look through the
	-- hold. (His line and the shout are the kit's: the bubble that said it is
	-- gone; so is the roar here - the kit plays UltEngine on the hit.)
	---------------------------------------------------------------------------
	function TT.awakenOn(char)
		local st = TT.state[char]
		if st and st.ending then
			TT.drop(char)
			st = nil
		end
		st = st or TT.on(char, true)
		if not st then
			return nil
		end
		st.since = os.clock()
		st.awakening = true
		st.len, st.heat = 0.02, 0
		TT.place(st)
		TT.paint(st)
		-- (the stubs are still on him till the yank)
		st.keepStubs = true
		TT.stubs(st, false)
		return st
	end
	-- the yank: the old mufflers out of both calves, flung away; the long ones
	-- grow in over `grow` and heat up along their length over `heat`
	function TT.yank(char, root, g, grow, heat)
		local st = TT.state[char]
		if not st or st.ending or not root.Parent then
			return
		end
		st.keepStubs = false
		TT.stubs(st, true)
		local bits = {}
		for _, tube in st.tubes do
			if not EK.lowEnd() or tube.i ~= 2 then
				local cf = tube.leg.CFrame * CFrame.new(tube.base + tube.dir * 0.15)
				local stub = newPart(Vector3.new(0.3, 0.16, 0.16), cf, Color3.fromRGB(95, 100, 110), Enum.Material.Metal, Enum.PartType.Cylinder)
				stub.Name = "TurboOldMuffler"
				local out = tube.leg.CFrame:VectorToWorldSpace(tube.dir)
				table.insert(bits, { part = stub, vel = out * rand(10, 16) + UP * rand(14, 22) + rng:NextUnitVector() * 3, spin = Vector3.new(rand(-12, 12), rand(-12, 12), rand(-12, 12)) })
			end
		end
		TT.fling(bits, 0.8)
		EK.backfire(char, nil, { scale = 1.5, sound = false })
		EK.cloud(g, 0.9, TP.DUST, 0.5, false)
		VFX.PlaySound("TurboTear", root.Position, 1)
		-- the long ones grow in, heating along their length
		TT.ease(st, "len", TT.TUBE.Length, grow)
		TT.pop(char, EK.PUFF.sparks, 6, 0.8)
		VFX.PlaySound("TurboGrow", root.Position, 1)
		st.mode = "turbo"
		TT.ease(st, "heat", 1, heat)
		for _, h in st.haze do
			h.smoke:Emit(EK.count(6))
		end
		VFX.PlaySound("TurboHeat", root.Position, 1)
	end
	-- the awakening over (its release, or called off): his tubes' own look
	function TT.awakenOff(char)
		local st = TT.state[char]
		if st then
			st.awakening = false
			st.keepStubs = false
			-- ((round 101 review) called off before the yank with his ult still
			-- on (a newer run on him): the long tubes grown in all the same -
			-- never left as stubs a fiftieth of their length)
			if not st.ending and st.len < TT.TUBE.Length * 0.9 then
				TT.ease(st, "len", TT.TUBE.Length, 0.3)
			end
		end
	end
	-- the eruption: the engines catch out of the white-hot tubes. opts: d (his
	-- facing: the starburst goes behind him - he's silhouetted against it, never
	-- inside it), skip(pos, r) (true: leave out a piece there - his own lens)
	function TT.erupt(char, root, opts)
		opts = type(opts) == "table" and opts or {}
		local st = TT.state[char]
		local g = groundPoint(root.Position)
		local p = g + UP * 0.6
		local star = g + UP * 1.2 - (typeof(opts.d) == "Vector3" and opts.d or Vector3.zero) * 2.2
		EK.flash(char, nil, TP.TURBO_WHITE, 1.8)
		TT.ready(char)
		EK.jets(char, "turbo", 0.75, { len = 6.5, fade = 0.3 })
		if st then
			TT.ease(st, "heat", 0, 0.65)
		end
		-- a yellow-white starburst, a pink shock disc, rocks
		EK.starSpark(star, { size = 10, spikes = 8, color = Color3.fromRGB(255, 240, 170), color2 = Color3.new(1, 1, 1), life = 0.3 })
		task.delay(0.04, function()
			EK.starSpark(star, { size = 7, spikes = 8, color = TP.IGNITE, color2 = TT.PINK, life = 0.26 })
		end)
		shockDisc(g + UP * 0.3, UP, 4, 46, 0.45, TT.PINK)
		shockDisc(g + UP * 0.5, UP, 2, 30, 0.35, Color3.new(1, 1, 1))
		billboardRing(p, 3, 34, TT.PINK, 6, 0.35)
		rocks(g, 2, EK.count(12))
		TT.spray(g, 6, opts.skip)
		EK.cloud(g, 1.5, TP.DUST, 0.55, false)
		if not EK.lowEnd() then
			local h = EK.holder(CFrame.new(p + UP * 2), 0.8, "TurboFlash")
			local pl = Instance.new("PointLight")
			pl.Color = Color3.fromRGB(255, 220, 245)
			pl.Range = 30
			pl.Brightness = 6
			pl.Parent = h
			tween(pl, 0.7, { Brightness = 0 })
		end
		VFX.PlaySound("TurboErupt", p, 1)
	end
	-- the white spray wall thrown up round him (radius r): smoke-white
	-- plumes all round, and glints ((round 101) skip(pos, r): a plume left out
	-- there - the awakening's own lens)
	function TT.spray(g, r, skip)
		local n = EK.lowEnd() and 6 or 12
		local h = EK.holder(CFrame.new(g), 1.6, "TurboSpray")
		for i = 1, n do
			local a = i / n * math.pi * 2
			local out = Vector3.new(math.cos(a), 0, math.sin(a))
			if skip and skip(g + out * r * 0.9 + UP * 2, 2.5) then
				continue
			end
			local att = Instance.new("Attachment")
			att.CFrame = CFrame.lookAt(out * r * 0.4, out * r * 0.4 + (UP * 1.6 + out).Unit)
			att.Parent = h
			local pe = EK.emitter(att, {
				tex = EK.TEX.smoke, color = { Color3.new(1, 1, 1), TP.VAPOR }, size = { { 0, 1.6 }, { 1, 5 } }, transp = { { 0, 0.15 }, { 0.6, 0.5 }, { 1, 1 } },
				life = { 0.6, 0.9 }, speed = { 18, 30 }, spread = 14, drag = 4, influence = 0.5, spin = { -40, 40 },
			})
			pe:Emit(3)
		end
		local glint = EK.emitter(h, { tex = EK.TEX.spark, color = { Color3.new(1, 1, 1), TP.TURBO_CYAN }, size = { { 0, 0.5 }, { 1, 0 } }, transp = 0, life = { 0.4, 0.7 }, speed = { 25, 45 }, spread = 60, dir = "Top", accel = Vector3.new(0, -40, 0), light = 1 })
		glint:Emit(EK.count(24))
	end

	-- Picks the closest enemy in front and blinks into them
	local function turboTarget(root, d, range)
		local best, bestDist
		local candidates = {}
		for _, plr in Players:GetPlayers() do
			if plr.Character and plr.Character ~= root.Parent then
				table.insert(candidates, plr.Character)
			end
		end
		local dummies = workspace:FindFirstChild("Dummies")
		if dummies then
			for _, m in dummies:GetChildren() do
				table.insert(candidates, m)
			end
		end
		for _, m in candidates do
			local r = m:FindFirstChild("HumanoidRootPart")
			local h = m:FindFirstChildOfClass("Humanoid")
			if r and h and h.Health > 0 then
				local v = r.Position - root.Position
				local dist = v.Magnitude
				if dist < range and dist > 1 and flatten(v, root):Dot(d) > 0.3 and (not bestDist or dist < bestDist) then
					best, bestDist = r, dist
				end
			end
		end
		return best, bestDist
	end

	-- (round 85) TURBO KICK: he's simply THERE. A gold ghost of him and a
	-- ring of air where he stood, and a bar of light from there to them -
	-- his body is out of sight on every screen while he blinks (the bar runs
	-- on with it), and he appears already in his flying side kick
	-- (MoveIidaTurboKick, held on its Hold key for the blink): a star spark,
	-- the violet kick smear, a shock ring, a jet out of the tubes, a white
	-- contrail along the bar, his camera's FOV punched. (The server gives the
	-- hit its hitstop.) The blink itself is as it was: 260 studs/s at the
	-- closest one in front, or 0.12 s straight ahead
	function Effects.TurboKick(char, data, isLocal, ability)
		local root = charParts(char)
		if not root then
			return
		end
		local d = flatten(data.Dir, root)
		local from = root.Position
		local target, dist = turboTarget(root, d, (ability and ability.Range) or 50)
		local bt = target and math.clamp((dist - 3) / 260, 0.05, 0.25) or 0.12
		if isLocal then
			if target then
				local v = (target.Position - root.Position).Unit
				face(root, v)
				dash(root, v * 260, bt)
			else
				face(root, d)
				dash(root, d * 260, bt)
			end
		end
		-- where he was
		EK.afterimage(char, TP.TURBO_GOLD, 0.45, { transparency = 0.42 })
		EK.vaporRings(from + d * 1.5, d, 1, { size = 2.4, life = 0.4 })
		VFX.PlaySound("TurboBlink", from, 1)
		TT.clip(char, "MoveIidaTurboKick", "IidaTurboKick", { holdFor = math.max(bt - 0.05, 0) })
		local show = TT.hide(char, bt + 0.3)
		-- the bar is there at once, all the way to where the blink ends (the
		-- same sum as his dash: 260 studs/s for bt), and snaps to where his
		-- body really is when it's there: he's never seen going
		local to = from + (target and (target.Position - from).Unit or d) * 260 * bt
		local bar = TT.bar(from + UP * 0.4, { width = 2.6, color = TP.TURBO_CYAN })
		bar.set(to + UP * 0.4)
		-- on his own machine the blink is exactly bt; on everyone else's it
		-- lasts till his body gets there and stops
		local t0 = os.clock()
		local conn
		conn = RunService.RenderStepped:Connect(function()
			if not root.Parent or not EK.alive(char) then
				conn:Disconnect()
				show()
				bar.stop(0.1)
				return
			end
			local t = os.clock() - t0
			local ok, v = pcall(function()
				return root.AssemblyLinearVelocity
			end)
			local slow = ok and typeof(v) == "Vector3" and Vector3.new(v.X, 0, v.Z).Magnitude < 70
			if t >= bt and (isLocal or slow or t >= bt + 0.25) then
				conn:Disconnect()
				show()
				bar.set(root.Position + UP * 0.4)
				TT.kickArrive(char, root, from, isLocal)
				task.delay(0.15, bar.stop, 0.35)
			end
		end)
	end
	function TT.kickArrive(char, root, from, isLocal)
		local look = TT.flat(root.CFrame.LookVector)
		local p = root.Position + look * 2.6 + UP * 0.3
		EK.starSpark(p, { size = 4.2, color = TP.TURBO_CYAN, color2 = TP.TURBO_GOLD })
		EK.kickSmear(CFrame.lookAt(root.Position, root.Position + look) * CFrame.new(0, -0.2, 0), { arc = 140, radius = 3.4, color = TP.TURBO_SMEAR, core = TP.TURBO_CYAN, life = 0.4, draw = 0.05 })
		shockDisc(p, look, 2, 9, 0.2, WIND)
		TT.ready(char)
		EK.jets(char, "turbo", 0.22, { len = 5 })
		EK.contrailLine(from + UP * 0.4, root.Position + UP * 0.4, { life = 0.7, width = 1 })
		VFX.PlaySound("Kick", p, 0.9)
		VFX.ShakeAt(p, 0.9, 40, 0.12)
		if isLocal then
			EK.fovPunch(12, 0.05, 0.3)
		end
	end

	---------------------------------------------------------------------------
	-- (round 85) TURBO RUSH (Effects.ReciproTurbo calls it). The server's
	-- beats: the rev to 0.45, the rush 0.45-1.05 (it catches whoever comes
	-- within 9 studs of a point 2 ahead of him along his aim), two flurry
	-- hits at 1.14 and 1.23 and the finisher at 1.35 on everyone it caught.
	-- He flies the same five legs as ever (0.11 s each at 200 studs/s, a
	-- zig-zag 24 degrees either side of his aim, the last one straight down
	-- it); the look is all light. Each leg leaves its own bar (cyan,
	-- green-cyan, blue, violet, white) that thins after half a second but
	-- hangs on to the finisher; a flying side kick a leg (left and right in
	-- turn). Whoever the rush catches gets THE CRISSCROSS at once (research
	-- 3.3, Ep 96: the bars crisscrossing round Honenuki): five bars through
	-- them from every side, as if he came back at them five times at the
	-- speed of light, and a star spark; the flurry slashes a bar across each
	-- of them; the finisher - a spinning back kick on him, a gold ghost of it
	-- at them, the blast on them (in front of him if he caught nobody) -
	-- flashes every bar still up white at once: an impact frame for anyone
	-- close, shock rings, the violet and cyan smears
	---------------------------------------------------------------------------
	-- his five legs, as they've always been (d: his aim, flat)
	function TT.rushPlan(d)
		local legs, right = {}, d:Cross(UP)
		for i = 1, 5 do
			local side = (i % 2 == 0) and 1 or -1
			table.insert(legs, { dir = i == 5 and d or (d + right * side * 0.45).Unit, len = 22 })
		end
		return legs
	end
	-- the crisscross round someone the rush caught (at p, his aim d), from
	-- leg i's colour on: five bars through them (three on a low-end
	-- machine) 36 degrees apart, drawn one after another as fast as light;
	-- each a little off their middle and tipped up or down, so they knot
	-- round them rather than meet in one point and read from the street
	-- too. Its bars go into list (the finisher flashes them)
	function TT.crisscross(p, d, i, list)
		local n = EK.lowEnd() and 3 or 5
		EK.starSpark(p + UP * 0.3, { size = 3.6, color = TT.BARS[i] or TT.BARS[5], color2 = Color3.new(1, 1, 1), spikes = 6 })
		shockDisc(p + UP * 0.3, d, 1, 10, 0.18, WIND)
		for k = 0, n - 1 do
			task.delay(k * 0.025, function()
				local u = TT.rotY(d, 18 + k * 360 / n)
				u = (u + UP * (k % 2 == 0 and 0.15 or -0.15)).Unit
				local c = p + UP * (0.1 + 0.3 * (k % 3)) + TT.flat(u:Cross(UP)) * ((k % 3) - 1) * 0.6
				local b = TT.bar(c - u * 9, { color = TT.BARS[(i + k - 1) % 5 + 1], width = 1.7 })
				b.crisscross = true
				b.set(c + u * 9)
				table.insert(list, b)
				task.delay(0.45, b.dim, 0.45, 0.3)
				VFX.PlaySound("TurboBar", c, 0.7)
			end)
		end
	end
	function TT.rush(char, data, isLocal)
		local root = charParts(char)
		if not root then
			return
		end
		local d = flatten(data.Dir, root)
		local t0 = os.clock()
		local bars = {}
		local function at(t)
			local w = t - (os.clock() - t0)
			if w > 0 then
				task.wait(w)
			end
			if root.Parent ~= nil and EK.alive(char) then
				return true
			end
			-- (he's gone: no bar hangs on)
			for _, b in bars do
				b.stop(0.2)
			end
			return false
		end
		if isLocal then
			face(root, d)
			VFX.Hooks.Dim(0.55, 0.9)
		end
		-- the rev: the set, the tubes white-hot, the turbo catching
		VFX.Pose(char, "Rev", 0.45)
		VFX.PlaySound("Engine", root.Position, 1.2)
		TT.ready(char)
		EK.ignite(char, { mode = "turbo", len = 4.5, dur = 0.2, snap = 0.22, sound = false })
		TT.flare(char, "white", 0.4)
		if not at(0.45) then
			return
		end
		local foes, caught, hitList = TT.foes(char), {}, {}
		for i, leg in TT.rushPlan(d) do
			local p0 = root.Position
			if isLocal then
				face(root, leg.dir)
				dash(root, leg.dir * 200, leg.len / 200)
			end
			TT.clip(char, i % 2 == 1 and "MoveIidaRushR" or "MoveIidaRushL", i % 2 == 1 and "IidaRushR" or "IidaRushL")
			EK.afterimage(char, TP.TURBO_GOLD, 0.3, { transparency = 0.45 })
			VFX.PlaySound("TurboBar", p0, 0.9)
			local bar = TT.bar(p0 + UP * 0.3 - leg.dir * 3, { color = TT.BARS[i] or TT.BARS[5], width = 2.2 })
			table.insert(bars, bar)
			-- the bar runs on with his body (on every screen), 3 studs past him;
			-- each leg ends on the server's clock (0.45 + 0.11 a leg), so a slow
			-- frame doesn't push the rest late. Whoever comes into the sweep's
			-- reach (the server's: 9 studs round 2 ahead along his aim) is
			-- caught: the crisscross round them
			local legEnd = 0.45 + 0.11 * i
			repeat
				local pos = root.Position
				local way = pos - p0
				way = way.Magnitude > 1 and TT.flat(way) or leg.dir
				bar.set(pos + UP * 0.3 + way * 3)
				local reach = pos + d * 2
				for _, m in foes do
					local r = not caught[m] and m.Parent and m:FindFirstChild("HumanoidRootPart")
					local h = r and m:FindFirstChildOfClass("Humanoid")
					if h and h.Health > 0 and (r.Position - reach).Magnitude < 9 then
						caught[m] = true
						table.insert(hitList, m)
						TT.crisscross(r.Position, d, i, bars)
					end
				end
				task.wait()
			until os.clock() - t0 >= legEnd or not root.Parent
			task.delay(0.5, bar.dim, 0.4, 0.3)
		end
		if isLocal and root.Parent then
			face(root, d)
		end
		-- where the flurry and the finisher land: on everyone the rush caught
		-- (the server hits them wherever they are), or in front of him
		local function spots()
			local out = {}
			for _, m in hitList do
				local r = m.Parent and m:FindFirstChild("HumanoidRootPart")
				if r and #out < 3 then
					table.insert(out, r.Position + UP * 0.3)
				end
			end
			if #out == 0 then
				table.insert(out, root.Position + TT.flat(root.CFrame.LookVector) * 3 + UP * 0.3)
			end
			return out
		end
		-- the flurry: a kick each, a bar slashed across each of them
		for k, beat in { 1.14, 1.23 } do
			if not at(beat - 0.045) then
				return
			end
			TT.clip(char, k == 1 and "MoveIidaRushL" or "MoveIidaRushR", k == 1 and "IidaRushL" or "IidaRushR")
			if not at(beat) then
				return
			end
			local list = spots()
			for _, p in list do
				local across = TT.rotY(d, k == 1 and 62 or -62)
				local b = TT.bar(p - across * 9, { color = TT.BARS[k + 2], width = 1.8 })
				b.set(p + across * 9)
				table.insert(bars, b)
				EK.starSpark(p, { size = 3.4, color = TT.BARS[k + 2], color2 = Color3.new(1, 1, 1), spikes = 6 })
				shockDisc(p, d, 1, 9, 0.16, WIND)
			end
			VFX.PlaySound("TurboBar", list[1], 0.8)
		end
		-- the finisher
		if not at(1.25) then
			return
		end
		TT.clip(char, "MoveIidaRushFinish", "IidaRushFinish")
		if not at(1.35) then
			return
		end
		local list = spots()
		local p = list[1]
		local look = TT.flat(root.CFrame.LookVector)
		for _, b in bars do
			b.flash(0.2)
		end
		local fb = TT.bar(p - d * 14, { color = Color3.new(1, 1, 1), edge = TP.TURBO_SMEAR, width = 3.2 })
		fb.set(p + d * 16)
		task.delay(0.12, fb.stop, 0.3)
		local MG = VFX.MANGA
		if MG then
			MG.impact(p, 0.08, { Radius = 90 })
		end
		for i = 0, 2 do
			task.delay(i * 0.04, function()
				shockDisc(p, d, 6, 32 + i * 6, 0.45, i == 1 and TP.TURBO_SMEAR or WIND, 40)
			end)
		end
		-- his spinning back kick's smears (on him), and where it lands far off
		-- him, a gold ghost of it there
		local hip = CFrame.lookAt(root.Position + look * 1.5, root.Position + look * 4.5)
		EK.kickSmear(hip, { arc = 300, radius = 4.6, color = TP.TURBO_SMEAR, core = Color3.new(1, 1, 1), life = 0.6 })
		EK.kickSmear(hip * CFrame.new(0, 0.4, 0), { arc = 240, radius = 3.6, color = TP.TURBO_CYAN, core = Color3.new(1, 1, 1), band = false, life = 0.5 })
		if (p - root.Position).Magnitude > 6 then
			local spot = p - d * 2.6
			EK.afterimage(char, TP.TURBO_GOLD, 0.4, { transparency = 0.25, offset = CFrame.new(spot.X - root.Position.X, 0, spot.Z - root.Position.Z) })
		end
		EK.starSpark(p, { size = 6.5, color = TP.TURBO_SMEAR, color2 = TP.TURBO_CYAN, life = 0.16 })
		for j = 2, #list do
			EK.starSpark(list[j], { size = 4.5, color = TP.TURBO_SMEAR, color2 = TP.TURBO_CYAN, life = 0.14 })
		end
		TT.ready(char)
		EK.jets(char, "turbo", 0.3, { len = 6 })
		VFX.PlaySound("TurboFlash", p, 1)
		VFX.PlaySound("Kick", p, 1.2)
		VFX.ShakeAt(p, 3, 160, 0.5)
		if isLocal then
			EK.fovPunch(14, 0.05, 0.35)
		end
		if nearCamera(p, 110) then
			VFX.Hooks.Flash(Color3.fromRGB(235, 215, 255), 0.2)
		end
	end

	---------------------------------------------------------------------------
	-- (round 85) RECIPRO: MAXIMUM BURST, the Final War's Maximum Speed on the
	-- server's clock (Handlers.ReciproMax: 0.6 s of charge, then 0.55 s of
	-- run - 160 studs at 320 studs/s - and whoever he passes is hit then;
	-- the server tells every screen where and when: ReciproMaxHit).
	-- THE CHARGE (0-0.6): his deepest sprinter's set (MoveIidaMaxSet, its GO
	-- on 0.6), a flare behind him growing and cycling crimson -> orange ->
	-- yellow -> cyan (0.15 s a colour; its light throws his shadow forward),
	-- the street splitting in a spiderweb under him, jets the same colours;
	-- at 0.36 the tubes stretch out and go white-hot; the bore flash whites
	-- his screen out at 0.6.
	-- GO: a star twinkle where he was, vapor rings, cracks, the mach cone, a
	-- contrail, the dust wall down the street, gold ghosts, and a wave of
	-- glass and surfaces bursting along his path as he passes (every 6 studs:
	-- shards blown off the buildings either side toward the street, glints
	-- and dust off the asphalt); a run-up (MoveIidaMaxRun) if the hit is far
	-- enough off, then the huge flying kick (MoveIidaMaxKick) out on the hit.
	-- THE HIT (ReciproMaxHit): an impact frame for anyone close; a slow-motion
	-- beat - the sparks crawl, the ring and the shock disc open slowly then
	-- blow out - a star, the violet smear, the crater. His camera ENDS ON IT
	-- (TT.maxShots). The server's hitstop freezes them both.
	-- THE END OF THE RUN (1.1): his mufflers blow - pops at both calves, the
	-- tubes' pieces tumbling off, charcoal smoke pouring off him for ~3 s -
	-- and he can't stick the landing (MoveIidaMaxLand). New tubes grow back
	-- 2 s later if he's still in the ult.
	---------------------------------------------------------------------------
	-- who he'll hit, where and when (every screen works it out the same way
	-- the server will: the first one in the run's path, within its sweep)
	function TT.maxPlan(root, d)
		local S = root.Position
		local plan = { S = S, d = d, stop = S + d * 160 }
		local best, bestAlong, bestLat
		for _, m in TT.foes(root.Parent) do
			local r = m:FindFirstChild("HumanoidRootPart")
			local h = m:FindFirstChildOfClass("Humanoid")
			if r and h and h.Health > 0 then
				local v = r.Position - S
				local along = v:Dot(d)
				local lat = (v - d * along).Magnitude
				if along > 0 and along < 173 and lat < 10 and (not best or along < bestAlong) then
					best, bestAlong, bestLat = r, along, lat
				end
			end
		end
		if best then
			-- (the sweep, 10 studs round a point 3 ahead of him, takes them as
			-- he comes within its reach)
			local reach = bestAlong - 3 - math.sqrt(math.max(100 - bestLat * bestLat, 0))
			plan.target = best.Parent
			plan.at = best.Position
			plan.tc = 0.6 + math.clamp(reach / 320, 0, 0.5)
		else
			plan.at = plan.stop
			plan.tc = 1.1
		end
		return plan
	end
	-- his cutscene, built at the press from the plan (the USS way): a high
	-- crane on him in the set, in front (the flare behind him throws his
	-- shadow at us); a macro on his calves as the tubes stretch out white-
	-- hot; the street from where he was, the wave running away down it; and
	-- it ENDS ON THE HIT - low from the side of it, held half a second while
	-- it plays out in slow motion. Every eye is pulled in short of anything
	-- between it and what it's on (a wall), and the last shot takes the
	-- side of the street with more room
	-- one end of a shot (eye looking at at, in the world) as the cutscene
	-- wants it (in basis' space), the eye pulled in short of anything between
	-- it and what it's on (a wall)
	function TT.pull(basis, eye, at, on)
		on = on or at
		pcall(function()
			rayParams.FilterDescendantsInstances = characterList()
			local gap = eye - on
			if gap.Magnitude > 0.5 then
				local hit = workspace:Raycast(on, gap, rayParams)
				if hit then
					eye = on + gap.Unit * math.max(hit.Distance - 0.8, math.min(1, hit.Distance * 0.5))
				end
			end
		end)
		return { basis:PointToObjectSpace(eye), basis:PointToObjectSpace(at) }
	end
	function TT.maxShots(root, d, plan)
		local S = root.Position
		local basis = CFrame.lookAt(S, S + d)
		local right = d:Cross(UP).Unit
		local function E(eye, at, on)
			return TT.pull(basis, eye, at, on)
		end
		local P = plan.at
		local side = right
		pcall(function()
			rayParams.FilterDescendantsInstances = characterList()
			local a = workspace:Raycast(P + UP, right * 12, rayParams)
			local b = workspace:Raycast(P + UP, -right * 12, rayParams)
			if (b and b.Distance or 12) > (a and a.Distance or 12) + 0.5 then
				side = -right
			end
		end)
		local calf = S - d * 1.7 + right * 0.6 - UP * 1.7 -- (his back calf, in the set)
		local shots = {
			{ T = 0.36, From = E(S + d * 7 + right * 3 + UP * 15, S - UP * 1.2, S), To = E(S + d * 5.5 + right * 2.5 + UP * 12, S - UP * 1.4, S), Fov = { 50, 44 } },
			-- (far enough back and out that the stretched tubes are side-on to it)
			{ T = 0.22, Cut = true, From = E(calf - d * 5.6 + right * 4.6 + UP * 1.5, calf - d * 1.9), To = E(calf - d * 5 + right * 4 + UP * 1.2, calf - d * 1.9), Fov = { 46, 38 } },
		}
		-- (a hit right in front of him: straight from the calves to the hit)
		local t = 0.58
		if plan.tc - 0.12 >= 0.7 then
			table.insert(shots, { T = plan.tc - 0.12 - t, Cut = true, Quiet = true, Fov = { 72, 62 },
				From = E(S - d * 10 + right * 3 + UP * 1.2, S + d * 60 + UP * 2.5, S), To = E(S - d * 8 + right * 2.6 + UP * 1.4, S + d * 60 + UP * 2.5, S) })
			t = plan.tc - 0.12
		end
		table.insert(shots, { T = plan.tc + 0.5 - t, Cut = true, Quiet = true, Style = Enum.EasingStyle.Quad, Fov = { 60, 50 },
			From = E(P - d * 10 + side * 12 + UP * 2.5, P - d * 2 + UP * 1, P), To = E(P - d * 6 + side * 11 + UP * 2, P + d * 2 + UP * 1, P) })
		return shots
	end
	-- the flare behind him (dur s): a growing glow with a white heart and
	-- rays turning round it, its colour stepping through crimson, orange,
	-- yellow, cyan; its light throws his shadow forward. It hangs up behind
	-- his shoulders (clear of his calves), and is held down to a third while
	-- dim = { from, to } (the macro on his tubes: they're its subject).
	-- Returns stop(); it stops itself a second after dur whatever happens
	function TT.halo(root, d, dur, dim)
		local pos = root.Position - d * 2.6 + UP * 2.2
		local h = EK.holder(CFrame.new(pos), dur + 1, "TurboHalo")
		local low = EK.lowEnd()
		local glow = EK.emitter(h, { tex = EK.TEX.glow, color = { Color3.new(1, 1, 1), TP.MAX[1] }, size = { { 0, 2.5 }, { 1, 3.5 } }, transp = { { 0, 0.35 }, { 0.5, 0.15 }, { 1, 1 } },
			life = { 0.12, 0.16 }, speed = { 0, 0 }, light = 1, bright = 1.6, locked = true, z = -1 })
		glow.Rate = low and 20 or 40
		local mid = Instance.new("Attachment")
		mid.Parent = h
		local rays = {}
		local n = low and 4 or 8
		for i = 1, n do
			local tip = Instance.new("Attachment")
			tip.Parent = h
			local b = EK.beam(mid, tip, { color = TP.MAX[1], w0 = 0.55, w1 = 0, light = 1, bright = 2 }, 1, h)
			b.Name = "TurboHalo"
			table.insert(rays, { tip = tip, b = b, a = i / n * math.pi * 2, len = i % 2 == 0 and 4 or 7.5 })
		end
		local pl = Instance.new("PointLight")
		pl.Color = TP.MAX[1]
		pl.Range = 28
		pl.Brightness = 2
		pl.Shadows = not low
		pl.Parent = h
		local t0 = os.clock()
		local conn
		local stopped = false
		local function stop()
			if stopped then
				return
			end
			stopped = true
			if conn then
				conn:Disconnect()
			end
			glow.Rate = 0
			pcall(h.Destroy, h)
		end
		conn = RunService.RenderStepped:Connect(function()
			local t = os.clock() - t0
			local k = math.clamp(t / dur, 0, 1)
			local m = (dim and t >= dim[1] and t < dim[2]) and 0.3 or 1
			local c = TP.MAX[math.clamp(math.floor(t / (dur / 4)) + 1, 1, 4)]
			glow.Color = ColorSequence.new(Color3.new(1, 1, 1), c)
			glow.Size = NumberSequence.new((1.5 + 3.5 * k) * m, (2.2 + 4 * k) * m)
			pl.Color = c
			pl.Brightness = (2 + 4 * k) * m
			local cam = workspace.CurrentCamera
			local look = cam and (pos - cam.CFrame.Position) or d
			look = look.Magnitude > 0.01 and look.Unit or d
			local rgt = look:Cross(math.abs(look.Y) > 0.95 and Vector3.new(1, 0, 0) or UP).Unit
			local up = rgt:Cross(look)
			for _, r in rays do
				local a = r.a + t * 0.8
				r.tip.CFrame = CFrame.new((rgt * math.cos(a) + up * math.sin(a)) * r.len * (0.3 + 0.7 * k) * m)
				r.b.Color = ColorSequence.new(c)
			end
		end)
		task.delay(dur + 1, stop)
		return stop
	end
	-- the spiderweb of cracks under his set (the kit's radial cracks, and
	-- two rings of crack between them), grown over grow s
	function TT.web(g, grow)
		EK.cracks(g + UP * 3, 7.5, 10, { grow = grow, crater = false, life = 3 })
		local n = EK.lowEnd() and 5 or 9
		for ring, r in { 3.2, 5.8 } do
			local base = rand(0, math.pi * 2)
			for i = 1, n do
				local a0, a1 = base + (i - 1) / n * math.pi * 2, base + i / n * math.pi * 2
				local p0 = g + Vector3.new(math.cos(a0), 0, math.sin(a0)) * r * rand(0.92, 1.08)
				local p1 = g + Vector3.new(math.cos(a1), 0, math.sin(a1)) * r * rand(0.92, 1.08)
				local seg = newPart(Vector3.new(0.12 + 0.06 * (2 - ring), 0.05, (p1 - p0).Magnitude + 0.1), CFrame.lookAt((p0 + p1) / 2 + UP * 0.05, p1 + UP * 0.05), TP.CRACK, Enum.Material.SmoothPlastic)
				seg.Name = "TurboCrack"
				seg.Transparency = 1
				tween(seg, 0.05, { Transparency = 0 }, nil, nil, grow * (0.35 + 0.4 * (ring - 1)) + rand(0, 0.08))
				tween(seg, 0.6, { Transparency = 1 }, nil, nil, 3)
				EK.gone(seg, 3.7)
			end
		end
	end
	-- the dust wake torn up off the street under his run (the kit's dust
	-- wall's puffs, under where he really is)
	TT.WAKE = {
		tex = EK.TEX.smoke, color = { TP.DUST, Color3.fromRGB(170, 140, 108) }, size = { { 0, 1.6 }, { 0.4, 3.6 }, { 1, 5 } },
		transp = { { 0, 0.3 }, { 0.5, 0.45 }, { 1, 1 } }, life = { 1, 1.8 }, speed = { 1.5, 4.5 }, spread = 70, dir = "Top",
		accel = Vector3.new(0, 1.2, 0), drag = 2.5, influence = 0.9, spin = { -30, 30 },
	}
	-- the wave along his path, from where he is now on for dur s: every 6
	-- studs he passes, the surfaces either side burst; and the dust wake
	-- off the street under him, taller toward the end (it stops where he
	-- does - a wall, his death). One holder for the bursts: one set of
	-- emitters a side, moved to each burst and fired there
	function TT.wave(root, d, dur)
		local right = d:Cross(UP).Unit
		local last = root.Position
		local t0 = os.clock()
		local n = 0
		local low = EK.lowEnd()
		local h = EK.holder(CFrame.new(last), dur + 1.6, "TurboWave")
		local W = { holder = h, sides = {} }
		for _, s in { 1, -1 } do
			local a = Instance.new("Attachment")
			a.Name = "TurboShards"
			a.Parent = h
			-- (a pane going: a white pop, then the glass and the dust blown out)
			W.sides[s] = {
				att = a,
				pop = EK.emitter(a, { tex = EK.TEX.glow, color = { Color3.new(1, 1, 1), TP.TURBO_CYAN }, size = { { 0, 2.6 }, { 1, 4.2 } }, transp = { { 0, 0.1 }, { 1, 1 } },
					life = { 0.12, 0.16 }, speed = { 0, 0 }, light = 1, bright = 2, rot = { 0, 0 } }),
				glints = EK.emitter(a, { tex = EK.TEX.spark, color = { Color3.new(1, 1, 1), TP.TURBO_CYAN }, size = { { 0, 0.75 }, { 1, 0 } }, transp = 0, life = { 0.45, 0.85 },
					speed = { 18, 38 }, spread = 45, accel = Vector3.new(0, -40, 0), light = 1 }),
				dust = EK.emitter(a, { tex = EK.TEX.smoke, color = { Color3.fromRGB(205, 205, 210), TP.DUST }, size = { { 0, 1.8 }, { 1, 5 } }, transp = { { 0, 0.25 }, { 1, 1 } },
					life = { 0.6, 1 }, speed = { 8, 14 }, spread = 35, drag = 3, influence = 1 }),
			}
		end
		local sa = Instance.new("Attachment")
		sa.Name = "TurboSpit"
		sa.Parent = h
		W.spit = { att = sa, pe = EK.emitter(sa, { tex = EK.TEX.spark, color = { Color3.new(1, 1, 1), TP.TURBO_CYAN }, size = { { 0, 0.4 }, { 1, 0 } }, transp = 0, life = { 0.3, 0.6 },
			speed = { 10, 22 }, spread = 50, accel = Vector3.new(0, -40, 0), light = 1 }) }
		-- (the wake: about 1.6 puffs a stud of his run, as the kit's dust wall)
		local wh = EK.holder(CFrame.new(groundPoint(last) + UP * 0.6), dur + 2.2, "TurboWake")
		wh.Size = Vector3.new(2.5, 0.6, 2.5)
		local wake = EK.emitter(wh, TT.WAKE, 1.12)
		wake.Shape = Enum.ParticleEmitterShape.Box
		local rate = low and 60 or 120
		task.spawn(function()
			local stage, prev = 0, last
			while os.clock() - t0 < dur + 0.05 and root.Parent and EK.alive(root.Parent) do
				local pos = root.Position
				while (pos - last):Dot(d) >= 6 and n < 40 do
					last += d * 6
					n += 1
					TT.burst(last, right, n, W)
				end
				-- (dust only while he's going)
				local moved = (pos - prev).Magnitude > 1
				prev = pos
				wh.CFrame = CFrame.new(groundPoint(pos) + UP * 0.6)
				wake.Rate = moved and rate or 0
				local s = math.clamp(math.floor((os.clock() - t0) / dur * 4), 0, 3)
				if s ~= stage then
					stage = s
					wake.Size = EK.ns(TT.WAKE.size, 1.12 * (1 + 0.15 * s))
				end
				task.wait()
			end
			wake.Rate = 0
		end)
	end
	-- one beat of it: a building's face either side (within 26 studs) blows
	-- out toward the street - glass shards (a few real ones) and glints and
	-- a puff of its dust; the street under him spits glints
	function TT.burst(p, right, n, W)
		local low = EK.lowEnd()
		for _, s in { 1, -1 } do
			local hit
			pcall(function()
				rayParams.FilterDescendantsInstances = characterList()
				hit = workspace:Raycast(p + UP * 3, right * s * 26, rayParams)
			end)
			if hit then
				local at, out = hit.Position, hit.Normal
				local side = W.sides[s]
				side.att.CFrame = W.holder.CFrame:ToObjectSpace(CFrame.lookAt(at, at + out))
				side.pop:Emit(1)
				side.glints:Emit(EK.count(8))
				side.dust:Emit(EK.count(4))
				if not low and n % 2 == 1 then -- (a real shard every 12 studs a side; the glints carry the rest)
					local shard = newPart(Vector3.new(rand(0.5, 0.9), 0.05, rand(0.35, 0.7)), CFrame.new(at + out * 0.2 + UP * rand(-1.5, 2.5)) * CFrame.Angles(rand(0, 6), rand(0, 6), 0), Color3.fromRGB(200, 240, 255), Enum.Material.Glass)
					shard.Name = "TurboShard"
					shard.Transparency = 0.25
					TT.fling({ { part = shard, vel = out * rand(14, 24) + UP * rand(4, 10), spin = Vector3.new(rand(-10, 10), rand(-10, 10), rand(-10, 10)) } }, 0.7)
				end
			end
		end
		if n % 2 == 0 then
			local g = groundPoint(p)
			W.spit.att.CFrame = W.holder.CFrame:ToObjectSpace(CFrame.lookAt(g + UP * 0.2, g + UP * 2))
			W.spit.pe:Emit(EK.count(6))
		end
		if n % 4 == 1 then
			VFX.PlaySound("MaxGlass", p, 0.8)
		end
	end
	-- the end of the run: his mufflers blow (pops at both calves, the tubes'
	-- pieces tumbling off, charcoal smoke pouring off him for ~3 s)
	function TT.blowOut(char, root)
		if not EK.alive(char) then
			return
		end
		VFX.PlaySound("MufflerBlow", root.Position, 1)
		EK.backfire(char, nil, { scale = 2.2, sound = false })
		local st = TT.state[char]
		for _, L in EK.legs(char) do
			local mid = st and st.bySide[L.side] and st.bySide[L.side][2]
			local at = mid and (mid.base + mid.dir * mid.w * 0.5) or EK.legPoint(L.leg, L.isR15, 0, -0.3, 0.8)
			local a = Instance.new("Attachment")
			a.Name = "TurboSmoke"
			a.CFrame = CFrame.new(at)
			a.Parent = L.leg
			if st then
				table.insert(st.legFx, a)
			end
			local pe = EK.emitter(a, TT.SMOKE)
			pe.Rate = EK.count(14)
			task.delay(2.6, function()
				pe.Rate = 0
			end)
			EK.gone(a, 4)
			local flash = EK.emitter(a, { tex = EK.TEX.glow, color = { Color3.fromRGB(255, 235, 190), TP.IGNITE_DEEP }, size = { { 0, 2 }, { 1, 4 } }, transp = { { 0, 0 }, { 1, 1 } },
				life = { 0.18, 0.22 }, speed = { 0, 0 }, light = 1, bright = 3, rot = { 0, 0 } })
			flash:Emit(1)
		end
		if st and not st.ending then
			local bits = {}
			for _, tube in st.tubes do
				for key, p in tube.parts do
					if (key == "s2" or key == "s3" or key == "tip") and (not EK.lowEnd() or tube.i ~= 2) then
						local piece = newPart(p.Size, p.CFrame, key == "tip" and TP.HOT_PIPE or TT.METAL, Enum.Material.Metal, Enum.PartType.Cylinder)
						piece.Name = "TurboTubePiece"
						local out = tube.leg.CFrame:VectorToWorldSpace(tube.dir)
						table.insert(bits, { part = piece, vel = out * rand(8, 16) + UP * rand(12, 22) + rng:NextUnitVector() * 4, spin = Vector3.new(rand(-14, 14), rand(-14, 14), rand(-14, 14)) })
					end
					p.LocalTransparencyModifier = 1
				end
			end
			TT.fling(bits, 1.1)
			st.blown = true
			st.regrowAt = os.clock() + 2
			st.goals = {}
			st.heat = 0
			TT.paint(st)
			-- (till they grow back: his old stubs on his calves, his exhaust out
			-- of them, no glow)
			TT.unmouth(st)
			TT.stubs(st, false)
			for _, g in st.glows do
				g.pe.Rate = 0
			end
		end
	end

	function Effects.ReciproMax(char, data, isLocal, ability)
		local root = charParts(char)
		if not root then
			return
		end
		local d = flatten(data.Dir, root)
		if isLocal then
			face(root, d)
			VFX.Hooks.Dim(0.6, 1.3)
		end
		local plan = TT.maxPlan(root, d)
		TT.maxRuns[char] = plan
		if isLocal then
			SHOTS.ReciproMax = TT.maxShots(root, d, plan)
		end
		cinematicFor(char, "ReciproMax", isLocal, ability and ability.Name or "RECIPRO: MAXIMUM BURST", TP.TURBO_SMEAR)
		local t0 = os.clock()
		local function at(t)
			local w = t - (os.clock() - t0)
			if w > 0 then
				task.wait(w)
			end
			return root.Parent ~= nil and EK.alive(char)
		end
		local st = TT.state[char]
		local S = root.Position
		local g = groundPoint(S)
		-- THE CHARGE
		TT.clip(char, "MoveIidaMaxSet", "IidaMaxSet", { lead = 0.6 })
		VFX.PlaySound("MaxCharge", S, 1)
		TT.ready(char)
		local _, jets = EK.jets(char, "max", 0.62, { len = 3.2 })
		for i, c in TP.MAX do
			task.delay((i - 1) * 0.15, function()
				if jets then
					jets.color(c)
				end
			end)
		end
		-- (the flare held down while the macro's on his tubes, 0.34-0.58)
		local stopHalo = TT.halo(root, d, 0.62, { 0.34, 0.58 })
		TT.web(g, 0.5)
		EK.cloud(g, 0.6, TP.DUST, 0.35, false)
		-- the tubes stretch out and heat along their length (magenta at the
		-- base, white at the mouths: the macro's subject), then go white-hot
		-- all over for the GO
		task.delay(0.36, function()
			if st and TT.state[char] == st and not st.blown and not st.ending then
				TT.ease(st, "len", TT.TUBE.Max, 0.16)
				st.mode = "turbo"
				TT.ease(st, "heat", 1, 0.14)
			end
			if jets then
				jets.setLen(4.5)
			end
		end)
		task.delay(0.5, function()
			if st and TT.state[char] == st and not st.blown and not st.ending then
				st.mode = "white"
				TT.paint(st)
			end
			EK.flash(char, nil, TP.TURBO_WHITE, 1.2)
		end)
		if isLocal then
			task.delay(0.5, EK.boreFlash)
		end
		if not at(0.6) then
			stopHalo()
			return
		end
		-- GO
		stopHalo()
		local from = root.Position
		if isLocal then
			dash(root, d * 320, 0.5)
		end
		if plan.tc - 0.68 >= 0.07 then -- (room for a run-up before the kick)
			TT.clip(char, "MoveIidaMaxRun", "IidaMaxRun")
		end
		task.delay(math.max(plan.tc - 0.08 - (os.clock() - t0), 0), function()
			if root.Parent and EK.alive(char) then
				-- (its Hit 0.08 ahead of the contact, held down the run)
				TT.clip(char, "MoveIidaMaxKick", "IidaMaxKick", { holdFor = math.max(0.92 - plan.tc, 0) })
			end
		end)
		TT.ready(char)
		local _, go = EK.jets(char, "max", 0.5, { len = 7 })
		if go then
			go.color(TP.TURBO_CYAN)
		end
		local MG = VFX.MANGA
		if MG then
			MG.flare(from + UP * 0.6, TP.TURBO_CYAN, 3.2, 0.5)
		end
		EK.starSpark(from + UP * 0.6, { size = 2.6, color = TP.TURBO_CYAN, color2 = Color3.new(1, 1, 1), life = 0.22 })
		EK.vaporRings(from + d * 2, d, 3, { size = 3.2 })
		-- (no cracks of its own: the web's there; the dust wake comes with the
		-- wave, under where he really runs)
		EK.machCone(root, 0.5, { size = 1.3 })
		EK.contrail(root, 0.55, { width = 1.2, life = 1.1 })
		TT.wave(root, d, 0.5)
		VFX.PlaySound("MaxGo", from, 1)
		VFX.ShakeAt(from, 2.4, 120, 0.35)
		task.spawn(function()
			local g0 = os.clock()
			while os.clock() - g0 < 0.5 and root.Parent and EK.alive(char) do
				EK.afterimage(char, TP.TURBO_GOLD, 0.35, { transparency = 0.5 })
				task.wait(EK.lowEnd() and 0.12 or 0.06)
			end
		end)
		-- (his own screen draws the hit as his kick reaches them - the server's
		-- word on it comes back a round trip later, when he's long past; like
		-- an M1, it's predicted: the one he'd hit still in the run's path)
		if isLocal and plan.target then
			task.delay(math.max(plan.tc - (os.clock() - t0), 0), function()
				local troot = plan.target:FindFirstChild("HumanoidRootPart")
				if troot and root.Parent and not plan.hit then
					local v = troot.Position - root.Position
					local along = v:Dot(d)
					if along > -20 and along < 20 and (v - d * along).Magnitude < 11 then
						plan.hit, plan.mine = true, true
						TT.impact(troot.Position, d, char, plan.target)
					end
				end
			end)
		end
		if not at(1.1) then
			return
		end
		-- THE END OF THE RUN (it caught nobody - nobody in his way, or they got
		-- out of it: the sonic boom where he stops. Everyone else's screen gives
		-- the server's word on a hit a moment longer to come)
		local function boom()
			if plan.hit or not root.Parent then
				return
			end
			local p = root.Position + d * 2
			TT.disc(p, d, 4, 10, 46, 0.12, 0.4, Color3.new(1, 1, 1))
			billboardRing(p, 3, 40, TP.TURBO_CYAN, 6, 0.4)
			EK.cloud(groundPoint(p), 1.4, TP.DUST, 0.6, true)
			VFX.PlaySound("ReciproBoom", p, 1)
			VFX.ShakeAt(p, 2, 140, 0.4)
		end
		if isLocal then
			boom()
		else
			task.delay(0.15, boom)
		end
		EK.cloud(groundPoint(root.Position), 1.2, TP.DUST, 0.55, false)
		TT.blowOut(char, root)
		TT.clip(char, "MoveIidaMaxLand", "IidaMaxLand")
	end
	-- the kick connecting, held (the anime's frozen frame; by the time it's
	-- drawn they're both long gone down the street): a gold ghost of him in
	-- his kick just short of the hit (his foot in them) and a violet one of
	-- them, drifting apart slowly while the ring opens, gone as it blows
	-- out. Either may be missing
	function TT.tableau(char, target, p, d)
		local list = {}
		local function add(body, at, color, transp, drift)
			local r = typeof(body) == "Instance" and (body:FindFirstChild("Torso") or body:FindFirstChild("UpperTorso") or body:FindFirstChild("HumanoidRootPart"))
			if not r then
				return
			end
			-- (moved along the street only, by his body's middle)
			local off = Vector3.new(at.X - r.Position.X, 0, at.Z - r.Position.Z)
			for _, part in body:GetChildren() do
				if part:IsA("BasePart") and part.Name ~= "HumanoidRootPart" and part.Transparency < 1 then
					local ghost = newPart(part.Size, part.CFrame + off, color, Enum.Material.Neon)
					ghost.Name = "TurboTableau"
					local mesh = part:FindFirstChildOfClass("SpecialMesh")
					if mesh and part.Name == "Head" then
						local m = Instance.new("SpecialMesh")
						m.MeshType = mesh.MeshType
						m.Scale = mesh.Scale
						m.Parent = ghost
					end
					ghost.Transparency = transp
					EK.gone(ghost, 0.8)
					table.insert(list, { part = ghost, cf0 = ghost.CFrame, drift = drift, t0 = transp })
				end
			end
		end
		add(char, p - d * 2.6, TP.TURBO_GOLD, 0.05, d * 0.7)
		add(target, p, TP.TURBO_VIOLET, 0.18, d * 1.8)
		if #list == 0 then
			return
		end
		TT.run(function(t)
			local fade = math.clamp((t - 0.3) / 0.3, 0, 1)
			for _, x in list do
				if x.part.Parent then
					x.part.CFrame = x.cf0 + x.drift * math.min(t / 0.6, 1)
					x.part.Transparency = x.t0 + (1 - x.t0) * fade
				end
			end
			return t >= 0.6
		end)
	end
	-- the server: the run caught someone (Target, Pos, Dir), now
	function Effects.ReciproMaxHit(char, data)
		local target = typeof(data.Target) == "Instance" and data.Target or nil
		local troot = target and target:FindFirstChild("HumanoidRootPart")
		local p = typeof(data.Pos) == "Vector3" and data.Pos or (troot and troot.Position)
		if not p then
			return
		end
		local plan = char and TT.maxRuns[char]
		if plan then
			plan.hit = true
			if plan.mine then
				return -- (his screen already drew it)
			end
		end
		TT.impact(p, typeof(data.Dir) == "Vector3" and TT.flat(data.Dir) or (plan and plan.d) or Vector3.new(0, 0, -1), char, target)
	end
	-- the hit itself, at p (the run going along d; char: him, target: them)
	function TT.impact(p, d, char, target)
		local g = groundPoint(p)
		local MG = VFX.MANGA
		if MG then
			MG.impact(p, 0.12, { Radius = 170, Flash = 0.1 })
		end
		TT.tableau(char, target, p, d)
		-- the slow-motion beat: what bursts off the hit crawls for 0.3 s
		local h = EK.holder(CFrame.lookAt(p, p + d), 2, "TurboImpact")
		local sparkle = EK.emitter(h, { tex = EK.TEX.spark, color = { Color3.new(1, 1, 1), TP.TURBO_CYAN, TP.TURBO_GOLD }, size = { { 0, 1 }, { 1, 0 } }, transp = 0,
			life = { 0.5, 0.9 }, speed = { 30, 60 }, spread = 70, drag = 2, light = 1 })
		local chunks = EK.emitter(h, { tex = EK.TEX.smoke, color = { Color3.new(1, 1, 1), TP.VAPOR }, size = { { 0, 2 }, { 1, 6 } }, transp = { { 0, 0.2 }, { 1, 1 } },
			life = { 0.6, 0.9 }, speed = { 20, 40 }, spread = 60, drag = 4, influence = 0.5 })
		for _, pe in { sparkle, chunks } do
			pe.TimeScale = 0.2
		end
		sparkle:Emit(EK.count(30))
		chunks:Emit(EK.count(8))
		task.delay(0.3, function()
			for _, pe in { sparkle, chunks } do
				pe.TimeScale = 1
			end
		end)
		-- (short, so the held kick reads through the slow-motion beat)
		EK.starSpark(p, { size = 7.5, color = TP.TURBO_CYAN, color2 = TP.TURBO_GOLD, life = 0.22 })
		EK.kickSmear(CFrame.lookAt(p - d * 2, p + d), { plane = "vertical", arc = 170, from = -70, radius = 5, color = TP.TURBO_SMEAR, core = TP.TURBO_CYAN, life = 0.7, draw = 0.08 })
		-- the huge ring: open slowly, then blown out
		TT.disc(p, d, 4, 12, 60, 0.3, 0.45, Color3.new(1, 1, 1))
		TT.disc(g + UP * 0.4, UP, 6, 16, 90, 0.3, 0.55, TP.TURBO_CYAN)
		task.delay(0.3, function()
			billboardRing(p, 8, 70, Color3.new(1, 1, 1), 10, 0.45)
			EK.cloud(g, 2, TP.DUST, 0.7, true)
			VFX.ShakeAt(p, 4, 220, 0.6)
		end)
		-- the crater
		EK.cracks(p, 11, 8, { glow = TP.TURBO_CYAN, life = 3.5 })
		rocks(g, 1.1, EK.count(8))
		VFX.PlaySound("MaxImpact", p, 1)
		VFX.ShakeAt(p, 2.4, 220, 0.3)
	end

	-- (round 85) the prank's muffler is one of his tubes: pulled out of his
	-- right calf (hidden there, growing back after `back` s)
	function TT.pluck(char, side, back)
		local st = TT.state[char]
		local tube = st and st.bySide[side or "Right"] and st.bySide[side or "Right"][2]
		if not tube then
			return nil
		end
		for _, p in tube.parts do
			p.LocalTransparencyModifier = 1
		end
		task.delay(back or 1.4, function()
			if TT.state[char] == st and not st.blown then
				for _, p in tube.parts do
					p.LocalTransparencyModifier = 0
				end
				EK.flash(char, side or "Right", TP.TURBO_WHITE, 0.8)
			end
		end)
		return tube.leg.CFrame * CFrame.lookAt(tube.base + tube.dir * st.len * tube.w * 0.5, tube.base + tube.dir * 2)
	end

	-- ((round 101, awaken_e) his awakening's camera is the kit's now - its
	-- two shots, every eye pulled in short of a wall: VFX.AK.shots)

	-- R15 bodies (no clips) play these
	MOTIONS.IidaTurboAwaken = {
		{ pose = { Waist = { -30, -30, 0 }, RightArm = { -60, 0, 15 }, LeftArm = { 60, 0, 20 }, RightLeg = -70, LeftKnee = 20 }, t = 0.07, hold = 0.03 },
		{ pose = { Waist = { -15, -40, 0 }, RightArm = { -150, 0, 40 }, LeftArm = { 60, 0, 20 }, RightLeg = -30, LeftKnee = 20 }, t = 0.05, hold = 0.08, style = SNAP },
		{ pose = "Rev", t = 0.15, hold = 0.55 },
		{ pose = { Waist = { -20, 0, 0 }, RightArm = { -80, 0, 30 }, LeftArm = { -80, 0, 30 }, RightLeg = 80, RightKnee = 90, LeftLeg = -20 }, t = 0.06, hold = 0.25, style = Enum.EasingStyle.Back },
		recover = 0.3,
	}
	MOTIONS.IidaTurboKick = {
		{ pose = { Waist = { 10, 80, 30 }, RightLeg = { 100, 0, 0 }, LeftLeg = -20, LeftKnee = 40, RightArm = { 10, 0, 30 }, LeftArm = { -60, 0, 30 } }, t = 0.04, hold = 0.25 },
		recover = 0.25,
	}
	MOTIONS.IidaRushR = { { pose = { Waist = { 10, 80, 30 }, RightLeg = { 98, 0, 0 }, LeftLeg = -25, LeftKnee = 40, LeftArm = { -60, 0, 30 } }, t = 0.04, hold = 0.12 }, recover = 0.2 }
	MOTIONS.IidaRushL = { { pose = { Waist = { 10, -80, -30 }, LeftLeg = { 98, 0, 0 }, RightLeg = -25, RightKnee = 40, RightArm = { -60, 0, 30 } }, t = 0.04, hold = 0.12 }, recover = 0.2 }
	MOTIONS.IidaRushFinish = {
		{ pose = { Waist = { -10, -60, 0 }, Crouch = 0.3, RightArm = { 30, 0, 40 }, LeftArm = { 30, 0, 40 } }, t = 0.06 },
		{ pose = { Waist = { -50, -170, 0 }, RightLeg = { 95, 0, 0 }, LeftKnee = 20, RightArm = { 0, 0, 85 }, LeftArm = { 0, 0, 85 } }, t = 0.04, hold = 0.2, style = SNAP },
		recover = 0.3,
	}
	MOTIONS.IidaMaxSet = { { pose = "Rev", t = 0.12, hold = 0.48 }, recover = 0.15 }
	MOTIONS.IidaMaxRun = {
		{ pose = { Waist = { -55, 0, 0 }, RightLeg = 50, LeftLeg = -50, RightArm = { -70, 0, 10 }, LeftArm = { 50, 0, 10 } }, t = 0.05 },
		{ pose = { Waist = { -55, 0, 0 }, RightLeg = -50, LeftLeg = 50, RightArm = { 50, 0, 10 }, LeftArm = { -70, 0, 10 } }, t = 0.05 },
		recover = 0.15,
	}
	MOTIONS.IidaMaxKick = {
		{ pose = { Waist = { 8, 88, 55 }, RightLeg = { 102, 0, 0 }, LeftLeg = -15, LeftKnee = 30, RightArm = { -150, 0, 10 }, LeftArm = { -60, 0, 30 } }, t = 0.06, hold = 0.4 },
		recover = 0.2,
	}
	MOTIONS.IidaMaxLand = {
		{ pose = { Waist = { -35, 10, 0 }, Crouch = 0.4, RightArm = { 90, 0, 40 }, LeftArm = { 70, 0, 50 } }, t = 0.12 },
		{ pose = { Waist = { -55, -14, 0 }, Crouch = 0.8, RightArm = { 5, 0, 10 }, LeftArm = { -30, 0, 30 } }, t = 0.14, hold = 0.4 },
		recover = 0.35,
	}

	-- the in-ult look's clock
	task.spawn(function()
		while true do
			local ok, err = pcall(TT.tick)
			if not ok then
				warn("[VFX] turbo tubes: " .. tostring(err))
				task.wait(1)
			end
			task.wait(TT.DRIVE.Every)
		end
	end)
end

---------------------------------------------------------------------------
-- MOVEMENT: quirk-flavoured dashes
---------------------------------------------------------------------------

-- Per-quirk extras registered further down (quirks added later in the file)
local QUIRK_FX = { Dash = {}, Ult = {} }

function Effects.Dash(char, data)
	local root = charParts(char)
	if not root then
		return
	end
	local dir = typeof(data.Dir) == "Vector3" and data.Dir.Magnitude > 0.1 and data.Dir.Unit or root.CFrame.LookVector
	local kind = data.Kind or "Front"
	if kind == "Side" then
		kind = "Right"
	elseif kind == "Chase" then
		kind = "Front" -- (round 65: JJS's anti-run dash - a front dash without the punch)
	end
	VFX.DashMotion(char, "Dash" .. kind)
	local g = groundPoint(root.Position)
	local grounded = (root.Position - g).Magnitude < 5
	local DUST = Color3.fromRGB(205, 196, 190)
	if grounded then
		-- kicked-up dust where they pushed off (a ring for the hop's takeoff)
		dustPuffs(g - dir * 1.5, kind == "Back" and 1 or 0.8, kind == "Back" and 6 or 4, DUST, 0.7, false)
		if kind == "Front" then
			shockDisc(g + UP * 0.4, UP, 2, 12, 0.25, WIND)
		end
	end
	streaks(root.Position, -dir, 8, 1.5, 6, 12, WIND, 0.22)
	-- afterimages strung along the path
	local ghost = (data.Quirk == "OneForAll" and GOLD) or (data.Quirk == "FullCowl" and Color3.fromRGB(120, 255, 160))
		or (data.Quirk == "Engine" and EXHAUST) or Color3.fromRGB(225, 235, 255)
	-- (the back dash: a ghost at every beat of the flip, a quick string of
	-- them through the twist, one on his hands and one as he lands - round 66)
	local B = Config.Movement.BackDashBeats or { Twist = 0.3, Hands = 0.52, Land = 0.74 }
	local beats = kind == "Back" and { 0, 0.07, 0.14, 0.2, B.Twist + 0.01, B.Twist + 0.045, B.Twist + 0.08, B.Twist + 0.11, B.Hands, B.Land }
		or { 0, 0.06, 0.12 }
	for _, at in beats do
		task.delay(at, function()
			if root.Parent then
				afterimage(char, ghost, 0.22)
			end
		end)
	end
	if kind == "Back" then
		-- (round 66) the twist: rings of wind round him as he spins
		for k = 0, 1 do
			task.delay(B.Twist + k * 0.07, function()
				if root.Parent then
					shockDisc(root.Position, dir, 1.5, 7, 0.2, WIND, 4)
					if k == 0 then
						VFX.PlaySound("BackTwist", root.Position, 0.7)
					end
				end
			end)
		end
		-- (round 65) his hands hit the street in the handstand
		task.delay(B.Hands, function()
			if not root.Parent then
				return
			end
			local plant = groundPoint(root.Position)
			if (root.Position - plant).Magnitude < 5 then
				dustPuffs(plant, 0.55, 3, DUST, 0.5, false)
				shockDisc(plant + UP * 0.3, UP, 1, 5, 0.18, WIND)
				VFX.PlaySound("PkRoll", plant, 0.45)
			end
		end)
	end
	-- the skid when a sidestep stops, the landing when the hop comes down
	task.delay(kind == "Back" and B.Land or 0.2, function()
		if not root.Parent then
			return
		end
		local land = groundPoint(root.Position)
		if (root.Position - land).Magnitude < 5 then
			dustPuffs(land + dir * 1.5, kind == "Back" and 1.1 or 0.7, kind == "Back" and 5 or 3, DUST, 0.6, false)
			if kind == "Back" then
				-- (round 66) the superhero landing: a thud, a ring along the street
				shockDisc(land + UP * 0.3, UP, 2, 14, 0.3, WIND)
				dustPuffs(land, 1.4, 6, DUST, 0.8, false)
				VFX.PlaySound("HeroLand", land, 0.8)
				VFX.ShakeAt(land, 0.5, 18, 0.12)
			elseif kind ~= "Front" then
				VFX.PlaySound("Skid", land, 0.6)
			end
		end
	end)
	local quirk = data.Quirk
	if quirk == "Explosion" then
		for k = 0, 1 do
			task.delay(k * 0.06, function()
				if root.Parent then
					toonExplosion(root.Position - dir * 3, 0.9, { NoDebris = true, NoScorch = true, NoEmbers = true, SmokeLife = 0.6 })
				end
			end)
		end
		legTrails(char, 0.25, FIRE[3])
	elseif quirk == "OneForAll" then
		shockDisc(root.Position - dir * 2, -dir, 2, 12, 0.25, WIND, 6)
		for _ = 1, 3 do
			bolt(root.Position, 2.5, GOLD)
		end
		legTrails(char, 0.25, GOLD)
	elseif quirk == "HalfCold" then
		-- (round 81) the fire side kicks off in a burst of flame; the ice side
		-- skates - a slick of ice laid under the dash, crystals spraying up
		-- and out either side of it like a blade's wake, chips flying off the
		-- push-off, and it all breaks up behind him
		if data.Alt then
			for k = 1, 4 do
				Flame.spot(g + UP * 0.2 - dir * k * 2, rand(2.5, 3.5), 0.3, 1.5)
			end
			if grounded then
				Flame.burst(g + UP - dir * 1.5, 2.2, 6)
			end
		elseif grounded then
			local flat = Vector3.new(dir.X, 0, dir.Z)
			flat = flat.Magnitude > 0.05 and flat.Unit or Vector3.new(0, 0, -1)
			local right = flat:Cross(UP)
			local model = outlineModel(ICE_OUTLINE)
			local slick = newPart(Vector3.new(2.2, 0.25, 0.2), CFrame.lookAt(g + UP * 0.1, g + UP * 0.1 + flat), ICE_TOP, Enum.Material.Ice, nil, model)
			tween(slick, 0.16, { Size = Vector3.new(2.4, 0.25, 13), CFrame = CFrame.lookAt(g + UP * 0.1 + flat * 6.5, g + UP * 0.1 + flat * 7.5) })
			local list = {}
			for k = 1, 6 do
				local side = k % 2 == 0 and 1 or -1
				local base = g + flat * (k * 2) + right * side * rand(0.9, 1.4) - UP * 0.3
				local tilt = (UP * 0.9 + right * side * rand(0.6, 0.9) - flat * 0.5).Unit
				table.insert(list, { set = makeSpike(model, base, tilt, rand(1.7, 2.4) + k * 0.18, 1, false, { quiet = true, shards = 0, flat = true }), delay = k * 0.025 })
			end
			growSpikes(list, 0.08)
			IceKit.particles(g - flat + UP * 0.4, "chips", 8, 0.6)
			IceKit.particles(g - flat + UP * 0.4, "puff", 5, 0.7)
			task.delay(0.8, function()
				shatter(model, 10, { from = g, instant = true, quiet = true })
			end)
		else
			IceKit.particles(root.Position - dir * 1.5, "mist", 6, 0.6)
		end
		legTrails(char, 0.25, data.Alt and FIRE[3] or Color3.fromRGB(150, 212, 255))
	elseif quirk == "Engine" then
		exhaust(char, 0.25, 1.4)
		afterimage(char, EXHAUST, 0.25)
		legTrails(char, 0.25, EXHAUST)
	elseif QUIRK_FX.Dash[quirk or ""] then -- (round 83: Decay's is in the Decay block)
		QUIRK_FX.Dash[quirk](char, root, dir, data)
	else
		legTrails(char, kind == "Back" and 0.85 or 0.25, WIND)
	end
	VFX.PlaySound("Dash", root.Position, 0.5)
end

