function Effects.DashPunch(char, data)
	local root = charParts(char)
	local target = typeof(data.Target) == "Instance" and data.Target or nil
	local troot = target and target:FindFirstChild("HumanoidRootPart")
	if not root then
		return
	end
	local d = flatten(data.Dir, root)
	VFX.Motion(char, "DashPunch")
	-- (the stomach, not the face)
	local hit = troot and (troot.Position - d * 1.1 - UP * 0.5) or (root.Position + d * 4 - UP * 0.5)
	swingSmear(root, "Straight", root.Position + d * 3 - UP * 0.3, M1_TRAIL[char:GetAttribute("Quirk") or ""] or WIND, true)
	shockDisc(hit, -d, 1, 7, 0.16, WIND, 2)
	streaks(hit, d, 7, 1.2, 4, 8, WIND, 0.18)
	VFX.PlaySound("Hit", hit, 0.9)
	if not troot then
		return
	end
	-- the wind knocked out of them: a burst out through their back, a puff
	-- at the mouth, and they fold over the fist for the stun
	shockDisc(troot.Position + d * 0.7 - UP * 0.4, d, 0.8, 5, 0.2, WIND, 3)
	local head = target:FindFirstChild("Head")
	if head then
		dustPuffs(head.Position - d * 0.9 - UP * 0.3, 0.3, 3, Color3.fromRGB(236, 240, 246), 0.35, false)
	end
	local time = ((Config.Movement or {}).DashPunch or {}).Stun or 1.1
	VFX.MuteGait(target, time)
	task.delay(0.08, function() -- (after the hit's own flinch)
		if troot.Parent then
			VFX.Pose(target, "Winded", time - 0.08)
		end
	end)
end

-- The ragdoll cancel: a burst of wind as they spring up, afterimages along
-- the quickstep, and (on their own machine) the quickstep itself
function Effects.Evasive(char, data)
	local root, hum = charParts(char)
	if not root then
		return
	end
	local d = flatten(data.Dir, root)
	local g = groundPoint(root.Position)
	billboardRing(root.Position, 2, 16, Color3.fromRGB(225, 245, 255), 4, 0.3)
	shockDisc(g + UP * 0.3, UP, 3, 18, 0.3, WIND)
	dustPuffs(g, 1.1, 7, Color3.fromRGB(215, 222, 230), 0.8, false)
	streaks(root.Position, -d, 10, 2, 6, 12, WIND, 0.25)
	VFX.PlaySound("Dash", root.Position, 0.8)
	for i = 0, 2 do
		task.delay(0.03 + i * 0.05, function()
			if root.Parent then
				afterimage(char, Color3.fromRGB(200, 235, 255), 0.25)
			end
		end)
	end
	if Players.LocalPlayer and Players.LocalPlayer.Character == char and hum then
		task.spawn(function()
			-- wait for the body to be ours again (the server just stood it up)
			local t0 = os.clock()
			while char:GetAttribute("Ragdolled") and os.clock() - t0 < 0.5 do
				task.wait()
			end
			if not root.Parent or hum.Health <= 0 then
				return
			end
			local q = (Config.Evasive and Config.Evasive.Quickstep) or {}
			local right = root.CFrame.RightVector
			VFX.DashMotion(char, (Vector3.new(right.X, 0, right.Z):Dot(d) >= 0) and "DashRight" or "DashLeft")
			dash(root, d * (q.Speed or 75), q.Time or 0.18)
		end)
	end
end

---------------------------------------------------------------------------
-- ULTIMATES: awakening + end
---------------------------------------------------------------------------

-- (round 101) every hero's awakening runs on the kit (VFX.AK, below): the
-- press, the gather, the pose's hit, the hold, the release - JJS-style
function Effects.UltActivate(char, data, isLocal)
	return VFX.AK.play(char, data, isLocal)
end

-- (round 101) All Might's old awakening pieces (they were inline in
-- UltActivate): his legacy burst, which VFX.AK runs on the hit until his
-- builder gives him his own VFX.AK.FX entry. (The shared pillar of light,
-- the 80-stud disc and the flash they used to sit on are retired: the
-- kit's burst.)
do
	-- ((round 101, awaken_p) All Might's is his own now: VFX.AK.FX.OneForAll)
	-- ((round 101, awaken_e) Todoroki's and Iida's: their own VFX.AK.FX
	-- entries now - PHOSPHOR and RECIPRO TURBO after the kit, below)
end

---------------------------------------------------------------------------
-- (round 101) THE AWAKENING KIT (VFX.AK): every hero's ult activation the
-- JJS way, on one timeline (Config.Awaken). The press cuts straight to a
-- close frontal shot while his body does one small thing (the gather); on
-- his pose's HIT the pose snaps and a hitstop holds it, the camera cuts to
-- the cut-in's frame with a kick, the impact frames flash, round 100's
-- cut-in lands (HUD.MO.ult through VFX.Hooks.UltCut), the burst and the
-- street's ring go off, his theme comes in and he says his line; the pose
-- holds; at the release the camera cuts back and he's free. Everyone else's
-- camera stays free: they see his body, the burst, the aura and a shout panel
-- over him.
-- A hero's own part is VFX.AK.FX[quirk] = { press, gather, hit, hold, release,
-- aura, impact } - each optional, each called with the run's ctx (aura
-- returns its stop; impact returns how long its frames run). A hero without
-- one runs his old awakening (QUIRK_FX.Ult) on the hit - or at the press, for
-- one that times itself (his Config.Awaken.Heroes row: Legacy = "press").
-- ctx = { char, root, hum, q, spec (his row), quirk, ult, color, accent, g
-- (the street under him; nil in the air), d (his facing, flat), scale, t0
-- (his pose clock at the press), w0 (os.clock at the press), hit, gather,
-- hold, release (seconds from the press), clip, headY, mine, low, phone,
-- beats (when each beat really went, from the press), props; from the hit:
-- after (how long his screen's impact frames run - 0 on anyone else's: a
-- big thing spawned on the hit waits it out), blasts (AK.blast's log) }.
-- ((round 101 review) the kit's own Highlights - his rim, the pair's
-- cut-out - never sit over or under another one on his body (AK.rimShow).)
-- Everything it makes goes at the release, on his death, another hero, the
-- ult ending or a newer run on the same body.
-- (Its own function: the main chunk's locals stay as they are.)
---------------------------------------------------------------------------
;(function()
	local AK = { FX = {}, runs = {}, locks = {}, rims = {}, auras = {}, lights = {}, held = {}, hush = {} }
	VFX.AK = AK
	local V3 = Vector3.new
	local TAU = math.pi * 2
	local Lighting = game:GetService("Lighting")
	local DUST = Color3.fromRGB(206, 196, 186)
	local CRACK = Color3.fromRGB(46, 42, 40)
	local function cfg()
		return Config.Awaken or {}
	end
	-- the template's clips' named keys (anim/moves_awaken.py), for a place
	-- without them
	AK.MARKS = {
		MoveAwaken = { Gather = 0.18, Hit = 0.3, Hold = 0.42, HoldEnd = 1.38 },
		MoveAwakenExplosion = { Gather = 0.18, Hit = 0.3, Hold = 0.42, HoldEnd = 1.38 },
	}

	---------------------------------------------------------------- basics
	-- his row of Config.Awaken.Heroes (never nil)
	function AK.spec(q)
		local row = (cfg().Heroes or {})[q or ""]
		return type(row) == "table" and row or {}
	end
	-- a low-end machine (the graphics slider, or under 40 fps)
	function AK.low()
		return IceKit.lowEnd()
	end
	-- a phone (touch, no keyboard)
	function AK.phone()
		local ok, phone = pcall(function()
			local uis = game:GetService("UserInputService")
			return uis.TouchEnabled and not uis.KeyboardEnabled
		end)
		return ok and phone == true
	end
	-- the body is yours AND you drive it (a body a dev is in gets the
	-- witness's version on its owner's screen)
	function AK.mine(char, isLocal)
		return isLocal == true and typeof(char) == "Instance" and char:GetAttribute("Possessed") ~= true
	end
	-- a clip's named key (Gather / Hit / Hold / HoldEnd), nil without one
	function AK.mark(clip, key)
		local IK = VFX.IidaKicks
		local v = IK and IK.mark and IK.mark(clip, key)
		if type(v) == "number" and v > 0 then
			return v
		end
		local m = AK.MARKS[clip or ""]
		return m and m[key] or nil
	end
	-- his body's scale once he's awakened: the ult's R6Scale if he hasn't
	-- grown yet (the server grows him on the hit; the shots are framed for it)
	function AK.scale(char, q)
		local torso = char and char:FindFirstChild("Torso")
		local s = torso and math.clamp(torso.Size.Y / 2, 0.25, 6) or 1
		local quirk = Config.Quirks[q or ""]
		local bs = quirk and quirk.Ult and quirk.Ult.BodyScale
		local post = bs and tonumber(bs.R6Scale) or 1
		if post > 1 and s < post - 0.02 then
			-- ((round 101, awaken_p) he grows from the form he's in now to the
			-- ult's: the same body x post / that form's own scale - Prime All
			-- Might's 1.45 -> 1.55, All Might's muscle 1.4 -> 1.5 - not x post
			-- on top of it)
			local now = 1
			for _, form in { quirk, quirk and quirk.Alt } do
				local fs = type(form) == "table" and type(form.BodyScale) == "table" and tonumber(form.BodyScale.R6Scale)
				if fs and math.abs(s - fs) < math.abs(s - now) then
					now = fs
				end
			end
			s *= post / now
		end
		return s
	end
	-- a clip's track at t (sampled the way VFX.Clip plays it)
	local function trackAt(tr, t)
		local times, cfs = tr.times, tr.cfs
		local n = #times
		if n == 0 then
			return CFrame.new()
		elseif t <= times[1] then
			return cfs[1]
		elseif t >= times[n] then
			return cfs[n]
		end
		local i = 1
		while times[i + 1] <= t do
			i += 1
		end
		local a = (t - times[i]) / math.max(times[i + 1] - times[i], 1e-6)
		local style = tr.styles[i]
		if style == "Constant" then
			a = 0
		elseif style ~= "Linear" then
			a = TweenService:GetValue(a, tr.easing[i], tr.dirs[i])
		end
		return cfs[i]:Lerp(cfs[i + 1], a)
	end
	-- the head's height over the root t seconds into a clip, on a stock 2-stud
	-- R6 body (times his scale for him); nil without the clip
	function AK.headAt(clipName, t)
		local clip = VFX.GetClip(tostring(clipName or ""))
		if not clip then
			return nil
		end
		local waist = clip.tracks.Waist and trackAt(clip.tracks.Waist, t) or CFrame.new()
		local neck = clip.tracks.Neck and trackAt(clip.tracks.Neck, t) or CFrame.new()
		local rj, nk = R6_STOCK.RootJoint, R6_STOCK.Neck
		local head = rj * waist * rj:Inverse() * nk * neck * (CFrame.new(0, -0.5, 0) * nk.Rotation):Inverse()
		local y = head.Position.Y
		return y == y and y or nil
	end
	-- when his activation's pose lands (seconds from the press): his row's
	-- HitAt, else his clip's Hit (inside Config.Awaken.Window), else HitAt.
	-- (The server's blast uses his row's HitAt or HitAt: a hero's clip keeps
	-- its Hit there.)
	function AK.hitFor(q)
		local A = cfg()
		local spec = AK.spec(q)
		if tonumber(spec.HitAt) then
			return tonumber(spec.HitAt)
		end
		local clip = VFX.GetClip(tostring(spec.Clip or "MoveAwaken"))
		local w = A.Window or { 0.15, 1 }
		if clip and clip.hit and clip.hit >= w[1] and clip.hit <= w[2] then
			return clip.hit
		end
		return A.HitAt or 0.3
	end
	-- his ult as his body or his player says it (nil: nobody's said)
	function AK.ultOn(char)
		local v = char:GetAttribute("UltActive")
		local plr = Players:GetPlayerFromCharacter(char)
		local pv = plr and plr:GetAttribute("UltActive")
		if v == true or pv == true then
			return true
		elseif v == false or pv == false then
			return false
		end
		return nil
	end
	-- the run is still on: him there and alive, this his newest run, the same
	-- hero, nobody new in his body, the ult not over
	function AK.alive(ctx)
		local char, hum = ctx.char, ctx.hum
		if ctx.dead or not char.Parent or not ctx.root.Parent or not hum.Parent or hum.Health <= 0 or AK.runs[char] ~= ctx then
			return false
		end
		if ctx.was ~= nil and char:GetAttribute("Quirk") ~= ctx.was then
			return false
		end
		if char:GetAttribute("Possessed") == true and not ctx.possessed then
			return false
		end
		local on = AK.ultOn(char)
		if on then
			ctx.seen = true
		elseif ctx.seen and on == false then
			return false
		end
		return true
	end
	-- seconds since the press: his pose clock (anyone's hitstop on him and the
	-- director's slow motion hold it back with his clip), plus the kit's own
	-- hitstop as it's served - so a beat at t lands t seconds after the press
	function AK.now(ctx)
		local served = ctx.hitAt and math.clamp(os.clock() - ctx.hitAt, 0, ctx.stop or 0) or 0
		return poseTime(ctx.char, os.clock()) - ctx.t0 + served
	end
	-- wait till t seconds after the press; false once the run's over
	function AK.at(ctx, t)
		while AK.alive(ctx) do
			local left = t - AK.now(ctx)
			if left <= 0 then
				return true
			end
			task.wait(math.min(left, 0.05))
		end
		return false
	end
	-- (tests: when each beat really went, os.clock seconds after the press)
	function AK.note(ctx, name)
		ctx.beats[name] = ctx.beats[name] or (os.clock() - ctx.w0)
	end
	-- a hero's own part, called safely (nil: none)
	function AK.call(ctx, phase)
		local fn = ctx.fx[phase]
		if type(fn) ~= "function" then
			return nil
		end
		local ok, res = pcall(fn, ctx)
		if not ok then
			warn("[VFX] AK " .. tostring(ctx.q) .. "." .. phase .. ": " .. tostring(res))
			return nil
		end
		return res
	end

	---------------------------------------------------------------- the camera
	-- (the lens rule, his own screen) true when pos (radius r) would sit on
	-- his cutscene camera: within Lens studs of an eye of his shots, or on the
	-- line from one to him. Never for anyone else.
	function AK.lens(ctx, pos, r)
		if not ctx.mine or not ctx.eyes or typeof(pos) ~= "Vector3" or pos ~= pos then
			return false
		end
		local lens = (cfg().Lens or 4) + (tonumber(r) or 0)
		local head = ctx.headPoint
		for _, eye in ctx.eyes do
			if (pos - eye).Magnitude < lens then
				return true
			end
			local seg = head - eye
			local len2 = seg:Dot(seg)
			if len2 > 0.01 then
				local k = math.clamp((pos - eye):Dot(seg) / len2, 0, 1)
				if k < 0.9 and (eye + seg * k - pos).Magnitude < lens * 0.6 then
					return true
				end
			end
		end
		return false
	end
	-- ((round 101 review) how far a toon explosion of this scale reaches (its
	-- flash grows to 15x its scale across): the radius to give AK.lens for one
	function AK.reach(scale)
		return (cfg().BlastReach or 7.5) * (tonumber(scale) or 1)
	end
	-- ((round 101 review) a toon explosion for an awakening: kept off his lens
	-- by its real reach, and logged in ctx.blasts ({ at, reach, name }) for
	-- tests. Returns true if it went off.
	--   VFX.AK.blast(ctx, ctx.root.Position - ctx.d * 4, 0.6, { NoScorch = true }, "backBlast")
	function AK.blast(ctx, at, scale, opts, name)
		local reach = AK.reach(scale)
		if typeof(at) ~= "Vector3" or at ~= at or AK.lens(ctx, at, reach) then
			return false
		end
		if name then
			AK.note(ctx, name)
		end
		ctx.blasts = ctx.blasts or {}
		table.insert(ctx.blasts, { at = at, reach = reach, name = name })
		toonExplosion(at, scale, opts)
		return true
	end
	-- his facing frame at the press (+X his right, -Z ahead; built from the
	-- axes - the same frame VFX.Cinematic's lookAt gives in Roblox)
	function AK.basis(ctx)
		return CFrame.fromMatrix(ctx.root.Position, ctx.d:Cross(UP), UP)
	end
	-- an eye (basis space) pulled in toward `from` (basis space) short of a wall
	function AK.clear(basis, eye, from)
		local we, wa = basis * eye, basis * from
		local d = we - wa
		if d.Magnitude < 0.05 then
			return eye
		end
		rayParams.FilterDescendantsInstances = characterList()
		local ok, hit = pcall(function()
			return workspace:Raycast(wa, d, rayParams)
		end)
		if ok and hit then
			local dist = tonumber(hit.Distance) or (hit.Position - wa).Magnitude
			local keep = math.max(dist - ((cfg().Shots or {}).Clear or 1.2), 1.5)
			return basis:PointToObjectSpace(wa + d.Unit * math.min(keep, d.Magnitude))
		end
		return eye
	end
	-- his two shots (his facing frame at the press, x his scale): A, close and
	-- frontal at chest height, creeping in to the hit; B, the cut-in's frame -
	-- off his head at the hit (him left of centre, a touch of up-look), the kick
	-- on its cut, creeping in to the release. Every eye pulled in short of a
	-- wall. Fills ctx.eyes / ctx.headPoint (world) for the lens rule.
	function AK.shots(ctx)
		local A = cfg()
		local SH = A.Shots or {}
		local SA, SB = SH.A or {}, SH.B or {}
		local s = ctx.scale
		local over = type(ctx.spec.Shot) == "table" and ctx.spec.Shot or {}
		local drop = (tonumber(over.Low) or 0) - (tonumber(over.High) or 0)
		local side = (tonumber(over.Side) or SB.Side or -1) * s
		-- ((round 101, awaken_p) a body that grows on the hit (BodyScale: the
		-- server scales him then) stands taller on it - his root rises with his
		-- longer legs (an R6 root stands 3 x his scale over the street): shot B,
		-- framed off his head at the hit, rises with it)
		local torso = ctx.char:FindFirstChild("Torso")
		local rise = torso and math.max(s - torso.Size.Y / 2, 0) * 3 or 0
		local ty = ctx.headY + rise - ((SB.HeadDrop or 1.36) + drop) * s
		local ey = ty - (SB.Below or 0.65) * s
		local dist = SB.Dist or { 8.4, 7.8 }
		local extra = tonumber(over.Dist) or 0
		local basis = AK.basis(ctx)
		local head = V3(0, ctx.headY, 0)
		local function eye(v)
			return AK.clear(basis, v, head)
		end
		local kick = A.Kick or {}
		local shake = (kick.Shake or 0) * (ctx.phone and ((A.Phone or {}).Shake or 0.6) or 1)
		local aFrom, aTo = SA.From or { V3(0, 0.3, -9), V3(0, 0.5, 0) }, SA.To or { V3(0, 0.35, -8.2), V3(0, 0.55, 0) }
		local shotA = {
			T = ctx.hit, Quiet = true, Style = Enum.EasingStyle.Quart, Dir = Enum.EasingDirection.Out,
			From = { eye(aFrom[1] * s), aFrom[2] * s }, To = { eye(aTo[1] * s), aTo[2] * s }, Fov = SA.Fov or { 46, 44 },
		}
		local shotB = {
			T = math.max(ctx.release - ctx.hit, 0.1), Cut = true, Quiet = true, Style = Enum.EasingStyle.Quart, Dir = Enum.EasingDirection.Out,
			From = { eye(V3(side, ey, -(dist[1] + extra) * s)), V3(side, ty, 0) },
			To = { eye(V3(side, ey, -(dist[2] + extra) * s)), V3(side, ty, 0) },
			Fov = SB.Fov or { 56, 54 },
			Kick = { Fov = kick.Fov, Time = kick.Time, Shake = shake, ShakeTime = kick.ShakeTime },
		}
		ctx.eyes = { basis * shotA.From[1], basis * shotA.To[1], basis * shotB.From[1], basis * shotB.To[1] }
		ctx.headPoint = basis * head
		return { shotA, shotB }
	end
	-- his own screen's camera: the two shots (none with cinematics off, or the
	-- director's camera up); no letterbox, no cut whoosh (the riser is the cut)
	function AK.camera(ctx)
		local Cn = Config.Cinematics or {}
		if not ctx.mine or Cn.Enabled == false or Cn.Awakenings == false then
			return false
		end
		local director = VFX.Director
		if director and director.on then
			return false
		end
		ctx.cine = VFX.Cinematic(ctx.char, ctx.shotList, { Own = true, Quiet = true, NoBars = true, Color = ctx.color }) == true
		ctx.cineToken = ctx.cine and VFX.CinematicToken() or nil
		return ctx.cine
	end
	-- (the director's camera on someone else's screen, letting his through:
	-- shot B from the hit, no cut-in)
	function AK.director(ctx)
		local director = VFX.Director
		if ctx.mine or not (director and director.on and director.cutFor) then
			return
		end
		local ok, cut = pcall(director.cutFor, ctx.char)
		if ok and cut then
			local shots = AK.shots(ctx)
			VFX.Cinematic(ctx.char, { shots[2] }, { Quiet = true, NoBars = true })
		end
	end

	---------------------------------------------------------------- his body's Highlights
	-- ((round 101 review) round 86's rule: never one Highlight under another.)
	-- The kit's own on a body - his rim (the burst's flare, the aura), the
	-- impact pair's cut-out - never sit over or under another one there (a
	-- hero's own rim, a silhouette, a move's glow, a zap): his rim stands aside
	-- while any other is on him, and the pair holds every other one off for its
	-- four frames - each put back exactly (counted holds: one record a
	-- Highlight, restored when the last hold lets go).
	-- (every Highlight in the effects folder, kept as they come)
	local added = 0
	local function lit(inst)
		if typeof(inst) == "Instance" and inst:IsA("Highlight") then
			AK.lights[inst] = true
			-- (the gone ones let go now and then: never a pile of dead ones held)
			added += 1
			if added % 32 == 0 then
				for h in AK.lights do
					if h.Parent == nil then
						AK.lights[h] = nil
					end
				end
			end
			task.defer(function()
				AK.rimsShow()
			end)
		end
	end
	pcall(function()
		for _, d in folder:GetDescendants() do
			lit(d)
		end
		folder.DescendantAdded:Connect(lit)
	end)
	-- is this Highlight on his body (its Adornee - else its parent - the body
	-- or a part or model of it)?
	local function onBody(h, char)
		local s = h.Adornee or h.Parent
		return s ~= nil and (s == char or s:IsDescendantOf(char))
	end
	-- every other Highlight showing on his body now (never the kit's own);
	-- deep: the effects folder looked through as well (once, for the pair)
	function AK.others(char, deep)
		local list, seen = {}, {}
		local function take(h)
			if not seen[h] and h.Parent and h.Enabled and h.Name ~= "AwakenRim" and h.Name ~= "AwakenCutout" and onBody(h, char) then
				seen[h] = true
				table.insert(list, h)
			end
		end
		if deep then
			for _, d in folder:GetChildren() do
				if d:IsA("Highlight") then
					AK.lights[d] = true
				end
			end
		end
		for h in AK.lights do
			if h.Parent == nil then
				AK.lights[h] = nil -- (gone)
			else
				take(h)
			end
		end
		for _, d in char:GetDescendants() do
			if d:IsA("Highlight") then
				take(d)
			end
		end
		return list
	end
	-- hold a Highlight off (the first hold saves how it was) / let it go (the
	-- last one puts it back exactly, in the world or not)
	function AK.holdOff(h)
		local rec = AK.held[h]
		if not rec then
			rec = { n = 0, was = h.Enabled }
			AK.held[h] = rec
		end
		rec.n += 1
		h.Enabled = false
	end
	function AK.letGo(h)
		local rec = AK.held[h]
		if not rec then
			return
		end
		rec.n -= 1
		if rec.n <= 0 then
			AK.held[h] = nil
			pcall(function()
				h.Enabled = rec.was
			end)
		end
	end
	-- his rim shows only while no other Highlight is on him and no impact
	-- pair holds it (AK.hush: the pairs holding it)
	function AK.rimShow(char)
		local h = char and AK.rims[char]
		if not (h and h.Parent) then
			return
		end
		local want = (AK.hush[char] or 0) <= 0 and #AK.others(char) == 0
		if h.Enabled ~= want then
			h.Enabled = want
		end
	end
	function AK.rimsShow()
		for char in AK.rims do
			AK.rimShow(char)
		end
	end

	---------------------------------------------------------------- the impact
	-- radial speed lines over the screen for the impact pair (nil: no PlayerGui)
	function AK.lines(ctx)
		local me = Players.LocalPlayer
		local pg = me and me:FindFirstChildOfClass("PlayerGui")
		if not pg then
			return nil
		end
		local cam = workspace.CurrentCamera
		local aspect = 16 / 9
		pcall(function()
			aspect = cam.ViewportSize.X / math.max(cam.ViewportSize.Y, 1)
		end)
		local sg = Instance.new("ScreenGui")
		sg.Name = "AwakenImpactLines"
		sg.IgnoreGuiInset = true
		sg.ResetOnSpawn = false
		sg.DisplayOrder = 50
		local bars = {}
		-- (round his body: shot B has him a little left of centre)
		local cx, cy = 0.44, 0.46
		local n = (cfg().Impact or {}).Lines or 18
		for i = 1, n do
			local a = (i - 0.5) / n * TAU + rand(-0.12, 0.12)
			local from, len = rand(0.24, 0.34), rand(0.3, 0.6)
			local mid = from + len / 2
			local f = Instance.new("Frame")
			f.Name = "Line"
			f.AnchorPoint = Vector2.new(0.5, 0.5)
			f.BorderSizePixel = 0
			f.BackgroundColor3 = Color3.new(0, 0, 0)
			f.Position = UDim2.fromScale(cx + math.cos(a) * mid, cy + math.sin(a) * mid * aspect)
			f.Size = UDim2.new(len, 0, 0, math.floor(rand(2, 7)))
			f.Rotation = math.deg(a)
			f.Parent = sg
			table.insert(bars, f)
		end
		sg.Parent = pg
		return {
			set = function(color)
				for _, b in bars do
					b.BackgroundColor3 = color
				end
			end,
			gone = function()
				sg:Destroy()
			end,
		}
	end
	-- ((round 101 review) the pair's backdrop: a sheet of pure colour (Neon:
	-- unlit) just behind his body as this camera sees him, so the world behind
	-- him is exactly white, then exactly black - whatever the grade makes of a
	-- bright sky or a dark building, and with the burst's blasts going off
	-- behind him. nil: no camera, or the camera's past him)
	function AK.backdrop(ctx)
		local cam = workspace.CurrentCamera
		if not cam then
			return nil
		end
		local eye = cam.CFrame.Position
		local gap = ctx.root.Position - eye
		if not (gap.Magnitude > 0.5) then
			return nil
		end
		-- (square to the line from the lens to him, his distance and Back past him)
		local look = gap.Unit
		local I = cfg().Impact or {}
		local at = eye + look * (gap.Magnitude + (I.Back or 2.6) * ctx.scale)
		local size = I.Sheet or 600
		local sheet = newPart(V3(size, size, 0.2), CFrame.lookAt(at, at + look), Color3.new(1, 1, 1), Enum.Material.Neon)
		sheet.Name = "AwakenBackdrop"
		return sheet
	end
	-- THE IMPACT PAIR (a Big hero's own screen, on the hit): two frames of a
	-- white world with him cut out black, two of a black world with him white,
	-- radial lines through them (Origin.impactFrame's recipe). Everything put
	-- back as it was. Returns how long it runs.
	-- ((round 101 review) his silhouette whole and on top of everything
	-- (AlwaysOnTop), a backdrop sheet behind him (AK.backdrop), and every other
	-- Highlight on him - his rim, a hero's own - held off for the four frames)
	function AK.pair(ctx)
		local I = cfg().Impact or {}
		local white, black = I.White or 0.033, I.Black or 0.033
		local bright, contrast = I.Bright or { 0.6, -0.45 }, I.Contrast or { 3, 4 }
		AK.pairToken = (AK.pairToken or 0) + 1
		local token = AK.pairToken
		local char = ctx.char
		local cc = Lighting:FindFirstChild("AwakenImpact")
		if not cc then
			cc = Instance.new("ColorCorrectionEffect")
			cc.Name = "AwakenImpact"
			cc.Enabled = false
			cc.Parent = Lighting
		end
		-- (never under or over another Highlight: his rim and anyone else's on him stand aside)
		local others = AK.others(char, true)
		for _, h in others do
			AK.holdOff(h)
		end
		AK.hush[char] = (AK.hush[char] or 0) + 1
		AK.rimShow(char)
		local cut = Instance.new("Highlight")
		cut.Name = "AwakenCutout"
		cut.FillTransparency = 0
		cut.OutlineTransparency = 1
		cut.DepthMode = Enum.HighlightDepthMode.AlwaysOnTop
		cut.Adornee = char
		cut.Parent = folder
		local sheet = AK.backdrop(ctx)
		local lines = AK.lines(ctx)
		ctx.pairUp = true
		VFX.ImpactHeld = math.max(VFX.ImpactHeld or 0, os.clock() + white + black) -- (no other B/W frame stacks on it)
		local function frame(figure, world, b, c)
			cc.Enabled = true
			cc.Saturation, cc.Brightness, cc.Contrast, cc.TintColor = -1, b, c, Color3.new(1, 1, 1)
			cut.FillColor = figure
			if sheet then
				sheet.Color = world
			end
			if lines then
				lines.set(figure)
			end
		end
		local BLACK, WHITE = Color3.new(0, 0, 0), Color3.new(1, 1, 1)
		frame(BLACK, WHITE, bright[1], contrast[1])
		AK.note(ctx, "impactWhite")
		task.delay(white, function()
			if AK.pairToken == token then
				frame(WHITE, BLACK, bright[2], contrast[2])
				AK.note(ctx, "impactBlack")
			end
		end)
		task.delay(white + black, function()
			if AK.pairToken == token then
				cc.Enabled = false
			end
			ctx.pairUp = nil
			cut:Destroy()
			if sheet then
				sheet:Destroy()
			end
			if lines then
				lines.gone()
			end
			for _, h in others do
				AK.letGo(h)
			end
			local n = (AK.hush[char] or 1) - 1
			AK.hush[char] = n > 0 and n or nil
			AK.rimShow(char)
		end)
		return white + black
	end
	-- THE IMPACT FRAMES (his own screen, on the hit): a Big hero's pair, a
	-- hero's own (FX.impact), or one hard black-and-white frame - just that
	-- on a low-end machine. Returns how long they run (the cut-in waits it out)
	function AK.impact(ctx)
		if not ctx.mine or ctx.spec.Impact == false then
			return 0
		end
		if type(ctx.fx.impact) == "function" then
			return math.max(tonumber(AK.call(ctx, "impact")) or 0, 0)
		end
		if ctx.spec.Big and not ctx.low then
			return AK.pair(ctx)
		end
		AK.note(ctx, "impactFlash")
		VFX.ImpactFrame((cfg().Impact or {}).Flash or 0.07)
		return 0
	end
	-- ROUND 100'S CUT-IN on his own screen, ON the pose's hit (after the
	-- impact frames): the slash wipes in, the title stamps from there; the
	-- shout and the exit keep to the hit (Config.Awaken.CutIn) for everyone
	function AK.cutIn(ctx, after)
		local cut = VFX.Hooks.UltCut
		if not ctx.mine or not ctx.ult or type(cut) ~= "function" then
			return
		end
		local C = cfg().CutIn or {}
		local view = Config.GetView(ctx.q, false, true)
		if not view then
			return
		end
		after = after or 0
		AK.note(ctx, "cutIn")
		ctx.cutUp = true
		local ok, err = pcall(cut, view, ctx.ult.Shout, {
			WipeAt = C.WipeAt, Wipe = C.Wipe, TitleAt = C.TitleAt, Exit = C.Exit,
			ShoutAt = math.max((C.ShoutAt or 0.2) - after, 0), Hold = math.max((C.Hold or 1.15) - after, 0.2),
		})
		if not ok then
			warn("[VFX] AK cut-in: " .. tostring(err))
		end
	end

	---------------------------------------------------------------- the burst
	-- his body's own Highlight (the burst's flare, the aura's rim): one a body
	function AK.rim(ctx)
		local h = AK.rims[ctx.char]
		if h and h.Parent then
			return h
		end
		h = Instance.new("Highlight")
		h.Name = "AwakenRim"
		h.FillColor = ctx.accent
		h.FillTransparency = 1
		h.OutlineColor = ctx.color
		h.OutlineTransparency = 1
		h.DepthMode = Enum.HighlightDepthMode.Occluded
		h.Adornee = ctx.char
		h.Parent = folder
		AK.rims[ctx.char] = h
		AK.rimShow(ctx.char) -- ((round 101 review) hidden while the pair or another Highlight is on him)
		return h
	end
	-- THE BURST (every screen, on the hit): a flare over his body in his ult's
	-- accent, a shock ring in its colour out along the street, a light that
	-- blinks out (not on a low-end machine). opts (his row's Burst): Flare /
	-- Ring / Light = false: none, or a number over Config.Awaken.Burst's
	function AK.burst(ctx, opts)
		opts = type(opts) == "table" and opts or {}
		local B = cfg().Burst or {}
		local function n(key)
			if opts[key] == false then
				return nil
			end
			return tonumber(opts[key]) or B[key]
		end
		AK.note(ctx, "burst")
		local root = ctx.root
		local flare = n("Flare")
		if flare then
			local h = AK.rim(ctx)
			h.FillColor, h.FillTransparency = ctx.accent, flare
			local ft = B.FlareTime or 0.25
			tween(h, ft, { FillTransparency = 1 }, Enum.EasingStyle.Quad, Enum.EasingDirection.Out)
			task.delay(ft + 0.05, function()
				-- (no aura to keep it: gone)
				if AK.rims[ctx.char] == h and not AK.auras[ctx.char] then
					AK.rims[ctx.char] = nil
					h:Destroy()
				end
			end)
		end
		local ring = n("Ring")
		if ring then
			local at = (ctx.g or (root.Position - UP * 2.5 * ctx.scale)) + UP * 0.5
			shockDisc(at, UP, 1, ring * ctx.scale, n("RingTime") or 0.35, ctx.color)
		end
		local light = n("Light")
		if light and not ctx.low then
			local pl = Instance.new("PointLight")
			pl.Name = "AwakenLight"
			pl.Color, pl.Brightness, pl.Range = ctx.accent, light, n("LightRange") or 24
			pl.Parent = root
			local lt = B.LightTime or 0.4
			tween(pl, lt, { Brightness = 0 }, Enum.EasingStyle.Quad, Enum.EasingDirection.Out)
			task.delay(lt + 0.05, function()
				pl:Destroy()
			end)
		end
	end
	-- a crack racing off along the street from `from` (a few dark segments
	-- wandering out, each where the street is)
	function AK.crack(from, dir, length, delayTime)
		local flat = V3(dir.X, 0, dir.Z)
		if flat.Magnitude < 0.05 or not (length > 0) then
			return
		end
		flat = flat.Unit
		local right = flat:Cross(UP)
		local steps = math.clamp(math.floor(length / 2.5), 2, 6)
		local prev, lat = from, 0
		for i = 1, steps do
			lat = math.clamp(lat + rand(-0.5, 0.5), -0.9, 0.9)
			local at = from + flat * length * i / steps + right * lat
			local hit = groundRay(at + UP * 2, 8)
			at = V3(at.X, (hit and hit.Position.Y or from.Y) + 0.06, at.Z)
			if (at - prev).Magnitude < 0.05 then
				continue -- (never a lookAt between two of the same point)
			end
			local seg = newPart(V3(0.22, 0.1, (at - prev).Magnitude + 0.2), CFrame.lookAt((prev + at) / 2, at), CRACK, Enum.Material.SmoothPlastic)
			seg.Transparency = 1
			local t = (delayTime or 0) + i * 0.02
			tween(seg, 0.03, { Transparency = 0.1 }, nil, nil, t)
			tween(seg, 0.5, { Transparency = 1 }, Enum.EasingStyle.Quad, Enum.EasingDirection.In, t + 1)
			cleanup(seg, t + 1.6)
			prev = at
		end
	end
	-- THE STREET (every screen, on the hit; only standing on it): dust blown
	-- flat out in a ring, cracks racing off his feet - none on his own lens.
	-- opts (his row's Ground): Dust / Cracks = false: none
	function AK.ground(ctx, opts)
		if opts == false or not ctx.g then
			return
		end
		opts = type(opts) == "table" and opts or {}
		local G = cfg().Ground or {}
		local g, s = ctx.g, ctx.scale
		AK.note(ctx, "ground")
		if opts.Dust ~= false then
			local n = math.max(math.floor((G.Dust or 12) * (ctx.low and ((cfg().Low or {}).Particles or 0.5) or 1)), 2)
			local R = (G.DustRing or 14) * s
			for i = 1, n do
				local a = (i - 0.5) / n * TAU + rand(-0.15, 0.15)
				local out = V3(math.cos(a), 0, math.sin(a))
				local to = g + out * R * rand(0.8, 1.15) + UP * 1.2 * s
				if not AK.lens(ctx, g + out * R * 0.6 + UP, 2) and not AK.lens(ctx, to, 2) then
					local puff = newPart(Vector3.one * 2.2 * s, CFrame.new(g + out * 2.5 * s + UP * 0.8 * s), DUST, Enum.Material.SmoothPlastic, Enum.PartType.Ball)
					puff.Name = "AwakenDust"
					puff.Transparency = 0.3
					tween(puff, 0.6, { CFrame = CFrame.new(to), Size = V3(5, 1.8, 5) * s, Transparency = 1 }, Enum.EasingStyle.Quad, Enum.EasingDirection.Out)
					cleanup(puff, 0.65)
				end
			end
		end
		if opts.Cracks ~= false then
			local n = G.Cracks or 8
			local L = G.CrackLength or { 6, 10 }
			for i = 1, n do
				local a = (i - 0.5) / n * TAU + rand(-0.2, 0.2)
				AK.crack(g, V3(math.cos(a), 0, math.sin(a)), rand(L[1], L[2]) * s, 0)
			end
		end
	end
	-- THE GATHER (every screen, from the press): the air and the street's grit
	-- sliding in to his feet from a ring round him, reaching him on the hit -
	-- none on his own lens
	function AK.gather(ctx)
		local WK = VFX.WindKit
		if not (WK and WK.curl and WK.streaks and WK.look) then
			return
		end
		local G = cfg().Ground or {}
		local base = ctx.g or (ctx.root.Position - UP * 3 * ctx.scale)
		local R = (G.AirRadius or 14) * ctx.scale
		local n = math.max(math.floor((G.Air or 12) * (ctx.low and ((cfg().Low or {}).Particles or 0.5) or 1)), 2)
		local life = math.max(ctx.hit, 0.15)
		AK.note(ctx, "air")
		for i = 1, n do
			local a = (i - 0.5) / n * TAU + rand(-0.25, 0.25)
			local out = V3(math.cos(a), 0, math.sin(a))
			local at = base + out * R * rand(0.7, 1) + UP * rand(0.4, 1.6)
			if not AK.lens(ctx, at, 1.5) then
				WK.curl(at, -out + UP * 0.12, { size = math.clamp(R * 0.12, 1.2, 3.4), drift = R * 0.55, life = life, spin = (i % 2 == 0 and 1 or -1) * 230, transparency = 0.15 })
				WK.streaks(WK.look(at, -out), { n = 2, length = R * 0.5, width = 0.24, spread = 1.4, speed = R * 0.5 / math.max(life * 0.6, 0.05), bend = i % 2 == 0 and 1 or -1 })
			end
		end
		-- the street's grit crawling in after it (from behind him and his sides:
		-- never across his own lens)
		if WK.debris and ctx.g then
			for i = 1, ctx.low and 2 or 3 do
				local a = math.atan2(-ctx.d.Z, -ctx.d.X) + (i - 2) * 1.1
				local out = V3(math.cos(a), 0, math.sin(a))
				local at = ctx.g + out * R * 0.8 + UP * 0.6
				if not AK.lens(ctx, at, 2) then
					WK.debris(at, -out * R * 1.3 + UP * 2, { n = 4, kinds = { "leaf", "grit", "paper", "grit" }, spread = 30, life = life + 0.15 })
				end
			end
		end
	end

	---------------------------------------------------------------- the aura
	function AK.auraStop(char)
		local rec = char and AK.auras[char]
		if rec and rec.stop then
			rec.stop()
		end
	end
	-- THE AURA (every screen, from the hit till the ult's over): his rim (his
	-- ult's colour round his body) and one preset of particles off him
	-- (Config.Awaken.Aura.Presets) - the rim alone on a low-end machine; "none":
	-- nothing. Returns stop()
	function AK.aura(ctx, preset)
		local AU = cfg().Aura or {}
		local char = ctx.char
		AK.auraStop(char)
		if preset == "none" or preset == false then
			return function() end
		end
		AK.note(ctx, "aura")
		local rim = AK.rim(ctx)
		rim.OutlineColor = ctx.color
		tween(rim, 0.25, { OutlineTransparency = AU.Rim or 0.5 }, Enum.EasingStyle.Quad, Enum.EasingDirection.Out)
		local P = (AU.Presets or {})[tostring(preset or "")]
		local torso = char:FindFirstChild("Torso") or char:FindFirstChild("UpperTorso") or ctx.root
		local pe
		if type(P) == "table" and not ctx.low then
			local life, speed = P.Life or { 0.5, 1 }, P.Speed or { 1, 2 }
			local c = (P.Color == "accent" and ctx.accent) or (typeof(P.Color) == "Color3" and P.Color) or ctx.color
			pe = Instance.new("ParticleEmitter")
			pe.Name = "AwakenAura"
			pe.Texture = P.Tex or "rbxasset://textures/particles/sparkles_main.dds"
			pe.Color = ColorSequence.new(c)
			pe.LightEmission = P.Light or 0.5
			pe.Size = NumberSequence.new({ NumberSequenceKeypoint.new(0, (P.Size or 0.4) * ctx.scale), NumberSequenceKeypoint.new(1, 0) })
			pe.Transparency = NumberSequence.new({ NumberSequenceKeypoint.new(0, 0.15), NumberSequenceKeypoint.new(1, 1) })
			pe.Lifetime = NumberRange.new(life[1], life[2])
			pe.Speed = NumberRange.new(speed[1], speed[2])
			pe.SpreadAngle = Vector2.new(P.Spread or 90, P.Spread or 90)
			pe.Acceleration = V3(0, P.Lift or 0, 0)
			pe.Rate = P.Rate or AU.Rate or 6
			pe.Parent = torso
		end
		local rec = { ctx = ctx, rim = rim, pe = pe }
		AK.auras[char] = rec
		local stopped = false
		local function stop()
			if stopped then
				return
			end
			stopped = true
			if AK.auras[char] == rec then
				AK.auras[char] = nil
			end
			if pe then
				pcall(function()
					pe.Enabled = false -- (his body may be gone already)
				end)
				task.delay(1.5, function()
					pe:Destroy()
				end)
			end
			if AK.rims[char] == rim then
				AK.rims[char] = nil
			end
			rim:Destroy()
		end
		rec.stop = stop
		task.spawn(function()
			-- (till the ult's over - his death, another hero, the ult off - or,
			-- for a body nobody says is in one, as long as one lasts)
			local cap = os.clock() + ((ctx.ult and tonumber(ctx.ult.Duration)) or 30) + 2
			local seen = false
			while not stopped do
				task.wait(AU.Tick or 0.15)
				local on = char.Parent and AK.ultOn(char)
				if on then
					seen = true
				end
				if not stopped and (not char.Parent or ctx.hum.Health <= 0 or (ctx.was ~= nil and char:GetAttribute("Quirk") ~= ctx.was)
					or (seen and on ~= true) or (not seen and os.clock() > cap)) then
					stop()
				elseif not stopped then
					AK.rimShow(char) -- ((round 101 review) aside while anyone else's Highlight is on him)
				end
			end
		end)
		return stop
	end

	---------------------------------------------------------------- the line
	-- THE SHOUT PANEL (everyone else's screen, on the shout): a paper slab
	-- leaning +6 degrees by his head, his shout in ink marker; it pops in, is
	-- held to the release and fades (AK.fadePanel)
	function AK.panel(ctx, text)
		if ctx.mine or ctx.spec.Panel == false or type(text) ~= "string" or text == "" then
			return nil
		end
		local P = cfg().Panel or {}
		local ST = (Config.UI or {}).Street or {}
		local head = ctx.char:FindFirstChild("Head") or ctx.root
		local k = (ctx.phone and ((cfg().Phone or {}).Panel or 0.8) or 1) * ctx.scale
		local size, off = P.Size or { 7.5, 1.9 }, P.Offset or { 2.6, 4.2 }
		local bb = Instance.new("BillboardGui")
		bb.Name = "AwakenPanel"
		bb.Adornee = head
		bb.Size = UDim2.new(size[1] * k, 0, size[2] * k, 0)
		bb.StudsOffset = V3(off[1] * k, 0, 0)
		bb.StudsOffsetWorldSpace = V3(0, off[2] * ctx.scale, 0)
		bb.AlwaysOnTop = true
		bb.MaxDistance = P.MaxDistance or 220
		bb.LightInfluence = 0
		local slab = Instance.new("Frame")
		slab.Name = "Slab"
		slab.AnchorPoint = Vector2.new(0.5, 0.5)
		slab.Position = UDim2.fromScale(0.5, 0.5)
		slab.Size = UDim2.fromScale(0.94, 0.78)
		slab.BackgroundColor3 = ST.Paper or Color3.fromRGB(244, 241, 234)
		slab.BorderSizePixel = 0
		slab.Rotation = -(P.Tilt or 6) -- (Roblox turns clockwise: the spec's +6, rising to the right)
		slab.Parent = bb
		local label = Instance.new("TextLabel")
		label.Name = "Shout"
		label.BackgroundTransparency = 1
		label.AnchorPoint = Vector2.new(0.5, 0.5)
		label.Position = UDim2.fromScale(0.5, 0.5)
		label.Size = UDim2.fromScale(0.9, P.Text or 0.62)
		label.TextScaled = true
		label.TextWrapped = true
		label.Text = text
		label.TextColor3 = ST.Ink or Color3.fromRGB(12, 12, 13)
		pcall(function()
			local note = ST.Fonts and ST.Fonts.Note
			label.FontFace = Font.new(note.Family, Enum.FontWeight[note.Weight or "Regular"], Enum.FontStyle.Normal)
		end)
		label.Parent = slab
		local pop = Instance.new("UIScale")
		pop.Scale = 0.6
		pop.Parent = slab
		bb.Parent = folder
		tween(pop, P.Pop or 0.06, { Scale = 1 }, Enum.EasingStyle.Back, Enum.EasingDirection.Out)
		ctx.panel = bb
		AK.note(ctx, "panel")
		return bb
	end
	function AK.fadePanel(ctx, fade)
		local bb = ctx.panel
		local slab = bb and bb:FindFirstChild("Slab")
		if not slab then
			return
		end
		tween(slab, fade, { BackgroundTransparency = 1 }, Enum.EasingStyle.Quad, Enum.EasingDirection.In)
		local label = slab:FindFirstChild("Shout")
		if label then
			tween(label, fade, { TextTransparency = 1 }, Enum.EasingStyle.Quad, Enum.EasingDirection.In)
		end
	end
	-- HIS LINE (Config.VoiceCues.Awaken, or his row's Voice; false: none): a
	-- clip lines its loudest word up on the hit (started from the press);
	-- text-to-speech starts on the hit
	function AK.voice(ctx, phase)
		local name = ctx.spec.Voice
		if name == false then
			return
		end
		if type(name) ~= "string" then
			local cues = Config.VoiceCues and Config.VoiceCues.Awaken
			name = cues and cues[ctx.q or ""]
		end
		local line = type(name) == "string" and Config.Voice and Config.Voice[name]
		if not line then
			return
		end
		local clip = VFX.VC ~= nil and VFX.VC.has(line)
		if phase == "press" and clip then
			AK.note(ctx, "voice")
			local s = VFX.Voice(name, ctx.root, math.max(ctx.hit - AK.now(ctx), 0.01))
			ctx.voiceSound = typeof(s) == "Instance" and s or nil
		elseif phase == "hit" and not clip then
			AK.note(ctx, "voice")
			VFX.Voice(name, ctx.root)
		end
	end
	-- HIS THEME (his own screen): held silent from the press, back on the hit
	-- over Config.Awaken.Music.FadeIn (the client's music loop brings his theme
	-- in that fast while a run of his is on: VFX.AK.fadeIn)
	function AK.music(ctx)
		local duck = VFX.Hooks.DuckMusic
		if not ctx.mine or ctx.spec.Music == false or type(duck) ~= "function" then
			return
		end
		local M = cfg().Music or {}
		local attack = M.Attack or 0.04
		AK.note(ctx, "duck")
		duck(0, attack, math.max(ctx.hit - attack, 0), M.FadeIn or 0.15)
	end
	-- (QuirkClient's music loop) how fast his theme comes in: the kit's FadeIn
	-- while a run of his own is on, nil otherwise
	function AK.fadeIn(char)
		local run = char and AK.runs[char]
		if run and run.mine and run.spec.Music ~= false then
			return (cfg().Music or {}).FadeIn or 0.15
		end
		return nil
	end
	-- ((round 101 review) QuirkClient's music loop) how long till his own
	-- run's hit (the theme's held silent till then): his theme starts that far
	-- before its Start, so its Start - a downbeat - lands on the hit; nil once
	-- it's hit (or no run of his own)
	function AK.lead(char)
		local run = char and AK.runs[char]
		if run and run.mine and run.spec.Music ~= false and not run.hitAt and AK.alive(run) then
			return math.max(run.hit - AK.now(run), 0)
		end
		return nil
	end
	-- one of the kit's sounds (Config.Awaken.Sounds: Riser / Hit), from him
	function AK.sound(ctx, which)
		local cue = (cfg().Sounds or {})[which]
		if type(cue) == "string" then
			AK.note(ctx, "sound" .. which)
			VFX.PlaySound(cue, ctx.root.Position, 1)
		end
	end

	---------------------------------------------------------------- props, the lock
	-- a prop in his hand for the activation (a staff, a hat, a glove): welded to
	-- that arm's hand ("Right" / "Left") at `offset` (the hand's space: R6, the
	-- arm's bottom), gone at the release or a cancel. Returns the part
	function AK.prop(ctx, name, hand, offset, size, color, material)
		local left = hand == "Left"
		local arm = limb(ctx.char, left and "LeftHand" or "RightHand", left and "Left Arm" or "Right Arm")
		if not arm then
			return nil
		end
		local p = Instance.new("Part")
		p.Name = "AwakenProp_" .. tostring(name)
		p.Size = typeof(size) == "Vector3" and size or V3(0.3, 0.3, 3)
		p.Color = typeof(color) == "Color3" and color or ctx.accent
		p.Material = material or Enum.Material.SmoothPlastic
		p.CanCollide, p.CanQuery, p.CanTouch, p.CastShadow, p.Massless = false, false, false, false, true
		local grip = CFrame.new(0, -arm.Size.Y / 2, 0) * (typeof(offset) == "CFrame" and offset or CFrame.new())
		p.CFrame = arm.CFrame * grip
		local weld = Instance.new("Weld")
		weld.Name = "AwakenPropWeld"
		weld.Part0, weld.Part1, weld.C0 = arm, p, grip
		weld.Parent = p
		p.Parent = folder
		table.insert(ctx.props, p)
		return p
	end
	-- (QuirkClient: busy() and the walk) your inputs and your walk held: your
	-- own run's lock, or the server's (AwakeningUntil, server time) - so it
	-- holds with cinematics off too
	function AK.locked(char)
		if typeof(char) ~= "Instance" then
			return false
		end
		if (AK.locks[char] or 0) > os.clock() then
			return true
		end
		local untilAt = char:GetAttribute("AwakeningUntil")
		return type(untilAt) == "number" and untilAt > workspace:GetServerTimeNow()
	end

	---------------------------------------------------------------- the run
	-- a hero without his own part: his old awakening (QUIRK_FX.Ult), on the
	-- hit - or at the press, for one that times itself
	function AK.default(q)
		local old = QUIRK_FX.Ult[q or ""]
		if not old then
			return {}
		end
		local function run(ctx)
			old(ctx.char, ctx.root, ctx.g or groundPoint(ctx.root.Position), ctx.mine)
		end
		if AK.spec(q).Legacy == "press" then
			return { press = run }
		end
		return { hit = run }
	end
	-- the body: his clip (his row's Clip), else his Motion (default the
	-- template's: MoveAwaken on R6, MOTIONS.Awaken on R15)
	function AK.body(ctx)
		local spec = ctx.spec
		if type(spec.Clip) == "string" and VFX.Clip(ctx.char, spec.Clip, { recover = 0.3 }) then
			return
		end
		local motion = type(spec.Motion) == "string" and MOTIONS[spec.Motion] and spec.Motion or "Awaken"
		VFX.Motion(ctx.char, motion)
	end
	function AK.context(char, data, isLocal)
		local root, hum = charParts(char)
		if not root or not hum then
			return nil
		end
		local A = cfg()
		local q = type(data) == "table" and type(data.Quirk) == "string" and data.Quirk or nil
		local quirk = Config.Quirks[q or ""]
		local ult = quirk and quirk.Ult
		local spec = AK.spec(q)
		local d = flatten(root.CFrame.LookVector, root)
		if d ~= d then
			d = V3(0, 0, -1)
		end
		local ctx = {
			char = char, root = root, hum = hum, q = q, spec = spec, quirk = quirk, ult = ult,
			color = ult and ult.Color or GOLD, accent = ult and ult.AccentColor or Color3.new(1, 1, 1),
			g = isGrounded(root) and groundPoint(root.Position) or nil, d = d, scale = AK.scale(char, q),
			t0 = poseTime(char, os.clock()), w0 = os.clock(), mine = AK.mine(char, isLocal), low = AK.low(), phone = AK.phone(),
			was = char:GetAttribute("Quirk"), possessed = char:GetAttribute("Possessed") == true,
			beats = {}, props = {},
		}
		ctx.release = A.Release or 1.6
		ctx.hit = math.clamp(AK.hitFor(q), 0.05, ctx.release - 0.2)
		ctx.clip = type(spec.Clip) == "string" and spec.Clip or ("Move" .. (type(spec.Motion) == "string" and spec.Motion or "Awaken"))
		ctx.gather = math.min(AK.mark(ctx.clip, "Gather") or A.Gather or 0.18, ctx.hit - 0.02)
		ctx.hold = math.max(AK.mark(ctx.clip, "Hold") or (ctx.hit + 0.12), ctx.hit + 0.02)
		ctx.headY = (AK.headAt(ctx.clip, ctx.hit) or (A.Shots or {}).Head or 1.5) * ctx.scale
		ctx.fx = AK.FX[q or ""] or AK.default(q)
		return ctx
	end
	-- THE HIT: every screen - the hitstop, the burst, the street, the sounds,
	-- his line, his own part, the aura; his own - the impact frames and the
	-- cut-in; everyone else's - a shake close by, the panel on the shout
	-- ((round 101 review) one of the kit's own steps, called safely: a step
	-- that breaks never takes the rest of the run with it - the release still
	-- comes and gives his HUD and his inputs back)
	function AK.safe(ctx, name, fn, ...)
		local ok, res = pcall(fn, ...)
		if not ok then
			warn("[VFX] AK " .. tostring(ctx.q) .. " " .. name .. ": " .. tostring(res))
			return nil
		end
		return res
	end
	function AK.hit(ctx)
		local A, spec = cfg(), ctx.spec
		ctx.hitAt = os.clock()
		AK.note(ctx, "hit")
		local stop = A.Hitstop or 0
		if stop > 0 then
			ctx.stop = stop
			VFX.Hitstop(ctx.char, stop)
		end
		ctx.after = 0
		if ctx.mine and not ctx.screenOff then
			local after = AK.safe(ctx, "impact", AK.impact, ctx) or 0
			-- (how long his screen's impact frames run: a big thing his own part
			-- spawns on the hit can wait them out - ctx.after)
			ctx.after = after
			if after > 0 then
				-- (f0 once the pair's frames are out, counted from this frame)
				local due = AK.now(ctx) + after
				task.spawn(function()
					if AK.at(ctx, due) and not ctx.screenOff then
						AK.safe(ctx, "cut-in", AK.cutIn, ctx, after)
					end
				end)
			else
				AK.safe(ctx, "cut-in", AK.cutIn, ctx, 0)
			end
		elseif not ctx.mine then
			AK.safe(ctx, "director", AK.director, ctx)
		end
		if not ctx.cine then
			-- (a camera close by shakes; his own takes the kick on its cut)
			local W = A.Witness or {}
			VFX.ShakeAt(ctx.root.Position, W.Shake or 1.2, W.Radius or 60, W.ShakeTime or 0.5)
		end
		AK.safe(ctx, "burst", AK.burst, ctx, spec.Burst)
		AK.safe(ctx, "ground", AK.ground, ctx, spec.Ground)
		AK.safe(ctx, "sound", AK.sound, ctx, "Hit")
		if spec.Sound ~= false then
			local cue = "Ult" .. tostring(ctx.q or "")
			VFX.PlaySound(Config.Sounds and Config.Sounds[cue] and cue or "Ult", ctx.root.Position, 1)
		end
		AK.safe(ctx, "voice", AK.voice, ctx, "hit")
		AK.call(ctx, "hit")
		if type(ctx.fx.aura) == "function" then
			AK.call(ctx, "aura")
		else
			AK.safe(ctx, "aura", AK.aura, ctx, spec.Aura)
		end
		task.spawn(function()
			if AK.at(ctx, ctx.hit + ((A.CutIn or {}).ShoutAt or 0.2)) then
				AK.note(ctx, "shout")
				AK.panel(ctx, ctx.ult and ctx.ult.Shout)
			end
		end)
	end
	-- the run's end: everything of it gone, his inputs and the HUD given back
	function AK.clean(ctx)
		if ctx.done then
			return
		end
		ctx.done = true
		local char = ctx.char
		if AK.runs[char] == ctx then
			AK.runs[char] = nil
			AK.locks[char] = nil
		end
		if ctx.aside and type(VFX.Hooks.Aside) == "function" then
			pcall(VFX.Hooks.Aside, "awaken", false)
		end
		for _, p in ctx.props do
			pcall(function()
				p:Destroy()
			end)
		end
		table.clear(ctx.props)
		if ctx.panel then
			pcall(function()
				ctx.panel:Destroy()
			end)
			ctx.panel = nil
		end
	end
	-- his camera taken back before the release (a respawn, the director's
	-- camera, anything that called VFX.CancelCinematic): his own screen's part
	-- of the awakening is over - the HUD back, no impact frames or cut-in (one
	-- that's up goes) - while his body's goes on for everyone
	function AK.watch(ctx)
		while not ctx.done and not ctx.dead do
			if not (VFX.InOwnCinematic() and VFX.CinematicToken() == ctx.cineToken) then
				if AK.now(ctx) < ctx.release - 0.05 and not ctx.done then
					AK.note(ctx, "unscreen")
					ctx.screenOff = true
					if ctx.cutUp and type(VFX.Hooks.UltCutOff) == "function" then
						pcall(VFX.Hooks.UltCutOff)
					end
					if ctx.aside and type(VFX.Hooks.Aside) == "function" then
						ctx.aside = false
						pcall(VFX.Hooks.Aside, "awaken", false)
					end
				end
				return
			end
			task.wait(0.03)
		end
	end
	-- THE RELEASE: his own part's release, then the run's end (his camera's
	-- shots end here by themselves)
	function AK.finish(ctx)
		AK.note(ctx, "release")
		AK.call(ctx, "release")
		AK.clean(ctx)
	end
	-- CALLED OFF (his death, another hero, the ult over, a newer run): the
	-- camera back now, the cut-in off, his line cut, the aura of this run gone
	function AK.stop(ctx)
		if ctx.done then
			return
		end
		AK.note(ctx, "stop")
		ctx.dead = true
		-- (only his: a kill cam or anything started since is left alone)
		if ctx.cine and VFX.InOwnCinematic() and VFX.CinematicToken() == ctx.cineToken then
			VFX.CancelCinematic()
		end
		if ctx.cutUp and type(VFX.Hooks.UltCutOff) == "function" then
			pcall(VFX.Hooks.UltCutOff)
		end
		if ctx.voiceSound then
			pcall(function()
				ctx.voiceSound:Destroy()
			end)
		end
		local rec = AK.auras[ctx.char]
		if rec and rec.ctx == ctx then
			rec.stop()
		end
		AK.clean(ctx)
	end
	-- THE ACTIVATION (Effects.UltActivate, every screen)
	function AK.play(char, data, isLocal)
		local ctx = AK.context(char, data, isLocal)
		if not ctx then
			return nil
		end
		local old = AK.runs[char]
		if old then
			AK.stop(old) -- (a newer one on the same body takes over)
		end
		AK.runs[char] = ctx
		AK.last = ctx
		-- THE PRESS: his inputs held, the HUD aside, the hard cut, the music
		-- held silent; the body gathers; the riser; the air sliding in
		if ctx.mine then
			AK.locks[char] = os.clock() + ctx.release
			if type(VFX.Hooks.Aside) == "function" then
				ctx.aside = true
				pcall(VFX.Hooks.Aside, "awaken", true)
			end
			ctx.shotList = AK.safe(ctx, "shots", AK.shots, ctx)
			if ctx.shotList and AK.safe(ctx, "camera", AK.camera, ctx) then
				task.spawn(AK.watch, ctx)
			end
			AK.safe(ctx, "music", AK.music, ctx)
		end
		AK.note(ctx, "press")
		AK.safe(ctx, "body", AK.body, ctx)
		AK.safe(ctx, "riser", AK.sound, ctx, "Riser")
		AK.call(ctx, "press")
		if ctx.spec.Gather ~= false then
			AK.safe(ctx, "gather", AK.gather, ctx)
		end
		AK.safe(ctx, "voice", AK.voice, ctx, "press")
		task.spawn(function()
			-- ((round 101 review) whatever breaks in it, the run ends and gives
			-- everything back - never a HUD left aside or a lock held)
			local ok, err = pcall(function()
				if not AK.at(ctx, ctx.gather) then
					return AK.stop(ctx)
				end
				AK.note(ctx, "gather")
				AK.call(ctx, "gather")
				if not AK.at(ctx, ctx.hit) then
					return AK.stop(ctx)
				end
				AK.hit(ctx)
				if not AK.at(ctx, ctx.hold) then
					return AK.stop(ctx)
				end
				AK.note(ctx, "hold")
				AK.call(ctx, "hold")
				local fade = (cfg().Panel or {}).Fade or 0.15
				if not AK.at(ctx, ctx.release - fade) then
					return AK.stop(ctx)
				end
				AK.fadePanel(ctx, fade)
				if not AK.at(ctx, ctx.release) then
					return AK.stop(ctx)
				end
				AK.finish(ctx)
			end)
			if not ok then
				warn("[VFX] AK " .. tostring(ctx.q) .. ": " .. tostring(err))
				pcall(AK.stop, ctx)
			end
		end)
		return ctx
	end

	---------------------------------------------------------------- BAKUGO
	-- DYNAMIGHT, the kit's reference hero (anim/moves_awaken.py's
	-- MoveAwakenExplosion): crouched, arms crossed low, sparks popping off his
	-- palms -> thrown into his launch stance, both palms flung back like
	-- rocket nozzles, a blast out of each; the ring of six round him; then
	-- embers off him and a palm popping now and then while he's in it
	local function palms(ctx)
		return { handPos(ctx.char, true), handPos(ctx.char, false) }
	end
	AK.FX.Explosion = {
		gather = function(ctx)
			local E = (cfg().Explosion or {}).Palms or {}
			VFX.PlaySound("BlastCharge", ctx.root.Position, 0.6)
			for i = 0, (E.Count or 3) - 1 do
				task.spawn(function()
					if AK.at(ctx, ctx.gather + i * (E.Gap or 0.05)) then
						for _, p in palms(ctx) do
							sparks(p, (E.Size or 0.9) * ctx.scale, FIRE[1], FIRE[3], ctx.low and 6 or 12)
						end
					end
				end)
			end
		end,
		hit = function(ctx)
			local E = cfg().Explosion or {}
			local N, R = E.Nozzles or {}, E.Ring or {}
			local s = ctx.scale
			-- ((round 101 review) a blast out behind each palm - set back and out
			-- so he's silhouetted against the pair, never inside one (a toon
			-- explosion's flash is 15x its scale across: the old 1.3 swallowed
			-- him whole on his own screen); on his screen they wait out the
			-- impact frames (ctx.after) and erupt with the cut-in)
			local right = ctx.d:Cross(UP)
			local ns = (N.Scale or 0.55) * s
			task.spawn(function()
				if not AK.at(ctx, ctx.hit + (ctx.after or 0)) then
					return
				end
				for i, p in palms(ctx) do
					local side = i == 1 and 1 or -1
					AK.blast(ctx, p - ctx.d * (N.Back or 3.4) * s + right * side * (N.Out or 0.6) * s, ns, { NoDebris = true, NoScorch = true }, "nozzles")
				end
			end)
			local g = ctx.g or (ctx.root.Position - UP * 3 * s)
			local n = R.Count or 6
			local spin = math.atan2(ctx.d.X, ctx.d.Z)
			local rs = (R.Scale or 1.1) * s
			for i = 1, n do
				local a = spin + (i - 0.5) / n * TAU
				local at = g + V3(math.cos(a) * (R.Radius or 11) * s, (R.Height or 3) * s, math.sin(a) * (R.Radius or 11) * s)
				task.spawn(function()
					-- ((round 101 review) kept off his lens by the blast's real reach, not a guess)
					if AK.at(ctx, ctx.hit + (R.From or 0.05) + (i - 1) * (R.Step or 0.05)) then
						AK.blast(ctx, at, rs, { NoScorch = true }, "ring" .. i)
					end
				end)
			end
		end,
		aura = function(ctx)
			local stop = AK.aura(ctx, ctx.spec.Aura or "embers")
			local rec = AK.auras[ctx.char]
			if not rec then
				return stop
			end
			local P = (cfg().Explosion or {}).Pop or {}
			task.spawn(function()
				while AK.auras[ctx.char] == rec do
					task.wait(P.Every or 0.7)
					if AK.auras[ctx.char] ~= rec or ctx.low or not (ctx.char.Parent and ctx.root.Parent) then
						break -- ((round 101 review) his body gone: never a pop at the world's origin)
					end
					-- (a palm pops: a spark and a quick flash, no sound)
					local p = handPos(ctx.char, rng:NextNumber() < 0.5)
					sparks(p, (P.Scale or 0.45) * ctx.scale, FIRE[1], FIRE[3], 5)
					local ball = newPart(Vector3.one * 0.5, CFrame.new(p), FIRE[2], Enum.Material.Neon, Enum.PartType.Ball)
					ball.Name = "AwakenPop"
					tween(ball, 0.12, { Size = Vector3.one * 2 * (P.Scale or 0.45) * 2 * ctx.scale, Transparency = 1 }, Enum.EasingStyle.Quad, Enum.EasingDirection.Out)
					cleanup(ball, 0.15)
				end
			end)
			return stop
		end,
	}
end)()

---------------------------------------------------------------------------
-- (round 101, awaken_e) TODOROKI's and IIDA's awakenings on the kit
-- (VFX.AK; their clips are anim/moves_awaken_e.py's, their numbers
-- Config.Awaken.HalfCold / Engine).
-- PHOSPHOR (MoveAwakenHalfCold): from the press the frost creeps up his
-- right side, feet to face, reaching it on the hit; in the gather - arms
-- crossed at his chest, head down - frost breath off him and embers off his
-- left arm. ON THE HIT he's torn apart, the ice arm flung low to his right,
-- the fire arm up to his left, and both halves go at once, as in the Sports
-- Festival: a glacier fans up on his right out of a spreading crust of
-- frost (blades leaning out, tallest at his side), frost cracks racing off;
-- a column of flame roars up off his left, fire bursting round that side;
-- where the two meet the air boils into steam. (On his own screen it all
-- waits out his impact pair, and nothing grows on his lens.) At the release
-- his fire melts the ice away; the frost goes a little after. His aura: the
-- rim, frost off him, embers off his left arm.
-- RECIPRO TURBO (MoveAwakenEngine): the press puts his tubes on him, the
-- Gather rips the old mufflers out of his calves (VFX.IidaTurbo.yank) and
-- heats the tubes by the hit, the Hit erupts (VFX.IidaTurbo.erupt: the
-- starburst behind him, the spray kept off his lens); the release hands the
-- tubes to the ult's own look.
-- (Its own function: VFX's main chunk gets no new local.)
---------------------------------------------------------------------------
;(function()
	local AK = VFX.AK
	local function cfg(q)
		return (Config.Awaken or {})[q] or {}
	end
	-- group E's clips' named keys (anim/moves_awaken_e.py), for a place
	-- without them
	for _, q in { "FullCowl", "HalfCold", "Engine", "Electrification", "Hellflame", "Blueflame", "PrimeDeku" } do
		AK.MARKS["MoveAwaken" .. q] = { Gather = 0.18, Hit = 0.3, Hold = 0.42, HoldEnd = 1.38 }
	end
	AK.MARKS.MoveAwakenWhirlwind = { Bow = 0.08, Gather = 0.2, Hit = 0.3, Hold = 0.42, HoldEnd = 1.38 }
	-- fn once the run's over: its release, or called off
	local function over(ctx, fn)
		task.spawn(function()
			AK.at(ctx, ctx.release)
			pcall(fn)
		end)
	end

	AK.FX.HalfCold = {
		press = function(ctx)
			local H = cfg("HalfCold")
			-- the frost creeping up his right side, the lowest crust first, up
			-- to his face by the hit
			local frost = IceKit.frostBody(ctx.char, { fadeIn = 1e5, fadeOut = 0.9 })
			local low, high = math.huge, -math.huge
			for _, p in frost.parts do
				low, high = math.min(low, p.CFrame.Position.Y), math.max(high, p.CFrame.Position.Y)
			end
			local creep = math.clamp(H.Creep or 0.26, 0.05, math.max(ctx.hit - 0.04, 0.05))
			for _, p in frost.parts do
				local goal = p:IsA("WedgePart") and 0 or 0.2
				p.Transparency = 1
				tween(p, 0.08, { Transparency = goal }, Enum.EasingStyle.Quad, nil, (p.CFrame.Position.Y - low) / math.max(high - low, 0.1) * creep)
			end
			AK.note(ctx, "frost")
			over(ctx, function()
				task.delay(H.FrostOff or 0.6, frost.off)
			end)
		end,
		gather = function(ctx)
			local H = cfg("HalfCold")
			IceKit.breath(ctx.char, H.Breath or 0.3, 0.5)
			local arm = limb(ctx.char, "LeftUpperArm", "Left Arm")
			if arm then
				local E = H.Embers or {}
				task.delay(math.max(ctx.hit - ctx.gather, 0.05) + 0.1, Flame.attach(arm, E.Size or 0.7, E.Rate or 0.8))
			end
		end,
		hit = function(ctx)
			local H = cfg("HalfCold")
			local G, C, S = H.Glacier or {}, H.Column or {}, H.Steam or {}
			local root, d = ctx.root, ctx.d
			local g = ctx.g or groundPoint(root.Position)
			local right = d:Cross(UP)
			local model = outlineModel(ICE_OUTLINE)
			-- (his fire melts the ice away at the release - or as the run's called off)
			over(ctx, function()
				IceKit.melt(model, { from = g - right * 4, time = H.Melt or 0.7 })
			end)
			task.spawn(function()
				if not AK.at(ctx, ctx.hit + (ctx.after or 0)) then
					return
				end
				AK.note(ctx, "glacier")
				-- the glacier fanned up on his right out of the crust, tallest
				-- at his side (none on his own lens)
				local list = {}
				local n = G.Count or 9
				local L = G.Length or { 7, 9 }
				for i = 1, n do
					local a = (i / n - 0.5) * math.pi
					local out = (right * math.cos(a) + d * math.sin(a)).Unit
					local side = math.cos(a) -- (1 = straight out to his right)
					local dir = (UP * (1.25 - side * 0.35) + out * (0.55 + side * 0.5)).Unit
					local len = rand(L[1], L[2]) + side * (G.Tall or 5)
					local base = g + out * ((G.Out or 5) + side) - UP
					if not AK.lens(ctx, base + UP, 2) and not AK.lens(ctx, base + dir * len, 1.5) then
						table.insert(list, { set = makeSpike(model, base, dir, len, 2 + side * 0.8, false, { face = root.Position }), delay = 0.06 + (1 - side) * 0.08 })
					end
				end
				AK.note(ctx, "spikes" .. #list)
				growSpikes(list, G.Grow or 0.15)
				local crust = newPart(Vector3.new(0.3, 2, 2), CFrame.new(g + UP * 0.07 + right * 5) * CFrame.Angles(0, 0, math.rad(90)), IceKit.PAL.FROST, Enum.Material.Snow, Enum.PartType.Cylinder, model)
				tween(crust, 0.3, { Size = Vector3.new(0.3, G.Crust or 18, G.Crust or 18) }, Enum.EasingStyle.Quad)
				local CL = G.CrackLength or { 14, 20 }
				for i = 1, G.Cracks or 4 do
					local a = (i / (G.Cracks or 4) - 0.6) * math.pi * 0.8
					IceKit.crackLine(g + right * 2, (right * math.cos(a) + d * math.sin(a)).Unit, rand(CL[1], CL[2]), { speed = 160, width = 0.35, life = 1 })
				end
				IceKit.particles(g + right * 4 + UP, "puff", ctx.low and 7 or 14, 1.6)
				IceKit.particles(root.Position + right * 4, "glint", ctx.low and 5 or 10, 1)
				IceKit.breath(ctx.char, math.max(ctx.release - AK.now(ctx), 0.3), 0.5)
				if not ctx.low then
					IceKit.light(g + right * 6 + UP * 5, 30, 1.8, 2.2)
				end
				-- the fire: a column off his left, bursts round that side
				AK.note(ctx, "column")
				Flame.column(g - right * (C.Side or 3.5), C.Height or 30, C.Radius or 3.2, C.Time or 1.3)
				local nb = C.Bursts or 5
				for i = 1, nb do
					local a = (i / nb - 0.5) * math.pi
					local out = (-right * math.cos(a) + d * math.sin(a)).Unit
					local at, s = g + out * rand(5, 8) + UP * rand(2, 4), rand(5, 7)
					if not AK.lens(ctx, at, s * 0.8) then
						task.delay(0.05 + i * 0.03, Flame.burst, at, s, 10)
					end
				end
				-- steam boiling up where they meet, in front of him (never on his
				-- own lens) and behind
				for i, k in { 1, -1 } do
					local at = g + d * 3 * k + UP * 2
					if not AK.lens(ctx, at, 2) then
						IceKit.steam(at, 1, i == 1 and 4 or 3, { delay = S[i] or (i == 1 and 0.15 or 0.25) })
					end
				end
			end)
		end,
		aura = function(ctx)
			local stop = AK.aura(ctx, ctx.spec.Aura or "frost")
			local rec = AK.auras[ctx.char]
			local arm = limb(ctx.char, "LeftUpperArm", "Left Arm")
			if not rec or ctx.low or not arm then
				return stop
			end
			-- embers off his left arm while he's in it
			local A = cfg("HalfCold").Arm or {}
			local out = Flame.attach(arm, A.Size or 0.8, A.Rate or 0.35)
			task.spawn(function()
				while AK.auras[ctx.char] == rec and arm.Parent do
					task.wait(0.2)
				end
				out()
			end)
			return stop
		end,
	}

	AK.FX.Engine = {
		press = function(ctx)
			local TT = VFX.IidaTurbo
			if TT and TT.awakenOn(ctx.char) then
				AK.note(ctx, "tubes")
			end
			over(ctx, function()
				TT.awakenOff(ctx.char)
			end)
		end,
		gather = function(ctx)
			local E = cfg("Engine")
			AK.note(ctx, "yank")
			-- (white-hot a moment before the hit, held for it)
			VFX.IidaTurbo.yank(ctx.char, ctx.root, ctx.g or groundPoint(ctx.root.Position), E.Grow or 0.1, math.max(ctx.hit - AK.now(ctx) - (E.HotFor or 0.04), 0.03))
		end,
		hit = function(ctx)
			AK.note(ctx, "erupt")
			VFX.IidaTurbo.erupt(ctx.char, ctx.root, {
				d = ctx.d,
				skip = function(pos, r)
					return AK.lens(ctx, pos, r)
				end,
			})
		end,
	}
end)()

---------------------------------------------------------------------------
-- (round 101, awaken_p) GROUP P's awakenings on the kit - All Might, Lemillion,
-- Gojo, Josuke, All Might (Plus Ultra), Prime All Might, DIO, Saitama: each
-- one his own pose (anim/moves_awaken_p.py) and his own part (VFX.AK.FX[q];
-- his numbers in Config.Awaken.<hero>). The heroes with a section of their
-- own have theirs written there (Lemillion, Gojo, Josuke, Prime, DIO,
-- Saitama); the two All Mights are here, with what the group shares
-- (VFX.AK.P: an impact pair in a hero's own colours - Gojo's void, DIO's
-- negative - and the ink menace marks).
-- (Its own function: the main chunk's locals stay as they are.)
---------------------------------------------------------------------------
;(function()
	local AK = VFX.AK
	local P = {}
	AK.P = P
	local V3 = Vector3.new
	local TAU = math.pi * 2
	local Lighting = game:GetService("Lighting")
	-- (a place without the clips yet: their named keys - anim/moves_awaken_p.py)
	for _, name in { "MoveAwakenOneForAll", "MoveAwakenLemillion", "MoveAwakenLimitless", "MoveAwakenCrazyDiamond", "MoveAwakenPlusUltra", "MoveAwakenPrimeMight", "MoveAwakenTheWorld" } do
		AK.MARKS[name] = { Gather = 0.18, Hit = 0.3, Hold = 0.42, HoldEnd = 1.38 }
	end
	AK.MARKS.MoveSaitamaAwaken = { Gather = 0.2, Hit = 0.32, Hold = 0.44, HoldEnd = 1.38 }
	-- a hero's own numbers (Config.Awaken.<hero>; never nil)
	function P.cfg(q)
		local c = (Config.Awaken or {})[q or ""]
		return type(c) == "table" and c or {}
	end

	-- white star specks over the screen for one of a pair's frames (nil: no PlayerGui)
	function P.specks(n)
		local me = Players.LocalPlayer
		local pg = me and me:FindFirstChildOfClass("PlayerGui")
		if not pg then
			return nil
		end
		local sg = Instance.new("ScreenGui")
		sg.Name = "AwakenSpecks"
		sg.IgnoreGuiInset = true
		sg.ResetOnSpawn = false
		sg.DisplayOrder = 49
		for _ = 1, n do
			local f = Instance.new("Frame")
			f.Name = "Speck"
			f.AnchorPoint = Vector2.new(0.5, 0.5)
			f.BorderSizePixel = 0
			f.BackgroundColor3 = Color3.new(1, 1, 1)
			f.Position = UDim2.fromScale(rand(0, 1), rand(0, 1))
			local px = math.floor(rand(2, 6))
			f.Size = UDim2.fromOffset(px, px)
			f.Rotation = 45
			f.Parent = sg
		end
		sg.Parent = pg
		return {
			show = function(on)
				sg.Enabled = on
			end,
			gone = function()
				sg:Destroy()
			end,
		}
	end

	-- AN IMPACT PAIR IN HIS OWN COLOURS (a Big hero's FX.impact, his own
	-- screen, on the hit): the kit's two frames (AK.pair's recipe: his
	-- cut-out whole and on top, the backdrop sheet behind him, the radial
	-- lines, every other Highlight on him held off - all put back exactly)
	-- in look's colours: World / Figure (per frame), the grade (Bright,
	-- Contrast, Saturation, Tint), Specks (white star specks over frame 1);
	-- sound on frame 1. One hard black-and-white frame on a low-end machine.
	-- Returns how long it runs (the cut-in waits it out).
	function P.pair(ctx, look, sound)
		local I = (Config.Awaken or {}).Impact or {}
		if ctx.low then
			AK.note(ctx, "impactFlash")
			VFX.ImpactFrame(I.Flash or 0.07)
			return 0
		end
		look = type(look) == "table" and look or {}
		local world = look.World or { Color3.new(1, 1, 1), Color3.new(0, 0, 0) }
		local figure = look.Figure or { Color3.new(0, 0, 0), Color3.new(1, 1, 1) }
		local one, two = I.White or 0.033, I.Black or 0.033
		AK.pairToken = (AK.pairToken or 0) + 1
		local token = AK.pairToken
		local char = ctx.char
		local cc = Lighting:FindFirstChild("AwakenImpact")
		if not cc then
			cc = Instance.new("ColorCorrectionEffect")
			cc.Name = "AwakenImpact"
			cc.Enabled = false
			cc.Parent = Lighting
		end
		local others = AK.others(char, true)
		for _, h in others do
			AK.holdOff(h)
		end
		AK.hush[char] = (AK.hush[char] or 0) + 1
		AK.rimShow(char)
		local cut = Instance.new("Highlight")
		cut.Name = "AwakenCutout"
		cut.FillTransparency = 0
		cut.OutlineTransparency = 1
		cut.DepthMode = Enum.HighlightDepthMode.AlwaysOnTop
		cut.Adornee = char
		cut.Parent = folder
		local sheet = AK.backdrop(ctx)
		local lines = AK.lines(ctx)
		local specks = (tonumber(look.Specks) or 0) > 0 and P.specks(math.floor(look.Specks)) or nil
		ctx.pairUp = true
		VFX.ImpactHeld = math.max(VFX.ImpactHeld or 0, os.clock() + one + two) -- (no other B/W frame stacks on it)
		local function frame(i)
			cc.Enabled = true
			cc.Saturation = look.Saturation and look.Saturation[i] or -1
			cc.Brightness = look.Bright and look.Bright[i] or 0
			cc.Contrast = look.Contrast and look.Contrast[i] or 2
			cc.TintColor = look.Tint and look.Tint[i] or Color3.new(1, 1, 1)
			cut.FillColor = figure[i]
			if sheet then
				sheet.Color = world[i]
			end
			if lines then
				lines.set(figure[i])
			end
			if specks then
				specks.show(i == 1)
			end
		end
		frame(1)
		-- (the kit's beat names for its two frames - the cut-in and the tests count from them)
		AK.note(ctx, "impactWhite")
		AK.note(ctx, "impactOwn")
		if type(sound) == "string" then
			VFX.PlaySound(sound, ctx.root.Position, 1)
		end
		task.delay(one, function()
			if AK.pairToken == token then
				frame(2)
				AK.note(ctx, "impactBlack")
			end
		end)
		task.delay(one + two, function()
			if AK.pairToken == token then
				cc.Enabled = false
			end
			ctx.pairUp = nil
			cut:Destroy()
			if sheet then
				sheet:Destroy()
			end
			if lines then
				lines.gone()
			end
			if specks then
				specks.gone()
			end
			for _, h in others do
				AK.letGo(h)
			end
			local n = (AK.hush[char] or 1) - 1
			AK.hush[char] = n > 0 and n or nil
			AK.rimShow(char)
		end)
		return one + two
	end

	-- THE INK MENACE MARKS (every screen): count jagged ink strokes beside
	-- him, rising rise studs and fading over life s (drawn marks, no text)
	function P.menace(ctx, color, count, rise, life)
		local root, s = ctx.root, ctx.scale
		local right = ctx.d:Cross(UP)
		for i = 1, count do
			local side = (i % 2 == 1) and 1 or -1
			local at = root.Position + right * side * rand(2.2, 3.2) * s + UP * (1 + i * 0.9) * s
			local anchor = newPart(Vector3.one * 0.1, CFrame.new(at), color)
			anchor.Name = "AwakenMenace"
			anchor.Transparency = 1
			local bb = Instance.new("BillboardGui")
			bb.Size = UDim2.new(1.6 * s, 0, 1.6 * s, 0)
			bb.LightInfluence = 0
			bb.MaxDistance = 220
			bb.Adornee = anchor
			bb.Parent = anchor
			-- (a zigzag of three strokes)
			for k, rot in { 28, -34, 28 } do
				local f = Instance.new("Frame")
				f.Name = "Stroke"
				f.AnchorPoint = Vector2.new(0.5, 0.5)
				f.BorderSizePixel = 0
				f.BackgroundColor3 = color
				f.Position = UDim2.fromScale(0.5 + (k - 2) * 0.12, 0.25 + (k - 1) * 0.25)
				f.Size = UDim2.fromScale(0.62, 0.11)
				f.Rotation = rot
				f.Parent = bb
				tween(f, life * 0.4, { BackgroundTransparency = 1 }, Enum.EasingStyle.Quad, Enum.EasingDirection.In, life * 0.6)
			end
			tween(anchor, life, { CFrame = CFrame.new(at + UP * rise * s) }, Enum.EasingStyle.Quad, Enum.EasingDirection.Out)
			cleanup(anchor, life + 0.05)
		end
		AK.note(ctx, "menace")
	end

	---------------------------------------------------------------- ALL MIGHT
	-- PLUS ULTRA (MoveAwakenOneForAll): from the press the steam closes round
	-- him - crunched over his fists in it - and on the hit it's blown out in
	-- a ring as he bursts up out of it in muscle form (the server grows him
	-- on the hit: the steam's still round him as he does), thumb up at the
	-- lens; gold bolts, two wind discs; then gold motes and a wisp of steam
	-- off a shoulder now and then while it lasts
	-- ((round 101 review) white steam - the classic, as his moves' own
	-- transformations have it - with every third puff the transform's purple;
	-- all purple read as poison smoke): a puff's dark and light colours
	local function steam(i, k)
		if i % 3 == 0 then
			return TRANSFORM_DARK:Lerp(TRANSFORM_LIGHT, k), TRANSFORM_LIGHT
		end
		return Color3.fromRGB(190, 190, 200):Lerp(STEAM, k), STEAM
	end
	AK.FX.OneForAll = {
		press = function(ctx)
			local S = P.cfg("OneForAll").Steam or {}
			local s = ctx.scale
			local base = ctx.g or (ctx.root.Position - UP * 3 * s)
			local n = math.max(math.floor((S.Count or 14) * (ctx.low and 0.5 or 1)), 4)
			local size = (S.Size or 2.2) * s
			for i = 1, n do
				local a = (i - 0.5) / n * TAU + rand(-0.15, 0.15)
				local out = V3(math.cos(a), 0, math.sin(a))
				local at = base + out * (S.Radius or 2.6) * s * rand(0.8, 1.05) + UP * (0.6 + (i % 5)) * s
				-- (none on his own lens: the steam is round him, never over the camera;
				-- on his own screen the ones between the camera and him are gone the
				-- moment he bursts out - his pose on the hit is never behind them)
				if not AK.lens(ctx, at, size * 0.5) then
					local wait = (i - 1) / n * 0.12
					local front = ctx.mine and out:Dot(ctx.d) > (S.Front or 0.3)
					local dark, light = steam(i, rand(0, 0.3))
					celPuff(folder, base + out * 6 * s + UP * 0.4 * s, at, size * rand(0.85, 1.1), dark, light,
						math.max(ctx.hit - wait, 0.05), front and 0.04 or (S.Shrink or 0.18), wait)
				end
			end
			AK.note(ctx, "steamIn")
		end,
		gather = function(ctx)
			-- (the heartbeat before he bursts out)
			VFX.PlaySound("MuscleThump", ctx.root.Position, 0.6)
		end,
		hit = function(ctx)
			local C = P.cfg("OneForAll")
			local S = C.Steam or {}
			local s, root = ctx.scale, ctx.root
			local base = ctx.g or (root.Position - UP * 3 * s)
			-- the steam blown out in a ring
			local n = math.max(math.floor((S.Ring or 18) * (ctx.low and 0.5 or 1)), 4)
			for i = 1, n do
				local a = (i - 0.5) / n * TAU
				local out = V3(math.cos(a), 0, math.sin(a))
				local from = base + out * 1.5 * s + UP * 2 * s
				local to = base + out * (S.RingRadius or 14) * s + UP * rand(1.2, 3) * s
				-- (his own screen: none blown at the camera - across his pose)
				if not (ctx.mine and out:Dot(ctx.d) > (S.Front or 0.3)) and not AK.lens(ctx, (from + to) / 2, 2 * s) and not AK.lens(ctx, to, 2 * s) then
					local dark, light = steam(i, rand(0.1, 0.5))
					celPuff(folder, from, to, (S.RingSize or 3.2) * s * rand(0.8, 1.1), dark, light, S.RingTime or 0.35, S.RingLife or 0.4, 0)
				end
			end
			AK.note(ctx, "steamOut")
			-- ((round 101 review) THE THUMB: a thumb up out of his raised fist -
			-- without it the most All Might gesture there is read as a fist by his
			-- head. The server grows him on the hit, a ping later here, and a prop
			-- is welded where the hand is when it's made: it waits for the growth
			-- (or Thumb.Wait at most) and is sized off the arm it's on)
			local Th = C.Thumb or {}
			task.spawn(function()
				if not AK.at(ctx, ctx.hit + (ctx.after or 0)) then
					return
				end
				local torso = ctx.char:FindFirstChild("Torso")
				local til = os.clock() + (Th.Wait or 0.35)
				while torso and torso.Size.Y / 2 < ctx.scale - 0.02 and os.clock() < til and AK.alive(ctx) do
					task.wait()
				end
				local arm = ctx.char:FindFirstChild("Right Arm")
				if arm and AK.alive(ctx) then
					local k = arm.Size.X
					local at, size = Th.At or { -0.26, 0.12, -0.62 }, Th.Size or { 0.3, 0.3, 0.72 }
					AK.prop(ctx, "Thumb", "Right", CFrame.new(at[1] * k, at[2] * k, at[3] * k), V3(size[1], size[2], size[3]) * k, arm.Color)
					AK.note(ctx, "thumb")
				end
			end)
			billboardRing(root.Position, 4, 40 * s, GOLD, 12, 0.4)
			local t0 = os.clock()
			task.spawn(function()
				while os.clock() - t0 < (C.Bolts or 0.3) and AK.alive(ctx) do
					bolt(root.Position, 5 * s, GOLD)
					bolt(root.Position, 5 * s, Color3.new(1, 1, 1))
					task.wait(0.03)
				end
			end)
			-- (low over the street: under his camera's eye)
			local D = C.Discs or {}
			for i = 1, D.Count or 2 do
				task.spawn(function()
					if AK.at(ctx, ctx.hit + (i - 1) * (D.Gap or 0.08)) then
						shockDisc(base + UP * (0.3 + i * 0.7) * s, UP, 8, (D.Size or 70) * s, 0.5, WIND)
					end
				end)
			end
		end,
		aura = function(ctx)
			local stop = AK.aura(ctx, ctx.spec.Aura or "motes")
			local rec = AK.auras[ctx.char]
			if not rec or ctx.low then
				return stop
			end
			local every = P.cfg("OneForAll").ShoulderSteam or 0.6
			task.spawn(function()
				while AK.auras[ctx.char] == rec do
					task.wait(every)
					if AK.auras[ctx.char] ~= rec or not (ctx.char.Parent and ctx.root.Parent) then
						break -- (his body gone: never a wisp at the world's origin)
					end
					local torso = ctx.char:FindFirstChild("Torso") or ctx.char:FindFirstChild("UpperTorso")
					if torso then
						local side = rng:NextNumber() < 0.5 and 1 or -1
						local at = (torso.CFrame * CFrame.new(side * torso.Size.X * 0.45, torso.Size.Y * 0.5, 0)).Position
						celPuff(folder, at, at + UP * 1.2 * ctx.scale, 0.9 * ctx.scale, STEAM, Color3.new(1, 1, 1), 0.2, 0.6, 0)
					end
				end
			end)
			return stop
		end,
	}

	---------------------------------------------------------------- ALL MIGHT, PLUS ULTRA
	-- SYMBOL OF PEACE (MoveAwakenPlusUltra): a crouch over his low fists
	-- while the wind gathers (light glinting off his fists) - then up into I
	-- AM HERE, fists on his hips, chest out: a gold sunburst fanned out
	-- behind him (once his own screen's impact frames are out), two wind
	-- discs; All Might's own boom (Config.Sounds.UltPlusUltra)
	AK.FX.PlusUltra = {
		gather = function(ctx)
			for _, right in { true, false } do
				sparks(handPos(ctx.char, right), 0.6 * ctx.scale, Color3.new(1, 1, 1), GOLD, ctx.low and 4 or 8)
			end
		end,
		hit = function(ctx)
			local C = P.cfg("PlusUltra")
			local S = C.Sun or {}
			local s, root = ctx.scale, ctx.root
			local base = ctx.g or (root.Position - UP * 3 * s)
			task.spawn(function()
				if not AK.at(ctx, ctx.hit + (ctx.after or 0)) then
					return
				end
				-- the rays: fanned up and out in the plane behind him, from a
				-- point behind his chest (each a flat slab facing his front)
				local torso = ctx.char:FindFirstChild("Torso") or ctx.char:FindFirstChild("UpperTorso") or root
				local right = ctx.d:Cross(UP)
				local c = torso.CFrame.Position - ctx.d * (S.Back or 2.2) * s + UP * 0.6 * s
				local n = S.Rays or 14
				local L = (S.Length or 14) * s
				local grow, fade = S.Grow or 0.15, S.Fade or 1.25
				for i = 1, n do
					local a = math.pi * (i - 0.5) / n
					local dir = (right * math.cos(a) + UP * (math.sin(a) * 0.9 + 0.05)).Unit
					local width = (S.Width or 0.7) * s * (i % 2 == 0 and 1 or 0.7)
					local function at(len)
						return CFrame.fromMatrix(c + dir * (1.5 * s + len / 2), dir, ctx.d)
					end
					local ray = newPart(V3(0.1, 0.12, width), at(0.1), i % 2 == 0 and ctx.color or ctx.accent, Enum.Material.Neon)
					ray.Name = "AwakenSunRay"
					ray.Transparency = 0.1
					tween(ray, grow, { Size = V3(L, 0.12, width), CFrame = at(L) }, Enum.EasingStyle.Quad, Enum.EasingDirection.Out)
					tween(ray, 0.4, { Transparency = 1 }, Enum.EasingStyle.Quad, Enum.EasingDirection.In, math.max(fade - 0.4, grow))
					cleanup(ray, fade + 0.05)
				end
				AK.note(ctx, "sunburst")
			end)
			local D = C.Discs or {}
			for i = 1, D.Count or 2 do
				task.spawn(function()
					if AK.at(ctx, ctx.hit + (i - 1) * (D.Gap or 0.08)) then
						shockDisc(base + UP * (0.3 + i * 0.7) * s, UP, 8, (D.Size or 70) * s, 0.5, WIND)
					end
				end)
			end
		end,
	}
end)()

function Effects.UltEnd(char)
	local root = charParts(char)
	if not root then
		return
	end
	dustPuffs(root.Position, 1.3, 10, STEAM, 1.2, true)
	shockDisc(root.Position, UP, 2, 16, 0.3, STEAM)
end

-- Server: an attack passed through someone's dash i-frames
function Effects.Dodge(_, data)
	local target = data.Target
	local root = target and target:FindFirstChild("HumanoidRootPart")
	if not root then
		return
	end
	-- (Phase: it went straight through Lemillion)
	afterimage(target, data.Phase and Color3.fromRGB(255, 240, 196) or Color3.fromRGB(235, 245, 255), 0.3)
	shockDisc(root.Position, UP, 2, 10, 0.2, data.Phase and Color3.fromRGB(255, 214, 60) or WIND)
end

---------------------------------------------------------------------------
-- ONE FOR ALL: United States of Smash + Colorado Smash
---------------------------------------------------------------------------

-- The twister United States of Smash leaves behind (round 78: rebuilt). In
-- the anime the wind pressure is a pale, roaring funnel climbing out of the
-- crater into a storm - strong enough to sway the news helicopter and carry
-- buildings off. Here: soft wind streaks (beams bent round it) on rings that
-- climb with the updraft - tight and fast at the foot, wide and slow up top,
-- dust-brown low down and white above - feeding a dark ring of storm cloud
-- with lightning in it; rubble and slabs of street and building ride it up
-- and round; the sky darkens round it while it lasts. It all dies away
-- (and the streaks fade) rather than blinking out.
local function twister(pos, duration, topR, height)
	height = height or 300
	topR = topR or 110
	local baseR = math.max(topR * 0.12, 10)
	local GROW, FADE = 1.2, 1.4
	local model = Instance.new("Model")
	model.Name = "Twister"
	model.Parent = folder
	-- (round 81) its wind, for as long as it lasts: the burst, then loops
	-- spaced evenly (under 1.9s apart: each rises as the one before starts
	-- to fade) so the last one dies away with the funnel - it used to dip
	-- to nothing, then restart at full roar
	do
		local LEN = 3.6 -- (the cues' Length)
		local span = math.max(duration + FADE - LEN, 0)
		local loops = math.ceil(span / 1.9 - 1e-6)
		VFX.PlaySound("USSTwister", pos, 1)
		for i = 1, loops do
			task.delay(span * i / loops, function()
				if model.Parent then
					VFX.PlaySound("USSTwisterLoop", pos, 1)
				end
			end)
		end
	end
	local function radiusAt(h)
		return baseR + (topR - baseR) * math.clamp(h / height, 0, 1) ^ 1.7
	end
	-- the axis sways more the higher you go
	local function axisAt(h, t)
		local k = h / height
		return pos + Vector3.new(math.sin(t * 0.9 + k * 2.2) * 30 * k, h, math.cos(t * 0.7 + k * 1.7) * 30 * k)
	end
	local DUST = Color3.fromRGB(206, 194, 178)
	local NS, NK = NumberSequence.new, NumberSequenceKeypoint.new
	local smokeTex = (Config.Assets and Config.Assets.SmokeTexture) or "rbxasset://textures/particles/smoke_main.dds"
	-- (a streak's see-through-ness in 20 steps: the sequences are reused)
	local fades = {}
	local function fadeSeq(alpha)
		local q = math.floor(math.clamp(alpha, 0, 1) * 20 + 0.5)
		local seq = fades[q]
		if not seq then
			local mid = 1 - (q / 20) * 0.6
			seq = NS({ NK(0, 1), NK(0.25, mid), NK(0.75, mid), NK(1, 1) })
			fades[q] = seq
		end
		return seq, q
	end

	-- THE WIND: rings of streaks round the funnel, climbing with the updraft
	local rings = {}
	local RINGS, PER = 24, 3
	for i = 1, RINGS do
		local anchor = newPart(Vector3.one * 0.2, CFrame.new(pos), WIND, nil, nil, model)
		anchor.Transparency = 1
		local ring = { part = anchor, h = (i - 0.5) / RINGS * height, spin = rand(0, math.pi * 2), shade = rand(0.88, 1), streaks = {}, q = -1, n = i }
		for j = 1, PER do
			local att0 = Instance.new("Attachment")
			att0.Parent = anchor
			local att1 = Instance.new("Attachment")
			att1.Parent = anchor
			local beam = Instance.new("Beam")
			beam.Attachment0 = att0
			beam.Attachment1 = att1
			beam.Segments = 14
			beam.FaceCamera = true
			beam.LightEmission = 0.2
			beam.LightInfluence = 0.5
			beam.Texture = smokeTex
			beam.TextureMode = Enum.TextureMode.Stretch
			beam.TextureSpeed = rand(0.5, 1.1)
			beam.Transparency = fadeSeq(0)
			beam.Parent = anchor
			table.insert(ring.streaks, { a0 = j / PER * math.pi * 2 + rand(-0.35, 0.35), span = rand(1, 1.6), att0 = att0, att1 = att1, beam = beam })
		end
		table.insert(rings, ring)
	end
	-- a ring's streaks at its height: each an arc of the circle (the beam's
	-- ends point along the spin, so it bends round it), climbing a little as
	-- it goes round, wider and paler the higher it is
	local function shapeRing(ring)
		local r = radiusAt(ring.h)
		local k = ring.h / height
		local width = 2 + r * 0.15
		local shade = ring.shade
		local color = ColorSequence.new(Color3.new(shade, shade, math.min(shade * 1.03, 1)):Lerp(DUST, math.clamp(1 - k * 3.5, 0, 1) * 0.75))
		for _, s in ring.streaks do
			local a0, a1 = s.a0, s.a0 + s.span
			local t0 = Vector3.new(-math.sin(a0), 0.08, math.cos(a0)).Unit
			local t1 = Vector3.new(-math.sin(a1), 0.08, math.cos(a1)).Unit
			local u0 = (UP - t0 * t0:Dot(UP)).Unit
			local u1 = (UP - t1 * t1:Dot(UP)).Unit
			s.att0.CFrame = CFrame.fromMatrix(Vector3.new(math.cos(a0) * r, 0, math.sin(a0) * r), t0, u0)
			s.att1.CFrame = CFrame.fromMatrix(Vector3.new(math.cos(a1) * r, s.span * r * 0.05, math.sin(a1) * r), t1, u1)
			local bend = 4 / 3 * math.tan(s.span / 4) * r
			s.beam.CurveSize0 = bend
			s.beam.CurveSize1 = bend
			s.beam.Width0 = width * 0.5
			s.beam.Width1 = width
			s.beam.Color = color
		end
	end
	for _, ring in rings do
		shapeRing(ring)
	end

	-- rubble riding the wind up and round, and slabs of street and building
	-- carried off it
	local ROCKS = { Color3.fromRGB(120, 112, 104), Color3.fromRGB(90, 84, 80), Color3.fromRGB(150, 138, 120), Color3.fromRGB(70, 66, 64) }
	local SLABS = { Color3.fromRGB(150, 146, 140), Color3.fromRGB(122, 118, 114), Color3.fromRGB(176, 168, 156), Color3.fromRGB(96, 104, 116) }
	local debris = {}
	for _ = 1, 40 do
		local sz = rand(0.8, 3.6)
		local part = newPart(Vector3.new(sz, sz * rand(0.5, 1), sz * rand(0.6, 1.3)), CFrame.new(pos), ROCKS[rng:NextInteger(1, 4)], Enum.Material.Slate, nil, model)
		table.insert(debris, {
			part = part, h = rand(0, height * 0.5), a = rand(0, math.pi * 2), rise = rand(16, 42), out = rand(0.75, 1.15),
			tumble = CFrame.Angles(rand(-0.2, 0.2), rand(-0.2, 0.2), rand(-0.2, 0.2)), rot = CFrame.Angles(rand(0, 6), rand(0, 6), rand(0, 6)),
		})
	end
	for _ = 1, 8 do
		local part = newPart(Vector3.new(rand(4, 9), rand(1.5, 3.5), rand(5, 12)), CFrame.new(pos), SLABS[rng:NextInteger(1, 4)], Enum.Material.Concrete, nil, model)
		table.insert(debris, {
			part = part, h = rand(-8, 6), a = rand(0, math.pi * 2), rise = rand(8, 15), out = rand(1.1, 1.4), slab = true, top = height * rand(0.3, 0.55),
			tumble = CFrame.Angles(rand(-0.06, 0.06), rand(-0.06, 0.06), rand(-0.06, 0.06)), rot = CFrame.Angles(rand(0, 6), rand(0, 6), rand(0, 6)),
		})
	end
	-- the storm cloud the funnel feeds, turning slowly overhead
	local clouds = {}
	for i = 1, 18 do
		local size = rand(40, 80)
		local shade = rand(0.26, 0.4)
		local part = newPart(Vector3.one * size, CFrame.new(pos), Color3.new(shade, shade, shade + 0.04), Enum.Material.SmoothPlastic, Enum.PartType.Ball, model)
		part.Transparency = 1
		table.insert(clouds, { part = part, shade = shade, a = i / 18 * math.pi * 2 + rand(-0.2, 0.2), r = topR * rand(0.75, 1.35), h = height * rand(0.95, 1.08) })
	end
	-- dust boiling off the ground at its foot, and hanging inside the funnel
	local skirt = newPart(Vector3.new(baseR * 5, 2, baseR * 5), CFrame.new(pos + UP), DUST, nil, nil, model)
	skirt.Transparency = 1
	local skirtFx = Instance.new("ParticleEmitter")
	skirtFx.Texture = smokeTex
	skirtFx.Color = ColorSequence.new(DUST, Color3.fromRGB(160, 150, 138))
	skirtFx.LightInfluence = 0.6
	skirtFx.Size = NS({ NK(0, 10), NK(1, 34) })
	skirtFx.Transparency = NS({ NK(0, 0.9), NK(0.2, 0.35), NK(1, 1) })
	skirtFx.Lifetime = NumberRange.new(1.6, 2.6)
	skirtFx.Speed = NumberRange.new(14, 30)
	skirtFx.SpreadAngle = Vector2.new(70, 70)
	skirtFx.Acceleration = Vector3.new(0, 10, 0)
	skirtFx.Drag = 0.8
	skirtFx.Rotation = NumberRange.new(0, 360)
	skirtFx.RotSpeed = NumberRange.new(-60, 60)
	skirtFx.Rate = 45
	skirtFx.Parent = skirt
	local column = newPart(Vector3.new(baseR * 1.4, height * 0.5, baseR * 1.4), CFrame.new(pos + UP * height * 0.25), DUST, nil, nil, model)
	column.Transparency = 1
	local columnFx = skirtFx:Clone()
	columnFx.Color = ColorSequence.new(Color3.fromRGB(226, 222, 216), Color3.fromRGB(180, 172, 164))
	columnFx.Size = NS({ NK(0, 14), NK(1, 40) })
	columnFx.Transparency = NS({ NK(0, 1), NK(0.3, 0.6), NK(1, 1) })
	columnFx.Speed = NumberRange.new(20, 40)
	columnFx.SpreadAngle = Vector2.new(15, 15)
	columnFx.Rate = 22
	columnFx.Parent = column

	-- the sky darkens round it (for anyone near enough to be under it)
	local cam = workspace.CurrentCamera
	local sky
	if cam and (cam.Focus.Position - pos).Magnitude < 700 then
		sky = Instance.new("ColorCorrectionEffect")
		sky.Name = "TwisterSky"
		sky.Parent = game:GetService("Lighting")
		tween(sky, 1.2, { Brightness = -0.07, Contrast = 0.1, TintColor = Color3.fromRGB(214, 222, 236) })
	end
	-- lightning flickering through the cloud
	local function lightning(t)
		local a, b = clouds[rng:NextInteger(1, #clouds)], clouds[rng:NextInteger(1, #clouds)]
		local from = axisAt(height, t) + Vector3.new(math.cos(a.a) * a.r, a.h - height - 10, math.sin(a.a) * a.r)
		local to = axisAt(height, t) + Vector3.new(math.cos(b.a) * b.r * 0.5, b.h - height - rand(30, 70), math.sin(b.a) * b.r * 0.5)
		local last = from
		for i = 1, 6 do
			local nxt = from:Lerp(to, i / 6) + (i < 6 and rng:NextUnitVector() * rand(3, 9) or Vector3.zero)
			local seg = newPart(Vector3.new(0.5, 0.5, (nxt - last).Magnitude), CFrame.lookAt((last + nxt) / 2, nxt), Color3.fromRGB(226, 236, 255), Enum.Material.Neon, nil, model)
			cleanup(seg, 0.12)
			last = nxt
		end
		a.part.Color = Color3.new(0.8, 0.84, 0.95)
		task.delay(0.1, function()
			a.part.Color = Color3.new(a.shade, a.shade, a.shade + 0.04)
		end)
		-- (round 81) and its thunder (a low roll: no more than one a second)
		VFX.PlaySound("USSThunder", from:Lerp(to, 0.5), 1)
	end

	local parts, cfs = {}, {}
	local t0 = os.clock()
	local lastShake, nextBolt, frame = 0, 0.8, 0
	local conn
	conn = RunService.RenderStepped:Connect(function(dt)
		local t = os.clock() - t0
		if t > duration + FADE or not model.Parent then
			conn:Disconnect()
			model:Destroy()
			if sky then
				tween(sky, 1.2, { Brightness = 0, Contrast = 0, TintColor = Color3.new(1, 1, 1) })
				cleanup(sky, 1.3)
			end
			return
		end
		frame += 1
		local grow = math.clamp(t / GROW, 0, 1) -- it rises out of the crater...
		local fade = math.clamp((duration + FADE - t) / FADE, 0, 1) -- ...and blows itself out
		table.clear(parts)
		table.clear(cfs)
		for _, ring in rings do
			local k = ring.h / height
			ring.h += (14 + 26 * k) * dt -- the updraft: faster the higher it gets
			if ring.h > height then
				ring.h -= height
			end
			k = ring.h / height
			ring.spin += (3.4 - 2.3 * k) * dt
			if (frame + ring.n) % 3 == 0 then
				shapeRing(ring) -- (wider as it climbs; a third of them each frame)
			end
			-- in at the foot, out at the top, only as high as it's grown so far
			local edge = math.min(1, k / 0.06, (1 - k) / 0.12)
			local seq, q = fadeSeq(k <= grow and edge * fade or 0)
			if q ~= ring.q then
				ring.q = q
				for _, s in ring.streaks do
					s.beam.Transparency = seq
				end
			end
			table.insert(parts, ring.part)
			table.insert(cfs, CFrame.new(axisAt(ring.h, t)) * CFrame.Angles(0, -ring.spin, 0))
		end
		for _, d in debris do
			if d.slab then
				-- carried up slowly, then round and round up there; dropped as it dies
				if fade < 1 then
					d.h -= (1 - fade) * 120 * dt
				elseif d.h < d.top * grow then
					d.h += d.rise * dt
				end
			else
				d.h += d.rise * dt
				if d.h > height * grow * 0.9 then
					d.h = rand(0, 12)
				end
			end
			d.a += (3.8 - 2.4 * math.max(d.h, 0) / height) * dt
			d.rot *= d.tumble
			local out = Vector3.new(math.cos(d.a), 0, math.sin(d.a))
			table.insert(parts, d.part)
			table.insert(cfs, CFrame.new(axisAt(math.max(d.h, 0), t) + out * radiusAt(math.max(d.h, 0)) * d.out) * d.rot)
			if fade < 1 then
				d.part.Transparency = 1 - fade
			end
		end
		for _, c in clouds do
			c.a += 0.22 * dt
			table.insert(parts, c.part)
			table.insert(cfs, CFrame.new(axisAt(height, t) + Vector3.new(math.cos(c.a) * c.r, c.h - height, math.sin(c.a) * c.r)))
			if grow < 1 or fade < 1 then
				c.part.Transparency = 1 - 0.82 * math.min(grow, fade)
			end
		end
		local ok = pcall(function()
			workspace:BulkMoveTo(parts, cfs, Enum.BulkMoveMode.FireCFrameChanged)
		end)
		if not ok then
			for i, part in parts do
				part.CFrame = cfs[i]
			end
		end
		if fade < 1 then
			skirtFx.Enabled = false
			columnFx.Enabled = false
		end
		if t > nextBolt and fade > 0.6 then
			nextBolt = t + rand(0.45, 1.1)
			lightning(t)
		end
		if t - lastShake > 0.5 and fade > 0.5 then
			lastShake = t
			VFX.ShakeAt(pos, 1, 220, 0.5)
		end
	end)
end

-- a glowing, swollen copy of a limb (All Might's arm pumped with power)
local function swell(char, names, color, scale)
	local glows = {}
	for _, pair in names do
		local part = limb(char, pair[1], pair[2])
		if part then
			local g = Instance.new("Part")
			g.Size = part.Size * scale
			g.CFrame = part.CFrame
			g.Color = color
			g.Material = Enum.Material.Neon
			g.Transparency = 0.55
			g.CanCollide = false
			g.CanQuery = false
			g.CanTouch = false
			g.Massless = true
			g.CastShadow = false
			local w = Instance.new("WeldConstraint")
			w.Part0 = part
			w.Part1 = g
			w.Parent = g
			g.Parent = folder
			table.insert(glows, g)
		end
	end
	return function(fade)
		for _, g in glows do
			tween(g, fade or 0.4, { Transparency = 1 })
			cleanup(g, (fade or 0.4) + 0.05)
		end
	end
end

-- (round 78) UNITED STATES OF SMASH: its effects (the lunge, the catch,
-- the strike, the slam) are at the end of this file

-- the parabola Colorado Smash rides: rises fast, peaks early, crashes steeply
local function arcPosition(from, to, height, s)
	local u = s ^ 0.75
	return from:Lerp(to, s) + UP * (height * 4 * u * (1 - u))
end

-- a warning circle on the landing spot until he arrives
local function landingMarker(pos, duration)
	groundMark(pos, 14, Color3.fromRGB(200, 40, 40), duration)
	task.spawn(function()
		local t0 = os.clock()
		while os.clock() - t0 < duration do
			billboardRing(pos + UP, 4, 30, Color3.fromRGB(255, 70, 60), 6, 0.35)
			task.wait(0.25)
		end
	end)
end

-- (round 75) COLORADO SMASH, aimed from the sky: pressed, he sinks into a
-- deep crouch on the street - legs loaded, the wind drawn in round him -
-- while his camera's up over the city picking the spot (the client's sky
-- camera); the second press (ColoradoGo, from the server) and he's gone
VFX.coloradoCharge = setmetatable({}, { __mode = "k" })
-- (legs loaded, leaning in, looking up at where he's going; arms swung back)
POSES.ColoradoCrouch = {
	Crouch = 1, Waist = { -26, 0, 0 }, Neck = { 30, 0, 0 },
	RightArm = { -40, 0, 24 }, LeftArm = { -40, 0, 24 }, RightElbow = 20, LeftElbow = 20,
	RightLeg = { 20, 0, 8 }, LeftLeg = { 30, 0, 6 }, RightKnee = 70, LeftKnee = 80,
}
function Effects.ColoradoSmash(char, data, isLocal, ability)
	local root = charParts(char)
	if not root then
		return
	end
	if not (ability and ability.Hold) then
		-- (not aimed from the sky: off at once, at the aim point)
		return Effects.ColoradoGo(char, { Pos = aimGround(root, data, (ability and ability.Range) or 160), Time = ability and ability.TravelTime }, isLocal, ability)
	end
	local token = {}
	VFX.coloradoCharge[char] = token
	local g = groundPoint(root.Position)
	shockDisc(g + UP * 0.3, UP, 3, 18, 0.4, WIND)
	VFX.PlaySound("MuscleRumble", root.Position, 0.8)
	local t0 = os.clock()
	while VFX.coloradoCharge[char] == token and root.Parent and os.clock() - t0 < (ability.Hold.Max or 6) + 0.5 do
		VFX.Pose(char, "ColoradoCrouch", 0.3)
		-- the wind pulled in to his legs, the street cracking under them
		local p = g + Vector3.new(rand(-10, 10), rand(0.5, 4), rand(-10, 10))
		local toward = root.Position - p
		streaks(p, toward.Magnitude > 0.1 and toward.Unit or UP, 1, 1, 4, 6, WIND, 0.25)
		if rng:NextNumber() < 0.3 then
			dustPuffs(g + Vector3.new(rand(-3, 3), 0, rand(-3, 3)), 0.5, 1, Color3.fromRGB(206, 196, 186), 0.6, false)
		end
		task.wait(0.12)
	end
end

-- the server: he goes (Pos: where he comes down). Everyone sees the ring
-- where he'll land (and a cut if they're there); his own machine flies him
function Effects.ColoradoGo(char, data, isLocal, ability)
	local root = charParts(char)
	local target = typeof(data.Pos) == "Vector3" and data.Pos
	if not root or not target then
		return
	end
	VFX.coloradoCharge[char] = nil
	ability = ability or Config.FindAbilityById("ColoradoSmash") or {}
	local mine = isLocal or (Players.LocalPlayer and Players.LocalPlayer.Character == char)
	local travel = tonumber(data.Time) or ability.TravelTime or 1.5
	local height = ability.Height or 105
	local flatDist = Vector3.new(target.X - root.Position.X, 0, target.Z - root.Position.Z).Magnitude
	local d = flatten(target - root.Position, root)
	landingMarker(target, travel + 0.3)
	if mine then
		face(root, d)
		VFX.Cinematic(char, {
			{ T = 0.3, From = { V(4, -2, -7), "root" }, To = { V(3.5, -2.2, -6), "root" }, Fov = { 55, 50 } },
			{ T = travel * 0.5, Cut = true, Follow = true, From = { V(6, -4, 14), "root" }, To = { V(4, -8, 20), "root" }, Fov = { 70, 80 } },
			{ T = travel * 0.5 + 0.9, Cut = true, From = { V(18, 45, -flatDist + 30), V(0, -3, -flatDist) }, To = { V(14, 30, -flatDist + 24), V(0, -3, -flatDist) }, Fov = { 70, 70 } },
		}, { Title = ability.Name or "COLORADO SMASH", Color = GOLD, Own = true })
	else
		local me = Players.LocalPlayer and Players.LocalPlayer.Character
		local myRoot = me and me:FindFirstChild("HumanoidRootPart")
		if Cine.Enabled and Cine.Witness ~= false and myRoot then
			local dist = (myRoot.Position - target).Magnitude
			if dist <= (Cine.WitnessRadius or 90) then
				VFX.Cinematic(me, witnessShots(dist), { Title = "COLORADO SMASH", Color = GOLD, Face = target })
			end
		end
	end
	VFX.Motion(char, "ColoradoSmash")
	task.wait(0.3)
	if not root.Parent then
		return
	end
	-- takeoff
	local from = root.Position
	local g = groundPoint(from)
	shockDisc(g + UP * 0.5, UP, 4, 40, 0.4, WIND)
	billboardRing(g + UP, 4, 30, Color3.new(1, 1, 1), 8, 0.3)
	dustPuffs(g, 1.6, 8, Color3.fromRGB(206, 196, 186), 1.2, true)
	rocks(g, 1.8, 10)
	VFX.PlaySound("ColoradoLeap", g, 1)
	VFX.ShakeAt(g, 1.5, 80, 0.3)
	local stopTrail = addTrail(root, GOLD, 0.4, 3)
	if mine then
		VFX.Hooks.SpeedLines(travel)
		-- ride the arc: a velocity that keeps steering back onto it
		local dest = target + UP * 3
		local att = Instance.new("Attachment")
		att.Parent = root
		local lv = Instance.new("LinearVelocity")
		lv.Attachment0 = att
		lv.MaxForce = moverForce(root, 20000)
		lv.RelativeTo = Enum.ActuatorRelativeTo.World
		lv.Parent = root
		local t0 = os.clock()
		while root.Parent do
			local t = os.clock() - t0
			local s = math.clamp(t / travel, 0, 1)
			local p1 = arcPosition(from, dest, height, s)
			local p2 = arcPosition(from, dest, height, math.clamp((t + 1 / 30) / travel, 0, 1))
			lv.VectorVelocity = (p2 - p1) * 30 + (p1 - root.Position) * 6
			if s >= 1 then
				break
			end
			streaks(root.Position, (p1 - p2).Magnitude > 0.01 and (p1 - p2).Unit or UP, 2, 2, 6, 12, WIND, 0.2)
			RunService.Heartbeat:Wait()
		end
		lv:Destroy()
		att:Destroy()
		if root.Parent then
			root.AssemblyLinearVelocity = Vector3.new(0, -160, 0) -- keep crashing through whatever is left
		end
	else
		local t0 = os.clock()
		while os.clock() - t0 < travel and root.Parent do
			streaks(root.Position, -UP, 2, 2, 6, 12, WIND, 0.2)
			task.wait(0.05)
		end
	end
	stopTrail(0)
end

-- Server: everyone else sees where he's coming down (+ a cut if you're there)
function Effects.ColoradoAim(char, data)
	local pos = typeof(data.Pos) == "Vector3" and data.Pos
	if not pos then
		return
	end
	landingMarker(pos, (data.Time or 1.5) + 0.3)
	local me = Players.LocalPlayer and Players.LocalPlayer.Character
	local myRoot = me and me:FindFirstChild("HumanoidRootPart")
	if Cine.Enabled and Cine.Witness ~= false and myRoot and me ~= char then
		local dist = (myRoot.Position - pos).Magnitude
		if dist <= (Cine.WitnessRadius or 90) then
			VFX.Cinematic(me, witnessShots(dist), { Title = "COLORADO SMASH", Color = GOLD, Face = pos })
		end
	end
end

-- Server: he hit the ground
function Effects.ColoradoLand(char, data)
	local root = charParts(char)
	local pos = typeof(data.Pos) == "Vector3" and data.Pos or (root and groundPoint(root.Position))
	if not pos then
		return
	end
	if root then
		VFX.Pose(char, "Land", 0.6)
	end
	if nearCamera(pos, 160) then
		VFX.ImpactFrame(0.12)
		VFX.Hooks.Flash(Color3.new(1, 1, 1), 0.3)
	end
	windBlast(pos + UP * 2, UP, 1.8)
	shockDisc(pos + UP * 0.5, UP, 6, 80, 0.55, WIND)
	shockDisc(pos + UP * 1, UP, 4, 60, 0.45, GOLD)
	billboardRing(pos + UP, 4, 50, Color3.new(1, 1, 1), 10, 0.4)
	for i = 1, 14 do
		local a = i / 14 * math.pi * 2
		dustPuffs(pos + Vector3.new(math.cos(a), 0, math.sin(a)) * rand(8, 22), 2.2, 2, Color3.fromRGB(206, 196, 186), 1.6, true)
	end
	rocks(pos, 3, 24)
	groundMark(pos, 18, Color3.fromRGB(52, 46, 44), 8)
	VFX.PlaySound("ColoradoImpact", pos, 1.2)
	VFX.ShakeAt(pos, 4, 220, 0.8)
end

---------------------------------------------------------------------------
-- (round 101, awaken_m) THE MATTER HEROES' AWAKENINGS - Creati, Suneater,
-- Kamui Woods, Overhaul, Shigaraki, Mr. Compress, Twice, Hawks: each one's
-- own part of the kit (VFX.AK.FX.<Quirk>) lives in his own section; these
-- are the few bits they share (VFX.AK.M): how far something growing out of
-- him toward the camera may reach and stay off its lens, a part of his own
-- hidden for the activation and given back exactly, a beat on his clock,
-- something drawn every frame while his run lasts, his clips' keys for a
-- place without them.
-- (Its own function: the main chunk's locals stay as they are.)
---------------------------------------------------------------------------
;(function()
	local AK = VFX.AK
	if not AK then
		return
	end
	local M = { held = {} }
	AK.M = M
	-- the clips' named keys (anim/moves_awaken_m.py, Hawks' retimed
	-- moves_hawks_ult.py), for a place without them
	for _, name in { "MoveAwakenCreation", "MoveAwakenManifest", "MoveAwakenArbor", "MoveAwakenOverhaul", "MoveAwakenDecay", "MoveAwakenCompress", "MoveAwakenDouble", "MoveHawksAwaken" } do
		AK.MARKS[name] = { Gather = 0.18, Hit = 0.3, Hold = 0.42, HoldEnd = 1.38 }
	end
	-- fn() at t seconds after the press (his clock, AK.at) - not if the run's over by then
	function M.at(ctx, t, fn, ...)
		local args = table.pack(...)
		task.spawn(function()
			if AK.at(ctx, t) then
				local ok, err = pcall(fn, table.unpack(args, 1, args.n))
				if not ok then
					warn("[VFX] AK " .. tostring(ctx.q) .. ": " .. tostring(err))
				end
			end
		end)
	end
	-- (his own screen) how far something reaching out from `from` along the
	-- unit `dir` may go - up to len - and keep radius r plus Config.Awaken.Lens
	-- clear of every eye of his cutscene (it stops short of the camera); len
	-- on anyone else's screen
	function M.reach(ctx, from, dir, len, r)
		if not ctx.mine or not ctx.eyes or typeof(from) ~= "Vector3" or typeof(dir) ~= "Vector3" then
			return len
		end
		local lens = ((Config.Awaken or {}).Lens or 4) + (tonumber(r) or 0)
		local L = len
		for _, eye in ctx.eyes do
			local rel = eye - from
			local along = rel:Dot(dir)
			local perp2 = rel:Dot(rel) - along * along
			if perp2 < lens * lens and along > -lens then
				-- (it would enter the eye's sphere: stop where it touches it)
				L = math.min(L, math.max(along - math.sqrt(lens * lens - perp2), 0))
			end
		end
		return L
	end
	-- parts of his own hidden on this screen for the run (a hat he takes off):
	-- one shared record a part (counted: the first hold keeps its own look, the
	-- last to let go gives it back - whether it's in the world right now or
	-- not, the place streams), held hidden while the run's on, given back when
	-- it ends (the release, or called off).
	-- ((round 101 review) pick(part) -> true: also every part of his body that
	-- matches, now or arriving while the run's on - the server rebuilds his
	-- gear on the hit (applyPassives -> applyGear: a NEW hat, a new cane, ~a
	-- ping after it), and a hat hidden by the part would have come straight
	-- back on his head while it's in his hand)
	function M.hide(ctx, parts, pick)
		local mine, taken = {}, {}
		local function take(p)
			if typeof(p) ~= "Instance" or not p:IsA("BasePart") or taken[p] then
				return
			end
			taken[p] = true
			local rec = M.held[p]
			if rec then
				rec.n += 1
			else
				local ok, ltm = pcall(function()
					return p.LocalTransparencyModifier
				end)
				M.held[p] = { n = 1, ltm = ok and ltm or 0 }
			end
			p.LocalTransparencyModifier = 1
			table.insert(mine, p)
		end
		local function scan()
			for _, d in ctx.char:GetDescendants() do
				if d:IsA("BasePart") and not taken[d] and pick(d) then
					take(d)
				end
			end
		end
		for _, p in parts or {} do
			take(p)
		end
		local conn
		if type(pick) == "function" and typeof(ctx.char) == "Instance" then
			scan()
			conn = ctx.char.DescendantAdded:Connect(function(d)
				if not ctx.done and d:IsA("BasePart") and pick(d) then
					take(d)
				end
			end)
		end
		if #mine == 0 and not conn then
			return
		end
		task.spawn(function()
			while not ctx.done do
				task.wait(0.05)
				if conn then
					pcall(scan) -- (anything DescendantAdded saw before its name was set)
				end
				for _, p in mine do
					pcall(function()
						if p.Parent and p.LocalTransparencyModifier ~= 1 then
							p.LocalTransparencyModifier = 1 -- (nothing else shows it in the meantime)
						end
					end)
				end
			end
			if conn then
				conn:Disconnect()
			end
			for _, p in mine do
				local rec = M.held[p]
				if rec then
					rec.n -= 1
					if rec.n <= 0 then
						M.held[p] = nil
						pcall(function()
							p.LocalTransparencyModifier = rec.ltm
						end)
					end
				end
			end
		end)
	end
	-- step(e) every frame for `life` seconds from now (e: seconds since), then
	-- done(); cut short (done() at once) if the run's called off
	function M.drive(ctx, life, step, done)
		local t0 = os.clock()
		local conn
		local function finish()
			if conn then
				conn:Disconnect()
				conn = nil
			end
			if done then
				pcall(done)
				done = nil
			end
		end
		conn = RunService.RenderStepped:Connect(function()
			local e = os.clock() - t0
			if e > life or ctx.dead or not ctx.root.Parent then
				finish()
				return
			end
			local ok = pcall(step, e)
			if not ok then
				finish()
			end
		end)
		return finish
	end
end)()

---------------------------------------------------------------------------
-- DECAY (fully awakened)
---------------------------------------------------------------------------

do -- DECAY: its helpers stay local to this block (Luau allows 200 locals per scope)
	-- (round 83) Shigaraki's look, rebuilt on one kit - DY, VFX.DecayKit (VFX.DK
	-- is Denki's) - in the anime's language. Decay is dry, not hot: dark
	-- cracks run on unbroken over the street with one hot point at the front;
	-- what they reach goes grey, lifts and crumbles; a low beige-grey surge of
	-- dust rolls along the front with broken shapes in it; bodies crust over
	-- in stone and flake, and a KO is a heap of ash. Red is only the front of
	-- a crack, Rivet Stab's lines and his own arm. All of it is anchored and
	-- tweened (no physics), at most one Highlight a cast, and the big moves
	-- halve on a low-end machine (IceKit.lowEnd).
	local DY = {
		CAP = 140, -- (live slabs and chunks: past it the oldest goes)
		slots = {},
		n = 0,
		bodies = setmetatable({}, { __mode = "k" }), -- [character] = its crust
		fading = setmetatable({}, { __mode = "k" }), -- [character] = a crust still flaking away
		ashed = setmetatable({}, { __mode = "k" }), -- [character] = when it went to ash
		filterAt = -10,
		tintToken = 0,
	}
	VFX.DecayKit = DY
	local PAL = {
		DUST_LIGHT = Color3.fromRGB(196, 184, 164), -- Deika's beige dust (ep 112)
		DUST_HI = Color3.fromRGB(222, 212, 194), -- the lit tops of the billows
		DUST_MID = Color3.fromRGB(176, 165, 152), -- the surge's billows
		DUST = Color3.fromRGB(150, 140, 142),
		DUST_MAP = Color3.fromRGB(116, 106, 110), -- (the server's greyed rim, Destruction)
		ASH = Color3.fromRGB(70, 60, 66),
		CHAR = Color3.fromRGB(38, 32, 36), -- decayed bodies (ep 109)
		CRACK = Color3.fromRGB(36, 26, 30),
		RED = Color3.fromRGB(214, 62, 66),
		HOT = Color3.fromRGB(255, 118, 104), -- the front of a crack
		LILAC = Color3.fromRGB(176, 164, 196), -- X-Less's mosaic, the Jaku light (ep 118)
		MAUVE = Color3.fromRGB(132, 118, 142), -- the dust swirling up in All For One's light
		STONE = Color3.fromRGB(168, 158, 146), -- a decaying body's crust
		TINT = Color3.fromRGB(226, 214, 238), -- the ult's purple air
		VIOLET = Color3.fromRGB(170, 80, 255), -- the edge of All For One's black lightning
		BLACK = Color3.fromRGB(16, 8, 24),
		TENDRIL = Color3.fromRGB(14, 10, 14),
		AMBER = Color3.fromRGB(255, 186, 90), -- Air Cannon's orb (ep 119)
		OLIVE = Color3.fromRGB(190, 196, 96), -- Radio Waves' blast over the street
		-- (round 84) Radio Waves as ep 119 draws it
		GOLD = Color3.fromRGB(255, 214, 110), -- Air Cannon's bubble and its bright rim
		CORE = Color3.fromRGB(255, 250, 222), -- its white-hot middle
		VIOLET_DEEP = Color3.fromRGB(140, 96, 230), -- the bubble's inside when it flickers violet
		HAZE = Color3.fromRGB(184, 196, 98), -- the yellow-green air the blast leaves
		YELLOW = Color3.fromRGB(240, 252, 128), -- the bright yellow streaks tearing out in it
		STATIC = Color3.fromRGB(150, 196, 255), -- a jammed body's static (ep 120)
		TOOTH = Color3.fromRGB(92, 84, 102), -- things breaking up inside the surge
	}
	DY.PAL = PAL
	local NS, NK = NumberSequence.new, NumberSequenceKeypoint.new
	local SMOKE = (Config.Assets and Config.Assets.SmokeTexture) or "rbxasset://textures/particles/smoke_main.dds"
	-- a quirk's hits can carry a tint of their own (Effects.Hit): Decay's are dust, not red
	VFX.HitTints = VFX.HitTints or {}
	VFX.HitTints.Decay = PAL.DUST_LIGHT

	-- half as much on a low-end machine
	function DY.k()
		return IceKit.lowEnd() and 0.5 or 1
	end

	-- a ray past the fighters (the filter refreshed twice a second); the hit or nil
	DY.params = RaycastParams.new()
	DY.params.FilterType = Enum.RaycastFilterType.Exclude
	function DY.cast(from, v)
		if os.clock() - DY.filterAt > 0.5 then
			DY.filterAt = os.clock()
			DY.params.FilterDescendantsInstances = characterList()
		end
		return workspace:Raycast(from, v, DY.params)
	end
	-- the street under pos (no street: height y, or pos's own), and the hit
	function DY.ground(pos, y)
		local hit = DY.cast(pos + UP * 3, Vector3.new(0, -16, 0))
		return Vector3.new(pos.X, hit and hit.Position.Y or (y or pos.Y), pos.Z), hit
	end
	-- what the street's made of: a plate lifts in its own colour
	function DY.colorOf(hit)
		local inst = hit and hit.Instance
		if typeof(inst) == "Instance" and inst:IsA("BasePart") and not inst:IsA("Terrain") then
			return inst.Color
		end
		return Color3.fromRGB(120, 112, 108)
	end
	-- every lifting plate / chunk takes a slot; past CAP the oldest goes
	function DY.track(p)
		local i = DY.n % DY.CAP + 1
		local old = DY.slots[i]
		if old and old ~= p and old.Parent then
			old:Destroy()
		end
		DY.slots[i] = p
		DY.n += 1
		return p
	end
	-- welded on to a limb (IceKit.frostBody's way): it moves with the body
	function DY.stick(limbPart, p)
		local w = Instance.new("Weld")
		w.Part0 = limbPart
		w.Part1 = p
		w.C0 = limbPart.CFrame:ToObjectSpace(p.CFrame)
		w.Parent = p
		p.Massless = true
		p.Anchored = false
	end

	-- A shell over a head: (size, cframe, shape). An R6 head is a 2x1x1 box
	-- round a ~1.25-stud rounded-cylinder mesh (IceKit.frostBody's note), so
	-- a ball pokes through it and sinks in by turns: a stood-up cylinder just
	-- over the mesh instead. R15 heads (MeshParts) get a ball, k x their
	-- smallest side.
	function DY.headFit(char, head, k)
		local s = head.Size
		if char:FindFirstChild("Torso") then
			return Vector3.one * s.Y * (k + 0.1), head.CFrame * CFrame.Angles(0, 0, math.pi / 2), Enum.PartType.Cylinder
		end
		return Vector3.one * math.min(s.X, s.Y, s.Z) * k, head.CFrame, Enum.PartType.Ball
	end

	-- how hidden a body part is on this screen (hideCharacter, first person):
	-- its LocalTransparencyModifier, 0 when there's none to read
	function DY.ltmOf(p)
		return p.LocalTransparencyModifier
	end
	function DY.hiddenBy(p)
		local ok, v = pcall(DY.ltmOf, p)
		return ok and type(v) == "number" and v or 0
	end

	-- whose body this is (the player, or nil for a dummy / NPC)
	function DY.ownerOf(char)
		return Players:GetPlayerFromCharacter(char)
	end

	-- an attachment at pos to hang a burst of particles on (in the Terrain: no
	-- part; IceKit's way), gone after `life`
	function DY.anchor(pos, life)
		local att = Instance.new("Attachment")
		att.Name = "DecayFX"
		local ok, terrain = pcall(function()
			return workspace.Terrain
		end)
		if ok and terrain then
			att.Parent = terrain
			att.WorldPosition = pos
			cleanup(att, life)
		else
			local holder = newPart(Vector3.one * 0.2, CFrame.new(pos), PAL.ASH)
			holder.Transparency = 1
			att.Parent = holder
			cleanup(holder, life)
		end
		return att
	end

	-- flat flakes peeling off and fluttering down (ep 11: the sleeve)
	function DY.flakes(pos, n, k, c0, c1)
		if typeof(pos) ~= "Vector3" then
			return
		end
		k = k or 1
		local holder = DY.anchor(pos, 1.4)
		local pe = Instance.new("ParticleEmitter")
		pe.Texture = "rbxasset://textures/triangle.png"
		pe.Color = ColorSequence.new(c0 or PAL.DUST, c1 or PAL.ASH)
		pe.LightInfluence = 1
		pe.Size = NS({ NK(0, 0.38 * k), NK(1, 0.16 * k) })
		pe.Squash = NS({ NK(0, -0.5), NK(0.5, 0.5), NK(1, -0.5) })
		pe.Transparency = NS({ NK(0, 0), NK(0.8, 0.1), NK(1, 1) })
		pe.Lifetime = NumberRange.new(0.6, 1.2)
		pe.Speed = NumberRange.new(5 * k, 12 * k)
		pe.SpreadAngle = Vector2.new(70, 70)
		pe.Drag = 2
		pe.Acceleration = Vector3.new(0, -14, 0)
		pe.Rotation = NumberRange.new(0, 360)
		pe.RotSpeed = NumberRange.new(-400, 400)
		pe.Enabled = false
		pe.Parent = holder
		pe:Emit(math.max(math.floor((n or 6) * DY.k()), 1))
	end

	-- A CRACK that runs on unbroken over the street: a chain of dark slabs on
	-- the ground (a ray at every joint), each growing out of the last at
	-- `speed` studs/s, wandering a little either side and narrowing to the
	-- tip, one hot point riding the front. Now and then a branch splits off.
	-- o: { speed (math.huge: all at once), w0, w1 (width at the root, the
	-- tip), step (studs a joint), wander, branch (chance at every third
	-- joint), hot (false: no hot point), life, delay, color }. Returns its
	-- joints (the last is the tip) and when it gets there.
	function DY.crack(from, dir, len, o)
		o = o or {}
		local flat = typeof(dir) == "Vector3" and Vector3.new(dir.X, 0, dir.Z) or Vector3.zero
		if typeof(from) ~= "Vector3" or flat.Magnitude < 0.05 or not len or len < 0.4 then
			return { from }, 0
		end
		flat = flat.Unit
		local right = flat:Cross(UP)
		local speed = math.max(o.speed or 120, 1)
		local step = o.step or 4
		local n = math.clamp(math.floor(len / step + 0.5), 1, 24)
		local wander = o.wander or 1.2
		local w0, w1 = o.w0 or 0.7, o.w1 or 0.2
		local life = o.life or 4
		local pts, lat, y = { from }, 0, from.Y
		for i = 1, n do
			-- (jagged: every joint pulls toward a fresh offset, so it never runs along the edge)
			lat = math.clamp(lat * 0.5 + rand(-0.8, 0.8) * wander, -wander, wander)
			local g = DY.ground(from + flat * (len * i / n) + right * lat, y)
			y = g.Y
			pts[i + 1] = g
		end
		local due, total = { 0 }, 0
		for i = 2, #pts do
			total += (pts[i] - pts[i - 1]).Magnitude
			due[i] = total / speed
		end
		task.spawn(function()
			local t0 = os.clock() + (o.delay or 0)
			local tip
			if o.hot ~= false then
				tip = newPart(Vector3.new(w0 * 1.3, 0.14, 1.1), CFrame.lookAt(from + UP * 0.1, from + UP * 0.1 + flat), PAL.HOT, Enum.Material.Neon)
				tip.Transparency = 1
			end
			for i = 2, #pts do
				local wait = t0 + due[i - 1] - os.clock()
				if wait > 0 then
					task.wait(wait)
				end
				local a, b = pts[i - 1] + UP * 0.07, pts[i] + UP * 0.07
				local seg = (b - a).Magnitude
				if seg > 0.05 then
					local w = w0 + (w1 - w0) * (due[i - 1] / math.max(due[#pts], 1e-6))
					local t = seg / speed
					local p = newPart(Vector3.new(w, 0.1, 0.05), CFrame.lookAt(a, b), o.color or PAL.CRACK)
					local goal = { Size = Vector3.new(w, 0.1, seg + w * 0.6), CFrame = CFrame.lookAt((a + b) / 2, b) }
					if t > 0.02 then
						tween(p, t, goal, Enum.EasingStyle.Linear)
					else
						p.Size, p.CFrame = goal.Size, goal.CFrame
					end
					tween(p, 1.2, { Transparency = 1 }, Enum.EasingStyle.Linear, nil, t + life)
					cleanup(p, t + life + 1.3)
					if tip then
						tip.Transparency = 0
						tween(tip, math.max(t, 0.01), { CFrame = CFrame.lookAt(b + UP * 0.03, b + UP * 0.03 + (b - a).Unit) }, Enum.EasingStyle.Linear)
					end
					if o.branch and i % 3 == 0 and i < #pts and rng:NextNumber() < o.branch then
						local turn = math.rad(rand(30, 50)) * (rng:NextNumber() < 0.5 and -1 or 1)
						DY.crack(pts[i - 1], flat * math.cos(turn) + right * math.sin(turn), math.min(rand(0.25, 0.4) * len, 12), {
							speed = speed, w0 = w * 0.6, w1 = 0.1, step = math.max(3, step * 0.6), wander = 0.6, hot = false, life = life, color = o.color,
						})
					end
				end
			end
			if tip then
				tween(tip, 0.25, { Transparency = 1, Size = Vector3.new(0.1, 0.1, 0.3) })
				cleanup(tip, 0.3)
			end
		end)
		return pts, due[#pts] + (o.delay or 0)
	end

	-- FIVE FINGERS: where his hand meets the street, the print of a palm and
	-- five cracks fanning out of the fingertips (their hot points together
	-- read as a red hand for a blink), a red rim round the print. Returns the
	-- fingers' tips.
	function DY.fingers(palm, dir, len, o)
		o = o or {}
		local flat = Vector3.new(dir.X, 0, dir.Z)
		flat = flat.Magnitude > 0.05 and flat.Unit or Vector3.new(0, 0, -1)
		local right = flat:Cross(UP)
		local g = DY.ground(palm)
		local lay = CFrame.new(g + UP * 0.06) * CFrame.lookAt(Vector3.zero, flat) * CFrame.Angles(0, 0, math.rad(90))
		local mark = newPart(Vector3.new(0.1, 1.7, 2), lay, PAL.CRACK, Enum.Material.SmoothPlastic, Enum.PartType.Cylinder)
		tween(mark, 1.2, { Transparency = 1 }, Enum.EasingStyle.Linear, nil, o.life or 4)
		cleanup(mark, (o.life or 4) + 1.3)
		local rim = newPart(Vector3.new(0.08, 2.1, 2.4), lay - UP * 0.01, PAL.RED, Enum.Material.Neon, Enum.PartType.Cylinder)
		tween(rim, 0.2, { Transparency = 1 }, Enum.EasingStyle.Quad, Enum.EasingDirection.In, 0.12)
		cleanup(rim, 0.35)
		local tips = {}
		for i, a in { -38, -19, 0, 19, 38 } do
			local fd = flat * math.cos(math.rad(a)) + right * math.sin(math.rad(a))
			local pts = DY.crack(g + fd * 0.9, fd, len * (i == 3 and 1 or rand(0.7, 0.92)), {
				speed = o.speed or 70, w0 = 0.42, w1 = 0.12, step = 1.6, wander = 0.45, life = o.life or 4,
			})
			tips[i] = pts[#pts]
		end
		return tips
	end

	-- THE PALM ON THE STREET: the five fingers, a low ring of dust hugging the
	-- ground, a dusty shock ring, a shake. o.frame: the big moves' impact
	-- frame (black and white, tinted lilac) for that long. o: { len, k, frame, radius }
	function DY.palm(pos, dir, o)
		o = o or {}
		local k = o.k or 1
		local g = DY.ground(pos)
		local tips = DY.fingers(g, dir, (o.len or 5) * k, o)
		for i = 1, 6 do
			local a = i / 6 * math.pi * 2 + rand(-0.3, 0.3)
			local out = Vector3.new(math.cos(a), 0, math.sin(a))
			celPuff(folder, g + out * 0.8, g + out * rand(2.5, 4) * k + UP * rand(0.6, 1.4) * k, rand(1.6, 2.6) * k, PAL.DUST, PAL.DUST_HI, 0.18, rand(0.6, 1), i * 0.01)
		end
		shockDisc(g + UP * 0.3, UP, 2, 14 * k, 0.3, PAL.DUST_LIGHT)
		VFX.ShakeAt(g, 0.8 * k, 60, 0.15)
		if o.frame and VFX.MANGA then
			VFX.MANGA.impact(g, o.frame, { Tint = PAL.TINT, Radius = o.radius or 90, Contrast = 1.25, Brightness = 0.08 })
		end
		return tips, g
	end

	-- A PLATE of the street lifting where the decay reaches it, in the
	-- street's own colour: it rises and tips, greys over, then crumbles away.
	-- o: { delay, rise, hold, tilt, yaw (CFrames), size3 (a Vector3), float
	-- (it floats up in the dust with dust pouring off it, ep 112), lift (how
	-- high it floats), flakes (chance) }
	function DY.slab(pos, size, o)
		o = o or {}
		local g, hit = DY.ground(pos)
		local d0 = o.delay or 0
		local dims = o.size3 or Vector3.new(size * rand(0.8, 1.15), math.clamp(size * 0.22, 0.4, 1.4), size * rand(0.6, 1))
		local yaw = o.yaw or CFrame.Angles(0, rand(0, math.pi * 2), 0)
		local p = newPart(dims, CFrame.new(g + UP * dims.Y * 0.25) * yaw, DY.colorOf(hit):Lerp(PAL.DUST_MAP, 0.35), Enum.Material.Slate)
		DY.track(p)
		local tilt = o.tilt or CFrame.Angles(math.rad(rand(8, 25) * (rng:NextNumber() < 0.5 and -1 or 1)), 0, math.rad(rand(-12, 12)))
		local rise = o.rise or (o.float and rand((o.lift or 6) * 1, (o.lift or 6) * 2.3) or rand(0.6, 2))
		local up = CFrame.new(g + UP * (dims.Y * 0.25 + rise)) * tilt * yaw
		local riseT = o.float and 0.9 or rand(0.12, 0.18)
		tween(p, riseT, { CFrame = up }, o.float and Enum.EasingStyle.Sine or Enum.EasingStyle.Quad, Enum.EasingDirection.Out, d0)
		tween(p, 0.45, { Color = PAL.DUST }, Enum.EasingStyle.Linear, nil, d0 + 0.08)
		local gone = d0 + riseT + (o.hold or rand(0.2, 0.45))
		tween(p, 0.35, { Size = dims * 0.25, Transparency = 1, CFrame = up - UP * 0.5 }, Enum.EasingStyle.Quad, Enum.EasingDirection.In, gone)
		cleanup(p, gone + 0.4)
		if rng:NextNumber() < (o.flakes or 0.3) then
			task.delay(gone, DY.flakes, up.Position, 4, math.clamp(size * 0.35, 0.5, 1.5))
		end
		if o.float then
			-- the dust pouring off its underside, in streaks
			local drop = rand(3, 6)
			local drip = newPart(Vector3.new(dims.X * 0.5, 0.2, dims.Z * 0.3), CFrame.new(up.Position - UP * dims.Y), PAL.DUST_MAP)
			drip.Transparency = 1
			tween(drip, riseT, { Size = Vector3.new(dims.X * 0.4, drop, dims.Z * 0.25), CFrame = CFrame.new(up.Position - UP * (dims.Y + drop / 2)), Transparency = 0.3 }, Enum.EasingStyle.Sine, Enum.EasingDirection.Out, d0 + riseT * 0.4)
			tween(drip, 0.4, { Transparency = 1 }, Enum.EasingStyle.Quad, Enum.EasingDirection.In, gone)
			cleanup(drip, gone + 0.45)
		end
		return p
	end

	-- a jagged dark shape breaking up in the dust (the buildings in ep 118's surge)
	function DY.tooth(pos, h, w, delayTime)
		local g = DY.ground(pos)
		local d0 = delayTime or 0
		local t = IceKit.wedge(folder, PAL.TOOTH, Enum.Material.Slate)
		t.Reflectance = 0
		local yaw = CFrame.Angles(0, rand(0, math.pi * 2), 0)
		local full = Vector3.new(w * rand(0.25, 0.45), h, w)
		t.Size = Vector3.new(full.X, 0.2, full.Z)
		t.CFrame = CFrame.new(g) * yaw
		tween(t, 0.12, { Size = full, CFrame = CFrame.new(g + UP * h / 2) * yaw * CFrame.Angles(rand(-0.25, 0.25), 0, rand(-0.25, 0.25)) }, Enum.EasingStyle.Quad, Enum.EasingDirection.Out, d0)
		local gone = d0 + 0.12 + rand(0.15, 0.3)
		tween(t, 0.4, { Size = Vector3.new(full.X * 0.5, h * 0.2, full.Z * 0.6), CFrame = CFrame.new(g + UP * h * 0.1) * yaw, Transparency = 1 }, Enum.EasingStyle.Quad, Enum.EasingDirection.In, gone)
		cleanup(t, gone + 0.45)
	end

	-- a two-tone billow of dust that swells, holds, then drifts up and thins
	-- o: { from, delay, grow, hold, fade, rise, dark, light }
	function DY.billow(pos, size, o)
		o = o or {}
		local d0 = o.delay or 0
		local from = o.from or pos
		local body = newPart(Vector3.one * size * 0.2, CFrame.new(from), o.dark or PAL.DUST, nil, Enum.PartType.Ball)
		local hi = newPart(Vector3.one * size * 0.15, CFrame.new(from), o.light or PAL.DUST_HI, nil, Enum.PartType.Ball)
		local off = Vector3.new(-0.1, 0.2, 0.05) * size
		local grow, hold, fade = o.grow or 0.5, o.hold or 0.6, o.fade or 1.2
		tween(body, grow, { Size = Vector3.one * size, CFrame = CFrame.new(pos) }, Enum.EasingStyle.Quad, Enum.EasingDirection.Out, d0)
		tween(hi, grow, { Size = Vector3.one * size * 0.74, CFrame = CFrame.new(pos + off) }, Enum.EasingStyle.Quad, Enum.EasingDirection.Out, d0)
		local rise = pos + UP * (o.rise or size * 0.4) + Vector3.new(rand(-1, 1), 0, rand(-1, 1)) * size * 0.15
		tween(body, fade, { Size = Vector3.one * size * 1.15, CFrame = CFrame.new(rise), Transparency = 1 }, Enum.EasingStyle.Sine, Enum.EasingDirection.In, d0 + grow + hold)
		tween(hi, fade, { Size = Vector3.one * size * 0.8, CFrame = CFrame.new(rise + off), Transparency = 1 }, Enum.EasingStyle.Sine, Enum.EasingDirection.In, d0 + grow + hold)
		cleanup(body, d0 + grow + hold + fade + 0.05)
		cleanup(hi, d0 + grow + hold + fade + 0.05)
	end

	-- THE SURGE (ep 118): a low wall of beige-grey dust rolling along the
	-- front at `speed` - real smoke riding it, billows thrown up at the front
	-- with jagged dark shapes breaking up inside, haze left behind it
	-- o: { delay, teeth (false: none) }
	function DY.surge(from, dir, len, width, speed, h, o)
		o = o or {}
		local flat = Vector3.new(dir.X, 0, dir.Z)
		if flat.Magnitude < 0.05 or len <= 0 then
			return
		end
		flat = flat.Unit
		local right = flat:Cross(UP)
		local k = DY.k()
		local t = len / math.max(speed, 1)
		local d0 = o.delay or 0
		local cf0 = CFrame.lookAt(from + UP * h * 0.35, from + UP * h * 0.35 + flat)
		local holder = newPart(Vector3.new(width, h * 0.3, 2), cf0, PAL.DUST)
		holder.Transparency = 1
		local pe = Instance.new("ParticleEmitter")
		pe.Texture = SMOKE
		pe.Color = ColorSequence.new(PAL.DUST_LIGHT, PAL.DUST)
		pe.LightInfluence = 0.6
		pe.Size = NS({ NK(0, h * 0.4), NK(0.4, h * 0.8), NK(1, h * 1.2) })
		pe.Transparency = NS({ NK(0, 0.25), NK(0.6, 0.55), NK(1, 1) })
		pe.Lifetime = NumberRange.new(0.8, 1.5)
		pe.Speed = NumberRange.new(2, 6)
		pe.EmissionDirection = Enum.NormalId.Front
		pe.SpreadAngle = Vector2.new(60, 25)
		pe.Drag = 1.5
		pe.Acceleration = Vector3.new(0, -1.5, 0)
		pe.Rotation = NumberRange.new(0, 360)
		pe.RotSpeed = NumberRange.new(-30, 30)
		pe.Shape = Enum.ParticleEmitterShape.Box
		pe.Rate = 60 * k
		pe.Enabled = d0 <= 0
		pe.Parent = holder
		tween(holder, t, { CFrame = cf0 + flat * len }, Enum.EasingStyle.Linear, nil, d0)
		task.delay(d0, function()
			pe.Enabled = true
			task.wait(t)
			pe.Enabled = false
		end)
		cleanup(holder, d0 + t + 1.6)
		task.spawn(function()
			if d0 > 0 then
				task.wait(d0)
			end
			local t0 = os.clock()
			while os.clock() - t0 <= t do
				local at = from + flat * ((os.clock() - t0) * speed)
				for _ = 1, k < 1 and 2 or 3 do
					local p = DY.ground(at + right * rand(-width / 2, width / 2), at.Y)
					celPuff(folder, p, p + UP * h * rand(0.5, 0.9) + flat * rand(1, 3), h * rand(0.65, 1), PAL.DUST_MID, PAL.DUST_HI, 0.2, rand(1.2, 1.8))
				end
				if o.teeth ~= false then
					DY.tooth(at + right * rand(-width * 0.4, width * 0.4) + flat * rand(-1, 2), h * rand(0.8, 1.3), rand(2, 3.5))
				end
				task.wait(0.1)
			end
		end)
	end

	-- THE SPREAD (Collapse, the awakening, Total Decay): the same layers going
	-- out in a ring in step with the server's own steps - cracks on fixed
	-- bearings racing out unbroken (each with its hot front), a band of
	-- plates lifting at the front, the surge rolling on it, a dusty ring.
	-- o: { cracks, slabs, puffs, teeth (each a step), h (the surge's
	-- height), w0, step, branch, slabScale, start, life, sound }
	function DY.ring(center, R, dur, o)
		o = o or {}
		local k = DY.k()
		local steps = math.max(3, math.floor(dur / 0.15 + 0.5))
		local n = math.max(math.floor((o.cracks or 10) * (k < 1 and 0.6 or 1)), 3)
		local speed = R / math.max(dur, 0.05)
		local start = o.start or 2
		local base = rand(0, math.pi * 2)
		for i = 1, n do
			local a = base + i / n * math.pi * 2 + rand(-0.12, 0.12)
			local dir = Vector3.new(math.cos(a), 0, math.sin(a))
			DY.crack(center + dir * start, dir, R - start, {
				speed = speed, w0 = o.w0 or 0.9, w1 = 0.25, step = o.step or math.clamp(R / 12, 3.5, 8),
				wander = math.clamp(R * 0.05, 1, 4), branch = k < 1 and 0 or (o.branch or 0.4), life = o.life or 5,
			})
		end
		local h = o.h or 7
		task.spawn(function()
			for i = 1, steps do
				local r0, r = R * (i - 1) / steps, R * i / steps
				local inner = math.min(math.max(r0, start), r)
				for _ = 1, math.floor((o.slabs or 8) * k) do
					local a = rand(0, math.pi * 2)
					DY.slab(center + Vector3.new(math.cos(a), 0, math.sin(a)) * rand(inner, r), rand(2.5, 4.5) * (o.slabScale or 1))
				end
				for _ = 1, math.floor((o.puffs or 6) * k) do
					local a = rand(0, math.pi * 2)
					local out = Vector3.new(math.cos(a), 0, math.sin(a))
					local p = DY.ground(center + out * r, center.Y)
					celPuff(folder, p, p + out * rand(1, 3) + UP * h * rand(0.5, 0.9), h * rand(0.65, 1), PAL.DUST_MID, PAL.DUST_HI, 0.2, rand(1.2, 1.8))
				end
				for _ = 1, math.floor((o.teeth or 2) * k) do
					local a = rand(0, math.pi * 2)
					DY.tooth(center + Vector3.new(math.cos(a), 0, math.sin(a)) * r, h * rand(0.8, 1.3), rand(2, 4))
				end
				shockDisc(center + UP * 0.6, UP, math.max(r0 * 2, 2), r * 2, 0.35, PAL.DUST_LIGHT)
				if o.sound ~= false and i % 2 == 1 then
					VFX.PlaySound("Crumble", center + Vector3.new(r, 0, 0), 0.6)
				end
				task.wait(dur / steps)
			end
		end)
	end

	-- Where the spread meets a wall that's left standing (the rim the server
	-- greys - what's inside it the server carves away): a crack up its face
	-- and a curtain of dust pouring down it as the front gets there. Six at
	-- most; no walls, nothing. (Only past R: a wall inside it is carved away
	-- the moment the front gets there, and a curtain would hang in the air.)
	function DY.curtains(center, R, dur)
		local made, base = 0, rand(0, math.pi * 2)
		for i = 1, 10 do
			if made >= 6 then
				break
			end
			local a = base + i / 10 * math.pi * 2
			local from = center + UP * 5
			local hit = DY.cast(from, Vector3.new(math.cos(a), 0, math.sin(a)) * (R + 20))
			local dist = hit and (hit.Position - from).Magnitude or 0
			if hit and dist > R + 1 and math.abs(hit.Normal.Y) < 0.5 then
				made += 1
				task.delay(dur, DY.curtain, hit.Position, hit.Normal)
			end
		end
	end
	function DY.curtain(at, normal)
		local side = normal:Cross(UP)
		side = side.Magnitude > 0.05 and side.Unit or Vector3.new(1, 0, 0)
		local foot = DY.ground(at, at.Y - 5)
		local base = Vector3.new(at.X, foot.Y, at.Z) + normal * 0.08
		local prev, lat = base, 0
		for j = 1, 5 do
			lat = math.clamp(lat + rand(-1, 1), -1.5, 1.5)
			local nxt = base + UP * (j * 2.6) + side * lat
			local seg = newPart(Vector3.new(0.55 - j * 0.07, 0.08, (nxt - prev).Magnitude + 0.3), CFrame.lookAt((prev + nxt) / 2, nxt, normal), PAL.CRACK)
			seg.Transparency = 1
			tween(seg, 0.04, { Transparency = 0 }, nil, nil, j * 0.04)
			tween(seg, 1, { Transparency = 1 }, Enum.EasingStyle.Linear, nil, 3)
			cleanup(seg, 4.1)
			prev = nxt
		end
		local holder = newPart(Vector3.new(5, 0.5, 1), CFrame.lookAt(base + normal + UP * 9, base + normal * 2 + UP * 9), PAL.DUST)
		holder.Transparency = 1
		local pe = Instance.new("ParticleEmitter")
		pe.Texture = SMOKE
		pe.Color = ColorSequence.new(PAL.DUST_LIGHT, PAL.DUST)
		pe.LightInfluence = 0.7
		pe.Size = NS({ NK(0, 1.5), NK(1, 4) })
		pe.Transparency = NS({ NK(0, 0.3), NK(0.7, 0.6), NK(1, 1) })
		pe.Lifetime = NumberRange.new(1, 1.6)
		pe.Speed = NumberRange.new(1, 3)
		pe.EmissionDirection = Enum.NormalId.Bottom
		pe.SpreadAngle = Vector2.new(15, 15)
		pe.Acceleration = Vector3.new(0, -22, 0)
		pe.Drag = 1
		pe.Shape = Enum.ParticleEmitterShape.Box
		pe.Rate = 30 * DY.k()
		pe.Parent = holder
		task.delay(1.2, function()
			pe.Enabled = false
		end)
		cleanup(holder, 3)
	end

	-- THE DOME (ep 112, Deika from the hillside): a mound of beige dust
	-- swelling up round the spot (a shell: the middle stays clear, so a
	-- camera inside it still sees), darker underneath, plates floating in
	-- it with dust pouring off them; it drifts up and thins away.
	-- o: { puffs, slabs, lift }
	function DY.dome(center, R, rise, life, o)
		o = o or {}
		local k = DY.k()
		for i = 1, math.floor((o.puffs or 20) * k) do
			local a = rand(0, math.pi * 2)
			local up = rand(0, 0.85) -- (0: at the foot, 1: the top)
			local out = Vector3.new(math.cos(a), 0, math.sin(a))
			local pos = center + out * R * rand(0.75, 1) * math.sqrt(1 - up * up) + UP * R * 0.6 * up
			local low = up < 0.3
			DY.billow(pos, R * rand(0.35, 0.55), {
				from = center + out * R * 0.4 + UP, delay = i * 0.015, grow = 0.6, hold = life * 0.35, fade = life * 0.65, rise = rise,
				dark = low and PAL.DUST or PAL.DUST_MID, light = low and PAL.DUST_MID or PAL.DUST_HI,
			})
		end
		smokeBurst(center + UP * R * 0.4, PAL.DUST_LIGHT, R * 0.5, R, life, math.floor(16 * k))
		for _ = 1, math.floor((o.slabs or 5) * k) do
			local a = rand(0, math.pi * 2)
			DY.slab(center + Vector3.new(math.cos(a), 0, math.sin(a)) * R * rand(0.4, 0.8), rand(3, 5), { float = true, lift = o.lift or 6, delay = rand(0.1, 0.4), hold = life * 0.5 })
		end
	end

	-- the ult's purple air (IceKit.coldTint's way): a lilac ColorCorrection
	function DY.tint(strength, hold, fade)
		local Lighting = game:GetService("Lighting")
		local cc = Lighting:FindFirstChild("DecayTint")
		if not cc then
			cc = Instance.new("ColorCorrectionEffect")
			cc.Name = "DecayTint"
			cc.Parent = Lighting
		end
		DY.tintToken += 1
		local token = DY.tintToken
		local s = math.clamp(tonumber(strength) or 1, 0, 1.5)
		cc.Enabled = true
		tween(cc, 0.1, { TintColor = Color3.new(1, 1, 1):Lerp(PAL.TINT, math.min(s, 1)), Saturation = -0.25 * s, Contrast = 0.08 * s, Brightness = 0.02 * s })
		task.delay(0.1 + (hold or 0.6), function()
			if token == DY.tintToken then
				tween(cc, fade or 1.2, { TintColor = Color3.new(1, 1, 1), Saturation = 0, Contrast = 0, Brightness = 0 }, Enum.EasingStyle.Sine)
			end
		end)
	end

	-- THE SKETCH FRAME (ep 112, Deika): for a blink the screen is a sheet of
	-- lilac-white paper with dry-brush strokes in purple-black ink swept in
	-- from the top left and fanned in from the right edge, and blots of ink
	-- spattered off their tips, boiling as it's redrawn; then the colour's back
	DY.SKETCH = {
		-- the two brushes: where the strokes start (screen fractions), the way
		-- they sweep (degrees, clockwise from the right), how wide they fan
		{ from = Vector2.new(-0.02, 0.06), spread = Vector2.new(0.02, 0.2), ang = 24, fan = 14, len = { 0.2, 0.42 } },
		{ from = Vector2.new(0.76, 0.5), spread = Vector2.new(0.01, 0.04), ang = 0, fan = 115, len = { 0.14, 0.24 } },
	}
	function DY.sketch(t)
		local MG = VFX.MANGA
		local gui = MG and MG.gui()
		if not gui then
			return
		end
		t = t or 0.12
		local v = MG.view()
		local sheet = Instance.new("Frame")
		sheet.Name = "DecaySketch"
		sheet.BackgroundColor3 = Color3.fromRGB(246, 242, 250)
		sheet.BackgroundTransparency = 0.03
		sheet.BorderSizePixel = 0
		sheet.Size = UDim2.fromScale(1, 1)
		sheet.ZIndex = 6
		sheet.Parent = gui
		local marks = {}
		for i = 1, 36 do
			local f = Instance.new("Frame")
			f.BorderSizePixel = 0
			f.AnchorPoint = Vector2.new(0.5, 0.5)
			f.BackgroundColor3 = Color3.fromRGB(46, 30, 62)
			f.ZIndex = 7
			f.Parent = sheet
			if i > 26 then
				local corner = Instance.new("UICorner")
				corner.CornerRadius = UDim.new(0.5, 0)
				corner.Parent = f
			end
			marks[i] = f
		end
		local px = v.Y / 720
		local function draw()
			-- 13 bristles a brush, each a stroke of its own length and weight
			-- fanned across the sweep; the last ten marks are blots of ink
			-- spattered near the brushes' ends
			local diag = v.Magnitude
			local i = 0
			local tips = {}
			for _, b in DY.SKETCH do
				for j = 1, 13 do
					i += 1
					local u = (j - 1) / 12
					local start = Vector2.new((b.from.X + (u - 0.5) * b.spread.X) * v.X, (b.from.Y + (u - 0.5) * b.spread.Y) * v.Y)
					local a = math.rad(b.ang + (u - 0.5) * b.fan + rand(-2, 2))
					local dir = Vector2.new(math.cos(a), math.sin(a))
					local len = diag * rand(b.len[1], b.len[2]) * (1 - math.abs(u - 0.5) * 0.6)
					local c = start + dir * len / 2
					local f = marks[i]
					f.Position = UDim2.fromOffset(c.X, c.Y)
					f.Size = UDim2.fromOffset(len, rand(2, 16) * px * (1 - math.abs(u - 0.5)))
					f.Rotation = math.deg(a)
					f.BackgroundTransparency = rand(0, 0.4)
					table.insert(tips, start + dir * len)
				end
			end
			for j = i + 1, #marks do
				local p = tips[((j * 7) % #tips) + 1] + Vector2.new(rand(-60, 60), rand(-40, 40)) * px
				local s = rand(4, 18) * px
				local f = marks[j]
				f.Position = UDim2.fromOffset(p.X, p.Y)
				f.Size = UDim2.fromOffset(s, s * rand(0.6, 1))
				f.Rotation = rand(0, 90)
				f.BackgroundTransparency = rand(0, 0.35)
			end
		end
		task.spawn(function()
			local t0 = os.clock()
			while os.clock() - t0 < t and sheet.Parent do
				draw()
				task.wait(1 / 12)
			end
			tween(sheet, 0.08, { BackgroundTransparency = 1 })
			for _, f in marks do
				tween(f, 0.08, { BackgroundTransparency = 1 })
			end
			task.wait(0.09)
			sheet:Destroy()
		end)
	end

	-- dust pouring off his hands as they come down (the server's hand dust,
	-- thickened for a moment)
	function DY.pour(char, dur, rightOnly)
		for _, right in rightOnly and { true } or { true, false } do
			local hand = limb(char, right and "RightHand" or "LeftHand", right and "Right Arm" or "Left Arm")
			if hand then
				local att = Instance.new("Attachment")
				att.Name = "DecayPour"
				att.Position = Vector3.new(0, -hand.Size.Y / 2, 0)
				att.Parent = hand
				local pe = Instance.new("ParticleEmitter")
				pe.Texture = SMOKE
				pe.Color = ColorSequence.new(PAL.DUST, PAL.ASH)
				pe.LightInfluence = 0.7
				pe.Size = NS({ NK(0, 0.5), NK(1, 1.6) })
				pe.Transparency = NS({ NK(0, 0.2), NK(0.7, 0.5), NK(1, 1) })
				pe.Lifetime = NumberRange.new(0.5, 0.9)
				pe.Speed = NumberRange.new(0.5, 2)
				pe.EmissionDirection = Enum.NormalId.Bottom
				pe.SpreadAngle = Vector2.new(40, 40)
				pe.Acceleration = Vector3.new(0, -8, 0)
				pe.Rate = 28
				pe.Parent = att
				task.delay(dur, function()
					pe.Enabled = false
				end)
				cleanup(att, dur + 1)
			end
		end
	end

	-- a ghost of his body left behind that crumbles (the dash, Decay Grasp):
	-- dull ash, not glowing, sagging and flaking as it goes
	function DY.ghost(char, life)
		local torso
		for _, part in char:GetChildren() do
			if part:IsA("BasePart") and part.Name ~= "HumanoidRootPart" and part.Transparency < 1 then
				local ghost = part:Clone()
				if ghost then
					ghost:ClearAllChildren()
					if ghost:IsA("MeshPart") then
						ghost.TextureID = ""
					end
					ghost.Anchored = true
					ghost.CanCollide = false
					ghost.CanQuery = false
					ghost.CanTouch = false
					ghost.CastShadow = false
					ghost.Massless = true
					ghost.Material = Enum.Material.SmoothPlastic
					ghost.Color = PAL.ASH
					ghost.Transparency = 0.4
					ghost.CFrame = part.CFrame
					ghost.Parent = folder
					tween(ghost, life, { Transparency = 1, Size = part.Size * 0.85, CFrame = part.CFrame - UP * 0.4 }, Enum.EasingStyle.Quad, Enum.EasingDirection.In)
					cleanup(ghost, life + 0.05)
				end
				if part.Name == "Torso" or part.Name == "UpperTorso" then
					torso = part.Position
				end
			end
		end
		if torso then
			DY.flakes(torso, 3, 0.8, PAL.DUST, PAL.ASH)
		end
	end

	-- a dark trail (addTrail's are additive: dark colours vanish in them)
	function DY.darkTrail(part, life, width)
		local a0 = Instance.new("Attachment")
		a0.Position = Vector3.new(0, width / 2, 0)
		a0.Parent = part
		local a1 = Instance.new("Attachment")
		a1.Position = Vector3.new(0, -width / 2, 0)
		a1.Parent = part
		local trail = Instance.new("Trail")
		trail.Attachment0 = a0
		trail.Attachment1 = a1
		trail.Color = ColorSequence.new(PAL.ASH, PAL.DUST)
		trail.Transparency = NS(0.15, 1)
		trail.LightEmission = 0
		trail.LightInfluence = 0.6
		trail.Lifetime = life
		trail.FaceCamera = true
		trail.Parent = part
		return function(after)
			task.delay(after or 0, function()
				pcall(function()
					trail.Enabled = false
				end)
				task.wait(life)
				for _, obj in { trail, a0, a1 } do
					pcall(obj.Destroy, obj)
				end
			end)
		end
	end

	-- red hairlines splitting a limb (the crust's front, his backlash): thin
	-- Neon strips welded across its face for `life`
	function DY.hairlines(limbPart, n, life)
		if not limbPart or not limbPart.Parent then
			return {}
		end
		local s = limbPart.Size
		local made = {}
		for _ = 1, n or 2 do
			local front = rng:NextNumber() < 0.6
			local off = front and CFrame.new(rand(-0.3, 0.3) * s.X, rand(-0.25, 0.25) * s.Y, -s.Z / 2 - 0.03)
				or CFrame.new((rng:NextNumber() < 0.5 and -1 or 1) * (s.X / 2 + 0.03), rand(-0.25, 0.25) * s.Y, rand(-0.3, 0.3) * s.Z)
			local p = newPart(Vector3.new(0.06, s.Y * rand(0.45, 0.75), 0.06), limbPart.CFrame * off * CFrame.Angles(0, 0, rand(-0.7, 0.7)), PAL.RED, Enum.Material.Neon)
			DY.stick(limbPart, p)
			tween(p, 0.2, { Transparency = 1 }, Enum.EasingStyle.Quad, Enum.EasingDirection.In, math.max((life or 0.3) - 0.2, 0))
			cleanup(p, (life or 0.3) + 0.05)
			table.insert(made, p)
		end
		return made
	end

	-- the backlash (ep 112, ep 118): his right arm red and cracked
	function DY.armCracks(char, life)
		for _, name in { "Right Arm", "RightUpperArm", "RightLowerArm", "RightHand" } do
			local part = char:FindFirstChild(name)
			if part and part:IsA("BasePart") then
				DY.hairlines(part, name == "RightHand" and 1 or 2, life)
			end
		end
	end

	-- five red hairlines splayed from a point, facing `normal` (a hand
	-- print: the grab, the finisher, the 4th claw)
	function DY.print(pos, normal, size, life)
		normal = (typeof(normal) == "Vector3" and normal.Magnitude > 0.05) and normal.Unit or UP
		local side = math.abs(normal.Y) < 0.9 and normal:Cross(UP).Unit or Vector3.new(1, 0, 0)
		local upv = side:Cross(normal)
		size = size or 1
		for _, a in { -50, -24, 0, 24, 58 } do
			local d = upv * math.cos(math.rad(a)) + side * math.sin(math.rad(a))
			local len = size * (a == 58 and 0.6 or rand(0.8, 1))
			local p0 = pos + d * size * 0.25
			local p = newPart(Vector3.new(0.07, 0.07, len), CFrame.lookAt(p0 + d * len / 2, p0 + d * len), PAL.RED, Enum.Material.Neon)
			tween(p, 0.15, { Transparency = 1 }, Enum.EasingStyle.Quad, Enum.EasingDirection.In, math.max((life or 0.25) - 0.15, 0))
			cleanup(p, (life or 0.25) + 0.05)
		end
	end

	-- the Decay player nearest pos (a Decaying broadcast doesn't say whose)
	function DY.casterNear(pos)
		local best, bestD = nil, 250
		for _, plr in Players:GetPlayers() do
			local c = plr.Character
			local r = c and c:FindFirstChild("HumanoidRootPart")
			if r and (c:GetAttribute("Quirk") == "Decay" or plr:GetAttribute("Quirk") == "Decay") then
				local d = (r.Position - pos).Magnitude
				if d < bestD then
					best, bestD = c, d
				end
			end
		end
		return best, bestD
	end

	-- A CRUST OF STONE over a decaying body (ep 118's X-Less; the frost
	-- crust's way, IceKit.frostBody): tessellated stone over each limb in
	-- turn, spreading out from where it got them (red hairlines splitting
	-- each as it forms), flakes peeling off and dust sifting down. One a body
	-- (a second dose stretches it). It ends with the Decaying attribute
	-- (o.watch: Overhaul can put them back together early) or after `dur`;
	-- a KO while it runs is ash. o: { stone (a colour), spread (s), watch, alpha }
	function DY.body(char, from, dur, o)
		o = o or {}
		local now = os.clock()
		local h = DY.bodies[char]
		if h and not h.gone then
			h.untilT = math.max(h.untilT, now + dur)
			h.watch = h.watch or o.watch
			return h
		end
		h = { parts = {}, limbs = {}, emitters = {}, untilT = now + dur, watch = o.watch, gone = false }
		function h.off() end
		local root = char and char:FindFirstChild("HumanoidRootPart")
		if not root or DY.ashed[char] then
			h.gone = true
			return h
		end
		DY.bodies[char] = h
		from = typeof(from) == "Vector3" and from or root.Position
		local limbs = {}
		for _, p in char:GetChildren() do
			if p:IsA("BasePart") and p ~= root and p.Transparency < 0.9 then
				table.insert(limbs, p)
			end
		end
		table.sort(limbs, function(a, b)
			return (a.Position - from).Magnitude < (b.Position - from).Magnitude
		end)
		local spread = o.spread or math.min(dur * 0.6, 1.6)
		for i, part in limbs do
			local s = part.Size
			local size, cf, shape = Vector3.new(s.X * 1.07 + 0.06, s.Y * 1.04 + 0.04, s.Z * 1.07 + 0.06), part.CFrame, nil
			if part.Name == "Head" then
				size, cf, shape = DY.headFit(char, part, 1.25)
			end
			local p = newPart(size, cf, o.stone or part.Color:Lerp(PAL.STONE, 0.8), Enum.Material.Cobblestone, shape)
			p.Name = "DecayCrust"
			p.Transparency = 1
			-- (hidden with the body: Compress's marble, first person)
			p.LocalTransparencyModifier = DY.hiddenBy(part)
			DY.stick(part, p)
			h.limbs[p] = part
			h.parts[i] = p
			-- (the limbs nearest the touch go to stone at once; the rest are
			-- half-crusted, and go over a little later)
			local f = (i - 1) / math.max(#limbs - 1, 1)
			local at = spread * f
			local alpha = o.alpha or 0.06
			tween(p, 0.25, { Transparency = f < 0.4 and alpha or 0.5 }, Enum.EasingStyle.Quad, Enum.EasingDirection.Out, at)
			if f >= 0.4 then
				tween(p, 0.6, { Transparency = alpha }, Enum.EasingStyle.Quad, Enum.EasingDirection.Out, at + math.max(dur * 0.45, 0.4))
			end
			if i <= 6 then
				task.delay(at, function()
					if DY.hiddenBy(part) < 0.99 then
						DY.hairlines(part, 2, 0.3)
					end
				end)
			end
		end
		local torso = char:FindFirstChild("UpperTorso") or char:FindFirstChild("Torso") or root
		local att = Instance.new("Attachment")
		att.Name = "DecayDust"
		att.Parent = torso
		local flake = Instance.new("ParticleEmitter")
		flake.Texture = "rbxasset://textures/triangle.png"
		flake.Color = ColorSequence.new(o.stone or PAL.DUST, PAL.ASH)
		flake.LightInfluence = 1
		flake.Size = NS({ NK(0, 0.3), NK(1, 0.12) })
		flake.Squash = NS({ NK(0, -0.5), NK(0.5, 0.5), NK(1, -0.5) })
		flake.Lifetime = NumberRange.new(0.6, 1.1)
		flake.Speed = NumberRange.new(1, 4)
		flake.SpreadAngle = Vector2.new(180, 180)
		flake.Drag = 2
		flake.Acceleration = Vector3.new(0, -10, 0)
		flake.Rotation = NumberRange.new(0, 360)
		flake.RotSpeed = NumberRange.new(-300, 300)
		flake.Rate = 5
		flake.Parent = att
		local trickle = Instance.new("ParticleEmitter")
		trickle.Texture = SMOKE
		trickle.Color = ColorSequence.new(PAL.DUST, PAL.ASH)
		trickle.LightInfluence = 0.7
		trickle.Size = NS({ NK(0, 0.6), NK(1, 1.6) })
		trickle.Transparency = NS(0.2, 1)
		trickle.Lifetime = NumberRange.new(0.6, 1.1)
		trickle.Speed = NumberRange.new(0.5, 2)
		trickle.Acceleration = Vector3.new(0, -6, 0)
		trickle.SpreadAngle = Vector2.new(180, 180)
		trickle.Rate = 18
		trickle.Parent = att
		h.emitters = { flake, trickle }
		VFX.PlaySound("DecayCrust", root.Position, 0.8)
		-- the end: the crust flakes away (instant: just gone - the body's ash)
		function h.off(t, instant)
			t = t or 0.5
			if h.gone then
				-- (still flaking away when they go to ash: what's left goes at once)
				if instant then
					for _, p in h.parts do
						if p.Parent then
							p:Destroy()
						end
					end
				end
				return
			end
			h.gone = true
			if DY.bodies[char] == h then
				DY.bodies[char] = nil
			end
			-- (the ash still finds a crust that's flaking away, to clear it)
			if not instant and t > 0 then
				DY.fading[char] = h
				task.delay(t + 0.05, function()
					if DY.fading[char] == h then
						DY.fading[char] = nil
					end
				end)
			end
			for _, pe in h.emitters do
				if pe.Parent then -- (the body may have gone already, its emitters with it)
					pe.Enabled = false
				end
			end
			cleanup(att, 1.2)
			for _, p in h.parts do
				if p.Parent then
					if instant or t <= 0 then
						p:Destroy()
					else
						tween(p, t, { Transparency = 1, Size = p.Size * 1.08 }, Enum.EasingStyle.Quad, Enum.EasingDirection.In)
						cleanup(p, t + 0.05)
					end
				end
			end
			if not instant and torso.Parent then
				DY.flakes(torso.Position, 8, 0.9, o.stone or PAL.DUST, PAL.ASH)
			end
		end
		task.spawn(function()
			local hum = char:FindFirstChildOfClass("Humanoid")
			local sawTrue = false
			while not h.gone do
				if not char.Parent or not root.Parent then
					h.off(0, true)
					break
				elseif hum and hum.Health <= 0 then
					if not DY.ash(char, { from = from }) then
						h.off(0.4)
					end
					break
				end
				if h.watch then
					local on = char:GetAttribute("Decaying")
					if on == true then
						sawTrue = true
					elseif sawTrue then
						h.off()
						break
					end
				end
				if os.clock() >= h.untilT then
					h.off()
					break
				end
				-- (hidden with the body: Compress's marble, first person - the
				-- crust lives in the effects folder, so hideCharacter misses it)
				for p, limb in h.limbs do
					p.LocalTransparencyModifier = DY.hiddenBy(limb)
				end
				local shown = DY.hiddenBy(torso) < 0.99
				for _, pe in h.emitters do
					pe.Enabled = shown
				end
				task.wait(0.1)
			end
		end)
		return h
	end

	-- TURNED TO ASH (ep 109; HB's Vanquish finisher): the body goes charcoal -
	-- a black silhouette for a blink, then lumps of grit that slump into a
	-- heap of dust where it stood, the far side last. The body itself is
	-- hidden on this screen (every screen plays this). Once a body; not the
	-- raid boss or Twice's doubles (they have ends of their own).
	function DY.ash(char, o)
		o = o or {}
		if not char or not char.Parent or DY.ashed[char] or char:GetAttribute("Boss") or char:GetAttribute("TwiceClone") then
			return false
		end
		DY.ashed[char] = os.clock()
		local h, fading = DY.bodies[char], DY.fading[char]
		if h then
			h.off(0, true)
		end
		if fading then
			fading.off(0, true)
			DY.fading[char] = nil
		end
		local root = char:FindFirstChild("HumanoidRootPart")
		local parts = {}
		for _, p in char:GetChildren() do
			if p:IsA("BasePart") and p ~= root and p.Transparency < 0.9 then
				table.insert(parts, p)
			end
		end
		local center = root and root.Position or (parts[1] and parts[1].Position)
		if not center then
			return false
		end
		local g = DY.ground(center, center.Y - 3)
		local from = typeof(o.from) == "Vector3" and o.from or center + UP * 2
		hideCharacter(char, o.hold or 6)
		-- (and nobody here walks into the invisible body lying there - only
		-- another player's body, which their own screen simulates. Not mine,
		-- and not a dummy or NPC: this screen may be the one simulating it,
		-- and it'd fall through the street)
		local owner = DY.ownerOf(char)
		if owner and owner ~= Players.LocalPlayer then
			for _, p in char:GetDescendants() do
				if p:IsA("BasePart") then
					pcall(function()
						p.CanCollide = false
					end)
				end
			end
		end
		local lumps = math.clamp(math.floor(40 / math.max(#parts, 1)), 2, 6)
		if DY.k() < 1 then
			lumps = math.max(math.floor(lumps / 2), 1)
		end
		for _, part in parts do
			local s, cf = part.Size, part.CFrame
			local d0 = (part.Position - from).Magnitude * 0.05
			-- the black silhouette (a blink)
			local shellSize, shellAt, shellShape = s * 1.03, cf, nil
			if part.Name == "Head" then
				shellSize, shellAt, shellShape = DY.headFit(char, part, 1.2)
			end
			local shell = newPart(shellSize, shellAt, PAL.CHAR, Enum.Material.Slate, shellShape)
			tween(shell, 0.12, { Transparency = 1 }, Enum.EasingStyle.Quad, Enum.EasingDirection.In, d0 + 0.08)
			cleanup(shell, d0 + 0.25)
			for _ = 1, lumps do
				local size = math.clamp(math.sqrt(s.X * s.Y) * rand(0.42, 0.62), 0.35, 1.4)
				local at = cf * Vector3.new(rand(-0.35, 0.35) * s.X, rand(-0.4, 0.4) * s.Y, rand(-0.3, 0.3) * s.Z)
				local col = rng:NextNumber() < 0.2 and PAL.ASH:Lerp(PAL.DUST, 0.5) or part.Color:Lerp(PAL.CHAR, 0.82)
				local spin = CFrame.Angles(rand(0, 6), rand(0, 6), rand(0, 6))
				local c = newPart(Vector3.one * size, CFrame.new(at) * spin, col, Enum.Material.Slate)
				local jitter = (at - center)
				jitter = jitter.Magnitude > 0.05 and jitter.Unit * 0.3 or Vector3.zero
				tween(c, 0.1, { CFrame = CFrame.new(at + jitter) * spin }, Enum.EasingStyle.Quad, Enum.EasingDirection.Out, d0)
				local fall = rand(0.5, 0.8)
				local land = g + Vector3.new(rand(-1.6, 1.6), size * 0.2, rand(-1.6, 1.6))
				tween(c, fall, { CFrame = CFrame.new(land) * spin * CFrame.Angles(1.2, 0.6, 0), Size = Vector3.one * size * 0.5 }, Enum.EasingStyle.Quad, Enum.EasingDirection.In, d0 + 0.12)
				local fade = d0 + 0.12 + fall + rand(1.2, 2)
				tween(c, 0.8, { Transparency = 1, Size = Vector3.one * size * 0.2 }, Enum.EasingStyle.Quad, Enum.EasingDirection.In, fade)
				cleanup(c, fade + 0.85)
			end
		end
		-- the heap: low billows of dust, a smudge, flakes of ash, fine dust
		for i = 1, 6 do
			local a = i / 6 * math.pi * 2
			DY.billow(g + Vector3.new(math.cos(a), 0.4, math.sin(a)) * rand(0.8, 1.8), rand(1.8, 2.8), {
				from = g + UP, delay = 0.25 + i * 0.03, grow = 0.35, hold = 0.6, fade = 1.2, rise = 1.5, dark = PAL.DUST, light = PAL.DUST_LIGHT,
			})
		end
		groundMark(g, 3, PAL.ASH, 5)
		DY.flakes(center, 30, 1, PAL.CHAR, PAL.ASH)
		smokeBurst(center, PAL.ASH, 2.5, 3, 1.6, 10)
		VFX.PlaySound("DecayAsh", center, 1)
		return true
	end

	-- a KO by Decay (Effects.KOFinisher's burst): they're ash where they stood
	-- (the body's launch is hidden). Radio Waves' isn't decay: a dust burst.
	function DY.koBurst(pos, _dir, target, data)
		local g = DY.ground(pos, pos.Y - 3)
		local radio = type(data) == "table" and data.Move == "RadioWaves"
		if radio or not (typeof(target) == "Instance" and DY.ash(target, { from = pos })) then
			groundMark(g, 8, PAL.ASH, 6)
			for i = 1, 6 do
				local a = i / 6 * math.pi * 2
				celPuff(folder, g, g + Vector3.new(math.cos(a), 0, math.sin(a)) * rand(2, 4) + UP * rand(1, 2.5), rand(2.5, 3.5), PAL.DUST, PAL.DUST_HI, 0.2, 1.1, i * 0.02)
			end
			if radio then
				sparks(pos, 1, PAL.VIOLET, Color3.new(1, 1, 1), 14)
			end
		end
		shockDisc(g + UP * 0.3, UP, 2, 18, 0.3, PAL.DUST_LIGHT)
	end

	-- THE FINISHER "DECAY" (FX.Decay; the server stands them 4.5 studs apart
	-- and, for this one, doesn't launch the body): his hand out at their
	-- face, five red fingers splayed over it, the crust spreading charcoal
	-- from the head down, black lightning crackling off his hand; on the
	-- blow they're ash where they stand. Only on the server's KO, though: it
	-- kills them only if both are still up at the end of the hold, so if he
	-- leaves or goes down first (or the KO never comes) the crust just
	-- flakes away and they live.
	function DY.finisher(char, target, troot, _d, time)
		VFX.Pose(char, "Grasp", time)
		VFX.PlaySound("DecayGrasp", troot.Position, 1)
		local root = char:FindFirstChild("HumanoidRootPart")
		local head = target:FindFirstChild("Head") or troot
		local toward = root and flatten(root.Position - troot.Position, troot) or troot.CFrame.LookVector
		DY.print(head.Position + toward * (head.Size.Z / 2 + 0.08), toward, 1.1, math.min(time, 0.6))
		local had = DY.bodies[target]
		local fresh = not (had and not had.gone)
		local crust = DY.body(target, head.Position + UP, math.max(time - 0.05, 0.3), { stone = PAL.CHAR, spread = time * 0.8, alpha = 0.05 })
		-- (it stays on until the ash or the abort below: timing out on its own
		-- just before the blow would leave a charcoal statue over the ash)
		crust.untilT = math.max(crust.untilT, os.clock() + time + 0.8)
		local hum = char:FindFirstChildOfClass("Humanoid")
		local function holding()
			return char.Parent ~= nil and not (hum and hum.Health <= 0)
		end
		local t0 = os.clock()
		while os.clock() - t0 < time and holding() and troot.Parent do
			bolt(handPos(char, true), 1.4, PAL.BLACK)
			if rng:NextNumber() < 0.35 then
				DY.flakes(troot.Position + rng:NextUnitVector(), 3, 0.7, PAL.DUST, PAL.CHAR)
			end
			task.wait(0.08)
		end
		local thum = target:FindFirstChildOfClass("Humanoid")
		if holding() and thum then
			-- (the KO replicates a moment after the hold ends here)
			local t1 = os.clock()
			while os.clock() - t1 < 0.5 and troot.Parent and thum.Health > 0 do
				task.wait(0.05)
			end
			if troot.Parent and thum.Health <= 0 then
				DY.ash(target, { from = head.Position })
				return
			end
		end
		if fresh then
			crust.off()
		end
	end

	-- RIVET STAB as drawn (ep 122): black tendrils, jagged and branching like
	-- lightning, red circuit lines running inside them. Every part goes in the
	-- cast's one outline model (a red edge, one Highlight a cast). It shoots
	-- out at `speed`, then crumbles back from the tip. The wobble stays within
	-- 1.2 studs of the straight line (the server's beam is 3.5 wide). Where it
	-- first meets a wall it crumbles a star in it (o.hits caps those a cast).
	-- o: { speed, segments, forks, sparse (lines on every other segment),
	-- delay, life, hits = { n }, retract (round 84: pulled back in, not crumbled) }
	function DY.tendril(origin, dir, len, thick, model, o)
		o = o or {}
		if typeof(dir) ~= "Vector3" or dir.Magnitude < 0.05 or len < 1 then
			return
		end
		dir = dir.Unit
		local speed = o.speed or 900
		local n = o.segments or math.clamp(math.floor(len / 14), 4, 8)
		local basis = CFrame.lookAt(origin, origin + dir)
		local pts = { origin }
		for i = 1, n do
			local wob = Vector3.zero
			if i < n then
				wob = basis.RightVector * rand(-1.2, 1.2) + basis.UpVector * rand(-1, 1)
				if wob.Magnitude > 1.2 then
					wob = wob.Unit * 1.2
				end
			end
			pts[i + 1] = origin + dir * (len * i / n) + wob
		end
		local d0 = o.delay or 0
		local life = o.life or 0.55
		local at, made = {}, {}
		local acc = 0
		for i = 1, n do
			local a, b = pts[i], pts[i + 1]
			local L = (b - a).Magnitude
			local t = d0 + acc / speed
			at[i] = t
			acc += L
			local w = thick * (1 - 0.55 * (i - 1) / math.max(n - 1, 1))
			local cf = CFrame.lookAt((a + b) / 2, b)
			local p = newPart(Vector3.new(w, w, 0.05), CFrame.lookAt(a, b), PAL.TENDRIL, Enum.Material.SmoothPlastic, nil, model)
			p.Transparency = 1
			tween(p, 0.01, { Transparency = 0 }, nil, nil, t)
			tween(p, math.max(L / speed, 0.01), { Size = Vector3.new(w, w, L + w * 0.6), CFrame = cf }, Enum.EasingStyle.Linear, nil, t)
			local list = { p }
			-- the red circuit line along one face, with a jog at its end on every other one
			if not o.sparse or i % 2 == 1 then
				local sl = L * rand(0.4, 0.8)
				local z = rand(-0.5, 0.5) * (L - sl)
				local onTop = i % 2 == 0
				local scf = cf * CFrame.new(onTop and 0 or w / 2 + 0.02, onTop and w / 2 + 0.02 or 0, z)
				local st = newPart(onTop and Vector3.new(0.07, 0.05, sl) or Vector3.new(0.05, 0.07, sl), scf, PAL.RED, Enum.Material.Neon, nil, model)
				st.Transparency = 1
				tween(st, 0.01, { Transparency = 0 }, nil, nil, t + L / speed)
				table.insert(list, st)
				if i % 2 == 0 then
					local jog = newPart(Vector3.new(w * 0.6, 0.05, 0.07), scf * CFrame.new(w * 0.3 * (rng:NextNumber() < 0.5 and -1 or 1), 0, -sl / 2), PAL.RED, Enum.Material.Neon, nil, model)
					jog.Transparency = 1
					tween(jog, 0.01, { Transparency = 0 }, nil, nil, t + L / speed)
					table.insert(list, jog)
				end
			end
			made[i] = { list = list, w = w, L = L }
		end
		-- a fork or two off the middle joints, like lightning
		for _ = 1, o.forks or 0 do
			local j = math.clamp(math.floor(rand(2, n)), 2, n)
			local q = rand(0, math.pi * 2)
			local turn = CFrame.fromAxisAngle(basis.RightVector * math.cos(q) + basis.UpVector * math.sin(q), math.rad(rand(25, 40)))
			local fd = (turn * dir).Unit
			local a = pts[j]
			local fl = rand(3, 6)
			local mid = a + fd * fl * 0.5 + basis.UpVector * rand(-0.5, 0.5)
			local b = mid + (fd + basis.RightVector * rand(-0.4, 0.4)).Unit * fl * 0.5
			for _, ab in { { a, mid }, { mid, b } } do
				local L = (ab[2] - ab[1]).Magnitude
				local w = made[j - 1].w * 0.55
				local p = newPart(Vector3.new(w, w, L + w * 0.5), CFrame.lookAt((ab[1] + ab[2]) / 2, ab[2]), PAL.TENDRIL, Enum.Material.SmoothPlastic, nil, model)
				p.Transparency = 1
				tween(p, 0.01, { Transparency = 0 }, nil, nil, at[j - 1] + 0.02)
				table.insert(made[j - 1].list, p)
			end
		end
		-- the first wall it meets crumbles
		if o.hits and o.hits.n < 6 then
			local hit = DY.cast(origin, dir * len)
			if hit then
				o.hits.n += 1
				task.delay(d0 + (hit.Position - origin).Magnitude / speed + 0.02, DY.rivetHit, hit.Position, hit.Normal)
			end
		end
		-- (round 84, o.retract) pulled back into his fingers, the tip first
		if o.retract then
			for i = n, 1, -1 do
				local when = d0 + life + (n - i) * 0.03
				local a, b = pts[i], pts[i + 1]
				local w = made[i].w
				for j, p in made[i].list do
					if j == 1 then
						tween(p, 0.05, { Size = Vector3.new(w, w, 0.05), CFrame = CFrame.lookAt(a, b) }, Enum.EasingStyle.Quad, Enum.EasingDirection.In, when)
						tween(p, 0.01, { Transparency = 1 }, nil, nil, when + 0.05)
					else
						tween(p, 0.03, { Transparency = 1 }, nil, nil, when)
					end
				end
			end
			return pts
		end
		-- it crumbles back from the tip
		for i = n, 1, -1 do
			local when = d0 + life + (n - i) * 0.025
			for _, p in made[i].list do
				tween(p, 0.15, { Transparency = 1, Size = p.Size * Vector3.new(0.3, 0.3, 0.5) }, Enum.EasingStyle.Quad, Enum.EasingDirection.In, when)
			end
			if i == n or i == math.ceil(n / 2) then
				task.delay(when, DY.flakes, pts[i + 1], 3, 0.6, PAL.CHAR, PAL.ASH)
			end
		end
		return pts
	end

	-- where a rivet meets a wall: a star of dry cracks in its face, a couple
	-- of chips knocked off it, flakes
	function DY.rivetHit(pos, normal)
		normal = (typeof(normal) == "Vector3" and normal.Magnitude > 0.1) and normal.Unit or UP
		local t1 = math.abs(normal.Y) < 0.9 and normal:Cross(UP).Unit or normal:Cross(Vector3.new(1, 0, 0)).Unit
		local t2 = normal:Cross(t1)
		local base = pos + normal * 0.06
		for i = 1, 4 do
			local a = i / 4 * math.pi * 2 + rand(-0.4, 0.4)
			local d = t1 * math.cos(a) + t2 * math.sin(a)
			local across = t1 * -math.sin(a) + t2 * math.cos(a)
			local len, prev = rand(2, 3.2), base
			for j = 1, 2 do
				local nxt = base + d * len * j / 2 + across * rand(-0.35, 0.35)
				local seg = newPart(Vector3.new(0.24 - j * 0.07, 0.08, (nxt - prev).Magnitude + 0.1), CFrame.lookAt((prev + nxt) / 2, nxt, normal), PAL.CRACK)
				tween(seg, 0.8, { Transparency = 1 }, Enum.EasingStyle.Linear, nil, 2.2)
				cleanup(seg, 3.1)
				prev = nxt
			end
		end
		for _ = 1, 2 do
			local s = rand(0.4, 0.8)
			local c = newPart(Vector3.one * s, CFrame.new(base) * CFrame.Angles(rand(0, 6), rand(0, 6), rand(0, 6)), PAL.DUST, Enum.Material.Slate)
			local land = DY.ground(base + normal * rand(1.5, 3) + t1 * rand(-1, 1), base.Y - 6)
			tween(c, 0.45, { CFrame = CFrame.new(land + UP * s * 0.3) * CFrame.Angles(rand(0, 6), rand(0, 6), 0) }, Enum.EasingStyle.Quad, Enum.EasingDirection.In)
			tween(c, 0.4, { Transparency = 1, Size = Vector3.one * s * 0.3 }, Enum.EasingStyle.Quad, Enum.EasingDirection.In, 1)
			cleanup(c, 1.45)
		end
		DY.flakes(base + normal * 0.3, 8, 0.8, PAL.DUST, PAL.ASH)
	end

	-- must match QuirkServer's Rivet Storm directions
	function DY.stormDirs()
		local dirs = {}
		for i = 1, 14 do
			local a = i / 14 * math.pi * 2
			table.insert(dirs, Vector3.new(math.cos(a), i % 2 == 0 and 0.18 or -0.04, math.sin(a)).Unit)
		end
		return dirs
	end

	-- THE VORTEX (ep 118, the release): blocks of the street, lit lilac on
	-- top, swirling up round him in the dust while he rises; flung out on
	-- the slam. Returns the fling.
	function DY.vortex(g, dur)
		local blocks = {}
		for i = 1, math.floor(12 * DY.k()) do
			local s = rand(0.9, 1.8)
			local body = newPart(Vector3.new(s, s * 0.8, s), CFrame.new(g), PAL.ASH:Lerp(PAL.LILAC, 0.25), Enum.Material.Slate)
			local top = newPart(Vector3.new(s * 1.01, 0.08, s * 1.01), CFrame.new(g), PAL.LILAC, Enum.Material.SmoothPlastic)
			cleanup(body, dur + 1) -- (if the fling never comes: he was cut off mid-cast)
			cleanup(top, dur + 1)
			table.insert(blocks, { body = body, top = top, s = s, r = rand(4, 9), a = i / 12 * math.pi * 2, w = rand(2, 3.2), y0 = rand(0.5, 1.5), y1 = rand(2, 8), spin = rand(-2, 2) })
		end
		local t0 = os.clock()
		task.spawn(function()
			while os.clock() - t0 < dur do
				local e = os.clock() - t0
				local k = math.min(e / dur, 1)
				for _, b in blocks do
					if b.body.Parent then
						local a = b.a + e * b.w
						local cf = CFrame.new(g + Vector3.new(math.cos(a) * b.r, b.y0 + (b.y1 - b.y0) * k, math.sin(a) * b.r)) * CFrame.Angles(e * b.spin, a, e * b.spin * 0.5)
						b.body.CFrame = cf
						b.top.CFrame = cf * CFrame.new(0, b.s * 0.4 + 0.04, 0)
					end
				end
				task.wait()
			end
		end)
		return function()
			for _, b in blocks do
				local out = b.body.CFrame.Position - g
				out = Vector3.new(out.X, 0, out.Z)
				out = out.Magnitude > 0.1 and out.Unit or Vector3.new(1, 0, 0)
				for _, p in { b.body, b.top } do
					tween(p, 0.45, { CFrame = p.CFrame + out * rand(18, 28) + UP * rand(2, 6), Transparency = 1 }, Enum.EasingStyle.Quad, Enum.EasingDirection.Out)
					cleanup(p, 0.5)
				end
			end
		end
	end

	-- ((round 101, awaken_m) his awakening's camera is the kit's two shots
	-- now (VFX.AK.shots) - his old three, SHOTS.AwakeningDecay, are retired)

	-- (round 83) his M1s (the hook in Effects.Punch): three thin red rake marks
	-- left in the air along the claw (his fingers), dust flaking off them; the
	-- 4th - five fingers, full lunge - a five-finger print; in the ult black
	-- lightning edged in violet off every one
	function VFX.DecayPunch(char, count, finisher, fist, look)
		local right = look:Cross(UP)
		if finisher then
			DY.print(fist + look * 0.6, -look, 1.3, 0.3)
			DY.flakes(fist + look * 0.6, 8, 0.8, PAL.DUST, PAL.ASH)
			celPuff(folder, fist, fist + look * 2 + UP * 0.6, 1.8, PAL.DUST, PAL.DUST_HI, 0.12, 0.5)
		else
			local along = count == 3 and UP or (right * (count == 2 and -0.7 or 0.7) - UP * 0.7).Unit
			local across = along:Cross(look).Unit
			for j = -1, 1 do
				local c = fist + across * j * 0.35 + along * j * 0.15
				local p = newPart(Vector3.new(0.06, 0.06, 2.4), CFrame.lookAt(c, c + along), PAL.RED, Enum.Material.Neon)
				tween(p, 0.15, { Transparency = 1, Size = Vector3.new(0.02, 0.02, 2.8) }, Enum.EasingStyle.Quad, Enum.EasingDirection.In, 0.05)
				cleanup(p, 0.22)
			end
			DY.flakes(fist, 4, 0.6, PAL.DUST, PAL.ASH)
		end
		if char:GetAttribute("UltActive") then
			bolt(fist, finisher and 2.2 or 1.6, PAL.BLACK)
			bolt(fist, finisher and 2 or 1.4, PAL.VIOLET)
		end
	end

	-- (round 83) the dash (QUIRK_FX.Dash): a ghost of him crumbling where he
	-- pushed off, a scuff of crack, dust and flakes, a dusty streak
	QUIRK_FX.Dash.Decay = function(char, root, dir)
		DY.ghost(char, 0.3)
		local g = groundPoint(root.Position)
		if (root.Position - g).Magnitude < 5 then
			for i = 1, 2 do
				celPuff(folder, g - dir * i, g - dir * (1.5 + i) + UP * rand(0.8, 1.6), rand(1.4, 2), PAL.DUST, PAL.DUST_HI, 0.15, 0.6, i * 0.04)
			end
			DY.crack(g - dir * 0.5, -dir, rand(4, 6), { speed = 80, w0 = 0.4, w1 = 0.1, step = 1.5, wander = 0.4, hot = false, life = 1.2 })
		end
		DY.flakes(root.Position - dir * 1.5, 6, 0.8, PAL.DUST, PAL.ASH)
		legTrails(char, 0.25, PAL.DUST_LIGHT)
	end

	-- (round 83) THE AWAKENING (the server carves 18 studs round him): black
	-- lightning edged in violet round both arms and his arm splitting red, ash
	-- rushing up round him, the five fingers under him, the white sketch frame
	-- (ep 112) and the lilac air, the spread out to 18 studs and the beige dome
	-- over it with plates floating in the dust.
	-- ((round 101, awaken_m) on the awakening kit, VFX.AK.FX.Decay - his clip
	-- MoveAwakenDecay: hunched, scratching his neck (the cracks running up his
	-- arm, ash flaking off his fingers), then ON the hit the open palm thrust
	-- at the lens - his sketch frame is his own impact pair (his screen, the
	-- same four frames), the lightning round his hands, the five fingers
	-- cracked into the street AHEAD of him, the ash (none on his lens), the
	-- lilac air, the spread and the dome (the server's 18 on the same hit);
	-- the hand on his face flexes from the press and springs open on the hit
	-- (Config.Cosmetics.Shigaraki.Charge.Awaken). His old burst at the press,
	-- QUIRK_FX.Ult.Decay, is folded in here.)
	VFX.AK.FX.Decay = {
		gather = function(ctx)
			DY.armCracks(ctx.char, 2.4)
			for i = 0, 2 do
				VFX.AK.M.at(ctx, ctx.gather + i * 0.04, function()
					DY.flakes(handPos(ctx.char, true), 5, 0.6 * ctx.scale, PAL.DUST, PAL.ASH)
				end)
			end
		end,
		impact = function(ctx)
			local I = (Config.Awaken or {}).Impact or {}
			if ctx.low then
				-- (a low-end machine: one hard frame, as anyone's)
				VFX.AK.note(ctx, "impactFlash")
				VFX.ImpactFrame(I.Flash or 0.07)
				return 0
			end
			local t = (I.White or 0.033) + (I.Black or 0.033)
			VFX.AK.note(ctx, "impactSketch")
			DY.sketch(t)
			-- (out hard after its four frames, like the pair's: the sketch's own
			-- redraw wait and fade-out would lie over the cut-in's first frames)
			local gui = VFX.MANGA and VFX.MANGA.gui and VFX.MANGA.gui()
			local sheet
			for _, c in gui and gui:GetChildren() or {} do
				if c.Name == "DecaySketch" then
					sheet = c -- (the newest: this one)
				end
			end
			if sheet then
				task.delay(t, function()
					sheet.Visible = false
				end)
			end
			return t
		end,
		hit = function(ctx)
			local D = (Config.Awaken or {}).Decay or {}
			local char, root, s = ctx.char, ctx.root, ctx.scale
			local g = ctx.g or (root.Position - UP * 3 * s)
			VFX.AK.note(ctx, "decayHit")
			task.spawn(function()
				local t0 = os.clock()
				while os.clock() - t0 < (D.Bolts or 0.6) and VFX.AK.alive(ctx) do
					for _, right in { true, false } do
						local hand = handPos(char, right)
						bolt(hand, 2.4 * s, PAL.BLACK)
						bolt(hand, 2 * s, PAL.VIOLET)
					end
					task.wait(0.08)
				end
			end)
			if ctx.g then
				DY.fingers(g + ctx.d * 1.2 * s, ctx.d, (D.Fingers or 6) * s, { life = 4 })
				shockDisc(g + UP * 0.3, UP, 2, 14 * s, 0.3, PAL.DUST_LIGHT)
			end
			-- ((round 101 review) on his own screen only the ash behind him
			-- (Config.Awaken.Decay.AshFront): 3-5 stud puffs at his sides and in
			-- front of him swallowed the palm thrust through the hold - the ash
			-- rises behind him like a backdrop; everyone else sees it all round)
			local ash = math.max(math.floor((D.Ash or 10) * (ctx.low and 0.5 or 1)), 1)
			ctx.ash = {}
			for i = 1, ash do
				local a = i / ash * math.pi * 2
				local out = Vector3.new(math.cos(a), 0, math.sin(a))
				local to = g + out * rand(5, 9) * s + UP * rand(5, 14) * s
				local front = ctx.mine and out:Dot(ctx.d) > (D.AshFront or -0.2)
				if not front and not VFX.AK.lens(ctx, g + out * 4 * s + UP * 3 * s, 3 * s) and not VFX.AK.lens(ctx, to, 3 * s) then
					celPuff(folder, g + out * 2.5 * s, to, rand(3.5, 5.5) * s, PAL.MAUVE, PAL.LILAC, 0.3, 1.3, i * 0.02)
					table.insert(ctx.ash, out)
				end
			end
			if nearCamera(root.Position, 90) then
				DY.tint(1, 0.8, 1.2)
			end
			if ctx.g then
				local spread, dome = D.Spread or { 18, 0.5 }, D.Dome or { 14, 2.2 }
				DY.ring(g, spread[1] * s, spread[2], { cracks = 9, h = 6, slabs = 4, puffs = 4, teeth = 2 })
				DY.dome(g, spread[1] * s, dome[1], dome[2], { puffs = 12, slabs = 4 })
			end
			for _ = 1, 4 do
				bolt(root.Position, 6 * s, PAL.RED)
			end
		end,
		aura = function(ctx)
			return VFX.AK.aura(ctx, ctx.spec.Aura or "ash")
		end,
	}

	-- DECAY (1): down on one knee, his right palm slapped flat on the street
	-- (the clip's Hit, 0.22 s) and five cracks fan out of his fingers; on the
	-- server's beat (0.25 s) it races off down the street at the server's
	-- speed - the middle finger's crack runs on as one unbroken crack, a
	-- side crack either side of it, plates lifting and crumbling just behind
	-- the front, the surge rolling over them
	function Effects.DecayWave(char, data, isLocal, ability)
		local root = charParts(char)
		if not root then
			return
		end
		local d = flatten(data.Dir, root)
		if isLocal then
			face(root, d)
		end
		VFX.Motion(char, "DecayWave")
		DY.pour(char, 0.22, true)
		task.wait(0.22)
		if not root.Parent then
			return
		end
		local range = (ability and ability.Range) or 64
		local start = groundPoint(root.Position)
		VFX.PlaySound("DecayWave", start, 1)
		DY.palm(DY.ground(handPos(char, true), start.Y), d, { len = 5, k = 0.9 })
		task.wait(0.03)
		if not root.Parent then
			return
		end
		local speed = range / 0.6 -- (the server's 8 steps of 0.075 s)
		local right = d:Cross(UP)
		DY.crack(start + d * 2, d, range - 2, { speed = speed, w0 = 1, w1 = 0.35, step = 4, wander = 1.4, branch = 0.45, life = 4 })
		for _, side in { -1, 1 } do
			DY.crack(start + d * 2.5 + right * side * 1.2, (d + right * side * 0.07).Unit, range * rand(0.8, 0.95), { speed = speed, w0 = 0.5, w1 = 0.15, step = 5, wander = 1, life = 3.5 })
		end
		DY.surge(start + d * 2, d, range, 12, speed, 6)
		for i = 1, 8 do
			local b = start + d * (range * i / 8)
			for _ = 1, math.max(math.floor(2 * DY.k()), 1) do
				-- (just behind the front)
				DY.slab(start + d * math.max(range * (i - 1) / 8 - rand(0, range / 8), 3) + right * rand(-5, 5), rand(2, 4), { delay = 0.04 })
			end
			if i % 2 == 0 then
				VFX.PlaySound("Crumble", b, 0.8)
			end
			VFX.ShakeAt(b, 0.6, 50, 0.12)
			task.wait(0.075)
		end
	end

	-- SINKHOLE (V): his palm to the street, five cracks racing into the
	-- ground in front of him, and on the server's beat (0.35 s) it gives way:
	-- the patch breaks into plates over a dark pit - the ones round the edge
	-- tip up and in (a lip round the hole: the street under it can't really
	-- drop), the inner ones settle and crumble one by one through the hold -
	-- dust spouting up round the rim, haze hanging in the hole, a puff where
	-- they're let out
	function Effects.Sinkhole(char, data, isLocal, ability)
		local root = charParts(char)
		if not root then
			return
		end
		ability = ability or {}
		local d = flatten(data.Dir, root)
		if isLocal then
			face(root, d)
		end
		VFX.Motion(char, "DecayWave")
		DY.pour(char, 0.3)
		task.wait(0.22)
		if not root.Parent then
			return
		end
		local range, width = ability.Range or 30, ability.Width or 24
		local hold = ability.HoldTime or 1.5
		local start = groundPoint(root.Position)
		local right = d:Cross(UP)
		DY.palm(DY.ground(handPos(char, true), start.Y), d, { len = 4, k = 0.8 })
		for i = -2, 2 do
			local v = d * (range * rand(0.75, 1)) + right * (i / 2) * width * 0.42
			DY.crack(start + d * 2, v, v.Magnitude, { speed = v.Magnitude / 0.13, w0 = 0.7, w1 = 0.2, step = 4, wander = 1.2, branch = 0.3, life = hold + 1.5 })
		end
		task.wait(0.13)
		if not root.Parent then
			return
		end
		local mid = start + d * (range / 2 + 2)
		VFX.PlaySound("Collapse", mid, 1)
		local hole = newPart(Vector3.new(0.2, width, range), CFrame.new(mid + UP * 0.08) * CFrame.lookAt(Vector3.zero, d) * CFrame.Angles(0, 0, math.rad(90)), PAL.CRACK, Enum.Material.Slate)
		tween(hole, 1, { Transparency = 1 }, nil, nil, hold + 0.5)
		cleanup(hole, hold + 1.6)
		-- the plates: 4 across, 5 along
		local rows, cols = 5, 4
		local yaw = CFrame.lookAt(Vector3.zero, d)
		for r = 1, rows do
			for c = 1, cols do
				local u, v = (c - 0.5) / cols - 0.5, (r - 0.5) / rows - 0.5
				local at = mid + d * v * range + right * u * width
				local dims = Vector3.new(width / cols * rand(0.78, 0.9), 0.55, range / rows * rand(0.78, 0.9))
				local spin = yaw * CFrame.Angles(0, rand(-0.12, 0.12), 0)
				if r == 1 or r == rows or c == 1 or c == cols then
					local out = d * v + right * u
					out = out.Magnitude > 0.01 and out.Unit or d
					DY.slab(at, 0, { size3 = dims, yaw = spin, rise = rand(0.4, 0.9), tilt = CFrame.fromAxisAngle(UP:Cross(-out).Unit, math.rad(rand(18, 30))), hold = hold * rand(0.6, 1), flakes = 0.4 })
				else
					DY.slab(at, 0, { size3 = dims, yaw = spin, rise = -0.2, tilt = CFrame.Angles(rand(-0.08, 0.08), 0, rand(-0.08, 0.08)), hold = rand(0.3, hold), flakes = 0.5 })
				end
			end
		end
		-- dust spouting up round the rim
		for i = 1, math.floor(8 * DY.k()) do
			local a = i / 8 * math.pi * 2
			local edge = mid + d * math.clamp(math.cos(a) * 0.75, -0.5, 0.5) * range + right * math.clamp(math.sin(a) * 0.75, -0.5, 0.5) * width
			local g = DY.ground(edge, start.Y)
			celPuff(folder, g, g + UP * rand(6, 10), rand(4, 6), PAL.DUST_MID, PAL.DUST_HI, 0.25, rand(1, 1.4), i * 0.02)
		end
		-- haze hanging in the hole
		local holder = newPart(Vector3.new(width * 0.8, 1, range * 0.8), CFrame.new(mid + UP * 0.5) * yaw, PAL.DUST)
		holder.Transparency = 1
		local pe = Instance.new("ParticleEmitter")
		pe.Texture = SMOKE
		pe.Color = ColorSequence.new(PAL.DUST_LIGHT, PAL.DUST)
		pe.LightInfluence = 0.7
		pe.Size = NS({ NK(0, 2), NK(1, 5) })
		pe.Transparency = NS({ NK(0, 0.5), NK(0.6, 0.7), NK(1, 1) })
		pe.Lifetime = NumberRange.new(1, 1.6)
		pe.Speed = NumberRange.new(1, 3)
		pe.SpreadAngle = Vector2.new(40, 40)
		pe.Shape = Enum.ParticleEmitterShape.Box
		pe.Rate = 18 * DY.k()
		pe.Parent = holder
		task.delay(hold, function()
			pe.Enabled = false
			-- they're let out
			smokeBurst(mid + UP * 2, PAL.DUST_LIGHT, 4, 6, 1.2, 10)
			for i = 1, 3 do
				local p = mid + right * (i - 2) * width * 0.25
				celPuff(folder, p, p + UP * rand(3, 5), rand(3, 4), PAL.DUST, PAL.DUST_HI, 0.18, 0.8, i * 0.03)
			end
		end)
		cleanup(holder, hold + 1.8)
		VFX.ShakeAt(start, 2, 100, 0.4)
	end

	-- DECAY GRASP (2): the gliding lunge, five fingers first - a dark trail
	-- off his hand with a thin red core, dust streaking off the fingertips,
	-- ghosts of him crumbling behind, a crack chasing along under him (the
	-- server tunnels with the Decay profile)
	function Effects.DecayGrasp(char, data, isLocal)
		local root = charParts(char)
		if not root then
			return
		end
		local d = flatten(data.Dir, root)
		if isLocal then
			face(root, d)
			dash(root, d * 110, 0.4)
		end
		VFX.Motion(char, "Grasp")
		local hand = limb(char, "RightHand", "Right Arm")
		local stopDark = hand and DY.darkTrail(hand, 0.25, 1.2)
		local stopCore = hand and addTrail(hand, PAL.RED, 0.15, 0.25)
		streaks(handPos(char, true), d, 5, 0.4, 2.5, 6, PAL.DUST_LIGHT, 0.25)
		VFX.PlaySound("Dash", root.Position, 0.8)
		DY.crack(groundPoint(root.Position), d, 44, { speed = 110, w0 = 0.45, w1 = 0.2, step = 4, wander = 0.8, life = 3 })
		local t0 = os.clock()
		while os.clock() - t0 < 0.4 and root.Parent do
			DY.ghost(char, 0.3)
			task.wait(0.13)
		end
		if stopDark then
			stopDark(0)
		end
		if stopCore then
			stopCore(0)
		end
	end

	-- Server: Decay Grasp caught someone - five red fingers splayed over
	-- them where his hand landed, the crust spreading out from there, the
	-- impact frame tinted lilac; ash bursts off them when they're shoved
	function Effects.Grasped(char, data)
		local target = data.Target
		local root = target and target:FindFirstChild("HumanoidRootPart")
		if not root then
			return
		end
		local aroot = char and char:FindFirstChild("HumanoidRootPart")
		local toward = aroot and flatten(aroot.Position - root.Position, root) or root.CFrame.LookVector
		local torso = target:FindFirstChild("UpperTorso") or target:FindFirstChild("Torso") or root
		local contact = torso.Position + toward * (torso.Size.Z / 2 + 0.06)
		DY.print(contact, toward, 1.1, 0.3)
		billboardRing(contact, 2, 10, PAL.DUST_LIGHT, 5, 0.3)
		DY.flakes(contact, 10, 1, PAL.DUST, PAL.ASH)
		if char and VFX.MANGA then
			VFX.MANGA.impact(contact, 0.08, { Tint = PAL.TINT, Radius = 45 })
		end
		DY.body(target, contact, 3, { watch = true })
		VFX.PlaySound("DecayGrasp", contact, 1)
		task.delay(0.6, function()
			if root.Parent then
				DY.flakes(root.Position, 12, 1.1, PAL.DUST, PAL.ASH)
				celPuff(folder, root.Position, root.Position - toward * 2 + UP, 2.5, PAL.DUST, PAL.DUST_HI, 0.15, 0.7)
			end
		end)
	end

	-- Server: someone is crumbling (Decay's damage over time; Duration is the
	-- ticks'). The crust spreads from where it got them: his hand if he's on
	-- them, else up from their feet; the stone goes lilac while he's ulting.
	function Effects.Decaying(_, data)
		local target = data.Target
		local root = target and target:FindFirstChild("HumanoidRootPart")
		if not root then
			return
		end
		local caster, dist = DY.casterNear(root.Position)
		local from = root.Position - UP * 3
		local croot = caster and caster:FindFirstChild("HumanoidRootPart")
		if croot and dist < 9 then
			from = root.Position + flatten(croot.Position - root.Position, root) * 0.6
		end
		local ult = caster and (caster:GetAttribute("UltActive") or (Players:GetPlayerFromCharacter(caster) and Players:GetPlayerFromCharacter(caster):GetAttribute("UltActive")))
		DY.body(target, from, tonumber(data.Duration) or 2, { stone = ult and PAL.LILAC or nil, watch = true })
	end

	-- COLLAPSE (3): arms open with dust pouring off his hands, plates popping
	-- round his feet; both palms down on the clip's Hit (0.5 s) - ten
	-- fingers' worth of cracks and the lilac impact frame - and on the
	-- server's beat (0.55 s) the spread to its radius in its 0.9 s, cracks
	-- climbing the walls left standing at the edge; a low dome of dust over
	-- the block after
	function Effects.Collapse(char, _data, _isLocal, ability)
		local root = charParts(char)
		if not root then
			return
		end
		VFX.Motion(char, "Collapse") -- (no cutscene: the camera stays with the fight)
		DY.pour(char, 0.5)
		local feet = groundPoint(root.Position)
		for i = 1, 3 do
			local a = rand(0, math.pi * 2)
			DY.slab(feet + Vector3.new(math.cos(a), 0, math.sin(a)) * rand(3, 6), rand(1.5, 2.5), { delay = 0.1 + i * 0.1, rise = rand(0.3, 0.7), hold = 0.3 })
		end
		task.wait(0.5)
		if not root.Parent then
			return
		end
		local center = groundPoint(root.Position)
		local look = Vector3.new(root.CFrame.LookVector.X, 0, root.CFrame.LookVector.Z)
		for _, right in { true, false } do
			DY.palm(DY.ground(handPos(char, right), center.Y), look, { len = 5, frame = right and 0.1 or nil })
		end
		VFX.PlaySound("Collapse", center, 1)
		task.wait(0.05)
		if not root.Parent then
			return
		end
		local R = (ability and ability.Radius) or 46
		DY.ring(center, R, 0.9, { cracks = 10, h = 7, slabs = 8, puffs = 6, teeth = 2 })
		DY.curtains(center, R, 0.9)
		groundMark(center, 14, PAL.CRACK, 8)
		VFX.ShakeAt(center, 3, 180, 1)
		task.wait(0.9)
		DY.dome(center, 14, 10, 2, { puffs = 14, slabs = 3 })
	end

	-- (round 84) a crack of black lightning from a to b - All For One's, with
	-- its violet edge coming from the outline model it's put in (ep 126's
	-- EMP): a few angular kinks, thinning to the end; shows at `delay` for
	-- `life` seconds
	function DY.jag(a, b, w, model, life, delay, color)
		local v = b - a
		local L = v.Magnitude
		if L < 0.1 then
			return
		end
		delay = delay or 0
		local basis = CFrame.lookAt(a, b)
		local n = math.clamp(math.floor(L / 1.6) + 2, 3, 6)
		local prev = a
		for i = 1, n do
			local nxt = b
			if i < n then
				nxt = a + v * (i / n) + basis.RightVector * rand(-0.55, 0.55) * L / n + basis.UpVector * rand(-0.3, 0.3) * L / n
			end
			local len = (nxt - prev).Magnitude
			if len > 0.02 then
				local k = 1 - 0.45 * (i - 1) / math.max(n - 1, 1)
				local seg = newPart(Vector3.new(w * k, w * k * 0.6, len + w * 0.4), CFrame.lookAt((prev + nxt) / 2, nxt), color or PAL.BLACK, Enum.Material.SmoothPlastic, nil, model)
				if delay > 0 then
					seg.Transparency = 1
					tween(seg, 0.01, { Transparency = 0 }, nil, nil, delay)
				end
				tween(seg, 0.06, { Transparency = 1 }, nil, nil, delay + life)
				cleanup(seg, delay + life + 0.1)
			end
			prev = nxt
		end
	end

	-- (round 84) a rivet held between two moving points - Rivet Stab's pin
	-- and reel, Rivet Storm's lift - its kinks staying put along it, redrawn
	-- every frame for `dur` seconds, then pulled back into `getFrom` over
	-- `retract`. getFrom / getTo return where its ends are now (nil: it's
	-- over). In `model` (a red outline).
	function DY.liveTendril(getFrom, getTo, thick, model, dur, retract, seed)
		local n = 5
		local r = Random.new(seed or 1)
		local kinks = {}
		for i = 1, n - 1 do
			kinks[i] = Vector2.new(r:NextNumber(-0.8, 0.8), r:NextNumber(-0.5, 0.5))
		end
		local segs, lines = {}, {}
		for i = 1, n do
			local w = thick * (1 - 0.45 * (i - 1) / (n - 1))
			segs[i] = newPart(Vector3.new(w, w, 0.1), CFrame.new(), PAL.TENDRIL, Enum.Material.SmoothPlastic, nil, model)
			segs[i].Transparency = 1
			lines[i] = newPart(Vector3.new(0.07, 0.05, 0.1), CFrame.new(), PAL.RED, Enum.Material.Neon, nil, model)
			lines[i].Transparency = 1
		end
		local function draw(k)
			local a, b = getFrom(), getTo()
			if typeof(a) ~= "Vector3" or typeof(b) ~= "Vector3" then
				return false
			end
			local v = b - a
			local L = v.Magnitude
			if L < 0.2 then
				return true
			end
			local basis = CFrame.lookAt(a, b)
			local bend = math.min(L / 9, 1.3)
			local prev = a
			for i = 1, n do
				local nxt = a + v * (i / n * k)
				if i < n then
					nxt += (basis.RightVector * kinks[i].X + basis.UpVector * kinks[i].Y) * bend * k
				end
				local len = (nxt - prev).Magnitude
				local seg, line = segs[i], lines[i]
				if len > 0.05 then
					local w = seg.Size.X
					seg.Size = Vector3.new(w, w, len + w * 0.5)
					seg.CFrame = CFrame.lookAt((prev + nxt) / 2, nxt)
					seg.Transparency = 0
					line.Size = Vector3.new(0.07, 0.05, len * 0.65)
					line.CFrame = seg.CFrame * CFrame.new(0, w / 2 + 0.02, 0)
					line.Transparency = 0
				else
					seg.Transparency, line.Transparency = 1, 1
				end
				prev = nxt
			end
			return true
		end
		task.spawn(function()
			local t0 = os.clock()
			while os.clock() - t0 < dur do
				if not draw(1) then
					break
				end
				task.wait()
			end
			local t1 = os.clock()
			while os.clock() - t1 < retract do
				if not draw(1 - (os.clock() - t1) / retract) then
					break
				end
				task.wait()
			end
			for i = 1, n do
				segs[i]:Destroy()
				lines[i]:Destroy()
			end
		end)
	end

	-- RIVET STAB (R), as All For One used it on All Might (ep 48) and
	-- Shigaraki through Endeavor (ep 122). (round 84) The fingertips go black
	-- and split red - five little rivets grow out of them while the backlash
	-- crackles on his arm - then (the server's Windup) they shoot out along
	-- the server's five lines, red circuits running in them, a red-black burst
	-- at his palm, and pull back into his fingers. The one the server pins
	-- stays skewered on three of them (Effects.RivetPin).
	function Effects.RivetStab(char, data, isLocal, ability)
		local root = charParts(char)
		if not root then
			return
		end
		ability = ability or {}
		local dir = typeof(data.Dir) == "Vector3" and data.Dir.Magnitude > 0.1 and data.Dir.Unit or root.CFrame.LookVector
		if isLocal then
			face(root, dir)
		end
		VFX.Motion(char, "RivetStab")
		local windup = ability.Windup or 0.2
		local ANGLES = { -14, -7, 0, 7, 14 }
		local claws = outlineModel(PAL.RED)
		local hand0 = handPos(char, true)
		local side0 = root.CFrame.RightVector
		for i, a in ANGLES do
			local from = hand0 + side0 * (a / 14) * 0.35
			DY.tendril(from, CFrame.Angles(0, math.rad(a), 0) * dir, 1.2, 0.26, claws,
				{ speed = 1.2 / math.max(windup * 0.6, 0.05), segments = 2, life = windup * 0.7, delay = i * 0.01, retract = true })
		end
		cleanup(claws, windup + 0.4)
		local t0 = os.clock()
		while os.clock() - t0 < windup * 0.75 and root.Parent do
			local hand = handPos(char, true)
			bolt(hand, 1.4, PAL.RED)
			bolt(hand, 1.2, PAL.BLACK)
			task.wait(0.05)
		end
		task.wait(math.max(windup - (os.clock() - t0), 0))
		if not root.Parent then
			return
		end
		local origin = root.Position + UP
		local length = ability.Range or 110
		local hand = handPos(char, true)
		local side = root.CFrame.RightVector
		local model = outlineModel(PAL.RED)
		local hits = { n = 0 }
		for i, a in ANGLES do
			-- (from his fingertips to the end of the server's line)
			local from = hand + side * (a / 14) * 0.35
			local to = origin + CFrame.Angles(0, math.rad(a), 0) * dir * length
			DY.tendril(from, to - from, (to - from).Magnitude, 0.85, model, { delay = i * 0.012, forks = i % 2, hits = hits, life = 0.32, retract = true })
		end
		cleanup(model, 0.95)
		-- the burst at his palm: red and black
		sparks(hand, 1, PAL.RED, PAL.BLACK, 12)
		billboardRing(hand, 0.6, 5, PAL.RED, 3, 0.16)
		shockDisc(hand, dir, 0.6, 5, 0.15, PAL.RED, 1.5)
		VFX.PlaySound("Rivet", origin, 1)
		VFX.ShakeAt(origin, 0.8, 60, 0.15)
	end

	-- (round 84) the server's pin: skewered on three rivets out of his hand,
	-- held there (Pin), then reeled in as they pull back into his fingers
	-- (Reel); he holds his hand out on them the whole time
	function Effects.RivetPin(char, data)
		local root = charParts(char)
		local target = data.Target
		local troot = typeof(target) == "Instance" and target:FindFirstChild("HumanoidRootPart")
		if not root or not troot then
			return
		end
		local pin, reel = tonumber(data.Pin) or 0.45, tonumber(data.Reel) or 0.3
		VFX.Pose(char, "APShot", pin + reel)
		local torso = target:FindFirstChild("Torso") or target:FindFirstChild("UpperTorso") or troot
		local model = outlineModel(PAL.RED)
		for i = 1, 3 do
			local off = CFrame.new((i - 2) * 0.45, 0.45 - (i % 2) * 0.7, 0)
			DY.liveTendril(function()
				return root.Parent and handPos(char, true) or nil
			end, function()
				return torso.Parent and (torso.CFrame * off).Position or nil
			end, 0.62 - math.abs(i - 2) * 0.14, model, pin + reel, 0.12, i * 7 + 3)
		end
		cleanup(model, pin + reel + 0.6)
		-- where it goes in: red and black bursting out of them
		sparks(torso.Position, 0.9, PAL.RED, PAL.BLACK, 10)
		VFX.PlaySound("Rivet", torso.Position, 0.8)
		task.delay(pin, function()
			if troot.Parent then
				VFX.PlaySound("RivetReel", troot.Position, 1)
				-- (the rush of air as they're yanked in)
				local toward = root.Parent and flatten(root.Position - troot.Position, troot) or troot.CFrame.LookVector
				streaks(troot.Position, toward, 6, 1.2, 4, 10, PAL.DUST_LIGHT, 0.2)
			end
		end)
	end

	-- (round 84) violet lightning striking down a building's face where the
	-- pulse meets it (ep 120): a violet bolt with a white core, black cracks
	-- left in the wall
	function DY.strike(pos, normal)
		normal = (typeof(normal) == "Vector3" and normal.Magnitude > 0.1) and normal.Unit or UP
		local top = pos + UP * rand(9, 15) + normal * 0.8
		local pts = { top }
		local n = 6
		for j = 1, n do
			pts[j + 1] = j == n and pos or top:Lerp(pos, j / n) + Vector3.new(rand(-1, 1), 0, rand(-1, 1)) * 1.1
		end
		for pass = 1, 2 do
			local w = pass == 1 and 0.4 or 0.14
			for j = 1, n do
				local a, b = pts[j], pts[j + 1]
				local seg = newPart(Vector3.new(w, w, (b - a).Magnitude + w), CFrame.lookAt((a + b) / 2, b), pass == 1 and PAL.VIOLET or Color3.new(1, 1, 1), Enum.Material.Neon)
				tween(seg, 0.18, { Transparency = 1 }, nil, nil, 0.09)
				cleanup(seg, 0.3)
			end
		end
		sparks(pos, 0.8, PAL.VIOLET, Color3.new(1, 1, 1), 8)
		DY.rivetHit(pos, normal)
	end

	-- (round 84) the air washed yellow-green for a moment round the blast
	function DY.radioTint(strength)
		local Lighting = game:GetService("Lighting")
		local cc = Lighting:FindFirstChild("RadioTint")
		if not cc then
			cc = Instance.new("ColorCorrectionEffect")
			cc.Name = "RadioTint"
			cc.Parent = Lighting
		end
		DY.radioToken = (DY.radioToken or 0) + 1
		local token = DY.radioToken
		local s = math.clamp(tonumber(strength) or 1, 0, 1)
		cc.Enabled = true
		tween(cc, 0.08, { TintColor = Color3.new(1, 1, 1):Lerp(Color3.fromRGB(226, 236, 170), s), Saturation = 0.1 * s, Contrast = 0.06 * s })
		task.delay(0.5, function()
			if token == DY.radioToken then
				tween(cc, 0.9, { TintColor = Color3.new(1, 1, 1), Saturation = 0, Contrast = 0 }, Enum.EasingStyle.Sine)
			end
		end)
	end

	-- RADIO WAVES (ep 119, with Air Cannon), rebuilt in round 84 from the
	-- episode frame by frame:
	--  * his palm out, black lightning edged violet crackling round both arms;
	--  * AIR CANNON'S GOLD ORB swelling round the palm - a bubble with a
	--    bright rim and amber light inside - twice flickering violet with
	--    black lightning cracked across it (the Radio Waves under it), its
	--    middle going white-hot;
	--  * the pop: a white-hot star and the screen white for a beat;
	--  * the blast rolling out across the fan at the server's speed: a wall
	--    of yellow-green air with a bright yellow crest along its foot and a
	--    violet edge; the YELLOW STREAKS - bright flecks of it tearing out
	--    ahead, smeared long; the street left in a yellow-green haze, black
	--    lightning hanging in it, purple lightning skittering through it,
	--    dry black cracks; violet lightning striking down the buildings it
	--    meets; the air round it washed yellow-green for a moment.
	function Effects.RadioWaves(char, data, isLocal, ability)
		local root = charParts(char)
		if not root then
			return
		end
		ability = ability or {}
		local d = flatten(data.Dir, root)
		if isLocal then
			face(root, d)
		end
		VFX.Motion(char, "RadioWaves")
		VFX.PlaySound("RadioCharge", root.Position, 1)
		local windup = ability.Windup or 0.4
		local at0 = handPos(char, true)
		local bubble = newPart(Vector3.one * 0.4, CFrame.new(at0), PAL.GOLD, Enum.Material.ForceField, Enum.PartType.Ball)
		bubble.Name = "RadioOrb"
		local glow = newPart(Vector3.one * 0.3, CFrame.new(at0), PAL.AMBER, Enum.Material.Neon, Enum.PartType.Ball)
		glow.Transparency = 0.45
		local core = newPart(Vector3.one * 0.2, CFrame.new(at0), PAL.CORE, Enum.Material.Neon, Enum.PartType.Ball)
		local light = Instance.new("PointLight")
		light.Color, light.Range, light.Brightness, light.Shadows = PAL.GOLD, 12, 2.5, false
		light.Parent = core
		cleanup(bubble, windup + 1)
		cleanup(glow, windup + 1)
		cleanup(core, windup + 1)
		local cracks = outlineModel(PAL.VIOLET)
		cleanup(cracks, windup + 0.5)
		local t0 = os.clock()
		local nextBolt, flick, lastK = 0, 0, 0
		local burst = at0
		-- (what the orb did, for a look afterwards: the tests)
		local orbInfo = { flickers = 0, size = 0 }
		DY.lastOrb = orbInfo
		while os.clock() - t0 < windup and root.Parent do
			local e = os.clock() - t0
			local k = math.min(e / windup, 1)
			local s = 0.5 + 3.3 * k
			orbInfo.size = s
			burst = handPos(char, true) + d * (0.3 + s * 0.45)
			bubble.CFrame, bubble.Size = CFrame.new(burst), Vector3.one * s
			glow.CFrame, glow.Size = CFrame.new(burst), Vector3.one * s * 0.82
			core.CFrame, core.Size = CFrame.new(burst), Vector3.one * s * (0.12 + 0.3 * k * k)
			-- (the two violet flickers)
			local window = (k > 0.32 and k < 0.44 and 1) or (k > 0.68 and k < 0.8 and 2) or 0
			-- (a slow frame that jumps right over one still shows it)
			if window == 0 and lastK <= 0.32 and k >= 0.44 and flick < 1 then
				window = 1
			elseif window == 0 and lastK <= 0.68 and k >= 0.8 and flick < 2 then
				window = 2
			end
			lastK = k
			bubble.Color = window > 0 and PAL.VIOLET or PAL.GOLD
			glow.Color = window > 0 and PAL.VIOLET_DEEP or PAL.AMBER
			light.Color = window > 0 and PAL.VIOLET or PAL.GOLD
			if window > 0 and flick ~= window then
				flick = window
				orbInfo.flickers += 1
				for _ = 1, 3 do
					DY.jag(burst + rng:NextUnitVector() * s * 0.45, burst + rng:NextUnitVector() * s * 0.45, 0.22, cracks, windup * 0.12, 0)
				end
			end
			if e >= nextBolt then
				nextBolt = e + 0.09
				for _, right in { true, false } do
					local hand = handPos(char, right)
					bolt(hand, 2.2, PAL.VIOLET)
					bolt(hand, 1.6, PAL.BLACK)
				end
			end
			task.wait()
		end
		bubble:Destroy()
		glow:Destroy()
		core:Destroy()
		if not root.Parent then
			return
		end
		-- the pop
		if VFX.MANGA then
			VFX.MANGA.flare(burst, PAL.CORE, 6, 0.35)
			if nearCamera(burst, 70) then
				VFX.MANGA.lines(0.25, { Kind = "focus" })
			end
		end
		billboardRing(burst, 2, 22, Color3.new(1, 1, 1), 6, 0.25)
		billboardRing(burst, 1, 14, PAL.GOLD, 4, 0.3)
		local range = ability.Range or 85
		local half = math.rad(ability.Angle or 60)
		local speed = math.max(ability.Speed or 220, 1)
		local origin = root.Position + d * 2 + UP * 1.5
		local g = DY.ground(origin, origin.Y - 4.5)
		local travel = range / speed
		local base = math.atan2(d.X, d.Z)
		local k = DY.k()
		-- the front, rolling out across the fan: the yellow-green wall (a rim
		-- of light over a hazy body), its bright yellow crest along the
		-- street, a violet edge behind
		local SEGS = 12
		local FRONTS = {
			-- colour, material, transparency, height, height off the street, delay
			{ PAL.HAZE, Enum.Material.ForceField, 0, 7, 3.5, 0 },
			{ PAL.HAZE, Enum.Material.Neon, 0.72, 5, 2.5, 0 },
			{ PAL.YELLOW, Enum.Material.Neon, 0.12, 0.9, 0.5, 0.02 },
			{ PAL.VIOLET, Enum.Material.Neon, 0.35, 2.4, 1.6, 0.08 },
		}
		for _, spec in FRONTS do
			task.delay(spec[6], function()
				for kk = 0, SEGS - 1 do
					local a = base - half + (kk + 0.5) / SEGS * half * 2
					local out = Vector3.new(math.sin(a), 0, math.cos(a))
					local tangent = Vector3.new(out.Z, 0, -out.X)
					local r0, r1 = 3, range
					local chord = 2 * math.sin(half / SEGS)
					local y = Vector3.new(0, g.Y + spec[5], 0)
					local p0 = Vector3.new(origin.X, 0, origin.Z) + out * r0 + y
					local p1 = Vector3.new(origin.X, 0, origin.Z) + out * r1 + y
					-- (looking along the arc: its length goes on Z, so it's a wall
					-- across the fan, not a spoke out of it)
					local seg = newPart(Vector3.new(0.8, spec[4], r0 * chord * 1.05), CFrame.lookAt(p0, p0 + tangent), spec[1], spec[2])
					seg.Transparency = spec[3]
					tween(seg, travel, { CFrame = CFrame.lookAt(p1, p1 + tangent), Size = Vector3.new(1.2, spec[4] * 1.7, r1 * chord * 1.05), Transparency = 1 }, Enum.EasingStyle.Linear)
					cleanup(seg, travel + 0.1)
				end
			end)
		end
		-- THE YELLOW STREAKS: bright flecks of the blast tearing out across the
		-- fan ahead of the front, smeared long
		for _ = 1, math.max(math.floor(34 * k), 8) do
			local a = base + rand(-half, half)
			local out = Vector3.new(math.sin(a), rand(-0.02, 0.12), math.cos(a)).Unit
			local start = Vector3.new(origin.X, g.Y, origin.Z) + Vector3.new(out.X, 0, out.Z) * rand(2, 10) + UP * rand(0.4, 6)
			local len = rand(2.5, 6)
			local dist = range * rand(0.55, 1.05)
			local t = dist / (speed * rand(1.05, 1.5))
			local delay = rand(0, 0.12)
			local fleck = newPart(Vector3.new(rand(0.25, 0.45), rand(0.2, 0.35), len), CFrame.lookAt(start, start + out), PAL.YELLOW, Enum.Material.Neon)
			fleck.Name = "RadioStreak"
			fleck.Transparency = 1
			tween(fleck, 0.01, { Transparency = 0.05 }, nil, nil, delay)
			tween(fleck, t, { CFrame = CFrame.lookAt(start + out * dist, start + out * (dist + 1)), Size = Vector3.new(0.12, 0.1, len * 1.8) }, Enum.EasingStyle.Quad, Enum.EasingDirection.Out, delay)
			tween(fleck, t * 0.4, { Transparency = 1 }, Enum.EasingStyle.Quad, Enum.EasingDirection.In, delay + t * 0.6)
			cleanup(fleck, delay + t + 0.05)
		end
		-- the street left in yellow-green haze: low banks of it drifting on,
		-- yellow smears over the ground, purple lightning skittering through
		for s2 = 6, range, 9 do
			task.delay(s2 / speed, function()
				for _ = 1, math.max(math.floor(3 * k), 1) do
					local a = base + rand(-half, half) * 0.9
					local out = Vector3.new(math.sin(a), 0, math.cos(a))
					local p = DY.ground(origin + out * s2, origin.Y - 4.5)
					local w = rand(6, 10) * (0.6 + s2 / range)
					local h = rand(2.5, 4)
					local slab = newPart(Vector3.new(w, h, rand(7, 11)), CFrame.lookAt(p + UP * h * 0.5, p + UP * h * 0.5 + out), PAL.HAZE, Enum.Material.SmoothPlastic)
					slab.Name = "RadioHaze"
					slab.Transparency = 0.6
					tween(slab, rand(0.9, 1.3), { CFrame = slab.CFrame + out * rand(4, 8) + UP * rand(1, 2.5), Size = slab.Size * Vector3.new(1.4, 1.6, 1.3), Transparency = 1 }, Enum.EasingStyle.Quad, Enum.EasingDirection.Out)
					cleanup(slab, 1.4)
				end
				for _ = 1, math.max(math.floor(3 * k), 1) do
					local a = base + rand(-half, half) * 0.9
					local out = Vector3.new(math.sin(a), 0, math.cos(a))
					local p = DY.ground(origin + out * s2, origin.Y - 4.5) + UP * 0.4
					local smear = newPart(Vector3.new(rand(1.5, 3), 0.2, rand(5, 9)), CFrame.lookAt(p, p + out), PAL.YELLOW:Lerp(PAL.HAZE, 0.4), Enum.Material.Neon)
					smear.Transparency = 0.35
					tween(smear, 0.3, { CFrame = CFrame.lookAt(p + out * 9 + UP * 0.5, p + out * 10 + UP * 0.5), Transparency = 1, Size = Vector3.new(0.3, 0.1, 12) }, Enum.EasingStyle.Quad, Enum.EasingDirection.Out)
					cleanup(smear, 0.35)
				end
				local a = base + rand(-half, half) * 0.8
				local p = DY.ground(origin + Vector3.new(math.sin(a), 0, math.cos(a)) * (s2 - 4), origin.Y - 4.5)
				bolt(p + UP * 1.2, 2.5, PAL.VIOLET)
				bolt(p + UP * 1.2, 2, PAL.BLACK)
			end)
		end
		-- black lightning hanging in the haze (violet-edged)
		local shards = outlineModel(PAL.VIOLET)
		for _ = 1, math.max(math.floor(9 * k), 3) do
			local a = base + rand(-half, half) * 0.9
			local out = Vector3.new(math.sin(a), 0, math.cos(a))
			local r = rand(8, range * 0.9)
			local p = DY.ground(origin + out * r, origin.Y - 4.5) + UP * rand(1.5, 7)
			local q = p + Vector3.new(rand(-1, 1), rand(-0.5, 0.5), rand(-1, 1)).Unit * rand(2.5, 5)
			DY.jag(p, q, 0.35, shards, 0.22, r / speed + rand(0, 0.08))
		end
		cleanup(shards, travel + 0.6)
		for i = -1, 1 do
			local a = base + i * half * 0.6 + rand(-0.1, 0.1)
			local out = Vector3.new(math.sin(a), 0, math.cos(a))
			DY.crack(DY.ground(origin + out * 4, origin.Y - 4.5), out, range * rand(0.6, 0.85), { speed = speed, w0 = 0.5, w1 = 0.15, step = 6, wander = 1.5, life = 2.5, hot = false })
		end
		-- where it meets a building: violet lightning down its face
		for i = -2, 2 do
			local a = base + i / 2 * half * 0.85
			local out = Vector3.new(math.sin(a), 0, math.cos(a))
			local hit = DY.cast(origin + UP * 1.5, out * range)
			if hit then
				task.delay((hit.Position - origin).Magnitude / speed, DY.strike, hit.Position, hit.Normal)
			end
		end
		shockDisc(origin, d, 4, 22, 0.3, PAL.VIOLET, 12)
		shockDisc(origin, d, 3, 18, 0.25, PAL.GOLD, 9)
		if nearCamera(origin, 90) then
			VFX.Hooks.Flash(Color3.fromRGB(255, 252, 236), 0.12)
		end
		if nearCamera(origin + d * range * 0.5, range * 0.8) then
			DY.radioTint(1)
		end
		VFX.PlaySound("RadioWaves", origin, 1)
		VFX.ShakeAt(origin, 2.4, 160, 0.5)
	end

	-- (round 84) the jam on someone, for everyone to see: static crackling
	-- pale blue round their head (the jammed comms in ep 120), a black bolt
	-- now and then, for as long as it lasts
	function Effects.RadioJam(_, data)
		local target = data.Target
		local head = typeof(target) == "Instance" and (target:FindFirstChild("Head") or target:FindFirstChild("HumanoidRootPart"))
		if not head then
			return
		end
		local dur = math.clamp(tonumber(data.Duration) or 2.5, 0, 6)
		VFX.PlaySound("RadioJam", head.Position, 1)
		local t0 = os.clock()
		while os.clock() - t0 < dur and head.Parent do
			bolt(head.Position + rng:NextUnitVector() * 0.4, 1.3, PAL.STATIC)
			if rng:NextNumber() < 0.3 then
				bolt(head.Position, 1.6, PAL.BLACK)
			end
			task.wait(0.09)
		end
	end

	-- server: the pulse jammed you - static over your screen
	function Effects.Jammed(_, data)
		if VFX.Hooks.Jam then
			VFX.Hooks.Jam(tonumber(data.Duration) or 2.5)
		end
	end

	-- RIVET STORM (ult 2): he folds in with black lightning tightening round
	-- him, then (the server's Windup) the rivets burst out of his hands and
	-- his back along the server's fourteen lines - (round 84) with a crown of
	-- them rising out of his spine behind him, held while the ones that
	-- caught someone lift them (Effects.RivetLift), all pulled back in after
	function Effects.RivetStorm(char, _data, isLocal, ability)
		local root = charParts(char)
		if not root then
			return
		end
		ability = ability or {}
		VFX.Motion(char, "RivetStorm")
		local windup = ability.Windup or 0.3
		local t0 = os.clock()
		while os.clock() - t0 < windup * 0.9 and root.Parent do
			local kk = (os.clock() - t0) / (windup * 0.9)
			bolt(root.Position + UP * 0.5, 3.4 - kk * 2, PAL.BLACK)
			bolt(root.Position + UP * 0.5, 3 - kk * 1.6, PAL.VIOLET)
			task.wait(0.06)
		end
		task.wait(math.max(windup - (os.clock() - t0), 0))
		if not root.Parent then
			return
		end
		local origin = root.Position + UP
		local length = ability.Range or 90
		local look = root.CFrame.LookVector
		local spine = origin + UP * 0.6 - look * 0.6
		local starts = { handPos(char, true), handPos(char, false), spine }
		local model = outlineModel(PAL.RED)
		local hits = { n = 0 }
		for i, v in DY.stormDirs() do
			local from = starts[i % 3 + 1]
			if (from - origin).Magnitude > 1.2 then
				from = origin + (from - origin).Unit * 1.2
			end
			local to = origin + v * length
			DY.tendril(from, to - from, (to - from).Magnitude, 1.05, model, { delay = (i % 3) * 0.03, segments = 5, sparse = true, forks = i % 2 + 1, hits = hits, life = 0.4, retract = true })
		end
		-- the crown out of his spine (Shigaraki in the sky, ep 122)
		local hold = (ability.LiftHold or 0.7) + (ability.SlamTime or 0.16)
		local right = root.CFrame.RightVector
		for i = 1, 6 do
			local side = (i - 3.5) / 2.5
			local v = (-look * 0.7 + UP * (1.1 - math.abs(side) * 0.5) + right * side * 1.3).Unit
			local len = rand(12, 20)
			DY.tendril(spine, v, len, 0.7, model, { delay = 0.02 * i, segments = 4, forks = 1, life = hold, retract = true, speed = 300 })
		end
		cleanup(model, hold + 0.8)
		shockDisc(DY.ground(root.Position, root.Position.Y - 3) + UP * 0.3, UP, 3, 26, 0.35, PAL.DUST_LIGHT)
		sparks(spine, 1.2, PAL.RED, PAL.BLACK, 14)
		if isLocal and VFX.MANGA then
			VFX.MANGA.mono(0.06, { Tint = Color3.fromRGB(255, 220, 220), Contrast = 1.2 })
		end
		VFX.PlaySound("Rivet", origin, 1.2)
		VFX.ShakeAt(origin, 2, 120, 0.4)
	end

	-- (round 84) the server's lift: everyone the storm caught, skewered on two
	-- rivets out of his back and held up on them (Lift, Hold), then slammed
	-- (RivetSlam)
	function Effects.RivetLift(char, data)
		local root = charParts(char)
		if not root or type(data.Targets) ~= "table" then
			return
		end
		local dur = (tonumber(data.Hold) or 0.7) + (tonumber(data.Slam) or 0.16)
		local model = outlineModel(PAL.RED)
		for n, target in data.Targets do
			local troot = typeof(target) == "Instance" and target:FindFirstChild("HumanoidRootPart")
			local torso = troot and (target:FindFirstChild("Torso") or target:FindFirstChild("UpperTorso") or troot)
			if torso then
				for j = 1, 2 do
					local off = CFrame.new((j - 1.5) * 0.6, 0.3, 0)
					DY.liveTendril(function()
						if not root.Parent then
							return nil
						end
						return root.Position + UP * 1.6 - root.CFrame.LookVector * 0.6 + root.CFrame.RightVector * (j - 1.5) * 0.8
					end, function()
						return torso.Parent and (torso.CFrame * off).Position or nil
					end, 0.75, model, dur, 0.12, n * 11 + j)
				end
				sparks(torso.Position, 0.9, PAL.RED, PAL.BLACK, 10)
			end
		end
		cleanup(model, dur + 0.6)
		VFX.PlaySound("RivetReel", root.Position, 0.9)
	end

	-- (round 84) ...and slammed into the street: a dent, dust, flakes
	function Effects.RivetSlam(_, data)
		if type(data.Points) ~= "table" then
			return
		end
		for _, p in data.Points do
			if typeof(p) == "Vector3" then
				groundMark(p, 4, PAL.CRACK, 4)
				shockDisc(p + UP * 0.3, UP, 2, 14, 0.3, PAL.DUST_LIGHT)
				for i = 1, 5 do
					local a = i / 5 * math.pi * 2
					celPuff(folder, p, p + Vector3.new(math.cos(a), 0, math.sin(a)) * rand(2, 3.5) + UP * rand(0.8, 2), rand(2, 3), PAL.DUST, PAL.DUST_HI, 0.2, 0.9, i * 0.02)
				end
				DY.flakes(p + UP, 8, 1, PAL.DUST, PAL.ASH)
				VFX.PlaySound("TentacleSlam", p, 1)
				VFX.ShakeAt(p, 1.5, 80, 0.3)
			end
		end
	end

	-- TOTAL DECAY (ult 3, the cinematic): he rises in a column of ash, blocks
	-- of the street lit lilac swirling up round him (ep 118), black lightning
	-- on his arms and his right arm splitting red; both palms down on the
	-- clip's Hit (1.2 s), and on the server's beat (1.3 s) the white sketch
	-- frame (ep 112), the air going lilac, and the spread to 120 studs in
	-- 2.4 s - the cracks, the plates, the low surge of dust - with the dome
	-- of dust rising over it for the crane shot. No fire.
	function Effects.TotalDecay(char, _data, isLocal, ability)
		local root = charParts(char)
		if not root then
			return
		end
		cinematicFor(char, "TotalDecay", isLocal, ability and ability.Name or "TOTAL DECAY", PAL.RED)
		if isLocal then
			VFX.Hooks.Dim(0.55, 3.2)
		end
		VFX.Motion(char, "TotalDecay")
		VFX.PlaySound("TotalDecay", root.Position, 1)
		local g = groundPoint(root.Position)
		DY.armCracks(char, 3.6)
		local fling = DY.vortex(g, 1.3)
		local t0 = os.clock()
		local palms = false
		local function palmsDown()
			palms = true
			local look = Vector3.new(root.CFrame.LookVector.X, 0, root.CFrame.LookVector.Z)
			for _, right in { true, false } do
				DY.palm(DY.ground(handPos(char, right), g.Y), look, { len = 7, k = 1.2 })
			end
		end
		while os.clock() - t0 < 1.3 and root.Parent do
			local e = os.clock() - t0
			local k = e / 1.3
			-- the dust swirling up round him, lit lilac
			local a = e * 7 + rand(-0.3, 0.3)
			local out = Vector3.new(math.cos(a), 0, math.sin(a))
			local p = g + out * rand(3, 5)
			celPuff(folder, p, p + out * rand(1, 2.5) + UP * rand(3, 9) * (0.6 + k), rand(2.5, 4) * (0.6 + k), PAL.MAUVE, PAL.LILAC, 0.25, 0.9)
			bolt(handPos(char, true), 2 + k * 2, PAL.BLACK)
			bolt(handPos(char, false), 2 + k * 2, PAL.VIOLET)
			if not palms and k >= 1.2 / 1.3 then
				palmsDown()
			end
			-- (never past the server's 1.3 s: the slam lands with its spread)
			task.wait(math.min(0.12, math.max(1.3 - (os.clock() - t0), 0)))
		end
		if not root.Parent then
			return
		end
		if not palms then
			palmsDown()
		end
		fling()
		local center = groundPoint(root.Position)
		if nearCamera(center, 300) then
			DY.sketch(0.2)
			DY.tint(1.2, 2.4, 1.5)
		end
		billboardRing(center + UP, 3, 80, Color3.new(1, 1, 1), 0, 0.25, true)
		VFX.PlaySound("Collapse", center, 1.3)
		local R = (ability and ability.Radius) or 120
		DY.ring(center, R, 2.4, { cracks = 12, h = 13, slabs = 8, puffs = 5, teeth = 2, w0 = 1.4, step = 9, slabScale = 1.4 })
		DY.curtains(center, R, 2.4)
		DY.dome(center, 40, 30, 3, { puffs = 22, slabs = 5, lift = 10 })
		groundMark(center, 30, PAL.CRACK, 14)
		VFX.ShakeAt(center, 5, 400, 2.6)
		task.delay(2.4, function()
			-- the haze left hanging over the dust plain
			smokeBurst(center + UP * 4, PAL.DUST_LIGHT, 14, R * 0.8, 2.3, math.floor(24 * DY.k()))
		end)
	end
end

---------------------------------------------------------------------------
-- GUARD: block, parry, guard break, KO
---------------------------------------------------------------------------

do -- GUARD: its helpers stay local to this block (Luau allows 200 locals per scope)
	local GUARD_FULL = Color3.fromRGB(196, 232, 255)
	local GUARD_LOW = Color3.fromRGB(255, 90, 70)
	local guardVisuals = setmetatable({}, { __mode = "k" }) -- [character] = { Shield, Conn }
	-- (round 74) THE GUARD ON AN R6 BODY (most bodies here are R6: no elbows,
	-- no knees - the old guard, built for elbows, held two stiff arms straight
	-- out in front). A boxer's cross-guard: sunk into a crouch, bladed a
	-- little, chin tucked, forearms crossed in front of the face - snapped
	-- up with a little overshoot, rocked back by every hit it takes (harder
	-- by a heavy one), a parry flung up and out, and a broken guard throws the
	-- arms wide and leaves them swaying on their feet. (R15 keeps its own.)
	-- (R6 signs, checked against the joint maths: Waist / Neck pitch - is
	-- forward / chin down; an arm's roll turns it about the body's forward
	-- axis - + takes a raised arm in across the face, a hanging one out)
	POSES.GuardR6 = {
		RightArm = { 142, 0, 70 }, LeftArm = { 134, 0, 82 },
		Waist = { -10, 14, 0 }, Neck = { -4, -10, 0 },
		RightLeg = { -14, 0, 6 }, LeftLeg = { 18, 0, 4 }, Crouch = 0.42,
	}
	POSES.GuardRaiseR6 = {
		RightArm = { 152, 0, 74 }, LeftArm = { 144, 0, 86 },
		Waist = { -14, 18, 0 }, Neck = { -8, -12, 0 },
		RightLeg = { -16, 0, 6 }, LeftLeg = { 20, 0, 4 }, Crouch = 0.55,
	}
	POSES.BlockHitR6 = {
		RightArm = { 150, 0, 64 }, LeftArm = { 142, 0, 76 },
		Waist = { -2, 10, 0 }, Neck = { 4, -8, 0 },
		RightLeg = { -20, 0, 6 }, LeftLeg = { 12, 0, 4 }, Crouch = 0.55,
	}
	POSES.BlockHitHeavyR6 = {
		RightArm = { 164, 0, 48 }, LeftArm = { 156, 0, 58 },
		Waist = { 9, 6, 0 }, Neck = { 12, 0, 0 },
		RightLeg = { -26, 0, 8 }, LeftLeg = { 10, 0, 6 }, Crouch = 0.72, Hips = { 0, 0, 0, 0, 0, 0.4 },
	}
	POSES.ParrySwipeR6 = {
		RightArm = { 164, 0, -30 }, LeftArm = { 80, 0, 30 },
		Waist = { 4, -26, 0 }, Neck = { 8, 18, 0 },
		RightLeg = { -10, 0, 6 }, LeftLeg = { 22, 0, 4 }, Crouch = 0.22,
	}
	POSES.ParryFollowR6 = {
		RightArm = { 118, 0, -10 }, LeftArm = { 96, 0, 36 },
		Waist = { -8, -10, 0 }, Neck = { -2, 8, 0 },
		RightLeg = { -12, 0, 6 }, LeftLeg = { 18, 0, 4 }, Crouch = 0.36,
	}
	POSES.GuardShatterR6 = {
		RightArm = { 166, 0, -64 }, LeftArm = { 158, 0, -60 },
		Waist = { 18, 0, 0 }, Neck = { 24, 0, 0 },
		RightLeg = { -8, 0, 10 }, LeftLeg = { 14, 0, 8 }, Crouch = 0.12,
	}
	POSES.DazedAR6 = {
		RightArm = { 18, 0, 26 }, LeftArm = { 34, 0, 20 },
		Waist = { -10, -14, 12 }, Neck = { -16, 22, 16 },
		RightLeg = { -16, 0, 12 }, LeftLeg = { 20, 0, 8 }, Crouch = 0.36,
	}
	POSES.DazedBR6 = {
		RightArm = { 32, 0, 18 }, LeftArm = { 16, 0, 28 },
		Waist = { -8, 14, -12 }, Neck = { -18, -20, -16 },
		RightLeg = { -16, 0, 12 }, LeftLeg = { 20, 0, 8 }, Crouch = 0.3,
	}
	MOTIONS.GuardRaiseR6 = { { pose = "GuardRaiseR6", t = 0.05, style = SNAP }, { pose = "GuardR6", t = 0.1 }, recover = 0.08, keep = "Guard" }
	MOTIONS.BlockRecoilR6 = { { pose = "BlockHitR6", t = 0.03, hold = 0.05, style = SNAP }, recover = 0.12, keep = "Guard" }
	MOTIONS.BlockRecoilHeavyR6 = { { pose = "BlockHitHeavyR6", t = 0.03, hold = 0.1, style = SNAP }, { pose = "BlockHitR6", t = 0.1, hold = 0.02 }, recover = 0.16, keep = "Guard" }
	MOTIONS.ParryR6 = { { pose = "ParrySwipeR6", t = 0.04, hold = 0.12, style = Enum.EasingStyle.Back }, { pose = "ParryFollowR6", t = 0.1, hold = 0.04 }, recover = 0.16, keep = "Guard" }
	MOTIONS.GuardBreakR6 = {
		{ pose = "GuardShatterR6", t = 0.05, hold = 0.12, style = SNAP },
		{ pose = "DazedAR6", t = 0.28, hold = 0.18 },
		{ pose = "DazedBR6", t = 0.38, hold = 0.14 },
		{ pose = "DazedAR6", t = 0.38, hold = 0.1 },
		recover = 0.35,
	}
	-- which guard motion a body plays: the R6 one on an R6 body
	local function guardMotion(model, name)
		if model and not model:FindFirstChild("UpperTorso") and MOTIONS[name .. "R6"] then
			return name .. "R6"
		end
		return MOTIONS[name] and name or "BlockRecoil"
	end

	local function guardColor(model)
		local max = (Config.Guard and Config.Guard.Max) or 100
		local ratio = math.clamp((model:GetAttribute("Guard") or max) / max, 0, 1)
		return GUARD_LOW:Lerp(GUARD_FULL, ratio)
	end

	local function removeGuardVisual(model)
		guarding[model] = nil
		local v = guardVisuals[model]
		guardVisuals[model] = nil
		if v then
			v.Conn:Disconnect()
			if v.Shield.Parent then
				tween(v.Shield, 0.12, { Transparency = 1, Size = v.Shield.Size * Vector3.new(1, 0.6, 0.6) })
				cleanup(v.Shield, 0.15)
			end
		end
	end

	-- data.On: guard raised / lowered. data.Target: whose guard.
	function Effects.Guard(char, data)
		local owner = typeof(data.Target) == "Instance" and data.Target or char
		local root = owner and owner:FindFirstChild("HumanoidRootPart")
		if not root then
			return
		end
		local me = Players.LocalPlayer
		local slot = slotInfo(Anim.Block)
		local useAnim = slot and rigMatches(owner)
		if not data.On then
			removeGuardVisual(owner)
			if useAnim then
				if me and me.Character == owner then
					VFX.StopAnimation(owner, slot)
				end
			end
			-- always: a stance left under a clip (or a late recoil) is what skews the body
			VFX.ReleasePose(owner, 0.12)
			return
		end
		removeGuardVisual(owner)
		if useAnim then
			if me and me.Character == owner then
				VFX.PlayAnimation(owner, slot, { Looped = true })
			end
		else
			poseBlockedUntil[owner] = nil
			guarding[owner] = true
			-- (round 74) snapped up with a little overshoot (R6: the cross-guard)
			if owner:FindFirstChild("UpperTorso") then
				VFX.Pose(owner, "Guard", -1)
			else
				VFX.Motion(owner, "GuardRaiseR6")
			end
		end
		guarding[owner] = true
		-- a see-through barrier in front of the arms, tinted by the guard meter
		local shield = Instance.new("Part")
		shield.Name = "GuardShield"
		shield.Shape = Enum.PartType.Cylinder
		shield.Size = Vector3.new(0.15, 1, 1)
		shield.Material = Enum.Material.ForceField
		shield.Color = guardColor(owner)
		shield.Transparency = 0.15
		shield.CanCollide = false
		shield.CanQuery = false
		shield.CanTouch = false
		shield.Massless = true
		shield.CastShadow = false
		shield.CFrame = root.CFrame * CFrame.new(0, 0.6, -1.7) * CFrame.Angles(0, math.rad(90), 0)
		local weld = Instance.new("WeldConstraint")
		weld.Part0 = root
		weld.Part1 = shield
		weld.Parent = shield
		shield.Parent = owner
		tween(shield, 0.1, { Size = Vector3.new(0.15, 6, 6) }, Enum.EasingStyle.Back)
		local conn = owner:GetAttributeChangedSignal("Guard"):Connect(function()
			if shield.Parent then
				shield.Color = guardColor(owner)
			end
		end)
		guardVisuals[owner] = { Shield = shield, Conn = conn }
		VFX.PlaySound("GuardUp", root.Position, 0.7)
	end

	-- A hit landed on someone's guard. data.Target, data.From (attacker position)
	function Effects.Block(_, data)
		local target = data.Target
		local root = target and target:FindFirstChild("HumanoidRootPart")
		if not root then
			return
		end
		local from = typeof(data.From) == "Vector3" and data.From or (root.Position + root.CFrame.LookVector * 4)
		local toward = Vector3.new(from.X - root.Position.X, 0, from.Z - root.Position.Z)
		toward = toward.Magnitude > 0.1 and toward.Unit or root.CFrame.LookVector
		local contact = root.Position + toward * 2 + Vector3.new(0, 0.6, 0)
		sparks(contact, 0.5, Color3.new(1, 1, 1), guardColor(target), 14)
		shockDisc(contact, toward, 1, 7, 0.16, guardColor(target))
		local v = guardVisuals[target]
		if v and v.Shield.Parent then
			v.Shield.Transparency = 0
			tween(v.Shield, 0.18, { Transparency = 0.15 })
		end
		if guarding[target] then
			VFX.Motion(target, guardMotion(target, data.Heavy and "BlockRecoilHeavy" or "BlockRecoil")) -- (arrives late if the guard already dropped)
		end
		VFX.PlaySound("Block", contact, 0.9)
		VFX.ShakeAt(contact, 0.4, 25, 0.1)
	end

	-- Perfect-timed guard. data.Target = who parried, data.Attacker = who got parried
	function Effects.Parry(_, data)
		local target = data.Target
		local root = target and target:FindFirstChild("HumanoidRootPart")
		if not root then
			return
		end
		local attacker = typeof(data.Attacker) == "Instance" and data.Attacker or nil
		local aroot = attacker and attacker:FindFirstChild("HumanoidRootPart")
		local toward = aroot and Vector3.new(aroot.Position.X - root.Position.X, 0, aroot.Position.Z - root.Position.Z) or Vector3.zero
		toward = toward.Magnitude > 0.1 and toward.Unit or root.CFrame.LookVector
		local contact = root.Position + toward * 2.2 + Vector3.new(0, 0.8, 0)
		local v = guardVisuals[target]
		if v and v.Shield.Parent then
			v.Shield.Transparency = 0
			tween(v.Shield, 0.25, { Transparency = 0.15 })
		end
		VFX.Motion(target, guardMotion(target, "Parry"))
		if attacker then
			VFX.Motion(attacker, "HeavyFlinch")
			afterimage(attacker, Color3.fromRGB(255, 230, 120), 0.35)
		end
		billboardRing(contact, 1, 14, Color3.new(1, 1, 1), 0, 0.14, true)
		billboardRing(contact, 2, 20, GOLD, 8, 0.3)
		shockDisc(contact, toward, 2, 16, 0.25, GOLD)
		sparks(contact, 1.2, Color3.new(1, 1, 1), GOLD, 40)
		streaks(contact, toward, 10, 1.2, 4, 12, Color3.new(1, 1, 1), 0.2)
		if nearCamera(contact, 45) then
			VFX.ImpactFrame(0.1)
		end
		VFX.PlaySound("Parry", contact, 1)
		VFX.ShakeAt(contact, 1.4, 50, 0.2)
	end

	-- The guard meter ran dry: the barrier shatters and the target is dazed
	function Effects.GuardBreak(_, data)
		local target = data.Target
		local root = target and target:FindFirstChild("HumanoidRootPart")
		if not root then
			return
		end
		local v = guardVisuals[target]
		local at = (v and v.Shield.Parent and v.Shield.Position) or (root.Position + root.CFrame.LookVector * 1.7)
		removeGuardVisual(target)
		for _ = 1, 16 do
			local shard = newPart(Vector3.new(rand(0.3, 0.9), rand(0.3, 1.2), 0.1), CFrame.new(at + rng:NextUnitVector() * rand(0.5, 2.5)) * CFrame.Angles(rand(0, 6), rand(0, 6), rand(0, 6)), GUARD_FULL, Enum.Material.Glass)
			shard.Transparency = 0.2
			shard.Anchored = false
			shard.AssemblyLinearVelocity = rng:NextUnitVector() * rand(10, 26) + Vector3.new(0, 14, 0)
			shard.AssemblyAngularVelocity = rng:NextUnitVector() * 12
			tween(shard, 0.4, { Transparency = 1 }, nil, nil, 0.6)
			cleanup(shard, 1.1)
		end
		billboardRing(at, 2, 18, GUARD_LOW, 8, 0.3)
		VFX.Motion(target, guardMotion(target, "GuardBreak"))
		-- dizzy stars circling the head for the length of the stun
		local head = target:FindFirstChild("Head")
		local duration = data.Duration or 1.6
		if head then
			local stars = {}
			for i = 1, 3 do
				stars[i] = newPart(Vector3.one * 0.45, head.CFrame, Color3.fromRGB(255, 226, 90), Enum.Material.Neon, Enum.PartType.Ball)
			end
			task.spawn(function()
				local t0 = os.clock()
				while os.clock() - t0 < duration and head.Parent do
					local t = os.clock() - t0
					for i, star in stars do
						local a = t * 7 + i * (math.pi * 2 / 3)
						star.CFrame = CFrame.new(head.Position + Vector3.new(math.cos(a) * 1.3, 1.1 + math.sin(t * 5 + i) * 0.15, math.sin(a) * 1.3))
					end
					task.wait()
				end
				for _, star in stars do
					star:Destroy()
				end
			end)
		end
		VFX.PlaySound("GuardBreak", at, 1)
		VFX.ShakeAt(at, 1.2, 45, 0.25)
	end

	-- Someone was knocked out. data.Target = the one who went down
	function Effects.KO(_, data)
		local target = data.Target
		local root = typeof(target) == "Instance" and target:FindFirstChild("HumanoidRootPart")
		local pos = typeof(data.Pos) == "Vector3" and data.Pos or (root and root.Position)
		if not pos then
			return
		end
		removeGuardVisual(target)
		-- (JJS: the body's left in a pool of it)
		if VFX.BLOOD then
			VFX.BLOOD.spray(pos + UP, UP, 12, 24, 0.9)
			task.delay(0.6, function()
				local r = typeof(target) == "Instance" and target:FindFirstChild("HumanoidRootPart")
				VFX.BLOOD.pool(r and r.Position or pos, 6)
			end)
		end
		billboardRing(pos, 2, 26, Color3.new(1, 1, 1), 0, 0.18, true)
		billboardRing(pos, 3, 34, Color3.fromRGB(255, 70, 60), 10, 0.4)
		shockDisc(pos, UP, 3, 30, 0.35, Color3.new(1, 1, 1))
		sparks(pos, 1.6, Color3.new(1, 1, 1), Color3.fromRGB(255, 80, 60), 50)
		VFX.PlaySound("KO", pos, 1)
		VFX.ShakeAt(pos, 2, 90, 0.35)
	end
end

