-- ONE FOR ALL: 9TH (Deku)
---------------------------------------------------------------------------

do -- Deku presentation: short motions, white pressure, mint edge, readable silhouettes.
local MINT = Color3.fromRGB(154, 245, 206)
local WHITE = Color3.fromRGB(246, 255, 252)
local TEAL = Color3.fromRGB(14, 57, 54)
local POWER = Color3.fromRGB(66, 239, 165)

local function active(char)
	local root, hum = charParts(char)
	return root and (not hum or hum.Health > 0) and not char:GetAttribute("Stunned") and not char:GetAttribute("Ragdolled") and not char:GetAttribute("Grabbed")
end

-- Thin tapered curves describe the force; they never obscure the fighters.
local function curveStroke(points, width, color, life, parent)
	local model = Instance.new("Model")
	model.Name = "CowlPressureArc"
	model.Parent = parent or folder
	for i = 1, #points - 1 do
		local a, b = points[i], points[i + 1]
		local delta = b - a
		if delta.Magnitude > 0.01 then
			local taper = math.sin(math.pi * (i - 0.5) / (#points - 1))
			local thick = math.max(0.025, width * taper)
			local seg = newPart(Vector3.new(thick, thick, delta.Magnitude + 0.03), CFrame.lookAt((a + b) / 2, b), color, Enum.Material.Neon, nil, model)
			seg.Transparency = 0.18
			tween(seg, life, { Transparency = 1, Size = Vector3.new(0.015, 0.015, seg.Size.Z) })
		end
	end
	cleanup(model, life + 0.04)
	return model
end

local function heelArc(root, d, radius, roll, color, parent)
	local basis = CFrame.lookAt(root.Position + UP * 0.15, root.Position + UP * 0.15 + d) * CFrame.Angles(0, 0, roll)
	local points = {}
	for i = 0, 14 do
		local angle = math.rad(-72 + 152 * i / 14)
		table.insert(points, basis:PointToWorldSpace(Vector3.new(math.sin(angle) * radius, math.cos(angle) * radius * 0.22, -math.cos(angle) * radius)))
	end
	curveStroke(points, 0.28, color, 0.18, parent)
end

local function briefTrail(part, duration, color, width, life)
	if not part then return function() end end
	local stop = addTrail(part, color, life or 0.12, width or 0.45)
	stop(duration)
	return stop
end

local function contact(pos, dir, strong)
	shockDisc(pos, dir, 0.6, strong and 10 or 5.5, strong and 0.2 or 0.14, WHITE)
	sparks(pos, strong and 0.44 or 0.23, WHITE, MINT, strong and 10 or 5)
	streaks(pos, dir, strong and 6 or 3, 0.4, strong and 3.5 or 2, strong and 7 or 4, WHITE, 0.15)
end

-- DELAWARE SMASH: AIR FORCE: side-on and low, flick after flick from
-- alternate hands, each one a bullet of compressed air - a rippling ball of
-- pressure shedding rings as it goes - the last one bigger, blowing them away
function Effects.DelawareSmash(char, data, isLocal, ability)
	local root = charParts(char)
	if not root then return end
	local d = aimDir(data, root)
	if isLocal then face(root, d) end
	local shots = (ability and ability.Shots) or 1
	local gap = (ability and ability.Gap) or 0.13
	local length = data.Air and 80 or ((ability and ability.Range) or 110)
	task.wait(0.07)
	for i = 1, shots do
		if not active(char) then return end
		local right = i % 2 == 1
		local last = i == shots
		VFX.Motion(char, right and "AirForceR" or "AirForceL")
		task.wait(0.05)
		local from = handPos(char, right) + d * 0.6
		local hit = firstHit(from, d, length)
		local to = hit or (from + d * length)
		local travel = math.max(0.03, (to - from).Magnitude / 420)
		local size = last and 2.6 or 1.7
		local ball = newPart(Vector3.one * size, CFrame.lookAt(from, from + d), WHITE, Enum.Material.ForceField, Enum.PartType.Ball)
		ball.Name = "DelawarePressure"
		ball.Transparency = 0.1
		local core = newPart(Vector3.one * size * 0.45, CFrame.new(from), WHITE, Enum.Material.Neon, Enum.PartType.Ball)
		core.Transparency = 0.35
		local stop = briefTrail(ball, travel, MINT, size * 0.5, 0.12)
		shockDisc(from, d, 0.5, last and 7 or 4.5, 0.14, WHITE)
		billboardRing(from, 0.6, last and 6 or 4, MINT, 3, 0.14)
		sparks(from, 0.3, WHITE, COWL_GREEN, 6)
		VFX.PlaySound("AirBullet", from, last and 1.4 or 1.1)
		if isLocal and data.Air then dash(root, -d * 10 + UP * 5, 0.06) end
		tween(ball, travel, { CFrame = CFrame.lookAt(to, to + d) }, Enum.EasingStyle.Linear)
		tween(core, travel, { CFrame = CFrame.new(to) }, Enum.EasingStyle.Linear)
		-- rings of pressure peeling off it as it goes
		for k = 1, math.min(6, math.floor((to - from).Magnitude / 12)) do
			task.delay(travel * k / 7, shockDisc, from:Lerp(to, k / 7), d, size * 0.8, size * 2.4, 0.18, WHITE)
		end
		cleanup(ball, travel + 0.1)
		cleanup(core, travel + 0.1)
		task.delay(travel, function()
			ball.Transparency = 1
			core.Transparency = 1
			stop(0)
			shockDisc(to, -d, 1, hit and (last and 16 or 9) or 5, 0.22, WHITE)
			if hit then
				billboardRing(to, 1, last and 18 or 10, WHITE, 5, 0.2)
			end
		end)
		if not last then
			task.wait(math.max(gap - 0.05, 0))
		end
	end
end

-- (the server's word that an air bullet landed)
function Effects.AirForceHit(_, data)
	local pos = typeof(data.Pos) == "Vector3" and data.Pos
	if not pos then return end
	local d = typeof(data.Dir) == "Vector3" and data.Dir or UP
	contact(pos, -d, data.Last == true)
	if data.Last then
		billboardRing(pos, 2, 24, WHITE, 7, 0.25)
		streaks(pos, d, 10, 0.4, 5, 16, WHITE, 0.25)
		VFX.PlaySound("DetroitImpact", pos, 0.8)
		VFX.ShakeAt(pos, 1.2, 60, 0.2)
	else
		VFX.PlaySound("Hit", pos, 0.8)
	end
end

function Effects.Blackwhip(char, data, isLocal, ability)
	local root = charParts(char)
	if not root then return end
	local d = aimDir(data, root)
	if isLocal then face(root, d) end
	VFX.Motion(char, "WhipCast")
	task.wait(0.12)
	if not active(char) then return end
	local from = handPos(char, true)
	local length = (ability and ability.Range) or 60
	local hit = firstHit(from, d, length)
	local reach = hit and (hit - from).Magnitude or length
	local t0 = os.clock()
	VFX.PlaySound("Blackwhip", from, 0.85)
	VFX.whipRope(function()
		return active(char) and handPos(char, true) or nil
	end, function()
		local t = os.clock() - t0
		local s = t < 0.12 and t / 0.12 or math.max(0, 1 - (t - 0.15) / 0.14)
		return from + d * reach * s
	end, 0.3, { Wave = 0.6, Grow = 0.015, Thick = 0.36, Segments = 16, Color = TEAL, OutlineColor = MINT })
end

function Effects.BlackwhipCatch(char, data)
	local target = typeof(data.Target) == "Instance" and data.Target
	local troot = target and target:FindFirstChild("HumanoidRootPart")
	if not char or not troot then return end
	local duration = data.Duration or 0.32
	VFX.Pose(char, "WhipCast", duration)
	VFX.whipRope(function()
		return active(char) and handPos(char, true) or nil
	end, function()
		return troot.Parent and troot.Position + UP * 0.35 or nil
	end, duration, { Wave = 0.35, Grow = 0.025, Thick = 0.25, Segments = 14, Color = TEAL, OutlineColor = MINT })
	local delta = char:GetPivot().Position - troot.Position
	contact(troot.Position + UP * 0.4, delta.Magnitude > 0.01 and delta.Unit or UP, false)
	VFX.PlaySound("Hit", troot.Position, 0.55)
end

-- Deku's R: the next quirk into his 4th slot (a crackle in its colour)
local PICK_COLORS = { Blackwhip = Color3.fromRGB(20, 30, 24), Smokescreen = SMOKE_GREY, Float = Color3.new(1, 1, 1), FaJinSmash = Color3.fromRGB(255, 70, 60), Gearshift = Color3.fromRGB(140, 255, 214) }
function Effects.QuirkCycle(char)
	local root = charParts(char)
	if not root then return end
	local quirk = Config.Quirks[char:GetAttribute("Quirk") or ""]
	local owner = Players:GetPlayerFromCharacter(char)
	local picked = quirk and owner and Config.PickedExtra(quirk, owner:GetAttribute("QuirkPick"))
	local color = picked and PICK_COLORS[picked.Id] or MINT
	VFX.Pose(char, "CycleFist", 0.3) -- (a fist clenched: the next quirk answering)
	sparks(handPos(char, true), 0.22, WHITE, color, 6)
	VFX.PlaySound("Spark", root.Position, 0.5)
end

function Effects.Smokescreen(char, _data, isLocal, ability)
	local root = charParts(char)
	if not root then
		return
	end
	local radius = (ability and ability.Radius) or 24
	local duration = (ability and ability.Duration) or 5
	local pos = root.Position
	VFX.Pose(char, "Clap", 0.3)
	smokeBurst(pos, SMOKE_GREY, 14, radius, duration, 70)
	smokeBurst(pos + UP * 4, SMOKE_DEEP, 10, radius * 0.8, duration * 0.8, 40)
	for i = 1, 12 do
		local a = i / 12 * math.pi * 2
		local out = Vector3.new(math.cos(a), 0, math.sin(a))
		celPuff(folder, pos, pos + out * radius * rand(0.5, 0.9) + UP * rand(1, 6), rand(6, 10), SMOKE_DEEP, Color3.fromRGB(196, 160, 236), 0.25, 1.4, i * 0.01)
	end
	if not isLocal then
		afterimage(char, SMOKE_GREY, 0.3)
		hideCharacter(char, 0.8) -- he vanishes into it
	end
	VFX.PlaySound("Smokescreen", pos, 1)
end

-- Server: you're choking in a smokescreen
function Effects.Smoked(_, data)
	VFX.Hooks.Flash(SMOKE_GREY, data.Duration or 2)
	VFX.Hooks.Dim(0.5, data.Duration or 2)
end

-- ST. LOUIS SMASH: AIR FORCE: he coils, spins right round on one foot and
-- the kick comes round the front - and out of it flies a blade of
-- compressed air, a white crescent skimming down the street, tearing it up
function Effects.StLouisSmash(char, data, isLocal, ability)
	local root = charParts(char)
	if not root then return end
	local a = Config.AimedDirection(data.Dir, root.CFrame.LookVector, ability and ability.Aim)
	local d = flatten(a, root)
	if isLocal then
		face(root, d)
		dash(root, d * 30, 0.16)
	end
	VFX.Motion(char, "StLouis")
	local foot = limb(char, "RightFoot", "Right Leg")
	briefTrail(foot, 0.36, MINT, 0.7, 0.14)
	briefTrail(foot, 0.36, WHITE, 0.3, 0.1)
	VFX.PlaySound("Swish", root.Position, 1)
	task.wait(0.18)
	if not active(char) then return end
	shockDisc(root.Position - UP * 1.5, UP, 3, 16, 0.25, WHITE)
	heelArc(root, d, 5.2, math.rad(13), WHITE)
	heelArc(root, d, 4.8, math.rad(13), MINT)
	VFX.PlaySound("Kick", root.Position + d * 3, 1.1)
	local range = (ability and ability.Range) or 45
	if range <= 16 then return end
	local width = (ability and ability.BladeWidth) or 16
	local from = root.Position + d * 3
	local right = d:Cross(UP).Unit
	local blade = {}
	for k = -5, 5 do
		local f = k / 5
		local seg = newPart(Vector3.new(0.35, 0.4 + (1 - math.abs(f)) * 0.9, width / 10 + 0.4), CFrame.new(from), k % 2 == 0 and WHITE or MINT, Enum.Material.Neon)
		seg.Transparency = 0.1
		table.insert(blade, { part = seg, f = f })
	end
	local travel = range / 150
	local t0 = os.clock()
	VFX.PlaySound("Wind", from, 1)
	local conn
	conn = RunService.RenderStepped:Connect(function()
		local u = math.clamp((os.clock() - t0) / travel, 0, 1)
		local center = from + a * range * u
		for _, e in blade do
			-- (the crescent bows forward in the middle)
			local p = center + right * e.f * width * 0.5 + d * (1 - e.f * e.f) * width * 0.25
			e.part.CFrame = CFrame.lookAt(p, p + right)
			e.part.Transparency = 0.1 + 0.8 * u ^ 3
		end
		if u >= 1 then
			conn:Disconnect()
			for _, e in blade do
				e.part:Destroy()
			end
		end
	end)
	for k = 1, 6 do
		task.delay(travel * k / 6, function()
			local p = from + a * range * k / 6
			local g = groundPoint(p)
			if (g - p).Magnitude < 8 then
				dustPuffs(g, 0.5, 2, Color3.fromRGB(206, 200, 190), 0.5, false)
				groundMark(g, 1.5, Color3.fromRGB(70, 66, 60), 2)
			end
			streaks(p, a, 3, 0.3, 4, 8, WHITE, 0.15)
		end)
	end
end

function Effects.CowlKickHit(_, data)
	local pos = typeof(data.Pos) == "Vector3" and data.Pos
	if not pos then return end
	local d = typeof(data.Dir) == "Vector3" and data.Dir.Magnitude > 0.01 and data.Dir.Unit or UP
	contact(pos, d, true)
	VFX.PlaySound("Hit", pos, 0.8)
	VFX.ShakeAt(pos, 0.65, 35, 0.12)
end

function Effects.ManchesterSmash(char, data, isLocal, ability)
	local root = charParts(char)
	if not root then return end
	local travel = (ability and ability.TravelTime) or 0.46
	local height = (ability and ability.Height) or 16
	local target = aimGround(root, data, (ability and ability.Range) or 38)
	local d = flatten(target - root.Position, root)
	local from = root.Position
	VFX.Motion(char, "Manchester")
	local g = groundPoint(from)
	shockDisc(g + UP * 0.2, UP, 2, 12, 0.3, WHITE)
	dustPuffs(g, 0.7, 4, Color3.fromRGB(200, 200, 192), 0.55, false)
	VFX.PlaySound("Leap", g, 0.9)
	local stops = {}
	for _, name in { { "RightFoot", "Right Leg" }, { "LeftFoot", "Left Leg" } } do
		table.insert(stops, briefTrail(limb(char, name[1], name[2]), travel, WHITE, 0.65, 0.16))
	end
	-- the somersault's wind wheeling round him
	for k = 1, 3 do
		task.delay(travel * (0.15 + k * 0.15), function()
			if active(char) then heelArc(root, d, 3.2, math.rad(90), k % 2 == 0 and WHITE or MINT) end
		end)
	end
	task.delay(travel * 0.72, function()
		if active(char) then
			heelArc(root, d, 4.2, math.rad(90), WHITE)
			VFX.PlaySound("Swish", root.Position, 1)
		end
	end)
	if isLocal then
		face(root, d)
		local ring = shockDisc(target + UP * 0.08, UP, 24, 24, travel, MINT)
		ring.Transparency = 0.78
		flyArc(root, from, target, height, travel)
		if ring.Parent then ring:Destroy() end
	else
		task.wait(travel)
	end
	for _, stop in stops do
		stop(0)
	end
end

-- the axe kick lands: a crater, the street heaving up round it, and a
-- shockwave rolling out past it
function Effects.ManchesterLand(_, data)
	local pos = typeof(data.Pos) == "Vector3" and data.Pos
	if not pos then return end
	local R = tonumber(data.Radius) or 12
	local S = tonumber(data.Shock) or R * 1.8
	shockDisc(pos + UP * 0.18, UP, 2, R * 2.4, 0.3, WHITE)
	shockDisc(pos + UP * 0.25, UP, 1, R * 1.6, 0.22, MINT)
	shockDisc(pos + UP * 0.3, UP, R, S * 2.2, 0.45, WHITE)
	billboardRing(pos + UP, 3, R * 2.6, WHITE, 8, 0.3)
	streaks(pos + UP * 2.5, -UP, 6, 0.4, 3, 5, WHITE, 0.16)
	for i = 1, 10 do
		local ang = i / 10 * math.pi * 2 + rand(-0.2, 0.2)
		local out = Vector3.new(math.cos(ang), 0, math.sin(ang))
		local at = pos + out * R * rand(0.7, 0.95) + UP * 0.4
		local slab = newPart(Vector3.new(rand(3, 5), rand(0.8, 1.4), rand(3, 5)), CFrame.lookAt(at, at + out) * CFrame.Angles(math.rad(rand(25, 45)), 0, 0), Color3.fromRGB(96, 96, 100), Enum.Material.Slate)
		tween(slab, 0.5, { Transparency = 1 }, nil, nil, 2.2)
		cleanup(slab, 2.8)
	end
	dustPuffs(pos, 1.4, 8, Color3.fromRGB(202, 202, 191), 1, true)
	rocks(pos, 1.3, 10)
	groundMark(pos, R * 0.6, Color3.fromRGB(61, 66, 61), 4)
	sparks(pos + UP * 0.8, 0.8, WHITE, MINT, 18)
	VFX.PlaySound("Smash", pos, 1.3)
	VFX.PlaySound("Downslam", pos, 0.9)
	VFX.ShakeAt(pos, 2.2, 90, 0.3)
end

-- FA JIN (Deku's 4th, tap 4 to start, tap 4 again to let go - or it goes by
-- itself at full). The third user's quirk stores the kinetic energy of a
-- repeated motion, glowing red: he squats - down, up, down, up - each one
-- quicker than the last, and the energy burns up his legs as red veins from
-- the feet to the hips, a ring of dust kicked off the street at the bottom
-- of every squat. Then it all goes out through his legs at once: the street
-- bursts under him, he rockets forward and it ends in one straight Detroit
-- Smash - a gale that scours the street, bigger the longer he stored it
do
	local FJ = {
		charging = setmetatable({}, { __mode = "k" }), -- [char] = token while he charges
		GOLD = Color3.fromRGB(255, 184, 70),
		DEEP = Color3.fromRGB(255, 118, 36),
		PALE = Color3.fromRGB(255, 244, 214),
		DUST = Color3.fromRGB(206, 200, 188),
		RED = Color3.fromRGB(255, 38, 38),
		BURN = Color3.fromRGB(255, 84, 60),
		HOT = Color3.fromRGB(255, 170, 140),
	}
	-- the squats: down (hips sunk, legs forward, body over his knees, arms
	-- out for balance) and up again, over `period` seconds - FaJinSquat1 is
	-- the first slow one, FaJinSquat8 the fastest (FJ.period gives the tempo)
	function FJ.period(k)
		return 0.52 - 0.41 * math.clamp(k, 0, 1) ^ 0.8
	end
	for i = 1, 8 do
		local p = FJ.period((i - 1) / 7)
		MOTIONS["FaJinSquat" .. i] = {
			mute = 0.3,
			{ pose = { Hips = { 0, 0, 0, 0, -1.55, -0.2 }, Crouch = 1.35, Waist = { -24, 0, 0 }, Neck = { 16, 0, 0 }, RightArm = { 86, 0, 6 }, LeftArm = { 86, 0, 6 }, RightElbow = 10, LeftElbow = 10, RightLeg = 71, LeftLeg = 71, RightKnee = 112, LeftKnee = 112 }, t = p * 0.45, style = Enum.EasingStyle.Sine },
			{ pose = { Hips = { 0, 0, 0, 0, -0.15, 0 }, Crouch = 0.1, Waist = { -4, 0, 0 }, Neck = { 2, 0, 0 }, RightArm = { 36, 0, 12 }, LeftArm = { 36, 0, 12 }, RightElbow = 96, LeftElbow = 96, RightLeg = 10, LeftLeg = 10, RightKnee = 10, LeftKnee = 10 }, t = p * 0.55, style = Enum.EasingStyle.Sine },
			recover = 0.2,
		}
	end
	-- the launch: low and flat out behind the fist, then the punch
	MOTIONS.FaJinLaunch = {
		{ pose = { Hips = { -30, 10, 0, 0, -0.6, -0.4 }, Crouch = 0.8, Waist = { -24, 18, 0 }, Neck = { 24, -14, 0 }, RightArm = { -46, 0, 18 }, RightElbow = 100, LeftArm = { 70, 0, 0 }, LeftElbow = 20, LeftLeg = 40, LeftKnee = 70, RightLeg = -44, RightKnee = 20 }, t = 0.06, hold = 0.18, style = SNAP },
		recover = 0.2,
	}
	MOTIONS.FaJinRelease = {
		{ pose = { Hips = { -12, 26, 0, 0, -0.5, -1.1 }, Waist = { -16, 34, 0 }, Neck = { -6, -40, 0 }, RightArm = { 96, 0, -4 }, RightElbow = 0, RightWrist = { -8, 0, 0 }, LeftArm = { -38, 0, 30 }, LeftElbow = 55, LeftLeg = 50, LeftKnee = 52, RightLeg = -38, RightKnee = 6 }, t = 0.035, hold = 0.55, style = SNAP },
		recover = 0.32,
	}

	-- the veins: jagged red lines over a limb's surface, from the end of it
	-- (a foot) up to where it joins the body (the hip), with short branches
	-- off them. names: the R15 pieces from the end up, then the R6 limb.
	-- v.update(k) shows as much of them as the charge has reached (k 0 -> 1);
	-- v.finish() flashes them and lets them go.
	function FJ.veins(char, names)
		local parts = {}
		for i = 1, #names - 1 do
			local p = char:FindFirstChild(names[i])
			if p then
				table.insert(parts, p)
			end
		end
		if #parts == 0 then
			parts = { char:FindFirstChild(names[#names]) }
		end
		if not parts[1] then
			return nil
		end
		local total = 0
		for _, p in parts do
			total += p.Size.Y
		end
		-- u runs 0 (the fist) to 1 (the shoulder); a face and a spot across it
		local function spot(u, side, w)
			local y = u * total
			for i, p in parts do
				if y <= p.Size.Y or i == #parts then
					local s = p.Size
					local ly = math.clamp(-s.Y / 2 + y, -s.Y / 2, s.Y / 2)
					local off
					if side == 1 then
						off = Vector3.new(w * s.X * 0.42, ly, -s.Z / 2 - 0.03)
					elseif side == 2 then
						off = Vector3.new(s.X / 2 + 0.03, ly, w * s.Z * 0.42)
					elseif side == 3 then
						off = Vector3.new(w * s.X * 0.42, ly, s.Z / 2 + 0.03)
					else
						off = Vector3.new(-s.X / 2 - 0.03, ly, w * s.Z * 0.42)
					end
					return { part = p, off = off, u = u, w = w }
				end
				y -= p.Size.Y
			end
		end
		local seeded = Random.new(9)
		local segs = {}
		local function line(points, thick)
			for i = 1, #points - 1 do
				local part = newPart(Vector3.new(thick, thick, 0.2), CFrame.new(), FJ.RED, Enum.Material.Neon)
				part.Name = "Vein"
				part.Transparency = 1
				table.insert(segs, { a = points[i], b = points[i + 1], part = part, thick = thick })
			end
		end
		for v = 1, 8 do
			local side = (v - 1) % 4 + 1
			local w = seeded:NextNumber(-0.5, 0.5)
			local u = seeded:NextNumber(0, 0.06)
			local points = {}
			while u < 1 do
				table.insert(points, spot(u, side, w))
				u += seeded:NextNumber(0.09, 0.15)
				w = math.clamp(w + seeded:NextNumber(-0.28, 0.28), -0.9, 0.9)
			end
			table.insert(points, spot(1, side, w))
			line(points, v <= 4 and 0.11 or 0.075)
			-- a couple of short branches off it
			for _ = 1, 2 do
				local from = points[seeded:NextInteger(2, math.max(#points - 2, 2))]
				if from then
					local bw = from.w
					local branch = { from }
					local bu, dir = from.u, seeded:NextNumber() < 0.5 and -1 or 1
					for _ = 1, 2 do
						bu = math.min(bu + seeded:NextNumber(0.05, 0.08), 1)
						bw = math.clamp(bw + dir * seeded:NextNumber(0.25, 0.4), -0.95, 0.95)
						table.insert(branch, spot(bu, side, bw))
					end
					line(branch, 0.055)
				end
			end
		end
		local vs = { segs = segs, k = 0 }
		function vs.update(k)
			vs.k = k
			local reach = k * 1.04
			local burn = k >= 1
			for _, sg in segs do
				local a, b = sg.a, sg.b
				if not (a.part.Parent and b.part.Parent) or a.u >= reach then
					sg.part.Transparency = 1
				else
					local pa = a.part.CFrame:PointToWorldSpace(a.off)
					local pb = b.part.CFrame:PointToWorldSpace(b.off)
					if b.u > reach then
						pb = pa:Lerp(pb, (reach - a.u) / math.max(b.u - a.u, 1e-3))
					end
					local len = (pb - pa).Magnitude
					if len < 0.02 then
						sg.part.Transparency = 1
					else
						local t = sg.thick * (burn and 1.35 or 1)
						sg.part.Size = Vector3.new(t, t, len + t)
						sg.part.CFrame = CFrame.lookAt((pa + pb) / 2, pb, a.part.CFrame.LookVector)
						-- (it throbs, harder the fuller it gets)
						sg.part.Transparency = rng:NextNumber() * (0.1 + 0.25 * k)
						sg.part.Color = burn and FJ.BURN or FJ.RED
					end
				end
			end
		end
		function vs.finish()
			for _, sg in segs do
				if sg.part.Transparency < 1 then
					sg.part.Color = FJ.HOT
					tween(sg.part, 0.3, { Transparency = 1 })
				end
				cleanup(sg.part, 0.35)
			end
		end
		return vs
	end

	-- ONE FOR ALL AT 100% (the way he had to use it before Full Cowl): the
	-- whole of it through one arm - and the arm can't take it. While
	-- BrokenArmR / BrokenArmL on a character is ahead of the server clock,
	-- that arm is dressed in the bruise: black-purple and swollen at the
	-- hand, purple up the forearm, red-purple at the shoulder, split with
	-- dark cracks and burst veins. It fades as it heals.
	FJ.PURPLE = { Color3.fromRGB(56, 24, 68), Color3.fromRGB(102, 46, 122), Color3.fromRGB(150, 70, 110) } -- hand, forearm, upper arm
	FJ.CRACK = Color3.fromRGB(30, 10, 36)
	FJ.bruises = setmetatable({}, { __mode = "k" }) -- [char] = { R = rec?, L = rec? }
	function FJ.bruiseOn(char, side)
		local holder = Instance.new("Folder")
		holder.Name = "OFABruise" .. side
		holder.Parent = char
		local rec = { holder = holder, parts = {} }
		local seeded = Random.new(side == "R" and 7 or 11)
		-- one band of it round a limb: `from`..`to` along it (0 = the hand end)
		local function band(limb, from, to, color, swell, alpha)
			local s = limb.Size
			local h = s.Y * (to - from)
			local cf = limb.CFrame * CFrame.new(0, -s.Y / 2 + s.Y * (from + to) / 2, 0)
			local p = newPart(Vector3.new(s.X * swell, h, s.Z * swell), cf, color, Enum.Material.SmoothPlastic, nil, holder)
			p.Transparency = alpha or 0
			table.insert(rec.parts, { part = p, alpha = alpha or 0 })
			-- cracks and burst veins across its faces
			for _ = 1, math.max(2, math.floor(h * 3)) do
				local face = seeded:NextInteger(1, 4)
				local y = seeded:NextNumber(-h / 2 + 0.1, h / 2 - 0.1)
				local w = seeded:NextNumber(-0.35, 0.35)
				local len = seeded:NextNumber(0.25, 0.55)
				local x, z, rot
				if face == 1 then
					x, z, rot = w * s.X * swell, -s.Z * swell / 2 - 0.02, CFrame.Angles(0, 0, seeded:NextNumber(-1, 1))
				elseif face == 2 then
					x, z, rot = s.X * swell / 2 + 0.02, w * s.Z * swell, CFrame.Angles(seeded:NextNumber(-1, 1), 0, 0)
				elseif face == 3 then
					x, z, rot = w * s.X * swell, s.Z * swell / 2 + 0.02, CFrame.Angles(0, 0, seeded:NextNumber(-1, 1))
				else
					x, z, rot = -s.X * swell / 2 - 0.02, w * s.Z * swell, CFrame.Angles(seeded:NextNumber(-1, 1), 0, 0)
				end
				local red = seeded:NextNumber() < 0.3
				local c = newPart(Vector3.new(0.05, len, 0.05), cf * CFrame.new(x, y, z) * rot, red and Color3.fromRGB(150, 24, 44) or FJ.CRACK, Enum.Material.SmoothPlastic, nil, holder)
				table.insert(rec.parts, { part = c, alpha = 0 })
			end
			return p
		end
		local r6 = char:FindFirstChild(side == "R" and "Right Arm" or "Left Arm")
		if r6 then
			band(r6, 0, 0.28, FJ.PURPLE[1], 1.12)
			band(r6, 0.28, 0.62, FJ.PURPLE[2], 1.07)
			band(r6, 0.62, 1, FJ.PURPLE[3], 1.04, 0.2)
		else
			local pre = side == "R" and "Right" or "Left"
			for i, n in { pre .. "Hand", pre .. "LowerArm", pre .. "UpperArm" } do
				local limb = char:FindFirstChild(n)
				if limb then
					band(limb, 0, 1, FJ.PURPLE[i], ({ 1.14, 1.08, 1.05 })[i], i == 3 and 0.2 or 0)
				end
			end
		end
		-- welded on: they move with the arm
		for _, e in rec.parts do
			local limb = r6
			if not limb then
				local best, bestD
				for _, n in { "Hand", "LowerArm", "UpperArm" } do
					local l = char:FindFirstChild((side == "R" and "Right" or "Left") .. n)
					if l then
						local dd = (l.CFrame.Position - e.part.CFrame.Position).Magnitude
						if not bestD or dd < bestD then
							best, bestD = l, dd
						end
					end
				end
				limb = best
			end
			if limb then
				local w = Instance.new("WeldConstraint")
				w.Part0 = limb
				w.Part1 = e.part
				w.Parent = e.part
				e.part.Massless = true
				e.part.Anchored = false
			end
		end
		return rec
	end
	function FJ.bruiseOff(rec)
		for _, e in rec.parts do
			tween(e.part, 1, { Transparency = 1 })
		end
		cleanup(rec.holder, 1.05)
	end
	FJ.bruiseClock = 0
	RunService.RenderStepped:Connect(function(dt)
		FJ.bruiseClock += dt
		if FJ.bruiseClock < 0.25 then
			return
		end
		FJ.bruiseClock = 0
		local now = workspace:GetServerTimeNow()
		for _, plr in Players:GetPlayers() do
			local char = plr.Character
			if char then
				local recs = FJ.bruises[char] or {}
				for _, side in { "R", "L" } do
					local untilT = tonumber(char:GetAttribute("BrokenArm" .. side))
					local broken = untilT ~= nil and untilT > now
					if broken and not recs[side] and char:FindFirstChild("HumanoidRootPart") then
						recs[side] = FJ.bruiseOn(char, side)
						FJ.bruises[char] = recs
					elseif broken and VFX.BLOOD and (Config.BrokenArms or {}).Drip ~= false and rng:NextNumber() < 0.2 and char:FindFirstChild("HumanoidRootPart") and nearCamera(char.HumanoidRootPart.Position, 150) then
						local arm = char:FindFirstChild(side == "R" and "Right Arm" or "Left Arm") or char:FindFirstChild(side == "R" and "RightHand" or "LeftHand")
						if arm then
							VFX.BLOOD.drip(arm, (arm.CFrame * CFrame.new(0, -arm.Size.Y / 2, 0)).Position, 1)
						end
					elseif not broken and recs[side] then
						FJ.bruiseOff(recs[side])
						recs[side] = nil
					end
				end
			end
		end
	end)

	-- 100%: DETROIT SMASH. The wind-up: the power gathers in one arm - red
	-- veins up it, red and green lightning off the fist...
	POSES.HundredWindR = { RightArm = { -70, 0, 30 }, RightElbow = 100, LeftArm = { 70, 0, 10 }, LeftElbow = 30, Waist = { 6, 40, 0 }, Neck = { 0, -30, 0 }, RightLeg = -20, LeftLeg = 40, LeftKnee = 50, RightKnee = 20, Crouch = 0.5 }
	POSES.HundredWindL = { LeftArm = { -70, 0, 30 }, LeftElbow = 100, RightArm = { 70, 0, 10 }, RightElbow = 30, Waist = { 6, -40, 0 }, Neck = { 0, 30, 0 }, LeftLeg = -20, RightLeg = 40, RightKnee = 50, LeftKnee = 20, Crouch = 0.5 }
	POSES.HundredPunchR = { RightArm = { 96, 0, 0 }, RightElbow = 0, LeftArm = { -40, 0, 30 }, LeftElbow = 40, Waist = { 14, -34, 0 }, Neck = { -8, 26, 0 }, RightLeg = -30, LeftLeg = 44, LeftKnee = 30, RightKnee = 10, Crouch = 0.45 }
	POSES.HundredPunchL = { LeftArm = { 96, 0, 0 }, LeftElbow = 0, RightArm = { -40, 0, 30 }, RightElbow = 40, Waist = { 14, 34, 0 }, Neck = { -8, -26, 0 }, LeftLeg = -30, RightLeg = 44, RightKnee = 30, LeftKnee = 10, Crouch = 0.45 }
	-- (after: the broken arm hangs, the other one holds it)
	POSES.HundredHurtR = { RightArm = { 10, 0, 8 }, RightElbow = 10, LeftArm = { 40, 34, 0 }, LeftElbow = 90, Waist = { 16, 10, 0 }, Neck = { 14, -12, 0 }, RightKnee = 16, LeftKnee = 22, Crouch = 0.3 }
	POSES.HundredHurtL = { LeftArm = { 10, 0, 8 }, LeftElbow = 10, RightArm = { 40, 34, 0 }, RightElbow = 90, Waist = { 16, -10, 0 }, Neck = { 14, 12, 0 }, RightKnee = 22, LeftKnee = 16, Crouch = 0.3 }
	MOTIONS.HundredWindR = { { pose = "HundredWindR", t = 0.2, hold = 0.45 }, recover = 0.3 }
	MOTIONS.HundredWindL = { { pose = "HundredWindL", t = 0.2, hold = 0.45 }, recover = 0.3 }
	MOTIONS.HundredPunchR = { { pose = "HundredPunchR", t = 0.05, hold = 0.35, style = SNAP }, { pose = "HundredHurtR", t = 0.25, hold = 0.35 }, recover = 0.4 }
	MOTIONS.HundredPunchL = { { pose = "HundredPunchL", t = 0.05, hold = 0.35, style = SNAP }, { pose = "HundredHurtL", t = 0.25, hold = 0.35 }, recover = 0.4 }
	function FJ.whichArm(char)
		local now = workspace:GetServerTimeNow()
		local rB = (tonumber(char:GetAttribute("BrokenArmR")) or 0) > now
		local lB = (tonumber(char:GetAttribute("BrokenArmL")) or 0) > now
		return not rB or lB
	end
	function Effects.HundredSmash(char, data, isLocal, ability)
		local root = charParts(char)
		if not root then
			return
		end
		local d = flatten(data.Dir, root)
		if isLocal then
			face(root, d)
		end
		local right = FJ.whichArm(char)
		local startup = (ability and ability.Startup) or 0.55
		VFX.MuteGait(char, startup + 0.9)
		VFX.Motion(char, right and "HundredWindR" or "HundredWindL")
		local vs = FJ.veins(char, right and { "RightHand", "RightLowerArm", "RightUpperArm", "Right Arm" } or { "LeftHand", "LeftLowerArm", "LeftUpperArm", "Left Arm" })
		local t0 = os.clock()
		local conn
		conn = RunService.RenderStepped:Connect(function()
			local k = math.clamp((os.clock() - t0) / (startup * 0.9), 0, 1)
			if vs then
				vs.update(k)
			end
			if os.clock() - t0 > startup + 0.08 or not char.Parent then
				conn:Disconnect()
				if vs then
					vs.finish()
				end
			end
		end)
		task.spawn(function()
			while os.clock() - t0 < startup and char.Parent do
				local hand = handPos(char, right)
				bolt(hand + rng:NextUnitVector() * 0.4, 1.3, rng:NextNumber() < 0.55 and FJ.RED or COWL_GREEN)
				task.wait(0.04)
			end
		end)
		sparks(handPos(char, right), 0.6, FJ.HOT, FJ.RED, 8)
		VFX.PlaySound("CowlCharge", root.Position, 1)
		if Players.LocalPlayer and Players.LocalPlayer.Character == char then
			VFX.Hooks.Callout("ONE FOR ALL... 100%!!", FJ.RED)
		end
	end
	-- ...and the punch: a gale that blows the street away - and the crack of
	-- the arm going with it
	function Effects.HundredSmashBlast(char, data)
		local root = charParts(char)
		if not root then
			return
		end
		local d = flatten(data.Dir, root)
		local right = data.Side ~= "L"
		local range, width = tonumber(data.Range) or 100, tonumber(data.Width) or 26
		VFX.Motion(char, right and "HundredPunchR" or "HundredPunchL")
		local fist = handPos(char, right) + d
		windBlast(fist, d, 2.4)
		for k = 1, 9 do
			task.delay(k * 0.035, shockDisc, fist + d * (range * k / 9), d, width * 0.3, width * 1.15, 0.35, WHITE, 6)
		end
		billboardRing(fist, 2, 40, WHITE, 8, 0.3)
		billboardRing(fist, 2, 26, FJ.RED, 6, 0.25)
		streaks(fist, d, 22, 0.5, 14, range * 0.6, WHITE, 0.45)
		for k = 1, 6 do
			task.delay(k * 0.05, dustPuffs, groundPoint(fist + d * (range * k / 7)), 1.4, 4, FJ.DUST, 1, true)
		end
		VFX.PlaySound("HundredSmash", fist, 1.3)
		VFX.ShakeAt(fist, 3, 220, 0.5)
		if nearCamera(fist, 80) then
			VFX.ImpactFrame(0.1)
		end
		if Players.LocalPlayer and Players.LocalPlayer.Character == char then
			VFX.Hooks.Callout("DETROIT SMASH!!", Color3.fromRGB(255, 240, 150))
		end
		task.delay(0.14, function()
			if not root.Parent then
				return
			end
			-- (round 75) the arm holds now: steam off it, the green crackling out
			local hand = handPos(char, right)
			dustPuffs(hand, 0.5, 3, Color3.fromRGB(235, 240, 238), 0.7, false)
			sparks(hand, 0.7, COWL_CORE, COWL_GREEN, 10)
			bolt(hand, 1.6, COWL_GREEN)
			billboardRing(hand, 0.4, 5, COWL_GREEN, 3, 0.2)
		end)
	end

	function Effects.FaJinSmash(char, data, isLocal, ability)
		local root = charParts(char)
		if not root then
			return
		end
		ability = ability or Config.FindAbilityById("FaJinSmash") or {}
		local spec = ability.Hold or {}
		local max = spec.Max or 2.4
		local token = {}
		FJ.charging[char] = token
		if isLocal then
			face(root, flatten(data.Dir, root))
			VFX.Hooks.Dim(0.18, max)
		end
		VFX.PlaySound("DetroitCharge", root.Position, 0.6)
		local glow = Instance.new("PointLight")
		glow.Color = FJ.RED
		glow.Range = 6
		glow.Brightness = 0.4
		glow.Parent = root
		local legs = {}
		for _, names in { { "RightFoot", "RightLowerLeg", "RightUpperLeg", "Right Leg" }, { "LeftFoot", "LeftLowerLeg", "LeftUpperLeg", "Left Leg" } } do
			table.insert(legs, FJ.veins(char, names))
		end
		local k = 0
		local conn = RunService.RenderStepped:Connect(function()
			for _, v in legs do
				v.update(k)
			end
		end)
		local t0 = os.clock()
		local level, nextSquat = 1, 0
		while FJ.charging[char] == token and root.Parent and os.clock() - t0 < max + 0.6 do
			local now = os.clock() - t0
			k = math.clamp(now / max, 0, 1)
			local reached = 1
			for i, t in spec.Levels or {} do
				if now >= t then
					reached = i + 1
				end
			end
			local g = groundPoint(root.Position)
			if reached > level then
				-- a new level: the legs flare, the street cracks under him
				level = reached
				billboardRing(g + UP * 1.5, 2, 8 + level * 6, level >= 3 and Color3.new(1, 1, 1) or FJ.RED, 6, 0.3)
				sparks(g + UP * 1, 0.4 * level, FJ.HOT, FJ.RED, 10 * level)
				groundMark(g, 2 + level, Color3.fromRGB(70, 40, 36), 3)
				VFX.PlaySound("DetroitCharge", root.Position, 0.6 + 0.25 * level)
				if level >= 3 then
					rocks(g, 0.9, 6)
					VFX.PlaySound("Spark", root.Position, 1)
				end
				if isLocal then
					VFX.Shake(0.25 * level, 0.22)
				end
			end
			-- the squats: each one quicker than the one before
			if os.clock() >= nextSquat then
				local period = FJ.period(k)
				VFX.Motion(char, "FaJinSquat" .. math.clamp(math.floor(k * 7 + 0.5) + 1, 1, 8))
				nextSquat = os.clock() + period
				task.delay(period * 0.45, FJ.thump, char, k, isLocal)
			end
			glow.Brightness = 0.4 + 3.2 * k
			glow.Range = 6 + 12 * k
			-- red crackling off his legs, more as it builds
			if rng:NextNumber() < 0.12 + 0.4 * k then
				bolt(g + Vector3.new(rand(-1.2, 1.2), rand(0.5, 3), rand(-1.2, 1.2)), 0.9 + 1.2 * k, FJ.RED)
			end
			task.wait(0.03)
		end
		conn:Disconnect()
		for _, v in legs do
			v.finish()
		end
		glow:Destroy()
		if FJ.charging[char] == token then
			FJ.charging[char] = nil
		end
	end

	-- the bottom of a squat: dust kicked out of the street, a red ring round
	-- his feet, a thump - bigger the more he's stored
	function FJ.thump(char, k, isLocal)
		local root = char and char:FindFirstChild("HumanoidRootPart")
		if not root or not FJ.charging[char] then
			return
		end
		local g = groundPoint(root.Position)
		shockDisc(g + UP * 0.25, UP, 3, 8 + 14 * k, 0.3, k > 0.66 and FJ.RED or FJ.DUST)
		billboardRing(g + UP * 0.8, 2, 6 + 8 * k, FJ.RED, 3 + 3 * k, 0.22)
		if k > 0.3 then
			dustPuffs(g, 0.35 + 0.5 * k, 2 + math.floor(3 * k), FJ.DUST, 0.6, false)
		end
		VFX.PlaySound("FaJinSwing", root.Position, 0.35 + 0.45 * k)
		if isLocal and k > 0.5 then
			VFX.Shake(0.12 + 0.25 * k, 0.12)
		end
	end

	-- ...and the second tap: everything he stored goes out through his legs -
	-- the street bursts under him, he rockets forward - and into one punch
	function Effects.FaJinSmashRelease(char, data, isLocal, ability)
		local root = charParts(char)
		if not root then
			return
		end
		FJ.charging[char] = nil
		ability = ability or Config.FindAbilityById("FaJinSmash") or {}
		local level = math.clamp(tonumber(data.Level) or 1, 1, 3)
		local k = tonumber(data.Power)
		if not k then
			k = (level - 1) / 2 -- (his own screen: the level he let go at)
		end
		k = math.clamp(k, 0, 1)
		local d = flatten(typeof(data.Dir) == "Vector3" and data.Dir or root.CFrame.LookVector, root)
		if isLocal then
			face(root, d)
		end
		local L = ability.Launch or {}
		local time = L.Time or 0.24
		local dist = (L.Min or 16) + ((L.Max or 62) - (L.Min or 16)) * k
		local g = groundPoint(root.Position)
		shockDisc(g + UP * 0.3, UP, 4, 20 + 22 * k, 0.4, FJ.RED)
		billboardRing(g + UP * 1.2, 3, 18 + 18 * k, FJ.RED, 7, 0.3)
		sparks(g + UP, 0.7 + k, FJ.HOT, FJ.RED, 16 + math.floor(16 * k))
		dustPuffs(g, 0.8 + 0.8 * k, 5 + math.floor(4 * k), FJ.DUST, 1, true)
		groundMark(g, 4 + 3 * k, Color3.fromRGB(64, 40, 36), 4)
		rocks(g, 0.7 + 0.6 * k, 4 + math.floor(5 * k))
		streaks(g + UP * 2, -d, 10, 0.3, 6, 12 + 10 * k, FJ.RED, 0.3)
		VFX.PlaySound("Launch", g, 0.9)
		VFX.Motion(char, "FaJinLaunch")
		local stopTrail = addTrail(root, FJ.RED, 0.25, 2.2)
		if isLocal then
			dash(root, d * (dist / time), time)
			VFX.Shake(0.5 + 0.6 * k, 0.2)
		end
		task.wait(time)
		stopTrail()
		if not root.Parent then
			return
		end
		VFX.Motion(char, "FaJinRelease")
		local length = (ability.Range or 110) * (0.65 + 0.35 * k)
		local width = (ability.Width or 26) * (0.7 + 0.3 * k)
		local right = d:Cross(UP).Unit
		local origin = root.Position + d * 3.5 + UP * 1.2
		-- the fist: a flash, a ring of air and the whole screen jolts
		billboardRing(origin, 2, 18 + 22 * k, Color3.new(1, 1, 1), 8, 0.25)
		shockDisc(origin, d, 2, width * 0.8, 0.22, FJ.PALE, 6)
		shockDisc(origin, d, 1, width * 0.5, 0.18, FJ.GOLD, 10)
		sparks(origin, 0.8 + k, FJ.PALE, FJ.GOLD, 24 + math.floor(24 * k))
		bolt(origin, 3 + 2 * k, FJ.RED)
		billboardRing(origin, 1, 10 + 12 * k, FJ.RED, 4, 0.2)
		VFX.PlaySound("DetroitImpact", origin, 0.9 + 0.3 * k)
		VFX.PlaySound("FaJinRelease", origin, 0.7 + 0.4 * k)
		if isLocal then
			VFX.ImpactFrame(0.05 + 0.05 * k)
			VFX.Hooks.Flash(FJ.PALE, 0.1 + 0.08 * k)
		end
		VFX.ShakeAt(origin, 1.1 + 1.4 * k, 90 + 70 * k, 0.35 + 0.25 * k)
		-- the pressure: a gold cone of air rushing down the street
		local cone = newPart(Vector3.new(2, 2, 2), CFrame.lookAt(origin, origin + d) * CFrame.Angles(0, math.rad(90), 0), FJ.GOLD, Enum.Material.Neon, Enum.PartType.Cylinder)
		cone.Transparency = 0.45
		local mid = origin + d * length * 0.5
		tween(cone, 0.3, { Size = Vector3.new(length, width * 0.55, width * 0.55), CFrame = CFrame.lookAt(mid, mid + d) * CFrame.Angles(0, math.rad(90), 0), Transparency = 1 }, Enum.EasingStyle.Quad)
		cleanup(cone, 0.4)
		local core = newPart(Vector3.new(2, 1, 1), CFrame.lookAt(origin, origin + d) * CFrame.Angles(0, math.rad(90), 0), Color3.new(1, 1, 1), Enum.Material.Neon, Enum.PartType.Cylinder)
		core.Transparency = 0.2
		tween(core, 0.22, { Size = Vector3.new(length, width * 0.2, width * 0.2), CFrame = CFrame.lookAt(mid, mid + d) * CFrame.Angles(0, math.rad(90), 0), Transparency = 1 }, Enum.EasingStyle.Quad)
		cleanup(core, 0.3)
		-- the energy he wound up, unwinding down it as a spiral
		local helix = {}
		for i = 0, 24 do
			local f = i / 24
			local a = f * (10 + 8 * k)
			local r = 1.2 + width * 0.22 * f
			table.insert(helix, origin + d * length * 0.85 * f + (right * math.cos(a) + UP * math.sin(a)) * r)
		end
		curveStroke(helix, 0.3 + 0.35 * k, FJ.GOLD, 0.4)
		streaks(origin, d, 12 + math.floor(12 * k), width / 30, 10 + 6 * k, length * 0.8, Color3.new(1, 1, 1), 0.3)
		-- the gale travels: rings of air, dust walls and rubble all the way down
		local waves = 5 + math.floor(3 * k)
		for i = 1, waves do
			task.delay(i / waves * 0.32, function()
				local f = i / waves
				local p = origin + d * length * f
				shockDisc(p, d, width * (0.35 + 0.3 * f), width * (0.7 + 0.5 * f), 0.35, i % 2 == 0 and Color3.new(1, 1, 1) or FJ.GOLD, 6)
				local g = groundPoint(p)
				dustPuffs(g, 0.6 + 0.7 * k, 3, FJ.DUST, 1, i % 2 == 0)
				groundMark(g, 2.5 + width * 0.12, Color3.fromRGB(70, 66, 60), 3.5)
				if i % 2 == 0 then
					rocks(g, 0.6 + 0.5 * k, 3 + level)
				end
				for side = -1, 1, 2 do
					celPuff(folder, g + right * side * width * 0.3 + UP, g + right * side * width * (0.6 + 0.3 * k) + UP * rand(2, 5), 3 + 3 * k, FJ.DUST, Color3.new(1, 1, 1), 0.5, 0.9)
				end
			end)
		end
		-- full power: the far end of it bursts
		if level >= 3 then
			task.delay(0.34, function()
				local e = origin + d * length * 0.9
				billboardRing(e, 4, width * 2.2, Color3.new(1, 1, 1), 10, 0.4)
				shockDisc(groundPoint(e) + UP * 0.4, UP, 4, width * 1.6, 0.45, FJ.GOLD)
				dustPuffs(groundPoint(e), 1.5, 8, FJ.DUST, 1.3, true)
				VFX.PlaySound("Smash", e, 0.9)
				VFX.ShakeAt(e, 1.6, 120, 0.4)
			end)
		end
	end

	-- (knocked out, or never let go: the wind-up just stops)
	function VFX.FaJinDrop(char)
		FJ.charging[char] = nil
	end
end

-- GEARSHIFT (Deku's 4th, the 2nd user Kudo's quirk - in the anime it wraps
-- whatever it touches in a glowing blue aura, and living things' eyes glow
-- blue): each press shifts him up a gear like a driver working the stick -
-- LOW, SECOND, THIRD, TOP - and he's faster and harder-hitting with every
-- one: the blue aura on him, a cog of light spinning round each fist and
-- ankle, quicker every gear, blue streaks peeling off him as he runs. At
-- TOP GEAR the next press is OVERDRIVE into TRANSMISSION: he's on them in a
-- blink, the punches come faster and faster, then DETROIT SMASH: QUINTUPLE
-- - five of them - and the last sends them flying, geared down (glowing
-- blue, eyes and all, and slow). Then the recoil hits him.
do
	local GS = {
		GLOW = Color3.fromRGB(96, 178, 255),
		CORE = Color3.fromRGB(226, 242, 255),
		DEEP = Color3.fromRGB(30, 84, 220),
		FAJIN = Color3.fromRGB(255, 70, 60),
		rigs = setmetatable({}, { __mode = "k" }), -- [char] = { cogs, gear, spin }
		LIMBS = {
			{ "RightHand", "Right Arm", -0.95 }, { "LeftHand", "Left Arm", -0.95 },
			{ "RightFoot", "Right Leg", -0.8 }, { "LeftFoot", "Left Leg", -0.8 },
		},
	}
	-- the shift: low like a driver in his seat, the right hand down on the
	-- stick at his hip - forward... and yanked back into the next gear
	MOTIONS.GearshiftShift = {
		{ pose = { Hips = { -6, 0, 0, 0, -0.4, 0 }, Crouch = 0.55, Waist = { -18, -10, 0 }, Neck = { 12, 10, 0 }, RightArm = { 28, 0, 14 }, RightElbow = 64, LeftArm = { 60, 0, 10 }, LeftElbow = 84, RightLeg = 30, LeftLeg = -6 }, t = 0.05, hold = 0.03 },
		{ pose = { Hips = { -6, 0, 0, 0, -0.4, 0 }, Crouch = 0.55, Waist = { -14, -16, 0 }, Neck = { 12, 14, 0 }, RightArm = { -22, 0, 18 }, RightElbow = 86, LeftArm = { 60, 0, 10 }, LeftElbow = 84, RightLeg = 30, LeftLeg = -6 }, t = 0.035, hold = 0.1, style = SNAP },
		recover = 0.18,
	}

	-- a cog: teeth round a ring, flat to `axis`
	function GS.cog(radius, teeth, thick)
		local parts = {}
		for i = 1, teeth do
			local a = i / teeth * math.pi * 2
			local tooth = newPart(Vector3.new(thick * 1.4, thick, radius * 0.42), CFrame.new(), GS.GLOW, Enum.Material.Neon)
			table.insert(parts, { part = tooth, a = a, r = radius * 1.08, len = true })
			local rim = newPart(Vector3.new(thick * 0.7, thick * 0.7, radius * 2 * math.sin(math.pi / teeth) + 0.05), CFrame.new(), GS.CORE, Enum.Material.Neon)
			table.insert(parts, { part = rim, a = a + math.pi / teeth, r = radius * 0.86 })
		end
		return parts
	end

	-- place a cog's pieces round `cf` (its axis cf's Y), turned `spin`
	function GS.placeCog(cog, cf, spin)
		for _, e in cog do
			local a = e.a + spin
			local at = cf * CFrame.new(math.cos(a) * e.r, 0, math.sin(a) * e.r)
			if e.len then
				e.part.CFrame = CFrame.lookAt(at.Position, cf.Position) * CFrame.new(0, 0, e.part.Size.Z * 0.1)
			else
				e.part.CFrame = CFrame.lookAt(at.Position, at.Position + cf:VectorToWorldSpace(Vector3.new(-math.sin(a), 0, math.cos(a))), cf.UpVector)
			end
		end
	end

	function GS.drop(char)
		local rig = GS.rigs[char]
		if not rig then
			return
		end
		GS.rigs[char] = nil
		if rig.aura then
			rig.aura:Destroy()
		end
		for _, cog in rig.cogs do
			for _, e in cog do
				tween(e.part, 0.25, { Transparency = 1, Size = e.part.Size * 0.3 })
				cleanup(e.part, 0.3)
			end
		end
	end

	function GS.step(dt)
		local now = os.clock()
		for _, plr in Players:GetPlayers() do
			local char = plr.Character
			local gear = char and char:GetAttribute("Gearshift")
			local root = char and char:FindFirstChild("HumanoidRootPart")
			local rig = char and GS.rigs[char]
			if gear and root then
				if not rig then
					rig = { cogs = {}, spin = 0 }
					for _ = 1, #GS.LIMBS do
						table.insert(rig.cogs, GS.cog(0.95, 8, 0.16))
					end
					-- (the blue aura Gearshift wraps him in)
					local aura = Instance.new("Highlight")
					aura.Name = "GearshiftAura"
					aura.FillColor = GS.GLOW
					aura.OutlineColor = GS.CORE
					aura.DepthMode = Enum.HighlightDepthMode.Occluded
					aura.Parent = char
					rig.aura = aura
					GS.rigs[char] = rig
				end
				rig.aura.FillTransparency = 0.88 - 0.06 * gear + math.sin(now * (6 + 2 * gear)) * 0.04
				rig.aura.OutlineTransparency = 0.6 - 0.08 * gear
				rig.spin += dt * (3 + 5 * gear)
				for i, spec in GS.LIMBS do
					local limbPart = limb(char, spec[1], spec[2])
					if limbPart then
						local at = limbPart.CFrame * CFrame.new(0, limbPart.Size.Y / 2 + spec[3], 0)
						GS.placeCog(rig.cogs[i], at, i % 2 == 0 and -rig.spin or rig.spin)
					end
				end
				-- green streaks off him, the faster he's going
				local v = root.AssemblyLinearVelocity
				local flat = Vector3.new(v.X, 0, v.Z)
				if flat.Magnitude > 18 and now - (rig.streak or 0) > 0.12 - 0.02 * gear then
					rig.streak = now
					local back = -flat.Unit
					local p = root.Position + Vector3.new(rand(-1.2, 1.2), rand(-2, 1.5), rand(-1.2, 1.2))
					local s = newPart(Vector3.new(0.12, 0.12, 3 + gear), CFrame.lookAt(p, p + back) * CFrame.new(0, 0, -(3 + gear) / 2), GS.GLOW, Enum.Material.Neon)
					tween(s, 0.25, { Transparency = 1, Size = Vector3.new(0.04, 0.04, 5 + gear * 2) })
					cleanup(s, 0.3)
				end
			elseif rig then
				GS.drop(char)
			end
		end
		for char in GS.rigs do
			if not char.Parent then
				GS.drop(char)
			end
		end
	end
	RunService.RenderStepped:Connect(GS.step)

	-- a big cog of light behind him, spun up and gone
	function GS.bigCog(cf, radius, life)
		local cog = GS.cog(radius, 10, 0.3)
		local t0 = os.clock()
		local conn
		conn = RunService.RenderStepped:Connect(function()
			local t = os.clock() - t0
			if t > life then
				conn:Disconnect()
				for _, e in cog do
					e.part:Destroy()
				end
				return
			end
			GS.placeCog(cog, cf * CFrame.Angles(math.pi / 2, 0, 0), t * 9)
			for _, e in cog do
				e.part.Transparency = math.clamp((t / life - 0.5) * 2, 0, 1)
			end
		end)
	end

	function Effects.Gearshift(char, _data, isLocal, ability)
		local root = charParts(char)
		if not root then
			return
		end
		ability = ability or Config.FindAbilityById("Gearshift") or {}
		local top = ability.TopGear or 4
		local gear = char:GetAttribute("Gearshift") or 0
		if gear >= top then
			-- OVERDRIVE into TRANSMISSION: the rush itself comes from the
			-- server (TransmissionRush, GearshiftHit)
			VFX.Motion(char, "GearshiftShift")
			GS.bigCog(root.CFrame * CFrame.new(0, 0.5, 1.8), 5, 0.45)
			return
		end
		local new = gear + 1
		VFX.Motion(char, "GearshiftShift")
		GS.bigCog(root.CFrame * CFrame.new(0, 0.5, 1.6), 2.4 + new * 0.6, 0.5)
		local g = groundPoint(root.Position)
		shockDisc(g + UP * 0.3, UP, 3, 10 + new * 4, 0.3, GS.GLOW)
		sparks(root.Position, 0.4 + 0.15 * new, GS.CORE, GS.GLOW, 8 + new * 3)
		VFX.PlaySound("ReciproRev", root.Position, 0.5 + 0.12 * new)
		VFX.PlaySound("Snap", root.Position, 0.8)
		if isLocal then
			local names = ability.Gears or {}
			VFX.Hooks.Callout(names[new] or ("GEAR " .. new), new >= top and Color3.fromRGB(255, 240, 150) or GS.GLOW)
			VFX.Shake(0.15 + 0.1 * new, 0.15)
		end
	end

	-- OVERDRIVE (Gearshift and Fa Jin together, 120%): red and blue burst
	-- off him and he's on them in a blink, a streak and a string of
	-- afterimages from where he was
	function Effects.TransmissionRush(char, data)
		local root = charParts(char)
		if not root then
			return
		end
		local d = typeof(data.Dir) == "Vector3" and data.Dir or root.CFrame.LookVector
		local at = root.Position
		billboardRing(at, 2, 26, GS.FAJIN, 6, 0.3)
		billboardRing(at, 2, 20, GS.GLOW, 6, 0.3)
		sparks(at, 1.2, GS.CORE, GS.FAJIN, 24)
		streaks(at, -d, 16, 0.3, 10, 24, GS.GLOW, 0.35)
		for i = 1, 4 do
			task.delay(i * 0.03, function()
				if char.Parent then
					afterimage(char, i % 2 == 0 and GS.FAJIN or GS.GLOW, 0.3)
				end
			end)
		end
		VFX.PlaySound("BlitzGo", at, 1.2)
		VFX.PlaySound("Dash", at, 1)
		if Players.LocalPlayer and Players.LocalPlayer.Character == char then
			VFX.Hooks.Callout("OVERDRIVE!!", Color3.fromRGB(255, 120, 110))
			VFX.Shake(0.8, 0.25)
		end
	end

	-- every punch faster than the last: the rings get bigger, the sound
	-- piles up, and the last one's a Detroit Smash
	function Effects.GearshiftHit(char, data)
		local root = charParts(char)
		local pos = typeof(data.Pos) == "Vector3" and data.Pos
		if not root or not pos then
			return
		end
		local n, hits = tonumber(data.N) or 1, tonumber(data.Hits) or 9
		local d = typeof(data.Dir) == "Vector3" and data.Dir or root.CFrame.LookVector
		local f = math.clamp(n / hits, 0, 1)
		local q = tonumber(data.Quintuple)
		if q then
			-- DETROIT SMASH: QUINTUPLE - five of them, a gale each
			VFX.Pose(char, q % 2 == 1 and "PunchR" or "PunchL", 0.14)
			windBlast(pos, d, 1 + q * 0.2)
			billboardRing(pos, 3, 30 + q * 6, q % 2 == 1 and Color3.new(1, 1, 1) or GS.GLOW, 8, 0.25)
			shockDisc(pos, d, 4, 22 + q * 3, 0.26, GS.CORE, 14)
			sparks(pos, 1 + q * 0.15, GS.CORE, GS.GLOW, 18)
			VFX.PlaySound("DetroitImpact", pos, 1 + q * 0.1)
			VFX.ShakeAt(pos, 1 + q * 0.25, 90, 0.2)
			-- a count over the hit: x1 ... x5
			local anchor = newPart(Vector3.one * 0.1, CFrame.new(pos + UP * 3), GS.GLOW)
			anchor.Transparency = 1
			local bb = Instance.new("BillboardGui")
			bb.Size = UDim2.fromOffset(140, 60)
			bb.AlwaysOnTop = true
			bb.LightInfluence = 0
			bb.MaxDistance = 200
			bb.Parent = anchor
			local label = Instance.new("TextLabel")
			label.BackgroundTransparency = 1
			label.Size = UDim2.fromScale(1, 1)
			label.Font = Enum.Font.LuckiestGuy
			label.TextScaled = true
			label.Text = "x" .. q
			label.TextColor3 = GS.CORE
			label.TextStrokeColor3 = GS.DEEP
			label.TextStrokeTransparency = 0
			label.Parent = bb
			tween(anchor, 0.6, { CFrame = anchor.CFrame + UP * 3 })
			tween(label, 0.3, { TextTransparency = 1, TextStrokeTransparency = 1 }, nil, nil, 0.3)
			cleanup(anchor, 0.65)
			if q == 1 and Players.LocalPlayer and Players.LocalPlayer.Character == char then
				VFX.Hooks.Callout("DETROIT SMASH: QUINTUPLE!!", Color3.fromRGB(255, 240, 150))
			end
			return
		end
		if data.Final then
			VFX.Pose(char, "PunchR", 0.4)
			billboardRing(pos, 4, 60, Color3.new(1, 1, 1), 10, 0.35)
			billboardRing(pos, 2, 40, GS.GLOW, 8, 0.3)
			shockDisc(pos, d, 4, 30, 0.3, GS.CORE, 18)
			streaks(pos, d, 18, 0.3, 14, 50, Color3.new(1, 1, 1), 0.35)
			sparks(pos, 1.6, GS.CORE, GS.GLOW, 36)
			windBlast(pos, d, 2.2)
			VFX.PlaySound("DetroitImpact", pos, 1.5)
			VFX.PlaySound("Smash", pos, 1.2)
			VFX.ShakeAt(pos, 2.4, 120, 0.4)
			if Players.LocalPlayer and Players.LocalPlayer.Character == char then
				VFX.Hooks.Callout("DETROIT SMASH!!", Color3.fromRGB(255, 240, 150))
			end
			return
		end
		if n == 1 and Players.LocalPlayer and Players.LocalPlayer.Character == char then
			VFX.Hooks.Callout("TRANSMISSION!!", GS.GLOW)
		end
		VFX.Pose(char, n % 2 == 0 and "PunchL" or "PunchR", 0.07 + 0.08 * (1 - f))
		billboardRing(pos, 1, 8 + 14 * f, n % 2 == 0 and GS.GLOW or Color3.new(1, 1, 1), 3 + 3 * f, 0.15)
		sparks(pos, 0.4 + 0.6 * f, GS.CORE, GS.GLOW, 6 + math.floor(10 * f))
		if f > 0.5 then
			shockDisc(pos, d, 2, 8 + 10 * f, 0.18, GS.GLOW, 6)
		end
		VFX.PlaySound(f > 0.6 and "HeavyHit" or "Hit", pos, 0.7 + 0.3 * f)
		VFX.ShakeAt(pos, 0.3 + 0.7 * f, 60, 0.08)
	end

	-- the recoil: steam off him and down on one knee for a moment
	function Effects.GearshiftRecoil(char, data)
		local root = charParts(char)
		if not root then
			return
		end
		local time = tonumber(data.Time) or 0.6
		VFX.Pose(char, "Kneel", time)
		for i = 1, 6 do
			task.delay(i * time / 6, function()
				if root.Parent then
					celPuff(folder, root.Position + Vector3.new(rand(-1, 1), rand(0, 2), rand(-1, 1)), root.Position + UP * rand(4, 7), 1.2, Color3.fromRGB(200, 204, 210), Color3.new(1, 1, 1), 0.6, 0.8)
				end
			end)
		end
		VFX.PlaySound("Wind", root.Position, 0.5)
	end

	-- GEARED DOWN: Gearshift on someone else - the blue aura, the eyes
	-- glowing blue, slow as a crawl for a few seconds
	function Effects.GearedDown(char, data)
		local head = char and char:FindFirstChild("Head")
		if not head then
			return
		end
		local time = tonumber(data.Time) or 3
		local aura = Instance.new("Highlight")
		aura.FillColor = GS.GLOW
		aura.OutlineColor = GS.CORE
		aura.FillTransparency = 0.55
		aura.DepthMode = Enum.HighlightDepthMode.Occluded
		aura.Parent = char
		tween(aura, 0.5, { FillTransparency = 1, OutlineTransparency = 1 }, nil, nil, math.max(time - 0.5, 0))
		cleanup(aura, time + 0.1)
		local eyes = {}
		for side = -1, 1, 2 do
			local eye = newPart(Vector3.new(0.22, 0.12, 0.05), head.CFrame, GS.GLOW, Enum.Material.Neon)
			table.insert(eyes, { part = eye, off = CFrame.new(side * 0.22, 0.12, -head.Size.Z / 2 - 0.02) })
		end
		local t0 = os.clock()
		local conn
		conn = RunService.RenderStepped:Connect(function()
			if os.clock() - t0 > time or not head.Parent then
				conn:Disconnect()
				for _, e in eyes do
					e.part:Destroy()
				end
				return
			end
			for _, e in eyes do
				e.part.CFrame = head.CFrame * e.off
			end
		end)
		VFX.PlaySound("Snap", head.Position, 0.6)
	end

	-- DANGER SENSE (Deku at 100%, the 4th user's quirk): the manga's jagged
	-- lines round his head, a red flash, and he's already a step aside
	function Effects.DangerSense(char, data)
		local root = charParts(char)
		if not root then
			return
		end
		local head = char:FindFirstChild("Head")
		local at = head and head.Position or root.Position + UP * 1.5
		local RED = Color3.fromRGB(255, 70, 70)
		for i = 1, 9 do
			local a = i / 9 * math.pi * 2
			local out = Vector3.new(math.cos(a), rand(-0.2, 0.7), math.sin(a)).Unit
			local side = out:Cross(UP).Magnitude > 0.1 and out:Cross(UP).Unit or Vector3.new(1, 0, 0)
			local prev = at + out * 1.1
			for k = 1, 3 do
				local nxt = at + out * (1.1 + k * 0.7) + side * (k % 2 == 0 and 0.25 or -0.25)
				local seg = newPart(Vector3.new(0.09, 0.09, (nxt - prev).Magnitude + 0.05), CFrame.lookAt((prev + nxt) / 2, nxt), RED, Enum.Material.Neon)
				tween(seg, 0.35, { Transparency = 1 }, nil, nil, 0.1)
				cleanup(seg, 0.5)
				prev = nxt
			end
		end
		afterimage(char, RED, 0.3)
		VFX.PlaySound("Blink", at, 1)
		local me = Players.LocalPlayer
		if me and me.Character == char then
			VFX.Hooks.Callout("DANGER SENSE!", Color3.fromRGB(255, 90, 90))
			local from = typeof(data.From) == "Vector3" and data.From or root.Position - root.CFrame.LookVector
			local away = flatten(root.Position - from, root)
			local step = away:Cross(UP).Unit * (rng:NextNumber() < 0.5 and -1 or 1)
			dash(root, (step * 0.8 + away * 0.6).Unit * 70, 0.12)
		end
	end

	-- the gears run down to neutral by themselves
	function Effects.GearshiftDown(char)
		local root = charParts(char)
		if root then
			VFX.PlaySound("Snap", root.Position, 0.5)
		end
	end
end

-- V: Float (Nana Shimura's quirk). (round 75) Pressing it doesn't lift him:
-- gravity lets go of him - a pale swirl at his feet, the street's dust
-- drifting up round him - but he's on his feet till he jumps (his own
-- machine floats him: VFX.Hooks.FloatArm). Everyone sees the lift-off, the
-- Air Force flicks and the touch-down through FloatFX.
function Effects.Float(char, _data, isLocal, ability)
	local root, hum = charParts(char)
	if not root then
		return
	end
	local pale = Color3.fromRGB(236, 255, 246)
	VFX.Pose(char, "FloatIdle", 0.45)
	local g = groundPoint(root.Position)
	shockDisc(g + UP * 0.3, UP, 2, 16, 0.5, pale)
	billboardRing(root.Position - UP * 2.5, 1.5, 10, COWL_GREEN, 3, 0.4)
	VFX.PlaySound("ZeroG", root.Position, 0.7)
	-- weightless: the dust round him lifting off the street
	for _ = 1, 10 do
		local p = g + Vector3.new(rand(-5, 5), 0.2, rand(-5, 5))
		local mote = newPart(Vector3.one * rand(0.15, 0.35), CFrame.new(p), Color3.fromRGB(210, 220, 214), Enum.Material.SmoothPlastic, Enum.PartType.Ball)
		tween(mote, rand(1.2, 2), { Position = p + UP * rand(3, 7), Transparency = 1 }, Enum.EasingStyle.Sine, Enum.EasingDirection.Out)
		cleanup(mote, 2.1)
	end
	if isLocal then
		if VFX.Hooks.FloatArm then
			VFX.Hooks.FloatArm(ability)
		elseif hum then
			launch(root, hum, UP * ((ability and ability.Lift) or 18)) -- (no machine to fly him: a hop)
		end
	end
end

do
	VFX.FloatHover = setmetatable({}, { __mode = "k" }) -- [char] = the lift it's showing
	function Effects.FloatFX(char, data)
		local root = charParts(char)
		if not root then
			return
		end
		local pale = Color3.fromRGB(236, 255, 246)
		if data.Kind == "End" then
			VFX.FloatHover[char] = nil
			sparks(root.Position - UP * 2.5, 0.4, pale, COWL_GREEN, 6)
			return
		end
		if data.Kind == "Boost" then
			-- AIR FORCE flicked out behind him throws him down the aim
			local d = (typeof(data.Dir) == "Vector3" and data.Dir.Magnitude > 0.01) and data.Dir.Unit or root.CFrame.LookVector
			VFX.Pose(char, "Flick", 0.25)
			local back = root.Position - d * 2.5
			shockDisc(back, -d, 1.5, 12, 0.3, WIND, 3)
			billboardRing(back, 1, 9, COWL_CORE, 3, 0.25)
			streaks(back, -d, 6, 1.5, 8, 18, WIND, 0.25)
			afterimage(char, COWL_GREEN, 0.25)
			VFX.PlaySound("AirBullet", back, 0.9)
			return
		end
		-- the lift-off: up, soft as anything, and hanging there
		local token = {}
		VFX.FloatHover[char] = token
		local g = groundPoint(root.Position)
		shockDisc(g + UP * 0.3, UP, 3, 22, 0.45, pale)
		dustPuffs(g, 1, 6, Color3.fromRGB(206, 200, 190), 0.9, false)
		streaks(root.Position - UP * 2, -UP, 6, 2, 6, 10, WIND, 0.3)
		VFX.PlaySound("Leap", root.Position, 0.6)
		VFX.PlaySound("ZeroG", root.Position, 0.5)
		task.spawn(function()
			local t0 = os.clock()
			local last = root.Position
			while VFX.FloatHover[char] == token and root.Parent and os.clock() - t0 < 12 do
				local v = (root.Position - last) / 0.15
				last = root.Position
				VFX.Pose(char, v.Magnitude > 18 and "Skydive" or "FloatIdle", 0.4)
				-- Nana's quirk: a pale ring under him, motes drifting off him
				billboardRing(root.Position - UP * 2.7, 1.2, 5, pale, 2, 0.3)
				local m = newPart(Vector3.one * rand(0.12, 0.25), CFrame.new(root.Position + rng:NextUnitVector() * rand(1, 2.2)), pale, Enum.Material.Neon, Enum.PartType.Ball)
				tween(m, 0.7, { Position = m.Position + UP * rand(1, 2.5) - v * 0.05, Transparency = 1 })
				cleanup(m, 0.75)
				task.wait(0.15)
			end
			if VFX.FloatHover[char] == token then
				VFX.FloatHover[char] = nil
			end
		end)
	end
end

---------------------------------------------------------------------------
-- (round 87) THE DIRECTOR CAMERA's world (Config.Director; the camera, its
-- keys and its clean frame are in QuirkClient, its overlay in HUD) - on the
-- director's own screen only.
--  TIME. What one screen can slow, it slows: every pose, clip and hitstop
--   runs on the pose clock (VFX.Warp, eased here frame by frame); an effect
--   started meanwhile tweens and lingers that much longer (the tween and
--   cleanup hooks); smoke, sparks and fire slow down (ParticleEmitter
--   .TimeScale); the game's sounds drop in pitch and go muffled. What it
--   can't slow - bodies thrown about, walking, rubble (the server and their
--   owners move them), trails, effects on their own clocks, cutscenes -
--   keeps real time. The FREEZE FRAME stops those too: a still copy of
--   every body near the camera, posed as it is that instant, stands in for
--   it (the real one hidden on this screen), every effect tween pauses and
--   every emitter holds its smoke in the air - a moment that holds still
--   while the camera flies round it. All of it is given back: the clock
--   carries on from where it got to (nothing jumps), each emitter's own
--   TimeScale, the paused tweens play on, the copies go, the bodies show,
--   the sounds come back.
--  HOLDS. A property set for as long as the director wants it, then given
--   back exactly - if the game changes it meanwhile, the game's value is
--   what's given back (the HUD, the name tags, a body it hides...). In named
--   sets; hot ones are checked every frame, the rest twice a second.
--  SHAKE. The game's camera shakes, kept for the director's camera (its
--   render step goes after the game's shake): smoothed, on the slowed clock.
-- (Its own block, one local: the main chunk is at its local limit.)
---------------------------------------------------------------------------
do
	local DC = {
		on = false, scale = 1, applied = 1, frozen = false, CFG = Config.Director or {},
		sets = {}, -- [set] = { [Instance] = { [property] = { want = the game's, value = ours, hot } } }
		emitters = {}, -- [ParticleEmitter] = { base = its own TimeScale, set = what was put on it }
		tweens = {}, -- effect tweens started while it's on (the finished ones dropped every second)
		paused = {}, -- the ones the freeze frame paused
		later = {}, -- effects to go, on the slowed clock: { obj, due }
		stills = {}, -- [real body] = its still copy
		shake = { amount = 0, untilW = 0, length = 1 },
		conns = {},
	}
	VFX.Director = DC

	---------------------------------------------------------------------------
	-- holds
	---------------------------------------------------------------------------
	function DC.hold(set, inst, prop, value, hot)
		if typeof(inst) ~= "Instance" then
			return false
		end
		local s = DC.sets[set]
		if not s then
			s = {}
			DC.sets[set] = s
		end
		local props = s[inst]
		local e = props and props[prop]
		if not e then
			local ok, cur = pcall(function()
				return inst[prop]
			end)
			if not ok then
				return false
			end
			props = props or {}
			s[inst] = props
			e = { want = cur }
			props[prop] = e
		end
		e.value = value
		e.hot = e.hot or hot == true
		pcall(function()
			if inst[prop] ~= value then
				inst[prop] = value
			end
		end)
		return true
	end
	function DC.held(set, inst, prop)
		local s = DC.sets[set]
		return s ~= nil and s[inst] ~= nil and s[inst][prop] ~= nil
	end
	-- a held property the game changed: that's its value now (it's what goes
	-- back later), and ours goes back on (hotOnly: just the ones checked
	-- every frame). Gone instances are dropped.
	function DC.enforce(set, hotOnly)
		local s = DC.sets[set]
		for inst, props in s or {} do
			if inst.Parent == nil then
				s[inst] = nil
			else
				for prop, e in props do
					if e.hot or not hotOnly then
						pcall(function()
							local cur = inst[prop]
							if cur ~= e.value then
								e.want = cur
								inst[prop] = e.value
							end
						end)
					end
				end
			end
		end
	end
	-- a set given back (all of it, or what `filter` picks): each property to
	-- the game's value - unless the game changed it since
	function DC.release(set, filter)
		local s = DC.sets[set]
		for inst, props in s or {} do
			if not filter or filter(inst) then
				for prop, e in props do
					pcall(function()
						if inst[prop] == e.value then
							inst[prop] = e.want
						end
					end)
				end
				s[inst] = nil
			end
		end
		if s and next(s) == nil then
			DC.sets[set] = nil
		end
	end
	function DC.unhold(set, inst, prop)
		local s = DC.sets[set]
		local props = s and s[inst]
		local e = props and props[prop]
		if not e then
			return
		end
		pcall(function()
			if inst[prop] == e.value then
				inst[prop] = e.want
			end
		end)
		props[prop] = nil
		if next(props) == nil then
			s[inst] = nil
		end
	end
	-- every frame from the director's camera: the hot holds; every set in full twice a second
	function DC.tick()
		local now = os.clock()
		local full = now >= (DC.fullAt or 0)
		if full then
			DC.fullAt = now + 0.5
		end
		for set in DC.sets do
			DC.enforce(set, not full)
		end
		-- (the effect tweens that have finished: nothing to hold any more)
		if now >= (DC.pruneAt or 0) then
			DC.pruneAt = now + 1
			for tw in DC.tweens do
				local state = tw.PlaybackState
				if state == Enum.PlaybackState.Completed or state == Enum.PlaybackState.Cancelled then
					DC.tweens[tw] = nil
				end
			end
		end
	end

	---------------------------------------------------------------------------
	-- time
	---------------------------------------------------------------------------
	function DC.begin()
		DC.on = true
		VFX.Slow = DC
		DC.shake.amount = 0
	end
	-- everything back (the director's gone)
	function DC.finish()
		DC.freeze(false)
		DC.time(1)
		DC.flushLater()
		VFX.Slow = nil
		DC.on = false
		table.clear(DC.tweens)
		for set in DC.sets do
			DC.release(set)
		end
		for key, c in DC.conns do
			c:Disconnect()
			DC.conns[key] = nil
		end
	end
	-- the pose clock runs at `scale` x the wall clock from now on (its anchor
	-- moved to now: it carries on from where it is)
	function DC.setScale(scale)
		local W = VFX.Warp
		if W.scale ~= scale then
			local now = os.clock()
			W.w = VFX.WarpTime(now)
			W.r = now
			W.scale = scale
		end
	end
	-- every frame from the director's camera: the scale it's easing through
	-- (0: frozen); the emitters and the sounds follow it
	function DC.time(scale)
		scale = math.clamp(tonumber(scale) or 1, 0, 1)
		DC.setScale(scale)
		DC.scale = scale
		if math.abs(scale - DC.applied) > 0.004 or (scale ~= DC.applied and (scale == 1 or scale == 0)) then
			DC.applied = scale
			DC.applyEmitters(scale)
			DC.applySound(scale)
		end
	end
	-- an effect tween started now: as much longer as time's slower (a freeze
	-- frame pauses it instead - track)
	function DC.stretch(t, delay)
		local s = VFX.Warp.scale
		if type(t) ~= "number" or s >= 0.999 or s <= 0 then
			return t, delay
		end
		return t / s, type(delay) == "number" and delay / s or delay
	end
	function DC.track(tw, obj)
		DC.tweens[tw] = obj or true -- (what it tweens: a tween on something gone isn't played on)
		if DC.frozen then
			pcall(function()
				tw:Pause()
			end)
			DC.paused[tw] = true
		end
	end
	-- an effect's cleanup while time's slowed: on the slowed clock (true: taken)
	function DC.cleanup(obj, t)
		if VFX.Warp.scale >= 0.999 or typeof(obj) ~= "Instance" then
			return false
		end
		table.insert(DC.later, { obj = obj, due = VFX.WarpTime(os.clock()) + (tonumber(t) or 0) })
		if not DC.conns.later then
			DC.conns.later = RunService.Stepped:Connect(function()
				local now = VFX.WarpTime(os.clock())
				for i = #DC.later, 1, -1 do
					local item = DC.later[i]
					if now >= item.due then
						table.remove(DC.later, i)
						pcall(function()
							item.obj:Destroy()
						end)
					end
				end
				if #DC.later == 0 and DC.conns.later then
					DC.conns.later:Disconnect()
					DC.conns.later = nil
				end
			end)
		end
		return true
	end
	-- (time's back) what's still waiting goes with what it has left
	function DC.flushLater()
		local now = VFX.WarpTime(os.clock())
		for _, item in DC.later do
			Debris:AddItem(item.obj, math.max(item.due - now, 0))
		end
		table.clear(DC.later)
		if DC.conns.later then
			DC.conns.later:Disconnect()
			DC.conns.later = nil
		end
	end
	-- smoke, sparks, fire: their own TimeScale x the clock's
	function DC.emitter(pe, scale)
		pcall(function()
			local e = DC.emitters[pe]
			if not e then
				e = { base = pe.TimeScale }
				DC.emitters[pe] = e
			elseif e.set and math.abs(pe.TimeScale - e.set) > 1e-3 then
				e.base = pe.TimeScale -- (the game set its own: that's what comes back)
			end
			e.set = math.clamp(e.base * scale, 0, 1)
			pe.TimeScale = e.set
		end)
	end
	function DC.applyEmitters(scale)
		if scale >= 1 then
			for pe, e in DC.emitters do
				pcall(function()
					if pe.Parent and math.abs(pe.TimeScale - e.set) < 1e-3 then
						pe.TimeScale = e.base
					end
				end)
			end
			table.clear(DC.emitters)
			if DC.conns.emit then
				DC.conns.emit:Disconnect()
				DC.conns.emit = nil
			end
			return
		end
		if not DC.conns.emit then
			-- every emitter there is (the map's found once: it doesn't change),
			-- and each one that turns up while it lasts
			if not DC.mapEmitters then
				DC.mapEmitters = {}
				local map = workspace:FindFirstChild("Map")
				for _, d in map and map:GetDescendants() or {} do
					if d:IsA("ParticleEmitter") then
						table.insert(DC.mapEmitters, d)
					end
				end
			end
			for _, pe in DC.mapEmitters do
				if pe.Parent then
					DC.emitter(pe, scale)
				end
			end
			for _, child in workspace:GetChildren() do
				if child.Name ~= "Map" then
					for _, d in child:GetDescendants() do
						if d:IsA("ParticleEmitter") then
							DC.emitter(d, scale)
						end
					end
				end
			end
			DC.conns.emit = workspace.DescendantAdded:Connect(function(d)
				if DC.applied < 1 and d:IsA("ParticleEmitter") then
					DC.emitter(d, DC.applied)
				end
			end)
			return
		end
		for pe in DC.emitters do
			DC.emitter(pe, scale)
		end
	end
	-- the game's sounds in slow motion: lower and muffled (an equaliser and
	-- a pitch shift on its sound group, taken off after)
	function DC.applySound(scale)
		local SND = (DC.CFG.Time or {}).Sound or {}
		local group = SoundService:FindFirstChild("QuirkSFX")
		if scale >= 1 or not group then
			for _, key in { "eq", "pitch" } do
				if DC[key] then
					DC[key]:Destroy()
					DC[key] = nil
				end
			end
			return
		end
		local k = math.clamp(1 - scale, 0, 1)
		if not (DC.eq and DC.eq.Parent) then
			DC.eq = Instance.new("EqualizerSoundEffect")
			DC.eq.Name = "DirectorSlowEq"
			DC.eq.Parent = group
		end
		if not (DC.pitch and DC.pitch.Parent) then
			DC.pitch = Instance.new("PitchShiftSoundEffect")
			DC.pitch.Name = "DirectorSlowPitch"
			DC.pitch.Parent = group
		end
		DC.eq.HighGain = -(SND.High or 22) * k
		DC.eq.MidGain = -(SND.Mid or 6) * k
		DC.eq.LowGain = (SND.Low or 2) * k
		DC.pitch.Octave = math.clamp(1 - (1 - (SND.Octave or 0.62)) * k, 0.5, 1)
	end

	---------------------------------------------------------------------------
	-- the freeze frame
	---------------------------------------------------------------------------
	-- every body that could be in a shot: players, dummies, Twice's doubles, the raid's Nomu
	function DC.bodies()
		local list = {}
		for _, plr in Players:GetPlayers() do
			local c = plr.Character
			if c and c.Parent and c:FindFirstChild("HumanoidRootPart") then
				table.insert(list, c)
			end
		end
		for _, name in { "Dummies", "TwiceClones", "NomuRaid" } do
			local holder = workspace:FindFirstChild(name)
			local found = holder and (name == "NomuRaid" and holder:GetDescendants() or holder:GetChildren()) or {}
			for _, m in found do
				if m:IsA("Model") and m:FindFirstChildOfClass("Humanoid") and m:FindFirstChild("HumanoidRootPart") then
					table.insert(list, m)
				end
			end
		end
		return list
	end
	-- a still copy of a body, posed exactly as it stands now: every part
	-- where it is, anchored, touching and moving nothing
	function DC.copyOf(model)
		local parts = {}
		for _, d in model:GetDescendants() do
			if d:IsA("BasePart") then
				table.insert(parts, d)
			end
		end
		if #parts == 0 then
			return nil
		end
		-- (each part marked, so its copy knows where to stand)
		for i, p in parts do
			pcall(p.SetAttribute, p, "DirectorStill", i)
		end
		local copy
		pcall(function()
			local was = model.Archivable
			model.Archivable = true
			copy = model:Clone()
			model.Archivable = was
		end)
		for _, p in parts do
			pcall(p.SetAttribute, p, "DirectorStill", nil)
		end
		if not copy then
			return nil
		end
		copy.Name = model.Name .. "_Still"
		local drop = {}
		for _, d in copy:GetDescendants() do
			if d:IsA("BasePart") then
				local src = parts[d:GetAttribute("DirectorStill") or 0]
				d:SetAttribute("DirectorStill", nil)
				d.Anchored = true
				d.CanCollide = false
				d.CanQuery = false
				d.CanTouch = false
				if src then
					d.CFrame = src.CFrame
					pcall(function()
						d.LocalTransparencyModifier = src.LocalTransparencyModifier
					end)
				end
			elseif d:IsA("JointInstance") or d:IsA("Constraint") or d:IsA("WeldConstraint") or d:IsA("LuaSourceContainer")
				or d:IsA("Sound") or d:IsA("ParticleEmitter") or d:IsA("Trail") or d:IsA("BillboardGui") or d:IsA("ForceField")
				or d:IsA("Animator") or d:IsA("BodyMover") or d:IsA("ProximityPrompt") then
				table.insert(drop, d)
			elseif d:IsA("Humanoid") then
				-- (kept for the clothes; nothing over its head, no thinking)
				pcall(function()
					d.DisplayDistanceType = Enum.HumanoidDisplayDistanceType.None
					d.HealthDisplayType = Enum.HumanoidHealthDisplayType.AlwaysOff
					d.BreakJointsOnDeath = false
					d.RequiresNeck = false
					d.PlatformStand = true
				end)
				pcall(function()
					d.EvaluateStateMachine = false
				end)
			end
		end
		for _, d in drop do
			pcall(d.Destroy, d)
		end
		copy:SetAttribute("DirectorStill", true)
		return copy
	end
	-- a body off this screen while its copy stands in (given back with the set)
	function DC.hide(model, set)
		for _, d in model:GetDescendants() do
			if d:IsA("BasePart") or d:IsA("Decal") then
				DC.hold(set, d, "LocalTransparencyModifier", 1, true)
			elseif d:IsA("Highlight") or d:IsA("BillboardGui") or d:IsA("SurfaceGui") then
				DC.hold(set, d, "Enabled", false)
			end
		end
	end
	-- from: where the camera is (the nearest bodies are kept); skip: a body
	-- left out (the director's own, while it's hidden)
	function DC.freeze(on, from, skip)
		on = on == true
		if on == DC.frozen then
			return
		end
		DC.frozen = on
		if on then
			-- every effect that's playing holds where it is
			for tw in DC.tweens do
				local state = tw.PlaybackState
				if state == nil or state == Enum.PlaybackState.Playing then
					pcall(function()
						tw:Pause()
					end)
					DC.paused[tw] = true
				end
			end
			-- every body near the camera: a still copy, the real one hidden
			local FR = (DC.CFG.Time or {}).Freeze or {}
			local list = {}
			for _, m in DC.bodies() do
				local root = m:FindFirstChild("HumanoidRootPart")
				local d = (from and root) and (root.Position - from).Magnitude or 0
				if m ~= skip and d <= (FR.Radius or 450) then
					table.insert(list, { m = m, d = d })
				end
			end
			table.sort(list, function(a, b)
				return a.d < b.d
			end)
			local folder = Instance.new("Folder")
			folder.Name = "DirectorStills"
			folder.Parent = VFX.Folder
			DC.stillFolder = folder
			for i = 1, math.min(#list, FR.Max or 24) do
				local m = list[i].m
				local copy = DC.copyOf(m)
				if copy then
					copy.Parent = folder
					DC.stills[m] = copy
					DC.hide(m, "still")
				end
			end
		else
			for tw in DC.paused do
				local state = tw.PlaybackState
				local obj = DC.tweens[tw]
				local gone = typeof(obj) == "Instance" and obj.Parent == nil
				if not gone and (state == nil or state == Enum.PlaybackState.Paused) then
					pcall(function()
						tw:Play()
					end)
				end
			end
			table.clear(DC.paused)
			if DC.stillFolder then
				DC.stillFolder:Destroy()
				DC.stillFolder = nil
			end
			table.clear(DC.stills)
			DC.release("still")
		end
	end
	function DC.stillOf(model)
		return model and DC.stills[model] or nil
	end

	---------------------------------------------------------------------------
	-- the shake, and the cutscenes
	---------------------------------------------------------------------------
	DC.baseShake = VFX.Shake
	function VFX.Shake(intensity, duration)
		DC.baseShake(intensity, duration)
		if DC.on and type(intensity) == "number" and type(duration) == "number" and duration > 0 then
			local s = DC.shake
			local now = VFX.WarpTime(os.clock())
			local left = math.max(s.untilW - now, 0)
			if intensity >= s.amount * (left / math.max(s.length, 1e-3)) then
				s.amount, s.length, s.untilW = intensity, duration, now + duration
			end
		end
	end
	-- the impacts' shake on the director's camera now (gain; freq: Hz of its
	-- wobble), on the slowed clock - smooth noise, not a per-frame jitter
	function DC.shakeOffset(gain, freq)
		local s = DC.shake
		local now = VFX.WarpTime(os.clock())
		if now >= s.untilW or s.amount <= 0 then
			return CFrame.new()
		end
		local k = s.amount * ((s.untilW - now) / math.max(s.length, 1e-3)) * (gain or 1)
		local t = now * (freq or 16)
		local function n(seed)
			return math.clamp(math.noise(t, seed, 0.37) * 2, -1, 1)
		end
		return CFrame.new(n(1.3) * k * 0.12, n(7.1) * k * 0.12, 0) * CFrame.Angles(n(3.7) * k * 0.012, n(5.9) * k * 0.012, n(9.2) * k * 0.008)
	end
	-- cinematicFor asks: does this body's cutscene play on the director's
	-- camera? (the client answers: DC.cuts)
	function DC.cutFor(char)
		return DC.on and DC.cuts ~= nil and DC.cuts(char) == true
	end
end

---------------------------------------------------------------------------
-- (round 87) THROUGH-THE-BUILDING KNOCKBACK (Config.Smash): a body going
-- through a wall, or splatted on one, on every screen (Effects.Smash, Kind
-- = Through / Splat: the thrown player's own predicted, everyone else's
-- from the server). THROUGH: a white star where he hits the wall, the wall
-- cracking out round the hole and its rim darkened; a beat later the wall
-- blown out of the FAR side along his path - its own brick and glass, a
-- dust plume rolling out of the exit hole after him - and a smoking hole
-- left behind; after him, a trail of dust and grit off his body, and where
-- he comes down in the street a skid of dust and scrapes. SPLAT: a crater
-- ringed with broken slabs and spider cracks, rock and dust thrown back
-- off the wall, grit trickling down while he's stuck there, a puff and a
-- crumble as he drops. Shakes for whoever's near; on the first wall an
-- impact frame for the one who threw him; the thrown one's own screen
-- kicked (FOV, speed lines). Built from the round-85/86 kits' pieces
-- (VFX.EngineKit, VFX.DFX), half of everything on a low-end machine.
-- (Its own block: the main chunk is at its local limit.)
---------------------------------------------------------------------------
do
	local SMX = {
		trails = {}, -- [char] = the trail / skid watcher on a body that's been through a wall (round 87, in Studio: not weak - the engine can drop an Instance key while it lives)
		PAL = {
			SHOCK = Color3.fromRGB(240, 246, 255), WARM = Color3.fromRGB(255, 224, 168), CRACK = Color3.fromRGB(36, 33, 31),
			CRATER = Color3.fromRGB(56, 52, 50), DUST = Color3.fromRGB(178, 166, 150), DUST_DARK = Color3.fromRGB(116, 108, 100),
			CONCRETE = Color3.fromRGB(130, 128, 132), SMOKE = Color3.fromRGB(92, 90, 96), SCRAPE = Color3.fromRGB(50, 46, 44),
		},
	}
	VFX.Smash = SMX

	function SMX.n(x)
		return VFX.EngineKit.count(x)
	end
	function SMX.vec(v)
		return typeof(v) == "Vector3" and v == v and v.Magnitude < 1e6
	end
	-- two directions flat on a wall (n: out of it)
	function SMX.axes(n)
		local right = n:Cross(math.abs(n.Y) < 0.9 and UP or Vector3.new(1, 0, 0)).Unit
		return right, right:Cross(n).Unit
	end
	-- the wall's own colour, darker, and plain concrete: its rubble
	function SMX.rubble(color)
		local c = typeof(color) == "Color3" and color or SMX.PAL.CONCRETE
		return { c, c:Lerp(Color3.new(0, 0, 0), 0.3), c:Lerp(SMX.PAL.CONCRETE, 0.5) }
	end

	-- (round 87 review) far off this screen's camera (Config.Smash.Far)? Then
	-- only what reads from there - the flash, the dust, the sound: no cracks,
	-- crater, chunks or skid marks nobody can see (a busy server's walls,
	-- a low-end machine). Never his own
	function SMX.far(pos, isLocal)
		local cam = workspace.CurrentCamera
		return not isLocal and cam ~= nil and (cam.Focus.Position - pos).Magnitude > ((Config.Smash or {}).Far or 360)
	end

	-- is there wall at p (n: out of it)?
	function SMX.onWall(p, n)
		rayParams.FilterDescendantsInstances = characterList()
		return workspace:Raycast(p + n * 0.5, -n * 1.5, rayParams) ~= nil
	end

	-- spider cracks on a wall: count jagged lines running out from r0 to
	-- about r1 round pos (n: out of the wall), growing out in grow s,
	-- gone after life; a few short ones joining them (the web)
	function SMX.cracks(pos, n, r0, r1, count, life, grow)
		local P = SMX.PAL
		local right, up = SMX.axes(n)
		count = SMX.n(count)
		grow = grow or 0.1
		local base = rand(0, math.pi * 2)
		local function seg(p1, p2, w, t0)
			local len = (p2 - p1).Magnitude
			if len < 0.05 then
				return
			end
			local c = newPart(Vector3.new(w, 0.05, 0.05), CFrame.lookAt(p1, p2, n), P.CRACK, Enum.Material.SmoothPlastic)
			c.Name = "SmashCrack"
			tween(c, grow / 3, { Size = Vector3.new(w, 0.05, len), CFrame = CFrame.lookAt((p1 + p2) / 2, p2, n) }, Enum.EasingStyle.Linear, nil, t0)
			tween(c, 0.6, { Transparency = 1 }, nil, nil, life)
			cleanup(c, life + 0.65)
		end
		-- (a crack runs only where there's wall: off its edge - the street,
		-- a window's gap - it stops)
		local function onWall(p)
			return SMX.onWall(p, n)
		end
		local ends = {}
		local wide = math.clamp(r1 / 7, 0.7, 1.2)
		for i = 1, count do
			local a = base + (i - 1) / count * math.pi * 2 + rand(-0.22, 0.22)
			local dir = right * math.cos(a) + up * math.sin(a)
			local side = n:Cross(dir)
			local reach = r1 * rand(0.7, 1.1)
			local last = pos + dir * r0
			for s = 1, 3 do
				local p = pos + dir * (r0 + (reach - r0) * s / 3) + side * rand(-0.35, 0.35) * (reach - r0) * 0.25
				if not onWall(p) then
					break
				end
				seg(last + n * (0.03 + i * 0.002), p + n * (0.03 + i * 0.002), (0.32 - 0.08 * s) * wide, grow * (s - 1) / 3)
				last = p
				if s == 2 then
					ends[i] = p
				end
			end
		end
		-- (the web: a few cross-cracks joining neighbours halfway out)
		for i = 1, count, 2 do
			local a, b = ends[i], ends[i % count + 1]
			if a and b then
				seg(a + n * 0.04, b + n * 0.04, 0.12, grow)
			end
		end
	end

	-- a crater in a wall: its dark floor, slabs broken round the rim and
	-- tipped out of it, a few lumps left in it; stays a while
	function SMX.crater(pos, n, R, color, stay)
		local P = SMX.PAL
		local right, up = SMX.axes(n)
		local wall = typeof(color) == "Color3" and color or P.CONCRETE
		stay = stay or 6
		local floor = newPart(Vector3.new(0.12, R * 1.7, R * 1.7), CFrame.lookAt(pos + n * 0.04, pos + n * 2) * CFrame.Angles(0, math.pi / 2, 0),
			wall:Lerp(P.CRATER, 0.75), Enum.Material.Slate, Enum.PartType.Cylinder)
		floor.Name = "SmashCrater"
		tween(floor, 1.2, { Transparency = 1 }, nil, nil, stay)
		cleanup(floor, stay + 1.3)
		local count = SMX.n(math.clamp(math.floor(R * 3), 7, 11))
		local base = rand(0, math.pi * 2)
		for i = 1, count do
			local a = base + (i - 0.5) / count * math.pi * 2 + rand(-0.15, 0.15)
			local out = right * math.cos(a) + up * math.sin(a)
			local w, h, t = rand(0.35, 0.55) * R, rand(0.18, 0.3) * R, rand(0.3, 0.55)
			local at = pos + out * R * rand(0.88, 1.05) + n * (t * 0.6)
			if not SMX.onWall(at, n) then
				continue -- (off the wall's edge)
			end
			-- (lying along the rim, its outer edge tipped up off the wall)
			local tang = n:Cross(out)
			local cf = CFrame.fromMatrix(at, tang, n, -out) * CFrame.Angles(math.rad(rand(18, 40)), 0, rand(-0.2, 0.2))
			local slab = newPart(Vector3.new(w, t, h), cf, wall:Lerp(P.CRATER, rand(0.15, 0.45)), Enum.Material.Slate)
			slab.Name = "SmashCrater"
			tween(slab, 1.2, { Transparency = 1 }, nil, nil, stay)
			cleanup(slab, stay + 1.3)
		end
		for _ = 1, SMX.n(4) do
			local s = rand(0.35, 0.8)
			local at = pos + (right * rand(-1, 1) + up * rand(-1, 1)) * R * 0.45 + n * 0.2
			local lump = newPart(Vector3.new(s * 1.3, s, s * 0.7), CFrame.new(at) * CFrame.Angles(rand(0, 6), rand(0, 6), rand(0, 6)), wall:Lerp(P.CRATER, 0.5), Enum.Material.Slate)
			lump.Name = "SmashCrater"
			tween(lump, 1.2, { Transparency = 1 }, nil, nil, stay)
			cleanup(lump, stay + 1.3)
		end
	end

	-- a burst of dust out along dir: n puffs, size k, rolling speed lo..hi
	function SMX.dust(pos, dir, k, n, lo, hi, life, color)
		local EK = VFX.EngineKit
		local P = SMX.PAL
		local h = EK.holder(CFrame.lookAt(pos, pos + dir), (life or 2) + 1.2, "SmashDust")
		h.Size = Vector3.new(2.5 * k, 2.5 * k, 1)
		local c = typeof(color) == "Color3" and color:Lerp(P.DUST, 0.55) or P.DUST
		local pe = EK.emitter(h, {
			tex = EK.TEX.smoke, color = { c, c:Lerp(P.DUST_DARK, 0.5) }, size = { { 0, 2.2 * k }, { 0.35, 5.5 * k }, { 1, 8 * k } },
			transp = { { 0, 0.05 }, { 0.6, 0.3 }, { 1, 1 } }, life = { (life or 2) * 0.7, life or 2 }, speed = { lo, hi }, spread = 38, drag = 2.6,
			accel = Vector3.new(0, 1.2, 0), influence = 0.85, spin = { -40, 40 },
		})
		pe.Shape = Enum.ParticleEmitterShape.Box
		pe:Emit(SMX.n(n))
		return pe
	end

	-- THROUGH: in at A (the wall's face Pad[1] on from it), out at B
	function SMX.through(char, data, isLocal)
		local a, b = data.A, data.B
		if not (SMX.vec(a) and SMX.vec(b)) then
			return
		end
		local DFX = VFX.DFX
		local EK = VFX.EngineKit
		local P = SMX.PAL
		local T = (Config.Smash or {}).Through or {}
		local d = SMX.vec(data.Dir) and data.Dir.Magnitude > 0.01 and data.Dir.Unit or ((b - a).Magnitude > 0.1 and (b - a).Unit or Vector3.new(0, 0, -1))
		local r = math.clamp(tonumber(data.R) or 3.4, 2, 12) -- ((round 87 review) a giant's hole is bigger)
		local into = math.clamp(tonumber(data.Into) or 120, 40, 400)
		local k = math.clamp(into / 140, 0.75, 1.6)
		local face = a + d * ((T.Pad or {})[1] or 1.4)
		local rubble = SMX.rubble(data.Color)
		local far = SMX.far(face, isLocal)
		-- the hit: a star on the wall, a shock flat on it, cracks out from the
		-- hole, grit back out of the entry
		EK.starSpark(face - d * 0.4, { color = P.SHOCK, color2 = P.WARM, size = 3 + r * 0.8 * k, life = 0.1 })
		if not isLocal then
			-- (not on his own screen: his camera comes through right behind him)
			shockDisc(face - d * 0.25, -d, r * 0.9, r * 3.4 * k, 0.26, P.SHOCK)
		end
		if not far then
			SMX.cracks(face - d * 0.06, -d, r * 0.95, r * 2.4 * k, 11, 4.5, 0.12)
			if DFX then
				DFX.chunks(face - d * 0.6, -d + UP * 0.35, 7, { spread = 0.9, speed = { 18, 42 }, size = { 0.35, 1.1 }, life = 1.8, colors = rubble })
			end
		end
		SMX.dust(face - d * 0.5, -d, 0.85 * k, 9, 8, 22, 1.6, data.Color)
		-- a beat later, out the far side: the wall blown out along his path,
		-- ahead of him (faster than he goes on: in front, not in his camera's way)
		task.delay(math.clamp((b - a).Magnitude / into, 0.03, 0.09), function()
			if DFX and not far then
				DFX.chunks(b, d, math.floor(13 * k), { spread = 0.6, speed = { 95 * k, 170 * k }, size = { 0.5, 1.7 }, up = 0.12, life = 2.8, colors = rubble })
				DFX.glass(b, d, data.Glass and 14 or 4)
			end
			SMX.dust(b, d, 1.35 * k, 20, 40 * k, 95 * k, 2.8, data.Color)
			if not isLocal then
				-- (not on his own screen: his camera goes through right there)
				shockDisc(b, d, r, r * 3.6, 0.3, P.SHOCK, 6)
				billboardRing(b, r, r * 4.2, P.SHOCK, 3, 0.3)
			end
		end)
		if DFX then
			DFX.plume(face + d * 0.8, 5, math.clamp(r / 4.2, 0.8, 1.4))
		end
		VFX.PlaySound("SmashThrough", face, math.clamp(0.7 + into / 400, 0.8, 1.3))
		-- who feels it
		local me = Players.LocalPlayer
		if isLocal then
			VFX.Shake(1.1, 0.3)
			EK.fovPunch(7, 0.04, 0.35, 0.03)
			VFX.Hooks.SpeedLines(0.3)
		elseif me and data.Attacker == me and (tonumber(data.N) or 1) <= 1 and nearCamera(face, 220) then
			VFX.ImpactFrame(0.045) -- (the one who threw him: subtle, the first wall)
			VFX.Shake(0.6, 0.2)
		else
			VFX.ShakeAt(face, 1.2, 110, 0.35)
		end
		if not far then
			SMX.track(char)
		end
	end

	-- SPLAT: the crater at Pos, him stuck in it for Hold s, then off it
	function SMX.splat(_char, data, isLocal)
		local pos, n = data.Pos, data.Normal
		if not (SMX.vec(pos) and SMX.vec(n)) or n.Magnitude < 0.5 then
			return
		end
		n = n.Unit
		local DFX = VFX.DFX
		local EK = VFX.EngineKit
		local P = SMX.PAL
		local SP = (Config.Smash or {}).Splat or {}
		local into = math.clamp(tonumber(data.Into) or 80, 30, 400)
		local k = math.clamp(into / 95, 0.75, 1.4)
		local hold = math.clamp(tonumber(data.Hold) or SP.Hold or 0.42, 0.05, 1.5)
		local R = (SP.Crater or 2.8) * k
		local rubble = SMX.rubble(data.Color)
		local far = SMX.far(pos, isLocal)
		if not far then
			SMX.crater(pos, n, R, data.Color, 6)
			SMX.cracks(pos, n, R * 0.9, R * 2.5, 12, 5, 0.1)
		end
		EK.starSpark(pos + n * 0.6, { color = P.SHOCK, color2 = P.WARM, size = 4.5 * k, life = 0.12 })
		shockDisc(pos + n * 0.3, n, 3, 10 * k, 0.26, P.SHOCK, 2)
		if DFX and not far then
			DFX.chunks(pos + n * 1.2, n + UP * 0.25, math.floor(9 * k), { spread = 0.8, speed = { 20, 55 }, size = { 0.35, 1.2 }, life = 2.2, colors = rubble })
		end
		SMX.dust(pos + n * 0.8, n, 0.8 * k, 9, 10, 26, 1.6, data.Color)
		VFX.PlaySound("SmashSplat", pos, math.clamp(0.75 + into / 300, 0.8, 1.3))
		-- grit trickling off the crater while he's stuck in it; a puff and a
		-- crumble as he comes off it
		-- ((round 87 review) looking straight down: its up given - out of the wall)
		local h = EK.holder(CFrame.lookAt(pos + n * 0.5, pos + n * 0.5 - UP, n), hold + 2, "SmashDust")
		h.Size = Vector3.new(R * 1.4, R * 1.4, 0.5)
		local grit = EK.emitter(h, {
			tex = EK.TEX.smoke, color = { (typeof(data.Color) == "Color3" and data.Color or P.DUST):Lerp(P.DUST, 0.5), P.DUST_DARK },
			size = { { 0, 0.5 }, { 1, 1.6 } }, transp = { { 0, 0.3 }, { 0.7, 0.55 }, { 1, 1 } }, life = { 0.6, 1 }, speed = { 1, 4 },
			spread = 25, accel = Vector3.new(0, -26, 0), drag = 1.2, influence = 0.9,
		})
		grit.Shape = Enum.ParticleEmitterShape.Box
		grit.Rate = SMX.n(26)
		task.delay(hold, function()
			grit.Enabled = false
			if DFX and not far then
				DFX.chunks(pos + n * 0.4, -UP + n * 0.2, 4, { spread = 0.4, speed = { 6, 16 }, size = { 0.3, 0.8 }, up = 0, life = 1.6, colors = rubble })
			end
			SMX.dust(pos + n * 0.6 - UP * 1.5, -UP + n * 0.3, 0.6 * k, 5, 4, 12, 1.4, data.Color)
			VFX.PlaySound("SmashCrumble", pos, 0.8)
		end)
		local me = Players.LocalPlayer
		if isLocal then
			VFX.Shake(1.5, 0.45)
			VFX.Hooks.Flash(Color3.new(1, 1, 1), 0.05)
		elseif me and data.Attacker == me and (tonumber(data.N) or 0) == 0 and nearCamera(pos, 220) then
			VFX.ImpactFrame(0.05) -- (the first wall he met: the one who threw him)
			VFX.Shake(0.7, 0.25)
		else
			VFX.ShakeAt(pos, 1.3, 100, 0.4)
		end
	end

	-- after a body that's gone through a wall: dust and grit off it while
	-- it flies, and where it comes down in the street a skid (dust kicked
	-- up, scrapes left on the street); over once it's slowed down
	function SMX.track(char)
		local root = charParts(char)
		if not root then
			return
		end
		local st = SMX.trails[char]
		if st then
			st.t0 = os.clock() -- (another wall: a while longer)
			return
		end
		local EK = VFX.EngineKit
		local P = SMX.PAL
		local SKD = (Config.Smash or {}).Skid or {}
		local torso = char:FindFirstChild("Torso") or char:FindFirstChild("UpperTorso") or root
		local att = Instance.new("Attachment")
		att.Name = "SmashTrail"
		att.Parent = torso
		local pe = EK.emitter(att, {
			tex = EK.TEX.smoke, color = { P.DUST, P.DUST_DARK }, size = { { 0, 1 }, { 0.5, 2.6 }, { 1, 4 } },
			transp = { { 0, 0.35 }, { 0.7, 0.6 }, { 1, 1 } }, life = { 0.6, 1.1 }, speed = { 1, 4 }, spread = 180, drag = 2,
			accel = Vector3.new(0, 1.5, 0), influence = 0.9, spin = { -30, 30 },
		})
		st = { t0 = os.clock(), skidAt = 0, shedAt = 0, slowAt = nil, att = att, pe = pe }
		SMX.trails[char] = st
		task.spawn(function()
			while SMX.trails[char] == st and char.Parent and root.Parent and torso.Parent and os.clock() - st.t0 < 2.6 do
				local now = os.clock()
				local v = root.AssemblyLinearVelocity
				local speed = v.Magnitude
				pe.Rate = speed > 30 and SMX.n(math.floor(math.min(speed, 200) * 0.22)) or 0
				-- grit shed off him for a moment after each wall
				if speed > 50 and now - st.t0 < 0.6 and now - st.shedAt > 0.12 and VFX.DFX then
					st.shedAt = now
					VFX.DFX.chunks(torso.Position, -v.Unit + UP * 0.3, 1, { spread = 0.6, speed = { 5, 15 }, size = { 0.25, 0.6 }, life = 1.2 })
				end
				-- down in the street, sliding: the skid
				local across = Vector3.new(v.X, 0, v.Z)
				if across.Magnitude > (SKD.Speed or 24) and now - st.skidAt > (SKD.Every or 0.07) then
					local hit = groundRay(torso.Position, (SKD.Height or 3.4) + 3) -- (the ray starts 3 over it)
					if hit and torso.Position.Y - hit.Position.Y < (SKD.Height or 3.4) then
						st.skidAt = now
						local g = hit.Position
						local dust = (hit.Instance and hit.Instance:IsA("BasePart")) and hit.Instance.Color:Lerp(P.DUST, 0.6) or P.DUST
						dustPuffs(g + UP * 0.2, 0.35, SMX.n(2), dust, 0.7, false)
						local fd = across.Unit
						local len = math.clamp(across.Magnitude * 0.08, 1.2, 5)
						local mark = newPart(Vector3.new(rand(0.25, 0.45), 0.05, len), CFrame.lookAt(g + UP * 0.04, g + UP * 0.04 + fd) * CFrame.new(0, 0, len / 2),
							P.SCRAPE, Enum.Material.SmoothPlastic)
						mark.Name = "SmashScrape"
						mark.Transparency = 0.25
						tween(mark, 1, { Transparency = 1 }, nil, nil, 3)
						cleanup(mark, 4.1)
						VFX.PlaySound("SmashSkid", g, math.clamp(across.Magnitude / 80, 0.5, 1))
					end
				end
				if speed < 15 then
					st.slowAt = st.slowAt or now
					if now - st.slowAt > 0.25 then
						break
					end
				else
					st.slowAt = nil
				end
				task.wait()
			end
			if SMX.trails[char] == st then
				SMX.trails[char] = nil
			end
			pe.Enabled = false
			cleanup(att, 1.2)
		end)
	end

	function Effects.Smash(char, data, isLocal)
		if data.Kind == "Through" then
			SMX.through(char, data, isLocal)
		elseif data.Kind == "Splat" then
			SMX.splat(char, data, isLocal)
		end
	end
end

---------------------------------------------------------------------------
-- (round 87) ADMIN-ABUSE EVENTS (Config.AdminEvents) in the world, on every
-- screen. The server sends the beats: a meteor's red ring (Effects.
-- AdminMeteor: the ring of dashes turning, the shadow filling it, the rock
-- falling out of the sky on its fire trail and smoke, the impact - the
-- game's own cel explosion, a shock ring, molten cracks, rocks, smoke, the
-- rock left glowing in the street and cooling), the bills (AdminBills:
-- they flutter down rocking and lie there glinting; AdminBillTaken: one
-- zips to whoever got it), a body growing or shrinking (AdminResize; your
-- own camera eases out / in to fit), a hero dealt (AdminShuffled). What's
-- running (QuirkClient reads it off workspace) sets the sky (AV.setLook:
-- an event's own ColorCorrection, the time of day, the Atmosphere, the
-- moon - each given back after, unless someone's changed it since) and the
-- loops (AV.ambient: meteors streaking far off across the sky, motes
-- drifting up in low gravity, a giant's footfalls shaking the street).
-- Half as much on a low-end machine. AV.clear() takes every trace away.
-- (Its own function: the main chunk is at its local limit, and a do block's
-- locals still count against it.)
---------------------------------------------------------------------------
VFX.AE = {}
;(function()
	local AV = VFX.AE
	for k, v in {
		AEC = Config.AdminEvents or {},
		bills = {}, -- [id] = a bill falling / lying there
		saved = {}, -- [instance] = { [property] = { Base, Mine, Until } }. (round 87, in Studio) not weak: the engine dropped Lighting's entry while it lived, and the meteor sky never went back
		amb = {}, -- what the loops hold (AV.ambient)
		stepAt = {}, -- [body] = its last footfall (cleared as the loop stops)
		ids = {}, -- what's running (in Order)
		PAL = {
			RING = Color3.fromRGB(255, 46, 36), FILL = Color3.fromRGB(64, 8, 8), ROCK = Color3.fromRGB(54, 42, 40),
			CORE = Color3.fromRGB(255, 120, 30), HOT = Color3.fromRGB(255, 196, 90), SMOKE = Color3.fromRGB(70, 58, 56),
			MOLTEN = Color3.fromRGB(255, 104, 34), BILL = Color3.fromRGB(96, 176, 96), INK = Color3.fromRGB(24, 82, 34),
			MOTE = Color3.fromRGB(226, 220, 255), DUST = Color3.fromRGB(176, 164, 150),
		},
		SLANT = Vector3.new(0.86, 0, 0.5), -- (meteors all come in from the same side of the sky)
	} do
		AV[k] = v
	end
	local EK = VFX.EngineKit
	local PAL = AV.PAL
	local function def(id)
		return AV.AEC.Events and AV.AEC.Events[id] or nil
	end
	local function low()
		return EK and EK.lowEnd() or false
	end
	local function count(n)
		return EK and EK.count(n) or n
	end

	---------------------------------------------------------------- meteors
	-- the red ring: dashes round the edge (turning), a faint disc over the
	-- area and the shadow filling it - when the shadow's full, it lands
	function AV.ring(pos, R, warnTime)
		local model = Instance.new("Model")
		model.Name = "AdminMeteorRing"
		model.Parent = folder
		local n = low() and 10 or 18
		local dashes = {}
		for i = 1, n do
			local seg = newPart(Vector3.new(0.4, 0.14, 2 * math.pi * R / n * 0.6), CFrame.new(pos), PAL.RING, Enum.Material.Neon, nil, model)
			seg.Name = "Dash"
			table.insert(dashes, { seg, (i - 1) / n * math.pi * 2 })
		end
		local flat = CFrame.new(pos + UP * 0.08) * CFrame.Angles(0, 0, math.rad(90))
		local area = newPart(Vector3.new(0.1, R * 2, R * 2), flat, PAL.RING, Enum.Material.Neon, Enum.PartType.Cylinder, model)
		area.Name = "Area"
		area.Transparency = 0.82
		local shadow = newPart(Vector3.new(0.12, 0.2, 0.2), flat + UP * 0.02, PAL.FILL, Enum.Material.SmoothPlastic, Enum.PartType.Cylinder, model)
		shadow.Name = "Shadow"
		shadow.Transparency = 0.35
		tween(shadow, warnTime, { Size = Vector3.new(0.12, R * 2, R * 2) }, Enum.EasingStyle.Quad, Enum.EasingDirection.In)
		local ring = { model = model, dashes = dashes, area = area, shadow = shadow, pos = pos, R = R }
		function ring.place(t)
			local spin = t * 1.6
			local pulse = 0.5 + 0.5 * math.cos(t * 18)
			for _, d in dashes do
				local a = d[2] + spin
				local at = pos + Vector3.new(math.cos(a) * R, 0.12, math.sin(a) * R)
				local tangent = Vector3.new(-math.sin(a), 0, math.cos(a))
				d[1].CFrame = CFrame.lookAt(at, at + tangent)
				d[1].Transparency = 0.05 + 0.3 * pulse
			end
		end
		ring.place(0)
		return ring
	end
	-- the rock: dark basalt round a molten core, a fire trail and smoke behind
	-- (far: no fire emitter and no light - a speck in the sky either way)
	function AV.rock(cf, far)
		local model = Instance.new("Model")
		model.Name = "AdminMeteor"
		model.Parent = folder
		-- (big and bright: it has to read against the sky from the street, 300 studs below it)
		local rock = newPart(Vector3.new(6.4, 5.6, 6), cf, PAL.ROCK, Enum.Material.Basalt, nil, model)
		rock.Name = "Rock"
		local core = newPart(Vector3.one * 7.6, cf, PAL.CORE, Enum.Material.Neon, Enum.PartType.Ball, model)
		core.Name = "Core"
		core.Transparency = 0.35
		local halo = newPart(Vector3.one * 12, cf, PAL.HOT, Enum.Material.Neon, Enum.PartType.Ball, model)
		halo.Name = "Halo"
		halo.Transparency = 0.72
		local a0, a1 = Instance.new("Attachment"), Instance.new("Attachment")
		a0.CFrame = CFrame.new(0, 4.2, 0)
		a1.CFrame = CFrame.new(0, -4.2, 0)
		a0.Parent, a1.Parent = core, core
		local trail = Instance.new("Trail")
		trail.Name = "Fire"
		trail.Attachment0, trail.Attachment1 = a0, a1
		trail.FaceCamera = true
		trail.Lifetime = 0.55
		trail.LightEmission = 0.9
		trail.Color = ColorSequence.new({ ColorSequenceKeypoint.new(0, PAL.HOT), ColorSequenceKeypoint.new(0.35, PAL.CORE), ColorSequenceKeypoint.new(1, PAL.SMOKE) })
		trail.Transparency = NumberSequence.new({ NumberSequenceKeypoint.new(0, 0.05), NumberSequenceKeypoint.new(0.6, 0.45), NumberSequenceKeypoint.new(1, 1) })
		trail.WidthScale = NumberSequence.new({ NumberSequenceKeypoint.new(0, 1.15), NumberSequenceKeypoint.new(1, 0.35) })
		trail.Parent = core
		local smoke, fire
		if EK then
			smoke = EK.emitter(core, {
				tex = EK.TEX.smoke, color = { PAL.SMOKE, Color3.fromRGB(40, 34, 34) }, size = { { 0, 5 }, { 1, 13 } },
				transp = { { 0, 0.3 }, { 0.6, 0.6 }, { 1, 1 } }, life = { 0.8, 1.2 }, speed = { 4, 9 }, spread = 30, influence = 0.8, spin = { -40, 40 }, dir = "Back",
			})
			smoke.Rate = (low() or far) and 18 or 40
			if not low() and not far then
				fire = EK.emitter(core, {
					tex = EK.TEX.fire, color = { PAL.HOT, PAL.CORE }, size = { { 0, 8 }, { 1, 2.5 } },
					transp = { { 0, 0.1 }, { 1, 1 } }, life = { 0.2, 0.32 }, speed = { 3, 8 }, spread = 22, light = 1, dir = "Back",
				})
				fire.Rate = 60
				local light = Instance.new("PointLight")
				light.Color = PAL.CORE
				light.Range = 36
				light.Brightness = 3
				light.Parent = core
			end
		end
		return { model = model, rock = rock, core = core, halo = halo, trail = trail, smoke = smoke, fire = fire }
	end
	-- the impact (pos: the street / roof it lands on; R: the ring's radius).
	-- far: (round 87 review) past Draw.Near from your camera - the blast and
	-- its sound only
	function AV.impact(pos, R, far)
		local small = low()
		toonExplosion(pos + UP * 1.6, 1.35, { NoDebris = true })
		if far then
			groundMark(pos, R * 0.55, Color3.fromRGB(30, 22, 20), 9)
			VFX.PlaySound("AdminMeteorImpact", pos, 1)
			return
		end
		shockDisc(pos + UP * 0.5, UP, 3, R * 3.4, 0.5, Color3.fromRGB(255, 226, 200))
		if EK then
			EK.cracks(pos, R * 0.95, small and 6 or 10, { glow = PAL.MOLTEN, rocks = small and 4 or 9, life = 5 })
			EK.cloud(pos, 1.7, Color3.fromRGB(96, 80, 74), 0.7, not small)
		end
		dustPuffs(pos + UP * 0.6, 1, small and 3 or 6, Color3.fromRGB(112, 102, 98), 1.4, true)
		emberCloud(pos + UP * 3, R * 0.7, 1.3, small and 14 or 34)
		groundMark(pos, R * 0.55, Color3.fromRGB(30, 22, 20), 9)
		-- the rock itself, left in the street, glowing, cooling
		local chunk = newPart(Vector3.new(3.4, 2.4, 3), CFrame.new(pos + UP * 0.7) * CFrame.Angles(rand(-0.5, 0.5), rand(0, 6.28), rand(-0.5, 0.5)), PAL.MOLTEN, Enum.Material.Neon)
		chunk.Name = "AdminMeteorChunk"
		tween(chunk, 1.6, { Color = Color3.fromRGB(160, 50, 22) }, Enum.EasingStyle.Sine)
		task.delay(1.6, function()
			if chunk.Parent then
				chunk.Material = Enum.Material.Basalt
				chunk.Color = Color3.fromRGB(96, 40, 26)
				tween(chunk, 3, { Color = PAL.ROCK }, Enum.EasingStyle.Sine)
				tween(chunk, 0.8, { Size = Vector3.new(0.4, 0.3, 0.4), Transparency = 1 }, Enum.EasingStyle.Quad, Enum.EasingDirection.In, 6)
			end
		end)
		cleanup(chunk, 8)
		VFX.ShakeAt(pos, 4, R * 12, 0.55)
		local cam = workspace.CurrentCamera
		if cam and (cam.Focus.Position - pos).Magnitude < R * 2.6 then
			VFX.Hooks.Flash(Color3.fromRGB(255, 170, 110), 0.15)
		end
		VFX.PlaySound("AdminMeteorImpact", pos, 1)
	end
	-- data: Pos (where it lands), Warn (s till then), Radius, Height
	function Effects.AdminMeteor(_, data)
		local pos = data.Pos
		if typeof(pos) ~= "Vector3" then
			return
		end
		local warnTime = math.clamp(tonumber(data.Warn) or 1.15, 0.3, 4)
		local R = math.clamp(tonumber(data.Radius) or 10, 2, 40)
		local H = math.clamp(tonumber(data.Height) or 420, 60, 1200)
		-- (round 87 review) by how far from your camera it lands (Draw): with a
		-- full server that's three a second, all over the city, on every screen
		local D = (def("Meteor") or {}).Draw or {}
		local cam = workspace.CurrentCamera
		local away = cam and (cam.CFrame.Position - pos).Magnitude or 0
		local reach = low() and 0.5 or 1
		if away > (D.Far or 1300) * reach then
			return
		end
		local far = away > (D.Near or 420) * reach
		local ring = (not far) and AV.ring(pos, R, warnTime) or nil
		local top = pos + AV.SLANT * H * 0.42 + UP * H
		local m = AV.rock(CFrame.new(top), far)
		local spin = Vector3.new(rand(4, 8), rand(3, 6), rand(-3, 3))
		VFX.PlaySound("AdminMeteorFall", pos, 1)
		local t0 = os.clock()
		while true do
			local t = os.clock() - t0
			if t >= warnTime or not m.model.Parent then
				break
			end
			local k = (t / warnTime) ^ 1.15
			local at = top:Lerp(pos + UP * 1.5, k)
			local cf = CFrame.new(at) * CFrame.Angles(spin.X * t, spin.Y * t, spin.Z * t)
			m.rock.CFrame = cf
			m.core.CFrame = CFrame.lookAt(at, at + (pos - top).Unit)
			m.halo.CFrame = m.core.CFrame
			if ring then
				ring.place(t)
			end
			task.wait()
		end
		-- (the rock's gone into the street: its trail and smoke die off behind it)
		m.rock:Destroy()
		m.halo:Destroy()
		m.core.Transparency = 1
		m.trail.Enabled = false
		if m.smoke then
			m.smoke.Enabled = false
		end
		if m.fire then
			m.fire.Enabled = false
		end
		cleanup(m.model, 1.2)
		-- the ring bursts out and goes
		if ring then
			ring.shadow.Color = Color3.new(1, 0.9, 0.8)
			tween(ring.shadow, 0.3, { Transparency = 1 })
			tween(ring.area, 0.3, { Transparency = 1 })
			for _, d in ring.dashes do
				local seg = d[1]
				local out = Vector3.new(seg.CFrame.Position.X - pos.X, 0, seg.CFrame.Position.Z - pos.Z)
				out = out.Magnitude > 0.01 and out.Unit or Vector3.new(1, 0, 0)
				tween(seg, 0.3, { CFrame = seg.CFrame + out * R * 0.5, Transparency = 1 })
			end
			cleanup(ring.model, 0.4)
		end
		AV.impact(pos, R, far)
	end

	---------------------------------------------------------------- the bills
	local function billPart(cf)
		-- (a big bill - 2.4 studs: it has to read from a fighter's camera, 15 studs off)
		local p = newPart(Vector3.new(2.4, 0.08, 1.1), cf, PAL.BILL, Enum.Material.SmoothPlastic)
		p.Name = "AdminBill"
		if low() then
			return p -- (a low-end machine: a plain green bill, no "$" drawn on it)
		end
		local sg = Instance.new("SurfaceGui")
		sg.Face = Enum.NormalId.Top
		sg.CanvasSize = Vector2.new(240, 110)
		sg.LightInfluence = 0.6
		sg.Parent = p
		local frame = Instance.new("Frame")
		frame.Size = UDim2.new(1, -12, 1, -12)
		frame.Position = UDim2.fromOffset(6, 6)
		frame.BackgroundTransparency = 1
		frame.Parent = sg
		local edge = Instance.new("UIStroke")
		edge.Color = PAL.INK
		edge.Thickness = 3
		edge.Transparency = 0.2
		edge.Parent = frame
		local label = Instance.new("TextLabel")
		label.Size = UDim2.fromScale(1, 1)
		label.BackgroundTransparency = 1
		label.Font = Enum.Font.Bangers
		label.TextScaled = true
		label.TextColor3 = PAL.INK
		label.Text = "$"
		label.Parent = frame
		return p
	end
	-- the loop that drives every bill (one, however many there are)
	function AV.billLoop()
		if AV.billsRunning then
			return
		end
		AV.billsRunning = true
		task.spawn(function()
			while next(AV.bills) ~= nil do
				local now = os.clock()
				local me = Players.LocalPlayer
				local full = me and (me:GetAttribute("EventBills") or 0) >= ((def("MoneyRain") or {}).Cap or 8)
				for id, b in AV.bills do
					local p = b.part
					if not p.Parent then
						AV.bills[id] = nil
					elseif b.zip then
						-- (taken: it zips to whoever got it)
					else
						local t = now - b.t0
						if t < b.fall then
							local k = t / b.fall
							local sway = math.sin(t * b.rate + b.phase)
							local at = b.from:Lerp(b.pos + UP * 0.1, k) + b.side * sway * 2.2 * (1 - k)
							p.CFrame = CFrame.new(at) * CFrame.Angles(0, b.yaw + t * 1.3, 0) * CFrame.Angles(sway * 0.9, 0, math.cos(t * b.rate * 0.7) * 0.5)
						elseif t < b.fall + b.life then
							-- lying there: a slow turn, a glint
							local lt = t - b.fall
							p.CFrame = CFrame.new(b.pos + UP * (0.12 + 0.08 * math.sin(lt * 3 + b.phase))) * CFrame.Angles(0, b.yaw + lt * 0.6, 0)
							if not b.glint and b.sparkle then
								b.glint = true
								b.sparkle.Rate = 1.4
							end
							p.Transparency = full and 0.6 or 0
						else
							AV.bills[id] = nil
							tween(p, 0.4, { Transparency = 1, Size = Vector3.new(0.4, 0.05, 0.2) })
							cleanup(p, 0.45)
						end
					end
				end
				task.wait()
			end
			AV.billsRunning = false
		end)
	end
	-- data: List = { { Id, Pos } }, Fall, Life - or Clear = true (it's over)
	function Effects.AdminBills(_, data)
		if data.Clear then
			AV.clearBills(true)
			return
		end
		local fall = math.clamp(tonumber(data.Fall) or 2.4, 0.3, 8)
		local life = math.clamp(tonumber(data.Life) or 14, 1, 60)
		for i, e in type(data.List) == "table" and data.List or {} do
			if type(e) == "table" and typeof(e.Pos) == "Vector3" and e.Id ~= nil and not AV.bills[e.Id] then
				local side = Vector3.new(rand(-1, 1), 0, rand(-1, 1))
				side = side.Magnitude > 0.05 and side.Unit or Vector3.new(1, 0, 0)
				local from = e.Pos + UP * rand(48, 62) + side * rand(4, 10)
				local p = billPart(CFrame.new(from))
				local sparkle
				if EK and not (low() and i % 2 == 0) then
					sparkle = EK.emitter(p, {
						tex = EK.TEX.spark, color = Color3.fromRGB(255, 250, 200), size = { { 0, 1.4 }, { 1, 0 } },
						transp = { { 0, 0.1 }, { 1, 1 } }, life = { 0.35, 0.5 }, speed = { 0, 0 }, light = 1, bright = 2,
					})
				end
				AV.bills[e.Id] = {
					part = p, sparkle = sparkle, from = from, pos = e.Pos, side = side, t0 = os.clock() - (i - 1) * 0.07,
					fall = fall, life = life, rate = rand(3.2, 4.4), phase = rand(0, 6.28), yaw = rand(0, 6.28),
				}
			end
		end
		AV.billLoop()
	end
	-- data: Id, By (the player), Value, Got / Cap (theirs)
	function Effects.AdminBillTaken(char, data)
		local b = AV.bills[data.Id]
		local root = typeof(char) == "Instance" and char:FindFirstChild("HumanoidRootPart")
		local me = Players.LocalPlayer
		local mine = me ~= nil and data.By == me
		if b then
			AV.bills[data.Id] = nil
			b.zip = true
			local p = b.part
			if root then
				tween(p, 0.18, { CFrame = root.CFrame, Size = Vector3.new(0.6, 0.05, 0.3) }, Enum.EasingStyle.Quad, Enum.EasingDirection.In)
			end
			tween(p, 0.1, { Transparency = 1 }, nil, nil, 0.16)
			cleanup(p, 0.3)
			if root then
				task.delay(0.17, function()
					sparks(root.Position, 0.5, Color3.fromRGB(200, 255, 200), PAL.BILL, mine and 14 or 6)
				end)
			end
		end
		if mine then
			VFX.PlaySound("AdminBillGrab", nil, 1)
		elseif root then
			VFX.PlaySound("AdminBillGrab", root.Position, 0.5)
		end
	end
	function AV.clearBills(poof)
		for id, b in AV.bills do
			AV.bills[id] = nil
			local p = b.part
			if p.Parent then
				if poof then
					tween(p, 0.35, { Transparency = 1, Size = Vector3.new(0.3, 0.05, 0.15) })
					cleanup(p, 0.4)
				else
					p:Destroy()
				end
			end
		end
	end

	------------------------------------------------- bodies: resized, dealt a hero
	-- data: From / To (the body's scale before and after)
	function Effects.AdminResize(char, data)
		local root = typeof(char) == "Instance" and char:FindFirstChild("HumanoidRootPart")
		if not root then
			return
		end
		local from, to = tonumber(data.From) or 1, tonumber(data.To) or 1
		local up = to > from
		local feet = root.Position - UP * 3 * to
		shockDisc(feet + UP * 0.3, UP, 2 * to, 14 * math.max(to, 1), 0.45, up and Color3.fromRGB(255, 220, 160) or Color3.fromRGB(190, 255, 210))
		dustPuffs(feet + UP * 0.4, 0.7 * math.max(to, 0.6), low() and 3 or 6, PAL.DUST, 1.1, true)
		billboardRing(root.Position, 4 * from, 9 * math.max(to, 1), up and Color3.fromRGB(255, 170, 60) or Color3.fromRGB(110, 225, 150), 6, 0.4)
		VFX.PlaySound(up and "AdminGrow" or "AdminShrink", root.Position, 1)
		if up then
			VFX.ShakeAt(feet, 2.4, 80, 0.4)
		end
		local me = Players.LocalPlayer
		if me and me.Character == char then
			AV.zoomFor(from, to)
		end
	end
	-- your own camera eases out for a bigger body (in for a smaller one):
	-- the zoom's least (or most) pushed for a moment, then given back
	function AV.zoomFor(from, to)
		local me = Players.LocalPlayer
		local cam = workspace.CurrentCamera
		if not me or not cam or VFX.InCinematic() or me.CameraMode == Enum.CameraMode.LockFirstPerson then
			return
		end
		local dist = (cam.CFrame.Position - cam.Focus.Position).Magnitude
		if dist < 1 then
			return
		end
		-- (not all the way: x(to / from)^0.7 - a giant still fills a little
		-- more of the screen and the street looks small round him; a tiny one
		-- the other way: r87/out/events_giant_camera.png)
		local want = math.clamp(dist * (to / math.max(from, 0.1)) ^ 0.7, 6, 60)
		-- (round 87 review) inside the place's own zoom range: a min pushed past
		-- the max (or a max under the min) has the engine move the other one,
		-- which nothing would give back
		want = math.clamp(want, me.CameraMinZoomDistance, math.max(me.CameraMinZoomDistance, me.CameraMaxZoomDistance))
		local key = want > dist and "CameraMinZoomDistance" or "CameraMaxZoomDistance"
		local was = me[key]
		AV.zoomToken = (AV.zoomToken or 0) + 1
		local token = AV.zoomToken
		me[key] = want
		task.delay(0.3, function()
			if AV.zoomToken == token then
				me[key] = was
			end
		end)
	end
	-- data: Hero (what they were dealt)
	function Effects.AdminShuffled(char, data)
		local root = typeof(char) == "Instance" and char:FindFirstChild("HumanoidRootPart")
		local q = Config.Quirks[tostring(data.Hero or "")]
		if not root or not q then
			return
		end
		local color = q.Color or Color3.new(1, 1, 1)
		billboardRing(root.Position, 3, 14, color, 8, 0.45)
		sparks(root.Position, 0.8, color:Lerp(Color3.new(1, 1, 1), 0.5), color, low() and 10 or 22)
		smokeBurst(root.Position - UP * 1.5, color:Lerp(Color3.new(1, 1, 1), 0.6), 3, 4, 0.5, low() and 8 or 16)
		local me = Players.LocalPlayer
		if me and me.Character == char then
			return -- (your own screen has the reel)
		end
		-- (everyone else: the new name over their head)
		local bb = Instance.new("BillboardGui")
		bb.Name = "AdminShuffledName"
		bb.Size = UDim2.fromOffset(220, 40)
		bb.StudsOffset = Vector3.new(0, 4.2, 0)
		bb.AlwaysOnTop = true
		bb.MaxDistance = 140
		bb.Adornee = root
		bb.Parent = folder
		local label = Instance.new("TextLabel")
		label.Size = UDim2.fromScale(1, 1)
		label.BackgroundTransparency = 1
		label.Font = Enum.Font.Bangers
		label.TextScaled = true
		label.TextColor3 = color:Lerp(Color3.new(1, 1, 1), 0.25)
		label.TextStrokeTransparency = 0.2
		label.Text = string.upper(q.DisplayName or tostring(data.Hero))
		label.Parent = bb
		tween(bb, 1.6, { StudsOffset = Vector3.new(0, 6.5, 0) }, Enum.EasingStyle.Sine)
		tween(label, 0.5, { TextTransparency = 1, TextStrokeTransparency = 1 }, nil, nil, 1.2)
		cleanup(bb, 1.8)
	end

	---------------------------------------------------------------- the sky
	local function same(a, b)
		if typeof(a) == "Color3" and typeof(b) == "Color3" then
			return math.abs(a.R - b.R) + math.abs(a.G - b.G) + math.abs(a.B - b.B) < 0.02
		elseif type(a) == "number" and type(b) == "number" then
			return math.abs(a - b) < 0.02
		end
		return a == b
	end
	-- one property: want (put it there - its own value saved the first time),
	-- or nil (give it back, if it still holds what we put there). force:
	-- (round 87 review) after the Vestige Realm put its snapshot back - ours,
	-- or ours half-way through a tween - put ours there again / give it back
	-- whatever it holds
	function AV.prop(inst, key, want, time, force)
		if not inst then
			return
		end
		local recs = AV.saved[inst]
		local rec = recs and recs[key]
		local now = os.clock()
		if want ~= nil then
			if not rec then
				local ok, base = pcall(function()
					return inst[key]
				end)
				if not ok then
					return
				end
				recs = recs or {}
				AV.saved[inst] = recs
				rec = { Base = base }
				recs[key] = rec
			end
			if force or rec.Mine == nil or not same(rec.Mine, want) then
				rec.Mine = want
				rec.Until = now + (time or 2.5) + 0.1
				pcall(tween, inst, time or 2.5, { [key] = want }, Enum.EasingStyle.Sine, Enum.EasingDirection.InOut)
			end
		elseif rec then
			recs[key] = nil
			if next(recs) == nil then
				AV.saved[inst] = nil
			end
			local ok, cur = pcall(function()
				return inst[key]
			end)
			if ok and (force or same(cur, rec.Mine) or now < (rec.Until or 0)) then
				pcall(tween, inst, time or 2.5, { [key] = rec.Base }, Enum.EasingStyle.Sine, Enum.EasingDirection.InOut)
			end
		end
	end
	-- (round 87 review) THE VESTIGE REALM (VFX.VR) swaps the lighting for its
	-- own dark while you're in it and puts back what it found as you leave. An
	-- event's sky waits outside it: nothing's changed in there, and once
	-- you're out (its snapshot back - which may be ours, even half-tweened,
	-- after an event that ended meanwhile) ours is put right, or given back.
	-- Without it, BLOOD MOON's night stayed for good after an event ended
	-- while you were inside.
	-- ((round 99) SPACE holds this screen's sky the same way while you're up
	-- there (VFX.SPX.held): an event's sky waits till you're back down)
	function AV.realmOn()
		return (VFX.VR ~= nil and VFX.VR.on == true) or (VFX.SPX ~= nil and VFX.SPX.held == true)
	end
	function AV.realmWatch()
		if AV.realmWatching then
			return
		end
		AV.realmWatching = true
		task.spawn(function()
			local was = AV.realmOn()
			while next(AV.saved) ~= nil or #AV.ids > 0 or was do
				task.wait(0.25)
				local on = AV.realmOn()
				if was and not on then
					AV.setLook(AV.ids, true)
				end
				was = on
			end
			AV.realmWatching = false
		end)
	end
	-- ids: what's running, in Order. force: after the realm (AV.prop)
	function AV.setLook(ids, force)
		AV.realmWatch()
		if AV.realmOn() then
			return -- (inside the realm: once you're out)
		end
		local L = game:GetService("Lighting")
		local tint, bright, contrast, sat = Color3.new(1, 1, 1), 0, 0, 0
		local clock, atmo, moon, stars, ambient
		local any = false
		for _, id in ids do
			local look = (def(id) or {}).Look
			if type(look) == "table" then
				any = true
				if typeof(look.Tint) == "Color3" then
					tint = Color3.new(tint.R * look.Tint.R, tint.G * look.Tint.G, tint.B * look.Tint.B)
				end
				bright += tonumber(look.Brightness) or 0
				contrast += tonumber(look.Contrast) or 0
				sat += tonumber(look.Saturation) or 0
				clock = tonumber(look.Clock) or clock
				atmo = type(look.Atmo) == "table" and look.Atmo or atmo
				moon = tonumber(look.Moon) or moon
				stars = tonumber(look.Stars) or stars
				ambient = typeof(look.Ambient) == "Color3" and look.Ambient or ambient
			end
		end
		-- the grade: an effect of its own (stacked on whatever else is there)
		local cc = L:FindFirstChild("AdminEventGrade")
		if any and not cc then
			cc = Instance.new("ColorCorrectionEffect")
			cc.Name = "AdminEventGrade"
			cc.Parent = L
		end
		if cc then
			AV.gradeToken = (AV.gradeToken or 0) + 1
			local token = AV.gradeToken
			tween(cc, 2.2, { TintColor = tint, Brightness = bright, Contrast = contrast, Saturation = sat }, Enum.EasingStyle.Sine, Enum.EasingDirection.InOut)
			if not any then
				task.delay(2.3, function()
					if AV.gradeToken == token and cc.Parent then
						cc:Destroy()
					end
				end)
			end
		end
		-- the time of day, the air, the moon and the stars
		AV.prop(L, "ClockTime", clock, 3, force)
		AV.prop(L, "OutdoorAmbient", ambient, 3, force)
		local air = L:FindFirstChildOfClass("Atmosphere")
		for _, key in { "Color", "Decay", "Density", "Haze", "Glare" } do
			AV.prop(air, key, atmo and atmo[key] or nil, nil, force)
		end
		local sky = L:FindFirstChildOfClass("Sky")
		if sky then
			local recs = AV.saved[sky]
			local base = recs and recs.MoonAngularSize and recs.MoonAngularSize.Base or sky.MoonAngularSize
			AV.prop(sky, "MoonAngularSize", moon and base * moon or nil, nil, force)
			AV.prop(sky, "StarCount", stars and math.floor(stars) or nil, nil, force)
		end
	end

	---------------------------------------------------------------- the loops
	-- far-off meteors streaking down the sky (cosmetic: no ring, no harm)
	function AV.skyStreak()
		local cam = workspace.CurrentCamera
		if not cam then
			return
		end
		local c = cam.CFrame.Position
		local a, dist = rand(0, math.pi * 2), rand(320, 620)
		local start = c + Vector3.new(math.cos(a) * dist, rand(170, 300), math.sin(a) * dist)
		local dir = (UP * -1 - AV.SLANT * 0.42).Unit
		-- (wide enough to read at 300-600 studs: ~5 px at 720p)
		local len = rand(90, 130)
		local p = newPart(Vector3.new(4.5, 4.5, len), CFrame.lookAt(start, start + dir), PAL.HOT, Enum.Material.Neon)
		p.Name = "AdminSkyStreak"
		p.Transparency = 0.15
		local head = newPart(Vector3.one * 9, CFrame.new(start + dir * len * 0.5), PAL.CORE, Enum.Material.Neon, Enum.PartType.Ball)
		head.Name = "AdminSkyStreak"
		local travel = rand(200, 300)
		local life = rand(0.9, 1.3)
		tween(p, life, { CFrame = CFrame.lookAt(start + dir * travel, start + dir * (travel + 1)), Transparency = 1, Size = Vector3.new(1, 1, len * 1.6) }, Enum.EasingStyle.Linear)
		tween(head, life, { CFrame = CFrame.new(start + dir * (travel + len * 0.5)), Transparency = 1, Size = Vector3.one * 1.5 }, Enum.EasingStyle.Linear)
		cleanup(p, life + 0.05)
		cleanup(head, life + 0.05)
	end
	-- a giant's footfall: a thud, a puff at the foot, the street shaking
	function AV.footfall(char, root, scale, spec)
		local side = (AV.stepAt[char] and AV.stepAt[char].side or 1) * -1
		AV.stepAt[char] = { at = os.clock(), side = side }
		local foot = root.Position + root.CFrame.RightVector * 0.5 * scale * side - UP * 3 * scale
		VFX.PlaySound("AdminGiantStep", foot, 1)
		dustPuffs(foot + UP * 0.3, 0.45 * scale, low() and 1 or 3, PAL.DUST, 0.7, false)
		VFX.ShakeAt(foot, spec.Shake or 1, spec.Reach or 70, 0.22)
	end
	-- ids: what's running, in Order: each loop starts with its event and stops after it
	function AV.ambient(ids)
		local on = {}
		for _, id in ids do
			on[id] = true
		end
		-- METEOR SHOWER: the sky full of them
		if on.Meteor and not AV.amb.streaks then
			local token = {}
			AV.amb.streaks = token
			task.spawn(function()
				while AV.amb.streaks == token do
					AV.skyStreak()
					task.wait(low() and rand(0.9, 1.6) or rand(0.35, 0.8))
				end
			end)
		elseif not on.Meteor then
			AV.amb.streaks = nil
		end
		-- LOW GRAVITY: motes drifting up round you
		if on.LowGravity and not AV.amb.motes then
			local holder = newPart(Vector3.new(90, 46, 90), CFrame.new(), Color3.new(1, 1, 1))
			holder.Name = "AdminMotes"
			holder.Transparency = 1
			local pe = EK and EK.emitter(holder, {
				tex = EK.TEX.glow, color = PAL.MOTE, size = { { 0, 0 }, { 0.2, 0.32 }, { 1, 0 } }, transp = { { 0, 1 }, { 0.25, 0.35 }, { 1, 1 } },
				life = { 6, 9 }, speed = { 0.2, 1 }, spread = 180, accel = Vector3.new(0, 0.7, 0), light = 0.7, bright = 1.5,
			})
			if pe then
				pe.Shape = Enum.ParticleEmitterShape.Box
				pe.Rate = low() and 6 or 14
			end
			local motes = { holder = holder }
			motes.conn = RunService.RenderStepped:Connect(function()
				local cam = workspace.CurrentCamera
				if cam and holder.Parent then
					holder.CFrame = CFrame.new(cam.CFrame.Position + cam.CFrame.LookVector * 20)
				end
			end)
			AV.amb.motes = motes
		elseif not on.LowGravity and AV.amb.motes then
			AV.amb.motes.conn:Disconnect()
			local holder = AV.amb.motes.holder
			for _, pe in holder:GetChildren() do
				if pe:IsA("ParticleEmitter") then
					pe.Enabled = false
				end
			end
			cleanup(holder, 9)
			AV.amb.motes = nil
		end
		-- GIANT MODE: footfalls (anyone big, walking: their speed, on the ground)
		if on.Giant and not AV.amb.steps then
			local token = {}
			AV.amb.steps = token
			local spec = (def("Giant") or {}).Step or {}
			task.spawn(function()
				while AV.amb.steps == token do
					for _, plr in Players:GetPlayers() do
						local c = plr.Character
						local r = c and c:FindFirstChild("HumanoidRootPart")
						local scale = c and tonumber(c:GetAttribute("BuffScale")) or 1
						if r and scale >= 1.5 then
							local v = r.AssemblyLinearVelocity
							local last = AV.stepAt[c]
							if Vector3.new(v.X, 0, v.Z).Magnitude > 6 and math.abs(v.Y) < 6 and (not last or os.clock() - last.at >= (spec.Every or 0.62)) then
								AV.footfall(c, r, scale, spec)
							end
						end
					end
					task.wait(0.05)
				end
			end)
		elseif not on.Giant then
			AV.amb.steps = nil
			table.clear(AV.stepAt) -- (round 87, in Studio: not weak any more)
		end
		-- MONEY RAIN over: whatever bills are left go
		if not on.MoneyRain and next(AV.bills) ~= nil then
			AV.clearBills(true)
		end
	end

	-- what's running changed (QuirkClient: in Order)
	function AV.set(ids)
		AV.ids = ids
		AV.setLook(ids)
		AV.ambient(ids)
	end
	-- every trace gone (the tests; a client shutting it all off)
	function AV.clear()
		AV.set({})
		AV.clearBills(false)
		for _, x in folder:GetChildren() do
			if x.Name == "AdminMeteor" or x.Name == "AdminMeteorRing" or x.Name == "AdminSkyStreak" or x.Name == "AdminShuffledName" then
				x:Destroy()
			end
		end
	end
end)()

---------------------------------------------------------------------------
-- (round 88) COSMETICS A on every screen (Config.CosmeticsA). The looks are
-- the server's (Kit.dekuBoots, Kit.grenadeBracers, Kit.iidaGlasses, in each
-- player's QuirkGear.Cosmetics); this makes them react to the fight from
-- what already reaches every screen - nothing is sent:
--   DEKU: the iron soles crackle green while he runs (his speed on the
--   street) or dashes - the seam round each sole lit and flickering, arcs
--   crawling round its edge, sparks spraying off; his kicks leave glowing
--   prints where he plants and pushes off, and an axe kick where it lands
--   (the moves' own effects: Config.CosmeticsA.Deku.Prints; an M1 kick's
--   standing foot); after a 100% move (its effect, or an arm breaking) the
--   boots crack - glowing green, then dark - the iron red-hot and cooling,
--   smoke curling off them, for a while.
--   BAKUGO: the sweat in his gauntlets - (round 90) the black band between
--   the green is the gauge, amber rising from the wrist, its top edge
--   glowing - his own SWEAT bar on his screen (QuirkClient hands it over:
--   CA.mySweat), and on everyone else's the rules his machine runs
--   (draining while he's BlastFlying, filling back up once he's been on the
--   street a moment); each blast lights the bands, nearly empty they throb
--   red, filling up they flash, full they breathe and the grenade pins glow.
--   IIDA: a burst (the Engine kit's big flashes: CA.burst) glints off a lens
--   - a star and the lens flashing white, when you can see his face; a
--   stall (EK.stall: CA.fog) fogs both lenses over, steam puffing off them,
--   clearing after.
-- Past Cull, a look you've hidden (SHOW COSMETICS), your own up close
-- (Roblox fades your body for a close camera), a body that's down or gone:
-- nothing runs. Half the particles and no lights on a low-end machine.
-- What it makes goes with the look; a rebuilt look is found again and what
-- was going on (the sweat, a strain, a fog) carries on onto it.
-- (Its own block: the main chunk is at its local limit.)
---------------------------------------------------------------------------
do
	local CA = {
		-- [char] = this screen's state for a body wearing one of the looks;
		-- [char] = what outlives a rebuilt look (the sweat, a strain, the
		-- arm-break times, a fog); [char] = its prints on the street, oldest
		-- first. None weak (the round-87 lesson): the scan, CA.drop and
		-- PlayerRemoving clear them
		bodies = {},
		logic = {},
		prints = {},
		mine = nil, -- his own screen's sweat, exactly: { char, pct } (CA.mySweat)
		KINDS = { FullCowl = "Deku", PrimeDeku = "Deku", Explosion = "Bakugo", Engine = "Iida" },
		WHITE = Color3.new(1, 1, 1),
		lastStep = os.clock(),
	}
	VFX.CosA = CA
	local EK = VFX.EngineKit

	function CA.cfg(kind)
		local c = Config.CosmeticsA or {}
		if kind then
			return c[kind] or {}
		end
		return c
	end
	function CA.low()
		return EK.lowEnd()
	end
	-- whoever might wear one: the players' bodies and the training dummies
	function CA.list()
		local out = {}
		for _, plr in Players:GetPlayers() do
			if plr.Character then
				table.insert(out, plr.Character)
			end
		end
		local dummies = workspace:FindFirstChild("Dummies")
		for _, d in dummies and dummies:GetChildren() or {} do
			if d:IsA("Model") then
				table.insert(out, d)
			end
		end
		return out
	end
	-- gone in t s (the director's slow motion stretches it: cleanup)
	function CA.gone(obj, t)
		if VFX.Slow then
			cleanup(obj, t)
		else
			task.delay(t, function()
				pcall(obj.Destroy, obj)
			end)
		end
	end
	-- a CFrame at `at` looking along `dir` (a segment's, a print's)
	function CA.along(at, dir)
		local look = dir.Magnitude > 1e-4 and dir.Unit or Vector3.new(0, 0, -1)
		local right = look:Cross(math.abs(look.Y) > 0.95 and Vector3.new(1, 0, 0) or UP).Unit
		return CFrame.fromMatrix(at, right, right:Cross(look), -look)
	end
	-- which side a piece of the look is on (the limb it's welded to)
	function CA.sideOf(part)
		local w = part:FindFirstChildOfClass("Weld")
		local n = w and w.Part0 and w.Part0.Name or ""
		return (n:find("Right") and "Right") or (n:find("Left") and "Left") or nil
	end

	---------------------------------------------------------------------------
	-- WHO'S WEARING WHAT
	---------------------------------------------------------------------------
	-- a body's look, found (nil: it isn't wearing it - MY COSMETICS off, an
	-- avatar with no legs...)
	function CA.build(char, kind, cos, lg)
		local st = { char = char, kind = kind, cos = cos, logic = lg }
		local all = cos:GetDescendants()
		if kind == "Deku" then
			st.boots, st.crackle = {}, 0
			for _, d in all do
				if d:IsA("BasePart") and (d.Name == "SolePlate" or d.Name == "BootShaft" or d.Name == "BootSeam") then
					local side = CA.sideOf(d)
					if side then
						local b = st.boots[side] or { seams = {} }
						st.boots[side] = b
						if d.Name == "SolePlate" then
							b.plate = d
						elseif d.Name == "BootShaft" then
							b.shaft = d
						else
							table.insert(b.seams, { part = d, color = d.Color, material = d.Material, transp = d.Transparency })
						end
					end
				end
			end
			for side, b in st.boots do
				if not b.plate then
					st.boots[side] = nil
				end
			end
			if next(st.boots) == nil then
				return nil
			end
		elseif kind == "Bakugo" then
			-- (round 90) the bands between the green (SweatFill) and their
			-- glowing top edges (SweatLevel), paired by the arm they're on
			st.bands, st.pins = {}, {}
			local edges = {}
			for _, d in all do
				if d:IsA("BasePart") and (d.Name == "SweatFill" or d.Name == "SweatLevel") then
					local w = d:FindFirstChildOfClass("Weld")
					if w then
						local rec = { fill = d, weld = w, size = d.Size, c0 = w.C0, color = d.Color, transp = d.Transparency, side = CA.sideOf(d) }
						table.insert(d.Name == "SweatFill" and st.bands or edges, rec)
					end
				elseif d:IsA("BasePart") and d.Name == "GrenadePin" then
					table.insert(st.pins, { part = d, color = d.Color, material = d.Material })
				end
			end
			if #st.bands == 0 then
				return nil
			end
			for _, e in edges do
				for _, b in st.bands do
					if not b.edge and b.side == e.side then
						b.edge = e
						break
					end
				end
			end
		elseif kind == "Iida" then
			st.lenses, st.fog, st.flash, st.which = {}, 0, 0, 0
			for _, d in all do
				if d:IsA("BasePart") and d.Name == "Lens" then
					table.insert(st.lenses, { part = d, color = d.Color, transp = d.Transparency, material = d.Material })
				end
			end
			if #st.lenses == 0 then
				return nil
			end
		end
		return st
	end

	-- let go of a look: everything made on it gone, its pieces as the server built them
	function CA.unbuild(st)
		if st.kind == "Deku" then
			CA.crackleFx(st, false)
			CA.strainFx(st, false)
			CA.seamsTo(st, nil)
		elseif st.kind == "Bakugo" then
			CA.pinsTo(st, false)
			for _, t in st.bands do
				for _, p in { t, t.edge } do
					if p.fill.Parent then
						p.fill.Size, p.fill.Color, p.fill.Transparency = p.size, p.color, p.transp
						p.weld.C0 = p.c0
					end
				end
			end
		elseif st.kind == "Iida" then
			for _, l in st.lenses do
				if l.part.Parent then
					l.part.Color, l.part.Transparency, l.part.Material = l.color, l.transp, l.material
				end
			end
			if st.steam then
				pcall(st.steam.Destroy, st.steam)
				st.steam = nil
			end
		end
	end

	-- a body that's gone, down, or someone else now: all of it let go (its
	-- prints on the street fade out by themselves)
	function CA.drop(char)
		local st = CA.bodies[char]
		CA.bodies[char] = nil
		CA.logic[char] = nil
		CA.prints[char] = nil
		if st then
			pcall(CA.unbuild, st)
		end
	end

	-- is the look out of sight on this screen? (SHOW COSMETICS off hides
	-- everyone else's; Roblox fades your own body for a close camera; Prime
	-- Deku's flash step and a dev's parked body are faded the same way)
	function CA.hidden(st)
		if st.char:GetAttribute("Parked") == true then
			return true
		end
		local ref
		if st.kind == "Deku" then
			local b = st.boots.Right or st.boots.Left
			ref = b and b.plate
		elseif st.kind == "Bakugo" then
			ref = st.bands[1].fill
		else
			ref = st.lenses[1].part
		end
		local ok, ltm = pcall(function()
			return ref.LocalTransparencyModifier
		end)
		return ok and type(ltm) == "number" and ltm > 0.5
	end

	-- one body: what it's wearing, near enough to see, still standing (true:
	-- it's one to watch)
	function CA.see(char, camPos, cull)
		local kind = CA.KINDS[char:GetAttribute("Quirk") or ""]
		local hum = char:FindFirstChildOfClass("Humanoid")
		local root = char:FindFirstChild("HumanoidRootPart")
		if not (kind and hum and root and hum.Health > 0) then
			return false
		end
		local lg = CA.logic[char]
		if not lg or lg.kind ~= kind then
			lg = { kind = kind }
			CA.logic[char] = lg
		end
		local gear = char:FindFirstChild("QuirkGear")
		local cos = gear and gear:FindFirstChild("Cosmetics")
		local st = CA.bodies[char]
		if st and (st.cos ~= cos or st.kind ~= kind) then
			-- (rebuilt - a form, the ult - or taken off: found again below)
			CA.bodies[char] = nil
			pcall(CA.unbuild, st)
			st = nil
		end
		if not st and cos then
			st = CA.build(char, kind, cos, lg)
			CA.bodies[char] = st
		end
		if st then
			st.root, st.hum = root, hum
			st.near = camPos == nil or (root.Position - camPos).Magnitude <= cull
			st.hide = CA.hidden(st)
			if kind == "Deku" then
				CA.arms(st)
			end
		end
		return true
	end

	-- every Scan s: everyone
	function CA.scan()
		local cull = CA.cfg().Cull or 160
		local cam = workspace.CurrentCamera
		local camPos = cam and cam.CFrame.Position
		local seen = {}
		for _, char in CA.list() do
			if CA.see(char, camPos, cull) then
				seen[char] = true
			end
		end
		for char in CA.bodies do
			if not seen[char] then
				CA.drop(char)
			end
		end
		for char in CA.logic do
			if not seen[char] then
				CA.drop(char)
			end
		end
		for char in CA.prints do
			if not seen[char] then
				CA.prints[char] = nil
			end
		end
	end

	-- every frame: what's going on, on each look
	function CA.step()
		local now = os.clock()
		local dt = math.clamp(now - CA.lastStep, 0, 0.1)
		CA.lastStep = now
		local stale
		for char, st in CA.bodies do
			-- (round 88 review) the server rebuilt the look (the ult, a form, MY
			-- COSMETICS) or took it off: what we welded to its old pieces would
			-- drop off them and fall through the street till the next scan -
			-- let it go this frame, and find the new one at once
			local cp = st.cos.Parent
			if cp == nil or cp.Parent ~= char then
				stale = stale or {}
				table.insert(stale, char)
				continue
			end
			if st.near then
				st.hide = CA.hidden(st) -- (every frame: a flash step fades him at once)
			end
			local live = st.near and not st.hide and char.Parent ~= nil and st.hum ~= nil and st.hum.Health > 0
			if st.kind == "Deku" then
				CA.dekuStep(st, dt, now, live)
			elseif st.kind == "Bakugo" then
				CA.sweatStep(st, dt, now, live)
			elseif st.kind == "Iida" then
				CA.iidaStep(st, dt, now, live)
			end
		end
		if stale then
			local cam = workspace.CurrentCamera
			for _, char in stale do
				local st = CA.bodies[char]
				CA.bodies[char] = nil
				if st then
					pcall(CA.unbuild, st)
				end
				pcall(CA.see, char, cam and cam.CFrame.Position, CA.cfg().Cull or 160)
			end
		end
	end

	-- on (or just over) the street? (one ray a tenth of a second a body)
	function CA.grounded(st, now, reach)
		if now >= (st.groundAt or 0) then
			st.groundAt = now + 0.1
			local root = st.root
			local hit = root and groundRay(root.Position, 12)
			st.onGround = hit ~= nil and root.Position.Y - hit.Position.Y <= reach
		end
		return st.onGround == true
	end

	-- what the moves do to the looks (VFX.Play, on every effect)
	function CA.onPlay(effectId, char, data)
		local st = typeof(char) == "Instance" and CA.bodies[char]
		if not st then
			return
		end
		data = type(data) == "table" and data or {}
		if st.kind == "Deku" then
			CA.dekuPlay(st, effectId, data)
		elseif st.kind == "Bakugo" and effectId == "BlastFly" and data.Kind ~= "End" then
			st.flashUntil = os.clock() + (CA.cfg("Bakugo").Flash or 0.14) -- (each blast draws on the bands)
		end
	end

	---------------------------------------------------------------------------
	-- DEKU: THE IRON SOLES
	---------------------------------------------------------------------------
	function CA.dekuStep(st, dt, now, live)
		local C = CA.cfg("Deku").Crackle or {}
		local want = false
		if live then
			local root = st.root
			local v = root.AssemblyLinearVelocity
			local speed = Vector3.new(v.X, 0, v.Z).Magnitude
			-- (thrown across the street, or dragged along it in someone's grip,
			-- isn't running)
			local thrown = st.char:GetAttribute("Ragdolled") or st.char:GetAttribute("Stunned") or st.char:GetAttribute("Grabbed")
				or root:FindFirstChild("Knockback") ~= nil
			want = not thrown and ((speed >= (C.SprintFrom or 27) and CA.grounded(st, now, C.Ground or 4.2)) or now < (st.dashUntil or 0))
		end
		if want then
			st.crackle = math.min(1, st.crackle + dt / (C.Rise or 0.08))
		elseif live then
			st.crackle = math.max(0, st.crackle - dt / (C.Fade or 0.25))
		else
			st.crackle = 0 -- (faded out of sight, down, too far: at once)
		end
		CA.crackleFx(st, st.crackle > 0)
		if st.fx then
			CA.crackleTick(st, now)
		end
		CA.strainTick(st, now, live)
		CA.seams(st, now)
	end

	-- the crackle's pieces on each sole: a spray of sparks off its bottom,
	-- and three hops of an arc (a white core in a green glow), lit by turns
	function CA.crackleFx(st, on)
		if on and not st.fx then
			local D = CA.cfg("Deku")
			local fx = { boots = {}, nextArc = 0, nextSound = os.clock() + rand(0.15, 0.4) }
			st.fx = fx
			for side, b in st.boots do
				local plate = b.plate
				if plate.Parent then
					local a = Instance.new("Attachment")
					a.Name = "CosASpark"
					a.CFrame = CFrame.new(0, -plate.Size.Y / 2, 0)
					a.Parent = plate
					local pe = EK.emitter(a, {
						tex = EK.TEX.spark, color = { D.Core or CA.WHITE, D.Green or CA.WHITE }, size = { { 0, 0.24 }, { 1, 0 } }, transp = 0,
						life = { 0.12, 0.28 }, speed = { 5, 11 }, spread = 75, accel = Vector3.new(0, -32, 0), drag = 2, light = 1, dir = "Top",
					})
					pe.Name = "CosASpark"
					-- (a green glow on the street under it: what reads from across the street)
					local light
					if not CA.low() then
						light = Instance.new("PointLight")
						light.Name = "CosASoleLight"
						light.Color = D.Green or CA.WHITE
						light.Range = (D.Crackle or {}).Light or 7
						light.Brightness = 0
						light.Shadows = false
						light.Parent = a
					end
					local segs = {}
					for i = 1, 3 do
						local core = newPart(Vector3.new(0.045, 0.045, 0.2), plate.CFrame, CA.WHITE, Enum.Material.Neon)
						local glow = newPart(Vector3.new(0.13, 0.13, 0.2), plate.CFrame, D.Green or CA.WHITE, Enum.Material.Neon)
						core.Name, glow.Name = "CosAArc", "CosAArc"
						core.Transparency, glow.Transparency = 1, 1
						EK.weld(core, plate, CFrame.new())
						EK.weld(glow, plate, CFrame.new())
						segs[i] = { core = core, glow = glow }
					end
					fx.boots[side] = { att = a, pe = pe, light = light, segs = segs, plate = plate, offAt = 0 }
				end
			end
		elseif not on and st.fx then
			for _, f in st.fx.boots do
				pcall(f.att.Destroy, f.att)
				for _, s in f.segs do
					pcall(s.core.Destroy, s.core)
					pcall(s.glow.Destroy, s.glow)
				end
			end
			st.fx = nil
		end
	end

	function CA.crackleTick(st, now)
		local C = CA.cfg("Deku").Crackle or {}
		local fx, lvl, low = st.fx, st.crackle, CA.low()
		local list = {}
		for _, f in fx.boots do
			if f.plate.Parent and f.att.Parent then
				f.pe.Rate = (C.Sparks or 36) * lvl * (low and 0.5 or 1)
				if f.light then
					f.light.Brightness = (C.Bright or 1.8) * lvl * ((f.lit and 1.35 or 0.75) + rand(-0.2, 0.2))
				end
				if f.lit and now >= f.offAt then
					for _, s in f.segs do
						if s.core.Parent and s.glow.Parent then
							s.core.Transparency, s.glow.Transparency = 1, 1
						end
					end
					f.lit = false
				end
				table.insert(list, f)
			end
		end
		-- a new arc, Arcs a second (half on a low-end machine), on a sole by turns
		if #list > 0 and lvl > 0.3 and now >= fx.nextArc then
			fx.nextArc = now + rand(0.6, 1.4) / math.max((C.Arcs or 14) * (low and 0.5 or 1) * lvl, 0.5)
			CA.arc(list[rng:NextInteger(1, #list)], now + (C.Arc or 0.07))
		end
		if lvl > 0.5 and now >= fx.nextSound then
			fx.nextSound = now + rand(0.7, 1.3)
			VFX.PlaySound("BootCrackle", st.root.Position - Vector3.new(0, 2.5, 0), 1)
		end
	end

	-- an arc crawling round a sole's edge: three hops along its rim from
	-- anywhere on it, kinked up onto the boot, a hair out from the iron
	function CA.arc(f, offAt)
		local s = f.plate.Size
		local hw, hl = s.X / 2 + 0.03, s.Z / 2 + 0.03
		local per = 2 * (s.X + s.Z)
		local function at(u)
			u %= per
			if u < s.Z then
				return Vector3.new(hw, 0, -hl + u / s.Z * 2 * hl)
			elseif u < s.Z + s.X then
				return Vector3.new(hw - (u - s.Z) / s.X * 2 * hw, 0, hl)
			elseif u < 2 * s.Z + s.X then
				return Vector3.new(-hw, 0, hl - (u - s.Z - s.X) / s.Z * 2 * hl)
			end
			return Vector3.new(-hw + (u - 2 * s.Z - s.X) / s.X * 2 * hw, 0, -hl)
		end
		local u = rand(0, per)
		local way = rng:NextNumber() < 0.5 and 1 or -1
		local p = at(u) + Vector3.new(0, rand(-s.Y / 2, s.Y / 2 + 0.1), 0)
		for _, seg in f.segs do
			if not (seg.core.Parent and seg.glow.Parent) then
				break
			end
			u += way * rand(0.22, 0.38)
			local q = at(u) + Vector3.new(0, rand(-s.Y / 2, s.Y / 2 + 0.3), 0)
			local len = (q - p).Magnitude
			if len > 0.01 then
				local cf = CA.along((p + q) / 2, q - p)
				seg.core.Size = Vector3.new(0.045, 0.045, len + 0.04)
				seg.glow.Size = Vector3.new(0.13, 0.13, len + 0.1)
				for _, part in { seg.core, seg.glow } do
					local w = part:FindFirstChildOfClass("Weld")
					if w then
						w.C0 = cf
					end
				end
				seg.core.Transparency, seg.glow.Transparency = 0, 0.45
			end
			p = q
		end
		f.lit, f.offAt = true, offAt
	end

	-- the seam round each sole: green and flickering while they crackle,
	-- red-hot after a 100% move (cooling over Heat), else as it was built
	function CA.seams(st, now)
		local D = CA.cfg("Deku")
		local S = D.Strain or {}
		local lg = st.logic
		local heat = 0
		if lg.strainAt and now < (lg.strainUntil or 0) then
			heat = math.clamp(1 - (now - lg.strainAt) / (S.Heat or 4), 0, 1)
		end
		if st.crackle > 0 and not st.hide then
			-- (a new flicker 20 times a second, not every frame: a buzz, not a strobe)
			if now >= (st.flickerAt or 0) then
				st.flickerAt = now + 0.05
				CA.seamsTo(st, (D.Green or CA.WHITE):Lerp(D.Core or CA.WHITE, rand(0, 0.6)), rand(0.02, 0.35) + (1 - st.crackle) * 0.5)
			end
		elseif heat > 0.03 and st.strain then
			CA.seamsTo(st, (S.Hot or CA.WHITE):Lerp(Color3.fromRGB(70, 22, 12), 1 - heat), 0)
		else
			CA.seamsTo(st, nil)
		end
	end
	function CA.seamsTo(st, color, transp)
		if color == nil and not st.seamsLit then
			return
		end
		st.seamsLit = color ~= nil
		for _, b in st.boots do
			for _, s in b.seams do
				if s.part.Parent then
					if color then
						s.part.Material = Enum.Material.Neon
						s.part.Color = color
						s.part.Transparency = math.clamp(transp or 0, 0, 0.9)
					else
						s.part.Material, s.part.Color, s.part.Transparency = s.material, s.color, s.transp
					end
				end
			end
		end
	end

	-- a 100% move: the boots strain - for Time s (a second one on top
	-- carries it on and lights the cracks again)
	function CA.strain(char)
		local lg = CA.logic[char]
		if not (lg and lg.kind == "Deku") then
			return
		end
		local now = os.clock()
		local time = (CA.cfg("Deku").Strain or {}).Time or 9
		-- (round 88 review) a fresh strain picks where its cracks run; one that
		-- carries on keeps them (the pieces are rebuilt whenever he's back in
		-- sight - a flash step, a rebuilt look - and mustn't jump about)
		if now >= (lg.strainUntil or 0) or not lg.strainSeed then
			lg.strainSeed = rng:NextInteger(1, 2 ^ 30)
		end
		lg.strainUntil = math.max(lg.strainUntil or 0, now + time)
		lg.strainAt = now
		local st = CA.bodies[char]
		if st and st.near and not st.hide and st.root then
			VFX.PlaySound("BootStrain", st.root.Position - Vector3.new(0, 2.5, 0), 1)
		end
	end

	-- an arm breaking (1,000,000%, INFINITE 100%: BrokenArmR / BrokenArmL,
	-- the server time it heals) strains the boots too. The first look at a
	-- body only remembers (a break from before you saw him isn't news)
	function CA.arms(st)
		local lg = st.logic
		local now = workspace:GetServerTimeNow()
		local first = lg.arms == nil
		lg.arms = lg.arms or {}
		for _, side in { "R", "L" } do
			local v = tonumber(st.char:GetAttribute("BrokenArm" .. side)) or 0
			local was = lg.arms[side] or 0
			lg.arms[side] = v
			if not first and v > now and v > was + 0.5 then
				CA.strain(st.char)
			end
		end
	end

	function CA.strainTick(st, now, live)
		local S = CA.cfg("Deku").Strain or {}
		local lg = st.logic
		local on = live and now < (lg.strainUntil or 0)
		if on and not st.strain then
			CA.strainFx(st, true)
		elseif not on and st.strain then
			CA.strainFx(st, false)
		end
		local sx = st.strain
		if not sx then
			return
		end
		local glow = math.clamp(1 - (now - lg.strainAt) / (S.Glow or 2.4), 0, 1)
		local fade = math.clamp((lg.strainUntil - now) / (S.Fade or 1.2), 0, 1) -- (1 till the last Fade s)
		for _, c in sx.cracks do
			if c.dark.Parent then -- (anything of ours someone else cleared away is left be)
				c.dark.Transparency = 1 - fade
				c.glow.Transparency = 1 - glow * fade
			end
		end
		local spent = math.clamp((now - lg.strainAt) / (S.Time or 9), 0, 1)
		for _, pe in sx.smoke do
			if pe.Parent then
				pe.Rate = (S.Smoke or 12) * (1 - spent * 0.7) * fade * (CA.low() and 0.5 or 1)
			end
		end
	end

	-- the strain's pieces: Cracks on each boot (zigzags of three hops, round
	-- it - the front, the outside, the back - a green glow down the middle of
	-- each) and pale smoke curling off its top
	function CA.strainFx(st, on)
		if on and not st.strain then
			local D = CA.cfg("Deku")
			local S = D.Strain or {}
			local sx = { cracks = {}, smoke = {}, made = {} }
			st.strain = sx
			for side, b in st.boots do
				local shaft = b.shaft
				if shaft and shaft.Parent then
					local s = shaft.Size
					local out = side == "Right" and 1 or -1
					-- (round 88 review: the strain's own dice - a Park-Miller
					-- generator off its seed - so rebuilt pieces crack in the
					-- same places)
					local dice = ((st.logic.strainSeed or 1) + (out > 0 and 0 or 7919)) % 2147483646 + 1
					local function rand(a, b)
						dice = dice * 16807 % 2147483647
						return a + (b - a) * (dice / 2147483647)
					end
					-- (round the boot by turns: the front, the outside, the front
					-- again, the back - the back is what his own camera sees)
					local faces = { "Front", "Out", "Front", "Back" }
					for i = 1, S.Cracks or 4 do
						local which = faces[(i - 1) % #faces + 1]
						local onSide = which == "Out"
						local across = onSide and s.Z or s.X
						local n = (which == "Out" and Vector3.new(out, 0, 0)) or (which == "Back" and Vector3.new(0, 0, 1)) or Vector3.new(0, 0, -1)
						-- a point on the face (u across it, v up it), a hair proud
						local function face(u, v)
							if onSide then
								return Vector3.new(out * (s.X / 2 + 0.01), v, u)
							end
							return Vector3.new(u, v, n.Z * (s.Z / 2 + 0.01))
						end
						-- (off the middle of the front, where the laces are; low and high)
						local u = onSide and rand(-across * 0.3, across * 0.3) or (rand(0, 1) < 0.5 and -1 or 1) * rand(across * 0.16, across * 0.36)
						-- (the front's lower half is behind the toe box: kept above it)
						local floor = which == "Front" and -s.Y * 0.04 or -s.Y / 2 + 0.06
						local v = rand(s.Y * 0.06, s.Y * 0.42)
						local p = face(u, v)
						for _ = 1, 3 do
							local a = math.rad(rand(-55, 55))
							local l = rand(0.16, 0.28) * math.min(s.X, 1.2)
							u = math.clamp(u + math.sin(a) * l, -across * 0.45, across * 0.45)
							v = math.clamp(v - math.cos(a) * l, floor, s.Y / 2 - 0.06)
							local q = face(u, v)
							local len = (q - p).Magnitude
							if len > 0.02 then
								local cf = CA.along((p + q) / 2, q - p)
								local dark = newPart(Vector3.new(0.08, 0.08, len + 0.05), shaft.CFrame, S.Crack or Color3.new(), Enum.Material.SmoothPlastic)
								local glow = newPart(Vector3.new(0.045, 0.045, len + 0.02), shaft.CFrame, D.Green or CA.WHITE, Enum.Material.Neon)
								dark.Name, glow.Name = "CosACrack", "CosACrack"
								EK.weld(dark, shaft, cf)
								EK.weld(glow, shaft, cf + n * 0.024)
								table.insert(sx.cracks, { dark = dark, glow = glow })
							end
							p = q
						end
					end
					local a = Instance.new("Attachment")
					a.Name = "CosASmoke"
					a.CFrame = CFrame.new(0, s.Y / 2, 0)
					a.Parent = shaft
					table.insert(sx.made, a)
					local pe = EK.emitter(a, {
						tex = EK.TEX.smoke, color = { S.Smog or CA.WHITE, Color3.fromRGB(150, 150, 156) }, size = { { 0, 0.5 }, { 1, 1.9 } },
						transp = { { 0, 1 }, { 0.12, 0.3 }, { 1, 1 } }, life = { 1.2, 2 }, speed = { 1.5, 3 }, spread = 30,
						accel = Vector3.new(0, 1.8, 0), drag = 1, dir = "Top", influence = 0.6, spin = { -40, 40 },
					})
					pe.Name = "CosASmoke"
					table.insert(sx.smoke, pe)
				end
			end
		elseif not on and st.strain then
			for _, c in st.strain.cracks do
				pcall(c.dark.Destroy, c.dark)
				pcall(c.glow.Destroy, c.glow)
			end
			for _, a in st.strain.made do
				pcall(a.Destroy, a)
			end
			st.strain = nil
		end
	end

	-- his moves: a dash sets the soles crackling, kicks print, 100% strains
	function CA.dekuPlay(st, id, data)
		local D = CA.cfg("Deku")
		if id == "Dash" then
			st.dashUntil = os.clock() + ((D.Crackle or {}).Dash or 0.4)
		elseif id == "Punch" then
			CA.m1Print(st, data)
		end
		for _, p in (D.Prints or {})[id] or {} do
			task.delay(p.At or 0, CA.printBy, st.char, p, data)
		end
		local after = ((D.Strain or {}).Moves or {})[id]
		if after then
			task.delay(after, CA.strain, st.char)
		end
	end

	-- an M1 that's a kick (his set's hit, the 4th's variant): the foot he
	-- stands on prints as it lands
	function CA.m1Print(st, data)
		local set, limbs = m1Set(st.char)
		local count = math.clamp(tonumber(data.Count) or 1, 1, 4)
		local finisher = data.Finisher == true
		local hit = set[finisher and 4 or math.min(count, 3)]
		local variant = finisher and VFX.M1Variants[data.Variant or ""] or nil
		if variant then
			hit = variant[limbs] or variant.Hands
		end
		if hit and (hit.Limb == "RightFoot" or hit.Limb == "LeftFoot") then
			local P = CA.cfg("Deku").Print or {}
			task.delay(hit.Contact or 0.1, CA.footPrint, st.char, hit.Limb == "RightFoot" and "Left" or "Right", P.M1Size, P.M1Life)
		end
	end

	-- one of Prints' entries, on its beat
	function CA.printBy(char, p, data)
		local st = CA.bodies[char]
		-- (round 88 review: on its beat he may be someone else - no boots)
		if not (st and st.kind == "Deku" and st.near and not st.hide and st.root) then
			return
		end
		local size = p.Size
		if p.How == "Plant" then
			CA.footPrint(char, p.Foot or "Left", size)
		elseif p.How == "Push" then
			CA.footPrint(char, "Right", size)
			CA.footPrint(char, "Left", size)
		elseif p.How == "Land" and typeof(data.Pos) == "Vector3" then
			local hit = groundRay(data.Pos, 14)
			if hit then
				local d = (typeof(data.Dir) == "Vector3" and data.Dir) or (typeof(data.Look) == "Vector3" and data.Look) or st.root.CFrame.LookVector
				CA.print(char, hit.Position, d, size, nil, hit.Normal)
			end
		elseif p.How == "Points" and type(data.Points) == "table" then
			local center = typeof(data.Center) == "Vector3" and data.Center or st.root.Position
			local gap = tonumber(data.Gap) or 0.07
			for i, pt in data.Points do
				if typeof(pt) == "Vector3" then
					task.delay((i - 1) * gap, function()
						local hit = groundRay(pt, 14)
						if hit and CA.bodies[char] == st then
							CA.print(char, hit.Position, center - pt, size, nil, hit.Normal)
						end
					end)
				end
			end
		end
	end

	-- a print under one of his feet, if it's on the street (Reach)
	function CA.footPrint(char, side, size, life)
		local st = CA.bodies[char]
		local b = st and st.kind == "Deku" and st.near and not st.hide and st.boots[side]
		local plate = b and b.plate
		if not (plate and plate.Parent) then
			return
		end
		local hit = groundRay(plate.CFrame.Position, 10)
		if hit and plate.CFrame.Position.Y - hit.Position.Y <= ((CA.cfg("Deku").Print or {}).Reach or 1.6) then
			CA.print(char, hit.Position, plate.CFrame.LookVector, size, life, hit.Normal)
		end
	end

	-- the print: a footprint burnt into the street - the forefoot and the
	-- heel apart (it reads as a foot from across the street; one glowing
	-- sole-shaped blob didn't), each a green glow round a white-hot middle;
	-- lit Hold s, then fading to a dark green and gone by `life`; a spit of
	-- sparks and a sizzle. At most Max of one Deku's (the oldest go). Laid
	-- on the street's own slope (normal: the ray's)
	function CA.print(char, at, look, size, life, normal)
		local D = CA.cfg("Deku")
		local P = D.Print or {}
		size = (size or 1) * (P.Size or 1)
		life = life or P.Life or 2.8
		local hold = math.min(P.Hold or 0.35, life * 0.5)
		local n = (typeof(normal) == "Vector3" and normal.Magnitude > 0.5) and normal.Unit or UP
		local f = look - n * look:Dot(n)
		if f.Magnitude < 0.05 then
			f = Vector3.new(0, 0, -1) - n * -n.Z
		end
		f = f.Magnitude > 0.05 and f.Unit or Vector3.new(1, 0, 0)
		local base = at + n * rand(0.03, 0.05)
		local cf = CFrame.fromMatrix(base, f:Cross(n).Unit, n, -f)
		local parts = {}
		for _, o in {
			{ Vector3.new(1.02, 0.04, 1.12), -0.44, D.Green, 0.45 },
			{ Vector3.new(0.86, 0.04, 0.74), 0.58, D.Green, 0.45 },
			{ Vector3.new(0.62, 0.06, 0.74), -0.44, D.Core, 0.08 },
			{ Vector3.new(0.5, 0.06, 0.44), 0.58, D.Core, 0.12 },
		} do
			local p = newPart(o[1] * size, cf * CFrame.new(0, 0, o[2] * size), o[3] or CA.WHITE, Enum.Material.Neon)
			p.Name = "CosAPrint"
			p.Transparency = o[4]
			local mesh = Instance.new("SpecialMesh")
			mesh.MeshType = Enum.MeshType.Sphere
			mesh.Parent = p
			tween(p, life - hold, { Transparency = 1, Color = D.Seam or Color3.new() }, Enum.EasingStyle.Quad, Enum.EasingDirection.In, hold)
			CA.gone(p, life + 0.1)
			table.insert(parts, p)
		end
		sparks(base + UP * 0.2, 0.25 * size, D.Core, D.Green, EK.count(6))
		VFX.PlaySound("BootPrint", base, 1)
		local list = CA.prints[char] or {}
		CA.prints[char] = list
		table.insert(list, parts)
		local max = math.max(1, math.floor((P.Max or 10) * (CA.low() and 0.5 or 1)))
		while #list > max do
			for _, p in table.remove(list, 1) do
				pcall(p.Destroy, p)
			end
		end
		return parts
	end

	---------------------------------------------------------------------------
	-- BAKUGO: THE SWEAT GAUGES (round 90: the bands between the green)
	---------------------------------------------------------------------------
	-- his own screen's SWEAT bar (QuirkClient: nil when he isn't Bakugo)
	function CA.mySweat(char, pct)
		CA.mine = (char and type(pct) == "number") and { char = char, pct = pct } or nil
	end

	function CA.sweatStep(st, dt, now, live)
		local B = CA.cfg("Bakugo")
		local lg = st.logic
		local mine = CA.mine
		local target
		if mine and mine.char == st.char then
			target = math.clamp(mine.pct / 100, 0, 1)
		else
			-- everyone else's: his machine's own rules (QuirkClient, BlastFly)
			local BF = ((Config.Quirks or {}).Explosion or {}).BlastFlight or {}
			local ult = st.char:GetAttribute("UltActive") == true and BF.Ult or nil
			local mx = (ult and ult.Fuel) or BF.Fuel or 3.5
			lg.fuel = math.min(lg.fuel or mx, mx)
			if st.char:GetAttribute("BlastFlying") then
				lg.fuel -= dt
				lg.landed = nil
			elseif lg.fuel < mx and CA.grounded(st, now, B.Ground or 4.2) then
				-- (round 88 review: a full tank doesn't look for the street - an
				-- idle Bakugo cost every screen 10 rays a second)
				lg.landed = lg.landed or now
				if now - lg.landed >= (BF.RegenDelay or 0.6) then
					lg.fuel += (BF.Regen or 1.2) * dt
				end
			else
				lg.landed = nil
			end
			lg.fuel = math.clamp(lg.fuel, 0, mx)
			target = lg.fuel / mx
		end
		lg.sweat = target
		if not live then
			CA.pinsTo(st, false)
			st.shown = nil
			-- (round 88 review: filled up out of sight isn't news - no click
			-- when he comes back into view full)
			st.wasLow = nil
			return
		end
		st.shown = st.shown and st.shown + (target - st.shown) * math.min(1, (B.Ease or 7) * dt) or target
		local level = st.shown
		local full = target >= 0.995
		if not full then
			st.wasLow = true
		end
		if full and st.wasLow then
			st.wasLow = false
			st.fullAt = now -- (round 90: the band's flash)
			VFX.PlaySound("SweatFull", st.root.Position, 1)
		end
		CA.pinsTo(st, full, now)
		CA.bandsTo(st, level, full, now)
	end

	-- (round 90) THE BANDS: the sweat in the grooves between the green, up
	-- from the wrist to his level (the cylinder's length is its X, up the
	-- forearm), its top edge glowing hotter; amber, white-hot for a moment
	-- on each blast, throbbing red nearly dry. Filling up: the edge runs the
	-- length of the band, the band flashes white-hot and eases back; full,
	-- it breathes with the pins. (Written only when something changes)
	function CA.bandsTo(st, level, full, now)
		local B = CA.cfg("Bakugo")
		local fill = B.Fill or CA.WHITE
		local hot = B.Hot or CA.WHITE
		local col = fill
		local sweep, edgeCol = nil, B.Level or hot
		local since = now - (st.fullAt or -1e9)
		local flash = B.FullFlash or 0.55
		if now < (st.flashUntil or 0) then
			col = hot
		elseif level < (B.LowAt or 0.18) then
			local k = 0.5 + 0.5 * math.sin(now * 11)
			col = fill:Lerp(B.Low or fill, k)
			edgeCol = (B.Level or hot):Lerp(B.Low or fill, k * 0.6)
		elseif full and since < (B.Sweep or 0.22) then
			-- (filling up: a white-hot edge runs the length of the band...)
			sweep = since / (B.Sweep or 0.22)
		elseif full and since < (B.Sweep or 0.22) + flash then
			-- (...and as it reaches the top the band flashes white-hot,
			-- easing back to the sweat)
			col = hot:Lerp(fill, math.clamp((since - (B.Sweep or 0.22)) / flash, 0, 1) ^ 0.6)
		elseif full then
			-- (charged: breathing in time with the pins)
			local k = 0.5 + 0.5 * math.sin(now * math.pi * 2 / (B.Throb or 1.1))
			col = fill:Lerp(B.Charged or fill, k)
		end
		-- (written in steps a screen can see, so a level easing in doesn't
		-- write the band every frame)
		local q = math.floor(level * 400 + 0.5) / 400
		for _, t in st.bands do
			if t.fill.Parent then
				local len = t.size.X
				if t.level ~= q then
					t.level = q
					local l = math.max(len * q, 0.02)
					t.fill.Size = Vector3.new(l, t.size.Y, t.size.Z)
					t.weld.C0 = t.c0 * CFrame.new(-(len - l) / 2, 0, 0)
					t.fill.Transparency = q < 0.012 and 1 or t.transp
				end
				if t.col ~= col then -- (round 88 review: only when it changes, not every frame)
					t.col = col
					t.fill.Color = col
				end
				-- the top edge: at the level while it's on its way (not
				-- empty, not full), or running up the band as it fills
				local e = t.edge
				if e and e.fill.Parent then
					local at = sweep or ((q > 0.03 and q < 0.97) and q or nil)
					local ec = sweep and hot or edgeCol
					local want = at and math.floor(at * 400 + 0.5) / 400 or -1
					if e.at ~= want then
						e.at = want
						if at then
							-- (just under the sweat's top, never past either end of the
							-- band: the server built it at the band's top end; running
							-- up as it fills it's three times as tall)
							local w = e.size.X * (sweep and 3 or 1)
							if e.fill.Size.X ~= w then
								e.fill.Size = Vector3.new(w, e.size.Y, e.size.Z)
							end
							local c = math.clamp(-len / 2 + at * len - w / 2, -len / 2 + w / 2, len / 2 - w / 2)
							e.weld.C0 = e.c0 * CFrame.new(c - len / 2, 0, 0)
						elseif e.fill.Size.X ~= e.size.X then
							e.fill.Size = e.size
						end
						e.fill.Transparency = at and 0 or 1
					end
					if at and e.col ~= ec then
						e.col = ec
						e.fill.Color = ec
					end
				end
			end
		end
	end

	-- the grenade pins: glowing and throbbing while the bands are full
	function CA.pinsTo(st, on, now)
		local B = CA.cfg("Bakugo")
		if on then
			local k = 0.5 + 0.5 * math.sin((now or os.clock()) * math.pi * 2 / (B.Throb or 1.1))
			local c = (B.Pin or CA.WHITE):Lerp(CA.WHITE, 0.12 + 0.4 * k)
			for _, p in st.pins do
				if p.part.Parent then
					p.part.Material = Enum.Material.Neon
					p.part.Color = c
					if not p.light and not CA.low() then
						local l = Instance.new("PointLight")
						l.Name = "CosAPin"
						l.Color = B.Pin or CA.WHITE
						l.Range = B.Light or 6
						l.Shadows = false
						l.Parent = p.part
						p.light = l
					end
					if p.light then
						p.light.Brightness = 0.8 + 1.4 * k
					end
				end
			end
			st.pinsLit = true
		elseif st.pinsLit then
			st.pinsLit = false
			for _, p in st.pins do
				if p.part.Parent then
					p.part.Material, p.part.Color = p.material, p.color
				end
				if p.light then
					pcall(p.light.Destroy, p.light)
					p.light = nil
				end
			end
		end
	end

	---------------------------------------------------------------------------
	-- IIDA: THE GLASSES
	---------------------------------------------------------------------------
	-- the Engine kit's flash at his calves (EK.flash): a big one is a burst
	function CA.burst(char, scale)
		local st = CA.bodies[char]
		local G = CA.cfg("Iida").Glint or {}
		if not (st and st.kind == "Iida") or (scale or 1) < (G.MinScale or 1.2) then
			return
		end
		local now = os.clock()
		if now - (st.glintAt or -1) < (G.Gap or 0.3) then
			return
		end
		st.glintAt = now
		CA.glint(st)
	end

	-- the glint: the lens flashes white, and - unless his back's to you - a
	-- star bursts off its outer top corner, turning as it goes (a ting)
	function CA.glint(st)
		if not (st.near and not st.hide and st.root) then
			return
		end
		local G = CA.cfg("Iida").Glint or {}
		st.flash = 1
		local head = st.char:FindFirstChild("Head")
		local cam = workspace.CurrentCamera
		if not (head and cam) then
			return
		end
		local to = cam.CFrame.Position - head.CFrame.Position
		if to.Magnitude > 0.01 and head.CFrame.LookVector:Dot(to.Unit) < (G.Facing or -0.25) then
			return -- (the lenses flash where you can't see them)
		end
		st.which = st.which % #st.lenses + 1
		local lens = st.lenses[st.which].part
		if not lens.Parent then
			return
		end
		local side = (lens.CFrame.Position - head.CFrame.Position):Dot(head.CFrame.RightVector) >= 0 and 1 or -1
		local a = Instance.new("Attachment")
		a.Name = "CosAGlint"
		a.CFrame = CFrame.new(side * lens.Size.X * 0.32, lens.Size.Y * 0.3, -0.02)
		a.Parent = lens
		local size, life = G.Size or 1.8, G.Life or 0.24
		local bb = Instance.new("BillboardGui")
		bb.Name = "CosAGlint"
		bb.Adornee = a
		bb.Size = UDim2.new(size * 0.3, 0, size * 0.3, 0)
		bb.StudsOffset = Vector3.new(0, 0, 0.6) -- (toward the camera: clear of his face)
		bb.LightInfluence = 0
		bb.Brightness = 2
		bb.AlwaysOnTop = false
		bb.Parent = a
		local star = Instance.new("Frame")
		star.Name = "Star"
		star.BackgroundTransparency = 1
		star.AnchorPoint = Vector2.new(0.5, 0.5)
		star.Position = UDim2.fromScale(0.5, 0.5)
		star.Size = UDim2.fromScale(1, 1)
		star.Parent = bb
		local tint = G.Color or CA.WHITE
		-- four long rays and four short ones, white in the middle, tinted and
		-- fading to nothing at the tips; a white-hot dot
		for _, r in { { 1, 0.08, 0 }, { 1, 0.08, 90 }, { 0.5, 0.05, 45 }, { 0.5, 0.05, -45 } } do
			local f = Instance.new("Frame")
			f.Name = "Ray"
			f.BorderSizePixel = 0
			f.BackgroundColor3 = CA.WHITE
			f.AnchorPoint = Vector2.new(0.5, 0.5)
			f.Position = UDim2.fromScale(0.5, 0.5)
			f.Size = UDim2.fromScale(r[1], r[2])
			f.Rotation = r[3]
			local g = Instance.new("UIGradient")
			g.Color = ColorSequence.new({ ColorSequenceKeypoint.new(0, tint), ColorSequenceKeypoint.new(0.5, CA.WHITE), ColorSequenceKeypoint.new(1, tint) })
			g.Transparency = NumberSequence.new({
				NumberSequenceKeypoint.new(0, 1), NumberSequenceKeypoint.new(0.36, 0.4), NumberSequenceKeypoint.new(0.5, 0),
				NumberSequenceKeypoint.new(0.64, 0.4), NumberSequenceKeypoint.new(1, 1),
			})
			g.Parent = f
			f.Parent = star
		end
		local dot = Instance.new("Frame")
		dot.Name = "Core"
		dot.BorderSizePixel = 0
		dot.BackgroundColor3 = CA.WHITE
		dot.AnchorPoint = Vector2.new(0.5, 0.5)
		dot.Position = UDim2.fromScale(0.5, 0.5)
		dot.Size = UDim2.fromScale(0.16, 0.16)
		local round = Instance.new("UICorner")
		round.CornerRadius = UDim.new(0.5, 0)
		round.Parent = dot
		dot.Parent = star
		-- it bursts open, then shrinks away
		tween(bb, life * 0.25, { Size = UDim2.new(size, 0, size, 0) }, Enum.EasingStyle.Quad, Enum.EasingDirection.Out)
		tween(star, life, { Rotation = 40 }, Enum.EasingStyle.Linear)
		task.delay(life * 0.25, function()
			if bb.Parent then
				tween(bb, life * 0.75, { Size = UDim2.new(0, 0, 0, 0) }, Enum.EasingStyle.Quad, Enum.EasingDirection.In)
			end
		end)
		CA.gone(a, life + 0.1)
		VFX.PlaySound("GlassesGlint", head.CFrame.Position, 1)
	end

	-- the engines stalling (EK.stall): the lenses fog over for most of it,
	-- a puff of steam off them; it clears after (CA.iidaStep)
	function CA.fog(char, dur)
		local lg = CA.logic[char]
		if not (lg and lg.kind == "Iida") then
			return
		end
		lg.fogUntil = math.max(lg.fogUntil or 0, os.clock() + (dur or 2.4) * 0.8)
		local st = CA.bodies[char]
		local head = char:FindFirstChild("Head")
		if not (st and st.near and not st.hide and head) then
			return
		end
		VFX.PlaySound("GlassesFog", head.CFrame.Position, 1)
		-- (never on his own screen up close: it'd be steam in his eyes)
		local cam = workspace.CurrentCamera
		if (cam and (cam.CFrame.Position - head.CFrame.Position).Magnitude < 4) or st.steam then
			return
		end
		local F = CA.cfg("Iida").Fog or {}
		local mid = Vector3.zero
		for _, l in st.lenses do
			mid += l.part.CFrame.Position / #st.lenses
		end
		local a = Instance.new("Attachment")
		a.Name = "CosASteam"
		a.CFrame = CFrame.new(head.CFrame:PointToObjectSpace(mid) + Vector3.new(0, 0.06, 0))
		a.Parent = head
		st.steam = a
		local pe = EK.emitter(a, {
			tex = EK.TEX.smoke, color = F.Color or CA.WHITE, size = { { 0, 0.15 }, { 1, 0.75 } }, transp = { { 0, 1 }, { 0.2, 0.4 }, { 1, 1 } },
			life = { 0.5, 0.9 }, speed = { 1, 2.2 }, spread = 40, accel = Vector3.new(0, 2, 0), drag = 1.5, dir = "Top", influence = 0.5,
		})
		pe.Name = "CosASteam"
		pe.Rate = (F.Steam or 10) * (CA.low() and 0.5 or 1)
		task.delay(0.9, function()
			pe.Enabled = false
		end)
		task.delay(2.4, function()
			if st.steam == a then
				st.steam = nil
			end
			pcall(a.Destroy, a)
		end)
	end

	function CA.iidaStep(st, dt, now, live)
		local I = CA.cfg("Iida")
		local F, G = I.Fog or {}, I.Glint or {}
		if live and now < (st.logic.fogUntil or 0) then
			st.fog = math.min(1, st.fog + dt / (F.In or 0.25))
		else
			st.fog = math.max(0, st.fog - dt / (F.Clear or 1.4))
		end
		st.flash = math.max(0, st.flash - dt / math.max(G.Life or 0.24, 0.05))
		if not live then
			st.fog, st.flash = 0, 0
		end
		if st.fog > 0 or st.flash > 0 or st.lensLit then
			st.lensLit = st.fog > 0 or st.flash > 0
			local f = st.fog * st.fog * (3 - 2 * st.fog)
			local fc, ft = F.Color or CA.WHITE, F.Transparency or 0.08
			-- (past half-fogged the glass goes flat white - glass that nearly
			-- opaque reads grey, reflecting the sky; a flash burns neon white)
			local mat
			for _, l in st.lenses do
				mat = (st.flash > 0.3 and Enum.Material.Neon) or (f > 0.5 and Enum.Material.SmoothPlastic) or l.material
				if l.part.Parent then
					l.part.Material = mat
					l.part.Color = l.color:Lerp(fc, f):Lerp(CA.WHITE, st.flash)
					local t = l.transp + (ft - l.transp) * f
					l.part.Transparency = t + (0.05 - t) * st.flash
				end
			end
		end
	end

	---------------------------------------------------------------------------
	-- THE CLOCKS
	---------------------------------------------------------------------------
	Players.PlayerRemoving:Connect(function(plr)
		local c = plr.Character
		if c then
			CA.drop(c)
		end
	end)
	task.spawn(function()
		while true do
			local ok, err = pcall(CA.scan)
			if not ok then
				warn("[VFX] cosmetics: " .. tostring(err))
				task.wait(1)
			end
			task.wait(CA.cfg().Scan or 0.4)
		end
	end)
	RunService.RenderStepped:Connect(function()
		if next(CA.bodies) == nil then
			CA.lastStep = os.clock()
			return
		end
		local ok, err = pcall(CA.step)
		if not ok and not CA.warned then
			CA.warned = true -- (once: it'd be every frame)
			warn("[VFX] cosmetics: " .. tostring(err))
		end
	end)
end

---------------------------------------------------------------------------
-- (round 88) COSMETICS B on every screen (Config.CosmeticsB): three
-- signature looks that move with the fight, off the beats every screen
-- already plays (VFX.Play hands each one to CB.onPlay) - nothing new is
-- sent. GOJO: in his ult the server builds his blindfold pushed up and the
-- Six Eyes under it; this screen slides it up from his eyes as his hand
-- comes past them, opens the eyes and flares a glint off both; when the ult
-- ends it drops back down over them as they dim. TODOROKI: frost crusts his
-- right shoulder after his ice moves (building up to his collar and jaw,
-- then his face and hair), his left side steams after his fire moves, and
-- fire sears the frost off. SHIGARAKI: the hand on his face clenches into
-- a trembling claw while he charges a Decay, greying and crumbling at the
-- fingertips, and springs open as it goes off. One RenderStepped driver,
-- only while something's moving. Everything is hidden with the look (SHOW
-- COSMETICS, WEAR COSMETICS, first person), halved on a low-end machine,
-- and let go explicitly: the body gone, down, another hero, done.
-- (Its own function: the main chunk is at its local limit.)
---------------------------------------------------------------------------
;(function()
	local CB = {
		gojo = {}, -- [char] = his band going up or coming down
		eyes = {}, -- [char] = his Six Eyes as they last were (the gear's rebuilt before a screen hears the ult's over)
		frost = {}, -- [char] = the frost on his right shoulder
		steam = {}, -- [char] = the steam off his left side
		flex = {}, -- [char] = the hand on his face clenching
		-- (none of these is weak - the round 87 lesson: every entry goes
		-- when its body does or when it's done)
		ASH = Color3.fromRGB(118, 108, 112),
		SMOKE = "rbxasset://textures/particles/smoke_main.dds",
		SPARKLE = "rbxasset://textures/particles/sparkles_main.dds",
	}
	VFX.CosB = CB
	local NS, NK = NumberSequence.new, NumberSequenceKeypoint.new

	function CB.cfg(name)
		return (Config.CosmeticsB or {})[name] or {}
	end
	-- his look (QuirkGear.Cosmetics), and the first piece of it test() picks
	function CB.cos(char)
		local gear = char and char:FindFirstChild("QuirkGear")
		return gear and gear:FindFirstChild("Cosmetics")
	end
	function CB.find(char, test)
		local cos = CB.cos(char)
		for _, p in cos and cos:GetChildren() or {} do
			if p:IsA("BasePart") and test(p) then
				return p
			end
		end
		return nil
	end
	function CB.ltm(part)
		local ok, v = pcall(function()
			return part.LocalTransparencyModifier
		end)
		return ok and type(v) == "number" and v or 0
	end
	-- a piece of a look this screen shows: there, not someone else's with
	-- SHOW COSMETICS off, not hidden (first person, a hidden body)
	function CB.shown(char, part)
		if not (part and part.Parent) then
			return false
		end
		local me = Players.LocalPlayer
		if me and me.Character ~= char and me:GetAttribute("ShowCosmetics") == false then
			return false
		end
		return CB.ltm(part) <= 0.5
	end
	-- still that hero, and up
	function CB.alive(char, quirk)
		if not (char and char.Parent) or char:GetAttribute("Quirk") ~= quirk then
			return false
		end
		local hum = char:FindFirstChildOfClass("Humanoid")
		return hum == nil or hum.Health > 0
	end
	-- 0 -> 1 with `over` (a share) past 1 and back
	function CB.backOut(a, over)
		a = math.clamp(a, 0, 1) - 1
		local c1 = 17.0158 * (over or 0.1)
		return 1 + (c1 + 1) * a * a * a + c1 * a * a
	end
	-- welded on to a body part at c0 (IceKit.frostBody's way: it moves with it).
	-- (round 88 review) The piece is put exactly where the weld will hold it
	-- first: it's still anchored when the weld goes on, and a weld between
	-- an anchored piece and a body at a C0 the piece isn't sitting at can
	-- pull the body to the piece (a frost crystal welded at its base while it
	-- stood at its full height would nudge his whole body, your own too)
	function CB.stick(limbPart, p, c0)
		p.CFrame = limbPart.CFrame * c0
		local w = Instance.new("Weld")
		w.Part0 = limbPart
		w.Part1 = p
		w.C0 = c0
		w.Parent = p
		p.Massless = true
		p.Anchored = false
		return w
	end

	-- THE DRIVER: one RenderStepped while anything moves (each kind's step
	-- in turn; one that errors is let go, not the rest)
	CB.KINDS = {
		{ "gojo", "gojoStep", "gojoEnd" },
		{ "frost", "frostStep", "frostKill" },
		{ "steam", "steamStep", "steamKill" },
		{ "flex", "flexStep", "flexEnd" },
	}
	function CB.busy()
		return next(CB.gojo) ~= nil or next(CB.frost) ~= nil or next(CB.steam) ~= nil or next(CB.flex) ~= nil
	end
	function CB.step()
		local now = os.clock()
		for _, kind in CB.KINDS do
			for char, st in CB[kind[1]] do
				local ok, err = pcall(CB[kind[2]], char, st, now)
				if not ok then
					warn("[VFX] CosB " .. kind[1] .. ": " .. tostring(err))
					pcall(CB[kind[3]], char)
					CB[kind[1]][char] = nil
				end
			end
		end
		if CB.conn and not CB.busy() then
			CB.conn:Disconnect()
			CB.conn = nil
		end
	end
	function CB.wake()
		if not CB.conn then
			CB.conn = RunService.RenderStepped:Connect(CB.step)
		end
	end
	-- everything let go at once (the tests)
	function CB.clear()
		for _, kind in CB.KINDS do
			for char in CB[kind[1]] do
				pcall(CB[kind[3]], char)
				CB[kind[1]][char] = nil
			end
		end
		table.clear(CB.eyes)
	end

	-- every move's beat on this screen (VFX.Play)
	function CB.onPlay(effectId, char, data)
		if typeof(char) ~= "Instance" or not char:IsA("Model") then
			return
		end
		local q = char:GetAttribute("Quirk")
		if effectId == "UltActivate" then
			local dq = type(data) == "table" and data.Quirk or q
			if dq == "Limitless" then
				CB.gojoFlip(char, true)
			elseif dq == "Decay" then
				CB.flexStart(char, (CB.cfg("Shigaraki").Charge or {}).Awaken or 0.6)
			end
		elseif effectId == "UltEnd" then
			if q == "Limitless" then
				CB.gojoFlip(char, false)
			end
		elseif q == "HalfCold" then
			CB.shoto(char, effectId, data)
		elseif q == "Whirlwind" and VFX.IN and VFX.IN.U then
			-- (round 99) in his ult: wind coiled round the arm that throws it
			VFX.IN.U.throw(char, effectId, data)
		elseif q == "Decay" then
			local charge = (CB.cfg("Shigaraki").Charge or {})[effectId]
			if charge then
				local ab = Config.FindAbilityById and Config.FindAbilityById(effectId)
				CB.flexStart(char, type(ab) == "table" and tonumber(ab.Windup) or charge)
			end
		end
	end

	---------------------------------------------------------------------
	-- GOJO: the blindfold up, the Six Eyes, the glint; and back down
	---------------------------------------------------------------------
	function CB.gojoFlip(char, up)
		CB.gojoEnd(char)
		local st = { up = up, t0 = os.clock() }
		if not up then
			st.ghosts = CB.ghostEyes(char)
		end
		CB.gojo[char] = st
		CB.wake()
	end
	-- the band's pieces built `state` ("Up" / "Down") with their welds, and the eyes
	function CB.band(char, state)
		local band, eyes = {}, {}
		local cos = CB.cos(char)
		for _, p in cos and cos:GetChildren() or {} do
			if p:IsA("BasePart") then
				if p:GetAttribute("BandState") == state then
					local w = p:FindFirstChildOfClass("Weld")
					if w then
						table.insert(band, { part = p, weld = w })
					end
				elseif p:GetAttribute("SixEye") then
					table.insert(eyes, p)
				end
			end
		end
		return band, eyes
	end
	-- a piece `a` of the way from down to up (past 1: that much higher again)
	function CB.bandAt(b, a)
		local p = b.part
		local down, up = p:GetAttribute("BandDown"), p:GetAttribute("BandUp")
		if typeof(down) ~= "CFrame" or typeof(up) ~= "CFrame" then
			return
		end
		-- (at either end exactly the server's)
		if a > 1 then
			b.weld.C0 = up + (up.Position - down.Position) * (a - 1)
		else
			b.weld.C0 = a >= 1 and up or a <= 0 and down or down:Lerp(up, a)
		end
		local s0, s1 = p:GetAttribute("BandDownSize"), p:GetAttribute("BandUpSize")
		if typeof(s0) == "Vector3" and typeof(s1) == "Vector3" then
			p.Size = a >= 1 and s1 or a <= 0 and s0 or s0:Lerp(s1, a)
		end
	end
	-- the eyes `open` of the way open (the glow with them)
	function CB.eyesOpen(eyes, open, G)
		for _, p in eyes do
			if p:GetAttribute("SixEye") == "Glow" then
				local light = p:FindFirstChildOfClass("PointLight")
				if light then
					light.Brightness = ((G.Glow or {}).Brightness or 1.8) * open
				end
			else
				p.Transparency = 1 - open
			end
		end
	end
	function CB.gojoStep(char, st, now)
		local G = CB.cfg("Gojo")
		if not CB.alive(char, "Limitless") then
			CB.gojoEnd(char)
			CB.gojo[char] = nil
			return
		end
		local e = now - st.t0
		local window = G.Window or 1.5
		if st.up then
			-- (until the server's new gear is here there's nothing to move:
			-- the time runs on, so it comes in where the lift has got to)
			local band, eyes = CB.band(char, "Up")
			local delay, lift = G.Delay or 0.1, math.max(G.LiftTime or 0.28, 0.01)
			local a = e <= delay and 0 or CB.backOut((e - delay) / lift, G.Overshoot or 0.08)
			for _, b in band do
				CB.bandAt(b, a)
			end
			local open = math.clamp((e - (G.EyesAt or 0.2)) / math.max(G.EyesIn or 0.16, 0.01), 0, 1)
			CB.eyesOpen(eyes, open, G)
			if not st.glinted and #eyes > 0 and e >= (G.GlintAt or 0.42) then
				st.glinted = true
				CB.glint(char, eyes, G)
			end
			if (st.glinted and e >= delay + lift and open >= 1) or e > window then
				-- (exactly the server's at the end)
				for _, b in band do
					CB.bandAt(b, 1)
				end
				CB.eyesOpen(eyes, 1, G)
				CB.snapEyes(char)
				CB.gojo[char] = nil
			end
		else
			-- it falls: slow off his forehead, quick down over his eyes
			local band = CB.band(char, "Down")
			local a = math.clamp(e / math.max(G.DropTime or 0.26, 0.01), 0, 1)
			for _, b in band do
				CB.bandAt(b, 1 - a * a)
			end
			local dim = math.clamp(e / math.max(G.EyesOut or 0.18, 0.01), 0, 1)
			for _, g in st.ghosts or {} do
				if g.Parent then
					g.Transparency = dim
				end
			end
			if (#band > 0 and a >= 1 and dim >= 1) or e > window then
				for _, b in band do
					CB.bandAt(b, 0)
				end
				CB.gojoEnd(char)
				CB.gojo[char] = nil
			end
		end
	end
	function CB.gojoEnd(char)
		local st = CB.gojo[char]
		for _, g in st and st.ghosts or {} do
			g:Destroy()
		end
		if st then
			st.ghosts = nil
			CB.gojoSettle(char)
		end
	end
	-- (round 88 review) a lift or a drop cut short (the body down, another
	-- hero, a step that failed): the band and the eyes go back exactly as the
	-- server built them, not left half way (and the eyes half open) here
	function CB.gojoSettle(char)
		local up, eyes = CB.band(char, "Up")
		for _, b in up do
			CB.bandAt(b, 1)
		end
		for _, b in (CB.band(char, "Down")) do
			CB.bandAt(b, 0)
		end
		CB.eyesOpen(eyes, 1, CB.cfg("Gojo"))
	end
	-- what his eyes are like now ({ C0 on the head, size, colour, material, round })
	function CB.snapEyes(char)
		local cos = CB.cos(char)
		local list = {}
		for _, p in cos and cos:GetChildren() or {} do
			local role = p:IsA("BasePart") and p:GetAttribute("SixEye")
			local w = role and role ~= "Glow" and p:FindFirstChildOfClass("Weld")
			if w then
				table.insert(list, { c0 = w.C0, size = p.Size, color = p.Color, material = p.Material, ball = p:FindFirstChildOfClass("SpecialMesh") ~= nil })
			end
		end
		if #list > 0 then
			CB.eyes[char] = { from = cos, list = list }
		end
	end
	-- the eyes as they were, on this screen only, to dim under the falling band
	function CB.ghostEyes(char)
		local snap, head = CB.eyes[char], char:FindFirstChild("Head")
		local made = {}
		if not (snap and head and CB.shown(char, head)) then
			return made
		end
		for _, s in snap.list do
			local p = newPart(s.size, head.CFrame * s.c0, s.color, s.material)
			p.Name = "SixEyesDimming"
			if s.ball then
				local mesh = Instance.new("SpecialMesh")
				mesh.MeshType = Enum.MeshType.Sphere
				mesh.Parent = p
			end
			CB.stick(head, p, s.c0)
			table.insert(made, p)
		end
		return made
	end
	-- THE GLINT: a four-point star flaring off each iris (it follows his
	-- head; drawn over everything, so only while his face is turned to you)
	function CB.glint(char, eyes, G)
		local head = char:FindFirstChild("Head")
		local cam = workspace.CurrentCamera
		if not (head and cam) then
			return
		end
		local toCam = cam.CFrame.Position - head.Position
		if toCam.Magnitude > 140 or (toCam.Magnitude > 0.1 and toCam.Unit:Dot(head.CFrame.LookVector) < 0.15) then
			return
		end
		-- (round 88 review) ...and only where you can see his face: drawn over
		-- everything, it would flare through a building between you and him
		if CB.blocked(cam.CFrame.Position, head.Position) then
			return
		end
		local any = false
		for _, p in eyes do
			if p:GetAttribute("SixEye") == "Iris" and CB.shown(char, p) then
				any = true
				CB.star(p, G.GlintSize or 2.2, G.GlintLife or 0.5, (G.Glow or {}).Color or Color3.fromRGB(120, 200, 255))
			end
		end
		if any then
			VFX.PlaySound("SixEyesGlint", head.Position, 1)
		end
	end
	-- something solid between the camera and a point (past every fighter and
	-- this screen's effects; see-through glass doesn't count)
	function CB.blocked(from, to)
		local ok, hit = pcall(function()
			rayParams.FilterDescendantsInstances = characterList()
			return workspace:Raycast(from, to - from, rayParams)
		end)
		if not (ok and hit and hit.Instance) then
			return false
		end
		local okT, seeThrough = pcall(function()
			return hit.Instance.Transparency > 0.6
		end)
		return not (okT and seeThrough)
	end
	function CB.star(part, size, life, color)
		local bb = Instance.new("BillboardGui")
		bb.Name = "SixEyesGlint"
		bb.Size = UDim2.new(size * 0.15, 0, size * 0.15, 0)
		bb.LightInfluence = 0
		bb.Brightness = 3
		bb.AlwaysOnTop = true
		bb.MaxDistance = 160
		bb.Adornee = part
		-- the long streak across, the short one up, a white core streak and the hot middle
		for i, spec in { { 1, 0.05, color }, { 0.05, 0.62, color }, { 0.55, 0.022, Color3.new(1, 1, 1) }, { 0.16, 0.16, Color3.new(1, 1, 1) } } do
			local f = Instance.new("Frame")
			f.AnchorPoint = Vector2.new(0.5, 0.5)
			f.Position = UDim2.fromScale(0.5, 0.5)
			f.Size = UDim2.fromScale(spec[1], spec[2])
			f.BackgroundColor3 = spec[3]
			f.BorderSizePixel = 0
			f.Parent = bb
			if i == 4 then
				local corner = Instance.new("UICorner")
				corner.CornerRadius = UDim.new(0.5, 0)
				corner.Parent = f
			else
				local grad = Instance.new("UIGradient")
				grad.Transparency = NS({ NK(0, 1), NK(0.5, 0), NK(1, 1) })
				grad.Rotation = i == 2 and 90 or 0
				grad.Parent = f
			end
		end
		bb.Parent = folder
		tween(bb, life * 0.3, { Size = UDim2.new(size, 0, size, 0) }, Enum.EasingStyle.Quad, Enum.EasingDirection.Out)
		task.delay(life * 0.3, function()
			if bb.Parent then
				tween(bb, life * 0.7, { Size = UDim2.new(0, 0, 0, 0) }, Enum.EasingStyle.Quad, Enum.EasingDirection.In)
			end
		end)
		cleanup(bb, life + 0.05)
		return bb
	end
	-- every half second: each Gojo in his ult has his eyes noted (for the
	-- drop - also for a body that came into view mid-ult), and his glow goes
	-- with his eyes on a screen that hides other people's looks
	function CB.scan()
		for char in CB.eyes do
			if not char.Parent then
				CB.eyes[char] = nil
			end
		end
		local me = Players.LocalPlayer
		for _, plr in Players:GetPlayers() do
			local char = plr.Character
			local cos = char and char:GetAttribute("Quirk") == "Limitless" and CB.cos(char)
			if cos then
				if char:GetAttribute("UltActive") and not CB.gojo[char] and (not CB.eyes[char] or CB.eyes[char].from ~= cos) then
					CB.snapEyes(char)
				end
				for _, p in cos:GetChildren() do
					local light = p:GetAttribute("SixEye") == "Glow" and p:FindFirstChildOfClass("PointLight")
					if light then
						light.Enabled = not (me and plr ~= me and me:GetAttribute("ShowCosmetics") == false)
					end
				end
			end
		end
	end
	task.spawn(function()
		while true do
			task.wait(0.5)
			local ok, err = pcall(CB.scan)
			if not ok then
				warn("[VFX] CosB scan: " .. tostring(err))
			end
		end
	end)

	---------------------------------------------------------------------
	-- TODOROKI: frost on his right shoulder, steam off his left side
	---------------------------------------------------------------------
	-- the frost, level by level, on an R6 body - in each body part's own
	-- space for a stock 1x2x1 arm, 2x2x1 torso and 1.2-stud head (scaled to
	-- the real one): a thin glaze of ice on the skin { level, part,
	-- "plate", size, at, tilt (deg) } and crystals growing out of it, fanned
	-- like frost { level, part, "spike", base, direction, length, width }
	CB.FROST = {
		-- 1: the shoulder - glazed over the top of the arm and the corner of
		-- the torso, three crystals fanning up and out of it (clear of the
		-- ice side's own spike, out at the side of the arm)
		{ 1, "Right Arm", "plate", Vector3.new(1.1, 0.12, 1.1), Vector3.new(0, 0.98, 0), Vector3.new(3, 0, -5) },
		{ 1, "Torso", "plate", Vector3.new(0.56, 0.1, 1.06), Vector3.new(0.74, 0.99, 0), Vector3.new(-2, 0, -8) },
		{ 1, "Right Arm", "spike", Vector3.new(0.12, 0.98, 0.22), Vector3.new(0.35, 1, 0.45), 0.85, 0.36 },
		{ 1, "Right Arm", "spike", Vector3.new(0.3, 0.92, -0.26), Vector3.new(0.9, 0.75, -0.4), 0.7, 0.32 },
		{ 1, "Torso", "spike", Vector3.new(0.72, 0.98, 0.12), Vector3.new(0.1, 1, 0.25), 0.6, 0.3 },
		-- 2: the glaze down over his collarbone, front and back, crystals by
		-- his neck and out the front, one along his jaw
		{ 2, "Torso", "plate", Vector3.new(0.6, 0.45, 0.06), Vector3.new(0.6, 0.73, -0.53), Vector3.new(6, 0, -4) },
		{ 2, "Torso", "plate", Vector3.new(0.6, 0.45, 0.06), Vector3.new(0.6, 0.73, 0.53), Vector3.new(-6, 0, -4) },
		{ 2, "Torso", "spike", Vector3.new(0.38, 0.98, -0.15), Vector3.new(-0.2, 1, -0.3), 0.5, 0.26 },
		{ 2, "Torso", "spike", Vector3.new(0.58, 0.82, -0.48), Vector3.new(0.3, 0.6, -1), 0.45, 0.24 },
		{ 2, "Head", "spike", Vector3.new(0.48, -0.36, -0.05), Vector3.new(0.9, 0.3, -0.2), 0.4, 0.22 },
		-- 3: the side of his face glazed, crystals up through his hair (his
		-- white side)
		{ 3, "Head", "plate", Vector3.new(0.05, 0.34, 0.48), Vector3.new(0.61, -0.04, 0.08), Vector3.new(0, 0, -3) },
		{ 3, "Head", "spike", Vector3.new(0.35, 0.5, -0.15), Vector3.new(0.5, 1, -0.3), 0.5, 0.24 },
		{ 3, "Head", "spike", Vector3.new(0.5, 0.35, 0.25), Vector3.new(0.9, 0.7, 0.4), 0.45, 0.22 },
		{ 3, "Head", "spike", Vector3.new(0.15, 0.56, 0.2), Vector3.new(0.2, 1, 0.3), 0.4, 0.2 },
	}
	-- where the steam comes off his left side: { which, part, at (x the part's size; the head's: x its visible size) }
	CB.STEAM_AT = {
		{ "Shoulder", "Left Arm", Vector3.new(0, 0.42, 0) },
		{ "Arm", "Left Arm", Vector3.new(0, -0.2, 0) },
		{ "Hair", "Head", Vector3.new(-0.25, 0.42, 0) },
	}
	CB.STOCK = { ["Right Arm"] = Vector3.new(1, 2, 1), ["Left Arm"] = Vector3.new(1, 2, 1), Torso = Vector3.new(2, 2, 1) }
	CB.R15 = { ["Right Arm"] = "RightUpperArm", ["Left Arm"] = "LeftUpperArm", Torso = "UpperTorso" }
	-- a body part, and the scale of the specs' space on it
	function CB.limbFor(char, name, r15)
		local p = char:FindFirstChild(name)
		if not (p and p:IsA("BasePart")) then
			p = char:FindFirstChild(r15 or CB.R15[name] or "")
		end
		if not (p and p:IsA("BasePart")) then
			return nil, nil
		end
		if name == "Head" then
			local v = p:FindFirstChildOfClass("SpecialMesh") and p.Size.Y * 1.2 or math.min(p.Size.X, p.Size.Y, p.Size.Z)
			return p, Vector3.one * (v / 1.2)
		end
		return p, p.Size / (CB.STOCK[name] or p.Size)
	end
	-- his look's gate: the scar (none: his look's off, nothing shows)
	function CB.scar(char, st)
		if not (st.gate and st.gate.Parent) then
			st.gate = CB.find(char, function(p)
				return p.Name == "Scar"
			end)
		end
		return st.gate
	end

	function CB.shoto(char, effectId, data)
		local T = CB.cfg("Todoroki")
		local F, S = T.Frost or {}, T.Steam or {}
		local iceAt, fireAt = (F.Moves or {})[effectId], (S.Moves or {})[effectId]
		if effectId == "SideSwap" then
			-- (to his fire side: the frost steams off; to his ice side: the steam cools)
			if type(data) == "table" and data.Alt == true then
				CB.frostMelt(char)
			elseif CB.steam[char] then
				CB.steam[char].untilT = math.min(CB.steam[char].untilT, os.clock() + 0.6)
			end
		elseif iceAt then
			task.delay(iceAt, function()
				if CB.alive(char, "HalfCold") then
					if CB.steam[char] then
						CB.steam[char].untilT = math.min(CB.steam[char].untilT, os.clock() + 0.6)
					end
					CB.frostUp(char)
				end
			end)
		elseif fireAt then
			task.delay(fireAt, function()
				if CB.alive(char, "HalfCold") then
					CB.frostMelt(char)
					CB.steamUp(char)
				end
			end)
		end
	end

	-- one more layer of frost (up to Max), and its hold starts over
	function CB.frostUp(char)
		local F = (CB.cfg("Todoroki").Frost or {})
		local st = CB.frost[char]
		if st and st.thawEnd then
			CB.frostKill(char)
			st = nil
		end
		if not st then
			st = { level = 0, parts = {}, built = {} }
			CB.frost[char] = st
		end
		if not CB.shown(char, CB.scar(char, st)) and st.level == 0 then
			CB.frost[char] = nil -- (his look's off or hidden here: nothing)
			return
		end
		local low = IceKit.lowEnd()
		st.level = math.min(st.level + 1, F.Max or 3)
		st.untilT = os.clock() + (F.Hold or 3.2)
		local spikes = 0
		for i, spec in CB.FROST do
			if spec[1] <= st.level and not st.built[i] then
				st.built[i] = true
				if spec[3] == "spike" then
					spikes += 1
				end
				-- (a low-end machine: every other spike)
				if spec[3] == "plate" or not low or spikes % 2 == 1 then
					CB.frostPiece(st, char, spec, F)
				end
			end
		end
		CB.frostEmitters(st, char, F, low)
		local arm = CB.limbFor(char, "Right Arm")
		if arm and CB.shown(char, CB.scar(char, st)) then
			local at = (arm.CFrame * CFrame.new(0, arm.Size.Y * 0.45, 0)).Position
			IceKit.particles(at, "glint", low and 2 or 4, 0.45)
			VFX.PlaySound("ShotoFrostCreep", at, 1)
		end
		CB.wake()
	end
	function CB.frostPiece(st, char, spec, F)
		local limbPart, s = CB.limbFor(char, spec[2])
		if not limbPart then
			return
		end
		local PAL = IceKit.PAL
		local grow = F.Grow or 0.2
		if spec[3] == "plate" then
			local size = spec[4] * s
			local tilt = spec[6]
			local c0 = CFrame.new(spec[5] * s) * CFrame.Angles(math.rad(tilt.X), math.rad(tilt.Y), math.rad(tilt.Z))
			local p = newPart(size * 0.3, limbPart.CFrame * c0, PAL.FROST, Enum.Material.Ice)
			p.Name = "ShotoFrost"
			p.Transparency = 1
			p.Reflectance = 0.05
			CB.stick(limbPart, p, c0)
			tween(p, grow, { Size = size, Transparency = F.Glaze or 0.25 }, Enum.EasingStyle.Quad)
			table.insert(st.parts, { part = p, limb = limbPart })
			return
		end
		-- a spike: two wedges folded about a spine into a V (IceKit's), the
		-- half facing the sun lit, growing out of its base
		local m = (s.X + s.Y + s.Z) / 3
		local base = limbPart.CFrame * (spec[4] * s)
		local dir = limbPart.CFrame:VectorToWorldSpace(spec[5] * s).Unit
		local len, w = spec[6] * m, spec[7] * m
		local fold = math.rad(28)
		local frame = IceKit.frameFor(base - dir * 0.1, dir, rand(0.8, 1.2))
		local first = IceKit.litFirst(frame, fold)
		local a = IceKit.wedge(folder, first and PAL.LIT or PAL.SHADE)
		local b = IceKit.wedge(folder, first and PAL.SHADE or PAL.LIT)
		IceKit.placeV(a, b, frame, len, w, w * 0.9, w * 0.4, fold)
		for _, wp in { a, b } do
			wp.Name = "ShotoFrost"
			local full, c0 = wp.Size, limbPart.CFrame:ToObjectSpace(wp.CFrame)
			wp.Size = Vector3.new(full.X, full.Y * 0.1, full.Z)
			local weld = CB.stick(limbPart, wp, c0 * CFrame.new(0, -full.Y * 0.45, 0))
			tween(wp, grow, { Size = full }, Enum.EasingStyle.Quad)
			tween(weld, grow, { C0 = c0 }, Enum.EasingStyle.Quad)
			table.insert(st.parts, { part = wp, limb = limbPart })
		end
	end
	-- snow falling off it, cold air sinking off it, glints popping on it
	function CB.frostEmitters(st, char, F, low)
		local arm = CB.limbFor(char, "Right Arm")
		if not arm then
			return
		end
		if not (st.att and st.att.Parent) then
			local att = Instance.new("Attachment")
			att.Name = "ShotoFrost"
			att.Position = Vector3.new(0, arm.Size.Y * 0.42, 0)
			att.Parent = arm
			local snow = Instance.new("ParticleEmitter")
			snow.Texture = "rbxasset://textures/whiteCircle.png"
			snow.Color = ColorSequence.new(Color3.new(1, 1, 1), Color3.fromRGB(214, 236, 252))
			snow.LightEmission = 0.4
			snow.LightInfluence = 0.5
			snow.Size = NS({ NK(0, 0.2), NK(1, 0.1) })
			snow.Transparency = NS({ NK(0, 1), NK(0.1, 0.1), NK(0.8, 0.3), NK(1, 1) })
			snow.Lifetime = NumberRange.new(1.2, 2)
			snow.Speed = NumberRange.new(0.4, 1.2)
			snow.SpreadAngle = Vector2.new(70, 70)
			snow.Acceleration = Vector3.new(0, -2.2, 0)
			snow.Drag = 1.2
			snow.Rate = 0
			snow.Parent = att
			local mist = Instance.new("ParticleEmitter")
			mist.Texture = CB.SMOKE
			mist.Color = ColorSequence.new(IceKit.PAL.MIST)
			mist.LightInfluence = 0.8
			mist.Size = NS({ NK(0, 0.4), NK(1, 1.6) })
			mist.Transparency = NS({ NK(0, 0.8), NK(0.3, 0.62), NK(1, 1) })
			mist.Lifetime = NumberRange.new(0.9, 1.4)
			mist.Speed = NumberRange.new(0.3, 1)
			mist.SpreadAngle = Vector2.new(60, 60)
			mist.Acceleration = Vector3.new(0, -2.5, 0)
			mist.Drag = 1
			mist.Rate = 0
			mist.Parent = att
			local glint = Instance.new("ParticleEmitter")
			glint.Texture = CB.SPARKLE
			glint.Color = ColorSequence.new(Color3.new(1, 1, 1), Color3.fromRGB(205, 238, 255))
			glint.LightEmission = 1
			glint.LightInfluence = 0
			glint.Size = NS({ NK(0, 0), NK(0.15, 0.6), NK(0.4, 0.15), NK(1, 0) })
			glint.Lifetime = NumberRange.new(0.35, 0.6)
			glint.Speed = NumberRange.new(0.2, 0.8)
			glint.SpreadAngle = Vector2.new(180, 180)
			glint.ZOffset = 1
			glint.Rate = 0
			glint.Parent = att
			st.att, st.emitters = att, { snow = snow, mist = mist, glint = glint }
		end
		local i = math.clamp(st.level, 1, 3)
		local k = low and 0.5 or 1
		st.emitters.snow.Rate = ((F.Snow or {})[i] or 4) * k
		st.emitters.mist.Rate = ((F.Mist or {})[i] or 3) * k
		st.emitters.glint.Rate = (1 + i) * k
	end
	-- it thaws away (time), or fire sears it off at once with a hiss of steam
	function CB.frostThaw(char, st, time, seared)
		if st.thawEnd then
			return
		end
		st.thawEnd = os.clock() + time
		for _, pe in st.emitters or {} do
			pe.Enabled = false
		end
		for _, x in st.parts do
			if x.part.Parent then
				tween(x.part, time, { Transparency = 1, Size = x.part.Size * 0.5 }, Enum.EasingStyle.Sine, Enum.EasingDirection.In)
			end
		end
		local arm = CB.limbFor(char, "Right Arm")
		if arm and char.Parent and CB.shown(char, CB.scar(char, st)) then
			local at = (arm.CFrame * CFrame.new(0, arm.Size.Y * 0.45, 0)).Position
			if seared then
				IceKit.steam(at + UP * 0.3, 0.3, 3, { rise = 0.6 })
				VFX.PlaySound("ShotoFrostMelt", at, 1)
			else
				IceKit.particles(at, "puff", 3, 0.3)
			end
		end
	end
	function CB.frostMelt(char)
		local st = CB.frost[char]
		if st and not st.thawEnd then
			CB.frostThaw(char, st, (CB.cfg("Todoroki").Frost or {}).Melt or 0.45, true)
		end
	end
	function CB.frostStep(char, st, now)
		if not char.Parent then
			CB.frostKill(char)
			CB.frost[char] = nil
			return
		end
		if not st.thawEnd and (not CB.alive(char, "HalfCold") or now >= (st.untilT or 0)) then
			-- (down, or someone else now: it goes quickly)
			CB.frostThaw(char, st, CB.alive(char, "HalfCold") and ((CB.cfg("Todoroki").Frost or {}).Fade or 1.4) or 0.3)
		end
		if st.thawEnd and now >= st.thawEnd then
			CB.frostKill(char)
			CB.frost[char] = nil
			return
		end
		-- each piece hides with the body part it's on (first person), and
		-- all of it with his look
		local hide = not CB.shown(char, CB.scar(char, st))
		for _, x in st.parts do
			if x.part.Parent then
				x.part.LocalTransparencyModifier = hide and 1 or CB.ltm(x.limb)
			end
		end
		for _, pe in st.emitters or {} do
			pe.Enabled = not hide and not st.thawEnd
		end
	end
	function CB.frostKill(char)
		local st = CB.frost[char]
		if not st then
			return
		end
		for _, x in st.parts do
			x.part:Destroy()
		end
		table.clear(st.parts)
		if st.att then
			for _, pe in st.emitters or {} do
				pe.Enabled = false
			end
			cleanup(st.att, 2) -- (what's in the air drifts off)
			st.att = nil
		end
	end

	-- his left side steams (again from the top: Time more seconds)
	function CB.steamUp(char)
		local S = (CB.cfg("Todoroki").Steam or {})
		local st = CB.steam[char]
		if not st then
			st = { emitters = {}, atts = {} }
			if not CB.shown(char, CB.scar(char, st)) then
				return
			end
			local low = IceKit.lowEnd()
			local mine = Players.LocalPlayer ~= nil and Players.LocalPlayer.Character == char
			for _, spec in CB.STEAM_AT do
				-- (no steam off your own hair: it'd rise past your camera)
				if not (spec[1] == "Hair" and (low or mine)) then
					local part, s = CB.limbFor(char, spec[2], spec[1] == "Arm" and "LeftLowerArm" or nil)
					if part then
						local att = Instance.new("Attachment")
						att.Name = "ShotoSteam"
						att.Position = spec[2] == "Head" and spec[3] * s * 1.2 or spec[3] * part.Size
						att.Parent = part
						local pe = Instance.new("ParticleEmitter")
						pe.Texture = CB.SMOKE
						pe.Color = ColorSequence.new(STEAM, Color3.fromRGB(250, 250, 252))
						pe.LightEmission = 0.1
						pe.LightInfluence = 0.5
						local sz = S.Size or { 0.5, 2.2 }
						pe.Size = NS({ NK(0, sz[1]), NK(0.4, (sz[1] + sz[2]) * 0.55), NK(1, sz[2]) })
						local alpha = S.Alpha or 0.58
						pe.Transparency = NS({ NK(0, 1), NK(0.15, alpha), NK(0.6, math.min(alpha + 0.2, 1)), NK(1, 1) })
						pe.Lifetime = NumberRange.new(1.1, 1.7)
						pe.Speed = NumberRange.new(0.8, 1.8)
						pe.SpreadAngle = Vector2.new(25, 25)
						pe.Acceleration = Vector3.new(0, S.Rise or 2.4, 0)
						pe.Drag = 1.2
						pe.Rotation = NumberRange.new(0, 360)
						pe.RotSpeed = NumberRange.new(-40, 40)
						pe.Rate = 0
						pe.Parent = att
						pe:Emit(S.Puff or 3) -- (a first breath of it)
						table.insert(st.atts, att)
						table.insert(st.emitters, { pe = pe, limb = part, rate = ((S.Rate or {})[spec[1]] or 6) * (low and 0.5 or 1) })
					end
				end
			end
			CB.steam[char] = st
			local root = char:FindFirstChild("HumanoidRootPart")
			if root then
				VFX.PlaySound("ShotoSteam", root.Position + UP, 1)
			end
		end
		st.t0 = os.clock()
		st.untilT = st.t0 + (S.Time or 4.5)
		CB.wake()
	end
	function CB.steamStep(char, st, now)
		if not char.Parent then
			CB.steamKill(char)
			CB.steam[char] = nil
			return
		end
		if not CB.alive(char, "HalfCold") then
			st.untilT = math.min(st.untilT, now)
		end
		local time = math.max((CB.cfg("Todoroki").Steam or {}).Time or 4.5, 0.1)
		local left = math.clamp((st.untilT - now) / time, 0, 1)
		local hide = not CB.shown(char, CB.scar(char, st))
		for _, x in st.emitters do
			x.pe.Rate = x.rate * left ^ 1.3
			x.pe.Enabled = left > 0 and not hide and CB.ltm(x.limb) <= 0.5
		end
		if now >= st.untilT then
			CB.steamKill(char, 2)
			CB.steam[char] = nil
		end
	end
	function CB.steamKill(char, linger)
		local st = CB.steam[char]
		if not st then
			return
		end
		for _, x in st.emitters do
			x.pe.Enabled = false
		end
		for _, att in st.atts do
			if linger then
				cleanup(att, linger) -- (the last of it drifts off)
			else
				att:Destroy()
			end
		end
		table.clear(st.atts)
		table.clear(st.emitters)
	end

	---------------------------------------------------------------------
	-- SHIGARAKI: the hand on his face clenches while he charges
	---------------------------------------------------------------------
	-- his hand's fingers (with their welds) and its palm
	function CB.fingers(char)
		local list, palm = {}, nil
		local cos = CB.cos(char)
		for _, p in cos and cos:GetChildren() or {} do
			if p:IsA("BasePart") then
				if p:GetAttribute("Finger") then
					local w = p:FindFirstChildOfClass("Weld")
					if w then
						table.insert(list, { part = p, weld = w })
					end
				elseif p:GetAttribute("Palm") then
					palm = p
				end
			end
		end
		return list, palm
	end
	-- a finger piece bent a1 at the knuckle and a2 more at the middle joint
	-- (+: up off his face), from where it rests
	function CB.bend(p, rest, a1, a2)
		local kn, jt, ax = p:GetAttribute("Knuckle"), p:GetAttribute("Joint"), p:GetAttribute("Axis")
		if typeof(kn) ~= "Vector3" or typeof(jt) ~= "Vector3" or typeof(ax) ~= "Vector3" or ax.Magnitude < 0.5 then
			return rest
		end
		local cf = rest
		if p:GetAttribute("Seg") == 2 then
			cf = CFrame.new(jt) * CFrame.fromAxisAngle(ax, a2) * CFrame.new(-jt) * cf
		end
		return CFrame.new(kn) * CFrame.fromAxisAngle(ax, a1) * CFrame.new(-kn) * cf
	end
	function CB.flexStart(char, charge)
		local fingers, palm = CB.fingers(char)
		local head = char:FindFirstChild("Head")
		if #fingers == 0 or not head then
			return
		end
		local st = CB.flex[char]
		if not st then
			st = { rest = {}, colors = {} }
			CB.flex[char] = st
		end
		local Z = CB.cfg("Shigaraki")
		st.t0 = os.clock()
		st.charge = math.max(tonumber(charge) or 0.3, (Z.In or 0.08) * 1.5)
		st.released = false
		if CB.shown(char, palm) then
			VFX.PlaySound("DecayKnuckles", head.Position, 1)
		end
		CB.wake()
	end
	-- the middle of his fingers, on his head
	function CB.fingerMid(fingers)
		local sum, n = Vector3.zero, 0
		for _, f in fingers do
			local jt = f.part:GetAttribute("Joint")
			if typeof(jt) == "Vector3" and f.part:GetAttribute("Finger") ~= 5 then
				sum += jt
				n += 1
			end
		end
		return n > 0 and sum / n or Vector3.new(0, 0.3, -0.6)
	end
	function CB.flexStep(char, st, now)
		local Z = CB.cfg("Shigaraki")
		local head = char:FindFirstChild("Head")
		if not (head and CB.alive(char, "Decay")) then
			CB.flexEnd(char)
			CB.flex[char] = nil
			return
		end
		local fingers, palm = CB.fingers(char)
		local e = now - st.t0
		local inT, settle = math.max(Z.In or 0.08, 0.01), math.max(Z.Settle or 0.34, 0.01)
		local k, held
		if e < inT then
			k, held = CB.backOut(e / inT, 0.12), true
		elseif e < st.charge then
			k, held = 1, true
		else
			-- springs open past where it rests, and settles
			local s = math.clamp((e - st.charge) / settle, 0, 1)
			k, held = (1 - s) ^ 2 * math.cos(s * math.pi * 1.5), false
		end
		local w = 2 * math.pi * (Z.TrembleHz or 16)
		local shake = held and e >= inT and math.rad(Z.Tremble or 3.5) or 0
		for _, f in fingers do
			local p = f.part
			if not st.rest[p] then
				st.rest[p] = f.weld.C0
				st.colors[p] = p.Color
			end
			local i = p:GetAttribute("Finger") or 1
			local scale = i == 5 and (Z.Thumb or 0.6) or 1
			local jitter = shake * (math.sin(w * e + i * 1.7) * 0.6 + math.sin(w * 1.37 * e + i * 0.9) * 0.4)
			f.weld.C0 = CB.bend(p, st.rest[p], (math.rad(Z.Curl or 28) * k + jitter) * scale, (math.rad(Z.Claw or -50) * k + jitter * 0.5) * scale)
			local ash = (Z.Ash or 0.45) * math.max(k, 0) * (p:GetAttribute("Seg") == 2 and 1 or 0.5)
			p.Color = st.colors[p]:Lerp(CB.ASH, ash)
		end
		-- dust crumbling off it while it's held (an attachment in his head,
		-- in the middle of his fingers)
		local shown = CB.shown(char, palm)
		if not (st.att and st.att.Parent) then
			local att = Instance.new("Attachment")
			att.Name = "FatherDust"
			att.Position = CB.fingerMid(fingers) + Vector3.new(0, -0.05, -0.18) -- (in front of his fingers, not behind them)
			att.Parent = head
			local pe = Instance.new("ParticleEmitter")
			pe.Texture = CB.SMOKE
			pe.Color = ColorSequence.new(VFX.DecayKit.PAL.DUST_LIGHT, VFX.DecayKit.PAL.DUST)
			pe.LightInfluence = 0.8
			pe.Size = NS({ NK(0, 0.22), NK(1, 0.65) })
			pe.Transparency = NS({ NK(0, 0.25), NK(0.7, 0.55), NK(1, 1) })
			pe.Lifetime = NumberRange.new(0.5, 0.9)
			pe.Speed = NumberRange.new(0.4, 1.4)
			pe.EmissionDirection = Enum.NormalId.Bottom
			pe.SpreadAngle = Vector2.new(70, 70)
			pe.Acceleration = Vector3.new(0, -6, 0)
			pe.Rate = (Z.Dust or 22) * VFX.DecayKit.k()
			pe.Parent = att
			st.att, st.pe = att, pe
		end
		st.pe.Enabled = held and shown
		if not held and not st.released then
			st.released = true
			if shown then
				-- (it springs open: flakes off the fingertips)
				local at = (head.CFrame * CFrame.new(CB.fingerMid(fingers))).Position
				VFX.DecayKit.flakes(at, Z.Flakes or 8, 0.5, VFX.DecayKit.PAL.DUST, VFX.DecayKit.PAL.ASH)
				st.pe:Emit(6)
			end
		end
		if e >= st.charge + settle then
			CB.flexEnd(char)
			CB.flex[char] = nil
		end
	end
	-- back exactly as it was
	function CB.flexEnd(char)
		local st = CB.flex[char]
		if not st then
			return
		end
		for p, rest in st.rest do
			if p.Parent then
				local w = p:FindFirstChildOfClass("Weld")
				if w then
					w.C0 = rest
				end
				p.Color = st.colors[p] or p.Color
			end
		end
		table.clear(st.rest)
		table.clear(st.colors)
		if st.att then
			if st.pe then
				st.pe.Enabled = false
			end
			cleanup(st.att, 1) -- (the last of it falls away)
			st.att, st.pe = nil, nil
		end
	end
end)()

---------------------------------------------------------------------------
-- (round 87) POSSESS on every screen (Config.Possess; the server's Kit.PS,
-- the dev's own machine: QuirkClient's DevFly.PS). The soul going into a
-- body and coming home: a dark wisp - a hot violet core inside a ribbon of
-- black smoke, shedding sparks, coiling round its own line - is pulled out
-- of his chest (a violet ghost of him left for a blink, a ring, the sub
-- suck-out), bows across to the body and goes in (a dark shock ring, smoke
-- bursting off it, the body lit violet from inside, its eyes flaring then
-- fading). Going home it's the other way round, and his body re-forms
-- round it as it lands. On his own screen the world drains while the soul
-- is in the air, and the body's hits land with a freeze and a jolt. His
-- parked body is hidden on every screen (the server clears its parts;
-- anything a screen made on it itself goes too). Config.Possess.Tell: a
-- possessed body keeps dim eyes and a thread of smoke (off by default, so
-- clips stay clean). Cleans up after itself; half the smoke on a low-end
-- machine.
-- (Its own block: the main chunk is at its local limit.)
---------------------------------------------------------------------------
do
	local PSX = {
		hidden = {}, -- [char] = what this screen hid on a parked body. (round 87, in Studio) none of these are weak: the engine can drop an Instance key from a weak table while the instance lives
		settle = {}, -- [char] = until when the scan leaves it as a beat left it (the server's word is on its way)
		eyes = {}, -- [body] = its glowing eyes
		tells = {}, -- [body] = its tell (Config.Possess.Tell)
		HIDE = { "ParticleEmitter", "Light", "Highlight", "Beam", "Trail", "Fire", "Smoke", "Sparkles", "BillboardGui", "SurfaceGui" },
		DARK = Color3.fromRGB(24, 10, 38), SMOKE = Color3.fromRGB(56, 30, 82), HOT = Color3.fromRGB(228, 200, 255),
		WHITE = Color3.new(1, 1, 1),
	}
	VFX.PSX = PSX
	-- the body taking him in: arched back, head snapped up, arms flung out a
	-- moment (held, then it settles); and letting him go: slumped, head down
	POSES.PossessJolt = { Waist = { 14, 0, 0 }, Neck = { 30, 0, 0 }, RightArm = { -18, 0, 38 }, LeftArm = { -18, 0, 38 }, RightElbow = 25, LeftElbow = 25 }
	POSES.PossessSlump = { Waist = { -16, 0, 0 }, Neck = { -34, 0, 0 }, RightArm = { -6, 0, 6 }, LeftArm = { -6, 0, 6 }, RightKnee = 18, LeftKnee = 18 }
	function PSX.cfg()
		return Config.Possess or {}
	end
	function PSX.color()
		return PSX.cfg().Color or Color3.fromRGB(150, 70, 255)
	end
	function PSX.isMine(data)
		local lp = Players.LocalPlayer
		return lp ~= nil and type(data) == "table" and data.Owner == lp.UserId
	end
	function PSX.n(x)
		return VFX.EngineKit.count(x)
	end
	-- a body's chest (where the wisp goes in / comes out)
	function PSX.chest(model)
		local r = typeof(model) == "Instance" and model:FindFirstChild("HumanoidRootPart")
		if not r or not r:IsA("BasePart") then
			return nil
		end
		return r.Position + UP * math.min(r.Size.Y * 0.4, 2)
	end

	---------------------------------------------------------------------------
	-- the parked body: hidden on this screen too
	---------------------------------------------------------------------------
	-- (only what this screen can see is on: the server's own switches it
	-- turns back itself, and a part's own Transparency is the server's -
	-- this screen only adds its LocalTransparencyModifier)
	function PSX.hideParked(char, on)
		local st = PSX.hidden[char]
		if on then
			if st or typeof(char) ~= "Instance" then
				return
			end
			st = { parts = {}, enabled = {} }
			PSX.hidden[char] = st
			local function hide(d)
				if d:IsA("BasePart") then
					st.parts[d] = true
					d.LocalTransparencyModifier = 1
					return
				end
				for _, className in PSX.HIDE do
					if d:IsA(className) then
						if d.Enabled then
							st.enabled[d] = true
							d.Enabled = false
						end
						return
					end
				end
			end
			for _, d in char:GetDescendants() do
				hide(d)
			end
			st.conn = char.DescendantAdded:Connect(hide)
		elseif st then
			PSX.hidden[char] = nil
			if st.conn then
				st.conn:Disconnect()
			end
			for d in st.parts do
				if d.Parent then
					d.LocalTransparencyModifier = 0
				end
			end
			for d in st.enabled do
				if d.Parent then
					d.Enabled = true
				end
			end
		end
	end

	---------------------------------------------------------------------------
	-- the pieces
	---------------------------------------------------------------------------
	-- a ghost of a body: its limbs in flat violet, fading from `from` to
	-- `to` over `life` (a flash in first when `flash`)
	function PSX.ghost(char, color, from, to, life, flash)
		if typeof(char) ~= "Instance" then
			return
		end
		for _, part in char:GetChildren() do
			if part:IsA("BasePart") and part.Name ~= "HumanoidRootPart" then
				local ok, g = pcall(function()
					return part:Clone()
				end)
				if ok and g then
					g:ClearAllChildren()
					if g:IsA("MeshPart") then
						g.TextureID = ""
					end
					g.Name = "PossessGhost"
					g.Anchored = true
					g.CanCollide = false
					g.CanQuery = false
					g.CanTouch = false
					g.CastShadow = false
					g.Massless = true
					g.Material = Enum.Material.Neon
					g.Color = color
					g.LocalTransparencyModifier = 0
					g.Transparency = from
					g.CFrame = part.CFrame
					g.Parent = folder
					if flash then
						tween(g, 0.07, { Transparency = flash })
						tween(g, life, { Transparency = to }, Enum.EasingStyle.Quad, Enum.EasingDirection.In, 0.07)
						cleanup(g, life + 0.12)
					else
						tween(g, life, { Transparency = to })
						cleanup(g, life + 0.05)
					end
				end
			end
		end
	end

	-- THE WISP: from `a` to wherever `bFn()` says (the body may be moving)
	-- over `t`; bowing up Travel.Arc x the distance and coiling round its
	-- line; done(where it landed) as it lands. Returns a stop function.
	function PSX.wisp(a, bFn, t, done, mine)
		local EK = VFX.EngineKit
		local v = PSX.color()
		local hold = EK.holder(CFrame.new(a), t + 1.4, "PossessWisp")
		local core = newPart(Vector3.one * 0.7, CFrame.new(a), PSX.HOT, Enum.Material.Neon, Enum.PartType.Ball)
		core.Name = "PossessCore"
		local shell = newPart(Vector3.one * 1.5, CFrame.new(a), v, Enum.Material.Neon, Enum.PartType.Ball)
		shell.Name = "PossessShell"
		shell.Transparency = 0.55
		local light = Instance.new("PointLight")
		light.Color = v
		light.Brightness = 2.5
		light.Range = 12
		light.Shadows = false
		light.Parent = core
		-- the ribbon: black smoke behind it, a thin hot line in it
		local function trail(width, c0, c1, life, glow)
			local a0 = Instance.new("Attachment")
			a0.Position = Vector3.new(0, width / 2, 0)
			a0.Parent = hold
			local a1 = Instance.new("Attachment")
			a1.Position = Vector3.new(0, -width / 2, 0)
			a1.Parent = hold
			local tr = Instance.new("Trail")
			tr.Name = "PossessTrail"
			tr.Attachment0 = a0
			tr.Attachment1 = a1
			tr.Color = ColorSequence.new(c0, c1)
			tr.Transparency = NumberSequence.new({ NumberSequenceKeypoint.new(0, glow and 0 or 0.1), NumberSequenceKeypoint.new(1, 1) })
			tr.WidthScale = NumberSequence.new({ NumberSequenceKeypoint.new(0, 1), NumberSequenceKeypoint.new(1, 0.15) })
			tr.LightEmission = glow and 1 or 0
			tr.LightInfluence = glow and 0 or 0.4
			tr.Lifetime = life
			tr.FaceCamera = true
			tr.Parent = hold
			return tr
		end
		-- (on his own screen the camera rides right behind it: a lighter smoke,
		-- so the soul leads the eye instead of a black ribbon filling the view)
		local smokeTrail = trail(mine and 0.8 or 1.7, PSX.DARK, PSX.SMOKE, 0.42, false)
		local hotTrail = trail(0.32, PSX.HOT, v, 0.22, true)
		local smoke = EK.emitter(hold, {
			tex = EK.TEX.smoke, color = { PSX.SMOKE, PSX.DARK }, size = { { 0, 1.1 }, { 0.4, 2.2 }, { 1, 3.2 } },
			transp = { { 0, 0.25 }, { 0.6, 0.6 }, { 1, 1 } }, life = { 0.45, 0.8 }, speed = { 0.5, 2 }, spread = 180, drag = 2.5,
			spin = { -60, 60 }, influence = 0.6,
		})
		smoke.Rate = (EK.lowEnd() and 40 or 80) * (mine and 0.35 or 1)
		local sparks = EK.emitter(hold, {
			tex = EK.TEX.spark, color = { PSX.HOT, v }, size = { { 0, 0.45 }, { 1, 0 } }, transp = { { 0, 0 }, { 1, 1 } },
			life = { 0.25, 0.45 }, speed = { 2, 6 }, spread = 180, light = 1, bright = 2, drag = 3,
		})
		sparks.Rate = EK.lowEnd() and 18 or 36
		local ARC = PSX.cfg().Travel and PSX.cfg().Travel.Arc or 0.16
		local t0 = os.clock()
		local over = false
		local conn
		local function finish(at)
			if over then
				return
			end
			over = true
			if conn then
				conn:Disconnect()
			end
			smoke.Enabled = false
			sparks.Enabled = false
			smokeTrail.Enabled = false
			hotTrail.Enabled = false
			tween(core, 0.12, { Size = Vector3.one * 1.6, Transparency = 1 })
			tween(shell, 0.15, { Size = Vector3.one * 3, Transparency = 1 })
			cleanup(core, 0.2)
			cleanup(shell, 0.2)
			if at and done then
				done(at)
			end
		end
		conn = RunService.RenderStepped:Connect(function()
			local ok, err = pcall(function()
				local k = math.clamp((os.clock() - t0) / math.max(t, 0.05), 0, 1)
				-- (it's pulled out slow, flies, and slows into the body)
				local e = k * k * (3 - 2 * k)
				local b = bFn() or a
				local d = b - a
				local dist = d.Magnitude
				local fwd = dist > 0.05 and d.Unit or Vector3.new(0, 0, -1)
				local right = fwd:Cross(UP)
				right = right.Magnitude > 0.1 and right.Unit or Vector3.new(1, 0, 0)
				local up2 = right:Cross(fwd).Unit
				local coil = (right * math.cos(e * 10) + up2 * math.sin(e * 10)) * 0.55 * math.sin(math.pi * e)
				local p = a:Lerp(b, e) + UP * dist * ARC * 4 * e * (1 - e) + coil
				local ahead = a:Lerp(b, math.min(e + 0.05, 1)) + UP * dist * ARC * 4 * math.min(e + 0.05, 1) * (1 - math.min(e + 0.05, 1))
				hold.CFrame = (ahead - p).Magnitude > 0.01 and CFrame.lookAt(p, ahead) or CFrame.new(p)
				local pulse = 1 + 0.18 * math.sin(os.clock() * 30)
				core.CFrame = CFrame.new(p)
				shell.CFrame = CFrame.new(p)
				shell.Size = Vector3.one * 1.5 * pulse
				if k >= 1 then
					finish(b)
				end
			end)
			if not ok then
				warn("[VFX] possess wisp: " .. tostring(err))
				finish(nil)
			end
		end)
		return function()
			finish(nil)
		end
	end

	-- the eyes: a dummy's lit in its head (two hot violet points, a glow); the
	-- raid's Nomu's own (its puppet's, on this screen) burning violet. They
	-- flare and fade - or (hold) stay, dim: the tell
	function PSX.lightEyes(body, hold)
		PSX.dimEyes(body, true)
		if typeof(body) ~= "Instance" then
			return
		end
		local st = { parts = {}, made = {} }
		PSX.eyes[body] = st
		local NMV = VFX.NMV
		local pp = NMV and NMV.bodyModel and NMV.bodyModel() == body and NMV.r and NMV.r.pp
		if pp then
			for _, e in pp.parts do
				local p = e.part
				if e.key == "head" and p.Shape == Enum.PartType.Ball and p.Color == PSX.WHITE then
					st.parts[p] = { p.Color, p.Material }
					p.Color = PSX.HOT
					p.Material = Enum.Material.Neon
				end
			end
		else
			local head = body:FindFirstChild("Head")
			if not (head and head:IsA("BasePart")) then
				return
			end
			local s = head.Size
			local d = math.clamp(math.min(s.X, s.Y) * 0.16, 0.14, 0.38)
			for side = -1, 1, 2 do
				local at = CFrame.new(side * s.X * 0.2, s.Y * 0.1, -s.Z * 0.5 + 0.03)
				local eye = newPart(Vector3.one * 0.05, head.CFrame * at, PSX.HOT, Enum.Material.Neon, Enum.PartType.Ball)
				eye.Name = "PossessEye"
				VFX.EngineKit.weld(eye, head, at)
				tween(eye, 0.1, { Size = Vector3.one * d * 1.8 })
				tween(eye, 0.3, { Size = Vector3.one * d }, nil, nil, 0.1)
				table.insert(st.made, eye)
			end
			local glow = Instance.new("PointLight")
			glow.Name = "PossessEyeGlow"
			glow.Color = PSX.color()
			glow.Brightness = 3
			glow.Range = 6
			glow.Shadows = false
			glow.Parent = head
			table.insert(st.made, glow)
		end
		if hold then
			for _, x in st.made do
				if x:IsA("BasePart") then
					tween(x, 0.6, { Transparency = 0.35 }, nil, nil, 0.4)
				end
			end
		else
			task.delay(1.4, function()
				if PSX.eyes[body] == st then
					PSX.dimEyes(body)
				end
			end)
		end
	end
	function PSX.dimEyes(body, now)
		local st = PSX.eyes[body]
		if not st then
			return
		end
		PSX.eyes[body] = nil
		for p, was in st.parts do
			if p.Parent then
				p.Color, p.Material = was[1], was[2]
			end
		end
		for _, x in st.made do
			if now or not x:IsA("BasePart") then
				x:Destroy()
			else
				tween(x, 0.4, { Transparency = 1, Size = Vector3.one * 0.05 })
				cleanup(x, 0.45)
			end
		end
	end

	-- out of a body: smoke, a ring, the suck-out
	function PSX.depart(char, at, sound)
		local v = PSX.color()
		dustPuffs(at - UP * 0.4, 0.45, PSX.n(5), PSX.SMOKE, 0.6, false)
		billboardRing(at, 1, 7, v, 4, 0.3)
		if sound then
			VFX.PlaySound(sound, at, 1)
		end
	end
	-- into a body: the shock, smoke off it, lit from inside, the eyes
	function PSX.arrive(body, at, mine)
		local v = PSX.color()
		billboardRing(at, 2, 14, v, 6, 0.35)
		billboardRing(at, 1, 7, PSX.HOT, 3, 0.2)
		local EK = VFX.EngineKit
		local h = EK.holder(CFrame.new(at), 1.6, "PossessBurst")
		local pe = EK.emitter(h, {
			tex = EK.TEX.smoke, color = { PSX.SMOKE, PSX.DARK }, size = { { 0, 1.5 }, { 0.5, 3.4 }, { 1, 4.5 } },
			transp = { { 0, 0.2 }, { 0.6, 0.55 }, { 1, 1 } }, life = { 0.5, 0.9 }, speed = { 10, 18 }, spread = 180, drag = 5,
			spin = { -80, 80 }, influence = 0.5,
		})
		pe:Emit(PSX.n(18))
		-- (the raid's Nomu is drawn by its puppet: that's what lights)
		local NMV = VFX.NMV
		local pp = NMV and NMV.bodyModel and NMV.bodyModel() == body and NMV.r and NMV.r.pp
		local hl = Instance.new("Highlight")
		hl.Name = "PossessFlash"
		hl.FillColor = v
		hl.FillTransparency = 0.25
		hl.OutlineColor = PSX.HOT
		hl.OutlineTransparency = 0
		hl.DepthMode = Enum.HighlightDepthMode.Occluded
		hl.Adornee = pp and pp.model or body
		hl.Parent = folder
		tween(hl, 0.6, { FillTransparency = 1, OutlineTransparency = 1 })
		cleanup(hl, 0.65)
		-- (a dummy jolts as he goes in; the raid's Nomu is its puppet's to pose)
		if not pp and typeof(body) == "Instance" and body:FindFirstChild("Head") then
			VFX.Pose(body, "PossessJolt", 0.3)
		end
		VFX.PlaySound("PossessIn", at, 1)
		if mine then
			VFX.Shake(0.5, 0.25)
		end
	end
	-- home: his body comes back round the wisp (a violet flash of it, a ring)
	function PSX.reform(char, at, mine)
		if typeof(char) == "Instance" then
			PSX.settle[char] = os.clock() + 0.8
			PSX.hideParked(char, false)
			PSX.ghost(char, PSX.color(), 0.85, 1, 0.38, 0.15)
		end
		billboardRing(at, 1, 9, PSX.color(), 5, 0.3)
		dustPuffs(at - UP * 2.4, 0.5, PSX.n(5), PSX.SMOKE, 0.55, false)
		VFX.PlaySound("PossessReform", at, 1)
		if mine then
			VFX.Shake(0.35, 0.2)
		end
	end

	-- his own screen while the soul's in the air: the world drains, cold violet
	function PSX.tint(t)
		local L = game:GetService("Lighting")
		local cc = L:FindFirstChild("PossessTint")
		if not cc then
			cc = Instance.new("ColorCorrectionEffect")
			cc.Name = "PossessTint"
			cc.Parent = L
		end
		cc.Enabled = true
		cc.TintColor = Color3.fromRGB(228, 216, 255)
		cc.Saturation = -0.45
		cc.Contrast = 0.12
		cc.Brightness = -0.03
		PSX.tintToken = (PSX.tintToken or 0) + 1
		local token = PSX.tintToken
		task.delay(t, function()
			if PSX.tintToken ~= token or not cc.Parent then
				return
			end
			tween(cc, 0.35, { TintColor = PSX.WHITE, Saturation = 0, Contrast = 0, Brightness = 0 })
			task.delay(0.4, function()
				if PSX.tintToken == token and cc.Parent then
					cc:Destroy()
				end
			end)
		end)
	end
	function PSX.untint()
		PSX.tintToken = (PSX.tintToken or 0) + 1
		local cc = game:GetService("Lighting"):FindFirstChild("PossessTint")
		if cc then
			cc:Destroy()
		end
	end

	---------------------------------------------------------------------------
	-- the beats (the server sends them to everyone)
	---------------------------------------------------------------------------
	-- data: { Kind = "In" | "Out", From, To (Out), Body, Char (his own), Owner
	-- (his UserId), Travel, Hop (In: from another body) }
	function Effects.Possess(_, data)
		local body, char = data.Body, data.Char
		local mine = PSX.isMine(data)
		local t = math.clamp(tonumber(data.Travel) or 0.5, 0.05, 2)
		local function bodyAt()
			return PSX.chest(body)
		end
		if data.Kind == "In" then
			local to0 = bodyAt()
			local from = typeof(data.From) == "Vector3" and data.From or to0
			if not from or not to0 then
				return
			end
			if data.Hop then
				PSX.depart(nil, from, "PossessBack")
			else
				-- (the ghost first: it's made from his body, before it goes)
				PSX.ghost(char, PSX.color(), 0.3, 1, 0.45)
				if typeof(char) == "Instance" then
					PSX.settle[char] = os.clock() + 0.8
				end
				PSX.hideParked(char, true)
				PSX.depart(char, from, "PossessOut")
			end
			if mine then
				PSX.tint(t)
			end
			PSX.wisp(from, function()
				return bodyAt() or to0
			end, t, function(at)
				PSX.arrive(body, at, mine)
				PSX.lightEyes(body, PSX.cfg().Tell == true)
			end, mine)
		elseif data.Kind == "Out" then
			local from = typeof(data.From) == "Vector3" and data.From or bodyAt()
			local to = typeof(data.To) == "Vector3" and data.To or nil
			if not from or not to then
				return
			end
			if typeof(body) == "Instance" then
				PSX.lightEyes(body, false) -- (one last flare as it goes out of them)
				task.delay(0.15, PSX.dimEyes, body)
				-- (a dummy slumps as it leaves: head down, its own again)
				if body:FindFirstChild("Head") then
					VFX.Pose(body, "PossessSlump", 0.5)
				end
			end
			PSX.depart(nil, from, "PossessBack")
			if mine then
				PSX.tint(t)
			end
			PSX.wisp(from, function()
				return to
			end, t, function(at)
				PSX.reform(char, at, mine)
			end, mine)
		end
	end
	-- a possessed body's punch landing: it freezes on the contact like a
	-- hero's does; on its dev's screen, the jolt (and on the 4th, the frame)
	function Effects.PossessHit(body, data)
		local stop = math.min(tonumber(data.Hitstop) or 0, 0.2)
		if stop > 0 and typeof(body) == "Instance" then
			VFX.Hitstop(body, stop)
		end
		if PSX.isMine(data) then
			VFX.Shake(data.Heavy and 1.1 or 0.35, stop + 0.06)
			if data.Heavy then
				VFX.ImpactFrame(0.045)
			end
		end
	end
	-- the server said no (or K found nothing to take)
	PSX.DENY = {
		NotABody = "NOTHING TO TAKE - AIM AT A DUMMY OR THE NOMU",
		Taken = "SOMEONE'S ALREADY IN THAT ONE",
		Busy = "NOT NOW - IT'S BUSY",
		You = "NOT NOW - YOU'RE BUSY",
	}
	function Effects.PossessDeny(_, data)
		VFX.PlaySound("PossessDeny", nil, 1)
		if VFX.Hooks.Callout then
			VFX.Hooks.Callout(PSX.DENY[data and data.Why or ""] or PSX.DENY.NotABody, PSX.color():Lerp(PSX.WHITE, 0.35))
		end
	end

	---------------------------------------------------------------------------
	-- every quarter second: parked bodies hidden (whoever's screen joined
	-- late), and the tell
	---------------------------------------------------------------------------
	function PSX.scan()
		local now = os.clock()
		-- (round 87, in Studio: the tables aren't weak any more) bodies gone from the game
		for c in PSX.settle do
			if not c.Parent then
				PSX.settle[c] = nil
			end
		end
		for _, plr in Players:GetPlayers() do
			local c = plr.Character
			if c and now >= (PSX.settle[c] or 0) then
				local parked = c:GetAttribute("Parked") == true
				if parked ~= (PSX.hidden[c] ~= nil) then
					PSX.hideParked(c, parked)
				end
			end
		end
		for c in PSX.hidden do
			if not c.Parent then
				PSX.hidden[c] = nil
			end
		end
		local tell = PSX.cfg().Tell == true
		for _, name in PSX.cfg().Folders or { "Dummies", "NomuRaid" } do
			local f = workspace:FindFirstChild(name)
			for _, m in f and f:GetChildren() or {} do
				local on = tell and m:GetAttribute("Possessed") == true
				if on and not PSX.tells[m] then
					PSX.tell(m)
				end
			end
		end
		for m, t in PSX.tells do
			if not (tell and m.Parent and m:GetAttribute("Possessed") == true) then
				PSX.tells[m] = nil
				t:Destroy()
				PSX.dimEyes(m)
			end
		end
	end
	-- (Tell) a thread of dark smoke off it, and its eyes kept lit, dim
	function PSX.tell(m)
		local root = m:FindFirstChild("HumanoidRootPart")
		if not root then
			return
		end
		local EK = VFX.EngineKit
		local h = EK.holder(root.CFrame, nil, "PossessTell")
		EK.weld(h, root, CFrame.new(0, -1, 0))
		local pe = EK.emitter(h, {
			tex = EK.TEX.smoke, color = { PSX.SMOKE, PSX.DARK }, size = { { 0, 0.8 }, { 1, 2.2 } }, transp = { { 0, 0.55 }, { 1, 1 } },
			life = { 0.8, 1.3 }, speed = { 0.5, 1.5 }, spread = 60, dir = "Top", accel = Vector3.new(0, 2, 0), influence = 0.6,
		})
		pe.Rate = EK.lowEnd() and 3 or 6
		PSX.tells[m] = h
		if not PSX.eyes[m] then
			PSX.lightEyes(m, true)
		end
	end
	task.spawn(function()
		while true do
			task.wait(0.25)
			local ok, err = pcall(PSX.scan)
			if not ok then
				warn("[VFX] possess: " .. tostring(err))
			end
		end
	end)
end

---------------------------------------------------------------------------
-- (round 88) THE CARRY (Config.DevFlight.Carry) on every screen: the dev
-- flight's 5th move, Omni-Man's grab. Who's carrying whom is the server's
-- (the body's CarriedBy, CarryState); every screen hangs the body off his
-- fist itself each frame before it's drawn (Config.DevFlight.Carry.at from
-- where his root is on that screen - the server's own copy of the body only
-- arrives a moment later and a little apart), so it never jitters or lags
-- behind him at 500 studs a second. His poses (anim/moves_carry.py, the
-- POSES below as the fallback): the hold by the collar in the hover, the
-- fist ahead in flight, both fists ahead in the dive and the ram, the grab,
-- the throw, the slam's kneel in the crater (the flight's pose picker asks
-- CRX.poseFor). Theirs: held up kicking, gone limp at speed. The beats
-- (Effects.DevCarry: Reach, Grab, Miss, Slam, Impact, Throw, Ram, Release):
-- the grip's snap and them yanked off the street, the slam's impact (the
-- deepest sound the game has, a body-print dent, cracks, a geyser of dust
-- and rock - on top of the flight's own crash), the hurl (a shock ring, a
-- streak off them as they go), the ram's punch-in. Half as much on a
-- low-end machine. (Its own block: the main chunk is at its local limit.
-- Round 87's lesson: plain tables, cleared when each carry ends.)
---------------------------------------------------------------------------
do
	local CRX = {
		pairs = {}, -- [the body carried] = { victim, vroot, carrier, croot, state, stateAt, ... }
		carriers = {}, -- [his body] = that pair
		busy = {}, -- [his body] = { untilAt } a beat of his playing (the flight's poses wait)
		shown = {}, -- [his body] = when his own screen showed the slam's impact (once)
		bound = false,
	}
	VFX.CRX = CRX
	function CRX.cfg()
		return (Config.DevFlight or {}).Carry or {}
	end
	function CRX.n(x)
		return VFX.EngineKit and VFX.EngineKit.count(x) or x
	end
	CRX.SHOCK = Color3.fromRGB(240, 246, 255)

	-- the poses (the fallback when the place has no R6 clip: anim/moves_carry.py)
	POSES.CarryHold = { RightArm = { 124, 0, 18 }, LeftArm = { -16, 0, 12 }, RightLeg = -4, LeftLeg = 10, Waist = { -5, 0, 0 }, Neck = { 6, 0, 0 } }
	POSES.CarryFly = { RightArm = { 170, 0, 10 }, LeftArm = { -34, 0, 24 }, RightLeg = -4, LeftLeg = -14, Waist = { -6, 0, 0 }, Neck = { 56, 0, 0 } }
	POSES.CarryPush = { RightArm = { 174, 0, -2 }, LeftArm = { 174, 0, -2 }, RightLeg = 0, LeftLeg = -3, Waist = { 2, 0, 0 }, Neck = { 64, 0, 0 } }
	POSES.Carried = { RightArm = { 146, 0, 6 }, LeftArm = { 140, 0, 6 }, RightLeg = -12, LeftLeg = 16, Neck = { 16, 0, 0 } }
	POSES.CarriedLimp = { RightArm = { 72, 0, 40 }, LeftArm = { 66, 0, 44 }, RightLeg = 34, LeftLeg = 26, Neck = { 34, 0, 0 } }
	POSES.CarrySlamDown = { Crouch = 1.35, Waist = { -44, 0, 0 }, Neck = { -20, 0, 0 }, RightArm = { 30, 0, 6 }, LeftArm = { -70, 0, 46 }, RightLeg = 40, LeftLeg = -40 }
	MOTIONS.CarryGrab = {
		{ pose = { RightArm = { 28, 0, 16 }, LeftArm = { -12, 0, 12 }, Waist = { 4, 0, 0 } }, t = 0.05 },
		{ pose = { RightArm = { 108, 0, 12 }, LeftArm = { -24, 0, 14 }, Waist = { 12, 0, 0 } }, t = 0.05, hold = 0.06 },
		{ pose = "CarryHold", t = 0.12, hold = 0.1 },
		recover = 0.2,
	}
	MOTIONS.CarryThrow = {
		{ pose = { RightArm = { 206, 0, 22 }, LeftArm = { 36, 0, 16 }, Waist = { -16, 0, 0 } }, t = 0.15 },
		{ pose = { RightArm = { 62, 0, 8 }, LeftArm = { -40, 0, 30 }, Waist = { 18, 0, 0 } }, t = 0.06, hold = 0.1 },
		{ pose = { RightArm = { 34, 0, 6 }, LeftArm = { -46, 0, 32 }, Waist = { 22, 0, 0 } }, t = 0.1, hold = 0.12 },
		recover = 0.3,
	}
	MOTIONS.CarrySlam = {
		{ pose = "CarrySlamDown", t = 0.04, hold = 0.7 },
		recover = 0.35,
	}

	-- who carries this body (the server's CarriedBy: his UserId)
	function CRX.playerById(id)
		if type(id) ~= "number" then
			return nil
		end
		for _, plr in Players:GetPlayers() do
			if plr.UserId == id then
				return plr
			end
		end
		return nil
	end
	function CRX.carrierOf(model)
		local plr = model and CRX.playerById(model:GetAttribute("CarriedBy"))
		return plr and plr.Character
	end
	function CRX.isMine(char)
		local lp = Players.LocalPlayer
		return lp ~= nil and char ~= nil and lp.Character == char
	end
	function CRX.scaleOf(char)
		local ok, s = pcall(function()
			return char:GetScale()
		end)
		return (ok and type(s) == "number" and s == s) and math.clamp(s, 0.5, 4) or 1
	end

	-- a carry starts on this screen (the server's grab, or its CarriedBy)
	function CRX.start(model, carrier)
		local p = CRX.pairs[model]
		if p then
			return p
		end
		carrier = carrier or CRX.carrierOf(model)
		local vroot = model and model:FindFirstChild("HumanoidRootPart")
		local croot = carrier and carrier:FindFirstChild("HumanoidRootPart")
		if not (vroot and croot) or carrier == model then
			return nil
		end
		local old = CRX.carriers[carrier]
		if old then
			CRX.stop(old.victim)
		end
		p = {
			victim = model, vroot = vroot, carrier = carrier, croot = croot, mine = CRX.isMine(carrier),
			state = model:GetAttribute("CarryState") or "Hold", stateAt = os.clock(), made = {}, scale = CRX.scaleOf(carrier),
		}
		CRX.pairs[model] = p
		CRX.carriers[carrier] = p
		p.conn = model:GetAttributeChangedSignal("CarryState"):Connect(function()
			local s = model:GetAttribute("CarryState")
			if s and s ~= p.state then
				p.state, p.stateAt = s, os.clock()
			end
		end)
		if not CRX.bound then
			CRX.bound = true
			-- (before the camera: the one carried may be this screen's own body)
			RunService:BindToRenderStep("QuirkCarryPlace", Enum.RenderPriority.Camera.Value - 5, CRX.place)
		end
		return p
	end
	-- the carry's over on this screen: their body back to the server's, posed no more
	function CRX.stop(model)
		local p = model and CRX.pairs[model]
		if not p then
			return
		end
		CRX.pairs[model] = nil
		if CRX.carriers[p.carrier] == p then
			CRX.carriers[p.carrier] = nil
		end
		if p.conn then
			p.conn:Disconnect()
		end
		for _, x in p.made do
			pcall(x.Destroy, x)
		end
		if model.Parent and not model:GetAttribute("Ragdolled") then
			VFX.ReleasePose(model, 0.25)
		end
		if VFX.DFX and VFX.DFX.posed[p.carrier] and string.sub(VFX.DFX.posed[p.carrier].name or "", 1, 5) == "Carry" then
			VFX.DFX.posed[p.carrier] = nil -- (his flight's own pose again)
		end
		if next(CRX.pairs) == nil and CRX.bound then
			CRX.bound = false
			pcall(function()
				RunService:UnbindFromRenderStep("QuirkCarryPlace")
			end)
		end
	end
	function CRX.clear()
		for model in CRX.pairs do
			CRX.stop(model)
		end
		table.clear(CRX.busy)
		table.clear(CRX.shown)
	end

	-- every frame, before it's drawn: each carried body in his fist (where his
	-- root is on this screen), and its pose
	function CRX.place()
		local C = CRX.cfg()
		local now = os.clock()
		for model, p in CRX.pairs do
			if not model.Parent or not p.vroot.Parent or not p.croot.Parent or not p.carrier.Parent then
				CRX.stop(model)
			elseif p.vroot.Anchored then -- (the server's hold is on: never a body this machine owns)
				local speed = p.croot.AssemblyLinearVelocity.Magnitude
				local F = p.mine and VFX.DevFly and VFX.DevFly.F
				if F and typeof(F.vel) == "Vector3" then
					speed = F.vel.Magnitude
				end
				-- (the slam: him down on the street before the impact's word - they
				-- stay where they hit, not up over him standing)
				local tier = VFX.DFX and VFX.DFX.tierOf(p.carrier)
				local landed = p.state == "Slam" and (tier == nil or tier == "Crash" or tier == "Land" or tier == "Soft")
				local cf = p.down or (not landed and C.at and C.at(p.croot.CFrame, speed, p.state, now - p.stateAt, p.scale)) or nil
				if cf and cf == cf then
					p.vroot.CFrame = cf
				end
				CRX.pose(p, speed, now)
			end
		end
	end

	-- the one he holds: kicking (re-struck so the kicks keep going), limp at
	-- speed or in the slam; given back if anything else poses them
	function CRX.pose(p, speed, now)
		local v = p.victim
		if v:GetAttribute("Ragdolled") or p.down then
			return
		end
		local want = (p.state == "Slam" or p.state == "Ram" or speed > 160) and "CarriedLimp" or "Carried"
		local token = VFX.PoseToken(v)
		local due = want ~= p.vname or (p.vtoken ~= nil and token ~= p.vtoken) or now - (p.vat or 0) > (want == "Carried" and 0.85 or 4)
		if due and now - (p.vat or 0) > 0.25 then
			p.vname, p.vat = want, now
			VFX.Pose(v, want, want == "Carried" and 1.05 or -1)
			p.vtoken = VFX.PoseToken(v)
		end
		-- (his hold jolts now and then: they're kicking)
		local D = VFX.DFX
		local cur = D and D.posed[p.carrier]
		if cur and cur.name == "CarryHold" and now - cur.at > (p.jolt or 1.2) then
			p.jolt = rand(0.9, 1.6)
			D.posed[p.carrier] = nil
		end
	end

	-- the flight's pose picker asks: holding someone, his poses are the
	-- carry's; a beat of his playing, nothing (nil) till it's done
	function CRX.poseFor(char, tier, name)
		local b = CRX.busy[char]
		if b then
			if os.clock() < b.untilAt then
				return nil
			end
			CRX.busy[char] = nil
		end
		local p = CRX.carriers[char]
		if not p then
			return name
		end
		if tier == "Hover" then
			return "CarryHold"
		end
		if tier == "Boost" or tier == "Dive" or p.state == "Ram" or p.state == "Slam" then
			return "CarryPush"
		end
		if tier == "Cruise" or tier == "Fast" or tier == "Hyper" then
			return "CarryFly"
		end
		return name
	end
	-- one of his beats (a clip, or the fallback motion), for len s
	function CRX.oneShot(char, motion, len)
		if not char or not char.Parent then
			return
		end
		CRX.busy[char] = { untilAt = os.clock() + len }
		if VFX.DFX then
			VFX.DFX.posed[char] = { name = "Move" .. motion, at = os.clock() }
		end
		VFX.Motion(char, motion)
	end
	-- (a state his own screen played ahead of the server's word: kept, not restarted)
	function CRX.setState(char, state)
		local p = CRX.carriers[char]
		if p and p.state ~= state then
			p.state, p.stateAt = state, os.clock()
		end
		return p
	end

	-- a streak off them as they go (thrown, flung on)
	function CRX.trail(model, life)
		if not (VFX.DFX and model and model.Parent) then
			return
		end
		local t = VFX.DFX.bodyTrail(model, 1.6, 0.32, CRX.SHOCK, 0.2, 0.4)
		if t then
			task.delay(life or 1, function()
				VFX.DFX.dropTrail(t)
			end)
		end
	end

	CRX.BEATS = {}
	-- the reach (his own screen, at once): the arm shot out, a swish
	function CRX.BEATS.Reach(char, data, isLocal)
		local root = charParts(char)
		if not root then
			return
		end
		CRX.oneShot(char, "CarryGrab", 0.3)
		local d = (typeof(data.Dir) == "Vector3" and data.Dir.Magnitude > 0.01) and data.Dir.Unit or root.CFrame.LookVector
		streaks(root.Position + UP * 0.8, d, CRX.n(5), 0.6, 4, 9, WIND, 0.2)
		VFX.PlaySound("DevCarryReach", (not isLocal) and root.Position or nil, 1)
	end
	-- THE GRAB: the grip - a white snap at the collar, a ring - them yanked
	-- off the street (dust, grit), now hanging off his fist; a jolt for both
	function CRX.BEATS.Grab(char, data, isLocal)
		local model = data.Target
		if typeof(model) ~= "Instance" or not model.Parent then
			return
		end
		CRX.start(model, char)
		local vroot = model:FindFirstChild("HumanoidRootPart")
		if not vroot then
			return
		end
		local EK = VFX.EngineKit
		local collar = (vroot.CFrame * CFrame.new(0, 0.9, -0.55)).Position
		EK.starSpark(collar, { color = CRX.SHOCK, color2 = CRX.cfg().Color or WIND, size = 3.2, life = 0.1 })
		billboardRing(collar, 1, 9, CRX.SHOCK, 3, 0.25)
		local hit = groundRay(vroot.Position, 6)
		if hit and VFX.DFX then
			local dust = VFX.DFX.dustOf(hit)
			dustPuffs(hit.Position + UP * 0.2, 0.5, CRX.n(6), dust, 0.8, false)
			VFX.DFX.chunks(hit.Position + UP * 0.4, UP, 4, { spread = 0.8, speed = { 12, 26 }, size = { 0.25, 0.6 }, up = 0.4, life = 1.4 })
		end
		VFX.PlaySound("DevCarryGrab", collar, 1)
		if CRX.isMine(model) then
			VFX.Shake(1.0, 0.3)
			EK.fovPunch(-6, 0.04, 0.3, 0.05)
			VFX.Hooks.Flash(Color3.new(1, 1, 1), 0.06)
		elseif CRX.isMine(char) then
			VFX.Shake(0.6, 0.2)
		else
			VFX.ShakeAt(collar, 0.6, 40, 0.2)
			CRX.oneShot(char, "CarryGrab", 0.3) -- (his own screen reached already)
		end
	end
	-- nobody in reach, or it didn't take (his screen only)
	function CRX.BEATS.Miss()
		VFX.PlaySound("DevCarryMiss", nil, 1)
		if VFX.Hooks.Callout then
			VFX.Hooks.Callout("MISSED", Color3.fromRGB(200, 222, 236))
		end
	end
	-- THE SLAM's dive: they go limp (the dive's own scream and mark are the flight's)
	function CRX.BEATS.Slam(char)
		local p = CRX.setState(char, "Slam")
		if p and p.vroot.Parent then
			streaks(p.vroot.Position, -UP, CRX.n(6), 1.2, 6, 14, WIND, 0.25)
		end
	end
	-- THE SLAM's impact: on top of the flight's crash - a dent the shape of
	-- a body, cracks out of it, a geyser of dust and rock, the deepest sound
	-- in the game, the impact frame; him knelt over them, fist in the street
	function CRX.BEATS.Impact(char, data, isLocal)
		local g = typeof(data.Pos) == "Vector3" and data.Pos or nil
		if not g then
			return
		end
		-- (his own screen showed it the moment he hit: not twice)
		if not isLocal and CRX.shown[char] and os.clock() - CRX.shown[char] < 2 then
			CRX.shown[char] = nil
			return
		end
		local C = CRX.cfg()
		local face = typeof(data.Face) == "Vector3" and data.Face or Vector3.new(0, 0, -1)
		local down = C.downAt and C.downAt(g, face)
		if isLocal then
			CRX.shown[char] = os.clock()
			local p = CRX.carriers[char]
			if p and down then
				p.down = down -- (lying in it on his screen at once; the server's word lets go of it)
				VFX.ReleasePose(p.victim, 0.06) -- (flat out in it, not still held up)
			end
		end
		local at = down and Vector3.new(down.Position.X, g.Y, down.Position.Z) or g
		local R = math.clamp(tonumber(data.Radius) or (C.Slam or {}).Crater or 6.5, 3, 14)
		local D = VFX.DFX
		local EK = VFX.EngineKit
		local P = D and D.PAL or {}
		local hit = groundRay(at + UP * 2, 8)
		local dust = D and D.dustOf(hit) or Color3.fromRGB(178, 166, 150)
		groundMark(at + UP * 0.03, 3.2, P.CRATER or Color3.fromRGB(64, 60, 58), 12)
		groundMark(at + UP * 0.05, 1.8, P.CRACK or Color3.fromRGB(40, 38, 36), 12)
		EK.cracks(at, R * 2.3, 11, { life = 8, grow = 0.08 })
		EK.starSpark(at + UP, { color = CRX.SHOCK, color2 = Color3.new(1, 1, 1), size = 7, life = 0.12 })
		shockDisc(g + UP * 0.3, UP, 3, R * 5, 0.35, CRX.SHOCK)
		billboardRing(g + UP * 1.5, 2, R * 5, CRX.SHOCK, 4, 0.4)
		if D then
			D.chunks(at + UP, UP, 14, { spread = 0.9, speed = { 40, 85 }, size = { 0.5, 1.6 }, up = 0.6, life = 2.6 })
		end
		smokeBurst(at + UP * 2.5, dust, R * 1.2, R * 0.7, 1.6, CRX.n(24))
		rocks(at, 1.2, CRX.n(8))
		VFX.PlaySound("DevCarrySlam", g, 1)
		local me = Players.LocalPlayer
		local cam = workspace.CurrentCamera
		local dist = cam and (cam.Focus.Position - g).Magnitude or 0
		if isLocal or (me and data.Target == me.Character) then
			VFX.ImpactFrame(0.07)
			VFX.Shake(2, 0.6)
			VFX.Hitstop(char, 0.1)
		else
			if dist < 120 then
				VFX.ImpactFrame(0.05)
			end
			VFX.ShakeAt(g, 2, 220, 0.6)
		end
		CRX.oneShot(char, "CarrySlam", 1.1)
	end
	-- THE THROW's wind-up: swung back over his shoulder
	function CRX.BEATS.Throw(char, _data, isLocal)
		CRX.setState(char, "Throw")
		local root = charParts(char)
		CRX.oneShot(char, "CarryThrow", 0.62)
		VFX.PlaySound("DevCarryWindup", (not isLocal and root) and root.Position or nil, 1)
	end
	-- THE RAM's punch-in: a flash at them, rings shed, the wind tearing
	function CRX.BEATS.Ram(char, data, isLocal)
		local p = CRX.setState(char, "Ram")
		local root = charParts(char)
		local at = (p and p.vroot.Parent and p.vroot.Position) or (root and root.Position)
		if not at then
			return
		end
		local d = (typeof(data.Dir) == "Vector3" and data.Dir.Magnitude > 0.01) and data.Dir.Unit or (root and root.CFrame.UpVector) or UP
		if VFX.DFX then
			VFX.DFX.flashBall(at, 4, 12, 0.12)
		end
		billboardRing(at, 3, 24, CRX.SHOCK, 3, 0.3)
		VFX.EngineKit.vaporRings(at - d * 2, -d, 2, { size = 4.5, gap = 5 })
		VFX.PlaySound("DevCarryRam", (not isLocal and root) and root.Position or nil, 1)
		if isLocal then
			VFX.Shake(0.9, 0.3)
			if VFX.Hooks.FlightBurst then
				VFX.Hooks.FlightBurst(0.3)
			end
		end
	end
	-- LET GO: thrown / flung on (a shock ring where they left his hand, a
	-- streak off them), or just dropped (a flap of cloth)
	function CRX.BEATS.Release(_char, data)
		local model = data.Target
		CRX.stop(model)
		local pos = typeof(data.Pos) == "Vector3" and data.Pos or nil
		if not pos then
			return
		end
		local why = data.Why
		local me = Players.LocalPlayer
		if why == "Throw" or why == "RamEnd" then
			local d = (typeof(data.Dir) == "Vector3" and data.Dir.Magnitude > 0.01) and data.Dir.Unit or UP
			VFX.EngineKit.starSpark(pos, { color = CRX.SHOCK, color2 = Color3.new(1, 1, 1), size = 4, life = 0.1 })
			billboardRing(pos, 2, 16, CRX.SHOCK, 3, 0.3)
			shockDisc(pos, d, 2, 11, 0.25, CRX.SHOCK, 4)
			streaks(pos, d, CRX.n(10), 1.5, 8, 22, WIND, 0.3)
			VFX.EngineKit.vaporRings(pos + d * 2, d, 1, { size = 4 })
			CRX.trail(model, why == "RamEnd" and 1.2 or 1)
			VFX.PlaySound("DevCarryThrow", pos, why == "RamEnd" and 1.1 or 1)
			if me and model == me.Character then
				VFX.Shake(1.2, 0.35)
				VFX.EngineKit.fovPunch(10, 0.05, 0.5, 0.05)
				VFX.Hooks.SpeedLines(0.5)
			end
		elseif why == "Drop" or why == "Time" or why == "Hit" or why == "Lost" then
			VFX.PlaySound("DevCarryRelease", pos, 1)
			dustPuffs(pos + UP, 0.3, CRX.n(3), WIND, 0.5, false)
		end
	end
	function Effects.DevCarry(char, data, isLocal)
		local beat = CRX.BEATS[data.Kind]
		if beat then
			beat(char, data, isLocal)
		end
	end

	-- (every 0.25 s) a carry this screen hasn't heard of yet (it came in
	-- before this screen had the bodies: CarriedBy), one that's over, and
	-- beats long done
	function CRX.scan()
		local now = os.clock()
		for model, p in CRX.pairs do
			local by = CRX.carrierOf(model)
			if not model.Parent or model:GetAttribute("CarriedBy") == nil or (by and by ~= p.carrier) then
				CRX.stop(model)
			end
		end
		local function look(model)
			if model:IsA("Model") and model:GetAttribute("CarriedBy") and not CRX.pairs[model] then
				CRX.start(model)
			end
		end
		for _, plr in Players:GetPlayers() do
			if plr.Character then
				look(plr.Character)
			end
		end
		for _, name in { "Dummies", "TwiceClones" } do
			local f = workspace:FindFirstChild(name)
			for _, m in f and f:GetChildren() or {} do
				look(m)
			end
		end
		for char, b in CRX.busy do
			if now > b.untilAt + 1 or not char.Parent then
				CRX.busy[char] = nil
			end
		end
		for char, t in CRX.shown do
			if now - t > 3 or not char.Parent then
				CRX.shown[char] = nil
			end
		end
	end
	do
		local acc = 0
		RunService.Heartbeat:Connect(function(dt)
			acc += tonumber(dt) or 0
			if acc < 0.25 then
				return
			end
			acc = 0
			local ok, err = pcall(CRX.scan)
			if not ok then
				warn("[DevCarry] " .. tostring(err))
			end
		end)
	end
end

---------------------------------------------------------------------------
-- (round 90) polish: THE SHIELD GOES DOWN, on every screen
-- (Config.SkyCoffin.Break; the server's Kit.SB; the owner: "turn off
-- animation for the shield"). A dev flying into the Sky Coffin's
-- electromagnetic field breaks it where he hits it: a white-hot flash and
-- a light, a shockwave across the field, sparks, gold lightning leaping
-- out over it, the field's hex shards flung on through after him
-- (tumbling, cooling white to gold, fading), the face cracked open round a
-- hexagon (its edge crackling) with cracks glowing out from it, and a
-- crackling boom. He flies straight on through (no flip, no roll - his own
-- camera gets a flash and a shake: SB.jolt). Then the whole shield powers
-- down, the failure running round the ring both ways from the break: each
-- panel flickers and stutters (surges, drop-outs) as an arc jumps between
-- its pillars, then its energy drains down out of it - the gold sinking to
-- the lawn behind a white-hot line, cooling to ember - and it's dark; the
-- roof over it fades out just behind; a pillar's light sputters and dies
-- once both its panels have, the peak's last; a fading electric hum under
-- it all. The arena's open. Then it boots back up: the pillars relight
-- round the ring from the generator, arcs leaping pillar to pillar, the
-- panels fill from the lawn up, the roof fades back in, a surge across the
-- whole field, the peak and a snap - every piece exactly as built.
-- Every screen times it on the server's clock from the island's own
-- BarrierDown / BarrierUp (SB.watch: a screen that comes near or joins
-- while it's down picks it up where it is); the beat (SkyBreak) brings
-- the break itself; the flyer's own screen plays it at once (predicted)
-- and calls it off if the server hasn't taken it in Confirm s. The crack
-- is drawn as the face round a hexagon (the outline and the hexagon
-- joined by triangles, two wedges each - the way the server draws the
-- roof) until its panel goes dark. Nothing written past Cull (from the
-- island's middle); the shards, arcs and crackles not past FxCull; a
-- low-end machine gets half the shards (plain ones), no lights, fewer
-- arcs, and flickers at half the rate.
-- (Its own block: the main chunk is at its local limit.)
---------------------------------------------------------------------------
do
	local SB = {
		holes = {}, -- [face] = the crack drawn in it (until its panel's dark)
		faces = {}, -- [face] = its drawn parts (found once)
		shards = {}, -- the shards in the air
		seq = nil, -- the shield going down and coming back up (nil: whole)
		TAU = math.pi * 2,
	}
	VFX.SB = SB
	-- the faces' and lights' names, made once (not a string a frame)
	SB.KEYS = { W = {}, R = {}, P = {} }
	for i = 0, 11 do
		SB.KEYS.W[i], SB.KEYS.R[i], SB.KEYS.P[i] = "W" .. i, "R" .. i, "P" .. i
	end
	-- the server's clock (the island's BarrierDown / BarrierUp are on it)
	function SB.now()
		local ok, t = pcall(function()
			return workspace:GetServerTimeNow()
		end)
		return (ok and type(t) == "number") and t or os.clock()
	end
	function SB.cfg()
		return (Config.SkyCoffin or {}).Break or {}
	end
	function SB.low()
		return VFX.EngineKit.lowEnd()
	end
	function SB.model()
		local map = workspace:FindFirstChild("Map")
		return (map and map:FindFirstChild("SkyCoffin")) or workspace:FindFirstChild("SkyCoffin")
	end
	-- a CFrame at `at` with its Z along `dir` (no lookAt: never a NaN)
	function SB.along(at, dir, upHint)
		local look = dir.Magnitude > 1e-4 and dir.Unit or Vector3.new(0, 0, -1)
		local ref = upHint or UP
		if math.abs(look:Dot(ref)) > 0.95 then
			ref = math.abs(look.X) < 0.9 and Vector3.new(1, 0, 0) or Vector3.new(0, 0, 1)
		end
		local right = look:Cross(ref).Unit
		return CFrame.fromMatrix(at, right, right:Cross(look), -look)
	end
	-- a glowing bar from a to b (the hole's edge, the cracks, the ribbons)
	function SB.bar(a, b, width, color, parent)
		local d = b - a
		local p = newPart(Vector3.new(width, width, math.max(d.Magnitude, 0.05)), SB.along((a + b) / 2, d), color, Enum.Material.Neon, nil, parent)
		p.Name = "SkyBreakFx"
		return p
	end
	-- the field's drawn parts on a face (the wall, the roof's two wedges)
	function SB.partsOf(face)
		local list = SB.faces[face]
		local whole = list ~= nil and #list > 0
		for _, p in list or {} do
			whole = whole and p.Parent ~= nil
		end
		if whole then
			return list
		end
		list = {}
		local m = SB.model()
		for _, d in m and m:GetChildren() or {} do
			if d:IsA("BasePart") and d.Name ~= "Barrier" and d:GetAttribute("BarrierFace") == face then
				table.insert(list, d)
			end
		end
		SB.faces[face] = list
		return list
	end

	---------------------------------------------------------------------------
	-- THE HOLE: the face round a hexagon
	---------------------------------------------------------------------------
	-- the order to join the outline's corners to the hexagon's: both walked
	-- round the hole's middle by angle, a triangle each step - the corners'
	-- angles never change as the hexagon shrinks, so neither does this.
	-- -> { { "o", i, "o", j, "h", k } ... } (o: the outline, h: the hexagon)
	function SB.plan(poly, cx, cy)
		local TAU = SB.TAU
		local outer = {}
		for k, p in poly do
			table.insert(outer, { k = k, a = math.atan2(p[2] - cy, p[1] - cx) % TAU })
		end
		table.sort(outer, function(x, y)
			return x.a < y.a
		end)
		local n = #outer
		local a0 = outer[1].a
		local j0 = 1
		for j = 1, 6 do
			if (j - 1) * math.pi / 3 <= a0 + 1e-9 then
				j0 = j
			end
		end
		local function oAt(s)
			local e = outer[s % n + 1]
			return e.a + (s >= n and TAU or 0), e.k
		end
		local function hAt(s)
			local idx = (j0 - 1 + s) % 6
			return idx * math.pi / 3 + (j0 - 1 + s >= 6 and TAU or 0), idx + 1
		end
		local tris = {}
		local i, j = 0, 0
		while i < n or j < 6 do
			local ao = i < n and oAt(i + 1) or math.huge
			local ah = j < 6 and hAt(j + 1) or math.huge
			if ao <= ah then
				local _, o1 = oAt(i)
				local _, o2 = oAt(i + 1)
				local _, h1 = hAt(j)
				table.insert(tris, { "o", o1, "o", o2, "h", h1 })
				i += 1
			else
				local _, h1 = hAt(j)
				local _, h2 = hAt(j + 1)
				local _, o1 = oAt(i)
				table.insert(tris, { "h", h1, "h", h2, "o", o1 })
				j += 1
			end
		end
		return tris
	end
	-- two wedges making the triangle a b c, thick through (the server's
	-- own way of drawing the roof; a sliver: hidden)
	function SB.tri(w1, w2, a, b, c, thick, transp)
		local ab, ac, bc = b - a, c - a, c - b
		local abd, acd, bcd = ab:Dot(ab), ac:Dot(ac), bc:Dot(bc)
		if abd > acd and abd > bcd then
			c, a = a, c
		elseif acd > bcd and acd > abd then
			a, b = b, a
		end
		ab, ac, bc = b - a, c - a, c - b
		local cr = ac:Cross(ab)
		if cr.Magnitude < 1e-3 or bc.Magnitude < 1e-3 then
			w1.Transparency, w2.Transparency = 1, 1
			return
		end
		local right = cr.Unit
		local up = bc:Cross(right).Unit
		local back = bc.Unit
		local height = math.max(math.abs(ab:Dot(up)), 0.01)
		w1.Size = Vector3.new(thick, height, math.max(math.abs(ab:Dot(back)), 0.01))
		w1.CFrame = CFrame.fromMatrix((a + b) / 2, right, up, back)
		w2.Size = Vector3.new(thick, height, math.max(math.abs(ac:Dot(back)), 0.01))
		w2.CFrame = CFrame.fromMatrix((a + c) / 2, -right, up, -back)
		w1.Transparency, w2.Transparency = transp, transp
	end
	-- the hexagon's corner k (1..6) at radius r, in the face's (u, v)
	function SB.corner(h, k, r)
		local th = (k - 1) * math.pi / 3
		return h.x + math.cos(th) * r, h.y + math.sin(th) * r
	end
	-- the face and its edge for the hole's radius now
	function SB.layout(h, r)
		local B, f = SB.cfg(), h.f
		local pts = { o = {}, h = {} }
		for k, p in f.poly do
			pts.o[k] = B.world(f, p[1], p[2])
		end
		for k = 1, 6 do
			pts.h[k] = B.world(f, SB.corner(h, k, r))
		end
		for i, t in h.plan do
			local w = h.wedges[i]
			SB.tri(w[1], w[2], pts[t[1]][t[2]], pts[t[3]][t[4]], pts[t[5]][t[6]], h.thick, h.transp)
		end
		-- the edge: a bar along each side of the hexagon (along it, never a lookAt)
		for k = 1, 6 do
			local a, b = pts.h[k], pts.h[k % 6 + 1]
			local bar = h.rim[k]
			if r > 0.08 then
				local e = (b - a).Unit
				bar.Size = Vector3.new(r + h.rimW * 0.6, h.rimW, h.rimW)
				bar.CFrame = CFrame.fromMatrix((a + b) / 2, e, f.n)
				bar.Transparency = 0
			else
				bar.Transparency = 1
			end
		end
		h.r = r
	end
	-- the crack in a face (face, the point he went through, its radius) ->
	-- the hole drawn there (its panel's failure flickers and fades it; it's
	-- gone when the panel's dark: SB.put)
	function SB.hole(face, at, r)
		local B = SB.cfg()
		local f = B.frame and B.frame(face)
		local parts = f and SB.partsOf(face) or {}
		if not f or #parts == 0 then
			return nil
		end
		local x, y = B.local2(f, at)
		local old = SB.holes[face]
		if old then
			SB.drop(old)
		end
		x, y, r = B.fit(f, x, y, r)
		local h = { face = face, f = f, x = x, y = y, r = r, r0 = r, born = os.clock(), was = {}, wedges = {}, rim = {}, recs = {} }
		local ref = parts[1]
		h.color, h.transp, h.material = ref.Color, ref.Transparency, ref.Material
		h.rimW = f.thick > 0.4 and 0.55 or 0.45
		-- (thinner than the face: where two of its translucent triangles meet,
		-- their edges barely show)
		h.thick = math.min(f.thick, 0.2)
		-- this screen draws the face from now on: the field's own hidden here
		for _, p in parts do
			h.was[p] = p.Transparency
			p.Transparency = 1
		end
		h.parts = parts
		h.model = Instance.new("Model")
		h.model.Name = "SkyHole"
		h.model.Parent = folder
		h.plan = SB.plan(f.poly, x, y)
		for i = 1, #h.plan do
			local pair = {}
			for k = 1, 2 do
				local w = Instance.new("WedgePart")
				w.Name = "SkyHoleFace"
				w.Anchored = true
				w.CanCollide = false
				w.CanQuery = false
				w.CanTouch = false
				w.CastShadow = false
				w.Color = h.color
				w.Material = h.material
				w.Transparency = h.transp
				w.Parent = h.model
				pair[k] = w
			end
			h.wedges[i] = pair
		end
		for k = 1, 6 do
			h.rim[k] = newPart(Vector3.one * 0.5, CFrame.new(at), B.Rim or GOLD, Enum.Material.Neon, nil, h.model)
			h.rim[k].Name = "SkyHoleEdge"
		end
		SB.layout(h, r)
		-- (what the failure flickers and fades: the face's triangles - not the
		-- slivers SB.tri hid - as the panel's own pieces would be)
		for _, pair in h.wedges do
			for _, w in pair do
				if w.Transparency < 1 then
					table.insert(h.recs, { part = w, size = w.Size, cf = w.CFrame, transp = h.transp, color = h.color, material = h.material })
				end
			end
		end
		SB.holes[face] = h
		return h
	end
	-- the hole gone: its pieces, and the field's face back as it was
	function SB.drop(h)
		if SB.holes[h.face] == h then
			SB.holes[h.face] = nil
		end
		for p, t in h.was do
			if p.Parent then
				p.Transparency = t
			end
		end
		h.was = {}
		if h.model then
			pcall(h.model.Destroy, h.model)
			h.model = nil
		end
	end
	-- cracks glowing out from the hexagon's corners over the face (kept on
	-- it), white-hot cooling to gold and gone
	function SB.cracks(h)
		local B, f = SB.cfg(), h.f
		for k = 1, B.Cracks or 6 do
			local cx, cy = SB.corner(h, (k - 1) % 6 + 1, h.r)
			local th = (k - 1) * math.pi / 3 + rand(-0.3, 0.3)
			local prev = B.world(f, cx, cy)
			local px, py = cx, cy
			for seg = 1, 2 do
				local len = h.r * (seg == 1 and rand(0.45, 0.85) or rand(0.3, 0.6))
				local nx, ny = px + math.cos(th) * len, py + math.sin(th) * len
				for _ = 1, 4 do
					if B.inside(f, nx, ny, 0.6) then
						break
					end
					len *= 0.5
					nx, ny = px + math.cos(th) * len, py + math.sin(th) * len
				end
				if not B.inside(f, nx, ny, 0.6) or len < 0.6 then
					break
				end
				local nxt = B.world(f, nx, ny)
				local c = SB.bar(prev, nxt, seg == 1 and 0.32 or 0.2, B.Hot or Color3.new(1, 1, 1), h.model)
				tween(c, 0.35, { Color = B.Color or GOLD })
				tween(c, 1.2, { Transparency = 1 }, Enum.EasingStyle.Quad, Enum.EasingDirection.In, 0.4)
				prev, px, py = nxt, nx, ny
				th += rand(-0.5, 0.5)
			end
		end
	end

	---------------------------------------------------------------------------
	-- THE SHATTER
	---------------------------------------------------------------------------
	-- the field's hex shards: flung on through the way he went (some blown
	-- back), tumbling, cooling white-hot to gold, fading
	function SB.shatter(at, n, u, dir, r, speed, count)
		local B = SB.cfg()
		local low = SB.low()
		local v = n:Cross(u)
		local k = math.clamp((tonumber(speed) or 200) / 400, 0.4, 1.3)
		local sp, life, size = B.ShardSpeed or { 26, 110 }, B.ShardLife or { 0.9, 1.7 }, B.ShardSize or { 1.2, 3.4 }
		local thick = 0.22
		for _ = 1, count do
			local a, d = rand(0, SB.TAU), r * 0.9 * math.sqrt(rand(0, 1))
			local radial = u * math.cos(a) + v * math.sin(a)
			local pos = at + radial * d
			local s = rand(size[1], size[2])
			local spd = rand(sp[1], sp[2]) * k
			local vel
			if rand(0, 1) < 0.25 then
				vel = -dir * spd * 0.35 + radial * spd * rand(0.2, 0.5) -- (blown back)
			else
				vel = dir * spd * rand(0.55, 1) + radial * spd * rand(0.15, 0.55) + n * rand(-4, 4)
			end
			local rec = {
				pos = pos, vel = vel, t0 = os.clock(), life = rand(life[1], life[2]),
				axis = rng:NextUnitVector(), spin = math.rad(rand(300, 900)), rot = CFrame.fromMatrix(Vector3.zero, u, n), parts = {}, offs = {},
			}
			-- a hexagon out of three bars turned 60 degrees apart (one on a low-end machine)
			for j = 0, low and 0 or 2 do
				local p = newPart(Vector3.new(s, thick, s * 1.732), CFrame.new(pos), B.Hot or Color3.new(1, 1, 1), Enum.Material.Neon)
				p.Name = "SkyShard"
				table.insert(rec.parts, p)
				table.insert(rec.offs, CFrame.Angles(0, j * math.pi / 3, 0))
			end
			table.insert(SB.shards, rec)
		end
	end
	-- the break: flash, light, shockwave, sparks, lightning, shards, a crackling boom
	function SB.burst(at, n, u, dir, r, speed)
		local B = SB.cfg()
		VFX.PlaySound("SkyBreak", at, 1)
		if not nearCamera(at, B.FxCull or 700) then
			return
		end
		local low = SB.low()
		local gold, hot = B.Color or GOLD, B.Hot or Color3.new(1, 1, 1)
		local k = 1
		-- (a quick flash: big enough to read as the field bursting, gone before
		-- it can white out his view of the hole)
		local flash = newPart(Vector3.one * r * 0.5 * k, CFrame.new(at), hot, Enum.Material.Neon, Enum.PartType.Ball)
		flash.Name = "SkyBreakFx"
		flash.Transparency = 0.1
		tween(flash, 0.18, { Size = Vector3.one * r * 1.5 * k, Transparency = 1 })
		if not low then
			local l = Instance.new("PointLight")
			l.Color = gold
			l.Range = math.min(60, r * 4 * k)
			l.Brightness = 6 * k
			l.Shadows = false
			l.Parent = flash
			tween(l, 0.25, { Brightness = 0 })
		end
		cleanup(flash, 0.3)
		shockDisc(at, n, r * 0.8 * k, r * 5 * k, 0.45, gold)
		sparks(at, 1.6 * k, hot, gold, math.floor((low and 20 or 44) * k))
		local DK = VFX.DK
		local v = n:Cross(u)
		if DK then
			for j = 1, low and 2 or 5 do
				local a = (j + rand(-0.3, 0.3)) / (low and 2 or 5) * SB.TAU
				local out = u * math.cos(a) + v * math.sin(a)
				DK.zig(at + out * r * 0.5, at + out * r * rand(1.3, 2.4), gold, 0.3, 0.32, 0.9)
			end
		end
		SB.shatter(at, n, u, dir, r, speed, math.floor(VFX.EngineKit.count(B.Shards or 22) * k + 0.5))
	end

	---------------------------------------------------------------------------
	-- THE SHIELD: its pieces (as built - put back exactly), going down and
	-- coming back up on the server's clock
	---------------------------------------------------------------------------
	function SB.rec(p)
		return { part = p, size = p.Size, cf = p.CFrame, transp = p.Transparency, color = p.Color, material = p.Material }
	end
	function SB.restoreRec(r)
		local p = r.part
		if p.Parent then
			p.Size, p.CFrame, p.Transparency, p.Color, p.Material = r.size, r.cf, r.transp, r.color, r.material
		end
	end
	-- the field's pieces, read as it's about to go down (it's whole then):
	-- walls[i] (the drawn wall), roofs[i] (its two wedges), lamps[i] (pillar
	-- i's light) and the peak's (SC.build tags them all)
	function SB.field()
		local m = SB.model()
		if not m then
			return nil
		end
		local fd = { model = m, walls = {}, roofs = {}, lamps = {}, apex = nil }
		for _, d in m:GetChildren() do
			if d:IsA("BasePart") then
				local face = d:GetAttribute("BarrierFace")
				local i = type(face) == "string" and tonumber(face:sub(2)) or nil
				if d.Name == "BarrierWall" and i then
					fd.walls[i] = SB.rec(d)
				elseif d.Name == "BarrierRoof" and i then
					fd.roofs[i] = fd.roofs[i] or {}
					table.insert(fd.roofs[i], SB.rec(d))
				elseif d.Name == "PillarLight" and type(d:GetAttribute("BarrierPillar")) == "number" then
					fd.lamps[d:GetAttribute("BarrierPillar")] = SB.rec(d)
				elseif d.Name == "BarrierApex" then
					fd.apex = SB.rec(d)
				end
			end
		end
		return fd
	end
	-- the shield going down (t0: when it broke, on the server's clock; hit:
	-- the wall it broke at; upAt: when it's whole again, once the island's
	-- said; predicted: his own screen's guess, before the server's taken it)
	-- -> the run of it (told again of the same break: the same one)
	function SB.start(t0, hit, upAt, predicted)
		local B = SB.cfg()
		local s = SB.seq
		if s then
			if math.abs(s.t0 - t0) < 1 then
				if upAt then
					s.upAt = upAt
					s.bootAt = upAt - (B.Boot or 3.4)
				end
				return s
			end
			SB.finish() -- (a new one: the last one's pieces back first)
		end
		local fd = SB.field()
		if not fd then
			return nil
		end
		local now = SB.now()
		s = { t0 = t0, hit = math.floor(tonumber(hit) or 0) % 12, fd = fd, st = {}, lines = {}, predicted = predicted == true }
		s.bootAt = upAt and upAt - (B.Boot or 3.4) or t0 + (B.Down or 15)
		s.upAt = upAt or s.bootAt + (B.Boot or 3.4)
		-- (not yet heard from the island: his own guess, or a beat it hasn't
		-- caught up with - called off if it never does)
		s.confirmBy = now + (B.Confirm or 1.5) * (predicted and 1 or 2)
		SB.seq = s
		return s
	end
	-- called off, or the island's whole again early: up it comes now, quickly
	function SB.cutShort(s, now)
		local B = SB.cfg()
		s.bootAt = math.min(s.bootAt, now)
		s.upAt = math.min(s.upAt, s.bootAt + math.min(B.Boot or 3.4, 1.2))
		s.confirmBy, s.seen = nil, false
	end
	-- all of it back exactly as built (its time up, called off, or a new one)
	function SB.finish()
		local s = SB.seq
		SB.seq = nil
		if not s then
			return
		end
		for _, h in SB.holes do
			SB.drop(h)
		end
		for _, ln in s.lines do
			pcall(ln.Destroy, ln)
		end
		local fd = s.fd
		for _, r in fd.walls do
			SB.restoreRec(r)
		end
		for _, r in fd.lamps do
			SB.restoreRec(r)
		end
		for _, list in fd.roofs do
			for _, r in list do
				SB.restoreRec(r)
			end
		end
		if fd.apex then
			SB.restoreRec(fd.apex)
		end
	end

	-- a face settled: "lit" (as built) or "dark" (its energy gone), written
	-- once. (While its crack's drawn the crack is the face: left alone till
	-- it's dark - then the crack goes.) -> what it was, if it changed
	function SB.put(s, key, recs, state)
		if s.st[key] == state then
			return nil
		end
		local h = SB.holes[key]
		if h and state ~= "dark" then
			return nil
		end
		local was = s.st[key]
		s.st[key] = state
		if h then
			SB.drop(h)
		end
		SB.line(s, key, nil)
		for _, r in recs do
			SB.restoreRec(r)
			if state == "dark" and r.part.Parent then
				r.part.Transparency = 1
			end
		end
		return was
	end
	-- the white-hot line along the top of a panel's energy (draining down,
	-- filling back up); nil: gone
	function SB.line(s, key, cf, width)
		local ln = s.lines[key]
		if not cf then
			if ln then
				s.lines[key] = nil
				pcall(ln.Destroy, ln)
			end
			return
		end
		if not ln then
			ln = newPart(Vector3.new(width or 1, 0.9, 0.9), cf, SB.cfg().Hot or Color3.new(1, 1, 1), Enum.Material.Neon)
			ln.Name = "SkyDrainLine"
			s.lines[key] = ln
		end
		ln.CFrame = cf
	end
	-- a face failing: surges, drop-outs, the gold jumping (each tick)
	function SB.flicker(s, key, recs, tick)
		if not tick then
			return
		end
		local B = SB.cfg()
		local h = SB.holes[key]
		local roll = rng:NextNumber()
		for _, r in h and h.recs or recs do
			local p = r.part
			if p.Parent then
				if roll < 0.3 then
					p.Transparency = 1 -- (a drop-out)
				elseif roll < 0.55 then
					-- (a surge: a gold-white glow - not a white-out of a panel
					-- the size of a building)
					p.Transparency = math.max(r.transp - 0.14, 0.55)
					p.Color = B.Rim or r.color
					p.Material = Enum.Material.Neon
				else
					p.Transparency = math.clamp(r.transp + rand(-0.08, 0.12), 0, 1)
					p.Color = r.color:Lerp(B.Hot or r.color, rand(0, 0.4))
					p.Material = r.material
				end
			end
		end
	end
	-- ...then its energy draining away (u: 0..1): a wall's sinks to the lawn
	-- behind a white-hot line, the gold cooling to ember; a roof's (or a
	-- cracked face's) fades where it is
	function SB.drain(s, key, recs, u, wall)
		local B = SB.cfg()
		local h = SB.holes[key]
		local e = u * u * (3 - 2 * u)
		local r1 = recs[1]
		local ember = B.Ember or (r1 and r1.color) or GOLD
		if wall and r1 then
			local hgt = math.max(r1.size.Y * (1 - e), 0.05)
			SB.line(s, key, r1.cf * CFrame.new(0, -r1.size.Y / 2 + hgt, 0), r1.size.X)
			if not h and r1.part.Parent then
				local p = r1.part
				p.Size = Vector3.new(r1.size.X, hgt, r1.size.Z)
				p.CFrame = r1.cf * CFrame.new(0, -(r1.size.Y - hgt) / 2, 0)
				p.Color = r1.color:Lerp(ember, e)
				p.Material = r1.material
				p.Transparency = r1.transp - 0.12 * math.sin(u * math.pi) -- (a touch brighter as it gathers)
				return
			end
		end
		for _, r in h and h.recs or recs do
			local p = r.part
			if p.Parent then
				p.Transparency = r.transp + (1 - r.transp) * e
				p.Color = r.color:Lerp(ember, e)
				p.Material = r.material
			end
		end
	end
	-- one face going down, t s into its failure (wall: it's a wall - i, its
	-- place round the ring)
	function SB.panel(s, key, recs, t, flick, drain, tick, wall, i)
		if t < 0 then
			SB.put(s, key, recs, "lit")
		elseif t < flick then
			if s.st[key] ~= "flicker" then
				s.st[key] = "flicker"
				if wall then
					SB.panelFx(i)
				end
			end
			SB.flicker(s, key, recs, tick)
		elseif t < flick + drain then
			s.st[key] = "drain"
			SB.drain(s, key, recs, (t - flick) / drain, wall)
		elseif SB.put(s, key, recs, "dark") == "drain" and wall then
			SB.footFx(recs[1])
		end
	end
	-- a pillar's light (or the peak's): "on", "sputter" or "dead"
	function SB.lamp(s, key, r, mode, tick)
		if not (r and r.part.Parent) then
			return
		end
		local B = SB.cfg()
		local p = r.part
		if mode == "sputter" then
			s.st[key] = "sputter"
			if tick then
				local on = rng:NextNumber() < 0.45
				p.Color = on and (B.Hot or r.color) or (B.Dead or r.color)
				p.Material = on and r.material or Enum.Material.SmoothPlastic
			end
			return
		end
		if s.st[key] == mode then
			return
		end
		local was = s.st[key]
		s.st[key] = mode
		if mode == "on" then
			SB.restoreRec(r)
		else
			p.Color = B.Dead or r.color
			p.Material = Enum.Material.SmoothPlastic
		end
		-- (going out, or catching: a spit of sparks and a crackle, near enough)
		local at = r.cf.Position
		if was == "sputter" and not SB.low() and nearCamera(at, B.FxCull or 700) then
			sparks(at, 0.9, B.Hot or Color3.new(1, 1, 1), B.Color or GOLD, mode == "on" and 10 or 16)
			VFX.PlaySound("SkyCrackle", at, 0.8)
		end
	end
	-- an arc of the field's lightning from a to b (a white core in gold;
	-- cheap: 8 segments, gone in `life`)
	function SB.arc(a, b, thick, life)
		local B = SB.cfg()
		local d = b - a
		if d.Magnitude < 1 then
			return
		end
		local look = d.Unit
		local s1 = look:Cross(math.abs(look.Y) > 0.9 and Vector3.new(1, 0, 0) or UP).Unit
		local s2 = look:Cross(s1).Unit
		local pts = { a, b }
		local amp = math.min(d.Magnitude * 0.12, 16)
		for _ = 1, 3 do
			local out = { pts[1] }
			for k = 1, #pts - 1 do
				local p, q = pts[k], pts[k + 1]
				table.insert(out, (p + q) / 2 + s1 * rand(-amp, amp) + s2 * rand(-amp, amp))
				table.insert(out, q)
			end
			pts, amp = out, amp * 0.55
		end
		for k = 1, #pts - 1 do
			for _, L in { { thick * 0.45, Color3.new(1, 1, 1), 0 }, { thick * 1.6, B.Color or GOLD, 0.35 } } do
				local seg = SB.bar(pts[k], pts[k + 1], L[1], L[2])
				seg.Name = "SkyArc"
				seg.Transparency = L[3]
				tween(seg, life, { Transparency = 1 }, Enum.EasingStyle.Quad, Enum.EasingDirection.In)
				cleanup(seg, life + 0.05)
			end
		end
	end
	-- a panel starting to fail: a crackle where it's nearest you, and an arc
	-- jumping between its pillars (every other one on a low-end machine)
	function SB.panelFx(i)
		local B = SB.cfg()
		local C, _, BH = B.dims()
		local a, b = B.pillar(i), B.pillar((i + 1) % 12)
		local cam = workspace.CurrentCamera
		local focus = cam and cam.Focus.Position or C
		local along = b - a
		local k = math.clamp((focus - a):Dot(along) / math.max(along:Dot(along), 1), 0, 1)
		local near = a + along * k
		near = Vector3.new(near.X, math.clamp(focus.Y, C.Y, C.Y + BH), near.Z)
		if (near - focus).Magnitude > (B.FxCull or 700) then
			return
		end
		VFX.PlaySound("SkyCrackle", near, 1)
		if SB.low() and i % 2 == 1 then
			return
		end
		local d = along.Unit
		SB.arc(a + Vector3.new(0, rand(0.15, 0.9) * BH, 0) + d * 9, b + Vector3.new(0, rand(0.15, 0.9) * BH, 0) - d * 9, 0.9, 0.35)
	end
	-- a wall's energy gone into the lawn: a spit of sparks at its foot
	function SB.footFx(r)
		local B = SB.cfg()
		if not r or SB.low() then
			return
		end
		local foot = (r.cf * CFrame.new(0, -r.size.Y / 2 + 1, 0)).Position
		if nearCamera(foot, B.FxCull or 700) then
			sparks(foot, 1.4, B.Hot or Color3.new(1, 1, 1), B.Ember or GOLD, 18)
		end
	end
	-- an arc leaping to pillar j's light from its neighbour nearer the
	-- generator (g), as it relights
	function SB.leap(j, g)
		local B = SB.cfg()
		local _, _, BH = B.dims()
		local prev = B.apart((j - 1) % 12, g) < B.apart(j, g) and (j - 1) % 12 or (j + 1) % 12
		local a = B.pillar(prev) + Vector3.new(0, BH - 12, 0)
		local b = B.pillar(j) + Vector3.new(0, BH - 12, 0)
		if not nearCamera((a + b) / 2, (B.FxCull or 700) + 120) or (SB.low() and j % 2 == 1) then
			return
		end
		local d = (b - a).Unit
		SB.arc(a + d * 9, b - d * 9, 1.1, 0.4)
	end

	-- GOING DOWN (e: s since it broke): the failure running round the ring
	-- both ways from the wall it broke at, the roofs just behind, each
	-- pillar's light dying once both its panels have, the peak's last
	function SB.failing(s, e, tick)
		local B = SB.cfg()
		local F = B.Fail or {}
		local start, step, flick, drain, lag = F.Start or 0.3, F.Step or 0.17, F.Flicker or 0.6, F.Drain or 0.75, F.Roof or 0.12
		local last = start + 6 * step + flick + drain + lag + 0.15
		-- (all of it dark and settled: nothing to do till it boots)
		if s.settled and e > last + 0.5 then
			return
		end
		local fd, K = s.fd, SB.KEYS
		s.one = s.one or {} -- (a wall's one piece as a list: [i], made once)
		for i = 0, 11 do
			local t = e - (start + B.apart(i, s.hit) * step)
			local wr = fd.walls[i]
			if wr then
				local one = s.one[i] or { wr }
				s.one[i] = one
				SB.panel(s, K.W[i], one, t, flick, drain, tick, true, i)
			end
			if fd.roofs[i] then
				SB.panel(s, K.R[i], fd.roofs[i], t - lag, flick, drain, tick, false, i)
			end
		end
		for j = 0, 11 do
			-- (pillar j stands between walls j - 1 and j)
			local k = math.max(B.apart(j, s.hit), B.apart((j - 1) % 12, s.hit))
			local t = e - (start + k * step + flick + drain)
			SB.lamp(s, K.P[j], fd.lamps[j], t < -0.25 and "on" or (t < 0 and "sputter" or "dead"), tick)
		end
		SB.lamp(s, "Apex", fd.apex, e < last - 0.3 and "on" or (e < last and "sputter" or "dead"), tick)
		s.settled = e > last + 0.5
	end
	-- COMING BACK UP (b: 0..1 of Boot): the pillars relight round the ring
	-- from the generator, an arc leaping to each from the last; each panel
	-- fills from the lawn up once both its pillars are lit; the roof fades
	-- back in; then a surge over the whole field (white-hot, settling to
	-- gold), the peak and a snap
	function SB.booting(s, b, tick)
		local B = SB.cfg()
		local fd = s.fd
		local g = B.genPillar()
		local SURGE = 0.86
		if not s.upPlayed then
			s.upPlayed = true
			if b < 0.2 then
				VFX.PlaySound("SkyPowerUp", s.mid, 1)
			end
		end
		local K = SB.KEYS
		for j = 0, 11 do
			local d = B.apart(j, g)
			local at = 0.04 + 0.04 * d
			local key = K.P[j]
			if b < at then
				SB.lamp(s, key, fd.lamps[j], "dead", tick)
			elseif b < at + 0.08 then
				if s.st[key] ~= "sputter" and d > 0 then
					SB.leap(j, g)
				end
				SB.lamp(s, key, fd.lamps[j], "sputter", tick)
			else
				SB.lamp(s, key, fd.lamps[j], "on", tick)
			end
		end
		s.one = s.one or {} -- (a wall's one piece as a list: [i], made once)
		for i = 0, 11 do
			local d = math.max(B.apart(i, g), B.apart((i + 1) % 12, g))
			local wall, roof = nil, fd.roofs[i]
			if fd.walls[i] then
				wall = s.one[i] or { fd.walls[i] }
				s.one[i] = wall
			end
			local k = (b - SURGE) / (1 - SURGE)
			if wall then
				if k < 0 then
					SB.fill(s, K.W[i], wall, (b - (0.14 + 0.04 * d)) / 0.3, true)
				else
					SB.surge(s, K.W[i], wall, k)
				end
			end
			if roof then
				if k < 0 then
					SB.fill(s, K.R[i], roof, (b - 0.6 - 0.01 * d) / 0.22, false)
				else
					SB.surge(s, K.R[i], roof, k)
				end
			end
		end
		if b >= SURGE and not s.onlinePlayed then
			s.onlinePlayed = true
			if b < SURGE + 0.1 then
				VFX.PlaySound("SkyOnline", s.mid, 1)
			end
		end
		SB.lamp(s, "Apex", fd.apex, b < SURGE and "dead" or (b < SURGE + 0.05 and "sputter" or "on"), tick)
	end
	-- a face filling back up (u: 0..1): a wall from the lawn up behind a
	-- white-hot line, ember warming to gold; a roof fading back in
	function SB.fill(s, key, recs, u, wall)
		if u <= 0 then
			SB.put(s, key, recs, "dark")
			return
		elseif u >= 1 then
			SB.put(s, key, recs, "lit")
			return
		end
		local B = SB.cfg()
		s.st[key] = "fill"
		local e = 1 - (1 - u) * (1 - u)
		for n, r in recs do
			local p = r.part
			local ember = B.Ember or r.color
			if p.Parent then
				p.Color = ember:Lerp(r.color, e)
				p.Material = r.material
				if wall and n == 1 then
					local hgt = math.max(r.size.Y * e, 0.05)
					p.Size = Vector3.new(r.size.X, hgt, r.size.Z)
					p.CFrame = r.cf * CFrame.new(0, -(r.size.Y - hgt) / 2, 0)
					p.Transparency = r.transp - 0.1
					SB.line(s, key, r.cf * CFrame.new(0, -r.size.Y / 2 + hgt, 0), r.size.X)
				else
					p.Transparency = 1 - (1 - r.transp) * e
				end
			end
		end
	end
	-- ...and the surge as it comes whole (k: 0..1): a gold-white glow over
	-- the whole field settling to its gold (not a white-out: everyone inside
	-- is looking at it)
	function SB.surge(s, key, recs, k)
		local B = SB.cfg()
		s.st[key] = "surge"
		SB.line(s, key, nil)
		for _, r in recs do
			local p = r.part
			if p.Parent then
				p.Size, p.CFrame = r.size, r.cf
				p.Color = (B.Rim or r.color):Lerp(r.color, k)
				p.Transparency = 0.64 + (r.transp - 0.64) * k
				p.Material = k < 0.4 and Enum.Material.Neon or r.material
			end
		end
	end
	-- each frame, on the server's clock: called off if the island never took
	-- it; done (all of it as built) at its time; nothing written out of sight
	function SB.stepField(now)
		local s = SB.seq
		if not s then
			return
		end
		local B = SB.cfg()
		if s.confirmBy and now > s.confirmBy then
			SB.cutShort(s, now)
		end
		if now >= s.upAt then
			SB.finish()
			return
		end
		local C, _, BH = B.dims()
		s.mid = C + Vector3.new(0, BH / 2, 0)
		if not nearCamera(s.mid, B.Cull or 1500) then
			return
		end
		local tick = now >= (s.tickAt or 0)
		if tick then
			s.tickAt = now + (SB.low() and 1 / 15 or 1 / 30)
		end
		if now < s.bootAt then
			-- (the hum, if this screen sees it go - not when it comes on it later)
			if not s.hummed and now - s.t0 < 1.5 then
				s.hummed = true
				VFX.PlaySound("SkyPowerDown", s.mid, 1)
			end
			SB.failing(s, now - s.t0, tick)
		else
			SB.booting(s, math.clamp((now - s.bootAt) / math.max(s.upAt - s.bootAt, 0.05), 0, 1), tick)
		end
	end
	-- the island's own clock (the server's): picks up a breakdown this
	-- screen wasn't told of (it came near, or joined, while it was down),
	-- confirms the one it was, and brings it up early if the island's whole
	function SB.watch(now)
		local m = SB.model()
		local s = SB.seq
		if not m then
			if s then
				SB.finish()
			end
			return
		end
		local down, up = m:GetAttribute("BarrierDown"), m:GetAttribute("BarrierUp")
		if type(down) == "number" and type(up) == "number" and now < up then
			local at = m:GetAttribute("BarrierAt")
			s = SB.start(down, type(at) == "number" and at or (s and s.hit) or 0, up, false)
			if s then
				s.seen, s.confirmBy = true, nil
			end
		elseif s and s.seen and now < s.bootAt then
			SB.cutShort(s, now)
		end
	end
	-- is it open (going down, down, or booting back up - this screen's own
	-- guess or the island's word)? There's nothing there to break
	function SB.isOpen()
		local now = SB.now()
		local s = SB.seq
		if s and now < s.upAt then
			return true
		end
		local m = SB.model()
		local up = m and m:GetAttribute("BarrierUp")
		return type(up) == "number" and now < up
	end
	-- the server has it down: its colliders are the server's to put back
	function SB.serverDown()
		local m = SB.model()
		return m ~= nil and type(m:GetAttribute("BarrierDown")) == "number"
	end
	-- his own camera as he breaks it: a flash and a shake - no turn
	function SB.jolt()
		local B = SB.cfg()
		VFX.Hooks.Flash(B.Hot or Color3.new(1, 1, 1), B.Flash or 0.1)
		VFX.Shake(B.Shake or 0.55, 0.35)
	end

	---------------------------------------------------------------------------
	-- every frame: the shards, the cracks' edges, the shield
	---------------------------------------------------------------------------
	function SB.step(dt)
		local now = os.clock()
		dt = math.clamp(tonumber(dt) or 1 / 60, 0, 0.1)
		local B = SB.cfg()
		-- the shards
		local i = 1
		while i <= #SB.shards do
			local s = SB.shards[i]
			local age = now - s.t0
			if age >= s.life or not s.parts[1].Parent then
				for _, p in s.parts do
					pcall(p.Destroy, p)
				end
				table.remove(SB.shards, i)
			else
				s.vel = s.vel * math.exp(-1.4 * dt) + Vector3.new(0, -35, 0) * dt
				s.pos += s.vel * dt
				s.rot = CFrame.fromAxisAngle(s.axis, s.spin * dt) * s.rot
				local cf = CFrame.new(s.pos) * s.rot
				local u = age / s.life
				local col = u < 0.25 and (B.Hot or Color3.new(1, 1, 1)):Lerp(B.Color or GOLD, u / 0.25) or nil
				local tr = u > 0.6 and (u - 0.6) / 0.4 or 0
				for j, p in s.parts do
					p.CFrame = cf * s.offs[j]
					p.Transparency = tr
					if col then
						p.Color = col
					elseif not s.cooled then
						p.Color = B.Color or GOLD
					end
				end
				s.cooled = col == nil
				i += 1
			end
		end
		-- the cracks (till their panels go dark): the edge flickering, now
		-- and then an arc off it; one with no shield going down is a stray -
		-- gone
		local low = SB.low()
		for _, h in SB.holes do
			if not h.model or not h.model.Parent or not SB.seq then
				SB.drop(h)
			else
				if now >= (h.flickAt or 0) then
					h.flickAt = now + (low and 1 / 15 or 1 / 30)
					for _, bar in h.rim do
						bar.Color = (B.Rim or GOLD):Lerp(B.Hot or Color3.new(1, 1, 1), rand(0, 0.7))
					end
				end
				if not low and now >= (h.arcAt or 0) then
					h.arcAt = now + rand(0.25, 0.7)
					local at = B.world(h.f, h.x, h.y)
					if VFX.DK and nearCamera(at, B.FxCull or 700) then
						local a = rand(0, SB.TAU)
						local p = B.world(h.f, h.x + math.cos(a) * h.r, h.y + math.sin(a) * h.r)
						local out = B.world(h.f, h.x + math.cos(a) * h.r * rand(1.3, 1.8), h.y + math.sin(a) * h.r * rand(1.3, 1.8))
						VFX.DK.zig(p, out, B.Color or GOLD, 0.16, 0.18, 0.8)
						if rand(0, 1) < 0.35 then
							VFX.PlaySound("SkyCrackle", p, 0.7)
						end
					end
				end
			end
		end
		-- the shield, on the server's clock (the island's word on it 4 times a second)
		local snow = SB.now()
		if snow >= (SB.watchAt or 0) then
			SB.watchAt = snow + 0.25
			SB.watch(snow)
		end
		SB.stepField(snow)
	end
	RunService.RenderStepped:Connect(function(dt)
		local ok, err = pcall(SB.step, dt)
		if not ok then
			warn("[SkyBreak] " .. tostring(err))
		end
	end)

	-- THE BEAT: { Face (W0..W11, R0..R11, or Lid - no face drawn there),
	-- Pos, R, Dir, Speed, Lid, T (when it broke, on the server's clock),
	-- Predicted } - his own screen's at once, everyone else's from the
	-- server (Kit.SB). The break where he hit it, and the shield going down
	-- round the ring from there
	function Effects.SkyBreak(_, data)
		local B = SB.cfg()
		local at = typeof(data.Pos) == "Vector3" and data.Pos or nil
		if not at or at ~= at or not B.frame then
			return
		end
		local dir = (typeof(data.Dir) == "Vector3" and data.Dir == data.Dir and data.Dir.Magnitude > 0.01) and data.Dir.Unit or Vector3.new(0, 0, -1)
		local speed = tonumber(data.Speed) or 200
		local r = math.clamp(tonumber(data.R) or B.radius(speed), 2, 30)
		local now = SB.now()
		local t0 = tonumber(data.T)
		if not t0 or t0 ~= t0 or t0 > now + 2 or t0 < now - 30 then
			t0 = now
		end
		SB.start(t0, B.wallAt(at), nil, data.Predicted == true)
		if not nearCamera(at, B.Cull or 1500) then
			return
		end
		-- the crack in the face he went through (not once its panel's past
		-- flickering: it'd be drawn over a dead face)
		local F = B.Fail or {}
		local f = type(data.Face) == "string" and B.frame(data.Face) or nil
		local n, u = UP, Vector3.new(1, 0, 0)
		if f then
			n, u = f.n, f.u
			local h = now - t0 < (F.Start or 0.3) + (F.Flicker or 0.6) and SB.hole(data.Face, at, r) or nil
			if h then
				at = B.world(h.f, h.x, h.y)
				r = h.r0
				SB.cracks(h)
			end
		end
		SB.burst(at, n, u, dir, r, speed)
	end
end

---------------------------------------------------------------------------
-- (round 90) DEVFLY2 - LIGHTSPEED on every screen (Config.DevFlight.Light;
-- Effects.DevFly Kind = Charge, Light, LightOut, Roll - VFX.DFX hands them
-- here, its watcher and his own screen call in each frame).
--   THE CHARGE: the plasma sheath forming round him, crackling (his own
--     ears: the orchestral swell and the riser; everyone else's: on him).
--   THE BREAK - the light barrier: a blinding flash, the shockwave split into
--     its colours (red, green and blue rings a beat apart - the light
--     dispersed, like a prism), a glassy disc of air across his line and
--     the barrier's shards flung out over it, a vapor cone twice the boom's,
--     white streaks thrown back - and a second, deeper boom with the glass
--     shattering in it (everyone else: the flash at once, the sound late by
--     the distance, as the boom is).
--   AT LIGHTSPEED: everyone else sees a streak of light with colour fringes
--     (red one side, cyan the other: the split), the sheath round him and
--     prismatic rings shed down his line; his own screen: the stars streaking
--     past down a tunnel, the colour graded and bloomed (the HUD splits the
--     edges and closes them in).
--   THE ROLL: a ghost of him where it started, the air whipped round.
-- Everything goes when he stops (DFX.untrack / DFX.stopMine call in here).
-- Half as much on a low-end machine. (One local: the main chunk's limit.)
---------------------------------------------------------------------------
do
	local LSX = {
		DEV = Config.DevFlight or {},
		mine = { stars = {}, k = 0 },
		voices = {}, -- [char] = the charge's sound on him (everyone else's ears; plain - let go on untrack)
		PRISM = { Color3.fromRGB(255, 70, 120), Color3.fromRGB(120, 255, 170), Color3.fromRGB(90, 170, 255) },
		CORE = Color3.fromRGB(236, 246, 255),
		SHEATH = Color3.fromRGB(150, 205, 255),
		SHEATH_OUT = Color3.fromRGB(116, 140, 255),
		FRINGE_R = Color3.fromRGB(255, 80, 150),
		FRINGE_C = Color3.fromRGB(80, 220, 255),
		STAR = { Color3.fromRGB(255, 255, 255), Color3.fromRGB(196, 226, 255), Color3.fromRGB(220, 196, 255), Color3.fromRGB(255, 214, 236) },
		BEATS = {},
	}
	VFX.LSX = LSX
	-- LIGHTSPEED's pose: streamlined, both arms swept back along his sides, head
	-- down his line (the R6 fallback; the flight's frame: the body lies along it)
	POSES.FlyLight = { RightArm = { -12, 0, 5 }, LeftArm = { -12, 0, 5 }, RightLeg = 0, LeftLeg = 0, Waist = { 2, 0, 0 }, Neck = { 68, 0, 0 } }

	function LSX.look()
		return (LSX.DEV.Light or {}).Look or {}
	end
	function LSX.n(x)
		return VFX.EngineKit.count(x)
	end

	-- THE PLASMA SHEATH: two glowing shells round him stretched down his line,
	-- a little ahead of him (k: 0..1, how formed - it grows with the charge;
	-- his own screen: fainter, the camera's behind it)
	function LSX.sheath(st, k)
		local S = LSX.look().Sheath or {}
		if k <= 0.01 or not st.root.Parent then
			LSX.unsheath(st)
			return
		end
		if not st.shells then
			st.shells = {}
			for i, spec in { { LSX.SHEATH, 1, 0.72 }, { LSX.SHEATH_OUT, 1.32, 0.86 } } do
				local p = newPart(Vector3.one, CFrame.new(st.root.Position), spec[1], Enum.Material.Neon)
				p.Name = "DevFlySheath"
				p.Transparency = 1
				local m = Instance.new("SpecialMesh")
				m.MeshType = Enum.MeshType.Sphere
				m.Parent = p
				st.shells[i] = { part = p, mesh = m, k = spec[2], base = spec[3] }
			end
		end
		local root = st.root
		local v = root.AssemblyLinearVelocity
		local d = v.Magnitude > 20 and v.Unit or root.CFrame.UpVector -- (level flight: his root's up is the way he goes)
		local at = root.Position + d * (S.Ahead or 1.2)
		local cf = CFrame.lookAt(at, at + d)
		local t = os.clock()
		for i, sh in st.shells do
			local flick = 0.93 + 0.07 * math.sin(t * (31 + 9 * i) + i)
			local w = (S.Width or 3.4) * sh.k * (0.55 + 0.45 * k) * flick
			local l = (S.Length or 9) * sh.k * (0.4 + 0.6 * k)
			sh.mesh.Scale = Vector3.new(w, w, l)
			sh.part.CFrame = cf
			sh.part.Transparency = 1 - (1 - sh.base) * k * (st.mine and 0.55 or 1)
		end
	end
	function LSX.unsheath(st)
		for _, sh in st.shells or {} do
			pcall(sh.part.Destroy, sh.part)
		end
		st.shells = nil
	end

	-- a trail across his shoulders, `off` studs to one side (the colour
	-- fringes on the streak of light)
	function LSX.edgeTrail(char, width, life, color, off)
		local torso = char:FindFirstChild("Torso") or char:FindFirstChild("UpperTorso") or char:FindFirstChild("HumanoidRootPart")
		if not torso then
			return nil
		end
		local a0 = Instance.new("Attachment")
		a0.Name = "DevFlyTrail"
		a0.CFrame = CFrame.new(off + width / 2, 0.3, 0)
		a0.Parent = torso
		local a1 = Instance.new("Attachment")
		a1.Name = "DevFlyTrail"
		a1.CFrame = CFrame.new(off - width / 2, 0.3, 0)
		a1.Parent = torso
		local trail = Instance.new("Trail")
		trail.Name = "DevFlyTrail"
		trail.Attachment0, trail.Attachment1 = a0, a1
		trail.Color = ColorSequence.new(color)
		trail.Transparency = NumberSequence.new({ NumberSequenceKeypoint.new(0, 0.05), NumberSequenceKeypoint.new(1, 1) })
		trail.WidthScale = NumberSequence.new(1, 0.15)
		trail.LightEmission = 0.65 -- (some of its colour kept against the sky - all additive washes to white)
		trail.Lifetime = life
		trail.FaceCamera = true
		trail.Parent = torso
		return { trail = trail, made = { trail, a0, a1 } }
	end
	-- THE STREAK OF LIGHT (everyone else: the white core, red fringe one side,
	-- cyan the other)
	function LSX.streak(st, on)
		if on and not st.streak then
			local SK = LSX.look().Streak or {}
			local life, w, f = SK.Life or 0.45, SK.Width or 1.3, SK.Fringe or 0.7
			st.streak = {
				VFX.DFX.bodyTrail(st.char, w, life, LSX.CORE, 0, 1),
				LSX.edgeTrail(st.char, w * 0.7, life * 0.9, LSX.FRINGE_R, f),
				LSX.edgeTrail(st.char, w * 0.7, life * 0.9, LSX.FRINGE_C, -f),
			}
		elseif not on and st.streak then
			for _, t in st.streak do
				VFX.DFX.dropTrail(t)
			end
			st.streak = nil
		end
		-- the fringes either side of it as this screen sees it (square to his
		-- line and to the way the camera looks at him - never edge on)
		local cam = workspace.CurrentCamera
		local torso = st.streak and st.streak[2] and st.streak[2].made[2].Parent
		if cam and torso and torso.Parent then
			local SK = LSX.look().Streak or {}
			local f, w = SK.Fringe or 1.3, (SK.Width or 1) * 0.7
			local side = st.root.AssemblyLinearVelocity:Cross(torso.Position - cam.CFrame.Position)
			if side.Magnitude > 1e-3 and side == side then
				side = torso.CFrame:VectorToObjectSpace(side.Unit)
				for i, sign in { 1, -1 } do
					local t = st.streak[i + 1]
					if t then
						local c = side * f * sign + Vector3.new(0, 0.3, 0)
						t.made[2].CFrame = CFrame.new(c + side * w / 2)
						t.made[3].CFrame = CFrame.new(c - side * w / 2)
					end
				end
			end
		end
	end

	-- the shockwave split into its colours: a ring of each, a beat apart
	function LSX.prismRings(pos, d, size, life)
		local EK = VFX.EngineKit
		local list = EK.lowEnd() and { LSX.PRISM[1], LSX.PRISM[3] } or LSX.PRISM
		for i, c in list do
			EK.vaporRings(pos - d * (i - 1) * 0.8, d, 1, { size = size * (1 + 0.08 * (i - 1)), life = life, color = c })
		end
	end

	-- the light barrier's shards: thin glowing triangles flung out across the
	-- disc round his line, spinning, gone in 0.6 s
	function LSX.shards(pos, d, n)
		local right = d:Cross(math.abs(d.Y) < 0.95 and UP or Vector3.new(1, 0, 0)).Unit
		local up = right:Cross(d).Unit
		for i = 1, n do
			local a = i / n * math.pi * 2 + rand(-0.2, 0.2)
			local out = right * math.cos(a) + up * math.sin(a)
			local w = Instance.new("WedgePart")
			w.Name = "DevFlyShard"
			w.Anchored = true
			w.CanCollide = false
			w.CanQuery = false
			w.CanTouch = false
			w.CastShadow = false
			w.Material = Enum.Material.Neon
			w.Color = LSX.PRISM[i % 3 + 1]:Lerp(Color3.new(1, 1, 1), 0.35)
			w.Size = Vector3.new(0.22, rand(2, 4.2), rand(2, 4.2))
			w.Transparency = 0.1
			local start = pos + out * rand(3, 6)
			w.CFrame = CFrame.new(start) * CFrame.Angles(rand(0, 6), rand(0, 6), rand(0, 6))
			w.Parent = folder
			local to = pos + out * rand(40, 75) + d * rand(-6, 6)
			tween(w, 0.6, { CFrame = CFrame.new(to) * CFrame.Angles(rand(0, 6), rand(0, 6), rand(0, 6)), Transparency = 1, Size = w.Size * 0.4 }, Enum.EasingStyle.Quad, Enum.EasingDirection.Out)
			cleanup(w, 0.65)
		end
	end

	-- where a beat is, and the way he's going
	function LSX.where(char, data)
		local root = charParts(char)
		local pos = typeof(data.Pos) == "Vector3" and data.Pos or (root and root.Position)
		local d = (typeof(data.Dir) == "Vector3" and data.Dir.Magnitude > 0.01 and data.Dir == data.Dir) and data.Dir.Unit
			or (root and root.CFrame.UpVector) or Vector3.new(0, 0, -1)
		return pos, d, root
	end

	---------------------------------------------------------------------------
	-- the beats
	---------------------------------------------------------------------------
	-- THE CHARGE on / off (the burst held at HYPERSONIC): the sheath forming
	-- (the watcher's), the swell and the riser (his ears flat; everyone
	-- else's on him) - let go fast if he lets go of the key
	function LSX.BEATS.Charge(char, data, isLocal)
		local DFX = VFX.DFX
		local st = DFX.flying[char]
		local on = data.On == true
		if st then
			st.chargeAt = on and os.clock() or nil
		end
		local SL = DFX.SND().Light or {}
		if isLocal then
			DFX.letGo(LSX.mine.charge, SL.Abort or 0.18)
			LSX.mine.charge = nil
			if on then
				LSX.mine.charge = DFX.voice("DevFlyLightCharge", nil, 1)
				DFX.hold(LSX.mine.charge)
			end
			return
		end
		-- ((round 90 review) a flyer far off may be streamed out of this
		-- machine: his body comes as nil, and a nil key here threw)
		if not char then
			return
		end
		DFX.letGo(LSX.voices[char], SL.Abort or 0.18)
		LSX.voices[char] = nil
		local root = charParts(char)
		if on and root then
			LSX.voices[char] = DFX.voice("DevFlyLightCharge", DFX.rider(char, root, 2.5), 0.8)
		end
	end

	-- THE LIGHT BARRIER BREAKING
	function LSX.BEATS.Light(char, data, isLocal)
		local DFX = VFX.DFX
		local pos, d = LSX.where(char, data)
		if not pos then
			return
		end
		local B = LSX.look().Break or {}
		local EK = VFX.EngineKit
		local st = DFX.flying[char]
		if st then
			st.chargeAt = nil
		end
		-- the flash, white, a star of light flaring off it, then the shockwave
		-- split into its colours (each a little wider and later than the last)
		DFX.flashBall(pos, 10, 46, 0.2)
		EK.starSpark(pos, { color = LSX.CORE, color2 = LSX.SHEATH, size = B.Flare or 30, life = 0.22 })
		local ring = B.Ring or 160
		for i, c in LSX.PRISM do
			task.delay((i - 1) * 0.035, function()
				billboardRing(pos, 8, ring * (1 + 0.1 * (i - 1)), c, 5, 0.7)
			end)
		end
		billboardRing(pos, 6, ring * 0.7, Color3.new(1, 1, 1), 6, 0.45)
		-- a glassy disc of air across his line, a white one a beat behind it
		local disc = shockDisc(pos, d, 6, B.Disc or 180, 0.75, LSX.SHEATH)
		disc.Transparency = 0.25
		shockDisc(pos - d * 4, d, 4, (B.Disc or 180) * 0.6, 0.55, Color3.new(1, 1, 1))
		-- the vapor cone, twice the boom's; the barrier's shards; streaks thrown back
		DFX.vaporCone(char, pos, d, { length = 18, radius = 10, life = 0.65, ride = 0.06, color = Color3.fromRGB(226, 238, 255) })
		LSX.shards(pos, d, LSX.n(B.Shards or 16))
		streaks(pos, -d, LSX.n(20), 3, 30, 120, Color3.new(1, 1, 1), 0.45)
		EK.vaporRings(pos - d * 2, -d, 3, { size = 9, gap = 9, life = 0.9, color = LSX.CORE })
		local SL = DFX.SND().Light or {}
		if isLocal then
			-- his own screen: the flash, the split rings (HUD), a frame of
			-- impact, the camera thrown; the break in his head, the world
			-- muffled, his ears ringing, the wind sucked out and roaring back
			if VFX.Hooks.LightBreak then
				VFX.Hooks.LightBreak()
			end
			VFX.Hooks.Flash(Color3.new(1, 1, 1), 0.2)
			VFX.ImpactFrame(0.07)
			VFX.Shake(1.8, 0.7)
			DFX.letGo(LSX.mine.charge, 0.05)
			LSX.mine.charge = nil
			VFX.PlaySound("DevFlyLightBreak", nil, 1)
			VFX.PlaySound("DevFlyLightShatter", nil, 1)
			DFX.muffle(SL.Muffle or 1)
			DFX.ring(SL.Ring or 1)
			DFX.duck("Light")
			LSX.mine.brokeAt = os.clock()
			return
		end
		-- ((round 90 review) not keyed by a nil body: a flyer streamed out of
		-- this machine (far off - exactly who hears the boom late) threw here
		-- and the late boom never came)
		if char then
			DFX.letGo(LSX.voices[char], 0.05)
			LSX.voices[char] = nil
		end
		-- everyone else: the light at once, the sound late by the distance (as the boom)
		local DEV = LSX.DEV
		local cam = workspace.CurrentCamera
		local dist = cam and (cam.Focus.Position - pos).Magnitude or 0
		local late = math.min(dist / (DEV.SoundSpeed or 980), DEV.BoomDelayMax or 2.5)
		task.delay(late, function()
			local cam2 = workspace.CurrentCamera
			DFX.boomSound(pos, dist, false, cam2 and cam2.Focus.Position or pos)
			VFX.PlaySound("DevFlyLightShatter", pos, 1)
			DFX.nearBoom(dist, SL.Muffle or 1)
			VFX.ShakeAt(pos, 1.4, 300, 0.6)
		end)
	end

	-- OUT OF LIGHTSPEED: a puff of light where it snapped off him, the colours
	-- in small rings, the light thrown on ahead, the air sucked back in
	function LSX.BEATS.LightOut(char, data, isLocal)
		local DFX = VFX.DFX
		local pos, d = LSX.where(char, data)
		if not pos then
			return
		end
		DFX.flashBall(pos, 4, 16, 0.12)
		for i, c in LSX.PRISM do
			billboardRing(pos, 3, 26 + 5 * i, c, 2, 0.35)
		end
		VFX.EngineKit.vaporRings(pos, d, 2, { size = 5, gap = 6, life = 0.5, color = LSX.CORE })
		streaks(pos, d, LSX.n(10), 2, 12, 40, LSX.SHEATH, 0.3)
		VFX.PlaySound("DevFlyLightOut", (not isLocal) and pos or nil, 1)
		if isLocal then
			DFX.duck("LightOut")
			VFX.Shake(0.7, 0.3)
			if VFX.Hooks.LightOut then
				VFX.Hooks.LightOut()
			end
		end
	end

	-- THE ROLL / THE SIDESTEP: a ghost where he started, the air whipped round
	function LSX.BEATS.Roll(char, data, isLocal)
		local root = charParts(char)
		if not root then
			return
		end
		local d = (typeof(data.Dir) == "Vector3" and data.Dir.Magnitude > 0.01 and data.Dir == data.Dir) and data.Dir.Unit or root.CFrame.RightVector
		VFX.EngineKit.afterimage(char, Color3.new(1, 1, 1), 0.22, { transparency = 0.5 })
		streaks(root.Position, -d, LSX.n(6), 1.5, 4, 10, WIND, 0.22)
		VFX.PlaySound("DevFlyRoll", (not isLocal) and root.Position or nil, data.Hover and 0.75 or 1)
	end

	---------------------------------------------------------------------------
	-- the watcher (DFX.step, every flyer on every screen) and his own screen
	---------------------------------------------------------------------------
	-- one frame of one flyer: the sheath (charging: forming; at LIGHTSPEED:
	-- full), the crackle round it while it forms, the streak of light (not on
	-- his own screen: the camera rides inside it), the prismatic rings
	function LSX.step(st, tier, speed, d, now, dt)
		local L = LSX.DEV.Light or {}
		local lit = tier == "Light"
		local k = 0
		if lit then
			k = 1
		elseif st.chargeAt then
			k = math.clamp((now - st.chargeAt) / math.max(L.Charge or 1.4, 0.1), 0, 1) * 0.85
			if now - st.chargeAt > (L.Charge or 1.4) + 1.5 then
				st.chargeAt = nil -- (a let go that never came)
			end
		end
		st.sheathK = st.sheathK or 0
		st.sheathK += (k - st.sheathK) * math.min(1, dt * (k > st.sheathK and 6 or 4))
		LSX.sheath(st, st.sheathK)
		local low = VFX.EngineKit.lowEnd()
		if st.chargeAt and not lit and now >= (st.next.crackle or 0) then
			st.next.crackle = now + (low and 0.16 or 0.08)
			VFX.EngineKit.starSpark(st.root.Position + rng:NextUnitVector() * rand(1.5, 3.2), { color = LSX.SHEATH, color2 = Color3.new(1, 1, 1), size = rand(1, 2.2), life = 0.08 })
		end
		LSX.streak(st, lit and not st.mine)
		if lit and speed > 300 and now >= (st.next.prism or 0) then
			st.next.prism = now + (LSX.look().Rings or 0.18) * (low and 2 or 1)
			LSX.prismRings(st.root.Position - d * 6, d, 3.6, 0.45)
		end
	end
	-- he's down (or gone): the sheath, the streak, the charge's sound
	function LSX.untrack(st)
		LSX.unsheath(st)
		LSX.streak(st, false)
		st.chargeAt = nil
		if LSX.voices[st.char] then
			VFX.DFX.letGo(LSX.voices[st.char], 0.15)
			LSX.voices[st.char] = nil
		end
	end

	-- HIS OWN SCREEN at LIGHTSPEED: the grade (the colour pushed and tinted,
	-- a bloom on the light) and the stars, faded in and out with it
	function LSX.frame(char, root, speed, tier, dt, cam)
		local M = LSX.mine
		local G = LSX.look().Grade or {}
		local want = tier == "Light" and 1 or 0
		M.k += (want - M.k) * math.min(1, dt * (want > M.k and 5 or 3))
		if M.k > 0.01 and not M.grade then
			local cc = Instance.new("ColorCorrectionEffect")
			cc.Name = "DevFlyLight"
			cc.Parent = Lighting
			local bloom = Instance.new("BloomEffect")
			bloom.Name = "DevFlyBloom"
			bloom.Intensity = 0
			bloom.Size = 28
			bloom.Threshold = 0.9
			bloom.Parent = Lighting
			M.grade, M.bloom = cc, bloom
		end
		if M.grade then
			M.grade.Saturation = (G.Saturation or 0.22) * M.k
			M.grade.Contrast = (G.Contrast or 0.14) * M.k
			M.grade.Brightness = 0.02 * M.k
			M.grade.TintColor = Color3.new(1, 1, 1):Lerp(G.Tint or Color3.fromRGB(222, 234, 255), M.k)
			M.bloom.Intensity = (G.Bloom or 0.7) * M.k
			if M.k <= 0.01 and want == 0 then
				LSX.ungrade()
			end
		end
		LSX.stars(cam, root, root.AssemblyLinearVelocity, M.k)
	end
	function LSX.ungrade()
		local M = LSX.mine
		for _, key in { "grade", "bloom" } do
			if M[key] then
				pcall(M[key].Destroy, M[key])
				M[key] = nil
			end
		end
	end
	-- THE STARS streaking past: long thin lines hung in a tunnel round his
	-- line out ahead of him, each put back out ahead once he's past it (the
	-- old specks, stretched a hundredfold)
	function LSX.stars(cam, root, v, k)
		local M = LSX.mine
		local S = LSX.look().Stars or {}
		local want = (k > 0.05 and cam and root and v.Magnitude > 200) and LSX.n(S.Count or 40) or 0
		while #M.stars > want do
			local gone = table.remove(M.stars)
			pcall(gone.Destroy, gone)
		end
		if want == 0 then
			return
		end
		local d = v.Unit
		local camPos = cam.CFrame.Position
		local right = d:Cross(math.abs(d.Y) < 0.95 and UP or Vector3.new(1, 0, 0)).Unit
		local up2 = right:Cross(d).Unit
		local R, A, Ln = S.Round or { 12, 70 }, S.Ahead or { 80, 420 }, S.Len or { 40, 90 }
		local function place(p, far)
			local a = rand(0, math.pi * 2)
			local at = root.Position + d * (far and rand((A[1] + A[2]) / 2, A[2]) or rand(A[1], A[2])) + (right * math.cos(a) + up2 * math.sin(a)) * rand(R[1], R[2])
			p:SetAttribute("At", at)
			p:SetAttribute("Len", rand(Ln[1], Ln[2]))
		end
		while #M.stars < want do
			local p = newPart(Vector3.new(0.09, 0.09, 1), CFrame.new(root.Position), LSX.STAR[#M.stars % #LSX.STAR + 1], Enum.Material.Neon)
			p.Name = "DevFlyStar"
			place(p, false)
			table.insert(M.stars, p)
		end
		for _, p in M.stars do
			local at = p:GetAttribute("At")
			if typeof(at) ~= "Vector3" or (at - camPos):Dot(d) < -5 or (at - root.Position).Magnitude > A[2] + 120 then
				place(p, true)
				at = p:GetAttribute("At")
			end
			local len = (tonumber(p:GetAttribute("Len")) or 60) * (0.3 + 0.7 * k)
			p.Size = Vector3.new(0.09, 0.09, len)
			p.CFrame = CFrame.lookAt(at, at + d)
			p.Transparency = 1 - 0.78 * k
		end
	end
	-- down: his screen's light gone (the charge's sound let go over `fade`)
	function LSX.stopMine(fade)
		local M = LSX.mine
		for _, p in M.stars do
			pcall(p.Destroy, p)
		end
		table.clear(M.stars)
		LSX.ungrade()
		M.k = 0
		if M.charge and VFX.DFX then
			VFX.DFX.letGo(M.charge, fade or 0.15)
		end
		M.charge, M.brokeAt = nil, nil
	end
end

---------------------------------------------------------------------------
-- (round 90) SAITAMA on every screen (VFX.ST; Config.Quirks.Saitama,
-- Config.Saitama): his cape (swung from how he moves, whipping in a gale),
-- his bored idle, the serious eyes' glint; every move (the normal punch's
-- gale, the flurry of fists, the sneeze, the afterimages, the street turned
-- over like a table, the awakening's "OK.", the ONE PUNCH finisher); and the
-- SERIOUS PUNCH: the windup (the sky gathering over the city, the wind, the
-- eyes, the fist drawn back, every screen shaking harder), then - when the
-- server says it's thrown (SeriousPunchGo) - THE WIPE: this screen's copy of
-- the whole city torn apart and blown to the horizon as the wave reaches
-- each part (Config.SeriousWave: the server's own law for who's hit when),
-- the clouds blown clear; and a while later every piece flown back into its
-- place. Nothing of the real map is changed (the server's crater and trench
-- are its own): the originals are only hidden on this screen, at most
-- Wipe.Max copies fly (all moved in one BulkMoveTo a frame), and everything
-- is put back exactly - on its timer, when another punch starts, or at
-- MaxTime whatever happens.
-- (In a function of its own: the main chunk is at its local limit.)
---------------------------------------------------------------------------
;(function()
	local ST = { rigs = {}, wind = {}, idle = {}, runs = {}, emoting = {} }
	VFX.ST = ST
	local Q = Config.Quirks.Saitama or {}
	local C = Config.Saitama or {}
	local W = C.Wipe or {}
	local LightingSvc = game:GetService("Lighting")
	local AIR = Color3.fromRGB(246, 250, 255)
	local DUST = Color3.fromRGB(204, 190, 168)
	local DUST_DARK = Color3.fromRGB(150, 136, 118)
	local LOOK = C.Look or {}

	---------------------------------------------------------------------
	-- helpers
	---------------------------------------------------------------------
	function ST.low()
		return IceKit.lowEnd()
	end
	-- the move as he has it right now (the ult's own numbers while he's in it)
	function ST.spec(char, id)
		local ult = char and char:GetAttribute("UltActive") == true and Q.Ult or nil
		for _, set in { ult and ult.Abilities, ult and { ult.Special, ult.Extra }, Q.Abilities, { Q.Special, Q.Extra }, Q.Ult and Q.Ult.Abilities } do
			for _, a in set or {} do
				if type(a) == "table" and a.Id == id then
					return a
				end
			end
		end
		return {}
	end
	function ST.me()
		local p = Players.LocalPlayer
		return p and p.Character
	end
	function ST.camPos()
		local cam = workspace.CurrentCamera
		return cam and cam.CFrame.Position or Vector3.zero
	end
	-- what a screen hears of something map-wide: flat (everywhere at once),
	-- louder the nearer it is
	function ST.far(name, at, gain)
		local dist = typeof(at) == "Vector3" and (ST.camPos() - at).Magnitude or 0
		VFX.PlaySound(name, nil, (gain or 1) * math.clamp(1.25 - dist / 1800, 0.35, 1.25))
	end
	function ST.isSaitama(char)
		return char ~= nil and char.Parent ~= nil and char:GetAttribute("Quirk") == "Saitama"
	end
	-- a flat direction (his facing when there's none)
	function ST.flat(v, root)
		return flatten(typeof(v) == "Vector3" and v or nil, root)
	end
	-- at `at`, looking along the flat d (fromMatrix: right in Roblox and in the test harness alike)
	function ST.lookAlong(at, d)
		local f = Vector3.new(d.X, 0, d.Z)
		f = f.Magnitude > 1e-3 and f.Unit or Vector3.new(0, 0, -1)
		local right = f:Cross(Vector3.new(0, 1, 0))
		return CFrame.fromMatrix(at, right, right:Cross(f))
	end
	-- a ray that sees only the map (not bodies, not effects)
	function ST.ray(from, to)
		local v = to - from
		if v.Magnitude < 0.05 then
			return nil
		end
		rayParams.FilterDescendantsInstances = characterList()
		return workspace:Raycast(from, v, rayParams)
	end

	---------------------------------------------------------------------
	-- procedural fallbacks for every clip (anim/moves_saitama.py): what an
	-- R15 body, or a place without the clips, plays
	---------------------------------------------------------------------
	POSES.SaitamaSeriousDraw = { RightArm = { -35, 0, 25 }, LeftArm = { 70, 0, -10 }, Waist = { -8, 42, 0 }, Neck = { 6, -34, 0 }, RightLeg = -18, LeftLeg = 24, Hips = { 0, 0, 0, 0, -0.55, 0 } }
	POSES.SaitamaSeriousAfter = { RightArm = { 92, 0, 0 }, LeftArm = { 12, 0, 12 }, Waist = { -4, -22, 0 }, Neck = { 0, 18, 0 }, RightLeg = 18, LeftLeg = -14, Hips = { 0, 0, 0, 0, -0.35, 0 } }
	POSES.SaitamaBored1 = { RightArm = { 118, 34, 0 }, LeftArm = { 6, 0, 6 }, Neck = { -6, 8, 0 } }
	POSES.SaitamaBored2 = { RightArm = { 168, 0, 14 }, LeftArm = { 8, 0, 8 }, Neck = { -18, 0, 10 } }
	POSES.SaitamaBored3 = { RightArm = { 52, 30, 0 }, LeftArm = { 4, 0, 6 }, Neck = { 14, 12, 0 } }
	MOTIONS.SaitamaNormalPunch = { { pose = { RightArm = { 20, 0, 10 }, LeftArm = { 30, 0, 10 }, Waist = { 0, -18, 0 } }, t = 0.1 }, { pose = { RightArm = 92, LeftArm = { 20, 0, 10 }, Waist = { -6, 24, 0 } }, t = 0.06, hold = 0.24 }, recover = 0.25 }
	MOTIONS.SaitamaFlurry = { { pose = { RightArm = 92, LeftArm = 40, Waist = { -6, 14, 0 } }, t = 0.07 }, { pose = { RightArm = 40, LeftArm = 92, Waist = { -6, -14, 0 } }, t = 0.07 }, recover = 0.1 }
	MOTIONS.SaitamaFlurryEnd = { { pose = { RightArm = 95, LeftArm = { 20, 0, 10 }, Waist = { -8, 26, 0 } }, t = 0.08, hold = 0.3 }, recover = 0.25 }
	MOTIONS.SaitamaSneeze = { { pose = { Neck = { -30, 0, 0 }, Waist = { 12, 0, 0 }, RightArm = { 10, 0, 8 } }, t = 0.5, hold = 0.2 }, { pose = { Neck = { 30, 0, 0 }, Waist = { -22, 0, 0 }, RightArm = { 70, 20, 0 } }, t = 0.06, hold = 0.35 }, recover = 0.3 }
	MOTIONS.SaitamaHops = { { pose = { RightLeg = 20, LeftLeg = -20, Waist = { -10, 0, 12 }, Hips = { 0, 0, 0, 0, -0.6, 0 } }, t = 0.06, hold = 0.18 }, { pose = { RightLeg = -20, LeftLeg = 20, Waist = { -10, 0, -12 }, Hips = { 0, 0, 0, 0, -0.6, 0 } }, t = 0.06, hold = 0.18 }, recover = 0.2 }
	MOTIONS.SaitamaTableFlip = { { pose = { RightArm = -20, LeftArm = -20, Waist = { -40, 0, 0 }, Hips = { 0, 0, 0, 0, -1, 0 } }, t = 0.3 }, { pose = { RightArm = 170, LeftArm = 170, Waist = { 10, 0, 0 } }, t = 0.12, hold = 0.4 }, recover = 0.35 }
	MOTIONS.SaitamaAwaken = { { pose = { Neck = { 8, 0, 0 } }, t = 0.25 }, { pose = { RightArm = { 10, 0, 14 }, LeftArm = { 10, 0, 14 }, Neck = { -4, 0, 0 }, Hips = { 0, 0, 0, 0, -0.2, 0 } }, t = 0.08, hold = 0.8 }, recover = 0.3 }
	MOTIONS.SaitamaSeriousSet = { { pose = { RightArm = { 10, 0, 16 }, LeftArm = { 10, 0, 16 }, Hips = { 0, 0, 0, 0, -0.35, 0 }, RightLeg = -16, LeftLeg = 16 }, t = 0.3, hold = 0.25 }, recover = 0.2 }
	MOTIONS.SaitamaSeriousPunch = { { pose = { RightArm = 95, LeftArm = { 10, 0, 14 }, Waist = { -10, -30, 0 }, RightLeg = 22, LeftLeg = -18, Hips = { 0, 0, 0, 0, -0.45, -0.3 } }, t = 0.06, hold = 0.5 }, recover = 0.3 }

	---------------------------------------------------------------------
	-- THE CAPE (the server's SaitamaCape: hinged segments) - every screen
	-- swings it from his motion, and whips it in a gale
	---------------------------------------------------------------------
	-- a gale on him: level 0..1 for `time` seconds (the windup, the punch, the awakening)
	function ST.gust(char, level, time)
		local w = ST.wind[char]
		local now = os.clock()
		if not w or w.untilAt < now or level >= w.level then
			ST.wind[char] = { level = level, untilAt = now + (time or 1) }
		end
	end
	function ST.windOf(char, now)
		local w = ST.wind[char]
		if not w then
			return 0
		end
		if w.untilAt < now then
			ST.wind[char] = nil
			return 0
		end
		return w.level * math.clamp((w.untilAt - now) / 0.4, 0, 1)
	end
	-- bind (or re-bind: the gear's rebuilt on every change) his cape
	function ST.bindCape(char)
		local gear = char:FindFirstChild("QuirkGear")
		local cos = gear and gear:FindFirstChild("Cosmetics")
		local cape = cos and cos:FindFirstChild("SaitamaCape")
		local rig = ST.rigs[char]
		if not cape then
			ST.rigs[char] = nil
			return nil
		end
		if rig and rig.model == cape then
			return rig
		end
		rig = { model = cape, segs = {}, phase = rng:NextNumber(0, 10) }
		for i = 1, 8 do
			local seg = cape:FindFirstChild("CapeSeg" .. i)
			local joint = seg and seg:FindFirstChild("CapeJoint")
			if not (joint and joint:IsA("Weld")) then
				break
			end
			rig.segs[i] = { joint = joint, at = joint.C0.Position, swing = 0, roll = 0 }
		end
		ST.rigs[char] = rig
		return rig
	end
	-- one frame of the cape: each segment's swing (degrees back off the one
	-- above) and roll toward where the air pushes it
	function ST.capeStep(char, rig, dt, now)
		local CP = C.Cape or {}
		local torso = char:FindFirstChild("Torso") or char:FindFirstChild("UpperTorso")
		local root = char:FindFirstChild("HumanoidRootPart")
		local n = #rig.segs
		if not torso or not root or n == 0 then
			return
		end
		local v = root.AssemblyLinearVelocity
		-- (round 90 review) a body's velocity gone NaN or wild for a frame (a
		-- fling): the cape keeps its last swing - a NaN joint would carry
		-- into the welded parts
		if v.Magnitude ~= v.Magnitude or v.Magnitude > 1e4 then
			return
		end
		local lv = torso.CFrame:VectorToObjectSpace(v)
		local fwd, side, fall = -lv.Z, lv.X, -v.Y
		-- (where "straight down" is from his torso: he leans, the cape still hangs)
		local g = torso.CFrame:VectorToObjectSpace(Vector3.new(0, -1, 0))
		local hang = math.deg(math.atan2(g.Z, math.max(-g.Y, 0.05)))
		local wind = ST.windOf(char, now)
		local speed = math.sqrt(fwd * fwd + side * side)
		local lift = math.clamp(math.max(fwd, 0) * (CP.Lift or 2.2) + math.max(fall, 0) * (CP.Fall or 1.4) + wind * 50, 0, CP.Max or 78)
		local amp = (CP.Flutter or 3) + speed * (CP.FlutterSpeed or 0.25) + wind * (CP.Wind or 26)
		local rate = (CP.Rate or 1.6) * (1 + speed / 30 + wind * 2.2) * math.pi * 2
		local k = 1 - math.exp(-(CP.Blend or 10) * dt)
		local rest = CP.Rest or 6
		local prevAbs = 0
		-- (round 93 review) the run's strides kick a leg up behind into it:
		-- held out past them (VFX.Gait.capeFloor), the chain followed down
		-- from the hinge side-on
		local legs = VFX.Gait.capeLegs(char, torso)
		local cy, cz, held = 0, 0, 0
		for i, s in rig.segs do
			local share = i / n
			local flutter = math.sin(rig.phase + now * rate - i * 0.9) * amp * share
			-- this segment's angle back from his torso's own down (never in
			-- through his back or his legs), then from the one above it
			local floor = i == 1 and rest or 0
			local abs = math.max(hang + floor + lift * share ^ 0.8 + flutter, floor)
			local rel = abs - prevAbs
			prevAbs = abs
			local roll = math.clamp(-side * (CP.Side or 1.2), -35, 35) * share + math.sin(rig.phase * 1.7 + now * rate * 0.7 + i) * amp * 0.25 * share
			s.swing += (rel - s.swing) * k
			s.roll += (roll - s.roll) * k
			if legs then
				if i == 1 then
					cy, cz = s.at.Y, s.at.Z
				end
				local h = 2 * s.joint.C1.Y
				local out = VFX.Gait.capeFloor(legs, cy, cz, h, held + s.swing)
				s.swing, held = out - held, out
				cy, cz = cy - h * math.cos(math.rad(out)), cz + h * math.sin(math.rad(out))
			end
			if s.joint.Parent then
				s.joint.C0 = CFrame.new(s.at) * CFrame.Angles(math.rad(-s.swing), 0, math.rad(s.roll))
			end
		end
	end

	---------------------------------------------------------------------
	-- THE BORED IDLE: standing about too long, out of a fight
	---------------------------------------------------------------------
	function ST.idleStep(char, now)
		local I = C.Idle or {}
		local root, hum = charParts(char)
		if not root or not hum then
			return
		end
		local st = ST.idle[char]
		if not st then
			st = { still = now, token = VFX.PoseToken(char), acted = now }
			ST.idle[char] = st
		end
		local token = VFX.PoseToken(char)
		if token ~= st.token then
			-- something else posed him (a move, a hit, a dash): not bored
			st.token = token
			st.acted = now
			st.mine = false
			st.playing = false
		end
		local v = root.AssemblyLinearVelocity
		local moving = Vector3.new(v.X, 0, v.Z).Magnitude > 1.5 or math.abs(v.Y) > 4
		-- ((round 90 review) and never in the middle of an emote: a dance runs
		-- 15 s standing still, and a bored pose would cut it and its song off)
		local busy = moving or char:GetAttribute("Ragdolled") or char:GetAttribute("Stunned") or char:GetAttribute("Holding")
			or char:GetAttribute("Grabbed") or hum.Health <= 0 or (ST.runs[char] ~= nil) or (ST.emoting[char] ~= nil)
		if busy then
			st.still = now
			if st.playing then
				st.playing = false
				VFX.ReleasePose(char, 0.18)
			end
			return
		end
		if st.playing or now - st.still < (I.After or 7) or now - st.acted < (I.Calm or 4) or now < (st.next or 0) then
			return
		end
		-- (the same pick on every screen, near enough: the server's clock)
		local clips = I.Clips or {}
		local pick = (math.floor(workspace:GetServerTimeNow() / math.max(I.Every or 12, 1)) + #char.Name) % math.max(#clips, 1) + 1
		local name = clips[pick]
		if not name then
			return
		end
		VFX.Pose(char, (name:gsub("^Pose", "")), I.Hold or 2.6)
		st.token = VFX.PoseToken(char) -- (ours: a change after it is someone else's)
		st.mine = true
		st.playing = true
		st.next = now + (I.Hold or 2.6) + (I.Every or 12)
		task.delay((I.Hold or 2.6) + 0.4, function()
			if ST.idle[char] == st then
				st.playing = false
			end
		end)
	end

	-- every Saitama this screen sees: the cape every frame (near the
	-- camera), the idle a few times a second
	ST.bodies = {}
	ST.scanAt, ST.idleAt = 0, 0
	function ST.step(dt)
		local now = os.clock()
		if now >= ST.scanAt then
			ST.scanAt = now + 0.5
			local list = {}
			for _, plr in Players:GetPlayers() do
				if ST.isSaitama(plr.Character) then
					table.insert(list, plr.Character)
				end
			end
			local dummies = workspace:FindFirstChild("Dummies")
			for _, m in dummies and dummies:GetChildren() or {} do
				if ST.isSaitama(m) then
					table.insert(list, m)
				end
			end
			ST.bodies = list
			for char in ST.rigs do
				if not ST.isSaitama(char) then
					ST.rigs[char] = nil
				end
			end
			for char in ST.idle do
				if not ST.isSaitama(char) then
					ST.idle[char] = nil
				end
			end
			-- ((round 90 review) a gale on a body that's gone: let go too - only
			-- a cape near the camera ever cleared its own)
			for char, w in ST.wind do
				if not char.Parent or w.untilAt < now then
					ST.wind[char] = nil
				end
			end
		end
		local cam = ST.camPos()
		local CP = C.Cape or {}
		local cull = ST.low() and (CP.LowCull or 80) or (CP.Cull or 160)
		local idleNow = now >= ST.idleAt
		if idleNow then
			ST.idleAt = now + 0.25
		end
		for _, char in ST.bodies do
			local root = char.Parent and char:FindFirstChild("HumanoidRootPart")
			if root and (root.Position - cam).Magnitude <= cull then
				local rig = ST.bindCape(char)
				if rig then
					ST.capeStep(char, rig, math.min(dt or 1 / 60, 0.1), now)
				end
			end
			if idleNow and root and (root.Position - cam).Magnitude <= ((C.Idle and C.Idle.Cull) or 140) then
				ST.idleStep(char, now)
			end
		end
	end
	RunService:BindToRenderStep("SaitamaCape", Enum.RenderPriority.Camera.Value + 3, function(dt)
		local ok, err = pcall(ST.step, dt)
		if not ok and not ST.warned then
			ST.warned = true
			warn("[VFX.ST] " .. tostring(err))
		end
	end)

	---------------------------------------------------------------------
	-- the pieces his moves are drawn with
	---------------------------------------------------------------------
	-- an afterimage of him: every visible part of his body and his look,
	-- copied where it is (or moved to `at`, his root's place), fading out
	function ST.ghost(char, life, at, tint)
		local root = char:FindFirstChild("HumanoidRootPart")
		if not root then
			return nil
		end
		local model = Instance.new("Model")
		model.Name = "SaitamaGhost"
		local shift = at and at * root.CFrame:Inverse() or nil
		local low = ST.low()
		for _, part in char:GetDescendants() do
			if part:IsA("BasePart") and part ~= root and part.Transparency < 0.95 and not (low and part.Size.Magnitude < 0.5) then
				local g = Instance.new("Part")
				g.Anchored = true
				g.CanCollide = false
				g.CanQuery = false
				g.CanTouch = false
				g.CastShadow = false
				g.Size = part.Size
				g.Color = tint and part.Color:Lerp(tint, 0.35) or part.Color
				g.Material = Enum.Material.SmoothPlastic
				g.Transparency = 0.25 + part.Transparency * 0.7
				g.CFrame = shift and shift * part.CFrame or part.CFrame
				local mesh = part:FindFirstChildOfClass("SpecialMesh")
				if mesh then
					local m = Instance.new("SpecialMesh")
					m.MeshType = mesh.MeshType
					m.Scale = mesh.Scale
					m.Parent = g
				end
				g.Parent = model
				tween(g, life, { Transparency = 1 }, Enum.EasingStyle.Quad, Enum.EasingDirection.In)
			end
		end
		model.Parent = folder
		cleanup(model, life + 0.05)
		return model
	end

	-- a ring of air facing along d (a flat disc that opens and fades)
	function ST.ring(pos, d, from, to, life, color, transparency)
		local cf = CFrame.lookAt(pos, pos + d) * CFrame.Angles(0, math.rad(90), 0)
		local p = newPart(Vector3.new(0.4, from, from), cf, color or AIR, Enum.Material.SmoothPlastic, Enum.PartType.Cylinder)
		p.Transparency = transparency or 0.45
		tween(p, life, { Size = Vector3.new(0.15, to, to), Transparency = 1 }, Enum.EasingStyle.Quad, Enum.EasingDirection.Out)
		cleanup(p, life + 0.05)
		return p
	end

	-- THE GALE: a punch's wind going on down the street behind where it
	-- landed (rings of air out along it, a tube of wind, streaks, the dust
	-- thrown up off the street under it)
	function ST.gale(pos, d, range, width, strong)
		local scale = strong and 1 or 0.7
		for i = 0, 4 do
			local at = pos + d * (range * i / 5)
			task.delay(i * range / 5 / 260, function()
				ST.ring(at, d, width * 0.4, width * (1.3 + i * 0.25) * scale, 0.35 + i * 0.04, AIR, 0.35 + i * 0.08)
			end)
		end
		local tube = newPart(Vector3.new(1, width * 0.6, width * 0.6), CFrame.lookAt(pos, pos + d) * CFrame.Angles(0, math.rad(90), 0), AIR, Enum.Material.SmoothPlastic, Enum.PartType.Cylinder)
		tube.Transparency = 0.55
		local reach = pos + d * range
		tween(tube, 0.22, { Size = Vector3.new(range, width * scale, width * scale), CFrame = CFrame.lookAt((pos + reach) / 2, reach) * CFrame.Angles(0, math.rad(90), 0) }, Enum.EasingStyle.Quad, Enum.EasingDirection.Out)
		tween(tube, 0.45, { Transparency = 1 }, Enum.EasingStyle.Quad, Enum.EasingDirection.In, 0.12)
		cleanup(tube, 0.6)
		streaks(pos, d, ST.low() and 8 or 18, 14, 10, range, AIR, 0.4)
		local steps = ST.low() and 3 or 6
		for i = 1, steps do
			task.delay(i * range / steps / 260, function()
				dustPuffs(groundPoint(pos + d * (range * i / steps)), (0.8 + i * 0.12) * scale, 3, DUST, 0.9, false)
			end)
		end
		VFX.ShakeAt(pos, 2.2 * scale, 140, 0.45)
	end

	---------------------------------------------------------------------
	-- 1: NORMAL PUNCH
	---------------------------------------------------------------------
	function Effects.NormalPunch(char, data, isLocal)
		local root = charParts(char)
		if not root then
			return
		end
		local spec = ST.spec(char, "NormalPunch")
		local d = ST.flat(data.Dir, root)
		local startup = spec.Startup or 0.16
		if isLocal then
			face(root, d)
			-- the lazy step in (his own machine moves him)
			dash(root, d * ((spec.Lunge or 6) / startup), startup)
		end
		VFX.Motion(char, "SaitamaNormalPunch")
		VFX.PlaySound("NormalPunchSwing", root.Position, 1)
		task.delay(startup, function()
			if root.Parent then
				-- the fist's own little puff (the server's NormalPunchHit lands the rest)
				ST.ring(handPos(char, true), d, 0.6, 5, 0.16, AIR, 0.3)
			end
		end)
	end

	-- (server) the punch landed - or didn't: the gale blows on down the line either way
	function Effects.NormalPunchHit(char, data)
		local pos = typeof(data.Pos) == "Vector3" and data.Pos or nil
		local dir = typeof(data.Dir) == "Vector3" and Vector3.new(data.Dir.X, 0, data.Dir.Z) or nil
		if not pos or not dir or dir.Magnitude < 0.05 then
			return
		end
		local d = dir.Unit
		local target = typeof(data.Target) == "Instance" and data.Target or nil
		local range = tonumber(data.Range) or 50
		local width = tonumber(data.Width) or 10
		local me = ST.me()
		VFX.PlaySound(target and "NormalPunchHit" or "NormalPunchGale", pos, 1)
		if target then
			-- the contact: a beat of black and white on the screens that matter,
			-- a star on the face, their body leaving a streak of air
			if me == char or me == target or nearCamera(pos, 45) then
				VFX.ImpactFrame(0.09)
			end
			VFX.HitStar(pos + Vector3.new(0, 0.6, 0), 8, Color3.new(1, 1, 1))
			local torso = target:FindFirstChild("Torso") or target:FindFirstChild("UpperTorso")
			if torso then
				addTrail(torso, AIR, 0.3, 2)(1.1)
			end
			VFX.PlaySound("NormalPunchGale", pos + d * range * 0.4, 0.9)
		end
		ST.gale(pos, d, range, width, target ~= nil)
	end

	---------------------------------------------------------------------
	-- 2: CONSECUTIVE NORMAL PUNCHES: fists everywhere in front of him
	---------------------------------------------------------------------
	-- the ghost fists (a sleeve and a glove), kept and reused
	function ST.fist(pool)
		for _, f in pool do
			if not f.busy then
				return f
			end
		end
		local f = { busy = false }
		f.sleeve = newPart(Vector3.new(0.9, 0.9, 1.8), CFrame.new(0, -1e4, 0), LOOK.Suit or Color3.new(1, 0.85, 0.2), Enum.Material.SmoothPlastic)
		f.glove = newPart(Vector3.new(1.0, 1.0, 0.9), CFrame.new(0, -1e4, 0), LOOK.Glove or Color3.new(0.8, 0.1, 0.15), Enum.Material.SmoothPlastic)
		f.sleeve.Name, f.glove.Name = "SaitamaFist", "SaitamaFist"
		table.insert(pool, f)
		return f
	end
	function ST.flurry(char, root, total, spec)
		local pool = {}
		local t0 = os.clock()
		local low = ST.low()
		local perFrame = low and 1 or 3
		local cone = math.rad(38)
		local reach = (spec.Range or 8) * 0.8
		local swish = 0
		while os.clock() - t0 < total and root.Parent and char.Parent do
			local look = root.CFrame
			for _ = 1, perFrame do
				local f = ST.fist(pool)
				f.busy = true
				-- out of his shoulder toward a spot in the cone in front of him
				local yaw, pitch = rand(-cone, cone), rand(-0.45, 0.4)
				local dir = (look * CFrame.Angles(pitch, yaw, 0)).LookVector
				local from = look.Position + Vector3.new(0, 0.6, 0) + look.RightVector * rand(-0.9, 0.9)
				local out = rand(reach * 0.55, reach)
				local cfA = CFrame.lookAt(from + dir * 1, from + dir * 2)
				local cfB = CFrame.lookAt(from + dir * out, from + dir * (out + 1))
				f.sleeve.CFrame = cfA * CFrame.new(0, 0, 0.9)
				f.glove.CFrame = cfA * CFrame.new(0, 0, -0.45)
				f.sleeve.Transparency, f.glove.Transparency = 0.15, 0.05
				tween(f.sleeve, 0.06, { CFrame = cfB * CFrame.new(0, 0, 0.9), Transparency = 0.6 }, Enum.EasingStyle.Quad, Enum.EasingDirection.Out)
				tween(f.glove, 0.06, { CFrame = cfB * CFrame.new(0, 0, -0.45), Transparency = 0.4 }, Enum.EasingStyle.Quad, Enum.EasingDirection.Out)
				task.delay(0.09, function()
					f.sleeve.CFrame = CFrame.new(0, -1e4, 0)
					f.glove.CFrame = CFrame.new(0, -1e4, 0)
					f.busy = false
				end)
				-- a pop of air where a fist lands
				if rng:NextNumber() < (low and 0.25 or 0.5) then
					local at = from + dir * (out + 0.6)
					local pop = newPart(Vector3.one * 0.6, CFrame.new(at), AIR, Enum.Material.Neon, Enum.PartType.Ball)
					pop.Transparency = 0.2
					tween(pop, 0.12, { Size = Vector3.one * rand(1.8, 2.8), Transparency = 1 })
					cleanup(pop, 0.15)
				end
			end
			swish += 1
			if swish % 2 == 0 then
				VFX.PlaySound("PunchFlurry", root.Position, 1)
			end
			task.wait()
		end
		for _, f in pool do
			cleanup(f.sleeve, 0.12)
			cleanup(f.glove, 0.12)
		end
	end

	function Effects.ConsecutivePunches(char, data, isLocal)
		local root = charParts(char)
		if not root then
			return
		end
		local spec = ST.spec(char, "ConsecutivePunches")
		local d = ST.flat(data.Dir, root)
		if isLocal then
			face(root, d)
		end
		VFX.Voice("SaitamaConsecutive", root)
		local startup = spec.Startup or 0.15
		local flurry = (spec.Hits or 14) * (spec.Interval or 0.07)
		local t0 = os.clock()
		-- the body: the jabs over and over (a new cycle every 0.28 s), the fists
		-- a blur round it, and the last punch on the server's beat
		task.spawn(function()
			task.wait(startup)
			if not root.Parent then
				return
			end
			task.spawn(ST.flurry, char, root, flurry, spec)
			while os.clock() - t0 < startup + flurry - 0.1 and root.Parent do
				VFX.Motion(char, "SaitamaFlurry")
				task.wait(0.27)
			end
			task.wait(math.max(startup + flurry - (os.clock() - t0), 0))
			if not root.Parent then
				return
			end
			VFX.Motion(char, "SaitamaFlurryEnd")
			task.wait(0.08)
			if not root.Parent then
				return
			end
			local fd = ST.flat(root.CFrame.LookVector, root)
			local at = root.Position + fd * 4.5
			VFX.PlaySound("PunchFlurryFinish", at, 1)
			ST.ring(at, fd, 2, 16, 0.3, AIR, 0.25)
			billboardRing(at, 2, 14, AIR, 6, 0.3)
			streaks(at, fd, ST.low() and 6 or 12, 10, 8, 30, AIR, 0.35)
			dustPuffs(groundPoint(at), 1, 4, DUST, 0.8, false)
			VFX.ShakeAt(at, 2, 90, 0.35)
		end)
	end

	---------------------------------------------------------------------
	-- 3: SERIOUS SNEEZE: "ah... AH... ACHOO" - a cone of wind down the aim
	---------------------------------------------------------------------
	function Effects.SeriousSneeze(char, data, isLocal)
		local root = charParts(char)
		if not root then
			return
		end
		local spec = ST.spec(char, "SeriousSneeze")
		local d = ST.flat(data.Dir, root)
		if isLocal then
			face(root, d)
		end
		local windup = spec.Windup or 0.75
		VFX.Motion(char, "SaitamaSneeze")
		VFX.Voice("SaitamaSneeze", root)
		VFX.PlaySound("SneezeInhale", root.Position, 1)
		VFX.SpeechBubble(char, "ah...", windup * 0.4)
		task.delay(windup * 0.45, function()
			if root.Parent then
				VFX.SpeechBubble(char, "AH...", windup * 0.5)
			end
		end)
		task.delay(windup, function()
			if not root.Parent then
				return
			end
			VFX.SpeechBubble(char, "ACHOO!!", 1.1)
			ST.sneeze(char, root, d, spec)
		end)
	end
	-- the blast: a cone of air (rings opening down it, a fan of streaks, a
	-- spray), the street's dust blown off ahead
	function ST.sneeze(char, root, d, spec)
		local range = spec.Range or 70
		local cone = math.rad(spec.Cone or 30)
		local head = char:FindFirstChild("Head")
		local from = (head and head.Position or root.Position + Vector3.new(0, 1.5, 0)) + d * 0.8
		VFX.PlaySound("SneezeBlast", from, 1)
		VFX.ShakeAt(from, 3, 160, 0.6)
		if ST.me() == char then
			VFX.Hooks.Flash(Color3.new(1, 1, 1), 0.1)
		end
		local low = ST.low()
		for i = 0, low and 3 or 6 do
			local k = i / (low and 3 or 6)
			local at = from + d * (range * k * 0.85) - Vector3.new(0, k * 2.5, 0)
			task.delay(k * range / 300, function()
				ST.ring(at, d, 1 + k * 4, 4 + range * math.tan(cone) * 2 * k, 0.3 + k * 0.15, AIR, 0.3 + k * 0.3)
			end)
		end
		for _, a in { -1, -0.5, 0, 0.5, 1 } do
			local dir = (CFrame.fromAxisAngle(Vector3.new(0, 1, 0), a * cone * 0.8) * d)
			streaks(from, dir, low and 3 or 6, 8, 12, range, AIR, 0.45)
		end
		-- the spray: specks out of the cone
		local spray = newPart(Vector3.one * 0.2, CFrame.lookAt(from, from + d), AIR, nil, nil)
		spray.Transparency = 1
		local pe = Instance.new("ParticleEmitter")
		pe.Texture = "rbxasset://textures/particles/smoke_main.dds"
		pe.Color = ColorSequence.new(Color3.new(1, 1, 1))
		pe.Transparency = NumberSequence.new({ NumberSequenceKeypoint.new(0, 0.35), NumberSequenceKeypoint.new(1, 1) })
		pe.Size = NumberSequence.new({ NumberSequenceKeypoint.new(0, 1.5), NumberSequenceKeypoint.new(1, 9) })
		pe.Speed = NumberRange.new(range * 1.6, range * 2.6)
		pe.Lifetime = NumberRange.new(0.25, 0.45)
		pe.SpreadAngle = Vector2.new(spec.Cone or 30, (spec.Cone or 30) * 0.5)
		pe.EmissionDirection = Enum.NormalId.Front
		pe.Rate = 0
		pe.Parent = spray
		pe:Emit(low and 14 or 34)
		cleanup(spray, 0.8)
		local steps = low and 3 or 5
		for i = 1, steps do
			task.delay(i * 0.06, function()
				local at = groundPoint(from + d * (range * i / steps))
				dustPuffs(at, 0.8 + i * 0.25, 3, DUST, 1, false)
			end)
		end
	end

	---------------------------------------------------------------------
	-- R: SERIOUS SIDE HOPS: a ring of afterimages round them; he's at their back
	---------------------------------------------------------------------
	-- whoever's nearest where he aimed (the same on every screen, near
	-- enough: the aim point and the bodies where this screen has them)
	function ST.hopTarget(char, root, d, aimPos, spec)
		local best, bestScore
		local range = spec.Range or 40
		local cosCone = math.cos(math.rad(spec.Cone or 55))
		local list = {}
		for _, plr in Players:GetPlayers() do
			if plr.Character and plr.Character ~= char then
				table.insert(list, plr.Character)
			end
		end
		for _, name in { "Dummies", "TwiceClones", "NomuRaid" } do
			local f = workspace:FindFirstChild(name)
			for _, m in f and f:GetChildren() or {} do
				if m ~= char then
					table.insert(list, m)
				end
			end
		end
		for _, model in list do
			local mr = model:FindFirstChild("HumanoidRootPart")
			local hum = model:FindFirstChildOfClass("Humanoid")
			if mr and hum and hum.Health > 0 then
				local v = mr.Position - root.Position
				local flat = Vector3.new(v.X, 0, v.Z)
				if flat.Magnitude > 2 and flat.Magnitude <= range and math.abs(v.Y) < 16 and flat.Unit:Dot(d) >= cosCone then
					local near = typeof(aimPos) == "Vector3" and (mr.Position - aimPos).Magnitude or flat.Magnitude
					local score = near + (1 - flat.Unit:Dot(d)) * 20
					if not bestScore or score < bestScore then
						best, bestScore = model, score
					end
				end
			end
		end
		return best
	end
	-- the hops: in toward them zigzagging, then round them (an arc, the side
	-- the seed picks) to their back - or, nobody there, a zigzag down the aim.
	-- Each node: where his root goes, facing them. Never into a wall.
	function ST.hopPath(origin, d, target, spec, seed)
		local n = math.max(spec.Hops or 8, 2)
		local nodes = {}
		local right = d:Cross(Vector3.new(0, 1, 0))
		local turn = ((tonumber(seed) or 0) % 2 == 0) and 1 or -1
		local tp = target and target:FindFirstChild("HumanoidRootPart")
		local y = origin.Y
		local function add(p, lookAt)
			local prev = #nodes > 0 and nodes[#nodes].Position or origin
			p = Vector3.new(p.X, y, p.Z)
			local hit = ST.ray(prev, p)
			if hit then
				local back = (p - prev).Magnitude > 0.1 and (p - prev).Unit or d
				p = hit.Position - back * 1.6
				p = Vector3.new(p.X, y, p.Z)
			end
			local look = Vector3.new(lookAt.X - p.X, 0, lookAt.Z - p.Z)
			look = look.Magnitude > 0.1 and look.Unit or d
			table.insert(nodes, ST.lookAlong(p, look))
		end
		if tp then
			local c = tp.Position
			local toT = Vector3.new(c.X - origin.X, 0, c.Z - origin.Z)
			local dist = toT.Magnitude
			local u = dist > 0.1 and toT.Unit or d
			local side = u:Cross(Vector3.new(0, 1, 0))
			local radius = math.clamp(dist * 0.6, 5, 9)
			local approach = math.max(math.floor(n * 0.4), 1)
			for i = 1, approach do
				local k = i / (approach + 1)
				local along = origin + u * math.max(dist - radius, 0) * k
				-- ((round 90 review) up or down to their level on the way: every
				-- node at his own height left him inside a ledge or a roof's
				-- edge they stood on - a body stuck in a part)
				y = origin.Y + (c.Y - origin.Y) * k
				add(along + side * (spec.Spread or 7) * ((i % 2 == 0) and 1 or -1) * (1 - k * 0.5), c)
			end
			y = c.Y
			local arc = n - approach
			local a0 = math.atan2(-u.Z, -u.X) -- (from them back toward where he stood)
			for i = 1, arc do
				local a = a0 + turn * math.pi * (i / arc)
				local r = i == arc and (spec.Behind or 4) + 1.5 or radius
				add(c + Vector3.new(math.cos(a), 0, math.sin(a)) * r, c)
			end
		else
			local dist = spec.Distance or 26
			for i = 1, n do
				local k = i / n
				add(origin + d * dist * k + right * (spec.Spread or 7) * ((i % 2 == 0) and 1 or -1) * (1 - k), origin + d * (dist + 20))
			end
		end
		return nodes
	end
	function Effects.SeriousSideHops(char, data, isLocal)
		local root = charParts(char)
		if not root then
			return
		end
		local spec = ST.spec(char, "SeriousSideHops")
		local d = ST.flat(data.Dir, root)
		local origin = root.Position
		local target = ST.hopTarget(char, root, d, data.Pos, spec)
		local nodes = ST.hopPath(origin, d, target, spec, data.Seed)
		local time = spec.Time or 0.5
		VFX.Motion(char, "SaitamaHops")
		VFX.PlaySound("HopStart", origin, 1)
		VFX.Voice("SaitamaSideHops", root)
		local t0 = os.clock()
		task.spawn(function()
			local low = ST.low()
			for i, node in nodes do
				local due = t0 + time * (i / #nodes)
				while os.clock() < due and root.Parent do
					task.wait()
				end
				if not root.Parent then
					return
				end
				if isLocal then
					-- his own machine puts him there (it owns his body)
					root.AssemblyLinearVelocity = Vector3.zero
					root.CFrame = node
				end
				-- an afterimage where he is: on his screen his body is there; on
				-- everyone else's, his last pose moved to the hop's spot
				if not low or i % 2 == 0 or i == #nodes then
					ST.ghost(char, (spec.Ghosts or 1.1) * (0.7 + 0.3 * i / #nodes), (not isLocal) and node or nil)
				end
				VFX.PlaySound("HopZip", node.Position, 1)
				dustPuffs(groundPoint(node.Position), 0.5, 2, DUST, 0.5, false)
			end
			local last = nodes[#nodes]
			if last then
				VFX.PlaySound("HopLand", last.Position, 1)
			end
		end)
	end

	---------------------------------------------------------------------
	-- 4: SERIOUS TABLE FLIP: the street in front, turned over like a table
	---------------------------------------------------------------------
	-- the slab: the street's own colour and stuff, a lane line on it, the
	-- rubble of its underside
	function ST.slab(cf, width, thick, length, street)
		local model = Instance.new("Model")
		model.Name = "SaitamaSlab"
		local color = street and street.Color or Color3.fromRGB(98, 98, 104)
		local material = street and street.Material or Enum.Material.Asphalt
		local top = newPart(Vector3.new(width, thick * 0.35, length), cf * CFrame.new(0, thick * 0.325, 0), color, material, nil, model)
		top.Name = "Top"
		local bed = newPart(Vector3.new(width * 0.98, thick * 0.65, length * 0.98), cf * CFrame.new(0, -thick * 0.175, 0), Color3.fromRGB(122, 104, 84), Enum.Material.Ground, nil, model)
		bed.Name = "Bed"
		for _, x in { -0.25, 0.25 } do
			local line = newPart(Vector3.new(0.5, 0.06, length * 0.86), cf * CFrame.new(width * x, thick * 0.5 + 0.03, 0), Color3.fromRGB(236, 232, 214), Enum.Material.SmoothPlastic, nil, model)
			line.Name = "Line"
		end
		-- rubble clinging to its underside
		for _ = 1, ST.low() and 4 or 10 do
			local s = rand(1.2, 3)
			local r = newPart(Vector3.new(s, s * 0.6, s), cf * CFrame.new(rand(-width * 0.4, width * 0.4), -thick * 0.5 - s * 0.2, rand(-length * 0.42, length * 0.42)) * CFrame.Angles(rand(-0.4, 0.4), rand(0, 3), rand(-0.4, 0.4)),
				Color3.fromRGB(110, 96, 80):Lerp(Color3.fromRGB(150, 140, 126), rng:NextNumber()), Enum.Material.Slate, nil, model)
			r.Name = "Rubble"
		end
		model.Parent = folder
		return model
	end
	function Effects.SeriousTableFlip(char, data, isLocal)
		local root = charParts(char)
		if not root then
			return
		end
		local spec = ST.spec(char, "SeriousTableFlip")
		local d = ST.flat(data.Dir, root)
		if isLocal then
			face(root, d)
		end
		local grip, flip = spec.Grip or 0.35, spec.Flip or 0.6
		local ahead, len, wid, thick = spec.Ahead or 3, spec.Length or 34, spec.Width or 26, spec.Thick or 3
		local hit = groundRay(root.Position, 40)
		local feet = hit and hit.Position or root.Position - Vector3.new(0, 3, 0)
		local street = hit and hit.Instance
		local look = ST.lookAlong(feet, d)
		local right = look.RightVector
		VFX.Motion(char, "SaitamaTableFlip")
		VFX.Voice("SaitamaTableFlip", root)
		VFX.PlaySound("FlipGrip", feet + d * (ahead + len / 2), 1)
		-- the slab's outline cracks open, dust seeping out of it
		local near = look * CFrame.new(0, 0, -ahead)
		local far = look * CFrame.new(0, 0, -(ahead + len))
		local cracks = {}
		for _, seg in {
			{ near * CFrame.new(-wid / 2, 0.05, 0), near * CFrame.new(wid / 2, 0.05, 0) },
			{ far * CFrame.new(-wid / 2, 0.05, 0), far * CFrame.new(wid / 2, 0.05, 0) },
			{ near * CFrame.new(-wid / 2, 0.05, 0), far * CFrame.new(-wid / 2, 0.05, 0) },
			{ near * CFrame.new(wid / 2, 0.05, 0), far * CFrame.new(wid / 2, 0.05, 0) },
		} do
			local a, b = seg[1].Position, seg[2].Position
			local c = newPart(Vector3.new(0.5, 0.12, 0.2), CFrame.lookAt(a, b) * CFrame.new(0, 0, -0.1), Color3.fromRGB(28, 24, 22), Enum.Material.SmoothPlastic)
			c.Name = "SlabCrack"
			tween(c, grip * 0.9, { Size = Vector3.new(0.5, 0.12, (b - a).Magnitude), CFrame = CFrame.lookAt(a, b) * CFrame.new(0, 0, -(b - a).Magnitude / 2) }, Enum.EasingStyle.Quad, Enum.EasingDirection.Out)
			table.insert(cracks, c)
		end
		task.delay(grip * 0.4, function()
			dustPuffs(near.Position, 0.9, 3, DUST, 0.7, false)
		end)
		task.delay(grip, function()
			for _, c in cracks do
				cleanup(c, 0.05)
			end
			if not root.Parent then
				return
			end
			VFX.PlaySound("FlipHeave", feet + d * (ahead + len / 2), 1)
			VFX.ShakeAt(feet, 2.5, 150, 0.5)
			-- the slab: turned over its far top edge (on the street), slow off
			-- the street then faster; it lands upside down on the street beyond
			local hinge = far
			local rest = look * CFrame.new(0, -thick / 2 + 0.02, -(ahead + len / 2))
			local offset = hinge:Inverse() * rest
			local slab = ST.slab(rest, wid, thick, len, street)
			-- the pit it left (until the server's own hole shows)
			local pit = newPart(Vector3.new(wid * 0.96, 0.3, len * 0.96), look * CFrame.new(0, -thick + 0.1, -(ahead + len / 2)), Color3.fromRGB(70, 58, 46), Enum.Material.Ground)
			pit.Name = "SlabPit"
			tween(pit, 1.2, { Transparency = 1 }, Enum.EasingStyle.Quad, Enum.EasingDirection.In, 5)
			cleanup(pit, 6.3)
			dustPuffs(near.Position, 1.6, 6, DUST, 1.1, false)
			rocks(near.Position, 1.4, ST.low() and 4 or 10)
			local parts = {}
			for _, p in slab:GetChildren() do
				table.insert(parts, { p = p, rel = rest:Inverse() * p.CFrame })
			end
			local t0 = os.clock()
			local done = false
			local conn
			conn = RunService.RenderStepped:Connect(function()
				local a = math.clamp((os.clock() - t0) / flip, 0, 1)
				-- (a heave: slow off the street, then over and down fast)
				local ang = math.pi * (a < 0.35 and (a / 0.35) ^ 1.5 * 0.35 or 0.35 + ((a - 0.35) / 0.65) ^ 1.8 * 0.65)
				local cf = hinge * CFrame.fromAxisAngle(Vector3.new(1, 0, 0), -ang) * offset
				for _, e in parts do
					if e.p.Parent then
						e.p.CFrame = cf * e.rel
					end
				end
				if a >= 1 and not done then
					done = true
					conn:Disconnect()
				end
			end)
			task.delay(flip + 0.02, function()
				if conn.Connected then
					conn:Disconnect()
				end
				-- slammed down upside down on the next stretch of street
				local landAt = (look * CFrame.new(0, 0, -(ahead + len * 1.5))).Position
				VFX.PlaySound("FlipSlam", landAt, 1)
				VFX.ShakeAt(landAt, 4, 220, 0.7)
				shockDisc(landAt + Vector3.new(0, 1, 0), Vector3.new(0, 1, 0), 6, math.max(wid, len) * 1.3, 0.45, DUST)
				for _, side in { -1, 1 } do
					dustPuffs(landAt + right * side * wid * 0.55, 1.8, 6, DUST, 1.2, false)
				end
				dustPuffs(landAt + d * len * 0.55, 2, 6, DUST, 1.2, false)
				rocks(landAt, 2, ST.low() and 6 or 14)
				-- a while later it breaks up and settles away
				task.delay(2.6, function()
					for _, e in parts do
						if e.p.Parent then
							tween(e.p, 0.9, { Transparency = 1, CFrame = e.p.CFrame - Vector3.new(0, thick * 0.8, 0) }, Enum.EasingStyle.Quad, Enum.EasingDirection.In)
						end
					end
					dustPuffs(landAt, 1.4, 5, DUST, 1, false)
					cleanup(slab, 1)
				end)
			end)
		end)
	end

	---------------------------------------------------------------------
	-- ULT 3: SERIOUS SERIES: SERIOUS PUNCH - the windup
	---------------------------------------------------------------------
	-- big words on this screen: his own (SERIOUS SERIES / SERIOUS PUNCH big
	-- in the middle, slammed in) or everyone else's (a banner up top, with
	-- whose it is)
	-- ((round 92) whoColor: the WHO line's colour - his suit's by default)
	function ST.title(text, mine, life, who, whoColor)
		-- ((round 100) Stark Street: the same big words as Inasa's - VFX.StreetTitle;
		-- the WHO line in paper, whoColor kept for the call's sake)
		return VFX.StreetTitle("SaitamaSerious", "SeriousTitle", text, mine, life, who)
	end

	-- his eyes going serious: the shadow over them deepens, a glint off each
	function ST.glint(char)
		local gear = char:FindFirstChild("QuirkGear")
		local cos = gear and gear:FindFirstChild("Cosmetics")
		local faceModel = cos and cos:FindFirstChild("SaitamaFace")
		for _, p in faceModel and faceModel:GetChildren() or {} do
			if p.Name == "FaceEye" and p:IsA("BasePart") then
				VFX.HitStar(p.CFrame.Position + p.CFrame.LookVector * 0.1, 1.5, Color3.new(1, 1, 1))
			elseif p.Name == "FaceShade" and p:IsA("BasePart") then
				tween(p, 0.25, { Transparency = 0.22 })
			end
		end
	end

	-- the cutscene, built from where he stands: each beat's shot (Beats), the
	-- punch, the crane up over the city as the wave goes, him after. The near
	-- shots' eyes are pulled in short of a wall between them and him.
	function ST.shots(root, d, spec)
		local B = spec.Beats or {}
		local windup = spec.Windup or 4.2
		local eyes, draw, fist, call = B.Eyes or 0.55, B.Draw or 1.4, B.Fist or 2.6, B.Call or 3.55
		local basis = CFrame.lookAt(root.Position, root.Position + d)
		local head = V(0, 1.5, 0)
		local function clear(eye)
			local we, wa = basis * eye, basis * head
			local hit = ST.ray(wa, we)
			if hit then
				local keep = math.max(hit.Distance - 1.2, 1.5)
				return basis:PointToObjectSpace(wa + (we - wa).Unit * keep)
			end
			return eye
		end
		local shots = {
			{ T = eyes, From = { V(5, 1.4, -8), V(0, 1, 0) }, To = { V(4, 1.2, -6.4), V(0, 1.3, 0) }, Fov = { 55, 48 } },
			{ T = draw - eyes, Cut = true, From = { V(0, 1.6, -2.4), V(0, 1.55, 0) }, To = { V(0, 1.58, -1.75), V(0, 1.55, 0) }, Fov = { 40, 30 } },
			{ T = fist - draw, Cut = true, From = { V(-14, -1.5, -10), V(0, 2.5, 0) }, To = { V(-21, -1, -15), V(0, 5, 0) }, Fov = { 64, 76 } },
			{ T = call - fist, Cut = true, From = { V(3.6, 1.3, -1.4), V(1, 0.4, 1.3) }, To = { V(2.9, 1.1, -0.9), V(1, 0.4, 1.3) }, Fov = { 50, 40 } },
			{ T = windup - call, Cut = true, From = { V(2.3, 3, 5.6), V(0, 2, -60) }, To = { V(1.9, 2.6, 4.3), V(0, 2, -60) }, Fov = { 60, 50 } },
			{ T = 0.35, Cut = true, Quiet = true, From = { V(0.7, 1.2, -5), V(0.4, 1, 0) }, To = { V(0.9, 1, -7.5), V(0.4, 1, 0) }, Fov = { 34, 62 } },
			{ T = 2.4, Cut = true, Quiet = true, From = { V(0, 50, 70), V(0, 0, -200) }, To = { V(0, 250, 300), V(0, 0, -560) }, Fov = { 70, 80 }, Style = Enum.EasingStyle.Quad },
			{ T = 0.9, Cut = true, From = { V(-3, 0.6, 9), V(0, 2, -40) }, To = { V(-2.5, 0.9, 7.5), V(0, 2.4, -40) }, Fov = { 55, 52 } },
		}
		for i, shot in shots do
			if i ~= 7 then
				shot.From = { clear(shot.From[1]), shot.From[2] }
				shot.To = { clear(shot.To[1]), shot.To[2] }
			end
		end
		return shots
	end

	-- (round 90 review) his body isn't on this screen (the place streams: a
	-- screen over ~1000 studs off is sent no body, so `char` is nil) - the
	-- city still gathers itself for it, from where the server says he
	-- stands. Without this, that screen read the whole city in the punch's
	-- own frame (a hitch at the worst moment) and had no windup sky.
	function ST.gatherFar(data)
		local origin = typeof(data.Origin) == "Vector3" and data.Origin or nil
		local dir = typeof(data.Dir) == "Vector3" and Vector3.new(data.Dir.X, 0, data.Dir.Z) or nil
		if not origin or origin ~= origin or not dir or dir ~= dir or dir.Magnitude < 0.05 then
			return nil
		end
		-- (ST.World: the wipe's table, set up further down)
		local world = ST.World
		-- ((round 92) a city read ahead for another kind of wipe is no punch's windup: this one takes over from it)
		if (ST.camPos() - origin).Magnitude > (W.Range or 2600) or (world.state and world.state.phase == "gather" and (world.state.kind or "punch") == "punch") then
			return nil
		end
		local st = world.gather({ origin = origin, d = dir.Unit, spec = ST.spec(nil, "SeriousPunch") })
		ST.far("SeriousWind", origin, 1)
		return st
	end

	function Effects.SeriousPunch(char, data, isLocal)
		local root = charParts(char)
		if not root then
			ST.gatherFar(data)
			return
		end
		local spec = ST.spec(char, "SeriousPunch")
		local d = ST.flat(data.Dir, root)
		local old = ST.runs[char]
		if old then
			ST.endRun(old, true)
		end
		local run = {
			char = char, root = root, d = d, spec = spec, mine = isLocal == true, t0 = os.clock(), origin = root.Position,
			did = {}, parts = {}, streaks = 0, near = (ST.camPos() - root.Position).Magnitude,
		}
		ST.runs[char] = run
		if isLocal then
			face(root, d)
			root.AssemblyLinearVelocity = Vector3.zero
			-- ((round 90 review) the bar's just SERIOUS SERIES: "SERIOUS PUNCH"
			-- under it from the first frame gave the call away 3.5 s early)
			VFX.Cinematic(char, ST.shots(root, d, spec), { Title = "SERIOUS SERIES", Color = Q.Ult and Q.Ult.Color, Own = true, Face = root.Position + d })
		end
		VFX.Motion(char, "SaitamaSeriousSet")
		ST.gust(char, 0.45, (spec.Windup or 4.2) + 0.5)
		VFX.PlaySound("SaitamaCape", root.Position, 1)
		-- the city gathers itself for it (the sky, the light, the wind): every
		-- screen near enough
		if run.near <= (W.Range or 2600) then
			ST.World.gather(run)
			ST.far("SeriousWind", root.Position, 1)
		end
		run.conn = RunService.RenderStepped:Connect(function(dt)
			local ok, err = pcall(ST.runStep, run, dt)
			if not ok then
				ST.endRun(run, true)
				warn("[VFX.ST] " .. tostring(err))
			end
		end)
	end

	-- a beat of the windup, once
	function ST.beat(run, name, at, fn)
		if not run.did[name] and os.clock() - run.t0 >= at then
			run.did[name] = true
			fn()
		end
	end
	function ST.runStep(run, dt)
		local char, root, spec = run.char, run.root, run.spec
		local B = spec.Beats or {}
		local windup = spec.Windup or 4.2
		local t = os.clock() - run.t0
		if not root.Parent or not char.Parent then
			ST.endRun(run, true)
			return
		end
		-- the server never threw it (refused, or he's gone): it ends here
		if t > windup + 1.6 and not run.went then
			ST.endRun(run, true)
			return
		end
		if t > windup + 4 then
			ST.endRun(run, false)
			return
		end
		-- (whose punch it is, for everyone else's titles: read once)
		if not run.whoName then
			local ok, nm = pcall(function()
				local who = Players:GetPlayerFromCharacter(char)
				return who and who.DisplayName
			end)
			run.whoName = string.upper(ok and type(nm) == "string" and nm ~= "" and nm or char.Name)
		end
		local whoName = run.whoName
		ST.beat(run, "eyes", B.Eyes or 0.55, function()
			VFX.Voice("SeriousSeries", root)
			ST.title("SERIOUS SERIES", run.mine, (B.Draw or 1.4) - (B.Eyes or 0.55) + 0.5, not run.mine and (whoName .. " IS GETTING SERIOUS") or nil)
			ST.glint(char)
			VFX.PlaySound("SeriousEyes", run.mine and nil or root.Position, run.mine and 0.9 or 1)
			ST.gust(char, 0.7, windup - (B.Eyes or 0.55) + 0.5)
		end)
		ST.beat(run, "draw", B.Draw or 1.4, function()
			VFX.Pose(char, "SaitamaSeriousDraw", windup - (B.Draw or 1.4))
			ST.far("SeriousCharge", root.Position, 1)
			ST.charge(run)
		end)
		ST.beat(run, "call", B.Call or 3.55, function()
			VFX.Voice("SeriousPunchCall", root)
			ST.title("SERIOUS PUNCH", run.mine, windup - (B.Call or 3.55) + 0.45, not run.mine and whoName or nil)
			ST.gust(char, 1, 3)
			if VFX.Hooks.DuckMusic and run.near <= (W.Range or 2600) then
				VFX.Hooks.DuckMusic(spec.MusicDuck or 0.12, 0.35, windup - (B.Call or 3.55) + 2.4, 3)
			end
		end)
		ST.beat(run, "swing", windup - 0.06, function()
			VFX.Motion(char, "SaitamaSeriousPunch")
		end)
		-- his own screen: the impact lands with his fist (everyone else's with the server's word)
		if run.mine then
			ST.beat(run, "impact", windup, function()
				ST.impact(run)
			end)
		end
		if t < windup then
			-- every screen shakes harder and harder (less the further off)
			local k = math.clamp(t / windup, 0, 1)
			local S = W.Shake or { 0.4, 2.8 }
			local fall = math.clamp(1.2 - run.near / 1600, 0.35, 1)
			VFX.Shake((S[1] + (S[2] - S[1]) * k ^ 1.6) * fall, 0.15)
			-- the air pulled into his fist from all round, the street's dust with it
			if run.near < 400 then
				ST.pull(run, t, k)
			end
		end
		-- his rocks tremble as they rise; the air round the fist pulses
		for _, r in run.rocks or {} do
			if r.part.Parent and not r.gone then
				local wob = (t - (B.Draw or 1.4)) * 1.2
				r.part.CFrame = r.base * CFrame.new(rand(-0.06, 0.06), math.min(wob, 1) * r.rise, rand(-0.06, 0.06)) * CFrame.Angles(rand(-0.03, 0.03), t * r.spin, 0)
			end
		end
		if run.lens and run.lens.Parent then
			local s = 1.6 + math.sin(t * 22) * 0.35 + math.max(t - (B.Fist or 2.6), 0) * 0.8
			run.lens.Size = Vector3.one * s
			run.lens.CFrame = CFrame.new(handPos(char, true))
		end
	end

	-- the air drawn into his fist (streaks converging), the street's dust
	-- dragged in to his feet
	function ST.pull(run, t, k)
		local low = ST.low()
		run.streaks += (low and 0.5 or 2) * (0.5 + k)
		local fist = handPos(run.char, true)
		while run.streaks >= 1 do
			run.streaks -= 1
			local dir = Vector3.new(rand(-1, 1), rand(-0.4, 0.9), rand(-1, 1))
			if dir.Magnitude < 0.1 then
				dir = Vector3.new(0, 1, 0)
			end
			dir = (dir.Unit + run.d * 0.6).Unit
			local from = fist + dir * rand(18, 40)
			local s = newPart(Vector3.new(0.12, 0.12, rand(4, 8)), CFrame.lookAt(from, fist), AIR, Enum.Material.Neon)
			s.Transparency = 0.5
			tween(s, 0.32, { CFrame = CFrame.lookAt(fist, fist + (fist - from).Unit), Size = Vector3.new(0.05, 0.05, 1), Transparency = 1 }, Enum.EasingStyle.Quad, Enum.EasingDirection.In)
			cleanup(s, 0.35)
		end
		if rng:NextNumber() < (low and 0.08 or 0.22) then
			local a = rand(0, math.pi * 2)
			local far = run.origin + Vector3.new(math.cos(a), 0, math.sin(a)) * rand(18, 46)
			local g = groundPoint(far)
			local feet = groundPoint(run.origin)
			local puff = newPart(Vector3.one * rand(2.5, 4.5), CFrame.new(g + Vector3.new(0, 1, 0)), DUST, Enum.Material.SmoothPlastic, Enum.PartType.Ball)
			puff.Transparency = 0.45
			tween(puff, 0.6, { CFrame = CFrame.new(feet + Vector3.new(0, 0.6, 0)), Size = Vector3.one * 0.6, Transparency = 1 }, Enum.EasingStyle.Quad, Enum.EasingDirection.In)
			cleanup(puff, 0.62)
		end
	end

	-- the fist drawn back: the street cracking under him, stones lifting off
	-- it round him, the air round the fist bending
	function ST.charge(run)
		local feet = groundPoint(run.origin)
		local low = ST.low()
		for i = 1, low and 5 or 9 do
			local a = i / (low and 5 or 9) * math.pi * 2 + rand(-0.2, 0.2)
			local dir = Vector3.new(math.cos(a), 0, math.sin(a))
			local len = rand(7, 15)
			local c = newPart(Vector3.new(rand(0.25, 0.5), 0.1, 0.2), CFrame.lookAt(feet + Vector3.new(0, 0.05, 0), feet + dir + Vector3.new(0, 0.05, 0)), Color3.fromRGB(30, 26, 24), Enum.Material.SmoothPlastic)
			c.Name = "SeriousCrack"
			tween(c, 0.9, { Size = Vector3.new(c.Size.X, 0.1, len), CFrame = CFrame.lookAt(feet + Vector3.new(0, 0.05, 0), feet + dir + Vector3.new(0, 0.05, 0)) * CFrame.new(0, 0, -len / 2) }, Enum.EasingStyle.Quad, Enum.EasingDirection.Out)
			table.insert(run.parts, c)
		end
		run.rocks = {}
		for _ = 1, low and 5 or 12 do
			local a = rand(0, math.pi * 2)
			local at = feet + Vector3.new(math.cos(a), 0, math.sin(a)) * rand(3.5, 12)
			local s = rand(0.5, 1.6)
			local rock = newPart(Vector3.new(s, s * 0.7, s), CFrame.new(at + Vector3.new(0, s * 0.3, 0)) * CFrame.Angles(rand(0, 3), rand(0, 3), rand(0, 3)), Color3.fromRGB(122, 116, 110):Lerp(Color3.fromRGB(160, 150, 138), rng:NextNumber()), Enum.Material.Slate)
			rock.Name = "SeriousRock"
			table.insert(run.rocks, { part = rock, base = rock.CFrame, rise = rand(1.5, 5), spin = rand(-0.6, 0.6) })
			table.insert(run.parts, rock)
		end
		dustPuffs(feet, 1.1, low and 3 or 6, DUST, 0.9, false)
		if run.near < 200 then
			local lens = newPart(Vector3.one * 1.6, CFrame.new(handPos(run.char, true)), Color3.fromRGB(230, 240, 255), Enum.Material.Glass, Enum.PartType.Ball)
			lens.Name = "SeriousLens"
			lens.Transparency = 0.65
			run.lens = lens
			table.insert(run.parts, lens)
		end
	end

	-- THE PUNCH, here: the frame of black and white, the white-out, the crack
	-- of the fist; his body after it; the stones and cracks blown away
	function ST.impact(run)
		if not run or run.hit then
			return
		end
		run.hit = true
		local char, root, d = run.char, run.root, run.d
		local fist = (root.Parent and root.Position or run.origin) + d * 2.5 + Vector3.new(0, 0.6, 0)
		local near = (ST.camPos() - fist).Magnitude
		if run.mine or near < 900 then
			VFX.ImpactFrame(0.16)
		end
		VFX.Hooks.Flash(Color3.new(1, 1, 1), (W.Flash or 0.35) * math.clamp(1.3 - near / 2000, 0.4, 1))
		ST.far("SeriousPunch", fist, 1.15)
		ST.gust(char, 1, 3)
		billboardRing(fist, 4, 80, AIR, 14, 0.5)
		shockDisc(fist, d, 4, 70, 0.4, AIR, 30)
		local feet = groundPoint(run.origin)
		shockDisc(feet + Vector3.new(0, 0.5, 0), Vector3.new(0, 1, 0), 8, 120, 0.6, DUST)
		dustPuffs(feet, 3, ST.low() and 6 or 14, DUST, 1.6, false)
		rocks(feet, 3, ST.low() and 6 or 16)
		for _, r in run.rocks or {} do
			if r.part.Parent then
				r.gone = true
				local out = (r.part.CFrame.Position - feet)
				out = Vector3.new(out.X, 0, out.Z)
				out = out.Magnitude > 0.1 and out.Unit or d
				tween(r.part, 0.7, { CFrame = r.part.CFrame + (out * 0.4 + d).Unit * rand(120, 260) + Vector3.new(0, rand(20, 60), 0), Transparency = 1 }, Enum.EasingStyle.Quad, Enum.EasingDirection.Out)
			end
		end
		for _, p in run.parts do
			if p.Name == "SeriousCrack" then
				tween(p, 0.4, { Transparency = 1 }, Enum.EasingStyle.Quad, Enum.EasingDirection.In, 2)
			elseif p.Name == "SeriousLens" then
				p:Destroy()
			end
		end
		run.lens = nil
		task.delay(0.5, function()
			if root.Parent and ST.runs[char] == run then
				VFX.Pose(char, "SaitamaSeriousAfter", 2.4)
			end
		end)
	end

	-- the server: thrown. The punch on this screen (if it hasn't already),
	-- and the city
	function Effects.SeriousPunchGo(char, data)
		local origin = typeof(data.Origin) == "Vector3" and data.Origin or nil
		local dir = typeof(data.Dir) == "Vector3" and Vector3.new(data.Dir.X, 0, data.Dir.Z) or nil
		if not origin or not dir or dir.Magnitude < 0.05 or origin ~= origin then
			return
		end
		local d = dir.Unit
		local spec = typeof(char) == "Instance" and ST.spec(char, "SeriousPunch") or {}
		if not spec.Front then
			spec = (Q.Ult and Q.Ult.Abilities and Q.Ult.Abilities[3]) or spec
		end
		local run = typeof(char) == "Instance" and ST.runs[char] or nil
		if not run then
			-- (a screen that never saw the windup: the punch alone)
			run = { char = char, root = char and char:FindFirstChild("HumanoidRootPart") or nil, d = d, spec = spec, mine = false, t0 = os.clock() - (spec.Windup or 4.2),
				origin = origin, did = { eyes = true, draw = true, call = true, swing = true }, parts = {}, streaks = 0, near = (ST.camPos() - origin).Magnitude }
			if run.root then
				ST.runs[char] = run
				run.conn = RunService.RenderStepped:Connect(function(dt)
					local ok = pcall(ST.runStep, run, dt)
					if not ok then
						ST.endRun(run, true)
					end
				end)
			end
		end
		run.went = true
		run.origin = origin
		run.d = d
		if run.root then
			ST.impact(run)
		end
		if (ST.camPos() - origin).Magnitude <= (W.Range or 2600) then
			ST.World.go(origin, d, tonumber(data.At) or workspace:GetServerTimeNow(), spec, char)
		end
		-- (and after: "...oops.")
		task.delay(3.4, function()
			local root = char and char.Parent and char:FindFirstChild("HumanoidRootPart")
			local hum = char and char:FindFirstChildOfClass("Humanoid")
			if root and hum and hum.Health > 0 then
				VFX.SpeechBubble(char, "...oops.", 2)
				VFX.Voice("SaitamaOops", root)
			end
		end)
	end

	-- the server: he never threw it (knocked out, gone): the windup's undone
	function Effects.SeriousPunchCancel(char)
		local run = typeof(char) == "Instance" and ST.runs[char] or nil
		if run then
			ST.endRun(run, true)
		elseif typeof(char) ~= "Instance" and next(ST.runs) == nil then
			-- ((round 90 review) a body this screen never had: the sky it
			-- gathered for him (ST.gatherFar) given back now too)
			ST.World.cancel()
		end
	end

	function ST.endRun(run, cancelled)
		if run.ended then
			return
		end
		run.ended = true
		if run.conn then
			run.conn:Disconnect()
		end
		if ST.runs[run.char] == run then
			ST.runs[run.char] = nil
		end
		for _, p in run.parts do
			if p.Parent then
				tween(p, 0.3, { Transparency = 1 })
				cleanup(p, 0.32)
			end
		end
		if cancelled then
			if run.mine and VFX.InOwnCinematic() and not run.went then
				VFX.CancelCinematic()
			end
			if not run.went then
				ST.World.cancel()
				if run.char and run.char.Parent then
					VFX.ReleasePose(run.char, 0.3)
				end
			end
		end
	end

	---------------------------------------------------------------------
	-- THE WIPE: this screen's copy of the whole city, blown away and put back
	---------------------------------------------------------------------
	-- WS.state (one at a time): the parts of the city by when the wave gets
	-- to them (buckets of 0.02 s), the copies flying, the sky, the light.
	-- Phases: gather (the windup: read the city, the clouds roll in) -> wave
	-- (each part hidden as the wave reaches it, its copies thrown) -> hold
	-- (the city's gone) -> rewind (every copy flies home, each part shown as
	-- its copy gets there) -> done (everything as it was).
	-- (round 92) The engine's shared: a wipe is the punch's (a wave down his
	-- line, Config.SeriousWave, Config.Saitama.Wipe's numbers) unless its
	-- opts say otherwise - Kind (whose: "punch" by default), Law (when the
	-- wave reaches a point), W (its own numbers: Wipe's under them), Windup
	-- (s a city read ahead is kept). ((round 99, craters) round 92's other
	-- wipe - LIGHTWIPE, a blast from a point - is gone, and its Radial with
	-- it: the punch's is the only one now)
	local WS = {}
	WS.held = {} -- (round 92) [part] = { n = wipes hiding it, its own LocalTransparencyModifier / CanCollide / CanQuery }
	ST.World = WS
	local BUCKET = 0.02

	-- when this wipe's wave gets to pos (its own law; the punch's by default)
	function WS.arrive(st, pos)
		return (st.law or Config.SeriousWave)(st.spec, st.origin, st.d, pos)
	end

	function WS.top(cf, size)
		return cf.Position.Y + (math.abs(cf.RightVector.Y) * size.X + math.abs(cf.UpVector.Y) * size.Y + math.abs(cf.LookVector.Y) * size.Z) / 2
	end
	-- the street under him (the map's roads and ground only - not a roof)
	function WS.street(origin, map)
		local params = RaycastParams.new()
		local list = {}
		for _, name in { "Roads", "Ground" } do
			local f = map and map:FindFirstChild(name)
			if f then
				table.insert(list, f)
			end
		end
		if #list > 0 then
			params.FilterType = Enum.RaycastFilterType.Include
			params.FilterDescendantsInstances = list
			local hit = workspace:Raycast(origin + Vector3.new(0, 5, 0), Vector3.new(0, -600, 0), params)
			if hit then
				return hit.Position.Y, true -- ((round 92 review) true: the street was found there, not guessed)
			end
			return W.Street or (origin.Y - 3)
		end
		return origin.Y - 3
	end

	function WS.new(origin, d, spec, char, opts)
		opts = opts or {}
		local W = opts.W or W
		local f = Instance.new("Folder")
		f.Name = "SaitamaWipe"
		f.Parent = folder
		local map = workspace:FindFirstChild("Map")
		local st = {
			origin = origin, d = d, spec = spec, char = char, map = map, folder = f, low = ST.low(),
			entries = 0, buckets = {}, maxBucket = 0, groups = {}, bi = 1, bk = 1,
			hidden = {}, late = {}, pieces = {}, pieceCount = 0, wall = {}, column = {}, rings = 0, vortex = {}, scour = {},
			flyList = {}, flown = {}, rubble = {}, rubbleCount = 0,
			conns = {}, phase = "gather", t0 = os.clock(), windup = opts.Windup or spec.Windup or 4.2, folders = {},
			-- (round 92) whose it is and how it goes (the punch's unless told);
			-- every map part read (known), and what turned up meanwhile (adds)
			kind = opts.Kind or "punch", W = W, law = opts.Law or Config.SeriousWave,
			known = {}, adds = {},
		}
		st.street = WS.street(origin, map)
		st.maxPieces = st.low and (W.LowMax or 520) or (W.Max or 1700)
		for _, name in W.Folders or {} do
			local fo = map and map:FindFirstChild(name)
			if fo then
				st.folders[fo] = name
			end
		end
		WS.state = st
		st.conns.frame = RunService.RenderStepped:Connect(function(dt)
			if st.finished then
				return
			end
			local ok, err = pcall(WS.step, st, dt)
			if not ok then
				warn("[VFX.ST] the wipe: " .. tostring(err))
				WS.finish(st)
			end
		end)
		if map then
			st.conns.added = map.DescendantAdded:Connect(function(inst)
				if not st.finished and inst:IsA("BasePart") then
					WS.arrived(st, inst)
				end
			end)
		end
		return st
	end

	-- which wiped folder a map part's in (nil: the street, the border - kept)
	function WS.folderOf(st, inst)
		local p = inst.Parent
		while p and p ~= st.map do
			if st.folders[p] then
				return st.folders[p]
			end
			p = p.Parent
		end
		return nil
	end

	-- a part's box in the world (min, max)
	function WS.box(cf, size)
		local h = size / 2
		local r, u, l = cf.RightVector, cf.UpVector, cf.LookVector
		local ext = Vector3.new(
			math.abs(r.X) * h.X + math.abs(u.X) * h.Y + math.abs(l.X) * h.Z,
			math.abs(r.Y) * h.X + math.abs(u.Y) * h.Y + math.abs(l.Y) * h.Z,
			math.abs(r.Z) * h.X + math.abs(u.Z) * h.Y + math.abs(l.Z) * h.Z
		)
		return cf.Position - ext, cf.Position + ext
	end
	function WS.vmin(a, b)
		return Vector3.new(math.min(a.X, b.X), math.min(a.Y, b.Y), math.min(a.Z, b.Z))
	end
	function WS.vmax(a, b)
		return Vector3.new(math.max(a.X, b.X), math.max(a.Y, b.Y), math.max(a.Z, b.Z))
	end
	function WS.bucket(st, e)
		local b = math.floor(e.arr / BUCKET) + 1
		local list = st.buckets[b]
		if not list then
			list = {}
			st.buckets[b] = list
		end
		table.insert(list, e)
		st.maxBucket = math.max(st.maxBucket, b)
	end

	-- an entry: a part of the city (above the foundations) and when the wave
	-- gets to it; `fly`: it flies too, as a copy of itself (a prop's biggest)
	function WS.add(st, p, gi, fly, vol)
		local W = st.W or W
		if st.known then
			st.known[p] = true
		end
		local cf, size = p.CFrame, p.Size
		if WS.top(cf, size) <= st.street + (W.Foundation or 3) then
			return nil
		end
		local e = { p = p, pos = cf.Position, gi = gi, fly = fly, vol = vol or 0 }
		e.arr = (WS.arrive(st, e.pos))
		WS.bucket(st, e)
		st.entries += 1
		if fly then
			table.insert(st.flyList, e)
		end
		return e
	end
	-- a chunk of a building: one cell of a grid laid over it, hugging what's
	-- in that cell, the colour most of it is (its walls count most) - the
	-- building comes apart in blocks you can read from across the city
	function WS.addChunk(st, gi, pos, size, color, material, vol, ground)
		local e = { chunk = true, pos = pos, size = size, color = color, material = material, gi = gi, fly = true, vol = vol, ground = ground }
		e.arr = (WS.arrive(st, pos))
		WS.bucket(st, e)
		table.insert(st.flyList, e)
		return e
	end
	function WS.chunkUp(st, gi, g, parts, tick)
		local W = st.W or W
		local floorY = st.street + (W.Foundation or 3)
		local lo0 = Vector3.new(g.min.X, math.max(g.min.Y, floorY), g.min.Z)
		local size = g.max - lo0
		if size.Y <= 0 then
			return
		end
		local target = st.low and (W.LowChunks or 14) or (W.Chunks or 36)
		local cell = math.clamp((math.max(size.X * size.Y * size.Z, 1) / target) ^ (1 / 3), W.ChunkMin or 10, W.ChunkMax or 40)
		local nx, ny, nz = math.max(math.ceil(size.X / cell), 1), math.max(math.ceil(size.Y / cell), 1), math.max(math.ceil(size.Z / cell), 1)
		local cells = {}
		for _, p in parts do
			local lo, hi = WS.box(p.CFrame, p.Size)
			if hi.Y > floorY and p.Transparency < 0.6 then
				local c = (lo + hi) / 2
				local ix = math.clamp(math.floor((c.X - lo0.X) / cell), 0, nx - 1)
				local iy = math.clamp(math.floor((c.Y - lo0.Y) / cell), 0, ny - 1)
				local iz = math.clamp(math.floor((c.Z - lo0.Z) / cell), 0, nz - 1)
				local key = ix + iy * nx + iz * nx * ny
				local cel = cells[key]
				if not cel then
					local cmin = lo0 + Vector3.new(ix, iy, iz) * cell
					cel = { cmin = cmin, cmax = cmin + Vector3.new(cell, cell, cell), vol = 0, votes = {}, iy = iy }
					cells[key] = cel
				end
				local s = p.Size
				local vol = s.X * s.Y * s.Z
				cel.vol += vol
				if p.Transparency < 0.3 then
					local col = p.Color
					local ck = math.floor(col.R * 255 + 0.5) * 65536 + math.floor(col.G * 255 + 0.5) * 256 + math.floor(col.B * 255 + 0.5)
					local v = cel.votes[ck]
					if not v then
						v = { w = 0, color = col, material = p.Material }
						cel.votes[ck] = v
					end
					v.w += vol * ((p.Parent and p.Parent.Name == "Color") and 4 or 1)
				end
				local a, b = WS.vmax(lo, cel.cmin), WS.vmin(hi, cel.cmax)
				cel.lo = cel.lo and WS.vmin(cel.lo, a) or a
				cel.hi = cel.hi and WS.vmax(cel.hi, b) or b
			end
			tick()
		end
		for _, cel in cells do
			local best
			for _, v in cel.votes do
				if not best or v.w > best.w then
					best = v
				end
			end
			if best and cel.vol >= (W.ChunkVolume or 40) then
				local s = cel.hi - cel.lo
				-- (a block, not a sheet: no side under a third of the longest)
				local big = math.max(s.X, s.Y, s.Z)
				s = Vector3.new(math.max(s.X, big * 0.34, 2), math.max(s.Y, big * 0.34, 2), math.max(s.Z, big * 0.34, 2))
				WS.addChunk(st, gi, (cel.lo + cel.hi) / 2, s, best.color, best.material, cel.vol, cel.iy == 0)
			end
		end
	end
	-- how many copies a part breaks into
	function WS.splits(size)
		local n, len = 1, math.max(size.X, size.Y, size.Z)
		for _ = 1, W.SplitMax or 2 do
			if len > (W.Split or 34) then
				n *= 2
				len /= 2
			end
		end
		return n
	end

	-- READ THE CITY (a little a frame, through the windup): each group (a
	-- building, a tree, a lamp...) and its parts. A building flies as chunks
	-- of itself; a prop as copies of its biggest parts; the biggest of all
	-- first, at most Max copies in all.
	function WS.scan(st)
		local W = st.W or W
		local done = 0
		local function tick()
			done += 1
			if done >= (W.ScanBudget or 900) then
				done = 0
				coroutine.yield()
			end
		end
		local props = st.low and (W.LowProps or {}) or (W.Props or {})
		local floorY = st.street + (W.Foundation or 3)
		for _, name in W.Folders or {} do
			local fo = st.map and st.map:FindFirstChild(name)
			for _, model in fo and fo:GetChildren() or {} do
				local g = { folder = name, model = model }
				table.insert(st.groups, g)
				local gi = #st.groups
				local parts = {}
				for _, p in model:IsA("BasePart") and { model } or model:GetDescendants() do
					if p:IsA("BasePart") then
						table.insert(parts, p)
						local lo, hi = WS.box(p.CFrame, p.Size)
						if hi.Y > floorY then
							g.min = g.min and WS.vmin(g.min, lo) or lo
							g.max = g.max and WS.vmax(g.max, hi) or hi
						end
						tick()
					end
				end
				if g.min then
					g.center = (g.min + g.max) / 2
					if name == "Buildings" then
						WS.chunkUp(st, gi, g, parts, tick)
					end
				end
				local n = name ~= "Buildings" and (props[name] or 0) or 0
				local fly = {}
				if n > 0 then
					local cands = {}
					for _, p in parts do
						local s = p.Size
						local vol = s.X * s.Y * s.Z
						if vol >= (W.MinVolume or 6) and p.Transparency < 0.9 then
							table.insert(cands, { p = p, vol = vol })
						end
					end
					table.sort(cands, function(a, b)
						return a.vol > b.vol
					end)
					for i = 1, math.min(n, #cands) do
						fly[cands[i].p] = cands[i].vol
					end
				end
				for _, p in parts do
					WS.add(st, p, gi, fly[p] ~= nil, fly[p])
					tick()
				end
			end
		end
		-- the budget: the biggest things fly, at most Max copies in all
		table.sort(st.flyList, function(a, b)
			return a.vol > b.vol
		end)
		local budget = st.maxPieces
		for _, e in st.flyList do
			local n = e.chunk and 1 or WS.splits(e.p.Size)
			if budget >= n then
				budget -= n
			else
				e.fly = false
			end
		end
		st.scanned = true
	end
	function WS.startScan(st)
		st.scanCo = coroutine.create(WS.scan)
		WS.resumeScan(st)
	end
	function WS.resumeScan(st)
		if st.scanCo and coroutine.status(st.scanCo) ~= "dead" then
			local ok, err = coroutine.resume(st.scanCo, st)
			if not ok then
				st.scanCo = nil
				st.scanned = true
				warn("[VFX.ST] reading the city: " .. tostring(err))
			end
		end
	end
	function WS.finishScan(st)
		local guard = 0
		while not st.scanned and st.scanCo and guard < 10000 do
			guard += 1
			WS.resumeScan(st)
		end
		st.scanned = true
	end
	-- the punch wasn't where the windup was (planned again from the server's)
	function WS.replan(st, origin, d)
		st.origin, st.d = origin, d
		local all = {}
		for _, list in st.buckets do
			for _, e in list do
				table.insert(all, e)
			end
		end
		st.buckets, st.maxBucket = {}, 0
		for _, e in all do
			e.arr = (WS.arrive(st, e.pos))
			local b = math.floor(e.arr / BUCKET) + 1
			st.buckets[b] = st.buckets[b] or {}
			table.insert(st.buckets[b], e)
			st.maxBucket = math.max(st.maxBucket, b)
		end
	end

	-- a part that turns up while it's going on (streamed in, rebuilt by the
	-- server): gone too if the wave's been past it
	function WS.arrived(st, p)
		if st.phase == "done" then
			return
		end
		if st.phase == "gather" then
			-- (round 92) one that turns up while the city's being read ahead
			-- (a wall the flight smashed through comes back as its pieces; a
			-- block streams in): read too, at the go (WS.settle). It used to be
			-- missed, and stood on in the empty city
			if st.adds then
				table.insert(st.adds, p)
			end
			return
		end
		local W = st.W or W
		local name = WS.folderOf(st, p)
		if not name or WS.top(p.CFrame, p.Size) <= st.street + (W.Foundation or 3) then
			return
		end
		local e = { p = p, pos = p.CFrame.Position, gi = 0, fly = false }
		e.arr = (WS.arrive(st, e.pos))
		local elapsed = WS.elapsed(st)
		if st.phase == "rewind" then
			-- ((round 90 review) the city's coming back: gone only till its
			-- own spot comes back - it used to stay hidden to the very end)
			e.restoreAt = st.holdEnd + (st.maxBucket * BUCKET - e.arr) * (st.rewindK or 1) + (W.RewindTime or 1.5)
			if e.restoreAt > elapsed then
				WS.hide(st, e, true)
			end
		elseif e.arr <= elapsed then
			WS.hide(st, e, true)
		else
			local b = math.floor(e.arr / BUCKET) + 1
			st.buckets[b] = st.buckets[b] or {}
			table.insert(st.buckets[b], e)
			st.maxBucket = math.max(st.maxBucket, b)
		end
	end

	-- (round 92) what turned up while it was being read, read now (WS.go,
	-- once the read's done and planned from where it's thrown)
	function WS.settle(st)
		local adds = st.adds or {}
		st.adds = {}
		for _, p in adds do
			if p.Parent and p:IsA("BasePart") and not (st.known and st.known[p]) and WS.folderOf(st, p) then
				WS.add(st, p, 0, false)
			end
		end
	end

	function WS.elapsed(st)
		return st.at and (workspace:GetServerTimeNow() - st.at) or -1
	end

	-- hidden here (not changed): see-through, not stood on, not seen by
	-- this screen's rays; its lights off. Its copies take off. (A chunk has
	-- no part of its own: it only flies.)
	function WS.hide(st, e, late)
		if e.chunk then
			if e.fly and not e.flown then
				e.flown = true
				table.insert(st.flown, e)
				WS.pieces(st, e)
			end
			return
		end
		local p = e.p
		if e.hidden or not p.Parent then
			return
		end
		e.hidden = true
		-- (round 92, integration: seen live - a LIGHTSPEED wipe left ~500 parts
		-- hidden for good) a part hidden twice (two wipes overlapping, or read
		-- twice) took "hidden" as its own look the second time, and whichever
		-- let go last put it back hidden. Now every wipe shares one record per
		-- part: its own look kept from the first hide, given back by the last
		local held = WS.held[p]
		if held then
			held.n += 1
		else
			WS.held[p] = { n = 1, ltm = p.LocalTransparencyModifier, cc = p.CanCollide, cq = p.CanQuery }
		end
		if e.fly and st.pieceCount < st.maxPieces then
			WS.pieces(st, e)
		end
		p.LocalTransparencyModifier = 1
		p.CanCollide = false
		p.CanQuery = false
		for _, l in p:GetChildren() do
			if l:IsA("Light") and l.Enabled then
				l.Enabled = false
				e.lights = e.lights or {}
				table.insert(e.lights, l)
			end
		end
		table.insert(late and st.late or st.hidden, e)
	end
	function WS.unhide(e)
		if not e.hidden then
			return
		end
		e.hidden = false
		local p = e.p
		local held = WS.held[p]
		if held then
			held.n -= 1
			if held.n > 0 then
				-- (another wipe still has it hidden: the last to let go gives it
				-- back - its lights too)
				for _, l in e.lights or {} do
					held.lights = held.lights or {}
					table.insert(held.lights, l)
				end
				e.lights = nil
				return
			end
			WS.held[p] = nil
			for _, l in held.lights or {} do
				e.lights = e.lights or {}
				table.insert(e.lights, l)
			end
		end
		-- ((round 94) given back whether it's in the world right now or not.
		-- The owner: "the map does not look right cosmetically speaking, it
		-- looks like it is missing parts of it." The place streams
		-- (Workspace.StreamingEnabled, opportunistic stream-out past 1024
		-- studs - the city is ~1250 across): a part streamed out is only
		-- parented to nil, and streams back in later as the same part, as it
		-- was left. One hidden by the wave that had streamed out by the
		-- rewind was skipped here and came back invisible for good - holes
		-- all over the city after every wipe)
		if held then
			pcall(function()
				p.LocalTransparencyModifier = held.ltm or 0
				p.CanCollide = held.cc ~= false
				p.CanQuery = held.cq ~= false
			end)
		end
		for _, l in e.lights or {} do
			pcall(function()
				l.Enabled = true
			end)
		end
	end
	-- (round 90 review) what's hidden, a slice a frame (CheckBudget, the
	-- whole city in about half a second): anything else on this screen that
	-- changed one of them meanwhile is undone - and what it set is what the
	-- part goes back to. The dev flight and the smash open walls here
	-- (CanCollide off; the smash's see-through too) and close them a moment
	-- later: a wall open as the wave got there used to come back open for
	-- good (see-through, walked through), and one they closed mid-wipe was
	-- an invisible wall in the empty city. (It was a pass over all ~15,000
	-- parts once a second, in one frame.)
	function WS.recheck(st)
		local W = st.W or W
		local nh = #st.hidden
		local total = nh + #st.late
		if total == 0 then
			return
		end
		local budget = math.min(st.low and (W.LowCheckBudget or 200) or (W.CheckBudget or 500), total)
		local i = st.ci or 0
		for _ = 1, budget do
			i = i % total + 1
			local e = i <= nh and st.hidden[i] or st.late[i - nh]
			local p = e and e.p
			if p and e.hidden and p.Parent then
				local held = WS.held[p]
				local ltm = p.LocalTransparencyModifier
				if ltm < 1 then
					if held then
						held.ltm = ltm
					end
					p.LocalTransparencyModifier = 1
				end
				if p.CanCollide then
					if held then
						held.cc = true
					end
					p.CanCollide = false
				end
				if p.CanQuery then
					if held then
						held.cq = true
					end
					p.CanQuery = false
				end
			end
		end
		st.ci = i
	end

	-- what a building leaves where it stood: rubble lying on the lot, dust
	-- boiling up off it (the city's gone, not tidied away)
	function WS.rubble(st, e)
		local W = st.W or W
		local R = W.Rubble or {}
		local D = W.Dust or {}
		if st.rubbleCount < (st.low and (R.LowMax or 90) or (R.Max or 320)) then
			local lo, hi = e.pos - e.size / 2, e.pos + e.size / 2
			local RS, RH = R.Size or { 3, 9 }, R.Height or { 1.5, 4.5 }
			for _ = 1, rng:NextInteger(1, R.PerChunk or 3) do
				local s = Vector3.new(rand(RS[1], RS[2]), rand(RH[1], RH[2]), rand(RS[1], RS[2]))
				local at = Vector3.new(rand(lo.X, hi.X), st.street + s.Y * 0.32, rand(lo.Z, hi.Z))
				local r = newPart(s, CFrame.new(at) * CFrame.Angles(rand(-0.35, 0.35), rand(0, 6.3), rand(-0.35, 0.35)), e.color:Lerp(Color3.fromRGB(70, 66, 62), rand(0.15, 0.45)),
					e.material, nil, st.folder)
				r.Name = "SeriousRubble"
				table.insert(st.rubble, { part = r, arr = e.arr })
				st.rubbleCount += 1
			end
		end
		local g = st.groups[e.gi]
		-- ((round 90 review) a bank a building, at most Dust.Max of them (an
		-- emitter and a few puffs each: ~227 buildings' worth on every screen
		-- at once was too much for a phone))
		st.dustCount = st.dustCount or 0
		if g and not g.dusted and g.center and st.dustCount < (st.low and (D.LowMax or 24) or (D.Max or 80)) then
			g.dusted = true
			st.dustCount += 1
			local span = (g.max - g.min)
			-- the dust boiling up off the lot: a bank of smoke (and a puff or two
			-- of the game's own toon dust under it)
			local base = Vector3.new(g.center.X, st.street + 4, g.center.Z)
			local holder = newPart(Vector3.new(math.max(span.X * 0.8, 4), 2, math.max(span.Z * 0.8, 4)), CFrame.new(base), DUST, nil, nil, st.folder)
			holder.Name = "SeriousDustBank"
			holder.Transparency = 1
			local pe = Instance.new("ParticleEmitter")
			pe.Texture = "rbxasset://textures/particles/smoke_main.dds"
			pe.Color = ColorSequence.new(DUST, DUST_DARK)
			pe.Transparency = NumberSequence.new({ NumberSequenceKeypoint.new(0, 0.45), NumberSequenceKeypoint.new(0.4, 0.6), NumberSequenceKeypoint.new(1, 1) })
			local DS = D.Size or { 14, 34 }
			pe.Size = NumberSequence.new({ NumberSequenceKeypoint.new(0, DS[1]), NumberSequenceKeypoint.new(1, DS[2]) })
			pe.Lifetime = NumberRange.new(3, 5)
			pe.Speed = NumberRange.new(4, 12)
			pe.SpreadAngle = Vector2.new(60, 60)
			pe.EmissionDirection = Enum.NormalId.Top
			pe.Acceleration = Vector3.new(0, 2, 0)
			pe.Drag = 0.6
			pe.RotSpeed = NumberRange.new(-20, 20)
			pe.Rate = 0
			pe.Parent = holder
			pe:Emit(st.low and (D.LowEmit or 4) or (D.Emit or 10))
			for _ = 1, st.low and (D.LowPuffs or 1) or (D.Puffs or 2) do
				local at = Vector3.new(g.center.X + rand(-0.3, 0.3) * span.X, st.street + 4, g.center.Z + rand(-0.3, 0.3) * span.Z)
				dustPuffs(at, rand(2.2, 3.2), 4, DUST, rand(2, 3), false)
			end
		end
	end

	-- a thing's flying copies (a building's chunk; a prop's part - a long
	-- one broken in two or four): it bursts apart where it stood, then the
	-- blast takes it - along the punch's line ahead of him, out and up
	-- everywhere else - tumbling, off over the horizon
	function WS.pieces(st, e)
		local W = st.W or W
		local boxes, color, material, alpha, shape
		if e.chunk then
			boxes = { { CFrame.new(e.pos), e.size } }
			color, material, alpha = e.color, e.material, 0
			if e.ground then
				WS.rubble(st, e)
			end
		else
			local p = e.p
			boxes = { { p.CFrame, p.Size } }
			color, material, alpha = p.Color, p.Material, p.Transparency
			local block = not p:IsA("Part") or p.Shape == Enum.PartType.Block
			shape = not block and p.Shape or nil
			for _ = 1, block and (W.SplitMax or 2) or 0 do
				local out = {}
				for _, b in boxes do
					local s = b[2]
					local axis = s.X >= s.Y and s.X >= s.Z and Vector3.new(1, 0, 0) or (s.Y >= s.Z and Vector3.new(0, 1, 0) or Vector3.new(0, 0, 1))
					local len = math.max(s.X, s.Y, s.Z)
					if len > (W.Split or 34) then
						local half = s - axis * (len / 2)
						table.insert(out, { b[1] * CFrame.new(axis * (len / 4)), half })
						table.insert(out, { b[1] * CFrame.new(axis * (-len / 4)), half })
					else
						table.insert(out, b)
					end
				end
				boxes = out
			end
		end
		local S, U = W.Speed or {}, W.Up or {}
		local spec = st.spec
		local g = st.groups[e.gi]
		for _, b in boxes do
			if st.pieceCount >= st.maxPieces then
				break
			end
			local cf, size = b[1], b[2]
			local q = Instance.new("Part")
			q.Name = "WipePiece"
			q.Anchored = true
			q.CanCollide = false
			q.CanQuery = false
			q.CanTouch = false
			q.CastShadow = false
			q.TopSurface = Enum.SurfaceType.Smooth
			q.BottomSurface = Enum.SurfaceType.Smooth
			if shape then
				pcall(function()
					q.Shape = shape
				end)
			end
			q.Size = size
			q.CFrame = cf
			q.Color = color
			q.Material = material
			q.Transparency = alpha
			q.Parent = st.folder
			local pos = cf.Position
			local rel = Vector3.new(pos.X - st.origin.X, 0, pos.Z - st.origin.Z)
			local dist = rel.Magnitude
			local out = dist > 0.5 and rel.Unit or st.d
			local j = W.SpeedJitter or 0.22
			-- ((round 99, craters) the punch's line - round 92's blast from a
			-- point, its pieces flung straight out, went with LIGHTWIPE)
			local front = math.max(out:Dot(st.d), 0) ^ (spec.Sharp or 1.6)
			local dirH = out + st.d * (W.Bias or 0.6) * front
			dirH = dirH.Magnitude > 0.01 and dirH.Unit or st.d
			local speed = ((S.Back or 360) + ((S.Front or 920) - (S.Back or 360)) * front) * (1 + rand(-j, j)) * math.clamp(1.25 - dist / 2200, 0.65, 1.25)
			local up = ((U.Back or 150) + ((U.Front or 55) - (U.Back or 150)) * front) * rand(0.6, 1.3) + math.max(pos.Y - st.street, 0) * 0.15
			-- (the burst: out of the middle of what it was part of)
			local burst = g and g.center and (pos - g.center) or Vector3.zero
			burst = burst.Magnitude > 0.5 and burst.Unit * rand(12, (W.Burst or 34)) or Vector3.zero
			local axis = Vector3.new(rand(-1, 1), rand(-1, 1), rand(-1, 1))
			axis = axis.Magnitude > 0.05 and axis.Unit or Vector3.new(0, 1, 0)
			table.insert(st.pieces, {
				part = q, c0 = cf, v = dirH * speed, up = up, burst = burst, axis = axis,
				w = (W.Spin or 4.5) * rand(0.4, 1) / (1 + math.max(size.X, size.Y, size.Z) / 20),
				t0 = e.arr + rand(0, 0.06), fly = (W.FlyTime or 3.1) + rand(-(W.FlyJitter or 0.5), W.FlyJitter or 0.5),
				alpha = alpha, e = e, W = W,
			})
			st.pieceCount += 1
		end
	end
	-- where a copy is tau seconds into its flight: the burst at once, the
	-- blast's push building up over its first Ramp seconds, gravity
	function WS.at(pc, tau)
		local W = pc.W or W
		local R = W.Ramp or 0.22
		local push = tau - R + R * math.exp(-tau / R)
		local p = pc.c0.Position + pc.burst * tau + pc.v * push + Vector3.new(0, pc.up * tau - 0.5 * (W.Gravity or 46) * tau * tau, 0)
		return CFrame.new(p) * pc.c0.Rotation * CFrame.fromAxisAngle(pc.axis, pc.w * tau)
	end
	function WS.move(parts, cfs)
		if #parts == 0 then
			return
		end
		if not WS.noBulk then
			local ok = pcall(function()
				workspace:BulkMoveTo(parts, cfs, Enum.BulkMoveMode.FireCFrameChanged)
			end)
			if ok then
				WS.bulkFails = 0
				return
			end
			WS.bulkFails = (WS.bulkFails or 0) + 1
			WS.noBulk = WS.bulkFails >= 3
		end
		for i, p in parts do
			p.CFrame = cfs[i]
		end
	end

	---------------------------------------------------------------- the sky and the light
	function WS.skyGather(st, time)
		local W = st.W or W
		local S = W.Sky or {}
		time = time or st.windup
		local terrain = workspace:FindFirstChildOfClass("Terrain")
		if terrain then
			local ok = pcall(function()
				-- ((round 90 review) one record of the sky's clouds while any
				-- punch has them (WS.cloud): a punch gathering while the last
				-- one's are still being given back carries on from them, and
				-- gives back what was there before either - it used to take the
				-- last one's half-dark sky for "what was there" and give that
				-- back for good, or lose its clouds to the last one's clean-up)
				local rec = WS.cloud
				if not (rec and rec.inst.Parent) then
					local c = terrain:FindFirstChildOfClass("Clouds")
					local made = false
					if not c then
						c = Instance.new("Clouds")
						c.Name = "SaitamaClouds"
						c.Cover = 0
						c.Density = 0
						c.Parent = terrain
						made = true
					end
					rec = { inst = c, made = made, saved = (not made) and { Cover = c.Cover, Density = c.Density, Color = c.Color } or nil, token = 0 }
					WS.cloud = rec
				end
				rec.token += 1 -- (a give-back under way: called off)
				st.clouds = rec
				tween(rec.inst, time, { Cover = S.Cover or 0.88, Density = S.Density or 0.72, Color = S.Color or Color3.fromRGB(70, 70, 82) }, Enum.EasingStyle.Sine, Enum.EasingDirection.InOut)
			end)
			if not ok then
				st.clouds = nil
			end
		end
		-- a ring of storm clouds wheeling in over him
		local n = st.low and (S.LowVortex or 10) or (S.Vortex or 18)
		local size = S.Size or { 150, 60 }
		for i = 1, n do
			-- (each a puffy bank: a wide dark base, a lighter top)
			local s = rand(size[2], size[1])
			local a0, h, r, spin = (i / n) * math.pi * 2 + rand(-0.2, 0.2), rand(-30, 40), rand(0.85, 1.15), rand(0.8, 1.2)
			for k = 1, 2 do
				local part = newPart(k == 1 and Vector3.new(s, s * 0.2, s * 0.62) or Vector3.new(s * 0.62, s * 0.24, s * 0.42), CFrame.new(st.origin + Vector3.new(0, 400, 0)),
					k == 1 and (S.Dark or Color3.fromRGB(64, 64, 76)) or (S.Light or Color3.fromRGB(150, 150, 164)), Enum.Material.SmoothPlastic, Enum.PartType.Ball, st.folder)
				part.Name = "SeriousCloud"
				part.Transparency = 1
				tween(part, math.min(time, 1.2), { Transparency = k == 1 and rand(0.35, 0.5) or rand(0.45, 0.6) })
				table.insert(st.vortex, { part = part, a0 = a0 + (k - 1) * 0.06, h = h + (k - 1) * s * 0.12, r = r, spin = spin })
			end
		end
	end
	function WS.skyStep(st, dt)
		local W = st.W or W
		local S = W.Sky or {}
		local R = S.Radius or { 700, 160 }
		if st.phase == "gather" then
			local k = math.clamp((os.clock() - st.t0) / st.windup, 0, 1)
			local radius = R[1] + (R[2] - R[1]) * k ^ 0.8
			local turn = (os.clock() - st.t0) * (0.25 + k * 0.9)
			for _, c in st.vortex do
				local a = c.a0 + turn * c.spin
				local pos = Vector3.new(st.origin.X + math.cos(a) * radius * c.r, st.street + (S.Height or 300) + c.h - k * 60, st.origin.Z + math.sin(a) * radius * c.r)
				local tangent = Vector3.new(-math.sin(a), 0, math.cos(a))
				c.part.CFrame = CFrame.lookAt(pos, pos + tangent)
			end
		else
			for _, c in st.vortex do
				if c.v and c.part.Parent then
					c.part.CFrame = c.part.CFrame + c.v * dt
				end
			end
		end
	end
	-- the punch blows the sky clear: the clouds in its line thrown down it,
	-- the rest out and away
	function WS.skyClear(st)
		local W = st.W or W
		local S = W.Sky or {}
		if st.clouds and st.clouds.inst.Parent then
			tween(st.clouds.inst, S.ClearTime or 1.3, { Cover = 0, Density = 0 }, Enum.EasingStyle.Quad, Enum.EasingDirection.Out)
		end
		for _, c in st.vortex do
			local rel = c.part.CFrame.Position - st.origin
			local out = Vector3.new(rel.X, 0, rel.Z)
			out = out.Magnitude > 1 and out.Unit or st.d
			if out:Dot(st.d) > 0.7 then
				c.v = st.d * rand(1300, 1700) + Vector3.new(0, rand(40, 120), 0)
			else
				c.v = out * rand(260, 380) + Vector3.new(0, rand(20, 60), 0)
			end
			tween(c.part, rand(1.1, 1.6), { Transparency = 1 }, Enum.EasingStyle.Quad, Enum.EasingDirection.In)
		end
	end
	function WS.skyRestore(st, time)
		local c = st.clouds
		st.clouds = nil
		if not c or WS.cloud ~= c then
			return
		end
		if not c.inst.Parent then
			WS.cloud = nil
			return
		end
		c.token += 1
		local token = c.token
		if c.made then
			tween(c.inst, time or 0.6, { Cover = 0, Density = 0 })
		elseif c.saved then
			tween(c.inst, time or 0.6, c.saved)
		end
		-- (given back: ours gone for sure, not left to Debris - unless another
		-- punch took the sky over meanwhile)
		task.delay((time or 0.6) + 0.05, function()
			if c.token == token and WS.cloud == c then
				WS.cloud = nil
				if c.made then
					pcall(c.inst.Destroy, c.inst)
				end
			end
		end)
	end
	function WS.grade(st, which, time)
		local W = st.W or W
		local G = (W.Grade or {})[which]
		if not G or (VFX.VR and VFX.VR.on) then
			return
		end
		local cc = st.grade
		if not (cc and cc.Parent) then
			cc = Instance.new("ColorCorrectionEffect")
			cc.Name = "SaitamaGrade"
			cc.Parent = LightingSvc
			st.grade = cc
		end
		tween(cc, time, { Brightness = G.Brightness or 0, Contrast = G.Contrast or 0, Saturation = G.Saturation or 0, TintColor = G.Tint or Color3.new(1, 1, 1) }, Enum.EasingStyle.Sine, Enum.EasingDirection.InOut)
	end
	function WS.gradePunch(st)
		local W = st.W or W
		WS.grade(st, "Windup", 0.01)
		if st.grade then
			st.grade.Brightness = 0.55
			st.grade.Contrast = 0.35
			st.grade.Saturation = -0.6
		end
		-- ((round 92) Grade.AfterDelay / AfterTime: how soon the white-out
		-- gives way to the After grade, and over how long - the punch's 0.1 / 1.1)
		local GR = W.Grade or {}
		task.delay(GR.AfterDelay or 0.1, function()
			if WS.state == st then
				WS.grade(st, "After", GR.AfterTime or 1.1)
			end
		end)
		task.delay(0.9, function()
			if WS.state ~= st or (VFX.VR and VFX.VR.on) then
				return
			end
			local R = (W.Grade or {}).SunRays or {}
			local ok, rays = pcall(function()
				local s = Instance.new("SunRaysEffect")
				s.Name = "SaitamaSunRays"
				s.Intensity = 0
				s.Spread = R.Spread or 0.7
				s.Parent = LightingSvc
				return s
			end)
			if ok and rays then
				st.rays = rays
				tween(rays, 1.5, { Intensity = R.Intensity or 0.16 })
			end
		end)
	end
	function WS.gradeOff(st, time)
		local cc, rays = st.grade, st.rays
		st.grade, st.rays = nil, nil
		time = time or 0.8
		-- (the screen's own light: gone for sure, not left to Debris)
		if cc and cc.Parent then
			tween(cc, time, { Brightness = 0, Contrast = 0, Saturation = 0, TintColor = Color3.new(1, 1, 1) })
			task.delay(time + 0.05, function()
				pcall(cc.Destroy, cc)
			end)
		end
		if rays and rays.Parent then
			tween(rays, time, { Intensity = 0 })
			task.delay(time + 0.05, function()
				pcall(rays.Destroy, rays)
			end)
		end
	end

	---------------------------------------------------------------- the blast
	-- the column of air down the punch's line (out to the horizon, a hair
	-- upward), tapering out wider as it goes, and the rings round it
	function WS.columnMake(st)
		local W = st.W or W
		local Cl = W.Column or {}
		local pitch = math.rad(Cl.Pitch or 3)
		st.colAxis = (st.d * math.cos(pitch) + Vector3.new(0, math.sin(pitch), 0)).Unit
		st.colFrom = st.origin + st.d * 2.5 + Vector3.new(0, 0.6, 0)
		local segs = st.low and 4 or 7
		st.colSegs = segs
		for i = 1, segs do
			for layer = 1, 2 do
				local p = newPart(Vector3.one, CFrame.new(st.colFrom), layer == 1 and Color3.new(1, 1, 1) or AIR, layer == 1 and Enum.Material.Neon or Enum.Material.SmoothPlastic, Enum.PartType.Cylinder, st.folder)
				p.Name = "SeriousColumn"
				p.Transparency = 1
				table.insert(st.column, { part = p, i = i, layer = layer, base = layer == 1 and 0.15 or 0.45 })
			end
		end
	end
	function WS.columnStep(st, elapsed)
		local W = st.W or W
		local Cl = W.Column or {}
		local R = Cl.Radius or { 5, 70 }
		local life = Cl.Life or 1.6
		local grow = math.clamp(elapsed / (Cl.Reach or 0.32), 0, 1)
		local L = (Cl.Length or 2600) * grow
		local fade = math.clamp(elapsed / life, 0, 1)
		for _, c in st.column do
			local a, b = (c.i - 1) / st.colSegs, c.i / st.colSegs
			local from, to = st.colFrom + st.colAxis * (L * a), st.colFrom + st.colAxis * (L * b)
			local len = (to - from).Magnitude
			if fade >= 1 or len < 0.2 then
				c.part.Transparency = 1
			else
				local r = (R[1] + (R[2] - R[1]) * ((a + b) / 2)) * (c.layer == 1 and 0.4 or 1) * (1 + elapsed * 0.5)
				c.part.Size = Vector3.new(len, r * 2, r * 2)
				c.part.CFrame = CFrame.lookAt((from + to) / 2, to) * CFrame.Angles(0, math.rad(90), 0)
				c.part.Transparency = c.base + (1 - c.base) * fade ^ 1.4
			end
		end
		-- a ring of air every so often down it, as its front goes past
		local n = Cl.Rings or 12
		while st.rings < n do
			local k = st.rings + 1
			local dist = (Cl.Spacing or 60) * k ^ 1.35
			if dist > L then
				break
			end
			st.rings = k
			local r = R[1] + (R[2] - R[1]) * math.clamp(dist / (Cl.Length or 2600), 0, 1)
			ST.ring(st.colFrom + st.colAxis * dist, st.colAxis, r * 1.6, r * 4.5, 0.5, AIR, 0.3)
		end
	end
	-- the wall of dust the wave drives across the city, round in every
	-- direction (fastest down the line)
	function WS.wallMake(st)
		local W = st.W or W
		local Wl = W.Wall or {}
		local n = st.low and (Wl.LowSegments or 24) or (Wl.Segments or 44)
		local spec = st.spec
		local box = WS.cityBox(st.map)
		for i = 1, n do
			local u = CFrame.fromAxisAngle(Vector3.new(0, 1, 0), (i - 1) / n * math.pi * 2) * st.d
			local front = math.max(u:Dot(st.d), 0) ^ (spec.Sharp or 1.6)
			local speed = (spec.Back or 520) + ((spec.Front or 1600) - (spec.Back or 520)) * front
			local dark = newPart(Vector3.one, CFrame.new(st.origin), DUST_DARK, Enum.Material.SmoothPlastic, Enum.PartType.Ball, st.folder)
			local light = newPart(Vector3.one, CFrame.new(st.origin), DUST, Enum.Material.SmoothPlastic, Enum.PartType.Ball, st.folder)
			dark.Name, light.Name = "SeriousDust", "SeriousDust"
			dark.Transparency, light.Transparency = 1, 1
			-- (it dies out at the city's edge, not out over the void)
			local reach = math.min(Wl.Reach or 1500, WS.inside(box, st.origin, u) + 40)
			table.insert(st.wall, { u = u, speed = speed, dark = dark, light = light, j = rand(0.8, 1.2), ph = rand(0, 6), reach = math.max(reach, 60) })
		end
	end
	function WS.wallStep(st, elapsed, parts, cfs)
		local W = st.W or W
		local Wl = W.Wall or {}
		local size = Wl.Size or { 18, 64 }
		local delay = st.spec.Delay or 0.05
		for _, s in st.wall do
			local reach = s.reach
			local r = s.speed * math.max(elapsed - delay, 0)
			if r > reach + 200 then
				if not s.gone then
					s.gone = true
					s.dark.Transparency, s.light.Transparency = 1, 1
				end
			elseif r > 2 then
				local k = math.clamp(r / (Wl.Reach or 1500), 0, 1)
				local sz = (size[1] + (size[2] - size[1]) * k) * s.j
				local pos = Vector3.new(st.origin.X, st.street, st.origin.Z) + s.u * r
				local wob = math.sin(elapsed * 9 + s.ph) * 0.06
				s.dark.Size = Vector3.new(sz * 1.25, sz * (0.6 + wob), sz)
				s.light.Size = Vector3.new(sz * 0.95, sz * (0.5 - wob), sz * 0.8)
				local cf = CFrame.lookAt(pos + Vector3.new(0, sz * 0.22, 0), pos + Vector3.new(0, sz * 0.22, 0) + s.u)
				table.insert(parts, s.dark)
				table.insert(cfs, cf)
				table.insert(parts, s.light)
				table.insert(cfs, cf * CFrame.new(0, sz * 0.18, -sz * 0.1))
				local t = r > reach and math.clamp((r - reach) / 200, 0, 1) or 0
				s.dark.Transparency = 0.2 + 0.8 * t
				s.light.Transparency = 0.3 + 0.7 * t
			end
		end
	end
	-- the scour marks the blast leaves fanned out over the street (each
	-- darkening as the wave goes over it)
	-- the walkable city (its ground and roads), once a map: nil without one
	function WS.cityBox(map)
		if not map then
			return nil
		end
		if WS.boxOf and WS.boxOf.map == map then
			return WS.boxOf.min and WS.boxOf or nil
		end
		local box = { map = map }
		for _, name in { "Ground", "Roads" } do
			local f = map:FindFirstChild(name)
			for _, p in f and f:GetDescendants() or {} do
				if p:IsA("BasePart") then
					local lo, hi = WS.box(p.CFrame, p.Size)
					box.min = box.min and WS.vmin(box.min, lo) or lo
					box.max = box.max and WS.vmax(box.max, hi) or hi
				end
			end
		end
		WS.boxOf = box
		return box.min and box or nil
	end
	-- how far from p along u before it leaves the city (huge without one)
	function WS.inside(box, p, u)
		if not box then
			return math.huge
		end
		local most = math.huge
		for _, axis in { "X", "Z" } do
			local v = u[axis]
			if v > 1e-3 then
				most = math.min(most, (box.max[axis] - 8 - p[axis]) / v)
			elseif v < -1e-3 then
				most = math.min(most, (box.min[axis] + 8 - p[axis]) / v)
			end
		end
		return most
	end
	function WS.scourMake(st)
		local W = st.W or W
		local Sc = W.Scour or {}
		local n = st.low and (Sc.LowCount or 16) or (Sc.Count or 34)
		local L, Wd = Sc.Length or { 220, 760 }, Sc.Width or { 6, 22 }
		local box = WS.cityBox(st.map)
		for _ = 1, n do
			local a = rng:NextNumber() < 0.7 and rand(-0.6, 0.6) or rand(-math.pi, math.pi)
			local u = CFrame.fromAxisAngle(Vector3.new(0, 1, 0), a) * st.d
			local len, wid, start = rand(L[1], L[2]), rand(Wd[1], Wd[2]), rand(10, 60)
			-- (on the city's own ground: never out over the void)
			len = math.min(len, WS.inside(box, st.origin, u) - start)
			if len < 30 then
				continue
			end
			local mid = st.origin + u * (start + len / 2)
			local gy = WS.street(mid + Vector3.new(0, 200, 0), st.map)
			if math.abs(gy - st.street) > 40 then
				gy = st.street
			end
			local g = Vector3.new(mid.X, gy + 0.08, mid.Z)
			local p = newPart(Vector3.new(wid, 0.08, len), CFrame.lookAt(g, g + u), Color3.fromRGB(52, 46, 42), Enum.Material.SmoothPlastic, nil, st.folder)
			p.Name = "SeriousScour"
			p.Transparency = 1
			local arr = (WS.arrive(st, st.origin + u * start))
			tween(p, 0.4, { Transparency = 0.45 }, Enum.EasingStyle.Quad, Enum.EasingDirection.Out, arr)
			table.insert(st.scour, p)
		end
	end

	---------------------------------------------------------------- the phases
	-- the windup: the city read, the sky rolling in, the light draining
	function WS.gather(run)
		if WS.state then
			WS.finish(WS.state)
		end
		local st = WS.new(run.origin, run.d, run.spec, run.char)
		WS.skyGather(st)
		WS.grade(st, "Windup", st.windup)
		WS.startScan(st)
		return st
	end
	-- the windup came to nothing: the sky and the light given back
	-- ((round 92) only a wipe of this kind's: the punch's by default - a
	-- city read ahead for another kind of wipe isn't his windup to call off)
	function WS.cancel(kind)
		local st = WS.state
		if st and st.phase == "gather" and (st.kind or "punch") == (kind or "punch") then
			WS.finish(st, 1)
		end
	end
	-- THE PUNCH (the server's moment, `at`): the wave goes out
	-- ((round 92) opts: the wipe's own - WS.new's; a city read ahead for a
	-- wipe of another kind isn't taken over: it's let go, and this one reads
	-- its own)
	function WS.go(origin, d, at, spec, char, opts)
		opts = opts or {}
		local st = WS.state
		if st and st.phase == "gather" and (st.kind or "punch") ~= (opts.Kind or "punch") then
			WS.finish(st, 0.3)
			st = nil
		end
		-- ((round 92 review) a city read from somewhere else is planned again
		-- from here (WS.replan) - but what it read was measured against the
		-- street under where it was read from (WS.new: what's above the
		-- foundations). One whose floor isn't this street's (read where none
		-- was found: the default Wipe.Street - the map's today, nobody's
		-- tomorrow - and its lowest floors were never read, so they'd stand
		-- in the empty plain) is let go, and this one reads its own
		if st and st.phase == "gather" and (st.origin - origin).Magnitude > 4 then
			local y, found = WS.street(origin, st.map)
			if found and math.abs(y - st.street) > ((st.W or W).Foundation or 3) * 2 then
				WS.finish(st, 0.3)
				st = nil
			end
		end
		if st and st.phase ~= "gather" then
			-- (a punch while the last one's city is still gone: that one's put back now)
			WS.finish(st)
			st = nil
		end
		if st then
			st.spec = spec
			st.char = char
			if (st.origin - origin).Magnitude > 4 or st.d:Dot(d) < 0.998 then
				WS.finishScan(st)
				WS.replan(st, origin, d)
			end
		else
			st = WS.new(origin, d, spec, char, opts)
			WS.skyGather(st, 0.3)
			WS.startScan(st)
		end
		WS.finishScan(st)
		WS.settle(st)
		st.at = at
		st.phase = "wave"
		WS.columnMake(st)
		WS.wallMake(st)
		WS.scourMake(st)
		WS.skyClear(st)
		WS.gradePunch(st)
		task.delay(1.6, function()
			if WS.state == st then
				ST.far("SeriousAftermath", st.origin, 1)
			end
		end)
		return st
	end

	-- this screen when the wave gets to it: the shake, the view kicked out,
	-- the white, the roar going over, dust round you
	function WS.hitMe(st, elapsed)
		local W = st.W or W
		local me = ST.me()
		local mr = me and me:FindFirstChild("HumanoidRootPart")
		local at = mr and mr.Position or ST.camPos()
		if elapsed < (WS.arrive(st, at)) then
			return
		end
		st.hitMe = true
		local k = math.clamp(1.2 - (at - st.origin).Magnitude / 1500, 0.4, 1)
		VFX.Shake((W.Hit or 6) * k, 1.1)
		local EK = VFX.EngineKit
		if EK and EK.fovPunch and not VFX.InCinematic() then
			EK.fovPunch((W.Fov or 14) * k, 0.06, 0.7, 0.1)
		end
		if me ~= st.char then
			VFX.Hooks.Flash(Color3.new(1, 1, 1), 0.2 * k)
		end
		ST.far("SeriousWave", nil, 1.1 * k)
		if mr then
			dustPuffs(groundPoint(mr.Position), 2, st.low and 2 or 5, DUST, 1, false)
		end
	end

	-- the hold over: the rewind's schedule - every part shown again as its
	-- copy gets home, the far side of the city first, converging on him
	function WS.rewindPlan(st)
		local W = st.W or W
		local maxArr = st.maxBucket * BUCKET
		local span = W.RewindSpan or 1.4
		local back = W.RewindTime or 1.5
		local start = st.holdEnd
		local k = span / math.max(maxArr, 0.1)
		st.rewindK = k -- (and a part that turns up meanwhile: WS.arrived)
		for _, e in st.hidden do
			e.restoreAt = start + (maxArr - e.arr) * k + back
		end
		for _, e in st.late do
			e.restoreAt = start + (maxArr - e.arr) * k + back
		end
		for _, e in st.flown do
			e.restoreAt = start + (maxArr - e.arr) * k + back
		end
		for _, r in st.rubble do
			r.goAt = start + (maxArr - r.arr) * k + back * 0.4
		end
		for _, pc in st.pieces do
			pc.back0 = pc.e.restoreAt and pc.e.restoreAt - back or (start + span)
		end
		-- (hidden in order of the wave: the last one hidden comes back first)
		st.ri = #st.hidden
		st.rewindEnd = start + span + back
		ST.far("SeriousRewind", st.origin, 1)
	end

	-- a part's shown again: if you're standing inside it, out you go (to the
	-- street beside what it belongs to)
	function WS.pushOut(st, e)
		local me = ST.me()
		local mr = me and me:FindFirstChild("HumanoidRootPart")
		local p = e.p
		if not mr or not p.Parent or e.cc == false then
			return
		end
		local lp = p.CFrame:PointToObjectSpace(mr.Position)
		local h = p.Size / 2 + Vector3.new(1, 2.5, 1)
		if math.abs(lp.X) > h.X or math.abs(lp.Y) > h.Y or math.abs(lp.Z) > h.Z then
			return
		end
		local g = st.groups[e.gi]
		local lo, hi = g and g.min or p.CFrame.Position - p.Size, g and g.max or p.CFrame.Position + p.Size
		local pos = mr.Position
		local moves = {
			{ pos.X - lo.X, Vector3.new(lo.X - 3, pos.Y, pos.Z) },
			{ hi.X - pos.X, Vector3.new(hi.X + 3, pos.Y, pos.Z) },
			{ pos.Z - lo.Z, Vector3.new(pos.X, pos.Y, lo.Z - 3) },
			{ hi.Z - pos.Z, Vector3.new(pos.X, pos.Y, hi.Z + 3) },
		}
		table.sort(moves, function(a, b)
			return a[1] < b[1]
		end)
		local spot = moves[1][2]
		local ground = WS.street(spot + Vector3.new(0, 200, 0), st.map)
		local out = Vector3.new(spot.X, ground + 3.2, spot.Z)
		mr.AssemblyLinearVelocity = Vector3.zero
		mr.CFrame = CFrame.new(out) * mr.CFrame.Rotation
	end

	function WS.step(st, dt)
		local W = st.W or W
		if st.phase == "gather" then
			WS.resumeScan(st)
			WS.skyStep(st, dt)
			if os.clock() - st.t0 > st.windup + 3 then
				WS.finish(st, 1) -- (never thrown: given back)
			end
			return
		end
		local elapsed = WS.elapsed(st)
		local cam = ST.camPos()
		local parts, cfs = {}, {}
		WS.skyStep(st, dt)
		if elapsed < (W.Column and W.Column.Life or 1.6) + 0.1 then
			WS.columnStep(st, elapsed)
		end
		if st.phase == "wave" then
			-- the wave: every part it's got to by now, hidden (a budget a frame)
			local upto = math.floor(math.max(elapsed, 0) / BUCKET) + 1
			local budget = st.low and (W.LowHideBudget or 400) or (W.HideBudget or 900)
			while st.bi <= math.min(upto, st.maxBucket) and budget > 0 do
				local list = st.buckets[st.bi]
				if list then
					while st.bk <= #list and budget > 0 do
						WS.hide(st, list[st.bk])
						st.bk += 1
						budget -= 1
					end
					if st.bk <= #list then
						break
					end
				end
				st.bi += 1
				st.bk = 1
			end
			if not st.hitMe then
				WS.hitMe(st, elapsed)
			end
			if st.bi > st.maxBucket and elapsed > st.maxBucket * BUCKET + 0.3 then
				st.phase = "hold"
				st.holdEnd = elapsed + (W.Hold or 7)
			end
		end
		WS.wallStep(st, elapsed, parts, cfs)
		-- the copies: flying, parked over the horizon, or flying home
		local fade = W.Fade or 0.5
		local clear = W.CameraClear or 12
		for _, pc in st.pieces do
			local q = pc.part
			if pc.state == nil then
				local tau = elapsed - pc.t0
				if tau >= pc.fly then
					q.Parent = nil
					pc.state = "parked"
				elseif tau >= 0 then
					local cf = WS.at(pc, tau)
					table.insert(parts, q)
					table.insert(cfs, cf)
					if tau > pc.fly - fade and (pc.faded or 0) < 2 then
						local second = tau > pc.fly - fade / 2
						if second or not pc.faded then
							pc.faded = second and 2 or 1
							q.Transparency = math.max(pc.alpha, second and 0.85 or 0.55)
						end
					end
					if not pc.near and (cf.Position - cam).Magnitude < clear then
						pc.near = true
						q.Transparency = math.max(q.Transparency, 0.9)
					end
				end
			elseif pc.state ~= "home" and pc.back0 and elapsed >= pc.back0 then
				local u = (elapsed - pc.back0) / (W.RewindTime or 1.5)
				if u >= 1 then
					pc.state = "home"
					q:Destroy()
				else
					if pc.state == "parked" then
						pc.state = "back"
						q.Transparency = pc.alpha
						q.Parent = st.folder
					end
					table.insert(parts, q)
					table.insert(cfs, WS.at(pc, pc.fly * (1 - u) ^ 2))
				end
			end
		end
		WS.move(parts, cfs)
		WS.recheck(st)
		if st.phase == "hold" then
			if elapsed >= st.holdEnd then
				st.phase = "rewind"
				WS.rewindPlan(st)
				for _, s in st.scour do
					tween(s, W.RewindSpan or 1.4, { Transparency = 1 }, Enum.EasingStyle.Sine, Enum.EasingDirection.In)
				end
				WS.gradeOff(st, (W.RewindSpan or 1.4) + (W.RewindTime or 1.5))
			end
		elseif st.phase == "rewind" then
			local budget = st.low and (W.LowHideBudget or 400) or (W.HideBudget or 900)
			while st.ri >= 1 and budget > 0 do
				local e = st.hidden[st.ri]
				if e.restoreAt > elapsed then
					break
				end
				WS.unhide(e)
				WS.pushOut(st, e)
				st.ri -= 1
				budget -= 1
			end
			for i = #st.late, 1, -1 do
				local e = st.late[i]
				if e.restoreAt and e.restoreAt <= elapsed then
					WS.unhide(e)
					WS.pushOut(st, e)
					table.remove(st.late, i)
				end
			end
			-- the rubble goes back up into what it fell from
			for _, r in st.rubble do
				if not r.gone and r.goAt and elapsed >= r.goAt and r.part.Parent then
					r.gone = true
					tween(r.part, 0.5, { Transparency = 1, CFrame = r.part.CFrame + Vector3.new(0, 6, 0) }, Enum.EasingStyle.Quad, Enum.EasingDirection.In)
				end
			end
			if elapsed >= st.rewindEnd + 0.3 then
				WS.finish(st)
				return
			end
		end
		if elapsed > (W.MaxTime or 30) then
			WS.finish(st)
		end
	end

	-- everything back as it was (now): every part shown, every copy gone, the
	-- sky and the light given back
	function WS.finish(st, time)
		if not st or st.finished then
			return
		end
		st.finished = true
		st.phase = "done"
		if WS.state == st then
			WS.state = nil
		end
		for _, c in st.conns do
			c:Disconnect()
		end
		st.scanCo = nil
		for _, e in st.hidden do
			WS.unhide(e)
		end
		for _, e in st.late do
			WS.unhide(e)
		end
		for _, pc in st.pieces do
			pcall(pc.part.Destroy, pc.part)
		end
		table.clear(st.pieces)
		-- ((round 92) let go of every map part it read)
		st.known, st.adds = {}, {}
		if time and time > 0 then
			for _, c in st.vortex do
				if c.part.Parent then
					tween(c.part, time, { Transparency = 1 })
				end
			end
			local f = st.folder
			f.Name = "SaitamaWipeGone"
			task.delay(time + 0.05, function()
				pcall(f.Destroy, f)
			end)
		else
			st.folder:Destroy()
		end
		WS.skyRestore(st, time)
		WS.gradeOff(st, time)
	end

	---------------------------------------------------------------------
	-- the awakening (G): "OK." - (round 101, awaken_p) on the awakening kit
	-- (MoveSaitamaAwaken, its Hit kept at 0.32 - his row's HitAt): a bored
	-- nod, a beat of nothing - then the glove tug, square on, deadpan: the
	-- eyes go serious (the glint), the cape snaps and the air round him
	-- jumps (the AIR disc, the dust blown flat). No flare, no pillar, no
	-- aura: he doesn't power up, he just stops being bored. "OK." is his line
	-- and his shout (the cut-in's; the paper panel over him on everyone
	-- else's screen).
	---------------------------------------------------------------------
	VFX.AK.FX.Saitama = {
		press = function(ctx)
			local G = (VFX.AK.P.cfg("Saitama").Gust or {})[1] or { 0.5, 1.6 }
			ST.gust(ctx.char, G[1], G[2])
		end,
		hit = function(ctx)
			local C = VFX.AK.P.cfg("Saitama")
			local char, root, s = ctx.char, ctx.root, ctx.scale
			local g = ctx.g or (root.Position - UP * 3 * s)
			local G = (C.Gust or {})[2] or { 1, 1.4 }
			ST.glint(char)
			ST.gust(char, G[1], G[2])
			VFX.AK.note(ctx, "glint")
			shockDisc(g + UP * 0.3, UP, 4, 70 * s, 0.5, AIR)
			billboardRing(root.Position, 3, 34 * s, AIR, 10, 0.4)
			-- the dust round him blown flat, out in a ring (none across his own lens)
			if ctx.g then
				local D = C.Dust or {}
				local n = math.max(math.floor((D.Count or 12) * (ctx.low and 0.5 or 1)), 3)
				local to = D.To or { 18, 26 }
				for i = 1, n do
					local a = i / n * math.pi * 2
					local dir = Vector3.new(math.cos(a), 0, math.sin(a))
					local goal = g + dir * rand(to[1], to[2]) * s + UP * 1.2 * s
					if not VFX.AK.lens(ctx, g + dir * 8 * s + UP, 2) and not VFX.AK.lens(ctx, goal, 2) then
						local puff = newPart(Vector3.one * 2.5 * s, CFrame.new(g + dir * (D.From or 3) * s + UP * 0.8 * s), DUST, Enum.Material.SmoothPlastic, Enum.PartType.Ball)
						puff.Name = "AwakenDust"
						puff.Transparency = 0.35
						tween(puff, 0.6, { CFrame = CFrame.new(goal), Size = Vector3.new(6, 2, 6) * s, Transparency = 1 }, Enum.EasingStyle.Quad, Enum.EasingDirection.Out)
						cleanup(puff, 0.62)
					end
				end
			end
		end,
	}

	-- a dash: one afterimage where he was
	QUIRK_FX.Dash.Saitama = function(char)
		ST.ghost(char, 0.3)
	end

	-- THE FINISHER (Config.Finishers.Styles.Saitama, FX.Saitama): bored, he
	-- looks away; one normal punch, and they're gone over the horizon (a
	-- twinkle in the sky where they went)
	function ST.finisher(char, _target, troot, d, time)
		VFX.Pose(char, "SaitamaBored3", math.max(time - 0.2, 0.2))
		task.delay(math.max(time - 0.16, 0), function()
			if char.Parent then
				VFX.Motion(char, "SaitamaNormalPunch")
				VFX.PlaySound("NormalPunchSwing", troot.Position, 1)
			end
		end)
		task.delay(time, function()
			if not troot.Parent then
				return
			end
			local flat = Vector3.new(d.X, 0, d.Z)
			flat = flat.Magnitude > 0.05 and flat.Unit or Vector3.new(0, 0, -1)
			VFX.PlaySound("NormalPunchHit", troot.Position, 1.1)
			ST.gale(troot.Position, flat, 70, 14, true)
			-- the twinkle: where they went, a star in the sky
			task.delay(1.4, function()
				if not troot.Parent then
					return
				end
				local at = troot.Position + flat * 40 + Vector3.new(0, 60, 0)
				VFX.HitStar(at, 22, Color3.new(1, 1, 1))
				task.delay(0.12, function()
					VFX.HitStar(at, 14, Color3.fromRGB(255, 240, 200))
				end)
			end)
		end)
	end

	-- (round 90 review) who's in an emote right now (ST.emoting[char]: the
	-- bored idle leaves them be). Effects.Emote runs until the emote's over
	-- or broken off, so it's wrapped - once the whole module's loaded (the
	-- emotes' own wrapper, VFX.EMOTES, is further down) - to mark the time
	-- it runs. A plain table, each entry cleared as its emote ends.
	task.defer(function()
		local base = Effects.Emote
		if type(base) ~= "function" or ST.emoteBase then
			return
		end
		ST.emoteBase = base
		Effects.Emote = function(char, ...)
			local mark = typeof(char) == "Instance" and char or nil
			if mark then
				ST.emoting[mark] = (ST.emoting[mark] or 0) + 1
			end
			local ok, err = pcall(base, char, ...)
			if mark then
				local n = (ST.emoting[mark] or 1) - 1
				ST.emoting[mark] = n > 0 and n or nil
			end
			if not ok then
				error(err, 0)
			end
		end
	end)
end)()

---------------------------------------------------------------------------
-- (round 99) GODSPEED on every screen (VFX.GSX; Config.DevFlight.God): the
-- strongest thing in the game going off.
--   THE CHARGE (Effects.DevFly Kind GodCharge): the power building in him -
--     his body crackling white-gold (a white core, the gold round it, an
--     electric-blue edge), lightning forking off it (more and longer as it
--     builds), the air round him warping (a shimmering bubble swelling),
--     dust and debris pulled up off the street toward him if he's low; the
--     rising roar and the deep rumble (his ears flat; everyone else's on him)
--   THE BOOM (Kind God): the biggest in the game - a white flash; the shock
--     sphere blasting out from him (Look.Boom.Sphere across: seen from
--     anywhere in the city); the ring torn through the clouds over him; the
--     shock ring racing over the streets under him; glass and loose debris
--     blown off the buildings round him; the vapor cone, the rings, the
--     lightning thrown off it; every screen shaking (harder the closer) and
--     the boom - his in his head (the world muffled, his ears ringing, his
--     wind sucked out and roaring back), everyone else's late by the
--     distance (the crack lost far off, the low end and the roll carrying)
--   AT GODSPEED (the watcher, GSX.step from DFX.step - every screen): a
--     blazing plasma sheath round him (white-gold core, electric-blue edge),
--     a huge shock cone off him (not on his own screen: the camera's inside
--     it), booms going off behind him in a chain, a thick contrail laid down
--     his way across the sky (it lingers: Look.Contrail.Life), the street
--     torn up in a wake under him when he skims it. His own screen
--     (GSX.frame): the colour pushed hot and bloomed, power streaks streaming past
--   A BUILDING HE GOES THROUGH (Kind GodBlast: his screen at once, everyone
--     else's from the server): blown open - a fireball in and out of it, the
--     wall bursting in and out the far side, glass, dust (no FULL POWER:
--     LIGHTSPEED's own hole)
--   OUT OF IT (Kind GodOut): the closing boom (a smaller one)
-- INTO THE GROUND ((round 99, craters): LIGHTWIPE's gone) is GODSPEED's crater
-- (VFX.CTX, Config.DevFlight.Crater.God - GSX.impact its glow and its power).
-- Everything it makes is this screen's alone and goes with it (the contrail
-- after its Life); nothing of the game's is changed (the grade and the bloom
-- are its own, destroyed after). Half as much on a low-end machine. (In a
-- function of its own: the main chunk's at its local limit.)
---------------------------------------------------------------------------
;(function()
	local DEVc = Config.DevFlight or {}
	local GC = DEVc.God or {}
	local LOOK = GC.Look or {}
	local Lit = game:GetService("Lighting")
	local CORE = LOOK.Core or Color3.fromRGB(255, 250, 236)
	local GOLD = LOOK.Gold or Color3.fromRGB(255, 212, 104)
	local DEEP = LOOK.Deep or Color3.fromRGB(255, 160, 54)
	local BLUE = LOOK.Blue or Color3.fromRGB(92, 170, 255)
	local WHITE = Color3.new(1, 1, 1)
	local CLOUD = Color3.fromRGB(242, 245, 250)
	local SMOKE = Color3.fromRGB(96, 90, 92)
	local ROCK = Color3.fromRGB(128, 124, 126)
	local BALL, CYL = Enum.PartType.Ball, Enum.PartType.Cylinder
	local GSX = {
		BEATS = {},
		-- his own screen: k (GODSPEED 0..1), the charge (the flight sets it), its voice
		mine = { k = 0, charge = 0, streaks = {} },
		voices = {}, -- [char] = the charge's sound on him (everyone else's ears; let go on untrack)
		contrail = {}, -- every piece of contrail hanging on this screen (every flyer's, oldest first)
	}
	VFX.GSX = GSX
	-- a sane Vector3 off the wire (no NaN, nowhere absurd), or nil
	local function vec(v)
		return (typeof(v) == "Vector3" and v == v and v.Magnitude < 1e6) and v or nil
	end
	-- the way a beat goes (a unit vector), else his body's line, else ahead
	local function dirOf(v, root)
		if typeof(v) == "Vector3" and v == v and v.Magnitude > 0.01 then
			return v.Unit
		end
		return root and root.CFrame.UpVector or Vector3.new(0, 0, -1)
	end
	function GSX.low()
		return VFX.EngineKit.lowEnd()
	end
	function GSX.n(x)
		return VFX.EngineKit.count(x)
	end
	function GSX.folder()
		local f = GSX.fxFolder
		if not (f and f.Parent) then
			f = Instance.new("Folder")
			f.Name = "GodSpeedFX"
			f.Parent = folder
			GSX.fxFolder = f
		end
		return f
	end
	-- parts moved in one go (VFX.ST.World's BulkMoveTo), or one at a time
	function GSX.move(parts, cfs)
		local WS = VFX.ST and VFX.ST.World
		if WS and WS.move then
			WS.move(parts, cfs)
			return
		end
		for i, p in parts do
			p.CFrame = cfs[i]
		end
	end
	-- fn(t) every frame for `life` s (t: s since it started), then `holder`
	-- and everything in it gone - or as soon as fn errors or it's gone
	function GSX.animate(holder, life, fn)
		local t0 = os.clock()
		local conn
		conn = RunService.RenderStepped:Connect(function()
			local t = os.clock() - t0
			if t > life or not holder.Parent or not pcall(fn, t) then
				conn:Disconnect()
				pcall(holder.Destroy, holder)
			end
		end)
		if not pcall(fn, 0) then
			conn:Disconnect()
			pcall(holder.Destroy, holder)
		end
		return conn
	end
	-- the city's street under a point (the map's Roads / Ground), at most
	-- depth studs down: the ray's hit, or nil (no city: whatever's under it)
	function GSX.street(pos, depth)
		local map = workspace:FindFirstChild("Map")
		local list = {}
		for _, name in { "Roads", "Ground" } do
			local f = map and map:FindFirstChild(name)
			if f then
				table.insert(list, f)
			end
		end
		if #list == 0 then
			return groundRay(pos, depth)
		end
		local params = RaycastParams.new()
		params.FilterType = Enum.RaycastFilterType.Include
		params.FilterDescendantsInstances = list
		return workspace:Raycast(pos + UP * 3, UP * -(depth + 3), params)
	end

	---------------------------------------------------------------------
	-- building blocks
	---------------------------------------------------------------------
	-- a fork of lightning from `from` out along `dir`, `len` studs: kinked
	-- strokes of light (a branch off it now and then), gone in `life`
	function GSX.bolt(from, dir, len, color, life, width)
		if typeof(dir) ~= "Vector3" or dir.Magnitude < 0.01 or dir ~= dir then
			return
		end
		life, width = life or 0.09, width or 0.22
		local d = dir.Unit
		local right = d:Cross(math.abs(d.Y) < 0.95 and UP or Vector3.new(1, 0, 0)).Unit
		local up2 = right:Cross(d).Unit
		local pts = { from }
		for i = 1, 4 do
			local jitter = i < 4 and (right * rand(-1, 1) + up2 * rand(-1, 1)) * len * 0.13 or Vector3.zero
			table.insert(pts, from + d * len * (i / 4) + jitter)
		end
		if len > 8 and rng:NextNumber() < 0.6 then
			local m = pts[3]
			local bd = (d + right * rand(-1.2, 1.2) + up2 * rand(-1.2, 1.2)).Unit
			table.insert(pts, m)
			table.insert(pts, m + bd * len * rand(0.25, 0.45))
		end
		for i = 1, #pts - 1 do
			local a, b = pts[i], pts[i + 1]
			local L = (b - a).Magnitude
			if L > 0.05 and not (i == 5 and #pts > 5) then
				local p = newPart(Vector3.new(width, width, L), CFrame.lookAt((a + b) / 2, b), color, Enum.Material.Neon, nil, GSX.folder())
				p.Name = "GodBolt"
				cleanup(p, life)
			end
		end
	end
	-- glowing shells round a body stretched down its line: { core, gold,
	-- blue } (a SpecialMesh sphere each, a light in the core)
	function GSX.shells(name, specs, light)
		local list = {}
		for i, spec in specs do
			local p = newPart(Vector3.one, CFrame.new(0, -5000, 0), spec[1], Enum.Material.Neon, nil, GSX.folder())
			p.Name = name
			p.Transparency = 1
			local m = Instance.new("SpecialMesh")
			m.MeshType = Enum.MeshType.Sphere
			m.Parent = p
			if i == 1 and light then
				local l = Instance.new("PointLight")
				l.Color = GOLD
				l.Range = light
				l.Brightness = 0
				l.Parent = p
			end
			list[i] = { part = p, mesh = m, k = spec[2], base = spec[3] }
		end
		return list
	end
	function GSX.drop(list)
		for _, sh in list or {} do
			pcall(sh.part.Destroy, sh.part)
		end
	end

	---------------------------------------------------------------------
	-- THE CHARGE on him (every screen: the watcher's, GSX.step)
	---------------------------------------------------------------------
	function GSX.charge(st, k, now, dt)
		local CH = LOOK.Charge or {}
		local root = st.root
		if k <= 0.01 or not root.Parent then
			GSX.unglow(st)
			return
		end
		if not st.godGlow then
			st.godGlow = GSX.shells("GodGlow", { { CORE, 1, 0.42 }, { GOLD, 1.35, 0.7 }, { BLUE, 1.75, 0.85 } }, 26)
			local w = newPart(Vector3.one, CFrame.new(root.Position), CORE, Enum.Material.ForceField, BALL, GSX.folder())
			w.Name = "GodWarp"
			w.Transparency = 1
			st.godWarp = w
		end
		local v = root.AssemblyLinearVelocity
		local d = v.Magnitude > 20 and v.Unit or root.CFrame.UpVector
		local G = CH.Glow or {}
		local at = root.Position + d * 0.6
		local cf = CFrame.lookAt(at, at + d)
		local flick = 0.88 + 0.12 * math.sin(now * 43)
		for _, sh in st.godGlow do
			local w = (G.Width or 5.6) * sh.k * (0.45 + 0.55 * k) * flick
			local l = (G.Length or 11) * sh.k * (0.4 + 0.6 * k)
			sh.mesh.Scale = Vector3.new(w, w, l)
			sh.part.CFrame = cf
			sh.part.Transparency = 1 - (1 - sh.base) * k * (st.mine and (G.Mine or 0.35) or 1)
			local light = sh.part:FindFirstChildOfClass("PointLight")
			if light then
				light.Brightness = 4 * k
			end
		end
		-- the air warping round him: a shimmering bubble, swelling
		local W = CH.Warp or { 8, 40 }
		st.godWarp.Size = Vector3.one * (W[1] + (W[2] - W[1]) * k * (0.94 + 0.06 * math.sin(now * 17)))
		st.godWarp.CFrame = CFrame.new(root.Position)
		-- (not on his own screen: the camera's 14 studs back - the bubble swells
		-- through it, a wall of white and then gone; his is the view tightening)
		st.godWarp.Transparency = st.mine and 1 or 1 - 0.6 * k
		-- lightning forking off him: more of it, and longer, as it builds
		local B = GSX.low() and (CH.LowBolts or { 5, 18 }) or (CH.Bolts or { 10, 40 })
		if now >= (st.next.godBolt or 0) then
			st.next.godBolt = now + 1 / math.max(B[1] + (B[2] - B[1]) * k, 1)
			local L = CH.BoltLen or { 6, 32 }
			local BW = CH.BoltWidth or { 0.2, 0.65 }
			local out = rng:NextUnitVector()
			local from = root.Position + out * rand(1, 2.4)
			GSX.bolt(from, out, (L[1] + (L[2] - L[1]) * k) * rand(0.6, 1), rng:NextNumber() < 0.4 and BLUE or CORE, CH.BoltLife or 0.1, BW[1] + (BW[2] - BW[1]) * k)
			VFX.EngineKit.starSpark(from, { color = GOLD, color2 = CORE, size = rand(1.2, 3) * (0.6 + k), life = 0.08 })
		end
		if now >= (st.next.godCrackle or 0) then
			st.next.godCrackle = now + rand(0.18, 0.32)
			local SN = (DEVc.Sound or {}).God or {}
			VFX.PlaySound("GodCrackle", (not st.mine) and root.Position or nil, (SN.Crackle or 0.7) * (0.5 + 0.5 * k))
		end
		GSX.pull(st, k, now, dt)
	end
	-- dust and debris pulled up off the street toward him (when it's within
	-- Pull.Height under him): chunks lifting off it and flying up at him,
	-- grit, wisps of dust
	function GSX.pull(st, k, now, dt)
		local P = (LOOK.Charge or {}).Pull or {}
		if now >= (st.next.godFloorAt or 0) then
			st.next.godFloorAt = now + 0.25
			local hit = GSX.street(st.root.Position, P.Height or 220)
			st.godFloor = hit and hit.Position or nil
		end
		local g = st.godFloor
		if not g then
			return
		end
		st.godPull = (st.godPull or 0) + (GSX.low() and (P.LowRate or 16) or (P.Rate or 36)) * k * dt
		local made = 0
		while st.godPull >= 1 and made < 6 do
			st.godPull -= 1
			made += 1
			local R = P.Reach or 70
			local a = rand(0, math.pi * 2)
			local from = g + Vector3.new(math.cos(a), 0, math.sin(a)) * rand(4, R) + UP * 0.4
			local to = st.root.Position + rng:NextUnitVector() * rand(3, 9)
			local s = rand(0.4, 1.7)
			local rock = newPart(Vector3.new(s, s * rand(0.5, 0.9), s * rand(0.7, 1.2)), CFrame.new(from) * CFrame.Angles(rand(0, 6), rand(0, 6), rand(0, 6)),
				ROCK:Lerp(Color3.new(0, 0, 0), rand(0, 0.35)), Enum.Material.Slate, nil, GSX.folder())
			rock.Name = "GodDebris"
			local t = rand(0.8, 1.3)
			tween(rock, t, { CFrame = CFrame.new(from:Lerp(to, rand(0.6, 0.9))) * CFrame.Angles(rand(0, 6), rand(0, 6), rand(0, 6)), Transparency = 1 },
				Enum.EasingStyle.Quad, Enum.EasingDirection.In)
			cleanup(rock, t + 0.05)
			if rng:NextNumber() < 0.3 then
				dustPuffs(from, 0.8, 1, VFX.DFX.PAL.DUST, 1, false)
			end
		end
	end
	function GSX.unglow(st)
		GSX.drop(st.godGlow)
		st.godGlow = nil
		if st.godWarp then
			pcall(st.godWarp.Destroy, st.godWarp)
			st.godWarp = nil
		end
	end

	---------------------------------------------------------------------
	-- THE BOOM (every screen)
	---------------------------------------------------------------------
	-- THE SHOCK SPHERE out from him: a shimmering shell (seen across the
	-- city: it's `size` studs across - a part's 2048 at most) and a glow in it
	function GSX.sphere(pos, size, t)
		local s = math.min(size, 2040)
		local shell = newPart(Vector3.one * 8, CFrame.new(pos), CORE, Enum.Material.ForceField, BALL, GSX.folder())
		shell.Name = "GodSphere"
		shell.Transparency = 0.02
		tween(shell, t, { Size = Vector3.one * s }, Enum.EasingStyle.Quart, Enum.EasingDirection.Out)
		tween(shell, t * 0.85, { Transparency = 1 }, Enum.EasingStyle.Quad, Enum.EasingDirection.In, t * 0.3)
		cleanup(shell, t * 1.2 + 0.05)
		local glow = newPart(Vector3.one * 8, CFrame.new(pos), Color3.fromRGB(220, 236, 255), Enum.Material.Neon, BALL, GSX.folder())
		glow.Name = "GodSphere"
		glow.Transparency = 0.6
		tween(glow, t * 0.8, { Size = Vector3.one * s * 0.9, Transparency = 1 }, Enum.EasingStyle.Quart, Enum.EasingDirection.Out)
		cleanup(glow, t * 0.8 + 0.05)
	end
	-- THE RING TORN THROUGH THE CLOUDS: a ring of cloud racing out from over
	-- him (Cloud.Rise over him, at least Cloud.Min over the street), out to
	-- Radius in Time, billowing as it goes, gone
	function GSX.cloudRing(pos)
		local C = (LOOK.Boom or {}).Cloud or {}
		local street = GSX.street(pos, 4000)
		local base = street and street.Position.Y or (pos.Y - 200)
		local c = Vector3.new(pos.X, math.max(pos.Y + (C.Rise or 260), base + (C.Min or 520)), pos.Z)
		local n = GSX.low() and (C.LowPuffs or 16) or (C.Puffs or 32)
		local S = C.Size or { 90, 180 }
		local f = Instance.new("Folder")
		f.Name = "GodCloudRing"
		f.Parent = GSX.folder()
		local puffs = {}
		-- ((round 99 review) lit by the flash: plain white puffs were shaded
		-- grey on their undersides - what the street sees - a ring of grey
		-- sausages. Glowing, see-through (Cloud.Glow), they read as one ring
		-- of light torn through the sky)
		local glow = C.Glow or 0.3
		for i = 1, n do
			local p = newPart(Vector3.one, CFrame.new(c), CLOUD, Enum.Material.Neon, BALL, f)
			p.Name = "GodCloud"
			p.Transparency = 1
			table.insert(puffs, { part = p, a = (i - 1) / n * math.pi * 2 + rand(-0.06, 0.06), s = rand(S[1], S[2]), h = rand(-16, 16) })
		end
		local R, T = C.Radius or 1800, C.Time or 2.6
		GSX.animate(f, T + 0.05, function(t)
			local a = math.clamp(t / T, 0, 1)
			local r = 30 + (R - 30) * (1 - (1 - a) ^ 3)
			local fade = math.clamp((a - 0.4) / 0.6, 0, 1)
			local parts, cfs = {}, {}
			-- (each at least Overlap x the gap to the next: one unbroken ring)
			local gap = 2 * math.pi * r / n * (C.Overlap or 1.5)
			for _, pf in puffs do
				local s = math.min(math.max(pf.s * (0.45 + 0.85 * a), gap * (0.85 + pf.s / (S[2] * 5))), 2000)
				pf.part.Size = Vector3.new(s, s * (C.Flat or 0.4), s * 0.7)
				pf.part.Transparency = glow + (1 - glow) * fade ^ 1.4
				table.insert(parts, pf.part)
				-- (long along the ring, thinner across it)
				table.insert(cfs, CFrame.fromMatrix(c + Vector3.new(math.cos(pf.a), 0, math.sin(pf.a)) * r + UP * pf.h, Vector3.new(-math.sin(pf.a), 0, math.cos(pf.a)), UP))
			end
			GSX.move(parts, cfs)
		end)
		return f
	end
	-- THE SHOCK RING RACING OVER THE STREETS under him (the street within
	-- Street.Depth): a ring of light out to Radius in Time, the dust rolling
	-- out from under him, the street cracked
	function GSX.streetRing(pos)
		local S = (LOOK.Boom or {}).Street or {}
		local hit = GSX.street(pos, S.Depth or 1500)
		if not hit then
			return nil
		end
		local g = hit.Position
		local n = GSX.low() and (S.LowSegments or 20) or (S.Segments or 40)
		local f = Instance.new("Folder")
		f.Name = "GodStreetRing"
		f.Parent = GSX.folder()
		local segs = {}
		for i = 1, n do
			local p = newPart(Vector3.one, CFrame.new(g), CORE, Enum.Material.Neon, nil, f)
			p.Name = "GodStreetRing"
			p.Transparency = 1
			segs[i] = p
		end
		local D = VFX.DFX
		D.skirt(g, D.PAL.DUST, { n = 18, reach = 70, height = 3.6, life = 2.8, from = 8, per = 4 })
		VFX.EngineKit.cracks(g, 40, 14, { life = 8, grow = 0.25 })
		local R, T = S.Radius or 1600, S.Time or 1.6
		GSX.animate(f, T + 0.05, function(t)
			local a = math.clamp(t / T, 0, 1)
			local r = 10 + (R - 10) * (1 - (1 - a) ^ 2.2)
			local len = math.min(2 * math.pi * r / n * 1.12, 2000)
			local parts, cfs = {}, {}
			for i, p in segs do
				local ang = (i - 1) / n * math.pi * 2
				local out = Vector3.new(math.cos(ang), 0, math.sin(ang))
				p.Size = Vector3.new(len, 1.6 + r * 0.004, 3 + r * 0.012)
				p.Transparency = 0.08 + 0.92 * a ^ 1.6
				table.insert(parts, p)
				table.insert(cfs, CFrame.fromMatrix(g + out * r + UP * 1.4, Vector3.new(-out.Z, 0, out.X), UP))
			end
			GSX.move(parts, cfs)
		end)
		return f
	end
	-- GLASS AND LOOSE DEBRIS BLOWN OFF THE BUILDINGS round him: rays out from
	-- where it went off (Glass.Rays, Glass.Range studs); each wall they meet
	-- (not the street) bursts - glass and grit blown on out from it, a puff
	-- of dust - as the shock gets there
	function GSX.glass(pos)
		local G = (LOOK.Boom or {}).Glass or {}
		local map = workspace:FindFirstChild("Map")
		if not map then
			return 0
		end
		local params = RaycastParams.new()
		params.FilterType = Enum.RaycastFilterType.Include
		params.FilterDescendantsInstances = { map }
		local street = { map:FindFirstChild("Roads"), map:FindFirstChild("Ground") }
		local n = GSX.low() and (G.LowRays or 14) or (G.Rays or 28)
		local made = 0
		local base = rand(0, math.pi * 2)
		for i = 1, n do
			if made >= (G.Most or 10) then
				break
			end
			local a = base + (i - 1) / n * math.pi * 2
			local dir = Vector3.new(math.cos(a), rand(-0.35, 0.12), math.sin(a)).Unit
			local hit = workspace:Raycast(pos, dir * (G.Range or 280), params)
			local inst = hit and hit.Instance
			if inst and not ((street[1] and inst:IsDescendantOf(street[1])) or (street[2] and inst:IsDescendantOf(street[2]))) then
				made += 1
				local at = hit.Position + hit.Normal * 0.6
				task.delay((hit.Position - pos).Magnitude / 900, function()
					local D = VFX.DFX
					D.glass(at, (dir + UP * 0.15).Unit, 14)
					D.chunks(at, dir + UP * 0.25, 4, { spread = 0.7, speed = { 30, 80 }, size = { 0.3, 1.1 }, life = 2 })
					dustPuffs(at, 1.3, GSX.low() and 1 or 2, D.PAL.DUST_LIGHT, 1.4, false)
				end)
			end
		end
		return made
	end
	-- all of it, where it went off (pos), d the way he's going
	function GSX.boom(char, pos, d, isLocal)
		local B = LOOK.Boom or {}
		local D = VFX.DFX
		local EK = VFX.EngineKit
		-- the flash, the white-hot core blooming out gold
		D.flashBall(pos, 24, 300, 0.4)
		local core = newPart(Vector3.one * 20, CFrame.new(pos), CORE, Enum.Material.Neon, BALL, GSX.folder())
		core.Name = "GodCore"
		tween(core, 0.2, { Size = Vector3.one * (B.Core or 130) }, Enum.EasingStyle.Quad, Enum.EasingDirection.Out)
		tween(core, 0.7, { Transparency = 1, Color = DEEP }, Enum.EasingStyle.Quad, Enum.EasingDirection.In, 0.18)
		cleanup(core, 0.95)
		GSX.sphere(pos, B.Sphere or 2040, B.SphereTime or 1.25)
		-- the rings (white, gold, electric blue), the disc of air across his
		-- line, the flat one out over everything, the vapor cone, streaks thrown
		-- back, lightning thrown off it
		for i, c in { WHITE, GOLD, BLUE } do
			task.delay((i - 1) * 0.04, function()
				billboardRing(pos, 10, 320 * (1 + 0.12 * (i - 1)), c, 9 - 2 * i, 0.8)
			end)
		end
		local disc = shockDisc(pos, d, 10, 700, 0.85, CORE)
		disc.Transparency = 0.15
		shockDisc(pos, UP, 12, 980, 1.2, GOLD)
		D.vaporCone(char, pos, d, { length = 46, radius = 26, life = 1.1, ride = 0.06, color = CORE })
		streaks(pos, -d, GSX.n(26), 5, 60, 320, CORE, 0.6)
		for _ = 1, GSX.n(12) do
			GSX.bolt(pos + rng:NextUnitVector() * 4, rng:NextUnitVector(), rand(30, 110), rng:NextNumber() < 0.5 and BLUE or CORE, 0.16, 0.9)
		end
		EK.starSpark(pos, { color = CORE, color2 = GOLD, size = 80, life = 0.35 })
		EK.vaporRings(pos - d * 4, -d, 4, { size = 22, gap = 16, life = 1.1, color = CORE })
		GSX.cloudRing(pos)
		GSX.streetRing(pos)
		GSX.glass(pos)
	end
	-- its sound for a pair of ears `dist` studs off (late already): the near
	-- one on where it went off, the far one flat - the crack lost far off, the
	-- low end and the roll carrying
	function GSX.boomSound(pos, dist)
		local ss = VFX.DFX.ss
		VFX.PlaySound("GodBoom", pos, 1 - 0.85 * ss(400, 2400, dist))
		VFX.PlaySound("GodBoomFar", nil, 0.25 + ss(200, 1600, dist))
	end

	---------------------------------------------------------------------
	-- the beats (Effects.DevFly: Kind = ...)
	---------------------------------------------------------------------
	-- THE CHARGE on / off: the look's the watcher's (st.godAt); its sound -
	-- his ears flat, everyone else's on him; let go fast if he lets go
	function GSX.BEATS.GodCharge(char, data, isLocal)
		local D = VFX.DFX
		local st = char and D and D.flying[char]
		local on = data.On == true
		if st then
			st.godAt = on and os.clock() or nil
		end
		local SN = (DEVc.Sound or {}).God or {}
		local M = GSX.mine
		if isLocal then
			D.letGo(M.voice, SN.Abort or 0.2)
			M.voice = nil
			if on then
				M.voice = D.voice("GodCharge", nil, 1)
				D.hold(M.voice)
			end
			return
		end
		-- (a flyer far off may be streamed out of this machine: no body)
		if not char then
			return
		end
		D.letGo(GSX.voices[char], SN.Abort or 0.2)
		GSX.voices[char] = nil
		local root = charParts(char)
		if on and root then
			GSX.voices[char] = D.voice("GodCharge", D.rider(char, root, (GC.Charge or 1.8) + 0.6), 0.85)
		end
	end

	-- THE BOOM
	function GSX.BEATS.God(char, data, isLocal)
		local LSX = VFX.LSX
		local pos, d = LSX.where(char, data)
		if not pos then
			return
		end
		local D = VFX.DFX
		local st = char and D.flying[char]
		if st then
			st.godAt, st.godK = nil, 0
			GSX.unglow(st)
		end
		GSX.boom(char, pos, d, isLocal)
		local B = LOOK.Boom or {}
		local SN = (DEVc.Sound or {}).God or {}
		local F = B.Flash or {}
		if isLocal then
			-- his own: the flash and the rings (HUD), a frame of impact, the
			-- camera thrown; the boom in his head, the world muffled, his ears
			-- ringing, his wind sucked out and roaring back over the top
			if VFX.Hooks.GodBoom then
				VFX.Hooks.GodBoom()
			end
			VFX.Hooks.Flash(WHITE, F[1] or 0.4)
			VFX.ImpactFrame(0.08)
			VFX.Shake(3.2, 0.9)
			D.letGo(GSX.mine.voice, 0.05)
			GSX.mine.voice = nil
			VFX.PlaySound("GodBoom", nil, 1)
			D.muffle(SN.Muffle or 1, { hold = 0.6 })
			D.ring(SN.Ring or 1)
			D.duck("God")
			GSX.mine.boomAt = os.clock()
			return
		end
		if char and GSX.voices[char] then
			D.letGo(GSX.voices[char], 0.05)
			GSX.voices[char] = nil
		end
		-- everyone else: the light at once (by how far), the boom and the shake
		-- late by the distance
		local cam = workspace.CurrentCamera
		local dist = cam and (cam.Focus.Position - pos).Magnitude or 0
		VFX.Hooks.Flash(WHITE, (F[2] or 0.28) + ((F[3] or 0.1) - (F[2] or 0.28)) * math.clamp(dist / (B.Far or 2600), 0, 1))
		task.delay(math.min(dist / (DEVc.SoundSpeed or 980), B.Delay or 3.2), function()
			GSX.boomSound(pos, dist)
			D.nearBoom(dist, SN.Muffle or 1)
			local S = B.Shake or { 6, 3200, 1.4 }
			VFX.ShakeAt(pos, S[1], S[2], S[3])
		end)
	end

	-- OUT OF IT: the closing boom - a flash, gold and blue rings, the air
	-- cracking shut round where he dropped out (his own: the wind ducked a
	-- moment, the HUD's ring); the sheath gone off him
	function GSX.BEATS.GodOut(char, data, isLocal)
		local LSX = VFX.LSX
		local pos, d = LSX.where(char, data)
		if not pos then
			return
		end
		local D = VFX.DFX
		local O = LOOK.Out or {}
		local ring = O.Ring or 110
		D.flashBall(pos, 8, 54, 0.16)
		for i, c in { GOLD, BLUE } do
			billboardRing(pos, 6, ring * (1 + 0.15 * (i - 1)), c, 4, 0.5)
		end
		local disc = shockDisc(pos, d, 6, ring * 1.3, 0.5, CORE)
		disc.Transparency = 0.3
		VFX.EngineKit.vaporRings(pos, d, 3, { size = 8, gap = 8, life = 0.6, color = CORE })
		streaks(pos, d, GSX.n(12), 3, 20, 70, GOLD, 0.35)
		local st = char and D.flying[char]
		if st then
			st.godOutAt = os.clock()
			GSX.off(st)
		end
		if isLocal then
			VFX.PlaySound("GodOut", nil, 1)
			D.duck("GodOut")
			VFX.Shake(1.2, 0.35)
			if VFX.Hooks.GodOut then
				VFX.Hooks.GodOut()
			end
			return
		end
		local cam = workspace.CurrentCamera
		local dist = cam and (cam.Focus.Position - pos).Magnitude or 0
		task.delay(math.min(dist / (DEVc.SoundSpeed or 980), 2), function()
			VFX.PlaySound("GodOut", pos, 1)
			VFX.ShakeAt(pos, 1.6, 400, 0.4)
		end)
	end

	-- A BUILDING HE GOES THROUGH (A: where he went in, B: on through it):
	-- FULL POWER's - blown open: a fireball at the way in and a bigger one
	-- out the far side, the wall bursting in and out, glass, dust left
	-- hanging; else LIGHTSPEED's own hole
	function GSX.BEATS.GodBlast(char, data, isLocal)
		local a = vec(data.A)
		if not a then
			return
		end
		local b = vec(data.B) or a
		local d = dirOf(data.Dir or (b - a), nil)
		local r = math.clamp(tonumber(data.R) or 8, 2, 24)
		local D = VFX.DFX
		if data.Full ~= true then
			if D.BEATS.Smash then
				D.BEATS.Smash(char, { A = a, B = b, Dir = d, R = math.min(r, 9) }, isLocal)
			end
			return
		end
		GSX.blast(a, b, d, r, isLocal)
	end
	function GSX.blast(a, b, d, r, isLocal)
		local BL = LOOK.Blast or {}
		local D = VFX.DFX
		local now = os.clock()
		-- (several in a moment - a run through downtown: the rest lighter)
		local busy = now - (GSX.lastBlast or -1e9) < 0.25
		GSX.lastBlast = now
		local fire = BL.Fire or 50
		for i, spec in { { a, 0.75, 0 }, { (a + b) / 2 + d * r * 0.5, 1, 0.04 } } do
			if i == 1 or not busy then
				task.delay(spec[3], function()
					local at, k = spec[1], spec[2]
					local core = newPart(Vector3.one * fire * 0.3 * k, CFrame.new(at), CORE, Enum.Material.Neon, BALL, GSX.folder())
					core.Name = "GodBlast"
					tween(core, 0.12, { Size = Vector3.one * fire * k }, Enum.EasingStyle.Quad, Enum.EasingDirection.Out)
					tween(core, 0.5, { Transparency = 1, Color = DEEP }, Enum.EasingStyle.Quad, Enum.EasingDirection.In, 0.1)
					cleanup(core, 0.65)
					local shell = newPart(Vector3.one * fire * 0.4 * k, CFrame.new(at), DEEP, Enum.Material.Neon, BALL, GSX.folder())
					shell.Name = "GodBlast"
					shell.Transparency = 0.3
					tween(shell, 0.18, { Size = Vector3.one * fire * 1.35 * k }, Enum.EasingStyle.Quad, Enum.EasingDirection.Out)
					tween(shell, 0.8, { Transparency = 1, Color = SMOKE, CFrame = CFrame.new(at + UP * fire * 0.4) }, Enum.EasingStyle.Quad, Enum.EasingDirection.In, 0.16)
					cleanup(shell, 1)
				end)
			end
		end
		local n = busy and math.floor((BL.Chunks or 18) * 0.4) or (BL.Chunks or 18)
		D.chunks(a, -d + UP * 0.4, math.floor(n * 0.6), { spread = 1, speed = { 50, 130 }, size = { 0.8, 2.6 }, up = 0.4, life = 2.6 })
		D.chunks(b, d + UP * 0.2, n, { spread = 0.7, speed = { 90, 220 }, size = { 0.8, 3.2 }, up = 0.2, life = 3 })
		D.glass(a, -d, busy and 6 or 14)
		if not busy then
			D.glass(b, d, 14)
			billboardRing(b, r, r * 8, GOLD, 5, 0.45)
			D.plume((a + b) / 2, 8, math.clamp(r / 4.5, 1, 3))
		end
		local disc = shockDisc(a, d, r, r * 5, 0.4, CORE)
		disc.Transparency = 0.25
		VFX.PlaySound("GodBlast", a, 1)
		if isLocal then
			VFX.Shake(1.3, 0.3)
		else
			VFX.ShakeAt(a, 2.2, 280, 0.5)
		end
	end

	---------------------------------------------------------------------
	-- AT GODSPEED (the watcher: every flyer on every screen, his own too)
	---------------------------------------------------------------------
	function GSX.step(st, tier, now, dt)
		local god = tier == "God" and not (st.godOutAt and now - st.godOutAt < 0.5)
		local Chg = math.max(GC.Charge or 1.8, 0.1)
		local k = 0
		if st.godAt and not god then
			k = math.clamp((now - st.godAt) / Chg, 0, 1)
			if now - st.godAt > Chg + 1.5 then
				st.godAt = nil -- (a let go that never came)
			end
		end
		st.godK = (st.godK or 0) + (k - (st.godK or 0)) * math.min(1, dt * (k > (st.godK or 0) and 9 or 5))
		GSX.charge(st, st.godK, now, dt)
		if god then
			if not st.godOn then
				st.godOn = true
				st.godLast, st.godWakeAt, st.godWakeG = st.root.Position, nil, nil
				st.next.godChain = now + 0.1
			end
			GSX.sheath(st, now)
			if st.mine then
				GSX.uncone(st)
			else
				GSX.cone(st)
			end
			GSX.chain(st, now)
			GSX.trail(st)
			GSX.wake(st)
		elseif st.godOn then
			GSX.off(st)
		end
	end
	-- he's out of it (or gone): the sheath and the cone off him (the contrail stays)
	function GSX.off(st)
		st.godOn, st.godTrailLow = nil, nil
		GSX.drop(st.godShells)
		st.godShells = nil
		GSX.uncone(st)
		st.godLast, st.godWakeAt, st.godWakeG, st.godTrailPend = nil, nil, nil, nil
	end
	function GSX.untrack(st)
		GSX.off(st)
		GSX.unglow(st)
		st.godAt, st.godK = nil, 0
		if st.char and GSX.voices[st.char] then
			VFX.DFX.letGo(GSX.voices[st.char], 0.15)
			GSX.voices[st.char] = nil
		end
	end
	-- THE PLASMA SHEATH: three shells round him stretched down his line - a
	-- white-gold core, the gold, an electric-blue edge (his own screen:
	-- fainter, the camera's behind it)
	function GSX.sheath(st, now)
		local S = LOOK.Sheath or {}
		local root = st.root
		if not st.godShells then
			st.godShells = GSX.shells("GodSheath", { { CORE, 1, 0.22 }, { GOLD, 1.3, 0.55 }, { BLUE, 1.65, 0.72 } }, 40)
		end
		local v = root.AssemblyLinearVelocity
		local d = v.Magnitude > 20 and v.Unit or root.CFrame.UpVector
		local at = root.Position + d * (S.Ahead or 1.6)
		local cf = CFrame.lookAt(at, at + d)
		for i, sh in st.godShells do
			local flick = 0.92 + 0.08 * math.sin(now * (29 + 7 * i) + i)
			local w = (S.Width or 6) * sh.k * flick
			sh.mesh.Scale = Vector3.new(w, w, (S.Length or 15) * sh.k)
			sh.part.CFrame = cf
			sh.part.Transparency = 1 - (1 - sh.base) * (st.mine and (S.Mine or 0.28) or 1)
			local light = sh.part:FindFirstChildOfClass("PointLight")
			if light then
				light.Brightness = 5
			end
		end
	end
	-- THE SHOCK CONE: the vapor shell flaring back off his shoulders, riding
	-- him (Cone: Length long, Radius round at its back; triangles of two
	-- wedges each, as the boom's cone - the flight's DFX.vaporCone)
	function GSX.cone(st)
		local C = LOOK.Cone or {}
		local root = st.root
		if not st.godCone then
			local n = GSX.low() and (C.LowFacets or 6) or (C.Facets or 10)
			local L, R = C.Length or 46, C.Radius or 17
			local facets = {}
			local function add(cf, size)
				local w = Instance.new("WedgePart")
				w.Name = "GodCone"
				w.Anchored = true
				w.CanCollide = false
				w.CanQuery = false
				w.CanTouch = false
				w.CastShadow = false
				w.Color = CORE
				w.Material = Enum.Material.SmoothPlastic
				w.Transparency = C.Transparency or 0.7
				w.Size = size
				w.Parent = GSX.folder()
				table.insert(facets, { part = w, off = cf })
			end
			local function tri(a, b, c)
				local ab, ac, bc = b - a, c - a, c - b
				local abd, acd, bcd = ab:Dot(ab), ac:Dot(ac), bc:Dot(bc)
				if abd > acd and abd > bcd then
					c, a = a, c
				elseif acd > bcd and acd > abd then
					a, b = b, a
				end
				ab, ac, bc = b - a, c - a, c - b
				local right = ac:Cross(ab).Unit
				local up = bc:Cross(right).Unit
				local back = bc.Unit
				local height = math.abs(ab:Dot(up))
				add(CFrame.fromMatrix((a + b) / 2, right, up, back), Vector3.new(0.05, height, math.abs(ab:Dot(back))))
				add(CFrame.fromMatrix((a + c) / 2, -right, up, -back), Vector3.new(0.05, height, math.abs(ac:Dot(back))))
			end
			for i = 0, n - 1 do
				local a0, a1 = i / n * math.pi * 2, (i + 1) / n * math.pi * 2
				tri(Vector3.zero, Vector3.new(math.cos(a0) * R, math.sin(a0) * R, L), Vector3.new(math.cos(a1) * R, math.sin(a1) * R, L))
			end
			st.godCone = facets
		end
		local v = root.AssemblyLinearVelocity
		local d = v.Magnitude > 20 and v.Unit or root.CFrame.UpVector
		local tip = root.Position + d * 3
		local held = CFrame.lookAt(tip, tip + d) * CFrame.Angles(0, 0, os.clock() * 0.7)
		local parts, cfs = {}, {}
		for _, f in st.godCone do
			table.insert(parts, f.part)
			table.insert(cfs, held * f.off)
		end
		GSX.move(parts, cfs)
	end
	function GSX.uncone(st)
		for _, f in st.godCone or {} do
			pcall(f.part.Destroy, f.part)
		end
		st.godCone = nil
	end
	-- THE BOOMS IN A CHAIN behind him (one every Chain.Every s): a ring, the
	-- air cracking round it, a flash - his ears a thump behind him, everyone
	-- else's late by the distance
	function GSX.chain(st, now)
		local C = LOOK.Chain or {}
		if now < (st.next.godChain or 0) then
			return
		end
		st.next.godChain = now + (GSX.low() and (C.LowEvery or 0.35) or (C.Every or 0.2))
		local SN = (DEVc.Sound or {}).God or {}
		-- ((round 99 review) his own screen: the thump behind him, nothing
		-- drawn. Each went off 8 studs behind him - between his camera (~22
		-- back) and him - and was left behind the next frame: one frame of a
		-- flash ball, a disc and a ring over where he's going, five times a
		-- second, a strobe)
		if st.mine then
			VFX.PlaySound("GodChain", nil, SN.Chain or 0.45)
			return
		end
		local root = st.root
		local v = root.AssemblyLinearVelocity
		local d = v.Magnitude > 20 and v.Unit or root.CFrame.UpVector
		local pos = root.Position - d * 8
		local ring = C.Ring or 80
		billboardRing(pos, 8, ring, WHITE, 5, 0.45)
		local disc = shockDisc(pos, d, 6, ring * 1.3, 0.5, CORE)
		disc.Transparency = 0.35
		disc.Name = "GodChain"
		VFX.DFX.flashBall(pos, 6, 34, 0.12)
		VFX.EngineKit.vaporRings(pos, d, 1, { size = ring * 0.16, life = 0.5, color = CORE })
		local cam = workspace.CurrentCamera
		local dist = cam and (cam.Focus.Position - pos).Magnitude or 0
		if dist <= (C.Range or 1800) then
			task.delay(math.min(dist / (DEVc.SoundSpeed or 980), 2), function()
				VFX.PlaySound("GodChain", pos, 1)
				VFX.ShakeAt(pos, 1.1, 300, 0.3)
			end)
		end
	end
	-- THE CONTRAIL: a piece every Contrail.Every studs he goes, laid thick and
	-- spreading as it hangs there (Life s), a gold core along it a moment;
	-- every screen's own (every flyer's: at most Max pieces, the oldest let go
	-- first). Only up in the sky: within Contrail.Low studs of the street (the
	-- wake's down there) none - (round 99 renders) a pass down a street left it
	-- filled with a white tube for its whole Life, on every screen
	function GSX.trail(st)
		local T = LOOK.Contrail or {}
		local p = st.root.Position
		local last = st.godLast
		if not last then
			st.godLast = p
			return
		end
		local L = (p - last).Magnitude
		if L > 2500 then
			st.godLast = p -- (a jump: streamed back in, respawned - nothing laid across it)
			return
		end
		if L < (T.Every or 60) then
			return
		end
		st.godLast = p
		local wasLow = st.godTrailLow
		st.godTrailLow = GSX.street(p, T.Low or 150) ~= nil
		if st.godTrailLow or wasLow then
			st.godTrailPend = nil
			return
		end
		-- ((round 99 review) his own screen: a piece behind. The newest ran
		-- from his body back past his camera (~22 studs behind, a few over his
		-- line, just outside its first 5 studs): a grey pipe from under the
		-- camera up to him, every frame - LIGHTSPEED's own streak isn't drawn
		-- on his screen at all)
		local a, b = last, p
		if st.mine then
			local pend = st.godTrailPend
			st.godTrailPend = { last, p }
			if not pend then
				return
			end
			a, b = pend[1], pend[2]
			L = (b - a).Magnitude
		end
		GSX.piece(a, b)
		local Co = T.Core or {}
		local w = Co.Width or 3
		local core = newPart(Vector3.new(L, w, w), CFrame.lookAt((a + b) / 2, b) * CFrame.Angles(0, math.rad(90), 0), GOLD, Enum.Material.Neon, CYL, GSX.folder())
		core.Name = "GodTrailCore"
		core.Transparency = 0.1
		tween(core, Co.Life or 1.2, { Transparency = 1, Size = Vector3.new(L, w * 0.3, w * 0.3) }, Enum.EasingStyle.Quad, Enum.EasingDirection.In)
		cleanup(core, (Co.Life or 1.2) + 0.05)
	end
	function GSX.piece(a, b)
		local T = LOOK.Contrail or {}
		local W = T.Width or { 18, 44 }
		local L = (b - a).Magnitude
		if L < 1 then
			return nil
		end
		local w0 = (T.Fresh or {}).Width or W[1]
		local p = newPart(Vector3.new(L + w0 * 0.5, w0, w0), CFrame.lookAt((a + b) / 2, b) * CFrame.Angles(0, math.rad(90), 0), CLOUD, Enum.Material.SmoothPlastic, CYL, GSX.folder())
		p.Name = "GodContrail"
		p.Transparency = 0.18
		table.insert(GSX.contrail, { part = p, t0 = os.clock(), L = L })
		local most = GSX.low() and (T.LowMax or 70) or (T.Max or 140)
		while #GSX.contrail > most do
			local old = table.remove(GSX.contrail, 1)
			pcall(old.part.Destroy, old.part)
		end
		GSX.contrailLoop()
		return p
	end
	-- the contrail hanging in the sky: spreading out, thinning, gone (a few
	-- times a second is plenty for something that slow)
	function GSX.contrailLoop()
		if GSX.contrailConn then
			return
		end
		GSX.contrailConn = RunService.Heartbeat:Connect(function()
			local now = os.clock()
			if now < (GSX.contrailAt or 0) then
				return
			end
			GSX.contrailAt = now + 0.06
			local T = LOOK.Contrail or {}
			local W = T.Width or { 18, 44 }
			local life = T.Life or 14
			local Fr = T.Fresh or {}
			local w0, grow = Fr.Width or W[1], math.max(Fr.Time or 0.35, 0.01)
			local i = 1
			while i <= #GSX.contrail do
				local c = GSX.contrail[i]
				local age = now - c.t0
				local a = age / life
				if a >= 1 or not c.part.Parent then
					pcall(c.part.Destroy, c.part)
					table.remove(GSX.contrail, i)
				else
					-- (thin right behind him, billowing out to Width's first in
					-- Fresh.Time, then spreading slowly over its Life)
					local w = W[1] + (W[2] - W[1]) * (1 - (1 - a) ^ 2)
					if age < grow then
						w = w0 + (w - w0) * (1 - (1 - age / grow) ^ 2)
					end
					c.part.Size = Vector3.new(c.L + w * 0.5, w, w)
					c.part.Transparency = 0.18 + 0.82 * a ^ 2.2
					i += 1
				end
			end
			if #GSX.contrail == 0 and GSX.contrailConn then
				GSX.contrailConn:Disconnect()
				GSX.contrailConn = nil
			end
		end)
	end
	-- THE STREET TORN UP under him (within Wake.Height of it: a burst every
	-- Wake.Every studs he goes, never more than Wake.Most a second) - a
	-- furrow torn down the street from the last one, slabs and grit thrown
	-- up, the street cracked, dust rolling. ((round 99 review) at 3000
	-- studs/s Every alone was a burst every frame on every screen - ~40 parts
	-- each, its cracks living 7 s: 500 of them after a 0.3 s pass down a
	-- street. Now ~20 a burst, 14 a second at most, and one furrow part
	-- carries the line between them)
	function GSX.wake(st)
		local W = LOOK.Wake or {}
		local p = st.root.Position
		local v = st.root.AssemblyLinearVelocity
		local every = math.max(W.Every or 45, v.Magnitude / math.max(W.Most or 14, 1))
		local last = st.godWakeAt
		if last and (p - last).Magnitude < every then
			return
		end
		st.godWakeAt = p
		local hit = GSX.street(p, W.Height or 70)
		if not hit then
			st.godWakeG = nil
			return
		end
		local g = hit.Position
		local fd = Vector3.new(v.X, 0, v.Z)
		fd = fd.Magnitude > 1 and fd.Unit or Vector3.new(0, 0, -1)
		local k = math.clamp(1.2 - (p.Y - g.Y) / (W.Height or 70), 0.25, 1)
		local D = VFX.DFX
		-- the furrow: from the last burst's spot on the street to this one (one
		-- part the whole stretch, scorched dark, a hot seam down it a moment)
		local from = st.godWakeG
		st.godWakeG = g
		local run = from and Vector3.new(g.X - from.X, 0, g.Z - from.Z)
		if run and run.Magnitude > 2 and run.Magnitude < every * 1.8 and math.abs(g.Y - from.Y) < 6 then
			local FU = W.Furrow or {}
			local len = run.Magnitude
			local mid = Vector3.new((g.X + from.X) / 2, math.max(g.Y, from.Y) + 0.08, (g.Z + from.Z) / 2)
			local cf = CFrame.lookAt(mid, mid + run.Unit)
			local wd = (FU.Width or 8) * (0.55 + 0.45 * k)
			local life = FU.Life or 6
			local furrow = newPart(Vector3.new(wd, 0.2, len + wd * 0.5), cf, D.PAL.CRATER, Enum.Material.Slate, nil, GSX.folder())
			furrow.Name = "GodFurrow"
			furrow.Transparency = 0.08
			tween(furrow, 1.2, { Transparency = 1 }, Enum.EasingStyle.Quad, Enum.EasingDirection.In, math.max(life - 1.2, 0))
			cleanup(furrow, life + 0.05)
			local seam = newPart(Vector3.new(wd * 0.28, 0.24, len), cf + UP * 0.03, DEEP, Enum.Material.Neon, nil, GSX.folder())
			seam.Name = "GodFurrow"
			tween(seam, FU.Seam or 0.7, { Transparency = 1, Color = SMOKE }, Enum.EasingStyle.Quad, Enum.EasingDirection.In)
			cleanup(seam, (FU.Seam or 0.7) + 0.05)
		end
		D.chunks(g + UP * 0.6, UP + fd * 0.5, math.max(math.floor((W.Chunks or 5) * k + 0.5), 1), { spread = 0.8, speed = { 50, 50 + 100 * k }, size = { 0.6, 0.6 + 1.8 * k }, up = 0.9, life = 2.4 })
		if k > 0.5 then
			local right = fd:Cross(UP)
			for _, side in { 1, -1 } do
				D.chunks(g + right * side * 4, right * side + UP * 0.8, 1, { speed = { 40, 90 }, size = { 0.5, 1.4 }, life = 2 })
			end
		end
		VFX.EngineKit.cracks(g, 8 + 12 * k, W.Cracks or 3, { life = W.CrackLife or 3.5, grow = 0.15, crater = false })
		dustPuffs(g + UP, 1.6 * k, GSX.low() and 1 or 2, D.dustOf(hit), 1.6, false)
		VFX.PlaySound("GodWake", g, k)
	end

	---------------------------------------------------------------------
	-- HIS OWN SCREEN (from the flight's DFX.frame every frame)
	---------------------------------------------------------------------
	-- the colour pushed hot and bloomed (the charge brings some of it in),
	-- power streaks streaming past him at GODSPEED
	function GSX.frame(_char, root, _speed, tier, dt, cam)
		local M = GSX.mine
		local want = tier == "God" and 1 or 0
		M.k += (want - M.k) * math.min(1, dt * (want > M.k and 8 or 6))
		if want == 0 and M.k < 0.01 then
			M.k = 0
		end
		local level = math.max(M.k, (M.charge or 0) * 0.55)
		local G = LOOK.Grade or {}
		if level > 0.01 then
			if not (M.grade and M.grade.Parent) then
				M.grade = Instance.new("ColorCorrectionEffect")
				M.grade.Name = "DevFlyGod"
				M.grade.Parent = Lit
				M.bloom = Instance.new("BloomEffect")
				M.bloom.Name = "DevFlyGodBloom"
				M.bloom.Intensity = 0
				M.bloom.Size = 36
				M.bloom.Threshold = G.Threshold or 0.9
				M.bloom.Parent = Lit
			end
			M.grade.Saturation = (G.Saturation or 0.22) * level
			M.grade.Contrast = (G.Contrast or 0.2) * level
			M.grade.Brightness = (G.Brightness or 0.03) * level
			M.grade.TintColor = WHITE:Lerp(G.Tint or Color3.fromRGB(255, 240, 220), level)
			M.bloom.Intensity = (G.Bloom or 1.1) * level
		elseif M.grade then
			GSX.ungrade()
		end
		GSX.streaks(cam, root, root.AssemblyLinearVelocity, M.k)
	end
	function GSX.ungrade()
		local M = GSX.mine
		for _, key in { "grade", "bloom" } do
			if M[key] then
				pcall(M[key].Destroy, M[key])
				M[key] = nil
			end
		end
	end
	-- THE POWER STREAKS: long lines of gold, white and electric blue hung in a
	-- tunnel round his line out ahead of him, each put back out ahead once
	-- he's past it (a pixel or so thick wherever they are)
	function GSX.streaks(cam, root, v, k)
		local M = GSX.mine
		local S = LOOK.Streaks or {}
		local want = (k > 0.05 and cam and root and v.Magnitude > 200) and GSX.n(S.Count or 44) or 0
		while #M.streaks > want do
			local gone = table.remove(M.streaks)
			pcall(gone.part.Destroy, gone.part)
		end
		if want == 0 then
			return
		end
		local d = v.Unit
		local camPos = cam.CFrame.Position
		local right = d:Cross(math.abs(d.Y) < 0.95 and UP or Vector3.new(1, 0, 0)).Unit
		local up2 = right:Cross(d).Unit
		local R, A, Ln = S.Round or { 14, 90 }, S.Ahead or { 140, 900 }, S.Len or { 70, 170 }
		local colors = { GOLD, CORE, BLUE }
		local function place(s, far)
			local a = rand(0, math.pi * 2)
			s.at = root.Position + d * (far and rand((A[1] + A[2]) / 2, A[2]) or rand(A[1], A[2])) + (right * math.cos(a) + up2 * math.sin(a)) * rand(R[1], R[2])
			s.len = rand(Ln[1], Ln[2])
		end
		while #M.streaks < want do
			local p = newPart(Vector3.new(0.12, 0.12, 1), CFrame.new(root.Position), colors[#M.streaks % 3 + 1], Enum.Material.Neon, nil, GSX.folder())
			p.Name = "GodStreak"
			local s = { part = p }
			place(s, false)
			table.insert(M.streaks, s)
		end
		for _, s in M.streaks do
			if (s.at - camPos):Dot(d) < -5 or (s.at - root.Position).Magnitude > A[2] + 300 then
				place(s, true)
			end
			local wd = math.max(0.12, (s.at - camPos).Magnitude * (S.Width or 0.003))
			s.part.Size = Vector3.new(wd, wd, s.len * (0.3 + 0.7 * k))
			s.part.CFrame = CFrame.lookAt(s.at, s.at + d)
			s.part.Transparency = 1 - 0.8 * k
		end
	end
	-- his screen's GODSPEED, all of it gone (the flight's over: DFX.stopMine)
	function GSX.stopMine(fade)
		local M = GSX.mine
		GSX.ungrade()
		for _, s in M.streaks do
			pcall(s.part.Destroy, s.part)
		end
		table.clear(M.streaks)
		M.k, M.charge, M.boomAt = 0, 0, nil
		if M.voice and VFX.DFX then
			VFX.DFX.letGo(M.voice, fade or 0.15)
		end
		M.voice = nil
	end

	---------------------------------------------------------------------
	-- ((round 99, craters) GODSPEED's crater - VFX.CTX calls in here for
	-- its own over the crater's: Config.DevFlight.Crater.God): the crater
	-- glowing white-hot and cooling, gold and electric-blue rings racing out
	-- over the street, lightning thrown up out of it, the deepest boom of
	-- all under the crater's own
	---------------------------------------------------------------------
	function GSX.impact(g, isLocal, near)
		local IL = ((DEVc.Crater or {}).God or {}).Look or {}
		local Gl = IL.Glow or {}
		local R, life = Gl.Radius or 52, Gl.Life or 9
		local glow = newPart(Vector3.new(1.2, R * 2, R * 2), CFrame.new(g + UP * 0.4) * CFrame.Angles(0, 0, math.rad(90)), CORE, Enum.Material.Neon, CYL, GSX.folder())
		glow.Name = "GodCraterGlow"
		tween(glow, 0.8, { Color = DEEP }, Enum.EasingStyle.Quad, Enum.EasingDirection.Out, 0.3)
		tween(glow, life, { Transparency = 1, Color = Color3.fromRGB(120, 40, 20), Size = Vector3.new(1.2, R * 1.4, R * 1.4) }, Enum.EasingStyle.Quad, Enum.EasingDirection.In, 1)
		cleanup(glow, life + 1.1)
		local hot = newPart(Vector3.new(1.4, R * 1.1, R * 1.1), CFrame.new(g + UP * 0.6) * CFrame.Angles(0, 0, math.rad(90)), WHITE, Enum.Material.Neon, CYL, GSX.folder())
		hot.Name = "GodCraterGlow"
		tween(hot, life * 0.6, { Transparency = 1, Color = GOLD, Size = Vector3.new(1.4, R * 0.4, R * 0.4) }, Enum.EasingStyle.Quad, Enum.EasingDirection.In, 0.4)
		cleanup(hot, life * 0.6 + 0.5)
		for i, c in { GOLD, WHITE, BLUE } do
			task.delay((i - 1) * 0.06, function()
				local disc = shockDisc(g + UP * (1 + i * 0.3), UP, 30, 1400 * (1 + 0.06 * (i - 1)), 1.2, c)
				disc.Transparency = 0.1
			end)
		end
		for _ = 1, GSX.n(16) do
			GSX.bolt(g + UP * 4, (UP * 1.4 + rng:NextUnitVector()).Unit, rand(60, 220), rng:NextNumber() < 0.5 and BLUE or CORE, 0.2, 1.4)
		end
		VFX.EngineKit.starSpark(g + UP * 12, { color = CORE, color2 = GOLD, size = 110, life = 0.4 })
		if isLocal then
			VFX.PlaySound("GodImpact", nil, 1.1)
		else
			task.delay(math.min((tonumber(near) or 0) / (DEVc.SoundSpeed or 980), 1.6), function()
				VFX.ST.far("GodImpact", g, 1.1)
			end)
		end
	end
end)()

---------------------------------------------------------------------------
-- (round 92) tweaks - PLUME CYCLONE WITHOUT A HITBOX (Config.CycloneLook;
-- the owner: "make plume cyclone hitbox not visible to other players").
-- Hawks' cyclone (VFX.HK's HK.cyclone - the ult's TEMPEST too) stood two
-- ForceField cylinders round him and laid a ForceField disc on the street,
-- the size of the shred radius, on every screen: a hitbox. They're gone.
-- Its wind is wind now (CL.wind): thin ribbons of air whipping round him
-- (Beams bent into arcs, facing the camera), each living a moment - in,
-- climbing, out - then back somewhere else, so nothing ever stands there
-- as a shape. On his own screen only (CL.reach), the way a held move's
-- marker is: a faint dashed ring on the street at the reach. And SCARLET
-- RAIN's red disc on the street (its whole area, on every screen) is his
-- screen's only now (CL.rainDisc).
---------------------------------------------------------------------------
do
	local CL = {}
	VFX.CycloneLook = CL
	function CL.cfg()
		return Config.CycloneLook or {}
	end
	-- his own screen? (his own cast says so - isLocal; the server's broadcast
	-- skips him, but his own body on this screen counts too)
	function CL.mine(char, isLocal)
		local me = Players.LocalPlayer
		return isLocal == true or (me ~= nil and char ~= nil and me.Character == char)
	end
	-- SCARLET RAIN's disc on this screen?
	function CL.rainDisc(char)
		local mode = CL.cfg().RainDisc
		if mode == "All" then
			return true
		end
		return mode == "Caster" and CL.mine(char)
	end

	-- THE WIND: arcs of air round c (R: the move's Radius). Returns
	-- { step(c, now), stop(fade) } - its owner moves it every frame
	function CL.wind(c, R, low)
		local W = CL.cfg().Wind or {}
		local n = low and (W.LowArcs or 3) or (W.Arcs or 6)
		local colors = W.Color or { Color3.new(1, 1, 1), Color3.fromRGB(255, 196, 188) }
		local holder = newPart(Vector3.one * 0.2, CFrame.new(c), colors[1])
		holder.Name = "HawksWind"
		holder.Transparency = 1
		local op = math.clamp(W.Opacity or 0.55, 0, 1)
		local lifeA = (W.Life or {})[1] or 0.42
		local lifeB = math.max((W.Life or {})[2] or 0.72, lifeA)
		local arcs = {}
		local self = { holder = holder, arcs = arcs, stopped = false }
		-- a new arc somewhere round him (t0: when its life started)
		local function respawn(a, t0)
			a.t0 = t0
			a.life = rand(lifeA, lifeB)
			a.r = R * rand(W.RadiusMin or 0.5, W.RadiusMax or 1.05)
			a.h = rand(W.HeightMin or -1.8, W.HeightMax or 3.6)
			a.ang = rand(0, math.pi * 2)
			a.span = (W.Span or 1.35) * rand(0.8, 1.15)
		end
		local now = os.clock()
		for i = 1, n do
			local a0, a1 = Instance.new("Attachment"), Instance.new("Attachment")
			a0.Parent, a1.Parent = holder, holder
			local b = Instance.new("Beam")
			b.Name = "HawksWind"
			b.Attachment0, b.Attachment1 = a0, a1
			b.Color = ColorSequence.new(colors[1], colors[2] or colors[1])
			b.Transparency = NumberSequence.new({
				NumberSequenceKeypoint.new(0, 1), NumberSequenceKeypoint.new(0.2, 1 - op),
				NumberSequenceKeypoint.new(0.65, 1 - op * 0.8), NumberSequenceKeypoint.new(1, 1),
			})
			b.LightEmission = W.Emission or 0.55
			b.LightInfluence = 0
			b.FaceCamera = true
			b.Segments = 10
			b.Width0, b.Width1 = 0, 0
			b.Parent = holder
			local a = { a0 = a0, a1 = a1, beam = b, dir = (i % math.max(W.Reverse or 3, 1) == 0) and -1 or 1 }
			-- (staggered: they don't all come and go together)
			respawn(a, now - (i - 1) / n * lifeA)
			arcs[i] = a
		end
		function self.step(at, t)
			if self.stopped or not holder.Parent then
				return
			end
			holder.CFrame = CFrame.new(at)
			local spin, climb, rise, width = W.Spin or 7.5, W.Climb or 1.2, W.Rise or 1.4, W.Width or 0.6
			for _, a in arcs do
				local age = t - a.t0
				if age >= a.life or age < 0 then
					respawn(a, t)
					age = 0
				end
				local u = age / a.life
				local env = math.sin(math.pi * u) -- (0, up to 1, back to 0)
				local th0 = a.ang + a.dir * spin * age
				local th1 = th0 + a.dir * a.span
				local h = a.h + rise * u
				-- (the tangents lie flat and are never zero: fromMatrix is safe)
				local t0 = Vector3.new(-math.sin(th0), 0, math.cos(th0)) * a.dir
				local t1 = Vector3.new(-math.sin(th1), 0, math.cos(th1)) * a.dir
				a.a0.CFrame = CFrame.fromMatrix(Vector3.new(math.cos(th0) * a.r, h, math.sin(th0) * a.r), t0, UP)
				a.a1.CFrame = CFrame.fromMatrix(Vector3.new(math.cos(th1) * a.r, h + climb, math.sin(th1) * a.r), t1, UP)
				-- (a Bezier's handles for a circular arc: 4/3 tan(span/4) r)
				local cs = 4 / 3 * math.tan(a.span / 4) * a.r
				a.beam.CurveSize0, a.beam.CurveSize1 = cs, cs
				a.beam.Width0, a.beam.Width1 = width * env, width * env * 0.35
			end
		end
		function self.stop(fade)
			if self.stopped then
				return
			end
			self.stopped = true
			fade = fade or 0.2
			for _, a in arcs do
				tween(a.beam, fade, { Width0 = 0, Width1 = 0 })
			end
			task.delay(fade, function()
				for _, a in arcs do
					if a.beam.Parent then
						a.beam.Enabled = false
					end
				end
			end)
			cleanup(holder, fade + 0.05)
		end
		self.step(c, now)
		return self
	end

	-- HIS REACH (his screen only): a faint dashed ring round c at R, on the
	-- street (y: the street's height) or round his middle in the air (y nil).
	-- Returns { step(c, now), stop(fade) }, or nil when it's off
	function CL.reach(c, R, y)
		local K = CL.cfg().Reach or {}
		if K.On == false then
			return nil
		end
		local n = math.max(K.Dashes or 24, 3)
		local len = 2 * math.pi * R / n * math.clamp(K.Fill or 0.5, 0.05, 1)
		local th = K.Thickness or 0.16
		local dashes = {}
		for i = 1, n do
			local d = newPart(Vector3.new(th, 0.05, len), CFrame.new(c), K.Color or Color3.fromRGB(255, 120, 110), Enum.Material.Neon)
			d.Name = "HawksReach"
			d.Transparency = 1
			tween(d, K.FadeIn or 0.2, { Transparency = K.Transparency or 0.55 })
			dashes[i] = d
		end
		local self = { dashes = dashes, stopped = false, t0 = os.clock() }
		function self.step(at, t)
			if self.stopped then
				return
			end
			local level = y and (y + (K.Lift or 0.12)) or (at.Y - (K.AirDrop or 0.5))
			local turn = (K.Spin or 0.6) * (t - self.t0)
			for i, d in dashes do
				local a = turn + (i - 1) / n * math.pi * 2
				local p = Vector3.new(at.X + math.cos(a) * R, level, at.Z + math.sin(a) * R)
				-- (each dash lies along the ring: its length - Z - on the tangent)
				d.CFrame = CFrame.fromMatrix(p, Vector3.new(math.cos(a), 0, math.sin(a)), UP)
			end
		end
		function self.stop(fade)
			if self.stopped then
				return
			end
			self.stopped = true
			for _, d in dashes do
				tween(d, fade or 0.2, { Transparency = 1 })
				cleanup(d, (fade or 0.2) + 0.05)
			end
		end
		self.step(c, os.clock())
		return self
	end
end

---------------------------------------------------------------------------
-- (round 92) BAKUGO: MAX CAPACITY on every screen (VFX.GB; Config.Quirks.
-- Explosion.Extra, the server's Kit.GB) - his 4th, the Grenadier Bracer's
-- pin (chapter 10, the first battle trial).
--   The windup (Effects.MaxCapacity, his press): he plants his feet and
--   brings the right gauntlet up across his chest, the left hand on its pin
--   ring (MoveMaxCapacity); it fills to bursting - the grooves between the
--   green go white-hot (Bakugo's cosmetic gauge, VFX.CosA), a ball of light
--   swells at his fist, it crackles and vents steam, the street's dust
--   skitters away from his feet; at Pin he rips the pin out (the real ring
--   hides, a copy goes spinning off and bounces in the street, a bright
--   ting) and swings the arm out dead straight at them, held there. On his
--   own screen the view tightens, a faint line shows where it'll go and his
--   body follows his aim (it streams up: LiveAim). In the air he hangs there
--   for it.
--   The blast (Effects.MaxCapacityBlast, the server's word at Windup, to
--   everyone, his own screen too): a white flash at the fist, a torrent of
--   cel fire (VFX.BLAZE.jet, in his colours) down the aim, its white-hot
--   core, a chain of explosions racing out with its front (Speed), shock
--   rings marching out along it, fire streaks; the street scorched and torn
--   up under it, dust rolling off both sides; the wall it meets blown out (a
--   fireball), from the air a crater where it lands; a tunnel of smoke left
--   hanging. He's thrown back by it (MoveMaxCapacityFire; his own machine
--   skids him back on his braced leg, or throws him back and up in the air)
--   and the gauntlet vents, red-hot and steaming. His screen: an impact frame,
--   the view kicked out and the camera jerked up by the recoil, a big shake,
--   "MAX CAPACITY!!"; anyone near the line: a flash and an impact frame;
--   everyone: the shake by how far off they are.
--   Knocked out of it (the server's MaxCapacityFizzle): it sputters out.
-- (A function of its own: the main chunk is at its local limit.)
---------------------------------------------------------------------------
;(function()
	local GB = { going = {} } -- (going: [char] = his windup on this screen - plain, cleared by its own stops)
	VFX.GB = GB
	-- the blast's fire (VFX.BLAZE's palette shape): white-hot at the heart,
	-- his yellow, orange, a red edge
	GB.PAL = {
		heart = Color3.fromRGB(255, 252, 236), hot = Color3.fromRGB(255, 236, 90), body = Color3.fromRGB(255, 164, 40),
		edge = Color3.fromRGB(240, 90, 24), tip = Color3.fromRGB(170, 44, 14), soot = Color3.fromRGB(56, 46, 42),
		fleck = Color3.fromRGB(40, 30, 26), light = Color3.fromRGB(255, 190, 90), ember = Color3.fromRGB(255, 226, 120), ember2 = Color3.fromRGB(255, 110, 30),
	}
	GB.SCORCH = Color3.fromRGB(36, 28, 26)
	GB.DUST = Color3.fromRGB(176, 166, 158)
	GB.HOT = Color3.fromRGB(255, 120, 50)

	function GB.spec()
		return Config.FindAbilityById("MaxCapacity") or {}
	end
	function GB.low()
		return VFX.EngineKit ~= nil and VFX.EngineKit.lowEnd() == true
	end
	function GB.mine(char)
		local me = Players.LocalPlayer
		return me ~= nil and char ~= nil and me.Character == char
	end
	-- a usable direction (never NaN, never zero), else nil
	function GB.unit(v)
		if typeof(v) == "Vector3" and v == v and v.Magnitude > 0.01 then
			return v.Unit
		end
		return nil
	end
	-- the look's numbers (Config ... Extra.Look), whatever's missing filled in
	function GB.look(spec)
		local L = spec.Look or {}
		return {
			Booms = L.Booms or 6, Rings = L.Rings or 8, JetLife = L.JetLife or 0.42, Fov = L.Fov or { -7, 16 },
			Kick = L.Kick or 4, Shake = L.Shake or 3.4, Near = L.Near or 50, Far = L.Far or 450,
		}
	end
	-- how wide the blast is s studs out
	function GB.width(spec, s)
		local w = spec.Width or { 8, 30 }
		return w[1] + (w[2] - w[1]) * math.clamp(s / (spec.Range or 120), 0, 1)
	end

	-- the right gauntlet's pin ring (Kit.grenadeBracers' GrenadePin nearest his
	-- right fist), if he's wearing them
	function GB.pinPart(char)
		local hand = handPos(char, true)
		local best, bestD
		for _, d in char:GetDescendants() do
			if d.Name == "GrenadePin" and d:IsA("BasePart") then
				local dist = (d.Position - hand).Magnitude
				if not bestD or dist < bestD then
					best, bestD = d, dist
				end
			end
		end
		return best
	end
	-- the pin ripped out: the real ring hidden on this screen (PinBack s), a
	-- copy spun off the left hand that bounces in the street and lies there
	function GB.pullPin(char, d)
		local spec = GB.spec()
		local real = GB.pinPart(char)
		if real then
			-- (round 92 review) his gauntlets hidden on this screen (SHOW
			-- COSMETICS off, a close camera fading his body: LocalTransparencyModifier)
			-- stay hidden - no pin flies off them - and the ring's hidden by its
			-- own Transparency, not that modifier: putting the modifier back to 0
			-- showed a pin floating on a hidden gauntlet
			local ok, ltm = pcall(function()
				return real.LocalTransparencyModifier
			end)
			if not (ok and type(ltm) == "number" and ltm > 0.5) then
				local was = real.Transparency
				if was < 1 then
					real.Transparency = 1
					task.delay(spec.PinBack or 2.4, function()
						if real.Parent and real.Transparency == 1 then
							real.Transparency = was
						end
					end)
				end
				GB.throwPin(char, d)
			end
		else
			GB.throwPin(char, d)
		end
		local hand = handPos(char, true)
		billboardRing(hand, 0.5, 6, Color3.new(1, 1, 1), 4, 0.2)
		sparks(hand, 0.4, Color3.new(1, 1, 1), FIRE[1], 8)
		local MG = VFX.MANGA
		if MG then
			MG.flare(hand, FIRE[1], 2.2, 0.3)
		end
		VFX.PlaySound("MaxCapPin", hand, 1)
	end
	-- the copy of the ring spun off his left hand, bouncing in the street
	function GB.throwPin(char, d)
		local from = handPos(char, false)
		local ring = newPart(Vector3.new(0.06, 0.4, 0.4), CFrame.new(from), Color3.fromRGB(214, 216, 222), Enum.Material.Metal, Enum.PartType.Cylinder)
		local rod = newPart(Vector3.new(0.07, 0.07, 0.55), CFrame.new(from), Color3.fromRGB(190, 192, 198), Enum.Material.Metal)
		local flat = Vector3.new(d.X, 0, d.Z)
		flat = flat.Magnitude > 0.05 and flat.Unit or Vector3.new(0, 0, -1)
		local side = Vector3.new(flat.Z, 0, -flat.X) -- (his left)
		local v = -flat * 9 + side * 7 + UP * 18
		local floorY = groundPoint(from).Y + 0.12
		task.spawn(function()
			local t0, last = os.clock(), os.clock()
			local p, spin, bounced = from, 0, false
			while os.clock() - t0 < 1.6 and ring.Parent do
				local now = os.clock()
				local dt = math.min(now - last, 0.05)
				last = now
				v += Vector3.new(0, -workspace.Gravity * 0.5 * dt, 0)
				p += v * dt
				if p.Y < floorY then
					p = Vector3.new(p.X, floorY, p.Z)
					if not bounced and v.Y < -6 then
						bounced = true
						v = Vector3.new(v.X * 0.45, -v.Y * 0.35, v.Z * 0.45)
						VFX.PlaySound("MaxCapPin", p, 0.35)
					else
						v = Vector3.zero
					end
				end
				spin += dt * (v.Magnitude > 1 and 26 or 0)
				local cf = CFrame.new(p) * CFrame.Angles(spin, spin * 0.7, 0)
				ring.CFrame = cf
				rod.CFrame = cf * CFrame.new(0, 0, -0.42)
				task.wait()
			end
			tween(ring, 0.5, { Transparency = 1 })
			tween(rod, 0.5, { Transparency = 1 })
			cleanup(ring, 0.55)
			cleanup(rod, 0.55)
		end)
	end

	-- the camera jerked up by the recoil (his own screen): up deg, back down over t.
	-- (round 92 review) Roblox's camera carries on next frame from wherever
	-- this one left it pointing (round 83's uppercut kick), so only the CHANGE
	-- in the tilt goes on each frame (GB.kickOn: what's on it now) and the
	-- last frame takes it all back off - the whole tilt every frame added up
	-- to ~30 degrees higher after every blast
	GB.kickOn = 0
	function GB.kick(deg, t)
		local t0 = os.clock()
		t = math.max(t or 0.4, 0.05)
		pcall(function()
			RunService:UnbindFromRenderStep("MaxCapKick")
		end)
		RunService:BindToRenderStep("MaxCapKick", Enum.RenderPriority.Camera.Value + 1, function()
			local a = (os.clock() - t0) / t
			local cam = workspace.CurrentCamera
			local cine = VFX.InCinematic()
			local k = 0
			if a < 1 then
				k = a < 0.12 and a / 0.12 or (1 - (a - 0.12) / 0.88) ^ 2
			end
			if cam and not cine then
				local want = math.rad(deg * k)
				cam.CFrame = cam.CFrame * CFrame.Angles(want - GB.kickOn, 0, 0)
				GB.kickOn = want
			else
				GB.kickOn = 0 -- (a cutscene has the camera: it puts the view back itself)
			end
			if a >= 1 or not cam or cine then
				GB.kickOn = 0
				pcall(function()
					RunService:UnbindFromRenderStep("MaxCapKick")
				end)
			end
		end)
	end

	-- the windup's light and line come down (the blast's here, it fizzled, or
	-- nothing came)
	function GB.stop(run, why)
		if run.done then
			return
		end
		run.done = why or true
		if GB.going[run.char] == run then
			GB.going[run.char] = nil
		end
		if run.conn then
			run.conn:Disconnect()
			run.conn = nil
		end
		if run.line then
			run.line:Destroy()
			run.line = nil
		end
		if run.ball then
			local quick = why == "blast"
			tween(run.ball, quick and 0.06 or 0.25, { Size = Vector3.one * (quick and 0.2 or 0.1), Transparency = 1 })
			cleanup(run.ball, 0.3)
		end
		if run.haze then
			tween(run.haze, 0.1, { Transparency = 1 })
			cleanup(run.haze, 0.15)
		end
	end

	-- THE WINDUP (his press: his own screen at once, everyone else's on the
	-- server's word)
	function Effects.MaxCapacity(char, data, isLocal, ability)
		local root, hum = charParts(char)
		if not root then
			return
		end
		local spec = ability or GB.spec()
		local windup = spec.Windup or 0.5
		local air = data.Air == true
		local d = GB.unit(data.Dir) or root.CFrame.LookVector
		local old = GB.going[char]
		if old then
			GB.stop(old, "again")
		end
		local run = { char = char, t0 = os.clock() }
		GB.going[char] = run
		local mine = GB.mine(char)
		if isLocal then
			face(root, flatten(d, root))
			if air and hum then
				-- (he hangs there for it: a blast off the left palm catches him)
				dash(root, Vector3.new(0, -3, 0), windup + 0.05)
				VFX.PalmBlast(handPos(char, false), -UP, 1.1)
			end
		end
		if VFX.MuteGait then
			VFX.MuteGait(char, windup + 1.4)
		end
		-- (held on its aim till the blast comes - longer on his own screen,
		-- where it comes a round trip after his press)
		local clip = Anim.MoveClips ~= false and VFX.GetClip("MoveMaxCapacity")
		local hold = clip and math.max(windup - (clip.holdAt or windup), 0) + 0.45 or 0
		if not (clip and VFX.Clip(char, "MoveMaxCapacity", { holdFor = hold, legs = not air })) then
			VFX.Motion(char, "MaxCapacity")
		end
		VFX.PlaySound("MaxCapCharge", root.Position, 1)
		-- the grooves of his gauntlets go white-hot (round 90's gauge)
		local CA = VFX.CosA
		local st = CA and CA.bodies and CA.bodies[char]
		if st and st.kind == "Bakugo" then
			st.flashUntil = os.clock() + windup + 0.15
		end
		-- the light swelling at his fist, the air shimmering round it
		local low = GB.low()
		run.ball = newPart(Vector3.one * 0.4, CFrame.new(handPos(char, true)), FIRE[3], Enum.Material.Neon, Enum.PartType.Ball)
		run.ball.Transparency = 0.15
		local light = Instance.new("PointLight")
		light.Color = GB.PAL.light
		light.Range = 8
		light.Brightness = 0
		light.Shadows = false
		light.Parent = run.ball
		if not low then
			run.haze = newPart(Vector3.one * 1, CFrame.new(handPos(char, true)), Color3.fromRGB(255, 220, 160), Enum.Material.ForceField, Enum.PartType.Ball)
			run.haze.Transparency = 0.2
		end
		-- (his own screen: a faint line where it'll go)
		if mine then
			run.line = newPart(Vector3.new(0.1, 0.1, 40), CFrame.new(root.Position), FIRE[3], Enum.Material.Neon)
			run.line.Transparency = 1
		end
		local pinAt = spec.Pin or 0.36
		local pulled, planted, nextPop = false, false, 0
		run.conn = RunService.RenderStepped:Connect(function()
			if run.done then
				return
			end
			if not root.Parent or not char.Parent then
				GB.stop(run, "gone")
				return
			end
			local t = os.clock() - run.t0
			local k = math.clamp(t / windup, 0, 1)
			local hand = handPos(char, true)
			-- his own screen: his body follows his aim (it's what the server takes)
			local aim = d
			if mine then
				local live = VFX.Hooks.Aim and VFX.Hooks.Aim()
				aim = Config.AimedDirection(GB.unit(live) or d, root.CFrame.LookVector, air and spec.AirAim or spec.Aim)
				face(root, flatten(aim, root))
				if run.line then
					local from = hand + flatten(aim, root) * 0.5
					run.line.CFrame = CFrame.lookAt(from, from + aim) * CFrame.new(0, 0, -20)
					run.line.Transparency = 0.82 - 0.3 * k + 0.08 * math.sin(t * 40)
				end
			end
			local size = 0.4 + 2 * k ^ 1.4
			run.ball.Size = Vector3.one * size
			run.ball.CFrame = CFrame.new(hand)
			run.ball.Color = FIRE[3]:Lerp(Color3.new(1, 1, 1), k)
			light.Brightness = 6 * k
			light.Range = 8 + 14 * k
			if run.haze then
				run.haze.Size = Vector3.one * (size * 1.8 + 0.4 * math.sin(t * 30))
				run.haze.CFrame = CFrame.new(hand)
			end
			-- crackling, venting as it fills
			if t >= nextPop then
				nextPop = t + (low and 0.12 or 0.06)
				sparks(hand, 0.25 + 0.3 * k, Color3.new(1, 1, 1), FIRE[1], low and 2 or 4)
				if rng:NextNumber() < 0.4 then
					VFX.PalmBlast(hand + rng:NextUnitVector() * 0.4, rng:NextUnitVector(), 0.35 + 0.3 * k)
				end
				if not low and rng:NextNumber() < 0.5 then
					dustPuffs(hand, 0.25, 1, STEAM, 0.5, false)
				end
			end
			-- planted: the street's dust skitters away from his feet
			if not planted and t >= 0.12 then
				planted = true
				if not air then
					local g = groundPoint(root.Position)
					shockDisc(g + UP * 0.3, UP, 3, 16, 0.35, GB.DUST)
					dustPuffs(g, 0.8, low and 3 or 6, GB.DUST, 0.8, true)
				end
				if mine then
					VFX.Shake(0.35, 0.25)
					if VFX.EngineKit then
						VFX.EngineKit.fovPunch(GB.look(spec).Fov[1], math.max(windup - 0.12, 0.1), 0.25, 0.3)
					end
				end
			end
			-- the pin
			if not pulled and t >= pinAt then
				pulled = true
				GB.pullPin(char, aim)
				if mine then
					VFX.Shake(0.7, 0.2)
				end
			end
			-- nothing came (the server never had it, or it's late): let it go
			if t > windup + 0.7 then
				GB.stop(run, "timeout")
			end
		end)
	end

	-- THE BLAST (the server's word, to every screen)
	function Effects.MaxCapacityBlast(char, data)
		local spec = GB.spec()
		local root, hum = charParts(char)
		local d = GB.unit(data.Dir) or (root and root.CFrame.LookVector) or Vector3.new(0, 0, -1)
		local range = spec.Range or 120
		local length = math.clamp(tonumber(data.Length) or range, 1, range * 1.2)
		if length ~= length then
			length = range
		end
		local from = typeof(data.From) == "Vector3" and data.From == data.From and data.From or (root and root.Position) or nil
		if not from then
			return
		end
		local mine = GB.mine(char)
		local run = char and GB.going[char]
		if run then
			GB.stop(run, "blast")
		end
		-- (from his fist, where his body is on this screen - unless that's
		-- far off the server's word)
		if root then
			local fist = handPos(char, true) + d * 0.6
			if (fist - from).Magnitude < 7 then
				from = fist
			end
		end
		local air = data.Air == true
		local look = GB.look(spec)
		-- (round 92 review) every machine in the server draws every blast: far
		-- off this screen (the line nowhere within Look.Far studs of its
		-- camera) it's drawn on the low-end budget with a third of the
		-- explosions, without the street's detail, the streaks or the smoke
		-- left hanging - the flash, the torrent, the chain and the rings
		-- still read from across the city
		local cam = workspace.CurrentCamera
		local eye = cam and cam.Focus.Position
		local nearest = eye and from + d * math.clamp((eye - from):Dot(d), 0, length)
		local far = nearest ~= nil and (eye - nearest).Magnitude > look.Far
		local low = GB.low() or far
		local speed = spec.Speed or 520
		local flat = Vector3.new(d.X, 0, d.Z)
		flat = flat.Magnitude > 0.05 and flat.Unit or (root and flatten(root.CFrame.LookVector, root)) or Vector3.new(0, 0, -1)
		-- him: thrown back by it
		if root then
			if not (Anim.MoveClips ~= false and VFX.Clip(char, "MoveMaxCapacityFire", { legs = not air })) then
				VFX.Motion(char, "MaxCapacityFire")
			end
			if mine and hum then
				face(root, flat)
				if air then
					local AR = spec.AirRecoil or { Back = 80, Up = 46 }
					local v = -d * (AR.Back or 80) + UP * (AR.Up or 46)
					if v.Magnitude > 130 then
						v = v.Unit * 130
					end
					launch(root, hum, v)
				else
					dash(root, -flat * (spec.Recoil or 34), spec.RecoilTime or 0.22)
				end
			end
		end
		-- the flash at his fist
		-- (not so big it whites out his own view of the torrent: storyboarded)
		local core = newPart(Vector3.one * 2, CFrame.new(from), Color3.new(1, 1, 1), Enum.Material.Neon, Enum.PartType.Ball)
		tween(core, 0.05, { Size = Vector3.one * 7 })
		tween(core, 0.22, { Size = Vector3.one * 1.5, Transparency = 1 }, Enum.EasingStyle.Quad, Enum.EasingDirection.In, 0.05)
		cleanup(core, 0.4)
		local flash = Instance.new("PointLight")
		flash.Color = GB.PAL.light
		flash.Range = 60
		flash.Brightness = 10
		flash.Shadows = false
		flash.Parent = core
		billboardRing(from, 2, 40, Color3.new(1, 1, 1), 0, 0.18, true)
		billboardRing(from, 3, 30, BLAST_YELLOW, 10, 0.32)
		billboardRing(from, 4, 44, Color3.fromRGB(255, 70, 40), 6, 0.4)
		local MG = VFX.MANGA
		if MG then
			MG.flare(from, FIRE[1], 7, 0.5)
		end
		-- the torrent
		local wEnd = GB.width(spec, length)
		if VFX.BLAZE and VFX.BLAZE.jet then
			pcall(VFX.BLAZE.jet, { From = from, Dir = d, Length = length, Width = wEnd * 0.85, Pal = GB.PAL, Rolls = low and 3 or 6, Life = look.JetLife, Fade = 0.35 })
		end
		beam(from, from + d * length, 2.6, Color3.new(1, 1, 1), FIRE[2], 0.32)
		if not far then
			streaks(from, d, low and 10 or 24, math.max(wEnd * 0.25, 2), 14, length * 0.9, FIRE[1], 0.42)
		end
		-- the front racing out: shock rings and a chain of explosions with it
		local rings = low and math.ceil(look.Rings / 2) or look.Rings
		for k = 1, rings do
			local s = length * k / rings
			local w = GB.width(spec, s)
			task.delay(s / speed, function()
				shockDisc(from + d * s, d, w * 0.55, w * 1.3, 0.34, k % 2 == 0 and FIRE[2] or Color3.new(1, 1, 1), 5)
			end)
		end
		-- (from ChainFrom studs out to its end, the furthest the biggest: the
		-- first ones any nearer fill his own view and hide the torrent)
		local booms = far and math.max(math.ceil(look.Booms / 3), 1) or low and math.ceil(look.Booms / 2) or look.Booms
		local basis = CFrame.lookAt(from, from + d)
		local first = math.min(spec.ChainFrom or 22, length * 0.4)
		for k = 1, booms do
			local s = first + (length - first) * (k - 1) / math.max(booms - 1, 1)
			local w = GB.width(spec, s)
			local at = from + d * s + basis.RightVector * rand(-w, w) * 0.2 + basis.UpVector * rand(-w, w) * 0.12
			task.delay(s / speed, function()
				-- (the near ones' smoke clears quickest: it'd hang in his own view)
				toonExplosion(at, 1.1 + 1.6 * math.clamp(s / range, 0, 1), { NoDebris = far or k % 2 == 1, NoEmbers = far, NoScorch = true, SmokeLife = 0.6 + 0.35 * k })
			end)
		end
		-- the street under it: scorched, torn up, the dust rolling off both sides
		if not air and not far then
			local step = low and 20 or 12
			local side = Vector3.new(-flat.Z, 0, flat.X)
			local s = 6
			while s < length do
				local p = from + d * s
				local w = GB.width(spec, s)
				local at = s
				task.delay(at / speed, function()
					groundMark(p, math.min(w * 0.32, 8), GB.SCORCH, 9)
					rocks(p, 0.9 + at / range, low and 2 or 4)
					if not low then
						for _, sgn in { 1, -1 } do
							dustPuffs(groundPoint(p + side * sgn * w * 0.45) + side * sgn * 1.5, 1.2 + at / range, 3, GB.DUST, 1.3, true)
						end
					end
				end)
				s += step
			end
		end
		-- what it meets: the wall blown out, or (from the air) the street
		local wall = typeof(data.Wall) == "Vector3" and data.Wall == data.Wall and data.Wall or nil
		local ground = typeof(data.Ground) == "Vector3" and data.Ground == data.Ground and data.Ground or nil
		if wall then
			task.delay((wall - from).Magnitude / speed, function()
				toonExplosion(wall - d * 2, 3.4, { SmokeLife = 3, NoEmbers = far, NoDebris = far })
				shockDisc(wall - d * 1.5, -d, 6, 44, 0.4, FIRE[2])
				if VFX.BLAZE and VFX.BLAZE.burst then
					pcall(VFX.BLAZE.burst, wall - d * 2, 7, { Pal = GB.PAL })
				end
				VFX.PlaySound("BigExplosion", wall, 1)
			end)
		end
		if ground then
			local radius = spec.Radius or 16
			task.delay((ground - from).Magnitude / speed, function()
				local g = ground + UP * 2
				toonExplosion(g, 4.4, { SmokeLife = 4, NoEmbers = far, NoDebris = far })
				shockDisc(ground + UP * 0.5, UP, 8, radius * 5, 0.55, FIRE[2])
				shockDisc(ground + UP * 1.5, UP, 6, radius * 3.4, 0.45, Color3.new(1, 1, 1))
				groundMark(ground, radius * 0.8, GB.SCORCH, 14)
				rocks(ground, 2.6, low and 10 or 24)
				dustPuffs(ground, 3, low and 5 or 10, GB.DUST, 1.8, true)
				if VFX.BLAZE and VFX.BLAZE.burst then
					pcall(VFX.BLAZE.burst, g, 9, { Pal = GB.PAL })
				end
				VFX.PlaySound("BigExplosion", ground, 1.2)
				VFX.ShakeAt(ground, 4, radius * 9, 0.6)
			end)
		end
		-- the smoke it leaves hanging down the line (from a third of the way
		-- out: not in his own face)
		task.delay(0.22, function()
			if far then
				return
			end
			local n = low and 2 or 4
			for k = 1, n do
				local s = length * (0.35 + 0.6 * (k - 0.5) / n)
				local w = GB.width(spec, s)
				smokeBurst(from + d * s, SMOKE_DARK:Lerp(SMOKE_LIGHT, 0.4), w * 0.45, w * 0.5, 2.6, low and 5 or 10)
			end
			emberCloud(from + d * length * 0.5, math.max(wEnd * 0.4, 4), 1.6, low and 20 or 50)
		end)
		VFX.PlaySound("MaxCapBlast", from, 1.3)
		-- the screens
		if mine then
			VFX.Shake(look.Shake, 0.6)
			GB.kick(look.Kick, 0.4)
			if VFX.EngineKit then
				VFX.EngineKit.fovPunch(look.Fov[2], 0.05, 0.65, 0.06)
			end
			if MG then
				MG.impact(nil, 0.08, {})
			else
				VFX.ImpactFrame(0.08)
			end
			VFX.Hooks.Callout("MAX CAPACITY!!", Color3.fromRGB(255, 200, 80))
		else
			VFX.ShakeAt(from, 3.2, 260, 0.55)
			-- (nearest: the nearest the line comes to this screen's camera)
			if nearest and (eye - nearest).Magnitude < look.Near then
				VFX.Hooks.Flash(Color3.fromRGB(255, 236, 200), 0.25)
				if MG then
					MG.impact(nearest, 0.07, { Radius = 60 })
				end
			end
		end
		-- the gauntlet after: red-hot, steaming, venting
		if root then
			task.delay(0.3, function()
				if not char.Parent then
					return
				end
				local hand = handPos(char, true)
				local glow = newPart(Vector3.one * 1.6, CFrame.new(hand), GB.HOT, Enum.Material.Neon, Enum.PartType.Ball)
				glow.Transparency = 0.3
				tween(glow, 1.4, { Transparency = 1, Size = Vector3.one * 0.6, Color = Color3.fromRGB(120, 30, 20) })
				cleanup(glow, 1.5)
				VFX.PlaySound("MaxCapVent", hand, 1)
				for i = 0, far and -1 or low and 3 or 7 do
					task.delay(i * 0.2, function()
						if char.Parent and glow.Parent then
							local h = handPos(char, true)
							glow.CFrame = CFrame.new(h)
							dustPuffs(h + UP * 0.3, 0.35, 2, STEAM, 0.9, false)
						end
					end)
				end
			end)
		end
	end

	-- knocked out of it before it went: it sputters out
	function Effects.MaxCapacityFizzle(char)
		local run = char and GB.going[char]
		if run then
			GB.stop(run, "fizzle")
		end
		local root = charParts(char)
		if not root then
			return
		end
		local hand = handPos(char, true)
		smokeBurst(hand, SMOKE_LIGHT, 2.5, 2, 0.8, 5)
		sparks(hand, 0.4, Color3.new(1, 1, 1), FIRE[3], 6)
		VFX.PlaySound("PalmPop", hand, 0.8)
	end

	-- (an R15 body - or no clips - plays these: the same beats)
	POSES.MaxCapGrip = {
		RightArm = { 82, 0, -50 }, RightElbow = 30, LeftArm = { 100, 0, -40 }, LeftElbow = 40,
		Waist = { -8, -18, 0 }, Neck = { 16, 10, 0 }, RightLeg = -18, LeftLeg = 24, LeftKnee = 30, RightKnee = 14,
	}
	POSES.MaxCapAim = {
		RightArm = { 94, 0, 12 }, RightElbow = 0, LeftArm = { 16, 0, 44 }, LeftElbow = 20,
		Waist = { -8, 26, 0 }, Neck = { 0, -24, 0 }, RightLeg = -20, LeftLeg = 26, LeftKnee = 32, RightKnee = 16,
	}
	POSES.MaxCapKick = {
		RightArm = { 130, 0, 12 }, LeftArm = { -10, 0, 60 }, LeftElbow = 20,
		Waist = { 12, 18, 0 }, Neck = { -15, -18, 0 }, RightLeg = -24, LeftLeg = 22, LeftKnee = 30, RightKnee = 20,
	}
	MOTIONS.MaxCapacity = {
		{ pose = "MaxCapGrip", t = 0.12, hold = 0.22 },
		{ pose = "MaxCapAim", t = 0.08, hold = 0.55, style = SNAP },
		recover = 0.3,
	}
	MOTIONS.MaxCapacityFire = {
		{ pose = "MaxCapKick", t = 0.04, hold = 0.14, style = SNAP },
		{ pose = "MaxCapAim", t = 0.3, hold = 0.1, style = Enum.EasingStyle.Sine },
		recover = 0.4,
	}
end)()

---------------------------------------------------------------------------
-- (round 92) INASA on every screen (VFX.IN; Config.Quirks.Whirlwind,
-- Config.Inasa): his cape (the long coat's tail - swung from how he moves,
-- snapping in his own gusts), his shouting, and his wind: SLICING GUST (a
-- fan of cutting crescents, the street's dust and leaves swept along each
-- one), GALE CANNON (the air sucked into his palms, the blast tearing down
-- the street with the rubble in it, bursting on a wall), DRAGON WHIRLWIND (a
-- tornado of streaks and dust rolling down the street), WIND WALL (a
-- shimmering wall of wind in front of him; a hit stopped dead on it, a shot
-- sent back), WIND RIDE (a gust under his feet: his own machine flies him on
-- it), the awakening (the bow, then "I LOVE THIS!!!" and the air going up
-- all round him), the M1s' puffs, the dash's gust, the SKY-HIGH SEND-OFF
-- finisher; and the SKYBREAKER CYCLONE: his windup (the cutscene, the
-- titles), then - from the server's word, on every screen in the city - the
-- funnel tearing up out of the street to the clouds, the sky dimming round
-- it, the pieces of the city the server sucked into it wheeling up it, and
-- the burst: everything it carried hurled at the bodies the server picked
-- (each piece landing when the server says it does). Everything is local
-- and cleaned up: on its own timer, a cancel, or Cyclone.MaxTime whatever happens.
-- (In a function of its own: the main chunk is at its local limit.)
---------------------------------------------------------------------------
;(function()
	local IN = { rigs = {}, wind = {}, hyped = {}, tornados = {}, walls = {}, rides = {}, boards = {}, runs = {}, storms = {} }
	VFX.IN = IN
	local Q = Config.Quirks.Whirlwind or {}
	local C = Config.Inasa or {}
	local WD = C.Wind or {}
	local CY = C.Cyclone or {}
	local LOOK = C.Look or {}
	local AIR = WD.Air or Color3.fromRGB(242, 250, 255)
	local PALE = WD.Pale or Color3.fromRGB(196, 226, 230)
	local DUST = WD.Dust or Color3.fromRGB(206, 192, 170)
	local DUST_DARK = WD.DustDark or Color3.fromRGB(150, 136, 118)
	local LightingSvc = game:GetService("Lighting")
	local SMOKE_TEX = (Config.Assets and Config.Assets.SmokeTexture) or "rbxasset://textures/particles/smoke_main.dds"
	local NS, NK = NumberSequence.new, NumberSequenceKeypoint.new

	---------------------------------------------------------------------
	-- helpers
	---------------------------------------------------------------------
	function IN.low()
		return IceKit.lowEnd()
	end
	-- the move as he has it right now (the ult's own numbers while he's in it)
	function IN.spec(char, id)
		local ult = char and char.Parent and char:GetAttribute("UltActive") == true and Q.Ult or nil
		for _, set in { ult and ult.Abilities, ult and { ult.Special, ult.Extra }, Q.Abilities, { Q.Special, Q.Extra }, Q.Ult and Q.Ult.Abilities } do
			for _, a in set or {} do
				if type(a) == "table" and a.Id == id then
					return a
				end
			end
		end
		return {}
	end
	function IN.me()
		local p = Players.LocalPlayer
		return p and p.Character
	end
	function IN.camPos()
		local cam = workspace.CurrentCamera
		return cam and cam.CFrame.Position or Vector3.zero
	end
	-- something the whole city hears: flat, louder the nearer it is
	function IN.far(name, at, gain)
		local dist = typeof(at) == "Vector3" and (IN.camPos() - at).Magnitude or 0
		VFX.PlaySound(name, nil, (gain or 1) * math.clamp(1.25 - dist / 1800, 0.35, 1.25))
	end
	function IN.isInasa(char)
		return char ~= nil and char.Parent ~= nil and char:GetAttribute("Quirk") == "Whirlwind"
	end
	-- a flat direction (his facing when there's none - or junk: a NaN never gets to a CFrame)
	function IN.flat(v, root)
		local f = flatten((typeof(v) == "Vector3" and v == v) and v or nil, root)
		-- (and a body looking straight up or down has no flat facing either)
		return f == f and f or Vector3.new(0, 0, -1)
	end
	-- a usable point (nil for junk)
	function IN.point(v)
		if typeof(v) ~= "Vector3" or v ~= v or v.Magnitude > 1e6 then
			return nil
		end
		return v
	end
	-- a usable flat unit direction from v (nil for junk / zero)
	function IN.dir(v)
		if typeof(v) ~= "Vector3" or v ~= v then
			return nil
		end
		local f = Vector3.new(v.X, 0, v.Z)
		return f.Magnitude > 0.05 and f.Unit or nil
	end
	-- a ray that sees only the map
	function IN.ray(from, to)
		local v = to - from
		if v.Magnitude < 0.05 then
			return nil
		end
		rayParams.FilterDescendantsInstances = characterList()
		return workspace:Raycast(from, v, rayParams)
	end
	-- where the street is under a point (or a little under it)
	function IN.ground(pos)
		return groundPoint(pos)
	end
	-- his hype: one of his lines in a bubble (Hype.Every apart at most)
	function IN.hype(char, line)
		local H = C.Hype or {}
		local now = os.clock()
		if not char or not char.Parent or now - (IN.hyped[char] or -1e9) < (H.Every or 3) then
			return
		end
		IN.hyped[char] = now
		local lines = H.Lines or {}
		local text = line or lines[rng:NextInteger(1, math.max(#lines, 1))]
		if text then
			VFX.SpeechBubble(char, text, 1.3)
		end
	end

	---------------------------------------------------------------------
	-- procedural fallbacks for every clip (anim/moves_inasa.py): what an R15
	-- body, or a place without the clips, plays
	---------------------------------------------------------------------
	MOTIONS.InasaGust = { { pose = { RightArm = { 40, 0, 40 }, LeftArm = { 40, 0, 40 }, Waist = { -6, 0, 0 } }, t = 0.18 }, { pose = { RightArm = { 95, 0, -30 }, LeftArm = { 95, 0, -30 }, Waist = { -12, 0, 0 }, Hips = { 0, 0, 0, 0, -0.3, 0 } }, t = 0.06, hold = 0.35 }, recover = 0.25 }
	MOTIONS.InasaCannon = { { pose = { RightArm = { 70, 0, 50 }, LeftArm = { 70, 0, -10 }, Waist = { 0, -40, 0 }, Hips = { 0, 0, 0, 0, -0.4, 0 } }, t = 0.3 }, { pose = { RightArm = 95, LeftArm = 95, Waist = { -10, 20, 0 }, Hips = { 0, 0, 0, 0, -0.5, 0 } }, t = 0.05, hold = 0.35 }, recover = 0.3 }
	MOTIONS.InasaWhirlwind = { { pose = { RightArm = { 170, 0, 20 }, LeftArm = { 30, 0, 20 }, Waist = { 8, 30, 0 } }, t = 0.26 }, { pose = { RightArm = { 80, 30, 0 }, LeftArm = { 20, 0, 20 }, Waist = { -14, -30, 0 }, Hips = { 0, 0, 0, 0, -0.4, 0 } }, t = 0.06, hold = 0.3 }, recover = 0.3 }
	MOTIONS.InasaRide = { { pose = { RightArm = { -20, 0, 30 }, LeftArm = { -20, 0, 30 }, Waist = { -20, 0, 0 }, Hips = { 0, 0, 0, 0, -0.9, 0 } }, t = 0.1 }, { pose = { RightArm = { 40, 0, 60 }, LeftArm = { 40, 0, 60 }, Waist = { 10, 0, 0 } }, t = 0.06, hold = 0.1 }, recover = 0.1 }
	MOTIONS.InasaAwaken = { { pose = { Waist = { -70, 0, 0 }, Neck = { -10, 0, 0 }, RightArm = { -10, 0, 8 }, LeftArm = { -10, 0, 8 } }, t = 0.25, hold = 0.2 }, { pose = { RightArm = { 160, 0, 40 }, LeftArm = { 160, 0, 40 }, Waist = { 14, 0, 0 }, Neck = { 24, 0, 0 } }, t = 0.08, hold = 0.9 }, recover = 0.35 }
	MOTIONS.InasaCycloneCall = { { pose = { RightArm = { 60, 0, 30 }, LeftArm = { 60, 0, 30 }, Waist = { -8, 0, 0 }, Hips = { 0, 0, 0, 0, -0.5, 0 } }, t = 0.4 }, { pose = { RightArm = { 170, 0, 20 }, LeftArm = { 170, 0, 20 }, Waist = { 10, 0, 0 }, Neck = { 30, 0, 0 } }, t = 0.15, hold = 0.3 }, recover = 0.2 }
	MOTIONS.InasaCycloneHurl = { { pose = { RightArm = { 95, 0, -10 }, LeftArm = { 95, 0, -10 }, Waist = { -22, 0, 0 }, Neck = { -6, 0, 0 }, Hips = { 0, 0, 0, 0, -0.5, 0 } }, t = 0.1, hold = 0.5 }, recover = 0.4 }
	MOTIONS.InasaFinish = { { pose = { RightArm = { -30, 0, 20 }, LeftArm = { 30, 0, 20 }, Waist = { -24, 0, 0 }, Hips = { 0, 0, 0, 0, -0.8, 0 } }, t = 0.25 }, { pose = { RightArm = 175, LeftArm = { 20, 0, 30 }, Waist = { 12, 0, 0 }, Neck = { 30, 0, 0 } }, t = 0.06, hold = 0.4 }, recover = 0.3 }
	POSES.InasaRide = { RightArm = { 40, 0, 70 }, LeftArm = { 30, 0, 60 }, Waist = { -14, 30, 0 }, Neck = { 0, -26, 0 }, RightLeg = 24, LeftLeg = -18, Hips = { 0, 0, 0, 0, -0.5, 0 } }
	POSES.InasaWall = { RightArm = { 95, 0, 55 }, LeftArm = { 95, 0, 55 }, Waist = { -6, 0, 0 }, Neck = { -4, 0, 0 }, RightLeg = -14, LeftLeg = 14, Hips = { 0, 0, 0, 0, -0.45, 0 } }
	POSES.InasaCycloneHold = { RightArm = { 170, 0, 18 }, LeftArm = { 170, 0, 18 }, Waist = { 10, 0, 0 }, Neck = { 28, 0, 0 }, RightLeg = -16, LeftLeg = 16, Hips = { 0, 0, 0, 0, -0.45, 0 } }
	-- ((round 99) INASA_STRIKES: the KO pose - the attack bow - is in the strikes block)

	---------------------------------------------------------------------
	-- THE CAPE (the server's InasaCape: hinged segments) - every screen
	-- swings it from his motion, and snaps it in his own gusts
	---------------------------------------------------------------------
	-- a gust on him: level 0..1 for `time` seconds (every move of his).
	-- (round 99) max: how far this gust throws the cape at full strength, in
	-- degrees off his back - past Coat.Max (e.g. 150: the bow's cape lifted
	-- up over his back in a tall triangle; 95: streaming flat out behind him
	-- on the ride). Without it a full gust lifts it Coat.WindLift
	IN.breeze = {} -- (round 99) [char] = the always-on wind's stir (VFX.WindKit's driver)
	IN.raise = {} -- (round 99) [char] = degrees the cape's held up by it (the ult)
	function IN.gust(char, level, time, max)
		if not char or type(level) ~= "number" or level ~= level then
			return
		end
		local w = IN.wind[char]
		local now = os.clock()
		if not w or w.untilAt < now or level >= w.level then
			IN.wind[char] = { level = level, untilAt = now + (tonumber(time) or 1), max = tonumber(max) }
		end
	end
	function IN.windOf(char, now)
		local w = IN.wind[char]
		if not w then
			return 0
		end
		if w.untilAt < now then
			IN.wind[char] = nil
			return 0
		end
		return w.level * math.clamp((w.untilAt - now) / 0.4, 0, 1)
	end
	-- bind (or re-bind: the gear's rebuilt on every change) his cape
	function IN.bindCape(char)
		local gear = char:FindFirstChild("QuirkGear")
		local cos = gear and gear:FindFirstChild("Cosmetics")
		local cape = cos and cos:FindFirstChild("InasaCape")
		local rig = IN.rigs[char]
		if not cape then
			IN.rigs[char] = nil
			return nil
		end
		if rig and rig.model == cape then
			return rig
		end
		rig = { model = cape, segs = {}, phase = rng:NextNumber(0, 10), snap = 0 }
		for i = 1, 8 do
			local seg = cape:FindFirstChild("InasaCapeSeg" .. i)
			local joint = seg and seg:FindFirstChild("InasaCapeJoint")
			if not (joint and joint:IsA("Weld")) then
				break
			end
			rig.segs[i] = { joint = joint, at = joint.C0.Position, swing = 0, roll = 0 }
		end
		IN.rigs[char] = rig
		return rig
	end
	-- one frame of the cape: each segment's swing back off the one above and
	-- its roll toward where the air pushes it
	function IN.capeStep(char, rig, dt, now)
		local CP = C.Coat or {}
		local torso = char:FindFirstChild("Torso") or char:FindFirstChild("UpperTorso")
		local root = char:FindFirstChild("HumanoidRootPart")
		local n = #rig.segs
		if not torso or not root or n == 0 then
			return
		end
		local v = root.AssemblyLinearVelocity
		-- (a velocity gone NaN or wild for a frame: it keeps its last swing -
		-- a NaN joint would carry into the welded parts)
		if v.Magnitude ~= v.Magnitude or v.Magnitude > 1e4 then
			return
		end
		local lv = torso.CFrame:VectorToObjectSpace(v)
		local fwd, side, fall = -lv.Z, lv.X, -v.Y
		local g = torso.CFrame:VectorToObjectSpace(Vector3.new(0, -1, 0))
		local hang = math.deg(math.atan2(g.Z, math.max(-g.Y, 0.05)))
		local wind = IN.windOf(char, now)
		local speed = math.sqrt(fwd * fwd + side * side)
		-- (round 99) his own wind throws it harder (WindLift), a gust may lift
		-- it past Max (IN.gust's max), the always-on wind keeps it stirring
		-- (the breeze: mostly at the hem) and the ult holds it up (IN.raise)
		local w = IN.wind[char]
		local cap = CP.Max or 72
		local windLift = CP.WindLift or 46
		if w and w.max and wind > 0.05 then
			windLift = math.clamp(w.max, 0, 175)
			cap = math.max(cap, windLift)
		end
		local breeze = math.clamp(tonumber(IN.breeze[char]) or 0, 0, 3)
		local raise = math.clamp(tonumber(IN.raise[char]) or 0, 0, 90)
		local lift = math.clamp(math.max(fwd, 0) * (CP.Lift or 1.8) + math.max(fall, 0) * (CP.Fall or 1.2) + wind * windLift + raise + breeze * (CP.BreezeLift or 0), 0, cap)
		local amp = (CP.Flutter or 2.5) + speed * (CP.FlutterSpeed or 0.22) + wind * (CP.Wind or 24)
		local stir = breeze * (CP.Breeze or 0)
		local rate = (CP.Rate or 1.4) * (1 + speed / 30 + wind * 2.4 * (CP.WindWhip or 1) + breeze * 0.4) * math.pi * 2
		local k = 1 - math.exp(-(CP.Blend or 9) * dt)
		local rest = CP.Rest or 5
		local prevAbs = 0
		-- (round 93 review) the run's strides kick a leg up behind into it:
		-- held out past them (VFX.Gait.capeFloor), the chain followed down
		-- from the hinge side-on
		local legs = VFX.Gait.capeLegs(char, torso)
		local cy, cz, held = 0, 0, 0
		for i, s in rig.segs do
			local share = i / n
			local flutter = math.sin(rig.phase + now * rate - i * 0.9) * (amp * share + stir * share * share)
			local floor = i == 1 and rest or 0
			local abs = math.max(hang + floor + lift * share ^ 0.8 + flutter, floor)
			local rel = abs - prevAbs
			prevAbs = abs
			local roll = math.clamp(-side * (CP.Side or 1), -35, 35) * share + math.sin(rig.phase * 1.7 + now * rate * 0.7 + i) * amp * 0.25 * share
			s.swing += (rel - s.swing) * k
			s.roll += (roll - s.roll) * k
			if legs then
				if i == 1 then
					cy, cz = s.at.Y, s.at.Z
				end
				local h = 2 * s.joint.C1.Y
				local out = VFX.Gait.capeFloor(legs, cy, cz, h, held + s.swing)
				s.swing, held = out - held, out
				cy, cz = cy - h * math.cos(math.rad(out)), cz + h * math.sin(math.rad(out))
			end
			if s.joint.Parent then
				s.joint.C0 = CFrame.new(s.at) * CFrame.Angles(math.rad(-s.swing), 0, math.rad(s.roll))
			end
		end
		-- (in a real gale the cloth snaps: a flap now and then)
		if wind > 0.5 and now >= rig.snap then
			rig.snap = now + rand(0.35, 0.6)
			VFX.PlaySound("InasaCape", root.Position, 0.8)
		end
	end
	-- every Inasa this screen sees: the cape every frame (near the camera)
	IN.bodies = {}
	IN.scanAt = 0
	function IN.step(dt)
		local now = os.clock()
		if now >= IN.scanAt then
			IN.scanAt = now + 0.5
			local list = {}
			for _, plr in Players:GetPlayers() do
				if IN.isInasa(plr.Character) then
					table.insert(list, plr.Character)
				end
			end
			local dummies = workspace:FindFirstChild("Dummies")
			for _, m in dummies and dummies:GetChildren() or {} do
				if IN.isInasa(m) then
					table.insert(list, m)
				end
			end
			IN.bodies = list
			for char in IN.rigs do
				if not IN.isInasa(char) then
					IN.rigs[char] = nil
				end
			end
			for char, w in IN.wind do
				if not char.Parent or w.untilAt < now then
					IN.wind[char] = nil
				end
			end
			for char in IN.hyped do
				if not char.Parent then
					IN.hyped[char] = nil
				end
			end
			-- (round 99) the always-on wind's stir on bodies that aren't his any more
			for _, t in { IN.breeze, IN.raise } do
				for char in t do
					if not IN.isInasa(char) then
						t[char] = nil
					end
				end
			end
		end
		local cam = IN.camPos()
		local CP = C.Coat or {}
		local cull = IN.low() and (CP.LowCull or 80) or (CP.Cull or 160)
		for _, char in IN.bodies do
			local root = char.Parent and char:FindFirstChild("HumanoidRootPart")
			if root and (root.Position - cam).Magnitude <= cull then
				local rig = IN.bindCape(char)
				if rig then
					IN.capeStep(char, rig, math.min(dt or 1 / 60, 0.1), now)
				end
			end
		end
	end
	RunService:BindToRenderStep("InasaCape", Enum.RenderPriority.Camera.Value + 3, function(dt)
		local ok, err = pcall(IN.step, dt)
		if not ok and not IN.warned then
			IN.warned = true
			warn("[VFX.IN] " .. tostring(err))
		end
	end)

	---------------------------------------------------------------------
	-- the pieces his wind is drawn with
	---------------------------------------------------------------------
	-- a ring of air facing along d (a flat disc that opens and fades)
	function IN.ring(pos, d, from, to, life, color, transparency)
		if d.Magnitude < 0.01 then
			d = UP
		end
		local cf = CFrame.lookAt(pos, pos + d.Unit) * CFrame.Angles(0, math.rad(90), 0)
		local p = newPart(Vector3.new(0.35, from, from), cf, color or AIR, Enum.Material.SmoothPlastic, Enum.PartType.Cylinder)
		p.Transparency = transparency or 0.45
		tween(p, life, { Size = Vector3.new(0.12, to, to), Transparency = 1 }, Enum.EasingStyle.Quad, Enum.EasingDirection.Out)
		cleanup(p, life + 0.05)
		return p
	end
	-- leaves and paper caught in the wind: flat bits tumbling from `pos`
	-- along `vel` (studs/s), lifting and drifting, gone after `life`
	function IN.bits(pos, vel, count, life, spread)
		local leaves = WD.Leaves or { Color3.fromRGB(116, 160, 70) }
		for _ = 1, count do
			local paper = rng:NextNumber() < 0.35
			local size = paper and Vector3.new(rand(0.5, 0.9), 0.04, rand(0.6, 1.1)) or Vector3.new(rand(0.35, 0.6), 0.05, rand(0.25, 0.45))
			local color = paper and (WD.Paper or Color3.fromRGB(240, 238, 228)) or leaves[rng:NextInteger(1, #leaves)]
			local from = pos + Vector3.new(rand(-1, 1), rand(-0.5, 1), rand(-1, 1)) * (spread or 2)
			local p = newPart(size, CFrame.new(from) * CFrame.Angles(rand(0, 6), rand(0, 6), rand(0, 6)), color, Enum.Material.SmoothPlastic)
			local l = (life or 1.2) * rand(0.75, 1.25)
			local to = from + vel * l * rand(0.6, 1.1) + Vector3.new(rand(-3, 3), rand(2, 7), rand(-3, 3))
			tween(p, l, { CFrame = CFrame.new(to) * CFrame.Angles(rand(0, 12), rand(0, 12), rand(0, 12)) }, Enum.EasingStyle.Quad, Enum.EasingDirection.Out)
			tween(p, 0.3, { Transparency = 1 }, Enum.EasingStyle.Linear, nil, l - 0.3)
			cleanup(p, l + 0.05)
		end
	end
	-- dust swept along the street under a gust (d flat), from `from` for `len` studs
	function IN.sweepDust(from, d, len, width, life)
		local low = IN.low()
		local n = low and 3 or 6
		for i = 1, n do
			local at = from + d * (len * (i - 0.5) / n) + d:Cross(UP) * rand(-width, width) * 0.4
			local g = IN.ground(at)
			local puff = newPart(Vector3.one * rand(1.5, 2.8), CFrame.new(g + UP * 0.8), DUST, Enum.Material.SmoothPlastic, Enum.PartType.Ball)
			puff.Transparency = 0.4
			local l = (life or 0.6) * rand(0.8, 1.2)
			tween(puff, l, { CFrame = CFrame.new(g + d * rand(6, 12) + UP * rand(1, 2.5)), Size = Vector3.new(rand(5, 8), rand(1.5, 2.5), rand(5, 8)), Transparency = 1 }, Enum.EasingStyle.Quad, Enum.EasingDirection.Out)
			cleanup(puff, l + 0.05)
		end
	end
	-- a long wind streak flying from `from` along `dir` (white, thin, fast)
	function IN.streak(from, dir, len, travel, life, color, width)
		if dir.Magnitude < 0.01 then
			return
		end
		dir = dir.Unit
		local p = newPart(Vector3.new(width or 0.18, width or 0.18, len), CFrame.lookAt(from, from + dir), color or AIR, Enum.Material.Neon)
		p.Transparency = 0.25
		tween(p, life, { CFrame = CFrame.lookAt(from + dir * travel, from + dir * (travel + 1)), Size = Vector3.new(0.04, 0.04, len * 1.4), Transparency = 1 }, Enum.EasingStyle.Quad, Enum.EasingDirection.Out)
		cleanup(p, life + 0.05)
	end

	-- A FUNNEL OF WIND (the tornado, the cyclone, the awakening): rings of
	-- streaks climbing it the twister's way (Beams bent round the circle,
	-- wider and paler the higher; dusty at the foot), a few shimmering shells
	-- round its body so it reads from far off, all moved in one BulkMoveTo
	-- a frame by whoever owns it (f.step adds its parts and CFrames).
	-- spec: { height, baseR, topR, rings, streaks, sway, spin, shells, rise, name }
	function IN.funnel(pos, spec)
		local model = Instance.new("Model")
		model.Name = spec.name or "InasaFunnel"
		model.Parent = folder
		local height, baseR, topR = spec.height or 30, spec.baseR or 2.5, spec.topR or 10
		local f = { model = model, rings = {}, shells = {}, height = height, pos = pos, spin = spec.spin or 3, frame = 0, fades = {} }
		function f.radiusAt(h)
			return baseR + (topR - baseR) * math.clamp(h / height, 0, 1) ^ (spec.flare or 1.6)
		end
		function f.axisAt(center, h, t)
			local k = h / height
			local sway = spec.sway or 0
			return center + Vector3.new(math.sin(t * 0.9 + k * 2.2) * sway * k, h, math.cos(t * 0.7 + k * 1.7) * sway * k)
		end
		function f.fadeSeq(alpha)
			local q = math.floor(math.clamp(alpha, 0, 1) * 20 + 0.5)
			local seq = f.fades[q]
			if not seq then
				local mid = 1 - (q / 20) * (spec.opacity or 0.6)
				seq = NS({ NK(0, 1), NK(0.25, mid), NK(0.75, mid), NK(1, 1) })
				f.fades[q] = seq
			end
			return seq, q
		end
		local n = spec.rings or 10
		for i = 1, n do
			local anchor = newPart(Vector3.one * 0.2, CFrame.new(pos), AIR, nil, nil, model)
			anchor.Transparency = 1
			local ring = { part = anchor, h = (i - 0.5) / n * height, spin = rand(0, math.pi * 2), shade = rand(0.88, 1), streaks = {}, q = -1, n = i }
			for j = 1, spec.streaks or 3 do
				local att0 = Instance.new("Attachment")
				att0.Parent = anchor
				local att1 = Instance.new("Attachment")
				att1.Parent = anchor
				local beam = Instance.new("Beam")
				beam.Attachment0 = att0
				beam.Attachment1 = att1
				beam.Segments = 12
				beam.FaceCamera = true
				beam.LightEmission = 0.25
				beam.LightInfluence = 0.5
				beam.Texture = SMOKE_TEX
				beam.TextureMode = Enum.TextureMode.Stretch
				beam.TextureSpeed = rand(0.6, 1.2)
				beam.Transparency = f.fadeSeq(0)
				beam.Parent = anchor
				table.insert(ring.streaks, { a0 = j / (spec.streaks or 3) * math.pi * 2 + rand(-0.35, 0.35), span = rand(1, 1.6), att0 = att0, att1 = att1, beam = beam })
			end
			table.insert(f.rings, ring)
		end
		-- the shimmering shells round its body (ForceField: see-through, bright at the edges)
		for i = 1, spec.shells or 0 do
			local h0 = (i - 1) / spec.shells * height
			local h1 = i / spec.shells * height
			local r = (f.radiusAt(h0) + f.radiusAt(h1)) / 2
			local shell = newPart(Vector3.new(h1 - h0 + 0.5, r * 2, r * 2), CFrame.new(pos), PALE, Enum.Material.ForceField, Enum.PartType.Cylinder, model)
			shell.Transparency = 1
			table.insert(f.shells, { part = shell, h = (h0 + h1) / 2, spin = rand(0, 6) })
		end
		function f.shape(ring)
			local r = f.radiusAt(ring.h)
			local k = ring.h / height
			local width = (spec.width or 1.2) + r * 0.15
			local shade = ring.shade
			local color = ColorSequence.new(Color3.new(shade, shade, math.min(shade * 1.03, 1)):Lerp(DUST, math.clamp(1 - k * 3.5, 0, 1) * 0.7))
			for _, s in ring.streaks do
				local a0, a1 = s.a0, s.a0 + s.span
				local t0 = Vector3.new(-math.sin(a0), 0.08, math.cos(a0)).Unit
				local t1 = Vector3.new(-math.sin(a1), 0.08, math.cos(a1)).Unit
				local u0 = (UP - t0 * t0:Dot(UP)).Unit
				local u1 = (UP - t1 * t1:Dot(UP)).Unit
				s.att0.CFrame = CFrame.fromMatrix(Vector3.new(math.cos(a0) * r, 0, math.sin(a0) * r), t0, u0)
				s.att1.CFrame = CFrame.fromMatrix(Vector3.new(math.cos(a1) * r, s.span * r * 0.05, math.sin(a1) * r), t1, u1)
				local bend = 4 / 3 * math.tan(s.span / 4) * r
				s.beam.CurveSize0 = bend
				s.beam.CurveSize1 = bend
				s.beam.Width0 = width * 0.5
				s.beam.Width1 = width
				s.beam.Color = color
			end
		end
		for _, ring in f.rings do
			f.shape(ring)
		end
		-- one frame: everything climbs and turns round `center` (its foot);
		-- grow 0..1: only so much of it is up yet; fade 1..0: dying away
		function f.step(dt, t, center, grow, fade, parts, cfs)
			f.frame += 1
			for _, ring in f.rings do
				local k = ring.h / height
				ring.h += ((spec.rise or 14) + (spec.rise or 14) * 1.8 * k) * dt
				if ring.h > height then
					ring.h -= height
				end
				k = ring.h / height
				ring.spin += f.spin * (1.4 - 0.9 * k) * dt
				if (f.frame + ring.n) % 3 == 0 then
					f.shape(ring)
				end
				local edge = math.min(1, k / 0.06, (1 - k) / 0.12)
				local seq, q = f.fadeSeq(k <= grow and edge * fade or 0)
				if q ~= ring.q then
					ring.q = q
					for _, s in ring.streaks do
						s.beam.Transparency = seq
					end
				end
				table.insert(parts, ring.part)
				table.insert(cfs, CFrame.new(f.axisAt(center, ring.h, t)) * CFrame.Angles(0, -ring.spin, 0))
			end
			for _, s in f.shells do
				s.spin += f.spin * 0.6 * dt
				local k = s.h / height
				local shown = k <= grow and fade or 0
				s.part.Transparency = 1 - (spec.shellAlpha or 0.5) * shown
				table.insert(parts, s.part)
				table.insert(cfs, CFrame.new(f.axisAt(center, s.h, t)) * CFrame.Angles(0, s.spin, math.rad(90)))
			end
		end
		function f.destroy()
			if model.Parent then
				model:Destroy()
			end
		end
		return f
	end
	-- move parts in one go (BulkMoveTo; the harness and old engines: one by one)
	function IN.move(parts, cfs)
		if #parts == 0 then
			return
		end
		local ok = IN.noBulk ~= true and pcall(function()
			workspace:BulkMoveTo(parts, cfs, Enum.BulkMoveMode.FireCFrameChanged)
		end)
		if not ok then
			for i, part in parts do
				if part.Parent then
					part.CFrame = cfs[i]
				end
			end
		end
	end
	-- a dust skirt boiling off the street at a funnel's foot
	function IN.skirt(model, pos, radius, rate)
		local skirt = newPart(Vector3.new(radius * 2, 1, radius * 2), CFrame.new(pos + UP), DUST, nil, nil, model)
		skirt.Transparency = 1
		local fx = Instance.new("ParticleEmitter")
		fx.Texture = SMOKE_TEX
		fx.Color = ColorSequence.new(DUST, DUST_DARK)
		fx.LightInfluence = 0.6
		fx.Size = NS({ NK(0, radius * 0.6), NK(1, radius * 2) })
		fx.Transparency = NS({ NK(0, 0.9), NK(0.2, 0.4), NK(1, 1) })
		fx.Lifetime = NumberRange.new(1, 1.8)
		fx.Speed = NumberRange.new(radius * 1.2, radius * 2.5)
		fx.SpreadAngle = Vector2.new(70, 70)
		fx.Acceleration = Vector3.new(0, radius, 0)
		fx.Drag = 0.8
		fx.Rotation = NumberRange.new(0, 360)
		fx.RotSpeed = NumberRange.new(-60, 60)
		fx.Rate = IN.low() and rate * 0.4 or rate
		fx.Parent = skirt
		return skirt, fx
	end

	-- (round 99) INASA_STRIKES: 1 SLICING GUST and 2 GALE CANNON are remade on
	-- the WIND KIT in the strikes block below (VFX.IN.strikes)

	---------------------------------------------------------------------
	-- (round 99) INASA_STORM: DRAGON WHIRLWIND, WIND WALL, WIND RIDE /
	-- STORM RIDE, his dash and his idle presence, remade on the WIND KIT
	-- (VFX.WindKit) the way round 85 remade Iida: his own clips
	-- (anim/moves_inasa_w.py: MoveInasaDragon, PoseInasaCurtain,
	-- PoseInasaGale), every beat waiting on its clip's key on his pose
	-- clock (a hitstop holds it with the clip; nothing comes before the
	-- throw it belongs to), his own sounds layered from the library
	-- (InasaDragon* / InasaCurtain* / InasaRide* / InasaDashGust /
	-- InasaIdleBreath), everything gone on every way out (its time, the
	-- server's word, his death, another hero), half on a low-end machine.
	-- What the moves do is the server's and isn't changed. The look's
	-- numbers: Config.Inasa.Storm. (VFX.InasaStorm, "SM")
	---------------------------------------------------------------------
	local SM = { read = {}, live = {}, moved = {}, goes = {}, pending = {}, heldFor = {}, idle = {} }
	VFX.InasaStorm = SM
	-- the clips' named keys (seconds) as anim/moves_inasa_w.py writes them:
	-- SM.mark reads them off the clip in the place (a moved key moves its
	-- effect), these if it isn't there
	SM.MARKS = {
		MoveInasaDragon = { Spin = 0.1, Cock = 0.25, Hit = 0.3 },
		PoseInasaCurtain = { Hit = 0.1, Hold = 0.22, HoldEnd = 0.5, Lift = 0.53 },
		PoseInasaGale = { Crouch = 0.07, Hit = 0.12, Hold = 0.28, HoldEnd = 0.9, Let = 0.93 },
	}
	-- what an R15 body (or a place without the clips) plays instead: round
	-- 92's procedural ones for the same moves
	MOTIONS.InasaDragon = MOTIONS.InasaWhirlwind
	POSES.InasaCurtain = POSES.InasaWall
	POSES.InasaGale = POSES.InasaRide
	function SM.cfg(key)
		local S = C.Storm
		return type(S) == "table" and type(S[key]) == "table" and S[key] or {}
	end
	-- a clip's named key (seconds): off the clip in the place, else SM.MARKS
	function SM.mark(name, key)
		local m = SM.read[name]
		if m == nil then
			local anims = game:GetService("ReplicatedStorage"):FindFirstChild("Animations")
			local ks = anims and anims:FindFirstChild(name)
			if ks and ks:IsA("KeyframeSequence") then
				m = {}
				for _, kf in ks:GetChildren() do
					if kf:IsA("Keyframe") and kf.Name ~= "Keyframe" then
						m[kf.Name] = kf.Time
					end
				end
				SM.read[name] = m
			end
		end
		return (m and m[key]) or (SM.MARKS[name] or {})[key] or 0
	end
	-- where a key falls in a clip held holdFor seconds (VFX.Clip slows its
	-- Hold..HoldEnd down to fill the hold; past HoldEnd it's just that later)
	function SM.due(name, key, holdFor)
		local t = SM.mark(name, key)
		local ha, he = SM.mark(name, "Hold"), SM.mark(name, "HoldEnd")
		holdFor = math.max(tonumber(holdFor) or 0, 0)
		if holdFor <= 0 or t <= ha then
			return t
		elseif he > ha and t < he then
			return ha + (t - ha) * (he - ha + holdFor) / (he - ha)
		end
		return t + holdFor
	end
	-- a move of his starting on this screen: its token (a newer one of his
	-- cuts the older one's beats)
	function SM.begin(char)
		local token = {}
		SM.live[char] = token
		SM.moved[char] = os.clock()
		return token
	end
	-- wait until `due` seconds of his pose clock have gone by since `from`
	-- (poseTime as his clip started: a hitstop's freeze doesn't count, so the
	-- clip and its effects stay together). false: the move's over - he's
	-- gone or down, someone else now (if he was Inasa as it began: was), or
	-- a newer move of his took over
	function SM.at(char, from, due, token, was)
		local WK = VFX.WindKit
		while true do
			if not char.Parent or (token and SM.live[char] ~= token) or (WK and WK.over(char, was)) then
				return false
			end
			local left = due - (poseTime(char, os.clock()) - from)
			if left <= 0 then
				return true
			end
			task.wait(math.min(left, 0.05))
		end
	end
	-- the screen whose camera is his (his own body, or the one a dev's in)
	function SM.mine(char)
		local lp = Players.LocalPlayer
		return lp ~= nil and typeof(char) == "Instance" and (lp.Character == char or char:GetAttribute("PossessedBy") == lp.UserId)
	end
	-- does this machine fly his body? His own - and (a gameplay fix) the
	-- machine of a dev in it (round 95's possess: that machine runs the
	-- body's physics; before, a possessed Inasa's WIND RIDE never flew - the
	-- board and pose played on the spot while the server's hits ran round him)
	function SM.drives(char, isLocal)
		if isLocal then
			return true
		end
		local lp = Players.LocalPlayer
		return lp ~= nil and char:GetAttribute("PossessedBy") == lp.UserId
	end
	-- knocked out of a ride (on every screen): stunned, thrown, grabbed,
	-- frozen, stopped in time, a knockback on him, his dev flight, down
	function SM.knocked(char, root)
		for _, a in { "Stunned", "Ragdolled", "Grabbed", "Frozen", "TimeStopped" } do
			if char:GetAttribute(a) == true then
				return true
			end
		end
		if char:GetAttribute("DevFlying") ~= nil or root:FindFirstChild("Knockback") ~= nil then
			return true
		end
		local hum = char:FindFirstChildOfClass("Humanoid")
		return hum ~= nil and hum.Health <= 0
	end

	---------------------------------------------------------------------
	-- 3: DRAGON WHIRLWIND - the anime's palm whirl (Ep 54) flung at the
	-- street: the whirl spun up on his raised palm, pitched overhand off it,
	-- and where it lands a real tornado climbs up out of the street (bands
	-- spiralling up it, its dust skirt, leaves, paper and grit wheeling up
	-- it in lanes, curls off its rim), rolling on down the server's path,
	-- the flat whirl it leaves on the street, the pull drawn (curls sliding
	-- in from its edge), whoever it holds wound round with bands and
	-- carried round it, and its burst
	---------------------------------------------------------------------
	-- whoever the server says it holds (DragonWhirlwindHeld): bands round them
	function SM.applyHeld(tw, targets)
		local WK = VFX.WindKit
		local vx = tw and tw.vx
		if not vx or not vx.alive or type(targets) ~= "table" then
			return
		end
		local H = SM.cfg("Whirl").Held or {}
		local want = {}
		for _, m in targets do
			local part = typeof(m) == "Instance" and (m:FindFirstChild("Torso") or m:FindFirstChild("UpperTorso") or m:FindFirstChild("HumanoidRootPart"))
			if part then
				want[part] = true
				if not vx.carried[part] then
					vx:carry(part, { radius = H.Radius or 2.4, spin = H.Spin or 3 })
					WK.curl(part.Position, UP, { n = 3, size = 1.6, drift = 3, life = 0.4 })
				end
			end
		end
		for part in vx.carried do
			if not want[part] then
				vx:drop(part)
			end
		end
	end
	-- the tornado rolling down the street from `start` along d (travel studs
	-- in `life` seconds). One per Inasa on a screen (keyed by his body - or
	-- its start, a screen without the body). opts.from: where it's flung from
	-- (the whirl off his palm, opts.palm, flies there in Fling seconds and
	-- lands - then the tornado climbs up out of the street); opts.t0: when
	-- the server set it going (its path's clock)
	function IN.tornado(char, start, d, travel, life, spec, opts)
		local WK = VFX.WindKit
		spec = type(spec) == "table" and spec or {}
		opts = type(opts) == "table" and opts or {}
		local key = char or start
		local old = IN.tornados[key]
		if old then
			old.stop(true)
		end
		local W = SM.cfg("Whirl")
		local low = IN.low()
		life = math.clamp(tonumber(life) or 2.6, 0.1, 8)
		local tw = { start = start, d = d, travel = travel, life = life, t0 = tonumber(opts.t0) or os.clock(), key = key, predicted = false, center = start, shift = Vector3.zero }
		IN.tornados[key] = tw
		local H = spec.Height or 24
		local R = spec.PullRadius or 16
		local flyFrom = opts.from and WK.v3(opts.from)
		local mini = flyFrom and opts.palm or nil
		local fling = mini and (W.Fling or 0.09) or 0
		local flung = os.clock()
		local landed = false
		local nextTrack, nextSuck, nextHeld, flip = 0, 0, 0, 1
		local function land(at)
			landed = true
			local vx = WK.vortex(at, {
				name = "InasaTornado", height = H * 0.3, baseR = 0.8, topR = 2.6, rings = W.Rings or 10, bands = W.Bands or 3,
				spin = W.Spin or 1.6, sway = W.Sway or 2.5, debris = W.Debris or 8, dust = W.Dust or 26, grow = W.Grow or 0.25,
				ease = 9, width = 1.1, sound = "InasaWindWhirl", life = life + 3,
			})
			tw.vx = vx
			if vx then
				vx:set({ height = H, baseR = W.BaseR or 3, topR = R * (W.TopShare or 0.62) })
			end
			if mini then
				mini:stop(0.12)
			end
			-- it lands: the street whirled, its dust thrown out, a pop of leaves
			local L = W.Land or {}
			WK.ground(at, L.Radius or 8, { loops = 3, spin = 2.4, life = 0.75 })
			WK.burst(at + UP * 0.8, UP, { radius = 4, streaks = 6, curls = 3, life = 0.3, ground = false })
			WK.debris(at + UP * 0.6, UP * 16 + tw.d * 4, { n = 4, spread = 80, life = 1.1 })
			VFX.PlaySound("InasaDragonLand", at, 1)
			VFX.PlaySound("InasaWhirlLoop", at, 0.7)
			if char and SM.mine(char) then
				WK.fovPunch(L.Fov or 4, 0.05, 0.3)
				WK.kick(tw.d, L.Kick or 0.5, 0.25)
			end
			-- (whoever the server said it holds before it landed here)
			if char and SM.heldFor[char] then
				SM.applyHeld(tw, SM.heldFor[char])
				SM.heldFor[char] = nil
			end
		end
		-- how: true = gone now; "burst" = thrown up and out; else it unwinds
		function tw.stop(how)
			if tw.done then
				return
			end
			tw.done = true
			if IN.tornados[key] == tw then
				IN.tornados[key] = nil
			end
			if mini then
				mini:stop(0.1)
			end
			local vx = tw.vx
			if vx then
				if how == true then
					-- (its roar let go first: it lives in the model)
					vx:stop(0.05)
					pcall(vx.model.Destroy, vx.model)
				else
					vx:stop(how == "burst" and 0.35 or 0.5, how == "burst" and "burst" or "unwind")
				end
			end
		end
		WK.run({ life = life + 4, kill = function()
			if not tw.done then
				tw.stop(true)
			end
		end, step = function(_, _, _dt, now)
			if tw.done then
				return false
			end
			local t = os.clock() - tw.t0
			local k = math.clamp(t / math.max(tw.life, 0.1), 0, 1)
			local ease = tw.adoptAt and math.clamp(1 - (os.clock() - tw.adoptAt) / 0.25, 0, 1) or 0
			local center = tw.start + tw.d * (tw.travel * k) + tw.shift * ease
			tw.center = center
			if not landed then
				local f = (os.clock() - flung) / math.max(fling, 1e-3)
				if mini and f < 1 then
					-- (the whirl off his palm, on its arc to the street)
					mini:move(flyFrom:Lerp(center, f) + UP * (W.Arc or 3) * 4 * f * (1 - f))
					return true
				end
				land(center)
			end
			local vx = tw.vx
			if not vx then
				return t < tw.life + 0.6
			end
			vx:move(center)
			-- the flat whirl it leaves on the street behind it
			if now >= nextTrack then
				nextTrack = now + (low and (W.LowTrack or 0.45) or (W.Track or 0.22))
				WK.ground(center, 3.4, { loops = 2, spin = 1.3, life = 0.9, dust = false, transparency = 0.45 })
			end
			-- the pull drawn: a curl sliding in from its edge (a streak with every other)
			if now >= nextSuck and t < tw.life then
				nextSuck = now + (W.Suck or 0.2) * (low and 2 or 1)
				flip = -flip
				local a = rand(0, math.pi * 2)
				local out = Vector3.new(math.cos(a), 0, math.sin(a))
				local round = UP:Cross(out)
				local p = center + out * R * rand(0.75, 0.95) + UP * rand(0.5, 2.2)
				WK.curl(p, -out + round * 0.6, { n = 1, size = 1.8, drift = R * 0.45, life = 0.5, spin = 240 })
				if flip > 0 then
					WK.streaks(WK.look(p, -out + round * 0.5), { n = 1, length = R * 0.5, width = 0.24, spread = 0.3, bend = 1 })
				end
			end
			-- whoever it holds: a curl burst off them now and then
			if now >= nextHeld then
				nextHeld = now + ((W.Held or {}).Curls or 0.3)
				for part in vx.carried do
					if part.Parent then
						local out = IN.dir(part.Position - center) or Vector3.new(1, 0, 0)
						WK.curl(part.Position, UP:Cross(out) + UP * 0.3, { n = 2, size = 1.5, drift = 3, life = 0.4 })
					end
				end
			end
			if t > tw.life + 0.6 then
				-- (no word from the server - a screen that missed it: it dies away by itself)
				tw.stop(false)
				return false
			end
			return true
		end })
		return tw
	end
	function Effects.DragonWhirlwind(char, data, isLocal)
		local root = charParts(char)
		local WK = VFX.WindKit
		if not root or not WK then
			return
		end
		local spec = IN.spec(char, "DragonWhirlwind")
		local d = IN.flat(data.Dir, root)
		if isLocal then
			face(root, d)
		end
		local W = SM.cfg("Whirl")
		local P = W.Palm or {}
		local token = SM.begin(char)
		local was = IN.isInasa(char)
		local name = "MoveInasaDragon"
		VFX.Motion(char, "InasaDragon")
		local from = poseTime(char, os.clock())
		VFX.Voice("InasaWhirl", root)
		IN.hype(char)
		IN.gust(char, 0.45, 0.6, 70)
		-- (a Go from the server that beats the throw here waits for it)
		SM.pending[char] = token
		task.spawn(function()
			local spinAt, hitAt = SM.mark(name, "Spin"), SM.mark(name, "Hit")
			local function over()
				if SM.pending[char] == token then
					SM.pending[char] = nil
				end
			end
			-- Spin: the whirl spun up on his raised palm, the air sucked up
			-- into it, the wind coiling up his arm
			if not SM.at(char, from, spinAt, token, was) then
				over()
				return
			end
			local function palm()
				return handPos(char, true) + UP * (P.Lift or 1.1)
			end
			local S = P.Spin or { 1, 4.5 }
			VFX.PlaySound("InasaDragonSpin", root.Position, 1)
			VFX.PlaySound("InasaWhirlSpin", root.Position, 0.6)
			local mini = WK.vortex(palm(), {
				name = "InasaDragonPalm", height = P.Height or 2.8, baseR = P.BaseR or 0.3, topR = P.TopR or 1.5, rings = 4, bands = 2,
				spin = S[1] or 1, dust = false, debris = 0, haze = false, curlEvery = 0.07, width = 0.55, ease = 14, life = 3,
			})
			local coil = WK.armWind(char, "Right", { strands = 2, spin = 3, dur = 1.5 })
			local follow = true
			local suckAt = 0
			WK.run({ life = 2, step = function(_, t, _dt, now)
				if not follow or not mini or not mini.alive or not char.Parent then
					return false
				end
				local f = math.clamp(t / math.max(hitAt - spinAt, 0.05), 0, 1)
				mini:move(palm())
				mini:set({ spin = (S[1] or 1) + ((S[2] or S[1] or 1) - (S[1] or 1)) * f })
				if now >= suckAt then
					suckAt = now + (IN.low() and 0.12 or 0.06)
					local a = rand(0, math.pi * 2)
					local off = Vector3.new(math.cos(a), rand(-0.6, 0.2), math.sin(a)) * 3.2
					WK.curl(palm() + off, -off, { n = 1, size = 1, drift = 2.6, life = 0.28, spin = 200 })
				end
				return true
			end })
			-- Hit: THE FLING - pitched overhand off his hand at the street
			local ok = SM.at(char, from, hitAt, token, was)
			follow = false
			over()
			if not ok then
				if mini then
					mini:stop(0.15)
				end
				if coil then
					coil:stop(0.1)
				end
				return
			end
			if coil then
				coil:release(d)
			end
			VFX.PlaySound("InasaDragonFling", root.Position, 1)
			IN.gust(char, 1, 0.7, 95)
			WK.vent(char, { "Back" }, { dir = -d, n = 5, speed = 14 })
			if SM.mine(char) then
				WK.kick(d, 0.35, 0.2)
			end
			local hand = handPos(char, true) + UP * 0.8
			-- set down where the server said, if its word's here already (an
			-- onlooker's screen); else where it will be (the word moves it)
			local go = SM.goes[char]
			SM.goes[char] = nil
			local have = IN.tornados[char]
			if not go and have and not have.done and have.fromServer then
				-- ((round 99 review) the server's word set it down here already -
				-- his throw came that late (the director's slow motion holds the
				-- clip, not the server's word): the whirl's flung into it, never a
				-- second one on a path of this screen's guessing)
				if mini then
					local t1 = os.clock()
					WK.run({ life = 0.6, step = function()
						local f = (os.clock() - t1) / math.max(W.Fling or 0.09, 0.02)
						if f >= 1 or have.done or typeof(have.center) ~= "Vector3" then
							mini:stop(0.1)
							return false
						end
						mini:move(hand:Lerp(have.center, f) + UP * (W.Arc or 3) * 4 * f * (1 - f))
						return true
					end })
				end
			elseif go then
				local tw = IN.tornado(char, go.From, go.Dir, go.Travel, go.Life, spec, { from = hand, palm = mini, t0 = go.At })
				tw.adopted, tw.fromServer = true, true
			else
				local start = IN.ground(root.Position + d * (spec.Ahead or 7))
				local want = (spec.Speed or 14) * (spec.Life or 2.6)
				local hit = IN.ray(start + UP * 3, start + UP * 3 + d * (want + 4))
				local travel = math.clamp((hit and hit.Distance or want + 4) - 4, 0, want)
				local tw = IN.tornado(char, start, d, travel, spec.Life or 2.6, spec, { from = hand, palm = mini })
				tw.predicted = true
			end
		end)
	end
	-- (server, to everyone) where it really is
	function Effects.DragonWhirlwindGo(char, data)
		local from, d = IN.point(data.From), IN.dir(data.Dir)
		if not from or not d then
			return
		end
		local travel = math.clamp(tonumber(data.Travel) or 0, 0, 400)
		local life = math.clamp(tonumber(data.Life) or 2.6, 0.2, 8)
		local tw = char and IN.tornados[char]
		if tw and not tw.done and not tw.adopted and os.clock() - tw.t0 < 1 then
			-- (one this screen set down on his throw: moved onto the server's
			-- path - eased over, not jumped)
			tw.adopted = true
			local was = tw.center
			tw.start, tw.d, tw.travel = from, d, travel
			local k = math.clamp((os.clock() - tw.t0) / math.max(tw.life, 0.1), 0, 1)
			local now = from + d * (travel * k)
			tw.shift, tw.adoptAt = (typeof(was) == "Vector3" and was or now) - now, os.clock()
			return
		end
		-- his throw hasn't come yet on this screen: it sets it down there
		-- (unless it never comes)
		if char and SM.pending[char] then
			local go = { From = from, Dir = d, Travel = travel, Life = life, At = os.clock() }
			SM.goes[char] = go
			task.delay(0.35, function()
				if SM.goes[char] == go then
					SM.goes[char] = nil
					local tw2 = IN.tornado(char, from, d, travel, life, IN.spec(char, "DragonWhirlwind"), { t0 = go.At })
					tw2.adopted, tw2.fromServer = true, true
				end
			end)
			return
		end
		local tw3 = IN.tornado(char, from, d, travel, life, IN.spec(char, "DragonWhirlwind"))
		tw3.adopted, tw3.fromServer = true, true
	end
	-- ((round 99) INASA_STORM: server, to everyone) who it holds now: the
	-- bands wound round them, carried round it
	function Effects.DragonWhirlwindHeld(char, data)
		local pos = IN.point(data.Pos)
		local tw = char and IN.tornados[char]
		if not tw and pos then
			-- (a screen without his body: the one there)
			for key, t in IN.tornados do
				if typeof(key) == "Vector3" and typeof(t.center) == "Vector3" and (t.center - pos).Magnitude < 14 then
					tw = t
				end
			end
		end
		if tw and tw.vx then
			SM.applyHeld(tw, data.Targets)
		elseif char then
			SM.heldFor[char] = type(data.Targets) == "table" and data.Targets or nil
		end
	end
	-- (server) it died: the burst that throws them - or, cut short with
	-- nobody in it (he went down: his wind dies with him), it unwinds
	function Effects.DragonWhirlwindEnd(char, data)
		local WK = VFX.WindKit
		local pos = IN.point(data.Pos)
		local tw = (char and IN.tornados[char]) or (pos and IN.tornados[pos])
		if not tw and pos then
			-- (a screen without his body: the one that's rolled there)
			for key, t in IN.tornados do
				if typeof(key) == "Vector3" and typeof(t.center) == "Vector3" and (t.center - pos).Magnitude < 14 then
					tw = t
				end
			end
		end
		if char then
			SM.goes[char], SM.heldFor[char] = nil, nil
		end
		local W = SM.cfg("Whirl")
		local targets = type(data.Targets) == "table" and data.Targets or {}
		local hum = char and char:FindFirstChildOfClass("Humanoid")
		local down = char ~= nil and (char.Parent == nil or (hum ~= nil and hum.Health <= 0))
		local early = tw ~= nil and os.clock() - tw.t0 < tw.life - (W.Late or 0.35)
		if #targets == 0 and (down or early) then
			if tw then
				tw.stop(false)
			end
			return
		end
		if tw then
			tw.stop("burst")
		end
		if not pos or not WK then
			return
		end
		local B = W.Burst or {}
		local R = B.Radius or 18
		local low = IN.low()
		VFX.PlaySound("InasaDragonBurst", pos, 1)
		WK.burst(pos + UP * 2.5, UP, { radius = R, streaks = 12, curls = 8, life = 0.5, grow = 0.22 })
		WK.ground(pos, R * 0.7, { loops = 4, spin = 2.8, life = 0.9, cracks = true })
		-- what it carried flung out all round (in order: a fan each way)
		local fans = low and 2 or 3
		for i = 1, fans do
			local a = (i - 1) / fans * math.pi * 2 + 0.4
			local out = Vector3.new(math.cos(a), 0, math.sin(a))
			WK.debris(pos + UP * 4 + out * 3, out * 30 + UP * 18, { n = 3, spread = 90, life = 1.3, kinds = { "leaf", "grit", "paper" } })
		end
		-- the ones it throws, streaked up after them
		for _, target in targets do
			local torso = typeof(target) == "Instance" and (target:FindFirstChild("Torso") or target:FindFirstChild("UpperTorso"))
			if torso then
				addTrail(torso, AIR, 0.35, 2)(1.1)
				WK.streaks(WK.look(torso.Position - UP * 2, UP), { n = 3, length = 14, width = 0.3, spread = 1.2 })
			end
		end
		VFX.ShakeAt(pos, B.Shake or 2.2, B.ShakeRange or 120, 0.35)
	end

	---------------------------------------------------------------------
	-- R: WIND WALL - the anime's gust curtain (Ep 59: a wall of wind
	-- pouring down, wider at the top, a jagged foot): his arms gather the
	-- air in and throw it out wide, and the curtain pours down onto the
	-- street in front of him, roaring, the wind streaming off his palms into
	-- it; a hit stopped on it ripples it, a puncher's blown back off it by a
	-- gust, a shot bulges it and is spat back down the line; it lifts away
	---------------------------------------------------------------------
	-- the wall in front of him (square to where he set it, following him as
	-- he shuffles on) for `time`: a marker at its foot at once (its model,
	-- "InasaWall"), the curtain when his arms throw it (wall.up())
	function IN.wallMake(char, root, d, spec, time)
		local WK = VFX.WindKit
		local old = IN.walls[char]
		if old then
			old.stop()
		end
		local WL = SM.cfg("Wall")
		local width, height = spec.Width or 14, spec.Height or 12
		local model = Instance.new("Model")
		model.Name = "InasaWall"
		model.Parent = folder
		local wall = { model = model, t0 = os.clock(), time = time, d = d, root = root, width = width, height = height }
		IN.walls[char] = wall
		local function foot()
			local g = IN.ground(root.Position + d * (WL.Out or 4.5))
			return WK.look(g, d)
		end
		local mark = newPart(Vector3.new(width, 0.2, 0.4), foot(), AIR, nil, nil, model)
		mark.Name = "InasaWallFoot"
		mark.Transparency = 1
		local curtain, roar, bandH
		local climbers = {}
		-- ((round 99 review) the ult's storm pillars at its two ends: its own,
		-- stood on the street when it lands and kept at its ends as he
		-- shuffles - the kit's own are made where the curtain is made, and it's
		-- made up in the sky to pour down: they hung there)
		local pillars = {}
		local palmAt, landed, hazeAt = 0, false, 0
		local drop = WL.Drop or 0.1
		local bow = width * (WL.Bow or 0.26)
		-- (the sheet's bow: a circle's arc - as the kit's curtain lays it)
		local Rb = (width * width / 4 + bow * bow) / (2 * math.max(bow, 0.05))
		local half = math.asin(math.clamp(width / 2 / Rb, 0, 1))
		function wall.up()
			if wall.done or curtain then
				return
			end
			local ult = width > 14 or char:GetAttribute("UltActive") == true
			wall.ult = ult
			curtain = WK.curtain(foot() + UP * height * 0.7, width, height, { bow = bow, streaks = WL.Streaks or 14, warm = ult, pillars = false, life = time + 1 })
			wall.curtain = curtain
			wall.dropAt = os.clock()
			if curtain then
				curtain.holder.Parent = model
				-- crescent bands pouring down the sheet one after another, widest
				-- up top (the anime's curtain pours down out of the sky; the kit's
				-- draws its top edge and its middle, its streaks running up it)
				bandH = WK.holder(curtain.holder.CFrame, "WallBands")
				bandH.Parent = model
				local n = IN.low() and 1 or (WL.Bands or 2)
				for i = 1, n do
					climbers[i] = { band = WK.band(bandH, { color = AIR, shade = ult and WK.PAL.PASSION or WK.PAL.SHADE }), ph = (i - 1) / n }
				end
			end
			roar = WK.loop("InasaCurtainRoar", root, { gain = WL.Roar or 0.9, fadeIn = 0.15, max = time + 1 })
		end
		function wall.stop()
			if wall.done then
				return
			end
			wall.done = true
			wall.stopAt = os.clock()
			if IN.walls[char] == wall then
				IN.walls[char] = nil
			end
			if curtain then
				curtain:stop(WL.Lift or 0.25)
				VFX.PlaySound("InasaCurtainLift", root.Position, 0.8)
			end
			for _, p in pillars do
				p:stop(WL.Lift or 0.25)
			end
			if roar then
				roar.stop(0.3)
			end
			-- (its own clean-up, not Debris: gone for sure)
			task.delay((WL.Lift or 0.25) + 0.05, function()
				if model.Parent then
					model:Destroy()
				end
			end)
		end
		WK.run({ holder = model, life = time + 2, kill = function()
			-- (gone any way at all: the pillars, which live outside its model, with it)
			for _, p in pillars do
				p:stop(0.15)
			end
		end, step = function(_, _, _dt, now)
			local fade = 1
			if wall.done then
				fade = 1 - math.clamp((os.clock() - (wall.stopAt or 0)) / (WL.Lift or 0.25), 0, 1)
			elseif not root.Parent or os.clock() - wall.t0 >= time then
				wall.stop()
			end
			local f = foot()
			if not wall.done then
				mark.CFrame = f
			end
			if not curtain then
				return not wall.done
			end
			-- pouring down out of the sky onto the street
			local k = math.clamp((os.clock() - wall.dropAt) / drop, 0, 1)
			if not wall.done then
				curtain:move(f + UP * height * 0.7 * (1 - k) * (1 - k))
			end
			-- the crescents pouring down it (lifted away with it at the end)
			if bandH and curtain.holder.Parent then
				bandH.CFrame = curtain.holder.CFrame
				local camPos = WK.cam().Position
				for _, c in climbers do
					-- ((round 99 review) poured off its top and gone by half-way
					-- down - the full height of them read as a ladder)
					local u = ((os.clock() - wall.dropAt) / (WL.Climb or 0.5) + c.ph) % 1
					local y = height * (0.98 - 0.5 * u)
					local s = 0.98 - 0.3 * u
					local o = math.sin(u * math.pi) ^ 0.7 * 0.7 * fade * math.min(k * 2, 1) * WK.nearK(bandH.Position + UP * y, camPos)
					WK.layBand(c.band, Vector3.new(0, y, -bow + Rb), Vector3.new(0, 0, -1), Vector3.new(1, 0, 0), Rb, -half * s, half * s, 0.95 - 0.5 * u, o)
				end
			end
			if wall.done then
				return true
			end
			if k >= 1 and not landed then
				-- (its foot hits the street: dust splashed all along it)
				landed = true
				for _, s in { -0.8, 0, 0.8 } do
					WK.dustRing(f.Position + f.RightVector * s * width * 0.5, 3, { n = 6 })
				end
				-- (the ult's: a storm pillar twisting up at each end)
				if wall.ult and not IN.low() then
					for i, s in { -1, 1 } do
						local base = (f * CFrame.new(s * width / 2, 0, 0)).Position
						pillars[i] = WK.rope(base, base + UP * height * 1.1, { radius = 1.4, storm = true, spin = 1.6 * s, strands = 2, life = time + 1 })
					end
				end
			end
			-- (...kept standing at its ends as he shuffles on)
			for i, p in pillars do
				local base = (f * CFrame.new((i == 1 and -1 or 1) * width / 2, 0, 0)).Position
				p:set(base, base + UP * height * 1.1)
			end
			if k >= 1 and now >= palmAt then
				-- the wind streaming off his palms into it
				palmAt = now + (WL.Palm or 0.15) * (IN.low() and 2 or 1)
				for _, right in { true, false } do
					local hand = handPos(char, right)
					local to = f.Position + UP * rand(height * 0.25, height * 0.6) + f.RightVector * (right and 1 or -1) * rand(1, width * 0.3)
					local v = to - hand
					if v.Magnitude > 0.5 then
						WK.streaks(WK.look(hand, v), { n = 1, length = v.Magnitude, width = 0.26, spread = 0.2, speed = v.Magnitude / 0.16, bend = right and 1 or -1 })
					end
				end
			end
			if k >= 1 and now >= hazeAt then
				-- ...and its body: haze washing up the sheet
				hazeAt = now + (WL.Haze or 0.22)
				WK.haze(f * CFrame.new(0, height * 0.3, -bow * 0.6), Vector3.new(width * 0.8, height * 0.5, 1), UP + f.LookVector * 0.3, { n = 5, speed = 0.35, life = 0.6, transparency = 0.7 })
			end
			return true
		end })
		return wall
	end
	function Effects.WindWall(char, data, isLocal)
		local root = charParts(char)
		local WK = VFX.WindKit
		if not root or not WK then
			return
		end
		local spec = IN.spec(char, "WindWall")
		local d = IN.flat(data.Dir, root)
		if isLocal then
			face(root, d)
		end
		local WL = SM.cfg("Wall")
		local time = spec.Time or 1.4
		local token = SM.begin(char)
		local was = IN.isInasa(char)
		local name = "PoseInasaCurtain"
		-- (held so its Lift - the arms sweeping it away - lands as it ends)
		local holdFor = math.max(time - SM.mark(name, "Lift"), 0)
		-- ((round 99 review) the game's switch for keyframed move clips, as
		-- VFX.Pose / VFX.Motion read it)
		if not (Anim.MoveClips ~= false and VFX.Clip(char, name, { holdFor = holdFor, recover = 0.25 })) then
			VFX.Pose(char, "InasaCurtain", time)
		end
		local from = poseTime(char, os.clock())
		local wall = IN.wallMake(char, root, d, spec, time)
		wall.pose = VFX.PoseToken(char)
		-- the gather: the air pulled in to his chest
		VFX.PlaySound("InasaWindSuck", root.Position, 0.6)
		IN.gust(char, 0.4, 0.2)
		local chest = root.Position + UP * 1.2 + d * 0.8
		for i = 1, IN.low() and 2 or 3 do
			local a = (i - 1) / 3 * math.pi * 2 + rand(-0.3, 0.3)
			local off = (d:Cross(UP) * math.cos(a) + UP * math.sin(a)) * 3 + d * 1.5
			WK.curl(chest + off, -off, { n = 1, size = 1.3, drift = 2.6, life = 0.2, spin = 220 })
		end
		task.spawn(function()
			-- Hit: thrown out wide - the curtain pours down in front of him
			if not SM.at(char, from, SM.mark(name, "Hit"), token, was) or wall.done then
				return
			end
			wall.up()
			VFX.PlaySound("InasaCurtainUp", root.Position, 1)
			VFX.PlaySound("InasaWallUp", root.Position, 0.6)
			IN.gust(char, 0.9, time + 0.3, WL.Cape or 80)
			WK.vent(char, { "Glove", "Knuckles", "Hands" }, { dir = d, speed = 16, n = 6 })
			if SM.mine(char) then
				WK.fovPunch(WL.Fov or 3, 0.05, 0.3)
				WK.kick(-d, WL.Kick or 0.4, 0.25)
			end
		end)
	end
	-- (server) the wall's down early (a hit from behind, a stun) or on time
	function Effects.WindWallEnd(char)
		local wall = char and IN.walls[char]
		if wall then
			local early = os.clock() - wall.t0 < wall.time - 0.1
			wall.stop()
			-- (cut short: his arms come down with it - unless something else
			-- has his body by now, a hit's reaction)
			if early and wall.pose and VFX.PoseToken(char) == wall.pose then
				VFX.ReleasePose(char, 0.2)
			end
		end
	end
	-- (server) a hit stopped dead on it: it ripples there, the air splashes
	-- off sideways along it, his palms puff; a puncher (Target) is blown
	-- back off it by a short gust front
	function Effects.WindWallBlock(char, data)
		local WK = VFX.WindKit
		local pos = IN.point(data.Pos)
		if not pos or not WK then
			return
		end
		VFX.PlaySound("InasaWallBlock", pos, 1)
		local wall = char and IN.walls[char]
		if wall and wall.curtain then
			wall.curtain:ripple(pos)
		end
		local root = char and char:FindFirstChild("HumanoidRootPart")
		local d = (wall and wall.d) or (root and IN.dir(pos - root.Position)) or Vector3.new(0, 0, -1)
		local side = d:Cross(UP)
		WK.burst(pos, d, { radius = 3, streaks = 6, curls = 2, ground = false, life = 0.3 })
		WK.streaks(WK.look(pos, side + d * 0.2), { n = 2, length = 5, width = 0.25, spread = 0.6 })
		WK.streaks(WK.look(pos, -side + d * 0.2), { n = 2, length = 5, width = 0.25, spread = 0.6 })
		if char then
			WK.vent(char, { "Glove", "Knuckles" }, { n = 4, dir = d })
		end
		local target = typeof(data.Target) == "Instance" and data.Target or nil
		local troot = target and target:FindFirstChild("HumanoidRootPart")
		-- ((round 99 review) only the one the server blows back - once a wall:
		-- a second punch into it is only stopped; Blow = false says so)
		if troot and data.Blow ~= false then
			local S = SM.cfg("Wall").Shove or {}
			local v = IN.dir(troot.Position - pos) or d
			WK.gustFront(pos - v, v, { range = S.Range or 7, cone = S.Cone or 24, bands = 2, height = 2, width = 1.2, curls = 3, trails = 3, debris = 2, speed = (S.Range or 7) / 0.15 })
			VFX.PlaySound("InasaWindImpact", troot.Position, 0.9)
		end
	end
	-- (server) a shot sent back: the sheet bulges where it hit and spits it
	-- back down the line as a small drill of wind at whoever threw it, at
	-- the wall's own ReflectSpeed (arriving when the server's return hit
	-- lands). Back = false: only stopped
	function Effects.WindWallDeflect(char, data)
		local WK = VFX.WindKit
		local from, to = IN.point(data.From), IN.point(data.To)
		if not from or not WK then
			return
		end
		local wall = char and IN.walls[char]
		if wall and wall.curtain then
			wall.curtain:bulge(from)
			wall.curtain:ripple(from)
		end
		VFX.PlaySound("InasaWallBlock", from, 0.8)
		WK.burst(from, (to and WK.dir(to - from)) or UP, { radius = 2.5, streaks = 4, curls = 2, ground = false, life = 0.25 })
		if not data.Back or not to or (to - from).Magnitude < 1 then
			return
		end
		local root = char and char:FindFirstChild("HumanoidRootPart")
		if root then
			VFX.Voice("InasaWall", root)
		end
		VFX.PlaySound("InasaWallDeflect", from, 1)
		VFX.PlaySound("InasaCurtainSpit", from, 1)
		local dir = (to - from).Unit
		local dist = (to - from).Magnitude
		local spec = IN.spec(char, "WindWall")
		-- (round 92 sent it back at a hard-coded 220: the ult's 260 arrived
		-- late. (round 99 review) The server's own word for it first - a
		-- screen without his body can't read his ult off him)
		local speed = tonumber(data.Speed)
		speed = (speed and speed == speed and speed > 1) and speed or spec.ReflectSpeed or 220
		local time = math.clamp(dist / math.max(speed, 1), 0.05, 0.8)
		local S = SM.cfg("Wall").Spit or {}
		WK.tube(from, dir, dist, { width = S.Width or 3.6, speed = dist / time, gap = S.Gap or 3, life = S.Life or 0.25, spin = 3 })
		if char and SM.mine(char) then
			WK.fovPunch(SM.cfg("Wall").Fov or 3, 0.05, 0.25)
		end
		task.delay(time, function()
			WK.burst(to, dir, { radius = 3.5, streaks = 6, curls = 3, life = 0.3 })
			VFX.PlaySound("InasaGustHit", to, 1.1)
		end)
	end

	---------------------------------------------------------------------
	-- 4: WIND RIDE / STORM RIDE - riding his own gale (the anime's Ep 57:
	-- standing on the mouth of his own funnel): the take-off (a whirl
	-- spinning up under his feet, the back unit and ankle rings venting,
	-- then a column of wind punching up under him), the funnel lying back
	-- and down along his path under his feet, the street's dust furrowing
	-- under him when he's low, the people he rides through blown aside, and
	-- the let-go (the funnel bursting into curls). STORM RIDE: a bigger
	-- funnel in the passion shade, two storm ropes coiling round him, leaves
	-- and grit in his wake. His own machine flies him (IN.ride, below)
	---------------------------------------------------------------------
	function IN.blocked(char, root, hum)
		return not root.Parent or not char.Parent or not hum or hum.Health <= 0 or root.Anchored
			or char:GetAttribute("Stunned") == true or char:GetAttribute("Ragdolled") == true or char:GetAttribute("Grabbed") == true
			or char:GetAttribute("Frozen") == true or char:GetAttribute("TimeStopped") == true or char:GetAttribute("DevFlying") ~= nil
			or root:FindFirstChild("Knockback") ~= nil or (char:GetAttribute("Quirk") ~= nil and char:GetAttribute("Quirk") ~= "Whirlwind")
	end
	-- where he's steering: where his camera looks
	function IN.aimOf(root)
		local cam = workspace.CurrentCamera
		local look = cam and cam.CFrame.LookVector or root.CFrame.LookVector
		return look == look and look or root.CFrame.LookVector
	end
	-- his own screen flies him: a LinearVelocity steered to where his camera
	-- looks (the pitch kept in MinPitch..MaxPitch), facing the way he goes;
	-- a hit, a stun, a grab, death, another hero - it lets go at once. At the
	-- end it lets him go with Carry of his speed (the let-go's look and sound
	-- are the gale's, IN.board, on every screen)
	function IN.ride(char, root, spec)
		local hum = char:FindFirstChildOfClass("Humanoid")
		if not hum then
			return nil
		end
		local old = IN.rides[char]
		if old then
			old.stop("Again")
		end
		local launch, time = spec.Launch or 0.12, spec.Time or 1.4
		local ride = { t0 = os.clock(), v = Vector3.zero }
		IN.rides[char] = ride
		local att = Instance.new("Attachment")
		att.Name = "InasaRideAttachment"
		att.Parent = root
		local lv = Instance.new("LinearVelocity")
		lv.Name = "InasaRide"
		lv.Attachment0 = att
		lv.MaxForce = moverForce(root, 6000)
		lv.RelativeTo = Enum.ActuatorRelativeTo.World
		lv.VectorVelocity = Vector3.new(0, 16, 0)
		lv.Parent = root
		local auto = hum.AutoRotate
		hum.AutoRotate = false
		local last = IN.flat(root.CFrame.LookVector, root)
		local conn
		function ride.stop(reason)
			if ride.done then
				return
			end
			ride.done = true
			ride.reason = reason
			if conn then
				conn:Disconnect()
			end
			if lv.Parent then
				lv:Destroy()
			end
			if att.Parent then
				att:Destroy()
			end
			if hum.Parent then
				hum.AutoRotate = auto
			end
			if IN.rides[char] == ride then
				IN.rides[char] = nil
			end
			if reason == "Done" and root.Parent then
				root.AssemblyLinearVelocity = ride.v * (spec.Carry or 0.45)
			end
		end
		conn = RunService.Stepped:Connect(function()
			local t = os.clock() - ride.t0
			if IN.blocked(char, root, hum) then
				ride.stop("Hit")
				return
			end
			if t >= launch + time then
				ride.stop("Done")
				return
			end
			if t < launch then
				return -- (the hop up onto it)
			end
			local look = IN.aimOf(root)
			local fl = Vector3.new(look.X, 0, look.Z)
			if fl.Magnitude > 0.05 and fl.Magnitude == fl.Magnitude then
				last = fl.Unit
			end
			local pitch = math.clamp(math.deg(math.asin(math.clamp(look.Y, -1, 1))), spec.MinPitch or -30, spec.MaxPitch or 35)
			local dir = last * math.cos(math.rad(pitch)) + UP * math.sin(math.rad(pitch))
			ride.v = dir * (spec.Speed or 80)
			lv.VectorVelocity = ride.v
			root.CFrame = CFrame.lookAt(root.Position, root.Position + last)
		end)
		return ride
	end
	-- the gale he rides, on every screen, for the ride's time: board.launch()
	-- (the column under him and his funnel) and board.letGo() are its clip's
	-- beats (Effects.WindRide waits on them); knocked out of it, or the beat
	-- never coming, it lets go by itself; board.stop(): gone, no let-go
	function IN.board(char, root, time, launch, opts)
		local WK = VFX.WindKit
		opts = type(opts) == "table" and opts or {}
		local old = IN.boards[char]
		if old then
			old.stop()
		end
		local RD = SM.cfg("Ride")
		local F = RD.Funnel or {}
		local SF = RD.Storm or {}
		local storm = opts.storm == true
		-- (STORM RIDE's funnel: that much bigger)
		local FK = storm and (SF.Scale or 1.25) or 1
		local board = { t0 = os.clock(), time = time, launch = launch, storm = storm }
		IN.boards[char] = board
		local torso = char:FindFirstChild("Torso") or char:FindFirstChild("UpperTorso")
		local scale = (torso and torso.Name == "Torso") and torso.Size.Y / 2 or 1
		local fun, wakeH, wakeFx
		local ropes = {}
		-- ((round 99 review) his jet stream from far off: ribbons spiralling
		-- off his funnel's rim, left hanging along his line - the streaks
		-- alone were a few dashes past 30 studs)
		local ribH, ribs, ribA = nil, {}, 0
		local last = IN.flat(root.CFrame.LookVector, root)
		local nextWake, nextDebris, nextTrail = 0, 0, 0
		local mine = SM.mine(char)
		local release -- (his always-on wind held off while his gale carries him)
		local function way()
			local v = root.AssemblyLinearVelocity
			if v == v and v.Magnitude > 5 and v.Magnitude < 1e4 then
				return v.Unit
			end
			return last
		end
		local function feet()
			return root.Position - UP * 3 * scale
		end
		function board.launch()
			if board.done or fun then
				return
			end
			local g = feet()
			local w = way()
			-- the column of wind punching up under him, tipping over into his way
			local Cc = RD.Column or {}
			local col = WK.vortex(g - UP * 0.5, {
				name = "InasaRideColumn", height = Cc.Height or 7, baseR = Cc.Radius or 2.2, topR = (Cc.Radius or 2.2) * 1.4, rings = 4, bands = 2,
				spin = 3, dust = false, debris = 0, haze = false, grow = 0.08, life = Cc.Life or 0.3, width = 0.8, ease = 10,
			})
			if col then
				col:set({ axis = -w + UP * 1.6 })
			end
			WK.burst(g, UP, { radius = 5, streaks = 8, curls = 3, life = 0.3 })
			-- his funnel: a small tornado lying back and down along his way,
			-- its mouth under his feet
			fun = WK.vortex(g - (w * (F.Back or 3) + UP * (F.Down or 3.8)) * FK, {
				name = "InasaRideFunnel", axis = w * (F.Back or 3) + UP * (F.Down or 3.8), height = (F.Height or 5) * FK, baseR = F.BaseR or 0.6,
				topR = storm and (SF.TopR or 4.5) or (F.TopR or 3.5), rings = storm and (SF.Rings or 7) or (F.Rings or 5), bands = 2, spin = F.Spin or 3,
				debris = F.Debris or 2, dust = false, haze = not mine, shade = storm and WK.PAL.PASSION or nil, curlEvery = 0.1, ease = 20,
				width = 0.8, sound = "InasaWindWhirl", life = time + 1.5, grow = 0.1,
			})
			board.funnel = fun
			release = WK.hold(char, time + 0.3)
			if storm then
				for i = 1, SF.Ropes or 2 do
					ropes[i] = WK.rope(g, g + UP * 6, { r0 = 0.45, r1 = 1, pitch = 2.6, strands = 2, width = 0.7, spin = i == 1 and 2.4 or -2.4, storm = true, life = time + 1 })
				end
			end
			-- the ribbons off its rim
			ribH = WK.holder(CFrame.new(g), "RideRibbons")
			local nRib = IN.low() and 1 or (RD.Ribbons or 2)
			for i = 1, nRib do
				local a0, a1 = WK.att(ribH), WK.att(ribH)
				local tr = Instance.new("Trail")
				tr.Name = "InasaWind"
				tr.Attachment0, tr.Attachment1 = a0, a1
				tr.Color = ColorSequence.new(AIR, storm and WK.PAL.PASSION or WK.PAL.SHADE)
				-- (fainter on his own screen: they stream back past his camera)
				tr.Transparency = NS({ NK(0, mine and 0.6 or 0.2), NK(0.55, mine and 0.8 or 0.55), NK(1, 1) })
				tr.WidthScale = NS({ NK(0, 1), NK(1, 0.25) })
				tr.Lifetime = RD.RibbonLife or 0.35
				tr.MinLength = 0.05
				tr.FaceCamera = true
				tr.LightEmission = 0.1
				tr.LightInfluence = 0.3
				tr.Parent = ribH
				ribs[i] = { a0 = a0, a1 = a1, trail = tr, ph = (i - 1) / nRib * math.pi * 2 }
			end
			-- the street's dust furrowing under him (an emitter there, its rate with how low he is)
			wakeH = WK.holder(CFrame.new(g), "RideWake")
			wakeH.Size = Vector3.new(2, 0.3, 2)
			wakeFx = Instance.new("ParticleEmitter")
			wakeFx.Name = "InasaWind"
			wakeFx.Texture = WK.TEX.smoke
			wakeFx.Color = ColorSequence.new(DUST, DUST_DARK)
			wakeFx.Transparency = NS({ NK(0, 1), NK(0.2, 0.5), NK(1, 1) })
			wakeFx.Size = NS({ NK(0, 1.4), NK(1, 4) })
			wakeFx.Lifetime = NumberRange.new(0.5, 0.9)
			wakeFx.Speed = NumberRange.new(4, 9)
			wakeFx.SpreadAngle = Vector2.new(50, 50)
			wakeFx.Acceleration = Vector3.new(0, 3, 0)
			wakeFx.Drag = 2
			wakeFx.LightInfluence = 0.7
			wakeFx.EmissionDirection = Enum.NormalId.Top
			wakeFx.Rate = 0
			wakeFx.Parent = wakeH
		end
		-- soft: gone without the let-go's burst (he's gone, or it never launched)
		function board.letGo(soft)
			if board.done then
				return
			end
			board.done = true
			if IN.boards[char] == board then
				IN.boards[char] = nil
			end
			if fun then
				fun:stop(soft and 0.2 or 0.3, "burst")
			end
			for _, r in ropes do
				r:stop(0.25)
			end
			if wakeFx then
				wakeFx.Rate = 0
				WK.after(wakeH, 1)
			end
			if ribH then
				-- (they stop growing; what's left hangs and fades with its time)
				for _, rb in ribs do
					rb.trail.Enabled = false
				end
				WK.after(ribH, (RD.RibbonLife or 0.35) + 0.1)
			end
			if release then
				release()
			end
			if mine then
				WK.fovPunch(0, RD.FovOut or 0.35, 0.01, 0)
			end
			if soft or not fun or not root.Parent then
				return
			end
			local f = feet()
			WK.curl(f + UP * 0.5, -way() + UP * 0.3, { n = 6, spread = 2, size = 2, drift = 5, life = 0.45 })
			local hit = groundRay(root.Position, 3 * scale + (RD.Ground or 8))
			if hit then
				WK.burst(hit.Position + UP * 0.3, UP, { radius = 6, streaks = 6, curls = 2, life = 0.35 })
			end
			VFX.PlaySound("InasaRideLetGo", root.Position, 1)
			VFX.PlaySound("InasaRideEnd", root.Position, 0.7)
		end
		function board.stop()
			board.letGo(true)
		end
		-- ((round 99 review) dropped any way at all - the kit's crowd past
		-- Kit.Live too - it lets go: the street-dust holder, the hold on his
		-- always-on wind and IN.boards never outlive it)
		WK.run({ life = launch + time + 3, kill = function()
			if not board.done then
				board.letGo(true)
			end
		end, step = function(_, _, dt, now)
			if board.done then
				return false
			end
			local t = os.clock() - board.t0
			if not root.Parent or not char.Parent then
				board.stop()
				return false
			end
			if t > launch + time + 1 then
				-- (its let-go beat never came)
				board.letGo()
				return false
			end
			if not fun then
				return true
			end
			if SM.knocked(char, root) then
				board.letGo()
				return false
			end
			local w = way()
			local fl = IN.dir(w)
			if fl then
				last = fl
			end
			local mouth = feet() - UP * 0.3
			local tip = mouth - (w * (F.Back or 3) + UP * (F.Down or 3.8)) * FK
			local ax = mouth - tip
			fun:set({ axis = ax, pos = tip, height = ax.Magnitude, now = true })
			-- the ribbons: turning round its rim, left hanging along his line
			if ribH then
				ribA += (RD.RibbonSpin or 2.2) * math.pi * 2 * dt
				ribH.CFrame = WK.upFrame(mouth, ax)
				local rr = (storm and (SF.TopR or 4.6) or (F.TopR or 3.6)) * 0.7
				for _, rb in ribs do
					local a = ribA + rb.ph
					local p = Vector3.new(math.cos(a), 0, math.sin(a)) * rr
					rb.a0.CFrame, rb.a1.CFrame = CFrame.new(p * 0.9), CFrame.new(p * 1.1)
				end
			end
			-- STORM RIDE's ropes coiling up out of its tip either side of him,
			-- streaming back past his hips (clear of his body)
			if #ropes > 0 then
				local side = fl and fl:Cross(UP) or Vector3.new(1, 0, 0)
				for i, r in ropes do
					r:set(tip, root.Position - UP * 0.6 * scale + side * (i == 1 and 1 or -1) * (SF.RopeR or 2.6) - w * 1.4)
				end
				if now >= nextDebris then
					nextDebris = now + (SF.Debris or 0.25) * (IN.low() and 2 or 1)
					WK.debris(mouth, -w * 22 + UP * 5, { n = 2, kinds = { "leaf", "grit" }, life = 0.8 })
				end
			end
			-- his trail in the air: streaks left hanging along his line (from
			-- far off it's a jet stream behind him)
			if now >= nextTrail then
				nextTrail = now + (RD.TrailEvery or 0.07) * (IN.low() and 2 or 1)
				local side = fl and fl:Cross(UP) or Vector3.new(1, 0, 0)
				WK.streaks(WK.look(mouth + UP * rand(0.5, 3) + side * rand(-1.5, 1.5), -w), { n = 1, length = (RD.TrailLength or 10) * FK, width = 0.3, spread = 0.3, transparency = 0.2 })
			end
			-- the wake: under Wake studs the street's dust furrows under him
			local hit = groundRay(root.Position, (RD.Wake or 15) + 3 * scale)
			if hit and wakeH then
				local h = math.max(root.Position.Y - 3 * scale - hit.Position.Y, 0)
				local k = math.clamp(1 - h / (RD.Wake or 15), 0, 1)
				wakeH.CFrame = CFrame.new(hit.Position + UP * 0.3)
				wakeFx.Rate = 34 * k * (IN.low() and 0.5 or 1)
				if now >= nextWake and k > 0.2 then
					nextWake = now + (RD.WakeEvery or 0.1) * (IN.low() and 2 or 1)
					WK.streaks(WK.look(hit.Position + UP * 0.25 + w * 2, -(fl or w)), { n = 1, length = 7, width = 0.34, spread = 0.6, color = DUST, transparency = 0.25 })
				end
			elseif wakeFx then
				wakeFx.Rate = 0
			end
			return true
		end })
		return board
	end
	function Effects.WindRide(char, data, isLocal)
		local root = charParts(char)
		local WK = VFX.WindKit
		if not root or not WK then
			return
		end
		local spec = IN.spec(char, "WindRide")
		local RD = SM.cfg("Ride")
		local launch, time = spec.Launch or 0.12, spec.Time or 1.4
		local token = SM.begin(char)
		local was = IN.isInasa(char)
		local name = "PoseInasaGale"
		-- (held so its Let - the let-go - lands as the ride ends)
		local holdFor = math.max(launch + time - SM.mark(name, "Let"), 0)
		if not (Anim.MoveClips ~= false and VFX.Clip(char, name, { holdFor = holdFor, recover = 0.3 })) then
			VFX.Pose(char, "InasaGale", launch + time)
		end
		local from = poseTime(char, os.clock())
		VFX.Voice("InasaRide", root)
		IN.hype(char)
		VFX.PlaySound("InasaRideStart", root.Position, 0.8)
		IN.gust(char, 0.6, launch + 0.15, 120)
		local board = IN.board(char, root, time, launch, { storm = char:GetAttribute("UltActive") == true })
		-- the flight: his machine's (or the one a dev driving his body is on)
		local drives = SM.drives(char, isLocal)
		if drives then
			IN.ride(char, root, spec)
			VFX.Hooks.SpeedLines(launch + time)
		end
		task.spawn(function()
			-- Crouch: a whirl spinning up under his feet, the back unit and
			-- ankle rings venting down at the street
			if not SM.at(char, from, SM.mark(name, "Crouch"), token, was) then
				board.stop()
				return
			end
			WK.ground(IN.ground(root.Position), 4.5, { loops = 3, spin = 2.8, life = 0.45 })
			WK.vent(char, { "Back", "Ankles" }, { dir = -UP, speed = 18, n = 6 })
			-- Hit = Launch: off the street on his gale
			if not SM.at(char, from, SM.mark(name, "Hit"), token, was) then
				board.stop()
				return
			end
			board.launch()
			VFX.PlaySound("InasaRideOff", root.Position, 1)
			VFX.PlaySound("InasaRideRush", root.Position, 1)
			IN.gust(char, 1, time + 0.3, 95)
			if drives and SM.mine(char) then
				WK.fovPunch(RD.Fov or 10, RD.FovIn or 0.15, RD.FovOut or 0.35, time)
			end
			-- Let: he lets it go
			if not SM.at(char, from, SM.due(name, "Let", holdFor), token, was) then
				board.stop()
				return
			end
			board.letGo()
		end)
	end
	-- (server) he rode through someone: an impact gust on them, a spray of
	-- curls off the side they're blown to, streaked after them
	function Effects.WindRideHit(char, data)
		local WK = VFX.WindKit
		local target = typeof(data.Target) == "Instance" and data.Target or nil
		local troot = target and target:FindFirstChild("HumanoidRootPart")
		if not troot or not WK then
			return
		end
		local d = WK.dir(data.Dir, UP)
		local pos = troot.Position
		VFX.PlaySound("InasaRideThrough", pos, 1)
		VFX.PlaySound("InasaGustHit", pos, 0.7)
		WK.burst(pos, d, { radius = 5, streaks = 8, curls = 2, life = 0.32 })
		local root = char and char:FindFirstChild("HumanoidRootPart")
		local fl = IN.dir(d) or Vector3.new(0, 0, -1)
		local side = fl:Cross(UP)
		local away = root and IN.dir(pos - root.Position)
		if away and side:Dot(away) < 0 then
			side = -side
		end
		WK.curl(pos + side, side + UP * 0.4 + fl * 0.3, { n = 4, spread = 1.5, size = 2, drift = 7, life = 0.45 })
		WK.streaks(WK.look(pos, side * 0.6 + fl * 0.4 + UP * 0.5), { n = 3, length = 10, width = 0.28, spread = 1 })
		local torso = target:FindFirstChild("Torso") or target:FindFirstChild("UpperTorso")
		if torso then
			addTrail(torso, AIR, 0.3, 1.6)(0.8)
		end
	end

	---------------------------------------------------------------------
	-- HIS IDLE PRESENCE (on top of the WIND KIT's always-on wind; the
	-- shared walk / stand is untouched): standing still a while, not
	-- mid-move, now and then a breath of wind gathers round him - a faint
	-- whirl on the street, a few leaves lifted into a slow ordered orbit
	-- round his feet, the coat lifted and settling, a soft whoosh. Every
	-- screen, near its camera only
	---------------------------------------------------------------------
	function SM.breath(char, root)
		local WK = VFX.WindKit
		local I = SM.cfg("Idle")
		local R = I.Radius or 3.4
		local g = IN.ground(root.Position)
		WK.ground(g, R, { loops = 2, spin = 0.8, life = 1.6, dust = false, transparency = 0.55 })
		WK.debris(g + UP * 0.4, Vector3.zero, { n = I.Leaves or 3, kinds = { "leaf", "paper", "leaf" }, life = 2.2, orbit = { center = g + UP * 0.3, radius = R * 0.9, height = 2.4, spin = 0.45, climb = 0.9 } })
		IN.gust(char, 0.35, 1.3, I.Lift or 40)
		local side = root.CFrame.RightVector
		WK.curl(root.Position + side * 1.6 + UP * 0.5, UP + side * 0.2, { n = 1, size = 1.3, drift = 3, life = 0.6, spin = 240 })
		VFX.PlaySound("InasaIdleBreath", root.Position, I.Gain or 0.35)
	end
	function SM.idleStep()
		local WK = VFX.WindKit
		if not WK then
			return
		end
		local I = SM.cfg("Idle")
		local every = type(I.Every) == "table" and I.Every or { 4.5, 6.5 }
		local now = os.clock()
		local cam = IN.camPos()
		local seen = {}
		for _, char in IN.bodies do
			local root = char.Parent and char:FindFirstChild("HumanoidRootPart")
			local hum = root and char:FindFirstChildOfClass("Humanoid")
			if root and hum and hum.Health > 0 and IN.isInasa(char) then
				seen[char] = true
				local st = SM.idle[char]
				if not st then
					st = { still = now, at = now + rand(every[1], every[2]), token = VFX.PoseToken(char) }
					SM.idle[char] = st
				end
				local v = root.AssemblyLinearVelocity
				local token = VFX.PoseToken(char)
				-- (busy: moving, a move or a swing just now - any pose or clip on him - hit)
				local busy = v ~= v or Vector3.new(v.X, 0, v.Z).Magnitude > 2 or math.abs(v.Y) > 6 or token ~= st.token
					or now - (SM.moved[char] or -1e9) < 2.5 or IN.walls[char] ~= nil or IN.boards[char] ~= nil
					or char:GetAttribute("Stunned") == true or char:GetAttribute("Ragdolled") == true or char:GetAttribute("Grabbed") == true
				st.token = token
				if busy then
					st.still = now
				elseif now - st.still >= (I.After or 3) and now >= st.at then
					st.at = now + rand(every[1], every[2])
					local torso = char:FindFirstChild("Torso") or char:FindFirstChild("UpperTorso")
					if (root.Position - cam).Magnitude <= (I.Range or 70) and not WK.isHeld(char) and not WK.hidden(torso) then
						SM.breath(char, root)
					end
				end
			end
		end
		for char in SM.idle do
			if not seen[char] then
				SM.idle[char] = nil
			end
		end
		-- (stale: bodies gone)
		for _, t in { SM.live, SM.moved, SM.goes, SM.pending, SM.heldFor } do
			for char in t do
				if typeof(char) ~= "Instance" or not char.Parent then
					t[char] = nil
				end
			end
		end
	end
	task.spawn(function()
		while true do
			task.wait(0.25)
			local ok, err = pcall(SM.idleStep)
			if not ok and not SM.warned then
				SM.warned = true
				warn("[VFX.InasaStorm] " .. tostring(err))
			end
		end
	end)

	---------------------------------------------------------------------
	-- ULT 3: SKYBREAKER CYCLONE - his windup (his screen: the cutscene)
	---------------------------------------------------------------------
	function VFX.StreetTitle(guiName, holderName, text, mine, life, who)
		-- ((round 100) Stark Street's big words over the world (Inasa's and
		-- Saitama's titles): Oswald in paper with a hard ink shadow (no stroke), on
		-- the rise (-6: rising to the right), stamped 1.12 -> 1 with no bounce;
		-- everyone else's smaller, at the top, with whose it is over it)
		local me = Players.LocalPlayer
		local pg = me and me:FindFirstChildOfClass("PlayerGui")
		if not pg then
			return nil
		end
		local g = pg:FindFirstChild(guiName)
		if not g then
			g = Instance.new("ScreenGui")
			g.Name = guiName
			g.IgnoreGuiInset = true
			g.ResetOnSpawn = false
			g.DisplayOrder = 24
			g.Parent = pg
		end
		local S = Config.UI.Street
		local face = Font.new(S.Fonts.Display.Family, Enum.FontWeight.Bold)
		local K = S.Fonts.Display.K
		local cam = workspace.CurrentCamera
		local vy = cam and cam.ViewportSize.Y or 720
		local k = math.clamp(vy / 720, 0.6, 1.5)
		local em = (mine and 96 or 30) * k -- (the em px; Roblox's TextSize is the line: em * K)
		local ts = em * K
		local big = math.max(ts / 100, 1)
		local holder = Instance.new("Frame")
		holder.Name = holderName
		holder.BackgroundTransparency = 1
		holder.AnchorPoint = Vector2.new(0.5, 0.5)
		holder.Position = mine and UDim2.fromScale(0.5, 0.36) or UDim2.fromScale(0.5, 0.2)
		-- (one UIScale does both: past Roblox's 100 TextSize - big - and the stamp,
		-- from 1.12 of that down to it; the words sit right in the holder)
		holder.Size = UDim2.fromOffset(math.floor(vy * 1.6 / big), math.floor(ts * 1.6 / big))
		holder.Rotation = mine and -6 or -3
		holder.Parent = g
		local stamp = Instance.new("UIScale")
		stamp.Name = "Stamp"
		stamp.Scale = big * 1.12
		stamp.Parent = holder
		local function label(name, offset, color)
			local l = Instance.new("TextLabel")
			l.Name = name
			l.BackgroundTransparency = 1
			l.Size = UDim2.new(1, 0, 0, math.ceil(ts / big))
			l.AnchorPoint = Vector2.new(0.5, 1)
			l.Position = UDim2.new(0.5, offset, 1, offset)
			l.FontFace = face
			l.TextSize = math.min(ts, 100)
			l.TextScaled = false
			l.Text = text
			l.TextColor3 = color
			l.Parent = holder
			return l
		end
		label("Shadow", math.max(2, math.floor(em * 0.05 / big + 0.5)), S.Ink).ZIndex = 1
		label("Text", 0, S.Paper).ZIndex = 2
		if who then
			local small = Instance.new("TextLabel")
			small.Name = "Who"
			small.BackgroundTransparency = 1
			small.AnchorPoint = Vector2.new(0, 1)
			small.Position = UDim2.new(0.08, 0, 1, -math.ceil(ts / big))
			small.Size = UDim2.new(0.84, 0, 0, math.ceil(14 * k * K / big))
			small.FontFace = face
			small.TextSize = math.min(14 * k * K, 100)
			small.TextXAlignment = Enum.TextXAlignment.Left
			small.Text = who
			small.TextColor3 = S.Paper
			small.TextTransparency = 0.25
			small.Parent = holder
		end
		tween(stamp, 0.06, { Scale = big }, Enum.EasingStyle.Quad, Enum.EasingDirection.Out)
		task.delay(0.07, function()
			stamp.Scale = big -- (the end state, even if frames were skipped)
		end)
		task.delay(life or 1, function()
			for _, l in holder:GetDescendants() do
				if l:IsA("TextLabel") then
					tween(l, 0.2, { TextTransparency = 1 })
				end
			end
			task.wait(0.22)
			holder:Destroy()
		end)
		return holder
	end
	function IN.title(text, mine, life, who)
		return VFX.StreetTitle("InasaTitles", "InasaTitle", text, mine, life, who)
	end
	-- ((round 99) INASA_ULT: the cutscene's shots - IN.shots - are VFX.IN.U's,
	-- in the INASA_ULT block after the WIND KIT)
	-- his name, for everyone else's titles
	function IN.whoName(char)
		local ok, nm = pcall(function()
			local who = Players:GetPlayerFromCharacter(char)
			return who and who.DisplayName
		end)
		return string.upper(ok and type(nm) == "string" and nm ~= "" and nm or char.Name)
	end
	-- ((round 99) INASA_ULT: his windup - Effects.SkyCyclone - is in the
	-- INASA_ULT block)

	---------------------------------------------------------------------
	-- THE CYCLONE ITSELF, on every screen (from the server's word)
	---------------------------------------------------------------------
	-- find a storm by its owner, or (his body's not on this screen) by where it is
	function IN.storm(char, pos)
		for _, st in IN.storms do
			if (char and st.char == char) or (pos and (st.pos - pos).Magnitude < 5) then
				return st
			end
		end
		return nil
	end
	function IN.chunk(st, pos)
		local S = CY.PieceSize or { 1.2, 4.5 }
		local s = rand(S[1], S[2])
		local colors = { Color3.fromRGB(130, 126, 122), Color3.fromRGB(96, 92, 90), Color3.fromRGB(168, 160, 148), Color3.fromRGB(110, 118, 128) }
		return newPart(Vector3.new(s, s * rand(0.5, 1), s * rand(0.7, 1.3)), CFrame.new(pos), colors[rng:NextInteger(1, #colors)], Enum.Material.Concrete, nil, st.model)
	end
	-- ((round 99) INASA_ULT: the cyclone - IN.addPiece, Effects.SkyCycloneGo /
	-- Debris / Hurl / Cancel - is remade on the WIND KIT in the INASA_ULT block)

	---------------------------------------------------------------------
	-- the awakening, the dash, the M1s, the finisher
	---------------------------------------------------------------------
	-- ((round 99) INASA_ULT: the awakening is PASSION STORM in the INASA_ULT
	-- block - (round 101) VFX.AK.FX.Whirlwind)
	-- a dash on a gust ((round 99) INASA_STORM, on the WIND KIT): it bursts
	-- off his ankle rings down at the street behind him (a flat whirl where
	-- he pushed off, its dust thrown out), streaks left along his line at
	-- his legs, curls peeling off his heels, his coat streamed out flat
	-- behind him - low and off his back, so his own camera isn't whited out
	QUIRK_FX.Dash.Whirlwind = function(char, root, dir)
		local d = typeof(dir) == "Vector3" and dir.Magnitude > 0.05 and dir.Unit or IN.flat(root.CFrame.LookVector, root)
		local flat = IN.dir(d) or IN.flat(root.CFrame.LookVector, root)
		local WK = VFX.WindKit
		local DS = SM.cfg("Dash")
		VFX.PlaySound("InasaDash", root.Position, 1)
		VFX.PlaySound("InasaDashGust", root.Position, 0.9)
		IN.gust(char, 0.8, 0.5, DS.Cape or 95)
		if not WK then
			return
		end
		local torso = char:FindFirstChild("Torso")
		local scale = torso and torso.Size.Y / 2 or 1
		WK.vent(char, { "Ankles" }, { dir = -flat - UP * 0.4, speed = 16, n = 4, size = 0.7 })
		local g = IN.ground(root.Position)
		if (root.Position - g).Magnitude < 5 * scale then
			WK.ground(g - flat * 1.5, DS.Radius or 3.4, { loops = 2, spin = 2.2, life = 0.45 })
		end
		WK.streaks(WK.look(root.Position - UP * 1.6 * scale - flat * 0.5, -flat), { n = 3, length = 8, width = 0.24, spread = 1.1 })
		WK.curl(root.Position - flat * 1.5 - UP * 2 * scale, -flat + UP * 0.5, { n = DS.Curls or 2, spread = 1.2, size = 1.4, drift = 4, life = 0.4 })
	end
	-- (Effects.Punch: his M1s' trail colour; (round 99) INASA_STRIKES: his M1
	-- set, VFX.InasaPunch and the SKY-HIGH SEND-OFF, IN.finisher, are remade
	-- in the strikes block below)
	M1_TRAIL.Whirlwind = AIR

	-- (stale state: bodies gone - every 2 s)
	task.spawn(function()
		while true do
			task.wait(2)
			for key, tw in IN.tornados do
				if os.clock() - tw.t0 > tw.life + 3 then
					tw.stop(true)
				end
				if typeof(key) == "Instance" and not key.Parent then
					tw.stop(true)
				end
			end
			for char, w in IN.walls do
				if not char.Parent then
					w.stop()
				end
			end
			for char, b in IN.boards do
				if not char.Parent then
					b.stop()
				end
			end
			for char, r in IN.runs do
				if not char.Parent then
					r.stop(true)
				end
			end
			for char, r in IN.rides do
				if not char.Parent then
					r.stop("Gone")
				end
			end
		end
	end)
end)()

---------------------------------------------------------------------------
-- (round 99) THE WIND KIT (VFX.WindKit - "WK"): Inasa's wind, made once and
-- used by every move of his, drawn the way the anime draws it (r99
-- inasa_research section 2): matte white SHAPES with a pale blue-lavender
-- shade on their inner edge, never glow - tapered crescent bands (stacked
-- into every gust front, ring and funnel), thin streak lines that draw
-- themselves head first and erase from the tail, comma-shaped curls
-- peeling off the edges, translucent haze, dust at the foot of a gust, and
-- the leaves, paper, grit and rubble it carries in ordered arcs. Curved
-- Beams facing the camera (true circle arcs: a Bezier's curve sizes are
-- 4/3 tan(t/4) r), a few built-in particle textures, plain parts for what
-- it carries. One stepper moves everything (WK.live, on the pose clock's
-- warp: the director's slow motion slows it too); every call caps what it
-- makes (Config.Inasa.Kit.Caps, half on a low-end machine), thins away
-- near the camera and cleans itself up. And his ALWAYS-ON WIND (WK.drive:
-- every screen, every Inasa near its camera) and held sound beds (WK.loop).
-- The reference, an example call for each function: r99 out/windkit.md.
-- (In a function of its own: the main chunk is at its local limit.)
---------------------------------------------------------------------------
;(function()
	local WK = { live = {}, auras = {}, held = {}, forced = {}, charges = {} }
	VFX.WindKit = WK
	-- (a number from anything - nil for junk: NaN and the infinities too, so a
	-- NaN in an option falls back to its default and never reaches a CFrame)
	local rawnum = tonumber
	local function tonumber(v)
		local n = rawnum(v)
		if n and n == n and n > -1e9 and n < 1e9 then
			return n
		end
		return nil
	end
	WK.num = tonumber
	local IN = VFX.IN or {}
	local C = Config.Inasa or {}
	local WD = C.Wind or {}
	local KC = C.Kit or {}
	local CAPS = KC.Caps or {}
	local AU = C.Aura or {}
	local NS, NK, CS = NumberSequence.new, NumberSequenceKeypoint.new, ColorSequence.new
	local TAU = math.pi * 2
	local X3, Y3, Z3 = Vector3.new(1, 0, 0), Vector3.new(0, 1, 0), Vector3.new(0, 0, 1)
	local PAL = {
		AIR = WD.Air or Color3.fromRGB(242, 250, 255),
		CORE = WD.Core or Color3.new(1, 1, 1),
		SHADE = WD.Shade or Color3.fromRGB(175, 200, 235),
		SHADE_GROUND = WD.ShadeGround or Color3.fromRGB(198, 202, 208),
		HAZE = WD.Haze or Color3.fromRGB(225, 232, 242),
		DUST = WD.Dust or Color3.fromRGB(206, 192, 170),
		DUST_DARK = WD.DustDark or Color3.fromRGB(150, 136, 118),
		STORM = WD.Storm or Color3.fromRGB(178, 168, 148),
		STORM_DARK = WD.StormDark or Color3.fromRGB(104, 98, 88),
		HATCH = WD.Hatch or Color3.fromRGB(60, 56, 52),
		RUBBLE = WD.Rubble or Color3.fromRGB(110, 110, 115),
		RUBBLE_LIGHT = WD.RubbleLight or Color3.fromRGB(150, 150, 150),
		SMOKE = WD.Smoke or Color3.fromRGB(62, 58, 62),
		EMBER = WD.Ember or Color3.fromRGB(220, 60, 50),
		PASSION = WD.Passion or Color3.fromRGB(196, 44, 66),
		SKY_DEEP = WD.SkyDeep or Color3.fromRGB(25, 55, 165),
		SKY_MID = WD.SkyMid or Color3.fromRGB(70, 120, 210),
		GRASS = WD.Grass or Color3.fromRGB(58, 84, 40),
		PAPER = WD.Paper or Color3.fromRGB(240, 238, 228),
		LEAVES = WD.Leaves or { Color3.fromRGB(116, 160, 70) },
	}
	WK.PAL = PAL
	-- built-in textures (every client has them)
	local TEX = {
		smoke = (Config.Assets and Config.Assets.SmokeTexture) or "rbxasset://textures/particles/smoke_main.dds",
		ring = "rbxasset://textures/particles/explosion01_shockwave_main.dds",
		glow = "rbxasset://textures/particles/explosion01_implosion_main.dds",
		spark = "rbxasset://textures/particles/sparkles_main.dds",
	}
	WK.TEX = TEX
	local LIGHT, INFL, BRIGHT = KC.Light or 0.12, KC.Influence or 0.3, KC.Bright or 1.2

	---------------------------------------------------------------------
	-- the basics
	---------------------------------------------------------------------
	-- a low-end machine (IceKit.lowEnd: the graphics slider, or under 40 fps) gets half
	function WK.low()
		return IceKit.lowEnd()
	end
	-- a count: whole, at least 0, halved on a low-end machine (at least 1 of
	-- something asked for)
	function WK.n(x)
		x = math.max(math.floor(tonumber(x) or 0), 0)
		if x > 0 and WK.low() then
			return math.max(math.floor(x * 0.5 + 0.5), 1)
		end
		return x
	end
	-- the kit's clock: the wall clock through the director's slow motion
	function WK.now()
		return VFX.WarpTime(os.clock())
	end
	-- a usable point (nil for junk: NaN, a nonsense distance, not a Vector3)
	function WK.v3(v)
		if typeof(v) ~= "Vector3" or v ~= v or v.Magnitude > 1e6 then
			return nil
		end
		return v
	end
	-- a unit direction from v (fallback for junk or zero)
	function WK.dir(v, fallback)
		if typeof(v) == "Vector3" and v == v then
			local m = v.Magnitude
			if m > 1e-3 and m < 1e7 then
				return v / m
			end
		end
		return fallback
	end
	-- a CFrame from a CFrame, a point, a part or an attachment (nil for junk)
	function WK.cf(v)
		local t = typeof(v)
		if t == "CFrame" then
			local lv = v.LookVector
			return WK.v3(v.Position) and lv == lv and v or nil
		elseif t == "Vector3" then
			local p = WK.v3(v)
			return p and CFrame.new(p) or nil
		elseif t == "Instance" then
			if v:IsA("BasePart") then
				return v.Parent and WK.v3(v.CFrame.Position) and v.CFrame or nil
			elseif v:IsA("Attachment") then
				local p = v.Parent
				return p and p:IsA("BasePart") and p.CFrame * v.CFrame or nil
			end
		end
		return nil
	end
	-- a CFrame at pos looking along dir (-Z), its up as near `up` as it can be
	-- (never CFrame.lookAt: a dir straight up or down is fine here)
	function WK.look(pos, dir, up)
		dir = WK.dir(dir, Vector3.new(0, 0, -1))
		up = WK.dir(up, UP)
		if math.abs(dir:Dot(up)) > 0.98 then
			up = math.abs(dir.X) < 0.9 and X3 or Z3
		end
		local right = dir:Cross(up).Unit
		return CFrame.fromMatrix(pos, right, right:Cross(dir))
	end
	-- a frame at pos whose Y axis is `axis` (a funnel's)
	function WK.upFrame(pos, axis)
		axis = WK.dir(axis, UP)
		local x = axis:Cross(Z3)
		if x.Magnitude < 0.1 then
			x = axis:Cross(X3)
		end
		return CFrame.fromMatrix(pos, x.Unit, axis)
	end
	-- an invisible anchored part to hang the attachments, beams and emitters on
	function WK.holder(cf, name)
		local p = newPart(Vector3.one * 0.2, cf, PAL.AIR)
		p.Name = "InasaWind" .. (name or "")
		p.Transparency = 1
		return p
	end
	function WK.att(parent, cf)
		local a = Instance.new("Attachment")
		a.Name = "InasaWind"
		if cf then
			a.CFrame = cf
		end
		a.Parent = parent
		return a
	end
	-- a Beam (facing the camera, matte: the anime's wind doesn't glow).
	-- st: transp (a NumberSequence), light, influence, bright, segments, z
	function WK.beam(a0, a1, color, w0, w1, parent, st)
		st = st or {}
		local b = Instance.new("Beam")
		b.Name = "InasaWind"
		b.Attachment0 = a0
		b.Attachment1 = a1
		b.Color = typeof(color) == "ColorSequence" and color or CS(typeof(color) == "Color3" and color or PAL.AIR)
		b.Transparency = st.transp or NS(0.2)
		b.Width0 = w0 or 0.3
		b.Width1 = w1 or w0 or 0.3
		b.FaceCamera = true
		b.LightEmission = st.light or LIGHT
		b.LightInfluence = st.influence or INFL
		b.Brightness = st.bright or BRIGHT
		b.Segments = st.segments or 10
		b.ZOffset = st.z or 0
		b.Parent = parent
		return b
	end
	-- a see-through NumberSequence for opacity o (0..1, cached in 1/24
	-- steps): "flat"; "rise" (fainter at its start), "fall" (at its end),
	-- "lens" (both ends gone), "tail" (gone at its start: a streak's tail)
	local seqs = {}
	function WK.seq(o, shape)
		local q = math.clamp(math.floor((tonumber(o) or 0) * 24 + 0.5), 0, 24)
		shape = shape or "flat"
		local key = shape .. q
		local s = seqs[key]
		if not s then
			local v = 1 - q / 24
			local soft = 1 - (1 - v) * 0.4
			if shape == "rise" then
				s = NS({ NK(0, soft), NK(0.45, v), NK(1, v) })
			elseif shape == "fall" then
				s = NS({ NK(0, v), NK(0.55, v), NK(1, soft) })
			elseif shape == "lens" then
				s = NS({ NK(0, 1), NK(0.3, v), NK(0.7, v), NK(1, 1) })
			elseif shape == "tail" then
				s = NS({ NK(0, 1), NK(0.6, v), NK(1, v) })
			else
				s = NS(v)
			end
			seqs[key] = s
		end
		return s
	end
	-- 0 at the camera .. 1 from Near[2] studs out: what's this close thins
	-- away (his own screen is never whited out by his own wind)
	function WK.nearK(pos, camPos)
		local N = KC.Near or { 2.5, 6 }
		return math.clamp(((pos - camPos).Magnitude - N[1]) / math.max(N[2] - N[1], 0.1), 0, 1)
	end
	function WK.cam()
		local cam = workspace.CurrentCamera
		return cam and cam.CFrame or CFrame.new()
	end
	-- move parts in one go (VFX.IN.move: BulkMoveTo)
	function WK.move(parts, cfs)
		if #parts == 0 then
			return
		end
		if IN.move then
			IN.move(parts, cfs)
		else
			for i, p in parts do
				p.CFrame = cfs[i]
			end
		end
	end
	local function rotAbout(v, axis, a)
		return v * math.cos(a) + axis:Cross(v) * math.sin(a) + axis * axis:Dot(v) * (1 - math.cos(a))
	end
	WK.rotAbout = rotAbout

	---------------------------------------------------------------------
	-- THE STEPPER: everything that moves is an item { step(item, t, dt,
	-- now) -> keep?, kill(item), holder (destroyed with it), life (its
	-- most) } - one RenderStepped for the lot. Past Kit.Live items at once
	-- the one nearest its end goes ((round 99 review) not the oldest: that
	-- was the long-lived handle - a cyclone, a curtain - wiped mid-move by
	-- a crowd of short gusts); an item that errors is dropped (one warning)
	---------------------------------------------------------------------
	function WK.run(item)
		item.t0 = item.t0 or WK.now()
		item.life = math.min(tonumber(item.life) or 30, 60)
		table.insert(WK.live, item)
		local list = WK.live
		while #list > (KC.Live or 160) do
			local pick, best = 1, math.huge
			for i, it in list do
				local ends = (it.t0 or 0) + (it.life or 0)
				if ends < best then
					pick, best = i, ends
				end
			end
			WK.kill(table.remove(list, pick))
		end
		return item
	end
	-- gone after t seconds (on the stepper, not Debris: the director's slow
	-- motion holds it too)
	function WK.after(obj, t)
		WK.run({ holder = obj, life = t, step = function()
			return true
		end })
		return obj
	end
	function WK.kill(item)
		if item and not item.dead then
			item.dead = true
			if item.kill then
				pcall(item.kill, item)
			end
			if item.holder then
				pcall(item.holder.Destroy, item.holder)
			end
		end
	end
	function WK.tick(dt)
		local now = WK.now()
		dt = math.clamp((tonumber(dt) or 1 / 60) * ((VFX.Warp and VFX.Warp.scale) or 1), 0, 0.1)
		local list = WK.live
		local i = 1
		while i <= #list do
			local it = list[i]
			local t = now - it.t0
			local keep = false
			if not it.dead and t <= it.life and not (it.holder and not it.holder.Parent) then
				local ok, res = pcall(it.step, it, t, dt, now)
				keep = ok and res ~= false
				if not ok and not WK.warned then
					WK.warned = true
					warn("[VFX.WindKit] " .. tostring(res))
				end
			end
			if keep then
				i += 1
			else
				table.remove(list, i)
				WK.kill(it)
			end
		end
	end
	RunService.RenderStepped:Connect(WK.tick)

	---------------------------------------------------------------------
	-- the geometry: arcs of circles as curved Beams
	---------------------------------------------------------------------
	-- on the circle (centre c, radius r, in the plane of unit u and v) at
	-- angle a: a CFrame whose X axis runs along it (an attachment a curved
	-- Beam leaves along)
	local function arcCF(c, u, v, r, a)
		local cs, sn = math.cos(a), math.sin(a)
		return CFrame.fromMatrix(c + (u * cs + v * sn) * r, v * cs - u * sn, u:Cross(v))
	end
	WK.arcCF = arcCF
	-- the curve size that makes a Bezier the circle's arc (span radians, radius r)
	local function bend(span, r)
		return 4 / 3 * math.tan(span / 4) * r
	end
	WK.bend = bend

	-- THE BAND (the anime's shape A): a crescent fat in the middle and
	-- pointed at both ends - two Beams meeting at a middle attachment, each
	-- curved to the circle - and, off a low-end machine, its shade: a
	-- narrower stroke along its inner edge (opts.shade: a colour; nil = none).
	-- 3 (+2) attachments, 2 (+1) beams. WK.layBand puts it on its circle
	function WK.band(parent, opts)
		opts = opts or {}
		local b = { atts = {}, beams = {}, q = -1, shadeK = opts.shadeK or 0.6 }
		for i = 1, 3 do
			b.atts[i] = WK.att(parent)
		end
		local col = CS(opts.color or PAL.AIR)
		local st = { segments = opts.segments or 10, z = opts.z, light = opts.light }
		b.beams[1] = WK.beam(b.atts[1], b.atts[2], col, 0.05, 1, parent, st)
		b.beams[2] = WK.beam(b.atts[2], b.atts[3], col, 1, 0.05, parent, st)
		if opts.shade and not WK.low() then
			b.s0, b.s1 = WK.att(parent), WK.att(parent)
			b.sb = WK.beam(b.s0, b.s1, opts.shade, 0.5, 0.5, parent, { segments = 8, z = (opts.z or 0) + 0.04, light = 0 })
		end
		return b
	end
	-- lay a band on its circle (in its parent's space): angles a0 .. a1, width w,
	-- opacity o; rise: studs it climbs out of the circle's plane from a0 to a1
	-- (a helix's piece: a tornado's bands spiral)
	local function riseCF(cf, nrm, h, slope)
		if h == 0 and slope == 0 then
			return cf
		end
		local x = (cf.RightVector + nrm * slope).Unit
		return CFrame.fromMatrix(cf.Position + nrm * h, x, nrm:Cross(x).Magnitude > 1e-3 and x:Cross(nrm:Cross(x)).Unit or cf.UpVector)
	end
	WK.riseCF = riseCF
	function WK.layBand(b, c, u, v, r, a0, a1, w, o, rise)
		local am = (a0 + a1) / 2
		local k = bend((a1 - a0) / 2, r)
		rise = tonumber(rise) or 0
		local nrm = rise ~= 0 and u:Cross(v) or nil
		local slope = rise ~= 0 and rise / math.max((a1 - a0) * r, 0.1) or 0
		if nrm then
			b.atts[1].CFrame = riseCF(arcCF(c, u, v, r, a0), nrm, -rise / 2, slope)
			b.atts[2].CFrame = riseCF(arcCF(c, u, v, r, am), nrm, 0, slope)
			b.atts[3].CFrame = riseCF(arcCF(c, u, v, r, a1), nrm, rise / 2, slope)
		else
			b.atts[1].CFrame = arcCF(c, u, v, r, a0)
			b.atts[2].CFrame = arcCF(c, u, v, r, am)
			b.atts[3].CFrame = arcCF(c, u, v, r, a1)
		end
		local tip = math.max(w * 0.06, 0.03)
		local b1, b2 = b.beams[1], b.beams[2]
		b1.CurveSize0, b1.CurveSize1, b2.CurveSize0, b2.CurveSize1 = k, k, k, k
		b1.Width0, b1.Width1, b2.Width0, b2.Width1 = tip, w, w, tip
		if b.sb then
			local rs = math.max(r - w * 0.3, r * 0.5)
			local s0, s1 = a0 + (a1 - a0) * 0.18, a1 - (a1 - a0) * 0.18
			if nrm then
				b.s0.CFrame = riseCF(arcCF(c, u, v, rs, s0), nrm, -rise * 0.32, slope)
				b.s1.CFrame = riseCF(arcCF(c, u, v, rs, s1), nrm, rise * 0.32, slope)
			else
				b.s0.CFrame = arcCF(c, u, v, rs, s0)
				b.s1.CFrame = arcCF(c, u, v, rs, s1)
			end
			local ks = bend(s1 - s0, rs)
			b.sb.CurveSize0, b.sb.CurveSize1 = ks, ks
			b.sb.Width0, b.sb.Width1 = w * 0.38, w * 0.38
		end
		WK.fadeBand(b, o)
	end
	function WK.fadeBand(b, o)
		local q = math.floor(math.clamp(o, 0, 1) * 24 + 0.5)
		if q == b.q then
			return
		end
		b.q = q
		local on = q > 0
		b.beams[1].Transparency = WK.seq(o, "rise")
		b.beams[2].Transparency = WK.seq(o, "fall")
		b.beams[1].Enabled, b.beams[2].Enabled = on, on
		if b.sb then
			b.sb.Transparency = WK.seq(o * b.shadeK, "lens")
			b.sb.Enabled = on
		end
	end
	function WK.colorBand(b, color, shade)
		local col = CS(color)
		b.beams[1].Color, b.beams[2].Color = col, col
		if b.sb and shade then
			b.sb.Color = CS(shade)
		end
	end

	-- a crisp ring: 4 curved beams (quarter circles), laid with ringLay
	local function ringMake(parent, color, w)
		local r = { atts = {}, beams = {}, q = -1 }
		for q = 0, 3 do
			r.atts[q] = WK.att(parent)
		end
		for q = 0, 3 do
			r.beams[q] = WK.beam(r.atts[q], r.atts[(q + 1) % 4], color, w, w, parent, { segments = 10 })
		end
		return r
	end
	local function ringLay(r, c, u, v, rad, w, o)
		local k = bend(math.pi / 2, rad)
		local q = math.floor(math.clamp(o, 0, 1) * 24 + 0.5)
		for i = 0, 3 do
			r.atts[i].CFrame = arcCF(c, u, v, rad, i * math.pi / 2)
			local b = r.beams[i]
			b.CurveSize0, b.CurveSize1 = k, k
			b.Width0, b.Width1 = w, w
			if q ~= r.q then
				b.Transparency = WK.seq(o)
				b.Enabled = q > 0
			end
		end
		r.q = q
	end
	WK.ringMake, WK.ringLay = ringMake, ringLay

	-- a streak: one beam whose tail and head slide along an arc (the head
	-- fat, the tail thin and see-through)
	local function streakMake(parent, color)
		local s = { a0 = WK.att(parent), a1 = WK.att(parent) }
		s.beam = WK.beam(s.a0, s.a1, color or PAL.AIR, 0.05, 0.3, parent, { segments = 8 })
		s.beam.Enabled = false
		return s
	end
	local function streakLay(s, c, u, v, r, aTail, aHead, w, o)
		if aHead - aTail < 1e-4 or o <= 0.02 then
			s.beam.Enabled = false
			return
		end
		s.a0.CFrame = arcCF(c, u, v, r, aTail)
		s.a1.CFrame = arcCF(c, u, v, r, aHead)
		local k = bend(aHead - aTail, r)
		s.beam.CurveSize0, s.beam.CurveSize1 = k, k
		s.beam.Width0, s.beam.Width1 = w * 0.15, w
		s.beam.Transparency = WK.seq(o, "tail")
		s.beam.Enabled = true
	end
	-- a straight streak from p0 (its tail) to p1 (its head), in its parent's space
	local function streakLine(s, p0, p1, w, o)
		local d = p1 - p0
		if d.Magnitude < 0.02 or o <= 0.02 then
			s.beam.Enabled = false
			return
		end
		local x = d.Unit
		local y = math.abs(x.Y) < 0.95 and UP or X3
		s.a0.CFrame = CFrame.fromMatrix(p0, x, x:Cross(y).Unit)
		s.a1.CFrame = CFrame.fromMatrix(p1, x, x:Cross(y).Unit)
		s.beam.CurveSize0, s.beam.CurveSize1 = 0, 0
		s.beam.Width0, s.beam.Width1 = w * 0.15, w
		s.beam.Transparency = WK.seq(o, "tail")
		s.beam.Enabled = true
	end
	WK.streakMake, WK.streakLay, WK.streakLine = streakMake, streakLay, streakLine

	---------------------------------------------------------------------
	-- WK.streaks(cf, opts) -> holder: THIN STREAK LINES (shape B) - n long
	-- gently curved strokes sweeping along cf.LookVector, each drawing itself
	-- head first and erasing from its tail. Their starts are spread evenly
	-- over a disc across the look (spread studs); they curve round
	-- cf.UpVector (opts.axis = "side": round cf.RightVector; or a Vector3).
	-- opts: n (5, at most Caps.Streaks), length (14 studs), radius (the
	-- curve's, length * 2.5), bend (1 / -1: all one way; nil: alternate),
	-- speed (studs/s, length / 0.28), lag (how long the tail trails the
	-- head), width (0.35), spread (2.5), stagger (0.03 s between them),
	-- color, transparency (0.1)
	---------------------------------------------------------------------
	function WK.streaks(cf, opts)
		opts = type(opts) == "table" and opts or {}
		cf = WK.cf(cf)
		local n = WK.n(math.min(tonumber(opts.n) or 5, CAPS.Streaks or 12))
		if not cf or n <= 0 then
			return nil
		end
		local len = math.clamp(tonumber(opts.length) or 14, 0.5, 600)
		local R = math.clamp(tonumber(opts.radius) or len * 2.5, 1, 1e4)
		local speed = math.max(tonumber(opts.speed) or len / 0.28, 1)
		local draw = len / speed
		local lag = math.max(tonumber(opts.lag) or draw * 0.6, 0.02)
		local w = math.clamp(tonumber(opts.width) or 0.35, 0.05, 20)
		local spread = math.max(tonumber(opts.spread) or 2.5, 0)
		local stagger = math.max(tonumber(opts.stagger) or 0.03, 0)
		local base = 1 - math.clamp(tonumber(opts.transparency) or 0.1, 0, 1)
		local look, right, up = cf.LookVector, cf.RightVector, cf.UpVector
		local axis = opts.axis == "side" and right or WK.dir(opts.axis, up)
		local holder = WK.holder(CFrame.new(cf.Position), "Streaks")
		local list = {}
		for i = 1, n do
			-- (an even spread: a sunflower over the disc)
			local ga = i * 2.39996
			local rad = spread * math.sqrt((i - 0.5) / n)
			local off = (right * math.cos(ga) + up * math.sin(ga)) * rad + look * rand(-0.12, 0.12) * len
			local sign = (opts.bend == 1 or opts.bend == -1) and opts.bend or (i % 2 == 0 and 1 or -1)
			local side = axis:Cross(look)
			side = (side.Magnitude > 1e-3 and side.Unit or right) * sign
			local r = R * rand(0.8, 1.25)
			local s = streakMake(holder, opts.color)
			s.c, s.u, s.v, s.r = off + side * r, -side, look, r
			s.span = len * rand(0.85, 1.12) / r
			s.delay = stagger * (i - 1) * rand(0.6, 1.4)
			s.w = w * rand(0.8, 1.15)
			list[i] = s
		end
		WK.run({ holder = holder, life = draw + lag + stagger * n * 1.5 + 0.4, step = function(_, t)
			local camPos = WK.cam().Position
			local hp = cf.Position
			local alive = false
			for _, s in list do
				local tt = t - s.delay
				if tt < 0 then
					alive = true
				else
					local hk = math.min(tt / draw, 1)
					local tk = math.clamp((tt - lag) / draw, 0, 1)
					local h = 1 - (1 - hk) * (1 - hk)
					local e = 1 - (1 - tk) * (1 - tk)
					local o = base * math.min(tt / 0.035, 1) * (1 - tk * tk) * WK.nearK(hp + s.c + s.u * s.r, camPos)
					streakLay(s, s.c, s.u, s.v, s.r, s.span * e, s.span * h, s.w, o)
					if tk < 1 then
						alive = true
					end
				end
			end
			return alive
		end })
		return holder
	end

	---------------------------------------------------------------------
	-- THE CURL (shape C): a comma - a fat teardrop head and a thin tail
	-- hooking back - one Beam drawn in the plane facing the camera (so it
	-- reads from any side), spinning and drifting along dir as it fades.
	-- The anime's most characteristic wind glyph: scatter them at a gust's
	-- edges and round every ring. Slots: an effect keeps a few on its own
	-- holder and re-arms them (no new instances)
	---------------------------------------------------------------------
	local function curlSlot(parent, color)
		local s = { a0 = WK.att(parent), a1 = WK.att(parent), on = false }
		s.beam = WK.beam(s.a0, s.a1, color or PAL.AIR, 0.8, 0.06, parent, { segments = 12 })
		s.beam.Enabled = false
		return s
	end
	local function armCurl(s, pos, dir, o, at)
		o = type(o) == "table" and o or {}
		-- ((round 99 review) junk in, nothing out: a size of 0 made the
		-- tail's direction a zero vector's .Unit - a NaN attachment)
		pos = WK.v3(pos)
		if not pos then
			return
		end
		s.on, s.t0 = true, tonumber(at) or WK.now()
		s.pos, s.dir = pos, WK.dir(dir, UP)
		s.size = math.clamp(tonumber(o.size) or 2.2, 0.1, 80) * rand(0.85, 1.15)
		s.life = math.clamp(tonumber(o.life) or 0.42, 0.05, 10) * rand(0.85, 1.2)
		local spin = tonumber(o.spin) or 260 * (rng:NextNumber() < 0.5 and -1 or 1)
		s.spin = math.rad(spin)
		s.hook = spin >= 0 and 1 or -1
		s.drift = math.clamp(tonumber(o.drift) or 4, -200, 200)
		s.w = math.clamp(tonumber(o.width) or 0.85, 0.02, 20)
		s.base = 1 - math.clamp(tonumber(o.transparency) or 0.08, 0, 1)
	end
	local function stepCurl(s, now, cam, hcf)
		if not s.on then
			return false
		end
		if now < s.t0 then
			return true
		end
		local t = (now - s.t0) / s.life
		if t >= 1 then
			s.on = false
			s.beam.Enabled = false
			return false
		end
		local e = 1 - (1 - t) * (1 - t)
		local origin = s.pos + s.dir * s.drift * e
		local f = origin - cam.Position
		if f.Magnitude < 0.5 then
			s.beam.Enabled = false
			return true
		end
		f = f.Unit
		local x = s.dir - f * s.dir:Dot(f)
		x = x.Magnitude > 1e-3 and x.Unit or cam.RightVector
		local y = f:Cross(x)
		local ang = s.spin * e
		local xr = x * math.cos(ang) + y * math.sin(ang)
		local yr = (y * math.cos(ang) - x * math.sin(ang)) * s.hook
		local L = s.size * (1 + 0.25 * e)
		-- ((round 99 review) a tighter hook curling back in under its fat
		-- head: a comma, where the first cut read as a long "?")
		local p3 = origin + xr * 0.28 * L + yr * 0.6 * L
		local p2 = origin + xr * 0.95 * L + yr * L
		local d1 = p3 - p2
		local inv = hcf:Inverse()
		s.a0.CFrame = inv * CFrame.fromMatrix(origin, xr, f)
		s.a1.CFrame = inv * CFrame.fromMatrix(p3, d1.Unit, f)
		s.beam.CurveSize0 = 0.85 * L
		s.beam.CurveSize1 = d1.Magnitude
		local o = s.base * math.min(t / 0.12, 1) * (1 - math.max(t - 0.45, 0) / 0.55) * WK.nearK(origin, cam.Position)
		s.beam.Width0 = s.w * L / 2.2 * (1 - 0.35 * e)
		s.beam.Width1 = 0.05
		s.beam.Transparency = WK.seq(o)
		s.beam.Enabled = o > 0.02
		return true
	end
	WK.curlSlot, WK.armCurl, WK.stepCurl = curlSlot, armCurl, stepCurl

	-- WK.curl(pos, dir, opts) -> holder: n curls (1; at most Caps.Curls) at
	-- pos, drifting along dir. opts: n, spread (studs they're scattered,
	-- 1.5), size (2.2), life (0.42), spin (degrees over its life, 260 either
	-- way; its sign is the way it hooks), drift (4 studs), width (0.85),
	-- stagger (0.04 s), color, transparency
	function WK.curl(pos, dir, opts)
		opts = type(opts) == "table" and opts or {}
		pos = WK.v3(pos)
		if not pos then
			return nil
		end
		dir = WK.dir(dir, UP)
		local n = WK.n(math.clamp(math.floor(tonumber(opts.n) or 1), 1, CAPS.Curls or 8))
		local holder = WK.holder(CFrame.new(pos), "Curl")
		local slots = {}
		local now = WK.now()
		local spread = tonumber(opts.spread) or 1.5
		for i = 1, n do
			local s = curlSlot(holder, opts.color)
			local off = n > 1 and Vector3.new(rand(-1, 1), rand(-1, 1), rand(-1, 1)) * spread or Vector3.zero
			armCurl(s, pos + off, dir + off * 0.2, opts, now + (i - 1) * (tonumber(opts.stagger) or 0.04))
			slots[i] = s
		end
		WK.run({ holder = holder, life = 3, step = function(_, _t, _dt, now2)
			local cam, hcf = WK.cam(), holder.CFrame
			local any = false
			for _, s in slots do
				if stepCurl(s, now2, cam, hcf) then
					any = true
				end
			end
			return any
		end })
		return holder
	end

	---------------------------------------------------------------------
	-- WK.haze(cf, size, dir, opts) -> holder: THE HAZE (shape D): a broad
	-- translucent veil of air sweeping along dir (the body of a gust: its
	-- lines are only its edges). A burst of soft smoke from a box of `size`
	-- (studs: a number or a Vector3 across x up) at cf. Nothing on a
	-- low-end machine. opts: n (8), speed (1: x 20-60 studs/s), life (0.5),
	-- color (Haze), transparency (0.72: its thickest)
	---------------------------------------------------------------------
	function WK.haze(cf, size, dir, opts)
		opts = type(opts) == "table" and opts or {}
		cf = WK.cf(cf)
		if not cf or WK.low() then
			return nil
		end
		dir = WK.dir(dir, cf.LookVector)
		local sx, sy = 6, 4
		if typeof(size) == "Vector3" and size == size then
			sx, sy = math.clamp(size.X, 0.5, 200), math.clamp(size.Y, 0.5, 200)
		elseif tonumber(size) then
			sx, sy = math.clamp(tonumber(size), 0.5, 200), math.clamp(tonumber(size) * 0.6, 0.5, 120)
		end
		local holder = WK.holder(WK.look(cf.Position, dir), "Haze")
		holder.Size = Vector3.new(sx, sy, 0.4)
		local k = math.clamp(math.max(sx, sy) / 8, 0.4, 12)
		local spd = tonumber(opts.speed) or 1
		local life = tonumber(opts.life) or 0.5
		local pe = Instance.new("ParticleEmitter")
		pe.Name = "InasaWind"
		pe.Texture = TEX.smoke
		pe.Color = CS(opts.color or PAL.HAZE, PAL.AIR)
		pe.Transparency = NS({ NK(0, 1), NK(0.15, tonumber(opts.transparency) or 0.72), NK(1, 1) })
		pe.Size = NS({ NK(0, 6 * k), NK(1, 14 * k) })
		pe.Lifetime = NumberRange.new(life * 0.7, life * 1.2)
		pe.Speed = NumberRange.new(20 * spd, 60 * spd)
		pe.SpreadAngle = Vector2.new(8, 8)
		pe.Drag = 2
		pe.LightEmission = 0.05
		pe.LightInfluence = 0.5
		pe.Rotation = NumberRange.new(0, 360)
		pe.RotSpeed = NumberRange.new(-30, 30)
		pe.EmissionDirection = Enum.NormalId.Front
		pe.Rate = 0
		pe.Parent = holder
		pe:Emit(math.clamp(math.floor(tonumber(opts.n) or 8), 1, 14))
		WK.after(holder, life * 1.3 + 0.2)
		return holder
	end

	-- dust thrown out round a point on the street: one emitter, emitted once
	-- (n puffs: 12, half on a low-end machine)
	function WK.dustRing(g, R, opts)
		opts = type(opts) == "table" and opts or {}
		g = WK.v3(g)
		if not g then
			return nil
		end
		R = math.clamp(tonumber(R) or 6, 0.5, 300)
		local holder = WK.holder(WK.look(g + UP * 0.3, UP), "Dust")
		local pe = Instance.new("ParticleEmitter")
		pe.Name = "InasaWind"
		pe.Texture = TEX.smoke
		pe.Color = CS(opts.color or PAL.DUST, PAL.DUST_DARK)
		pe.Transparency = NS({ NK(0, 0.5), NK(0.4, 0.62), NK(1, 1) })
		pe.Size = NS({ NK(0, R * 0.16 + 0.8), NK(1, R * 0.42 + 2) })
		pe.Lifetime = NumberRange.new(0.5, 0.9)
		pe.Speed = NumberRange.new(R * 2.2, R * 3.4)
		pe.SpreadAngle = Vector2.new(82, 82)
		pe.Drag = 4
		pe.Acceleration = Vector3.new(0, -4, 0)
		pe.LightInfluence = 0.7
		pe.Rotation = NumberRange.new(0, 360)
		pe.RotSpeed = NumberRange.new(-40, 40)
		pe.EmissionDirection = Enum.NormalId.Front
		pe.Rate = 0
		pe.Parent = holder
		pe:Emit(WK.n(math.clamp(math.floor(tonumber(opts.n) or 12), 1, 24)))
		WK.after(holder, 1.2)
		return holder
	end

	---------------------------------------------------------------------
	-- WK.burst(pos, dir, opts) -> holder: AN IMPACT GUST - a pressure ring
	-- opening across dir (a crisp ring, its shaded twin just inside, a soft
	-- ring of air behind), short streaks radiating out of it, curls thrown
	-- off, and - near the street - a flat shock ring and a dust ring on it.
	-- opts: radius (6), grow (0.18 s), life (0.4), streaks (8), curls (4),
	-- ground (true: look for the street within 6 studs; false: never),
	-- haze (false), color, shade (Shade)
	---------------------------------------------------------------------
	function WK.burst(pos, dir, opts)
		opts = type(opts) == "table" and opts or {}
		pos = WK.v3(pos)
		if not pos then
			return nil
		end
		dir = WK.dir(dir, UP)
		local R = math.clamp(tonumber(opts.radius) or 6, 0.5, 300)
		local grow = math.max(tonumber(opts.grow) or 0.18, 0.02)
		local life = math.max(tonumber(opts.life) or 0.4, 0.05)
		local frame = WK.look(pos, dir)
		local holder = WK.holder(frame, "Burst")
		local wK = math.clamp(R / 6, 0.5, 6)
		local ring = ringMake(holder, opts.color or PAL.AIR, 0.5)
		local inner = not WK.low() and ringMake(holder, opts.shade or PAL.SHADE, 0.3) or nil
		local spokes = {}
		for i = 1, WK.n(math.clamp(math.floor(tonumber(opts.streaks) or 8), 0, CAPS.Streaks or 12)) do
			local a = (i - 0.5) * TAU / 8 + rand(-0.2, 0.2) + (i > 8 and 0.2 or 0)
			local s = streakMake(holder, opts.color)
			s.d = Vector3.new(math.cos(a), math.sin(a), 0)
			s.k = rand(0.8, 1.25)
			spokes[i] = s
		end
		local curls = {}
		local now0 = WK.now()
		local nc = WK.n(math.clamp(math.floor(tonumber(opts.curls) or 4), 0, CAPS.Curls or 8))
		for i = 1, nc do
			local a = (i - 0.5) / nc * TAU + rand(-0.4, 0.4)
			local d = frame:VectorToWorldSpace(Vector3.new(math.cos(a), math.sin(a), 0))
			local s = curlSlot(holder, opts.color)
			armCurl(s, pos + d * R * 0.55, d + dir * 0.3, { size = math.clamp(R * 0.35, 1, 14), drift = R * 0.7, life = life + 0.1 }, now0 + 0.03)
			curls[i] = s
		end
		-- the soft ring of air behind the crisp one
		local pe = Instance.new("ParticleEmitter")
		pe.Name = "InasaWind"
		pe.Texture = TEX.ring
		pe.Color = CS(PAL.AIR)
		pe.Size = NS({ NK(0, 2), NK(0.3, R * 2.4), NK(1, R * 2.9) })
		pe.Transparency = NS({ NK(0, 0.2), NK(0.5, 0.5), NK(1, 1) })
		pe.Lifetime = NumberRange.new(grow + life * 0.6, grow + life * 0.6)
		pe.Speed = NumberRange.new(0.5, 0.5)
		pe.LightEmission = 0.2
		pe.LightInfluence = 0.5
		pe.EmissionDirection = Enum.NormalId.Front
		pe.Rate = 0
		pe.Parent = holder
		pe:Emit(WK.low() and 1 or 2)
		-- the street under it
		local street
		if opts.ground ~= false then
			local hit = groundRay(pos, 9)
			if hit then
				local g = hit.Position
				street = { holder = WK.holder(CFrame.new(g + UP * 0.2), "BurstStreet") }
				street.holder.Parent = holder
				street.ring = ringMake(street.holder, PAL.AIR, 0.4)
				WK.dustRing(g, R * 0.9, { n = 10 })
			end
		end
		if opts.haze then
			WK.haze(CFrame.new(pos), R * 1.4, dir, { life = life + 0.1 })
		end
		local total = grow + life
		WK.run({ holder = holder, life = total + 0.8, step = function(_, t, _dt, now)
			local cam = WK.cam()
			local a = math.min(t / grow, 1)
			local e = 1 - (1 - a) ^ 3
			local f = math.clamp((t - grow * 0.6) / life, 0, 1)
			local rad = 0.8 + (R - 0.8) * e
			local o = (1 - f * f) * WK.nearK(pos, cam.Position)
			ringLay(ring, Vector3.zero, X3, Y3, rad, (0.12 + 0.42 * (1 - f)) * wK, o * 0.92)
			if inner then
				ringLay(inner, Vector3.new(0, 0, 0.05), X3, Y3, rad * 0.86, (0.08 + 0.3 * (1 - f)) * wK, o * 0.6)
			end
			for _, s in spokes do
				local r0 = rad * (0.25 + 0.55 * e)
				local r1 = rad * (0.55 + 0.75 * e) * s.k
				streakLine(s, s.d * r0, s.d * r1, 0.32 * wK * (1 - 0.6 * f), o * 0.85)
			end
			local hcf = holder.CFrame
			local any = false
			for _, s in curls do
				if stepCurl(s, now, cam, hcf) then
					any = true
				end
			end
			if street then
				local se = 1 - (1 - math.min(t / (grow * 1.5), 1)) ^ 3
				ringLay(street.ring, Vector3.zero, X3, Z3, 1 + (R * 1.35 - 1) * se, (0.1 + 0.35 * (1 - f)) * wK, o * 0.75)
			end
			return t < total or any
		end })
		return holder
	end

	---------------------------------------------------------------------
	-- WK.ground(pos, radius, opts) -> holder: THE STREET UNDER A BIG GUST -
	-- a flat whirl (shape G: crescent loops lying on the street, turning and
	-- opening out), a dust ring pushed out, cracks for the biggest beats, and
	-- on grass the blades flattened in radiating lines. opts: loops (3, at
	-- most Caps.Loops), spin (1.6 turns a second), turn (1 / -1: which
	-- way), life (0.8), dust (true), cracks (false: VFX.EngineKit.cracks),
	-- grass (nil: when the street is grass; true / false), color, shade,
	-- snap (true: onto the street under pos), transparency (0.15)
	---------------------------------------------------------------------
	function WK.ground(pos, radius, opts)
		opts = type(opts) == "table" and opts or {}
		pos = WK.v3(pos)
		if not pos then
			return nil
		end
		local R = math.clamp(tonumber(radius) or 6, 0.5, 300)
		local hit = opts.snap ~= false and groundRay(pos, 12) or nil
		local g = hit and hit.Position or pos
		local holder = WK.holder(CFrame.new(g + UP * 0.25), "Ground")
		local shade = opts.shade or PAL.SHADE_GROUND
		local nl = WK.n(math.clamp(math.floor(tonumber(opts.loops) or 3), 1, CAPS.Loops or 4))
		local turn = opts.turn == -1 and -1 or 1
		local loops = {}
		for i = 1, nl do
			local k = (i - 0.5) / nl
			loops[i] = {
				band = WK.band(holder, { color = opts.color or PAL.AIR, shade = shade }),
				r = R * (0.35 + 0.6 * k), a = rand(0, TAU), arc = math.rad(rand(140, 210)),
				spin = (tonumber(opts.spin) or 1.6) * TAU * (1.3 - 0.5 * k) * turn,
			}
		end
		if opts.dust ~= false then
			WK.dustRing(g, R, { n = 12 })
		end
		if opts.cracks and VFX.EngineKit and VFX.EngineKit.cracks then
			pcall(VFX.EngineKit.cracks, g + UP * 0.1, R * 0.7, 8, { crater = false, rocks = 0, life = 2 })
		end
		local grass = opts.grass
		if grass == nil then
			grass = hit ~= nil and (hit.Material == Enum.Material.Grass or hit.Material == Enum.Material.LeafyGrass)
		end
		local blades = {}
		if grass then
			for i = 1, WK.n(10) do
				local a = (i - 0.5) / 10 * TAU + rand(-0.2, 0.2)
				local s = streakMake(holder, PAL.GRASS)
				s.beam.LightInfluence = 0.8
				s.d = Vector3.new(math.cos(a), 0, math.sin(a))
				blades[i] = s
			end
		end
		local life = math.max(tonumber(opts.life) or 0.8, 0.1)
		local base = 1 - math.clamp(tonumber(opts.transparency) or 0.15, 0, 1)
		WK.run({ holder = holder, life = life + 1.2, step = function(_, t, dt)
			local camPos = WK.cam().Position
			local f = math.clamp(t / life, 0, 1)
			local o = math.min(t / 0.06, 1) * (1 - f * f) * base * WK.nearK(g, camPos)
			for _, L in loops do
				L.a += L.spin * dt * (1 - 0.6 * f)
				local rr = L.r * (1 + 0.25 * f)
				WK.layBand(L.band, Vector3.zero, X3, Z3, rr, L.a, L.a + L.arc, math.clamp(0.3 + rr * 0.07, 0.3, 4) * (1 - 0.5 * f), o)
			end
			local gf = math.clamp(t / (life + 1), 0, 1)
			for _, s in blades do
				streakLine(s, s.d * R * 0.3, s.d * R * (0.4 + 0.6 * math.min(t / 0.12, 1)), 0.16, (1 - gf) * 0.7)
			end
			return f < 1 or (#blades > 0 and gf < 1)
		end })
		return holder
	end

	---------------------------------------------------------------------
	-- WK.debris(pos, vel, opts) -> model: WHAT THE WIND CARRIES - leaves,
	-- paper, grit and rubble flung along vel (studs/s) in an ORDERED fan
	-- (canon: his currents never collide - no random scatter): leaves and
	-- paper flutter and float, grit and rubble arc and drop. opts: n (6, at
	-- most Caps.Debris), kinds ({ "leaf", "paper", "grit", "leaf" } in
	-- turn, or "rubble"), pieces (the server's Destruction.Rubble list -
	-- { Position, Size, Color, Material } - flown as they are, instead),
	-- spread (the fan, 30 degrees), scatter (studs round pos, 1), life (1.2),
	-- orbit ({ center, radius, height, spin, climb }: wheel round a centre
	-- instead)
	---------------------------------------------------------------------
	local function debrisPart(kind, piece, parent, i)
		if piece then
			local s = typeof(piece.Size) == "Vector3" and piece.Size == piece.Size and piece.Size or Vector3.one
			s = Vector3.new(math.clamp(s.X, 0.3, 6), math.clamp(s.Y, 0.3, 6), math.clamp(s.Z, 0.3, 6))
			local mat = typeof(piece.Material) == "EnumItem" and piece.Material or Enum.Material.Concrete
			return newPart(s, CFrame.new(), typeof(piece.Color) == "Color3" and piece.Color or PAL.RUBBLE, mat, nil, parent)
		elseif kind == "paper" then
			return newPart(Vector3.new(rand(0.55, 0.9), 0.04, rand(0.65, 1.1)), CFrame.new(), PAL.PAPER, Enum.Material.SmoothPlastic, nil, parent)
		elseif kind == "grit" then
			return newPart(Vector3.one * rand(0.18, 0.3), CFrame.new(), PAL.DUST_DARK, Enum.Material.Slate, nil, parent)
		elseif kind == "rubble" then
			return newPart(Vector3.new(rand(0.5, 1.2), rand(0.4, 0.9), rand(0.5, 1.1)), CFrame.new(), i % 2 == 0 and PAL.RUBBLE or PAL.RUBBLE_LIGHT, Enum.Material.Concrete, nil, parent)
		end
		local leaves = PAL.LEAVES
		return newPart(Vector3.new(rand(0.35, 0.6), 0.05, rand(0.25, 0.45)), CFrame.new(), leaves[(i - 1) % #leaves + 1], Enum.Material.SmoothPlastic, nil, parent)
	end
	WK.debrisPart = debrisPart
	function WK.debris(pos, vel, opts)
		opts = type(opts) == "table" and opts or {}
		pos = WK.v3(pos)
		if not pos then
			return nil
		end
		vel = WK.v3(vel) or Vector3.zero
		local pieces = type(opts.pieces) == "table" and #opts.pieces > 0 and opts.pieces or nil
		local n = WK.n(math.clamp(math.floor(pieces and #pieces or tonumber(opts.n) or 6), 0, CAPS.Debris or 12))
		if n <= 0 then
			return nil
		end
		local kinds = type(opts.kinds) == "table" and #opts.kinds > 0 and opts.kinds or { "leaf", "paper", "grit", "leaf" }
		local model = Instance.new("Model")
		model.Name = "InasaWindDebris"
		model.Parent = folder
		local orbit = type(opts.orbit) == "table" and opts.orbit or nil
		local life = math.clamp(tonumber(opts.life) or 1.2, 0.1, 20)
		local spread = math.rad(tonumber(opts.spread) or 30)
		local scatter = tonumber(opts.scatter) or 1
		-- (they start in order too: spread across the fan the way it opens)
		local across = UP:Cross(vel)
		across = across.Magnitude > 1e-3 and across.Unit or X3
		local list = {}
		for i = 1, n do
			local piece = pieces and pieces[i]
			local kind = piece and "rubble" or kinds[(i - 1) % #kinds + 1]
			local p = debrisPart(kind, piece, model, i)
			local k = (i - 0.5) / n
			local from = piece and WK.v3(piece.Position) or pos + across * (k - 0.5) * 2 * scatter + Vector3.new(0, math.sin(i * 2.4) * 0.3 * scatter, 0)
			local light = kind == "leaf" or kind == "paper"
			list[i] = {
				p = p, from = from, light = light,
				v = rotAbout(vel, UP, (k - 0.5) * spread) * (0.85 + 0.3 * ((i * 0.618) % 1)) + Vector3.new(0, (k - 0.5) * 3, 0),
				drag = light and 1.6 or (kind == "grit" and 0.8 or 0.25), g = light and 4 or (kind == "grit" and 18 or 34),
				rot = Vector3.new(rand(-1, 1), rand(-1, 1), rand(-1, 1)) * (light and 9 or 5), ph = rand(0, TAU),
				ang = (i - 1) / n * TAU, h0 = k,
			}
		end
		local parts, cfs = {}, {}
		WK.run({ holder = model, life = life + 0.3, step = function(_, t)
			table.clear(parts)
			table.clear(cfs)
			local f = math.clamp((t - life * 0.7) / (life * 0.3), 0, 1)
			for _, d in list do
				local p2
				if orbit then
					local c = WK.v3(orbit.center) or pos
					local H = tonumber(orbit.height) or 10
					local ang = d.ang + (tonumber(orbit.spin) or 1) * TAU * t
					local h = (d.h0 * H + (tonumber(orbit.climb) or 5) * t) % H
					local rr = (tonumber(orbit.radius) or 4) * (0.6 + 0.5 * h / H)
					p2 = c + Vector3.new(math.cos(ang) * rr, h, math.sin(ang) * rr)
				else
					local ex = (1 - math.exp(-d.drag * t)) / d.drag
					p2 = d.from + d.v * ex - Vector3.new(0, 0.5 * d.g * t * t, 0)
					if d.light then
						p2 += Vector3.new(math.sin(t * 7 + d.ph), math.sin(t * 5 + d.ph) * 0.5, math.cos(t * 6 + d.ph)) * 0.5
					end
				end
				table.insert(parts, d.p)
				table.insert(cfs, CFrame.new(p2) * CFrame.Angles(d.rot.X * t + d.ph, d.rot.Y * t, d.rot.Z * t))
				if f > 0 then
					d.p.Transparency = f
				end
			end
			WK.move(parts, cfs)
			return t < life
		end })
		return model
	end

	---------------------------------------------------------------------
	-- WK.gustFront(origin, dir, opts) -> holder: A TRAVELLING GUST FRONT -
	-- crescent bands stacked one over the other, bowed forward and racing
	-- out from origin across a cone (each a circle's arc round origin, its
	-- radius the distance travelled), curls peeling off their tips, a haze
	-- behind, a dust sheet boiling along its foot on the street, and debris
	-- tumbling ahead in it. opts: range (20 studs), speed (studs/s: range /
	-- 0.32; it eases out), cone (35: degrees either side), height (3: the
	-- stack's), width (1.6: a band's middle), bands (3, at most
	-- Caps.Bands), from (2: where it starts), tilt (degrees round dir: a
	-- slice rising to the right is 25), curls (4), debris (3; 0 for none),
	-- dust (70 a second along its foot; 0 for none), haze (true), ground
	-- (true), trails (4: streak lines it leaves behind it), storm (the
	-- Final War's tan-grey ropes' palette), color, shade, transparency (0.08)
	---------------------------------------------------------------------
	function WK.gustFront(origin, dir, opts)
		opts = type(opts) == "table" and opts or {}
		origin = WK.v3(origin)
		dir = WK.dir(dir, nil)
		if not (origin and dir) then
			return nil
		end
		local range = math.clamp(tonumber(opts.range) or 20, 2, 600)
		local speed = math.max(tonumber(opts.speed) or range / 0.32, 5)
		local cone = math.rad(math.clamp(tonumber(opts.cone) or 35, 3, 85))
		local height = math.clamp(tonumber(opts.height) or 3, 0, 100)
		local width = math.clamp(tonumber(opts.width) or 1.6, 0.1, 40)
		local nb = WK.n(math.clamp(math.floor(tonumber(opts.bands) or 3), 1, CAPS.Bands or 3))
		local storm = opts.storm == true
		local color = opts.color or (storm and PAL.STORM or PAL.AIR)
		local shade = opts.shade or (storm and PAL.STORM_DARK or PAL.SHADE)
		local r0 = math.clamp(tonumber(opts.from) or 2, 0.5, range * 0.8)
		local frame = WK.look(origin, dir) * CFrame.Angles(0, 0, math.rad(tonumber(opts.tilt) or 0))
		local holder = WK.holder(frame, "GustFront")
		local bands = {}
		local mid = (nb + 1) / 2
		for i = 1, nb do
			local main = math.abs(i - mid) < 0.6 or nb == 1
			-- (not three bars in a stack: the outer bands shorter, thinner and
			-- off to one side, a beat behind)
			local off = main and 0 or (i < mid and -0.22 or 0.18) * cone
			bands[i] = {
				band = WK.band(holder, { color = color, shade = shade }),
				y = nb == 1 and 0 or (i - mid) * height / math.max(nb - 1, 1),
				lag = math.abs(i - mid) * 0.04, wk = main and 1 or 0.58,
				a0 = -cone * (main and 1 or 0.72) + off, a1 = cone * (main and 1 or 0.72) + off,
			}
		end
		-- the streak lines it leaves behind it (shape B: the path of the gust)
		local trails = {}
		for i = 1, WK.n(math.clamp(math.floor(tonumber(opts.trails) or 4), 0, 6)) do
			local s = streakMake(holder, color)
			s.a = ((i - 0.5) / 4 * 2 - 1) * cone * 0.8 + rand(-0.06, 0.06)
			s.y = (rand(-0.5, 0.5)) * height
			s.k = rand(0.85, 1.05)
			trails[i] = s
		end
		local T = (range - r0) / speed
		local cs = {}
		for i = 1, WK.n(math.clamp(math.floor(tonumber(opts.curls) or 4), 0, 6)) do
			cs[i] = curlSlot(holder, color)
		end
		local ci, nextCurl = 0, 0
		-- the dust sheet along its foot (the street, if it's near)
		local foot, dust
		local hit = opts.ground ~= false and groundRay(origin, height / 2 + 9) or nil
		local rate = (tonumber(opts.dust) or 70) * (WK.low() and 0.5 or 1)
		if hit and rate > 0 then
			foot = WK.holder(CFrame.new(hit.Position), "GustDust")
			foot.Parent = holder
			dust = Instance.new("ParticleEmitter")
			dust.Name = "InasaWind"
			dust.Texture = TEX.smoke
			dust.Color = CS(PAL.DUST, PAL.DUST_DARK)
			dust.Transparency = NS({ NK(0, 1), NK(0.15, 0.55), NK(1, 1) })
			dust.Size = NS({ NK(0, 1.4), NK(1, 4) })
			dust.Lifetime = NumberRange.new(0.5, 0.9)
			dust.Speed = NumberRange.new(4, 10)
			dust.SpreadAngle = Vector2.new(25, 25)
			dust.Acceleration = Vector3.new(0, 3, 0)
			dust.Drag = 1.5
			dust.LightInfluence = 0.7
			dust.Rotation = NumberRange.new(0, 360)
			dust.RotSpeed = NumberRange.new(-60, 60)
			dust.EmissionDirection = Enum.NormalId.Front
			dust.Rate = 0
			dust.Parent = foot
		end
		if opts.haze ~= false then
			WK.haze(CFrame.new(origin + dir * range * 0.2), Vector3.new(range * math.sin(cone) * 0.8 + 2, height + 3, 1), dir, { speed = math.clamp(speed / 60, 0.4, 4), life = T + 0.15 })
		end
		local nd = tonumber(opts.debris) or 3
		if nd > 0 then
			WK.debris(hit and hit.Position + UP * 1.2 or origin, dir * math.min(speed * 0.55, 90) + UP * 6, { n = nd, spread = math.deg(cone) * 1.4, life = T + 0.7 })
		end
		local base = 1 - math.clamp(tonumber(opts.transparency) or 0.08, 0, 1)
		local fwd, side = Vector3.new(0, 0, -1), X3
		WK.run({ holder = holder, life = T + 1.2, step = function(_, t, _dt, now)
			local cam = WK.cam()
			local hcf = holder.CFrame
			local rNow = r0
			for _, B in bands do
				local tt = math.max(t - B.lag, 0)
				local x = math.min(tt / T, 1)
				local e = 1 - (1 - x) * (1 - x)
				local r = r0 + (range - r0) * e
				if B.wk == 1 then
					rNow = r
				end
				local fade = math.clamp((tt - T * 0.6) / (T * 0.4 + 0.18), 0, 1)
				local o = base * math.min(tt / 0.05, 1) * (1 - fade) * WK.nearK(hcf * Vector3.new(0, B.y, -r), cam.Position)
				local w = width * B.wk * (0.6 + 0.7 * e) * (1 - 0.45 * fade)
				WK.layBand(B.band, Vector3.new(0, B.y, 0), fwd, side, r, B.a0, B.a1, w, o)
			end
			for _, s in trails do
				local x = math.min(t / T, 1)
				local e = 1 - (1 - x) * (1 - x)
				local r = (r0 + (range - r0) * e) * s.k
				local d = fwd * math.cos(s.a) + side * math.sin(s.a)
				local tail = math.max(r * (0.25 + 0.5 * x), r0)
				local fade = math.clamp((t - T * 0.5) / (T * 0.5 + 0.15), 0, 1)
				streakLine(s, d * tail + Vector3.new(0, s.y, 0), d * r * 0.97 + Vector3.new(0, s.y, 0), width * 0.22, base * 0.8 * (1 - fade) * math.min(t / 0.05, 1))
			end
			-- curls off its tips, in turn
			if #cs > 0 and t < T and now >= nextCurl then
				nextCurl = now + T / (#cs + 1)
				ci = ci % #cs + 1
				local tipSide = ci % 2 == 0 and 1 or -1
				local a = cone * tipSide
				local at = hcf * (fwd * math.cos(a) * rNow + side * math.sin(a) * rNow)
				local out = hcf:VectorToWorldSpace(side * tipSide * 0.8 + fwd * 0.6) + hcf.UpVector * 0.3
				armCurl(cs[ci], at, out, { size = math.clamp(width * 1.5, 1.2, 12), drift = width * 3, spin = 260 * tipSide })
			end
			for _, s in cs do
				stepCurl(s, now, cam, hcf)
			end
			if foot then
				local m = hcf * (fwd * rNow)
				foot.CFrame = WK.look(Vector3.new(m.X, hit.Position.Y + 0.4, m.Z), Vector3.new(dir.X, 0, dir.Z).Magnitude > 0.05 and Vector3.new(dir.X, 0, dir.Z) or dir)
				foot.Size = Vector3.new(math.max(2 * rNow * math.sin(cone), 1), 0.4, 0.6)
				dust.Rate = t < T and rate or 0
			end
			return t < T + 0.25 + 0.4
		end })
		return holder
	end

	---------------------------------------------------------------------
	-- WK.vortex(pos, opts) -> handle: A TORNADO - rings of crescent bands
	-- (2-3 a ring, gaps between them: never a closed tube) climbing it and
	-- turning (faster at the foot, slower up top), narrow at the street and
	-- flaring out (r = baseR .. topR by (h/height)^1.3), its axis swaying at
	-- the top; a dust skirt boiling at its foot; leaves, paper, grit and
	-- rubble wheeling up it on spiral orbits; curls flicking off its rim.
	-- Resizable live, eased (handle:set). opts: height (20), baseR (2.5),
	-- topR (8), spin (1.6 turns a second at its middle), sway (0 studs),
	-- axis (up; any direction: the ride's funnel lies along his path),
	-- rings (10, at most Caps.Rings), bands (2 a ring, at most
	-- Caps.RingBands), rise (0.45: a ring climbs this share of the height a
	-- second), storm (0: the share from its foot drawn in the storm palette),
	-- debris (6), dust (18 a second; false for none), curls (true;
	-- curlEvery 0.15 s), ease (6), width (1: the bands'), maxWidth (40),
	-- shade, sound (a Config.Sounds loop cue, e.g. "InasaWindWhirl"), life
	-- (stops itself after it), grow (seconds it takes to climb up out of the
	-- street), name, haze (its faint body of haze rising up it: on for a
	-- funnel up to 80 tall, never on a low-end machine; true / false to say).
	-- (round 99 review: the rings climb more evenly - the top half was
	-- sparse - and the bands are a little wider as it flares)
	-- The handle: :set({ height, baseR, topR, spin, sway, axis, pos })
	-- (eased toward), :move(pos) (the foot, at once), :carry(part, opts) (2
	-- bands round a body it's holding, at its height: radius 2.2, spin 3) /
	-- :drop(part), :feed(pieces) (the server's rubble: flown into its foot,
	-- then wheeled up it), :stop(fade, how) (how: nil fades it; "burst":
	-- the rings shoot up and out and the debris is flung; "unwind": it slows
	-- and dies away), .model, .alive, .radiusAt(k) / .axisAt(k) (0 at its
	-- foot .. 1 at its top)
	---------------------------------------------------------------------
	function WK.vortex(pos, opts)
		opts = type(opts) == "table" and opts or {}
		pos = WK.v3(pos)
		if not pos then
			return nil
		end
		local low = WK.low()
		local vx = { alive = true, carried = {}, pieces = {} }
		local cur = {
			height = math.clamp(tonumber(opts.height) or 20, 1, 3000),
			baseR = math.clamp(tonumber(opts.baseR) or 2.5, 0.2, 600),
			topR = math.clamp(tonumber(opts.topR) or 8, 0.2, 900),
			spin = math.clamp(tonumber(opts.spin) or 1.6, -20, 20),
			sway = math.clamp(tonumber(opts.sway) or 0, 0, 500),
			axis = WK.dir(opts.axis, UP), pos = pos,
		}
		local target = table.clone(cur)
		vx.cur, vx.target = cur, target
		local nr = WK.n(math.clamp(math.floor(tonumber(opts.rings) or 10), 2, CAPS.Rings or 10))
		local nb = math.clamp(math.floor(tonumber(opts.bands) or 2), 1, CAPS.RingBands or 3)
		if low then
			nb = math.min(nb, 2)
		end
		local storm = math.clamp(tonumber(opts.storm) or 0, 0, 1)
		local riseK = math.clamp(tonumber(opts.rise) or 0.45, 0, 5)
		local wK = math.clamp(tonumber(opts.width) or 1, 0.1, 10)
		local maxW = tonumber(opts.maxWidth) or 40
		local ease = math.max(tonumber(opts.ease) or 6, 0.1)
		local model = Instance.new("Model")
		model.Name = type(opts.name) == "string" and opts.name or "InasaVortex"
		model.Parent = folder
		vx.model = model
		local base = WK.holder(WK.upFrame(pos, cur.axis), "VortexBase")
		base.Parent = model
		vx.base = base
		local rings = {}
		for i = 1, nr do
			local anchor = WK.holder(CFrame.new(pos), "VortexRing")
			anchor.Parent = model
			local k0 = (i - 0.5) / nr
			local ring = { part = anchor, k = k0, spin = rand(0, TAU), bands = {}, rate = rand(0.9, 1.1), lastR = -1, frame = i, storm = nil }
			for j = 1, nb do
				ring.bands[j] = { band = WK.band(anchor, { color = PAL.AIR, shade = opts.shade or PAL.SHADE }), a0 = (j - 1) / nb * TAU + rand(-0.3, 0.3), span = TAU / nb * rand(0.66, 0.86), rise = rand(0.35, 0.6) }
			end
			rings[i] = ring
		end
		vx.rings = rings
		local function radiusAt(k)
			return cur.baseR + (cur.topR - cur.baseR) * math.clamp(tonumber(k) or 0, 0, 1) ^ 1.3
		end
		vx.radiusAt = radiusAt
		-- the axis's point k (0 at the foot .. 1 at the top) up it, swaying -
		-- ((round 99 review) callable from the start: it was only made on the
		-- first frame, so a move asking right after making it errored)
		local frameB, tNow = WK.upFrame(pos, cur.axis), 0
		local growT = tonumber(opts.grow)
		local function axisAt(k)
			k = tonumber(k) or 0
			local s = cur.sway * k
			return frameB * Vector3.new(math.sin(tNow * 0.9 + k * 2.2) * s, k * cur.height, math.cos(tNow * 0.7 + k * 1.7) * s)
		end
		vx.axisAt = axisAt
		-- the dust skirt at its foot
		local skirt
		if opts.dust ~= false then
			skirt = Instance.new("ParticleEmitter")
			skirt.Name = "InasaWind"
			skirt.Texture = TEX.smoke
			skirt.Color = CS(PAL.DUST, PAL.DUST_DARK)
			skirt.LightInfluence = 0.6
			skirt.Transparency = NS({ NK(0, 0.9), NK(0.2, 0.45), NK(1, 1) })
			skirt.Lifetime = NumberRange.new(1, 1.8)
			skirt.SpreadAngle = Vector2.new(70, 70)
			skirt.Drag = 0.8
			skirt.Rotation = NumberRange.new(0, 360)
			skirt.RotSpeed = NumberRange.new(-60, 60)
			skirt.EmissionDirection = Enum.NormalId.Top
			skirt.Rate = 0
			skirt.Parent = base
		end
		local skirtRate = (tonumber(opts.dust) or 18) * (low and 0.45 or 1)
		-- (round 99 review) its body: a faint haze rising up the funnel (shape
		-- D - the bands are only its edges); a funnel up to 80 tall, off a
		-- low-end machine (opts.haze: true / false to say)
		local haze
		local wantHaze = opts.haze
		if wantHaze == nil then
			wantHaze = cur.height <= 80
		end
		if wantHaze and not low then
			haze = Instance.new("ParticleEmitter")
			haze.Name = "InasaWind"
			haze.Texture = TEX.smoke
			haze.Color = CS(PAL.HAZE, PAL.AIR)
			haze.LightEmission = 0.05
			haze.LightInfluence = 0.5
			haze.Transparency = NS({ NK(0, 1), NK(0.2, 0.8), NK(0.75, 0.84), NK(1, 1) })
			haze.Lifetime = NumberRange.new(1.1, 1.4)
			haze.SpreadAngle = Vector2.new(4, 4)
			haze.Rotation = NumberRange.new(0, 360)
			haze.RotSpeed = NumberRange.new(-90, 90)
			haze.LockedToPart = true
			haze.EmissionDirection = Enum.NormalId.Top
			haze.Rate = 0
			haze.Parent = base
		end
		local hazeKey = -1
		-- debris wheeling up it
		local nd = WK.n(math.clamp(math.floor(tonumber(opts.debris) or 6), 0, CAPS.Debris or 12))
		local kinds = { "leaf", "paper", "grit", "rubble", "leaf", "grit" }
		for i = 1, nd do
			local p = debrisPart(kinds[(i - 1) % #kinds + 1], nil, model, i)
			table.insert(vx.pieces, { p = p, ang = rand(0, TAU), k = (i - 0.5) / nd * 0.9, spin = rand(1, 1.25), rot = Vector3.new(rand(-6, 6), rand(-6, 6), rand(-6, 6)) })
		end
		-- curls off its rim
		local cs = {}
		if opts.curls ~= false then
			for i = 1, low and 3 or 6 do
				cs[i] = curlSlot(base)
			end
		end
		local curlEvery = tonumber(opts.curlEvery) or 0.15
		local ci, nextCurl = 0, 0
		local loop = type(opts.sound) == "string" and WK.loop(opts.sound, base, { fadeIn = 0.3, max = math.min(tonumber(opts.life) or 30, 30) + 1 }) or nil
		local parts, cfs = {}, {}
		local spinAngle = 0
		local stopping
		local tAll = 0
		function vx:set(spec)
			if type(spec) ~= "table" then
				return
			end
			for _, key in { "height", "baseR", "topR", "spin", "sway" } do
				local v = tonumber(spec[key])
				if v and v == v then
					target[key] = key == "spin" and math.clamp(v, -20, 20) or math.clamp(v, 0.05, 3000)
				end
			end
			target.axis = WK.dir(spec.axis, target.axis)
			target.pos = WK.v3(spec.pos) or target.pos
			if spec.now then
				for k, v in target do
					cur[k] = v
				end
			end
		end
		function vx:move(p)
			p = WK.v3(p)
			if p then
				cur.pos, target.pos = p, p
			end
		end
		function vx:carry(part, o)
			if typeof(part) ~= "Instance" or not part:IsA("BasePart") or self.carried[part] then
				return
			end
			local count = 0
			for _ in self.carried do
				count += 1
			end
			if count >= (CAPS.Carried or 4) then
				return
			end
			o = type(o) == "table" and o or {}
			local anchor = WK.holder(part.CFrame, "VortexCarry")
			anchor.Parent = model
			local c = { part = part, anchor = anchor, r = tonumber(o.radius) or 2.2, spin = (tonumber(o.spin) or 3) * TAU, a = 0, bands = {} }
			for j = 1, 2 do
				c.bands[j] = WK.band(anchor, { color = PAL.AIR, shade = PAL.SHADE })
				WK.layBand(c.bands[j], Vector3.new(0, (j - 1.5) * 1.2, 0), X3, Z3, c.r * (j == 1 and 1 or 0.85), j * math.pi, j * math.pi + 2.2, 0.5, 0.85)
			end
			self.carried[part] = c
		end
		function vx:drop(part)
			local c = self.carried[part]
			if c then
				self.carried[part] = nil
				pcall(c.anchor.Destroy, c.anchor)
			end
		end
		function vx:feed(list)
			if type(list) ~= "table" then
				return
			end
			for _, piece in list do
				if #self.pieces >= (CAPS.Debris or 12) * (low and 1 or 2) then
					break
				end
				local from = type(piece) == "table" and WK.v3(piece.Position)
				if from then
					local p = debrisPart("rubble", piece, model, #self.pieces + 1)
					table.insert(self.pieces, { p = p, ang = rand(0, TAU), k = 0.02, spin = rand(1, 1.25), rot = Vector3.new(rand(-5, 5), rand(-5, 5), rand(-5, 5)), from = from, t0 = tAll })
				end
			end
		end
		function vx:stop(fade, how)
			if not stopping then
				stopping = { t = tAll, fade = math.max(tonumber(fade) or 0.4, 0.05), how = how }
				if loop then
					loop.stop(stopping.fade + 0.2)
				end
			end
		end
		local maxLife = tonumber(opts.life)
		WK.run({ holder = model, life = (maxLife or 40) + 3, kill = function()
			vx.alive = false
			if loop then
				loop.stop(0.2)
			end
		end, step = function(_, t, dt, now)
			tAll = t
			if maxLife and t > maxLife and not stopping then
				vx:stop(0.4)
			end
			-- eased toward what it was set to
			local a = 1 - math.exp(-ease * dt)
			for _, key in { "height", "baseR", "topR", "spin", "sway" } do
				cur[key] += (target[key] - cur[key]) * a
			end
			cur.axis = WK.dir(cur.axis:Lerp(target.axis, a), cur.axis)
			cur.pos = cur.pos:Lerp(target.pos, a)
			local alpha, spinK, grow, burst = 1, 1, 1, 0
			if growT then
				grow = math.clamp(t / math.max(growT, 0.01), 0, 1)
			end
			if stopping then
				local f = (t - stopping.t) / stopping.fade
				if f >= 1 then
					return false
				end
				alpha = 1 - f
				if stopping.how == "burst" then
					burst = f
				elseif stopping.how == "unwind" then
					spinK = 1 - f
				end
			end
			local cam = WK.cam()
			local B = WK.upFrame(cur.pos, cur.axis)
			frameB, tNow = B, t
			base.CFrame = B
			spinAngle += cur.spin * spinK * TAU * dt
			table.clear(parts)
			table.clear(cfs)
			for _, ring in rings do
				ring.k += riseK * (1 + 0.7 * ring.k) * dt * (1 + burst * 3)
				if ring.k > 1 then
					ring.k -= 1
				end
				local k = ring.k
				ring.spin += cur.spin * spinK * TAU * (1.4 - 0.7 * k) * ring.rate * dt
				local isStorm = k < storm
				if isStorm ~= ring.storm then
					ring.storm = isStorm
					for _, rb in ring.bands do
						WK.colorBand(rb.band, isStorm and PAL.STORM or PAL.AIR, isStorm and PAL.STORM_DARK or (opts.shade or PAL.SHADE))
					end
				end
				local r = radiusAt(k) * (1 + burst * 2.2)
				local edge = math.min(1, k / 0.08, (1 - k) / 0.15)
				local c = axisAt(k)
				local shown = k <= grow and edge * alpha or 0
				local o = shown * (1 - burst) * WK.nearK(c, cam.Position) * 0.92
				ring.frame += 1
				local w = math.clamp((0.35 + r * 0.16) * wK, 0.3, maxW)
				if math.abs(r - ring.lastR) > ring.lastR * 0.03 or ring.frame % 3 == 0 or o ~= ring.lastO then
					ring.lastR, ring.lastO = r, o
					for _, rb in ring.bands do
						WK.layBand(rb.band, Vector3.zero, X3, Z3, r, rb.a0, rb.a0 + rb.span, w, o, r * rb.rise)
					end
				end
				table.insert(parts, ring.part)
				table.insert(cfs, CFrame.fromMatrix(c, B.RightVector, B.UpVector) * CFrame.Angles(0, -ring.spin, 0))
			end
			-- the debris wheeling up it (the server's rubble flies in first)
			for _, d in vx.pieces do
				local p2
				if d.from and t - d.t0 < 0.5 then
					local f = (t - d.t0) / 0.5
					p2 = d.from:Lerp(axisAt(0.05) + B.RightVector * radiusAt(0.05), f * f)
				else
					d.ang += cur.spin * spinK * TAU * 1.05 * d.spin * dt
					d.k += 0.32 * dt * (1 + burst * 2)
					if d.k > 0.92 then
						d.k = 0.04
					end
					local rr = radiusAt(d.k) * (0.85 + burst * 2.5)
					p2 = axisAt(d.k) + (B.RightVector * math.cos(d.ang) + (-B.LookVector) * math.sin(d.ang)) * rr
				end
				table.insert(parts, d.p)
				table.insert(cfs, CFrame.new(p2) * CFrame.Angles(d.rot.X * t, d.rot.Y * t, d.rot.Z * t))
				if stopping then
					d.p.Transparency = 1 - alpha
				end
			end
			-- the bodies it's holding
			for part, c in vx.carried do
				if not part.Parent then
					vx:drop(part)
				else
					c.a += c.spin * dt
					table.insert(parts, c.anchor)
					table.insert(cfs, CFrame.fromMatrix(part.CFrame.Position, B.RightVector, B.UpVector) * CFrame.Angles(0, -c.a, 0))
					for _, b in c.bands do
						WK.fadeBand(b, 0.85 * alpha)
					end
				end
			end
			WK.move(parts, cfs)
			if skirt then
				base.Size = Vector3.new(cur.baseR * 2, 0.6, cur.baseR * 2)
				skirt.Size = NS({ NK(0, cur.baseR * 0.6), NK(1, cur.baseR * 2) })
				skirt.Speed = NumberRange.new(cur.baseR * 1.2, cur.baseR * 2.5)
				skirt.Acceleration = cur.axis * cur.baseR
				skirt.Rate = stopping and 0 or skirtRate * grow
			end
			if haze then
				local key = math.floor(cur.height * 2 + cur.topR * 8 + cur.baseR * 16)
				if key ~= hazeKey then
					hazeKey = key
					haze.Speed = NumberRange.new(cur.height / 1.25)
					haze.Size = NS({ NK(0, cur.baseR * 1.5), NK(1, cur.topR * 1.7) })
				end
				haze.Rate = stopping and 0 or 9 * grow
			end
			-- curls flicking off the rim
			if #cs > 0 and not stopping and now >= nextCurl then
				nextCurl = now + curlEvery
				ci = ci % #cs + 1
				local k = rand(0.1, 0.85)
				local ang = rand(0, TAU)
				local radial = B.RightVector * math.cos(ang) + (-B.LookVector) * math.sin(ang)
				local tangent = ((-B.LookVector) * math.cos(ang) - B.RightVector * math.sin(ang)) * (cur.spin >= 0 and -1 or 1)
				local r = radiusAt(k)
				armCurl(cs[ci], axisAt(k) + radial * r, tangent + radial * 0.6 + cur.axis * 0.3, { size = math.clamp(r * 0.4, 1.1, 16), drift = math.clamp(r * 0.5, 1.5, 30) })
			end
			local bcf = base.CFrame
			for _, s in cs do
				stepCurl(s, now, cam, bcf)
			end
			return true
		end })
		return vx
	end

	---------------------------------------------------------------------
	-- WK.tube(origin, dir, len, opts) -> handle: THE DRILL TUNNEL (the
	-- anime's Gale Cannon from his fist): a head racing down the line - a
	-- drill cone of curved strokes spiralling to a point and a pressure ring
	-- - and behind it ring after ring of crescent bands round the axis, each
	-- opening from 1.5 studs to width/2 and spinning as it's left, then
	-- fading: the eye stays clear (you see down it). Rubble rides its walls
	-- on a helix (a turn every 15 studs). opts: width (10), speed (260
	-- studs/s), gap (studs between rings, 4; at most Caps.TubeRings), spin
	-- (2.5 turns a second), life (each ring's fade, 0.35), pieces (the
	-- server's rubble list, or a count of street chunks), splash (a
	-- radius: the head bursts there at the end - a wall), storm (the outer
	-- band tan-grey and 2 rope coils twisting round it), color.
	-- The handle: :stop() (gone now), :headAt() (where the head is), .model
	---------------------------------------------------------------------
	function WK.tube(origin, dir, len, opts)
		opts = type(opts) == "table" and opts or {}
		origin = WK.v3(origin)
		dir = WK.dir(dir, nil)
		if not (origin and dir) then
			return nil
		end
		len = math.clamp(tonumber(len) or 40, 1, 3000)
		local R = math.clamp(tonumber(opts.width) or 10, 1, 300) / 2
		local speed = math.max(tonumber(opts.speed) or 260, 1)
		local nr = WK.n(math.clamp(math.ceil(len / math.max(tonumber(opts.gap) or 4, 0.5)), 2, CAPS.TubeRings or 14))
		local nb = WK.low() and 2 or 3
		local spin = (tonumber(opts.spin) or 2.5) * TAU
		local ringLife = math.max(tonumber(opts.life) or 0.35, 0.05)
		local storm = opts.storm == true
		local frame = WK.look(origin, dir)
		local model = Instance.new("Model")
		model.Name = "InasaWindTube"
		model.Parent = folder
		local rings = {}
		for i = 1, nr do
			local d = (i - 0.5) / nr * len
			local anchor = WK.holder(frame * CFrame.new(0, 0, -d), "TubeRing")
			anchor.Parent = model
			local ring = { part = anchor, d = d, born = d / speed, bands = {}, a = rand(0, TAU) }
			for j = 1, nb do
				local outer = storm and j == nb
				ring.bands[j] = { band = WK.band(anchor, { color = outer and PAL.STORM or opts.color or PAL.AIR, shade = outer and PAL.STORM_DARK or PAL.SHADE }), a0 = (j - 1) / nb * TAU + rand(-0.25, 0.25), span = TAU / nb * rand(0.55, 0.7) }
				WK.fadeBand(ring.bands[j].band, 0)
			end
			rings[i] = ring
		end
		-- the head: the drill's point and its pressure ring
		local head = WK.holder(frame, "TubeHead")
		head.Parent = model
		local tip = WK.att(head, CFrame.fromMatrix(Vector3.new(0, 0, -R * 1.1), Vector3.new(0, 0, -1), UP))
		local cone = {}
		for q = 1, 4 do
			local a = q / 4 * TAU
			local tan = Vector3.new(-math.sin(a), math.cos(a), 0)
			local x = (tan * 0.6 + Vector3.new(0, 0, -0.8)).Unit
			local rim = WK.att(head, CFrame.fromMatrix(Vector3.new(math.cos(a), math.sin(a), 0) * R * 0.85, x, Vector3.new(math.cos(a), math.sin(a), 0):Cross(x).Unit))
			local b = WK.beam(rim, tip, opts.color or PAL.AIR, R * 0.22, 0.05, head, { segments = 10, transp = WK.seq(0.85, "rise") })
			b.CurveSize0, b.CurveSize1 = R * 0.6, R * 0.3
			cone[q] = b
		end
		local hring = ringMake(head, PAL.CORE, 0.4)
		-- rubble riding its walls
		local pieces = {}
		local plist = opts.pieces
		if type(plist) == "number" then
			local n = math.floor(plist)
			plist = {}
			for i = 1, math.clamp(n, 0, 32) do
				plist[i] = { Position = origin + dir * rand(1, math.min(len, 30)) + Vector3.new(rand(-3, 3), -2, rand(-3, 3)) }
			end
		end
		if type(plist) == "table" then
			local cap = WK.n(CAPS.Debris or 12) + (WK.low() and 0 or 4)
			for i, pc in plist do
				if #pieces >= cap then
					break
				end
				local from = type(pc) == "table" and WK.v3(pc.Position)
				if from then
					local p = debrisPart("rubble", pc.Size and pc or nil, model, i)
					local along = math.clamp((from - origin):Dot(dir), 0, len)
					table.insert(pieces, { p = p, from = from, along = along, a0 = i * 2.4, lag = rand(1, 6), rot = Vector3.new(rand(-6, 6), rand(-6, 6), rand(-6, 6)), out = rand(0.8, 1.2) })
				end
			end
		end
		local ropes = {}
		if storm and not WK.low() then
			for i = 1, 2 do
				ropes[i] = WK.rope(origin, origin + dir * len, { radius = R * 1.12, pitch = 14, strands = 1, spin = (i == 1 and 1 or -1) * 1.2, life = len / speed + ringLife + 0.2, phase = i * math.pi, width = R * 0.09, curls = false })
			end
		end
		local T = len / speed
		local splashed = false
		-- (the street under it: the rubble rides its walls above it, not through it)
		local gHit = #pieces > 0 and groundRay(origin, 30) or nil
		local gy = gHit and gHit.Position.Y or -math.huge
		local h = { model = model }
		local stopped = false
		function h:stop()
			stopped = true
			for _, rp in ropes do
				rp:stop(0.05)
			end
		end
		function h:headAt()
			return origin + dir * math.min((WK.now() - h.t0) * speed, len)
		end
		h.t0 = WK.now()
		local parts, cfs = {}, {}
		local headHidden = false
		WK.run({ holder = model, life = T + ringLife + 3, step = function(_, t, dt)
			if stopped then
				return false
			end
			local cam = WK.cam()
			table.clear(parts)
			table.clear(cfs)
			local hd = math.min(t * speed, len)
			for _, ring in rings do
				local age = t - ring.born
				if age >= 0 then
					local ge = 1 - (1 - math.min(age / 0.2, 1)) ^ 3
					local fade = math.clamp((age - 0.05) / ringLife, 0, 1)
					local r = 1.5 + (R - 1.5) * ge
					ring.a += spin * dt * (1 - 0.5 * fade)
					local cf = frame * CFrame.new(0, 0, -ring.d) * CFrame.Angles(0, 0, ring.a)
					local o = (1 - fade) * math.min(age / 0.03, 1) * WK.nearK(cf.Position, cam.Position) * 0.92
					if o > 0 or not ring.gone then
						ring.gone = o <= 0
						local w = math.clamp(0.4 + r * 0.17, 0.4, 6) * (1 - 0.5 * fade)
						for _, rb in ring.bands do
							WK.layBand(rb.band, Vector3.zero, X3, Y3, r, rb.a0, rb.a0 + rb.span, w, o)
						end
						table.insert(parts, ring.part)
						table.insert(cfs, cf)
					end
				end
			end
			if t <= T then
				table.insert(parts, head)
				table.insert(cfs, frame * CFrame.new(0, 0, -hd) * CFrame.Angles(0, 0, t * spin * 1.6))
				ringLay(hring, Vector3.zero, X3, Y3, R * 0.95, math.clamp(R * 0.06, 0.25, 2), 0.75 * WK.nearK(frame * Vector3.new(0, 0, -hd), cam.Position))
			elseif not headHidden then
				headHidden = true
				for _, b in cone do
					b.Enabled = false
				end
				ringLay(hring, Vector3.zero, X3, Y3, R, 0.2, 0)
				if opts.splash and not splashed then
					splashed = true
					local endPos = origin + dir * len
					WK.burst(endPos - dir * 0.5, -dir, { radius = tonumber(opts.splash) or R, streaks = 10, curls = 6, ground = true })
				end
			end
			-- rubble in its walls, then flung out past the end
			for _, pc in pieces do
				local p2
				local d = math.min(hd - pc.lag, len)
				if d < pc.along then
					p2 = pc.from
				else
					local ph = pc.a0 + d / 15 * TAU
					local rr = R * 0.78
					p2 = frame * Vector3.new(math.cos(ph) * rr, math.sin(ph) * rr, -d)
					local since = (d - pc.along) / speed
					if since < 0.08 then
						p2 = pc.from:Lerp(p2, since / 0.08)
					end
					if t > T then
						local after = t - T
						p2 += dir * after * speed * 0.35 * pc.out + (p2 - (origin + dir * d)) * after * 1.5 - Vector3.new(0, 30 * after * after, 0)
						pc.p.Transparency = math.clamp((after - 0.8) / 0.4, 0, 1)
					end
					if p2.Y < gy + 0.4 then
						p2 = Vector3.new(p2.X, gy + 0.4, p2.Z)
					end
				end
				table.insert(parts, pc.p)
				table.insert(cfs, CFrame.new(p2) * CFrame.Angles(pc.rot.X * t, pc.rot.Y * t, pc.rot.Z * t))
			end
			WK.move(parts, cfs)
			return t < T + ringLife + 0.3 or (#pieces > 0 and t < T + 1.3)
		end })
		return h
	end

	---------------------------------------------------------------------
	-- WK.compress(target, opts) -> handle: AIR PACKED BETWEEN HIS PALMS -
	-- a ball of short curling strokes orbiting a point on tilted orbits
	-- (2-4 turns a second), shrinking from `from` to `to` studs across over
	-- `time`; thin streaks sucked into it from 6-8 studs out every 0.04 s; a
	-- soft pulsing core; a pressure hum (the InasaWindHum bed, and the
	-- InasaWindSuck draw). target: a CFrame, a point, a part, an attachment,
	-- or a function returning one (followed every frame: between his
	-- palms). opts: n (8 strokes, at most Caps.Curls), from (1.8), to (0.6),
	-- time (0.35), spin (3), suckEvery (0.04), sound (true), life (4: it
	-- stops itself). The handle: :release(dir) (folds flat across dir into a
	-- disc for 0.06 s, then gone - throw your blast from there), :stop(fade),
	-- .holder
	---------------------------------------------------------------------
	function WK.compress(target, opts)
		opts = type(opts) == "table" and opts or {}
		local function where()
			if type(target) == "function" then
				local ok, v = pcall(target)
				return ok and WK.cf(v) or nil
			end
			return WK.cf(target)
		end
		local cf0 = where()
		if not cf0 then
			return nil
		end
		local last = cf0
		local holder = WK.holder(CFrame.new(cf0.Position), "Compress")
		local n = WK.n(math.clamp(math.floor(tonumber(opts.n) or 8), 1, CAPS.Curls or 8))
		local r0 = math.clamp(tonumber(opts.from) or 1.8, 0.1, 50)
		local r1 = math.clamp(tonumber(opts.to) or 0.6, 0.05, 50)
		local time = math.max(tonumber(opts.time) or 0.35, 0.02)
		local rate = (tonumber(opts.spin) or 3) * TAU
		local orbits = {}
		for i = 1, n do
			local ta, tb = i * 2.39996, math.acos(1 - 2 * (i - 0.5) / n)
			local nrm = Vector3.new(math.sin(tb) * math.cos(ta), math.cos(tb), math.sin(tb) * math.sin(ta))
			local u = nrm:Cross(math.abs(nrm.Y) < 0.9 and UP or X3).Unit
			local s = streakMake(holder, i % 3 == 0 and PAL.SHADE or PAL.AIR)
			s.u, s.v, s.nrm, s.a, s.span, s.rate = u, nrm:Cross(u), nrm, rand(0, TAU), math.rad(rand(90, 130)), rate * rand(0.8, 1.25)
			orbits[i] = s
		end
		local suck = {}
		for i = 1, WK.n(6) do
			suck[i] = streakMake(holder)
		end
		local core = Instance.new("ParticleEmitter")
		core.Name = "InasaWind"
		core.Texture = TEX.glow
		core.Color = CS(PAL.AIR)
		core.LockedToPart = true
		core.Size = NS({ NK(0, r0 * 1.3), NK(1, r0 * 0.6) })
		core.Transparency = NS({ NK(0, 0.55), NK(1, 1) })
		core.Lifetime = NumberRange.new(0.14, 0.2)
		core.Speed = NumberRange.new(0, 0)
		core.LightEmission = 0.25
		core.LightInfluence = 0.2
		core.Rate = 26
		core.Parent = holder
		local loop
		if opts.sound ~= false then
			VFX.PlaySound("InasaWindSuck", cf0.Position, 1)
			loop = WK.loop("InasaWindHum", holder, { fadeIn = 0.12, max = (tonumber(opts.life) or 4) + 0.5 })
		end
		local h = { holder = holder }
		local state, relT, relDir, fadeT = "hold", 0, UP, 0.12
		function h:release(dir)
			if state == "hold" then
				state, relT = "release", WK.now()
				relDir = WK.dir(dir, last.LookVector)
				core.Rate = 0
				if loop then
					loop.stop(0.08)
				end
			end
		end
		function h:stop(fade)
			if state == "hold" then
				state, relT, fadeT = "stop", WK.now(), math.max(tonumber(fade) or 0.12, 0.02)
				core.Rate = 0
				if loop then
					loop.stop(fadeT)
				end
			end
		end
		local nextSuck, si = 0, 0
		WK.run({ holder = holder, life = math.clamp(tonumber(opts.life) or 4, 0.1, 20), kill = function()
			if loop then
				loop.stop(0.1)
			end
		end, step = function(_, t, dt, now)
			last = where() or last
			holder.CFrame = CFrame.new(last.Position)
			local camPos = WK.cam().Position
			local k = math.min(t / time, 1)
			local r = r0 + (r1 - r0) * (1 - (1 - k) * (1 - k))
			local o, flat = 0.9, 0
			if state == "release" then
				local f = (now - relT) / 0.06
				if f >= 1 then
					return false
				end
				flat, r, o = f, r * (1 + 1.8 * f), 0.9 * (1 - 0.4 * f)
			elseif state == "stop" then
				local f = (now - relT) / fadeT
				if f >= 1 then
					return false
				end
				o = 0.9 * (1 - f)
			end
			o *= WK.nearK(last.Position, camPos)
			local pulse = 1 + 0.12 * math.sin(t * 34)
			for _, s in orbits do
				s.a += s.rate * dt
				local u, v = s.u, s.v
				if flat > 0 then
					-- (folded into the plane across the blast)
					local nrm = WK.dir(s.nrm:Lerp(relDir, flat), s.nrm)
					u = WK.dir(nrm:Cross(math.abs(nrm.Y) < 0.9 and UP or X3), s.u)
					v = nrm:Cross(u)
				end
				streakLay(s, Vector3.zero, u, v, r * pulse, s.a, s.a + s.span, math.clamp(r0 * 0.2, 0.12, 2), o)
			end
			if state == "hold" and now >= nextSuck then
				nextSuck = now + (tonumber(opts.suckEvery) or 0.04)
				si = si % #suck + 1
				local s = suck[si]
				s.on, s.t0, s.from = true, now, WK.dir(Vector3.new(rand(-1, 1), rand(-0.6, 1), rand(-1, 1)), UP) * rand(6, 8) * math.max(r0 / 1.8, 0.5)
			end
			for _, s in suck do
				if s.on then
					local f = (now - s.t0) / 0.14
					if f >= 1 or state ~= "hold" then
						s.on = false
						s.beam.Enabled = false
					else
						local hk = f * f
						local tk = math.clamp(f - 0.3, 0, 1) / 0.7
						streakLine(s, s.from * (1 - tk * tk), s.from * (1 - hk) + s.from.Unit * r, 0.16, o * (1 - f * 0.5))
					end
				end
			end
			return true
		end })
		return h
	end

	---------------------------------------------------------------------
	-- the costume's wind points (where his wind comes out: canon says the
	-- costume flushes it through its tubes). WK.points(char) -> { Glove =
	-- {cf}, Knuckles = {cf x3}, Back = {cf x2}, Hips = {cf x2}, Ankles =
	-- {cf x2}, Knees = {cf x2}, Feet = {cf x2}, Hands = {right, left} }:
	-- each a world CFrame looking the way the air leaves. Worked out from his
	-- limbs every call (the look's own parts may be off: WEAR COSMETICS off,
	-- or hidden on a screen) - an R15 body too
	---------------------------------------------------------------------
	function WK.points(char)
		local out = { Glove = {}, Knuckles = {}, Back = {}, Hips = {}, Ankles = {}, Knees = {}, Feet = {}, Hands = {} }
		if typeof(char) ~= "Instance" or not char.Parent then
			return out
		end
		local L = C.Look or {}
		local function lookCF(pos, d, up)
			return WK.look(pos, d, up)
		end
		local la = limb(char, "LeftHand", "Left Arm")
		if la then
			local cf, s = la.CFrame, la.Size
			local r15 = la.Name == "LeftHand"
			local gh = r15 and s.Y or s.Y * (L.GloveShare or 0.4)
			local down = -cf.UpVector
			table.insert(out.Glove, lookCF((cf * CFrame.new(0, -s.Y / 2 + gh * 0.1, -(s.Z / 2 + 0.22))).Position, down, -cf.LookVector))
			for _, x in { -0.3, 0, 0.3 } do
				table.insert(out.Knuckles, lookCF((cf * CFrame.new(x * s.X, -s.Y / 2 - 0.16, -s.Z * 0.22)).Position, down, -cf.LookVector))
			end
		end
		for _, side in { { "RightHand", "Right Arm" }, { "LeftHand", "Left Arm" } } do
			local p = limb(char, side[1], side[2])
			if p then
				table.insert(out.Hands, lookCF((p.CFrame * CFrame.new(0, -p.Size.Y / 2, 0)).Position, -p.CFrame.UpVector))
			end
		end
		local torso = limb(char, "UpperTorso", "Torso")
		local lower = char:FindFirstChild("LowerTorso") or torso
		if torso then
			local cf, s = torso.CFrame, torso.Size
			for _, x in { -0.3, 0.3 } do
				table.insert(out.Back, lookCF((cf * CFrame.new(x * s.X / 2, s.Y * 0.18, s.Z / 2 + 0.15)).Position, (-cf.LookVector - cf.UpVector * 0.7).Unit))
			end
		end
		if lower then
			local cf, s = lower.CFrame, lower.Size
			for _, side in { 1, -1 } do
				local x = side * (s.X / 2 + 0.2)
				local y = lower == torso and -s.Y / 2 + 0.3 or 0
				table.insert(out.Hips, lookCF((cf * CFrame.new(x, y, 0)).Position, (cf.RightVector * side * 0.5 - cf.UpVector - cf.LookVector * 0.5).Unit))
			end
		end
		for _, side in { { "RightLowerLeg", "Right Leg", 1 }, { "LeftLowerLeg", "Left Leg", -1 } } do
			local leg = limb(char, side[1], side[2])
			if leg then
				local cf, s = leg.CFrame, leg.Size
				local r15 = leg.Name:find("Lower") ~= nil
				local fh = r15 and 0.3 or s.Y * (L.ShoeShare or 0.26)
				local ph = r15 and 0 or s.Y * (L.PantsShare or 0.5)
				table.insert(out.Ankles, lookCF((cf * CFrame.new(side[3] * (s.X / 2 + 0.22), -s.Y / 2 + fh + 0.04, 0)).Position, (cf.RightVector * side[3] - cf.UpVector * 0.8).Unit))
				table.insert(out.Knees, lookCF((cf * CFrame.new(0, s.Y / 2 - ph + 0.06, -(s.Z / 2 + 0.2))).Position, cf.LookVector))
				table.insert(out.Feet, lookCF((cf * CFrame.new(0, -s.Y / 2, 0)).Position, -cf.UpVector))
			end
		end
		return out
	end

	---------------------------------------------------------------------
	-- WK.vent(char, where, opts) -> holder: little white jets out of the
	-- costume (WK.points: "Glove", "Knuckles", "Back", "Hips", "Ankles",
	-- "Knees", "Feet", "Hands", or a list of them): a puff of air and a
	-- short streak shooting out of each, at most Caps.Vents. opts: n (8
	-- puffs a point), speed (12), size (1), length (2.2: the streak's),
	-- streak (true), dir (a world direction for all of them)
	---------------------------------------------------------------------
	function WK.vent(char, where, opts)
		opts = type(opts) == "table" and opts or {}
		local pts = WK.points(char)
		local list = {}
		for _, key in type(where) == "table" and where or { where or "Glove" } do
			for _, cf in pts[key] or {} do
				if #list < WK.n(CAPS.Vents or 8) then
					table.insert(list, cf)
				end
			end
		end
		if #list == 0 then
			return nil
		end
		local holder = WK.holder(CFrame.new(list[1].Position), "Vent")
		local k = tonumber(opts.size) or 1
		local spd = tonumber(opts.speed) or 12
		local forced = WK.dir(opts.dir, nil)
		local jets = {}
		for i, cf in list do
			local d = forced or cf.LookVector
			local h = WK.holder(WK.look(cf.Position, d), "VentJet")
			h.Parent = holder
			local pe = Instance.new("ParticleEmitter")
			pe.Name = "InasaWind"
			pe.Texture = TEX.smoke
			pe.Color = CS(PAL.CORE, PAL.HAZE)
			pe.Transparency = NS({ NK(0, 0.3), NK(1, 1) })
			pe.Size = NS({ NK(0, 0.45 * k), NK(1, 1.6 * k) })
			pe.Lifetime = NumberRange.new(0.15, 0.24)
			pe.Speed = NumberRange.new(spd * 0.8, spd * 1.2)
			pe.SpreadAngle = Vector2.new(12, 12)
			pe.Drag = 3
			pe.LightEmission = 0.1
			pe.LightInfluence = 0.4
			pe.EmissionDirection = Enum.NormalId.Front
			pe.Rate = 0
			pe.Parent = h
			pe:Emit(WK.n(math.clamp(math.floor(tonumber(opts.n) or 8), 1, 16)))
			if opts.streak ~= false then
				local s = streakMake(h)
				s.len = math.clamp(tonumber(opts.length) or 2.2, 0.3, 20) * k
				jets[i] = s
			end
		end
		WK.run({ holder = holder, life = 0.6, step = function(_, t)
			local f = math.clamp(t / 0.16, 0, 1)
			for _, s in jets do
				streakLine(s, Vector3.new(0, 0, -s.len * (0.1 + 0.9 * math.clamp((t - 0.05) / 0.12, 0, 1))), Vector3.new(0, 0, -s.len * (0.3 + 0.7 * f)), 0.2 * k, 0.85 * (1 - f * f))
			end
			return t < 0.5
		end })
		return holder
	end

	---------------------------------------------------------------------
	-- WK.armWind(char, arm, opts) -> handle: WIND COILED ROUND AN ARM (his
	-- throws start there: the anime coils thin helix lines round the arm a
	-- beat before the punch) - 2-3 strands of thin streaks wrapped round it,
	-- sliding from the shoulder to the hand and turning. The gloved left arm
	-- vents from its knuckles and nozzle when it starts. arm: "Left" (the
	-- glove) or "Right". opts: strands (2, at most Caps.Strands), spin (2
	-- turns a second), radius (1.05: outside the glove), width (0.16), dur (nil: until it's let
	-- go or stopped; at most 6 s), vent (true on the left), color.
	-- The handle: :release(dir) (the coils straighten into streaks shooting
	-- off the hand along dir, the glove vents again), :stop(fade)
	---------------------------------------------------------------------
	function WK.armWind(char, arm, opts)
		opts = type(opts) == "table" and opts or {}
		if typeof(char) ~= "Instance" or not char.Parent then
			return nil
		end
		local left = arm == "Left" or arm == "L" or arm == "left"
		local upper = limb(char, left and "LeftUpperArm" or "RightUpperArm", left and "Left Arm" or "Right Arm")
		local hand = limb(char, left and "LeftHand" or "RightHand", left and "Left Arm" or "Right Arm")
		if not (upper and hand) then
			return nil
		end
		local ns = WK.n(math.clamp(math.floor(tonumber(opts.strands) or 2), 1, CAPS.Strands or 3))
		local spin = (tonumber(opts.spin) or 2) * TAU
		local R = math.clamp(tonumber(opts.radius) or 1.05, 0.2, 10)
		local w = math.clamp(tonumber(opts.width) or 0.16, 0.04, 4)
		local holder = WK.holder(upper.CFrame, "ArmWind")
		local strands = {}
		for i = 1, ns do
			local st = { atts = {}, beams = {}, ph = (i - 1) / ns * TAU }
			for j = 1, 4 do
				st.atts[j] = WK.att(holder)
			end
			for j = 1, 3 do
				st.beams[j] = WK.beam(st.atts[j], st.atts[j + 1], opts.color or PAL.AIR, w * (0.25 + 0.25 * j), w * (0.5 + 0.25 * j), holder, { segments = 8 })
			end
			strands[i] = st
		end
		if left and opts.vent ~= false then
			WK.vent(char, { "Glove", "Knuckles" }, { n = 6, length = 1.4 })
		end
		local h = { holder = holder }
		local state, relT, fadeT = "on", 0, 0.1
		function h:release(dir)
			if state ~= "on" then
				return
			end
			state, relT, fadeT = "off", WK.now(), 0.08
			local hp = hand.CFrame * CFrame.new(0, -hand.Size.Y / 2, 0)
			local d = WK.dir(dir, -hand.CFrame.UpVector)
			WK.streaks(WK.look(hp.Position, d), { n = ns * 2, length = 9, spread = R * 0.9, width = w * 1.4, speed = 70, bend = 1 })
			if left and opts.vent ~= false then
				WK.vent(char, "Knuckles", { n = 8, length = 2.6, speed = 16 })
			end
		end
		function h:stop(fade)
			if state == "on" then
				state, relT, fadeT = "off", WK.now(), math.max(tonumber(fade) or 0.1, 0.02)
			end
		end
		local dur = math.clamp(tonumber(opts.dur) or 6, 0.05, 6)
		local was = IN.isInasa(char)
		WK.run({ holder = holder, life = dur + 0.3, step = function(_, t, dt, now)
			if not (upper.Parent and hand.Parent) or WK.over(char, was) then
				return false
			end
			local o = 0.85 * math.min(t / 0.08, 1)
			if state == "off" then
				local f = (now - relT) / fadeT
				if f >= 1 then
					return false
				end
				o *= 1 - f
			elseif t > dur then
				return false
			end
			-- the arm's axis: from the top of the upper arm to the bottom of the hand
			local top = (upper.CFrame * CFrame.new(0, upper.Size.Y / 2, 0)).Position
			local bottom = (hand.CFrame * CFrame.new(0, -hand.Size.Y / 2, 0)).Position
			local ax = bottom - top
			local L = ax.Magnitude
			if L < 0.1 then
				return true
			end
			local ay = -ax.Unit
			local rx = upper.CFrame.RightVector
			rx = WK.dir(rx - ay * rx:Dot(ay), ay:Cross(Z3).Magnitude > 0.1 and ay:Cross(Z3).Unit or X3)
			local frame = CFrame.fromMatrix(top, rx, ay)
			holder.CFrame = frame
			o *= WK.nearK(top, WK.cam().Position) * (WK.hidden(hand) and 0 or 1)
			for _, st in strands do
				-- a strand coils 1.3 turns round 70% of the arm, sliding down it
				local slide = ((t * 1.6 + st.ph / TAU) % 1)
				local y0 = -L * (slide * 0.6 - 0.2)
				for j = 1, 4 do
					local s = (j - 1) / 3
					local phi = st.ph + spin * t + s * TAU * 1.3
					local y = math.clamp(y0 - s * L * 0.7, -L * 1.02, 0.2)
					local p = Vector3.new(math.cos(phi) * R, y, math.sin(phi) * R)
					local tanv = Vector3.new(-math.sin(phi) * R * TAU * 1.3, -L * 0.7, math.cos(phi) * R * TAU * 1.3).Unit
					st.atts[j].CFrame = CFrame.fromMatrix(p, tanv, Vector3.new(math.cos(phi), 0, math.sin(phi)):Cross(tanv).Unit)
				end
				local seg = math.sqrt(bend(TAU * 1.3 / 3, R) ^ 2 + (L * 0.7 / 9) ^ 2)
				for _, b in st.beams do
					b.CurveSize0, b.CurveSize1 = seg, seg
					b.Transparency = WK.seq(o, "flat")
					b.Enabled = o > 0.02
				end
			end
			return true
		end })
		return h
	end

	---------------------------------------------------------------------
	-- WK.curtain(cf, width, height, opts) -> handle: THE GUST CURTAIN (the
	-- anime's wall of wind pouring down - WIND WALL): a bowed sheet across
	-- cf's front (cf: its foot's middle on the street, LookVector out of it)
	-- - a veil of haze, streaks flowing up and forward through it, curls
	-- rolling along its top edge and sides, a jagged foot of short streaks
	-- pouring down and splashing dust. opts: bow (studs its middle stands
	-- out, width * 0.18), streaks (16, at most Caps.CurtainStreaks), warm
	-- (the ult's: the passion shade), pillars (2 storm ropes at its ends),
	-- life (it stops itself; at most 12 s), color.
	-- The handle: :ripple(point) (a ring opening on the sheet there),
	-- :bulge(point) (a dome of bands pushed out of it), :move(cf), :stop(t)
	-- (it lifts up and away into curls), .holder
	---------------------------------------------------------------------
	function WK.curtain(cf, width, height, opts)
		opts = type(opts) == "table" and opts or {}
		cf = WK.cf(cf)
		if not cf then
			return nil
		end
		local W = math.clamp(tonumber(width) or 14, 1, 200)
		local H = math.clamp(tonumber(height) or 12, 1, 200)
		local bow = tonumber(opts.bow) or W * 0.18
		local low = WK.low()
		local shade = opts.warm and PAL.PASSION or PAL.SHADE
		local holder = WK.holder(cf, "Curtain")
		local frame = cf
		local function sheet(s, y)
			-- a point on the sheet (in the holder's space): s -1 .. 1 across, y up
			return Vector3.new(s * W / 2, y, -bow * (1 - s * s))
		end
		local function normal(s)
			local tx = Vector3.new(W / 2, 0, 2 * bow * s).Unit
			return tx:Cross(UP)
		end
		-- the veil
		local veils = {}
		for i = 1, low and 1 or 3 do
			local s = low and 0 or (i - 2) * 0.62
			local vh = WK.holder(cf, "CurtainVeil")
			vh.Parent = holder
			vh.Size = Vector3.new(W / (low and 1 or 3) * 1.1, 0.5, 0.5)
			local pe = Instance.new("ParticleEmitter")
			pe.Name = "InasaWind"
			pe.Texture = TEX.smoke
			pe.Color = CS(PAL.AIR, PAL.HAZE)
			pe.Transparency = NS({ NK(0, 1), NK(0.25, 0.62), NK(0.7, 0.75), NK(1, 1) })
			pe.Size = NS({ NK(0, H * 0.3), NK(1, H * 0.62) })
			pe.Lifetime = NumberRange.new(0.5, 0.75)
			pe.Speed = NumberRange.new(H * 1.1, H * 1.6)
			pe.SpreadAngle = Vector2.new(10, 10)
			pe.Drag = 1
			pe.LightEmission = 0.05
			pe.LightInfluence = 0.5
			pe.Rotation = NumberRange.new(0, 360)
			pe.RotSpeed = NumberRange.new(-20, 20)
			pe.EmissionDirection = Enum.NormalId.Top
			pe.Rate = low and 12 or 16
			pe.Parent = vh
			veils[i] = { holder = vh, s = s, pe = pe }
		end
		-- its body: wide soft sheets of haze flowing up it (smoke scrolling up
		-- wide beams), widest at the top
		local sheets = {}
		for i = 1, low and 3 or 5 do
			local n = low and 3 or 5
			local sv = ((i - 0.5) / n) * 2 - 1
			local a0, a1 = WK.att(holder), WK.att(holder)
			local b = WK.beam(a0, a1, CS(PAL.HAZE, PAL.AIR), W / n * 1.5, W / n * 1.9, holder, { segments = 6, light = 0.08, influence = 0.45, transp = NS({ NK(0, 1), NK(0.2, 0.84), NK(0.75, 0.74), NK(1, 0.88) }), z = -0.2 })
			b.Texture = TEX.smoke
			b.TextureMode = Enum.TextureMode.Wrap
			b.TextureLength = H * 0.55
			b.TextureSpeed = 1.3 + (i % 2) * 0.3
			sheets[i] = { a0 = a0, a1 = a1, s = sv, beam = b }
		end
		-- the dust boiling at its foot
		local footH = WK.holder(cf, "CurtainFoot")
		footH.Parent = holder
		footH.Size = Vector3.new(W, 0.4, 1.2)
		local dust = Instance.new("ParticleEmitter")
		dust.Name = "InasaWind"
		dust.Texture = TEX.smoke
		dust.Color = CS(PAL.DUST, PAL.DUST_DARK)
		dust.Transparency = NS({ NK(0, 1), NK(0.2, 0.55), NK(1, 1) })
		dust.Size = NS({ NK(0, 1.2), NK(1, 3.4) })
		dust.Lifetime = NumberRange.new(0.5, 0.9)
		dust.Speed = NumberRange.new(3, 8)
		dust.SpreadAngle = Vector2.new(35, 35)
		dust.Acceleration = Vector3.new(0, 2, 0)
		dust.Drag = 1.5
		dust.LightInfluence = 0.7
		dust.EmissionDirection = Enum.NormalId.Front
		dust.Rate = low and 12 or 26
		dust.Parent = footH
		-- the streaks (a third of them the foot's teeth pouring down)
		local ns = WK.n(math.clamp(math.floor(tonumber(opts.streaks) or 16), 1, CAPS.CurtainStreaks or 18))
		local streaksL = {}
		for i = 1, ns do
			streaksL[i] = streakMake(holder, opts.color)
			streaksL[i].tooth = i % 3 == 0
			streaksL[i].t0 = -rand(0, 0.4)
		end
		local cs = {}
		for i = 1, low and 3 or 6 do
			cs[i] = curlSlot(holder, opts.color)
		end
		-- its top edge (a wedge, widest up there) and a band across its middle:
		-- crescents along the bow
		local Rb = (W * W / 4 + bow * bow) / (2 * math.max(bow, 0.05))
		local half = math.asin(math.clamp(W / 2 / Rb, 0, 1))
		local edges = {}
		for i, e in { { y = H, w = 1.5, k = 1 }, { y = H * 0.58, w = 0.8, k = 0.8 } } do
			if i == 1 or not low then
				edges[i] = { band = WK.band(holder, { color = opts.color or PAL.AIR, shade = shade }), y = e.y, w = e.w, k = e.k, ph = rand(0, TAU) }
			end
		end
		local ripples = {}
		for i = 1, 3 do
			ripples[i] = { ring = ringMake(holder, PAL.AIR, 0.3), t0 = -10 }
		end
		local bulges = {}
		for i = 1, 2 do
			bulges[i] = { band = WK.band(holder, { color = PAL.AIR, shade = shade }), t0 = -10 }
		end
		local pillars = {}
		if opts.pillars and not low then
			for i, s in { -1, 1 } do
				local foot = cf * sheet(s, 0)
				pillars[i] = WK.rope(foot, foot + UP * H * 1.1, { radius = 1.4, storm = true, spin = 1.6 * s, strands = 2 })
			end
		end
		local h = { holder = holder }
		local stopAt, stopT
		local ri, bi = 0, 0
		local function nearestS(point)
			local lp = frame:PointToObjectSpace(point)
			return math.clamp(lp.X / (W / 2), -1, 1), math.clamp(lp.Y, 0.5, H - 0.5)
		end
		function h:ripple(point)
			point = WK.v3(point)
			if point then
				ri = ri % #ripples + 1
				local s, y = nearestS(point)
				ripples[ri].s, ripples[ri].y, ripples[ri].t0 = s, y, WK.now()
			end
		end
		function h:bulge(point)
			point = WK.v3(point)
			if point then
				bi = bi % #bulges + 1
				local s, y = nearestS(point)
				bulges[bi].s, bulges[bi].y, bulges[bi].t0 = s, y, WK.now()
			end
		end
		function h:move(newCF)
			newCF = WK.cf(newCF)
			if newCF then
				frame = newCF
			end
		end
		function h:stop(t)
			if not stopAt then
				stopAt, stopT = WK.now(), math.max(tonumber(t) or 0.25, 0.05)
				for _, v in veils do
					v.pe.Rate = 0
				end
				dust.Rate = 0
				for i, s in cs do
					armCurl(s, frame * sheet((i - 0.5) / #cs * 2 - 1, H), frame.UpVector + frame.LookVector * 0.4, { size = 2.6, drift = H * 0.4, life = stopT + 0.2 })
				end
				for _, p in pillars do
					p:stop(stopT)
				end
			end
		end
		local life = math.clamp(tonumber(opts.life) or 12, 0.1, 12)
		local nextCurl, ci = 0, 0
		WK.run({ holder = holder, life = life + 1, step = function(_, t, _dt, now)
			if t > life and not stopAt then
				h:stop(0.25)
			end
			local lift = 0
			local alpha = math.min(t / 0.12, 1)
			if stopAt then
				local f = (now - stopAt) / stopT
				if f >= 1 then
					return false
				end
				lift = H * 0.6 * f * f
				alpha *= 1 - f
			end
			local hcf = frame + frame.UpVector * lift
			holder.CFrame = hcf
			local cam = WK.cam()
			local o0 = alpha * WK.nearK(hcf.Position, cam.Position)
			for _, v in veils do
				v.holder.CFrame = hcf * CFrame.new(sheet(v.s, H * 0.05))
			end
			footH.CFrame = hcf * CFrame.new(0, 0.3, -bow * 0.6)
			-- the streaks: up and forward through it (the teeth: down into the street)
			for _, s in streaksL do
				local age = t - s.t0
				local dur = s.tooth and 0.22 or 0.38
				if age > dur or not s.at then
					s.t0, s.at = t, rand(-0.95, 0.95)
					s.w = rand(0.18, 0.36)
					s.y0 = s.tooth and 0 or rand(0, H * 0.45)
					age = 0
				end
				local f = age / dur
				local hk = 1 - (1 - math.min(f / 0.7, 1)) ^ 2
				local tk = math.clamp((f - 0.35) / 0.65, 0, 1)
				local p0, p1
				if s.tooth then
					p0 = sheet(s.at, 2.2 * (1 - tk)) + normal(s.at) * 0.2
					p1 = sheet(s.at, 2.2 * (1 - hk)) + normal(s.at) * 0.2
				else
					local span = H - s.y0
					p0 = sheet(s.at, s.y0 + span * tk) + normal(s.at) * (tk * tk * 1.5)
					p1 = sheet(s.at, s.y0 + span * hk) + normal(s.at) * (hk * hk * 1.5)
				end
				streakLine(s, p0, p1, s.w, 0.7 * o0 * (1 - tk))
			end
			for _, sh in sheets do
				sh.a0.CFrame = CFrame.fromMatrix(sheet(sh.s, 0), UP, normal(sh.s))
				sh.a1.CFrame = CFrame.fromMatrix(sheet(sh.s, H) + normal(sh.s) * 0.8, UP, normal(sh.s))
				sh.beam.CurveSize0, sh.beam.CurveSize1 = H * 0.3, H * 0.2
				local q = math.floor(o0 * 12 + 0.5)
				if q ~= sh.q then
					sh.q = q
					local v = 1 - q / 12 * 0.26
					sh.beam.Transparency = NS({ NK(0, 1), NK(0.2, 1 - (1 - 0.84) * q / 12), NK(0.75, v), NK(1, 1 - (1 - 0.88) * q / 12) })
					sh.beam.Enabled = q > 0
				end
			end
			for _, e in edges do
				local wob = math.sin(t * 9 + e.ph) * 0.15
				WK.layBand(e.band, Vector3.new(0, e.y + wob, -bow + Rb), Vector3.new(0, 0, -1), X3, Rb, -half * e.k, half * e.k, e.w * (1 + 0.15 * math.sin(t * 13 + e.ph)), 0.9 * o0)
			end
			-- curls rolling along its top and off its sides
			if not stopAt and now >= nextCurl and #cs > 0 then
				nextCurl = now + 0.12
				ci = ci % #cs + 1
				local edge = ci % 3 == 0
				local s = edge and (ci % 2 == 0 and 1 or -1) or rand(-0.9, 0.9)
				local y = edge and rand(H * 0.3, H) or H
				local out = edge and (hcf.RightVector * s) or (hcf.UpVector + hcf.LookVector * 0.5)
				armCurl(cs[ci], hcf * sheet(s, y), out, { size = math.clamp(H * 0.2, 1.2, 6), drift = 2.5 })
			end
			for _, s in cs do
				stepCurl(s, now, cam, hcf)
			end
			for _, rp in ripples do
				local f = (now - rp.t0) / 0.28
				if f >= 0 and f <= 1 then
					local nrm = normal(rp.s)
					local u = Vector3.new(W / 2, 0, 2 * bow * rp.s).Unit
					ringLay(rp.ring, sheet(rp.s, rp.y) + nrm * 0.1, u, UP, 1 + 4 * (1 - (1 - f) ^ 2), 0.35 * (1 - f) + 0.08, 0.9 * (1 - f) * o0)
					rp.shown = true
				elseif rp.shown then
					rp.shown = false
					ringLay(rp.ring, Vector3.zero, X3, Y3, 1, 0.1, 0)
				end
			end
			for _, bg in bulges do
				local f = (now - bg.t0) / 0.24
				if f >= 0 and f <= 1 then
					local nrm = normal(bg.s)
					local c = sheet(bg.s, bg.y)
					local r = 2 + 1.2 * math.min(f / 0.35, 1)
					WK.layBand(bg.band, c, -nrm, UP, r, -1.2, 1.2, 0.9 * (1 - f) + 0.2, 0.9 * (1 - math.max(f - 0.35, 0) / 0.65) * o0)
					bg.shown = true
				elseif bg.shown then
					bg.shown = false
					WK.fadeBand(bg.band, 0)
				end
			end
			return true
		end })
		return h
	end

	---------------------------------------------------------------------
	-- WK.rope(a, b, opts) -> handle: A ROPE TWISTER (the Final War's storm
	-- ropes, shape E): a twisted column from a to b of helical strands - the
	-- tan-grey storm palette with a dark hatch streak in it - turning on its
	-- axis, white sawtooth curls flicking off its edges. opts: radius (2; r0
	-- / r1: at a / at b), pitch (8 studs a turn; at most Caps.RopeTurns a
	-- strand), strands (3, at most Caps.RopeStrands), width (1.2), spin
	-- (1.5 turns a second; negative the other way), storm (true; false: the
	-- white bands' palette), phase, curls (true), life (it stops itself).
	-- The handle: :set(a, b) (its ends), :stop(fade), .holder
	---------------------------------------------------------------------
	function WK.rope(a, b, opts)
		opts = type(opts) == "table" and opts or {}
		a, b = WK.v3(a), WK.v3(b)
		if not (a and b) or (b - a).Magnitude < 0.5 then
			return nil
		end
		local low = WK.low()
		local r0 = math.clamp(tonumber(opts.r0) or tonumber(opts.radius) or 2, 0.1, 200)
		local r1 = math.clamp(tonumber(opts.r1) or tonumber(opts.radius) or 2, 0.1, 200)
		local pitch = math.max(tonumber(opts.pitch) or 8, 0.5)
		local ns = math.clamp(math.floor(tonumber(opts.strands) or 3), 1, CAPS.RopeStrands or 3)
		if low then
			ns = math.min(ns, 2)
		end
		local w = math.clamp(tonumber(opts.width) or 1.2, 0.05, 40)
		local spin = (tonumber(opts.spin) or 1.5) * TAU
		local storm = opts.storm ~= false
		local styles = storm and {
			{ color = PAL.STORM, w = 1, r = 1 }, { color = PAL.STORM_DARK, w = 0.7, r = 0.92 }, { color = PAL.HATCH, w = 0.22, r = 1.06 },
		} or {
			{ color = PAL.AIR, w = 1, r = 1 }, { color = PAL.SHADE, w = 0.7, r = 0.92 }, { color = PAL.CORE, w = 0.25, r = 1.05 },
		}
		local holder = WK.holder(WK.upFrame(a, b - a), "Rope")
		local len = (b - a).Magnitude
		local strands = {}
		for i = 1, ns do
			local st = styles[i]
			local s = { atts = {}, beams = {}, style = st, ph = (tonumber(opts.phase) or 0) + (i - 1) / ns * TAU }
			strands[i] = s
		end
		local function lay()
			local turns = math.min(len / pitch, CAPS.RopeTurns or 8)
			local pieces = math.max(math.ceil(turns * 3), 1)
			for _, s in strands do
				-- (made, or grown, as the length asks)
				while #s.atts < pieces + 1 do
					table.insert(s.atts, WK.att(holder))
				end
				while #s.beams < pieces do
					local j = #s.beams + 1
					table.insert(s.beams, WK.beam(s.atts[j], s.atts[j + 1], s.style.color, 1, 1, holder, { segments = 8, light = 0.05, influence = 0.5 }))
				end
				for j = pieces + 1, #s.beams do
					s.beams[j].Enabled = false
				end
				local dphi = turns * TAU / pieces
				for j = 1, pieces + 1 do
					local k = (j - 1) / pieces
					local phi = s.ph + k * turns * TAU
					local r = (r0 + (r1 - r0) * k) * s.style.r
					local p = Vector3.new(math.cos(phi) * r, k * len, math.sin(phi) * r)
					local tanv = Vector3.new(-math.sin(phi) * r * turns * TAU, len, math.cos(phi) * r * turns * TAU).Unit
					s.atts[j].CFrame = CFrame.fromMatrix(p, tanv, Vector3.new(math.cos(phi), 0, math.sin(phi)):Cross(tanv).Unit)
				end
				for j = 1, pieces do
					local k = (j - 0.5) / pieces
					local r = (r0 + (r1 - r0) * k) * s.style.r
					local seg = math.sqrt((r * dphi) ^ 2 + (len / pieces) ^ 2) / 3
					local bm = s.beams[j]
					bm.CurveSize0, bm.CurveSize1 = seg, seg
					local wk = w * s.style.w * (0.75 + 0.5 * (r0 + (r1 - r0) * k) / math.max(r0, r1))
					bm.Width0, bm.Width1 = wk, wk
					bm.Enabled = true
				end
				s.pieces = pieces
			end
		end
		lay()
		local cs = {}
		if opts.curls ~= false then
			for i = 1, low and 2 or 4 do
				cs[i] = curlSlot(holder, storm and PAL.AIR or PAL.CORE)
			end
		end
		local h = { holder = holder }
		local stopAt, stopT
		local A, Bp = a, b
		function h:set(na, nb2)
			na, nb2 = WK.v3(na), WK.v3(nb2)
			if na and nb2 and (nb2 - na).Magnitude >= 0.5 then
				A, Bp = na, nb2
				local nl = (nb2 - na).Magnitude
				if math.abs(nl - len) > len * 0.1 then
					len = nl
					lay()
				end
			end
		end
		function h:stop(fade)
			if not stopAt then
				stopAt, stopT = WK.now(), math.max(tonumber(fade) or 0.3, 0.02)
			end
		end
		local life = tonumber(opts.life)
		local angle, nextCurl, ci, q = 0, 0, 0, -1
		WK.run({ holder = holder, life = math.min(life or 30, 30) + 1, step = function(_, t, dt, now)
			if life and t > life and not stopAt then
				h:stop(0.3)
			end
			local alpha = math.min(t / 0.15, 1)
			if stopAt then
				local f = (now - stopAt) / stopT
				if f >= 1 then
					return false
				end
				alpha *= 1 - f
			end
			angle += spin * dt
			local axis = Bp - A
			local scale = axis.Magnitude / len
			holder.CFrame = WK.upFrame(A, axis) * CFrame.Angles(0, -angle, 0)
			local cam = WK.cam()
			local o = 0.88 * alpha * WK.nearK(A + axis * 0.5, cam.Position)
			local nq = math.floor(o * 24 + 0.5)
			if nq ~= q then
				q = nq
				for _, s in strands do
					for j = 1, s.pieces do
						s.beams[j].Transparency = WK.seq(o, "flat")
						s.beams[j].Enabled = nq > 0
					end
				end
			end
			if #cs > 0 and not stopAt and now >= nextCurl then
				nextCurl = now + 0.2
				ci = ci % #cs + 1
				local k = rand(0.1, 0.95)
				local phi = rand(0, TAU)
				local hcf = holder.CFrame
				local r = (r0 + (r1 - r0) * k) * 1.05
				local radial = hcf:VectorToWorldSpace(Vector3.new(math.cos(phi), 0, math.sin(phi)))
				armCurl(cs[ci], hcf * Vector3.new(math.cos(phi) * r, k * len * scale, math.sin(phi) * r), radial + hcf.UpVector * 0.4, { size = math.clamp(r * 0.6, 0.8, 10), drift = math.clamp(r, 1, 12), life = 0.32 })
			end
			local hcf = holder.CFrame
			for _, s in cs do
				stepCurl(s, now, cam, hcf)
			end
			return true
		end })
		return h
	end

	---------------------------------------------------------------------
	-- WK.screenWind(kind, time, opts) -> the ScreenGui: THIS SCREEN ONLY
	-- (call it on his own screen, or a cutscene's): the anime's screen
	-- dressing, built of plain frames and gradients, gone after `time`.
	-- kind: "field" (the Ep 54 "wind field": a deep-blue sky swept by dense
	-- curved white strokes all flowing one way - for a cinematic arm shot,
	-- 0.2-0.35 s; opts.angle: their slant, -16), "hatch" (black diagonal
	-- manga hatching down both sides behind a close-up, 0.15-0.3 s),
	-- "radial" (white streaks bursting out from the middle: the gather
	-- point's burst, 0.3 s), "wipe" (a translucent white band sweeping
	-- across the lens, 0.25 s; opts.dir 1 / -1). opts: color, strength (1)
	---------------------------------------------------------------------
	function WK.screenWind(kind, time, opts)
		opts = type(opts) == "table" and opts or {}
		local lp = Players.LocalPlayer
		local pg = lp and lp:FindFirstChildOfClass("PlayerGui")
		if not pg or (kind ~= "field" and kind ~= "hatch" and kind ~= "radial" and kind ~= "wipe") then
			return nil
		end
		time = math.clamp(tonumber(time) or 0.3, 0.05, 3)
		local low = WK.low()
		local gui = Instance.new("ScreenGui")
		gui.Name = "InasaScreenWind"
		gui.IgnoreGuiInset = true
		gui.ResetOnSpawn = false
		gui.DisplayOrder = 10
		local items = {}
		local function frame(parent, color, tr)
			local f = Instance.new("Frame")
			f.BorderSizePixel = 0
			f.BackgroundColor3 = color
			f.BackgroundTransparency = tr
			f.Parent = parent
			return f
		end
		local strength = math.clamp(tonumber(opts.strength) or 1, 0, 1)
		if kind == "field" then
			local bg = frame(gui, Color3.new(1, 1, 1), 1) -- (its gradient is the colour: a UIGradient multiplies)
			bg.Size = UDim2.fromScale(1, 1)
			local grad = Instance.new("UIGradient")
			grad.Color = ColorSequence.new(PAL.SKY_DEEP, PAL.SKY_MID)
			grad.Rotation = 35
			grad.Parent = bg
			items.bg = bg
			local ang = tonumber(opts.angle) or -16
			items.strokes = {}
			for i = 1, low and 14 or 26 do
				local y = (i - 0.5) / (low and 14 or 26)
				local s = frame(gui, opts.color or PAL.AIR, 1)
				s.AnchorPoint = Vector2.new(0.5, 0.5)
				local thick = 2 + (i * 7) % 5
				local long = 0.45 + ((i * 0.37) % 1) * 0.55
				s.Size = UDim2.new(long, 0, 0, thick)
				s.Rotation = ang + math.sin(i * 1.3) * 4
				local corner = Instance.new("UICorner")
				corner.CornerRadius = UDim.new(1, 0)
				corner.Parent = s
				table.insert(items.strokes, { f = s, y = y * 1.3 - 0.15, x0 = -0.6 - ((i * 0.53) % 1) * 0.5, speed = 2.6 + ((i * 0.71) % 1) * 1.6, tr = 0.05 + ((i * 0.29) % 1) * 0.4 })
			end
		elseif kind == "hatch" then
			items.lines = {}
			local n = low and 18 or 34
			for i = 1, n do
				local left = i % 2 == 0
				local k = math.floor((i - 1) / 2) / math.max(math.floor(n / 2) - 1, 1)
				local s = frame(gui, Color3.fromRGB(14, 12, 14), 1)
				s.AnchorPoint = Vector2.new(0.5, 0.5)
				local long = 0.18 + ((i * 0.41) % 1) * 0.22
				s.Size = UDim2.new(long, 0, 0, 3 + i % 3)
				s.Rotation = -52
				s.Position = UDim2.fromScale((left and 0.1 or 0.9) + ((i * 0.37) % 1 - 0.5) * 0.16, -0.05 + k * 1.1)
				table.insert(items.lines, { f = s, base = s.Position, tr = 0.05 + ((i * 0.23) % 1) * 0.25 })
			end
		elseif kind == "radial" then
			items.rays = {}
			local n = low and 12 or 24
			for i = 1, n do
				local a = (i - 0.5) / n * TAU + math.sin(i * 7.1) * 0.08
				local s = frame(gui, opts.color or PAL.AIR, 1)
				s.AnchorPoint = Vector2.new(0.5, 0.5)
				s.Rotation = math.deg(a)
				local corner = Instance.new("UICorner")
				corner.CornerRadius = UDim.new(1, 0)
				corner.Parent = s
				table.insert(items.rays, { f = s, a = a, k = 0.7 + ((i * 0.61) % 1) * 0.6, thick = 2 + i % 4 })
			end
		else
			local band = frame(gui, opts.color or PAL.HAZE, 0)
			band.AnchorPoint = Vector2.new(0.5, 0.5)
			band.Size = UDim2.fromScale(0.55, 1.8)
			band.Rotation = 14
			local grad = Instance.new("UIGradient")
			grad.Transparency = NumberSequence.new({ NK(0, 1), NK(0.35, 0.55), NK(0.5, 0.45), NK(0.65, 0.55), NK(1, 1) })
			grad.Parent = band
			items.band = band
		end
		gui.Parent = pg
		local dir = opts.dir == -1 and -1 or 1
		WK.run({ holder = gui, life = time + 0.2, step = function(_, t)
			local f = math.clamp(t / time, 0, 1)
			local env = math.min(f / 0.15, 1) * math.min((1 - f) / 0.25, 1)
			local vis = 1 - env * strength
			if kind == "field" then
				items.bg.BackgroundTransparency = 1 - (1 - 0.12) * env * strength
				for _, s in items.strokes do
					local x = s.x0 + s.speed * f * 0.6
					s.f.Position = UDim2.fromScale(x + 0.5, s.y + (x - 0.2) * math.tan(math.rad(-(tonumber(opts.angle) or -16))) * 0.5)
					s.f.BackgroundTransparency = 1 - (1 - s.tr) * env * strength
				end
			elseif kind == "hatch" then
				local jit = math.floor(t / 0.05) % 2 == 0 and 0.004 or -0.004
				for _, s in items.lines do
					s.f.Position = s.base + UDim2.fromScale(jit, 0)
					s.f.BackgroundTransparency = 1 - (1 - s.tr) * env * strength
				end
			elseif kind == "radial" then
				local e = 1 - (1 - f) * (1 - f)
				for _, s in items.rays do
					local r = 0.05 + 0.75 * e * s.k
					local long = 0.08 + 0.32 * e * s.k
					s.f.Position = UDim2.fromScale(0.5 + math.cos(s.a) * (r + long / 2) * 0.5625, 0.5 + math.sin(s.a) * (r + long / 2))
					s.f.Size = UDim2.new(long * 0.5625, 0, 0, s.thick)
					s.f.BackgroundTransparency = 1 - (1 - 0.1) * env * strength
				end
			else
				items.band.Position = UDim2.fromScale(dir > 0 and (-0.4 + 1.8 * f) or (1.4 - 1.8 * f), 0.5)
				items.band.BackgroundTransparency = 1 - env * strength
			end
			return t < time and vis >= 0
		end })
		return gui
	end

	---------------------------------------------------------------------
	-- WK.kick(dir, amount, time): HIS OWN CAMERA shoved along dir (a gust's
	-- way: amount studs, dying away over time - 0.25 s) on top of whatever
	-- the camera does; none in a cutscene. WK.fovPunch is the Engine kit's
	-- (VFX.EngineKit.fovPunch: an offset that never fights the sprint's)
	---------------------------------------------------------------------
	WK.kicks = {}
	WK.kickState = { last = Vector3.zero }
	function WK.kick(dir, amount, time)
		dir = WK.dir(dir, nil)
		amount = tonumber(amount)
		if not dir or not amount or amount ~= amount or VFX.InCinematic() then
			return
		end
		table.insert(WK.kicks, { dir = dir, amount = math.clamp(amount, -4, 4), time = math.clamp(tonumber(time) or 0.25, 0.05, 2), t0 = WK.now() })
		if not WK.kickBound then
			WK.kickBound = true
			RunService:BindToRenderStep("InasaWindKick", Enum.RenderPriority.Camera.Value + 2, function()
				local cam = workspace.CurrentCamera
				local now = WK.now()
				local off = Vector3.zero
				for i = #WK.kicks, 1, -1 do
					local k = WK.kicks[i]
					local f = (now - k.t0) / k.time
					if f >= 1 then
						table.remove(WK.kicks, i)
					else
						off += k.dir * k.amount * math.sin(f * math.pi * 1.5) * (1 - f) * (1 - f)
					end
				end
				if #WK.kicks == 0 then
					local K = WK.kickState
					if cam and K.written and (cam.CFrame.Position - K.written).Magnitude < 1e-4 then
						cam.CFrame = cam.CFrame - K.last
					end
					K.written, K.last = nil, Vector3.zero
					WK.kickBound = false
					pcall(function()
						RunService:UnbindFromRenderStep("InasaWindKick")
					end)
					return
				end
				if cam and not VFX.InCinematic() and cam.CameraType ~= Enum.CameraType.Scriptable and off == off then
					-- (an offset on top of the camera: where nothing put the camera
					-- back since our last frame, last frame's offset comes off first)
					local cf = cam.CFrame
					local K = WK.kickState
					if K.written and (cf.Position - K.written).Magnitude < 1e-4 then
						cf = cf - K.last
					end
					cam.CFrame = cf + off
					K.written, K.last = cam.CFrame.Position, off
				end
			end)
		end
	end
	WK.fovPunch = function(...)
		local EK = VFX.EngineKit
		if EK and EK.fovPunch then
			return EK.fovPunch(...)
		end
	end

	---------------------------------------------------------------------
	-- WK.loop(cue, parent, opts) -> handle: A HELD SOUND BED from a
	-- Config.Sounds cue (every layer its own looped Sound - the ClashLoop
	-- way: a cue's one-shot layers can't loop, and die after 12 s). On a part
	-- it's heard there (others hear his wind); parent nil: flat. A take
	-- that starts past 0 loops from its Start (its LoopRegion, once loaded).
	-- opts: gain (1), fadeIn (0.25), max (20 s: it stops itself).
	-- The handle: :set(gain, speedK) (louder / softer, higher / lower),
	-- .stop(fade) (it fades out and goes; also handle:stop(fade))
	---------------------------------------------------------------------
	function WK.loop(cueName, parent, opts)
		opts = type(opts) == "table" and opts or {}
		local cue = Config.Sounds and Config.Sounds[cueName]
		local h = { sounds = {} }
		local stopped = false
		function h.stop(a, b)
			local fade = type(a) == "number" and a or b
			if stopped then
				return
			end
			stopped = true
			fade = math.max(tonumber(fade) or 0.25, 0.01)
			for _, s in h.sounds do
				pcall(function()
					tween(s.sound, fade, { Volume = 0 }, Enum.EasingStyle.Sine, Enum.EasingDirection.Out)
				end)
				task.delay(fade + 0.05, function()
					pcall(s.sound.Destroy, s.sound)
				end)
			end
		end
		function h.set(a, b, c)
			local gain, speedK
			if type(a) == "table" then
				gain, speedK = b, c
			else
				gain, speedK = a, b
			end
			if stopped then
				return
			end
			for _, s in h.sounds do
				if tonumber(gain) then
					s.sound.Volume = math.clamp(s.vol * tonumber(gain), 0, 8)
				end
				if tonumber(speedK) then
					s.sound.PlaybackSpeed = math.max(s.speed * tonumber(speedK), 0.05)
				end
			end
		end
		if type(cue) ~= "table" then
			stopped = true
			return h
		end
		local layers = cue.Id ~= nil and { cue } or cue
		local group = SoundService:FindFirstChild("QuirkSFX")
		local gain = tonumber(opts.gain) or 1
		for i, layer in ipairs(layers) do
			if i > 3 then
				break
			end
			local take = layer.Id
			if type(take) == "table" then
				take = take[rng:NextInteger(1, math.max(#take, 1))]
			end
			local id = type(take) == "table" and take.Id or take
			local start = type(take) == "table" and take.Start or layer.Start
			if type(id) == "string" and id ~= "" then
				local s = Instance.new("Sound")
				s.Name = "InasaWindLoop"
				s.SoundId = id
				s.Looped = true
				local vol = math.clamp((tonumber(layer.Volume) or 0.6) * gain, 0, 8)
				local speed = type(layer.Speed) == "table" and ((layer.Speed[1] or 1) + (layer.Speed[2] or layer.Speed[1] or 1)) / 2 or tonumber(layer.Speed) or 1
				s.PlaybackSpeed = math.max(speed, 0.05)
				s.RollOffMode = Enum.RollOffMode.InverseTapered
				s.RollOffMinDistance = layer.Near or 14
				s.RollOffMaxDistance = cue.Range or 400
				if group then
					s.SoundGroup = group
				end
				if start and start > 0 then
					s.TimePosition = start
					-- (a looped Sound restarts from 0: loop from the take's Start once it has loaded)
					local function region()
						pcall(function()
							if s.TimeLength > start + 0.5 then
								s.PlaybackRegionsEnabled = true
								s.LoopRegion = NumberRange.new(start, s.TimeLength)
							end
						end)
					end
					local okL, loaded = pcall(function()
						return s.IsLoaded
					end)
					if okL and loaded then
						region()
					else
						pcall(function()
							s.Loaded:Once(region)
						end)
					end
				end
				s.Volume = 0
				s.Parent = (typeof(parent) == "Instance" and parent.Parent) and parent or SoundService
				pcall(function()
					s:Play()
				end)
				tween(s, math.max(tonumber(opts.fadeIn) or 0.25, 0.01), { Volume = vol }, Enum.EasingStyle.Sine, Enum.EasingDirection.InOut)
				table.insert(h.sounds, { sound = s, vol = vol, speed = speed })
			end
		end
		task.delay(math.clamp(tonumber(opts.max) or 20, 0.5, 60), function()
			h.stop(0.4)
		end)
		return h
	end

	---------------------------------------------------------------------
	-- HIS ALWAYS-ON WIND (Config.Inasa.Aura): every screen draws it on every
	-- Inasa (VFX.IN's scan: players and dummies) within Cull of its camera.
	-- Standing: faint streaks circling his feet, dust curling up at them, a
	-- curl rising past his shoulders now and then, the cape stirring (the
	-- cape driver's breeze). Running: streaks peeling off his shoulders, dust
	-- kicked up behind him, curls off the cape's hem at speed. In the ult
	-- (Aura.UltOn): two rings of bands round him with the passion shade, red
	-- embers drifting up, the cape held lifted. Off at once when he dies or
	-- is someone else; gone with a body that's gone. WK.aura forces a mode
	-- (or adds the charge spiral); WK.hold keeps it off (a cutscene's)
	---------------------------------------------------------------------
	local function auraVisible(st, on)
		if st.shown == on then
			return
		end
		st.shown = on
		-- ((round 99 review) shown again, nothing's forced back on: the
		-- next step puts on what this moment wants - it was turning the foot
		-- streaks on while he ran and the ult's rings on for good long after
		-- the ult, once he'd been far from this camera or held)
		st.q = -1
		for _, b in st.loops do
			b.Enabled = false
		end
		if st.dust then
			st.dust.Rate = 0
		end
		for _, w in st.wake or {} do
			w[3].Enabled = false
		end
		if st.ult then
			st.ult.embers.Rate = 0
			st.ult.on = false
			for _, b in st.ult.bands do
				WK.fadeBand(b, 0)
			end
		end
		if not on then
			for _, s in st.curls do
				s.on = false
				s.beam.Enabled = false
			end
		end
	end
	function WK.drive(char)
		if WK.auras[char] then
			return WK.auras[char]
		end
		if not (IN.isInasa and IN.isInasa(char)) then
			return nil
		end
		local root = char:FindFirstChild("HumanoidRootPart")
		local hum = char:FindFirstChildOfClass("Humanoid")
		if not root or (hum and hum.Health <= 0) then
			return nil
		end
		local torso = char:FindFirstChild("Torso") or char:FindFirstChild("UpperTorso")
		local LP = AU.Loops or {}
		local st = { char = char, root = root, torso = torso, spin = rand(0, TAU), shown = true, conns = {}, wake = {}, curls = {}, loops = {}, nextCurl = WK.now() + rand(0.4, 1.2), nextHem = 0, wakeT = 0, q = -1, ultSpin = 0 }
		local holder = WK.holder(CFrame.new(root.CFrame.Position), "Aura")
		st.holder = holder
		-- the faint streaks circling his feet (flat; the holder turns them)
		local rad = LP.Radius or 2.5
		local span = math.rad(LP.Arc or 150)
		for i = 1, 2 do
			local r = rad * (i == 1 and 1 or 0.78)
			local a0 = (i - 1) * math.pi + rand(-0.3, 0.3)
			local att0 = WK.att(holder, arcCF(Vector3.zero, X3, Z3, r, a0))
			local att1 = WK.att(holder, arcCF(Vector3.zero, X3, Z3, r, a0 + span))
			local b = WK.beam(att0, att1, PAL.AIR, 0.04, LP.Width or 0.3, holder, { segments = 12 })
			local k = bend(span, r)
			b.CurveSize0, b.CurveSize1 = k, k
			b.Transparency = NS({ NK(0, 1), NK(0.5, LP.Transparency or 0.7), NK(1, LP.Transparency or 0.7) })
			st.loops[i] = b
		end
		-- the dust curling up at his feet (kicked up behind him running)
		holder.Size = Vector3.new(2.6, 0.3, 2.6)
		local dust = Instance.new("ParticleEmitter")
		dust.Name = "InasaWind"
		dust.Texture = TEX.smoke
		dust.Color = CS(PAL.DUST, PAL.DUST_DARK)
		dust.Transparency = NS({ NK(0, 1), NK(0.2, 0.62), NK(1, 1) })
		dust.Size = NS({ NK(0, 1), NK(1, 3) })
		dust.Lifetime = NumberRange.new(0.9, 1.5)
		dust.Speed = NumberRange.new(0.6, 2)
		dust.SpreadAngle = Vector2.new(60, 60)
		dust.Acceleration = Vector3.new(0, 1.2, 0)
		dust.Drag = 1
		dust.LightInfluence = 0.7
		dust.Rotation = NumberRange.new(0, 360)
		dust.RotSpeed = NumberRange.new(-120, 120)
		dust.EmissionDirection = Enum.NormalId.Top
		dust.Rate = 0
		dust.Parent = holder
		st.dust = dust
		-- the streaks peeling off his shoulders (two trails, in his torso)
		if torso then
			local WP = AU.Wake or {}
			for _, side in { 1, -1 } do
				local a0 = Instance.new("Attachment")
				a0.Name = "InasaWake"
				a0.CFrame = CFrame.new(side * 0.85, 0.95, 0.3)
				a0.Parent = torso
				local a1 = Instance.new("Attachment")
				a1.Name = "InasaWake"
				a1.CFrame = CFrame.new(side * 0.85, 0.95 - (WP.Width or 0.45), 0.3)
				a1.Parent = torso
				local tr = Instance.new("Trail")
				tr.Name = "InasaWake"
				tr.Attachment0, tr.Attachment1 = a0, a1
				tr.Lifetime = WP.Life or 0.24
				tr.Color = CS(PAL.AIR)
				tr.Transparency = NS({ NK(0, WP.Transparency or 0.5), NK(1, 1) })
				tr.WidthScale = NS({ NK(0, 1), NK(1, 0.1) })
				tr.LightEmission = 0.1
				tr.LightInfluence = 0.3
				tr.FaceCamera = true
				tr.MinLength = 0.05
				tr.Enabled = false
				tr.Parent = torso
				table.insert(st.wake, { a0, a1, tr })
			end
		end
		st.curls = { curlSlot(holder), curlSlot(holder), curlSlot(holder) }
		if hum then
			table.insert(st.conns, hum.Died:Connect(function()
				WK.undrive(char)
			end))
		end
		table.insert(st.conns, char:GetAttributeChangedSignal("Quirk"):Connect(function()
			if not IN.isInasa(char) then
				WK.undrive(char)
			end
		end))
		WK.auras[char] = st
		return st
	end
	-- the ult's rings and embers (made the first time he's in it)
	local function ultMake(st)
		local U = AU.Ult or {}
		local u = { holder = WK.holder(st.root.CFrame, "AuraUlt"), bands = {}, lay = {} }
		u.holder.Parent = st.holder
		for ri, hgt in U.Heights or { -0.7, 1.5 } do
			for j = 1, math.clamp(U.Bands or 3, 1, 3) do
				local b = WK.band(u.holder, { color = PAL.AIR, shade = PAL.PASSION })
				b.shadeK = 0.9
				local a0 = (j - 1) / (U.Bands or 3) * TAU + ri * 0.7
				WK.layBand(b, Vector3.new(0, hgt, 0), X3, Z3, (U.Radius or 3.5) * (ri == 1 and 1.08 or 0.94), a0, a0 + TAU / (U.Bands or 3) * 0.6, 0.55, 0)
				table.insert(u.bands, b)
			end
		end
		local em = Instance.new("ParticleEmitter")
		em.Name = "InasaWind"
		em.Texture = TEX.spark
		em.Color = CS(PAL.EMBER)
		em.Transparency = NS({ NK(0, 0.1), NK(0.7, 0.3), NK(1, 1) })
		em.Size = NS({ NK(0, 0.35), NK(1, 0.05) })
		em.Lifetime = NumberRange.new(1, 1.6)
		em.Speed = NumberRange.new(2, 4)
		em.SpreadAngle = Vector2.new(35, 35)
		em.Acceleration = Vector3.new(0, 1.5, 0)
		em.Drag = 0.6
		em.LightEmission = 0.6
		em.LightInfluence = 0.2
		em.EmissionDirection = Enum.NormalId.Top
		em.Rate = 0
		em.Parent = u.holder
		u.holder.Size = Vector3.new(4, 4, 4)
		u.embers = em
		st.ult = u
		return u
	end
	function WK.undrive(char)
		local st = WK.auras[char]
		if not st then
			return
		end
		WK.auras[char] = nil
		for _, c in st.conns do
			pcall(function()
				c:Disconnect()
			end)
		end
		for _, w in st.wake do
			for _, x in w do
				pcall(x.Destroy, x)
			end
		end
		pcall(st.holder.Destroy, st.holder)
		IN.breeze[char] = nil
		IN.raise[char] = nil
	end
	local THROWN = { Physics = true, FallingDown = true, Ragdoll = true, PlatformStanding = true }
	-- is this body the one this machine plays? (only its own Humanoid's state is to be trusted)
	function WK.isMine(char)
		local lp = Players.LocalPlayer
		return lp ~= nil and lp.Character == char
	end
	-- (round 99 review) a body this screen doesn't show: hidden here (a
	-- warp's or a kidnap's LocalTransparencyModifier; his own body with the
	-- camera in his head - first person, the scope) or made invisible for
	-- everyone. Its wind isn't drawn round nothing - and the wake's trails
	-- in his torso would stream out of the lens in first person
	function WK.hidden(part)
		if typeof(part) ~= "Instance" or not part:IsA("BasePart") then
			return false
		end
		local ok, ltm, tr = pcall(function()
			return part.LocalTransparencyModifier, part.Transparency
		end)
		return ok and ((tonumber(ltm) or 0) > 0.5 or (tonumber(tr) or 0) > 0.95)
	end
	-- (round 99 review) a body-bound effect's way out (the arm's coils, the
	-- charge spiral): he's gone or dead, or - if he was Inasa when it
	-- started - someone else now. It goes with him instead of running its
	-- time out round a corpse or another hero
	function WK.over(char, wasInasa)
		if typeof(char) ~= "Instance" or not char.Parent then
			return true
		end
		local hum = char:FindFirstChildOfClass("Humanoid")
		if hum and hum.Health <= 0 then
			return true
		end
		return wasInasa == true and not IN.isInasa(char)
	end
	-- one frame of his wind (near this camera)
	function WK.auraStep(st, dt, now, camPos)
		local char, root = st.char, st.root
		local pos = root.CFrame.Position
		local dist = (pos - camPos).Magnitude
		local far = dist > (WK.low() and (AU.LowCull or 80) or (AU.Cull or 160))
		if far or WK.isHeld(char, now) or WK.hidden(st.torso) then
			auraVisible(st, false)
			IN.breeze[char], IN.raise[char] = nil, nil
			return
		end
		auraVisible(st, true)
		local okV, v = pcall(function()
			return root.AssemblyLinearVelocity
		end)
		if not okV or typeof(v) ~= "Vector3" or v ~= v or v.Magnitude > 1e4 then
			v = Vector3.zero
		end
		local speed = Vector3.new(v.X, 0, v.Z).Magnitude
		local thrown = (char:GetAttribute("Ragdolled") or char:GetAttribute("Stunned") or char:GetAttribute("Grabbed")) and true or false
		if not thrown and WK.isMine(char) then
			local hum = char:FindFirstChildOfClass("Humanoid")
			local ok, state = pcall(function()
				return hum and hum:GetState()
			end)
			thrown = ok and typeof(state) == "EnumItem" and THROWN[state.Name] == true
		end
		local forced = WK.forced[char]
		if forced and now > forced.untilAt then
			WK.forced[char] = nil
			forced = nil
		end
		local mode = forced and forced.mode
		local run = thrown and 0 or math.clamp((speed - (AU.RunFrom or 6)) / math.max((AU.FullAt or 24) - (AU.RunFrom or 6), 1), 0, 1)
		if mode == "idle" then
			run = 0
		elseif mode == "run" then
			run = math.max(run, 1)
		end
		local ult = (mode == "ult") or (mode == nil and AU.UltOn ~= false and char:GetAttribute("UltActive") == true)
		local low = WK.low() and 0.5 or 1
		local scale = st.torso and st.torso.Size.Y / 2 or 1
		local foot = pos - UP * 3 * scale
		st.spin += (AU.Loops and AU.Loops.Spin or 0.3) * TAU * dt
		st.holder.CFrame = CFrame.new(foot + UP * 0.15) * CFrame.Angles(0, -st.spin, 0)
		-- the foot streaks: there standing, gone running
		local q = math.floor((1 - run) * 12 + 0.5)
		if q ~= st.q then
			st.q = q
			local tr = 1 - (1 - (AU.Loops and AU.Loops.Transparency or 0.7)) * q / 12
			for _, b in st.loops do
				b.Transparency = NS({ NK(0, 1), NK(0.5, tr), NK(1, tr) })
				b.Enabled = q > 0
			end
		end
		-- dust: curling up standing, kicked up behind running (on the street only)
		if now >= (st.groundAt or 0) then
			st.groundAt = now + 0.3
			local hit = groundRay(pos, 3 * scale + 4.5)
			st.grounded = hit ~= nil
		end
		st.dust.Rate = st.grounded and ((AU.Dust or 0.5) * (1 - run) + (AU.RunDust or 8) * run) * low or 0
		-- the wake off his shoulders: drawn On, then a gap - streaks, not a ribbon
		-- ((round 99 review) and none with the camera right on him: a Trail
		-- doesn't thin near the lens the way the kit's beams do)
		local WP = AU.Wake or {}
		local waking = run > 0.15 and not thrown and dist > ((KC.Near or {})[2] or 6)
		st.wakeT += dt
		local cyc = (WP.On or 0.16) + (WP.Off or 0.09)
		local on = waking and (st.wakeT % cyc) < (WP.On or 0.16)
		for _, w in st.wake do
			if w[3].Enabled ~= on then
				w[3].Enabled = on
			end
		end
		-- curls: past his shoulders standing, off the cape's hem at speed
		local cam = WK.cam()
		if now >= st.nextCurl and run < 0.3 and not thrown then
			local cr = AU.Curl or { 1.2, 1.8 }
			st.nextCurl = now + rand(cr[1], cr[2]) * (ult and 0.5 or 1)
			local s = st.curls[1].on and st.curls[2] or st.curls[1]
			local side = rng:NextNumber() < 0.5 and 1 or -1
			local up = root.CFrame.UpVector
			armCurl(s, pos + root.CFrame.RightVector * side * 1.6 * scale + up * 0.6 * scale, up + root.CFrame.RightVector * side * 0.3, { size = 1.3, drift = 3, life = 0.55, spin = 240 * side, transparency = 0.25 })
		end
		if speed > (AU.HemFrom or 20) and now >= st.nextHem and not thrown then
			st.nextHem = now + (AU.HemCurl or 0.4)
			local gear = char:FindFirstChild("QuirkGear")
			local cos = gear and gear:FindFirstChild("Cosmetics")
			local cape = cos and cos:FindFirstChild("InasaCape")
			local hemPos = pos - root.CFrame.LookVector * 1.2 * scale - UP * 1.5 * scale
			if cape then
				local last
				for i = 1, 8 do
					local seg = cape:FindFirstChild("InasaCapeSeg" .. i)
					if not seg then
						break
					end
					last = seg
				end
				if last then
					hemPos = (last.CFrame * CFrame.new(0, -last.Size.Y / 2, 0)).Position
				end
			end
			armCurl(st.curls[3], hemPos, -v.Unit + UP * 0.3, { size = 1.6, drift = 3.5, life = 0.4 })
		end
		local hcf = st.holder.CFrame
		for _, s in st.curls do
			stepCurl(s, now, cam, hcf)
		end
		-- the cape: stirring, harder in the ult and held up in it
		local B = AU.Breeze or {}
		local U = AU.Ult or {}
		IN.breeze[char] = (B.Idle or 0.6) * (1 - run) + (B.Run or 1) * run + (ult and (U.Breeze or 1.6) or 0)
		IN.raise[char] = ult and (U.Lift or 28) or nil
		-- the ult's rings and embers
		if ult and not st.ult then
			ultMake(st)
		end
		if st.ult then
			local u = st.ult
			if ult then
				st.ultSpin += (U.Spin or 0.6) * TAU * dt
				u.holder.CFrame = CFrame.new(pos) * CFrame.Angles(0, -st.ultSpin, 0)
				local o = (1 - (U.Transparency or 0.5)) * WK.nearK(pos, camPos)
				for _, b in u.bands do
					WK.fadeBand(b, o)
				end
				u.embers.Rate = (U.Embers or 3.3) * low
			elseif u.on then
				for _, b in u.bands do
					WK.fadeBand(b, 0)
				end
				u.embers.Rate = 0
			end
			u.on = ult
		end
	end
	-- WK.aura(char, mode, dur) -> stop(): his always-on wind made to show
	-- `mode` for dur seconds (nil: until stopped): "idle" / "run" (that
	-- look, whatever his speed), "ult" (the ult's rings and embers, in or
	-- out of it), "off" (nothing: WK.hold), "charge" (on top of it: a spiral
	-- of streaks rising round him, the cape lifting - a big move's windup).
	-- nil / "auto" lets it follow him again
	function WK.aura(char, mode, dur)
		if typeof(char) ~= "Instance" then
			return function() end
		end
