			VFX.Motion(char, "InasaUpdraftLand")
		end
		task.spawn(function()
			if root then
				IS.at(char, from, IS.mark("MoveInasaUpdraftLand", "Hit"))
				if WK.over(char, was) then
					return
				end
			end
			IS.beat("UpdraftLand", char)
			-- the street whirled out from under him (LandRadius: where it hits),
			-- a ring of curls spreading out along it
			local R = (sl.LandRadius or 10) * (L.Whirl or 0.8)
			WK.ground(pos, R, { loops = 3, spin = 1.8, life = 0.7 })
			local nc = WK.low() and 3 or 6
			for i = 1, nc do
				local a = i / nc * math.pi * 2
				local out = Vector3.new(math.cos(a), 0, math.sin(a))
				-- ((round 99 review) born clear of his legs: from 1.5 studs out
				-- the ring's commas sat over his boots and coat from his camera)
				WK.curl(pos + out * (L.CurlFrom or 3) + UP * 0.6, out + UP * 0.2, { size = L.Curl or 2.4, drift = R * 0.6, life = 0.45 })
			end
			local look = root and IN.flat(root.CFrame.LookVector, root) or Vector3.new(0, 0, -1)
			for s = -1, 1, 2 do
				WK.debris(pos + UP * 0.6, (look * s) * 18 + UP * 9, { n = WK.low() and 2 or 4, kinds = { "grit", "leaf", "grit" }, spread = 120, life = 0.9 })
			end
			if root then
				IN.gust(char, 0.8, 0.5, L.Lift or 70)
			end
			VFX.PlaySound("InasaUpdraftLand", pos, 1)
			VFX.ShakeAt(pos, 1.4, 70, 0.3)
		end)
	end

	---------------------------------------------------------------------
	-- THE SKY-HIGH SEND-OFF (Config.Finishers.Styles.Whirlwind; FX.Whirlwind
	-- in the finisher block calls this, `time` before the server's launch):
	-- the wrap (his crouch; a whirl of wind round them - they're anchored:
	-- it's only a look - and the wind coiling round his glove), then 0.3 s
	-- before the launch his uppercut clip; on its Hit (= the launch) a
	-- column of wind erupts under them up into the sky, the street rings out,
	-- paper and leaves thrown up after them; a twinkle where they went
	-- (Effects.Finisher's impact frame, flash, sound and shake are the
	-- shared ones: not stacked)
	---------------------------------------------------------------------
	POSES.InasaSendoff = POSES.InasaWall
	MOTIONS.InasaSendoff = MOTIONS.InasaFinish
	function IN.finisher(char, target, troot, d, time)
		local F = ST.Sendoff or {}
		time = math.clamp(tonumber(time) or 1.2, 0.35, 5)
		VFX.Pose(char, "InasaSendoff", math.max(time - 0.3, 0.2))
		local from = IS.clock(char)
		local was = IN.isInasa(char)
		IN.gust(char, 0.8, time + 0.6)
		local g = IN.ground(troot.Position)
		IS.beat("SendoffWrap", char)
		local Wr = F.Wrap or {}
		local wrap = WK.vortex(g, { height = Wr.Height or 8, baseR = Wr.Base or 2.2, topR = Wr.Top or 3.6, rings = 7, bands = 2, spin = Wr.Spin or 2.4, dust = 14,
			debris = 4, life = time + 0.6, grow = 0.25, sound = "InasaWindWhirl", name = "InasaSendoffWrap" })
		if wrap then
			wrap:carry(troot, { radius = 2.4, spin = 3 })
		end
		local coil = WK.armWind(char, "Left", { dur = time + 0.2, strands = 2 })
		VFX.PlaySound("InasaWhirlSpin", troot.Position, 1)
		local function unwind()
			if wrap then
				wrap:stop(0.4, "unwind")
			end
			if coil then
				coil:stop(0.15)
			end
		end
		task.spawn(function()
			IS.at(char, from, math.max(time - 0.3, 0))
			if IS.over(char, was) or not troot.Parent then
				unwind()
				return
			end
			VFX.Motion(char, "InasaSendoff")
			local from2 = IS.clock(char)
			VFX.SpeechBubble(char, "SKY-HIGH!!", 1)
			local Ti = F.Tight or {}
			if wrap then
				wrap:set({ height = Ti.Height or 14, baseR = Ti.Base or 1.6, topR = Ti.Top or 3, spin = Ti.Spin or 4 })
			end
			IS.at(char, from2, IS.mark("MoveInasaSendoff", "Hit"))
			if IS.over(char, was) then
				unwind()
				return
			end
			IS.beat("SendoffLaunch", char)
			if coil then
				coil:release(UP)
			end
			if wrap then
				wrap:stop(0.3, "burst")
			end
			local Co = F.Column or {}
			local col = WK.vortex(g, { height = Co.Height or 40, baseR = Co.Base or 2, topR = Co.Top or 5.5, rings = 10, bands = 2, spin = Co.Spin or 5, dust = 30,
				debris = 6, grow = 0.14, life = (Co.Life or 1.1) + 0.5, name = "InasaSendoffColumn" })
			if col then
				task.delay(Co.Life or 1.1, function()
					col:stop(0.45, "burst")
				end)
			end
			WK.streaks(WK.look(g + UP, UP), { n = 10, length = 34, spread = 2.4, width = 0.45, speed = 175, axis = "side" })
			WK.burst(g + UP * 0.6, UP, { radius = F.Burst or 7, streaks = 12, curls = 6, ground = false })
			WK.ground(g, F.Street or 6, { loops = 3, cracks = true, life = 0.8 })
			WK.debris(g + UP, UP * 40, { n = 8, kinds = { "paper", "leaf", "grit", "leaf" }, spread = 60, life = 2.2 })
			VFX.PlaySound("InasaSendoff", g, 1)
			-- a twinkle up where they went
			task.delay(F.Twinkle or 1.2, function()
				if troot.Parent then
					VFX.HitStar(troot.Position + UP * 20, 18, Color3.new(1, 1, 1))
				end
			end)
		end)
	end

	---------------------------------------------------------------------
	-- HIS KO (the KO finisher's pose and burst - the KO block's BURST hands
	-- his to this): the deep attack bow, arms flung out (PoseKO_Whirlwind),
	-- the cape lifted up over his back by his own wind; round the body a
	-- whirl of wind bursting, debris thrown on with it, the street whirled
	---------------------------------------------------------------------
	POSES.KO_Whirlwind = { Waist = { -70, 0, 0 }, Neck = { -14, 0, 0 }, RightArm = { 0, 0, 88 }, LeftArm = { 0, 0, 88 } }
	function IN.koBurst(pos, dir, _target, _data, char)
		pos = WK.v3(pos)
		if not pos then
			return
		end
		local KO = ST.KO or {}
		dir = WK.dir(dir, Vector3.new(0, 0, -1))
		IS.beat("KOBurst", char)
		WK.burst(pos, dir, { radius = KO.Burst or 12, streaks = 12, curls = 8, haze = true })
		local g = IS.street(pos, 12) or pos
		local vx = WK.vortex(g, { height = 14, baseR = 2, topR = 7, rings = 7, bands = 2, spin = 3, life = 1.2, grow = 0.12, dust = 20, debris = 6, name = "InasaKOWhirl" })
		if vx then
			task.delay(0.55, function()
				vx:stop(0.4, "burst")
			end)
		end
		WK.debris(pos, dir * 40 + UP * 14, { n = 8, life = 1.4 })
		VFX.PlaySound("InasaWindGale", pos, 1)
		if typeof(char) == "Instance" and IN.isInasa(char) then
			-- the bow: his cape lifted up over his back, the street whirled under him
			IN.gust(char, 1, KO.Hold or 1.3, KO.Lift or 150)
			local root = char:FindFirstChild("HumanoidRootPart")
			local feet = root and IS.street(root.Position, 6)
			if feet then
				WK.ground(feet, 5, { loops = 2, life = 0.9, spin = 1.4 })
			end
		end
	end

	-- (stale state: bodies gone, claims run out - every 2 s)
	task.spawn(function()
		while true do
			task.wait(2)
			local now = WK.now()
			for char, c in IS.cannons do
				if not char.Parent or now - c.t0 > 3 then
					IS.cannons[char] = nil
				end
			end
			for char, at in IS.served do
				if now - at > 3 then
					IS.served[char] = nil
				end
			end
			for char, run in IS.runs do
				if not char.Parent then
					pcall(run.stop)
					IS.runs[char] = nil
				end
			end
			for char, st in IS.claims do
				local live = false
				for _, c in st.list do
					if now <= c.untilAt then
						live = true
					end
				end
				if not live or not char.Parent then
					IS.unclaim(char)
				end
			end
		end
	end)
end)()

---------------------------------------------------------------------------
-- (round 99) INASA_ULT: PASSION STORM, HIS LOOK IN THE ULT and the SKYBREAKER
-- CYCLONE, remade the round-85 way (r99 inasa_research 7.8-7.10): his own
-- clips (anim/moves_inasa_u.py) with every effect waiting on their keys (the
-- pose clock: a slow motion holds them with the clip - never before the
-- beat), drawn with the WIND KIT (VFX.WindKit: matte crescent bands, streak
-- lines, curls, haze, dust, the street's own rubble in ordered lanes - the
-- anime's wind, never neon or glass).
--   PASSION STORM ((round 101) VFX.AK.FX.Whirlwind, on the awakening kit):
--     the breath in (the air sucked in off the street to his feet, his own
--     wind gone still, the music dead silent), the deep sudden BOW with his
--     arms flung wide (the wind gathering round him, his cape lifting off
--     his back into a tall triangle, an orchestra swelling - sucked out),
--     then UP: the whirlwind ERUPTS round him (a vortex of bands 30 up, the
--     street whirled flat and cracked, dust, leaves and paper thrown up in
--     it) on "I LOVE THIS!!!" - the music in on that beat. The camera, the
--     cut-in and the line are the kit's.
--   THE ULT'S LOOK: the kit's always-on wind in its ult mode (Config.Inasa.
--     Aura.Ult: the rings of bands with the passion shade, embers, the cape
--     held up), his wild face (the server's: white eyes, pin pupils, the
--     clenched square teeth), and wind coiled round the arm that throws each
--     move while he's in it (U.throw, from VFX.CosB.onPlay).
--   SKYBREAKER CYCLONE (Effects.SkyCyclone*): the call (the street's air
--     dragged in to him, arms flung up at the sky), the funnel torn up out of
--     the street to the clouds on every screen - the storm palette's ropes
--     twisting round its foot, smoke cloud banks turning over it, lightning -
--     the city's rubble climbing it in ordered rings, the bodies in its eye
--     wrapped in it; THE GATHER POINT (everything it carries pulled into one
--     knot high in it, the roar dropping out); "CYCLONE!!!": the knot bursts,
--     the funnel shoots up and tears apart, every piece flies the server's
--     path. His cutscene on the anime's camera (U.skyShots). The server's
--     maths and times are untouched: this is all looks.
-- Everything is cleaned up: on its own clock (the kit's stepper), on a
-- cancel, on his death or another hero. A low-end machine gets half.
-- (In a function of its own: the main chunk is at its local limit.)
---------------------------------------------------------------------------
;(function()
	local IN, WK = VFX.IN, VFX.WindKit
	if not (IN and WK) then
		return
	end
	local Q = Config.Quirks.Whirlwind or {}
	local C = Config.Inasa or {}
	local CU = C.Ult or {}
	local CY = C.Cyclone or {}
	local PAL = WK.PAL
	local TAU = math.pi * 2
	local LightingSvc = game:GetService("Lighting")
	local U = { runs = {} }
	IN.U = U

	---------------------------------------------------------------------
	-- his clips' keys and the pose clock
	---------------------------------------------------------------------
	-- each clip's named keys as moves_inasa_u.py writes them (IK.mark reads
	-- them off the clip in the place, so a moved key moves its effects)
	U.MARKS = {
		MoveInasaPassion = { Bow = 0.12, BowDeep = 0.33, Hit = 0.45, Pump = 1.1 },
		MoveInasaSkyCall = { Gather = 0.42, Hit = 0.9 },
		PoseInasaSkyHold = { Hold = 0.1, Knot = 2.88, HoldEnd = 3.2 },
		MoveInasaSkyHurl = { Hit = 0.1 },
	}
	function U.mark(clip, key)
		local IK = VFX.IidaKicks
		local v = IK and IK.mark and IK.mark(clip, key)
		if type(v) == "number" and v > 0 then
			return v
		end
		return (U.MARKS[clip] or {})[key] or 0
	end
	-- his pose clock (a hitstop's frozen time and the director's slow motion
	-- don't count: VFX's poseTime)
	function U.clock(char)
		return poseTime(char, os.clock())
	end
	-- wait until `due` seconds of his pose clock have gone by since `from`;
	-- false when there's no point any more (he's gone, dead - or someone else,
	-- if he was Inasa when it started: `was`)
	function U.at(char, from, due, was)
		while char.Parent do
			local left = due - (poseTime(char, os.clock()) - from)
			if left <= 0 then
				return not WK.over(char, was)
			end
			task.wait(math.min(left, 0.05))
		end
		return false
	end
	function U.mine(char)
		return char ~= nil and IN.me() == char
	end
	-- the R15 bodies' (and a place without the clips') procedural versions
	MOTIONS.InasaPassion = {
		{ pose = { Waist = { 8, 0, 0 }, Neck = { 8, 0, 0 }, RightArm = { -10, 0, 20 }, LeftArm = { -10, 0, 20 } }, t = 0.06 },
		{ pose = { Waist = { -76, 0, 0 }, Neck = { -20, 0, 0 }, RightArm = { 10, 0, 85 }, LeftArm = { 10, 0, 85 } }, t = 0.14, hold = 0.2 },
		{ pose = { RightArm = { 160, 0, 45 }, LeftArm = { 160, 0, 45 }, Waist = { 16, 0, 0 }, Neck = { 26, 0, 0 } }, t = 0.06, hold = 0.55 },
		{ pose = { LeftArm = { 88, 0, 0 }, RightArm = { -26, 0, 30 }, Waist = { -6, -20, 0 }, Neck = { -4, 14, 0 } }, t = 0.08, hold = 0.35 },
		recover = 0.35,
	}
	MOTIONS.InasaSkyCall = MOTIONS.InasaCycloneCall
	MOTIONS.InasaSkyHurl = MOTIONS.InasaCycloneHurl
	POSES.InasaSkyHold = POSES.InasaCycloneHold

	---------------------------------------------------------------------
	-- the camera: shots framed in his facing, every eye pulled in short of a
	-- wall (from his head - or, for a far eye, from what it looks at)
	---------------------------------------------------------------------
	function U.basis(root, d)
		return CFrame.lookAt(root.Position, root.Position + d)
	end
	-- an eye (basis space) pulled in toward `from` (basis space) short of a wall
	function U.clear(basis, eye, from)
		local we, wa = basis * eye, basis * from
		local hit = IN.ray(wa, we)
		if hit then
			local keep = math.max(hit.Distance - 1.2, 1.5)
			return basis:PointToObjectSpace(wa + (we - wa).Unit * keep)
		end
		return eye
	end
	function U.clearAll(basis, shots, head)
		for _, shot in shots do
			local from = shot.ClearFrom or head
			shot.From = { U.clear(basis, shot.From[1], from), shot.From[2] }
			shot.To = { U.clear(basis, shot.To[1], from), shot.To[2] }
			shot.ClearFrom = nil
		end
		return shots
	end

	---------------------------------------------------------------------
	-- PASSION STORM (the awakening) - (round 101, awaken_e) on the kit
	-- (VFX.AK.FX.Whirlwind): his clip is anim/moves_awaken_e.py's
	-- MoveAwakenWhirlwind - round 99's bow and roar, tightened to the kit's
	-- 1.6 s with the roar on the hit at 0.30 (the fist at the lens left out);
	-- the shots, the air sucked in to his feet, the music held silent and
	-- in on the hit, his line, the cut-in and the shout panel are the kit's.
	-- The press: his own wind goes still (the pressure drop). THE BOW (the
	-- clip's Bow): the orchestra swelling - sucked out right on the hit - the
	-- wind gathering round him, his cape lifting off his back, higher at its
	-- deepest (the Gather). ON THE HIT - up, chest out, arms flung wide at the
	-- sky - the whirlwind ERUPTS round him: a vortex of bands 30 up, the
	-- street whirled flat and cracked, the dust blown off his feet, leaves and
	-- paper thrown up in it; across his own screen the wind rushes. The storm
	-- lifts off him into the sky (Lift) and thins into the ult's own wind
	-- round him (Settle) - at once if the run's called off.
	---------------------------------------------------------------------
	-- the eruption (the clip's Hit): run = U.runs[char]
	function U.erupt(ctx, run)
		local P = CU.Passion or {}
		local S = P.Storm or {}
		local char, root = ctx.char, ctx.root
		local g = ctx.g or groundPoint(root.Position)
		IN.gust(char, 1, 1.2, P.CapeMax or 150)
		if run.charge then
			run.charge()
		end
		-- the whirlwind round him: up out of the street in a blink, opening out
		local vx = WK.vortex(g, {
			name = "InasaPassionStorm", height = S.Height or 28, baseR = S.BaseR or 3.2, topR = S.TopR or 9,
			rings = S.Rings or 10, bands = 3, spin = S.Spin or 2.4, rise = S.Rise or 0.9, grow = S.Grow or 0.2,
			sway = 1.2, debris = S.Debris or 10, dust = S.Dust or 34, curlEvery = 0.07, width = S.Width or 0.95,
			sound = "InasaWindWhirl", life = S.Life or 2.4, haze = false,
		})
		if vx then
			vx:set({ baseR = S.OpenBase or 4.6, topR = S.OpenTop or 13 })
			run.vx = vx
		end
		WK.ground(g, S.Ground or 12, { loops = 3, spin = 2.2, cracks = true, life = 1.1 })
		WK.burst(root.Position, UP, { radius = S.Burst or 8, streaks = 12, curls = 8, life = 0.45, ground = false })
		-- (the activation's shove - the server's blast, on the hit: a ring of
		-- dust blown flat off his feet)
		WK.dustRing(g, (S.Ground or 12) * 1.4)
		WK.debris(g + UP * 1.5, UP * 30, { n = 10, kinds = { "leaf", "paper", "grit", "leaf", "paper" }, spread = 70, scatter = 3, life = 1.7 })
		if ctx.mine and not ctx.screenOff then
			WK.screenWind("radial", 0.32)
			task.delay(0.3, function()
				WK.screenWind("wipe", 0.26, { dir = -1, strength = 0.7 })
			end)
		end
	end
	-- the storm thins into the ult's own wind (the kit's aura takes over)
	function U.settle(char, run, now)
		if run.vx then
			if now then
				run.vx:stop(0.3, "unwind")
			else
				run.vx:set({ baseR = 3.2, topR = 5, height = 9 })
				run.vx:stop(0.55)
			end
		end
		if run.charge then
			run.charge()
		end
		if run.release then
			run.release()
		end
		if U.runs[char] == run then
			U.runs[char] = nil
		end
	end
	VFX.AK.FX.Whirlwind = {
		press = function(ctx)
			local P = CU.Passion or {}
			local char = ctx.char
			local old = U.runs[char]
			if old then
				U.settle(char, old, true)
			end
			local run = { ctx = ctx, beats = {} }
			U.runs[char] = run
			-- his own wind goes still (the pressure drop) till his storm hands
			-- him over to the ult's
			run.release = WK.hold(char, P.Still or 1.4)
			task.spawn(function()
				-- THE BOW: the orchestra swelling (sucked out on the hit), the
				-- wind gathering round him, his cape lifting off his back
				local bow = VFX.AK.mark(ctx.clip, "Bow") or 0.08
				if VFX.AK.at(ctx, bow) then
					VFX.AK.note(ctx, "bow")
					VFX.PlaySound("InasaPassionBow", ctx.root.Position, 1)
					IN.gust(char, 0.35, ctx.gather - bow + 0.2, P.CapeMax or 150)
					run.charge = WK.charge(char, math.max(ctx.hit - bow, 0.05))
				end
				-- the storm lifts off him into the sky...
				if VFX.AK.at(ctx, P.Lift or 0.95) and run.vx then
					VFX.AK.note(ctx, "lift")
					local S = P.Storm or {}
					run.vx:set({ height = (S.Height or 28) * 2.5, baseR = 8, topR = (S.OpenTop or 13) * 2.6, spin = (S.Spin or 2.4) * 1.3 })
					run.vx:stop(P.LiftTime or 0.55)
					run.vx = nil
					WK.streaks(WK.look(ctx.root.Position + UP * 3, UP), { n = 6, length = 26, spread = 5, width = 0.4, speed = 120 })
					IN.gust(char, 1, 0.6, P.CapeMax or 150)
				end
				-- ...and thins into the ult's own wind round him (at once if the
				-- run's called off)
				U.settle(char, run, not VFX.AK.at(ctx, P.Settle or 1.35))
			end)
		end,
		gather = function(ctx)
			local P = CU.Passion or {}
			IN.gust(ctx.char, 1, ctx.hit - ctx.gather + 0.3, P.CapeMax or 150)
		end,
		hit = function(ctx)
			local run = U.runs[ctx.char]
			if run and run.ctx == ctx then
				VFX.AK.note(ctx, "storm")
				U.erupt(ctx, run)
			end
		end,
	}

	---------------------------------------------------------------------
	-- THE ULT'S SHARED TOUCH: wind coiled round the arm(s) that throw each
	-- move while he's in it, straightening off the hand on the move's own
	-- beat (the pose clock) - VFX.CosB.onPlay calls this for every effect
	---------------------------------------------------------------------
	function U.throw(char, effectId, data)
		local T = CU.Throws or {}
		local arms = T[effectId]
		if not arms or typeof(char) ~= "Instance" or char:GetAttribute("UltActive") ~= true or not IN.isInasa(char) then
			return
		end
		local root = char:FindFirstChild("HumanoidRootPart")
		if not root or (root.Position - IN.camPos()).Magnitude > (T.Cull or 160) then
			return
		end
		data = type(data) == "table" and data or {}
		local contact
		if arms == "M1" then
			local count = math.clamp(tonumber(data.Count) or 1, 1, 4)
			local finisher = data.Finisher == true
			local style = (Config.M1.Styles or {}).Whirlwind
			if type(style) == "table" then
				style = style.Ult or style.Base
			end
			local sets = VFX.M1Sets or {}
			local set = sets[style or "Brawler"] or sets.Brawler or {}
			local hit = set[finisher and 4 or math.min(count, 3)]
			local variant = finisher and VFX.M1Variants and VFX.M1Variants[data.Variant or ""]
			if variant then
				-- ((round 99 review) the set's own uppercut / downslam where it
				-- has one - VFX's m1Set keys them by the style: inasa_strikes'
				-- are thrown with the LEFT glove - else the hands' or feet's)
				hit = (style and variant[style]) or variant[(set[4] and set[4].Limb == "RightFoot") and "Feet" or "Hands"] or hit
			end
			local limbName = type(hit) == "table" and tostring(hit.Limb or "RightHand") or "RightHand"
			arms = { limbName:find("Left") and "Left" or "Right" }
			local CT = Config.M1.Contact or {}
			contact = (finisher and data.Variant and CT[data.Variant]) or CT[finisher and 4 or math.min(count, 3)] or 0.12
		else
			local key = (T.At or {})[effectId]
			contact = type(key) == "number" and key or tonumber(IN.spec(char, effectId)[key or "Startup"]) or 0.2
		end
		local from = U.clock(char)
		local d = IN.flat(data.Dir, root)
		local coils = {}
		for _, arm in type(arms) == "table" and arms or {} do
			local h = WK.armWind(char, arm, { strands = 2, spin = T.Spin or 3, radius = 1.15, width = 0.2, dur = contact + 0.5, vent = arm == "Left" })
			if h then
				table.insert(coils, h)
			end
		end
		if #coils == 0 then
			return
		end
		task.spawn(function()
			local ok = U.at(char, from, contact, true)
			for _, h in coils do
				if ok then
					h:release(d)
				else
					h:stop(0.1)
				end
			end
		end)
		return coils
	end

	---------------------------------------------------------------------
	-- THE ULT'S WIND UNDER HIM (every screen, every Inasa in his ult near
	-- its camera): on top of the kit's ult aura (its rings with the passion
	-- shade, the embers, the cape held up), the hover's flat whirl turning
	-- round his feet (the anime's shape G - Ep 59's hover, Ep 155's) - the
	-- piece that reads from 30-60 studs - and his glove venting now and
	-- then. Gone the moment he's out of the ult, dead, someone else, hidden
	-- on this screen, held off (a cutscene) or far from its camera
	---------------------------------------------------------------------
	U.ult = {}
	local X3, Z3 = Vector3.new(1, 0, 0), Vector3.new(0, 0, 1)
	function U.ultMake(char, root)
		local UW = CU.Whirl or {}
		local st = { char = char, root = root, holder = WK.holder(CFrame.new(root.Position), "UltWhirl"), loops = {}, spin = rand(0, TAU), nextVent = WK.now() + rand(0.5, 1.5) }
		local n = WK.n(UW.Loops or 3)
		for i = 1, n do
			local k = (i - 0.5) / n
			st.loops[i] = { band = WK.band(st.holder, { color = PAL.AIR, shade = PAL.PASSION }), r = (UW.Radius or 5) * (0.62 + 0.45 * k), a = i / n * TAU, arc = math.rad(150 + 50 * k), rate = 1.25 - 0.5 * k }
		end
		U.ult[char] = st
		return st
	end
	function U.ultDrop(char)
		local st = U.ult[char]
		if st then
			U.ult[char] = nil
			pcall(st.holder.Destroy, st.holder)
		end
	end
	function U.ultStep(dt)
		local UW = CU.Whirl or {}
		local AU = C.Aura or {}
		dt = math.clamp(tonumber(dt) or 1 / 60, 0, 0.1)
		local now = WK.now()
		local camPos = WK.cam().Position
		local cull = WK.low() and (AU.LowCull or 80) or (AU.Cull or 160)
		local want = {}
		for _, char in IN.bodies or {} do
			local root = typeof(char) == "Instance" and char.Parent and char:FindFirstChild("HumanoidRootPart")
			local hum = root and char:FindFirstChildOfClass("Humanoid")
			local torso = root and (char:FindFirstChild("Torso") or char:FindFirstChild("UpperTorso"))
			if root and IN.isInasa(char) and char:GetAttribute("UltActive") == true and (not hum or hum.Health > 0)
				and (root.Position - camPos).Magnitude <= cull and not WK.isHeld(char, now) and not WK.hidden(torso) then
				want[char] = true
				local st = U.ult[char] or U.ultMake(char, root)
				local scale = torso and torso.Size.Y / 2 or 1
				local foot = root.Position - UP * (3 * scale - 0.25)
				st.holder.CFrame = CFrame.new(foot)
				st.spin += (UW.Spin or 0.9) * TAU * dt
				local o = (1 - (UW.Transparency or 0.3)) * WK.nearK(foot, camPos)
				for _, L in st.loops do
					local a = L.a + st.spin * L.rate
					WK.layBand(L.band, Vector3.zero, X3, Z3, L.r * scale, a, a + L.arc, (UW.Width or 0.9) * scale, o)
				end
				-- his glove venting now and then
				if now >= st.nextVent then
					st.nextVent = now + rand((UW.Vent or { 1.8, 3 })[1], (UW.Vent or { 1.8, 3 })[2])
					WK.vent(char, { "Glove", "Knuckles" }, { n = 4, length = 1.6 })
				end
			end
		end
		for char in U.ult do
			if not want[char] then
				U.ultDrop(char)
			end
		end
	end
	pcall(function()
		RunService:BindToRenderStep("InasaUltWind", Enum.RenderPriority.Camera.Value + 5, U.ultStep)
	end)

	---------------------------------------------------------------------
	-- SKYBREAKER CYCLONE: his windup (every screen; his own: the cutscene)
	---------------------------------------------------------------------
	-- the far wide shot's eye: R studs off the funnel's foot along the
	-- clearest way out of it (a street, not a wall: cast from the funnel),
	-- low - the sides first (him and it in one frame), then the diagonals,
	-- then down the street; boxed in, up over the roofs
	function U.farEye(centre, d, R)
		local right = d:Cross(UP).Unit
		local tries = { right, -right, (right - d).Unit, (-right - d).Unit, (right + d).Unit, (-right + d).Unit, -d, d }
		local best, bestScore, bestDist = right, -math.huge, R
		local from = centre + UP * 6
		for i, dir in tries do
			local hit = IN.ray(from, from + dir * R)
			local dist = hit and hit.Distance or R
			local score = dist - (i > 2 and (i > 6 and 30 or 12) or 0)
			if score > bestScore then
				best, bestScore, bestDist = dir, score, dist
			end
		end
		local keep = math.clamp(bestDist - 6, 30, R)
		local up = keep < R * 0.6 and (R * 0.6 - keep) * 0.7 or 0
		return centre + best * keep + UP * (4 + up), best
	end
	-- the cutscene, from where he stands (the eye `ahead` studs down d), on
	-- the anime's camera (r99 inasa_research 2.5 / 7.10): worm's-eye over his
	-- shoulder as he sinks and gathers; his face from below as his arms go up
	-- (the hatching); the far wide, low, as the funnel tears up to the
	-- clouds; the crane over it looking down into its eye (the rubble
	-- climbing in rings); up from his feet - him straining, the spiral over
	-- him filling the sky; THE GATHER POINT - up over his shoulder at the
	-- knot, tight and held; the burst, pulling back as it all flies out.
	-- Every eye is pulled in short of a wall (the far one found clear)
	function U.skyShots(root, d, spec, ahead)
		local form, hold = spec.Form or 1.1, spec.EyeHold or 3.4
		local arms = (spec.Beats or {}).Arms or 0.9
		local S = CU.Sky or {}
		local basis = U.basis(root, d)
		local head = V(0, 1.6, 0)
		local eye = V(0, -3.2, -ahead)
		local burst = form + hold
		local b = { arms, arms + 0.3, form + 1.25, burst - 0.95, burst - 0.42, burst - 0.05, burst + 0.95 }
		for i = 2, #b do
			b[i] = math.max(b[i], b[i - 1] + 0.15)
		end
		local far, side = U.farEye(basis * eye, d, S.Far or 160)
		local farA = basis:PointToObjectSpace(far)
		local farB = basis:PointToObjectSpace(far + side * 14 + UP * 5)
		local knot = eye + V(0, S.KnotHeight or 66, 0)
		local shots = {
			{ T = b[1], From = { V(7.5, -1.2, 8.5), V(-1.5, 5, -18) }, To = { V(6.6, -1.4, 7.4), V(-1.5, 9, -20) }, Fov = { 64, 58 } },
			-- ((round 99 review) his FACE: his head is thrown back on the arms'
			-- Hit, so the old eye down at his knees only saw his chin and the
			-- fur - this one is in front at his face's height, under its tilt)
			-- (close: the ult aura's rings round him - Config.Inasa.Aura.Ult,
			-- radius 3.9 - pass right by this lens and thin away there; any
			-- further out and they cross in front of his face)
			{ T = b[2] - b[1], Cut = true, From = { V(1.2, 1.1, -5), V(0, 1.3, 0.75) }, To = { V(1, 1, -4.2), V(0, 1.4, 0.75) }, Fov = { 46, 40 } },
			{ T = b[3] - b[2], Cut = true, From = { farA, eye + V(0, 60, 0) }, To = { farB, eye + V(0, 430, 0) }, Fov = { 60, 72 }, Style = Enum.EasingStyle.Quad, ClearFrom = eye + V(0, 6, 0) },
			-- ((round 99 review) THE OVERHEAD (Ep 59): straight down its throat
			-- from over the eye, sinking - the rings narrowing to the street,
			-- the rubble going round in its lanes under the lens. (The old crane
			-- 70-95 studs off its side framed mostly empty street, the funnel
			-- small in a corner)
			{ T = b[4] - b[3], Cut = true, Quiet = true, From = { eye + V(5, 175, 12), eye + V(0, 22, 0) }, To = { eye + V(3, 140, 7), eye + V(0, 26, 0) }, Fov = { 72, 64 }, ClearFrom = eye + V(0, 22, 0) },
			{ T = b[5] - b[4], Cut = true, From = { V(3, -2.3, 8.5), V(0, 16, -ahead * 0.5) }, To = { V(2.7, -2.5, 7.6), V(0, 24, -ahead * 0.6) }, Fov = { 76, 68 } },
			{ T = b[6] - b[5], Cut = true, Quiet = true, From = { V(-3, 2.2, 8), knot }, To = { V(-2.8, 2.4, 7), knot }, Fov = { 38, 32 } },
			-- ((round 99 review) the burst opens ON the knot - it bursts at the
			-- lens, the anime's gather point - then sweeps down after the
			-- pieces; the old one looked under it as it went)
			{ T = b[7] - b[6], Cut = true, Quiet = true, From = { V(7, 4, 12), knot }, To = { V(11, 9, 27), V(0, 8, -1.6 * ahead) }, Fov = { 62, 84 } },
		}
		return U.clearAll(basis, shots, head)
	end
	IN.shots = U.skyShots
	-- (the bodies on this screen: the players' and the dummies)
	function U.fighters()
		local list = {}
		for _, plr in Players:GetPlayers() do
			if plr.Character then
				table.insert(list, plr.Character)
			end
		end
		local dummies = workspace:FindFirstChild("Dummies")
		for _, m in dummies and dummies:GetChildren() or {} do
			if m:IsA("Model") then
				table.insert(list, m)
			end
		end
		return list
	end
	-- leaves and grit crawling in along the street to him from a ring round him
	function U.inward(g, R, life)
		for i = 1, WK.low() and 2 or 4 do
			local a = i / 4 * TAU + 0.4
			local out = Vector3.new(math.cos(a), 0, math.sin(a))
			WK.debris(g + out * R + UP * 0.6, -out * R * 1.1 + UP * 2, { n = 4, kinds = { "leaf", "grit", "paper", "grit" }, spread = 30, life = life })
		end
	end
	-- the hold: PoseInasaSkyHold with its Hold..HoldEnd slowed down to fill
	-- `total` seconds from now (its Knot key lands on the knot), or the pose
	function U.hold(char, total)
		local clip = VFX.GetClip and VFX.GetClip("PoseInasaSkyHold")
		if clip and clip.holdAt and clip.holdEnd then
			local want = math.max(total - clip.holdAt, 0.2)
			if VFX.Clip(char, "PoseInasaSkyHold", { holdFor = math.max(want - (clip.holdEnd - clip.holdAt), 0), recover = 0.2 }) then
				return clip
			end
		end
		VFX.Pose(char, "InasaSkyHold", total)
		return nil
	end
	function Effects.SkyCyclone(char, data, isLocal)
		local root = charParts(char)
		if not root then
			return
		end
		data = type(data) == "table" and data or {}
		local spec = IN.spec(char, "SkyCyclone")
		local d = IN.flat(data.Dir, root)
		local pos = IN.point(data.Pos)
		local ahead = pos and (pos - root.Position):Dot(d) or (spec.Range or 70)
		ahead = math.clamp(ahead == ahead and ahead or 0, spec.MinAhead or 26, spec.Range or 70)
		local old = IN.runs[char]
		if old then
			old.stop(true)
		end
		local from = U.clock(char)
		local run = { t0 = os.clock(), from = from, mine = isLocal == true, did = {}, beats = {}, was = IN.isInasa(char) }
		IN.runs[char] = run
		local B = spec.Beats or {}
		local S = CU.Sky or {}
		local form, hold = spec.Form or 1.1, spec.EyeHold or 3.4
		local arms = U.mark("MoveInasaSkyCall", "Hit")
		local gather = U.mark("MoveInasaSkyCall", "Gather")
		local hurlLead = U.mark("MoveInasaSkyHurl", "Hit")
		local who = not run.mine and string.format((C.Titles and C.Titles.Who) or "%s: SKYBREAKER CYCLONE", IN.whoName(char)) or nil
		if isLocal then
			face(root, d)
			root.AssemblyLinearVelocity = Vector3.zero
			VFX.Cinematic(char, U.skyShots(root, d, spec, ahead), { Title = "SKYBREAKER CYCLONE", Color = Q.Ult and Q.Ult.Color, Own = true, Face = root.Position + d * ahead })
		end
		VFX.Motion(char, "InasaSkyCall")
		IN.gust(char, 0.5, arms, 95)
		run.charge = WK.charge(char, arms)
		IN.far("InasaSkyWind", root.Position, 1)
		local g = IN.ground(root.Position)
		local conn
		function run.stop(now)
			if run.done then
				return
			end
			run.done = true
			if conn then
				conn:Disconnect()
			end
			if IN.runs[char] == run then
				IN.runs[char] = nil
			end
			if run.charge then
				run.charge()
			end
			for _, c in run.coils or {} do
				c:stop(0.1)
			end
			if run.ult then
				run.ult()
			end
			if now and char.Parent then
				VFX.ReleasePose(char, 0.2)
			end
		end
		local nextSuck, nextStrain = 0.03, arms + 0.5
		conn = RunService.RenderStepped:Connect(function()
			if not root.Parent or not char.Parent or WK.over(char, run.was) then
				run.stop(true)
				return
			end
			local t = U.clock(char) - from
			-- (the server never sent its burst: it ends here)
			if t > form + hold + 2.5 then
				run.stop(true)
				return
			end
			-- the call: the street's air dragged in to him from all round
			if t < arms and t >= nextSuck then
				nextSuck = t + (WK.low() and 0.14 or 0.08)
				local a = rand(0, TAU)
				local out = Vector3.new(math.cos(a), 0, math.sin(a))
				local R = rand(14, S.SuckRadius or 30)
				local at = g + out * R + UP * rand(0.3, 1.4)
				WK.curl(at, -out + UP * 0.1, { size = 2.4, drift = R * 0.7, life = 0.45, spin = (rng:NextNumber() < 0.5 and 1 or -1) * 240 })
				WK.streaks(WK.look(at, -out), { n = 1, length = R * 0.45, width = 0.26, speed = R * 1.6 })
				run.beats.suck = run.beats.suck or t
			end
			if not run.did.call and t >= (B.Call or 0.2) then
				run.did.call = true
				run.beats.call = t
				VFX.Voice("InasaSkyCall", root)
				IN.title((C.Titles and C.Titles.Call) or "SKYBREAKER...", run.mine, form + 0.9, who)
				IN.far("InasaSkyRiser", root.Position, 1)
				if VFX.Hooks.DuckMusic and (IN.camPos() - root.Position).Magnitude < 1200 then
					VFX.Hooks.DuckMusic(spec.MusicDuck or 0.25, 0.4, form + hold + 1.5, 2)
				end
			end
			-- the gather: wind coiled round both his arms, the leaves and grit
			-- crawling in along the street
			if not run.did.gather and t >= gather then
				run.did.gather = true
				run.beats.gather = t
				run.coils = {}
				for _, arm in { "Left", "Right" } do
					local h = WK.armWind(char, arm, { strands = 3, spin = 2.6, radius = 1.2, width = 0.22, dur = arms - gather + 0.5 })
					if h then
						table.insert(run.coils, h)
					end
				end
				U.inward(g, 20, 0.6)
			end
			-- ARMS UP: the coils thrown up off his hands at the sky
			if not run.did.arms and t >= arms then
				run.did.arms = true
				run.beats.arms = t
				for _, c in run.coils or {} do
					c:release(UP)
				end
				run.coils = nil
				IN.gust(char, 1, form + hold - arms + 0.4, S.CapeMax or 120)
				WK.ground(g, 10, { loops = 3, spin = 2, life = 0.9 })
				WK.curl(root.Position + UP * 5, UP, { n = 6, spread = 3, size = 2.6, drift = 10, life = 0.5 })
				WK.streaks(WK.look(root.Position + UP * 4, UP), { n = 6, length = 30, spread = 3, width = 0.4, speed = 140 })
				VFX.PlaySound("InasaWindGale", root.Position, 1)
				run.ult = WK.aura(char, "ult", form + hold - arms + 0.4)
				if run.mine then
					WK.screenWind("hatch", 0.3, { strength = 0.9 })
				end
			end
			-- ...held up there (the hold's Knot key on the gather point)
			if not run.did.held and t >= arms + 0.1 then
				run.did.held = true
				U.hold(char, form + hold - hurlLead - t)
			end
			-- the strain: his wind venting off his back and ankles, the dust
			-- whirled round his feet
			if run.did.arms and t >= nextStrain and t < form + hold - 0.4 then
				nextStrain = t + (S.StrainEvery or 0.75)
				WK.vent(char, { "Back", "Ankles" }, { n = 6, length = 1.8 })
				WK.ground(g, 6, { loops = 2, spin = 2.6, life = 0.6 })
			end
			if not run.did.hurl and t >= form + hold - hurlLead then
				run.did.hurl = true
				run.beats.hurl = t
				VFX.Motion(char, "InasaSkyHurl")
				IN.gust(char, 1, 1.2, S.CapeMax or 120)
			end
		end)
	end

	---------------------------------------------------------------------
	-- THE CYCLONE ITSELF, on every screen (from the server's word)
	---------------------------------------------------------------------
	-- a piece of the city in it: it climbs to its ring and goes round in it -
	-- Lanes rings one over the other, the pieces in each evenly round it
	-- (canon: his currents carry things without them ever colliding)
	function IN.addPiece(st, part, h)
		local cap = WK.low() and (CY.LowPieces or 36) or (CY.MaxPieces or 90)
		if #st.pieces >= cap then
			part:Destroy()
			return nil
		end
		local S = CU.Sky or {}
		local lanes = S.Lanes or 6
		st.count = (st.count or 0) + 1
		local lane = (st.count - 1) % lanes + 1
		local slot = math.floor((st.count - 1) / lanes)
		local pc = {
			part = part, h = h or rand(0, 30), lane = lane, slot = slot,
			a = lane * 2.4 + slot * TAU / (S.PerLane or 12), out = 0.9,
			ceil = (S.LaneLow or 34) + (lane - 1) * (S.LaneGap or 22),
			rot = CFrame.Angles(rand(0, 6), rand(0, 6), rand(0, 6)),
			tumble = CFrame.Angles(rand(-0.12, 0.12), rand(-0.12, 0.12), rand(-0.12, 0.12)),
			climb = rand(0.85, 1.15) * (CY.Climb or 70),
		}
		table.insert(st.pieces, pc)
		return pc
	end
	function Effects.SkyCycloneGo(char, data)
		data = type(data) == "table" and data or {}
		local pos = IN.point(data.Pos)
		local d = IN.dir(data.Dir) or Vector3.new(0, 0, -1)
		if not pos then
			return
		end
		local old = IN.storm(char, pos)
		if old then
			old.stop(true)
		end
		local dist = (IN.camPos() - pos).Magnitude
		if dist > (CY.Range or 4000) then
			return
		end
		local spec = IN.spec(char, "SkyCyclone")
		local low = WK.low()
		local S = CU.Sky or {}
		local LO, HI = S.Low or {}, S.High or {}
		local form, hold = spec.Form or 1.1, spec.EyeHold or 3.4
		local model = Instance.new("Model")
		model.Name = "InasaCyclone"
		model.Parent = folder
		local st = {
			char = char, pos = pos, d = d, model = model, t0 = os.clock(), pieces = {}, clouds = {}, ropes = {},
			form = form, hold = hold, near = dist, knotAt = form + hold - (S.KnotLead or 0.45),
		}
		table.insert(IN.storms, st)
		-- (each kit piece hung in the storm's model: it all goes with it)
		local function adopt(x)
			local m = x and (x.model or x.holder)
			if m then
				m.Parent = model
			end
			return x
		end
		local lowH = LO.Height or 220
		local hiFrom, hiH = HI.From or 190, HI.Height or 710
		st.lowH = lowH
		-- THE FUNNEL: its foot torn up out of the street (the storm palette
		-- low down: the Final War's dusty ropes), then the upper funnel up
		-- out of it to the clouds, flaring out over the city
		st.low = adopt(WK.vortex(pos, {
			name = "InasaCycloneLow", height = lowH, baseR = CY.BaseRadius or 12, topR = LO.TopR or 46, rings = 10, bands = 3,
			storm = LO.Storm or 0.5, width = LO.Width or 2.4, maxWidth = 24, spin = LO.Spin or 1.1, sway = LO.Sway or 6,
			rise = LO.Rise or 0.32, debris = 0, dust = LO.Dust or 70, curlEvery = 0.05, grow = form * 0.55, haze = false,
			life = form + hold + 6,
		}))
		-- the axis and the radius at height h (the two funnels as one)
		function st.axis(h)
			if st.high and h > lowH * 0.85 then
				return st.high.axisAt((h - hiFrom) / hiH)
			end
			return st.low and st.low.axisAt(h / lowH) or pos + UP * h
		end
		function st.radius(h)
			if st.high and h > lowH then
				return st.high.radiusAt(math.clamp((h - hiFrom) / hiH, 0, 1))
			end
			return st.low and st.low.radiusAt(math.clamp(h / lowH, 0, 1)) or (CY.BaseRadius or 12)
		end
		-- the storm clouds it feeds, turning over it (smoke banks)
		local NS, NK = NumberSequence.new, NumberSequenceKeypoint.new
		local CS2 = CY.CloudSize or { 120, 60 }
		local nClouds = low and (CY.LowClouds or 8) or (CY.Clouds or 18)
		for i = 1, nClouds do
			local holder = WK.holder(CFrame.new(pos), "CycloneCloud")
			holder.Parent = model
			local em = Instance.new("ParticleEmitter")
			em.Name = "InasaWind"
			em.Texture = WK.TEX.smoke
			local shade = rand(0.3, 0.44)
			em.Color = ColorSequence.new(Color3.new(shade, shade, shade + 0.05), Color3.new(shade * 0.78, shade * 0.78, shade * 0.86))
			em.LightInfluence = 0.6
			em.Transparency = NS({ NK(0, 1), NK(0.18, 0.3), NK(0.78, 0.38), NK(1, 1) })
			em.Size = NS({ NK(0, math.min(CS2[2], 100)), NK(1, math.min(CS2[1], 100)) })
			em.Lifetime = NumberRange.new(5, 8)
			em.Speed = NumberRange.new(0, 3)
			em.Rotation = NumberRange.new(0, 360)
			em.RotSpeed = NumberRange.new(-6, 6)
			em.LockedToPart = true
			em.Rate = 0
			em.Parent = holder
			table.insert(st.clouds, { part = holder, em = em, a = i / nClouds * TAU + rand(-0.2, 0.2), r = (CY.CloudRadius or 260) * rand(0.7, 1.3), h = (CY.CloudHeight or 820) * rand(0.95, 1.06) })
		end
		-- street chunks torn up with it, leaves and paper
		for _ = 1, low and (CY.LowExtra or 10) or (CY.Extra or 30) do
			local pc = IN.addPiece(st, IN.chunk(st, pos), rand(-20, 10))
			if pc then
				pc.delay = rand(0, form)
			end
		end
		local leaves = (C.Wind or {}).Leaves or { Color3.fromRGB(116, 160, 70) }
		for _ = 1, low and (CY.LowLeaves or 14) or (CY.Leaves or 40) do
			local paper = rng:NextNumber() < 0.4
			local p = newPart(paper and Vector3.new(1.2, 0.05, 1.5) or Vector3.new(0.7, 0.06, 0.5), CFrame.new(pos), paper and PAL.PAPER or leaves[rng:NextInteger(1, #leaves)], Enum.Material.SmoothPlastic, nil, model)
			table.insert(st.pieces, { part = p, h = rand(0, 200), a = rand(0, TAU), out = rand(0.9, 1.4), rot = CFrame.Angles(rand(0, 6), rand(0, 6), rand(0, 6)), tumble = CFrame.Angles(0.3, 0.2, 0.25), climb = rand(1.2, 2) * (CY.Climb or 70), leaf = true })
		end
		-- the sky dims round it (the screens near enough to be under it)
		if dist < (CY.Near or 600) then
			local G = CY.Grade or {}
			local grade = Instance.new("ColorCorrectionEffect")
			grade.Name = "InasaCycloneGrade"
			grade.Parent = LightingSvc
			tween(grade, form, { Brightness = G.Brightness or -0.06, Contrast = G.Contrast or 0.14, Saturation = G.Saturation or -0.3, TintColor = G.Tint or Color3.fromRGB(214, 226, 236) })
			st.grade = grade
		end
		IN.far("InasaSkyRise", pos, 1)
		local top = lowH + hiH * 0.95
		-- lightning flickering through the cloud
		function st.bolt()
			if #st.clouds < 2 then
				return
			end
			local a, b = st.clouds[rng:NextInteger(1, #st.clouds)], st.clouds[rng:NextInteger(1, #st.clouds)]
			local axisTop = st.axis(top)
			local from = axisTop + Vector3.new(math.cos(a.a) * a.r, a.h - top - 10, math.sin(a.a) * a.r)
			local to = axisTop + Vector3.new(math.cos(b.a) * b.r * 0.4, b.h - top - rand(40, 120), math.sin(b.a) * b.r * 0.4)
			local last = from
			for i = 1, 6 do
				local nxt = from:Lerp(to, i / 6) + (i < 6 and rng:NextUnitVector() * rand(4, 12) or Vector3.zero)
				if (nxt - last).Magnitude > 0.1 then
					local seg = newPart(Vector3.new(1, 1, (nxt - last).Magnitude), CFrame.lookAt((last + nxt) / 2, nxt), Color3.fromRGB(226, 236, 255), Enum.Material.Neon, nil, model)
					WK.after(seg, 0.12)
				end
				last = nxt
			end
		end
		local parts, cfs = {}, {}
		local nextBolt, lastShake, nextRoar, nextHeld = 0.8, 0, form, form
		local conn
		function st.stop(now)
			if st.done then
				return
			end
			st.done = true
			if conn then
				conn:Disconnect()
			end
			local at = table.find(IN.storms, st)
			if at then
				table.remove(IN.storms, at)
			end
			for _, c in st.clouds do
				c.em.Rate = 0
			end
			if st.knotFx then
				-- (it may have run out and gone already)
				pcall(st.knotFx.stop, st.knotFx, 0.1)
			end
			if st.grade then
				local grade = st.grade
				st.grade = nil
				tween(grade, 1.2, { Brightness = 0, Contrast = 0, Saturation = 0, TintColor = Color3.new(1, 1, 1) })
				task.delay(1.3, function()
					if grade.Parent then
						grade:Destroy()
					end
				end)
			end
			if now then
				model:Destroy()
				return
			end
			-- (blown out or called off: it unwinds and fades, what's left in it drops)
			for _, vx in { st.low, st.high } do
				if not st.hurled then
					vx:stop(0.8, "unwind")
				end
			end
			for _, r in st.ropes do
				r:stop(0.5)
			end
			for _, pc in st.pieces do
				if not pc.thrown and pc.part.Parent then
					pc.thrown = true
					tween(pc.part, 0.9, { CFrame = pc.part.CFrame - UP * rand(20, 60), Transparency = 1 }, Enum.EasingStyle.Quad, Enum.EasingDirection.In)
				end
			end
			WK.after(model, 1.5)
		end
		conn = RunService.RenderStepped:Connect(function(dt)
			local t = os.clock() - st.t0
			if t > (CY.MaxTime or 14) or not model.Parent then
				st.stop(false)
				return
			end
			-- (never burst - the server's word lost: it dies away by itself)
			if not st.hurled and t > form + hold + 3 then
				st.stop(false)
				return
			end
			local grow = math.clamp(t / math.max(form, 0.1), 0, 1) ^ 0.7
			-- the upper funnel, up out of the lower one as it gets there
			if not st.high and t >= form * (HI.At or 0.35) then
				st.high = adopt(WK.vortex(pos + UP * hiFrom, {
					name = "InasaCycloneHigh", height = hiH, baseR = HI.BaseR or 40, topR = CY.TopRadius or 240, rings = 10, bands = HI.Bands or 2,
					width = HI.Width or 3, maxWidth = 60, spin = HI.Spin or 0.45, sway = CY.Sway or 40, rise = HI.Rise or 0.18,
					debris = 0, dust = false, curlEvery = 0.08, grow = form * 0.6, haze = false, life = form + hold + 6,
				}))
				if st.high then
					st.high:move(st.low and st.low.axisAt(hiFrom / lowH) or pos + UP * hiFrom)
				end
			end
			-- keep the upper funnel's foot on the lower one's sway
			if st.high and st.low and not st.hurled then
				st.high:move(st.low.axisAt(hiFrom / lowH))
			end
			-- the ropes: the Final War's storm twisters round its foot, rising with it
			-- ((round 99 review) wound round the outside of its skin - foot
			-- to RopeHeight, leaning round it - braided: strands about as
			-- wide as their twist (Config.Inasa.Ult.Sky.Rope), so they read
			-- as twisted ropes. 5-stud strands 1.3-2.6 out made two solid tan
			-- poles crossing through the funnel; thinner ones, springs)
			local RP = S.Rope or {}
			if #st.ropes == 0 and t >= form * 0.3 and not st.hurled then
				for i = 1, low and 1 or (S.Ropes or 2) do
					local r = adopt(WK.rope(pos + UP, pos + UP * 20, { r0 = RP.R0 or 2, r1 = RP.R1 or 4, pitch = RP.Pitch or 28, strands = 3, width = RP.Width or 3.8, spin = 1.3, storm = true, phase = i, life = form + hold + 3 }))
					if r then
						r.ang = i / (S.Ropes or 2) * TAU
						table.insert(st.ropes, r)
					end
				end
			end
			for _, r in st.ropes do
				r.ang += (S.RopeOrbit or 0.22) * TAU * dt
				local hgt = (S.RopeHeight or 150) * grow
				local ra, rb = (CY.BaseRadius or 12) * (RP.Foot or 1.7), st.radius(hgt) * (RP.Top or 1.15)
				local a, lean = r.ang, RP.Lean or 1.1
				r:set(pos + Vector3.new(math.cos(a) * ra, 0.5, math.sin(a) * ra), st.axis(hgt) + Vector3.new(math.cos(a + lean) * rb, 0, math.sin(a + lean) * rb))
			end
			-- the clouds: in as it reaches them
			table.clear(parts)
			table.clear(cfs)
			local axisTop = st.axis(top)
			for _, c in st.clouds do
				c.a += 0.18 * dt
				if not c.on and grow >= 0.55 then
					c.on = true
					c.em.Rate = (S.CloudRate or 0.32) * (low and 0.6 or 1)
					pcall(function()
						c.em:Emit(2)
					end)
				end
				table.insert(parts, c.part)
				table.insert(cfs, CFrame.new(axisTop + Vector3.new(math.cos(c.a) * c.r, c.h - top, math.sin(c.a) * c.r)))
			end
			-- THE GATHER POINT: everything it carries pulled into one knot high
			-- in it (where the server throws from), the funnel winding tighter
			if not st.knot and not st.hurled and t >= st.knotAt then
				st.knot = true
				IN.far("InasaSkyKnot", pos, 1)
				if st.low then
					st.low:set({ spin = (LO.Spin or 1.1) * 1.8, baseR = (CY.BaseRadius or 12) * 0.8 })
				end
				if st.high then
					st.high:set({ spin = (HI.Spin or 0.45) * 1.8 })
				end
				st.knotFx = WK.compress(function()
					return st.axis(S.KnotHeight or 66)
				end, { from = S.KnotRadius or 16, to = 7, time = 0.3, n = 8, spin = 4, sound = false, life = 1.2 })
				if st.knotFx and st.knotFx.holder then
					st.knotFx.holder.Parent = model
				end
			end
			local knotPos = st.axis(S.KnotHeight or 66)
			local O = CY.Orbit or { 6, 60 }
			for _, pc in st.pieces do
				if not pc.thrown and pc.part.Parent then
					if pc.delay then
						pc.delay -= dt
						if pc.delay > 0 then
							continue
						end
						pc.delay = nil
					end
					local p
					if st.knot and not pc.leaf then
						if not pc.kFrom then
							pc.kFrom = pc.part.CFrame.Position
							pc.kT0 = t
							local i = pc.lane * 5 + pc.slot
							local z = 1 - 2 * ((i * 0.618) % 1)
							local rr = math.sqrt(math.max(1 - z * z, 0))
							pc.kOff = Vector3.new(math.cos(i * 2.4) * rr, z, math.sin(i * 2.4) * rr) * rand(2.5, (S.KnotRadius or 16) * 0.55)
						end
						local f = math.clamp((t - pc.kT0) / 0.18, 0, 1)
						f = 1 - (1 - f) * (1 - f)
						local w = t * 4
						local off = Vector3.new(pc.kOff.X * math.cos(w) - pc.kOff.Z * math.sin(w), pc.kOff.Y, pc.kOff.X * math.sin(w) + pc.kOff.Z * math.cos(w))
						p = pc.kFrom:Lerp(knotPos + off, f)
					else
						if pc.leaf then
							pc.h += pc.climb * dt
							if pc.h >= (S.LeafTop or 200) * grow then
								pc.h = rand(0, 20)
							end
						else
							pc.h = math.min(pc.h + pc.climb * dt, math.max(pc.ceil * math.max(grow, 0.15), 2))
						end
						local k = math.clamp(pc.h / 300, 0, 1)
						pc.a += (CY.OrbitSpeed or 0.35) * TAU * (1.6 - k) * dt
						local h = math.max(pc.h, 0)
						local r = math.max(st.radius(h) * pc.out, O[1])
						p = st.axis(h) + Vector3.new(math.cos(pc.a) * r, 0, math.sin(pc.a) * r)
					end
					pc.rot *= pc.tumble
					table.insert(parts, pc.part)
					table.insert(cfs, CFrame.new(p) * pc.rot)
				end
			end
			IN.move(parts, cfs)
			-- the bodies in its eye, wrapped in it (the server holds them there)
			if st.low and t >= nextHeld and t >= form and not st.knot and not st.hurled then
				nextHeld = t + 0.25
				local eyeR = (spec.EyeRadius or 14) + 2
				local want = {}
				for _, body in U.fighters() do
					local tr = body ~= char and (body:FindFirstChild("Torso") or body:FindFirstChild("UpperTorso"))
					if tr then
						local rel = tr.CFrame.Position - pos
						if Vector3.new(rel.X, 0, rel.Z).Magnitude <= eyeR and rel.Y > -6 and rel.Y < (spec.Height or 220) then
							want[tr] = true
							st.low:carry(tr, { radius = 3, spin = 2.4 })
						end
					end
				end
				for part in st.low.carried do
					if not want[part] then
						st.low:drop(part)
					end
				end
				st.held = want
			end
			if st.knot and st.low and next(st.low.carried) then
				for part in st.low.carried do
					st.low:drop(part)
				end
			end
			if t > nextBolt and grow >= 1 and not st.knot then
				nextBolt = t + rand(0.45, (CY.Bolts or 0.7) * 1.6)
				st.bolt()
			end
			-- its roar (dropping out before the gather point)
			if t >= nextRoar and not st.hurled and t < st.knotAt - (S.RoarQuiet or 1.6) then
				nextRoar = t + 1.8
				IN.far("InasaWhirlLoop", pos, 1.4)
			end
			if t - lastShake > 0.4 and st.near < (CY.Near or 600) and not st.hurled and not st.knot then
				lastShake = t
				local SH = CY.Shake or { 0.6, 2.2 }
				VFX.Shake((SH[1] + (SH[2] - SH[1]) * grow) * math.clamp(1.2 - st.near / (CY.Near or 600), 0.3, 1), 0.45)
			end
		end)
	end
	-- (server) the city's rubble sucked up into it: each piece flies from
	-- where the server took it into the funnel's foot, then climbs to its ring
	function Effects.SkyCycloneDebris(char, data)
		data = type(data) == "table" and data or {}
		local pos = IN.point(data.Pos)
		local st = IN.storm(char, pos)
		if not st or st.done then
			return
		end
		for _, piece in type(data.Pieces) == "table" and data.Pieces or {} do
			local at = type(piece) == "table" and IN.point(piece.Position)
			if at then
				local size = typeof(piece.Size) == "Vector3" and piece.Size or Vector3.one * 2
				size = Vector3.new(math.clamp(size.X, 0.5, 5), math.clamp(size.Y, 0.5, 5), math.clamp(size.Z, 0.5, 5))
				local p = newPart(size, CFrame.new(at), typeof(piece.Color) == "Color3" and piece.Color or PAL.DUST_DARK,
					typeof(piece.Material) == "EnumItem" and piece.Material or Enum.Material.Concrete, nil, st.model)
				local pc = IN.addPiece(st, p, 0)
				if pc then
					pc.delay = 0.5
					tween(p, 0.5, { CFrame = CFrame.new(st.pos + UP * 4) * CFrame.Angles(rand(0, 6), rand(0, 6), rand(0, 6)) }, Enum.EasingStyle.Quad, Enum.EasingDirection.In)
				end
			end
		end
	end
	-- a thrown piece's streak (matte, his wind's white)
	function U.trail(part, life)
		local a0, a1 = Instance.new("Attachment"), Instance.new("Attachment")
		local w = math.clamp(part.Size.Magnitude * 0.35, 0.6, 2.2)
		a0.Position, a1.Position = Vector3.new(0, w / 2, 0), Vector3.new(0, -w / 2, 0)
		a0.Parent, a1.Parent = part, part
		local tr = Instance.new("Trail")
		tr.Name = "InasaWind"
		tr.Attachment0, tr.Attachment1 = a0, a1
		tr.Color = ColorSequence.new(PAL.AIR, PAL.SHADE)
		tr.Transparency = NumberSequence.new(0.25, 1)
		tr.WidthScale = NumberSequence.new(1, 0.2)
		tr.LightEmission = 0.1
		tr.LightInfluence = 0.4
		tr.FaceCamera = true
		tr.Lifetime = life or 0.3
		tr.Parent = part
		return tr
	end
	-- THE BURST, on every screen: the knot bursts, the funnel shoots up and
	-- tears apart from its foot, the shockwave rolls off the eye, and every
	-- piece is hurled at the body the server picked - landing when the
	-- server's maths says it does
	function Effects.SkyCycloneHurl(char, data)
		data = type(data) == "table" and data or {}
		local pos = IN.point(data.Pos)
		local st = IN.storm(char, pos)
		pos = pos or (st and st.pos)
		if not pos then
			return
		end
		local d = IN.dir(data.Dir) or Vector3.new(0, 0, -1)
		local low = WK.low()
		local S = CU.Sky or {}
		local root = char and char:FindFirstChild("HumanoidRootPart")
		if root then
			VFX.Voice("InasaSkyHurl", root)
		end
		local run = char and IN.runs[char]
		local mine = run and run.mine
		IN.title((C.Titles and C.Titles.Hurl) or "CYCLONE!!!", mine == true, 1.2,
			not mine and char and string.format((C.Titles and C.Titles.Who) or "%s: SKYBREAKER CYCLONE", IN.whoName(char)) or nil)
		IN.far("InasaHurlBlast", pos, 1)
		local camPos = IN.camPos()
		local near = (camPos - pos).Magnitude
		if near < 300 or mine then
			VFX.ImpactFrame(0.1)
			if VFX.Hooks.Flash then
				VFX.Hooks.Flash(Color3.new(1, 1, 1), 0.25)
			end
		end
		if mine or near < (S.RadialNear or 140) then
			WK.screenWind("radial", 0.38)
		end
		VFX.Shake(math.clamp(5 - near / 120, 1, 5), 0.6)
		-- the knot bursts (facing whoever's looking), the shockwave off the eye
		local knot = st and st.axis(S.KnotHeight or 66) or pos + UP * (S.KnotHeight or 66)
		if st and st.knotFx then
			pcall(st.knotFx.release, st.knotFx, UP)
		end
		WK.burst(knot, WK.dir(camPos - knot, UP), { radius = S.KnotBurst or 26, grow = 0.2, streaks = 12, curls = 8, life = 0.5, ground = false })
		WK.burst(pos + UP * 6, UP, { radius = S.Shock or 46, grow = 0.3, life = 0.7, streaks = 12, curls = 8 })
		WK.ground(pos, S.Ground or 60, { loops = 4, spin = 1.1, cracks = true, life = 1.6 })
		WK.dustRing(pos, S.Ground or 60, { n = 12 })
		shockDisc(pos + UP, UP, 10, S.Disc or 220, 0.6, PAL.AIR)
		-- the funnel shoots up and tears apart, from its foot up
		if st then
			st.hurled = true
			if st.low then
				st.low:stop(0.5, "burst")
			end
			local high = st.high
			if high then
				task.delay(0.12, function()
					high:stop(0.9, "burst")
				end)
			end
			for _, r in st.ropes do
				r:stop(0.35)
			end
		end
		-- every piece thrown: at the body, on the server's clock
		local pool = {}
		if st then
			for _, pc in st.pieces do
				if not pc.leaf and not pc.thrown and pc.part.Parent then
					table.insert(pool, pc)
				end
			end
		end
		local landed = {}
		for i, th in type(data.Throws) == "table" and data.Throws or {} do
			local aim = type(th) == "table" and IN.point(th.Aim)
			local from = type(th) == "table" and IN.point(th.From) or (pos + UP * 40)
			if aim then
				local delay = math.clamp(tonumber(th.Delay) or 0, 0, 3)
				local time = math.clamp(tonumber(th.Time) or 0.6, 0.1, 3)
				local pc = pool[(i - 1) % math.max(#pool, 1) + 1]
				local part
				if pc and not pc.thrown then
					pc.thrown = true
					part = pc.part
				elseif st then
					part = IN.chunk(st, from)
				else
					local s = rand(1.5, 3.5)
					part = newPart(Vector3.new(s, s * 0.8, s), CFrame.new(from), Color3.fromRGB(130, 126, 122), Enum.Material.Concrete)
				end
				-- ((round 92 review) out of the storm's model: it goes 1.5 s after
				-- the burst, and a piece thrown at someone far off is still flying)
				part.Parent = folder
				local target = type(th) == "table" and th.Target or nil
				task.delay(delay, function()
					if not part.Parent then
						return
					end
					local start = part.CFrame.Position
					local peak = (start + aim) / 2 + UP * math.min((aim - start).Magnitude * 0.25, 60)
					local t0 = os.clock()
					VFX.PlaySound("InasaChunkWhoosh", start, 1)
					if not low or i % 2 == 1 then
						U.trail(part, 0.3)
					end
					local spin = CFrame.Angles(rand(-0.4, 0.4), rand(-0.4, 0.4), rand(-0.4, 0.4))
					local rot = part.CFrame - part.CFrame.Position
					local conn
					conn = RunService.RenderStepped:Connect(function()
						local k = math.clamp((os.clock() - t0) / time, 0, 1)
						if not part.Parent then
							conn:Disconnect()
							return
						end
						local a = start:Lerp(peak, k)
						local b = peak:Lerp(aim, k)
						rot *= spin
						part.CFrame = CFrame.new(a:Lerp(b, k)) * rot
						if k >= 1 then
							conn:Disconnect()
							VFX.PlaySound("InasaChunkHit", aim, 1)
							dustPuffs(aim, 0.9, low and 2 or 4, PAL.DUST, 0.8, false)
							rocks(aim, 1, low and 2 or 4)
							-- (the first on each body: the air it carried slamming down round them)
							local key = typeof(target) == "Instance" and target or i
							if not landed[key] then
								landed[key] = true
								WK.burst(aim, UP, { radius = 5, streaks = 5, curls = 3, life = 0.35 })
							end
							tween(part, 0.4, { Transparency = 1 }, Enum.EasingStyle.Linear, nil, 0.3)
							WK.after(part, 0.75)
						end
					end)
				end)
			end
		end
		-- the ones in the eye: thrown out of it, a spray of curls off them
		for _, target in type(data.Out) == "table" and data.Out or {} do
			local torso = typeof(target) == "Instance" and (target:FindFirstChild("Torso") or target:FindFirstChild("UpperTorso"))
			if torso then
				local out = WK.dir(Vector3.new(torso.Position.X - pos.X, 0, torso.Position.Z - pos.Z), d)
				WK.curl(torso.Position, out + UP * 0.6, { n = low and 2 or 4, size = 2.8, drift = 8, life = 0.5 })
				addTrail(torso, PAL.AIR, 0.35, 2.4)(1.4)
			end
		end
		if st then
			-- (what's left in it is flung out as it blows apart)
			for _, pc in st.pieces do
				if not pc.thrown and pc.part.Parent then
					pc.thrown = true
					local at = pc.part.CFrame.Position
					local out = Vector3.new(at.X - pos.X, 0, at.Z - pos.Z)
					out = out.Magnitude > 0.1 and out.Unit or d
					tween(pc.part, 1.2, { CFrame = CFrame.new(at + out * rand(30, 80) + UP * rand(-40, 10)), Transparency = 1 }, Enum.EasingStyle.Quad, Enum.EasingDirection.Out)
				end
			end
			task.delay(0.3, function()
				st.stop(false)
			end)
		end
	end
	-- (server) called off: it all unwinds quickly, his windup ends
	function Effects.SkyCycloneCancel(char, data)
		local st = IN.storm(char, IN.point(data and data.Pos))
		if st then
			st.stop(false)
		end
		local run = char and IN.runs[char]
		if run then
			-- ((round 92 review) and his own cutscene with it)
			if run.mine and not run.did.hurl and VFX.InOwnCinematic() then
				VFX.CancelCinematic()
			end
			run.stop(true)
		end
	end
end)()

---------------------------------------------------------------------------
-- (round 86) DEV FLIGHT (Config.DevFlight): how a flying dev looks and
-- sounds on every screen - Invincible's language. The world shows the
-- force: the street cracks and a dust skirt rings out as he goes, clods
-- fly; a dust wake rolls under him when he skims the street; walls burst
-- out the far side and leave a smoking hole; the crash is a dust event
-- first (a burst that holds, a wall rolling out, a leaning wisp) and a
-- crater second (tilted slabs round the rim, cracks running out). At speed
-- the body becomes a line: contrails off the fists and feet, a white
-- sheath at HYPERSONIC, vapor rings and the bow-wave, and the sonic boom
-- (a vapor disc, a flash, rings - heard late by everyone else, distance /
-- the speed of sound). Poses follow intent: hover arms-down, one fist
-- forward, the free arm swept back, a spear, the braking flip, the
-- superhero landing, the crouch in the crater (R6 clips in anim/moves_fly.py;
-- the POSES below are the fallback).
-- Every client watches the flyers (the body's DevFlying, from the server;
-- your own body's DevFlyLocal, set at once by your machine) and draws them
-- from where their body really is; the beats come as Effects.DevFly (your
-- own predicted, everyone else's from the server). Built from the round-85
-- kit's pieces (VFX.EngineKit) so it reads like the rest of the game, and
-- half as much on a low-end machine.
-- (Its own block, one local: the main chunk is at its local limit.)
---------------------------------------------------------------------------
do
	local DFX = {
		DEV = Config.DevFlight or {},
		flying = setmetatable({}, { __mode = "k" }), -- [char] = the watcher's state while he's up
		posed = setmetatable({}, { __mode = "k" }), -- [char] = { name, at } the held flight pose
		landedAt = setmetatable({}, { __mode = "k" }), -- [char] = when a landing / crash took his body
		PAL = {
			DUST = Color3.fromRGB(178, 166, 150), DUST_DARK = Color3.fromRGB(118, 110, 102), DUST_LIGHT = Color3.fromRGB(214, 206, 192),
			FIELD = Color3.fromRGB(200, 172, 124), CONCRETE = Color3.fromRGB(130, 128, 132), CONCRETE_DARK = Color3.fromRGB(72, 70, 74),
			GLASS = Color3.fromRGB(200, 230, 255), SMOKE = Color3.fromRGB(92, 90, 96), CRATER = Color3.fromRGB(64, 60, 58),
			CRACK = Color3.fromRGB(40, 38, 36), SHOCK = Color3.fromRGB(240, 246, 255), CONTRAIL = Color3.fromRGB(242, 246, 252),
			AFTERGLOW = Color3.fromRGB(255, 206, 150), MARK = Color3.fromRGB(255, 70, 60),
		},
	}
	VFX.DFX = DFX

	-- the poses (the fallback when the place has no R6 clip; R6 reads the
	-- shoulders, hips, Waist and Neck, and Crouch = studs). Held in the
	-- flight's own frame: the body lies along where he's going, so an arm at
	-- ~176 points down the flight path and a Neck of +58..70 looks ahead.
	POSES.FlyHover = { RightArm = { -6, 0, 10 }, LeftArm = { -6, 0, 10 }, RightLeg = { -3, 0, 3 }, LeftLeg = { 6, 0, 3 }, Waist = { 4, 0, 0 }, Neck = { -8, 0, 0 } }
	POSES.FlyCruise = { RightArm = { 176, 0, 6 }, LeftArm = { -10, 0, 10 }, RightLeg = -4, LeftLeg = -14, Waist = { 8, 0, 0 }, Neck = { 58, 0, 0 } }
	POSES.FlyFast = { RightArm = { 176, 0, 4 }, LeftArm = { -38, 0, 26 }, RightLeg = -6, LeftLeg = -9, Waist = { 10, 0, 0 }, Neck = { 62, 0, 0 } }
	POSES.FlyHyper = { RightArm = { 178, 0, -3 }, LeftArm = { -4, 0, 3 }, RightLeg = 0, LeftLeg = 0, Waist = { 0, 0, 0 }, Neck = { 66, 0, 0 } }
	POSES.FlyBoost = { RightArm = { 178, 0, -4 }, LeftArm = { -2, 0, 2 }, RightLeg = 0, LeftLeg = 0, Waist = { -4, 0, 0 }, Neck = { 70, 0, 0 } }
	POSES.FlyDive = { RightArm = { 178, 0, -4 }, LeftArm = { 178, 0, -4 }, RightLeg = 0, LeftLeg = 0, Neck = { 70, 0, 0 } }
	POSES.FlyBrake = { RightArm = { 70, 0, 60 }, LeftArm = { 70, 0, 60 }, RightLeg = 55, LeftLeg = 35, Waist = { -18, 0, 0 }, Neck = { 25, 0, 0 } }
	POSES.FlyCrouch = { Crouch = 1.3, Waist = { -26, 0, 0 }, Neck = { 22, 0, 0 }, RightArm = { -34, 0, 18 }, LeftArm = { -34, 0, 18 } }
	POSES.FlyLaunch = { RightArm = { -4, 0, 2 }, LeftArm = { -4, 0, 2 }, RightLeg = 0, LeftLeg = 0, Waist = { 6, 0, 0 }, Neck = { 30, 0, 0 } }
	POSES.FlyLand = { Crouch = 1.5, Waist = { -34, 0, 0 }, Neck = { 30, 0, 0 }, RightArm = { 40, 0, 6 }, LeftArm = { -50, 0, 55 }, RightLeg = 40, LeftLeg = -40 }
	POSES.FlyCrash = { Crouch = 1.5, Waist = { -30, 0, 0 }, Neck = { 28, 0, 0 }, RightArm = { -30, 0, 28 }, LeftArm = { -30, 0, 28 } }

	function DFX.kit()
		return VFX.EngineKit
	end
	-- half as much on a low-end machine
	function DFX.n(x)
		return VFX.EngineKit.count(x)
	end
	function DFX.isMine(char)
		local lp = Players.LocalPlayer
		return lp ~= nil and char ~= nil and lp.Character == char
	end
	-- how he's flying (nil: he isn't). Your own body: what your machine says
	-- this frame; anyone else's: the server's DevFlying
	function DFX.tierOf(char)
		if not char then
			return nil
		end
		if DFX.isMine(char) then
			return char:GetAttribute("DevFlyLocal")
		end
		return char:GetAttribute("DevFlying")
	end
	-- the dust a surface throws up: the street's, a field's on grass
	function DFX.dustOf(hit)
		local P = DFX.PAL
		if not hit then
			return P.DUST
		end
		local m = hit.Material
		if m == Enum.Material.Grass or m == Enum.Material.LeafyGrass or m == Enum.Material.Ground or m == Enum.Material.Sand or m == Enum.Material.Mud then
			return P.FIELD
		end
		local inst = hit.Instance
		if inst and inst:IsA("BasePart") then
			return P.DUST:Lerp(inst.Color, 0.2)
		end
		return P.DUST
	end
	-- the ground under a point (and how far down), or nil
	function DFX.below(pos, depth)
		local hit = groundRay(pos, depth or 60)
		return hit, hit and (pos.Y - hit.Position.Y) or math.huge
	end

	---------------------------------------------------------------------------
	-- poses
	---------------------------------------------------------------------------
	-- hold a flight pose: its clip (Pose<name>, from the place) if there is
	-- one, blended over `fade`, else the procedural one. holdFor: a timed
	-- hold (the hover's breath, re-struck every cycle); nil holds it till the
	-- next one. A pose already held isn't struck again (no jitter).
	function DFX.pose(char, name, fade, holdFor)
		local cur = DFX.posed[char]
		if cur and cur.name == name and not holdFor then
			return
		end
		DFX.posed[char] = { name = name, at = os.clock() }
		local A = Config.Animations or {}
		if A.MoveClips ~= false and VFX.GetClip and VFX.GetClip("Pose" .. name) and not char:FindFirstChild("UpperTorso")
			and VFX.Clip(char, "Pose" .. name, { holdFor = holdFor or 1e6, fade = fade or 0.2, recover = 0.25 }) then
			return
		end
		VFX.Pose(char, name, holdFor and holdFor + 1.4 or -1)
	end
	-- a pose that plays out and lets go by itself (the landings): the
	-- flight's held pose is over
	function DFX.once(char, name, holdFor)
		DFX.posed[char] = nil
		DFX.landedAt[char] = os.clock()
		local A = Config.Animations or {}
		if A.MoveClips ~= false and VFX.GetClip and VFX.GetClip("Pose" .. name) and not char:FindFirstChild("UpperTorso")
			and VFX.Clip(char, "Pose" .. name, { holdFor = holdFor or 0.4, fade = 0.06, recover = 0.3 }) then
			return
		end
		VFX.Pose(char, name, (holdFor or 0.4) + 0.4)
	end
	function DFX.unpose(char, t)
		if DFX.posed[char] then
			DFX.posed[char] = nil
			VFX.ReleasePose(char, t or 0.25)
		end
	end
	-- which pose a tier holds (nil: leave the body alone)
	DFX.POSE_OF = {
		Crouch = "FlyCrouch", Ascent = "FlyLaunch", Hover = "FlyHover", Cruise = "FlyCruise", Fast = "FlyFast",
		Hyper = "FlyHyper", Boost = "FlyBoost", Dive = "FlyDive", Brake = "FlyBrake",
		Light = "FlyLight", -- (round 90: LIGHTSPEED - VFX.LSX's POSES.FlyLight)
		God = "FlyLight", -- (round 99: GODSPEED - the same streamlined line, in its sheath)
	}
	-- how quickly into it (a launch, a brake snap; tiers blend)
	DFX.FADE_OF = { Crouch = 0.12, Ascent = 0.05, Boost = 0.06, Dive = 0.1, Brake = 0.08, Hover = 0.35, Light = 0.08, God = 0.06 }

	---------------------------------------------------------------------------
	-- building blocks
	---------------------------------------------------------------------------
	-- a ring of dust rolling out along the ground: `n` holders round `from`
	-- studs, each blowing smoke outward (reach: how far it rolls, height:
	-- how tall it billows, life: how long it hangs)
	function DFX.skirt(ground, color, opts)
		opts = opts or {}
		local EK = DFX.kit()
		local n = DFX.n(opts.n or 14)
		local reach, height, life = opts.reach or 16, opts.height or 1, opts.life or 1.8
		local from = opts.from or 2
		local base = rand(0, math.pi * 2)
		for i = 1, n do
			local a = base + (i - 1) / n * math.pi * 2
			local out = Vector3.new(math.cos(a), 0, math.sin(a))
			local at = ground + out * from + UP * (0.5 + 0.3 * height)
			local h = EK.holder(CFrame.lookAt(at, at + out + UP * (opts.lift or 0.12)), life + 0.5, "DevFlyDust")
			local pe = EK.emitter(h, {
				tex = EK.TEX.smoke, color = { color, color:Lerp(DFX.PAL.DUST_DARK, 0.45) },
				size = { { 0, 1.6 * height }, { 0.35, 4.4 * height }, { 1, 6.5 * height } }, transp = { { 0, 0.15 }, { 0.6, 0.4 }, { 1, 1 } },
				life = { life * 0.75, life }, speed = { reach * 1.6, reach * 2.2 }, spread = 14, drag = 3.2,
				accel = Vector3.new(0, 2.2 * height, 0), influence = 0.85, spin = { -40, 40 },
			})
			pe:Emit(opts.per or 3)
		end
	end

	-- chunks of the street / a wall thrown out along `dir` (a cone of
	-- `spread`, 0..1): real bodies that tumble and land, shrinking away
	function DFX.chunks(origin, dir, n, opts)
		opts = opts or {}
		local colors = opts.colors or { DFX.PAL.CONCRETE, DFX.PAL.CONCRETE_DARK }
		local spread = opts.spread or 0.6
		local lo, hi = (opts.speed or { 40, 90 })[1], (opts.speed or { 40, 90 })[2]
		local s0, s1 = (opts.size or { 0.5, 1.6 })[1], (opts.size or { 0.5, 1.6 })[2]
		local d = dir.Magnitude > 0.01 and dir.Unit or UP
		for _ = 1, DFX.n(n) do
			local s = rand(s0, s1)
			local p = Instance.new("Part")
			p.Name = "DevFlyChunk"
			p.Size = Vector3.new(s, s * rand(0.45, 0.9), s * rand(0.7, 1.3))
			p.Color = colors[rng:NextInteger(1, #colors)]:Lerp(Color3.new(0, 0, 0), rand(0, 0.2))
			p.Material = Enum.Material.Slate
			p.CanQuery = false
			p.CanTouch = false
			p.CastShadow = false
			pcall(function()
				p.CollisionGroup = "Debris" -- (never in anyone's way)
			end)
			p.CFrame = CFrame.new(origin + rng:NextUnitVector() * (opts.jitter or 0.8)) * CFrame.Angles(rand(0, 6), rand(0, 6), rand(0, 6))
			p.Parent = folder
			local v = (d + rng:NextUnitVector() * spread + UP * (opts.up or 0.2))
			p.AssemblyLinearVelocity = (v.Magnitude > 0.01 and v.Unit or d) * rand(lo, hi)
			p.AssemblyAngularVelocity = rng:NextUnitVector() * rand(8, 20)
			local life = opts.life or 2.4
			tween(p, 0.5, { Size = Vector3.one * 0.05 }, Enum.EasingStyle.Quad, Enum.EasingDirection.In, life - 0.5)
			cleanup(p, life + 0.05)
		end
	end

	-- glass glinting as it falls (a window went with the wall)
	function DFX.glass(origin, dir, n)
		local EK = DFX.kit()
		local h = EK.holder(CFrame.lookAt(origin, origin + dir), 1.6, "DevFlyGlass")
		local pe = EK.emitter(h, {
			tex = EK.TEX.spark, color = { DFX.PAL.GLASS, Color3.new(1, 1, 1) }, size = { { 0, 0.5 }, { 1, 0.15 } }, transp = { { 0, 0 }, { 0.7, 0.2 }, { 1, 1 } },
			life = { 0.7, 1.2 }, speed = { 30, 70 }, spread = 40, drag = 1.5, accel = Vector3.new(0, -60, 0), light = 1, bright = 2, spin = { -300, 300 },
		})
		pe:Emit(DFX.n(n or 10))
	end

	-- a smoke plume left hanging in a hole, drifting off (a line of them
	-- along his path: the city after he's been through)
	function DFX.plume(pos, life, k)
		local EK = DFX.kit()
		k = k or 1
		local h = EK.holder(CFrame.new(pos), life + 3, "DevFlyPlume")
		h.Size = Vector3.new(3 * k, 3 * k, 3 * k)
		local pe = EK.emitter(h, {
			tex = EK.TEX.smoke, color = { DFX.PAL.SMOKE, DFX.PAL.CONCRETE }, size = { { 0, 2 * k }, { 0.5, 5 * k }, { 1, 8 * k } },
			transp = { { 0, 0.35 }, { 0.6, 0.55 }, { 1, 1 } }, life = { 2.2, 3 }, speed = { 1, 3 }, spread = 30, dir = "Top",
			accel = Vector3.new(2.5, 2.6, 1), drag = 0.6, influence = 0.9, spin = { -20, 20 },
		})
		pe.Shape = Enum.ParticleEmitterShape.Box
		pe.Rate = 5 * (EK.lowEnd() and 0.5 or 1)
		task.delay(life, function()
			pe.Enabled = false
		end)
	end

	-- a flash ball: a white sphere swelling and gone (the boom, the burst)
	function DFX.flashBall(pos, from, to, t)
		local p = newPart(Vector3.one * from, CFrame.new(pos), Color3.new(1, 1, 1), Enum.Material.Neon, Enum.PartType.Ball)
		p.Name = "DevFlyFlash"
		p.Transparency = 0.2
		tween(p, t or 0.12, { Size = Vector3.one * to, Transparency = 1 }, Enum.EasingStyle.Quad, Enum.EasingDirection.Out)
		cleanup(p, (t or 0.12) + 0.05)
	end

	-- (round 86 review) THE VAPOR CONE - the Prandtl-Glauert cloud, the
	-- picture everyone knows of the sound barrier: a white shell flaring back
	-- off his shoulders the instant he breaks through, riding him for `ride`
	-- s, then left hanging in the air where it happened, swelling and
	-- thinning out over `life`. Built of triangles round the cone (two
	-- wedges each, so it's one clean shape from the side in a single frame),
	-- 12 facets - 8 on a low-end machine
	function DFX.vaporCone(char, pos, d, opts)
		opts = opts or {}
		if typeof(pos) ~= "Vector3" or typeof(d) ~= "Vector3" or d.Magnitude < 0.01 then
			return
		end
		d = d.Unit
		local root = char and charParts(char)
		local n = DFX.kit().lowEnd() and 8 or 12
		local L, R = opts.length or 9, opts.radius or 4.6
		local ahead = opts.ahead or 2.4 -- (the tip, just past his head)
		local life, ride = opts.life or 0.42, opts.ride or 0.1
		local color = opts.color or DFX.PAL.CONTRAIL
		local facets = {}
		local function add(cf, size)
			local w = Instance.new("WedgePart")
			w.Name = "DevFlyCone"
			w.Anchored = true
			w.CanCollide = false
			w.CanQuery = false
			w.CanTouch = false
			w.CastShadow = false
			w.Color = color
			w.Material = Enum.Material.SmoothPlastic
			w.Transparency = 1
			w.Size = size
			w.Parent = folder
			cleanup(w, life + 0.3)
			table.insert(facets, { part = w, pos = cf.Position, rot = cf.Rotation, size = size })
		end
		-- a triangle as two wedges, in the cone's own frame (tip at 0,
		-- flaring back down +Z)
		local function tri(a, b, c)
			local ab, ac, bc = b - a, c - a, c - b
			local abd, acd, bcd = ab:Dot(ab), ac:Dot(ac), bc:Dot(bc)
			if abd > acd and abd > bcd then
				c, a = a, c
			elseif acd > bcd and acd > abd then
				a, b = b, a
			end
			ab, ac, bc = b - a, c - a, c - b
			local right = ac:Cross(ab).Unit
			local up = bc:Cross(right).Unit
			local back = bc.Unit
			local height = math.abs(ab:Dot(up))
			add(CFrame.fromMatrix((a + b) / 2, right, up, back), Vector3.new(0.05, height, math.abs(ab:Dot(back))))
			add(CFrame.fromMatrix((a + c) / 2, -right, up, -back), Vector3.new(0.05, height, math.abs(ac:Dot(back))))
		end
		local spin = rand(0, math.pi * 2)
		for i = 0, n - 1 do
			local a0, a1 = spin + i / n * math.pi * 2, spin + (i + 1) / n * math.pi * 2
			tri(Vector3.zero, Vector3.new(math.cos(a0) * R, math.sin(a0) * R, L), Vector3.new(math.cos(a1) * R, math.sin(a1) * R, L))
		end
		local held = CFrame.lookAt(pos + d * ahead, pos + d * (ahead + 1))
		local function place(t)
			if t < ride and root and root.Parent then
				local p = root.Position + d * ahead
				held = CFrame.lookAt(p, p + d)
			end
			local k = math.clamp(t / life, 0, 1)
			local grow = 0.55 + 0.6 * (1 - (1 - k) * (1 - k)) -- (snapping open, then swelling slowly)
			local tr = 0.28 + 0.72 * k ^ 1.6
			for _, f in facets do
				local part = f.part
				if part.Parent then
					part.Size = Vector3.new(f.size.X, f.size.Y * grow, f.size.Z * grow)
					part.CFrame = held * CFrame.new(f.pos * grow) * f.rot
					part.Transparency = tr
				end
			end
		end
		place(0)
		task.spawn(function()
			local t0 = os.clock()
			while os.clock() - t0 < life do
				task.wait()
				place(os.clock() - t0)
			end
			for _, f in facets do
				pcall(f.part.Destroy, f.part)
			end
		end)
	end

	-- the crater: a dark floor, tilted slabs standing round the rim (leaning
	-- out), rubble in it and cracks running out - it stays a while
	function DFX.crater(ground, R, hit)
		local P = DFX.PAL
		local street = (hit and hit.Instance and hit.Instance:IsA("BasePart")) and hit.Instance.Color or P.CONCRETE
		local stay = 14
		groundMark(ground, R * 0.92, P.CRATER, stay)
		groundMark(ground, R * 0.55, P.CRACK, stay)
		local n = DFX.n(math.clamp(math.floor(R * 0.9), 10, 16))
		local base = rand(0, math.pi * 2)
		for i = 1, n do
			local a = base + (i - 0.5) / n * math.pi * 2 + rand(-0.12, 0.12)
			local out = Vector3.new(math.cos(a), 0, math.sin(a))
			local w, h, t = rand(0.22, 0.34) * R, rand(0.18, 0.3) * R, rand(0.6, 1.1)
			local at = ground + out * R * rand(0.86, 1.02) + UP * (h * 0.18)
			-- (stood on its edge across the rim, tipped back out from the hole)
			local cf = CFrame.lookAt(at, at + out) * CFrame.Angles(math.rad(rand(30, 60)), rand(-0.25, 0.25), 0)
			local slab = newPart(Vector3.new(w, h, t), cf, street:Lerp(P.CONCRETE_DARK, rand(0.1, 0.45)), Enum.Material.Slate)
			slab.Name = "DevFlySlab"
			slab.Transparency = 0
			tween(slab, 1.5, { Transparency = 1 }, Enum.EasingStyle.Quad, Enum.EasingDirection.In, stay)
			cleanup(slab, stay + 1.6)
		end
		for _ = 1, DFX.n(8) do
			local at = ground + Vector3.new(rand(-1, 1), 0, rand(-1, 1)) * R * 0.6 + UP * 0.25
			local s = rand(0.6, 1.4)
			local rub = newPart(Vector3.new(s * 1.3, s * 0.6, s), CFrame.new(at) * CFrame.Angles(rand(-0.5, 0.5), rand(0, 6), rand(-0.5, 0.5)),
				street:Lerp(P.CRATER, rand(0.3, 0.6)), Enum.Material.Slate)
			rub.Name = "DevFlySlab"
			tween(rub, 1.5, { Transparency = 1 }, nil, nil, stay)
			cleanup(rub, stay + 1.6)
		end
		DFX.kit().cracks(ground, R * 2.2, 11, { crater = false, life = stay * 0.6, grow = 0.2 })
	end

	---------------------------------------------------------------------------
	-- the beats (Effects.DevFly: Kind = ...)
	---------------------------------------------------------------------------
	DFX.BEATS = {}

	-- the crouch before the take-off: hairline cracks round his feet, grit
	-- lifting off the street, the air drawn in (his own machine only; others
	-- see the crouch itself)
	function DFX.BEATS.Crouch(char, data)
		local root = charParts(char)
		if not root then
			return
		end
		local hit = DFX.below(root.Position, 12)
		local g = hit and hit.Position or (root.Position - UP * 3)
		local k = math.clamp(tonumber(data.Charge) or 0, 0, 1)
		DFX.kit().cracks(g, 3 + 5 * k, 5 + math.floor(4 * k), { crater = false, grow = 0.3, life = 1.6 })
		local dust = DFX.dustOf(hit)
		for _ = 1, DFX.n(8 + math.floor(8 * k)) do
			local p = g + Vector3.new(rand(-3, 3), 0.15, rand(-3, 3))
			local grit = newPart(Vector3.one * rand(0.12, 0.3), CFrame.new(p) * CFrame.Angles(rand(0, 6), rand(0, 6), 0), dust:Lerp(DFX.PAL.CONCRETE_DARK, rand(0, 0.5)), Enum.Material.Slate)
			grit.Name = "DevFlyGrit"
			tween(grit, rand(0.5, 0.9), { CFrame = CFrame.new(p + UP * rand(0.8, 2.4)) * CFrame.Angles(rand(0, 6), rand(0, 6), 0), Transparency = 1 }, Enum.EasingStyle.Sine)
			cleanup(grit, 1)
		end
		for _ = 1, DFX.n(4) do
			local p = g + Vector3.new(rand(-9, 9), rand(0.5, 3), rand(-9, 9))
			local toward = root.Position - p
			streaks(p, toward.Magnitude > 0.1 and toward.Unit or UP, 1, 0.5, 3.5, 5, WIND, 0.22)
		end
		if k <= 0 then
			VFX.PlaySound("DevFlyCrouch", g, 1)
		end
	end

	-- THE TAKE-OFF: still, then gone. The street tells you: cracks and a
	-- scorch, a white shock flat on the street, a dust skirt ringing out and
	-- rising, clods thrown up in two fans, a streak up where he went
	function DFX.BEATS.Takeoff(char, data, isLocal)
		local root = charParts(char)
		local k = math.clamp(tonumber(data.Charge) or 0, 0, 1)
		local g = typeof(data.Pos) == "Vector3" and data.Pos or (root and root.Position - UP * 3)
		if not g then
			return
		end
		local hit = DFX.below(g + UP * 2, 8)
		if hit then
			g = hit.Position
		end
		local P = DFX.PAL
		local dust = DFX.dustOf(hit)
		local EK = DFX.kit()
		EK.cracks(g, 6 + 6 * k, 8 + math.floor(4 * k), { life = 4 + 2 * k, grow = 0.1 })
		shockDisc(g + UP * 0.3, UP, 4, 26 + 12 * k, 0.35, P.SHOCK)
		billboardRing(g + UP * 1.2, 3, 22 + 10 * k, P.SHOCK, 4, 0.35)
		DFX.skirt(g, dust, { n = 14, reach = 14 + 6 * k, height = 1 + 0.5 * k, life = 1.9 + 0.4 * k })
		-- (two fans of clods, either side of the way he faced)
		local f = root and Vector3.new(root.CFrame.RightVector.X, 0, root.CFrame.RightVector.Z) or Vector3.new(1, 0, 0)
		f = f.Magnitude > 0.05 and f.Unit or Vector3.new(1, 0, 0)
		for _, side in { 1, -1 } do
			DFX.chunks(g + UP * 0.6, f * side + UP * 1.6, 5 + math.floor(3 * k), { colors = { dust:Lerp(P.CONCRETE_DARK, 0.4), P.CONCRETE_DARK }, spread = 0.45, speed = { 30, 55 + 15 * k }, size = { 0.3, 0.9 }, up = 0.3, life = 2.2 })
		end
		EK.contrailLine(g + UP * 2, g + UP * (40 + 30 * k), { width = 1.6 + 0.6 * k, life = 0.45 })
		VFX.PlaySound("DevFlyTakeoff", g, 0.85 + 0.3 * k)
		-- (round 87) the street cracks where he stood; the rising whoosh goes
		-- up with him; his own wind comes up out of silence into the roar
		if isLocal then
			DFX.mine.launchAt = os.clock()
			DFX.hold(DFX.voice("DevFlyTakeoffRise", nil, 0.9 + 0.3 * k))
		elseif root then
			DFX.voice("DevFlyTakeoffRise", DFX.rider(char, root, 1.5), 0.9 + 0.3 * k)
		end
		if isLocal then
			VFX.Shake(0.9 + 0.4 * k, 0.35)
		else
			VFX.ShakeAt(g, 1.2 + 0.6 * k, 60, 0.5)
		end
	end

	-- caught himself in the air: a snap of cloth, a ring of air under him
	function DFX.BEATS.Catch(char)
		local root = charParts(char)
		if not root then
			return
		end
		billboardRing(root.Position, 2, 11, DFX.PAL.SHOCK, 3, 0.3)
		shockDisc(root.Position - UP * 2.5, UP, 2, 12, 0.3, DFX.PAL.SHOCK)
		VFX.PlaySound("DevFlyCatch", root.Position, 1)
	end

	-- THE SONIC BOOM, passing BoomAt: a vapor disc hanging where he broke
	-- through, a flash, two thin rings, vapor rings down his path. His own
	-- screen: a white flash, an impact frame, the shake, the boom at once.
	-- Everyone else hears it distance / SoundSpeed late (it never arrives
	-- before the picture), and feels it then
	function DFX.BEATS.Boom(char, data, isLocal)
		local root = charParts(char)
		local pos = typeof(data.Pos) == "Vector3" and data.Pos or (root and root.Position)
		if not pos then
			return
		end
		local d = (typeof(data.Dir) == "Vector3" and data.Dir.Magnitude > 0.01) and data.Dir.Unit or (root and root.CFrame.LookVector) or Vector3.new(0, 0, -1)
		local P = DFX.PAL
		for i, spec in { { 1.5, 3, 9 }, { 4, 4, 12 }, { 7, 5, 14 } } do
			task.delay((i - 1) * 0.02, function()
				local disc = shockDisc(pos - d * spec[1], d, spec[2], spec[3] * 1.4, 0.45, P.SHOCK, -6)
				disc.Transparency = 0.3
			end)
		end
		DFX.flashBall(pos, 6, 18, 0.14)
		DFX.vaporCone(char, pos, d) -- (round 86 review: the cone everyone knows)
		billboardRing(pos, 6, 60, P.SHOCK, 3, 0.5)
		billboardRing(pos, 4, 40, P.SHOCK, 2, 0.45)
		DFX.kit().vaporRings(pos - d * 2, -d, 3, { size = 6, gap = 7, life = 0.8 })
		local DEV = DFX.DEV
		if isLocal then
			VFX.Hooks.Flash(Color3.new(1, 1, 1), 0.14)
			VFX.ImpactFrame(0.05)
			VFX.Shake(1.4, 0.6)
			-- (round 87) the boom in his head - the double crack, the pressure,
			-- the sub, the boom - then the world muffled for a beat and his
			-- ears ringing, the wind sucked out and roaring back in, the roll
			-- and the city's echoes left behind him
			-- (round 87 review: boom after boom, only the first muffles and rings)
			local _, again = DFX.boomSound(pos, 0, true, pos)
			local AG = (DFX.SND().Boom or {}).Again or {}
			DFX.muffle(again and (AG.Muffle or 0) or 1)
			if not again then
				DFX.ring(1)
			end
			DFX.duck("Boom")
			-- (the bow-wave round him is the watcher's: it's up from 300)
			return
		end
		local cam = workspace.CurrentCamera
		local dist = cam and (cam.Focus.Position - pos).Magnitude or 0
		local late = math.min(dist / (DEV.SoundSpeed or 980), DEV.BoomDelayMax or 2.5)
		task.delay(late, function()
			-- (round 87) the flash came first; now the boom, mixed by how far it
			-- came (the crack lost on the way, the low end and the roll
			-- carrying), the city's echoes after it - and close enough, the
			-- world muffled and your ears ringing
			local cam2 = workspace.CurrentCamera
			local _, again = DFX.boomSound(pos, dist, false, cam2 and cam2.Focus.Position or pos)
			if again then
				DFX.nearBoom(dist, ((DFX.SND().Boom or {}).Again or {}).Muffle or 0, true)
			else
				DFX.nearBoom(dist, 1)
			end
			VFX.ShakeAt(pos, 1.0, 250, 0.5)
		end)
	end

	-- THE MACH BURST: a flash and rings round him, vapor rings shed behind;
	-- his own screen: white streaks rushing in, a blink of blur, focus lines
	function DFX.BEATS.Boost(char, data, isLocal)
		local root = charParts(char)
		if not root then
			return
		end
		local d = (typeof(data.Dir) == "Vector3" and data.Dir.Magnitude > 0.01) and data.Dir.Unit or root.CFrame.UpVector
		DFX.flashBall(root.Position, 5, 14, 0.12)
		billboardRing(root.Position, 4, 30, DFX.PAL.SHOCK, 3, 0.35)
		billboardRing(root.Position - d * 3, 3, 18, DFX.PAL.SHOCK, 2, 0.3)
		DFX.kit().vaporRings(root.Position - d * 2, -d, 2, { size = 4.5, gap = 5 })
		streaks(root.Position, -d, DFX.n(10), 2.5, 9, 26, WIND, 0.3)
		-- (round 87: in his own ears - he's gone from where it happened at once -
		-- and the wind punched out and back in harder)
		VFX.PlaySound("DevFlyBoost", (not isLocal) and root.Position or nil, 1)
		if isLocal then
			DFX.duck("Boost")
			VFX.Shake(1.0, 0.3)
			if VFX.Hooks.FlightBurst then
				VFX.Hooks.FlightBurst(0.3)
			end
			if VFX.MANGA and VFX.MANGA.lines then
				pcall(VFX.MANGA.lines, 0.25, { Kind = "focus", Count = 26 })
			end
			local blur = Instance.new("BlurEffect")
			blur.Name = "DevFlyBlur"
			blur.Size = 6
			blur.Parent = game:GetService("Lighting")
			tween(blur, 0.12, { Size = 0 }, Enum.EasingStyle.Quad, Enum.EasingDirection.In, 0.05)
			cleanup(blur, 0.2)
		end
	end

	-- THE BRAKING FLIP: air bursting out in front of him, a puff ring, the
	-- streaks thrown on ahead (his own screen shakes)
	function DFX.BEATS.Brake(char, data, isLocal)
		local root = charParts(char)
		if not root then
			return
		end
		local d = (typeof(data.Dir) == "Vector3" and data.Dir.Magnitude > 0.01) and data.Dir.Unit or root.CFrame.LookVector
		shockDisc(root.Position + d * 3, d, 4, 18, 0.3, DFX.PAL.SHOCK, 6)
		DFX.kit().vaporRings(root.Position + d * 2, d, 1, { size = 5, life = 0.5 })
		streaks(root.Position, d, DFX.n(8), 2, 6, 20, WIND, 0.3)
		VFX.PlaySound("DevFlyBrake", (not isLocal) and root.Position or nil, 1)
		if isLocal then
			DFX.duck("Brake") -- (round 87: the air stops dead, then catches up)
			VFX.Shake(0.5, 0.2)
		end
	end

	-- THROUGH A BUILDING (A: where he went in, B: out the far side): the
	-- wall bursting in, then out the far side half again as hard - concrete,
	-- glass, dust - a star where he hit, and a plume left in the hole
	function DFX.BEATS.Smash(char, data, isLocal)
		local a = typeof(data.A) == "Vector3" and data.A or nil
		local b = typeof(data.B) == "Vector3" and data.B or a
		if not a then
			return
		end
		local d = (typeof(data.Dir) == "Vector3" and data.Dir.Magnitude > 0.01) and data.Dir.Unit or ((b - a).Magnitude > 0.1 and (b - a).Unit or Vector3.new(0, 0, -1))
		local P = DFX.PAL
		local EK = DFX.kit()
		local r = math.clamp(tonumber(data.R) or 4.5, 2, 9)
		DFX.chunks(a, -d + UP * 0.3, 5, { spread = 0.9, speed = { 18, 40 }, size = { 0.4, 1.2 }, life = 2 })
		EK.starSpark(a, { color = P.SHOCK, color2 = Color3.new(1, 1, 1), size = 3 + r * 0.6, life = 0.12 })
		shockDisc(a, d, r * 0.8, r * 3, 0.25, P.SHOCK)
		local function burst(at, k, front)
			DFX.chunks(at, d, math.floor(10 * k), { spread = 0.55, speed = { 60, 130 }, size = { 0.5, 1.8 }, up = 0.15, life = 2.6 })
			DFX.glass(at, d, math.floor(8 * k))
			local h = EK.holder(CFrame.lookAt(at, at + d), 3.2, "DevFlyDust")
			h.Size = Vector3.new(r * 1.2, r * 1.2, 1)
			local pe = EK.emitter(h, {
				tex = EK.TEX.smoke, color = { P.CONCRETE:Lerp(P.DUST, 0.4), P.SMOKE }, size = { { 0, 2.5 * k }, { 0.35, 6 * k }, { 1, 9 * k } },
				transp = { { 0, 0.12 }, { 0.6, 0.4 }, { 1, 1 } }, life = { 1.4, 2.2 }, speed = { 18, 45 }, spread = 40, drag = 2.4,
				accel = Vector3.new(0, 1.5, 0), influence = 0.85, spin = { -40, 40 },
			})
			pe.Shape = Enum.ParticleEmitterShape.Box
			pe:Emit(DFX.n(math.floor(14 * k)))
			if front then
				-- (blown out the far side and on down the street: a front of
				-- dust and grit rolling on after him)
				local f = EK.holder(CFrame.lookAt(at, at + d), 3.4, "DevFlyDust")
				f.Size = Vector3.new(r, r, 1)
				local pf = EK.emitter(f, {
					tex = EK.TEX.smoke, color = { P.CONCRETE, P.DUST }, size = { { 0, 3 }, { 0.5, 7 }, { 1, 10 } },
					transp = { { 0, 0.3 }, { 0.6, 0.5 }, { 1, 1 } }, life = { 1.6, 2.4 }, speed = { 55, 95 }, spread = 22, drag = 1.6,
					accel = Vector3.new(0, -4, 0), influence = 0.85, spin = { -30, 30 },
				})
				pf.Shape = Enum.ParticleEmitterShape.Box
				pf:Emit(DFX.n(12))
			end
		end
		burst(a, 1, false)
		task.delay(math.clamp((b - a).Magnitude / 500, 0.03, 0.08), function()
			burst(b, 1.5, true)
			shockDisc(b, d, r, r * 3.4, 0.3, P.SHOCK, 6)
			billboardRing(b, r, r * 4, P.SHOCK, 3, 0.3)
		end)
		DFX.plume((a + b) / 2, 6, math.clamp(r / 4.5, 0.8, 1.6))
		VFX.PlaySound("DevFlySmash", a, 1)
		if isLocal then
			VFX.Shake(0.8, 0.25)
		else
			VFX.ShakeAt(a, 1.2, 90, 0.4)
		end
	end

	-- an UNBREAKABLE wall at speed (a base plate, the Sky Coffin's barrier):
	-- stopped dead - a crater of cracks in the wall, rock and dust thrown
	-- back off it
	function DFX.BEATS.WallHit(char, data, isLocal)
		local pos = typeof(data.Pos) == "Vector3" and data.Pos or nil
		if not pos then
			return
		end
		local n = (typeof(data.Normal) == "Vector3" and data.Normal.Magnitude > 0.01) and data.Normal.Unit or UP
		local P = DFX.PAL
		local EK = DFX.kit()
		local side = n:Cross(math.abs(n.Y) < 0.9 and UP or Vector3.new(1, 0, 0)).Unit
		local up2 = side:Cross(n).Unit
		for i = 1, DFX.n(9) do
			local a = i / 9 * math.pi * 2 + rand(-0.2, 0.2)
			local dir = side * math.cos(a) + up2 * math.sin(a)
			local len = rand(3, 7)
			local mid = pos + n * 0.06 + dir * (0.8 + len / 2)
			local crack = newPart(Vector3.new(rand(0.25, 0.45), 0.05, len), CFrame.lookAt(mid, mid + dir, n), P.CRACK, Enum.Material.SmoothPlastic)
			crack.Name = "DevFlyCrack"
			tween(crack, 0.6, { Transparency = 1 }, nil, nil, 3)
			cleanup(crack, 3.7)
		end
		local mark = newPart(Vector3.new(0.12, 5, 5), CFrame.lookAt(pos + n * 0.05, pos + n * 2) * CFrame.Angles(0, math.pi / 2, 0), P.CRATER, Enum.Material.SmoothPlastic, Enum.PartType.Cylinder)
		mark.Name = "DevFlyCrack"
		mark.Transparency = 0.15
		tween(mark, 0.6, { Transparency = 1 }, nil, nil, 3)
		cleanup(mark, 3.7)
		DFX.chunks(pos + n, n, 10, { spread = 0.8, speed = { 30, 70 }, size = { 0.4, 1.3 }, life = 2.2 })
		EK.starSpark(pos + n * 0.5, { color = P.SHOCK, color2 = Color3.new(1, 1, 1), size = 5, life = 0.12 })
		shockDisc(pos + n * 0.5, n, 3, 16, 0.3, P.SHOCK, 4)
		local h = EK.holder(CFrame.lookAt(pos + n, pos + n * 2), 2.2, "DevFlyDust")
		local pe = EK.emitter(h, {
			tex = EK.TEX.smoke, color = { P.DUST, P.CONCRETE }, size = { { 0, 2 }, { 0.4, 5 }, { 1, 7 } }, transp = { { 0, 0.2 }, { 0.6, 0.45 }, { 1, 1 } },
			life = { 1, 1.6 }, speed = { 12, 26 }, spread = 60, drag = 3, accel = Vector3.new(0, 1.5, 0), influence = 0.85,
		})
		pe:Emit(DFX.n(10))
		VFX.PlaySound("DevFlyWallHit", pos, 1)
		if isLocal then
			VFX.ImpactFrame(0.05)
			VFX.Shake(1.4, 0.5)
		else
			VFX.ShakeAt(pos, 1.4, 90, 0.45)
		end
	end

	-- THE SUPERHERO LANDING: one knee down, a fist on the street - cracks
	-- round it, a dust ring, a few chips, white streaks thrown up
	function DFX.BEATS.Land(char, data, isLocal)
		local root = charParts(char)
		local g = typeof(data.Pos) == "Vector3" and data.Pos or (root and root.Position - UP * 3)
		if not g then
			return
		end
		local hit = DFX.below(g + UP * 2, 8)
		if hit then
			g = hit.Position
		end
		local P = DFX.PAL
		local dust = DFX.dustOf(hit)
		DFX.kit().cracks(g, 4.5, 7, { life = 3, grow = 0.08 })
		shockDisc(g + UP * 0.2, UP, 3, 20, 0.3, P.SHOCK)
		DFX.skirt(g, dust, { n = 12, reach = 10, height = 0.85, life = 1.4, per = 3 })
		rocks(g, 0.8, DFX.n(6))
		streaks(g, UP, DFX.n(8), 2.5, 5, 10, WIND, 0.3)
		VFX.PlaySound("DevFlyLand", g, 1)
		if root and char.Parent then
			DFX.once(char, "FlyLand", (DFX.DEV.Land or {}).Hold or 0.45)
		end
		if isLocal then
			VFX.Shake(0.6, 0.25)
		end
	end

	-- a soft touchdown (sinking slowly onto the street): a little puff
	function DFX.BEATS.Soft(char, data)
		local root = charParts(char)
		local g = typeof(data.Pos) == "Vector3" and data.Pos or (root and root.Position - UP * 3)
		if not g then
			return
		end
		local hit = DFX.below(g + UP * 2, 8)
		dustPuffs((hit and hit.Position or g) + UP * 0.2, 0.45, DFX.n(4), DFX.dustOf(hit), 0.8, false)
		billboardRing((hit and hit.Position or g) + UP * 0.4, 2, 9, DFX.PAL.SHOCK, 2, 0.3)
		VFX.PlaySound("DevFlySoft", g, 1)
		if root then
			DFX.posed[char] = nil
			VFX.ReleasePose(char, 0.3)
		end
	end

	-- THE OMNI-MAN CRASH: an impact frame; a dust burst full-size in a
	-- quarter of a second that holds; a wall of dust rolling out along the
	-- street; a ring of debris; then the crater (slabs, cracks) as it thins,
	-- a leaning wisp left over it, and him crouched in the middle getting up.
	-- Close enough, the dust swallows your camera
	function DFX.BEATS.Crash(char, data, isLocal)
		local root = charParts(char)
		local g = typeof(data.Pos) == "Vector3" and data.Pos or (root and root.Position - UP * 3)
		if not g then
			return
		end
		local hit = DFX.below(g + UP * 3, 10)
		if hit then
			g = hit.Position
		end
		local CR = DFX.DEV.Crash or {}
		local R = math.clamp(tonumber(data.Radius) or ((CR.Radius or {})[1] or 9), 4, 24)
		local P = DFX.PAL
		local EK = DFX.kit()
		local dust = DFX.dustOf(hit)
		local cam = workspace.CurrentCamera
		local near = cam and (cam.Focus.Position - g).Magnitude or 0
		if isLocal or near < 160 then
			VFX.ImpactFrame(0.08)
		end
		DFX.crater(g, R, hit)
		-- the shock along the street, and the ring
		shockDisc(g + UP * 0.4, UP, R * 2, R * 9, 0.5, P.SHOCK)
		billboardRing(g + UP * 2, R, R * 7, P.SHOCK, 5, 0.6)
		DFX.flashBall(g + UP * 2, R * 0.6, R * 1.6, 0.18)
		-- the burst: full in a quarter second, holding ~1.5 s (a dark heart
		-- under a lighter cauliflower top). ((round 89) data.Dust: the burst's
		-- own size, when it isn't the crater's - the bomb's on his own screen)
		local DR = math.clamp(tonumber(data.Dust) or R, 4, 24)
		smokeBurst(g + UP * DR * 0.45, dust, DR * 1.7, DR * 1.1, 2.4, DFX.n(56))
		smokeBurst(g + UP * DR * 0.2, dust:Lerp(P.DUST_DARK, 0.5), DR * 1.2, DR * 0.8, 2, DFX.n(24))
		-- the dust wall rolling out along the street, lingering
		DFX.skirt(g, dust, { n = 22, from = R * 0.8, reach = 40, height = 2.2 + R / 12, life = 3.2, per = 3, lift = 0.05 })
		-- the debris ring
		DFX.chunks(g + UP * 1.5, UP, 24, { spread = 1.25, speed = { 45, 100 }, size = { 0.6, 1.9 }, up = 0.9, life = 3, colors = { dust:Lerp(P.CONCRETE_DARK, 0.5), P.CONCRETE, P.CONCRETE_DARK } })
		-- the leaning wisp, as the burst thins
		task.delay(1.4, function()
			local h = EK.holder(CFrame.new(g + UP * 2), 6.5, "DevFlyWisp")
			h.Size = Vector3.new(R * 0.8, 1, R * 0.8)
			local pe = EK.emitter(h, {
				tex = EK.TEX.smoke, color = { dust, P.SMOKE }, size = { { 0, R * 0.35 }, { 0.5, R * 0.7 }, { 1, R } },
				transp = { { 0, 0.45 }, { 0.6, 0.6 }, { 1, 1 } }, life = { 2.2, 3 }, speed = { 4, 8 }, spread = 15, dir = "Top",
				accel = Vector3.new(3, 1, 1.5), drag = 0.8, influence = 0.9, spin = { -15, 15 },
			})
			pe.Shape = Enum.ParticleEmitterShape.Box
			pe.Rate = DFX.n(6)
			task.delay(2.6, function()
				pe.Enabled = false
			end)
		end)
		-- (round 87) the crash: his own ears at once - the world muffled, the
		-- ringing, the city's echoes; everyone else hears it distance /
		-- SoundSpeed late (the dust first), muffled and ringing up close
		local CS = DFX.SND().Crash or {}
		if isLocal then
			VFX.PlaySound("DevFlyCrash", g, 1)
			DFX.muffle(CS.Muffle or 0.7, { delay = 0.05 })
			DFX.ring(CS.Ring or 0.7)
			DFX.duck("Crash")
			DFX.echoSound(g + UP * 4, g + UP * 4, CS.Echo or 3, 0.8)
		else
			task.delay(math.min(near / (DFX.DEV.SoundSpeed or 980), CS.Late or 1.5), function()
				VFX.PlaySound("DevFlyCrash", g, 1)
				local cam2 = workspace.CurrentCamera
				local ears = cam2 and cam2.Focus.Position or g
				local shiver = 1 - DFX.ss(90, 380, near)
				if shiver > 0.02 then
					VFX.PlaySound("DevFlyBoomShiver", ears + Vector3.new(rand(-14, 14), rand(2, 8), rand(-14, 14)), shiver)
				end
				DFX.nearBoom(near, CS.Ring or 0.7)
				DFX.echoSound(g + UP * 4, ears, CS.Echo or 3, 0.8)
			end)
		end
		if root and char.Parent then
			DFX.once(char, "FlyCrash", CR.Hold or 0.9)
		end
		if isLocal then
			VFX.Hooks.Flash(Color3.new(1, 1, 1), 0.08)
			VFX.Shake(2.2, 0.9)
		else
			VFX.ShakeAt(g, 2.4, 300, 0.9)
		end
		-- the camera swallowed by the dust (close enough)
		if (isLocal or near < 40) and VFX.Hooks.FlightDust then
			task.delay(0.12, function()
				VFX.Hooks.FlightDust(0.9, dust)
			end)
		end
	end

	-- THE DIVE SLAM: where he's coming down, marked (and the whistle)
	function DFX.BEATS.Dive(char, data, isLocal)
		local root = charParts(char)
		if typeof(data.Pos) == "Vector3" then
			local hit = DFX.below(data.Pos + UP * 3, 12)
			local g = hit and hit.Position or data.Pos
			groundMark(g, 10, Color3.fromRGB(200, 40, 40), 1.2)
			for i = 0, 2 do
				task.delay(i * 0.2, function()
					billboardRing(g + UP, 4, 26, DFX.PAL.MARK, 5, 0.35)
				end)
			end
		end
		if root then
			-- (round 87) the scream rising as he comes down: in his own ears
			-- (he leaves any point behind at once), riding his body for
			-- everyone else
			if isLocal then
				VFX.PlaySound("DevFlyDive", nil, 1)
				VFX.Shake(0.5, 0.3)
			else
				DFX.voice("DevFlyDive", DFX.rider(char, root, 2.3), 1)
			end
		end
	end

	-- somebody knocked flying out of his way: a white burst where he hit them
	function DFX.BEATS.Ram(_char, data)
		local pos = typeof(data.Pos) == "Vector3" and data.Pos or nil
		if not pos then
			return
		end
		local d = (typeof(data.Dir) == "Vector3" and data.Dir.Magnitude > 0.01) and data.Dir.Unit or UP
		DFX.kit().starSpark(pos, { color = DFX.PAL.SHOCK, color2 = Color3.new(1, 1, 1), size = 4, life = 0.1 })
		dustPuffs(pos, 0.5, DFX.n(5), Color3.new(1, 1, 1), 0.5, false)
		streaks(pos, d, DFX.n(6), 1, 5, 12, WIND, 0.25)
		VFX.PlaySound("DevFlyRam", pos, 1)
		VFX.ShakeAt(pos, 1, 70, 0.3)
	end

	function Effects.DevFly(char, data, isLocal)
		-- (round 90: LIGHTSPEED's and the roll's are VFX.LSX's; round 99: GODSPEED's VFX.GSX's)
		local beat = DFX.BEATS[data.Kind] or (VFX.LSX and VFX.LSX.BEATS[data.Kind]) or (VFX.GSX and VFX.GSX.BEATS[data.Kind])
		if beat then
			beat(char, data, isLocal)
		end
	end

	---------------------------------------------------------------------------
	-- the watcher: every flyer, every frame, on every screen
	---------------------------------------------------------------------------
	-- a thin trail off the end of a limb (a fist, a foot)
	function DFX.limbTrail(char, name, width, life, transp)
		local part = char:FindFirstChild(name)
		if not part then
			return nil
		end
		local tip = Vector3.new(0, -part.Size.Y / 2 + 0.15, 0)
		local a0 = Instance.new("Attachment")
		a0.Name = "DevFlyTrail"
		a0.CFrame = CFrame.new(tip + Vector3.new(0, 0, width / 2))
		a0.Parent = part
		local a1 = Instance.new("Attachment")
		a1.Name = "DevFlyTrail"
		a1.CFrame = CFrame.new(tip - Vector3.new(0, 0, width / 2))
		a1.Parent = part
		local trail = Instance.new("Trail")
		trail.Name = "DevFlyTrail"
		trail.Attachment0, trail.Attachment1 = a0, a1
		trail.Color = ColorSequence.new(DFX.PAL.CONTRAIL)
		trail.Transparency = NumberSequence.new(transp or 0.45, 1)
		trail.WidthScale = NumberSequence.new(1, 0.3)
		trail.LightEmission = 0.35
		trail.Lifetime = life
		trail.FaceCamera = true
		trail.Parent = part
		return { trail = trail, made = { trail, a0, a1 } }
	end
	-- a wide trail across the shoulders (the body itself a line)
	function DFX.bodyTrail(char, width, life, color, transp, light)
		local torso = char:FindFirstChild("Torso") or char:FindFirstChild("UpperTorso") or char:FindFirstChild("HumanoidRootPart")
		if not torso then
			return nil
		end
		local a0 = Instance.new("Attachment")
		a0.Name = "DevFlyTrail"
		a0.CFrame = CFrame.new(width / 2, 0.3, 0)
		a0.Parent = torso
		local a1 = Instance.new("Attachment")
		a1.Name = "DevFlyTrail"
		a1.CFrame = CFrame.new(-width / 2, 0.3, 0)
		a1.Parent = torso
		local trail = Instance.new("Trail")
		trail.Name = "DevFlyTrail"
		trail.Attachment0, trail.Attachment1 = a0, a1
		trail.Color = typeof(color) == "ColorSequence" and color or ColorSequence.new(color or DFX.PAL.CONTRAIL)
		trail.Transparency = NumberSequence.new({ NumberSequenceKeypoint.new(0, transp or 0.25), NumberSequenceKeypoint.new(1, 1) })
		trail.WidthScale = NumberSequence.new(1, 0)
		trail.LightEmission = light or 0.3
		trail.Lifetime = life
		trail.FaceCamera = true
		trail.Parent = torso
		return { trail = trail, made = { trail, a0, a1 } }
	end
	-- let a trail finish drawing out, then take it away
	function DFX.dropTrail(t)
		if not t then
			return
		end
		pcall(function()
			t.trail.Enabled = false
		end)
		task.delay(t.trail.Lifetime + 0.05, function()
			for _, x in t.made do
				pcall(x.Destroy, x)
			end
		end)
	end

	-- start drawing a flyer (idempotent)
	function DFX.track(char)
		if DFX.flying[char] or not char then
			return
		end
		local root = char:FindFirstChild("HumanoidRootPart")
		if not root then
			return
		end
		local st = { char = char, root = root, trails = {}, t = 0, next = {}, mine = DFX.isMine(char) }
		DFX.flying[char] = st
		st.conn = RunService.Heartbeat:Connect(function(dt)
			local ok, err = pcall(DFX.step, st, math.min(tonumber(dt) or 1 / 60, 0.1))
			if not ok then
				warn("[DevFly] " .. tostring(err))
				DFX.untrack(char)
			end
		end)
	end

	-- stop drawing him (the trails draw out, the wind dies away)
	function DFX.untrack(char)
		local st = DFX.flying[char]
		if not st then
			return
		end
		DFX.flying[char] = nil
		if st.conn then
			st.conn:Disconnect()
		end
		for key, t in st.trails do
			DFX.dropTrail(t)
			st.trails[key] = nil
		end
		if st.cone then
			st.cone(0.2)
			st.cone = nil
		end
		if st.nose then
			cleanup(st.nose, 0.4)
			st.nose = nil
		end
		if st.wake then
			st.wake.pe.Enabled = false
			cleanup(st.wake.holder, 3.5)
		end
		if st.swirl then
			st.swirl.pe.Enabled = false
			cleanup(st.swirl.holder, 3)
		end
		-- (round 90) LIGHTSPEED's on him: the sheath, the streak, the charge's sound
		if VFX.LSX then
			VFX.LSX.untrack(st)
		end
		-- (round 99) GODSPEED's: its charge, the sheath, the cone, the charge's sound (its contrail lingers)
		if VFX.GSX then
			VFX.GSX.untrack(st)
		end
		-- (round 87) his wind and any whoosh die away with him, and the point
		-- they rode on goes
		if st.ear then
			local ear = st.ear
			st.ear = nil
			for name, s in st.beds do
				tween(s, 0.4, { Volume = 0 })
				st.beds[name] = nil
			end
			for _, vo in st.voices do
				pcall(function()
					tween(vo.sound, 0.3, { Volume = 0 })
				end)
			end
			task.delay(0.45, function()
				pcall(ear.Destroy, ear)
			end)
		end
		-- (a landing took his body: it lets go by itself)
		if not (DFX.landedAt[char] and os.clock() - DFX.landedAt[char] < 2) then
			DFX.unpose(char, 0.3)
		else
			DFX.posed[char] = nil
		end
	end

	-- one frame of one flyer
	function DFX.step(st, dt)
		local char, root = st.char, st.root
		local tier = DFX.tierOf(char)
		local hum = char:FindFirstChildOfClass("Humanoid")
		if not tier or not char.Parent or not root.Parent or not hum or hum.Health <= 0 then
			DFX.untrack(char)
			return
		end
		st.t += dt
		local now = os.clock()
		local v = root.AssemblyLinearVelocity
		local speed = v.Magnitude
		local d = speed > 1 and v.Unit or root.CFrame.UpVector
		-- (round 99) GODSPEED's charge on him, and at it its own look (VFX.GSX:
		-- the sheath, the cone, the chain of booms, the contrail, the wake) in
		-- place of the flight's trails, cones and rings; his wind's the
		-- flight's (its beds by his speed: GODSPEED's roar over LIGHTSPEED's)
		if VFX.GSX then
			VFX.GSX.step(st, tier, now, dt)
		end
		local EK = DFX.kit()
		local P = DFX.PAL
		-- the pose
		local name = DFX.POSE_OF[tier]
		if VFX.CRX then
			name = VFX.CRX.poseFor(char, tier, name) -- (round 88: holding someone, the carry's poses)
		end
		local landed = DFX.landedAt[char] and now - DFX.landedAt[char] < 1.6
		if name and not landed then
			if name == "FlyHover" then
				-- (hanging there, breathing: struck again each cycle)
				local cur = DFX.posed[char]
				if not cur or cur.name ~= name or now - cur.at > 2.05 then
					DFX.pose(char, name, (cur and cur.name == name) and 0.4 or DFX.FADE_OF.Hover, 1)
				end
			elseif name == "FlyCrouch" then
				-- (struck once: the coil deepens over the charge, Hold..HoldEnd)
				local cur = DFX.posed[char]
				if not cur or cur.name ~= name then
					DFX.pose(char, name, DFX.FADE_OF.Crouch, 0.55)
				end
			else
				DFX.pose(char, name, DFX.FADE_OF[tier] or 0.25)
			end
			VFX.MuteGait(char, 0.3)
		end
		-- (round 90: LIGHTSPEED is all of these, and more - VFX.LSX)
		local light = tier == "Light"
		local fast = tier == "Fast" or tier == "Hyper" or tier == "Boost" or tier == "Dive" or light
		local hyper = tier == "Hyper" or tier == "Boost" or tier == "Dive" or light
		-- contrails off the fists and feet (fast), the body a white line (hyper)
		local want = {
			RH = fast and { "Right Arm", 0.18, 0.5 }, LH = fast and { "Left Arm", 0.16, 0.45 },
			RF = fast and { "Right Leg", 0.16, 0.45 }, LF = fast and { "Left Leg", 0.16, 0.45 },
		}
		for key, spec in want do
			if spec and not st.trails[key] then
				st.trails[key] = DFX.limbTrail(char, spec[1], spec[2], hyper and spec[3] * 2.4 or spec[3], 0.45)
			elseif not spec and st.trails[key] then
				DFX.dropTrail(st.trails[key])
				st.trails[key] = nil
			end
		end
		-- (not on his own screen: the camera rides inside that line)
		-- (round 90: at LIGHTSPEED the streak of light takes its place - VFX.LSX)
		if hyper and not light and not st.mine and not st.trails.Body then
			st.trails.Body = DFX.bodyTrail(char, 1.4, 2.2, P.CONTRAIL, 0.25, 0.3)
		elseif (not hyper or light) and st.trails.Body then
			DFX.dropTrail(st.trails.Body)
			st.trails.Body = nil
		end
		-- the comet sheath while the burst lasts (his colour washed to white, a white core)
		if tier == "Boost" and not st.mine and not st.trails.Sheath then
			local torso = char:FindFirstChild("Torso") or char:FindFirstChild("UpperTorso")
			local c = (torso and torso.Color or P.AFTERGLOW):Lerp(Color3.new(1, 1, 1), 0.5)
			st.trails.Sheath = DFX.bodyTrail(char, 2.5, 0.35, ColorSequence.new(c, P.AFTERGLOW), 0.1, 0.6)
			st.trails.Core = DFX.bodyTrail(char, 0.8, 0.35, Color3.new(1, 1, 1), 0, 1)
		elseif tier ~= "Boost" and st.trails.Sheath then
			DFX.dropTrail(st.trails.Sheath)
			DFX.dropTrail(st.trails.Core)
			st.trails.Sheath, st.trails.Core = nil, nil
		end
		-- the bow-wave at HYPERSONIC (on a nose that looks where he's going:
		-- his own root looks at the street - his chest - in level flight)
		if hyper and speed > 300 and not st.cone then
			st.nose = st.nose or EK.holder(CFrame.lookAt(root.Position, root.Position + d), nil, "DevFlyNose")
			st.cone = EK.machCone(st.nose, nil, { size = 1.25, ahead = 2.6 })
		elseif (not hyper or speed < 250) and st.cone then
			st.cone(0.2)
			st.cone = nil
		end
		if st.nose then
			st.nose.CFrame = CFrame.lookAt(root.Position - d * 0.6, root.Position + d)
		end
		-- vapor rings shed along the path, and a ghost of him (it hides the
		-- stepping of a body seen over the network at these speeds)
		if hyper and not light and speed > 300 and now >= (st.next.ring or 0) then
			st.next.ring = now + (EK.lowEnd() and 0.6 or 0.32)
			EK.vaporRings(root.Position - d * 4, d, 1, { size = 3.4, life = 0.5 })
		end
		-- (round 90) the charge's sheath and crackle, LIGHTSPEED's streak and rings
		if VFX.LSX then
			VFX.LSX.step(st, tier, speed, d, now, dt)
		end
		if hyper and not light and not st.mine and speed > 250 and now >= (st.next.ghost or 0) then
			st.next.ghost = now + (EK.lowEnd() and 0.22 or 0.11)
			EK.afterimage(char, P.CONTRAIL, 0.16, { transparency = 0.55 })
		end
		-- the ground: a dust wake rolling under him when he skims it, and the
		-- dust swirled clear in a ring under him while he hovers low
		if now >= (st.next.ground or 0) then
			st.next.ground = now + 0.06
			local hit, h = DFX.below(root.Position, 30)
			st.hit, st.h = hit, h
		end
		local hit, h = st.hit, st.h or math.huge
		local skimming = hit and speed > 55 and h < 14 and tier ~= "Hover"
		if skimming then
			if not st.wake then
				local holder = EK.holder(CFrame.new(hit.Position), nil, "DevFlyWake")
				holder.Size = Vector3.new(4, 0.4, 4)
				local pe = EK.emitter(holder, {
					tex = EK.TEX.smoke, color = { DFX.dustOf(hit), DFX.dustOf(hit):Lerp(P.DUST_DARK, 0.5) }, size = { { 0, 3.5 }, { 0.3, 9 }, { 1, 14 } },
					transp = { { 0, 0.15 }, { 0.6, 0.4 }, { 1, 1 } }, life = { 1.2, 1.8 }, speed = { 5, 12 }, spread = 75, dir = "Top",
					accel = Vector3.new(0, 4, 0), drag = 1.4, influence = 0.9, spin = { -40, 40 },
				})
				pe.Shape = Enum.ParticleEmitterShape.Box
				st.wake = { holder = holder, pe = pe }
			end
			local k = math.clamp(1.15 - h / 14, 0.15, 1)
			-- (under him every frame - the street's height from the last ray -
			-- and stretched along a frame of his path, so the bank is unbroken)
			local flatD = Vector3.new(-d.X, 0, -d.Z)
			local under = Vector3.new(root.Position.X, hit.Position.Y + 0.3, root.Position.Z)
			st.wake.holder.Size = Vector3.new(5, 0.4, math.clamp(speed * dt * 1.2, 2, 30))
			st.wake.holder.CFrame = CFrame.new(under) * CFrame.lookAt(Vector3.zero, flatD.Magnitude > 0.01 and flatD or Vector3.new(0, 0, -1)).Rotation
			-- (a puff every couple of studs he covers: a rolling bank, not dots)
			st.wake.pe.Rate = math.min(speed * 0.8, 300) * k * (EK.lowEnd() and 0.5 or 1)
			st.wake.pe.Enabled = true
		elseif st.wake then
			st.wake.pe.Enabled = false
		end
		local swirling = hit and tier == "Hover" and h < 25
		if swirling then
			if not st.swirl then
				local holder = EK.holder(CFrame.new(hit.Position), nil, "DevFlySwirl")
				local pe = EK.emitter(holder, {
					tex = EK.TEX.smoke, color = { DFX.dustOf(hit), P.DUST_LIGHT }, size = { { 0, 1.8 }, { 0.5, 4.5 }, { 1, 6 } },
					transp = { { 0, 0.3 }, { 0.5, 0.45 }, { 1, 1 } }, life = { 1.4, 2 }, speed = { 6, 10 }, spread = 12,
					drag = 1.2, accel = Vector3.new(0, 1, 0), influence = 0.9, spin = { -30, 30 },
				})
				st.swirl = { holder = holder, pe = pe, a = 0 }
			end
			-- (the emitter goes round a ring under him, blowing along it)
			local s = st.swirl
			s.a += dt * 2.2
			local r = 8 + 2 * math.sin(st.t * 0.7)
			local at = hit.Position + Vector3.new(math.cos(s.a) * r, 0.4, math.sin(s.a) * r)
			s.holder.CFrame = CFrame.lookAt(at, at + Vector3.new(-math.sin(s.a), 0, math.cos(s.a)))
			s.pe.Rate = (EK.lowEnd() and 9 or 18) * math.clamp(1.2 - h / 25, 0.2, 1)
			s.pe.Enabled = true
		elseif st.swirl then
			st.swirl.pe.Enabled = false
		end
		-- everyone else hears the wind on him (his own machine plays it flat)
		if not st.mine then
			-- (round 87: the tier beds crossfaded by his exact speed, bending
			-- with the doppler as he comes and goes, and a whoosh when he
			-- passes close - DFX.watchSound)
			st.tier = tier
			DFX.watchSound(st, root, v, speed, dt, now)
			-- feel him go over at HYPERSONIC (round 90: LIGHTSPEED harder, farther)
			if hyper and now >= (st.next.shake or 0) then
				st.next.shake = now + 0.2
				VFX.ShakeAt(root.Position, light and 1 or 0.6, light and 140 or 70, 0.3)
			end
		end
	end

	-- a looped Sound from a cue's first layer (its first take), on `parent`
	-- (a body: heard there; nil: flat, in your ears). Starts at `volume`.
	function DFX.loop(name, parent, volume)
		local cue = Config.Sounds and Config.Sounds[name]
		local layer = type(cue) == "table" and (cue.Id and cue or cue[1]) or nil
		local id = layer and layer.Id
		if type(id) == "table" then
			id = id[1]
		end
		local start = 0
		if type(id) == "table" then
			id, start = id.Id, id.Start or 0
		end
		if type(id) ~= "string" or id == "" then
			return nil
		end
		local s = Instance.new("Sound")
		s.Name = "DevFly_" .. name
		s.SoundId = id
		s.Looped = true
		s.Volume = volume or 0
		s.PlaybackSpeed = math.clamp(tonumber(layer.Speed) or 1, 0.3, 3) -- (round 86 review: the cue's pitch)
		s.RollOffMode = Enum.RollOffMode.InverseTapered
		s.RollOffMinDistance = 30
		s.RollOffMaxDistance = 700
		local group = SoundService:FindFirstChild("QuirkSFX")
		if group and group:IsA("SoundGroup") then
			s.SoundGroup = group
		end
		s.Parent = parent or SoundService
		if start > 0 then
			s.TimePosition = start
			-- (a loop restarts from 0: skip the lead-in every time round)
			local function region()
				pcall(function()
					if s.TimeLength > start + 1 then
						s.PlaybackRegionsEnabled = true
						s.LoopRegion = NumberRange.new(start, s.TimeLength)
					end
				end)
			end
			if s.IsLoaded then
				region()
			else
				s.Loaded:Once(region)
			end
		end
		s:Play()
		return s
	end
	-- a bed's own volume (the cue's first layer)
	function DFX.bedVolume(name)
		local cue = Config.Sounds and Config.Sounds[name]
		local layer = type(cue) == "table" and (cue.Id and cue or cue[1]) or nil
		return (layer and tonumber(layer.Volume)) or 1
	end

	---------------------------------------------------------------------------
	-- (round 87, flightsfx) THE SOUND OF IT. The wind rides his exact speed
	-- (beds crossfaded with equal power, each pitched and brightened by the
	-- speed, buffeting at FAST, swelling and gusting in hard turns, the cape
	-- snapping faster the faster he goes, silence into the roar at the
	-- launch). The sonic boom is built like the real thing: the N-wave's
	-- double crack, the pressure, the sub, the boom, thunder rolling on and
	-- the city answering it (echoes off the walls the rays find, late by the
	-- way round), mixed by distance; up close the world goes muffled for a
	-- beat and your ears ring. Anyone flying past you bends in pitch as he
	-- comes and goes. Mixed by Config.DevFlight.Sound; the cues are
	-- Config.Sounds DevFly*. What it puts on the game's sound groups (the
	-- muffle) always comes off again.
	---------------------------------------------------------------------------
	function DFX.SND()
		return DFX.DEV.Sound or {}
	end

	-- the air's loudness at a speed (Sound.Level: dB along a line)
	function DFX.level(speed)
		local pts = DFX.SND().Level
		if type(pts) ~= "table" or #pts == 0 then
			return 1
		end
		local db = pts[#pts][2]
		if speed <= pts[1][1] then
			db = pts[1][2]
		else
			for i = 2, #pts do
				if speed <= pts[i][1] then
					local a, b = pts[i - 1], pts[i]
					db = a[2] + (b[2] - a[2]) * (speed - a[1]) / math.max(b[1] - a[1], 1e-3)
					break
				end
			end
		end
		return 10 ^ (db / 20)
	end

	-- how much of a bed at a speed: faded in over In, out over Out, as
	-- power (so two beds crossing never dip)
	function DFX.bedMix(spec, speed)
		local k = 1
		if spec.In then
			k = DFX.ss(spec.In[1], spec.In[2], speed)
		end
		if spec.Out then
			k *= 1 - DFX.ss(spec.Out[1], spec.Out[2], speed)
		end
		return math.sqrt(math.clamp(k, 0, 1))
	end

	-- a cue's own pitch (its first layer's Speed)
	function DFX.cueSpeed(name)
		local cue = Config.Sounds and Config.Sounds[name]
		local layer = type(cue) == "table" and (cue.Id and cue or cue[1]) or nil
		return (layer and tonumber(layer.Speed)) or 1
	end

	-- a bed's pitch riding the speed: its own x (speed / Center) ^ Ride
	function DFX.bedPitch(name, spec, speed)
		local c = DFX.SND().PitchClamp or { 0.7, 1.4 }
		local ride = spec.Ride or 0
		local k = ride ~= 0 and (math.max(speed, 5) / (spec.Center or 300)) ^ ride or 1
		return DFX.cueSpeed(name) * math.clamp(k, c[1], c[2])
	end

	-- a sound group of the flight's own for what the muffle mustn't touch
	-- (the ringing in your ears), as loud as the fight sounds
	function DFX.dryGroup()
		local g = SoundService:FindFirstChild("DevFlyDry")
		if not g then
			g = Instance.new("SoundGroup")
			g.Name = "DevFlyDry"
			g.Parent = SoundService
		end
		local sfx = SoundService:FindFirstChild("QuirkSFX")
		g.Volume = (sfx and sfx:IsA("SoundGroup")) and sfx.Volume or 1
		return g
	end

	-- a cue's layers as Sounds the flight holds on to (a fly-by's pitch
	-- bends as he passes; a scream rides his body): on `parent` (a part or an
	-- attachment: heard there; nil: flat), `gain` x each layer's Volume,
	-- opts.pitch x each layer's Speed, in opts.group (else QuirkSFX). Each
	-- lets go after its Length (its last Fade s dying away), else 8 s; at
	-- most Sound.Voices at once. Returns { { sound, base, stop, done } }
	DFX.live = 0
	function DFX.voice(name, parent, gain, opts)
		opts = opts or {}
		local cue = Config.Sounds and Config.Sounds[name]
		local made = {}
		if type(cue) ~= "table" then
			return made
		end
		local layers = cue.Id and { cue } or cue
		local group = opts.group or SoundService:FindFirstChild("QuirkSFX")
		for _, layer in ipairs(layers) do
			if DFX.live >= (DFX.SND().Voices or 10) then
				break
			end
			local id, start = layer.Id, layer.Start
			if type(id) == "table" then
				local take = id[rng:NextInteger(1, math.max(#id, 1))]
				if type(take) == "table" then
					id, start = take.Id, take.Start or start
				else
					id = take
				end
			end
			if type(id) == "string" and id ~= "" then
				local sp = layer.Speed
				local base = type(sp) == "table" and rand(sp[1], sp[2] or sp[1]) or (tonumber(sp) or 1)
				local vol = math.clamp((tonumber(layer.Volume) or 0.6) * gain, 0, 8)
				local s = Instance.new("Sound")
				s.Name = "DevFly_" .. name
				s.SoundId = id
				s.PlaybackSpeed = math.max(base * (opts.pitch or 1), 0.05)
				s.Volume = (layer.FadeIn and layer.FadeIn > 0) and 0 or vol
				s.RollOffMode = Enum.RollOffMode.InverseTapered
				s.RollOffMinDistance = layer.Near or 14
				s.RollOffMaxDistance = cue.Range or 400
				if group and group:IsA("SoundGroup") then
					s.SoundGroup = group
				end
				if start then
					s.TimePosition = start
				end
				s.Parent = parent or SoundService
				s:Play()
				if layer.FadeIn and layer.FadeIn > 0 then
					tween(s, layer.FadeIn, { Volume = vol }, Enum.EasingStyle.Sine)
				end
				DFX.live += 1
				local done = false
				local function finish()
					if not done then
						done = true
						DFX.live -= 1
						pcall(s.Destroy, s)
					end
				end
				s.Ended:Connect(finish)
				-- (round 87 review: a take still downloading restarts from 0 once
				-- it loads - back to its Start, so a fly-by still peaks at the pass)
				if start and not s.IsLoaded then
					s.Loaded:Once(function()
						if not done then
							s.TimePosition = start
						end
					end)
				end
				local len = layer.Length or 8
				local fade = math.clamp(layer.Fade or 0.15, 0.05, len)
				task.delay(len - fade, function()
					-- (gone with what it rode on: just let go)
					if not done and s.Parent then
						tween(s, fade, { Volume = 0 }, Enum.EasingStyle.Sine)
						task.wait(fade + 0.02)
					end
					finish()
				end)
				task.delay(8.5, finish)
				table.insert(made, { sound = s, base = base, stop = finish, done = function()
					return done
				end })
			end
		end
		return made
	end

	-- his own held sounds (stopped with the rest of his screen when he's down)
	function DFX.hold(list)
		local M = DFX.mine
		M.held = M.held or {}
		for i = #M.held, 1, -1 do
			if M.held[i].done() then
				table.remove(M.held, i)
			end
		end
		for _, vo in list or {} do
			table.insert(M.held, vo)
		end
	end

	-- a point riding someone's body for `life` s for a sound to sit on (the
	-- watcher's own when it has one): an attachment in Terrain moved to him
	-- every frame - not his own part, so the engine's doppler (made for
	-- cars, wild at 500+ studs/s) never bends it; ours does
	function DFX.rider(char, root, life)
		local st = char and DFX.flying[char]
		if st and st.ear and st.ear.Parent then
			return st.ear
		end
		local a = Instance.new("Attachment")
		a.Name = "DevFlyVoice"
		a.Parent = workspace.Terrain
		a.WorldPosition = root.Position
		local conn = RunService.Heartbeat:Connect(function()
			if root.Parent and a.Parent then
				a.WorldPosition = root.Position
			end
		end)
		task.delay(life or 2, function()
			conn:Disconnect()
			pcall(a.Destroy, a)
		end)
		return a
	end

	-- your ears ringing (outside the muffle): `gain` of the cue, one at a time
	function DFX.ring(gain)
		gain = math.min(tonumber(gain) or 0, 1)
		if gain < 0.05 then
			return
		end
		local M = DFX.mine
		for _, vo in M.ring or {} do
			vo.stop()
		end
		M.ring = DFX.voice("DevFlyEarRing", nil, gain, { group = DFX.dryGroup() })
	end

	-- THE MUFFLE: an EqualizerSoundEffect of the flight's own on each of the
	-- game's sound groups (the fight sounds, the music, any other), its gains
	-- following one envelope (Sound.Boom.Muffle: in over Attack from Delay,
	-- held, eased back out) - then taken off again, the groups exactly as
	-- they were. A deeper one takes over; a shallower one under it is let be
	DFX.mute = { fx = {} }
	function DFX.muffleLevel(now)
		local st = DFX.mute
		if not st.t0 then
			return 0
		end
		local t = now - st.t0
		if t < 0 then
			return st.from
		end
		if t < st.attack then
			return st.from + (st.depth - st.from) * (t / st.attack)
		end
		t -= st.attack
		if t < st.hold then
			return st.depth
		end
		t -= st.hold
		if t < st.release then
			local a = t / st.release
			return st.depth * (1 - a * a * (3 - 2 * a))
		end
		return 0
	end
	function DFX.muffle(depth, opts)
		opts = opts or {}
		local MU = (DFX.SND().Boom or {}).Muffle or {}
		depth = math.clamp(tonumber(depth) or 0, 0, 1)
		local st = DFX.mute
		local now = os.clock()
		local cur = st.conn and DFX.muffleLevel(now) or 0
		-- (round 87 review: one still on its way in counts at the depth it's
		-- heading for - a shallower boom arriving in its first beat used to
		-- take its place, and the deep one never came)
		local heading = cur
		if st.conn and st.t0 and now < st.t0 + (st.attack or 0) + (st.hold or 0) then
			heading = math.max(cur, st.depth or 0)
		end
		if depth < 0.03 or (st.conn and heading >= depth) then
			return
		end
		st.from, st.depth = cur, depth
		st.t0 = now + (opts.delay or MU.Delay or 0.16)
		st.attack = math.max(MU.Attack or 0.08, 0.01)
		st.hold = opts.hold or MU.Hold or 0.32
		st.release = math.max(MU.Release or 1.1, 0.05)
		st.untilAt = st.t0 + st.attack + st.hold + st.release
		if not st.conn then
			st.conn = RunService.Heartbeat:Connect(function()
				if not pcall(DFX.muffleStep) then
					DFX.unmuffle()
				end
			end)
		end
		-- (whatever happens to the frames: it comes off)
		local token = st.untilAt
		task.delay(token - now + 0.5, function()
			if DFX.mute.untilAt == token then
				DFX.unmuffle()
			end
		end)
	end
	function DFX.muffleStep()
		local st = DFX.mute
		local now = os.clock()
		if now >= (st.untilAt or 0) then
			DFX.unmuffle()
			return
		end
		local k = DFX.muffleLevel(now)
		-- ({ Low, Mid, High } dB, as a cue's Eq)
		local eq = ((DFX.SND().Boom or {}).Muffle or {}).Eq or { 2, -12, -30 }
		for _, g in SoundService:GetChildren() do
			if g:IsA("SoundGroup") and g.Name ~= "DevFlyDry" then
				local fx = st.fx[g]
				if not fx or fx.Parent ~= g then
					fx = Instance.new("EqualizerSoundEffect")
					fx.Name = "DevFlyMuffle"
					fx.Parent = g
					st.fx[g] = fx
				end
				fx.LowGain = (eq[1] or 0) * k
				fx.MidGain = (eq[2] or 0) * k
				fx.HighGain = (eq[3] or 0) * k
			end
		end
	end
	function DFX.unmuffle()
		local st = DFX.mute
		if st.conn then
			st.conn:Disconnect()
			st.conn = nil
		end
		st.t0, st.untilAt = nil, nil
		for g, fx in st.fx do
			pcall(fx.Destroy, fx)
			st.fx[g] = nil
		end
		-- (belt and braces: none of ours left on any group)
		for _, g in SoundService:GetChildren() do
			if g:IsA("SoundGroup") then
				for _, c in g:GetChildren() do
					if c.Name == "DevFlyMuffle" then
						pcall(c.Destroy, c)
					end
				end
			end
		end
	end
	-- (round 87 review) let a muffle go from where it is over `t` s (down
	-- mid-boom: the world comes back, not snapped back in one frame)
	function DFX.muffleRelease(t)
		local st = DFX.mute
		local now = os.clock()
		local cur = st.conn and DFX.muffleLevel(now) or 0
		t = tonumber(t) or 0
		if cur < 0.02 or t <= 0.02 then
			DFX.unmuffle()
			return
		end
		st.from, st.depth, st.t0 = cur, cur, now
		st.attack, st.hold, st.release = 0.001, 0, t
		st.untilAt = now + 0.001 + t
		local token = st.untilAt
		task.delay(t + 0.5, function()
			if DFX.mute.untilAt == token then
				DFX.unmuffle()
			end
		end)
	end
	-- held voices let go over `t` s (at once: t <= 0)
	function DFX.letGo(list, t)
		t = tonumber(t) or 0
		for _, vo in list or {} do
			if t <= 0.02 or vo.done() then
				vo.stop()
			else
				pcall(tween, vo.sound, t, { Volume = 0 })
				task.delay(t + 0.02, vo.stop)
			end
		end
	end

	-- close to a boom (or a crash): the world muffled and your ears ringing,
	-- less the farther (none past MuffleWithin / RingWithin)
	-- (noRing: the last one's ringing still going - round 87 review)
	function DFX.nearBoom(d, k, noRing)
		local B = DFX.SND().Boom or {}
		local m = (1 - DFX.ss(60, B.MuffleWithin or 260, d)) * 0.8 * (k or 1)
		if m > 0.05 then
			DFX.muffle(m, { delay = 0.05 })
		end
		if not noRing then
			DFX.ring((1 - DFX.ss(60, B.RingWithin or 220, d)) * (k or 1))
		end
	end

	-- his wind ducked (Sound.Duck[kind]), then roaring back in
	function DFX.duck(kind)
		local spec = (DFX.SND().Duck or {})[kind]
		if spec then
			DFX.mine.duck = { t0 = os.clock(), to = spec.To or 0.3, hold = spec.Hold or 0.2, back = math.max(spec.Back or 0.8, 0.05), over = spec.Over or 1 }
		end
	end
	-- what his wind is at right now: up out of silence after a launch,
	-- ducked and roaring back after a boom, a burst, a brake
	function DFX.master(now)
		local M = DFX.mine
		local g = 1
		if M.launchAt then
			local L = DFX.SND().Launch or { 0.08, 0.7 }
			local t = now - M.launchAt
			if t < L[2] then
				g *= DFX.ss(L[1], L[2], t)
			else
				M.launchAt = nil
			end
		end
		local dk = M.duck
		if dk then
			local t = now - dk.t0
			local v
			if t < 0.04 then
				v = 1 + (dk.to - 1) * (t / 0.04)
			elseif t < 0.04 + dk.hold then
				v = dk.to
			else
				local u = (t - 0.04 - dk.hold) / dk.back
				if u >= 1 then
					M.duck = nil
					v = 1
				elseif u < 0.55 then
					local a = u / 0.55
					v = dk.to + (dk.over - dk.to) * a * a * (3 - 2 * a)
				else
					local a = (u - 0.55) / 0.45
					v = dk.over + (1 - dk.over) * a * a * (3 - 2 * a)
				end
			end
			g *= v
		end
		return g
	end

	-- the buffeting: the low rumble shaken at a few rates at once, harder
	-- the faster he goes and the harder he turns
	function DFX.buffet(now, speed, turnK)
		local B = DFX.SND().Buffet or {}
		local r = B.Rates or { 5.3, 8.7, 2.1 }
		local tau = math.pi * 2
		local wob = 0.5 * math.sin(now * r[1] * tau) + 0.3 * math.sin(now * r[2] * tau + 1.3) + 0.2 * math.sin(now * r[3] * tau + 2.1)
		local depth = (B.Depth or 0.45) * DFX.ss(160, 320, speed) + (B.TurnDepth or 0.35) * turnK
		return math.max(0.05, 1 + depth * wob)
	end

	-- THE CITY ANSWERING a boom at `pos`, for ears at `ears`: rays out round
	-- it at each tilt (and one at the street); each wall a ray meets sends it
	-- back from there, late by the extra way round (pos -> wall -> ears,
	-- against straight to the ears) / SoundSpeed, quieter the farther it
	-- went. Returns the strongest `taps` { at, late, gain }, soonest first
	function DFX.echoes(pos, ears, taps)
		local E = (DFX.SND().Boom or {}).Echo or {}
		local c = DFX.DEV.SoundSpeed or 980
		local reach = E.Reach or 520
		local direct = (ears - pos).Magnitude
		local found = {}
		rayParams.FilterDescendantsInstances = characterList()
		local function cast(dir)
			local ok, hit = pcall(function()
				return workspace:Raycast(pos, dir * reach, rayParams)
			end)
			if ok and hit and typeof(hit.Position) == "Vector3" then
				local r1 = (hit.Position - pos).Magnitude
				if r1 > 4 then
					local n = typeof(hit.Normal) == "Vector3" and hit.Normal or -dir
					local at = hit.Position + n * 2
					table.insert(found, {
						at = at,
						late = (r1 + (ears - at).Magnitude - direct) / c,
						gain = (E.Absorb or 0.9) * math.clamp((E.Near or 60) / math.max(r1, 1), 0.08, 1),
					})
				end
			end
		end
		local n = DFX.n(E.Rays or 10)
		local spin = rand(0, math.pi * 2)
		for _, tilt in E.Tilts or { -0.2, -0.7 } do
			for i = 0, n - 1 do
				local a = spin + i / n * math.pi * 2
				cast(Vector3.new(math.cos(a), tilt, math.sin(a)).Unit)
			end
		end
		if E.Ground ~= false then
			cast(Vector3.new(0, -1, 0))
		end
		table.sort(found, function(a, b)
			return a.gain > b.gain
		end)
		local picked = {}
		local want = taps or DFX.n(E.Taps or 4)
		for _, e in found do
			if #picked >= want then
				break
			end
			if e.late >= (E.MinLate or 0.12) and e.late <= (E.MaxLate or 3) then
				local clear = true
				for _, p in picked do
					if math.abs(p.late - e.late) < (E.Spacing or 0.07) then
						clear = false
						break
					end
				end
				if clear then
					table.insert(picked, e)
				end
			end
		end
		table.sort(picked, function(a, b)
			return a.late < b.late
		end)
		return picked
	end
	-- play them: each echo from its wall, when it gets back
	function DFX.echoSound(pos, ears, taps, gain)
		-- (round 87 review: no rays for walls too far off to be heard)
		local cue = Config.Sounds and Config.Sounds.DevFlyBoomEcho
		if (ears - pos).Magnitude > ((type(cue) == "table" and cue.Range) or 2600) then
			return {}
		end
		local list = DFX.echoes(pos, ears, taps)
		for _, e in list do
			task.delay(e.late, function()
				VFX.PlaySound("DevFlyBoomEcho", e.at, e.gain * (gain or 1))
			end)
		end
		return list
	end

	-- THE SONIC BOOM'S SOUND for one pair of ears `d` studs from it (his own:
	-- isLocal, flat in his head - only the roll stays out where it happened):
	-- its parts mixed by distance (Sound.Boom.Mix: far off the crack is gone
	-- and the low end and the roll carry; close by the windows shiver round
	-- you), then the city's echoes. `ears`: where they are. Returns the
	-- echoes and whether it came within Boom.Again of the last full one
	-- (round 87 review: then it's only the punch - see Config)
	function DFX.boomSound(pos, d, isLocal, ears)
		local B = DFX.SND().Boom or {}
		local A = B.Again or {}
		ears = ears or pos
		local now = os.clock()
		local again = now - (DFX.fullBoomAt or -math.huge) < (A.Within or 3)
		if not again then
			DFX.fullBoomAt = now
		end
		local skip = again and A.Skip or {}
		for name, m in B.Mix or {} do
			local g = m[1] + (m[2] - m[1]) * DFX.ss(m[3], m[4], d)
			if g > 0.02 and not (isLocal and name == "DevFlyBoomShiver") and not skip[name] then
				local at = pos
				if isLocal and name ~= "DevFlyBoomRoll" then
					at = nil
				elseif name == "DevFlyBoomShiver" then
					at = ears + Vector3.new(rand(-14, 14), rand(2, 8), rand(-14, 14))
				end
				VFX.PlaySound(name, at, g)
			end
		end
		if again then
			return {}, true
		end
		return DFX.echoSound(pos, ears), false
	end

	-- SOMEONE ELSE FLYING, one frame of how he sounds: the tier beds on a
	-- point that follows him (an attachment in Terrain: the engine's own
	-- doppler can't bend it - ours does, tamed), crossfaded by his exact
	-- speed, pitched by it and by the doppler (c / (c - K x how fast he's
	-- coming at you)); a whoosh riding him when he'll pass close to your ears
	DFX.WATCH_BEDS = { "DevFlyCruiseBed", "DevFlyFastBed", "DevFlyHyperBed", "DevFlyHyperRumble", "DevFlyLightBed", "DevFlyLightDeep", "GodRoar", "GodGrowl" } -- (round 90: LIGHTSPEED's two; round 99: GODSPEED's two)
	function DFX.watchSound(st, root, v, speed, dt, now)
		local SN = DFX.SND()
		if not st.ear then
			local a = Instance.new("Attachment")
			a.Name = "DevFlyVoice"
			a.Parent = workspace.Terrain
			st.ear = a
			st.beds, st.vol, st.voices, st.dop = {}, {}, {}, 1
		end
		st.ear.WorldPosition = root.Position
		local cam = workspace.CurrentCamera
		local ears = cam and cam.CFrame.Position or root.Position
		local toL = ears - root.Position
		local dist = toL.Magnitude
		-- (how fast he's coming at you against how you're moving: two flyers
		-- side by side hear each other unbent)
		local mine = Players.LocalPlayer and Players.LocalPlayer.Character
		local myRoot = mine and mine:FindFirstChild("HumanoidRootPart")
		local rel = v - (myRoot and myRoot.AssemblyLinearVelocity or Vector3.zero)
		local D = SN.Doppler or {}
		local cl = D.Clamp or { 0.72, 1.35 }
		local c = DFX.DEV.SoundSpeed or 980
		local vr = dist > 0.5 and rel:Dot(toL / dist) or 0
		local want = math.clamp(c / math.max(c - (D.K or 0.4) * vr, 1), cl[1], cl[2])
		st.dop += (want - st.dop) * math.min(1, dt * (D.Follow or 10))
		local level = DFX.level(speed) * (SN.Watch or 1.2)
		-- (out of earshot - the beds' roll-off ends at 700 - none are kept)
		local audible = dist < 760
		for _, name in DFX.WATCH_BEDS do
			local spec = (SN.Beds or {})[name]
			local k = (spec and audible) and DFX.bedMix(spec, speed) or 0
			local s = st.beds[name]
			if k > 0.01 and not s then
				s = DFX.loop(name, st.ear, 0)
				st.beds[name] = s
				st.vol[name] = 0
			end
			if s then
				st.vol[name] += (DFX.bedVolume(name) * k * level - st.vol[name]) * math.min(1, dt * (SN.Follow or 6))
				s.Volume = st.vol[name]
				s.PlaybackSpeed = DFX.bedPitch(name, spec, speed) * st.dop
				if k <= 0.01 and st.vol[name] < 0.003 then
					pcall(s.Destroy, s)
					st.beds[name] = nil
				end
			end
		end
		-- the whooshes riding him bend with him
		for i = #st.voices, 1, -1 do
			local vo = st.voices[i]
			if vo.done() then
				table.remove(st.voices, i)
			else
				vo.sound.PlaybackSpeed = math.max(vo.base * vo.pitch * st.dop, 0.05)
			end
		end
		-- a fly-by: closest to your ears within Lead s (when the whoosh
		-- peaks), close enough
		-- (round 87 review: not while something has his body - Held: a grab,
		-- a hit flinging him - he isn't flying past you, he's being thrown)
		local FB = SN.FlyBy or {}
		if cam and st.tier ~= "Held" and speed > (FB.MinSpeed or 150) and rel.Magnitude > (FB.MinSpeed or 150) and now >= (st.next.flyby or 0) then
			local tca = toL:Dot(rel) / math.max(rel:Dot(rel), 1)
			local miss = (toL - rel * tca).Magnitude
			local R = FB.Radius or { 40, 0.12 }
			local radius = R[1] + R[2] * speed
			local u = DFX.ss(FB.MinSpeed or 150, 980, speed)
			local P = FB.Pitch or { 1.08, 0.84 }
			local pitch = P[1] + (P[2] - P[1]) * u
			if tca > 0 and tca <= (FB.Lead or 0.4) / (pitch * st.dop) and miss < radius then
				st.next.flyby = now + (FB.Every or 1.2)
				DFX.flyby(st, speed, miss / radius, pitch, u)
			end
		end
	end
	-- the whoosh of him passing (louder and lower the faster he goes), riding him
	function DFX.flyby(st, speed, near, pitch, u)
		local FB = DFX.SND().FlyBy or {}
		if #st.voices >= (FB.Voices or 6) then
			return
		end
		local G = FB.Gain or { 0.45, 1.3 }
		local g = (G[1] + (G[2] - G[1]) * u) * (1 - 0.5 * near)
		local list = DFX.voice("DevFlyFlyBy", st.ear, g, { pitch = pitch })
		if speed >= (FB.Tear or 220) and not DFX.kit().lowEnd() then
			for _, vo in DFX.voice("DevFlyFlyByTear", st.ear, g * DFX.ss(FB.Tear or 220, 560, speed), { pitch = pitch }) do
				table.insert(list, vo)
			end
		end
		-- (round 90) at LIGHTSPEED: the deep whomp, the zoom and the crack of him going past
		-- (round 99: at GODSPEED, its own - the whomp, the searing boom, the crack)
		if st.tier == "Light" or st.tier == "God" then
			for _, vo in DFX.voice(st.tier == "God" and "GodPass" or "DevFlyLightPass", st.ear, g, { pitch = pitch }) do
				table.insert(list, vo)
			end
		end
		for _, vo in list do
			vo.pitch = pitch
			table.insert(st.voices, vo)
		end
	end

	-- look for flyers four times a second (your own is started at once)
	task.spawn(function()
		while true do
			task.wait(0.25)
			pcall(function()
				for _, plr in Players:GetPlayers() do
					local char = plr.Character
					if char and DFX.tierOf(char) and not DFX.flying[char] then
						DFX.track(char)
					end
				end
				-- (round 87: a muffle never outlives its envelope)
				local mu = DFX.mute
				if (mu.conn or next(mu.fx)) and os.clock() > (mu.untilAt or 0) + 0.6 then
					DFX.unmuffle()
				end
			end)
		end
	end)

	---------------------------------------------------------------------------
	-- HIS OWN SCREEN (the flight calls these every frame while he's up)
	---------------------------------------------------------------------------
	DFX.mine = { beds = {}, next = {}, specks = {}, vol = {}, idle = {}, pull = 0 }

	-- a smoothstep (0 under a, 1 over b)
	function DFX.ss(a, b, x)
		local t = math.clamp((x - a) / (b - a), 0, 1)
		return t * t * (3 - 2 * t)
	end

	-- the wind in his ears: a bed for each tier, crossfaded by his speed
	-- (no bed on the street - restraint, so the boom has room), the howl of
	-- gusts at speed, the cloth snapping while he hangs there; and at
	-- HYPERSONIC the picture tightens (a little contrast, the colour drained,
	-- the far city blurred while he stays sharp)
	-- (round 87) the beds ride his exact speed (Config.DevFlight.Sound.Beds:
	-- equal-power crossfades, each pitched and brightened by the speed); the
	-- air buffets him at FAST and tears at HYPERSONIC; a hard turn swells the
	-- wind and throws a gust; the cape snaps faster the faster he goes; after
	-- a launch the wind comes up out of silence, after a boom it's sucked out
	-- and roars back in (DFX.master)
	function DFX.frame(char, root, speed, tier, dt)
		local M = DFX.mine
		local ss = DFX.ss
		local SN = DFX.SND()
		local now = os.clock()
		local up = not (tier == "Crouch" or tier == "Land" or tier == "Crash" or tier == nil)
		-- how hard the air pulls him sideways (studs/s^2): a turn, a bank
		local v = root.AssemblyLinearVelocity
		local pull = 0
		if M.lastV and dt > 0 and speed > 20 and v.Magnitude > 1 then
			local dv = (v - M.lastV) / dt
			local along = v.Unit
			pull = (dv - along * dv:Dot(along)).Magnitude
		end
		M.lastV = v
		M.pull += (math.min(pull, 6000) - M.pull) * math.min(1, dt * 8)
		local G = SN.Gust or {}
		local turnK = math.clamp(M.pull / ((G.Turn or 900) * 1.6), 0, 1)
		local master = DFX.master(now)
		local level = DFX.level(speed) * (1 + (G.Swell or 0.35) * turnK)
		local low = DFX.kit().lowEnd()
		for name, spec in SN.Beds or {} do
			local k = up and DFX.bedMix(spec, speed) or 0
			local s = M.beds[name]
			if k > 0.01 and not s then
				s = DFX.loop(name, nil, 0)
				M.beds[name] = s
				M.vol[name] = 0
			end
			if s then
				local target = DFX.bedVolume(name) * k * level * 0.85
				M.vol[name] = (M.vol[name] or 0) + (target - (M.vol[name] or 0)) * math.min(1, dt * (SN.Follow or 6))
				-- (the buffet and the duck act on what's heard at once; the
				-- speed's ride is smoothed)
				s.Volume = M.vol[name] * (spec.Buffet and DFX.buffet(now, speed, turnK) or 1) * master
				s.PlaybackSpeed = DFX.bedPitch(name, spec, speed)
				if spec.Bright and not low then
					local eq = s:FindFirstChild("DevFlyBright")
					if not eq then
						eq = Instance.new("EqualizerSoundEffect")
						eq.Name = "DevFlyBright"
						eq.Parent = s
					end
					local cen = spec.Center or 300
					eq.HighGain = spec.Bright[1] + (spec.Bright[2] - spec.Bright[1]) * ss(cen * 0.5, cen * 1.6, speed) + 3 * turnK
				end
				-- (silent a while: let it go - a new one when it's wanted)
				if k <= 0.01 and M.vol[name] < 0.003 then
					M.idle[name] = M.idle[name] or now
					if now - M.idle[name] > (SN.Idle or 1.5) then
						pcall(s.Destroy, s)
						M.beds[name], M.idle[name] = nil, nil
					end
				else
					M.idle[name] = nil
				end
			end
		end
		if up and master > 0.05 and speed > (G.MinSpeed or 150) and tier ~= "Hover" then
			if now >= (M.next.gust or 0) then
				local every = G.Every or { 2, 4 }
				M.next.gust = now + rand(every[1], every[2])
				VFX.PlaySound("DevFlyGust", nil, math.clamp(speed / 320, 0.5, 1.2) * master)
			elseif M.pull > (G.Turn or 900) and now >= (M.next.turnGust or 0) then
				-- (a hard turn: the air tearing past him)
				M.next.turnGust = now + (G.TurnGap or 0.6)
				M.next.gust = math.max(M.next.gust, now + 1)
				VFX.PlaySound("DevFlyGust", nil, math.clamp(M.pull / (G.Turn or 900) * 0.6, 0.5, 1.3) * master)
			end
		end
		-- the cape: flapping faster the faster he goes, lost under the roar
		local C = SN.Cape or {}
		-- (timed from the last flap at the rate of right now: speeding up out
		-- of a hover, it quickens at once)
		local R = C.Rate or { 1, 8, 450 }
		local rate = (R[1] + (R[2] - R[1]) * ss(0, R[3], speed)) * (low and 0.5 or 1)
		M.flapJit = M.flapJit or rand(0.7, 1.3)
		if up and master > 0.05 and now - (M.lastFlap or 0) >= M.flapJit / math.max(rate, 0.2) then
			M.lastFlap, M.flapJit = now, rand(0.7, 1.3)
			local mask = C.Masked or { 450, 700 }
			local g = (0.55 + 0.45 * ss(40, 300, speed)) * (1 - 0.6 * ss(mask[1], mask[2], speed)) * master
			VFX.PlaySound(speed >= (C.Fast or 160) and "DevFlyFlutterFast" or "DevFlyFlutter", nil, g)
		end
		local cam = workspace.CurrentCamera
		local k = ss(380, 520, speed)
		if k > 0.01 and not M.grade then
			local lighting = game:GetService("Lighting")
			local cc = Instance.new("ColorCorrectionEffect")
			cc.Name = "DevFlyGrade"
			cc.Parent = lighting
			local dof = Instance.new("DepthOfFieldEffect")
			dof.Name = "DevFlyFocus"
			dof.FarIntensity = 0
			dof.NearIntensity = 0
			dof.InFocusRadius = 30
			dof.Parent = lighting
			M.grade, M.dof = cc, dof
		end
		if M.grade then
			M.grade.Contrast = 0.08 * k
			M.grade.Saturation = -0.1 * k
			M.dof.FarIntensity = 0.3 * k
			M.dof.FocusDistance = (cam and root) and math.clamp((cam.CFrame.Position - root.Position).Magnitude, 4, 60) or 18
		end
		-- (round 90) LIGHTSPEED on his screen: the grade, the bloom, the stars
		if VFX.LSX then
			VFX.LSX.frame(char, root, speed, tier, dt, cam)
		end
		-- (round 99) GODSPEED on his screen: the colour pushed hot, the power
		-- streaks (VFX.GSX)
		if VFX.GSX then
			VFX.GSX.frame(char, root, speed, tier, dt, cam)
		end
	end

	-- specks of air streaming past the camera (parallax even in an empty
	-- sky): thin white lines hanging in the world ahead of him, stretched
	-- by his speed, each put back out ahead once he's passed it
	function DFX.specks(cam, root, v, dt)
		local M = DFX.mine
		local speed = v.Magnitude
		local want = speed > 70 and DFX.n(26) or 0
		local list = M.specks
		while #list > want do
			local gone = table.remove(list)
			pcall(gone.Destroy, gone)
		end
		if want == 0 or not cam or not root then
			return
		end
		local d = v.Unit
		local camPos = cam.CFrame.Position
		local k = math.clamp((speed - 70) / 450, 0, 1)
		local len = math.clamp(speed * 0.035, 1, 22)
		local right = d:Cross(math.abs(d.Y) < 0.95 and UP or Vector3.new(1, 0, 0)).Unit
		local up2 = right:Cross(d).Unit
		local function place(p, far)
			local at = root.Position + d * (far and rand(60, 140) or rand(10, 140)) + right * rand(-28, 28) + up2 * rand(-18, 18)
			p:SetAttribute("At", at)
		end
		while #list < want do
			local p = newPart(Vector3.new(0.07, 0.07, 1), CFrame.new(root.Position), Color3.new(1, 1, 1), Enum.Material.Neon)
			p.Name = "DevFlySpeck"
			place(p, false)
			table.insert(list, p)
		end
		for _, p in list do
			local at = p:GetAttribute("At")
			-- (passed: out ahead again)
			if typeof(at) ~= "Vector3" or (at - camPos):Dot(d) < -2 or (at - root.Position).Magnitude > 220 then
				place(p, true)
				at = p:GetAttribute("At")
			end
			p.Size = Vector3.new(0.07, 0.07, len)
			p.CFrame = CFrame.lookAt(at, at + d)
			p.Transparency = 1 - 0.55 * k
		end
	end

	-- down: everything of his own screen goes (the wind dies away)
	function DFX.stopMine(fade)
		local M = DFX.mine
		fade = fade or 0.5
		for name, s in M.beds do
			M.beds[name] = nil
			tween(s, fade, { Volume = 0 })
			cleanup(s, fade + 0.05)
		end
		for _, p in M.specks do
			pcall(p.Destroy, p)
		end
		table.clear(M.specks)
		for _, key in { "grade", "dof" } do
			if M[key] then
				pcall(M[key].Destroy, M[key])
				M[key] = nil
			end
		end
		-- (round 87) the muffle off the game's sounds (the groups exactly as
		-- they were), the ringing stopped, the wind's state forgotten
		-- (round 87 review: let go over the fade, not cut - a crash's landing
		-- stops the flight 1.45 s in, mid-ring; Off mid-boom popped the muffle)
		DFX.muffleRelease(fade)
		DFX.letGo(M.ring, fade)
		DFX.letGo(M.held, fade)
		M.ring, M.held, M.duck, M.launchAt, M.lastV, M.pull = nil, nil, nil, nil, nil, 0
		table.clear(M.vol)
		table.clear(M.idle)
		-- (round 90) LIGHTSPEED's too (the stars, the grade, the charge's sound)
		if VFX.LSX then
			VFX.LSX.stopMine(fade)
		end
		-- (round 99) and GODSPEED's (the grade, the bloom, the streaks, the charge's sound)
		if VFX.GSX then
			VFX.GSX.stopMine(fade)
		end
	end
end

---------------------------------------------------------------------------
-- (round 89) FLIGHTBOOM on every screen (Effects.DevFly: Bomb, Shaft;
-- Effects.DevCarry: ThrowLand). THE BOMB: the round-86 crash underneath it
-- at the bomb's size (its crater, the dust burst, the debris ring, the wisp,
-- his pose, the muffle and the ringing, the city's echoes, the camera
-- swallowed by the dust) and over it the blast - a white flash, the fireball
-- blooming and rolling up into its smoke column, a shock dome swelling off
-- the street and the front racing out along it, fire round the rim, a wall
-- of dust rolling out down the street, the street's chunks thrown out hard,
-- embers coming back down, the scorch left behind - the deepest boom
-- (DevFlyBomb on the boom's sub and roll: late by how far off you are, as
-- the crash's is), the world muffled, and everyone near shaken hard. At a
-- wall (the mach burst's): the same blast stood on the wall, glass and
-- brick thrown back out and in. ALL THE WAY DOWN: the roof bursting in,
-- each floor giving way as he gets to it (a shock ring, its slab's chunks
-- driven down, its dust, the crunch), the dust left hanging in the shaft.
-- THE THROW'S LANDING: a body-sized crater, the dust thrown up, chunks, the
-- thump (the one thrown: their own screen hit). Half as much on a low-end
-- machine. (Its own block: the main chunk is at its local limit.)
---------------------------------------------------------------------------
do
	local FBX = { FIRE = Color3.fromRGB(255, 206, 150), SCORCH = Color3.fromRGB(30, 24, 22) }
	VFX.FBX = FBX
	function FBX.n(x)
		return VFX.EngineKit and VFX.EngineKit.count(x) or x
	end
	-- a dome of air swelling off the blast (the shock front everyone sees)
	function FBX.dome(pos, from, to, life, color)
		local p = newPart(Vector3.one * from, CFrame.new(pos), color, Enum.Material.ForceField, Enum.PartType.Ball)
		p.Name = "FlightBombDome"
		p.Transparency = 0.15
		tween(p, life, { Size = Vector3.one * to, Transparency = 1 }, Enum.EasingStyle.Quad, Enum.EasingDirection.Out)
		cleanup(p, life + 0.05)
		return p
	end
	-- the fire blooming out of the blast and gone (no smoke: his own screen)
	function FBX.fire(center, R)
		for i = 1, FBX.n(10) do
			local off = rng:NextUnitVector() * rand(0.1, 0.45) * R
			off = Vector3.new(off.X, math.abs(off.Y) * 0.6, off.Z)
			local ball = newPart(Vector3.one * R * 0.15, CFrame.new(center), FIRE[(i % #FIRE) + 1], Enum.Material.Neon, Enum.PartType.Ball)
			ball.Name = "FlightBombFire"
			ball.Transparency = 0.15
			local d = rand(0, 0.05)
			tween(ball, 0.14, { Size = Vector3.one * R * rand(0.35, 0.6), CFrame = CFrame.new(center + off) }, Enum.EasingStyle.Quad, Enum.EasingDirection.Out, d)
			tween(ball, 0.26, { Size = Vector3.one * R * 0.05, CFrame = CFrame.new(center + off * 1.5 + UP * R * 0.3), Transparency = 1 }, Enum.EasingStyle.Quad, Enum.EasingDirection.In, d + 0.14)
			cleanup(ball, d + 0.45)
		end
	end
	-- the fire round the rim, going off as the blast gets there
	function FBX.rim(ground, R, n)
		for i = 1, n do
			local a = i / n * math.pi * 2 + rand(-0.2, 0.2)
			local at = ground + Vector3.new(math.cos(a), 0, math.sin(a)) * R * rand(0.75, 1) + UP * 2
			task.delay(rand(0.02, 0.12), function()
				Flame.burst(at, 3 + R * 0.18, 10)
			end)
		end
	end

	-- THE BOMB (data: Pos, Radius, K, Speed; a wall's: Wall, Normal)
	function FBX.bomb(char, data, isLocal)
		local D = VFX.DFX
		local pos = typeof(data.Pos) == "Vector3" and data.Pos or nil
		if not pos or not D then
			return
		end
		local R = math.clamp(tonumber(data.Radius) or 14, 4, 30)
		local k = math.clamp(tonumber(data.K) or 0, 0, 1)
		local wall = data.Wall == true
		local n = (wall and typeof(data.Normal) == "Vector3" and data.Normal.Magnitude > 0.01) and data.Normal.Unit or UP
		local P = D.PAL
		local EK = VFX.EngineKit
		local cam = workspace.CurrentCamera
		local near = cam and (cam.Focus.Position - pos).Magnitude or 0
		local shake = ((Config.DevFlight or {}).Bomb or {}).Shake or { 3.4, 420 }
		local ground, dust = pos, P.DUST
		if not wall then
			-- (the crash underneath it, the bomb's size - its dust burst on his
			-- own screen no bigger than OwnDust: he's in the middle of it)
			local own = ((Config.DevFlight or {}).Bomb or {}).OwnDust or 14
			D.BEATS.Crash(char, { Pos = pos, Radius = math.min(R, 24), Speed = data.Speed, Dust = isLocal and math.min(R, own) or nil }, isLocal)
			local hit = D.below(pos + UP * 3, 10)
			if hit then
				ground = hit.Position
			end
			dust = D.dustOf(hit)
		end
		local center = ground + n * R * 0.25
		-- the flash and the fireball (white-hot, the fire mass rolling up into
		-- its column). (His own camera is right in it: there it's the fire
		-- blooming round him and gone - no smoke column; the crash's dust has
		-- his screen - so the blast doesn't hide where he is for a second)
		D.flashBall(center, R * 0.8, R * 2.4, 0.16)
		if isLocal then
			FBX.fire(center, R)
		else
			toonExplosion(center, math.clamp(R / 6, 1.6, 4), { NoDebris = true, NoScorch = wall, SmokeLife = 1.8 + 0.8 * k })
		end
		-- the shock: a dome off the street, the front racing out along it, the rings
		FBX.dome(ground, R * 0.5, R * 3.4, 0.5, P.SHOCK)
		shockDisc(ground + n * 0.5, n, R * 2.5, R * 14, 0.7, P.SHOCK)
		billboardRing(center, R, R * 10, P.SHOCK, 6, 0.7)
		billboardRing(center, R * 0.6, R * 6, FBX.FIRE, 8, 0.45)
		-- fire round the rim, embers coming back down
		FBX.rim(ground + n * 0.5 - UP * 0.5, R, FBX.n(wall and 4 or 8))
		emberCloud(center + n * R * 0.4, R * 1.2, 3 + k, math.floor(80 + 120 * k))
		-- the street (or the wall) thrown out hard
		local colors = { dust:Lerp(P.CONCRETE_DARK, 0.5), P.CONCRETE, P.CONCRETE_DARK, P.CRATER }
		D.chunks(ground + n * 1.5, n, 30, { spread = wall and 0.9 or 1.4, speed = { 70, 150 + 60 * k }, size = { 0.8, 2.8 }, up = wall and 0.4 or 1.1, life = 3.8, colors = colors })
		if wall then
			D.chunks(ground - n * 2, -n, 16, { spread = 0.7, speed = { 90, 170 }, size = { 0.6, 2 }, up = 0.2, life = 3, colors = colors })
			D.glass(ground + n, n, 16)
			EK.starSpark(ground + n, { color = P.SHOCK, color2 = Color3.new(1, 1, 1), size = 6 + R * 0.4, life = 0.14 })
			smokeBurst(ground + n * R * 0.4, dust, R * 1.4, R * 0.9, 2.6, FBX.n(40))
			D.plume(ground + n * 2, 7, math.clamp(R / 6, 1, 2))
		else
			-- the wall of dust rolling out down the street, the scorch, the cracks
			D.skirt(ground, dust, { n = 26, from = R * 0.9, reach = 70 + 30 * k, height = 3 + R / 8, life = 4.5, per = 3, lift = 0.04 })
			groundMark(ground, R * 1.15, FBX.SCORCH, 18)
			EK.cracks(ground, R * 3, 14, { crater = false, life = 10, grow = 0.25 })
		end
		-- the deepest boom, the world muffled, everyone near shaken hard: his
		-- own ears at once; everyone else's late by how far (the light first)
		if isLocal then
			VFX.PlaySound("DevFlyBomb", ground, 1)
			VFX.PlaySound("DevFlyBoomSub", ground, 1)
			VFX.PlaySound("DevFlyBoomRoll", ground, 1)
			D.muffle(1, { delay = 0.04, hold = 0.6 })
			D.ring(1)
			VFX.Hooks.Flash(FBX.FIRE, 0.18)
			VFX.ImpactFrame(0.1)
			VFX.Shake(shake[1], 1.2)
		else
			if near < 260 then
				VFX.Hooks.Flash(FBX.FIRE, 0.14)
				VFX.ImpactFrame(0.08)
			end
			VFX.ShakeAt(ground, shake[1], shake[2], 1.2)
			task.delay(math.min(near / ((Config.DevFlight or {}).SoundSpeed or 980), 1.5), function()
				VFX.PlaySound("DevFlyBomb", ground, 1)
				VFX.PlaySound("DevFlyBoomSub", ground, 1)
				VFX.PlaySound("DevFlyBoomRoll", ground, 1)
				D.nearBoom(near, 1)
			end)
		end
	end

	-- ALL THE WAY DOWN (data: Top, Bottom, Floors - each floor's height, R,
	-- Speed): the roof bursting in, then each floor as he gets to it
	function FBX.shaft(_char, data, isLocal)
		local D = VFX.DFX
		local top = typeof(data.Top) == "Vector3" and data.Top or nil
		local bottom = typeof(data.Bottom) == "Vector3" and data.Bottom or nil
		if not top or not bottom or not D then
			return
		end
		local P = D.PAL
		local EK = VFX.EngineKit
		local r = math.clamp(tonumber(data.R) or 7, 2, 12)
		local speed = math.max(tonumber(data.Speed) or 520, 100)
		local function floor(at, first)
			shockDisc(at + UP * 0.3, UP, r, r * (first and 6 or 4), 0.35, P.SHOCK)
			billboardRing(at + UP, r, r * (first and 5 or 3.5), P.SHOCK, 4, 0.3)
			EK.starSpark(at + UP, { color = P.SHOCK, color2 = Color3.new(1, 1, 1), size = first and 8 or 6, life = 0.12 })
			D.chunks(at, -UP, first and 10 or 14, { spread = 1, speed = { 30, 80 }, size = { 0.6, 2 }, up = 0, life = 2.6 })
			D.skirt(at, P.DUST, { n = 12, from = r * 0.7, reach = 16, height = 1.3, life = 2, per = 2 })
			smokeBurst(at - UP * 1.5, P.DUST, r * 1.1, r * 0.9, 1.6, FBX.n(10))
			VFX.PlaySound("DevFlyShaft", at, first and 1 or 0.9)
		end
		-- the roof: bursting in, chunks thrown up and out of the hole, its dust rising
		floor(top, true)
		D.chunks(top + UP, UP, 16, { spread = 1.1, speed = { 40, 95 }, size = { 0.6, 2 }, up = 0.8, life = 2.6 })
		smokeBurst(top + UP * 3, P.DUST, r * 1.4, r, 2.2, FBX.n(18))
		D.plume(top + UP * 2, 7, 1.4)
		-- each floor under it as he gets there ((round 89 review) at most Beats
		-- of them, BeatGap+ studs apart: down the top of an outside wall he
		-- meets every band of it - 36 beats of parts and crunches at once)
		local SH = (Config.DevFlight or {}).Shaft or {}
		local lastY, played = top.Y, 0
		for i, y in type(data.Floors) == "table" and data.Floors or {} do
			if i > 1 and type(y) == "number" and y == y and y < top.Y and y > bottom.Y and lastY - y >= (SH.BeatGap or 6) and played < (SH.Beats or 12) then
				lastY, played = y, played + 1
				local at = Vector3.new(top.X, y, top.Z)
				task.delay(math.clamp((top.Y - y) / speed, 0, 1), function()
					floor(at, false)
					if not isLocal then
						VFX.ShakeAt(at, 1.2, 120, 0.3)
					end
				end)
			end
		end
		-- the dust left hanging down the shaft
		D.plume((top + bottom) / 2, 6, math.clamp(r / 4.5, 1, 2))
		if isLocal then
			VFX.Shake(1.4, 0.35)
			VFX.ImpactFrame(0.04)
		else
			VFX.ShakeAt(top, 1.6, 160, 0.4)
		end
	end

	-- THE THROW'S LANDING (data: Target, Pos, Speed, K, Radius, Dir)
	function FBX.throwLand(_char, data)
		local D = VFX.DFX
		local g = typeof(data.Pos) == "Vector3" and data.Pos or nil
		if not g or not D then
			return
		end
		local P = D.PAL
		local EK = VFX.EngineKit
		local k = math.clamp(tonumber(data.K) or 0.5, 0, 1)
		local r = math.clamp(tonumber(data.Radius) or 3.5, 1.5, 8)
		local d = (typeof(data.Dir) == "Vector3" and data.Dir.Magnitude > 0.01) and data.Dir.Unit or Vector3.zero
		local hit = groundRay(g + UP * 2, 8)
		local dust = D.dustOf(hit)
		D.crater(g, r, hit)
		shockDisc(g + UP * 0.3, UP, 2, r * 6, 0.3, P.SHOCK)
		billboardRing(g + UP, 2, r * 5, P.SHOCK, 3, 0.3)
		EK.starSpark(g + UP, { color = P.SHOCK, color2 = Color3.new(1, 1, 1), size = 4 + 2 * k, life = 0.1 })
		D.skirt(g, dust, { n = 12, reach = 12 + 8 * k, height = 0.9 + 0.4 * k, life = 1.6 })
		D.chunks(g + UP, UP + d * 0.5, 10, { spread = 0.9, speed = { 30, 60 + 30 * k }, size = { 0.4, 1.4 }, up = 0.5, life = 2.2 })
		smokeBurst(g + UP * 1.5, dust, r * 1.4, r * 0.8, 1.4, FBX.n(16))
		rocks(g, 1, FBX.n(6))
		VFX.PlaySound("DevCarryThrowLand", g, 0.9 + 0.3 * k)
		local me = Players.LocalPlayer
		if me and data.Target ~= nil and data.Target == me.Character then
			VFX.Shake(1.6 + k, 0.5)
			VFX.ImpactFrame(0.05)
		else
			VFX.ShakeAt(g, 1.2 + k, 120, 0.4)
		end
	end

	if VFX.DFX then
		VFX.DFX.BEATS.Bomb = FBX.bomb
		VFX.DFX.BEATS.Shaft = FBX.shaft
	end
	if VFX.CRX then
		VFX.CRX.BEATS.ThrowLand = FBX.throwLand
	end
end

---------------------------------------------------------------------------
-- (round 99) CRATERS on every screen (VFX.CTX; Config.DevFlight.Crater):
-- LIGHTSPEED AND GODSPEED INTO THE GROUND - the owner: "get rid of
-- lightwipe just make the crater bigger, for both lightspeed and godspeed".
-- Round 92's LIGHTWIPE (the city wiped and flown back) is gone; the crash at
-- LIGHTSPEED is the mach burst's bomb (VFX.FBX.bomb) grown far past it, and
-- GODSPEED's is bigger again (its tier's Look: everything scaled up). The
-- flight's beat Kind Crater (his screen the moment he hits; everyone else's
-- from the server, Kit.CT):
--   THE IMPACT: a white-out (his own the longest, everyone else's by how far
--     off), the crash's own crater, dust burst, pose and sound under it all,
--     a huge fireball (white-hot core, orange shell rolling up - on his own
--     screen a fire bloom round him: he's in the middle of it) and the toon
--     fireball's smoke, a flash ball, the shock dome, the rings
--   THE CRATER: a scorched floor, slabs of street stood on end round its
--     rim leaning out, the lip of rubble thrown up round it, rubble in it,
--     cracks running out across the street - it stays a while
--   DEBRIS THROWN HIGH out of it (real chunks: they tumble and land), the
--     street thrown out hard along the ground, embers coming back down
--   THE RUN (every frame till its cloud's gone - CTX.step): the ring of
--     light racing out over the streets by the server's own law (Config
--     .DevFlight.Crater.reach - the hits and the rips go by it), the dust
--     wall rolling out behind it and hanging there, the mushroom of dust
--     climbing over the crater (fire in it at first; his own screen only its
--     cap - he's in its stem), the ground shaking near it as it goes up
--   THE BOOM (DevFlyCrater: his ears at once - the world muffled, ringing;
--     everyone else's late by the distance, flat by how far) and the shake
--     felt across the city - harder close; the cloud's rumble
--   GODSPEED's own over it (VFX.GSX.impact: the crater glowing white-hot,
--     the gold and electric-blue rings, lightning thrown up, GodImpact)
-- Half as much on a low-end machine. Everything it makes is this screen's
-- and gone after (its folder; the chunks and marks on their own timers).
-- (In a function of its own: the main chunk is at its local limit.)
---------------------------------------------------------------------------
;(function()
	local CTX = { runs = {} }
	VFX.CTX = CTX
	local DEVc = Config.DevFlight or {}
	local CC = DEVc.Crater or {}
	local WHITE = Color3.new(1, 1, 1)
	local HOT = Color3.fromRGB(255, 236, 196)
	local ORANGE = Color3.fromRGB(255, 168, 84)
	local ASH = Color3.fromRGB(108, 94, 86)
	local CAP_DARK = Color3.fromRGB(150, 130, 116)
	local CAP_LIGHT = Color3.fromRGB(212, 196, 178)
	local STEM = Color3.fromRGB(172, 154, 138)
	local SCORCHED = Color3.fromRGB(32, 26, 24)
	local BALL, CYL = Enum.PartType.Ball, Enum.PartType.Cylinder

	function CTX.low()
		return IceKit.lowEnd()
	end
	-- half as much on a low-end machine
	function CTX.n(x)
		if CTX.low() then
			return math.max(math.floor(x * 0.5 + 0.5), x > 0 and 1 or 0)
		end
		return x
	end
	-- a sane Vector3 off the wire (no NaN, nowhere absurd), or nil
	function CTX.vec(v)
		return (typeof(v) == "Vector3" and v == v and v.Magnitude < 1e6) and v or nil
	end
	-- a tier's numbers ("God", else LIGHTSPEED's)
	function CTX.spec(tier)
		return (tier == "God" and CC.God) or CC.Light or {}
	end
	function CTX.camPos()
		local cam = workspace.CurrentCamera
		return cam and cam.CFrame.Position or Vector3.zero
	end
	-- everything a run moves this frame, in one go
	function CTX.move(parts, cfs)
		if #parts == 0 then
			return
		end
		if not CTX.noBulk then
			local ok = pcall(function()
				workspace:BulkMoveTo(parts, cfs, Enum.BulkMoveMode.FireCFrameChanged)
			end)
			if ok then
				return
			end
			CTX.noBulk = true
		end
		for i, p in parts do
			p.CFrame = cfs[i]
		end
	end
	-- the boom where you are: flat, louder the nearer (Saitama's), late by the distance
	function CTX.far(name, at, gain)
		if VFX.ST and VFX.ST.far then
			VFX.ST.far(name, at, gain)
		else
			VFX.PlaySound(name, nil, gain)
		end
	end

	-- the fireball: a white-hot core swelling out of the crater, an orange
	-- shell round it, both rolling up and gone as the cloud takes over
	function CTX.fireball(g, FB)
		FB = FB or { 30, 240, Rise = 0.35, Life = 1.6 }
		local rise, life = FB.Rise or 0.35, FB.Life or 1.6
		local c = g + UP * FB[2] * 0.22
		local core = newPart(Vector3.one * FB[1], CFrame.new(c), WHITE, Enum.Material.Neon, BALL)
		core.Name = "CraterFireball"
		core.Transparency = 0.05
		tween(core, rise, { Size = Vector3.one * FB[2] * 0.78 }, Enum.EasingStyle.Quad, Enum.EasingDirection.Out)
		tween(core, life, { Transparency = 1, Color = ORANGE }, Enum.EasingStyle.Quad, Enum.EasingDirection.In, rise)
		cleanup(core, rise + life + 0.05)
		local shell = newPart(Vector3.one * FB[1] * 1.2, CFrame.new(c), ORANGE, Enum.Material.Neon, BALL)
		shell.Name = "CraterFireball"
		shell.Transparency = 0.35
		tween(shell, rise * 1.2, { Size = Vector3.one * FB[2] }, Enum.EasingStyle.Quad, Enum.EasingDirection.Out)
		tween(shell, life, { Transparency = 1, CFrame = CFrame.new(c + UP * FB[2] * 0.5), Color = ASH }, Enum.EasingStyle.Quad, Enum.EasingDirection.In, rise * 1.2)
		cleanup(shell, rise * 1.2 + life + 0.05)
	end

	-- THE CRATER on the street (R studs; hit: the street under it): the
	-- scorched floor, slabs stood on end round the rim leaning out, the lip
	-- of rubble thrown up round it, rubble in it, cracks running out
	function CTX.bowl(g, R, hit, B, stay)
		local D = VFX.DFX
		local P = D.PAL
		B = B or {}
		local street = (hit and hit.Instance and hit.Instance:IsA("BasePart")) and hit.Instance.Color or P.CONCRETE
		groundMark(g, R * 0.98, SCORCHED, stay)
		groundMark(g, R * 0.62, P.CRATER, stay)
		groundMark(g, R * 0.3, P.CRACK, stay)
		local n = CTX.n(B.Slabs or 22)
		local base = rand(0, math.pi * 2)
		for i = 1, n do
			local a = base + (i - 0.5) / n * math.pi * 2 + rand(-0.1, 0.1)
			local out = Vector3.new(math.cos(a), 0, math.sin(a))
			local w, h, t = rand(0.14, 0.22) * R, rand(0.1, 0.17) * R, rand(1.2, 2.6)
			local at = g + out * R * rand(0.88, 1.04) + UP * (h * 0.2)
			-- (stood on its edge across the rim, tipped back out from the hole)
			local cf = CFrame.lookAt(at, at + out) * CFrame.Angles(math.rad(rand(28, 58)), rand(-0.3, 0.3), 0)
			local slab = newPart(Vector3.new(w, h, t), cf, street:Lerp(P.CONCRETE_DARK, rand(0.15, 0.5)), Enum.Material.Slate)
			slab.Name = "CraterSlab"
			tween(slab, 2, { Transparency = 1 }, Enum.EasingStyle.Quad, Enum.EasingDirection.In, stay)
			cleanup(slab, stay + 2.1)
		end
		-- the lip: rubble thrown up in a ring just past the rim
		local nl = math.floor(n * 0.5)
		for i = 1, nl do
			local a = base + (i - 1) / math.max(nl, 1) * math.pi * 2 + rand(-0.2, 0.2)
			local out = Vector3.new(math.cos(a), 0, math.sin(a))
			local s = rand(0.12, 0.22) * R
			local at = g + out * R * rand(1.04, 1.18) + UP * s * 0.12
			local mound = newPart(Vector3.new(s * 1.6, s * 0.38, s), CFrame.lookAt(at, at + out) * CFrame.Angles(math.rad(rand(-8, 8)), 0, 0), street:Lerp(P.CRATER, rand(0.35, 0.7)), Enum.Material.Slate, BALL)
			mound.Name = "CraterLip"
			tween(mound, 2, { Transparency = 1 }, Enum.EasingStyle.Quad, Enum.EasingDirection.In, stay)
			cleanup(mound, stay + 2.1)
		end
		for _ = 1, CTX.n(8) do
			local at = g + Vector3.new(rand(-1, 1), 0, rand(-1, 1)) * R * 0.7 + UP * 0.4
			local s = rand(0.03, 0.07) * R
			local rub = newPart(Vector3.new(s * 1.3, s * 0.6, s), CFrame.new(at) * CFrame.Angles(rand(-0.5, 0.5), rand(0, 6), rand(-0.5, 0.5)),
				street:Lerp(P.CRATER, rand(0.3, 0.7)), Enum.Material.Slate)
			rub.Name = "CraterSlab"
			tween(rub, 2, { Transparency = 1 }, nil, nil, stay)
			cleanup(rub, stay + 2.1)
		end
		local EK = VFX.EngineKit
		if EK then
			EK.cracks(g, R * (B.Cracks or 2.2), 12, { crater = false, life = stay * 0.6, grow = 0.35 })
		end
	end

	-- THE CRATER (data: Pos - the street where it went off, Tier "Light" /
	-- "God", Radius; isLocal: his own screen, the moment he hits). Returns its run
	function CTX.beat(char, data, isLocal)
		local D = VFX.DFX
		local g = type(data) == "table" and CTX.vec(data.Pos) or nil
		if not g or not D then
			return nil
		end
		local tier = data.Tier == "God" and "God" or "Light"
		local T = CTX.spec(tier)
		local L = T.Look or {}
		local R = math.clamp(tonumber(data.Radius) or T.Radius or 60, 10, 200)
		R = R == R and R or (T.Radius or 60)
		-- ((round 99 review) a screen too far off to see it (the moon, deep
		-- space: Look.Range) plays none of it - no white-out, no boom, no ~800
		-- parts; his own always)
		if not isLocal and not ((CTX.camPos() - g).Magnitude <= (L.Range or 6000)) then
			return nil
		end
		local hit = D.below(g + UP * 3, 12)
		if hit then
			g = hit.Position
		end
		local dust = D.dustOf(hit)
		local near = (CTX.camPos() - g).Magnitude
		local P = D.PAL
		local EK = VFX.EngineKit
		-- THE FLASH (his own the longest; everyone else's by how far off)
		local F = L.Flash or { 0.45, 0.35, 0.1 }
		VFX.Hooks.Flash(WHITE, isLocal and F[1] or (F[2] + (F[3] - F[2]) * math.clamp(near / (L.FlashFar or 2000), 0, 1)))
		if isLocal or near < 900 then
			VFX.ImpactFrame(0.12)
		end
		-- the crash under it all: the crater's heart, the dust burst (his own
		-- no bigger than OwnDust - he's in the middle of it), his pose, its sound
		if D.BEATS and D.BEATS.Crash then
			D.BEATS.Crash(char, { Pos = g, Radius = 24, Speed = ((DEVc.Light or {}).Speed or 1400), Dust = isLocal and (L.OwnDust or 14) or nil }, isLocal)
		end
		-- THE FIREBALL
		local center = g + UP * R * 0.25
		D.flashBall(center, R * 0.6, R * 3, 0.2)
		if isLocal then
			if VFX.FBX then
				VFX.FBX.fire(center, R * 0.7)
			end
		else
			CTX.fireball(g, L.Fireball)
			toonExplosion(center, math.clamp(R / 15, 3, 5), { NoDebris = true, SmokeLife = 3 })
		end
		-- THE SHOCK: the dome swelling off the street, the disc racing out
		-- along it, the rings
		local DM = L.Dome or { 560, 0.8 }
		if VFX.FBX then
			VFX.FBX.dome(g, R, math.min(DM[1] or 560, 2000), DM[2] or 0.8, P.SHOCK)
		end
		shockDisc(g + UP * 0.6, UP, R * 2, math.min(((T.Ring or {}).Reach or 640) * 2, 2040), ((T.Ring or {}).Time or 1.1) * 0.8, P.SHOCK)
		billboardRing(g + UP * 8, R, R * 12, WHITE, 10, 0.8)
		billboardRing(g + UP * 4, R * 0.6, R * 7, ORANGE, 12, 0.5)
		if EK then
			EK.starSpark(g + UP * 10, { color = WHITE, color2 = HOT, size = R * 0.9, life = 0.3 })
		end
		-- THE CRATER on the street
		CTX.bowl(g, R, hit, L.Bowl, (L.Bowl or {}).Stay or 18)
		-- DEBRIS THROWN HIGH; the street thrown out hard along the ground; embers
		local DB = L.Debris or {}
		local colors = { dust:Lerp(P.CONCRETE_DARK, 0.5), P.CONCRETE, P.CONCRETE_DARK, P.CRATER }
		D.chunks(g + UP * 3, UP, DB.Count or 40, { spread = 0.9, speed = DB.Speed or { 150, 320 }, size = DB.Size or { 1, 4 }, up = DB.Up or 1.8, life = DB.Life or 6, colors = colors, jitter = R * 0.3 })
		D.chunks(g + UP * 2, UP, 20, { spread = 1.6, speed = { 120, 240 }, size = { 0.8, 2.6 }, up = 0.5, life = 4.5, colors = colors, jitter = R * 0.2 })
		emberCloud(g + UP * R * 0.6, R * 1.4, 5, CTX.n(L.Embers or 220))
		-- the dust wall's own smoke rolling out (the run's puffs ride its front)
		D.skirt(g, dust, { n = 18, from = R * 0.9, reach = 90 + R, height = 4 + R / 8, life = 6, per = 3, lift = 0.05 })
		-- THE RUN: the ring of light, the dust wall, the mushroom
		local run = CTX.start(g, R, T, tier, isLocal == true, dust)
		-- GODSPEED's own over it: the crater glowing, its rings, its lightning, GodImpact
		if tier == "God" and VFX.GSX and VFX.GSX.impact then
			VFX.GSX.impact(g, isLocal, near)
		end
		-- THE BOOM and the shake: his ears at once (the world muffled,
		-- ringing); everyone else's late by the distance - across the city,
		-- harder close
		local S = L.Shake or { 5, 1600, 1.6 }
		local SN = L.Sound or {}
		if isLocal then
			VFX.PlaySound(SN.Cue or "DevFlyCrater", nil, 1.15)
			D.muffle(1, { delay = 0.04, hold = 1.2 })
			D.ring(1)
			VFX.Shake(S[1] * (L.Mine or 0.8), S[3])
		else
			VFX.ShakeAt(g, S[1], S[2], S[3])
			task.delay(math.min(near / (DEVc.SoundSpeed or 980), 2.5), function()
				CTX.far(SN.Cue or "DevFlyCrater", g, 1.15)
				D.nearBoom(near, 1)
			end)
		end
		return run
	end

	-- the run: the parts made once, moved every frame in one go
	function CTX.start(g, R, T, tier, mine, dust)
		local L = T.Look or {}
		local low = CTX.low()
		local f = Instance.new("Folder")
		f.Name = "CraterFX"
		f.Parent = folder
		local M = L.Mushroom or {}
		local run = { g = g, R = R, T = T, tier = tier, mine = mine, folder = f, t0 = os.clock(), ring = {}, dust = {}, cap = {}, crown = {}, stem = {}, M = M, did = {} }
		local function part(color, material, shape, name)
			local p = newPart(Vector3.one, CFrame.new(g), color, material, shape, f)
			p.Name = name
			p.Transparency = 1
			return p
		end
		local RG = L.Ring or {}
		for _ = 1, low and (RG.Low or 18) or (RG.Segments or 36) do
			table.insert(run.ring, part(WHITE, Enum.Material.Neon, nil, "CraterRing"))
		end
		local DS = L.Dust or {}
		local nd = low and (DS.Low or 20) or (DS.Puffs or 40)
		for i = 1, nd do
			table.insert(run.dust, {
				part = part(dust:Lerp(CAP_LIGHT, rand(0, 0.35)), nil, BALL, "CraterDust"),
				a = (i - 1) / nd * math.pi * 2 + rand(-0.06, 0.06), k = i % 2 == 0 and 1 or rand(0.82, 0.9), s = rand(0.8, 1.2), lag = rand(0, 0.12),
			})
		end
		local nc = low and (M.LowCap or 8) or (M.Cap or 14)
		for i = 1, nc do
			table.insert(run.cap, {
				dark = part(CAP_DARK, nil, BALL, "CraterCloud"), light = part(CAP_LIGHT, nil, BALL, "CraterCloud"),
				a = (i - 1) / nc * math.pi * 2 + rand(-0.12, 0.12), phi = rand(0, math.pi * 2), s = rand(0.88, 1.12),
			})
		end
		for _ = 1, low and 2 or 3 do
			table.insert(run.crown, { part = part(CAP_LIGHT, nil, BALL, "CraterCloud"), off = Vector3.new(rand(-0.3, 0.3), rand(0, 0.2), rand(-0.3, 0.3)), s = rand(0.85, 1.05) })
		end
		-- (his own screen: no stem - he's standing in it, and it'd fill his view for seconds)
		if not mine then
			local ns = low and (M.LowStem or 6) or (M.Stem or 10)
			for j = 1, ns do
				table.insert(run.stem, {
					part = part(STEM:Lerp(CAP_DARK, (j / ns) * 0.5), nil, BALL, "CraterCloud"), k = (j - 0.5) / ns, wob = rand(0, math.pi * 2),
					s = rand(0.85, 1.15), off = Vector3.new(rand(-0.12, 0.12), 0, rand(-0.12, 0.12)),
				})
			end
		end
		run.glow = part(ORANGE, Enum.Material.Neon, BALL, "CraterGlow")
		run.conn = RunService.RenderStepped:Connect(function(dt)
			local ok, err = pcall(CTX.step, run, dt)
			if not ok then
				warn("[VFX.CTX] " .. tostring(err))
				CTX.stop(run, 0)
			end
		end)
		run.life = math.max(M.Life or 10, DS.Life or 6) + 0.5
		task.delay(run.life + 2, function()
			CTX.stop(run, 0)
		end)
		table.insert(CTX.runs, run)
		return run
	end

	function CTX.step(run, _dt)
		if run.stopped then
			return
		end
		local t = os.clock() - run.t0
		if t > run.life then
			CTX.stop(run, 0.6)
			return
		end
		local g, T = run.g, run.T
		local L = T.Look or {}
		local parts, cfs = {}, {}
		-- THE RING OF LIGHT racing out over the streets (the server's own law:
		-- the hits and the rips as it gets to them)
		local reachMax = (T.Ring or {}).Reach or 640
		local r = CC.reach and CC.reach(T, t) or 0
		local n = #run.ring
		if r > 2 and r < reachMax and n > 0 then
			run.ringOn = true
			local len = math.min(2 * math.pi * r / n * 1.15, 2000)
			local fade = 0.15 + 0.85 * math.clamp(r / reachMax, 0, 1) ^ 1.3
			for i, p in run.ring do
				local a = (i - 1) / n * math.pi * 2
				local out = Vector3.new(math.cos(a), 0, math.sin(a))
				p.Size = Vector3.new(len, 1.6 + r * 0.004, 2.5 + r * 0.012)
				p.Transparency = fade
				table.insert(parts, p)
				table.insert(cfs, CFrame.fromMatrix(g + out * r + UP * 1.4, Vector3.new(-out.Z, 0, out.X), UP))
			end
		elseif run.ringOn then
			run.ringOn = false
			for _, p in run.ring do
				p.Transparency = 1
			end
		end
		-- THE DUST WALL rolling out behind the ring to Dust.Reach, billowing
		-- up as it goes, hanging there, thinning
		local DS = L.Dust or {}
		local dReach = DS.Reach or 300
		local H = DS.Height or { 10, 34 }
		local life = DS.Life or 6
		for _, d in run.dust do
			local rr = math.min(CC.reach and CC.reach(T, math.max(t - 0.06 - d.lag, 0)) * 0.92 or 0, dReach * d.k)
			local p = d.part
			if rr < run.R * 0.6 or t > life then
				if p.Transparency < 1 then
					p.Transparency = 1
				end
			else
				local k = math.clamp(rr / dReach, 0, 1)
				local size = (H[1] + (H[2] - H[1]) * k) * d.s * (1 + math.max(t - 1, 0) * 0.06)
				local out = Vector3.new(math.cos(d.a), 0, math.sin(d.a))
				p.Size = Vector3.new(size * 1.6, size, size * 1.3)
				p.Transparency = math.clamp(0.2 + 0.8 * math.max(t - life * 0.45, 0) / (life * 0.55), 0.2, 1)
				table.insert(parts, p)
				table.insert(cfs, CFrame.lookAt(g + out * rr + UP * size * 0.32, g + out * (rr + 10) + UP * size * 0.32))
			end
		end
		-- THE MUSHROOM over the crater
		CTX.mushroom(run, t, parts, cfs)
		CTX.move(parts, cfs)
		-- the cloud going up: its rumble; the ground shaking near it
		if not run.did.rumble and t >= 0.8 then
			run.did.rumble = true
			CTX.far((L.Sound or {}).Rumble or "DevFlyCraterRumble", g, 1)
		end
		local RB = L.Rumble or { 0.5, 600, 3 }
		if t < (RB[3] or 3) then
			local near = (CTX.camPos() - g).Magnitude
			if near < (RB[2] or 600) then
				VFX.Shake((RB[1] or 0.5) * (1 - near / (RB[2] or 600)), 0.15)
			end
		end
	end

	-- the mushroom t s after the impact: the cap (a ring of rolling puffs -
	-- up the middle, out over the top, down the outside - a crown over it)
	-- climbing to Height and spreading to Width across, the stem under it
	-- (wide at the street: the base surge), fire in it at first (Glow); held,
	-- thinning, gone over its Life
	function CTX.mushroom(run, t, parts, cfs)
		local M = run.M
		local g = run.g
		local H, tau = M.Height or 360, M.Rise or 1.6
		local tt = math.max(t, 0)
		local hc = H * (1 - math.exp(-tt / tau))
		local Rc = (M.Width or 280) / 3.2 * (0.3 + 0.7 * (1 - math.exp(-tt / (tau * 1.25))))
		local rm = Rc * 0.55
		local life = M.Life or 10
		local alpha = math.clamp(0.05 + math.max(tt - 2.5, 0) * 0.03, 0.05, 0.35)
		alpha = alpha + (1 - alpha) * math.clamp((tt - (life - 3)) / 3, 0, 1)
		-- (the fireball first; on his own screen till the cap's climbed clear of
		-- him - low, it came down round his camera in the renders)
		if tt < (run.mine and 0.55 or 0.12) then
			alpha = 1
		end
		local glowK = math.clamp(tt / (M.Glow or 1.6), 0, 1)
		local capColor = ORANGE:Lerp(CAP_DARK, glowK ^ 0.6)
		local center = g + UP * hc
		for _, c in run.cap do
			local a = c.a + tt * 0.06
			local phi = c.phi - tt * 0.9
			local out = Vector3.new(math.cos(a), 0, math.sin(a))
			local pos = center + out * (Rc + rm * math.cos(phi)) + UP * (rm * 0.6 * math.sin(phi))
			local d = math.max(rm * 2.3 * c.s, 0.5)
			c.dark.Size = Vector3.one * d
			c.light.Size = Vector3.one * d * 0.74
			c.dark.Color = capColor
			c.dark.Transparency = alpha
			c.light.Transparency = math.min(alpha + 0.06, 1)
			table.insert(parts, c.dark)
			table.insert(cfs, CFrame.new(pos))
			table.insert(parts, c.light)
			table.insert(cfs, CFrame.new(pos + UP * d * 0.24 - out * d * 0.08))
		end
		for _, c in run.crown do
			c.part.Size = Vector3.one * math.max(Rc * 1.35 * c.s, 0.5)
			c.part.Transparency = math.min(alpha + 0.04, 1)
			table.insert(parts, c.part)
			table.insert(cfs, CFrame.new(center + UP * rm * 0.5 + c.off * Rc))
		end
		local top = math.max(hc - rm * 0.4, 0)
		for _, s in run.stem do
			local d = math.max(Rc * (0.45 + 0.9 * (1 - s.k) ^ 5) * s.s, 0.5)
			local wob = Vector3.new(math.sin(tt * 0.7 + s.wob), 0, math.cos(tt * 0.6 + s.wob)) * Rc * 0.04
			s.part.Size = Vector3.one * d
			s.part.Transparency = alpha
			table.insert(parts, s.part)
			table.insert(cfs, CFrame.new(g + UP * (s.k * top) + wob + s.off * d))
		end
		local glow = run.glow
		glow.Size = Vector3.one * math.max(rm * 2.4, 0.5)
		glow.Transparency = math.max(0.15 + 0.85 * glowK, alpha)
		table.insert(parts, glow)
		table.insert(cfs, CFrame.new(center))
	end

	function CTX.stop(run, fade)
		if run.stopped then
			return
		end
		run.stopped = true
		if run.conn then
			run.conn:Disconnect()
		end
		local at = table.find(CTX.runs, run)
		if at then
			table.remove(CTX.runs, at)
		end
		local f = run.folder
		if fade and fade > 0 and f.Parent then
			for _, p in f:GetChildren() do
				if p:IsA("BasePart") and p.Transparency < 1 then
					tween(p, fade, { Transparency = 1 })
				end
			end
			f.Name = "CraterFXGone"
			task.delay(fade + 0.05, function()
				pcall(f.Destroy, f)
			end)
		else
			pcall(f.Destroy, f)
		end
	end

	if VFX.DFX then
		VFX.DFX.BEATS.Crater = CTX.beat
	end
end)()

function Effects.GearshiftRush(char, data, isLocal, ability)
	local root = charParts(char)
	if not root then return end
	local d = flatten(data.Dir, root)
	if isLocal then face(root, d); dash(root, d * 65, 0.12) end
	afterimage(char, TEAL, 0.14)
	local left = limb(char, "LeftFoot", "Left Leg")
	local right = limb(char, "RightFoot", "Right Leg")
	briefTrail(left, 0.65, MINT, 0.45, 0.09)
	briefTrail(right, 0.65, WHITE, 0.45, 0.09)
	task.wait(0.12)
	local hits = (ability and ability.Hits) or 6
	for i = 1, hits do
		if not active(char) then return end
		VFX.Pose(char, i % 2 == 0 and "RainCross" or "PunchR", 0.075)
		local hand = handPos(char, i % 2 ~= 0)
		local endPoint = hand + d * 3.5
		curveStroke({ hand - d * 0.4, hand + UP * 0.3, endPoint }, 0.16, i % 2 == 0 and MINT or WHITE, 0.11)
		if i == 3 then afterimage(char, TEAL, 0.12) end
		VFX.PlaySound("Swing", hand, 0.42)
		task.wait(0.065)
	end
	if not active(char) then return end
	VFX.Motion(char, "StLouis")
	heelArc(root, d, 4.6, math.rad(75), WHITE)
	VFX.PlaySound("Kick", root.Position + d * 3, 0.8)
end

function Effects.BlackwhipSlam(char, data, isLocal, ability)
	local root = charParts(char)
	if not root then return end
	local d = flatten(data.Dir, root)
	if isLocal then face(root, d) end
	VFX.Motion(char, "WhipBind")
	VFX.PlaySound("Blackwhip", root.Position, 0.95)
	local range = (ability and ability.Range) or 55
	for k = -1, 1 do
		local dir = (CFrame.Angles(0, math.rad(k * 15), 0) * d).Unit
		local from = root.Position + UP
		local t0 = os.clock()
		VFX.whipRope(function()
			return active(char) and handPos(char, k >= 0) or nil
		end, function()
			local t = os.clock() - t0
			local reach = t < 0.18 and t / 0.18 or math.max(0, 1 - (t - 0.24) / 0.15)
			return from + dir * range * reach
		end, 0.4, { Wave = 0.65, Grow = 0.02, Thick = 0.28, Segments = 14, Color = TEAL, OutlineColor = POWER })
	end
end

function Effects.BlackwhipBind(char, data)
	local targets = type(data.Targets) == "table" and data.Targets or {}
	local slamDelay = data.SlamDelay or 0.6
	local duration = data.Duration or 0.75
	for i, target in targets do
		local troot = typeof(target) == "Instance" and target:FindFirstChild("HumanoidRootPart")
		if troot then
			VFX.whipRope(function()
				return active(char) and handPos(char, i % 2 == 0) or nil
			end, function()
				return troot.Parent and troot.Position or nil
			end, duration, { Wave = 0.6, Grow = 0.045, Thick = 0.3, Segments = 14, Color = TEAL, OutlineColor = POWER })
			task.delay(slamDelay, function()
				if active(char) and troot.Parent then
					local g = groundPoint(troot.Position)
					shockDisc(g + UP * 0.15, UP, 2, 17, 0.24, WHITE)
					sparks(g + UP, 0.4, WHITE, POWER, 8)
					dustPuffs(g, 0.6, 4, Color3.fromRGB(198, 200, 190), 0.55, false)
					rocks(g, 0.75, 4)
					VFX.PlaySound("Smash", g, 0.8)
					VFX.ShakeAt(g, 0.9, 42, 0.16)
				end
			end)
		end
	end
end

