	---------------------------------------------------------------------------
	-- Food: eating, the snack machines, and the shopkeeper's speech bubble
	---------------------------------------------------------------------------

	function Effects.Eat(char, data)
		local root = charParts(char)
		local item = Config.Items[data.Item or ""]
		if not root or not item then
			return
		end
		VFX.Pose(char, "Drink", 0.7)
		local hand = limb(char, "RightHand", "Right Arm")
		local food
		if data.Item == "PizzaSlice" then
			food = newPart(Vector3.new(0.15, 0.9, 1.2), CFrame.new(handPos(char, true)), Color3.fromRGB(245, 200, 100), Enum.Material.SmoothPlastic)
			local wedge = Instance.new("SpecialMesh")
			wedge.MeshType = Enum.MeshType.Wedge
			wedge.Parent = food
		elseif data.Item == "WholePizza" then
			food = newPart(Vector3.new(1.8, 0.3, 1.8), CFrame.new(handPos(char, true)), Color3.fromRGB(190, 150, 100), Enum.Material.Cardboard)
		else
			food = newPart(Vector3.new(0.6, 0.8, 0.25), CFrame.new(handPos(char, true)), item.Color or Color3.new(1, 1, 1), Enum.Material.SmoothPlastic)
		end
		local t0 = os.clock()
		task.spawn(function()
			while os.clock() - t0 < 0.7 and food.Parent and hand and hand.Parent do
				food.CFrame = hand.CFrame * CFrame.new(0, -hand.Size.Y / 2 - 0.2, -0.3)
				task.wait()
			end
			food:Destroy()
		end)
		VFX.PlaySound(item.Sound or "Munch", root.Position, 1)
		task.wait(0.5)
		if root.Parent then
			sparks(root.Position, 0.35, HEAL_GREEN, Color3.new(1, 1, 1), 16)
			floatText(root.Position + UP * 3, data.Item == "WholePizza" and "FULL HP" or ("+" .. tostring(data.Heal or item.Heal)), HEAL_GREEN)
		end
	end

	-- where a snack machine stands (its feet, facing out)
	local function machineBase(machine)
		local body = typeof(machine) == "Instance" and machine:FindFirstChild("Body")
		return body and body.CFrame * CFrame.new(0, -3.2, 0) or nil
	end

	-- the snack falls off its shelf into the flap
	function Effects.Vend(_, data)
		local base = machineBase(data.Machine)
		local item = Config.Items[data.Item or ""]
		if not base then
			return
		end
		VFX.PlaySound("Vend", base.Position + UP * 3, 1)
		local snack = newPart(Vector3.new(0.5, 0.7, 0.18), base * CFrame.new(-0.5, 4.6, -1.4), item and item.Color or Color3.new(1, 1, 1))
		tween(snack, 0.4, { CFrame = base * CFrame.new(-0.5, 1.05, -1.4) * CFrame.Angles(math.rad(80), 0, 0) }, Enum.EasingStyle.Quad, Enum.EasingDirection.In)
		cleanup(snack, 0.9)
	end

	-- punched: the whole machine rocks back and forth for a moment
	local shaking = setmetatable({}, { __mode = "k" })
	function Effects.MachineHit(_, data)
		local machine = data.Machine
		local base = machineBase(machine)
		if not base or shaking[machine] then
			return
		end
		shaking[machine] = true
		VFX.PlaySound("MachineHit", base.Position + UP * 3, 1)
		sparks(base.Position + UP * 3 + base.LookVector * 1.6, 0.3, Color3.new(1, 1, 1), Color3.fromRGB(255, 200, 120), 8)
		local parts = {}
		for _, p in machine:GetDescendants() do
			if p:IsA("BasePart") then
				parts[p] = base:ToObjectSpace(p.CFrame)
			end
		end
		for i = 1, 6 do
			local tilt = CFrame.Angles(math.rad((i % 2 == 0 and 1 or -1) * (7 - i) * 0.9), 0, 0)
			for p, rel in parts do
				if p.Parent then
					p.CFrame = base * tilt * rel
				end
			end
			task.wait(0.04)
		end
		for p, rel in parts do
			if p.Parent then
				p.CFrame = base * rel
			end
		end
		shaking[machine] = nil
	end

	-- the free snack flies out of the flap and lands on the pavement
	function Effects.SnackDrop(_, data)
		local to = data.Pos
		local base = machineBase(data.Machine)
		local item = Config.Items[data.Item or ""]
		if typeof(to) ~= "Vector3" or not base then
			return
		end
		local from = (base * CFrame.new(-0.5, 1.05, -1.7)).Position
		local flying = newPart(Vector3.new(0.9, 0.9, 0.9), CFrame.new(from), item and item.Color or Color3.new(1, 1, 1))
		local t0 = os.clock()
		while os.clock() - t0 < 0.4 do
			local k = (os.clock() - t0) / 0.4
			flying.CFrame = CFrame.new(from:Lerp(to, k) + UP * math.sin(math.pi * k) * 3) * CFrame.Angles(k * 9, k * 5, 0)
			task.wait()
		end
		flying:Destroy()
		dustPuffs(to, 0.4, 3, Color3.fromRGB(220, 215, 205), 0.6, false)
		floatText(to + UP * 2, "FREE SNACK!", Color3.fromRGB(255, 220, 90))
	end

	-- a speech bubble over a shopkeeper's head (and a wave)
	local bubbles = setmetatable({}, { __mode = "k" })
	function Effects.NpcSay(_, data)
		local npc = data.Npc
		local head = typeof(npc) == "Instance" and npc:FindFirstChild("Head")
		if not head then
			return
		end
		if bubbles[npc] then
			bubbles[npc]:Destroy()
		end
		local bb = Instance.new("BillboardGui")
		bb.Name = "SpeechBubble"
		bb.Size = UDim2.fromOffset(260, 70)
		bb.StudsOffset = Vector3.new(0, 3.6, 0)
		bb.MaxDistance = 70
		bb.Adornee = head
		local box = Instance.new("TextLabel")
		box.Size = UDim2.fromScale(1, 1)
		box.BackgroundColor3 = Color3.new(1, 1, 1)
		box.Font = Enum.Font.GothamBold
		box.TextColor3 = Color3.fromRGB(30, 30, 36)
		box.TextScaled = true
		box.TextWrapped = true
		box.Text = tostring(data.Text or "")
		box.Parent = bb
		local corner = Instance.new("UICorner")
		corner.CornerRadius = UDim.new(0, 14)
		corner.Parent = box
		local pad = Instance.new("UIPadding")
		pad.PaddingLeft = UDim.new(0, 10)
		pad.PaddingRight = UDim.new(0, 10)
		pad.PaddingTop = UDim.new(0, 6)
		pad.PaddingBottom = UDim.new(0, 6)
		pad.Parent = box
		bb.Parent = folder
		bubbles[npc] = bb
		cleanup(bb, 4)
		VFX.Pose(npc, "Wave", 0.9)
		VFX.PlaySound("Bell", head.Position, 0.6)
	end

