	function Effects.Launch(_, data)
		local r = typeof(data.Target) == "Instance" and data.Target:FindFirstChild("HumanoidRootPart")
		if r then
			local g = groundPoint(r.Position)
			dustPuffs(g, 1.2, 5, Color3.fromRGB(206, 196, 186), 1, true)
			shockDisc(g + UP * 0.5, UP, 3, 18, 0.35, WIND)
			VFX.PlaySound("Launch", g, 0.8)
		end
	end

	---------------------------------------------------------------------------
	-- DISCO PARTY: a mirror ball, sweeping coloured lights, music, and
	-- everyone standing around nearby dances on the beat
	---------------------------------------------------------------------------

	local DISCO_COLORS = {
		Color3.fromRGB(255, 60, 120), Color3.fromRGB(60, 200, 255), Color3.fromRGB(255, 220, 60),
		Color3.fromRGB(120, 255, 120), Color3.fromRGB(190, 90, 255), Color3.fromRGB(255, 140, 40),
	}
	local DANCES = { "Dance1", "Dance2", "Dance3", "Dance4" }
	local BEAT = 0.5
	local discoToken = 0

	function VFX.SetDisco(on, center)
		discoToken += 1
		local token = discoToken
		local old = folder:FindFirstChild("DiscoParty")
		if old then
			old:Destroy()
		end
		local tint = game:GetService("Lighting"):FindFirstChild("DiscoTint")
		if not on then
			if tint then
				tint:Destroy()
			end
			return
		end
		center = typeof(center) == "Vector3" and center or Vector3.zero
		local party = Instance.new("Model")
		party.Name = "DiscoParty"
		party.Parent = folder
		local ballPos = center + UP * 16
		local ball = newPart(Vector3.one * 5, CFrame.new(ballPos), Color3.fromRGB(220, 224, 235), Enum.Material.Foil, Enum.PartType.Ball, party)
		ball.Reflectance = 0.7
		newPart(Vector3.new(0.15, 30, 0.15), CFrame.new(ballPos + UP * 17), Color3.fromRGB(60, 60, 66), nil, nil, party)
		local glitter = Instance.new("ParticleEmitter")
		glitter.Texture = "rbxasset://textures/particles/sparkles_main.dds"
		glitter.LightEmission = 1
		glitter.Size = NumberSequence.new(0.5, 0)
		glitter.Speed = NumberRange.new(20, 40)
		glitter.SpreadAngle = Vector2.new(180, 180)
		glitter.Lifetime = NumberRange.new(0.3, 0.6)
		glitter.Rate = 40
		glitter.Parent = ball
		local beams = {}
		for i = 1, 6 do
			local b = newPart(Vector3.new(0.6, 0.6, 30), CFrame.new(ballPos), DISCO_COLORS[i], Enum.Material.Neon, nil, party)
			b.Transparency = 0.55
			local light = Instance.new("PointLight")
			light.Color = DISCO_COLORS[i]
			light.Range = 18
			light.Brightness = 2
			light.Parent = b
			beams[i] = b
		end
		local music = Instance.new("Sound")
		music.SoundId = Config.Music and Config.Music.Disco or ""
		music.Looped = true
		music.Volume = 0.7
		music.RollOffMaxDistance = 260
		music.RollOffMinDistance = 30
		music.Parent = ball
		music:Play()
		if not tint then
			tint = Instance.new("ColorCorrectionEffect")
			tint.Name = "DiscoTint"
			tint.Parent = game:GetService("Lighting")
		end
		task.spawn(function()
			local t0 = os.clock()
			local nextBeat = 0
			local beat = 0
			while discoToken == token and party.Parent do
				local t = os.clock() - t0
				ball.CFrame = CFrame.new(ballPos) * CFrame.Angles(0, t * 1.5, 0)
				for i, b in beams do
					local a = t * 1.3 + i / #beams * math.pi * 2
					local tilt = 0.55 + 0.3 * math.sin(t * 0.9 + i)
					local dir = Vector3.new(math.cos(a) * math.cos(tilt), -math.sin(tilt), math.sin(a) * math.cos(tilt))
					b.CFrame = CFrame.lookAt(ballPos + dir * 17, ballPos + dir * 34)
				end
				-- the whole scene takes on the colour of the beat
				local near = false
				local cam = workspace.CurrentCamera
				if cam then
					near = (cam.CFrame.Position - center).Magnitude < 120
				end
				tint.TintColor = near and Color3.new(1, 1, 1):Lerp(DISCO_COLORS[beat % #DISCO_COLORS + 1], 0.25) or Color3.new(1, 1, 1)
				if t >= nextBeat then
					nextBeat = t + BEAT
					beat += 1
					for i, target in characterList() do
						if target ~= folder and target:IsA("Model") then
							local root = target:FindFirstChild("HumanoidRootPart")
							local hum = target:FindFirstChildOfClass("Humanoid")
							if root and hum and hum.Health > 0 and (root.Position - center).Magnitude < 70
								and root.AssemblyLinearVelocity.Magnitude < 3 and not target:GetAttribute("Stunned") then
								VFX.Pose(target, DANCES[(beat + i) % #DANCES + 1], BEAT + 0.1)
							end
						elseif target.Name == "Dummies" then
							-- dummies dance too
							for j, dummy in target:GetChildren() do
								local root = dummy:FindFirstChild("HumanoidRootPart")
								if root and (root.Position - center).Magnitude < 70 and root.AssemblyLinearVelocity.Magnitude < 3 then
									VFX.Pose(dummy, DANCES[(beat + j) % #DANCES + 1], BEAT + 0.1)
								end
							end
						end
					end
				end
				task.wait()
			end
		end)
	end
end
addItemEffects()

---------------------------------------------------------------------------
-- Dispatcher
---------------------------------------------------------------------------

-- effects whose animation belongs to the target rather than the caster
---------------------------------------------------------------------------
-- LEMILLION: Permeation. A copy of his body drops through the street (the
-- street itself hides it as it goes under) while the real one is hidden and
-- held by the server; coming back out, a copy rises out of the ground and the
-- real body takes its place. Phasing (Permeate, the Prediction stance) makes
-- him a see-through ghost with a golden outline.
---------------------------------------------------------------------------
do
	-- (a few tables rather than many locals: this file sits at Luau's
	-- 200-locals-in-scope limit)
	local C = {
		GOLD = Color3.fromRGB(255, 214, 60),
		PHASE = Color3.fromRGB(255, 240, 196),
		RED = Color3.fromRGB(214, 40, 44),
		DIRT = Color3.fromRGB(196, 186, 172),
		SINK = 0.3,
		STRIKES = { "PunchR", "Kick", "PunchL", "PunchR", "Kick", "PunchL", "AxeKick", "FinishUppercut" },
	}
	local S = {
		hide = setmetatable({}, { __mode = "k" }), -- [char] = os.clock() it stays hidden until
		fade = setmetatable({}, { __mode = "k" }), -- [char] = os.clock() it stays see-through until
		look = {}, -- [char] = { Glow = Highlight }
	}
	local Lem = {}

	function Lem.isMine(char)
		local me = Players.LocalPlayer
		return me ~= nil and char ~= nil and me.Character == char
	end

	-- this form's version of a move (the ult has bigger ones)
	function Lem.ability(char, id)
		local quirk = Config.Quirks.Lemillion
		local set = (char:GetAttribute("UltActive") and quirk.Ult.Abilities) or quirk.Abilities
		for _, a in set do
			if a.Id == id then
				return a
			end
		end
		return Config.FindAbilityById(id) or {}
	end

	function Lem.setAlpha(char, alpha)
		for _, d in char:GetDescendants() do
			if (d:IsA("BasePart") and d.Name ~= "HumanoidRootPart") or d:IsA("Decal") then
				d.LocalTransparencyModifier = alpha
			end
		end
	end

	-- a still copy of the body as it stands right now (clothes, hair, gear)
	function Lem.double(char)
		local was = char.Archivable
		char.Archivable = true
		local ok, copy = pcall(char.Clone, char)
		char.Archivable = was
		if not ok or not copy then
			return nil
		end
		for _, d in copy:GetDescendants() do
			if d:IsA("LuaSourceContainer") or d:IsA("Sound") or d:IsA("ParticleEmitter") or d:IsA("Highlight")
				or d:IsA("BillboardGui") or d:IsA("Constraint") or d:IsA("Trail") then
				d:Destroy()
			elseif d:IsA("BasePart") then
				d.Anchored = true
				d.CanCollide = false
				d.CanQuery = false
				d.CanTouch = false
				d.CastShadow = false
				d.LocalTransparencyModifier = 0
				if d.Name == "HumanoidRootPart" then
					d.Transparency = 1
				end
			elseif d:IsA("Decal") then
				d.LocalTransparencyModifier = 0
			end
		end
		local hum = copy:FindFirstChildOfClass("Humanoid")
		if hum then
			hum.DisplayDistanceType = Enum.HumanoidDisplayDistanceType.None
			hum.HealthDisplayType = Enum.HumanoidHealthDisplayType.AlwaysOff
			hum.EvaluateStateMachine = false
		end
		copy.Name = "PhaseDouble"
		copy.Parent = folder
		return copy
	end

	-- move a copy from one place to another over `time` (eased), then remove it
	function Lem.glide(copy, from, to, time, style)
		if not copy then
			return
		end
		copy:PivotTo(from)
		task.spawn(function()
			local t0 = os.clock()
			while copy.Parent and os.clock() - t0 < time do
				local a = TweenService:GetValue(math.clamp((os.clock() - t0) / time, 0, 1), style or Enum.EasingStyle.Quad, Enum.EasingDirection.In)
				copy:PivotTo(from:Lerp(to, a))
				task.wait()
			end
			copy:Destroy()
		end)
	end

	function Lem.ripple(g, size, color)
		shockDisc(g + UP * 0.15, UP, 1, size, 0.35, color or C.PHASE)
		billboardRing(g + UP * 0.3, size * 0.3, size, C.GOLD, 2, 0.3)
		dustPuffs(g, 0.5, 3, C.DIRT, 0.5, false)
	end

	-- down through the street
	function Lem.sink(char, root, time, extraHidden)
		local copy = Lem.double(char)
		S.hide[char] = os.clock() + time + (extraHidden or 0)
		local pivot = char:GetPivot()
		Lem.glide(copy, pivot, pivot - UP * 6.5, time, Enum.EasingStyle.Quad)
		Lem.ripple(groundPoint(root.Position), 9)
		VFX.PlaySound("PhaseSink", root.Position, 1)
	end

	-- up out of it, at cf (where the real body is about to be)
	function Lem.rise(char, cf, time)
		local copy = Lem.double(char)
		local g = groundPoint(cf.Position)
		Lem.glide(copy, cf - UP * 6, cf, time, Enum.EasingStyle.Quart)
		Lem.ripple(g, 10, C.GOLD)
		streaks(g + UP, UP, 10, 1.5, 6, 14, C.PHASE, 0.3)
		dustPuffs(g, 1, 5, C.DIRT, 0.8, true)
		VFX.PlaySound("PhaseOut", g, 1)
	end

	-- hidden / see-through bodies, kept up every frame (the camera resets the
	-- local body's transparency as it zooms)
	RunService:BindToRenderStep("LemillionPhase", Enum.RenderPriority.Camera.Value + 2, function()
		local now = os.clock()
		for _, plr in Players:GetPlayers() do
			local char = plr.Character
			if not char or gone(char) then
				continue
			end
			local hidden = char:GetAttribute("Submerged") == true or (S.hide[char] or 0) > now
			local phasing = char:GetAttribute("Phasing") == true or char:GetAttribute("Countering") == true
			local faded = (S.fade[char] or 0) > now
			local st = S.look[char]
			if hidden or phasing or faded then
				if not st then
					st = {}
					S.look[char] = st
				end
				Lem.setAlpha(char, hidden and 1 or 0.55)
				if phasing and not hidden then
					if not st.Glow or not st.Glow.Parent then
						local h = Instance.new("Highlight")
						h.Name = "PhaseGlow"
						h.FillColor = C.PHASE
						h.OutlineColor = C.GOLD
						h.FillTransparency = 0.75
						h.OutlineTransparency = 0.15
						h.DepthMode = Enum.HighlightDepthMode.Occluded
						h.Adornee = char
						h.Parent = folder
						st.Glow = h
					end
				elseif st.Glow then
					st.Glow:Destroy()
					st.Glow = nil
				end
			elseif st then
				Lem.setAlpha(char, 0)
				if st.Glow then
					st.Glow:Destroy()
				end
				S.look[char] = nil
			end
		end
		for char, st in S.look do
			if gone(char) then
				if st.Glow then
					pcall(st.Glow.Destroy, st.Glow)
				end
				S.look[char] = nil
			end
		end
	end)

	POSES.PhaseDrop = { RightArm = { 160, 0, 12 }, LeftArm = { 160, 0, 12 }, RightElbow = 20, LeftElbow = 20, Waist = { 6, 0, 0 } }
	POSES.Prediction = {
		LeftArm = { 72, 0, -12 }, LeftElbow = 30, RightArm = { 10, 0, 18 }, RightElbow = 100,
		Waist = { -4, -22, 0 }, RightLeg = -10, LeftLeg = 18, LeftKnee = 22, RightKnee = 16,
	}
	POSES.AxeKick = { RightLeg = 135, LeftLeg = -18, Waist = { -12, 0, 0 }, RightArm = { -40, 0, 25 }, LeftArm = { -40, 0, 25 } }
	POSES.HammerUp = { RightArm = { 172, 0, -12 }, LeftArm = { 172, 0, -12 }, RightElbow = 40, LeftElbow = 40, Waist = { -14, 0, 0 } }
	MOTIONS.HammerDown = {
		{ pose = "HammerUp", t = 0.08, hold = 0.1 },
		{ pose = { RightArm = { 40, 0, -10 }, LeftArm = { 40, 0, -10 }, RightElbow = 10, LeftElbow = 10, Waist = { 30, 0, 0 } }, t = 0.05, hold = 0.3, style = Enum.EasingStyle.Back },
		recover = 0.25,
	}

	function Effects.DeepDive(char, data, isLocal)
		local root = charParts(char)
		if not root then
			return
		end
		local ability = Lem.ability(char, "DeepDive")
		local target = aimGround(root, data, ability.Range or 55)
		local travel = 0.12 + (target - root.Position).Magnitude / 260
		local d = flatten(data.Dir, root)
		if isLocal then
			face(root, d)
		end
		VFX.Pose(char, "PhaseDrop", C.SINK)
		Lem.sink(char, root, C.SINK, travel)
		Lem.ripple(target, 6, C.PHASE) -- the spot starts to stir
		task.wait(C.SINK + travel - 0.12)
		local dest = target + UP * 3.2
		Lem.rise(char, CFrame.lookAt(dest, dest + d), 0.14)
		task.wait(0.12)
		if char.Parent then
			VFX.Pose(char, "FinishUppercut", 0.45)
			shockDisc(target + UP * 0.5, UP, 2, (ability.Radius or 9) * 2.2, 0.3, C.GOLD)
			rocks(target, 0.8, 4)
			VFX.ShakeAt(target, 1.2, 60, 0.2)
		end
	end

	function Lem.phantomStart(char, data, isLocal, title)
		local root = charParts(char)
		if not root then
			return
		end
		local d = flatten(data.Dir, root)
		if isLocal then
			face(root, d)
			VFX.Hooks.Callout(title, C.GOLD)
		end
		VFX.Pose(char, "PhaseDrop", 0.18)
		Lem.sink(char, root, 0.18, 0.02)
	end

	function Effects.PhantomMenace(char, data, isLocal)
		Lem.phantomStart(char, data, isLocal, "PHANTOM MENACE!")
	end

	function Effects.PhantomRush(char, data, isLocal)
		Lem.phantomStart(char, data, isLocal, "BLIND SPOTS!")
	end

	-- Server: nobody was there - he phases straight ahead instead
	function Effects.PhantomMiss(char, data)
		local root = charParts(char)
		if not root then
			return
		end
		local d = flatten(data.Dir, root)
		S.hide[char] = nil
		S.fade[char] = os.clock() + 0.35
		if Lem.isMine(char) then
			dash(root, d * 110, 0.18)
		end
		for i = 0, 3 do
			task.delay(i * 0.06, function()
				if root.Parent then
					afterimage(char, C.PHASE, 0.25)
				end
			end)
		end
		VFX.PlaySound("PhantomBlink", root.Position, 0.8)
	end

	-- Server: he's out of nowhere at another blind spot, and it lands
	function Effects.PhantomStrike(char, data)
		local target = data.Target
		local troot = typeof(target) == "Instance" and target:FindFirstChild("HumanoidRootPart")
		local at = typeof(data.At) == "Vector3" and data.At
		if not troot or not at or not char.Parent then
			return
		end
		S.hide[char] = nil
		local i = tonumber(data.Index) or 1
		local pose = data.Last and (at.Y > troot.Position.Y + 1 and "AxeKick" or "FinishUppercut") or C.STRIKES[(i - 1) % #C.STRIKES + 1]
		VFX.Pose(char, pose, 0.22)
		billboardRing(at, 1, 7, C.GOLD, 3, 0.2)
		task.delay(0.03, function()
			if char.Parent then
				afterimage(char, C.PHASE, 0.3)
			end
		end)
		local hitAt = troot.Position + (at - troot.Position).Unit * 1.2
		sparks(hitAt, data.Last and 0.9 or 0.5, Color3.new(1, 1, 1), C.GOLD, data.Last and 18 or 8)
		shockDisc(hitAt, (troot.Position - at).Unit, 1, data.Last and 12 or 6, 0.2, WIND, 4)
		VFX.PlaySound("PhantomBlink", at, 0.7)
		if data.Last then
			VFX.ShakeAt(hitAt, 2, 80, 0.3)
			if nearCamera(hitAt, 70) then
				VFX.ImpactFrame(0.07)
			end
		end
	end

	function Effects.Prediction(char, data, isLocal)
		local root = charParts(char)
		if not root then
			return
		end
		if isLocal then
			face(root, flatten(data.Dir, root))
			VFX.Hooks.Callout("PREDICTION", C.GOLD)
		end
		VFX.Pose(char, "Prediction", (Lem.ability(char, "Prediction").Duration or 1))
		billboardRing(root.Position, 2, 10, C.PHASE, 3, 0.3)
		VFX.PlaySound("CounterReady", root.Position, 1)
	end

	-- Server: something hit him in the stance - it passes straight through
	-- PHANTOM GRASP (V): his arm goes down through the street...
	function Effects.PhantomGrasp(char, data, isLocal)
		local root = charParts(char)
		if not root then
			return
		end
		local d = flatten(data.Dir, root)
		if isLocal then
			face(root, d)
		end
		VFX.Pose(char, "ReachDown", 0.6)
		Lem.ripple(groundPoint(root.Position + d * 2), 6)
		VFX.PlaySound("Leap", root.Position, 0.6)
	end

	-- ...and comes up under them: hands out of the street round their legs,
	-- down to the waist, then up they go
	function Effects.PhantomGraspCatch(char, data)
		local target = typeof(data.Target) == "Instance" and data.Target or nil
		local tr = target and target:FindFirstChild("HumanoidRootPart")
		if not char or not tr then
			return
		end
		local g = groundPoint(tr.Position)
		Lem.ripple(g, 12)
		local hands = {}
		for side = -1, 1, 2 do
			local p = g + Vector3.new(side * 1.2, 0.5, 0)
			local hand = newPart(Vector3.new(0.9, 1.6, 0.9), CFrame.new(p - UP), C.RED, Enum.Material.SmoothPlastic)
			tween(hand, 0.15, { CFrame = CFrame.new(p + UP * 0.6) })
			table.insert(hands, hand)
		end
		VFX.PlaySound("Hit", g, 1)
		task.wait(data.Time or 1.2)
		for _, hand in hands do
			hand:Destroy()
		end
		Lem.ripple(g, 16)
		dustPuffs(g, 1.2, 8, C.DIRT, 0.9, true)
		streaks(g, UP, 8, 1, 6, 16, C.PHASE, 0.3)
		VFX.PlaySound("Uppercut", g, 1)
	end

	function Effects.PredictionTrigger(char, data)
		local root = charParts(char)
		if not root then
			return
		end
		VFX.PlaySound("CounterTrigger", root.Position, 1)
		afterimage(char, C.PHASE, 0.4)
		billboardRing(root.Position, 1, 14, Color3.new(1, 1, 1), 4, 0.25)
		Lem.sink(char, root, 0.3, 0.05)
		if nearCamera(root.Position, 60) then
			VFX.Hooks.Flash(Color3.new(1, 1, 1), 0.12)
		end
		if Lem.isMine(char) then
			VFX.Hooks.Callout("READ IT.", C.GOLD)
		elseif Lem.isMine(data.Attacker) then
			VFX.Hooks.Callout("COUNTERED!", C.RED)
		end
	end

	-- Server: up out of the street behind them, and one heavy punch
	function Effects.PredictionStrike(char, data)
		local target = data.Target
		local troot = typeof(target) == "Instance" and target:FindFirstChild("HumanoidRootPart")
		local at = typeof(data.At) == "Vector3" and data.At
		if not troot or not at then
			return
		end
		S.hide[char] = nil
		VFX.Motion(char, "DetroitSmash")
		local g = groundPoint(at)
		Lem.ripple(g, 8, C.GOLD)
		streaks(g + UP, UP, 6, 1, 5, 10, C.PHASE, 0.25)
		local hitAt = troot.Position + (at - troot.Position).Unit * 1.2
		sparks(hitAt, 1, Color3.new(1, 1, 1), C.GOLD, 20)
		shockDisc(hitAt, (troot.Position - at).Unit, 2, 16, 0.25, WIND, 8)
		VFX.PlaySound("HeavyHit", hitAt, 1)
		VFX.ShakeAt(hitAt, 2.5, 90, 0.3)
		if nearCamera(hitAt, 70) then
			VFX.ImpactFrame(0.08)
		end
	end

	-- R: on the ground he goes see-through and walks through walls; in the
	-- air he lets go and drops straight through everything below him
	function Effects.Permeate(char, data, isLocal)
		local root = charParts(char)
		if not root then
			return
		end
		if data and data.Air then
			if isLocal then
				VFX.Hooks.Callout("PHASE DIVE", C.GOLD)
			end
			VFX.Pose(char, "DiveBomb", 0.4)
			afterimage(char, C.PHASE, 0.35)
			streaks(root.Position, -UP, 12, 2, 6, 18, C.PHASE, 0.35)
			Lem.ripple(groundPoint(root.Position), 10)
			VFX.PlaySound("PhaseDive", root.Position, 1)
			return
		end
		if isLocal then
			VFX.Hooks.Callout("PERMEATE", C.GOLD)
		end
		VFX.Pose(char, "PhaseSink", 0.5) -- (arms up, going down through the street)
		afterimage(char, C.PHASE, 0.35)
		billboardRing(root.Position, 2, 12, C.GOLD, 3, 0.3)
		VFX.PlaySound("Permeate", root.Position, 1)
	end

	-- the ground spits him out (the dive's exit) - or a wall does, when a
	-- phase ran out with him inside it (Wall)
	function Effects.PermeateSpit(char, data)
		local g = typeof(data.Pos) == "Vector3" and data.Pos or nil
		if not g then
			return
		end
		if data.Wall then
			Lem.ripple(g + UP * 3, 6, C.GOLD)
			VFX.PlaySound("PhaseOut", g, 0.8)
			return
		end
		Lem.ripple(g, 14, C.GOLD)
		shockDisc(g + UP * 0.3, UP, 3, 30, 0.35, C.DIRT)
		rocks(g, 1.2, 10)
		dustPuffs(g, 1.6, 8, C.DIRT, 1.1, true)
		streaks(g + UP, UP, 16, 2, 8, 24, C.PHASE, 0.4)
		if char then
			VFX.Pose(char, "Skydive", 0.8)
		end
		VFX.PlaySound("PhaseSpit", g, 1)
		VFX.ShakeAt(g, 1.6, 80, 0.3)
	end

	-- the ult's finisher. The cutscene is framed on wherever the target stands
	function Lem.lineTarget(root, d, range)
		local bestDist
		for _, plr in Players:GetPlayers() do
			local c = plr.Character
			local r = c and c ~= root.Parent and c:FindFirstChild("HumanoidRootPart")
			if r then
				local v = r.Position - root.Position
				local along = v:Dot(d)
				if along > 0 and along < range and (v - d * along).Magnitude < 8 and (not bestDist or along < bestDist) then
					bestDist = along
				end
			end
		end
		local dummies = workspace:FindFirstChild("Dummies")
		for _, c in dummies and dummies:GetChildren() or {} do
			local r = c:FindFirstChild("HumanoidRootPart")
			if r then
				local v = r.Position - root.Position
				local along = v:Dot(d)
				if along > 0 and along < range and (v - d * along).Magnitude < 8 and (not bestDist or along < bestDist) then
					bestDist = along
				end
			end
		end
		return bestDist
	end

	function Effects.MillionPunch(char, data, isLocal, ability)
		local root = charParts(char)
		if not root then
			return
		end
		local d = flatten(data.Dir, root)
		if isLocal then
			face(root, d)
		end
		local range = (ability and ability.Range) or 60
		local dist = Lem.lineTarget(root, d, range)
		if not dist then
			local aim = typeof(data.Pos) == "Vector3" and data.Pos or root.Position + d * 30
			dist = math.clamp(Vector3.new(aim.X - root.Position.X, 0, aim.Z - root.Position.Z).Magnitude, 10, range)
		end
		local D = dist
		SHOTS.MillionPunch = {
			{ T = 0.55, From = { V(2.5, 1.4, -6), V(0, 0.5, 0) }, To = { V(2, 0.4, -5), V(0, -1.5, 0) }, Fov = { 55, 45 } },
			{ T = 0.55, Cut = true, From = { V(6, 1, -D + 7), V(0, 5, -D) }, To = { V(7, 0.6, -D + 9), V(0, 16, -D) }, Fov = { 70, 76 } },
			{ T = 0.95, Cut = true, From = { V(9, 26, -D + 12), V(0, 22, -D) }, To = { V(12, 16, -D + 15), V(0, 3, -D) }, Fov = { 70, 72 } },
		}
		cinematicFor(char, "MillionPunch", isLocal, (ability and ability.Name) or "ONE MILLION", C.GOLD)
		VFX.Pose(char, "PhaseDrop", 0.55)
		Lem.sink(char, root, 0.5, 0.05)
		VFX.PlaySound("UltLemillion", root.Position, 0.8)
	end

	-- Server: he bursts up out of the street under them
	function Effects.MillionPunchRise(char, data)
		local g = typeof(data.Pos) == "Vector3" and data.Pos
		if not g then
			return
		end
		S.hide[char] = nil
		local root = charParts(char)
		if root then
			Lem.rise(char, root.CFrame, 0.1)
		end
		VFX.Pose(char, "FinishUppercut", 0.4)
		shockDisc(g + UP * 0.5, UP, 3, 34, 0.4, C.GOLD)
		shockDisc(g + UP * 1, UP, 2, 22, 0.3, WIND)
		rocks(g, 1.6, 10)
		dustPuffs(g, 1.8, 8, C.DIRT, 1.2, true)
		streaks(g, UP, 22, 3, 14, 40, C.PHASE, 0.45)
		VFX.PlaySound("Smash", g, 0.8)
		VFX.ShakeAt(g, 3, 120, 0.4)
	end

	-- Server: out of thin air above them
	function Effects.MillionPunchDrop(char, data)
		local at = typeof(data.At) == "Vector3" and data.At
		if not at then
			return
		end
		S.hide[char] = nil
		VFX.Motion(char, "HammerDown")
		billboardRing(at, 2, 16, C.GOLD, 4, 0.25)
		sparks(at - UP * 3, 1.4, Color3.new(1, 1, 1), C.GOLD, 26)
		shockDisc(at - UP * 3, -UP, 3, 24, 0.3, WIND, 10)
		VFX.PlaySound("HeavySwing", at, 1)
		if nearCamera(at, 120) then
			VFX.Hooks.Flash(Color3.new(1, 1, 1), 0.15)
			VFX.ImpactFrame(0.1)
		end
	end

	-- Server: they hit the street
	function Effects.MillionPunchImpact(_, data)
		local g = typeof(data.Pos) == "Vector3" and data.Pos
		if not g then
			return
		end
		shockDisc(g + UP * 0.5, UP, 4, 60, 0.6, WIND)
		shockDisc(g + UP * 0.8, UP, 3, 38, 0.45, C.GOLD)
		billboardRing(g + UP, 4, 44, C.GOLD, 6, 0.4)
		rocks(g, 2.4, 16)
		dustPuffs(g, 2.6, 10, C.DIRT, 1.8, true)
		VFX.PlaySound("MillionPunch", g, 1)
		VFX.ShakeAt(g, 5, 260, 0.8)
	end

	-- G: (round 75) PHANTOM MENACE - (round 101, awaken_p) on the awakening
	-- kit (MoveAwakenLemillion): he drops into the street - his body hidden
	-- on every screen while a still copy of him sinks, head and shoulders
	-- left by the gather, gold rippling where he went in - and on the hit he
	-- BREACHES: up out of it to the hips, arms flung up in a V, laughing (his
	-- legs in the street); the street splashes gold - the ripples, the wall
	-- of light going up off the ring - afterimages; he steps up out of it
	-- through the hold. In the air there's no street to drop into: the breach
	-- alone. (His body's never under the street: the clip keeps his torso over
	-- it, the copy does the sinking.)
	VFX.AK.FX.Lemillion = {
		press = function(ctx)
			if not ctx.g then
				return
			end
			local L = VFX.AK.P.cfg("Lemillion")
			local char = ctx.char
			ctx.lemHide = os.clock() + ctx.hit + 0.1 -- (a safety: the hit shows him)
			S.hide[char] = ctx.lemHide
			Lem.ripple(ctx.g, 10 * ctx.scale, C.GOLD)
			VFX.PlaySound("PhaseSink", ctx.root.Position, 1)
			local copy = Lem.double(char)
			if not copy then
				return
			end
			copy.Name = "AwakenPhaseDouble"
			local pivot = char:GetPivot()
			local depth = (L.Depth or 4.2) * ctx.scale
			VFX.AK.note(ctx, "sink")
			task.spawn(function()
				-- (down fast, then slower: head and shoulders left by the gather;
				-- gone on the hit - or as soon as the run's off)
				while copy.Parent and VFX.AK.alive(ctx) do
					local t = VFX.AK.now(ctx)
					if t >= ctx.hit then
						break
					end
					-- ((round 101 review) his body's hide kept up a moment at a time
					-- while his copy sinks: on the run's own clock (a slow-motion
					-- director's camera holds it back), and gone 0.15 s after the
					-- copy is - never his body and his copy at once)
					if S.hide[char] == ctx.lemHide or (S.hide[char] or 0) < os.clock() then
						ctx.lemHide = os.clock() + 0.15
						S.hide[char] = ctx.lemHide
					end
					local a = TweenService:GetValue(math.clamp(t / math.max(ctx.hit, 0.05), 0, 1), Enum.EasingStyle.Quart, Enum.EasingDirection.Out)
					copy:PivotTo(pivot - UP * depth * a)
					task.wait()
				end
				copy:Destroy()
			end)
		end,
		hit = function(ctx)
			local char, root, s = ctx.char, ctx.root, ctx.scale
			if ctx.lemHide and S.hide[char] == ctx.lemHide then
				S.hide[char] = nil
			end
			local L = VFX.AK.P.cfg("Lemillion")
			local g = ctx.g
			VFX.PlaySound("PhaseOut", root.Position, 1)
			VFX.AK.note(ctx, "breach")
			if g then
				for _, r in L.Ripples or { { 18, 0 }, { 34, 0.06 } } do
					task.spawn(function()
						if VFX.AK.at(ctx, ctx.hit + r[2]) then
							Lem.ripple(g, r[1] * s, r[2] > 0 and C.PHASE or C.GOLD)
						end
					end)
				end
				streaks(g, UP, ctx.low and 12 or 24, 3 * s, 10 * s, 30 * s, C.PHASE, 0.5)
				dustPuffs(g, 1.4 * s, ctx.low and 4 or 8, C.DIRT, 1.2, false)
				-- the wall of light going up off the ring (none on his own lens)
				local W = L.Wall or {}
				local n, R, H = W.Count or 20, (W.Radius or 12) * s, (W.Height or 16) * s
				for i = 1, n do
					local a = i / n * math.pi * 2
					local out = Vector3.new(math.cos(a), 0, math.sin(a))
					local p = g + out * R
					if not VFX.AK.lens(ctx, p + UP * H * 0.3, 2) then
						local slab = newPart(Vector3.new(3.9 * s, 0.2, 0.3), CFrame.lookAt(p, p + out), i % 2 == 0 and C.GOLD or C.PHASE, Enum.Material.Neon)
						slab.Name = "AwakenLightWall"
						slab.Transparency = 0.25
						tween(slab, 0.35, { Size = Vector3.new(3.9 * s, H, 0.3), CFrame = CFrame.lookAt(p + UP * H / 2, p + UP * H / 2 + out) }, Enum.EasingStyle.Quad, Enum.EasingDirection.Out, i * 0.008)
						tween(slab, 0.5, { Transparency = 1, Size = Vector3.new(3.9 * s, H * 1.5, 0.1) }, Enum.EasingStyle.Quad, Enum.EasingDirection.In, 0.45)
						cleanup(slab, 1)
					end
				end
			end
			task.spawn(function()
				if VFX.AK.at(ctx, ctx.hit + (ctx.after or 0)) then
					afterimage(char, C.PHASE, 0.5)
					afterimage(char, C.GOLD, 0.3)
				end
			end)
		end,
		aura = function(ctx)
			-- gold motes, and a faint afterimage while he's running
			local stop = VFX.AK.aura(ctx, ctx.spec.Aura or "motes")
			local rec = VFX.AK.auras[ctx.char]
			if not rec or ctx.low then
				return stop
			end
			local L = VFX.AK.P.cfg("Lemillion")
			task.spawn(function()
				while VFX.AK.auras[ctx.char] == rec do
					task.wait(L.Afterimage or 0.3)
					local char, root = ctx.char, ctx.root
					if VFX.AK.auras[char] ~= rec or not (char.Parent and root.Parent) then
						break
					end
					local v = root.AssemblyLinearVelocity
					if Vector3.new(v.X, 0, v.Z).Magnitude > (L.AfterimageSpeed or 20) and (S.hide[char] or 0) < os.clock()
						and char:GetAttribute("Submerged") ~= true and char:GetAttribute("Phasing") ~= true then
						afterimage(char, C.PHASE, 0.25)
					end
				end
			end)
			return stop
		end,
		release = function(ctx)
			-- (never left hidden by this run)
			if ctx.lemHide and S.hide[ctx.char] == ctx.lemHide then
				S.hide[ctx.char] = nil
			end
		end,
		-- (tests: his body hidden on this screen right now - not a phase the kit calls)
		isHidden = function(char)
			return (S.hide[char] or 0) > os.clock()
		end,
	}

	-----------------------------------------------------------------------
	-- (round 75) PHANTOM MENACE: ENDGAME (the ult's 4). He's gone into the
	-- street; up out of it under each of them in turn, a golden pillar
	-- throwing each one up; then out of thin air over them all, and down
	-- through the middle of them - the street erupts in gold
	-----------------------------------------------------------------------
	SHOTS.PhantomEndgame = {
		{ T = 0.5, From = { V(2.5, 1.4, -6), V(0, 0.5, 0) }, To = { V(2, 0.4, -5), V(0, -1.5, 0) }, Fov = { 55, 45 } },
		-- high and wide over the street: everyone thrown up in turn
		{ T = 2.8, Cut = true, From = { V(0, 42, 34), V(0, 0, -12) }, To = { V(12, 50, 40), V(0, 4, -12) }, Fov = { 70, 74 } },
	}
	SHOTS.EndgameDrop = {
		-- (from him, 34 up: the street looking up at him coming down)
		{ T = 0.5, From = { V(12, -31, -16), "root" }, To = { V(13, -32, -15), "root" }, Fov = { 72, 60 } },
		{ T = 0.8, Cut = true, From = { V(-24, -29, -24), V(0, -33, 0) }, To = { V(-32, -24, -32), V(0, -31, 0) }, Fov = { 70, 82 }, Style = Enum.EasingStyle.Quad },
	}
	function Effects.PhantomEndgame(char, data, isLocal, ability)
		local root = charParts(char)
		if not root then
			return
		end
		local d = flatten(data.Dir, root)
		if isLocal then
			face(root, d)
			VFX.Hooks.Callout("PHANTOM MENACE... ENDGAME!!", C.GOLD)
		end
		cinematicFor(char, "PhantomEndgame", isLocal, (ability and ability.Name) or "PHANTOM MENACE: ENDGAME", C.GOLD)
		VFX.Pose(char, "PhaseDrop", 0.5)
		Lem.sink(char, root, 0.45, 6) -- (gone till he comes up: EndgameRise / EndgameDrop)
		Lem.ripple(groundPoint(root.Position), 26, C.GOLD)
		VFX.PlaySound("UltLemillion", root.Position, 0.8)
	end

	-- Server: up out of the street under one of them
	function Effects.EndgameRise(char, data)
		local g = typeof(data.Pos) == "Vector3" and data.Pos
		if not g then
			return
		end
		local root = charParts(char)
		local target = typeof(data.Target) == "Instance" and data.Target
		local troot = target and target:FindFirstChild("HumanoidRootPart")
		S.hide[char] = nil
		if root then
			local look = troot and flatten(troot.Position - g, root) or root.CFrame.LookVector
			Lem.rise(char, CFrame.lookAt(g + UP * 2.6, g + UP * 2.6 + look), 0.08)
		end
		VFX.Pose(char, "FinishUppercut", 0.3)
		-- the golden pillar it comes up in
		local pillar = newPart(Vector3.new(0.2, 5, 5), CFrame.new(g + UP * 0.1) * CFrame.Angles(0, 0, math.rad(90)), C.GOLD, Enum.Material.Neon, Enum.PartType.Cylinder)
		pillar.Transparency = 0.2
		tween(pillar, 0.15, { Size = Vector3.new(40, 6, 6), CFrame = CFrame.new(g + UP * 20) * CFrame.Angles(0, 0, math.rad(90)) }, Enum.EasingStyle.Quad, Enum.EasingDirection.Out)
		tween(pillar, 0.35, { Transparency = 1, Size = Vector3.new(46, 0.5, 0.5) }, nil, nil, 0.15)
		cleanup(pillar, 0.55)
		shockDisc(g + UP * 0.5, UP, 3, 26, 0.35, C.GOLD)
		Lem.ripple(g, 12, C.PHASE)
		rocks(g, 1.2, 8)
		streaks(g, UP, 14, 2, 12, 30, C.PHASE, 0.35)
		VFX.PlaySound("PhaseOut", g, 1)
		VFX.PlaySound("Smash", g, 0.7)
		VFX.ShakeAt(g, 2, 90, 0.3)
		if Lem.isMine(char) then
			VFX.Hooks.Callout(tostring(tonumber(data.Index) or 1) .. "!", C.GOLD)
		end
		-- ...and straight back down into it
		task.delay(0.24, function()
			if (S.hide[char] or 0) < os.clock() then
				S.hide[char] = os.clock() + 2
				Lem.ripple(g, 8, C.GOLD)
			end
		end)
	end

	-- Server: out of thin air over them all, and down
	function Effects.EndgameDrop(char, data)
		local g = typeof(data.Pos) == "Vector3" and data.Pos
		local root = charParts(char)
		if not g or not root then
			return
		end
		local time = tonumber(data.Time) or 0.5
		S.hide[char] = nil
		if Lem.isMine(char) then
			VFX.CancelCinematic()
			VFX.Cinematic(char, SHOTS.EndgameDrop, { Title = "PHANTOM MENACE: ENDGAME", Color = C.GOLD, Own = true })
		end
		VFX.Pose(char, "MeteorDive", time + 0.1)
		landingMarker(g, time)
		local at = root.Position
		billboardRing(at, 2, 18, C.GOLD, 5, 0.3)
		shockDisc(at, UP, 2, 16, 0.3, C.PHASE)
		sparks(at, 1.2, Color3.new(1, 1, 1), C.GOLD, 20)
		VFX.PlaySound("HeavySwing", at, 1)
		if nearCamera(at, 120) then
			VFX.Hooks.Flash(Color3.new(1, 1, 1), 0.12)
		end
		local stop = addTrail(root, C.GOLD, 0.35, 3)
		local t0 = os.clock()
		while os.clock() - t0 < time and root.Parent do
			afterimage(char, C.PHASE, 0.2)
			streaks(root.Position, UP, 3, 1.5, 8, 14, C.GOLD, 0.2)
			task.wait(0.05)
		end
		stop(0)
	end

	-- Server: down through the middle of them - the street erupts
	function Effects.EndgameBlast(char, data)
		local g = typeof(data.Pos) == "Vector3" and data.Pos
		if not g then
			return
		end
		local r = tonumber(data.Radius) or 26
		VFX.Motion(char, "HammerDown")
		shockDisc(g + UP * 0.5, UP, 4, r * 2.6, 0.6, WIND)
		shockDisc(g + UP * 0.8, UP, 3, r * 1.8, 0.45, C.GOLD)
		billboardRing(g + UP, 4, r * 1.8, C.GOLD, 8, 0.45)
		Lem.ripple(g, r * 1.4, C.GOLD)
		-- golden columns bursting up out of the street all round
		for i = 1, 12 do
			local a = i / 12 * math.pi * 2 + rand(-0.2, 0.2)
			local p = groundPoint(g + Vector3.new(math.cos(a), 0, math.sin(a)) * rand(r * 0.3, r * 0.9) + UP * 4)
			local h = rand(14, 30)
			task.delay(i * 0.02, function()
				local col = newPart(Vector3.new(0.2, 2.6, 2.6), CFrame.new(p) * CFrame.Angles(0, 0, math.rad(90)), i % 2 == 0 and C.GOLD or C.PHASE, Enum.Material.Neon, Enum.PartType.Cylinder)
				tween(col, 0.15, { Size = Vector3.new(h, 2.6, 2.6), CFrame = CFrame.new(p + UP * h / 2) * CFrame.Angles(0, 0, math.rad(90)) }, Enum.EasingStyle.Quad, Enum.EasingDirection.Out)
				tween(col, 0.45, { Transparency = 1, Size = Vector3.new(h * 1.2, 0.3, 0.3) }, nil, nil, 0.2)
				cleanup(col, 0.7)
				rocks(p, 0.8, 3)
			end)
		end
		rocks(g, 2.6, 18)
		dustPuffs(g, 2.8, 12, C.DIRT, 1.8, true)
		VFX.PlaySound("MillionPunch", g, 1.1)
		VFX.ShakeAt(g, 5, 260, 0.8)
		if nearCamera(g, 90) then
			VFX.ImpactFrame(0.12)
			VFX.Hooks.Flash(C.PHASE, 0.25)
		end
	end

	-- Dash: he phases through the air (see-through, golden afterimages)
	QUIRK_FX.Dash.Lemillion = function(char, root, dir)
		S.fade[char] = os.clock() + 0.25
		for i = 0, 2 do
			task.delay(i * 0.05, function()
				if root.Parent then
					afterimage(char, C.PHASE, 0.25)
				end
			end)
		end
		streaks(root.Position, -dir, 6, 1.2, 5, 10, C.GOLD, 0.2)
	end
end

---------------------------------------------------------------------------
-- SUNEATER (Tamaki Amajiki): Manifest. Everything he grows is built on
-- every screen out of parts: octopus tentacles (reddish purple, pale
-- suckers down one side), clamshells (ridged, cream and grey), a spider
-- crab's claw (orange-red, white-spotted, spiny), chicken talons (yellow,
-- scaly, black claws) and wings (white feathers) - and in the ult, the
-- Kraken, the Centaur, the Octopus Mirage with a scorpion's tail, and the
-- Plasma Cannon arm.
---------------------------------------------------------------------------
do
	local SE = {
		TENT = Color3.fromRGB(176, 72, 112),
		TENT_DARK = Color3.fromRGB(120, 40, 80),
		SUCKER = Color3.fromRGB(244, 206, 214),
		SHELL = Color3.fromRGB(236, 226, 206),
		SHELL_RIDGE = Color3.fromRGB(160, 146, 128),
		CRAB = Color3.fromRGB(214, 84, 44),
		CRAB_SPOT = Color3.fromRGB(250, 236, 220),
		TALON = Color3.fromRGB(240, 196, 70),
		CLAW = Color3.fromRGB(34, 30, 30),
		FEATHER = Color3.fromRGB(250, 248, 242),
		INK = Color3.fromRGB(46, 30, 66),
		VENOM = Color3.fromRGB(170, 80, 220),
		PLASMA = Color3.fromRGB(196, 255, 226),
		cannons = setmetatable({}, { __mode = "k" }), -- [char] = the Plasma Cannon arm while it charges
		faded = setmetatable({}, { __mode = "k" }), -- [char] = true while Octopus Mirage hides him
	}
	VFX.SE = SE

	-- weld a (new, anchored) part onto a body part so it rides along with it
	function SE.attach(to, part, c0)
		local w = Instance.new("Weld")
		w.Part0 = to
		w.Part1 = part
		w.C0 = c0 or CFrame.new()
		w.Parent = part
		part.Anchored = false
		part.Massless = true
		part.CanCollide = false
		return w
	end

	function SE.limb(char, which)
		local names = {
			RightArm = { "RightHand", "Right Arm" }, LeftArm = { "LeftHand", "Left Arm" },
			RightLeg = { "RightFoot", "Right Leg" }, LeftLeg = { "LeftFoot", "Left Leg" },
			Torso = { "UpperTorso", "Torso" },
		}
		local n = names[which]
		return n and limb(char, n[1], n[2]) or nil
	end

	-- A tentacle, blocky (a friend's sketch): a chain of square segments
	-- tapering to the tip, shades alternating so each block reads, with two
	-- suckers side by side on the underside of every segment (one when it's
	-- too thin for two). Redrawn between two points with a bend and a
	-- wriggle: t.set(from, to, bend, wiggle); t.fade(time) makes it go.
	function SE.tentacle(thick, segs, color)
		segs = segs or 8
		local base = color or SE.TENT
		local shade = base:Lerp(Color3.new(0, 0, 0), 0.16)
		local two = thick >= 0.5
		local t = { parts = {}, suckers = {}, phase = rand(0, 6) }
		for i = 1, segs do
			t.parts[i] = newPart(Vector3.new(thick, thick, 0.2), CFrame.new(), i % 2 == 0 and shade or base, Enum.Material.SmoothPlastic)
			for k = 1, two and 2 or 1 do
				table.insert(t.suckers, { seg = i, side = two and (k == 1 and -1 or 1) or 0,
					part = newPart(Vector3.new(0.05, 0.1, 0.1), CFrame.new(), SE.SUCKER, Enum.Material.SmoothPlastic, Enum.PartType.Cylinder) })
			end
		end
		local frames = {}
		function t.set(from, to, bend, wiggle)
			local span = to - from
			local len = span.Magnitude
			if len < 0.05 then
				return
			end
			local dir = span / len
			local ref = math.abs(dir.Y) < 0.9 and UP or Vector3.new(1, 0, 0)
			local side = dir:Cross(ref).Unit
			local up = side:Cross(dir).Unit
			local now = os.clock()
			local function at(k)
				local wave = math.sin(k * math.pi * 2 + now * 9 + t.phase) * (wiggle or 0.4) * k
				return from + span * k + up * math.sin(k * math.pi) * (bend or 0) + side * wave
			end
			local prev = at(0)
			for i, p in t.parts do
				local k = i / segs
				local nextP = at(k)
				local w = thick * (1 - 0.6 * (k - 1 / segs))
				local seg = nextP - prev
				local segLen = seg.Magnitude
				if segLen > 0.01 then
					-- square in section, its top toward the bend (the suckers go under)
					local fwd = seg / segLen
					local top = (up - fwd * up:Dot(fwd))
					top = top.Magnitude > 0.01 and top.Unit or side:Cross(fwd).Unit
					local cf = CFrame.fromMatrix((prev + nextP) / 2, fwd:Cross(top), top, -fwd)
					p.Size = Vector3.new(w, w, segLen + w * 0.06)
					p.CFrame = cf
					frames[i] = { cf = cf, w = w, len = segLen }
				end
				prev = nextP
			end
			for _, s in t.suckers do
				local f = frames[s.seg]
				if f then
					local disc = f.w * (s.side == 0 and 0.5 or 0.36)
					s.part.Size = Vector3.new(math.max(f.w * 0.08, 0.05), disc, math.min(disc, f.len * 0.9))
					-- a disc flat on the underside (the cylinder's axis points down)
					s.part.CFrame = f.cf * CFrame.new(s.side * f.w * 0.22, -f.w / 2 - 0.02, 0) * CFrame.Angles(0, 0, math.rad(90))
				end
			end
		end
		function t.fade(time)
			for _, p in t.parts do
				tween(p, time or 0.2, { Transparency = 1, Size = p.Size * Vector3.new(0.3, 0.3, 1) })
				cleanup(p, (time or 0.2) + 0.05)
			end
			for _, s in t.suckers do
				tween(s.part, time or 0.2, { Transparency = 1 })
				cleanup(s.part, (time or 0.2) + 0.05)
			end
		end
		return t
	end

	-- a blocky coil of tentacle round someone it's caught: two square loops
	-- (chest and hips), following them; c.set(root) each frame, c.fade(time)
	function SE.coil(thick, color)
		local c = { parts = {} }
		for i = 1, 8 do
			c.parts[i] = newPart(Vector3.one * thick, CFrame.new(), (color or SE.TENT):Lerp(Color3.new(0, 0, 0), i % 2 == 0 and 0.16 or 0), Enum.Material.SmoothPlastic)
		end
		function c.set(troot)
			local base = troot.CFrame
			for loop = 0, 1 do
				local ring = base * CFrame.new(0, loop == 0 and 0.9 or -0.5, 0) * CFrame.Angles(0, math.rad(loop * 45 + os.clock() * 40), 0)
				for k = 1, 4 do
					local p = c.parts[loop * 4 + k]
					local edge = ring * CFrame.Angles(0, math.rad(k * 90), 0) * CFrame.new(0, 0, -1.25)
					p.Size = Vector3.new(2.5 + thick, thick, thick)
					p.CFrame = edge
				end
			end
		end
		function c.fade(time)
			for _, p in c.parts do
				tween(p, time or 0.2, { Transparency = 1, Size = p.Size * 0.3 })
				cleanup(p, (time or 0.2) + 0.05)
			end
		end
		return c
	end

	-- a clamshell: a ridged half-shell (scale ~ how big across)
	function SE.shell(scale, cf)
		local model = {}
		local shell = newPart(Vector3.new(2.6, 0.9, 2.2) * scale, cf, SE.SHELL, Enum.Material.Slate)
		local mesh = Instance.new("SpecialMesh")
		mesh.MeshType = Enum.MeshType.Sphere
		mesh.Parent = shell
		table.insert(model, shell)
		for k = -2, 2 do
			local ridge = newPart(Vector3.new(0.12, 0.2, 2) * scale, cf * CFrame.new(k * 0.45 * scale, 0.36 * scale, 0) * CFrame.Angles(0, math.rad(k * 14), 0), SE.SHELL_RIDGE, Enum.Material.Slate)
			table.insert(model, ridge)
		end
		return model
	end

	-- pieces welded onto a limb for a moment, then gone
	function SE.wear(parts, to, c0s, life)
		for i, p in parts do
			SE.attach(to, p, c0s[i] or c0s[1])
		end
		if life then
			task.delay(life, function()
				for _, p in parts do
					if p.Parent then
						tween(p, 0.15, { Transparency = 1 })
						cleanup(p, 0.2)
					end
				end
			end)
		end
	end

	-- a half-shell on a fist (the clam fist)
	function SE.clamFist(char, right, life)
		local hand = SE.limb(char, right and "RightArm" or "LeftArm")
		if not hand then
			return
		end
		local parts = SE.shell(0.55, hand.CFrame)
		local c0s = {}
		local base = CFrame.new(0, -hand.Size.Y / 2 + 0.2, -0.35) * CFrame.Angles(math.rad(90), 0, 0)
		for i, p in parts do
			c0s[i] = base * (parts[1].CFrame:ToObjectSpace(p.CFrame))
		end
		SE.wear(parts, hand, c0s, life)
	end

	-- a chicken talon on a foot: a scaly yellow foot, three claws forward, one back
	function SE.talon(char, right, scale, life)
		local leg = SE.limb(char, right and "RightLeg" or "LeftLeg")
		if not leg then
			return
		end
		local parts, c0s = {}, {}
		local bottom = CFrame.new(0, -leg.Size.Y / 2, 0)
		local foot = newPart(Vector3.new(1.1, 0.55, 1.3) * scale, leg.CFrame, SE.TALON, Enum.Material.Slate)
		local m = Instance.new("SpecialMesh")
		m.MeshType = Enum.MeshType.Sphere
		m.Parent = foot
		table.insert(parts, foot)
		table.insert(c0s, bottom)
		for i = -1, 1 do
			local toe = newPart(Vector3.new(0.3, 0.3, 1.2) * scale, leg.CFrame, SE.TALON, Enum.Material.Slate)
			table.insert(parts, toe)
			table.insert(c0s, bottom * CFrame.Angles(0, math.rad(i * 26), 0) * CFrame.new(0, -0.05, -0.9 * scale))
			local claw = newPart(Vector3.new(0.18, 0.4, 0.6) * scale, leg.CFrame, SE.CLAW, Enum.Material.SmoothPlastic, Enum.PartType.Wedge)
			table.insert(parts, claw)
			table.insert(c0s, bottom * CFrame.Angles(0, math.rad(i * 26), 0) * CFrame.new(0, -0.12, -1.65 * scale) * CFrame.Angles(math.rad(180), 0, 0))
		end
		local spur = newPart(Vector3.new(0.18, 0.35, 0.55) * scale, leg.CFrame, SE.CLAW, Enum.Material.SmoothPlastic, Enum.PartType.Wedge)
		table.insert(parts, spur)
		table.insert(c0s, bottom * CFrame.new(0, -0.05, 0.7 * scale))
		SE.wear(parts, leg, c0s, life)
		return parts
	end

	-- a spider crab's claw over the right arm: a spiny shell sleeve, a
	-- swollen palm, two pincers that open and close (returns close(t, shut))
	function SE.claw(char, scale, life)
		local arm = SE.limb(char, "RightArm")
		if not arm then
			return nil
		end
		local s = scale or 1
		local parts, c0s = {}, {}
		local sleeve = newPart(Vector3.new(1.3, 2.2, 1.3) * s, arm.CFrame, SE.CRAB, Enum.Material.Slate)
		table.insert(parts, sleeve)
		table.insert(c0s, CFrame.new(0, 0.1, 0))
		for k = 1, 6 do
			local spike = newPart(Vector3.new(0.25, 0.7, 0.25) * s, arm.CFrame, SE.CRAB_SPOT, Enum.Material.Slate, Enum.PartType.Wedge)
			table.insert(parts, spike)
			local a = k * 1.1
			table.insert(c0s, CFrame.new(math.cos(a) * 0.7 * s, 0.9 - k * 0.3, math.sin(a) * 0.7 * s) * CFrame.Angles(0, -a, math.rad(-60)))
		end
		local palmCf = CFrame.new(0, -arm.Size.Y / 2 - 0.9 * s, 0)
		local palm = newPart(Vector3.new(1.9, 2.2, 1.7) * s, arm.CFrame, SE.CRAB, Enum.Material.Slate)
		local m = Instance.new("SpecialMesh")
		m.MeshType = Enum.MeshType.Sphere
		m.Parent = palm
		table.insert(parts, palm)
		table.insert(c0s, palmCf)
		for _ = 1, 3 do
			local spot = newPart(Vector3.one * 0.3 * s, arm.CFrame, SE.CRAB_SPOT, Enum.Material.SmoothPlastic, Enum.PartType.Ball)
			table.insert(parts, spot)
			table.insert(c0s, palmCf * CFrame.new(rand(-0.6, 0.6) * s, rand(-0.6, 0.6) * s, -0.85 * s))
		end
		SE.wear(parts, arm, c0s, life)
		-- the pincers, hinged at the end of the palm
		local pincers = {}
		for i, side in { 1, -1 } do
			local p = newPart(Vector3.new(0.7, 2.6, 0.6) * s, arm.CFrame, i == 1 and SE.CRAB or SE.CRAB:Lerp(Color3.new(), 0.2), Enum.Material.Slate, Enum.PartType.Wedge)
			local tip = newPart(Vector3.new(0.3, 0.8, 0.3) * s, arm.CFrame, SE.CLAW, Enum.Material.SmoothPlastic, Enum.PartType.Wedge)
			local hinge = palmCf * CFrame.new(side * 0.45 * s, -1 * s, 0)
			local w = SE.attach(palm, p, CFrame.new(side * 0.45 * s, -1.2 * s, 0) * CFrame.Angles(0, 0, math.rad(side * 18)))
			SE.attach(p, tip, CFrame.new(0, -1.5 * s, 0))
			pincers[i] = { weld = w, side = side, hinge = hinge }
			table.insert(parts, p)
			table.insert(parts, tip)
		end
		if life then
			task.delay(life, function()
				for _, p in parts do
					if p.Parent then
						tween(p, 0.2, { Transparency = 1 })
						cleanup(p, 0.25)
					end
				end
			end)
		end
		return function(time, shut)
			for _, pin in pincers do
				local ang = shut and pin.side * 2 or pin.side * 34
				tween(pin.weld, time, { C0 = CFrame.new(pin.side * 0.45 * s, -1.2 * s, 0) * CFrame.Angles(0, 0, math.rad(ang)) }, Enum.EasingStyle.Back)
			end
		end
	end

	-- chicken wings out of his back; flap(times) beats them
	function SE.wings(char, life)
		local torso = SE.limb(char, "Torso")
		if not torso then
			return nil
		end
		local welds, folds = {}, {}
		for _, side in { 1, -1 } do
			local root = newPart(Vector3.new(0.4, 0.4, 0.4), torso.CFrame, SE.FEATHER, Enum.Material.SmoothPlastic)
			root.Transparency = 1
			local w = SE.attach(torso, root, CFrame.new(side * 0.6, 0.6, 0.55) * CFrame.Angles(0, 0, math.rad(side * -30)))
			table.insert(welds, { weld = w, side = side })
			local feathers = {}
			for k = 1, 3 do
				local feather = newPart(Vector3.new(3.2 - k * 0.5, 0.18, 1.1), torso.CFrame, SE.FEATHER:Lerp(Color3.fromRGB(210, 200, 190), k * 0.15), Enum.Material.SmoothPlastic)
				table.insert(feathers, { part = feather, weld = SE.attach(root, feather, CFrame.new(side * (1.5 - k * 0.2), -0.35 * k, 0.1 * k) * CFrame.Angles(0, 0, math.rad(side * -8 * k))) })
				-- (they grow out of his back)
				local full = feather.Size
				feather.Size = full * Vector3.new(0.1, 1, 0.2)
				tween(feather, 0.1, { Size = full })
			end
			-- done: they fold shut and shrink back into his back (the
			-- manifestation undoing itself), with a little puff of flesh
			local folded = false
			local function fold()
				if folded or not root.Parent then
					return
				end
				folded = true
				do
					tween(w, 0.24, { C0 = CFrame.new(side * 0.2, 0.45, 0.25) * CFrame.Angles(0, 0, math.rad(side * -75)) }, Enum.EasingStyle.Quad, Enum.EasingDirection.In)
					for _, f in feathers do
						tween(f.weld, 0.24, { C0 = CFrame.new() }, Enum.EasingStyle.Quad, Enum.EasingDirection.In)
						tween(f.part, 0.24, { Size = f.part.Size * Vector3.new(0.06, 1, 0.1) }, Enum.EasingStyle.Quad, Enum.EasingDirection.In)
					end
					task.delay(0.22, function()
						if torso.Parent then
							dustPuffs((torso.CFrame * CFrame.new(side * 0.3, 0.5, 0.6)).Position, 0.18, 2, SE.TENT:Lerp(Color3.new(1, 1, 1), 0.45), 0.3, false)
						end
						for _, f in feathers do
							f.part.Transparency = 1
						end
					end)
					cleanup(root, 0.3)
				end
			end
			table.insert(folds, fold)
			if life then
				task.delay(life, fold)
			end
		end
		-- (the flap - and, second, a way to fold them away now)
		return function(times, beat)
			task.spawn(function()
				for _ = 1, times or 2 do
					for _, w in welds do
						tween(w.weld, (beat or 0.12), { C0 = CFrame.new(w.side * 0.6, 0.6, 0.55) * CFrame.Angles(0, 0, math.rad(w.side * 20)) })
					end
					task.wait(beat or 0.12)
					for _, w in welds do
						tween(w.weld, (beat or 0.12), { C0 = CFrame.new(w.side * 0.6, 0.6, 0.55) * CFrame.Angles(0, 0, math.rad(w.side * -40)) })
					end
					task.wait(beat or 0.12)
				end
			end)
		end, function()
			for _, f in folds do
				f()
			end
		end
	end

	-- a huge chicken leg over his leg (canon: chicken talons strengthened
	-- with octopus muscle), blocky: a feathered thigh, a scaly yellow shin in
	-- bands, a foot pad, three toes forward and one back, black claws
	SE.FEATHER_TAN = Color3.fromRGB(226, 196, 150)
	function SE.chickenLeg(char, right, scale, life)
		local leg = SE.limb(char, right and "RightLeg" or "LeftLeg")
		if not leg then
			return nil
		end
		local s = scale or 1
		local h = leg.Size.Y
		local parts, c0s = {}, {}
		local function add(size, color, material, c0, shape)
			table.insert(parts, newPart(size * s, leg.CFrame, color, material or Enum.Material.SmoothPlastic, shape))
			table.insert(c0s, c0)
		end
		add(Vector3.new(1.35, 0.9, 1.35), SE.FEATHER_TAN, Enum.Material.SmoothPlastic, CFrame.new(0, h * 0.28, 0))
		add(Vector3.new(0.85, 1.3, 0.85), SE.TALON, Enum.Material.Slate, CFrame.new(0, -h * 0.12, 0))
		for k = 0, 2 do
			add(Vector3.new(0.92, 0.1, 0.92), SE.TALON:Lerp(Color3.new(0, 0, 0), 0.25), Enum.Material.Slate, CFrame.new(0, -h * 0.12 + (k - 1) * 0.38 * s, 0))
		end
		local sole = CFrame.new(0, -h / 2 - 0.1 * s, 0)
		add(Vector3.new(0.95, 0.4, 0.95), SE.TALON, Enum.Material.Slate, sole)
		for i = -1, 1 do
			local toe = sole * CFrame.Angles(0, math.rad(i * 28), 0) * CFrame.new(0, -0.05 * s, -0.95 * s)
			add(Vector3.new(0.34, 0.3, 1.25), SE.TALON, Enum.Material.Slate, toe)
			add(Vector3.new(0.2, 0.36, 0.55), SE.CLAW, Enum.Material.SmoothPlastic, toe * CFrame.new(0, -0.05 * s, -0.8 * s) * CFrame.Angles(math.rad(180), 0, 0), Enum.PartType.Wedge)
		end
		add(Vector3.new(0.28, 0.26, 0.8), SE.TALON, Enum.Material.Slate, sole * CFrame.new(0, 0, 0.7 * s))
		add(Vector3.new(0.18, 0.3, 0.45), SE.CLAW, Enum.Material.SmoothPlastic, sole * CFrame.new(0, -0.05 * s, 1.2 * s), Enum.PartType.Wedge)
		SE.wear(parts, leg, c0s, life)
		return parts
	end

	-- a swordfish's bill for a hand: the dark blue head over his fist, the
	-- long flat bill (navy on top, silver under) and a tall sail of a fin
	-- along the forearm
	SE.FISH = Color3.fromRGB(38, 58, 108)
	SE.FISH_BELLY = Color3.fromRGB(204, 214, 228)
	SE.FIN = Color3.fromRGB(26, 40, 86)
	function SE.bill(char, life)
		local arm = SE.limb(char, "RightArm")
		if not arm then
			return nil
		end
		local h = arm.Size.Y
		local parts, c0s = {}, {}
		local function add(size, color, c0, shape)
			table.insert(parts, newPart(size, arm.CFrame, color, Enum.Material.SmoothPlastic, shape))
			table.insert(c0s, c0)
		end
		add(Vector3.new(1.15, 1.1, 1.2), SE.FISH, CFrame.new(0, -h / 2 - 0.25, 0))
		add(Vector3.new(1.18, 0.5, 1.22), SE.FISH_BELLY, CFrame.new(0, -h / 2 - 0.25, 0.1))
		add(Vector3.new(0.36, 5.2, 0.22), SE.FISH, CFrame.new(0, -h / 2 - 3.3, -0.04))
		add(Vector3.new(0.26, 5.2, 0.12), SE.FISH_BELLY, CFrame.new(0, -h / 2 - 3.3, 0.1))
		add(Vector3.new(0.36, 0.8, 0.22), SE.FISH, CFrame.new(0, -h / 2 - 6.3, -0.04) * CFrame.Angles(0, 0, math.rad(180)), Enum.PartType.Wedge)
		add(Vector3.new(0.14, 1.9, 1.3), SE.FIN, CFrame.new(0, 0.1, 0.9) * CFrame.Angles(math.rad(-12), 0, 0), Enum.PartType.Wedge)
		for _, side in { 1, -1 } do
			add(Vector3.new(0.8, 0.12, 0.5), SE.FIN, CFrame.new(side * 0.8, -h / 2 + 0.1, 0.2) * CFrame.Angles(0, 0, math.rad(side * -25)))
		end
		SE.wear(parts, arm, c0s, life)
		return parts
	end

	-- the clam hammer: both fists become one ridged clamshell the size of a
	-- car door, closed, on the end of his arms
	function SE.hammer(char, life)
		local arm = SE.limb(char, "RightArm")
		if not arm then
			return nil
		end
		local h = arm.Size.Y
		local parts, c0s = {}, {}
		for _, flip in { 0, 180 } do
			local shell = SE.shell(1.7, arm.CFrame)
			local base = CFrame.new(-0.5, -h / 2 - 1.1, 0) * CFrame.Angles(0, 0, math.rad(flip)) * CFrame.new(0, 0.45, 0)
			for _, p in shell do
				table.insert(parts, p)
				table.insert(c0s, base * (shell[1].CFrame:ToObjectSpace(p.CFrame)))
			end
		end
		SE.wear(parts, arm, c0s, life)
		return parts
	end

	-- the reshaping itself: a wet pop of flesh at the spot
	function SE.pop(pos, scale)
		dustPuffs(pos, 0.6 * scale, 4, SE.TENT:Lerp(Color3.new(1, 1, 1), 0.4), 0.5, false)
		sparks(pos, 0.4 * scale, SE.SUCKER, SE.TENT, math.floor(6 * scale))
		VFX.PlaySound("Manifest", pos, 0.8)
	end

	-- one tentacle out of his right hand that grabs: SE.arms[char] while it's
	-- out. It reaches along the aim, waits for the server to say who it got,
	-- then follows them (coiled round them) until they're let go
	SE.arms = setmetatable({}, { __mode = "k" })
	function SE.reach(char, thick, segs, goal, bend, reachTime)
		local old = SE.arms[char]
		if old then
			old.done = true
		end
		local arm = { tent = SE.tentacle(thick, segs), goal = goal, bend = bend or 1.5, t0 = os.clock(), reachTime = reachTime or 0.14, done = false }
		SE.arms[char] = arm
		local conn
		conn = RunService.RenderStepped:Connect(function()
			local t = os.clock() - arm.t0
			local troot = arm.target and arm.target:FindFirstChild("HumanoidRootPart")
			local over = arm.done or not char.Parent or t > (arm.life or 0.7)
				or (arm.target and (not troot or not troot.Parent or (arm.holdUntil and os.clock() > arm.holdUntil and not arm.target:GetAttribute("Grabbed"))))
			if over then
				conn:Disconnect()
				arm.tent.fade(0.2)
				if arm.coil then
					arm.coil.fade(0.2)
				end
				if SE.arms[char] == arm then
					SE.arms[char] = nil
				end
				return
			end
			local from = handPos(char, true)
			local goalPos = troot and troot.Position or arm.goal
			local k = math.clamp(t / arm.reachTime, 0, 1)
			if arm.retract then
				k = 1 - math.clamp((os.clock() - arm.retract) / 0.15, 0, 1)
				if k <= 0 then
					arm.done = true
				end
			end
			arm.tent.set(from, from:Lerp(goalPos, k), arm.bend * (troot and 1 or (1 - k * 0.5)), troot and 0.2 or 0.45)
			if troot and arm.coil then
				arm.coil.set(troot)
			end
		end)
		return arm
	end

	-- the arm got someone: coil round them and hold on (until the server lets go)
	function SE.caught(char, target, thick, bend)
		local arm = SE.arms[char]
		local troot = target:FindFirstChild("HumanoidRootPart")
		if not arm or not troot then
			return nil
		end
		arm.target = target
		arm.bend = bend or arm.bend
		arm.coil = SE.coil(thick)
		arm.life = 2.2
		arm.holdUntil = os.clock() + 0.25
		SE.pop(troot.Position, 1.1)
		VFX.PlaySound("Tentacle", troot.Position, 0.9)
		return arm
	end

