	-- CHICKEN KICK -----------------------------------------------------------
	function Effects.ChickenKick(char, data, isLocal)
		local root = charParts(char)
		if not root then
			return
		end
		local d = flatten(data.Dir, root)
		if isLocal then
			face(root, d)
		end
		if data.Air then
			SE.bambooSweep(char, root, d, isLocal) -- (round 59: 1 in the air)
			return
		end
		SE.chickenLeg(char, true, 1.35, 0.75)
		VFX.Motion(char, "ChickenKick")
		SE.pop(root.Position - UP * 2 + d, 1)
		task.wait(0.15)
		if not root.Parent then
			return
		end
		local front = root.Position + d * 3
		shockDisc(front + UP * 1.5, UP, 2, 14, 0.25, SE.TALON, 8)
		streaks(front, UP, 12, 2, 7, 18, WIND, 0.3)
		billboardRing(front + UP * 2, 2, 12, Color3.new(1, 1, 1), 6, 0.2)
		dustPuffs(groundPoint(root.Position + d * 2), 0.9, 5, Color3.fromRGB(205, 196, 190), 0.7, false)
		VFX.PlaySound("ChickenKick", front, 1)
		VFX.ShakeAt(front, 1.3, 50, 0.2)
	end

	-- TAKO SNATCH ------------------------------------------------------------
	-- the arm shoots out along the aim (his own screen: straight away), then
	-- the server says who it caught
	function Effects.TakoSnatch(char, data, isLocal, ability)
		local root = charParts(char)
		if not root then
			return
		end
		local d = flatten(data.Dir, root)
		local aim = Config.AimedDirection(data.Dir, d, { Up = 75, Down = 30 })
		if isLocal then
			face(root, d)
		end
		VFX.Pose(char, aim.Y > 0.35 and "TentacleCastUp" or "TentacleCast", 0.6)
		SE.pop(handPos(char, true), 1)
		VFX.PlaySound("Tentacle", root.Position, 1)
		local reach = (ability and ability.Range) or 45
		SE.reach(char, 0.9, 11, root.Position + UP * 1.5 + aim * reach, 1.8, math.min(reach / 160, 0.28) + 0.12)
	end

	function Effects.TakoSnatchCatch(char, data)
		local root = charParts(char)
		if not root then
			return
		end
		local target = typeof(data.Target) == "Instance" and data.Target or nil
		if not SE.arms[char] then
			-- (they never saw it go out: it reaches for them now)
			local reach = tonumber(data.Reach) or 30
			local dir = typeof(data.Dir) == "Vector3" and data.Dir.Unit or root.CFrame.LookVector
			SE.reach(char, 0.9, 11, root.Position + UP * 1.5 + dir * reach, 1.8, 0.1)
		end
		if not target then
			if typeof(data.Swing) == "Vector3" then
				return -- (it latched onto a building: TakoSwing takes it from here)
			end
			local arm = SE.arms[char]
			if arm then
				arm.retract = os.clock() + 0.05
			end
			return
		end
		SE.caught(char, target, 0.55, 3)
		VFX.Pose(char, "ThrashUp", 0.3)
		task.delay(0.26, function()
			if char.Parent then
				VFX.Pose(char, "ThrashRight", 0.35)
			end
		end)
	end

	-- ...it hit a building instead: the tentacle holds on to it and he swings
	-- off it (his own screen swings him; everyone sees the tentacle)
	function Effects.TakoSwing(char, data)
		local root = charParts(char)
		local anchor = typeof(data.Anchor) == "Vector3" and data.Anchor
		if not root or not anchor then
			return
		end
		local time = tonumber(data.Time) or 1
		local arm = SE.reach(char, 0.8, 11, anchor, 0.3, 0.06)
		arm.life = time + 0.2
		VFX.Pose(char, "SwingHang", time)
		SE.pop(anchor, 0.8)
		VFX.PlaySound("Tentacle", anchor, 0.9)
		if Players.LocalPlayer and char == Players.LocalPlayer.Character then
			VFX.Swing(char, anchor, {
				Time = time,
				OnEnd = function()
					if SE.arms[char] == arm then
						arm.retract = os.clock()
					end
				end,
			})
		end
	end


	-- (round 60) ...it hit a building instead: THE ZIP. The tentacle holds on
	-- and reels him in to it (his own screen moves him; everyone sees the
	-- tentacle, and his body fly along it). A jump on the way: the point launch.
	POSES.ZipPull = { RightArm = { 160, 0, 4 }, RightElbow = 4, LeftArm = { 40, 0, 30 }, LeftElbow = 50, Waist = { -16, 0, 0 }, Neck = { -14, 0, 0 }, RightLeg = -24, LeftLeg = 18, RightKnee = 30, LeftKnee = 55 }
	POSES.ZipCling = { RightArm = { 150, 0, 16 }, RightElbow = 30, LeftArm = { 140, 0, 20 }, LeftElbow = 40, Waist = { 6, 0, 0 }, Neck = { -8, 0, 0 }, RightLeg = 30, LeftLeg = 12, RightKnee = 70, LeftKnee = 45 }
	POSES.ZipLaunch = { RightArm = { 170, 0, 30 }, LeftArm = { 170, 0, 30 }, RightElbow = 10, LeftElbow = 10, Waist = { 26, 0, 0 }, Neck = { 16, 0, 0 }, RightLeg = 80, LeftLeg = 80, RightKnee = 110, LeftKnee = 110 }
	function Effects.TakoZip(char, data)
		local root = charParts(char)
		local anchor = typeof(data.Anchor) == "Vector3" and data.Anchor
		if not root or not anchor then
			return
		end
		local spec = (Config.FindAbilityById and Config.FindAbilityById("TakoSnatch") or {}).Zip or {}
		local arm = SE.reach(char, 0.8, 11, anchor, 0.1, 0.05)
		arm.life = (spec.MaxTime or 1.4) + (spec.Cling or 0.45) + 0.4
		VFX.Pose(char, "ZipPull", spec.MaxTime or 1.4)
		SE.pop(anchor, 0.8)
		VFX.PlaySound("ZipPull", root.Position, 1)
		local function letGo()
			if SE.arms[char] == arm then
				arm.retract = os.clock()
			end
		end
		if Players.LocalPlayer and char == Players.LocalPlayer.Character then
			local st
			st = VFX.Zip(char, anchor, {
				Normal = data.Normal,
				Ledge = data.Ledge == true,
				Speed = spec.Speed, Accel = spec.Accel, MaxTime = spec.MaxTime, Cling = spec.Cling,
				LaunchUp = spec.LaunchUp, LaunchForward = spec.LaunchForward,
				OnLaunch = function()
					letGo()
					VFX.Pose(char, "ZipLaunch", 0.45)
					VFX.PlaySound("ZipLaunch", root.Position, 1)
					streaks(root.Position, UP, 6, 1, 5, 12, SE.TENT, 0.25)
				end,
				OnEnd = function(launched)
					letGo()
					if not launched then
						VFX.ReleasePose(char, 0.2)
					end
				end,
			})
			if st then
				-- (on the wall: hands on it)
				task.spawn(function()
					while VFX.Zipping(char) and char.Parent do
						if st.clinging then
							VFX.Pose(char, "ZipCling", 0.2)
						end
						task.wait(0.1)
					end
				end)
			else
				letGo()
			end
		else
			-- (someone else: the tentacle lets go once they'd be there)
			task.delay(math.min((anchor - root.Position).Magnitude / 110 + 0.35, (spec.MaxTime or 1.4) + 0.3), letGo)
		end
	end

	-- a tentacle slams someone into the street
	function Effects.TentacleSlam(_, data)
		local pos = typeof(data.Pos) == "Vector3" and data.Pos
		if not pos then
			return
		end
		local big = data.Big == true
		shockDisc(pos + UP * 0.4, UP, 2, big and 22 or 14, 0.3, SE.TENT)
		dustPuffs(pos, big and 1.3 or 0.9, big and 8 or 5, Color3.fromRGB(205, 196, 190), 0.9, false)
		rocks(pos, big and 1.2 or 0.8, big and 7 or 4)
		groundMark(pos, big and 4 or 3, Color3.fromRGB(58, 52, 50), 4)
		VFX.PlaySound("TentacleSlam", pos, 1)
		VFX.ShakeAt(pos, big and 2 or 1.3, 70, 0.25)
	end

	-- TAKO THRASH ------------------------------------------------------------
	function Effects.TakoThrash(char, data, isLocal)
		local root = charParts(char)
		if not root then
			return
		end
		local d = flatten(data.Dir, root)
		if isLocal then
			face(root, d)
		end
		if data.Air then
			SE.urchin(char, root, isLocal) -- (round 59: 3 in the air)
			return
		end
		VFX.Pose(char, "ThrashHold", 0.4)
		SE.pop(handPos(char, true), 1.4)
		VFX.PlaySound("Tentacle", root.Position, 1.1)
