POSES.StandCommand = { RightArm = { 92, 0, -12 }, RightElbow = 6, LeftArm = { 18, 0, 22 }, LeftElbow = 40, Waist = { -6, 20, 0 }, Neck = { 0, -16, 0 }, RightLeg = -8, LeftLeg = 14, LeftKnee = 18 }
POSES.StandCommandL = { LeftArm = { 92, 0, -12 }, LeftElbow = 6, RightArm = { 18, 0, 22 }, RightElbow = 40, Waist = { -6, -20, 0 }, Neck = { 0, 16, 0 }, LeftLeg = -8, RightLeg = 14, RightKnee = 18 }
POSES.StandCommandFin = {
	RightArm = { 128, 0, -22 }, RightElbow = 4, LeftArm = { 150, 0, -40 }, LeftElbow = 125,
	Waist = { -12, 26, 8 }, Neck = { 10, -20, 0 }, RightLeg = -10, LeftLeg = 20, LeftKnee = 30,
}

---------------------------------------------------------------------------
-- MR. COMPRESS (Atsuhiro Sako): Compress. Marbles - little glass balls
-- with a swirl of the thing inside - things shrinking into them with a
-- suck of light, and popping back out full size. A magician's flourishes.
---------------------------------------------------------------------------
do
	local MC = { GLASS = Color3.fromRGB(150, 214, 255), ORANGE = Color3.fromRGB(230, 120, 40), SMOKE = Color3.fromRGB(80, 68, 92), riding = setmetatable({}, { __mode = "k" }) }
	VFX.MC = MC
	local STREET, WHITE = Color3.fromRGB(120, 118, 112), Color3.new(1, 1, 1)

	POSES.CaneStrike = { RightArm = { 95, 0, 8 }, RightElbow = 10, LeftArm = { -30, 0, 15 }, LeftElbow = 40, Waist = { 8, -32, 0 }, Neck = { -6, 20, 0 }, RightLeg = -18, LeftLeg = 22, LeftKnee = 24, Hips = { 0, 0, 0, 0, -0.3, 0.2 } }
	POSES.CaneCatch = { RightArm = { 165, 0, 20 }, RightElbow = 25, LeftArm = { 20, 0, 30 }, Waist = { -12, 10, 0 }, Neck = { -25, 0, 0 } }
	POSES.MarbleFlick = { RightArm = { 100, 0, 25 }, RightElbow = 15, RightWrist = { -30, 0, 0 }, LeftArm = { 15, 0, 20 }, Waist = { 6, -20, 0 }, RightLeg = -12, LeftLeg = 18, LeftKnee = 20 }
	POSES.MarbleHold = { RightArm = { 70, 0, -10 }, RightElbow = 95, LeftArm = { 10, 0, 25 }, Waist = { 4, -10, 0 }, Neck = { 6, -12, 0 } }
	-- ((round 101, awaken_m) the bow and his KO bow bend FORWARD: a positive
	-- Waist pitch is a back-bend on this rig (the audit's render) - as the
	-- BOW emote's -48)
	POSES.Bow = { Waist = { -42, 0, 0 }, Neck = { 12, 0, 0 }, RightArm = { 55, 0, -45 }, RightElbow = 110, LeftArm = { -50, 0, 60 }, LeftElbow = 10, RightLeg = 10, LeftLeg = -14 }
	POSES.Present = { RightArm = { 85, 0, 80 }, LeftArm = { 85, 0, 80 }, RightElbow = 20, LeftElbow = 20, Waist = { -10, 0, 0 }, Neck = { -12, 0, 0 } }
	POSES.HatTip = { RightArm = { 160, 0, 30 }, RightElbow = 100, LeftArm = { 15, 0, 25 }, Waist = { 14, 0, 0 }, Neck = { 12, 0, 0 } }
	POSES.Lob = { RightArm = { 175, 0, 15 }, RightElbow = 40, LeftArm = { 60, 0, 10 }, Waist = { -14, -30, 0 }, RightLeg = -14, LeftLeg = 20, RightKnee = 10 }
	POSES.KO_Compress = { Waist = { -40, 0, 0 }, Neck = { 10, 0, 0 }, RightArm = { 60, 0, -50 }, RightElbow = 110, LeftArm = { -55, 0, 70 }, LeftElbow = 10, RightLeg = 12, LeftLeg = -16 }

	MOTIONS.RubbleThrow = { { pose = "Lob", t = 0.16, hold = 0.06 }, { pose = "MarbleFlick", t = 0.07, hold = 0.25, style = SNAP }, recover = 0.3 }
	MOTIONS.CaneStrike = { { pose = "CaneStrike", t = 0.08, hold = 0.25, style = SNAP }, recover = 0.25 }
	MOTIONS.CaneTrick = { { pose = "CaneStrike", t = 0.08, hold = 0.2, style = SNAP }, { pose = "MarbleHold", t = 0.12, hold = 0.12 }, { pose = "PunchR", t = 0.06, hold = 0.2, style = SNAP }, { pose = "CaneCatch", t = 0.2, hold = 0.35 }, recover = 0.3 }
	MOTIONS.VanishingAct = { { pose = "Grab", t = 0.12, hold = 0.1 }, { pose = "MarbleHold", t = 0.15, hold = 0.75 }, { pose = "MarbleFlick", t = 0.06, hold = 0.3, style = SNAP }, recover = 0.3 }
	MOTIONS.MarbleToss = { { pose = "MarbleFlick", t = 0.06, hold = 0.3, style = SNAP }, recover = 0.3 }
	MOTIONS.CompressGrab = { { pose = "Grab", t = 0.1, hold = 0.12 }, { pose = "MarbleHold", t = 0.12, hold = 0.25 }, recover = 0.25 }
	MOTIONS.MagiciansChoice = { { pose = "HatTip", t = 0.08, hold = 0.1, style = SNAP }, recover = 0.15 }
	MOTIONS.MarbleStorm = { { pose = "Present", t = 0.2, hold = 0.1 }, { pose = "Lob", t = 0.1, hold = 0.7 }, recover = 0.3 }
	MOTIONS.CurtainCall = { { pose = "ArmsUp", t = 0.25, hold = 0.9 }, { pose = "PalmDown", t = 0.08, hold = 0.3, style = SNAP }, recover = 0.35 }
	MOTIONS.DisappearingAct = { { pose = "Present", t = 0.2, hold = 1.2 }, { pose = "Lob", t = 0.08, hold = 0.5, style = SNAP }, recover = 0.3 }
	MOTIONS.Showtime = { { pose = "HatTip", t = 0.2, hold = 0.4 }, { pose = "Bow", t = 0.3, hold = 0.8 }, { pose = "Present", t = 0.2, hold = 0.5 }, recover = 0.4 }

	-- a marble: a glass ball with a swirl of the thing inside it
	function MC.marble(cf, size, color)
		size = size or 0.5
		local ball = newPart(Vector3.one * size, cf, MC.GLASS, Enum.Material.Glass, Enum.PartType.Ball)
		ball.Transparency = 0.25
		ball.Reflectance = 0.3
		local core = newPart(Vector3.one * size * 0.45, cf, color or MC.ORANGE, Enum.Material.Neon, Enum.PartType.Ball)
		local m = { Ball = ball, Core = core }
		function m.set(c)
			ball.CFrame = c
			core.CFrame = c * CFrame.Angles(os.clock() * 4, os.clock() * 2, 0) * CFrame.new(size * 0.12, 0, 0)
		end
		function m.gone(t)
			t = t or 0.1
			tween(ball, t, { Transparency = 1, Size = Vector3.one * 0.05 })
			tween(core, t, { Transparency = 1 })
			cleanup(ball, t + 0.05)
			cleanup(core, t + 0.05)
		end
		return m
	end
	-- something shrinking into a marble at `pos`: rings of light sucked in,
	-- the glassy ping
	function MC.suck(pos, radius, color)
		for i = 1, 3 do
			task.delay((i - 1) * 0.05, function()
				billboardRing(pos, (radius or 3) * 2.2, 0.3, color or MC.GLASS, 5, 0.22)
			end)
		end
		sparks(pos, 0.9, WHITE, color or MC.GLASS, 10)
		VFX.PlaySound("Compress", pos, 1)
	end
	-- a piece of the city, full size again: a lump of blocks in its colour
	function MC.chunk(cf, radius, color, material)
		local parts = {}
		for i = 1, 6 do
			local s = Vector3.new(rand(0.5, 1), rand(0.4, 0.9), rand(0.5, 1)) * radius
			local off = i == 1 and Vector3.zero or Vector3.new(rand(-0.5, 0.5), rand(-0.4, 0.4), rand(-0.5, 0.5)) * radius
			local p = newPart(s, cf * CFrame.new(off) * CFrame.Angles(rand(0, 1), rand(0, 1), rand(0, 1)), color or STREET, material or Enum.Material.Concrete)
			table.insert(parts, { part = p, rel = cf:ToObjectSpace(p.CFrame) })
		end
		local c = { parts = parts }
		function c.set(cf2)
			for _, e in parts do
				e.part.CFrame = cf2 * e.rel
			end
		end
		function c.shatter()
			for _, e in parts do
				local p = e.part
				tween(p, 0.4, { CFrame = p.CFrame * CFrame.new(rand(-3, 3), rand(-1, 2), rand(-3, 3)) * CFrame.Angles(rand(0, 2), rand(0, 2), 0), Transparency = 1 })
				cleanup(p, 0.45)
			end
		end
		function c.gone()
			for _, e in parts do
				e.part:Destroy()
			end
		end
		return c
	end
	-- a piece of the city popping back out and coming down at `pos`
	function MC.decompress(pos, radius, color, material, dir)
		local chunk = MC.chunk(CFrame.new(pos + UP * radius * 0.4), radius, color, material)
		for _, e in chunk.parts do
			local p = e.part
			local full = p.Size
			p.Size = full * 0.15
			tween(p, 0.1, { Size = full }, Enum.EasingStyle.Back)
		end
		billboardRing(pos, 0.5, radius * 4, WHITE, 5, 0.2)
		shockDisc(pos + UP * 0.3, dir or UP, 2, radius * 3.5, 0.3, MC.GLASS, 4)
		dustPuffs(groundPoint(pos), radius * 0.35, 5, Color3.fromRGB(200, 190, 175), 0.8, true)
		rocks(pos, radius * 0.25, 6)
		VFX.PlaySound("Decompress", pos, 1)
		VFX.ShakeAt(pos, radius * 0.25, 60, 0.2)
		task.delay(0.9, chunk.shatter)
		return chunk
	end
	-- a marble riding a body the server's carrying (in his hand, thrown)
	function MC.ride(target, time)
		local troot = target and target:FindFirstChild("HumanoidRootPart")
		if not troot then
			return
		end
		MC.unride(target)
		local m = MC.marble(troot.CFrame, 0.6, MC.ORANGE)
		MC.riding[target] = m
		local t0 = os.clock()
		local conn
		conn = RunService.RenderStepped:Connect(function()
			if not troot.Parent or MC.riding[target] ~= m or os.clock() - t0 > time then
				conn:Disconnect()
				if MC.riding[target] == m then
					MC.riding[target] = nil
				end
				m.gone(0.15)
				return
			end
			m.set(troot.CFrame)
		end)
	end
	function MC.unride(target)
		local m = MC.riding[target]
		if m then
			MC.riding[target] = nil
			m.gone(0.05)
		end
	end
	-- the cosmetic cane, shown / hidden (the trick makes it vanish)
	function MC.showCane(char, on)
		for _, d in char:GetDescendants() do
			if d.Name == "Cane" and d:IsA("BasePart") then
				d.LocalTransparencyModifier = on and 0 or 1
			end
		end
	end
	-- a marble lobbed along an arc (From, Vel, Gravity) for `time`; `at` is
	-- called every frame with where it is
	function MC.lob(from, vel, gravity, time, color, at)
		local m = MC.marble(CFrame.new(from), 0.55, color)
		local stop = addTrail(m.Ball, MC.GLASS, 0.18, 0.4)
		VFX.PlaySound("MarbleThrow", from, 0.9)
		task.spawn(function()
			local t0 = os.clock()
			while os.clock() - t0 < time and m.Ball.Parent do
				local t = os.clock() - t0
				local p = from + vel * t - UP * (0.5 * gravity * t * t)
				m.set(CFrame.new(p))
				if at then
					at(p, t / time)
				end
				task.wait()
			end
			stop(0.1)
			m.gone(0.05)
		end)
		return m
	end

	-- R: a piece of the city shrinks into a marble that flies to his hand
	function Effects.CompressTake(char, data, isLocal)
		local root = charParts(char)
		local pos = typeof(data.Pos) == "Vector3" and data.Pos or (root and root.Position)
		if not root or not pos then
			return
		end
		if isLocal and typeof(data.Dir) == "Vector3" then
			face(root, data.Dir)
		end
		VFX.Motion(char, "CompressGrab")
		local radius = tonumber(data.Radius) or 5
		local chunk = MC.chunk(CFrame.new(pos), radius * 0.8, data.Color, data.Material)
		MC.suck(pos, radius, MC.GLASS)
		groundMark(groundPoint(pos + UP), radius * 0.9, Color3.fromRGB(60, 56, 54), 6)
		task.wait(0.05)
		local hand = handPos(char, true)
		for _, e in chunk.parts do
			tween(e.part, 0.28, { CFrame = CFrame.new(hand) * CFrame.Angles(rand(0, 3), rand(0, 3), 0), Size = Vector3.one * 0.1 }, Enum.EasingStyle.Quad, Enum.EasingDirection.In)
			cleanup(e.part, 0.3)
		end
		task.wait(0.28)
		if not root.Parent then
			return
		end
		-- (the marble in his palm for a moment, then pocketed)
		local m = MC.marble(CFrame.new(handPos(char, true)), 0.5, data.Color or MC.ORANGE)
		sparks(handPos(char, true), 0.5, WHITE, MC.GLASS, 6)
		local t0 = os.clock()
		while os.clock() - t0 < 0.35 and root.Parent do
			m.set(CFrame.new(handPos(char, true)))
			task.wait()
		end
		m.gone(0.12)
	end

	-- 1: the marble lobbed; at the top of its arc it pops into the piece of
	-- the city, tumbling down onto them
	function Effects.RubbleLob(char, data)
		local root = charParts(char)
		local from = typeof(data.From) == "Vector3" and data.From or (root and root.Position + UP * 2)
		local vel = typeof(data.Vel) == "Vector3" and data.Vel or Vector3.new(0, 20, -40)
		if not from then
			return
		end
		local gravity, time = tonumber(data.Gravity) or workspace.Gravity, tonumber(data.LandTime) or 1
		local land = typeof(data.Land) == "Vector3" and data.Land or (from + vel * time - UP * (0.5 * gravity * time * time))
		if data.Big then
			local chunk
			local popAt = math.max(time * 0.45, 0.12)
			MC.lob(from, vel, gravity, popAt, data.Color or MC.ORANGE)
			task.delay(popAt, function()
				local p0 = from + vel * popAt - UP * (0.5 * gravity * popAt * popAt)
				chunk = MC.chunk(CFrame.new(p0), 3, data.Color, data.Material)
				for _, e in chunk.parts do
					local full = e.part.Size
					e.part.Size = full * 0.2
					tween(e.part, 0.08, { Size = full }, Enum.EasingStyle.Back)
				end
				billboardRing(p0, 0.5, 8, WHITE, 4, 0.18)
				VFX.PlaySound("Decompress", p0, 0.8)
				local t1 = os.clock()
				local spin = CFrame.new()
				while os.clock() - t1 < time - popAt and chunk.parts[1].part.Parent do
					local t = popAt + (os.clock() - t1)
					spin = spin * CFrame.Angles(0.12, 0.08, 0.05)
					chunk.set(CFrame.new(from + vel * t - UP * (0.5 * gravity * t * t)) * spin)
					task.wait()
				end
				chunk.set(CFrame.new(land + UP * 1.2) * spin)
				task.wait(0.12)
				-- down: it breaks up in the street
				dustPuffs(groundPoint(land), 1.3, 7, Color3.fromRGB(200, 190, 175), 1, true)
				rocks(land, 1.1, 10)
				shockDisc(land + UP * 0.3, UP, 2, 24, 0.3, Color3.fromRGB(220, 210, 190), 5)
				groundMark(groundPoint(land + UP), 5, Color3.fromRGB(60, 56, 54), 8)
				VFX.PlaySound("RubbleLand", land, 1)
				VFX.ShakeAt(land, 1.4, 70, 0.25)
				if nearCamera(land, 50) then
					VFX.ImpactFrame(0.06)
				end
				chunk.shatter()
			end)
		else
			-- a rock off the street
			local rock = newPart(Vector3.new(0.9, 0.7, 0.8), CFrame.new(from), STREET, Enum.Material.Slate)
			local stop = addTrail(rock, Color3.fromRGB(200, 190, 175), 0.12, 0.3)
			VFX.PlaySound("MarbleThrow", from, 0.7)
			local t0 = os.clock()
			while os.clock() - t0 < time and rock.Parent do
				local t = os.clock() - t0
				rock.CFrame = CFrame.new(from + vel * t - UP * (0.5 * gravity * t * t)) * CFrame.Angles(t * 9, t * 5, 0)
				task.wait()
			end
			stop(0.05)
			dustPuffs(groundPoint(land), 0.5, 3, Color3.fromRGB(200, 190, 175), 0.6, false)
			rocks(land, 0.5, 4)
			VFX.PlaySound("CaneHit", land, 0.8)
			rock:Destroy()
		end
	end

	-- 2: the cane's pommel; the trick: the cane shrinks into a marble at
	-- their feet, a punch, the cane pops back out under their chin and he
	-- catches it
	function Effects.CaneTrick(char, data, isLocal)
		local root = charParts(char)
		if not root then
			return
		end
		local d = flatten(data.Dir, root)
		if isLocal then
			face(root, d)
		end
		local target = typeof(data.Target) == "Instance" and data.Target or nil
		local troot = target and target:FindFirstChild("HumanoidRootPart")
		if data.Trick and troot then
			VFX.Motion(char, "CaneTrick")
		end
		local hit = troot and troot.Position + UP * 1.2 or root.Position + d * 4 + UP * 1.2
		VFX.PlaySound(troot and "CaneHit" or "Swish", hit, 1)
		if troot then
			sparks(hit, 0.7, WHITE, MC.ORANGE, 8)
			billboardRing(hit, 1, 8, WHITE, 4, 0.18)
		end
		if not (data.Trick and troot) then
			return
		end
		-- the cane's gone: a marble drops at their feet
		MC.showCane(char, false)
		local feet = groundPoint(troot.Position) + UP * 0.4
		MC.suck(handPos(char, true), 1.2, MC.GLASS)
		local m = MC.marble(CFrame.new(handPos(char, true)), 0.45, Color3.fromRGB(30, 28, 32))
		tween(m.Ball, 0.22, { CFrame = CFrame.new(feet) }, Enum.EasingStyle.Bounce)
		tween(m.Core, 0.22, { CFrame = CFrame.new(feet) }, Enum.EasingStyle.Bounce)
		task.wait(0.28)
		-- the punch
		if troot.Parent then
			sparks(troot.Position + UP, 0.6, WHITE, MC.ORANGE, 6)
			VFX.PlaySound("Hit", troot.Position, 0.9)
		end
		task.wait(0.27)
		if not root.Parent or not troot.Parent then
			m.gone(0.1)
			MC.showCane(char, true)
			return
		end
		-- the cane pops back out of the marble - straight up under the chin
		m.gone(0.06)
		local cane = newPart(Vector3.new(0.16, 3.2, 0.16), CFrame.new(feet + UP * 0.2), Color3.fromRGB(24, 22, 26), Enum.Material.SmoothPlastic)
		cane.Size = Vector3.new(0.16, 0.3, 0.16)
		local knob = newPart(Vector3.one * 0.32, CFrame.new(feet + UP * 0.3), Color3.fromRGB(214, 176, 70), Enum.Material.Metal, Enum.PartType.Ball)
		local chin = troot.Position + UP * 2.2
		tween(cane, 0.1, { Size = Vector3.new(0.16, 3.2, 0.16), CFrame = CFrame.new(feet + UP * 1.7) }, Enum.EasingStyle.Back)
		tween(knob, 0.1, { CFrame = CFrame.new(chin) }, Enum.EasingStyle.Back)
		VFX.PlaySound("Decompress", feet, 0.9)
		task.wait(0.1)
		sparks(chin, 1, WHITE, MC.ORANGE, 12)
		billboardRing(chin, 1, 12, MC.ORANGE, 5, 0.22)
		VFX.PlaySound("CaneHit", chin, 1.1)
		if nearCamera(chin, 40) then
			VFX.ImpactFrame(0.05)
		end
		-- up it goes, spinning, and back down into his hand
		local top = chin + UP * 6 + d * -1
		tween(cane, 0.22, { CFrame = CFrame.new(top) * CFrame.Angles(0, 0, math.rad(200)) }, Enum.EasingStyle.Quad, Enum.EasingDirection.Out)
		tween(knob, 0.22, { CFrame = CFrame.new(top + UP * 1.5) }, Enum.EasingStyle.Quad, Enum.EasingDirection.Out)
		task.wait(0.22)
		local hand = handPos(char, true)
		tween(cane, 0.22, { CFrame = CFrame.new(hand - UP * 1.1) * CFrame.Angles(0, 0, math.rad(360)) }, Enum.EasingStyle.Quad, Enum.EasingDirection.In)
		tween(knob, 0.22, { CFrame = CFrame.new(hand + UP * 0.5) }, Enum.EasingStyle.Quad, Enum.EasingDirection.In)
		task.wait(0.22)
		cane:Destroy()
		knob:Destroy()
		MC.showCane(char, true)
		sparks(hand, 0.4, WHITE, MC.GLASS, 4)
		VFX.PlaySound("Snap", hand, 0.7)
	end

	-- "another hit": a marble flicked at them, popping into a fistful of rubble
	function Effects.MarblePop(char, data)
		local root = charParts(char)
		local target = typeof(data.Target) == "Instance" and data.Target or nil
		local troot = target and target:FindFirstChild("HumanoidRootPart")
		local to = troot and troot.Position + UP or (typeof(data.Pos) == "Vector3" and data.Pos)
		if not root or not to then
			return
		end
		VFX.Pose(char, "MarbleFlick", 0.25)
		local from = handPos(char, true)
		local m = MC.marble(CFrame.new(from), 0.4, MC.ORANGE)
		local stop = addTrail(m.Ball, MC.GLASS, 0.15, 0.3)
		VFX.PlaySound("MarbleThrow", from, 0.7)
		local t0 = os.clock()
		while os.clock() - t0 < 0.12 do
			m.set(CFrame.new(from:Lerp(to, math.clamp((os.clock() - t0) / 0.12, 0, 1))))
			task.wait()
		end
		stop(0.05)
		m.gone(0.05)
		rocks(to, 0.6, 6)
		sparks(to, 0.6, WHITE, MC.ORANGE, 6)
		billboardRing(to, 0.5, 7, WHITE, 4, 0.16)
		VFX.PlaySound("MarblePop", to, 1)
	end

	-- 3: them, shrunk into a marble in his hand (their body's gone), flicked
	-- away and popped back out into the street
	function Effects.VanishingGrab(char, data, isLocal)
		local root = charParts(char)
		if not root then
			return
		end
		local d = flatten(data.Dir, root)
		if isLocal then
			face(root, d)
		end
		local target = typeof(data.Target) == "Instance" and data.Target or nil
		local troot = target and target:FindFirstChild("HumanoidRootPart")
		if not troot then
			sparks(root.Position + d * 3 + UP, 0.4, WHITE, MC.GLASS, 4)
			VFX.ReleasePose(char, 0.2)
			return
		end
		local held = tonumber(data.Held) or 1
		VFX.Pose(char, "MarbleHold", held + 0.3) -- (round 59: until he flicks it)
		MC.suck(troot.Position + UP, 3, MC.GLASS)
		-- (a ghost of them, sucked into the palm)
		afterimage(target, MC.GLASS, 0.25)
		hideCharacter(target, held + 0.45)
		MC.ride(target, held + 0.6)
		if nearCamera(troot.Position, 40) then
			VFX.ImpactFrame(0.05)
		end
	end
	function Effects.VanishingThrow(char, data)
		if char then
			VFX.Motion(char, "MarbleToss")
		end
		local target = typeof(data.Target) == "Instance" and data.Target or nil
		local from = typeof(data.From) == "Vector3" and data.From
		if from then
			VFX.PlaySound("MarbleThrow", from, 1)
			streaks(from, (typeof(data.To) == "Vector3" and (data.To - from).Unit) or UP, 6, 0.6, 4, 8, MC.GLASS, 0.25)
		end
		if target then
			MC.ride(target, (tonumber(data.Time) or 0.32) + 0.15)
		end
	end
	function Effects.VanishingPop(char, data)
		if char and data.Dropped then
			VFX.ReleasePose(char, 0.2) -- (knocked about holding it: he dropped it)
		end
		local target = typeof(data.Target) == "Instance" and data.Target or nil
		local pos = typeof(data.Pos) == "Vector3" and data.Pos or (target and target:FindFirstChild("HumanoidRootPart") and target.HumanoidRootPart.Position)
		if target then
			MC.unride(target)
			for _, p in target:GetDescendants() do
				if p:IsA("BasePart") or p:IsA("Decal") then
					p.LocalTransparencyModifier = 0
				end
			end
			afterimage(target, MC.ORANGE, 0.2)
		end
		if pos then
			billboardRing(pos, 0.5, 14, WHITE, 5, 0.22)
			shockDisc(pos + UP * 0.3, typeof(data.Dir) == "Vector3" and data.Dir or UP, 2, 14, 0.28, MC.GLASS, 4)
			dustPuffs(groundPoint(pos), 0.9, 5, Color3.fromRGB(200, 190, 175), 0.8, true)
			rocks(pos, 0.8, 8)
			VFX.PlaySound("Decompress", pos, 1)
			VFX.ShakeAt(pos, 1.2, 50, 0.2)
			if nearCamera(pos, 50) then
				VFX.ImpactFrame(0.06)
			end
		end
	end

	-- 4: he tips his hat and he's a marble: a puff of smoke, the marble
	-- flies, and he pops back out over there
	function Effects.MagiciansFly(char, data)
		local root = charParts(char)
		if not root then
			return
		end
		local from = typeof(data.From) == "Vector3" and data.From or root.Position
		local to = typeof(data.To) == "Vector3" and data.To or from
		local time = tonumber(data.Time) or 0.3
		VFX.MuteGait(char, time + 0.3)
		afterimage(char, MC.GLASS, 0.2)
		hideCharacter(char, time + 0.05)
		MC.suck(from + UP * 1.5, 3, MC.GLASS)
		-- the smoke bomb
		dustPuffs(groundPoint(from), 1.4, 8, MC.SMOKE, 1.1, true)
		smokeBurst(from + UP, MC.SMOKE, 2.5, 5, 1.2, 6)
		billboardRing(from + UP, 1, 12, MC.SMOKE, 6, 0.3)
		-- the marble's flight (the same arc the server flies him on)
		local m = MC.marble(CFrame.new(from + UP * 1.5), 0.6, MC.ORANGE)
		local stop = addTrail(m.Ball, MC.GLASS, 0.2, 0.5)
		VFX.PlaySound("MarbleThrow", from, 1)
		local t0 = os.clock()
		while os.clock() - t0 < time do
			local s = math.clamp((os.clock() - t0) / time, 0, 1)
			m.set(CFrame.new(from:Lerp(to, s) + UP * (1.5 + 5 * 4 * s * (1 - s))))
			task.wait()
		end
		stop(0.05)
		m.gone(0.05)
	end
	function Effects.MagiciansPop(char, data)
		local pos = typeof(data.Pos) == "Vector3" and data.Pos
		if not pos then
			return
		end
		if char then
			afterimage(char, MC.ORANGE, 0.22)
			VFX.Pose(char, "Present", 0.35)
		end
		billboardRing(pos + UP, 0.5, 14, WHITE, 5, 0.22)
		shockDisc(pos + UP * 0.3, typeof(data.Dir) == "Vector3" and data.Dir or UP, 2, 14, 0.28, MC.GLASS, 4)
		dustPuffs(groundPoint(pos), 1, 6, MC.SMOKE, 0.9, true)
		sparks(pos + UP, 1, WHITE, MC.ORANGE, 12)
		VFX.PlaySound("Decompress", pos, 1)
	end

	-- ULT: the fan of marbles (each one's a RubbleThrow of its own)
	function Effects.MarbleStorm(char, data, isLocal)
		local root = charParts(char)
		if not root then
			return
		end
		if isLocal then
			face(root, flatten(data.Dir, root))
		end
		VFX.Motion(char, "MarbleStorm")
		VFX.PlaySound("Compress", root.Position, 1)
		billboardRing(root.Position + UP * 2, 1, 10, MC.ORANGE, 5, 0.25)
	end

	-- ULT: a slab of the city, taken and dropped out of the sky
	function Effects.CurtainSlab(char, data, isLocal)
		local root = charParts(char)
		local pos = typeof(data.Pos) == "Vector3" and data.Pos
		if not root or not pos then
			return
		end
		if isLocal then
			face(root, flatten(data.Dir, root))
		end
		local time = tonumber(data.Time) or 1
		if typeof(data.From) == "Vector3" then
			MC.suck(data.From, 9, MC.GLASS)
			local taken = MC.chunk(CFrame.new(data.From), 7, data.Color, data.Material)
			for _, e in taken.parts do
				tween(e.part, 0.3, { CFrame = CFrame.new(handPos(char, true)), Size = Vector3.one * 0.1 }, Enum.EasingStyle.Quad, Enum.EasingDirection.In)
				cleanup(e.part, 0.32)
			end
		end
		landingMarker(pos, time - 0.3)
		-- the slab out of the sky
		local slab = MC.chunk(CFrame.new(pos + UP * 70), 9, data.Color, data.Material)
		for _, e in slab.parts do
			local full = e.part.Size
			e.part.Size = full * 0.1
			tween(e.part, 0.12, { Size = full }, Enum.EasingStyle.Back)
		end
		VFX.PlaySound("Decompress", pos + UP * 30, 1.2)
		local t0 = os.clock()
		local fall = time - 0.35
		while os.clock() - t0 < fall and slab.parts[1].part.Parent do
			local s = math.clamp((os.clock() - t0) / fall, 0, 1)
			slab.set(CFrame.new(pos + UP * (70 * (1 - s * s) + 3)) * CFrame.Angles(0, s * 0.6, 0))
			task.wait()
		end
		MC.slab = slab
	end
	function Effects.CurtainDrop(_char, data)
		local pos = typeof(data.Pos) == "Vector3" and data.Pos
		if not pos then
			return
		end
		if MC.slab then
			MC.slab.shatter()
			MC.slab = nil
		end
		dustPuffs(groundPoint(pos), 2.4, 12, Color3.fromRGB(200, 190, 175), 1.3, true)
		rocks(pos, 2, 18)
		shockDisc(pos + UP * 0.3, UP, 3, 40, 0.4, Color3.fromRGB(220, 210, 190), 6)
		billboardRing(pos + UP, 3, 34, MC.ORANGE, 8, 0.35)
		groundMark(groundPoint(pos + UP), 12, Color3.fromRGB(60, 56, 54), 10)
		VFX.PlaySound("RubbleLand", pos, 1.3)
		VFX.PlaySound("Decompress", pos, 1)
		VFX.ShakeAt(pos, 3, 140, 0.5)
		if nearCamera(pos, 90) then
			VFX.ImpactFrame(0.1)
		end
	end

	-- ULT: everyone round him into marbles in his hand, then the lot thrown
	function Effects.DisappearingGrab(char, data)
		local root = charParts(char)
		if not root then
			return
		end
		local held = tonumber(data.Held) or 1.2
		billboardRing(root.Position + UP, 2, 40, MC.GLASS, 6, 0.35)
		VFX.PlaySound("Compress", root.Position, 1.2)
		for _, target in (type(data.Targets) == "table" and data.Targets or {}) do
			local troot = typeof(target) == "Instance" and target:FindFirstChild("HumanoidRootPart")
			if troot then
				MC.suck(troot.Position + UP, 3, MC.GLASS)
				afterimage(target, MC.GLASS, 0.25)
				hideCharacter(target, held + 0.75)
				MC.ride(target, held + 0.9)
			end
		end
	end


	-- the casts (played the moment a move's used, from the aim alone; the
	-- server's effects follow with what happened)
