	-- a dash: a crackle and a streak
	QUIRK_FX.Dash.Electrification = function(char, root, dir)
		DK.crackleOn(char, 0.2, DK.YELLOW)
		DK.zig(root.Position - dir * 4 + UP, root.Position + UP, DK.YELLOW, 0.16, 0.2, 0.5)
		streaks(root.Position - dir + UP, dir, 6, 0.8, 5, 8, DK.YELLOW, 0.2)
		legTrails(char, 0.25, DK.YELLOW)
	end
	-- 1,300,000 VOLTS ((round 101, awaken_e) on the kit, VFX.AK; his clip
	-- anim/moves_awaken_e.py's MoveAwakenElectrification, his numbers
	-- Config.Awaken.Electrification): hunched over his fists, the charge
	-- crawling over him and the light round him flickering - then ON THE HIT
	-- he goes rigid as a lightning rod, arms dead straight out to the sides:
	-- three bolts up off him into the sky, a ring, a disc, sparks, and arcs
	-- cracking out of both hands sideways all through the hold while the
	-- current shakes him. His aura: the rim, static, and arcs crawling over
	-- him for the whole ult, now and then one cracking off into the street
	function DK.awakenCfg()
		return (Config.Awaken or {}).Electrification or {}
	end
	VFX.AK.FX.Electrification = {
		gather = function(ctx)
			local E = DK.awakenCfg()
			local F = E.Flicker or {}
			local climb = math.max(ctx.hit - ctx.gather, 0.06)
			DK.crackleOn(ctx.char, climb, DK.YELLOW)
			for _, right in { true, false } do
				sparks(handPos(ctx.char, right), 0.5 * ctx.scale, WHITE, DK.YELLOW, ctx.low and 3 or 6)
			end
			-- the light round him flickering as it builds
			if not ctx.low then
				local pl = Instance.new("PointLight")
				pl.Name = "AwakenFlicker"
				pl.Color, pl.Range, pl.Brightness = DK.YELLOW, F.Range or 14, 0
				pl.Parent = ctx.root
				cleanup(pl, climb + 0.1)
				task.spawn(function()
					for i = 1, F.Count or 3 do
						pl.Brightness = (F.Light or 4) * (i % 2 == 1 and 1 or 0.25)
						task.wait(F.Gap or 0.04)
						pl.Brightness = 0
						task.wait(F.Gap or 0.04)
					end
				end)
			end
			VFX.AK.note(ctx, "charge")
		end,
		hit = function(ctx)
			local E = DK.awakenCfg()
			local Z, A = E.Zigs or {}, E.Arcs or {}
			local root = ctx.root
			local g = ctx.g or groundPoint(root.Position)
			for k = 1, Z.Count or 3 do
				DK.zig(root.Position, root.Position + UP * (Z.Height or 30) + rng:NextUnitVector() * 4, k == 2 and DK.BLUE or DK.YELLOW, 0.5, 0.6, 2)
			end
			billboardRing(root.Position + UP, 2, 30, DK.YELLOW, 7, 0.4)
			shockDisc(g + UP * 0.3, UP, 2, 26, 0.35, WHITE, 5)
			sparks(root.Position + UP * 2, 1.6, WHITE, DK.YELLOW, ctx.low and 12 or 24)
			-- arcs cracking out of both hands sideways, all through the hold
			-- (never at his own lens)
			local right = ctx.d:Cross(UP)
			local reach = A.Reach or { 6, 10 }
			task.spawn(function()
				local n = 0
				while VFX.AK.alive(ctx) and VFX.AK.now(ctx) < (A.Till or 1.3) do
					for i, side in { 1, -1 } do
						local hand = handPos(ctx.char, i == 1)
						local to = hand + (right * side + UP * rand(-0.35, 0.45) + ctx.d * rand(-0.3, 0.3)).Unit * rand(reach[1], reach[2]) * ctx.scale
						if not VFX.AK.lens(ctx, to, 1) then
							DK.zig(hand, to, (n + i) % 3 == 0 and DK.BLUE or DK.YELLOW, 0.22, 0.14, 0.8)
						end
					end
					n += 1
					VFX.AK.note(ctx, "arcs")
					task.wait((A.Every or 0.12) * (ctx.low and 2 or 1))
				end
			end)
		end,
		aura = function(ctx)
			local stop = VFX.AK.aura(ctx, ctx.spec.Aura or "static")
			local rec = VFX.AK.auras[ctx.char]
			if not rec then
				return stop
			end
			local S = DK.awakenCfg().Static or {}
			local char, root = ctx.char, ctx.root
			-- (all through the ult: arcs crawling over him, now and then one
			-- cracking off into the street)
			task.spawn(function()
				while VFX.AK.auras[char] == rec and char.Parent and root.Parent do
					DK.crackleOn(char, S.Every or 0.3, rng:NextNumber() < 0.7 and DK.YELLOW or DK.BLUE)
					if not ctx.low and rng:NextNumber() < (S.Ground or 0.35) then
						local at = root.Position + UP * rand(0, 2)
						DK.zig(at, groundPoint(at + Vector3.new(rand(-5, 5), 0, rand(-5, 5))), DK.YELLOW, 0.14, 0.18, 0.5)
					end
					task.wait(S.Every or 0.3)
				end
			end)
			return stop
		end,
	}
	-- M1s: every hit crackles
	function VFX.ElectrificationPunch(_char, count, finisher, fist, look)
		for _ = 1, finisher and 4 or 2 do
			DK.arc(fist, fist + (look * 0.6 + rng:NextUnitVector()).Unit * rand(1, finisher and 2.6 or 1.6), DK.YELLOW, 0.07)
		end
		sparks(fist, finisher and 0.9 or 0.4, WHITE, DK.YELLOW, finisher and 10 or 3)
		VFX.PlaySound("ElectricZap", fist, finisher and 1 or 0.55)
		if count == 4 or finisher then
			billboardRing(fist + look, 0.6, 8, DK.YELLOW, 4, 0.18)
		end
	end
	-- the finisher: a hand on them and everything he's got, point blank
	function DK.finisher(char, target, troot, _d, time)
		VFX.Pose(char, "GraspHold", time)
		DK.crackleOn(char, time, DK.YELLOW)
		DK.crackleOn(target, time, DK.YELLOW)
		VFX.PlaySound("StaticCrackle", troot.Position, 1)
		task.wait(time * 0.6)
		if not troot.Parent then
			return
		end
		for k = 1, 3 do
			DK.zig(handPos(char, true), troot.Position + UP, k == 2 and DK.BLUE or DK.YELLOW, 0.35, 0.35, 1.2)
		end
		DK.zap(troot.Position + UP, 1.8, DK.YELLOW)
		VFX.PlaySound("Discharge", troot.Position, 1.1)
	end
	-- the KO burst: a bolt from the sky and lightning everywhere
	function DK.burst(pos, dir)
		for k = 1, 2 do
			DK.zig(pos + UP * 50, pos + UP, k == 1 and DK.YELLOW or DK.BLUE, k == 1 and 0.5 or 0.25, 0.4, 2)
		end
		for i = 1, 10 do
			local a = i / 10 * math.pi * 2
			DK.zig(pos + UP, pos + UP + Vector3.new(math.cos(a), 0.3, math.sin(a)) * rand(6, 12), DK.YELLOW, 0.25, 0.35, 1.2)
		end
		shockDisc(pos, dir, 2, 30, 0.35, WHITE, 5)
		billboardRing(pos, 2, 26, DK.YELLOW, 6, 0.3)
		sparks(pos, 1.5, WHITE, DK.YELLOW, 20)
		VFX.PlaySound("Thunderbolt", pos, 1)
	end
end

---------------------------------------------------------------------------
-- PUPPETS: figures built out of parts - a torso, a head, two arms and two
-- legs, each a list of pieces - and posed every frame from a small pose
-- table. Best Jeanist on the Sky Coffin; All Might and All For One in the
-- sky. Per limb: { pitch (+ forward), yaw (+ inward), roll (+ outward),
-- bend } in degrees - bend folds the elbow / knee (pieces on "foreR" /
-- "shinR" etc. hang off it); head { pitch (+ up), yaw }; lean (+ back),
-- twist (+ left), roll (+ tips right).
---------------------------------------------------------------------------
do
	local PUP = { LIMBS = { "armR", "armL", "legR", "legL" } }
	VFX.PUP = PUP

	function PUP.new(name, scale, outline)
		local model = Instance.new("Model")
		model.Name = name
		model.Parent = folder
		local pp = { model = model, parts = {}, scale = scale or 1, frames = {} }
		if outline then
			local hl = Instance.new("Highlight")
			hl.FillTransparency = 1
			hl.OutlineColor = outline
			hl.OutlineTransparency = 0.2
			hl.DepthMode = Enum.HighlightDepthMode.Occluded
			hl.Adornee = model
			hl.Parent = model
			pp.highlight = hl
		end
		return pp
	end

	-- a piece on a limb (size and offset at scale 1)
	function PUP.part(pp, key, size, offset, color, material, shape)
		local s = pp.scale
		local p = newPart(size * s, CFrame.new(), color, material, shape, pp.model)
		table.insert(pp.parts, { part = p, key = key, offset = offset.Rotation + offset.Position * s })
		if key == "head" and not pp.head then
			pp.head = p
		end
		return p
	end

	function PUP.limb(pivot, spec, side)
		spec = spec or {}
		return pivot * CFrame.Angles(0, math.rad(side * (spec[2] or 0)), 0) * CFrame.Angles(0, 0, math.rad(side * (spec[3] or 0))) * CFrame.Angles(math.rad(spec[1] or 0), 0, 0)
	end

	-- cf: the middle of the torso
	function PUP.place(pp, cf, pose)
		local s = pp.scale
		local torso = cf * CFrame.Angles(0, 0, math.rad(-(pose.roll or 0))) * CFrame.Angles(math.rad(pose.lean or 0), math.rad(pose.twist or 0), 0)
		local head = pose.head or {}
		local f = pp.frames
		f.torso = torso
		f.head = torso * CFrame.new(0, s, 0) * CFrame.Angles(math.rad(head[1] or 0), math.rad(head[2] or 0), 0)
		f.armR = PUP.limb(torso * CFrame.new(1.5 * s, 0.5 * s, 0), pose.armR, 1)
		f.armL = PUP.limb(torso * CFrame.new(-1.5 * s, 0.5 * s, 0), pose.armL, -1)
		f.legR = PUP.limb(torso * CFrame.new(0.5 * s, -s, 0), pose.legR, 1)
		f.legL = PUP.limb(torso * CFrame.new(-0.5 * s, -s, 0), pose.legL, -1)
		-- elbows forward, knees back
		f.foreR = f.armR * CFrame.new(0, -s, 0) * CFrame.Angles(math.rad((pose.armR or {})[4] or 0), 0, 0)
		f.foreL = f.armL * CFrame.new(0, -s, 0) * CFrame.Angles(math.rad((pose.armL or {})[4] or 0), 0, 0)
		f.shinR = f.legR * CFrame.new(0, -s, 0) * CFrame.Angles(math.rad(-((pose.legR or {})[4] or 0)), 0, 0)
		f.shinL = f.legL * CFrame.new(0, -s, 0) * CFrame.Angles(math.rad(-((pose.legL or {})[4] or 0)), 0, 0)
		local parts, cfs = {}, {}
		for i, e in pp.parts do
			parts[i] = e.part
			cfs[i] = f[e.key] * e.offset
		end
		if not pcall(function()
			workspace:BulkMoveTo(parts, cfs, Enum.BulkMoveMode.FireCFrameChanged)
		end) then
			for i, p in parts do
				p.CFrame = cfs[i]
			end
		end
	end

	-- the tip of an arm or leg (a fist, a foot)
	function PUP.tip(pp, key)
		if pp.jointed then
			local lower = key == "armR" and "foreR" or key == "armL" and "foreL" or key == "legR" and "shinR" or "shinL"
			return (pp.frames[lower] * CFrame.new(0, -pp.scale, 0)).Position
		end
		return (pp.frames[key] * CFrame.new(0, -1.5 * pp.scale, 0)).Position
	end

	-- a pose part-way from a to b
	function PUP.blend(a, b, k)
		local out = {}
		for _, key in { "armR", "armL", "legR", "legL", "head" } do
			local x, y = a[key] or {}, b[key] or {}
			out[key] = {}
			for i = 1, 4 do
				local u, v = x[i] or 0, y[i] or 0
				out[key][i] = u + (v - u) * k
			end
		end
		out.lean = (a.lean or 0) + ((b.lean or 0) - (a.lean or 0)) * k
		out.twist = (a.twist or 0) + ((b.twist or 0) - (a.twist or 0)) * k
		out.roll = (a.roll or 0) + ((b.roll or 0) - (a.roll or 0)) * k
		return out
	end

	-- 0 = gone, 1 = fully there (each piece keeps its own see-through-ness)
	function PUP.fade(pp, alpha)
		if pp.alpha == alpha then
			return
		end
		pp.alpha = alpha
		for _, e in pp.parts do
			if not e.nofade then
				e.base = e.base or e.part.Transparency
				e.part.Transparency = 1 - alpha * (1 - e.base)
			end
		end
		if pp.highlight then
			pp.highlight.OutlineTransparency = 1 - alpha * 0.8
		end
	end

	-- a shout over its head
	function PUP.say(pp, text, color, stroke, life, px, far)
		if not pp.head then
			return
		end
		local bb = Instance.new("BillboardGui")
		bb.Size = UDim2.fromOffset(px or 260, math.floor((px or 260) * 0.24))
		bb.StudsOffsetWorldSpace = Vector3.new(0, 2.6 * pp.scale, 0)
		bb.LightInfluence = 0
		bb.MaxDistance = far or 400
		bb.Adornee = pp.head
		bb.Parent = pp.model
		local label = Instance.new("TextLabel")
		label.BackgroundTransparency = 1
		label.Size = UDim2.fromScale(1, 1)
		label.Font = Enum.Font.LuckiestGuy
		label.TextScaled = true
		label.Text = text
		label.TextColor3 = color
		label.TextStrokeColor3 = stroke
		label.TextStrokeTransparency = 0
		label.Rotation = rand(-5, 5)
		label.Parent = bb
		tween(label, life * 0.3, { TextTransparency = 1, TextStrokeTransparency = 1 }, nil, nil, life * 0.7)
		cleanup(bb, life + 0.05)
	end
end

---------------------------------------------------------------------------
-- THE SKY COFFIN's floor defending itself against Decay (chapter 346): the
-- decay creeps over a plate, the plate's fired off into the sky and crumbles
-- to nothing - and BEST JEANIST rappels down out of the sky on a thread and
-- stitches the floor back together: denim fibers shoot from his fingers to
-- every empty socket, weave a mat across it, warp then weft, and it sets
-- hard into a new plate. When it's all mended he tugs his collar straight
-- and zips back up into the sky. (All for the eyes: nobody's hurt by it.)
---------------------------------------------------------------------------
do
	local ST = {
		LAWN = Color3.fromRGB(128, 166, 72),
		DECAYED = Color3.fromRGB(112, 100, 98),
		CRACK = Color3.fromRGB(36, 26, 30),
		DUST = Color3.fromRGB(150, 140, 142),
		SOCKET = Color3.fromRGB(28, 30, 34),
		DENIM = Color3.fromRGB(52, 78, 126),
		DENIM_LIGHT = Color3.fromRGB(116, 146, 196),
		JEANS = Color3.fromRGB(36, 54, 92),
		crew = {}, -- the Jeanists on duty
		snapAt = 0,
	}
	ST.POSES = {
		drop = { armR = { 172, 0, 4 }, armL = { 24, 0, 22 }, legR = { 12, 0, 4 }, legL = { -8, 0, 4 }, head = { -12, 0 } },
		land = { armR = { 56, -24, 44 }, armL = { 56, -24, 44 }, legR = { 42, 0, 12 }, legL = { -34, 0, 12 }, head = { 4, 0 }, lean = -20 },
		fibers = { armR = { 86, -26, 16 }, armL = { 86, -26, 16 }, legR = { 16, 0, 9 }, legL = { -12, 0, 9 }, head = { 2, 0 }, lean = 5 },
		collar = { armR = { 152, 50, 0 }, armL = { 12, 0, 8 }, legR = { 2, 0, 4 }, legL = { -2, 0, 4 }, head = { 10, -12 }, lean = 3 },
		zip = { armR = { 178, 0, 0 }, armL = { 176, 0, 0 }, legR = { -10, 0, 2 }, legL = { 10, 0, 2 }, head = { 18, 0 } },
	}

	-- the man himself: denim jacket and jeans, the high collar up over his
	-- mouth and nose, swept blond hair, a sharp stare
	function ST.jeanist()
		local PUP = VFX.PUP
		local pp = PUP.new("BestJeanist", 1.1, Color3.fromRGB(18, 24, 46))
		local D, DL, M = ST.DENIM, ST.DENIM_LIGHT, Enum.Material.Fabric
		local SKIN, HAIR = Color3.fromRGB(238, 200, 164), Color3.fromRGB(246, 222, 132)
		PUP.part(pp, "torso", Vector3.new(2, 2, 1), CFrame.new(), D, M)
		for side = -1, 1, 2 do
			PUP.part(pp, "torso", Vector3.new(0.08, 1.9, 0.05), CFrame.new(side * 0.18, 0, -0.52), DL, M)
			PUP.part(pp, "torso", Vector3.new(0.55, 0.42, 0.05), CFrame.new(side * 0.56, 0.42, -0.52), DL, M)
		end
		PUP.part(pp, "torso", Vector3.new(2.04, 0.26, 1.04), CFrame.new(0, -0.86, 0), Color3.fromRGB(96, 62, 36))
		PUP.part(pp, "torso", Vector3.new(0.42, 0.22, 0.08), CFrame.new(0, -0.86, -0.54), GOLD, Enum.Material.Metal)
		PUP.part(pp, "head", Vector3.new(1.1, 1.15, 1.1), CFrame.new(0, 0.62, 0), SKIN)
		PUP.part(pp, "head", Vector3.new(1.42, 0.95, 1.32), CFrame.new(0, 0.34, 0.02), D, M)
		PUP.part(pp, "head", Vector3.new(1.46, 0.1, 1.36), CFrame.new(0, 0.82, 0.02), DL, M)
		PUP.part(pp, "head", Vector3.new(1.2, 0.45, 1.2), CFrame.new(0, 1.3, 0.04), HAIR)
		PUP.part(pp, "head", Vector3.new(0.78, 0.55, 0.3), CFrame.new(-0.2, 1.1, -0.5) * CFrame.Angles(0, 0, math.rad(-18)), HAIR)
		PUP.part(pp, "head", Vector3.new(0.4, 0.5, 1.1), CFrame.new(0.5, 1.04, 0.05), HAIR)
		for side = -1, 1, 2 do
			PUP.part(pp, "head", Vector3.new(0.26, 0.07, 0.05), CFrame.new(side * 0.24, 0.94, -0.56), Color3.fromRGB(28, 32, 54))
		end
		for _, key in { "armR", "armL" } do
			PUP.part(pp, key, Vector3.new(1, 1.6, 1), CFrame.new(0, -0.3, 0), D, M)
			PUP.part(pp, key, Vector3.new(1.06, 0.26, 1.06), CFrame.new(0, -1.1, 0), DL, M)
			PUP.part(pp, key, Vector3.new(0.86, 0.5, 0.86), CFrame.new(0, -1.45, 0), SKIN)
		end
		for _, key in { "legR", "legL" } do
			PUP.part(pp, key, Vector3.new(1, 1.6, 1), CFrame.new(0, -0.8, 0), ST.JEANS, M)
			PUP.part(pp, key, Vector3.new(1.04, 0.5, 1.2), CFrame.new(0, -1.75, -0.08), Color3.fromRGB(58, 40, 30))
		end
		return pp
	end

	-- a thread: a strand of denim from his hand out to a point
	function ST.line(j, to, hand)
		local part = newPart(Vector3.new(0.14, 0.14, 1), CFrame.new(to), ST.DENIM_LIGHT, Enum.Material.Fabric)
		local line = { part = part, to = to, hand = hand, t0 = os.clock() }
		j.lines[line] = true
		return line
	end

	-- the Jeanist on duty near here (or a new one, rappelling in)
	function ST.jeanistFor(from, extent)
		local cfg = Config.SkyCoffin or {}
		local center = cfg.Center
		for _, j in ST.crew do
			if j.state ~= "leave" and (j.spot - from).Magnitude < 170 then
				return j
			end
		end
		if #ST.crew >= 3 then
			return ST.crew[#ST.crew]
		end
		local toMid = Vector3.new(center.X - from.X, 0, center.Z - from.Z)
		local dir = toMid.Magnitude > 5 and toMid.Unit or Vector3.new(1, 0, 0)
		local spot = from + dir * math.clamp(extent + 12, 30, 80)
		local flat = Vector3.new(spot.X - center.X, 0, spot.Z - center.Z)
		local LR = (cfg.Radius or 425) - 34
		if flat.Magnitude > LR then
			flat = flat.Unit * LR
		end
		spot = Vector3.new(center.X + flat.X, center.Y, center.Z + flat.Z)
		local s = 1.1
		local j = {
			pp = ST.jeanist(),
			spot = spot,
			stand = spot + UP * 3 * s,
			look = -dir,
			state = "enter",
			t0 = os.clock(),
			pose = ST.POSES.drop,
			queue = {},
			lines = {},
			active = 0,
			idleSince = nil,
		}
		j.sky = ST.line(j, j.stand + UP * 160, "armR")
		table.insert(ST.crew, j)
		VFX.PlaySound("Swish", spot, 1)
		return j
	end

	-- one socket stitched shut: a fiber out to it, the weave, the new plate
	function ST.stitch(j, job)
		j.active += 1
		local T, cf = job.T, job.cf
		local w = T - 0.3
		local hand = rng:NextNumber() < 0.5 and "armR" or "armL"
		local line = ST.line(j, cf.Position + UP * 0.25, hand)
		task.wait(0.2)
		local strips = {}
		if job.extra then
			-- warp, then weft, as fast as a sewing machine
			for pass = 1, 2 do
				for k = 1, 5 do
					local off = (k - 3) * w / 5
					local at = pass == 1 and CFrame.new(0, 0.2, off) or CFrame.new(off, 0.28, 0)
					local full = pass == 1 and Vector3.new(w, 0.1, 0.36) or Vector3.new(0.36, 0.1, w)
					local strip = newPart(pass == 1 and Vector3.new(0.2, 0.1, 0.36) or Vector3.new(0.36, 0.1, 0.2), cf * at, k % 2 == 0 and ST.DENIM_LIGHT or ST.DENIM, Enum.Material.Fabric)
					tween(strip, 0.1, { Size = full })
					table.insert(strips, strip)
					task.wait(0.03)
				end
			end
		else
			local mat = newPart(Vector3.new(0.3, 0.12, 0.3), cf * CFrame.new(0, 0.22, 0), ST.DENIM, Enum.Material.Fabric)
			tween(mat, 0.3, { Size = Vector3.new(w, 0.12, w) })
			table.insert(strips, mat)
			task.wait(0.3)
		end
		-- it sets hard into a new plate, and the lawn comes back over it
		local plate = newPart(Vector3.new(w, 0.3, w), cf * CFrame.new(0, 0.16, 0), ST.DENIM, Enum.Material.Fabric)
		plate.Transparency = 1
		tween(plate, 0.12, { Transparency = 0 })
		task.wait(0.12)
		if job.socket then
			job.socket:Destroy()
		end
		for _, strip in strips do
			strip:Destroy()
		end
		plate.Material = Enum.Material.Grass
		tween(plate, 0.35, { Color = ST.LAWN })
		if job.extra then
			for _, e in { { 0, w / 2, w, 0.25 }, { 0, -w / 2, w, 0.25 }, { w / 2, 0, 0.25, w }, { -w / 2, 0, 0.25, w } } do
				local edge = newPart(Vector3.new(e[3], 0.08, e[4]), cf * CFrame.new(e[1], 0.34, e[2]), ST.DENIM_LIGHT, Enum.Material.Neon)
				tween(edge, 0.35, { Transparency = 1 })
				cleanup(edge, 0.4)
			end
		end
		if os.clock() - ST.snapAt > 0.15 then
			ST.snapAt = os.clock()
			VFX.PlaySound("Snap", cf.Position, 0.7)
		end
		-- the fiber snaps back to his hand
		line.back = os.clock()
		tween(plate, 0.3, { Transparency = 1 }, nil, nil, 0.45)
		cleanup(plate, 0.8)
		task.wait(0.2)
		j.lines[line] = nil
		line.part:Destroy()
		j.active -= 1
	end

	-- one plate (cf: the middle of its top face, on the lawn)
	function ST.plate(cf, T, big, from, extent)
		local extra = not big or rng:NextNumber() < 0.35
		local top = newPart(Vector3.new(T - 0.3, 0.3, T - 0.3), cf * CFrame.new(0, 0.16, 0), ST.LAWN, Enum.Material.Grass)
		top.Name = "Plate"
		-- the decay creeps over it
		tween(top, 0.22, { Color = ST.DECAYED })
		local cracks = {}
		if extra then
			for _ = 1, 2 do
				local c = newPart(Vector3.new(T * rand(0.5, 0.9), 0.06, 0.2), cf * CFrame.new(rand(-T / 4, T / 4), 0.33, rand(-T / 4, T / 4)) * CFrame.Angles(0, rand(0, math.pi), 0), ST.CRACK, Enum.Material.Slate)
				c.Transparency = 1
				tween(c, 0.18, { Transparency = 0 })
				table.insert(cracks, c)
			end
		end
		task.wait(0.24)
		-- the socket it leaves, and the plate fired off: a slab spinning up into
		-- the sky, crumbling away as it goes
		local socket = newPart(Vector3.new(T - 0.2, 0.12, T - 0.2), cf * CFrame.new(0, 0.07, 0), ST.SOCKET, Enum.Material.Metal)
		socket.Name = "Socket"
		top.Material = Enum.Material.Slate
		top.Size = Vector3.new(T - 0.3, 1.6, T - 0.3)
		local height, life = rand(70, 150), rand(1.1, 1.6)
		local flyTo = cf * CFrame.new(rand(-6, 6), height, rand(-6, 6)) * CFrame.Angles(rand(-1.2, 1.2), rand(-2, 2), rand(-1.2, 1.2))
		tween(top, life, { CFrame = flyTo, Size = Vector3.new(T * 0.3, 0.5, T * 0.3), Transparency = 1 }, Enum.EasingStyle.Quad)
		cleanup(top, life + 0.05)
		cleanup(socket, 5) -- (in case nobody comes for it)
		for _, c in cracks do
			c:Destroy()
		end
		if extra then
			-- the launcher's kick out of the seams: chips of plate and decay dust
			for _ = 1, 3 do
				local chunk = newPart(Vector3.one * rand(0.6, 1.4), cf * CFrame.new(rand(-T / 2, T / 2), 0.6, rand(-T / 2, T / 2)), ST.DUST, Enum.Material.Slate)
				local t = rand(0.8, 1.3)
				tween(chunk, t, { CFrame = chunk.CFrame * CFrame.new(rand(-5, 5), rand(25, 70), rand(-5, 5)) * CFrame.Angles(rand(0, 6), rand(0, 6), rand(0, 6)), Transparency = 1, Size = Vector3.one * 0.2 })
				cleanup(chunk, t + 0.05)
			end
		end
		-- and Best Jeanist sees to the hole
		local j = ST.jeanistFor(from, extent)
		table.insert(j.queue, { cf = cf, T = T, extra = extra, socket = socket, at = os.clock() + rand(0.2, 0.45) })
	end

	function ST.step(dt)
		local now = os.clock()
		local PUP = VFX.PUP
		local k = 1 - math.exp(-dt * 12)
		for i = #ST.crew, 1, -1 do
			local j = ST.crew[i]
			local t = now - j.t0
			local cf, target = nil, ST.POSES.fibers
			if j.state == "enter" then
				-- down the thread out of the sky, landing in a crouch
				local u = math.clamp(t / 0.55, 0, 1)
				local drop = (1 - u) ^ 2 * 120
				cf = CFrame.lookAt(j.stand + UP * drop, j.stand + UP * drop + j.look)
				target = ST.POSES.drop
				if u >= 1 then
					j.state, j.t0 = "work", now
					j.pose = ST.POSES.land
					j.sky.back = now
					shockDisc(j.spot + UP * 0.2, UP, 2, 14, 0.35, ST.DENIM_LIGHT, 0)
					dustPuffs(j.spot, 1, 6, ST.DUST, 0.6)
					PUP.say(j.pp, "FIBER MASTER!", ST.DENIM_LIGHT, Color3.fromRGB(14, 22, 48), 1.6)
					VFX.PlaySound("Scarf", j.spot, 1.1)
				end
			elseif j.state == "work" then
				local busy = j.active > 0 or #j.queue > 0
				-- turn to the holes he's working on
				local sum, n = Vector3.zero, 0
				for line in j.lines do
					if line ~= j.sky then
						sum += line.to
						n += 1
					end
				end
				if n > 0 then
					local d = Vector3.new(sum.X / n - j.stand.X, 0, sum.Z / n - j.stand.Z)
					if d.Magnitude > 1 then
						j.look = j.look:Lerp(d.Unit, k * 0.5)
					end
				end
				cf = CFrame.lookAt(j.stand, j.stand + j.look)
				local wiggle = math.sin(now * 18) * 6
				target = {
					armR = { 86 + wiggle, -26, 16 }, armL = { 86 - wiggle, -26, 16 },
					legR = ST.POSES.fibers.legR, legL = ST.POSES.fibers.legL, head = ST.POSES.fibers.head, lean = 5,
				}
				if t < 0.25 then
					target = ST.POSES.land
				end
				for q = #j.queue, 1, -1 do
					local job = j.queue[q]
					if now >= job.at and t >= 0.2 then
						table.remove(j.queue, q)
						task.spawn(ST.stitch, j, job)
					end
				end
				if busy then
					j.idleSince = nil
				elseif not j.idleSince then
					j.idleSince = now
				elseif now - j.idleSince > 0.6 then
					j.state, j.t0 = "leave", now
					PUP.say(j.pp, "A perfect fit.", ST.DENIM_LIGHT, Color3.fromRGB(14, 22, 48), 1.4)
				end
			elseif #j.queue > 0 and t < 0.7 then
				j.state, j.t0 = "work", now - 0.3 -- (more holes before he's gone: back to it)
				cf = CFrame.lookAt(j.stand, j.stand + j.look)
			else
				-- a tug at his collar, then back up his thread into the sky
				target = t < 0.7 and ST.POSES.collar or ST.POSES.zip
				local u = math.clamp((t - 0.7) / 0.5, 0, 1)
				cf = CFrame.lookAt(j.stand + UP * u * u * 140, j.stand + UP * u * u * 140 + j.look)
				if t >= 0.7 and not j.up then
					j.up = ST.line(j, j.stand + UP * 170, "armR")
					VFX.PlaySound("Swish", j.spot, 1)
				end
				PUP.fade(j.pp, 1 - math.clamp((t - 0.95) / 0.25, 0, 1))
				if t > 1.25 then
					for line in j.lines do
						line.part:Destroy()
					end
					j.pp.model:Destroy()
					table.remove(ST.crew, i)
					continue
				end
			end
			j.pose = PUP.blend(j.pose, target, k)
			PUP.place(j.pp, cf, j.pose)
			-- the fibers, from his hands out to their tips
			for line in j.lines do
				local hand = PUP.tip(j.pp, line.hand)
				local reach = line.back and 1 - math.clamp((now - line.back) / 0.18, 0, 1) or math.clamp((now - line.t0) / 0.18, 0, 1)
				local tip = hand:Lerp(line.to, reach)
				local len = (tip - hand).Magnitude
				line.part.Transparency = len < 0.2 and 1 or 0
				line.part.Size = Vector3.new(0.14, 0.14, math.max(len, 0.1))
				line.part.CFrame = CFrame.lookAt((hand + tip) / 2, tip + Vector3.new(0, 1e-3, 0))
			end
		end
	end
	RunService.RenderStepped:Connect(ST.step)

	function Effects.SkyTiles(_, data)
		local cfg = Config.SkyCoffin or {}
		local center = cfg.Center
		if not center or type(data.Tiles) ~= "table" then
			return
		end
		local from = typeof(data.From) == "Vector3" and data.From or center
		if not nearCamera(from, 700) then
			return
		end
		local T = 12
		local big = #data.Tiles > 40
		local extent = 0
		local cfs = {}
		for _, t in data.Tiles do
			local ix, iz = tonumber(t[1]), tonumber(t[2])
			if ix and iz then
				local cf = CFrame.new(center + Vector3.new((ix + 0.5) * T, 0, (iz + 0.5) * T))
				extent = math.max(extent, (Vector3.new(cf.X - from.X, 0, cf.Z - from.Z)).Magnitude)
				table.insert(cfs, cf)
			end
		end
		extent = math.max(extent, math.min(tonumber(data.Reach) or 0, 160))
		local ground = Vector3.new(from.X, center.Y, from.Z)
		for _, cf in cfs do
			task.delay(rand(0, 0.08), ST.plate, cf, T, big, ground, extent)
		end
		VFX.PlaySound("Crumble", from, 1.1)
		task.delay(0.24, function()
			VFX.PlaySound("Leap", from, 0.9)
		end)
	end
end

---------------------------------------------------------------------------
-- ALL MIGHT vs ALL FOR ONE, in the sky. Every few minutes (Config.SkyBattle)
-- the two of them tear across the sky over wherever you are - the city or
-- the Sky Coffin - on everyone's screen at once. They fly: in on long arcs,
-- a loop chase, a corkscrew climb, weaving through Rivet Stab, a plummet and
-- back up. And they fight with elbows and knees: guards, jabs, hooks,
-- uppercuts, kicks, All For One's arm swelling to three times its size -
-- every hit a boom you feel, arriving late like thunder. Air Cannon punched
-- out of the air by a DETROIT SMASH; a clash that rings the clouds; CAROLINA
-- SMASH into the arm; "I AM HERE!" and a TEXAS SMASH; a warp gate at his
-- back; "GO BEYOND! PLUS ULTRA!" and the UNITED STATES OF SMASH that sends
-- him off over the horizon. Then All Might turns and points at you: "NEXT...
-- IT'S YOUR TURN." (Kamino, chapters 88-94.)
---------------------------------------------------------------------------
