	-- ...rockets straight up on a column of fire with them in his arms...
	function Effects.SkyProminenceRise(char, data)
		local root = charParts(char)
		if not root then
			return
		end
		local time = tonumber(data.Time) or 1.1
		VFX.Pose(char, "SkyHold", time + 0.4)
		VFX.PlaySound("SkyRise", root.Position, 1.2)
		local j = B.jet({ From = root.Position - UP * 2.5, Dir = -UP, Length = 26, Width = 8, Pal = "hell", Rolls = 3 })
		local t0 = os.clock()
		while os.clock() - t0 < time and root.Parent do
			j.aim(root.Position - UP * 2.5, -UP)
			task.wait()
		end
		j.stop(0.4)
		local from = typeof(data.From) == "Vector3" and data.From
