		task.delay(2.2, function()
			col.kill(0.8)
		end)
		for k = 1, 3 do
			task.delay(k * 0.1, function()
				shockDisc(pos, UP, 6, 90 + k * 30, 0.6, k == 2 and B.PAL.hell.body or WHITE)
				billboardRing(pos, 6, 80 + k * 20, WHITE, 10, 0.5)
			end)
		end
		if nearCamera(pos, 500) then
			VFX.Hooks.Flash(Color3.fromRGB(255, 244, 214), 0.35)
			VFX.Hooks.Callout("PLUS ULTRA!!", B.PAL.hell.body)
