	local function tpose(yaw, up)
		return { Hips = { 0, yaw, 0, 0, up, 0 }, RightArm = { 0, 0, 90 }, LeftArm = { 0, 0, 90 }, RightElbow = 0, LeftElbow = 0 }
	end
	MOTIONS.EmoteTPose = {
		{ pose = tpose(0, 0), t = 0.04, hold = 0.7, style = SNAP },
		{ pose = tpose(90, 0.4), t = 0.55 }, { pose = tpose(180, 0.8), t = 0.55 },
		{ pose = tpose(270, 1.1), t = 0.55 }, { pose = tpose(360, 1.3), t = 0.55, hold = 0.8 },
		recover = 0.3,
	}
	EM.props.TPose = function(char, token, root)
		VFX.PlaySound("Bell", root.Position, 0.8)
		EM.label(root, "ASSERTING DOMINANCE", Color3.fromRGB(255, 70, 70), 24, 3.6, 1)
		local t0 = os.clock()
		while os.clock() - t0 < 3.6 and EM.alive(char, token, root) do
			dustPuffs(groundPoint(root.Position), 0.4, 1, Color3.fromRGB(200, 196, 190), 0.8)
			task.wait(0.4)
		end
	end

