	POSES.GriddyL = { Hips = { 0, 0, 0, 0, 0.25, 0 }, LeftLeg = -40, LeftKnee = 100, RightLeg = 10, RightKnee = 12, LeftArm = { 50, 0, 20 }, RightArm = { -40, 0, 20 }, Waist = { -10, -14, 0 }, Neck = { 6, 10, 0 } }
