	---------------------------------------------------------------------------
	POSES.NapSit = { Hips = { 0, 0, 0, 0, -2, 0 }, RightLeg = 90, LeftLeg = 90, RightArm = { 25, 0, 25 }, LeftArm = { 25, 0, 25 }, Waist = { -12, 0, 0 }, Neck = { -32, 0, 10 } }
	POSES.NapWake = { Hips = { 0, 0, 0, 0, -1.6, 0 }, RightLeg = 90, LeftLeg = 90, RightArm = { 60, 0, 50 }, LeftArm = { 60, 0, 50 }, Waist = { 6, 0, 0 }, Neck = { 14, 0, 0 } }
	MOTIONS.EmoteNap = { { pose = "NapSit", t = 0.4, hold = 4.6 }, { pose = "NapWake", t = 0.06, hold = 0.7, style = SNAP }, recover = 0.4 }
	EM.props.Nap = function(char, token, root)
		local head = char:FindFirstChild("Head")
		if not head then
			return
		end
		local bag = EM.bag()
		local bubble = part(bag, Vector3.one * 0.2, head.CFrame, Color3.fromRGB(190, 230, 255), Enum.Material.Glass, Enum.PartType.Ball)
		bubble.Transparency = 0.45
		local t0 = os.clock()
		local lastZ = 0
		while os.clock() - t0 < 5 and EM.alive(char, token, root) do
			local t = os.clock() - t0
			-- breathing in and out, bigger and bigger - then pop
			local s = 0.2 + (0.35 + 0.5 * math.clamp((t - 2.5) / 2, 0, 1)) * (0.5 + 0.5 * math.sin(t * 4.5))
			bubble.Size = Vector3.one * s
			bubble.CFrame = head.CFrame * CFrame.new(0.12, -0.1 - s * 0.2, -0.55 - s * 0.45)
			if t - lastZ > 0.7 then
				lastZ = t
				EM.label(root, "Z", Color3.fromRGB(200, 220, 255), 24 + rng:NextInteger(0, 12), 1.4, 2.5)
			end
			task.wait()
		end
		if EM.alive(char, token, root) then
			VFX.PlaySound("MarblePop", bubble.Position, 0.8)
			sparks(bubble.Position, 0.5, Color3.fromRGB(220, 240, 255), Color3.fromRGB(160, 210, 255), 8)
			VFX.SpeechBubble(char, "!?", 0.8)
		end
		bag:Destroy()
	end

