	-- FAKE DEATH
	---------------------------------------------------------------------------
	POSES.DeathClutch = { RightArm = { 70, 0, -45 }, LeftArm = { 40, 0, 50 }, Waist = { -20, 15, 10 }, Neck = { -15, 0, 15 }, RightKnee = 30, LeftKnee = 20, Crouch = 0.3 }
	POSES.DeathStagger = { Hips = { 0, 0, 0, 0.4, 0, 0 }, Waist = { 15, -10, -15 }, Neck = { 20, 0, -10 }, RightArm = { 120, 0, 40 }, LeftArm = { -20, 0, 30 } }
	POSES.DeathLie = { Hips = { 86, 0, 0, 0, -2.4, 0.6 }, RightArm = { 0, 0, 80 }, LeftArm = { 0, 0, 80 }, Neck = { 0, 0, 20 }, RightLeg = 4, LeftLeg = -4 }
	POSES.DeathJK = { Hips = { 0, 0, 0, 0, 0.3, 0 }, RightArm = { 95, 0, -10 }, RightElbow = 80, LeftArm = { 10, 0, 30 }, Waist = { 4, -14, 0 }, Neck = { 6, 12, 0 } }
	MOTIONS.EmoteFakeDeath = {
		{ pose = "DeathClutch", t = 0.25, hold = 0.7 },
		{ pose = "DeathStagger", t = 0.2, hold = 0.3 },
		{ pose = "DeathLie", t = 0.35, hold = 2.4, style = Enum.EasingStyle.Quad },
		{ pose = "DeathJK", t = 0.1, hold = 0.9, style = SNAP },
		recover = 0.35,
	}
	EM.props.FakeDeath = function(char, token, root)
		VFX.SpeechBubble(char, "ugh... tell my mom...", 1)
		task.wait(1.6)
		if not EM.alive(char, token, root) then
			return
		end
		VFX.PlaySound("KO", root.Position, 0.7)
		-- his soul, floating up out of him, halo and all
		local bag = EM.bag()
		local ghost = {}
		for _, p in char:GetChildren() do
			if p:IsA("BasePart") and p.Name ~= "HumanoidRootPart" and p.Transparency < 1 then
				local g = p:Clone()
				if g then
					g:ClearAllChildren()
					g.Anchored, g.CanCollide, g.CanQuery, g.CanTouch, g.CastShadow = true, false, false, false, false
					g.Material = Enum.Material.Neon
					g.Color = Color3.fromRGB(230, 240, 255)
					g.Transparency = 0.55
					g.Name = "EmoteProp"
					g.Parent = bag
					table.insert(ghost, { g, root.CFrame:ToObjectSpace(p.CFrame) })
				end
			end
		end
		local head = char:FindFirstChild("Head")
		local halo = part(bag, Vector3.new(0.12, 1.3, 1.3), CFrame.new(), Color3.fromRGB(255, 230, 110), Enum.Material.Neon, Enum.PartType.Cylinder)
		local hole = part(bag, Vector3.new(0.14, 0.95, 0.95), CFrame.new(), Color3.new(0, 0, 0), nil, Enum.PartType.Cylinder)
		hole.Transparency = 1
		local base = root.CFrame
		local t0 = os.clock()
		while os.clock() - t0 < 2.2 and EM.alive(char, token, root) do
			local t = os.clock() - t0
			-- up, swaying; then yanked back down into him
			local rise = t < 1.7 and (t / 1.7) * 5 or 5 * (1 - (t - 1.7) / 0.5)
			local cf = base * CFrame.new(math.sin(t * 5) * 0.4, rise, 0)
			for _, gp in ghost do
				gp[1].CFrame = cf * gp[2]
			end
			local top = head and (cf * base:ToObjectSpace(head.CFrame)) or cf
			halo.CFrame = CFrame.new(top.Position + UP * 1.1) * CFrame.Angles(0, 0, math.pi / 2)
			hole.CFrame = halo.CFrame
			task.wait()
		end
		bag:Destroy()
		if EM.alive(char, token, root) then
			VFX.SpeechBubble(char, "JK!!", 1)
			VFX.PlaySound("Confetti", root.Position, 0.8)
			sparks(root.Position + UP * 2, 1, Color3.fromRGB(255, 230, 120), Color3.fromRGB(120, 220, 255), 16)
		end
	end

	---------------------------------------------------------------------------
	-- WHY ARE YOU CRYING (round 72), to 我真的特别爱你 (为什么你会流泪): 36
	-- beats at the song's 116.9 bpm. Shy (beats 1-2), a huge breath while the
	-- song drops out (3-4), down on one knee on the hook under a big pastel
	-- heart - "I REALLY LOVE YOU!!" (5-12). The heart cracks in two (13). He
	-- falls apart: sobbing into his hands, anime waterfall tears, a rain
	-- cloud all his own (13-20); on his knees pounding the street and wailing
	-- at the sky, a puddle growing under him (21-28); a tantrum face down on
	-- the floor (29-32). Then he's up like nothing happened, dabs his eyes
	-- with a hanky (33-34), and a smug finger heart: "why are YOU crying?"
	-- (35-36). (Its own function: this script is near Luau's local limit.)
	---------------------------------------------------------------------------
	;(function()
		local entry = {}
		for _, e in Config.Emotes or {} do
			if e.Id == "WhyCry" then
				entry = e
			end
		end
		local B = 60 / (entry.Bpm or 116.9)
		local BEATS = 36
		local function beat(pose, beats, style)
			local t = math.min(0.12, B * beats * 0.4)
			return { pose = pose, t = t, hold = B * beats - t, style = style or SNAP }
		end
		local m = { recover = 0.45 }
		local function add(step)
			table.insert(m, step)
		end
		-- 1-2: shy - hands behind his back, a toe scuffing the street, swaying
		for k = 1, 2 do
			local s = k % 2 == 0 and 1 or -1
			add(beat({
				RightArm = { -30, 0, -20 }, RightElbow = 40, LeftArm = { -30, 0, -20 }, LeftElbow = 40,
				Waist = { 4, 10 * s, 6 * s }, Neck = { 14, -10 * s, 16 * s }, RightLeg = 16, RightKnee = 30, LeftKnee = 6,
				Hips = { 0, 8 * s, 0, 0.12 * s, 0, 0 },
			}, 1, Enum.EasingStyle.Sine))
		end
		-- 3-4 (the song drops out): a HUGE breath in... and hold it
		add(beat({ RightArm = { 20, 0, 34 }, LeftArm = { 20, 0, 34 }, RightElbow = 20, LeftElbow = 20, Waist = { 12, 0, 0 }, Neck = { -20, 0, 0 }, Hips = { 0, 0, 0, 0, 0.15, 0 } }, 1, Enum.EasingStyle.Sine))
		add(beat({ RightArm = { 26, 0, 40 }, LeftArm = { 26, 0, 40 }, RightElbow = 24, LeftElbow = 24, Waist = { 17, 0, 0 }, Neck = { -26, 0, 0 }, Hips = { 0, 0, 0, 0, 0.22, 0 } }, 1))
		-- 5-12 (the hook): down on one knee, a hand on his heart, the other
		-- reaching out to you, rocking with it
		for k = 1, 4 do
			local s = k % 2 == 0 and 1 or -1
			add(beat({
				Hips = { 0, 0, 0, 0.1 * s, -1.25, 0 }, Crouch = 1, RightLeg = 62, RightKnee = 90, LeftLeg = -58, LeftKnee = 95,
				RightArm = { 96 + 8 * s, 0, 12 }, RightElbow = 4, LeftArm = { 45, 0, -42 }, LeftElbow = 110,
				Waist = { -4, -10 + 5 * s, 5 * s }, Neck = { -16, 0, 9 * s },
			}, 2, k == 1 and Enum.EasingStyle.Back or Enum.EasingStyle.Sine))
		end
		-- 13: it cracks - he jumps out of his skin
		add(beat({ RightArm = { 150, 0, 40 }, LeftArm = { 150, 0, 40 }, RightElbow = 20, LeftElbow = 20, Waist = { 14, 0, 0 }, Neck = { -22, 0, 0 }, Hips = { 0, 0, 0, 0, 0.3, 0 }, RightLeg = 10, LeftLeg = -10 }, 1))
		-- 14-20: sobbing into his hands, shoulders heaving every half beat
		for k = 1, 14 do
			local s = k % 2 == 0 and 1 or -1
			add(beat({
				RightArm = { 128 + 4 * s, 0, -40 }, RightElbow = 60, LeftArm = { 128 + 4 * s, 0, -40 }, LeftElbow = 60,
				Waist = { -22 + 7 * s, 0, 0 }, Neck = { 20 - 6 * s, 0, 0 }, RightKnee = 18, LeftKnee = 18,
				Hips = { 0, 0, 0, 0, -0.25 + 0.12 * s, 0 },
			}, 0.5, Enum.EasingStyle.Sine))
		end
		-- 21-28: on his knees - pound, pound, pound, WAIL at the sky (twice)
		local function kneel(p)
			p.Hips, p.Crouch, p.RightLeg, p.LeftLeg, p.RightKnee, p.LeftKnee = { 0, 0, 0, 0, -1.6, 0 }, 1.3, -69, -69, 100, 100
			return p
		end
		for _ = 1, 2 do
			for k = 1, 3 do
				local s = k % 2 == 0 and 1 or -1
				add(beat(kneel({
					RightArm = s > 0 and { 150, 0, 20 } or { 40, 0, -6 }, RightElbow = s > 0 and 40 or 0,
					LeftArm = s > 0 and { 40, 0, -6 } or { 150, 0, 20 }, LeftElbow = s > 0 and 0 or 40,
					Waist = { -38, 8 * s, 0 }, Neck = { 12, 0, 0 },
				}), 1))
			end
			add(beat(kneel({ RightArm = { 165, 0, 30 }, LeftArm = { 165, 0, 30 }, RightElbow = 10, LeftElbow = 10, Waist = { 12, 0, 0 }, Neck = { -38, 0, 0 } }), 1, Enum.EasingStyle.Back))
		end
		-- 29-32: a tantrum, face down on the floor, fists and feet going
		for k = 1, 8 do
			local s = k % 2 == 0 and 1 or -1
			add(beat({
				Hips = { -84, 0, 0, 0, -2.3, -0.6 }, Crouch = 1.6, RightLeg = s > 0 and -35 or 0, RightKnee = s > 0 and 100 or 20,
				LeftLeg = s > 0 and 0 or -35, LeftKnee = s > 0 and 20 or 100,
				RightArm = { 160, 0, s > 0 and 30 or 10 }, RightElbow = s > 0 and 60 or 10, LeftArm = { 160, 0, s > 0 and 10 or 30 }, LeftElbow = s > 0 and 10 or 60,
				Neck = { -30, 12 * s, 0 },
			}, 0.5, Enum.EasingStyle.Sine))
		end
		-- 33-34: up like nothing happened, dabbing his eyes with a hanky
		for k = 1, 4 do
			local s = k % 2 == 0 and 1 or -1
			add(beat({
				RightArm = { 128, 0, -32 }, RightElbow = 70, LeftArm = { 10, 0, 18 }, LeftElbow = 20,
				Waist = { 2, 8 * s, 0 }, Neck = { -4, -10 * s, 10 * s },
			}, 0.5, k == 1 and SNAP or Enum.EasingStyle.Sine))
		end
		-- 35-36: a smug finger heart, a hip popped, a wink
		add(beat({
			RightArm = { 82, 0, -12 }, RightElbow = 42, LeftArm = { -8, 0, 22 }, LeftElbow = 70,
			Waist = { 6, -16, 0 }, Neck = { -6, 20, 14 }, Hips = { 0, -10, 0, 0.22, 0, 0 }, RightLeg = 6, LeftLeg = -4, LeftKnee = 12,
		}, 2, Enum.EasingStyle.Back))
		MOTIONS.EmoteWhyCry = m

		local PINK, BLUE = Color3.fromRGB(255, 150, 205), Color3.fromRGB(140, 200, 255)
		local TEAR, CLOUD = Color3.fromRGB(120, 205, 255), Color3.fromRGB(118, 124, 140)
		-- a word (or a heart) floating up off somewhere
		local function floater(bag, pos, text, color, size, life, rise)
			local a = part(bag, Vector3.one * 0.1, CFrame.new(pos), Color3.new(), nil, nil)
			a.Transparency = 1
			local bb = Instance.new("BillboardGui")
			bb.Size = UDim2.fromOffset(size * 7, size * 1.6)
			bb.MaxDistance = 90
			bb.LightInfluence = 0
			bb.Parent = a
			local t = Instance.new("TextLabel")
			t.Size = UDim2.fromScale(1, 1)
			t.BackgroundTransparency = 1
			t.Font = Enum.Font.GothamBlack
			t.TextSize = size
			t.TextColor3 = color
			t.TextStrokeTransparency = 0
			t.Text = text
			t.Parent = bb
			tween(a, life, { CFrame = CFrame.new(pos + UP * rise + Vector3.new(rand(-1, 1), 0, rand(-1, 1))) }, Enum.EasingStyle.Sine)
			tween(t, 0.3, { TextTransparency = 1, TextStrokeTransparency = 1 }, nil, nil, life - 0.3)
			cleanup(a, life + 0.05)
		end
		-- the big heart over his head (blue to pink, like the song's cover),
		-- and the two halves it cracks into
		local function heartLabel(parent, name)
			local h = Instance.new("TextLabel")
			h.Name = name
			h.AnchorPoint = Vector2.new(0.5, 0.5)
			h.Position = UDim2.fromScale(0.5, 0.5)
			h.Size = UDim2.fromScale(1, 1)
			h.BackgroundTransparency = 1
			h.Font = Enum.Font.GothamBlack
			h.TextScaled = true
			h.Text = "♥"
			h.TextColor3 = Color3.new(1, 1, 1)
			h.TextStrokeColor3 = Color3.fromRGB(96, 70, 120)
			h.TextStrokeTransparency = 0.3
			h.Parent = parent
			local g = Instance.new("UIGradient")
			g.Color = ColorSequence.new(BLUE, PINK)
			g.Rotation = 35
			g.Parent = h
			return h
		end

		EM.props.WhyCry = function(char, token, root)
			local head = char:FindFirstChild("Head")
			if not head then
				return
			end
			local bag = EM.bag()
			-- the song, from where the emote's timed to (round 76: the Emotes
			-- folder in Workspace, else Song, else the licensed FallbackSong)
			local song
			local songId, songVolume, songStart = VFX.EmoteSong(entry)
			if songId then
				song = Instance.new("Sound")
				song.Name = "EmoteSong"
				song.SoundId = songId
				song.Volume = songVolume
				song.RollOffMode = Enum.RollOffMode.InverseTapered
				song.RollOffMinDistance = 12
				song.RollOffMaxDistance = 90
				song.TimePosition = songStart
				song.Parent = root
				pcall(function()
					song:Play()
				end)
			end
			local anchor = part(bag, Vector3.one * 0.1, head.CFrame, Color3.new(), nil, nil)
			anchor.Transparency = 1
			local bb = Instance.new("BillboardGui")
			bb.Name = "WhyCryHeart"
			bb.Size = UDim2.fromOffset(190, 190)
			bb.MaxDistance = 120
			bb.LightInfluence = 0
			bb.Parent = anchor
			local box = Instance.new("Frame")
			box.AnchorPoint = Vector2.new(0.5, 0.5)
			box.Position = UDim2.fromScale(0.5, 0.5)
			box.Size = UDim2.fromScale(0.2, 0.2)
			box.BackgroundTransparency = 1
			box.Parent = bb
			local heart = heartLabel(box, "Heart")
			local halves = {}
			for k, side in { -1, 1 } do
				local clip = Instance.new("Frame")
				clip.Name = "Half"
				clip.Position = UDim2.fromScale(side < 0 and 0 or 0.5, 0)
				clip.Size = UDim2.fromScale(0.5, 1)
				clip.BackgroundTransparency = 1
				clip.ClipsDescendants = true
				clip.Visible = false
				clip.Parent = box
				local h = heartLabel(clip, "HalfHeart")
				h.AnchorPoint = Vector2.zero
				h.Size = UDim2.fromScale(2, 1)
				h.Position = UDim2.fromScale(side < 0 and 0 or -1, 0)
				halves[k] = clip
			end
			local crack = Instance.new("TextLabel")
			crack.Name = "Crack"
			crack.AnchorPoint = Vector2.new(0.5, 0.5)
			crack.Position = UDim2.fromScale(0.5, 0.5)
			crack.Size = UDim2.fromScale(0.5, 1)
			crack.BackgroundTransparency = 1
			crack.Font = Enum.Font.GothamBlack
			crack.TextScaled = true
			crack.Text = "ϟ"
			crack.TextColor3 = Color3.fromRGB(60, 40, 70)
			crack.Visible = false
			crack.Parent = box
			-- tears: a stream from each eye, arcing out (anime waterfall tears)
			local streams = {}
			for _, side in { -1, 1 } do
				local drops = {}
				for k = 1, 12 do
					local p = part(bag, Vector3.one * 0.25, head.CFrame, TEAR, Enum.Material.Neon, Enum.PartType.Ball)
					p.Name = "Tear"
					p.Transparency = 1
					drops[k] = p
				end
				streams[side] = drops
			end
			-- his own rain cloud, and its rain
			local puffs = {}
			for k, o in { { 0, 0, 0, 1.9 }, { 1, 0.2, 0.3, 1.5 }, { -1, 0.1, -0.2, 1.6 }, { 0.4, 0.5, -0.5, 1.4 }, { -0.5, 0.45, 0.5, 1.3 } } do
				local p = part(bag, Vector3.one * 0.1, head.CFrame, CLOUD, nil, Enum.PartType.Ball)
				p.Name = "RainCloud"
				p.Transparency = 1
				puffs[k] = { p, Vector3.new(o[1], o[2], o[3]), o[4] }
			end
			local rain = {}
			for k = 1, 12 do
				local p = part(bag, Vector3.new(0.07, 0.6, 0.07), head.CFrame, Color3.fromRGB(170, 205, 255), Enum.Material.Neon)
				p.Name = "Rain"
				p.Transparency = 1
				rain[k] = { p, Vector3.new(rand(-1.2, 1.2), 0, rand(-1.2, 1.2)) }
			end
			-- the puddle growing under him
			local puddle = part(bag, Vector3.new(0.06, 0.1, 0.1), CFrame.new(root.Position), TEAR, Enum.Material.Glass, Enum.PartType.Cylinder)
			puddle.Name = "Puddle"
			puddle.Transparency = 1
			puddle.Reflectance = 0.2
			local hanky = part(bag, Vector3.new(1.2, 0.05, 1.2), head.CFrame, Color3.fromRGB(255, 196, 222))
			hanky.Name = "Hanky"
			hanky.Transparency = 1

			local ground = groundPoint(root.Position)
			local heartScale, heartOn = 0.16, true
			local tearAmp, cloudOn, puddleR = 0, false, 0
			local function pop(scale)
				heartScale = scale
				box.Size = UDim2.fromScale(scale * 1.25, scale * 1.25)
				tween(box, 0.18, { Size = UDim2.fromScale(scale, scale) }, Enum.EasingStyle.Back)
			end
			-- what happens on each beat
			local function onBeat(b)
				if b == 0 then
					floater(bag, head.Position + UP * 1.2, "♪", PINK, 26, 1.4, 2.5)
				elseif b == 2 then
					floater(bag, head.Position + UP * 1.4, "*inhales*", Color3.fromRGB(220, 220, 230), 22, 1.6, 1.5)
					tween(box, B * 2, { Size = UDim2.fromScale(0.3, 0.3) }, Enum.EasingStyle.Sine)
				elseif b == 4 then
					pop(0.62)
					VFX.PlaySound("Boing", head.Position, 0.6)
					VFX.SpeechBubble(char, "我真的特别爱你!!", 2.2)
				elseif b == 8 then
					VFX.SpeechBubble(char, "I REALLY LOVE YOU!!", 2)
				elseif b == 12 then
					-- it cracks... and comes apart
					crack.Visible = true
					VFX.PlaySound("Shatter", head.Position, 0.5)
					VFX.SpeechBubble(char, "!?", 0.8)
					task.delay(B * 0.5, function()
						if not bag.Parent then
							return
						end
						heartOn = false
						crack.Visible = false
						heart.Visible = false
						for k, clip in halves do
							clip.Visible = true
							local side = k == 1 and -1 or 1
							tween(clip, B * 2, { Position = UDim2.fromScale((side < 0 and 0 or 0.5) + side * 0.5, 0.9) }, Enum.EasingStyle.Quad, Enum.EasingDirection.In)
							for _, h in clip:GetChildren() do
								if h:IsA("TextLabel") then
									tween(h, B * 2, { TextTransparency = 1, TextStrokeTransparency = 1 }, nil, nil)
								end
							end
						end
					end)
				elseif b == 13 then
					tearAmp = 1
				elseif b == 14 then
					cloudOn = true
					VFX.PlaySound("HairPoof", head.Position + UP * 3, 0.5)
				elseif b == 15 or b == 17 or b == 19 then
					floater(bag, head.Position + UP * 1.2, "*sob*", Color3.fromRGB(170, 200, 240), 22, 1.3, 1.6)
				elseif b == 20 then
					tearAmp = 1.6
				end
				-- pounding the street: splashes in the puddle
				if (b >= 20 and b <= 22) or (b >= 24 and b <= 26) then
					local at = groundPoint(root.Position + root.CFrame.LookVector * 1.6)
					sparks(at + UP * 0.2, 0.5, TEAR, Color3.new(1, 1, 1), 6)
					VFX.PlaySound("MemoryThud", at, 0.45)
				elseif b == 23 or b == 27 then
					floater(bag, head.Position + UP * 1.6, "WAAAAAAHHH", BLUE, 40, 1.8, 3.5)
				elseif b >= 28 and b <= 31 then
					floater(bag, head.Position + UP * 0.8 + Vector3.new(rand(-1.5, 1.5), 0, rand(-1.5, 1.5)), b % 2 == 0 and "waah" or "WAAH", BLUE, 24, 1.1, 2)
				end
				if b == 32 then
					-- all better (as if)
					tearAmp, cloudOn = 0, false
					hanky.Transparency = 0
					VFX.PlaySound("HairPoof", head.Position + UP * 3, 0.5)
				elseif b == 34 then
					hanky.Transparency = 1
					floater(bag, head.Position + UP * 0.6, "✨", Color3.new(1, 1, 0.8), 30, 1, 1.5)
					-- the heart's back - good as new
					for _, clip in halves do
						clip.Visible = false
					end
					heart.Visible, heartOn = true, true
					pop(0.5)
					VFX.SpeechBubble(char, "为什么你会流泪? 😏", 1.2)
				elseif b == 35 then
					VFX.SpeechBubble(char, "...why are YOU crying?", 1.5)
					task.delay(B * 0.5, function()
						if not bag.Parent then
							return
						end
						heartOn = false
						heart.Visible = false
						VFX.PlaySound("Confetti", head.Position, 0.7)
						for k = 1, 10 do
							floater(bag, head.Position + UP * 2.4 + Vector3.new(rand(-2, 2), rand(-0.5, 1), rand(-2, 2)), "♥", k % 2 == 0 and PINK or BLUE, 30, 1.2, 2.5)
						end
					end)
				end
			end

			local t0 = os.clock()
			local last, lastT = -1, 0
			while EM.alive(char, token, root) do
				local t = os.clock() - t0
				local dt = math.min(t - lastT, 0.1)
				lastT = t
				if t > BEATS * B + 0.3 then
					break
				end
				local b = math.floor(t / B)
				if b > last then
					for nb = last + 1, math.min(b, BEATS - 1) do
						onBeat(nb)
					end
					last = b
				end
				local frac = t / B - b
				local hc = head.CFrame
				-- the heart: over his head, throbbing on every beat of the hook
				anchor.CFrame = CFrame.new(hc.Position + UP * 2.6)
				if heartOn and b >= 4 and b < 12 and frac < 0.5 then
					local k = 1 + 0.16 * math.exp(-frac * 7)
					box.Size = UDim2.fromScale(heartScale * k, heartScale * k)
				end
				-- the tears
				for side, drops in streams do
					local eye = (hc * CFrame.new(0.2 * side, 0.15, -0.5)).Position
					local out, fwd = hc.RightVector * side, hc.LookVector
					for k, p in drops do
						if tearAmp > 0 then
							local u = ((k - 1) / #drops + t * 1.7) % 1
							p.CFrame = CFrame.new(eye + (out * 2.4 * u + fwd * 0.7 * u + UP * (1.3 * u - 3.8 * u * u)) * tearAmp)
							p.Size = Vector3.one * (0.3 - 0.12 * u)
							p.Transparency = 0.1
						else
							p.Transparency = 1
						end
					end
				end
				-- the cloud and its rain
				local top = hc.Position + UP * (3.4 + math.sin(t * 3) * 0.15)
				for _, pf in puffs do
					if cloudOn then
						pf[1].Size = Vector3.one * pf[3]
						pf[1].CFrame = CFrame.new(top + pf[2])
						pf[1].Transparency = 0.05
					elseif pf[1].Transparency < 1 then
						-- poof: puffs up and fades
						pf[1].Size += Vector3.one * 3 * dt
						pf[1].Transparency = math.min(1, pf[1].Transparency + 4 * dt)
					end
				end
				for k, rd in rain do
					if cloudOn then
						local u = ((k - 1) / #rain + t * 2.2) % 1
						rd[1].CFrame = CFrame.new(top + rd[2] - UP * (0.5 + u * 2.6))
						rd[1].Transparency = 0.3
					else
						rd[1].Transparency = 1
					end
				end
				-- the puddle: grows while he cries, gone the moment he stops
				if b >= 13 and b < 32 then
					puddleR = math.min(5.5, puddleR + (5.5 / (19 * B)) * dt)
				elseif b >= 32 then
					puddleR = math.max(0, puddleR - 6 * dt)
				end
				if puddleR > 0.05 then
					ground = groundPoint(root.Position)
					puddle.Size = Vector3.new(0.06, puddleR * 2, puddleR * 2)
					puddle.CFrame = CFrame.new(ground + UP * 0.04) * CFrame.Angles(0, 0, math.pi / 2)
					puddle.Transparency = 0.35
				else
					puddle.Transparency = 1
				end
				-- the hanky, dabbing
				if hanky.Transparency < 1 then
					local hand = handPos(char, true)
					hanky.CFrame = CFrame.lookAt(hand, hc.Position) * CFrame.Angles(math.pi / 2, 0, math.sin(t * 20) * 0.4)
				end
				task.wait()
			end
			if song then
				tween(song, 0.35, { Volume = 0 })
				task.delay(0.36, function()
					pcall(function()
						song:Stop()
					end)
					song:Destroy()
				end)
			end
			bag:Destroy()
		end
	end)()

	---------------------------------------------------------------------------
	-- (round 85) DANCE: 16 beats of house on the drop of Tony Romera - "I
	-- Can't" (126 bpm): the step-clap (1-4), raise the roof (5-8), the pump
	-- (9-12), a whip-around spin (13), coiled up low (14) and a ta-da (15-16).
	-- Notes float off him every other beat and a sparkle pops on the ta-da.
	-- The song is the wrapper's (EM.song). (Its own function: local limit.)
	---------------------------------------------------------------------------
	;(function()
		local entry = EM.entry("Dance") or { Id = "Dance", Bpm = 126 }
		local BACK, SINE, LIN = Enum.EasingStyle.Back, Enum.EasingStyle.Sine, Enum.EasingStyle.Linear
		local steps = {}
		local function add(pose, beats, style, t)
			table.insert(steps, { pose = pose, beats = beats, style = style, t = t })
		end
		local B = 60 / (entry.Bpm or 126)
		local SWAY = B * 0.5 * 0.85 -- (an "and": eased the whole half beat)
		-- (R6: Crouch with the legs left out swings them forward - its knees;
		-- each Hips y lifts a pose whose leaning or spread legs would push a
		-- foot into the street - measured offline, round 85)
		-- 1-4: the step-clap - a step out to the side on 1 and 3, a clap in
		-- front with a dip on 2 and 4, bouncing up on every "and"
		for k = 1, 2 do
			local s = k == 1 and 1 or -1 -- (right, then left)
			add({
				Hips = { 0, 0, 0, 0.3 * s, 0.07, 0 }, Waist = { -4, -8 * s, -5 * s },
				RightLeg = s > 0 and { 0, 0, 2 } or { 4, 0, 22 }, LeftLeg = s > 0 and { 4, 0, 22 } or { 0, 0, 2 },
				RightArm = { -28, 0, 16 }, LeftArm = { -28, 0, 16 }, Neck = { -2, -12 * s, 0 },
			}, 0.5)
			add({ Hips = { 0, 0, 0, 0.15 * s, 0, 0 }, Waist = { 2, -3 * s, -2 * s }, RightArm = { 28, 0, 10 }, LeftArm = { 28, 0, 10 }, Neck = { 2, -6 * s, 0 } }, 0.5, SINE, SWAY)
			add({
				Hips = { 0, 0, 0, 0.08 * s, 0, 0 }, Crouch = 0.3, Waist = { -14, 0, 0 },
				RightArm = { 80, 38, 0 }, LeftArm = { 80, -38, 0 }, Neck = { -8, 0, 0 },
			}, 0.5)
			add({ Waist = { 0, 4 * s, 0 }, RightArm = { 30, 0, 12 }, LeftArm = { 30, 0, 12 }, Neck = { 4, 6 * s, 0 } }, 0.5, SINE, SWAY)
		end
		-- 5-8: raise the roof - both hands pushed up on the beat, a bounce on
		-- the "and", the hips swaying side to side
		for k = 1, 4 do
			local s = k % 2 == 1 and 1 or -1
			add({
				Hips = { 0, 8 * s, 0, 0.3 * s, 0.12, 0 }, Waist = { 6, 0, 6 * s }, RightArm = { 166, 0, -14 }, LeftArm = { 166, 0, -14 },
				RightLeg = { 0, 0, 6 }, LeftLeg = { 0, 0, 6 }, Neck = { 18, 0, -8 * s },
			}, 0.5)
			add({
				Hips = { 0, 4 * s, 0, 0.18 * s, 0.05, 0 }, Crouch = 0.28, Waist = { -10, 0, 3 * s },
				RightArm = { 140, 0, -18 }, LeftArm = { 140, 0, -18 }, Neck = { 0, 0, -3 * s },
			}, 0.5, SINE, SWAY)
		end
		-- 9-12: the pump - one fist punched at the sky on every beat, the
		-- other leg kicked out to the side, leaning into it; back down on the "and"
		for k = 1, 4 do
			local s = k % 2 == 1 and 1 or -1 -- (the right fist first)
			local up, down = { 176, 0, 6 }, { 14, 0, 26 }
			add({
				Hips = { 0, 0, 0, 0.3 * s, 0.19, 0 }, Waist = { 4, 12 * s, 10 * s },
				RightArm = s > 0 and up or down, LeftArm = s > 0 and down or up,
				RightLeg = s > 0 and { 0, 0, 4 } or { 6, 0, 30 }, LeftLeg = s > 0 and { 6, 0, 30 } or { 0, 0, 4 },
				Neck = { 20, -14 * s, 0 },
			}, 0.5)
			add({
				Hips = { 0, 0, 0, 0.12 * s, 0.03, 0 }, Crouch = 0.26, Waist = { -10, 4 * s, 2 * s },
				RightArm = s > 0 and { 120, 0, 14 } or { 30, 0, 18 }, LeftArm = s > 0 and { 30, 0, 18 } or { 120, 0, 14 },
				Neck = { 2, -6 * s, 0 },
			}, 0.5, SINE, SWAY)
		end
		-- 13: whipped round on the spot, a quarter turn every quarter beat
		-- (arms flung out; Linear, each turn the whole step)
		for q = 1, 4 do
			add({
				Waist = { 0, (q * 90) % 360, 0 }, RightArm = { 20, 0, 72 }, LeftArm = { 20, 0, 72 },
				RightLeg = { 0, 0, 4 }, LeftLeg = { 0, 0, 4 }, Neck = { 4, 0, 0 },
			}, 0.25, LIN, B * 0.25)
		end
		-- 14: coiled up - low, hands together, head down...
		add({ Hips = { 0, 0, 0, 0, 0.09, 0 }, Crouch = 0.55, Waist = { -24, 0, 0 }, RightArm = { 55, 32, 0 }, LeftArm = { 55, -32, 0 }, Neck = { -16, 0, 0 } }, 1)
		-- 15-16: ...TA-DA - sprung up into a wide V, chest out, a foot pointed
		add({
			Hips = { 0, -12, 0, -0.15, 0.09, 0 }, Waist = { 12, 0, -6 }, RightArm = { 150, 0, -40 }, LeftArm = { 150, 0, -40 },
			RightLeg = { 0, 0, 3 }, LeftLeg = { 6, 0, 26 }, Neck = { 18, 0, 8 },
		}, 2, BACK)
		MOTIONS.EmoteDance = EM.beatMotion(entry, steps, { recover = 0.45 })

		-- (round 85 review) the beat shows from across the street too: a faint
		-- ring at his feet on every bar; the ta-da gets a bigger ring and a
		-- little puff of confetti with its sparkle
		local GOLD = Color3.fromRGB(255, 220, 90)
		local COLORS = {
			Color3.fromRGB(255, 64, 160), Color3.fromRGB(64, 200, 255), Color3.fromRGB(255, 220, 60),
			Color3.fromRGB(120, 255, 110), Color3.fromRGB(190, 110, 255), Color3.fromRGB(255, 130, 50),
		}
		local function confettiPuff(at, n)
			for _ = 1, n do
				local bit = newPart(Vector3.new(0.24, 0.04, 0.24), CFrame.new(at) * CFrame.Angles(rand(0, 6), rand(0, 6), rand(0, 6)), COLORS[rng:NextInteger(1, #COLORS)], Enum.Material.SmoothPlastic)
				local out = Vector3.new(rand(-1, 1), 0, rand(-1, 1)) * rand(1.5, 3.5)
				tween(bit, 0.3, { CFrame = bit.CFrame + out + UP * rand(2.5, 4.5) }, Enum.EasingStyle.Quad, Enum.EasingDirection.Out)
				task.delay(0.3, function()
					tween(bit, 1, { CFrame = bit.CFrame * CFrame.Angles(rand(-3, 3), rand(-3, 3), rand(-3, 3)) - UP * 4.5, Transparency = 1 }, Enum.EasingStyle.Sine)
				end)
				cleanup(bit, 1.4)
			end
		end
		EM.props.Dance = function(char, token, root)
			EM.beatLoop(char, token, root, entry, 16, function(b)
				if b % 4 == 0 and b < 14 then -- (the bars: 1, 5, 9 and the spin)
					shockDisc(groundPoint(root.Position) + UP * 0.2, UP, 2, 6, 0.3, GOLD)
				end
				if b % 2 == 0 and b < 14 then
					EM.label(root, b % 4 == 0 and "♪" or "♫", GOLD, 30, B * 3, 2)
				elseif b == 14 then
					sparks(root.Position + UP * 2.5, 1, Color3.fromRGB(255, 236, 140), Color3.fromRGB(120, 220, 255), 18)
					shockDisc(groundPoint(root.Position) + UP * 0.2, UP, 2, 9, 0.45, Color3.fromRGB(255, 245, 210))
					confettiPuff(root.Position + UP * 2.6, 16)
				end
			end)
		end
	end)()

	---------------------------------------------------------------------------
	-- (round 85) THE GRIDDY to Slippy - "Flow" (156 bpm, a 78 half-time
	-- swagger), from its drop: a heel tap on every beat - the other foot
	-- kicked up behind, a little hop, the arms swinging like he's running -
	-- 8 of them square on (1-8), 4 turned out to one side then the other
	-- (9-12), then the goggles on the hook (13-16). Notes every other beat.
	---------------------------------------------------------------------------
	;(function()
		local entry = EM.entry("Griddy") or { Id = "Griddy", Bpm = 156 }
		local BACK, SINE = Enum.EasingStyle.Back, Enum.EasingStyle.Sine
		local B = 60 / (entry.Bpm or 156)
		local steps = {}
		local function add(pose, beats, style, t)
			table.insert(steps, { pose = pose, beats = beats, style = style, t = t })
		end
		-- one griddy step on side s (+1: the right heel taps out in front, the
		-- left foot's kicked up behind, the left arm swung up across), turned
		-- by yaw: the tap with a hop on the beat, settling on the "and"
		local function griddy(s, yaw)
			add({
				Hips = { 0, yaw, 0, 0.06 * s, 0.2, 0 }, Waist = { -14, 10 * s, 0 },
				RightLeg = s > 0 and { 26, 0, 4 } or { -50, 0, 6 }, LeftLeg = s > 0 and { -50, 0, 6 } or { 26, 0, 4 },
				RightArm = s > 0 and { -40, 0, 10 } or { 78, 18, 0 }, LeftArm = s > 0 and { 78, -18, 0 } or { -40, 0, 10 },
				Neck = { 8, -10 * s, 0 },
			}, 0.5)
			add({
				Hips = { 0, yaw, 0, 0.03 * s, 0.04, 0 }, Waist = { -10, 4 * s, 0 },
				RightLeg = s > 0 and { 22, 0, 6 } or { -26, 0, 6 }, LeftLeg = s > 0 and { -26, 0, 6 } or { 22, 0, 6 },
				RightArm = s > 0 and { -14, 0, 8 } or { 40, 10, 6 }, LeftArm = s > 0 and { 40, -10, 6 } or { -14, 0, 8 },
				Neck = { 4, -4 * s, 0 },
			}, 0.5, SINE, B * 0.5 * 0.85)
		end
		for k = 1, 8 do -- 1-8
			griddy(k % 2 == 1 and 1 or -1, 0)
		end
		for k = 1, 4 do -- 9-12: turned out to his left, then his right
			griddy(k % 2 == 1 and 1 or -1, k <= 2 and 35 or -35)
		end
		-- 13-16: the goggles - fingers round the eyes (R6: a raised arm's +
		-- roll brings the hand in), leaning back, a hip popped, a nod, the
		-- lean switched, chin up to finish (round 85 review: the chin a little
		-- higher, so it shows under the arms; the goggles themselves are a prop)
		local G = { 140, 0, 55 }
		add({ RightArm = G, LeftArm = G, Waist = { 10, 0, 6 }, Hips = { 0, 0, 0, 0.2, 0.11, 0 }, RightLeg = { 0, 0, 4 }, LeftLeg = { 16, 0, 16 }, Neck = { 10, 0, -6 } }, 1, BACK)
		add({ RightArm = G, LeftArm = G, Waist = { 4, 0, 6 }, Hips = { 0, 0, 0, 0.2, 0.09, 0 }, Crouch = 0.25, Neck = { -4, 0, -6 } }, 1)
		add({ RightArm = G, LeftArm = G, Waist = { 10, 0, -6 }, Hips = { 0, 0, 0, -0.2, 0.11, 0 }, RightLeg = { 16, 0, 16 }, LeftLeg = { 0, 0, 4 }, Neck = { 10, 0, 6 } }, 1)
		add({ RightArm = G, LeftArm = G, Waist = { 12, -10, -8 }, Hips = { 0, 0, 0, -0.2, 0.16, 0 }, RightLeg = { 16, 0, 16 }, LeftLeg = { 0, 0, 4 }, Neck = { 14, 12, 8 } }, 1, BACK)
		MOTIONS.EmoteGriddy = EM.beatMotion(entry, steps, { recover = 0.35 })

		-- (round 85 review) the props: notes every other beat and a faint ring
		-- at his feet on every bar; on the hook a pair of glowing goggle lenses
		-- (a cyan Neon rim round a dark glass, on each hand, facing where his
		-- head faces: on R6 the arms hide his face, the lenses say "goggles"
		-- from across the street); a glint off them on the chin-up
		local GOLD, CYAN = Color3.fromRGB(255, 220, 90), Color3.fromRGB(90, 230, 255)
		EM.props.Griddy = function(char, token, root)
			local bag, lenses = nil, nil
			EM.beatLoop(char, token, root, entry, 16, function(b)
				if b % 2 == 0 then
					EM.label(root, b % 4 == 0 and "♪" or "♫", GOLD, 30, B * 3, 2)
				end
				if b % 4 == 0 and b < 12 then
					shockDisc(groundPoint(root.Position) + UP * 0.2, UP, 2, 6, 0.3, GOLD)
				end
				if b == 12 then
					bag, lenses = EM.bag(), {}
					for _, right in { true, false } do
						local rim = part(bag, Vector3.new(0.06, 0.62, 0.62), root.CFrame, CYAN, Enum.Material.Neon, Enum.PartType.Cylinder)
						local glass = part(bag, Vector3.new(0.08, 0.44, 0.44), root.CFrame, Color3.fromRGB(26, 34, 52), Enum.Material.Glass, Enum.PartType.Cylinder)
						glass.Transparency = 0.15
						table.insert(lenses, { right = right, rim = rim, glass = glass })
					end
				elseif b == 15 and lenses then
					local head = char:FindFirstChild("Head")
					sparks((head and head.Position or root.Position + UP * 1.5) + UP * 0.3, 0.45, Color3.new(1, 1, 1), CYAN, 10)
				end
			end, function()
				if lenses then
					local head = char:FindFirstChild("Head")
					local look = (head or root).CFrame.LookVector
					for _, l in lenses do
						local at = handPos(char, l.right) + look * 0.06
						local cf = CFrame.lookAt(at, at + look) * CFrame.Angles(0, math.pi / 2, 0)
						l.rim.CFrame, l.glass.CFrame = cf, cf + look * 0.02
					end
				end
			end)
			if bag then
				bag:Destroy()
			end
		end
	end)()

	---------------------------------------------------------------------------
	-- (round 85) ROBO-CHOP: Iida, class rep, takes the floor to Pegboard
	-- Nerds & Tokyo Machine - "MOSHI" (128 bpm, from the drop). His glasses
	-- pushed up (glint), attention, THE CHOP (his hands chopping the air in
	-- turn, half a beat each), robot turns with his head a beat behind, a
	-- stiff-legged march - then at double time - with his calves popping
	-- exhaust on every step, a robot arm wave, a rev in a sprinter's set
	-- (ignition, jets getting longer on every beat) and a chop salute.
	-- (Its own function: local limit.)
	---------------------------------------------------------------------------
	;(function()
		local entry = EM.entry("RoboChop") or { Id = "RoboChop", Bpm = 128 }
		local B = 60 / (entry.Bpm or 128)
		local BACK = Enum.EasingStyle.Back
		local steps = {}
		local function add(pose, beats, style, t)
			table.insert(steps, { pose = pose, beats = beats, style = style, t = t })
		end
		local SIDE = { 0, 0, 3 } -- (an arm snapped to his side)
		-- 1-2: the glasses pushed up his nose with a flat hand... the head
		-- snaps up (the glint)
		add({ RightArm = { 150, 0, 60 }, LeftArm = SIDE, Waist = { 2, 0, 0 }, Neck = { -8, 0, 0 } }, 1, BACK)
		add({ RightArm = { 146, 0, 60 }, LeftArm = SIDE, Waist = { 4, 0, 0 }, Neck = { 8, 0, 0 } }, 1, nil, 0.05)
		-- 3-4: ATTENTION - arms at his sides, heels together, up on his
		-- toes, dead still
		add({ RightArm = SIDE, LeftArm = SIDE, RightLeg = { 0, 0, -1 }, LeftLeg = { 0, 0, -1 }, Hips = { 0, 0, 0, 0, 0.1, 0 }, Waist = { 3, 0, 0 }, Neck = { 2, 0, 0 } }, 2, nil, 0.05)
		-- 5-12: THE CHOP - one flat hand chopping down as the other comes
		-- up, a half beat each, stiff as a board; the head ticks side to
		-- side on the beat
		for k = 1, 16 do
			local s = k % 2 == 1 and 1 or -1
			local tick = (math.floor((k - 1) / 2) % 2 == 0) and 7 or -7
			add({
				RightArm = s > 0 and { 164, 10, 0 } or { 52, 12, 0 }, LeftArm = s > 0 and { 52, -12, 0 } or { 164, -10, 0 },
				Waist = { -3, 4 * s, 0 }, Neck = { -2, tick - 4 * s, 0 }, -- (the chest ticking toward the chopping hand)
			}, 0.5, nil, 0.05)
		end
		-- 13-16: robot turns - arms straight out in front, the body snapping
		-- a quarter turn on the beat and the head left behind, catching up on
		-- the "and"
		local ARMS = { 90, 0, 0 }
		for k, yaw in { -45, -90, -45, 0 } do
			local was = ({ 0, -45, -90, -45 })[k]
			add({ Hips = { 0, yaw, 0, 0, 0, 0 }, RightArm = ARMS, LeftArm = ARMS, Neck = { 0, was - yaw, 0 } }, 0.5, nil, 0.06)
			add({ Hips = { 0, yaw, 0, 0, 0, 0 }, RightArm = ARMS, LeftArm = ARMS, Neck = { 0, 0, 0 } }, 0.5, nil, 0.05)
		end
		-- 17-20: the march - a stiff leg kicked up on the beat (the calf
		-- pops), stamped down on the "and", the arms swinging stiff
		for k = 1, 4 do
			local s = k % 2 == 1 and 1 or -1 -- (the right leg first)
			add({
				RightLeg = s > 0 and { 50, 0, 2 } or { 0, 0, 2 }, LeftLeg = s > 0 and { 0, 0, 2 } or { 50, 0, 2 },
				RightArm = s > 0 and { -35, 0, 6 } or { 62, 0, 6 }, LeftArm = s > 0 and { 62, 0, 6 } or { -35, 0, 6 },
				Waist = { 2, 0, 0 }, Neck = { 0, 0, 0 },
			}, 0.5, nil, 0.06)
			add({ RightLeg = { 0, 0, 2 }, LeftLeg = { 0, 0, 2 }, RightArm = SIDE, LeftArm = SIDE, Waist = { 0, 0, 0 } }, 0.5, nil, 0.06)
		end
		-- 21-24: ...at double time ("NO RUNNING IN THE HALLS!"), a leg on
		-- every half beat
		for k = 1, 8 do
			local s = k % 2 == 1 and 1 or -1
			add({
				RightLeg = s > 0 and { 44, 0, 2 } or { -8, 0, 2 }, LeftLeg = s > 0 and { -8, 0, 2 } or { 44, 0, 2 },
				RightArm = s > 0 and { -40, 0, 6 } or { 70, 0, 6 }, LeftArm = s > 0 and { 70, 0, 6 } or { -40, 0, 6 },
				Waist = { -6, 0, 0 }, Neck = { 4, 0, 0 },
			}, 0.5, nil, 0.05)
		end
		-- 25-28: the robot arm wave - arms out, a ripple passing through
		-- him a quarter beat a joint: right arm, shoulders, head, shoulders,
		-- left arm... and back. (round 85 review) Bigger, so it reads from
		-- a distance: the arms see-saw (one up high as the other dips) and
		-- the shoulders roll 9 degrees - lifted a little so the low foot
		-- stays on the street (an R6 roll tips the hips with it).
		local T = { 0, 0, 90 }
		local ripple = {
			{ RightArm = { 0, 0, 145 }, LeftArm = { 0, 0, 62 } },
			{ Waist = { 0, 0, 9 }, Hips = { 0, 0, 0, 0, 0.16, 0 } },
			{ Neck = { 0, 0, 16 } },
			{ Waist = { 0, 0, -9 }, Hips = { 0, 0, 0, 0, 0.16, 0 } },
			{ LeftArm = { 0, 0, 145 }, RightArm = { 0, 0, 62 } },
			{ Waist = { 0, 0, -9 }, Hips = { 0, 0, 0, 0, 0.16, 0 } },
			{ Neck = { 0, 0, -16 } },
			{ Waist = { 0, 0, 9 }, Hips = { 0, 0, 0, 0, 0.16, 0 } },
		}
		for k = 1, 16 do
			local pose = { RightArm = T, LeftArm = T, Waist = { 0, 0, 0 }, Neck = { 0, 0, 0 }, Hips = { 0, 0, 0, 0, 0.02, 0 } }
			for joint, v in ripple[(k - 1) % 8 + 1] do
				pose[joint] = v
			end
			add(pose, 0.25, nil, 0.05)
		end
		-- 29-31: the rev - down in a sprinter's set, sinking deeper on
		-- every beat as the jets catch and grow
		for k = 1, 3 do
			add({
				Waist = { -28 - 5 * k, 0, 0 }, RightLeg = -32 - 4 * k, LeftLeg = 28 + 4 * k, RightArm = { 52, 0, 8 }, LeftArm = { -42, 0, 8 }, Hips = { 0, 0, 0, 0, 0.06, 0 },
				Neck = { 26 + 4 * k, 0, 0 },
			}, 1, k == 1 and BACK or nil, 0.08)
		end
		-- 32: the class rep's salute - a flat hand chopped up in front of
		-- him, the other tucked behind his back, chest out
		add({
			RightArm = { 118, 14, 0 }, LeftArm = { -32, 0, 14 }, Waist = { 8, 0, 0 }, Neck = { 6, 0, 0 },
			RightLeg = { 0, 0, -1 }, LeftLeg = { 0, 0, -1 }, Hips = { 0, 0, 0, 0, 0.05, 0 },
		}, 1, BACK)
		MOTIONS.EmoteRoboChop = EM.beatMotion(entry, steps, { recover = 0.4 }) -- 2+2+8+4+4+4+4+3+1 = 32 beats

		-- the props: Iida's rectangular glasses on his face (a glint off
		-- them on the push and the salute); a white crescent off every chop;
		-- a gear clunk on every robot turn; his calves (the Engine Kit, on
		-- anyone: it's a robot routine) puffing on the bars and popping on
