		-- pipes catch (ignition) and the jets grow every beat; the salute:
		-- a backfire from both calves, hot pipes, "ORDER!!"
		local IIDA = Color3.fromRGB(60, 120, 255)
		local CHOP = Color3.fromRGB(205, 236, 255)
		local FRAME, GLASS = Color3.fromRGB(34, 40, 72), Color3.fromRGB(200, 226, 255)
		-- the glasses' pieces on the head: { size, offset, colour, glass? }.
		-- (round 85 review) Thin dark frames round clear lenses, like Iida's
		-- own (Kit.iidaGlasses) a touch bigger; Iida keeps his real ones.
		local SPECS = {}
		do
			local w, h, t, y, z = 0.4, 0.22, 0.05, 0.1, -0.655
			for _, side in { 1, -1 } do
				local cx = side * 0.27
				table.insert(SPECS, { Vector3.new(w + t, t, t), CFrame.new(cx, y + h / 2, z), FRAME })
				table.insert(SPECS, { Vector3.new(w + t, t, t), CFrame.new(cx, y - h / 2, z), FRAME })
				table.insert(SPECS, { Vector3.new(t, h, t), CFrame.new(cx + w / 2, y, z), FRAME })
				table.insert(SPECS, { Vector3.new(t, h, t), CFrame.new(cx - w / 2, y, z), FRAME })
				table.insert(SPECS, { Vector3.new(w, h, 0.012), CFrame.new(cx, y, z - 0.005), GLASS, true })
				table.insert(SPECS, { Vector3.new(0.17, t, t), CFrame.new(side * 0.55, y + h / 2 - t / 2, z), FRAME }) -- (the hinge)
				table.insert(SPECS, { Vector3.new(t, t, 0.62), CFrame.new(side * 0.63, y + h / 2 - t / 2, -0.34), FRAME }) -- (the arm)
			end
			table.insert(SPECS, { Vector3.new(0.14, t, t), CFrame.new(0, y + h * 0.22, z), FRAME }) -- (the bridge)
		end
		local RIPPLE_AT = { "RightHand", "RightShoulder", "Head", "LeftShoulder", "LeftHand", "LeftShoulder", "Head", "RightShoulder" }
		-- a speech bubble that goes when the emote does (hidden: VFX.SpeechBubble
		-- fades and destroys its own a moment later)
		local function bubble(char, text, life)
			local head = char:FindFirstChild("Head")
			VFX.SpeechBubble(char, text, life)
			local found
			for _, g in folder:GetChildren() do
				if g.Name == "SpeechBubble" and g:IsA("BillboardGui") and g.Adornee == head then
					found = g
				end
			end
			return found
		end
		EM.props.RoboChop = function(char, token, root)
			local EK = VFX.EngineKit
			local bag = EM.bag()
			local head = char:FindFirstChild("Head")
			local torso = char:FindFirstChild("Torso") or char:FindFirstChild("UpperTorso")
			local glasses = {}
			-- (Iida has his own glasses on: the glint comes off those)
			local own = char:FindFirstChild("Glasses", true) ~= nil
			for _, sp in own and {} or SPECS do
				local p = part(bag, sp[1], head and head.CFrame or root.CFrame, sp[3], sp[4] and Enum.Material.Glass or Enum.Material.SmoothPlastic)
				if sp[4] then
					p.Transparency = 0.7
				end
				table.insert(glasses, { part = p, at = sp[2] })
			end
			local function glint()
				local at = head and (head.CFrame * CFrame.new(own and 0.215 or 0.27, 0.12, own and -0.7 or -0.72)).Position or root.Position + UP * 1.6
				sparks(at, 0.32, Color3.new(1, 1, 1), CHOP, 8)
				local star = part(bag, Vector3.one * 0.5, CFrame.new(at), Color3.new(1, 1, 1), Enum.Material.Neon, Enum.PartType.Ball)
				tween(star, 0.18, { Size = Vector3.one * 0.05, Transparency = 1 })
				VFX.PlaySound("Bell", root.Position, 0.7)
			end
			local stops, bubbles = {}, {}
			local function keep(stop)
				if stop then
					table.insert(stops, stop)
				end
				return stop
			end
			local lastHalf, lastQuarter = -1, -1
			local jets, hot, finale
			local done = EM.beatLoop(char, token, root, entry, 32, function(b)
				if b == 1 or b == 31 then
					glint()
				end
				if b == 4 then
					table.insert(bubbles, bubble(char, "EVERYONE, PLEASE SETTLE DOWN!!", 1.8))
				elseif b == 20 then
					table.insert(bubbles, bubble(char, "NO RUNNING IN THE HALLS!!", 1.6))
				end
				if b == 4 or b == 8 or b == 12 then -- (a robot venting on the bars)
					EK.backfire(char, nil, { scale = 0.45, sound = false })
				end
				if b >= 12 and b < 16 then -- (the robot turns: a gear clunk as he snaps round)
					VFX.PlaySound("EngineGear", root.Position, 0.6)
				end
				if b >= 16 and b < 24 then -- (the march: a pop's sound on every beat)
					VFX.PlaySound("EngineBackfire", root.Position, 0.45)
				end
				if b == 28 then -- (the rev: the pipes catch...)
					keep((EK.jets(char, "ignite", B * 1.05, { len = 2.4 })))
					VFX.PlaySound("EngineIgnite", root.Position, 0.9)
				elseif b == 29 then -- (...snap to cyan jets...)
					local stop
					stop, jets = EK.jets(char, "burst", nil, { len = 3.2 })
					keep(stop)
					EK.flash(char, nil, Color3.new(1, 1, 1), 1)
					VFX.PlaySound("EngineGear", root.Position, 0.8)
				elseif b == 30 then -- (...and roar out longer)
					if jets and jets.setLen then
						jets.setLen(5.5)
						jets.pulse(7.5, 0.15)
					end
					VFX.PlaySound("Engine", root.Position, 0.9)
				elseif b == 31 then -- (the salute)
					for _, stop in stops do
						stop(0.2)
					end
					table.clear(stops)
					EK.backfire(char, nil, { scale = 1.3 })
					-- (round 85 review) the hot pipes cool for their whole 1.4 s
					-- when it's danced to the end (stopped at once if it's broken
					-- off), and the word gets to rise and fade
					hot = EK.hotPipes(char, 1.4)
					finale = EM.label(root, "ORDER!!", IIDA, 36, 1.4, 2.2)
					finale.Parent = bag
				end
			end, function(t, b)
				if head then
					local hcf = head.CFrame
					for _, g in glasses do
						g.part.CFrame = hcf * g.at
					end
				end
				-- THE CHOP (beats 5-12): a crescent off the hand that's coming down,
				-- every half beat (the right hand on the even steps; from the
				-- second: on the first the left arm is still coming up from his
				-- side)
				local half = math.floor(t / (B / 2))
				if half > lastHalf then
					lastHalf = half
					local k = half - 7 -- (1 .. 16)
					if k >= 2 and k <= 16 and torso then
						local right = k % 2 == 0
						local shoulder = torso.CFrame * CFrame.new(right and 1.5 or -1.5, 0.5, 0)
						EK.kickSmear(shoulder, {
							plane = "vertical", arc = 100, from = -68, spin = -1, radius = 1.7, width = 0.7,
							color = CHOP, core = Color3.new(1, 1, 1), band = false, life = 0.24, draw = 0.05,
						})
						if k % 2 == 1 then
							VFX.PlaySound("Swing", root.Position, 0.35)
						end
					end
					-- the march (17-24): a pop out of the calf of the leg kicked up
					-- (on the beat; at double time on every half beat)
					if b >= 16 and b < 24 and (b >= 20 or half % 2 == 0) then
						local n = b >= 20 and half - 40 or (half - 32) / 2
						EK.backfire(char, n % 2 == 0 and "Right" or "Left", { scale = 0.8, sound = false })
					end
				end
				-- the robot wave (25-28): sparks where the ripple is, a quarter
				-- beat a joint
				local quarter = math.floor(t / (B / 4))
				if quarter > lastQuarter then
					lastQuarter = quarter
					local q = quarter - 96 -- (0 .. 15)
					if q >= 0 and q < 16 and torso then
						local where = RIPPLE_AT[q % 8 + 1]
						local at
						if where == "RightHand" or where == "LeftHand" then
							at = handPos(char, where == "RightHand")
						elseif where == "Head" then
							at = head and head.Position + UP * 0.6 or root.Position + UP * 2
						else
							at = (torso.CFrame * CFrame.new(where == "RightShoulder" and 1 or -1, 1, 0)).Position
						end
						sparks(at, 0.45, Color3.new(1, 1, 1), IIDA, 8)
					end
				end
			end)
			for _, stop in stops do
				stop(done and 0.3 or 0.1)
			end
			if hot and not done then
				hot(0.1)
			end
			if done and finale and finale.Parent then
				finale.Parent = folder -- (EM.label clears it away itself)
			end
			for _, g in bubbles do
				if g and g.Parent then
					g.Enabled = false
				end
			end
			bag:Destroy()
		end
	end)()

	---------------------------------------------------------------------------
	-- (round 85) AURA FARM: "AURA = INF" (146 bpm, half-time phonk). A long
	-- racing canoe slides in under him on a river; shades drop onto his
	-- face; stood on the raised bow he does the calm arm rolls and hand
	-- waves of the 2025 boat-race clips while the rowers behind him paddle
	-- on the beat - the air paddle, the wrist flick, leaning out over the
	-- bow - mist on the water, aura flames rising round him, and a +AURA
	-- freeze. (Its own function: local limit.)
	---------------------------------------------------------------------------
	;(function()
		local entry = EM.entry("AuraFarm") or { Id = "AuraFarm", Bpm = 146 }
		local B = 60 / (entry.Bpm or 146)
		local BACK, SINE, LIN = Enum.EasingStyle.Back, Enum.EasingStyle.Sine, Enum.EasingStyle.Linear
		local LIFT = 1.09 -- (he stands on the bow, a stud up; + a little: his feet spread a touch and he sways)
		local steps = {}
		local function add(pose, beats, style, t)
			local h = pose.Hips or { 0, 0, 0, 0, 0, 0 }
			pose.Hips = { h[1], h[2], h[3], h[4], (h[5] or 0) + LIFT, h[6] }
			table.insert(steps, { pose = pose, beats = beats, style = style, t = t })
		end
		local LOOSE, LEGS = { 8, 0, 9 }, { 0, 0, 7 }
		-- 1-4: the shades drop on; feet planted wide, a slow sway... and the
		-- cool look round (glint)
		for k = 1, 3 do
			local s = k % 2 == 1 and 1 or -1
			add({ RightArm = LOOSE, LeftArm = LOOSE, RightLeg = LEGS, LeftLeg = LEGS, Waist = { -2, 5 * s, -2 * s }, Hips = { 0, 0, 0, 0.1 * s, 0.03, 0 }, Neck = { -4, -3 * s, 0 } }, 1, SINE, B * 0.8)
		end
		add({ RightArm = LOOSE, LeftArm = LOOSE, RightLeg = LEGS, LeftLeg = LEGS, Waist = { 0, -4, 0 }, Hips = { 0, 0, 0, 0, 0.03, 0 }, Neck = { 10, 22, 0 } }, 1, SINE, B * 0.6)
		-- the roll: the straight arm drawing a smooth circle out in front of
		-- his shoulder (in, up, out, down: a hand ~1.3 studs round), two
		-- beats a turn. (round 85 review) Eight points a turn, each reached
		-- at an even speed (Linear, the whole step), so the hand never stops;
		-- pitch and yaw make the circle (roll does nothing with the arm out
		-- in front). The body sways on the same circle, sampled the same way.
		local function circle(a, s)
			-- s: 1 his right arm, -1 his left (the yaw mirrored: the same
			-- circle on the other side)
			return { 80 + 26 * math.sin(a), 30 * s * math.cos(a), 6 }
		end
		local function roll(arm, other, s, a)
			add({
				[arm] = circle(a, s), [other] = LOOSE, RightLeg = LEGS, LeftLeg = LEGS,
				Hips = { 0, 0, 0, 0, 0.04, 0 },
				Waist = { -2 + 2 * math.sin(a), s * (5 - 3 * math.cos(a)), 2 * s * math.sin(a) },
				Neck = { 3 + 4 * math.sin(a), s * (7 - 4 * math.cos(a)), 0 },
			}, 0.25, LIN, B * 0.25)
		end
		-- 5-8: the roll, his right arm (two turns); 9-12: his left
		for k = 1, 16 do
			roll("RightArm", "LeftArm", 1, k * math.pi / 4)
		end
		for k = 1, 16 do
			roll("LeftArm", "RightArm", -1, k * math.pi / 4)
		end
		-- 13-16: both arms rolling the same way round, half a turn apart
		-- (both in, then one up as the other goes down, both out...) -
		-- paddling the air, rowing the crowd, with a bounce on every beat
		for k = 1, 16 do
			local a = k * math.pi / 4
			add({
				RightArm = circle(a, 1), LeftArm = circle(a + math.pi, -1), RightLeg = LEGS, LeftLeg = LEGS,
				Waist = { -4, 4 * math.sin(a), 0 }, Hips = { 0, 0, 0, 0, 0.03 + 0.05 * math.abs(math.sin(a)), 0 }, Neck = { 2, -4 * math.sin(a), 0 },
			}, 0.25, LIN, B * 0.25)
		end
		-- 17-20: the air paddle - reach forward on one side, pull it back to
		-- the hip; then the other side
		for k = 1, 2 do
			local s = k == 1 and 1 or -1 -- (+1: paddling on his left)
			add({
				RightArm = { 84, 34 * s, 0 }, LeftArm = { 74, 34 * s, 0 }, RightLeg = LEGS, LeftLeg = LEGS,
				Waist = { -14, 22 * s, 0 }, Hips = { 0, 0, 0, 0, 0.05, 0 }, Neck = { 6, -10 * s, 0 },
			}, 1, BACK, 0.16)
			add({
				RightArm = { 4, 30 * s, 10 }, LeftArm = { -10, 30 * s, 10 }, RightLeg = LEGS, LeftLeg = LEGS,
				Waist = { -4, 30 * s, 0 }, Hips = { 0, 0, 0, 0, 0.03, 0 }, Neck = { 2, -18 * s, 0 },
			}, 1, SINE, B * 0.9)
		end
		-- 21-24: the point down the river, a flick of the wrist on every
		-- beat, the other hand on his hip
		for _ = 1, 4 do
			add({ RightArm = { 106, 0, -6 }, LeftArm = { -16, 0, 30 }, RightLeg = LEGS, LeftLeg = LEGS, Waist = { 2, -6, 0 }, Hips = { 0, 0, 0, -0.08, 0.04, 0 }, Neck = { 6, 0, 0 } }, 0.5, nil, 0.06)
			add({ RightArm = { 92, 0, 0 }, LeftArm = { -16, 0, 30 }, RightLeg = LEGS, LeftLeg = LEGS, Waist = { 0, -6, 0 }, Hips = { 0, 0, 0, -0.08, 0.03, 0 }, Neck = { 2, 0, 0 } }, 0.5, SINE, B * 0.4)
		end
		-- 25-28: leaning out over the bow, the hand smoothing the water
		-- side to side, maximum calm
		for k = 1, 2 do
			local s = k == 1 and 1 or -1
			add({
				RightArm = { 66, 26 * s, 0 }, LeftArm = { 6, 0, 14 }, RightLeg = LEGS, LeftLeg = LEGS,
				Waist = { -12, 6 * s, 0 }, Hips = { 0, 0, 0, 0, 0.06, 0 }, Neck = { 2, 6 * s, 0 },
			}, 2, SINE, B * 1.6)
		end
		-- 29-31: a hand to his chest, a nod... a fist pump
		add({ RightArm = { 56, 48, 0 }, LeftArm = LOOSE, RightLeg = LEGS, LeftLeg = LEGS, Waist = { 2, 0, 0 }, Hips = { 0, 0, 0, 0, 0.03, 0 }, Neck = { -8, 0, 0 } }, 1, SINE, B * 0.6)
		add({ RightArm = { 56, 48, 0 }, LeftArm = LOOSE, RightLeg = LEGS, LeftLeg = LEGS, Waist = { 0, 0, 0 }, Hips = { 0, 0, 0, 0, 0.03, 0 }, Neck = { 4, 0, 0 } }, 1, SINE, B * 0.6)
		add({ RightArm = { 160, 0, -8 }, LeftArm = LOOSE, RightLeg = LEGS, LeftLeg = LEGS, Waist = { 6, 0, 0 }, Hips = { 0, 0, 0, 0, 0.05, 0 }, Neck = { 12, 0, 0 } }, 1, BACK, 0.12)
		-- 32: the freeze - pointing down the river, chin up, looking round
		add({ RightArm = { 94, 0, 0 }, LeftArm = { -12, 0, 22 }, RightLeg = LEGS, LeftLeg = LEGS, Waist = { 4, -8, 0 }, Hips = { 0, 0, 0, 0, 0.04, 0 }, Neck = { 10, 26, 0 } }, 1, BACK, 0.12)
		MOTIONS.EmoteAuraFarm = EM.beatMotion(entry, steps, { recover = 0.5 }) -- 4+4+4+4+4+4+4+3+1 = 32 beats

		-- the props, in the boat's own space (x his right, y up, z back from
		-- his feet; the river runs past it from the bow to the stern):
		-- the canoe (a long dark-wood hull with red and yellow stripes, a
		-- raised bow deck he stands on, a gold beak, a stern tail) rocking
		-- gently on the water; 8 rowers (4 on a low-end machine) in single
		-- file, their paddles dipping together on every other beat (a splash
		-- down both sides); a river round it with foam streaks running past,
		-- a bow wave and a wake; mist; black shades dropped onto his face;
		-- aura flames from beat 17; on the freeze a burst, a ring on the
		-- water and "+∞ AURA". It rises out of the water as he steps up and
		-- sinks as he steps down.
		local WOOD, DARK = Color3.fromRGB(96, 60, 36), Color3.fromRGB(56, 34, 22)
		local RED, YELLOW, GOLD = Color3.fromRGB(196, 40, 36), Color3.fromRGB(240, 196, 50), Color3.fromRGB(255, 214, 90)
		local SHIRT, SKIN = Color3.fromRGB(235, 120, 40), Color3.fromRGB(110, 72, 48)
		local WATER, FOAM = Color3.fromRGB(34, 92, 112), Color3.fromRGB(236, 246, 250)
		local VIOLET, INDIGO = Color3.fromRGB(176, 96, 255), Color3.fromRGB(70, 40, 190)
		local deg = math.rad
		-- the hull: { class, size, where (boat space), colour, material }
		local HULL = {
			{ "Part", Vector3.new(2.4, 0.95, 22), CFrame.new(0, 0.37, 13.6), WOOD, Enum.Material.Wood },
			{ "Part", Vector3.new(1.9, 0.06, 21.6), CFrame.new(0, 0.86, 13.6), DARK },
			{ "Part", Vector3.new(0.26, 0.14, 22), CFrame.new(1.07, 0.9, 13.6), WOOD, Enum.Material.Wood },
			{ "Part", Vector3.new(0.26, 0.14, 22), CFrame.new(-1.07, 0.9, 13.6), WOOD, Enum.Material.Wood },
			{ "Part", Vector3.new(0.06, 0.16, 22), CFrame.new(1.21, 0.62, 13.6), RED },
			{ "Part", Vector3.new(0.06, 0.16, 22), CFrame.new(-1.21, 0.62, 13.6), RED },
			{ "Part", Vector3.new(0.06, 0.12, 22), CFrame.new(1.21, 0.4, 13.6), YELLOW },
			{ "Part", Vector3.new(0.06, 0.12, 22), CFrame.new(-1.21, 0.4, 13.6), YELLOW },
			{ "Part", Vector3.new(2.2, 1.15, 3.6), CFrame.new(0, 0.475, 0.8), WOOD, Enum.Material.Wood }, -- (the bow deck: his feet)
			{ "Part", Vector3.new(2.24, 0.14, 3.64), CFrame.new(0, 0.62, 0.8), RED },
			{ "WedgePart", Vector3.new(2.2, 1.15, 1.8), CFrame.new(0, 0.475, -1.9), WOOD, Enum.Material.Wood }, -- (the prow)
			{ "Part", Vector3.new(0.3, 0.3, 1.8), CFrame.new(0, 0.75, -2.75) * CFrame.Angles(deg(32), 0, 0), GOLD, Enum.Material.Metal }, -- (the beak)
			{ "WedgePart", Vector3.new(2.4, 0.95, 2.4), CFrame.new(0, 0.37, 25.8) * CFrame.Angles(0, math.pi, 0), WOOD, Enum.Material.Wood }, -- (the stern)
			{ "Part", Vector3.new(0.26, 2, 0.4), CFrame.new(0, 1.3, 26.4) * CFrame.Angles(deg(-24), 0, 0), GOLD, Enum.Material.Metal }, -- (its tail)
		}
		local function make(bag, class, size, color, material)
			local p = Instance.new(class)
			p.Name = "EmoteProp"
			p.Anchored, p.CanCollide, p.CanQuery, p.CanTouch, p.CastShadow = true, false, false, false, false
			p.TopSurface, p.BottomSurface = Enum.SurfaceType.Smooth, Enum.SurfaceType.Smooth
			p.Size, p.Color, p.Material = size, color, material or Enum.Material.SmoothPlastic
			p.Parent = bag
			return p
		end
		local function emitter(parent, texture, colors, size, transp, life, speed, rate, light)
			local pe = Instance.new("ParticleEmitter")
			pe.Texture = texture
			pe.Color = ColorSequence.new(colors[1], colors[2] or colors[1])
			pe.Size = size
			pe.Transparency = transp
			pe.Lifetime = life
			pe.Speed = speed
			pe.Rate = rate
			pe.LightEmission = light or 0
			pe.Parent = parent
			return pe
		end
		EM.props.AuraFarm = function(char, token, root)
			local bag = EM.bag()
			local low = VFX.EngineKit and VFX.EngineKit.lowEnd and VFX.EngineKit.lowEnd()
			local g = groundPoint(root.Position)
			local look = Vector3.new(root.CFrame.LookVector.X, 0, root.CFrame.LookVector.Z)
			look = look.Magnitude > 0.1 and look.Unit or Vector3.new(0, 0, -1)
			local base = CFrame.lookAt(g, g + look)
			local boat = {} -- { part, where } that ride (and rock) with the boat
			for _, h in HULL do
				local p = make(bag, h[1], h[2], h[4], h[5])
				table.insert(boat, { part = p, at = h[3] })
			end
			-- the rowers: a torso, a head, a paddle (shaft + blade) each
			local rowers = {}
			for i = 1, (low and 4 or 8) do
				local z = low and (4.5 + (i - 1) * 5.2) or (4 + (i - 1) * 2.6)
				local r = {
					z = z, side = i % 2 == 1 and -1 or 1,
					torso = make(bag, "Part", Vector3.new(1, 1.1, 0.7), SHIRT),
					head = make(bag, "Part", Vector3.one * 0.78, SKIN),
					shaft = make(bag, "Part", Vector3.new(0.12, 2.7, 0.12), Color3.fromRGB(150, 110, 70), Enum.Material.Wood),
					blade = make(bag, "Part", Vector3.new(0.08, 0.95, 0.5), RED),
				}
				r.head.Shape = Enum.PartType.Ball
				table.insert(rowers, r)
			end
			-- the river: 18 x 44 studs in 8 pieces. (round 85 review) A piece
			-- whose street isn't level with his (a curb, a slope, a drop) or
			-- that's behind a wall from him stays hidden, so the water doesn't
			-- float over the street or run through a building.
			local water = {}
			local here = groundRay(root.Position, 40)
			for ix = 0, 1 do
				for iz = 0, 3 do
					local at = base * CFrame.new((ix - 0.5) * 9, -0.03, -12 + 5.5 + iz * 11)
					local ok = true
					if here then
						local hit = groundRay(at.Position + UP * 1.5, 8)
						local dir = Vector3.new(at.Position.X - g.X, 0, at.Position.Z - g.Z)
						local wall = workspace:Raycast(g + UP * 1.5, dir, rayParams)
						ok = hit ~= nil and math.abs(hit.Position.Y - g.Y) < 0.6 and not wall
					end
					local p = make(bag, "Part", Vector3.new(9, 0.2, 11), WATER)
					p.CFrame = at
					p.Transparency = 1
					table.insert(water, { part = p, ok = ok, x = (ix - 0.5) * 9, z = -12 + 5.5 + iz * 11 })
				end
			end
			-- (is a spot of the river shown?)
			local function wet(x, z)
				for _, w in water do
					if math.abs(x - w.x) <= 4.5 and math.abs(z - w.z) <= 5.5 then
						return w.ok
					end
				end
				return false
			end
			local foam = {}
			for i = 1, (low and 8 or 16) do
				local side = i % 2 == 0 and 1 or -1
				local f = make(bag, "Part", Vector3.new(0.14, 0.05, rand(1.2, 3.2)), FOAM)
				f.Transparency = 0.35
				table.insert(foam, { part = f, x = side * rand(1.7, 8), z = rand(-12, 32) })
			end
			local wakes = {}
			for _, w in { { -2.9, 26, 4.5 }, { -2.9, -26, 4.5 }, { 26.8, 22, 5 }, { 26.8, -22, 5 } } do
				local len = w[3]
				local p = make(bag, "Part", Vector3.new(0.22, 0.05, len), FOAM)
				local yaw = deg(w[2])
				local at = CFrame.new(0, 0.1, w[1]) * CFrame.Angles(0, yaw, 0) * CFrame.new(0, 0, len / 2)
				p.Transparency = wet(at.X, at.Z) and 0.3 or 1
				table.insert(wakes, { part = p, at = at })
			end
			-- spray off the bow, a splash down both sides on the catch, mist
			local bow = make(bag, "Part", Vector3.new(1, 0.2, 0.6), FOAM)
			bow.Transparency = 1
			local spray = emitter(bow, "rbxasset://textures/particles/smoke_main.dds", { FOAM }, NumberSequence.new(0.4, 1.4), NumberSequence.new(0.35, 1), NumberRange.new(0.3, 0.6), NumberRange.new(4, 8), low and 10 or 22)
			spray.SpreadAngle = Vector2.new(70, 30)
			local splashes = {}
			for _, side in { -1, 1 } do
				local s = make(bag, "Part", Vector3.new(0.4, 0.2, low and 21 or 19), FOAM)
				s.Transparency = 1
				local pe = emitter(s, "rbxasset://textures/particles/smoke_main.dds", { FOAM }, NumberSequence.new(0.3, 0.9), NumberSequence.new(0.3, 1), NumberRange.new(0.25, 0.45), NumberRange.new(3, 6), 0)
				pe.SpreadAngle = Vector2.new(25, 25)
				pe.Acceleration = Vector3.new(0, -14, 0)
				table.insert(splashes, { part = s, side = side, pe = pe })
			end
			if not low then
				for _, w in water do
					if w.ok then -- (mist off the water that's shown: about 6 a second in all)
						local pe = emitter(w.part, "rbxasset://textures/particles/smoke_main.dds", { Color3.fromRGB(230, 240, 248) }, NumberSequence.new(4, 8), NumberSequence.new({
							NumberSequenceKeypoint.new(0, 1), NumberSequenceKeypoint.new(0.3, 0.86), NumberSequenceKeypoint.new(1, 1),
						}), NumberRange.new(3, 5), NumberRange.new(0.4, 1), 0.75)
						pe.Acceleration = Vector3.new(0, 0.3, 0)
					end
				end
			end
			-- his shades (dropped on during the first beat)
			local head = char:FindFirstChild("Head")
			local SHADES = {
				{ Vector3.new(0.5, 0.27, 0.05), CFrame.new(0.27, 0.1, -0.665) },
				{ Vector3.new(0.5, 0.27, 0.05), CFrame.new(-0.27, 0.1, -0.665) },
				{ Vector3.new(1.06, 0.07, 0.05), CFrame.new(0, 0.21, -0.665) },
			}
			local shades = {}
			for _, sp in SHADES do
				table.insert(shades, { part = make(bag, "Part", sp[1], Color3.fromRGB(14, 14, 18)), at = sp[2] })
			end
			-- the aura (from beat 17): violet flames licking up all round him,
			-- gold motes rising through them
			local aura = make(bag, "Part", Vector3.new(2.8, 4.6, 1.8), GOLD)
			aura.Transparency = 1
			local flames = emitter(aura, "rbxasset://textures/particles/fire_main.dds", { VIOLET, INDIGO }, NumberSequence.new({
				NumberSequenceKeypoint.new(0, 1.2), NumberSequenceKeypoint.new(0.35, 2.6), NumberSequenceKeypoint.new(1, 0.6),
			}), NumberSequence.new({
				NumberSequenceKeypoint.new(0, 1), NumberSequenceKeypoint.new(0.2, 0.45), NumberSequenceKeypoint.new(1, 1),
			}), NumberRange.new(0.7, 1.2), NumberRange.new(1.5, 3), 0, 1)
			flames.EmissionDirection = Enum.NormalId.Top
			flames.SpreadAngle = Vector2.new(10, 10)
			local motes = emitter(aura, "rbxasset://textures/particles/sparkles_main.dds", { GOLD, Color3.new(1, 1, 1) }, NumberSequence.new(0.45, 0),
				NumberSequence.new(0, 1), NumberRange.new(0.8, 1.4), NumberRange.new(2, 4), 0, 1)
			motes.EmissionDirection = Enum.NormalId.Top
			motes.SpreadAngle = Vector2.new(20, 20)
			local function glint()
				if head then
					sparks((head.CFrame * CFrame.new(-0.27, 0.15, -0.72)).Position, 0.35, Color3.new(1, 1, 1), GOLD, 8)
				end
			end
			local STROKE = 2 * B -- (the rowers: a stroke every other beat, the catch on the beat)
			local T = 32 * B -- (the routine's end: he steps down off the bow)
			-- (round 85 review) how far under its place the boat is at time t.
			-- It comes up with him (his lift eases in, a 0.29 s Sine Out: the
			-- boat starts deeper and rises a touch slower, so it can't come up
			-- through his feet); when he steps down (the recovery, a 0.55 s
			-- Sine Out) the deck goes down with his feet, then on under.
			local function sunk(t)
				if t < T then
					return -(LIFT + 0.6) * (1 - math.sin(math.clamp(t / 0.36, 0, 1) * math.pi / 2))
				end
				return -LIFT * math.sin(math.clamp((t - T) / 0.55, 0, 1) * math.pi / 2) - 0.8 * math.clamp((t - T - 0.55) / 0.25, 0, 1) ^ 2
			end
			-- (every moving part is put in place with one BulkMoveTo a frame)
			local moved, cfs = {}, {}
			local function put(p, cf)
				table.insert(moved, p)
				table.insert(cfs, cf)
			end
			local function place(t, rise)
				table.clear(moved)
				table.clear(cfs)
				local rock = CFrame.new(0, LIFT + rise, 0) * CFrame.Angles(deg(0.6) * math.sin(t * 1.3), 0, deg(1.6) * math.sin(t * math.pi / (2 * B))) * CFrame.new(0, -LIFT, 0)
				local hull = base * rock
				for _, b in boat do
					put(b.part, hull * b.at)
				end
				local p = (t % STROKE) / STROKE
				for _, r in rowers do
					-- pull (blade in the water) for the first half, then the
					-- recovery: up out of the water and forward again
					local swing, lift, lean
					if p < 0.5 then
						local k = p / 0.5
						swing, lift, lean = deg(36 - 66 * k), 0, deg(-14 + 22 * k)
					else
						local k = (p - 0.5) / 0.5
						swing, lift, lean = deg(-30 + 66 * k), 0.85 * math.sin(k * math.pi), deg(8 - 22 * k)
					end
					local seat = hull * CFrame.new(0, 0.9, r.z)
					put(r.torso, seat * CFrame.Angles(lean, 0, 0) * CFrame.new(0, 0.55, 0))
					put(r.head, seat * CFrame.Angles(lean, 0, 0) * CFrame.new(0, 1.5, 0))
					local grip = seat * CFrame.new(r.side * 0.75, 0.45 + lift, 0) * CFrame.Angles(swing, 0, r.side * deg(24 + lift * 12))
					put(r.shaft, grip * CFrame.new(0, -0.35, 0))
					put(r.blade, grip * CFrame.new(0, -2.0, 0))
				end
				for _, w in wakes do
					put(w.part, base * CFrame.new(0, math.max(rise, -LIFT) * 0.2, 0) * w.at)
				end
				put(bow, base * CFrame.new(0, 0.15, -2.9))
				for _, s in splashes do
					put(s.part, base * CFrame.new(s.side * 1.7, 0.15, low and 15 or 13.1))
				end
				for _, f in foam do
					local z = (f.z + t * 9 + 12) % 44 - 12
					local shown = wet(f.x, z)
					if shown ~= f.shown then
						f.shown = shown
						f.part.Transparency = shown and 0.35 or 1
					end
					put(f.part, base * CFrame.new(f.x, 0.09 + math.max(rise, -LIFT) * 0.1, z))
				end
				put(aura, root.CFrame * CFrame.new(0, -0.6 + LIFT, 0))
				local ok = pcall(function()
					workspace:BulkMoveTo(moved, cfs, Enum.BulkMoveMode.FireCFrameChanged)
				end)
				if not ok then
					for i, p in moved do
						p.CFrame = cfs[i]
					end
				end
			end
			local function river(k) -- (0 hidden .. 1 shown)
				for _, w in water do
					w.part.Transparency = w.ok and 1 - 0.88 * k or 1
				end
			end
			local function wear(t)
				if head then
					local drop = math.clamp(t / (B * 0.8), 0, 1) -- (the shades fall onto his face)
					local hcf = head.CFrame
					for _, s in shades do
						s.part.CFrame = hcf * s.at + UP * 3.2 * (1 - drop * drop)
					end
				end
			end
			local finale
			local done = EM.beatLoop(char, token, root, entry, 32, function(b)
				if b % 2 == 0 then -- (the catch: a splash down both sides)
					for _, s in splashes do
						s.pe:Emit(low and 6 or 14)
					end
				end
				if b == 3 then
					glint()
				elseif b == 16 then
					flames.Rate, motes.Rate = low and 10 or 20, low and 6 or 12
				elseif b == 24 then
					flames.Rate, motes.Rate = low and 14 or 30, low and 8 or 18
				elseif b == 31 then
					flames:Emit(low and 20 or 40)
					motes:Emit(low and 15 or 30)
					shockDisc(g + UP * 0.25, UP, 3, 18, 0.6, GOLD)
					glint()
					finale = EM.label(root, "+∞ AURA", GOLD, 38, 1.6, 2.4)
					finale.Parent = bag
					VFX.PlaySound("Bell", root.Position, 0.6)
				end
			end, function(t)
				place(t, sunk(t)) -- (up out of the water as he steps up)
				river(math.clamp(t / 0.3, 0, 1))
				wear(t)
			end)
			if done then
				-- he steps down: the deck goes down with his feet and on under
				-- the water, the river fades (to 0.8 s after the last beat);
				-- the word rises and fades on its own
				if finale and finale.Parent then
					finale.Parent = folder
				end
				local t1, from = os.clock(), T + 0.3
				flames.Rate, motes.Rate = 0, 0
				while os.clock() - t1 < 0.5 do
					local t = from + os.clock() - t1
					place(t, sunk(t))
					river(1 - (os.clock() - t1) / 0.5)
					wear(t)
					task.wait()
				end
			end
			bag:Destroy()
		end
	end)()

	---------------------------------------------------------------------------
	-- (round 85) FEVER TIME: Saturday-night disco to "I Like To Disco B"
	-- (120 bpm). A light-up floor under him and a mirror ball coming down,
	-- throwing specks of light; the strut, THE POINT (up to the sky, down
	-- across his body), hip rolls, a spin into the point, the hustle, the
	-- point at double time, the splits and the poster pose in a spotlight.
	-- (Its own function: local limit.)
	---------------------------------------------------------------------------
	;(function()
		local entry = EM.entry("FeverTime") or { Id = "FeverTime", Bpm = 120 }
		local B = 60 / (entry.Bpm or 120)
		local BACK, SINE, LIN = Enum.EasingStyle.Back, Enum.EasingStyle.Sine, Enum.EasingStyle.Linear
		local steps = {}
		local function add(pose, beats, style, t)
			table.insert(steps, { pose = pose, beats = beats, style = style, t = t })
		end
		local HIP = { -18, 0, 34 } -- (a hand on the hip: R6 arms are straight)
		-- 1-4: the strut - a hand on his hip, the hips popping side to side,
		-- a nod on every beat
		for k = 1, 4 do
			local s = k % 2 == 1 and 1 or -1
			add({
				RightArm = HIP, LeftArm = { 14, 0, 10 }, Hips = { 0, 0, 0, 0.16 * s, 0.08, 0 }, Waist = { 2, 4 * s, -5 * s },
				RightLeg = s > 0 and { 0, 0, 2 } or { 4, 0, 12 }, LeftLeg = s > 0 and { 4, 0, 12 } or { 0, 0, 2 }, Neck = { -6, 0, 4 * s },
			}, 1, SINE, B * 0.5)
		end
		-- THE POINT: up to the sky on the right, then down across his body
		local function point(up, beats, t)
			if up then
				add({
					RightArm = { 158, 0, -26 }, LeftArm = HIP, Hips = { 0, 0, 0, 0.2, 0.09, 0 }, Waist = { 4, 0, 4 },
					RightLeg = { 0, 0, 2 }, LeftLeg = { 4, 0, 14 }, Neck = { 22, -16, 0 },
				}, beats, nil, t)
			else
				add({
					RightArm = { 30, 46, 0 }, LeftArm = HIP, Hips = { 0, 0, 0, -0.12, 0.08, 0 }, Waist = { -8, 10, -3 },
					RightLeg = { 2, 0, 5 }, LeftLeg = { 2, 0, 5 }, Neck = { -18, 10, 0 },
				}, beats, nil, t)
			end
		end
		-- 5-12: THE POINT, once a beat
		for k = 1, 8 do
			point(k % 2 == 1, 1, 0.08)
		end
		-- 13-16: hip rolls - hands up, the hips going round, twice. (round 85
		-- review) Bigger and smooth: the body circles 0.3 studs out over his
		-- planted feet (the legs lean in to keep them where they are), the
		-- head tilting against it; eight points a turn at an even speed.
		for k = 1, 16 do
			local a = k * math.pi / 4
			local dx, dz = 0.3 * math.cos(a), 0.16 * math.sin(a)
			local r, p = math.deg(math.asin(dx / 2)), math.deg(math.asin(dz / 2)) -- (the feet back under the hips)
			add({
				RightArm = { 162, 0, -22 - 8 * math.cos(a) }, LeftArm = { 162, 0, -22 + 8 * math.cos(a) }, Hips = { 0, 0, 0, dx, 0.03, dz },
				Waist = { -5 * math.sin(a), 0, -3 * math.cos(a) }, RightLeg = { p, 0, 4 - r }, LeftLeg = { p, 0, 4 + r }, Neck = { 6, 0, 10 * math.cos(a) },
			}, 0.25, LIN, B * 0.25)
		end
		-- 17-18: the spin (a quarter turn every half beat), arms tucked...
		for q = 1, 4 do
			add({ Waist = { 0, -(q * 90) % 360, 0 }, RightArm = { 30, 30, 0 }, LeftArm = { 30, -30, 0 }, RightLeg = { 0, 0, 2 }, LeftLeg = { 0, 0, 2 }, Neck = { 4, 0, 0 } }, 0.5, LIN, B * 0.5)
		end
		-- 19-20: ...into the point, held
		point(true, 2, 0.12)
		-- 21-24: the hustle - a step out to the side, the other foot
		-- touched in with a clap; the other way
		for k = 1, 2 do
			local s = k == 1 and 1 or -1
			add({
				RightArm = { 40, 0, 40 }, LeftArm = { 40, 0, 40 }, Hips = { 0, 6 * s, 0, 0.3 * s, 0.13, 0 }, Waist = { 0, 0, -6 * s },
				RightLeg = s > 0 and { 2, 0, 20 } or { 0, 0, 2 }, LeftLeg = s > 0 and { 0, 0, 2 } or { 2, 0, 20 }, Neck = { 0, -10 * s, 0 },
			}, 1, SINE, B * 0.6)
			add({
				RightArm = { 78, 36, 0 }, LeftArm = { 78, -36, 0 }, Hips = { 0, 6 * s, 0, 0.36 * s, 0.03, 0 }, Crouch = 0.22, Waist = { -10, 0, 0 },
				Neck = { -6, -10 * s, 0 },
			}, 1, nil, 0.08)
		end
		-- 25-28: THE POINT at double time
		for k = 1, 8 do
			point(k % 2 == 1, 0.5, 0.06)
		end
		-- 29-30: down into the splits, pointing at the sky. (round 85 review)
		-- Crouch takes him all the way down so both feet are on the floor
		-- (R6 legs have no knees: a kneel is a split), leaning back so the
		-- point clears the spotlight.
		add({
			RightLeg = 60, LeftLeg = -60, Crouch = 1.0, Waist = { 12, 0, 0 }, RightArm = { 172, 0, -14 }, LeftArm = { -20, 0, 34 }, Neck = { 22, -10, 0 },
		}, 2, BACK, 0.12)
		-- 31: up, coiled, arms crossed in front...
		add({ RightArm = { 70, 40, 0 }, LeftArm = { 70, -40, 0 }, Crouch = 0.35, Hips = { 0, 0, 0, 0, 0.03, 0 }, Waist = { -14, 0, 0 }, Neck = { -12, 0, 0 } }, 1, nil, 0.1)
		-- 32: ...THE POSE - one arm flung up to the sky, the other down and
		-- out, hips cocked, a foot pointed
		add({
			RightArm = { 160, 0, -32 }, LeftArm = { -24, 0, 42 }, Hips = { 0, -10, 0, 0.18, 0.08, 0 }, Waist = { 6, 0, 4 },
			RightLeg = { 0, 0, 2 }, LeftLeg = { 8, 0, 20 }, Neck = { 18, -12, 0 },
		}, 1, BACK, 0.12)
		MOTIONS.EmoteFeverTime = EM.beatMotion(entry, steps, { recover = 0.45 }) -- 4+8+4+2+2+4+4+2+1+1 = 32 beats

		-- the props: a 5x5 light-up floor in the warm disco colours (its
		-- pattern changing with each move: rings, the checker for the point,
		-- a sweep for the hip rolls, half the floor for each hustle step...);
		-- a mirror ball lowered on a rod, turning, glittering, with rays of
		-- light down to the specks it throws on the floor (they wheel round
		-- him as it turns); a spotlight finding him for the splits; and on
		-- the pose the floor goes gold - "FEVER!!", confetti
		local COLORS = {
			Color3.fromRGB(255, 70, 70), Color3.fromRGB(255, 150, 40), Color3.fromRGB(255, 226, 70), Color3.fromRGB(255, 80, 190),
			Color3.fromRGB(80, 150, 255), Color3.fromRGB(255, 244, 214),
		}
		local GOLD = Color3.fromRGB(255, 210, 80)
		local function pattern(x, z, b)
			local ring = math.max(math.abs(x - 3), math.abs(z - 3)) -- (0 in the middle .. 2 at the edge)
			if b < 4 or (b >= 28 and b < 31) then -- (rings: out, then in for the finish - the edge, the middle, the centre)
				return ring == (b < 4 and b % 3 or 30 - b)
			elseif b < 12 or (b >= 24 and b < 28) then -- (the checker, flipping on the point)
				return (x + z + b) % 2 == 0
			elseif b < 16 then -- (a sweep across, with the hips)
				return (x + z) % 4 == b % 4
			elseif b < 20 then -- (the spin: the edge, then the middle)
				if b % 2 == 0 then
					return ring == 2
				end
				return ring < 2
			end
			return (b % 4 < 2) == (x >= 3) -- (the hustle: the side he steps to)
		end
		-- (the floor patterns, for the tests)
		EM.patterns = EM.patterns or {}
		EM.patterns.FeverTime = pattern
		local function confettiPuff(at, n)
			for _ = 1, n do
				local bit = newPart(Vector3.new(0.26, 0.04, 0.26), CFrame.new(at) * CFrame.Angles(rand(0, 6), rand(0, 6), rand(0, 6)), COLORS[rng:NextInteger(1, #COLORS)], Enum.Material.SmoothPlastic)
				local out = Vector3.new(rand(-1, 1), 0, rand(-1, 1)) * rand(2, 4.5)
				tween(bit, 0.35, { CFrame = bit.CFrame + out + UP * rand(3, 5.5) }, Enum.EasingStyle.Quad, Enum.EasingDirection.Out)
				task.delay(0.35, function()
					tween(bit, 1.1, { CFrame = bit.CFrame * CFrame.Angles(rand(-3, 3), rand(-3, 3), rand(-3, 3)) - UP * 5, Transparency = 1 }, Enum.EasingStyle.Sine)
				end)
				cleanup(bit, 1.5)
			end
		end
		EM.props.FeverTime = function(char, token, root)
			local bag = EM.bag()
			local floor = EM.floor(bag, root, { n = 5, pattern = pattern, colors = COLORS })
			local g = groundPoint(root.Position)
			local look = Vector3.new(root.CFrame.LookVector.X, 0, root.CFrame.LookVector.Z)
			look = look.Magnitude > 0.1 and look.Unit or Vector3.new(0, 0, -1)
			local HANG, FROM = 8.2, 20 -- (how high the ball hangs over the floor; where it comes down from)
			-- the mirror ball, its rod, its glitter and its light
			local ball = part(bag, Vector3.one * 2.4, CFrame.new(g + UP * FROM), Color3.fromRGB(226, 228, 238), Enum.Material.Foil, Enum.PartType.Ball)
			local rod = part(bag, Vector3.new(0.12, 14, 0.12), CFrame.new(g + UP * (FROM + 8)), Color3.fromRGB(60, 60, 70), Enum.Material.Metal)
			local glitter = Instance.new("ParticleEmitter")
			glitter.Texture = "rbxasset://textures/particles/sparkles_main.dds"
			glitter.Color = ColorSequence.new(Color3.new(1, 1, 1), Color3.fromRGB(200, 230, 255))
			glitter.LightEmission = 1
			glitter.Size = NumberSequence.new({ NumberSequenceKeypoint.new(0, 0.7), NumberSequenceKeypoint.new(1, 0) })
			glitter.Lifetime = NumberRange.new(0.25, 0.5)
			glitter.Speed = NumberRange.new(0.5, 1.5)
			glitter.SpreadAngle = Vector2.new(180, 180)
			glitter.Rate = 22
			glitter.Parent = ball
			local light = Instance.new("PointLight")
			light.Color = Color3.fromRGB(255, 236, 210)
			light.Range = 16
			light.Brightness = 1.2
			light.Parent = ball
			-- the specks it throws on the floor, a ray of light down to each
			local hub = Instance.new("Attachment")
			hub.Parent = ball
			local specks = {}
			for k = 1, 8 do
				local col = ({ Color3.new(1, 1, 1), GOLD, Color3.fromRGB(255, 120, 200), Color3.fromRGB(140, 200, 255) })[(k - 1) % 4 + 1]
				local speck = part(bag, Vector3.new(0.06, 0.8, 0.8), CFrame.new(g), col, Enum.Material.Neon, Enum.PartType.Cylinder)
				speck.Transparency = 0.15
				local tip = Instance.new("Attachment")
				tip.Parent = speck
				local ray = Instance.new("Beam")
				ray.Attachment0, ray.Attachment1 = hub, tip
				ray.Width0, ray.Width1 = 0.08, 0.42
				ray.Color = ColorSequence.new(col)
				ray.Transparency = NumberSequence.new(0.55, 0.85)
				ray.LightEmission = 1
				ray.FaceCamera = true
				ray.Segments = 1
				ray.Parent = speck
				table.insert(specks, { part = speck, r = 2.4 + (k % 3) * 1.6, a = k * math.pi * 2 / 8 + (k % 2) * 0.3 })
			end
			-- the spotlight (off till the splits): a soft cone from high up
			-- in front of him, and a pool of light
			local lamp = part(bag, Vector3.one * 0.2, CFrame.new(g + UP * 16 + look * 3), Color3.new(1, 1, 1))
			lamp.Transparency = 1
			local spotTop = Instance.new("Attachment")
			spotTop.Parent = lamp
			local pool = part(bag, Vector3.new(0.06, 5, 5), CFrame.new(g + UP * 0.16) * CFrame.Angles(0, 0, math.pi / 2), Color3.fromRGB(255, 244, 220), Enum.Material.Neon, Enum.PartType.Cylinder)
			pool.Transparency = 1
			local spotBase = Instance.new("Attachment")
			spotBase.Parent = pool
			local cone = Instance.new("Beam")
			cone.Attachment0, cone.Attachment1 = spotTop, spotBase
			cone.Width0, cone.Width1 = 1, 5 -- (round 85 review: narrower, so his point clears it)
			cone.Color = ColorSequence.new(Color3.fromRGB(255, 246, 225))
			cone.Transparency = NumberSequence.new(1)
			cone.LightEmission = 0.7
			cone.FaceCamera = true
			cone.Segments = 1
			cone.Parent = pool
			local spotOn, finale = false, nil
			local done = EM.beatLoop(char, token, root, entry, 32, function(b)
				if b < 31 then
					floor.beat(b)
				else
					-- the pose: the floor goes gold, FEVER!!, confetti, the ball bursts with glitter
					floor.flash(GOLD)
					finale = EM.label(root, "FEVER!!", GOLD, 40, 1.5, 2.5)
					finale.Parent = bag
					confettiPuff(root.Position + UP * 3, 24)
					glitter:Emit(40)
					VFX.PlaySound("Confetti", root.Position, 0.8)
				end
				if b % 4 == 0 and b < 28 then
					EM.label(root, b % 8 == 0 and "♪" or "♫", GOLD, 30, B * 3, 2).Parent = bag
				end
