		local root = char and char:FindFirstChild("HumanoidRootPart")
		local entry = EM.entry(id)
		local started, done = os.clock(), false
		local stopSong, token
		local before = char and poseTokens[char]
		if root and (fx or entry) then
			task.defer(function()
				token = poseTokens[char]
