		local UPRIGHT = CFrame.Angles(0, 0, math.pi / 2) -- (a cylinder's axis is X: stood up)
		local hat = {
			{ cyl(Vector3.new(0.07, 1.6, 1.6), BLACK), UPRIGHT },
			{ cyl(Vector3.new(0.2, 1.0, 1.0), BAND), CFrame.new(0, 0.14, 0) * UPRIGHT },
			{ cyl(Vector3.new(1.0, 0.96, 0.96), BLACK), CFrame.new(0, 0.53, 0) * UPRIGHT },
		}
		local cane = {
			{ EM.part(bag, Vector3.one * 0.32, root.CFrame, SILVER, Enum.Material.Metal, Enum.PartType.Ball), CFrame.new(-0.2, 0, 0) },
			{ cyl(Vector3.new(0.1, 0.18, 0.18), GOLD_S, Enum.Material.Metal), CFrame.new(-0.02, 0, 0) },
			{ cyl(Vector3.new(L - 0.1, 0.15, 0.15), BLACK), CFrame.new(L / 2 - 0.02, 0, 0) },
			{ cyl(Vector3.new(0.14, 0.16, 0.16), Color3.fromRGB(240, 240, 236)), CFrame.new(L - 0.05, 0, 0) },
		}
		-- a bow tie
		local tie = {
			{ EM.part(bag, Vector3.new(0.28, 0.26, 0.08), root.CFrame, BLACK), CFrame.new(0.17, 0, 0) * CFrame.Angles(0, 0, math.rad(10)) },
			{ EM.part(bag, Vector3.new(0.28, 0.26, 0.08), root.CFrame, BLACK), CFrame.new(-0.17, 0, 0) * CFrame.Angles(0, 0, math.rad(-10)) },
			{ EM.part(bag, Vector3.new(0.12, 0.12, 0.1), root.CFrame, BAND), CFrame.new(0, 0, -0.01) },
		}
		local function place(list, cf)
			for _, it in list do
				it[1].CFrame = cf * it[2]
			end
		end
		local function show(list, on)
			for _, it in list do
				it[1].Transparency = on and 0 or 1
			end
		end
		show(hat, false)
		show(cane, false)
		show(tie, false)
		-- where the cane is: its grip (a hand) and the way it points
		local caneCF, hatCF, blendCane, blendHat, mode, hatMode = nil, nil, 1, 1, nil, nil
		local function plantAt(side, lift) -- (the spot out front it's planted on)
			local target = (root.CFrame * CFrame.new(2.3 * side, 0, -1.5)).Position
			return Vector3.new(target.X, g0.Y + 0.05 + (lift or 0), target.Z) -- (he can't move: the street's where it was)
		end
		local function canePose(t, b, frac)
			local rh, lh = handPos(char, true), handPos(char, false)
			local look = root.CFrame.LookVector
			-- planted: from his hand to the spot, its tip ON it (round 85
			-- review: a hand nearer than the cane's long slides up the shaft,
			-- so the tip doesn't sink into the street)
			local function planted(hand, side, lift)
				local dir = plantAt(side, lift) - hand
				local dist = dir.Magnitude
				dir = dist > 0.1 and dir.Unit or -UP
				return along(hand - dir * math.max(L - dist, 0), dir)
			end
			if b < 4 then
				return "plant", planted(rh, 1)
			elseif b >= 24 and b < 28 then -- tapped: down on the beat, lifted clear on the "and"
				return "plant", planted(rh, 1, 0.45 * math.sin(math.pi * frac))
			elseif b >= 16 and b < 20 then -- twirled like a baton, held in the middle
				local a = t * 15
				local axis = UP * math.cos(a) + look * math.sin(a)
				return "twirl", along(rh - axis * (L / 2), axis)
			elseif b >= 20 and b < 24 then -- up over his head in both hands
				local span = lh - rh
				local axis = span.Magnitude > 0.1 and span.Unit or root.CFrame.RightVector * -1
				return "over", along((rh + lh) / 2 - axis * (L / 2), axis)
			elseif b >= 29 then -- in his left hand from the coil on, planted
				return "left", planted(lh, -1)
			end
			-- carried (round 85 review: it hangs from his fist the way a
			-- carried cane does - knob up, tipped a little forward, more as
			-- the arm swings forward - the fist sliding down the shaft so
			-- the tip stays just off the street; not poked out like a lance)
			local arm = char:FindFirstChild("Right Arm") or char:FindFirstChild("RightHand")
			local swing = arm and -arm.CFrame.UpVector:Dot(look) or 0 -- (how far forward the arm hangs)
			local a = math.clamp(0.2 + 0.3 * swing, -0.1, 0.5)
			local d = look * math.sin(a) - UP * math.cos(a)
			local grip = math.clamp(L - (rh.Y - g0.Y - 0.12) / math.cos(a), 0.15, L * 0.75)
			return "carry", along(rh - d * grip, d)
		end
		local function hatPose(b, frac)
			local head = char:FindFirstChild("Head")
			local hcf = head and head.CFrame or root.CFrame * CFrame.new(0, 1.5, 0)
			if b >= 30 then -- tipped (31-32): off his head, out in his hand, tilted to them
				local rh = handPos(char, true)
				return "hand", CFrame.new(rh) * root.CFrame.Rotation * CFrame.Angles(math.rad(-35), 0, 0) * CFrame.new(0, 0.05, -0.6)
			elseif b == 29 and frac >= 0.5 then -- a hand at the brim (30's "and"): tilted forward a little
				return "head", hcf * CFrame.new(0, 0.48, 0.02) * CFrame.Angles(math.rad(-14), 0, math.rad(-9))
			end
			return "head", hcf * CFrame.new(0, 0.48, 0.04) * CFrame.Angles(math.rad(-4), 0, math.rad(-9))
		end
		-- (round 85 review) the avatar's own hats and hair, hidden on this
		-- screen while the top hat's on (they'd poke through it); put back
		-- when it goes. Ones something else already hides are left alone;
		-- ones another emote's props hid (tagged EmoteHidden) are taken over.
		-- (As I AM HERE's headwear / cover: each emote has its own copy.)
		local covered, hiding = {}, false
		for _, acc in char:GetChildren() do
			local h = acc:IsA("Accessory") and acc:FindFirstChild("Handle")
			if h and h:IsA("BasePart") and ((h.LocalTransparencyModifier or 0) < 1 or h:GetAttribute("EmoteHidden")) then
				local okT, kind = pcall(function()
					return acc.AccessoryType == Enum.AccessoryType.Hat or acc.AccessoryType == Enum.AccessoryType.Hair
				end)
				if (okT and kind) or h:FindFirstChild("HatAttachment") or h:FindFirstChild("HairAttachment") then
					table.insert(covered, h)
				end
			end
		end
		local function cover(on)
			hiding = on
			for _, h in covered do
				if h.Parent then
					h.LocalTransparencyModifier = on and 1 or 0
					if (h:GetAttribute("EmoteHidden") == true) ~= on then
						h:SetAttribute("EmoteHidden", on or nil)
					end
				end
			end
		end
		local function uncover()
			if hiding then
				cover(false)
			end
		end
		local words = {} -- (the notes: gone at once if he's broken off)
		local lastT, poofed, dimmed = 0, false, false
		local finished = EM.beatLoop(char, token, root, entry, 32, function(b)
			local g = groundPoint(root.Position)
			if b == 0 then -- poof: the hat and cane appear
				show(hat, true)
				show(cane, true)
				show(tie, true)
				smokeBurst(root.Position + UP * 1.5, Color3.fromRGB(250, 250, 250), 0.8, 1.2, 0.6, 6)
				sparks(root.Position + UP * 2.5, 0.8, Color3.new(1, 1, 1), GOLD_S, 16)
				VFX.PlaySound("HairPoof", root.Position, 0.8)
			elseif b >= 24 and b < 28 then -- the taps (where it's planted: this frame's cane may still be on its way)
				local tip = plantAt(1)
				dustPuffs(Vector3.new(tip.X, g.Y, tip.Z), 0.25, 3, Color3.fromRGB(214, 206, 196), 0.4)
				VFX.PlaySound("ClockTick", tip, 0.7)
			elseif b == 28 then
				VFX.PlaySound("Scarf", root.Position, 0.8)
			elseif b == 30 then -- the hat tip
				sparks(handPos(char, true) + UP * 0.4, 0.8, Color3.new(1, 1, 1), GOLD_S, 18)
				shockDisc(g + UP * 0.2, UP, 2, 10, 0.4, GOLD_S)
				VFX.PlaySound("Bell", root.Position, 1)
				table.insert(words, EM.label(root, "✨", GOLD_S, 34, B * 2.4, 1.2))
			end
			if b % 2 == 0 and b > 0 and b < 30 then
				table.insert(words, EM.label(root, b % 4 == 0 and "♪" or "♫", GOLD_S, 28, B * 3, 2))
			end
			if b % 4 == 0 and b > 0 and b < 28 then -- a ring of light on every bar
				shockDisc(g + UP * 0.2, UP, 2, 7, 0.3, WARM)
			end
		end, function(t, b, frac)
			local dt = math.clamp(t - lastT, 0, 0.1)
			lastT = t
			if t >= 32 * B and not dimmed then -- the music's done: the spotlight goes
				dimmed = true
				tween(pool, 0.25, { Transparency = 1 })
				tween(beam, 0.25, { Width0 = 0, Width1 = 0 })
			end
			if t >= 32 * B + 0.2 and not poofed then -- then the hat and cane go in a poof (held through the bow)
				poofed = true
				show(hat, false)
				show(cane, false)
				show(tie, false)
				uncover()
				smokeBurst(handPos(char, true), Color3.fromRGB(250, 250, 250), 0.7, 1, 0.5, 5)
				VFX.PlaySound("HairPoof", root.Position, 0.6)
			end
			if poofed then
				return
			end
			if #covered > 0 then -- (his own hats and hair, under the top hat)
				cover(true)
			end
			-- the cane: eased over into each new way of holding it
			local m, want = canePose(t, b, frac)
			if m ~= mode then
				mode, blendCane = m, 0
			end
			blendCane = math.min(blendCane + dt / 0.12, 1)
			caneCF = (caneCF and blendCane < 1 and m ~= "twirl") and caneCF:Lerp(want, blendCane) or want
			place(cane, caneCF)
			-- the hat: on his head, then swept off into his hand
			local hm, hwant = hatPose(b, frac)
			if hm ~= hatMode then
				hatMode, blendHat = hm, 0
			end
			blendHat = math.min(blendHat + dt / 0.15, 1)
			hatCF = (hatCF and blendHat < 1) and hatCF:Lerp(hwant, blendHat) or hwant
			place(hat, hatCF)
			local torso = char:FindFirstChild("Torso") or char:FindFirstChild("UpperTorso")
			place(tie, (torso and torso.CFrame or root.CFrame) * CFrame.new(0, 0.82, -0.53))
			-- the spotlight breathes with the bar
			if not dimmed then
				pool.Transparency = 0.8 - 0.08 * (1 - frac)
			end
		end)
		uncover()
		if not finished then
			for _, w in words do
				if w.Parent then
					w:Destroy()
				end
			end
		end
		bag:Destroy()
	end
end)()

---------------------------------------------------------------------------
-- (round 85) MENACING: a JoJo-style menace taunt on the drop of Pegboard
-- Nerds - "Shaku" (Monstercat, 140 bpm), 8 beats (3.4 s, quick enough for
-- mid-fight): four poses, each snapped into on a hit of the drop (1, 3, 5,
-- 7) and leaned further into on the next beat - the glare back over his
-- shoulder, a hand over his face; leaned back, an arm up past his head;
-- low and twisted, framing his face; and the point, right at you. Purple
-- ゴゴゴ letters drift up round him, pulsing on the beat, a dark purple
-- outline and smoke round him; a boom and a ring on every new pose.
---------------------------------------------------------------------------
;(function()
	local EM = VFX.EMOTES
	local entry = EM.entry("Menacing") or { Id = "Menacing", Bpm = 140 }
	local B = 60 / (entry.Bpm or 140)
	local BACK, SINE = Enum.EasingStyle.Back, Enum.EasingStyle.Sine
	local steps = {}
	-- each pose: snapped into on the hit, then leaned further into (the
	-- waist and neck a little more) over the next beat
	local function pose(p, more)
		table.insert(steps, { pose = p, beats = 1, style = BACK, t = 0.12 })
		local q = table.clone(p)
		for _, k in { "Waist", "Neck" } do
			local v = p[k]
			if v then
				q[k] = { v[1] * more, v[2] * more, v[3] * more }
			end
		end
		table.insert(steps, { pose = q, beats = 1, style = SINE, t = B * 0.9 })
	end
	-- (R6: one body joint, so the twist is the whole body's and the head
	-- turns back to glare; Hips x / y keep the weight over the planted foot)
	pose({ -- 1-2: the glare back over his shoulder, a hand over his face, one toe pointed
		Hips = { 0, 0, 0, 0.2, 0.25, 0 }, Waist = { 8, 40, 10 }, Neck = { -8, -50, -6 },
		RightArm = { 140, 0, 50 }, LeftArm = { -30, 0, 25 }, RightLeg = { 10, 0, -6 }, LeftLeg = { -4, 0, 16 },
	}, 1.15)
	pose({ -- 3-4: leaned right back, an arm up past his head, looking down his nose
		Hips = { 0, 0, 0, -0.15, 0.32, 0 }, Waist = { 22, -32, -10 }, Neck = { -14, 32, 12 },
		LeftArm = { 165, 0, -25 }, RightArm = { 35, 20, 18 }, RightLeg = { 28, 0, 6 }, LeftLeg = { -20, 0, 12 },
	}, 1.12)
	pose({ -- 5-6: low and twisted, framing his face
		Crouch = 0.45, Hips = { 0, 0, 0, 0, 0.5, 0 }, Waist = { -12, 25, 8 }, Neck = { 8, -30, -14 },
		RightArm = { 165, 0, 30 }, LeftArm = { 90, -40, 0 }, RightLeg = { 20, 0, 18 }, LeftLeg = { 24, 0, 16 },
	}, 1.12)
	pose({ -- 7-8: the point - right at you
		Hips = { 0, 0, 0, -0.12, 0.01, 0 }, Waist = { 12, 30, -10 }, Neck = { 2, -28, 14 },
		RightArm = { 92, -10, 0 }, LeftArm = { 150, 0, 45 }, RightLeg = { 8, 0, -8 }, LeftLeg = { -6, 0, 12 },
	}, 1.1)
	MOTIONS.EmoteMenacing = EM.beatMotion(entry, steps, { recover = 0.35 }) -- 4 poses x 2 beats = 8 beats

	local PURPLE, INK, DEEP = Color3.fromRGB(196, 86, 255), Color3.fromRGB(30, 0, 46), Color3.fromRGB(46, 8, 70)
	EM.props.Menacing = function(char, token, root)
		local bag = EM.bag()
		local low = IceKit.lowEnd() -- (a low-end machine: half the smoke, letters on the beat only)
		-- a dark figure in a purple outline, purple smoke rising off him
		local aura = Instance.new("Highlight")
		aura.FillColor = DEEP
		aura.FillTransparency = 0.62
		aura.OutlineColor = PURPLE
		aura.OutlineTransparency = 0.15
		aura.DepthMode = Enum.HighlightDepthMode.Occluded
		aura.Adornee = char
		aura.Parent = bag
		local g = groundPoint(root.Position)
		local pool = EM.part(bag, Vector3.new(0.08, 7, 7), CFrame.new(g + UP * 0.05) * CFrame.Angles(0, 0, math.pi / 2), DEEP, Enum.Material.Neon, Enum.PartType.Cylinder)
		pool.Transparency = 0.55
		local vent = EM.part(bag, Vector3.new(3, 0.2, 3), CFrame.new(g + UP * 0.3), DEEP)
		vent.Transparency = 1
		local smoke = Instance.new("ParticleEmitter")
		smoke.Texture = "rbxasset://textures/particles/smoke_main.dds"
		smoke.Color = ColorSequence.new(Color3.fromRGB(130, 50, 200), DEEP)
		smoke.Transparency = NumberSequence.new({ NumberSequenceKeypoint.new(0, 1), NumberSequenceKeypoint.new(0.25, 0.55), NumberSequenceKeypoint.new(1, 1) })
		smoke.Size = NumberSequence.new(1.5, 4)
		smoke.Lifetime = NumberRange.new(0.8, 1.3)
		smoke.Rate = low and 9 or 18
		smoke.Speed = NumberRange.new(2, 5)
		smoke.SpreadAngle = Vector2.new(25, 25)
		smoke.EmissionDirection = Enum.NormalId.Top
		smoke.LightEmission = 0.2
		smoke.Parent = vent
		-- the letters: ゴ, in two columns either side of him as whoever's
		-- watching sees him, drifting up, pulsing on the beat
		local letters, pulse = {}, 0
		local function side()
			local cam = workspace.CurrentCamera
			local r = cam and cam.CFrame.RightVector or root.CFrame.RightVector
			r = Vector3.new(r.X, 0, r.Z)
			return r.Magnitude > 0.1 and r.Unit or Vector3.new(1, 0, 0)
		end
		local function letter(s, y, size)
			local anchor = EM.part(bag, Vector3.one * 0.1, root.CFrame, PURPLE)
			anchor.Transparency = 1
			local bb = Instance.new("BillboardGui")
			bb.Size = UDim2.fromScale(size, size)
			bb.LightInfluence = 0
			bb.MaxDistance = 160
			bb.Parent = anchor
			local label = Instance.new("TextLabel")
			label.BackgroundTransparency = 1
			label.Size = UDim2.fromScale(1, 1)
			label.TextScaled = true
			label.Font = Enum.Font.GothamBlack
			label.Text = "ゴ"
			label.TextColor3 = PURPLE
			label.TextStrokeColor3 = INK
			label.TextStrokeTransparency = 0
			label.TextTransparency = 1
			label.Rotation = rand(-12, 12)
			label.Parent = bb
			table.insert(letters, { anchor = anchor, bb = bb, label = label, born = os.clock(), s = s, x = rand(3, 3.7), y = y, size = size, phase = rand(0, 6) })
		end
		EM.beatLoop(char, token, root, entry, 8, function(b)
			pulse = os.clock()
			if b % 2 == 0 then -- a new pose: a boom, a ring
				local at = groundPoint(root.Position)
				shockDisc(at + UP * 0.3, UP, 3, b == 6 and 22 or 15, 0.4, PURPLE)
				billboardRing(root.Position + UP * 0.8, 2, b == 6 and 14 or 10, PURPLE, 7, 0.3)
				VFX.PlaySound("MuscleThump", root.Position, b == 0 and 0.8 or 0.55)
				if b == 0 then
					VFX.PlaySound("StandOn", root.Position, 0.9)
				end
			end
			-- a letter up one side on the beat, the other on the "and"
			-- (bigger on a new pose)
			local s = b % 2 == 0 and 1 or -1
			letter(s, -0.6, b % 2 == 0 and 2.5 or 2.1)
			task.delay(B * 0.5, function()
				if EM.alive(char, token, root) and not low then
					letter(-s, -0.6, 2.1)
				end
			end)
		end, function(t)
			local now = os.clock()
			local r = side()
			local beat = math.clamp(1 - (now - pulse) / 0.18, 0, 1)
			local over = math.clamp((t - 8 * B + 0.15) / 0.3, 0, 1) -- (fading out as it ends)
			smoke.Enabled = over <= 0
			pool.Transparency = 0.55 - 0.2 * beat + 0.45 * over
			aura.FillTransparency = 0.62 + 0.38 * over
			aura.OutlineTransparency = 0.15 + 0.85 * over
			for i = #letters, 1, -1 do
				local l = letters[i]
				local age = now - l.born
				if age > 1.7 then
					l.anchor:Destroy()
					table.remove(letters, i)
				else
					local wob = math.sin(age * 5 + l.phase) * 0.15
					l.anchor.CFrame = CFrame.new(root.Position + r * (l.s * l.x + wob) + UP * (l.y + age * 1.5))
					local k = 1 + 0.25 * beat
					l.bb.Size = UDim2.fromScale(l.size * k, l.size * k)
					local fade = math.max(1 - age / 0.12, (age - 1.3) / 0.4, over, 0)
					l.label.TextTransparency = math.clamp(fade, 0, 1)
					l.label.TextStrokeTransparency = math.clamp(fade, 0, 1)
				end
			end
		end)
		bag:Destroy()
	end
end)()

---------------------------------------------------------------------------
-- (round 85) SIX SEVEN: the 2025 "6 7" meme to a drift phonk (DRIFT NIGHT
-- PHONK, DistroKid, 155 bpm): palms up, the hands see-sawing like he's
-- weighing it - a big "6" pops over the high hand, then a "7" over the
-- other - four on the beat, two at double time, and a shrug with "67"
-- stamped over his head. 6 beats (2.3 s): quick enough for mid-fight.
---------------------------------------------------------------------------
;(function()
	local EM = VFX.EMOTES
	local entry = EM.entry("SixSeven") or { Id = "SixSeven", Bpm = 155 }
	local B = 60 / (entry.Bpm or 155)
	local SINE, BACK = Enum.EasingStyle.Sine, Enum.EasingStyle.Back
	local steps = {}
	local function add(pose, beats, style, t)
		table.insert(steps, { pose = pose, beats = beats, style = style, t = t })
	end
	-- one weigh, on side s (+1: the right hand up - "6"): dipped into on the
	-- beat, easing back up on the "and"
	local function weigh(s, beats)
		local up, down = { 104, 0, 14 }, { 50, 0, 14 }
		add({
			Crouch = 0.14, Hips = { 0, 0, 0, 0.08 * s, 0.06, 0 }, Waist = { -6, 0, 5 * s },
			RightArm = s > 0 and up or down, LeftArm = s > 0 and down or up, Neck = { 0, 8 * s, -6 * s },
		}, beats * 0.5)
		add({
			Hips = { 0, 0, 0, 0.04 * s, 0.01, 0 }, Waist = { -2, 0, 2 * s },
			RightArm = s > 0 and { 92, 0, 14 } or { 62, 0, 14 }, LeftArm = s > 0 and { 62, 0, 14 } or { 92, 0, 14 }, Neck = { 0, 4 * s, -3 * s },
		}, beats * 0.5, SINE, B * beats * 0.42)
	end
	for k = 1, 4 do -- 1-4: 6, 7, 6, 7
		weigh(k % 2 == 1 and 1 or -1, 1)
	end
	weigh(1, 0.5) -- 5: 6-7, twice as fast
	weigh(-1, 0.5)
	-- 6: the shrug - both palms up, shoulders up
	add({ Crouch = 0.2, Waist = { -4, 0, 0 }, RightArm = { 96, 0, 28 }, LeftArm = { 96, 0, 28 }, Neck = { -6, 0, 8 } }, 1, BACK, 0.1)
	MOTIONS.EmoteSixSeven = EM.beatMotion(entry, steps, { recover = 0.3 }) -- 4 + 1 + 1 = 6 beats

	local SIX, SEVEN = Color3.fromRGB(90, 225, 255), Color3.fromRGB(255, 96, 196)
	-- a number popping up over a hand (or his head), floating off
	local function number(bag, at, text, color, size, life)
		local anchor = EM.part(bag, Vector3.one * 0.1, CFrame.new(at), color)
		anchor.Transparency = 1
		local bb = Instance.new("BillboardGui")
		bb.Size = UDim2.fromScale(0, 0)
		bb.LightInfluence = 0
		bb.MaxDistance = 150
		bb.Parent = anchor
		local label = Instance.new("TextLabel")
		label.BackgroundTransparency = 1
		label.Size = UDim2.fromScale(1, 1)
		label.TextScaled = true
		label.Font = Enum.Font.LuckiestGuy
		label.Text = text
		label.TextColor3 = color
		label.TextStrokeColor3 = Color3.fromRGB(20, 16, 30)
		label.TextStrokeTransparency = 0
		label.Parent = bb
		tween(bb, 0.12, { Size = UDim2.fromScale(size, size) }, BACK)
		tween(anchor, life, { CFrame = anchor.CFrame + UP * 1.2 }, Enum.EasingStyle.Sine)
		tween(label, life * 0.4, { TextTransparency = 1, TextStrokeTransparency = 1 }, nil, nil, life * 0.6)
		cleanup(anchor, life + 0.05)
		return label
	end
	EM.props.SixSeven = function(char, token, root)
		local bag = EM.bag()
		local live = {} -- (the 6s and 7s: cleared off when the "67" lands)
		local function pop(s, size, life)
			-- (over where the high hand gets to: in front of him, to that side)
			local at = (root.CFrame * CFrame.new(1.45 * s, 2.3, -1.5)).Position
			table.insert(live, number(bag, at, s > 0 and "6" or "7", s > 0 and SIX or SEVEN, size, life))
			VFX.PlaySound("Bell", at, 0.45)
		end
		local finished = EM.beatLoop(char, token, root, entry, 6, function(b)
			if b < 4 then
				pop(b % 2 == 0 and 1 or -1, 2.6, B * 1.6)
			elseif b == 4 then
				pop(1, 2.1, B)
				task.delay(B * 0.5, function()
					if EM.alive(char, token, root) then
						pop(-1, 2.1, B)
					end
				end)
			else -- the shrug: "67" stamped over his head (round 85 review: the
				-- last 6 and 7 cleared off first, so it reads "67", not "677")
				for _, l in live do
					if l.Parent then
						tween(l, 0.08, { TextTransparency = 1, TextStrokeTransparency = 1 })
						tween(l.Parent, 0.08, { Size = UDim2.fromScale(0, 0) })
					end
				end
				local head = char:FindFirstChild("Head")
				local at = (head and head.Position or root.Position + UP * 1.5) + UP * 2.2
				number(bag, at - UP * 0.4, "67", Color3.fromRGB(255, 236, 90), 4.2, B * 2)
				shockDisc(groundPoint(root.Position) + UP * 0.3, UP, 2, 12, 0.35, Color3.fromRGB(255, 236, 90))
				sparks(at, 0.7, SIX, SEVEN, 14)
				VFX.PlaySound("Confetti", root.Position, 0.8)
			end
		end)
		if finished then -- (the "67" fades out in full, unless he moves first)
			local t1 = os.clock()
			while os.clock() - t1 < 0.4 and EM.alive(char, token, root) do
				task.wait()
			end
		end
		bag:Destroy()
	end
end)()

---------------------------------------------------------------------------
-- ONE FOR ALL: THE VESTIGE REALM, on your own screen (round 58). Drifting
-- off (VestigeIn) and waking up (VestigeOut); inside, the world goes dark -
-- a black void, a green haze, embers drifting up round you, lightning
-- crawling over the flame - and as you walk up to each of the vestiges,
-- who they were comes up at the foot of the screen.
-- (A function of its own: this script is near Luau's local limit.)
---------------------------------------------------------------------------
;(function()
	local VR = { on = false, saved = nil }
	VFX.VR = VR
	local CFG = Config.VestigeRealm or {}
	local CENTER = CFG.Center or Vector3.new(2600, 1400, -2600)
	local OFA = Color3.fromRGB(150, 255, 190)

	-- the black screen and the words over it (and the names, lower down)
	local screen, black, lineA, lineB, nameBox
	local function ui()
		if screen and screen.Parent then
			return
		end
		local me = Players.LocalPlayer
		local pg = me and me:FindFirstChildOfClass("PlayerGui")
		if not pg then
			return
		end
		screen = Instance.new("ScreenGui")
		screen.Name = "VestigeScreen"
		screen.IgnoreGuiInset = true
		screen.ResetOnSpawn = false
		screen.DisplayOrder = 30
		screen.Parent = pg
		black = Instance.new("Frame")
		black.Name = "Black"
		black.Size = UDim2.fromScale(1, 1)
		black.BackgroundColor3 = Color3.new(0, 0, 0)
		black.BackgroundTransparency = 1
		black.BorderSizePixel = 0
		black.Parent = screen
		local function words(y, size, font)
			local t = Instance.new("TextLabel")
			t.AnchorPoint = Vector2.new(0.5, 0.5)
			t.Position = UDim2.fromScale(0.5, y)
			t.Size = UDim2.new(0.8, 0, 0, size + 8)
			t.BackgroundTransparency = 1
			t.Font = font
			t.TextSize = size
			t.TextColor3 = Color3.fromRGB(226, 255, 236)
			t.TextTransparency = 1
			t.Text = ""
			t.Parent = screen
			return t
		end
		lineA = words(0.46, 22, Enum.Font.GothamMedium)
		lineB = words(0.53, 14, Enum.Font.GothamMedium)
		nameBox = Instance.new("Frame")
		nameBox.Name = "Vestige"
		nameBox.AnchorPoint = Vector2.new(0.5, 1)
		nameBox.Position = UDim2.new(0.5, 0, 1, -150)
		nameBox.Size = UDim2.fromOffset(520, 76)
		nameBox.BackgroundTransparency = 1
		nameBox.Parent = screen
		local function line(name, y, size, font, color)
			local t = Instance.new("TextLabel")
			t.Name = name
			t.Position = UDim2.fromOffset(0, y)
			t.Size = UDim2.new(1, 0, 0, size + 6)
			t.BackgroundTransparency = 1
			t.Font = font
			t.TextSize = size
			t.TextColor3 = color
			t.TextTransparency = 1
			t.TextStrokeTransparency = 1
			t.Text = ""
			t.Parent = nameBox
			return t
		end
		line("Name", 0, 26, Enum.Font.GothamBlack, Color3.new(1, 1, 1))
		line("Title", 32, 14, Enum.Font.GothamBold, Color3.fromRGB(255, 220, 120))
		line("Line", 52, 13, Enum.Font.GothamMedium, Color3.fromRGB(200, 236, 214))
	end

	local function fadeWords(t, text, show, time)
		if text then
			t.Text = text
		end
		tween(t, time or 0.6, { TextTransparency = show and 0.05 or 1 })
	end

	-- drifting off: heavy eyes, dark, and then you're somewhere else
	function Effects.VestigeIn()
		ui()
		if not black then
			return
		end
		tween(black, 1.1, { BackgroundTransparency = 0 }, Enum.EasingStyle.Sine)
		fadeWords(lineA, "your eyes close...", true, 0.8)
		task.delay(1.5, function()
			fadeWords(lineA, "...where is this?", true, 0.5)
			fadeWords(lineB, "INSIDE ONE FOR ALL", true, 0.9)
			tween(black, 1.8, { BackgroundTransparency = 1 }, Enum.EasingStyle.Sine)
			VFX.PlaySound("Wind", CENTER, 0.6)
		end)
		task.delay(4.2, function()
			fadeWords(lineA, nil, false, 1.2)
			fadeWords(lineB, nil, false, 1.2)
		end)
	end

	-- waking up, back on the roof
	function Effects.VestigeOut()
		ui()
		if not black then
			return
		end
		tween(black, 0.9, { BackgroundTransparency = 0 }, Enum.EasingStyle.Sine)
		fadeWords(lineA, "...", true, 0.5)
		task.delay(1.35, function()
			fadeWords(lineA, "you wake up.", true, 0.4)
			tween(black, 1.3, { BackgroundTransparency = 1 }, Enum.EasingStyle.Sine)
		end)
		task.delay(3, function()
			fadeWords(lineA, nil, false, 1)
		end)
	end

	-- the dark in there: your own screen's lighting, swapped while you're in
	-- it and put back as you leave
	local function swap(on)
		local L = game:GetService("Lighting")
		local atmo = L:FindFirstChildOfClass("Atmosphere")
		-- ((round 100, ui_moments) never the B/W of an ult cut-in or the K.O. screen
		-- (StreetMono: the kit's, gone when let go) - its grey would be "put back"
		-- onto the place's own grade as you leave)
		local cc
		for _, e in L:GetChildren() do
			if e:IsA("ColorCorrectionEffect") and e.Name ~= "StreetMono" then
				cc = e
				break
			end
		end
		if on then
			VR.saved = { Ambient = L.Ambient, OutdoorAmbient = L.OutdoorAmbient, Brightness = L.Brightness, FogColor = L.FogColor, FogStart = L.FogStart, FogEnd = L.FogEnd }
			pcall(function()
				VR.saved.ClockTime = L.ClockTime
				L.ClockTime = 0
			end)
			L.Ambient = Color3.fromRGB(20, 30, 26)
			L.OutdoorAmbient = Color3.fromRGB(10, 16, 13)
			L.Brightness = 0.3
			L.FogColor = Color3.fromRGB(2, 4, 4)
			L.FogStart = 50
			L.FogEnd = 420
			if atmo then
				VR.saved.atmo = { Density = atmo.Density, Offset = atmo.Offset, Color = atmo.Color, Decay = atmo.Decay, Glare = atmo.Glare, Haze = atmo.Haze }
				atmo.Density, atmo.Offset, atmo.Glare, atmo.Haze = 0.62, 0, 0, 0
				atmo.Color, atmo.Decay = Color3.fromRGB(6, 12, 9), Color3.new(0, 0, 0)
			end
			if cc then
				VR.saved.cc = { TintColor = cc.TintColor, Saturation = cc.Saturation, Contrast = cc.Contrast, Brightness = cc.Brightness }
				cc.TintColor = Color3.fromRGB(214, 255, 228)
				cc.Saturation = -0.2
				cc.Contrast = 0.14
				cc.Brightness = -0.02
			end
		elseif VR.saved then
			for k, v in VR.saved do
				if k ~= "atmo" and k ~= "cc" then
					pcall(function()
						L[k] = v
					end)
				end
			end
			if atmo and VR.saved.atmo then
				for k, v in VR.saved.atmo do
					atmo[k] = v
				end
			end
			if cc and VR.saved.cc then
				for k, v in VR.saved.cc do
					cc[k] = v
				end
			end
			VR.saved = nil
		end
	end

	-- embers drifting up round you
	local motes
	local function moteField(root)
		if not motes or not motes.Parent then
			motes = newPart(Vector3.new(70, 1, 70), CFrame.new(root.Position), OFA)
			motes.Name = "RealmMotes"
			motes.Transparency = 1
			local pe = Instance.new("ParticleEmitter")
			pe.Rate = 26
			pe.Lifetime = NumberRange.new(4, 7)
			pe.Speed = NumberRange.new(1, 3)
			pe.EmissionDirection = Enum.NormalId.Top
			pe.SpreadAngle = Vector2.new(20, 20)
			pe.Size = NumberSequence.new({ NumberSequenceKeypoint.new(0, 0), NumberSequenceKeypoint.new(0.2, 0.18), NumberSequenceKeypoint.new(1, 0) })
			pe.Color = ColorSequence.new(OFA, Color3.fromRGB(255, 226, 150))
			pe.LightEmission = 1
			pe.Parent = motes
		end
		motes.CFrame = CFrame.new(root.Position - Vector3.new(0, 3, 0))
	end

	-- who's that? the nearest vestige you've walked up to
	local shown
	local function reveal(root)
		local realm = workspace:FindFirstChild("VestigeRealm")
		local best, bestD = nil, 26
		for _, m in realm and realm:GetChildren() or {} do
			if m:IsA("Model") and m:GetAttribute("VestigeName") then
				local ok, pivot = pcall(function()
					return m:GetPivot()
				end)
				local d = ok and (pivot.Position - root.Position) * Vector3.new(1, 0, 1)
				if d and d.Magnitude < bestD then
					best, bestD = m, d.Magnitude
				end
			end
		end
		if best == shown or not nameBox then
			return
		end
		shown = best
		for _, key in { "Name", "Title", "Line" } do
			local t = nameBox:FindFirstChild(key)
			if t then
				if best then
					t.Text = tostring(best:GetAttribute("Vestige" .. key) or "")
				end
				tween(t, 0.8, { TextTransparency = best and 0.05 or 1, TextStrokeTransparency = best and 0.6 or 1 })
			end
		end
	end

	-- lightning crawling over the flame now and then
	local nextBolt = 0
	local function crackle(now)
		if now < nextBolt then
			return
		end
		nextBolt = now + 0.6 + math.random() * 1.6
		local realm = workspace:FindFirstChild("VestigeRealm")
		local heart = realm and realm:FindFirstChild("Heart")
		if heart then
			-- (an arc of it, big enough to see from where you woke)
			local p = heart.Position + Vector3.new(math.random() * 6 - 3, math.random() * 18 - 6, math.random() * 6 - 3)
			for _ = 1, 5 do
				local q = p + Vector3.new(math.random() * 8 - 4, math.random() * 6 - 1, math.random() * 8 - 4)
				local seg = newPart(Vector3.new(0.35, 0.35, (q - p).Magnitude), CFrame.lookAt((p + q) / 2, q), OFA, Enum.Material.Neon)
				cleanup(seg, 0.1)
				p = q
			end
		end
	end

	function VR.watch()
		if VR.watching then
			return
		end
		VR.watching = true
		local last = 0
		RunService.Heartbeat:Connect(function()
			local now = os.clock()
			if now - last < 0.15 then
				return
			end
			last = now
			local me = Players.LocalPlayer
			local char = me and me.Character
			local root = char and char:FindFirstChild("HumanoidRootPart")
			local inside = root ~= nil and (root.Position - CENTER).Magnitude < 460
			if inside ~= VR.on then
				VR.on = inside
				swap(inside)
				ui()
				if not inside then
					if motes then
						motes:Destroy()
						motes = nil
					end
					shown = false
					reveal({ Position = Vector3.new(0, 1e9, 0) }) -- (the name fades out)
				end
			end
			if inside then
				moteField(root)
				reveal(root)
				crackle(now)
			end
		end)
	end
end)()


---------------------------------------------------------------------------
-- (round 69) TWICE (Jin Bubaigawara): Double. Mud that takes his shape (or
-- yours) and lets go of it again; a yellow measuring tape that cuts; knives.
---------------------------------------------------------------------------
do
	local TW = {
		MUD = Color3.fromRGB(104, 70, 46), MUD2 = Color3.fromRGB(66, 44, 30), TAPE = Color3.fromRGB(240, 202, 58),
		STEEL = Color3.fromRGB(206, 210, 220), RED = Color3.fromRGB(214, 44, 52), WHITE = Color3.new(1, 1, 1),
	}
	VFX.TW = TW
	M1_TRAIL.Double = TW.STEEL

	POSES.KnifeWind = { RightArm = { 150, 0, 40 }, RightElbow = 70, LeftArm = { 60, 0, -10 }, LeftElbow = 20, Waist = { 4, 34, 0 }, Neck = { 0, -26, 0 }, RightLeg = 14, LeftLeg = -16, LeftKnee = 12 }
	POSES.KnifeThrow = { RightArm = { 88, 0, -18 }, RightElbow = 4, RightWrist = { -20, 0, 0 }, LeftArm = { 10, 0, 28 }, LeftElbow = 50, Waist = { -10, -28, 0 }, Neck = { 4, 20, 0 }, RightLeg = -18, LeftLeg = 20, LeftKnee = 22 }
	POSES.TapeCast = { RightArm = { 96, 0, 0 }, RightElbow = 0, LeftArm = { -24, 0, 18 }, LeftElbow = 30, Waist = { -6, -14, 0 }, Neck = { 2, 12, 0 }, RightLeg = -12, LeftLeg = 16, LeftKnee = 18 }
	POSES.TapeZip = { Hips = { 0, 0, 0, 0, -0.3, 0 }, RightArm = { 150, 0, 0 }, RightElbow = 0, LeftArm = { 70, 0, 30 }, LeftElbow = 60, Waist = { -30, 0, 0 }, Neck = { 22, 0, 0 }, RightLeg = -30, LeftLeg = 26, RightKnee = 40, LeftKnee = 50 }
	POSES.TapeSlash = { RightArm = { 70, 0, 70 }, RightElbow = 8, LeftArm = { 30, 0, -20 }, LeftElbow = 60, Waist = { -14, -40, 0 }, Neck = { 6, 30, 0 }, RightLeg = -20, LeftLeg = 22, LeftKnee = 26 }
	POSES.TapeReel = { RightArm = { 40, 0, -20 }, RightElbow = 110, LeftArm = { 60, 0, 10 }, LeftElbow = 40, Waist = { 10, 14, 0 }, Neck = { -4, -10, 0 }, RightLeg = 12, LeftLeg = -14, RightKnee = 10 }
	-- splitting in two: hunched, arms out from his sides, head down
	POSES.Split = { Waist = { -24, 0, 0 }, Neck = { -18, 0, 0 }, RightArm = { 10, 0, 60 }, RightElbow = 40, LeftArm = { 10, 0, 60 }, LeftElbow = 40, RightLeg = -8, LeftLeg = -8, RightKnee = 20, LeftKnee = 20 }
	-- "which one's the real one?!": both hands on his head
	POSES.HoldHead = { RightArm = { 150, 0, 40 }, RightElbow = 130, LeftArm = { 150, 0, 40 }, LeftElbow = 130, Waist = { -18, 0, 0 }, Neck = { -20, 0, 0 } }
	POSES.ParadePoint = { RightArm = { 100, 0, 10 }, RightElbow = 0, LeftArm = { 170, 0, 20 }, LeftElbow = 20, Waist = { -8, -18, 0 }, Neck = { -10, 14, 0 }, RightLeg = -16, LeftLeg = 18, LeftKnee = 20 }
	POSES.KO_Double = { RightArm = { 90, 0, 60 }, RightElbow = 10, LeftArm = { 30, 0, -30 }, LeftElbow = 70, Waist = { -18, -44, 0 }, Neck = { 8, 34, 0 }, RightLeg = -22, LeftLeg = 24, LeftKnee = 30 }

	MOTIONS.DaggerShot = { { pose = "KnifeWind", t = 0.08, hold = 0.02 }, { pose = "KnifeThrow", t = 0.05, hold = 0.12, style = SNAP }, { pose = "KnifeWind", t = 0.06, hold = 0 }, { pose = "KnifeThrow", t = 0.05, hold = 0.2, style = SNAP }, recover = 0.25 }
	MOTIONS.TwiceThrow = { { pose = "KnifeWind", t = 0.08, hold = 0.02 }, { pose = "KnifeThrow", t = 0.05, hold = 0.2, style = SNAP }, recover = 0.25 }
	MOTIONS.TapeDash = { { pose = "TapeCast", t = 0.06, hold = 0.04, style = SNAP }, { pose = "TapeZip", t = 0.08, hold = 0.26 }, { pose = "TapeSlash", t = 0.06, hold = 0.18, style = SNAP }, recover = 0.25 }
	MOTIONS.MeasureTape = { { pose = "TapeCast", t = 0.08, hold = 0.25, style = SNAP }, { pose = "TapeReel", t = 0.12, hold = 0.45 }, recover = 0.3 }
	MOTIONS.TwiceDouble = { { pose = "Split", t = 0.12, hold = 0.25 }, recover = 0.3 }
	MOTIONS.DoubleCross = { { pose = "HoldHead", t = 0.08, hold = 0.2 }, recover = 0.2 }
	MOTIONS.ParadeMarch = { { pose = "HoldHead", t = 0.12, hold = 0.2 }, { pose = "ParadePoint", t = 0.08, hold = 0.6, style = SNAP }, recover = 0.3 }
	MOTIONS.Dogpile = { { pose = "ParadePoint", t = 0.08, hold = 0.7, style = SNAP }, recover = 0.3 }
	MOTIONS.SadMansParade = { { pose = "HoldHead", t = 0.15, hold = 0.55 }, { pose = "Split", t = 0.12, hold = 0.35 }, { pose = "Present", t = 0.15, hold = 0.4 }, recover = 0.4 }

	-- a knife (blade and grip) at cf, blade forward (-Z)
	function TW.knife(cf)
		local blade = newPart(Vector3.new(0.1, 0.16, 0.9), cf * CFrame.new(0, 0, -0.35), TW.STEEL, Enum.Material.Metal)
		local grip = newPart(Vector3.new(0.14, 0.2, 0.4), cf * CFrame.new(0, 0, 0.3), Color3.fromRGB(34, 32, 36), Enum.Material.SmoothPlastic)
		local k = {}
		function k.set(c)
			blade.CFrame = c * CFrame.new(0, 0, -0.35)
			grip.CFrame = c * CFrame.new(0, 0, 0.3)
		end
		function k.gone(t)
			for _, p in { blade, grip } do
				tween(p, t or 0.15, { Transparency = 1 })
				cleanup(p, (t or 0.15) + 0.05)
			end
		end
		return k
	end
	-- the measuring tape: a thin yellow strip from a to b, out in `time`
	function TW.tape(a, b, time, life)
		local len = (b - a).Magnitude
		if len < 0.1 then
			return nil
		end
		local cf = CFrame.lookAt(a, b)
		local strip = newPart(Vector3.new(0.34, 0.05, 0.1), cf * CFrame.new(0, 0, -0.05), TW.TAPE, Enum.Material.SmoothPlastic)
		tween(strip, time or 0.1, { Size = Vector3.new(0.34, 0.05, len), CFrame = cf * CFrame.new(0, 0, -len / 2) })
		-- the ticks on it
		local ticks = newPart(Vector3.new(0.36, 0.06, 0.1), cf * CFrame.new(0, 0, -0.05), Color3.fromRGB(40, 36, 30), Enum.Material.SmoothPlastic)
		ticks.Transparency = 0.7
		tween(ticks, time or 0.1, { Size = Vector3.new(0.12, 0.06, len), CFrame = cf * CFrame.new(0.1, 0.01, -len / 2) })
		task.delay((time or 0.1) + (life or 0.25), function()
			for _, p in { strip, ticks } do
				tween(p, 0.12, { Size = Vector3.new(0.3, 0.04, 0.1), CFrame = cf * CFrame.new(0, 0, -0.05), Transparency = 1 })
				cleanup(p, 0.15)
			end
		end)
		return strip
	end
	-- a splash of mud at pos (scale ~ 1 for a body's worth)
	function TW.mud(pos, scale)
		scale = scale or 1
		local g = groundPoint(pos)
		local puddle = newPart(Vector3.new(0.2, 3 * scale, 3 * scale), CFrame.new(g + UP * 0.06) * CFrame.Angles(0, 0, math.rad(90)), TW.MUD2, Enum.Material.Mud, Enum.PartType.Cylinder)
		tween(puddle, 0.25, { Size = Vector3.new(0.2, 6 * scale, 6 * scale) })
		tween(puddle, 0.8, { Transparency = 1 }, Enum.EasingStyle.Quad, Enum.EasingDirection.In, 0.7)
		cleanup(puddle, 1.6)
		for _ = 1, math.floor(6 * scale) + 2 do
			local blob = newPart(Vector3.one * rand(0.3, 0.7) * scale, CFrame.new(pos), TW.MUD, Enum.Material.Mud, Enum.PartType.Ball)
			local out = Vector3.new(rand(-1, 1), rand(0.4, 1.2), rand(-1, 1)) * 4 * scale
			tween(blob, 0.3, { CFrame = CFrame.new(pos + out) }, Enum.EasingStyle.Quad, Enum.EasingDirection.Out)
			tween(blob, 0.25, { CFrame = CFrame.new(groundPoint(pos + out * 1.4) + UP * 0.1), Size = Vector3.new(0.6, 0.1, 0.6) * scale, Transparency = 0.4 }, Enum.EasingStyle.Quad, Enum.EasingDirection.In, 0.3)
			tween(blob, 0.5, { Transparency = 1 }, Enum.EasingStyle.Quad, Enum.EasingDirection.In, 0.8)
			cleanup(blob, 1.4)
		end
	end
	-- the parts of a body the mud shows on
	function TW.bodyParts(model)
		local out = {}
		for _, p in model:GetDescendants() do
			if p:IsA("BasePart") and p.Name ~= "HumanoidRootPart" and p.Transparency < 1 then
				table.insert(out, p)
			end
		end
		return out
	end
	-- a copy of a body on this screen only (the ult's crowd, the finisher)
	function TW.ghost(char, cf, life)
		local was = char.Archivable
		char.Archivable = true
		local ok, g = pcall(function()
			return char:Clone()
		end)
		char.Archivable = was
		if not ok or not g then
			return nil
		end
		for _, d in g:GetDescendants() do
			if d:IsA("LuaSourceContainer") or d:IsA("Highlight") or d:IsA("BillboardGui") or d:IsA("Sound") or d:IsA("Constraint") or d:IsA("ParticleEmitter") then
				d:Destroy()
			elseif d:IsA("BasePart") then
				d.Anchored = true
				d.CanCollide = false
				d.CanQuery = false
				d.CanTouch = false
			end
		end
		local hum = g:FindFirstChildOfClass("Humanoid")
		if hum then
			hum.DisplayDistanceType = Enum.HumanoidDisplayDistanceType.None
			hum.HealthDisplayType = Enum.HumanoidHealthDisplayType.AlwaysOff
		end
		g.Name = "TwiceGhost"
		g:PivotTo(cf)
		g.Parent = folder
		if life then
			task.delay(life, TW.meltModel, g, 0.5, true)
		end
		return g
	end
	-- mud rising into the shape: the colours come through the mud
	function TW.form(model, time)
		for _, p in TW.bodyParts(model) do
			local c = p.Color
			p.Color = TW.MUD
			tween(p, time or 0.35, { Color = c })
		end
	end
	-- back into mud: brown, slumping into the street, gone
	function TW.meltModel(model, time, destroy)
		time = time or 0.7
		local root = model:FindFirstChild("HumanoidRootPart")
		if root then
			TW.mud(root.Position, 0.9)
			VFX.PlaySound("CloneMelt", root.Position, 0.9)
		end
		for _, p in TW.bodyParts(model) do
			tween(p, time * 0.3, { Color = TW.MUD })
			tween(p, time * 0.7, { CFrame = p.CFrame * CFrame.new(0, -2.2, 0), Transparency = 1 }, Enum.EasingStyle.Quad, Enum.EasingDirection.In, time * 0.3)
		end
		for _, d in model:GetDescendants() do
			if d:IsA("Decal") or d:IsA("Texture") then
				tween(d, time * 0.6, { Transparency = 1 })
			end
		end
		if destroy then
			cleanup(model, time + 0.1)
		end
	end

	-- 1: DAGGER SHOT (the knives are TwiceKnife, from the server)
	function Effects.DaggerShot(char, data, isLocal)
		local root = charParts(char)
		if root and isLocal and typeof(data.Dir) == "Vector3" then
			face(root, flatten(data.Dir, root))
		end
		VFX.Motion(char, "DaggerShot")
	end
	Effects.DaggerStorm = Effects.DaggerShot
	-- one of his doubles throwing too
	function Effects.TwiceThrow(clone, data)
		local root = charParts(clone)
		if root and typeof(data.Dir) == "Vector3" then
			face(root, flatten(data.Dir, root))
		end
		VFX.Motion(clone, "TwiceThrow")
	end
	-- a knife in flight, and where it lands
	function Effects.TwiceKnife(_thrower, data)
		local from, to = data.From, data.To
		if typeof(from) ~= "Vector3" or typeof(to) ~= "Vector3" then
			return
		end
		local d = to - from
		local dist = d.Magnitude
		if dist < 0.5 then
			return
		end
		local time = math.clamp(dist / (tonumber(data.Speed) or 190), 0.04, 0.8)
		local k = TW.knife(CFrame.lookAt(from, to))
		VFX.PlaySound("KnifeThrow", from, 0.7)
		local t0 = os.clock()
		task.spawn(function()
			while os.clock() - t0 < time do
				local a = (os.clock() - t0) / time
				k.set(CFrame.lookAt(from:Lerp(to, a), to) * CFrame.Angles(0, 0, a * 20))
				task.wait()
			end
			k.set(CFrame.lookAt(to - d.Unit * 0.3, to))
			if typeof(data.Hit) == "Instance" then
				sparks(to, 0.5, TW.WHITE, TW.STEEL, 5)
				VFX.PlaySound("KnifeHit", to, 0.8)
				k.gone(0.1)
			else
				-- (stuck in whatever it hit)
				task.delay(1.2, k.gone, 0.3)
			end
		end)
	end

	-- 2: TAPE DASH - his machine zips him along the tape
	function Effects.TapeDash(char, data, isLocal, ability)
		local root = charParts(char)
		if not root then
			return
		end
		local d = typeof(data.Dir) == "Vector3" and data.Dir.Magnitude > 0.1 and data.Dir.Unit or root.CFrame.LookVector
		if d.Y < -0.2 then
			d = Vector3.new(d.X, -0.2, d.Z).Unit
		end
		local range = (ability and ability.Range) or 36
		local time = (ability and ability.Time) or 0.32
		if isLocal then
			face(root, flatten(d, root))
		end
		VFX.Motion(char, "TapeDash")
		local hand = handPos(char, true)
		TW.tape(hand, hand + d * range, 0.07, time)
		VFX.PlaySound("TapeWhip", hand, 0.9)
		task.wait(0.08)
		if not root.Parent then
			return
		end
		if isLocal then
			dash(root, d * (range / time), time)
		end
		local stop = addTrail(root, TW.TAPE, 0.2, 1.2)
		task.delay(time, stop, 0)
		streaks(root.Position, -d, 6, 1.5, 6, 12, WIND, 0.25)
	end
	function Effects.TapeSlash(char, data)
		local root = charParts(char)
		local target = typeof(data.Target) == "Instance" and data.Target or nil
		local troot = target and target:FindFirstChild("HumanoidRootPart")
		if not root or not troot then
			return
		end
		swingSmear(root, "HookRight", troot.Position, TW.STEEL, true)
		sparks(troot.Position, 0.7, TW.WHITE, TW.STEEL, 8)
		VFX.PlaySound("KnifeHit", troot.Position, 1)
	end

	-- 3: MEASURE - the tape lashes out (MeasureLash), wraps them (Measured)
	function Effects.MeasureTape(char, data, isLocal)
		local root = charParts(char)
		if root and isLocal and typeof(data.Dir) == "Vector3" then
			face(root, flatten(data.Dir, root))
		end
		VFX.Motion(char, "MeasureTape")
	end
	function Effects.MeasureLash(char, data)
		local root = charParts(char)
		if not root or typeof(data.To) ~= "Vector3" then
			return
		end
		local hand = handPos(char, true)
		local target = typeof(data.Target) == "Instance" and data.Target or nil
		local time = math.clamp((data.To - hand).Magnitude / 160, 0.05, 0.3)
		VFX.PlaySound("TapeWhip", hand, 1)
		TW.tape(hand, data.To, time, target and 0.8 or 0.12)
		if target then
			task.delay(time, function()
				local troot = target:FindFirstChild("HumanoidRootPart")
				if troot then
					sparks(troot.Position, 0.6, TW.WHITE, TW.TAPE, 6)
				end
			end)
		end
	end
	-- measured: a loop of tape round their waist while it lasts
	function Effects.Measured(_char, data)
		local target = typeof(data.Target) == "Instance" and data.Target or nil
		local troot = target and target:FindFirstChild("HumanoidRootPart")
		if not troot then
			return
		end
		-- (a flat disc through the waist: the body hides the middle, so it
		-- reads as a band)
		local ring = newPart(Vector3.new(0.3, 2.6, 2.6), troot.CFrame * CFrame.Angles(0, 0, math.rad(90)), TW.TAPE, Enum.Material.SmoothPlastic, Enum.PartType.Cylinder)
		ring.Transparency = 0.2
		local t0 = os.clock()
		local life = math.min(tonumber(data.Time) or 25, 30)
		task.spawn(function()
			while os.clock() - t0 < life and troot.Parent and target:GetAttribute("MeasuredBy") ~= nil do
				ring.CFrame = troot.CFrame * CFrame.new(0, -0.6, 0) * CFrame.Angles(0, 0, math.rad(90))
				task.wait()
			end
			tween(ring, 0.2, { Transparency = 1 })
			cleanup(ring, 0.25)
		end)
	end

	-- R: DOUBLE - he hunches and the mud comes off him (TwiceSplit: it's up)
	function Effects.Double(char)
		VFX.Motion(char, "TwiceDouble")
		local root = charParts(char)
		if root then
			TW.mud(root.Position, 0.6)
			VFX.PlaySound("CloneForm", root.Position, 0.9)
		end
	end
	function Effects.TwiceSplit(clone, data)
		local root = charParts(clone)
		if not root then
			return
		end
		TW.form(clone, 0.4)
		TW.mud(root.Position, 0.8)
		VFX.PlaySound("CloneForm", root.Position, 1)
		if typeof(data.From) == "Instance" then
			afterimage(data.From, TW.MUD, 0.2)
		end
	end
	function Effects.TwiceMelt(clone, data)
		TW.meltModel(clone, tonumber(data.Time) or 0.7, false)
	end
	-- one of his doubles swinging
	function Effects.TwiceClonePunch(clone, data)
		local root = charParts(clone)
		if root and typeof(data.Dir) == "Vector3" then
			face(root, flatten(data.Dir, root))
		end
		VFX.Play("Punch", clone, { Count = tonumber(data.Count) or 1, Finisher = false }, false)
	end

	-- 4: DOUBLE CROSS - hands to his head; mud at both ends of the swap
	-- (DoubleSwap, from the server)
	function Effects.DoubleCross(char)
		VFX.Motion(char, "DoubleCross")
	end
	function Effects.DoubleSwap(_char, data)
		for _, p in { data.From, data.To } do
			if typeof(p) == "Vector3" then
				TW.mud(p, 0.7)
				dustPuffs(p, 0.8, 5, TW.MUD, 0.5, false)
			end
		end
		if typeof(data.From) == "Vector3" then
			VFX.PlaySound("CloneForm", data.From, 0.8)
		end
	end
	-- nobody to swap with: a lump of mud lobbed to the spot (it stands up there)
	function Effects.CloneToss(_char, data)
		local from, to = data.From, data.To
		if typeof(from) ~= "Vector3" or typeof(to) ~= "Vector3" then
			return
		end
		local ball = newPart(Vector3.one * 1.6, CFrame.new(from), TW.MUD, Enum.Material.Mud, Enum.PartType.Ball)
		local t0 = os.clock()
		task.spawn(function()
			while os.clock() - t0 < 0.35 do
				local a = (os.clock() - t0) / 0.35
				ball.CFrame = CFrame.new(from:Lerp(to, a) + UP * 10 * a * (1 - a))
				task.wait()
			end
			ball:Destroy()
			TW.mud(to, 1)
		end)
	end

	-- ULT 1: PARADE - he points, they stampede
	function Effects.ParadeMarch(char, data, isLocal)
		local root = charParts(char)
		if root and isLocal and typeof(data.Dir) == "Vector3" then
			face(root, flatten(data.Dir, root))
		end
		VFX.Motion(char, "ParadeMarch")
		if root then
			VFX.PlaySound("ParadeRoar", root.Position, 1)
			local d = flatten(data.Dir, root)
			for i = 1, 6 do
				task.delay(i * 0.12, function()
					if root.Parent then
						dustPuffs(groundPoint(root.Position + d * (i * 6)), 1, 4, Color3.fromRGB(205, 196, 190), 0.6, false)
					end
				end)
			end
		end
	end
	-- ULT 3: DOGPILE
	function Effects.Dogpile(char, data, isLocal)
		local root = charParts(char)
		if root and isLocal and typeof(data.Dir) == "Vector3" then
			face(root, flatten(data.Dir, root))
		end
		VFX.Motion(char, "Dogpile")
	end
	function Effects.DogpileGo(char, data)
		local target = typeof(data.Target) == "Instance" and data.Target or nil
		local troot = target and target:FindFirstChild("HumanoidRootPart")
		if troot then
			VFX.PlaySound("ParadeRoar", troot.Position, 0.9)
		end
	end
	function Effects.DogpileBurst(_char, data)
		if typeof(data.Pos) ~= "Vector3" then
			return
		end
		TW.mud(data.Pos, 1.8)
		shockDisc(groundPoint(data.Pos) + UP * 0.3, UP, 3, 22, 0.35, TW.MUD, 3)
		VFX.PlaySound("CloneMelt", data.Pos, 1.3)
		VFX.ShakeAt(data.Pos, 1.4, 70, 0.3)
	end

	-- a dash: a smear of mud where he pushed off
	QUIRK_FX.Dash.Double = function(_char, root, dir)
		dustPuffs(root.Position - dir * 1.5, 0.6, 4, TW.MUD, 0.5, false)
	end
	-- SAD MAN'S PARADE: clutching his mask - then a crowd of him bursts out.
	-- ((round 101, awaken_m) on the awakening kit, VFX.AK.FX.Double - his clip
	-- MoveAwakenDouble, ONE pose (MOTIONS.SadMansParade was three, 2.2 s, and
	-- its hands-on-head can't be drawn on R6): the right hand clutching his
	-- mask, hunched, twitching (a smear of him jittering off to the side);
	-- then ON the hit the manic ringmaster - right arm flung up, left out -
	-- and the parade bursts out of the mud BEHIND him, one after another: two
	-- crowds of him either side, a gap left clear right behind him so his own
	-- pose reads between them (they were all round him at 0.55, some in the
	-- camera; a fan right behind him buried him in his own crowd), every other
	-- one doing his own awakening a beat late, the rest pointing the way; the
	-- server's real doubles pour out on the same hit; a splash of mud. Mud
	-- drips off him while he's in it. QUIRK_FX.Ult.Double folded in here.)
	VFX.AK.FX.Double = {
		gather = function(ctx)
			for i = 0, 1 do
				VFX.AK.M.at(ctx, 0.1 + i * 0.04, function()
					afterimage(ctx.char, TW.MUD, 0.12)
				end)
			end
		end,
		hit = function(ctx)
			local TC = (Config.Awaken or {}).Double or {}
			local P = TC.Parade or {}
			local char, root, s = ctx.char, ctx.root, ctx.scale
			local g = ctx.g or (root.Position - UP * 3 * s)
			if ctx.g then
				shockDisc(g + UP * 0.3, UP, 2, (TC.Splash or 30) * s, 0.4, TW.MUD, 5)
			end
			TW.mud(root.Position, 2 * s)
			VFX.PlaySound("CloneForm", root.Position, 1.2)
			-- the parade: alternate sides, working out from the gap behind him,
			-- facing the way he does
			local n = math.max(math.floor((P.Count or 8) * (ctx.low and 0.5 or 1)), 2)
			local per = math.ceil(n / 2)
			local back = math.atan2(-ctx.d.Z, -ctx.d.X)
			local half, gap = math.rad((P.Fan or 170) / 2), math.rad((P.Gap or 50) / 2)
			local radius = P.Radius or { 5, 9 }
			ctx.ghosts = {}
			for i = 1, n do
				local side = i % 2 == 0 and 1 or -1
				local a = back + side * (gap + (half - gap) * (math.floor((i - 1) / 2) + 0.5) / per)
				local out = Vector3.new(math.cos(a), 0, math.sin(a))
				local at = root.Position + out * rand(radius[1], radius[2]) * s
				if not VFX.AK.lens(ctx, at, 2 * s) then
					VFX.AK.M.at(ctx, ctx.hit + (i - 1) * (P.Stagger or 0.03), function()
						local ghost = TW.ghost(char, CFrame.lookAt(at, at + ctx.d), (ctx.release - ctx.hit) + i * 0.05)
						if ghost then
							-- (out of pale wet clay, turning into him: in the cut-in's black
							-- and white they read apart from his own dark silhouette)
							-- ((round 101 review) turning slowly at first (Quad In over
							-- Form): a linear 0.8 s had them as dark as him by the shout,
							-- his pose lost in a black crowd for the whole hold)
							local clay = P.Clay or Color3.fromRGB(168, 128, 92)
							for _, p in TW.bodyParts(ghost) do
								local c = p.Color
								p.Color = clay
								tween(p, P.Form or 1.3, { Color = c }, Enum.EasingStyle.Quad, Enum.EasingDirection.In)
							end
							TW.mud(at, 0.8 * s)
							if not (i % 2 == 0 and VFX.Clip(ghost, ctx.clip, { recover = 0.3 })) then
								VFX.Pose(ghost, "ParadePoint", 1.2)
							end
							table.insert(ctx.ghosts, ghost)
						end
					end)
				end
			end
			VFX.AK.note(ctx, "parade")
		end,
		aura = function(ctx)
			return VFX.AK.aura(ctx, ctx.spec.Aura or "ink")
		end,
	}
	-- M1s: a knife in the fist glints on the last one
	function VFX.TwicePunch(_char, count, finisher, fist)
		if finisher or count == 4 then
			sparks(fist, 0.6, TW.WHITE, TW.STEEL, 6)
			VFX.PlaySound("KnifeHit", fist, 0.7)
		end
	end
	-- the finisher: four of him round them, all punching at once, then his
	-- own knife
	function TW.finisher(char, target, troot, d, time)
		local root = char:FindFirstChild("HumanoidRootPart")
		if not root then
			return
		end
		for i = 1, 4 do
			local a = i / 4 * math.pi * 2 + 0.4
			local at = troot.Position + Vector3.new(math.cos(a), 0, math.sin(a)) * 3.2
			local ghost = TW.ghost(char, CFrame.lookAt(at, Vector3.new(troot.Position.X, at.Y, troot.Position.Z)), time * 0.8)
			if ghost then
				TW.form(ghost, 0.2)
				TW.mud(at, 0.6)
				task.delay(0.15 + i * 0.08, function()
					VFX.Pose(ghost, "PunchR", 0.4)
					sparks(troot.Position + UP, 0.6, TW.WHITE, TW.MUD, 5)
					VFX.PlaySound("Hit", troot.Position, 0.8)
				end)
			end
		end
		VFX.PlaySound("CloneForm", troot.Position, 1)
		task.wait(time * 0.6)
		VFX.Pose(char, "KO_Double", time * 0.4)
		swingSmear(root, "HookRight", troot.Position, TW.STEEL, true)
		VFX.PlaySound("KnifeHit", troot.Position, 1.2)
		sparks(troot.Position + UP, 1, TW.WHITE, TW.STEEL, 12)
		shockDisc(troot.Position + UP, d, 1, 12, 0.25, TW.STEEL, 4)
	end
end


---------------------------------------------------------------------------
-- (round 71) QUIRK CLASHES on screen (Config.Clash) - Jujutsu Shenanigans'
-- beam clash. Two beams out of the two of them meet at a white-hot knot of
-- light that bulges, sparks and throws lightning; rings race up each beam
-- with every good press; the street shakes and cracks under it. The two in
-- it get the camera (side on, your end on the LEFT, like JJS), letterbox
-- bars, "CLASH!", the tug meter in both colours up top and the prompt in
-- the middle (a keycap: W A D / Y X B; on a phone it jumps round the
-- screen - tap it wherever it lands). Everyone else sees it happen, with a
-- little meter floating over it. When it's decided the winner's beam
-- surges through the knot into the loser and it all goes up.
-- CL.solo runs one against a pretend opponent on your screen only (the
-- memory in One For All: Deku's Smash against Todoroki's flames).
---------------------------------------------------------------------------
do
	local CL = { live = {}, seen = {} }
	VFX.CL = CL
	POSES.ClashPush = { RightArm = { 96, 0, -14 }, RightElbow = 10, LeftArm = { 92, 0, 14 }, LeftElbow = 14, Waist = { -12, 0, 0 }, Neck = { 8, 0, 0 }, RightLeg = -20, LeftLeg = 26, RightKnee = 14, LeftKnee = 30 }
	local KEYCODES = { W = Enum.KeyCode.W, A = Enum.KeyCode.A, D = Enum.KeyCode.D }

	function CL.cfg()
		return Config.Clash or {}
	end
	-- how a move looks in a clash (Config.Clash.Moves)
	function CL.look(moveId)
		local spec = (CL.cfg().Moves or {})[moveId or ""]
		return spec or { Color = WIND, Core = Color3.new(1, 1, 1), Width = 4, Kind = "energy" }
	end
	-- where a beam leaves someone: out in front of the chest, at arm's length
	function CL.origin(char, towards, last)
		local root = char and char:FindFirstChild("HumanoidRootPart")
		if not root then
			return last or Vector3.zero
		end
		local d = typeof(towards) == "Vector3" and flatten(towards - root.Position, root) or flatten(root.CFrame.LookVector, root)
		return root.Position + d * 2.4 + UP * 0.8
	end
	-- the prompt after this one (the same as the server's: the seed is shared)
	function CL.nextKey(c)
		local keys = CL.cfg().Keys or { "W", "A", "D" }
		return keys[c.rng:NextInteger(1, #keys)]
	end
	function CL.reseed(c, index)
		c.rng = Random.new(c.seed + (c.me == "A" and 1 or 2) * 7919)
		c.key = CL.nextKey(c)
		for _ = 2, index do
			c.key = CL.nextKey(c)
		end
		c.index = index
	end
	function CL.padMode()
		local uis = game:GetService("UserInputService")
		local t = uis:GetLastInputType()
		if t == Enum.UserInputType.Touch then
			return "touch"
		end
		local name = tostring(t)
		return name:find("Gamepad") and "pad" or "keys"
	end

	-- a clash (opts: Id, A / B = characters, or GetA / GetB = functions for
	-- the points the beams leave from; AMove / BMove; AName / BName; Time;
	-- Seed; Me = "A" | "B" | nil; Solo = true for one on your screen only)
	function CL.new(o)
		local cam = workspace.CurrentCamera
		local c = {
			id = o.Id, me = o.Me, solo = o.Solo == true, seed = o.Seed or 1, t0 = os.clock(),
			ends = os.clock() + (o.Time or CL.cfg().Time or 10), m = 0, target = 0, shake = 0, punch = 0,
			lookA = CL.look(o.AMove), lookB = CL.look(o.BMove), nameA = o.AName or "", nameB = o.BName or "",
			charA = o.A, charB = o.B, pulses = {}, timers = {}, onEnd = o.OnEnd, npc = o.Npc,
		}
		local lastA, lastB
		c.getA = o.GetA or function()
			lastA = CL.origin(c.charA, c.charB and c.charB:FindFirstChild("HumanoidRootPart") and c.charB.HumanoidRootPart.Position, lastA)
			return lastA
		end
		c.getB = o.GetB or function()
			lastB = CL.origin(c.charB, c.charA and c.charA:FindFirstChild("HumanoidRootPart") and c.charA.HumanoidRootPart.Position, lastB)
			return lastB
		end
		local a, b = c.getA(), c.getB()
		-- (far off: nothing to draw - the pushes and the end are still tracked)
		c.drawn = c.me ~= nil or (cam and (cam.CFrame.Position - (a + b) / 2).Magnitude < 450)
		if c.me then
			CL.reseed(c, 1)
		end
		if c.drawn then
			CL.build(c, a, b)
			for _, char in { c.charA, c.charB } do
				if typeof(char) == "Instance" and char:IsA("Model") then
					VFX.Pose(char, "ClashPush", -1)
				end
			end
			VFX.PlaySound("ClashStart", (a + b) / 2, 1.2)
			VFX.ShakeAt((a + b) / 2, 2, 140, 0.5)
		end
		if c.me then
			CL.ui(c)
			CL.camera(c)
			CL.bind(c)
		elseif c.drawn then
			CL.billboard(c)
		end
		c.conn = RunService.Heartbeat:Connect(function(dt)
			local ok, err = pcall(CL.step, c, dt)
			if not ok then
				warn("[VFX] clash: " .. tostring(err))
				CL.cleanup(c)
			end
		end)
		return c
	end

	-- the beams and the knot where they meet
	function CL.build(c, a, b)
		local model = Instance.new("Model")
		model.Name = "Clash"
		model.Parent = folder
		c.model = model
		local function layer(color, material, transparency)
			local p = newPart(Vector3.new(1, 1, 1), CFrame.new(a), color, material, Enum.PartType.Cylinder, model)
			p.Transparency = transparency
			return p
		end
		for _, side in { "A", "B" } do
			local look = side == "A" and c.lookA or c.lookB
			c["beam" .. side] = {
				glow = layer(look.Color, Enum.Material.ForceField, 0.1),
				body = layer(look.Color, Enum.Material.Neon, 0.3),
				core = layer(look.Core, Enum.Material.Neon, 0.05),
				hand = newPart(Vector3.one * look.Width * 1.1, CFrame.new(a), look.Core, Enum.Material.Neon, Enum.PartType.Ball, model),
			}
		end
		local mid = (a + b) / 2
		c.orb = newPart(Vector3.one * 5, CFrame.new(mid), Color3.new(1, 1, 1), Enum.Material.Neon, Enum.PartType.Ball, model)
		c.shellA = newPart(Vector3.one * 8, CFrame.new(mid), c.lookA.Color, Enum.Material.ForceField, Enum.PartType.Ball, model)
		c.shellB = newPart(Vector3.one * 8, CFrame.new(mid), c.lookB.Color, Enum.Material.ForceField, Enum.PartType.Ball, model)
		local light = Instance.new("PointLight")
		light.Range = 46
		light.Brightness = 6
		light.Color = c.lookA.Color:Lerp(c.lookB.Color, 0.5)
		light.Parent = c.orb
		-- sparks spraying off the knot
		local at = Instance.new("Attachment")
		at.Parent = c.orb
		local pe = Instance.new("ParticleEmitter")
		pe.Texture = "rbxasset://textures/particles/sparkles_main.dds"
		pe.Rate = 140
		pe.Lifetime = NumberRange.new(0.25, 0.6)
		pe.Speed = NumberRange.new(40, 90)
		pe.SpreadAngle = Vector2.new(180, 180)
		pe.Size = NumberSequence.new(1.1, 0)
		pe.Color = ColorSequence.new(Color3.new(1, 1, 1), c.lookA.Color:Lerp(c.lookB.Color, 0.5))
		pe.LightEmission = 1
		pe.Drag = 4
		pe.Parent = at
		c.sparks = pe
		-- the roar of it
		local cue = Config.Sounds and Config.Sounds.ClashLoop
		local layerCue = type(cue) == "table" and cue[1]
		-- (a layer's Id: an asset id, or a list of takes { Id, Start })
		local take = layerCue and layerCue.Id
		if type(take) == "table" then
			take = take[1]
		end
		local id = type(take) == "table" and take.Id or take
		if type(id) == "string" and id ~= "" then
			local s = Instance.new("Sound")
			s.SoundId = id
			if type(take) == "table" and take.Start then
				s.TimePosition = take.Start
			end
			s.Looped = true
			s.Volume = layerCue.Volume or 1
			s.PlaybackSpeed = type(layerCue.Speed) == "number" and layerCue.Speed or 1
			s.RollOffMaxDistance = 320
			s.Parent = c.orb
			pcall(function()
				s:Play()
			end)
			c.loop = s
		end
		-- a scorch mark on the street under it
		groundMark(groundPoint(mid), 7, Color3.fromRGB(40, 34, 30), (c.ends - os.clock()) + 2)
	end

	-- one beam from `from` to the knot
	function CL.lay(beam, from, to, width, t, phase)
		local len = (to - from).Magnitude
		if len < 0.05 then
			return
		end
		local cf = CFrame.lookAt((from + to) / 2, to) * CFrame.Angles(0, math.rad(90), 0)
		local w = width * (1 + 0.1 * math.sin(t * 31 + phase) + 0.06 * math.sin(t * 57 + phase * 2))
		beam.glow.Size = Vector3.new(len, w * 1.9, w * 1.9)
		beam.body.Size = Vector3.new(len, w, w)
		beam.core.Size = Vector3.new(len, w * 0.42, w * 0.42)
		beam.glow.CFrame, beam.body.CFrame, beam.core.CFrame = cf, cf, cf
		beam.hand.CFrame = CFrame.new(from)
		beam.hand.Size = Vector3.one * w * (1.15 + 0.15 * math.sin(t * 40 + phase))
	end

	-- a ring racing up a beam to the knot (a good press)
	function CL.pulse(c, side)
		if not c.drawn or c.gone then
			return
		end
		local look = side == "A" and c.lookA or c.lookB
		local ring = newPart(Vector3.new(0.4, look.Width * 2.4, look.Width * 2.4), CFrame.new(), look.Core, Enum.Material.Neon, Enum.PartType.Cylinder, c.model)
		ring.Transparency = 0.15
		table.insert(c.pulses, { part = ring, side = side, born = os.clock() })
		c.bump = os.clock()
		c.shake = math.min(c.shake + 0.25, 1.6)
		if c.me == side then
			c.punch = 3
		end
		local now = os.clock()
		if now - (c.lastPushSound or 0) > 0.07 then
			c.lastPushSound = now
			VFX.PlaySound("ClashPush", c.point or c.getA(), 0.7)
		end
	end

	function CL.step(c, dt)
		if c.gone then
			return
		end
		local now = os.clock()
		local t = now - c.t0
		-- (a memory's pretend opponent: it presses too)
		if c.solo and c.npc and not c.done and now >= (c.npcNext or 0) then
			c.npcNext = now + (1 / (c.npc.Rate or 3.5)) * rand(0.75, 1.25)
			local step = CL.cfg().Step or 0.055
			if rng:NextNumber() < (c.npc.Accuracy or 0.85) then
				c.target = math.clamp(c.target - step, -1, 1)
				CL.pulse(c, "B")
			end
			CL.checkSolo(c)
		end
		if c.solo and not c.done and now >= c.ends then
			CL.over(c, math.abs(c.target) <= (CL.cfg().Draw or 0.06) and "Draw" or (c.target > 0 and "A" or "B"))
		end
		c.m += (c.target - c.m) * (1 - math.exp(-dt * (c.done and 22 or 12)))
		local a, b = c.getA(), c.getB()
		local point = a:Lerp(b, 0.5 + 0.45 * math.clamp(c.m, -1.12, 1.12))
		c.point = point
		c.shake = math.max(0, c.shake - dt * 2.4)
		c.punch = math.max(0, c.punch - dt * 12)
		if c.drawn and c.model then
			local lead = c.done and c.winner or nil
			CL.lay(c.beamA, a, lead == "A" and b or point, c.lookA.Width * (lead == "A" and 1.4 or lead == "B" and 0.35 or 1), t, 0)
			CL.lay(c.beamB, b, lead == "B" and a or point, c.lookB.Width * (lead == "B" and 1.4 or lead == "A" and 0.35 or 1), t, 1.7)
			local bumped = now - (c.bump or 0) < 0.08
			local s = 5 + 1.4 * math.sin(t * 26) + (bumped and 2 or 0) + math.min(t, 8) * 0.15
			local axis = (b - a).Magnitude > 0.1 and (b - a).Unit or Vector3.new(1, 0, 0)
			c.orb.Size = Vector3.one * s
			c.orb.CFrame = CFrame.new(point)
			c.shellA.Size = Vector3.one * s * 1.7
			c.shellB.Size = Vector3.one * s * 1.7
			c.shellA.CFrame = CFrame.new(point - axis * s * 0.25)
			c.shellB.CFrame = CFrame.new(point + axis * s * 0.25)
			-- the rings racing up the beams
			for i = #c.pulses, 1, -1 do
				local p = c.pulses[i]
				local u = (now - p.born) / 0.16
				if u >= 1 or not p.part.Parent then
					p.part:Destroy()
					table.remove(c.pulses, i)
				else
					local from = p.side == "A" and a or b
					local at = from:Lerp(point, u)
					p.part.CFrame = CFrame.lookAt(at, point) * CFrame.Angles(0, math.rad(90), 0)
					p.part.Transparency = 0.15 + u * 0.6
				end
			end
			-- what flies off the knot, on its own clocks
			local tm = c.timers
			if now >= (tm.spark or 0) then
				tm.spark = now + 0.09
				bolt(point, s * 0.9, rng:NextNumber() < 0.5 and c.lookA.Color or c.lookB.Color)
				if rng:NextNumber() < 0.5 then
					bolt(point, s * 1.3, Color3.new(1, 1, 1))
				end
			end
			if now >= (tm.ring or 0) then
				tm.ring = now + 0.24
				tm.flip = not tm.flip
				shockDisc(point, axis, s * 0.6, s * 3.4, 0.28, tm.flip and c.lookA.Color or c.lookB.Color, 0)
				VFX.ShakeAt(point, 0.45 + c.shake * 0.5, 110, 0.26)
			end
			if now >= (tm.ground or 0) then
				tm.ground = now + 0.35
				local g = groundPoint(point)
				if (point - g).Magnitude < 16 then
					dustPuffs(g, 0.9, 3, Color3.fromRGB(205, 196, 190), 0.6, false)
					if rng:NextNumber() < 0.5 then
						rocks(g, 0.7, 2)
					end
				end
				for _, look in { c.lookA, c.lookB } do
					if look.Kind == "fire" and Flame and Flame.burst then
						pcall(Flame.burst, point + Vector3.new(rand(-1, 1), rand(-1, 1), rand(-1, 1)) * s * 0.4, 0.9, 3)
					elseif look.Kind == "wind" then
						streaks(point, axis:Cross(UP).Unit * (rng:NextNumber() < 0.5 and 1 or -1), 3, 0.8, s, s * 3, WIND, 0.2)
					elseif look.Kind == "energy" then
						billboardRing(point, s * 0.8, s * 3, look.Color, 3, 0.22)
					end
				end
			end
			if c.bb then
				CL.meterSet(c.bb, (c.m + 1) / 2)
			end
		end
		if c.gui then
			CL.uiStep(c, now)
		end
		-- (safety net: the server's end never came)
		if now > c.ends + 4 then
			CL.cleanup(c)
		end
	end

	-- a pretend opponent's clash (a memory): is it decided?
	function CL.checkSolo(c)
		if not c.done and math.abs(c.target) >= 1 then
			CL.over(c, c.target > 0 and "A" or "B")
		end
	end

	---------------------------------------------------------------- the prompt
	function CL.send(c, key)
		local cfg = CL.cfg()
		local now = os.clock()
		if c.done or c.gone or now - (c.lastSend or 0) < (cfg.MinGap or 0.07) then
			return
		end
		c.lastSend = now
		local want = c.key
		local index = c.index
		c.index += 1
		c.key = CL.nextKey(c)
		if not c.solo then
			local remotes = game:GetService("ReplicatedStorage"):FindFirstChild("Remotes")
			local remote = remotes and remotes:FindFirstChild("Clash")
			if remote then
				remote:FireServer(c.id, index, key)
			end
		end
		CL.promptShow(c)
		if now < (c.lock or 0) then
			return -- (still reeling: it doesn't count)
		end
		local toward = c.me == "A" and 1 or -1
		if key == want then
			CL.promptFeedback(c, true)
			if c.solo then
				c.target = math.clamp(c.target + (cfg.Step or 0.055) * toward, -1, 1)
				CL.pulse(c, c.me)
				CL.checkSolo(c)
			end
		else
			c.lock = now + (cfg.WrongPenalty or 0.35)
			CL.promptFeedback(c, false)
			if c.solo then
				c.target = math.clamp(c.target - (cfg.Step or 0.055) * 0.5 * toward, -1, 1)
			end
		end
	end

	function CL.bind(c)
		local cas = game:GetService("ContextActionService")
		local pads = CL.cfg().PadKeys or {}
		local byName, codes = {}, {}
		for key, code in KEYCODES do
			byName[code.Name] = key
			table.insert(codes, code)
		end
		for key, name in pads do
			local ok, code = pcall(function()
				return Enum.KeyCode[name]
			end)
			if ok and code then
				byName[code.Name] = key
				table.insert(codes, code)
			end
		end
		cas:BindActionAtPriority("QuirkClash", function(_, state, input)
			if state == Enum.UserInputState.Begin then
				local key = input and input.KeyCode and byName[input.KeyCode.Name]
				if key then
					CL.send(c, key)
				end
			end
			return Enum.ContextActionResult.Sink
		end, false, Enum.ContextActionPriority.High.Value + 100, table.unpack(codes))
		c.bound = true
	end
	function CL.unbind(c)
		if c.bound then
			c.bound = false
			pcall(function()
				game:GetService("ContextActionService"):UnbindAction("QuirkClash")
			end)
		end
	end

	---------------------------------------------------------------- the screen
	local function label(parent, text, size, color, font)
		local t = Instance.new("TextLabel")
		t.BackgroundTransparency = 1
		t.Text = text
		t.TextSize = size
		t.TextColor3 = color or Color3.new(1, 1, 1)
		t.Font = font or Enum.Font.GothamBlack
		t.TextStrokeTransparency = 0.4
		t.Parent = parent
		return t
	end
	CL.label = label
	local function round(parent, r)
		local corner = Instance.new("UICorner")
		corner.CornerRadius = r or UDim.new(0, 8)
		corner.Parent = parent
		return corner
	end
	local function stroke(parent, color, thick)
		local s = Instance.new("UIStroke")
		s.Color = color
		s.Thickness = thick or 2
		s.ApplyStrokeMode = Enum.ApplyStrokeMode.Border
		s.Parent = parent
		return s
	end

	-- a word slammed onto the screen
	function CL.slam(parent, text, color, size, life, y)
		local t = label(parent, text, size, Color3.new(1, 1, 1), Enum.Font.LuckiestGuy)
		t.AnchorPoint = Vector2.new(0.5, 0.5)
		t.Position = UDim2.fromScale(0.5, y or 0.34)
		t.Size = UDim2.new(1, 0, 0, size + 20)
		t.TextStrokeColor3 = color
		t.TextStrokeTransparency = 0
		t.Rotation = rand(-6, 6)
		local sc = Instance.new("UIScale")
		sc.Scale = 2.6
		sc.Parent = t
		tween(sc, 0.16, { Scale = 1 }, Enum.EasingStyle.Back, Enum.EasingDirection.Out)
		tween(sc, 0.35, { Scale = 0.6 }, Enum.EasingStyle.Quad, Enum.EasingDirection.In, life - 0.35)
		tween(t, 0.35, { TextTransparency = 1, TextStrokeTransparency = 1 }, nil, nil, life - 0.35)
		cleanup(t, life + 0.05)
		return t
	end

	-- the tug meter: your colour from the left, theirs from the right
	function CL.meter(parent, width, height, left, right)
		local bar = Instance.new("Frame")
		bar.AnchorPoint = Vector2.new(0.5, 0)
		bar.Size = UDim2.fromOffset(width, height)
		bar.BackgroundColor3 = Color3.fromRGB(16, 16, 22)
		bar.BorderSizePixel = 0
		bar.Parent = parent
		round(bar, UDim.new(0, height // 2))
		stroke(bar, Color3.new(1, 1, 1), 2)
		local l = Instance.new("Frame")
		l.Name = "L"
		l.BackgroundColor3 = left
		l.BorderSizePixel = 0
		l.Size = UDim2.fromScale(0.5, 1)
		l.Parent = bar
		round(l, UDim.new(0, height // 2))
		local r = Instance.new("Frame")
		r.Name = "R"
		r.BackgroundColor3 = right
		r.BorderSizePixel = 0
		r.Position = UDim2.fromScale(0.5, 0)
		r.Size = UDim2.fromScale(0.5, 1)
		r.Parent = bar
		round(r, UDim.new(0, height // 2))
		local knot = Instance.new("Frame")
		knot.Name = "Knot"
		knot.AnchorPoint = Vector2.new(0.5, 0.5)
		knot.Position = UDim2.fromScale(0.5, 0.5)
		knot.Size = UDim2.fromOffset(height + 12, height + 12)
		knot.Rotation = 45
		knot.BackgroundColor3 = Color3.new(1, 1, 1)
		knot.BorderSizePixel = 0
		knot.ZIndex = 3
		knot.Parent = bar
		stroke(knot, Color3.fromRGB(255, 236, 160), 3)
		return bar
	end
	function CL.meterSet(bar, f)
		f = math.clamp(f, 0, 1)
		local l, r, k = bar:FindFirstChild("L"), bar:FindFirstChild("R"), bar:FindFirstChild("Knot")
		if l then
			l.Size = UDim2.fromScale(f, 1)
		end
		if r then
			r.Position = UDim2.fromScale(f, 0)
			r.Size = UDim2.fromScale(1 - f, 1)
		end
		if k then
			k.Position = UDim2.fromScale(f, 0.5)
		end
	end

	function CL.ui(c)
		local me = Players.LocalPlayer
		local pg = me and me:FindFirstChildOfClass("PlayerGui")
		if not pg then
			return
		end
		local mine = c.me == "A" and c.lookA or c.lookB
		local theirs = c.me == "A" and c.lookB or c.lookA
		local gui = Instance.new("ScreenGui")
		gui.Name = "ClashGui"
		gui.IgnoreGuiInset = true
		gui.ResetOnSpawn = false
		gui.DisplayOrder = 40
		gui.Parent = pg
		c.gui = gui
		local bar = CL.meter(gui, 560, 22, mine.Color, theirs.Color)
		bar.Position = UDim2.new(0.5, 0, 0, 96)
		c.bar = bar
		local you = label(gui, "YOU", 18, mine.Color)
		you.AnchorPoint = Vector2.new(0, 1)
		you.Position = UDim2.new(0.5, -280, 0, 92)
		you.Size = UDim2.fromOffset(200, 22)
		you.TextXAlignment = Enum.TextXAlignment.Left
		local them = label(gui, string.upper(c.me == "A" and c.nameB or c.nameA), 18, theirs.Color)
		them.AnchorPoint = Vector2.new(1, 1)
		them.Position = UDim2.new(0.5, 280, 0, 92)
		them.Size = UDim2.fromOffset(240, 22)
		them.TextXAlignment = Enum.TextXAlignment.Right
		c.clock = label(gui, "", 16, Color3.fromRGB(255, 236, 160))
		c.clock.AnchorPoint = Vector2.new(0.5, 1)
		c.clock.Position = UDim2.new(0.5, 0, 0, 92)
		c.clock.Size = UDim2.fromOffset(120, 20)
		-- the prompt: a keycap (a button you tap, on a phone)
		local key = Instance.new("TextButton")
		key.Name = "Prompt"
		key.AnchorPoint = Vector2.new(0.5, 0.5)
		key.Position = UDim2.fromScale(0.5, 0.66)
		key.Size = UDim2.fromOffset(112, 112)
		key.BackgroundColor3 = Color3.fromRGB(20, 20, 28)
		key.AutoButtonColor = false
		key.Font = Enum.Font.GothamBlack
		key.TextSize = 60
		key.TextColor3 = Color3.new(1, 1, 1)
		key.Text = ""
		key.Parent = gui
		round(key, UDim.new(0, 18))
		c.keyStroke = stroke(key, mine.Color, 4)
		c.keyScale = Instance.new("UIScale")
		c.keyScale.Parent = key
		local ring = Instance.new("Frame")
		ring.Name = "Ring"
		ring.AnchorPoint = Vector2.new(0.5, 0.5)
		ring.Position = UDim2.fromScale(0.5, 0.5)
		ring.Size = UDim2.fromOffset(170, 170)
		ring.BackgroundTransparency = 1
		ring.Parent = key
		round(ring, UDim.new(1, 0))
		c.ring = stroke(ring, Color3.new(1, 1, 1), 3)
		c.ringFrame = ring
		c.keyButton = key
		key.Activated:Connect(function()
			-- (a phone: tapping the button is pressing what it says)
			if c.key then
				CL.send(c, c.key)
			end
		end)
		local hint = label(key, "PRESS!", 16, Color3.fromRGB(255, 236, 160))
		hint.AnchorPoint = Vector2.new(0.5, 0)
		hint.Position = UDim2.new(0.5, 0, 1, 12)
		hint.Size = UDim2.fromOffset(160, 20)
		c.hint = hint
		CL.promptShow(c)
		VFX.Hooks.Letterbox(true)
		VFX.Hooks.Flash(Color3.new(1, 1, 1), 0.18)
		CL.slam(gui, "CLASH!", mine.Color, 110, 1.1, 0.36)
	end

	-- what to press now (a phone: the button moves somewhere new)
	function CL.promptShow(c)
		if not c.keyButton or not c.key then
			return
		end
		local mode = CL.padMode()
		local labels = CL.cfg().PadLabels or {}
		c.keyButton.Text = mode == "pad" and (labels[c.key] or c.key) or c.key
		if mode == "touch" then
			c.keyButton.Position = UDim2.fromScale(rand(0.22, 0.78), rand(0.36, 0.8))
		else
			c.keyButton.Position = UDim2.fromScale(0.5, 0.66)
		end
		c.keyScale.Scale = 1.22
		tween(c.keyScale, 0.12, { Scale = 1 }, Enum.EasingStyle.Back, Enum.EasingDirection.Out)
	end
	function CL.promptFeedback(c, good)
		if not c.keyButton then
			return
		end
		local mine = c.me == "A" and c.lookA or c.lookB
		if good then
			c.keyButton.BackgroundColor3 = mine.Color:Lerp(Color3.new(1, 1, 1), 0.3)
			tween(c.keyButton, 0.14, { BackgroundColor3 = Color3.fromRGB(20, 20, 28) })
			c.punch = 3
		else
			c.keyButton.BackgroundColor3 = Color3.fromRGB(200, 30, 40)
			tween(c.keyButton, 0.35, { BackgroundColor3 = Color3.fromRGB(20, 20, 28) })
			local base = c.keyButton.Position
			for i = 1, 4 do
				task.delay(i * 0.04, function()
					if c.keyButton then
						c.keyButton.Position = base + UDim2.fromOffset(i % 2 == 0 and -8 or 8, 0)
					end
				end)
			end
			task.delay(0.2, function()
				if c.keyButton then
					c.keyButton.Position = base
				end
			end)
			VFX.PlaySound("ClashWrong", nil, 0.8)
		end
	end

	function CL.uiStep(c, now)
		local mine = c.me == "A" and c.m or -c.m
		CL.meterSet(c.bar, (mine + 1) / 2)
		c.clock.Text = c.done and "" or string.format("%.1f", math.max(0, c.ends - now))
		local u = (now * 2.4) % 1
		c.ringFrame.Size = UDim2.fromOffset(170 - 50 * u, 170 - 50 * u)
		c.ring.Transparency = u
		local locked = now < (c.lock or 0)
		c.hint.Text = locked and "MISSED!" or "PRESS!"
		c.hint.TextColor3 = locked and Color3.fromRGB(255, 90, 90) or Color3.fromRGB(255, 236, 160)
		c.keyButton.TextTransparency = locked and 0.6 or 0
	end

	-- for everyone watching: a little meter hanging over it
	function CL.billboard(c)
		local bb = Instance.new("BillboardGui")
		bb.Size = UDim2.fromOffset(240, 60)
		bb.StudsOffsetWorldSpace = Vector3.new(0, 8, 0)
		bb.AlwaysOnTop = true
		bb.LightInfluence = 0
		bb.MaxDistance = 300
		bb.Adornee = c.orb
		bb.Parent = c.model
		local word = label(bb, "CLASH!", 26, Color3.new(1, 1, 1), Enum.Font.LuckiestGuy)
		word.Size = UDim2.new(1, 0, 0, 30)
		word.TextStrokeColor3 = c.lookA.Color:Lerp(c.lookB.Color, 0.5)
		word.TextStrokeTransparency = 0
		local bar = CL.meter(bb, 200, 12, c.lookA.Color, c.lookB.Color)
		bar.Position = UDim2.new(0.5, 0, 0, 38)
		c.bb = bar
	end

	---------------------------------------------------------------- the camera
	function CL.camera(c)
		local cam = workspace.CurrentCamera
		if not cam then
			return
		end
		VFX.CancelCinematic()
		c.camSaved = { Type = cam.CameraType, Fov = cam.FieldOfView }
		c.camFrom = cam.CFrame
		cam.CameraType = Enum.CameraType.Scriptable
		RunService:BindToRenderStep("QuirkClash", Enum.RenderPriority.Camera.Value + 2, function()
			if c.gone then
				return
			end
			local now = os.clock()
			local a, b = c.getA(), c.getB()
			local mid = c.point or (a + b) / 2
			local span = b - a
			local axis = Vector3.new(span.X, 0, span.Z)
			axis = axis.Magnitude > 0.1 and axis.Unit or Vector3.new(1, 0, 0)
			local side = axis:Cross(UP).Unit
			-- your end on the left of the screen
			local mineAt = c.me == "A" and a or b
			local lookDir = -side
			if (mineAt - mid):Dot(lookDir:Cross(UP)) > 0 then
				side = -side
			end
			local t = now - c.t0
			local sway = math.sin(t * 0.55) * 0.2
			local sep = span.Magnitude
			local dist = math.max(15, sep * 0.62) * (c.zoom or 1)
			local focus = mid
			if c.done and c.focus then
				focus = c.focus
				dist *= 0.8
			end
			local pos = focus + (side * math.cos(sway) + axis * math.sin(sway)) * dist + UP * (2.5 + sep * 0.07)
			local k = math.clamp(c.shake, 0, 2)
			local jitter = CFrame.Angles(math.rad(rand(-1, 1) * k), math.rad(rand(-1, 1) * k), math.rad(math.sin(t * 1.3) * 3 + rand(-1, 1) * k))
			local target = CFrame.lookAt(pos, focus + UP * 0.6) * jitter
			local blend = math.clamp(t / 0.55, 0, 1)
			cam.CFrame = blend < 1 and c.camFrom:Lerp(target, TweenService:GetValue(blend, Enum.EasingStyle.Quint, Enum.EasingDirection.Out)) or target
			local intensity = math.clamp(t / (c.ends - c.t0), 0, 1)
			cam.FieldOfView = 66 - 10 * intensity - c.punch
		end)
	end
	function CL.cameraBack(c)
		if not c.camSaved then
			return
		end
		local saved = c.camSaved
		c.camSaved = nil
		RunService:UnbindFromRenderStep("QuirkClash")
		local cam = workspace.CurrentCamera
		if cam then
			cam.CameraType = saved.Type ~= Enum.CameraType.Scriptable and saved.Type or Enum.CameraType.Custom
			cam.FieldOfView = saved.Fov
			local me = Players.LocalPlayer and Players.LocalPlayer.Character
			local hum = me and me:FindFirstChildOfClass("Humanoid")
			if hum then
				cam.CameraSubject = hum
			end
		end
		VFX.Hooks.Letterbox(false)
	end

	---------------------------------------------------------------- the end
	-- result: "A" | "B" (who won) | "Draw"
	function CL.over(c, result)
		if c.done or c.gone then
			return
		end
		c.done = true
		c.winner = result ~= "Draw" and result or nil
		c.target = result == "A" and 1.12 or result == "B" and -1.12 or c.target
		CL.unbind(c)
		local a, b = c.getA(), c.getB()
		local loserAt = result == "A" and b or result == "B" and a or (c.point or (a + b) / 2)
		c.focus = loserAt
		if c.gui then
			local mineWon = result == c.me
			local mine = c.me == "A" and c.lookA or c.lookB
			local theirs = c.me == "A" and c.lookB or c.lookA
			if c.keyButton then
				c.keyButton.Visible = false
			end
			if result == "Draw" then
				CL.slam(c.gui, "DEAD EVEN!", Color3.fromRGB(255, 236, 160), 90, 1.6, 0.4)
			elseif mineWon then
				CL.slam(c.gui, "OVERPOWERED!", mine.Color, 96, 1.7, 0.4)
			else
				CL.slam(c.gui, "PUSHED BACK...", theirs.Color, 80, 1.7, 0.4)
			end
		end
		task.delay(0.28, function()
			if c.gone then
				return
			end
			local winnerLook = result == "A" and c.lookA or result == "B" and c.lookB or nil
			local color = winnerLook and winnerLook.Color or Color3.new(1, 1, 1)
			if c.drawn then
				toonExplosion(loserAt, result == "Draw" and 3.2 or 2.6)
				shockDisc(loserAt, UP, 4, 46, 0.45, color, 6)
				billboardRing(loserAt, 4, 50, color, 8, 0.45)
				sparks(loserAt, 2.2, Color3.new(1, 1, 1), color, 30)
				dustPuffs(groundPoint(loserAt), 2.2, 10, Color3.fromRGB(205, 196, 190), 1.4, true)
				rocks(groundPoint(loserAt), 1.4, 10)
				VFX.ShakeAt(loserAt, 3.2, 220, 0.8)
				VFX.PlaySound("ClashWin", loserAt, 1.3)
			end
			if c.me then
				VFX.Hooks.Flash(Color3.new(1, 1, 1), 0.25)
			end
		end)
		for _, char in { c.charA, c.charB } do
			if typeof(char) == "Instance" and char:IsA("Model") then
				VFX.ReleasePose(char, 0.2)
			end
		end
		task.delay(1.5, function()
			CL.cleanup(c)
			if c.onEnd then
				task.spawn(c.onEnd, result)
			end
		end)
	end

	function CL.cleanup(c)
		if c.gone then
			return
		end
		c.gone = true
		CL.unbind(c)
		CL.cameraBack(c)
		if c.conn then
			c.conn:Disconnect()
		end
		if c.loop then
			c.loop:Stop()
		end
		if c.model then
			for _, p in c.model:GetDescendants() do
				if p:IsA("BasePart") then
					tween(p, 0.3, { Transparency = 1 })
				end
			end
			cleanup(c.model, 0.35)
		end
		if c.gui then
			cleanup(c.gui, 0.6)
		end
		if c.id then
			CL.live[c.id] = nil
		end
	end

	-- one against a pretend opponent, on your screen only (a memory).
	-- o: GetA / GetB, AMove / BMove, AName / BName, Time, Rate, Accuracy,
	-- OnEnd(result) - you're A
	function CL.solo(o)
		return CL.new({
			GetA = o.GetA, GetB = o.GetB, AMove = o.AMove, BMove = o.BMove, AName = o.AName, BName = o.BName,
			Time = o.Time or 8, Seed = math.random(1, 2 ^ 30), Me = "A", Solo = true, OnEnd = o.OnEnd,
			Npc = { Rate = o.Rate or 3.6, Accuracy = o.Accuracy or 0.85 },
		})
	end

	---------------------------------------------------------------- the server's
	function Effects.ClashStart(_, data)
		if typeof(data.A) ~= "Instance" or typeof(data.B) ~= "Instance" or CL.live[data.Id] then
			return
		end
		local me = Players.LocalPlayer and Players.LocalPlayer.Character
		CL.live[data.Id] = CL.new({
			Id = data.Id, A = data.A, B = data.B, AMove = data.AMove, BMove = data.BMove, AName = data.AName, BName = data.BName,
			Time = data.Time, Seed = data.Seed, Me = (me ~= nil and me == data.A and "A") or (me ~= nil and me == data.B and "B") or nil,
		})
	end
	function Effects.ClashPush(_, data)
		local c = CL.live[data.Id or 0]
		if not c or c.done then
			return
		end
		c.target = tonumber(data.M) or c.target
		if data.Good then
			CL.pulse(c, data.Side)
		end
	end
	-- (the server skipped a press: pick the prompt back up where it is)
	function Effects.ClashSync(_, data)
		local c = CL.live[data.Id or 0]
		if c and c.me and type(data.Index) == "number" and data.Index >= 1 then
			CL.reseed(c, data.Index)
			CL.promptShow(c)
		end
	end
	function Effects.ClashEnd(_, data)
		local c = CL.live[data.Id or 0]
		if not c then
			return
		end
		c.target = tonumber(data.M) or c.target
		CL.over(c, data.Draw and "Draw" or (data.Winner == c.charA and "A" or "B"))
	end
end


---------------------------------------------------------------------------
-- (round 71) NOMU RAIDS on screen (Config.NomuRaid). The High-End Nomu
-- (Hood): a hulking body in dark navy-purple, the brain showing through a
-- V-shaped slit in the hood of skin over its head, two small eyes under
-- it, red scars across the shoulders and arms, khaki trousers, skull-faced
-- guards on its knees, huge hands, bare feet - and the jets on its
-- shoulders. The server's body is invisible; this puppet is drawn over it
-- every frame (walking with it, winding up and swinging with its moves).
-- The raid itself: the warning and the red circle where it'll come down,
-- the fall and the landing, the boss bar (health, phase, clock, healing),
-- the damage board, a marker so you can find it, and how it ended.
---------------------------------------------------------------------------
do
	local NMV = {
		SKIN = Color3.fromRGB(54, 52, 90), SKIN_D = Color3.fromRGB(36, 34, 64), SCAR = Color3.fromRGB(178, 42, 66),
		PANTS = Color3.fromRGB(200, 180, 124), PANTS_D = Color3.fromRGB(162, 142, 94), BELT = Color3.fromRGB(70, 52, 36),
		BONE = Color3.fromRGB(228, 226, 216), HOLE = Color3.fromRGB(34, 30, 34), BRAIN = Color3.fromRGB(198, 130, 118),
		BRAIN_D = Color3.fromRGB(150, 88, 84), RIM = Color3.fromRGB(216, 198, 150), METAL = Color3.fromRGB(64, 64, 74),
		JET = Color3.fromRGB(255, 150, 60), RED = Color3.fromRGB(210, 34, 44),
		S = 2.5, -- (puppet scale: ~15 studs tall)
	}
	VFX.NMV = NMV
	-- per limb { pitch (+ forward), yaw, roll (+ out), bend }; head { pitch (+ up), yaw }; lean (+ back)
	NMV.P = {
		idle = { armR = { 14, 0, 14, 24 }, armL = { 14, 0, 14, 24 }, legR = { 8, 0, 12, 16 }, legL = { 8, 0, 12, 16 }, head = { 12, 0 }, lean = -14 },
		swipeWind = { armR = { 30, 0, 80, 40 }, armL = { 20, 0, 10, 40 }, legR = { 18, 0, 14, 30 }, legL = { -6, 0, 14, 12 }, head = { 10, -20 }, lean = -10, twist = -38 },
		swipeHit = { armR = { 86, 0, -30, 6 }, armL = { -10, 0, 20, 30 }, legR = { -10, 0, 14, 10 }, legL = { 24, 0, 14, 30 }, head = { 6, 20 }, lean = -22, twist = 44 },
		crouch = { armR = { 60, 0, 30, 60 }, armL = { 60, 0, 30, 60 }, legR = { 70, 0, 14, 100 }, legL = { 70, 0, 14, 100 }, head = { 30, 0 }, lean = -36 },
		air = { armR = { 170, 0, 20, 30 }, armL = { 170, 0, 20, 30 }, legR = { 40, 0, 10, 70 }, legL = { 40, 0, 10, 70 }, head = { 10, 0 }, lean = -10 },
		slamLand = { armR = { 70, 0, 20, 10 }, armL = { 70, 0, 20, 10 }, legR = { 76, 0, 16, 90 }, legL = { 60, 0, 16, 76 }, head = { 24, 0 }, lean = -48 },
		charge = { armR = { -46, 0, 24, 30 }, armL = { -46, 0, 24, 30 }, legR = { 40, 0, 12, 50 }, legL = { -20, 0, 12, 30 }, head = { 34, 0 }, lean = -48 },
		roar = { armR = { 46, 0, 84, 40 }, armL = { 46, 0, 84, 40 }, legR = { 12, 0, 18, 22 }, legL = { 12, 0, 18, 22 }, head = { 38, 0 }, lean = 14 },
		fall = { armR = { 150, 0, 40, 30 }, armL = { 150, 0, 40, 30 }, legR = { 20, 0, 10, 30 }, legL = { -10, 0, 10, 20 }, head = { -20, 0 }, lean = 6 },
		down = { armR = { 60, 0, 40, 0 }, armL = { 40, 0, 50, 0 }, legR = { 20, 0, 20, 10 }, legL = { 10, 0, 20, 10 }, head = { -30, 0 }, lean = -85 },
	}

	-- the Nomu, built out of parts (PUP)
	function NMV.build()
		local PUP = VFX.PUP
		local pp = PUP.new("HighEndNomuPuppet", NMV.S, Color3.fromRGB(12, 10, 22))
		pp.jointed = true
		local function P(key, size, at, color, material, shape)
			return PUP.part(pp, key, size, at, color, material, shape)
		end
		local SK, SD = NMV.SKIN, NMV.SKIN_D
		-- the torso: a barrel chest, pecs, the abs, the huge trapezius, shoulders
		P("torso", Vector3.new(3.0, 1.35, 1.6), CFrame.new(0, 0.42, 0), SK)
		for side = -1, 1, 2 do
			P("torso", Vector3.new(1.4, 0.85, 0.55), CFrame.new(side * 0.72, 0.52, -0.72), SK)
			P("torso", Vector3.one * 1.7, CFrame.new(side * 1.5, 0.78, 0), SK, nil, Enum.PartType.Ball)
			-- the red scars across the shoulders
			P("torso", Vector3.new(0.7, 0.12, 0.12), CFrame.new(side * 1.75, 1.1, -0.55) * CFrame.Angles(0, 0, math.rad(side * 28)), NMV.SCAR, Enum.Material.Neon)
			P("torso", Vector3.new(0.5, 0.1, 0.1), CFrame.new(side * 1.2, 0.2, -0.9) * CFrame.Angles(0, 0, math.rad(side * -20)), NMV.SCAR)
			-- the shoulder jets: engines sat on its back, nozzles out behind
			P("torso", Vector3.new(0.95, 0.72, 0.72), CFrame.new(side * 1.05, 1.05, 0.95) * CFrame.Angles(math.rad(-30), math.rad(90), 0), NMV.METAL, Enum.Material.Metal, Enum.PartType.Cylinder)
			local nozzle = P("torso", Vector3.new(0.2, 0.8, 0.8), CFrame.new(side * 1.05, 1.32, 1.4) * CFrame.Angles(math.rad(-30), math.rad(90), 0), NMV.HOLE, Enum.Material.Metal, Enum.PartType.Cylinder)
			nozzle.Name = side > 0 and "JetR" or "JetL"
		end
		P("torso", Vector3.new(2.3, 0.95, 1.6), CFrame.new(0, 1.18, 0.18), SK)
		P("torso", Vector3.new(1.9, 1.15, 1.3), CFrame.new(0, -0.55, -0.05), SD)
		for k = -1, 1 do
			P("torso", Vector3.new(1.4, 0.06, 0.06), CFrame.new(0, -0.55 + k * 0.32, -0.72), NMV.HOLE)
		end
		P("torso", Vector3.new(0.06, 1.0, 0.06), CFrame.new(0, -0.55, -0.72), NMV.HOLE)
		-- the trousers' waist and belt
		P("torso", Vector3.new(2.25, 0.5, 1.5), CFrame.new(0, -1.1, 0), NMV.PANTS)
		P("torso", Vector3.new(2.3, 0.16, 1.55), CFrame.new(0, -0.9, 0), NMV.BELT)
		P("torso", Vector3.new(0.18, 0.22, 0.06), CFrame.new(0, -1.02, -0.78), NMV.PANTS_D)
		-- the head: a thick neck, the hood of skin, the brain in the slit
		P("head", Vector3.new(1.15, 0.7, 1.0), CFrame.new(0, 0.1, 0.1), SD)
		P("head", Vector3.new(1.5, 1.85, 1.6), CFrame.new(0, 0.9, 0.08), SK, nil, Enum.PartType.Ball)
		P("head", Vector3.new(0.85, 1.3, 0.55), CFrame.new(0, 0.95, -0.55), NMV.BRAIN, nil, Enum.PartType.Ball)
		for i, c in { { -0.18, 1.3 }, { 0.16, 1.18 }, { -0.2, 0.85 }, { 0.18, 0.72 }, { 0, 1.02 }, { -0.1, 0.55 }, { 0.12, 1.45 } } do
			P("head", Vector3.one * (0.26 + (i % 3) * 0.05), CFrame.new(c[1], c[2], -0.78), NMV.BRAIN_D, nil, Enum.PartType.Ball)
		end
		for side = -1, 1, 2 do
			P("head", Vector3.new(0.12, 1.55, 0.22), CFrame.new(side * 0.36, 0.95, -0.72) * CFrame.Angles(0, 0, math.rad(side * -14)), NMV.RIM)
			P("head", Vector3.one * 0.22, CFrame.new(side * 0.17, 0.36, -0.78), Color3.new(1, 1, 1), nil, Enum.PartType.Ball)
			P("head", Vector3.one * 0.08, CFrame.new(side * 0.17, 0.36, -0.89), Color3.new(0, 0, 0), nil, Enum.PartType.Ball)
		end
		-- the arms: huge upper arms, bigger forearms, fists like boulders
		for _, k in { { "armR", "foreR", 1 }, { "armL", "foreL", -1 } } do
			local side = k[3]
			P(k[1], Vector3.new(1.5, 1.4, 1.5), CFrame.new(side * 0.35, -0.55, 0), SK)
			P(k[1], Vector3.one * 1.3, CFrame.new(side * 0.35, -0.5, -0.35), SK, nil, Enum.PartType.Ball)
			P(k[1], Vector3.new(0.6, 0.12, 0.1), CFrame.new(side * 0.35, -0.35, -0.8) * CFrame.Angles(0, 0, math.rad(side * 24)), NMV.SCAR)
			P(k[2], Vector3.new(1.7, 1.45, 1.6), CFrame.new(side * 0.35, -0.6, 0), SK)
			P(k[2], Vector3.new(0.7, 0.12, 0.1), CFrame.new(side * 0.35, -0.5, -0.82) * CFrame.Angles(0, 0, math.rad(side * -30)), NMV.SCAR)
			P(k[2], Vector3.new(1.65, 1.05, 1.55), CFrame.new(side * 0.35, -1.55, -0.05), SD)
			for f = -1.5, 1.5 do
				P(k[2], Vector3.one * 0.42, CFrame.new(side * 0.35 + f * 0.36, -1.95, -0.62), SD, nil, Enum.PartType.Ball)
			end
		end
		-- the legs: khaki to the knee, the skull knee guards, bare feet
		for _, k in { { "legR", "shinR", 1 }, { "legL", "shinL", -1 } } do
			local side = k[3]
			P(k[1], Vector3.new(1.45, 1.35, 1.5), CFrame.new(side * 0.2, -0.55, 0), NMV.PANTS)
			P(k[1], Vector3.new(0.08, 1.0, 0.3), CFrame.new(side * 0.2 + side * 0.66, -0.6, -0.2), NMV.PANTS_D)
			P(k[2], Vector3.new(1.25, 1.1, 1.3), CFrame.new(side * 0.2, -0.55, 0), SK)
			P(k[2], Vector3.new(1.05, 1.05, 0.5), CFrame.new(side * 0.2, 0.0, -0.78), NMV.BONE)
			for e = -1, 1, 2 do
				P(k[2], Vector3.new(0.24, 0.32, 0.06), CFrame.new(side * 0.2 + e * 0.2, 0.08, -1.05), NMV.HOLE)
			end
			P(k[2], Vector3.new(0.5, 0.2, 0.06), CFrame.new(side * 0.2, -0.3, -1.05), NMV.HOLE)
			P(k[2], Vector3.new(1.35, 0.45, 1.95), CFrame.new(side * 0.2, -1.1, -0.35), SD)
			for t = -1.5, 1.5 do
				P(k[2], Vector3.one * 0.34, CFrame.new(side * 0.2 + t * 0.3, -1.18, -1.28), SD, nil, Enum.PartType.Ball)
			end
		end
		for _, e in pp.parts do
			e.part.CastShadow = true
		end
		return pp
	end
	-- the jets on its shoulders firing (for `time`)
	function NMV.jets(pp, time, big)
		for _, e in pp.parts do
			if e.part.Name == "JetR" or e.part.Name == "JetL" then
				local nozzle = e.part
				local stop = addTrail(nozzle, NMV.JET, 0.25, big and 2.4 or 1.4)
				task.delay(time, stop, 0)
				local t0 = os.clock()
				task.spawn(function()
					while os.clock() - t0 < time and nozzle.Parent do
						local back = -nozzle.CFrame.RightVector
						local flare = newPart(Vector3.new(0.6, 1.6, 1.6) * (big and 1.6 or 1), nozzle.CFrame * CFrame.new(-0.6, 0, 0), NMV.JET, Enum.Material.Neon, Enum.PartType.Ball)
						flare.Transparency = 0.2
						tween(flare, 0.16, { Size = Vector3.new(0.2, 0.4, 0.4), Transparency = 1, CFrame = CFrame.new(nozzle.Position + back * 3) })
						cleanup(flare, 0.2)
						task.wait(0.05)
					end
				end)
			end
		end
	end

	-- the raid on this screen
	function NMV.rec()
		NMV.r = NMV.r or { move = nil, phase = 1, lastPos = nil, walk = 0 }
		return NMV.r
	end
	function NMV.bodyModel()
		local f = workspace:FindFirstChild("NomuRaid")
		return f and f:FindFirstChild("HighEndNomu")
	end
	function NMV.drive()
		if NMV.conn then
			return
		end
		NMV.conn = RunService.Heartbeat:Connect(function(dt)
			local ok, err = pcall(NMV.step, dt)
			if not ok then
				warn("[VFX] nomu: " .. tostring(err))
			end
		end)
	end
	function NMV.stop()
		if NMV.conn then
			NMV.conn:Disconnect()
			NMV.conn = nil
		end
		local r = NMV.r
		if r and r.pp then
			r.pp.model:Destroy()
		end
		NMV.r = nil
	end

	function NMV.step(dt)
		local r = NMV.rec()
		local now = os.clock()
		local body = NMV.bodyModel()
		local root = body and body:FindFirstChild("HumanoidRootPart")
		if r.falling then
			return -- (the fall is its own animation)
		end
		if not root then
			if r.pp and not r.dying then
				r.pp.model:Destroy()
				r.pp = nil
			end
			if now > (r.idleUntil or 0) and not r.dying then
				NMV.stop()
			end
			return
		end
		r.idleUntil = now + 3
		if not r.pp then
			r.pp = NMV.build()
			NMV.marker(r, root)
		end
		local S = NMV.S
		local hip = ((Config.NomuRaid or {}).HipHeight or 6) + 3.5
		local look = root.CFrame.LookVector
		look = Vector3.new(look.X, 0, look.Z)
		look = look.Magnitude > 0.01 and look.Unit or Vector3.new(0, 0, -1)
		local speed = r.lastPos and Vector3.new(root.Position.X - r.lastPos.X, 0, root.Position.Z - r.lastPos.Z).Magnitude / math.max(dt, 1 / 240) or 0
		r.lastPos = root.Position
		-- the pose: its move if it's making one, else walking or standing
		local pose = NMV.P.idle
		local drop = 0
		local mv = r.move
		local t = mv and now - mv.t0 or 0
		if r.dying then
			pose = NMV.blend(NMV.P.idle, NMV.P.down, math.clamp((now - r.dying) / 0.8, 0, 1))
			drop = -S * 1.6 * math.clamp((now - r.dying) / 0.8, 0, 1)
		elseif mv and mv.Kind == "Swipe" and t < (mv.Windup or 0.45) + 0.5 then
			local w = mv.Windup or 0.45
			pose = t < w and NMV.blend(NMV.P.idle, NMV.P.swipeWind, math.clamp(t / w, 0, 1)) or NMV.blend(NMV.P.swipeHit, NMV.P.idle, math.clamp((t - w - 0.15) / 0.35, 0, 1))
			if (mv.Side or 1) < 0 then
				pose = NMV.mirror(pose)
			end
		elseif mv and mv.Kind == "Slam" and t < (mv.Windup or 0.35) + (mv.Air or 0.85) + 0.7 then
			local w, air = mv.Windup or 0.35, mv.Air or 0.85
			if t < w then
				pose = NMV.blend(NMV.P.idle, NMV.P.crouch, t / w)
			elseif t < w + air then
				pose = NMV.blend(NMV.P.crouch, NMV.P.air, math.clamp((t - w) / (air * 0.4), 0, 1))
			else
				pose = NMV.blend(NMV.P.slamLand, NMV.P.idle, math.clamp((t - w - air - 0.3) / 0.4, 0, 1))
				drop = -S * 0.8 * (1 - math.clamp((t - w - air) / 0.6, 0, 1))
			end
		elseif mv and mv.Kind == "Charge" and t < (mv.Windup or 0.6) + (mv.Time or 0.5) + 0.4 then
			pose = NMV.blend(NMV.P.idle, NMV.P.charge, math.clamp(t / 0.3, 0, 1))
		elseif mv and mv.Kind == "Roar" and t < 1.4 then
			pose = NMV.blend(NMV.P.idle, NMV.P.roar, math.clamp(t / 0.25, 0, 1) * (1 - math.clamp((t - 1.1) / 0.3, 0, 1)))
		elseif mv and mv.Kind == "Escape" then
			pose = NMV.P.air
		elseif speed > 1.5 then
			-- a heavy, lumbering walk
			r.walk += dt * math.clamp(speed, 4, 30) * 0.32
			local sw = math.sin(r.walk)
			local k = math.clamp(speed / 20, 0.4, 1)
			pose = {
				armR = { 14 - sw * 26 * k, 0, 14, 28 }, armL = { 14 + sw * 26 * k, 0, 14, 28 },
				legR = { 8 + sw * 30 * k, 0, 12, 16 + math.max(0, -sw) * 40 * k }, legL = { 8 - sw * 30 * k, 0, 12, 16 + math.max(0, sw) * 40 * k },
				head = { 12, 0 }, lean = -16 - 6 * k, twist = sw * 6 * k,
			}
			drop = -math.abs(math.cos(r.walk)) * 0.25 * S
		end
		local ground = root.Position - UP * hip
		local cf = CFrame.lookAt(ground + UP * (3.1 * S + drop), ground + UP * (3.1 * S + drop) + look)
		VFX.PUP.place(r.pp, cf, pose)
		-- healing: green steam off it
		if body:GetAttribute("Regen") and now >= (r.steam or 0) then
			r.steam = now + 0.18
			dustPuffs(root.Position + Vector3.new(rand(-3, 3), rand(-2, 5), rand(-3, 3)), 0.8, 1, Color3.fromRGB(150, 255, 170), 0.8, false)
		end
		NMV.markerStep(r, root)
	end
	-- (PUP.blend: a pose part-way between two)
	function NMV.blend(a, b, k)
		return VFX.PUP.blend(a, b, math.clamp(k, 0, 1))
	end
	function NMV.mirror(pose)
		local out = table.clone(pose)
		out.armR, out.armL = pose.armL, pose.armR
		out.legR, out.legL = pose.legL, pose.legR
		out.twist = -(pose.twist or 0)
		local h = pose.head or { 0, 0 }
		out.head = { h[1] or 0, -(h[2] or 0) }
		return out
	end

	-- a marker over it you can see from anywhere
	function NMV.marker(r, root)
		local bb = Instance.new("BillboardGui")
		bb.Name = "NomuMarker"
		bb.Size = UDim2.fromOffset(120, 44)
		bb.StudsOffsetWorldSpace = Vector3.new(0, 14, 0)
		bb.AlwaysOnTop = true
		bb.LightInfluence = 0
		bb.Adornee = root
		bb.Parent = r.pp.model
		local t = VFX.CL.label(bb, "NOMU", 20, NMV.RED, Enum.Font.LuckiestGuy)
		t.Size = UDim2.new(1, 0, 0, 24)
		t.TextStrokeColor3 = Color3.new(0, 0, 0)
		t.TextStrokeTransparency = 0
		local d = VFX.CL.label(bb, "", 14, Color3.new(1, 1, 1))
		d.Position = UDim2.fromOffset(0, 24)
		d.Size = UDim2.new(1, 0, 0, 18)
		r.markerGui, r.markerDist = bb, d
	end
	function NMV.markerStep(r, root)
		local cam = workspace.CurrentCamera
		if not r.markerGui or not cam then
			return
		end
		local dist = (cam.CFrame.Position - root.Position).Magnitude
		r.markerGui.Enabled = dist > 70
		r.markerDist.Text = string.format("%dm", math.floor(dist))
	end

	---------------------------------------------------------------- the screen
	function NMV.gui()
		local me = Players.LocalPlayer
		local pg = me and me:FindFirstChildOfClass("PlayerGui")
		if not pg then
			return nil
		end
		local gui = pg:FindFirstChild("NomuRaidGui")
		if gui then
			return gui
		end
		gui = Instance.new("ScreenGui")
		gui.Name = "NomuRaidGui"
		gui.IgnoreGuiInset = true
		gui.ResetOnSpawn = false
		gui.DisplayOrder = 20
		gui.Parent = pg
		return gui
	end
	function NMV.banner(title, sub, color, life)
		local gui = NMV.gui()
		if not gui then
			return
		end
		local box = Instance.new("Frame")
		box.Name = "Banner"
		box.AnchorPoint = Vector2.new(0.5, 0.5)
		box.Position = UDim2.fromScale(0.5, 0.3)
		box.Size = UDim2.fromOffset(640, 110)
		box.BackgroundColor3 = Color3.fromRGB(12, 6, 10)
		box.BackgroundTransparency = 0.25
		box.BorderSizePixel = 0
		box.Parent = gui
		local stripe = Instance.new("Frame")
		stripe.Size = UDim2.new(1, 0, 0, 4)
		stripe.BackgroundColor3 = color
		stripe.BorderSizePixel = 0
		stripe.Parent = box
		local t = VFX.CL.label(box, title, 50, Color3.new(1, 1, 1), Enum.Font.LuckiestGuy)
		t.Position = UDim2.fromOffset(0, 10)
		t.Size = UDim2.new(1, 0, 0, 56)
		t.TextStrokeColor3 = color
		t.TextStrokeTransparency = 0
		local s = VFX.CL.label(box, sub or "", 17, Color3.fromRGB(240, 226, 210), Enum.Font.GothamBold)
		s.Position = UDim2.fromOffset(0, 70)
		s.Size = UDim2.new(1, 0, 0, 24)
		local sc = Instance.new("UIScale")
		sc.Scale = 1.6
		sc.Parent = box
		tween(sc, 0.2, { Scale = 1 }, Enum.EasingStyle.Back, Enum.EasingDirection.Out)
		tween(box, 0.4, { BackgroundTransparency = 1 }, nil, nil, (life or 4) - 0.4)
		tween(t, 0.4, { TextTransparency = 1, TextStrokeTransparency = 1 }, nil, nil, (life or 4) - 0.4)
		tween(s, 0.4, { TextTransparency = 1, TextStrokeTransparency = 1 }, nil, nil, (life or 4) - 0.4)
		tween(stripe, 0.4, { BackgroundTransparency = 1 }, nil, nil, (life or 4) - 0.4)
		cleanup(box, life or 4)
		return box
	end

	-- the boss bar and the damage board
	function NMV.hud()
		local gui = NMV.gui()
		if not gui then
			return nil
		end
		local h = gui:FindFirstChild("Boss")
		if h then
			return h
		end
		h = Instance.new("Frame")
		h.Name = "Boss"
		h.AnchorPoint = Vector2.new(0.5, 0)
		h.Position = UDim2.new(0.5, 0, 0, 30)
		h.Size = UDim2.fromOffset(520, 64)
		h.BackgroundTransparency = 1
		h.Parent = gui
		local name = VFX.CL.label(h, "HIGH-END NOMU", 22, Color3.new(1, 1, 1), Enum.Font.LuckiestGuy)
		name.Name = "Title"
		name.Size = UDim2.new(1, 0, 0, 24)
		name.TextXAlignment = Enum.TextXAlignment.Left
		name.TextStrokeColor3 = NMV.RED
		name.TextStrokeTransparency = 0
		local clock = VFX.CL.label(h, "", 16, Color3.fromRGB(255, 220, 160))
		clock.Name = "Clock"
		clock.Size = UDim2.new(1, 0, 0, 24)
		clock.TextXAlignment = Enum.TextXAlignment.Right
		local bar = Instance.new("Frame")
		bar.Name = "Bar"
		bar.Position = UDim2.fromOffset(0, 28)
		bar.Size = UDim2.new(1, 0, 0, 16)
		bar.BackgroundColor3 = Color3.fromRGB(24, 12, 16)
		bar.BorderSizePixel = 0
		bar.Parent = h
		local trail = Instance.new("Frame")
		trail.Name = "Trail"
		trail.Size = UDim2.fromScale(1, 1)
		trail.BackgroundColor3 = Color3.fromRGB(255, 236, 200)
		trail.BorderSizePixel = 0
		trail.Parent = bar
		local fill = Instance.new("Frame")
		fill.Name = "Fill"
		fill.Size = UDim2.fromScale(1, 1)
		fill.BackgroundColor3 = NMV.RED
		fill.BorderSizePixel = 0
		fill.Parent = bar
		local tick = Instance.new("Frame")
		tick.Position = UDim2.fromScale(0.5, 0)
		tick.Size = UDim2.new(0, 2, 1, 0)
		tick.BackgroundColor3 = Color3.new(1, 1, 1)
		tick.BorderSizePixel = 0
		tick.ZIndex = 3
		tick.Parent = bar
		local note = VFX.CL.label(h, "", 14, Color3.fromRGB(150, 255, 170), Enum.Font.GothamBold)
		note.Name = "Note"
		note.Position = UDim2.fromOffset(0, 46)
		note.Size = UDim2.new(1, 0, 0, 18)
		note.TextXAlignment = Enum.TextXAlignment.Left
		local board = VFX.CL.label(h, "", 14, Color3.new(1, 1, 1), Enum.Font.GothamBold)
		board.Name = "Board"
		board.AnchorPoint = Vector2.new(0, 0)
		board.Position = UDim2.new(1, 16, 0, 0)
		board.Size = UDim2.fromOffset(230, 100)
		board.TextXAlignment = Enum.TextXAlignment.Left
		board.TextYAlignment = Enum.TextYAlignment.Top
		return h
	end
	function NMV.hudSet(data)
		local h = NMV.hud()
		if not h then
			return
		end
		local f = math.clamp((tonumber(data.Health) or 0) / math.max(tonumber(data.Max) or 1, 1), 0, 1)
		local fill, trail = h.Bar.Fill, h.Bar.Trail
		fill.Size = UDim2.fromScale(f, 1)
		tween(trail, 0.6, { Size = UDim2.fromScale(f, 1) }, nil, nil, 0.25)
		h.Title.Text = (data.Phase == 2) and "HIGH-END NOMU  ·  ENRAGED" or "HIGH-END NOMU"
		local left = tonumber(data.Left) or 0
		h.Clock.Text = string.format("%d:%02d", left // 60, left % 60)
		h.Note.Text = data.Regen and "SUPER REGENERATION - keep hitting it!" or "Team up! Players near it can't hurt each other."
		h.Note.TextColor3 = data.Regen and Color3.fromRGB(150, 255, 170) or Color3.fromRGB(230, 220, 210)
		local lines = { "TOP DAMAGE" }
		for i = 1, 3 do
			local e = data.Top and data.Top[i]
			if e then
				table.insert(lines, string.format("%d. %s  %d", i, tostring(e.Name), tonumber(e.Damage) or 0))
			end
		end
		local me = Players.LocalPlayer
		local mine = me and data.Board and data.Board[tostring(me.UserId)]
		table.insert(lines, mine and string.format("YOU: %d (#%d of %d)", mine.Damage, mine.Rank, tonumber(data.Count) or 0) or "YOU: hit it to get on the board")
		h.Board.Text = table.concat(lines, "\n")
	end

	---------------------------------------------------------------- the server's
	-- incoming: the warning, the circle where it'll land, the fall
	function Effects.NomuIncoming(_, data)
		local pos = data.Pos
		if typeof(pos) ~= "Vector3" then
			return
		end
		local land = tonumber(data.Land) or 2.6
		local r = NMV.rec()
		NMV.drive()
		NMV.banner("HIGH-END NOMU", "incoming in the middle of the city - team up! everyone who fights it gets paid", NMV.RED, 4.5)
		VFX.PlaySound("NomuSiren", nil, 1)
		-- the red circle it's coming down on
		local g = groundPoint(pos)
		for i, rad in { 12, 22, 34 } do
			local ring = newPart(Vector3.new(0.3, rad * 2, rad * 2), CFrame.new(g + UP * (0.12 + i * 0.02)) * CFrame.Angles(0, 0, math.rad(90)), NMV.RED, Enum.Material.Neon, Enum.PartType.Cylinder)
			ring.Transparency = 0.55 + i * 0.1
			tween(ring, 0.4, { Transparency = 0.85 }, Enum.EasingStyle.Sine, Enum.EasingDirection.InOut)
			cleanup(ring, land + 0.3)
		end
		-- the fall: out of the sky, jets blazing
		r.falling = true
		local pp = NMV.build()
		r.pp = pp
		local S = NMV.S
		NMV.jets(pp, land, true)
		local t0 = os.clock()
		local top = g + UP * 300 + Vector3.new(40, 0, 40)
		local foot = g + UP * (3.1 * S)
		task.spawn(function()
			while os.clock() - t0 < land and pp.model.Parent do
				local k = (os.clock() - t0) / land
				local at = top:Lerp(foot, k * k)
				VFX.PUP.place(pp, CFrame.lookAt(at, at + Vector3.new(-1, 0, -1)), NMV.P.fall)
				task.wait()
			end
			if not pp.model.Parent then
				return
			end
			VFX.PUP.place(pp, CFrame.lookAt(foot - UP * S * 0.8, foot - UP * S * 0.8 + Vector3.new(-1, 0, -1)), NMV.P.slamLand)
			-- THE LANDING
			toonExplosion(g + UP * 2, 2.6, { NoDebris = true })
			shockDisc(g + UP * 0.4, UP, 6, 80, 0.55, Color3.fromRGB(220, 206, 190), 4)
			billboardRing(g + UP * 2, 6, 70, NMV.RED, 8, 0.5)
			dustPuffs(g, 3, 16, Color3.fromRGB(205, 196, 190), 1.8, true)
			rocks(g, 2, 18)
			groundMark(g, 16, Color3.fromRGB(40, 34, 30), 20)
			VFX.ShakeAt(g, 4, 400, 1)
			VFX.PlaySound("NomuLand", g, 1.4)
			VFX.Hooks.Flash(Color3.new(1, 1, 1), 0.2)
			task.wait(0.4)
			r.falling = false
			pp.model:Destroy()
			r.pp = nil
		end)
	end
	function Effects.NomuLanded(_, data)
		NMV.drive()
		NMV.hudSet({ Health = data.Max, Max = data.Max, Phase = 1, Left = (Config.NomuRaid or {}).TimeLimit or 240 })
	end
	function Effects.NomuState(_, data)
		NMV.drive()
		NMV.hudSet(data)
	end
	function Effects.NomuMove(body, data)
		local r = NMV.rec()
		NMV.drive()
		r.move = { Kind = data.Kind, t0 = os.clock(), Windup = data.Windup, Air = data.Air, Time = data.Time, Side = data.Side }
		local root = typeof(body) == "Instance" and body:FindFirstChild("HumanoidRootPart")
		if not root then
			return
		end
		local pos = root.Position
		if data.Kind == "Swipe" then
			VFX.PlaySound("NomuSwipe", pos, 1)
			task.delay(data.Windup or 0.45, function()
				if root.Parent then
					local d = typeof(data.Dir) == "Vector3" and data.Dir or root.CFrame.LookVector
					moonArc(CFrame.lookAt(root.Position + d * 6, root.Position + d * 12) * CFrame.Angles(0, 0, math.rad(90 * (data.Side or 1))), 9, NMV.SKIN, 170)
					streaks(root.Position + d * 5, d, 6, 1.2, 8, 14, WIND, 0.2)
					VFX.ShakeAt(root.Position, 1.2, 60, 0.25)
				end
			end)
		elseif data.Kind == "Slam" then
			VFX.PlaySound("NomuRoar", pos, 0.6)
			local to = data.To
			if typeof(to) == "Vector3" then
				-- where it'll come down: a red ring on the street
				local g = groundPoint(to)
				local ring = newPart(Vector3.new(0.3, 36, 36), CFrame.new(g + UP * 0.15) * CFrame.Angles(0, 0, math.rad(90)), NMV.RED, Enum.Material.Neon, Enum.PartType.Cylinder)
				ring.Transparency = 0.6
				tween(ring, (data.Windup or 0.35) + (data.Air or 0.85), { Size = Vector3.new(0.3, 8, 8), Transparency = 0.3 })
				cleanup(ring, (data.Windup or 0.35) + (data.Air or 0.85))
			end
		elseif data.Kind == "Charge" then
			VFX.PlaySound("NomuJet", pos, 1.2)
			if r.pp then
				NMV.jets(r.pp, (data.Windup or 0.6) + (data.Time or 0.5), true)
			end
			task.delay(data.Windup or 0.6, function()
				if root.Parent then
					local d = typeof(data.Dir) == "Vector3" and data.Dir or root.CFrame.LookVector
					streaks(root.Position, -d, 10, 2, 10, 20, WIND, 0.3)
					VFX.ShakeAt(root.Position, 1.5, 90, 0.4)
				end
			end)
		elseif data.Kind == "Roar" then
			VFX.PlaySound("NomuRoar", pos, 1.3)
			for i = 1, 3 do
				task.delay(i * 0.18, function()
					if root.Parent then
						shockDisc(root.Position + UP * 4, UP, 4, 60, 0.45, Color3.fromRGB(255, 220, 220), 0)
						billboardRing(root.Position + UP * 6, 6, 60, NMV.RED, 5, 0.4)
					end
				end)
			end
			VFX.ShakeAt(pos, 2.4, 180, 0.9)
			if data.Phase == 2 then
				NMV.banner("IT'S ENRAGED", "the Nomu's hitting harder and faster", NMV.RED, 3)
			end
		elseif data.Kind == "Escape" then
			VFX.PlaySound("NomuJet", pos, 1.4)
			if r.pp then
				NMV.jets(r.pp, 2.5, true)
			end
		end
	end
	function Effects.NomuImpact(_, data)
		local pos = data.Pos
		if typeof(pos) ~= "Vector3" then
			return
		end
		local g = groundPoint(pos)
		local radius = tonumber(data.Radius) or 18
		shockDisc(g + UP * 0.3, UP, 4, radius * 2.6, 0.4, Color3.fromRGB(220, 206, 190), 3)
		dustPuffs(g, 2.2, 12, Color3.fromRGB(205, 196, 190), 1.4, true)
		rocks(g, 1.6, 14)
		groundMark(g, radius * 0.6, Color3.fromRGB(40, 34, 30), 12)
		VFX.ShakeAt(g, 3, 220, 0.7)
		VFX.PlaySound("NomuLand", g, 1)
	end
	function Effects.NomuRaidEnd(_, data)
		local r = NMV.rec()
		local won = data.Result == "Defeated"
		if won then
			r.dying = os.clock()
			VFX.PlaySound("NomuDown", nil, 1.2)
		end
		task.delay(won and 3.8 or 2.4, function()
			NMV.stop()
		end)
		local gui = NMV.gui()
		local h = gui and gui:FindFirstChild("Boss")
		if h then
			cleanup(h, 0.2)
		end
		local lines = {}
		for i, e in data.Top or {} do
			table.insert(lines, string.format("%d. %s - %d damage%s", i, tostring(e.Name), tonumber(e.Damage) or 0, (tonumber(e.Reward) or 0) > 0 and string.format("  (+$%d)", e.Reward) or ""))
		end
		NMV.banner(won and "NOMU DEFEATED!" or "THE NOMU GOT AWAY", #lines > 0 and table.concat(lines, "   ") or "nobody laid a finger on it", won and Color3.fromRGB(255, 212, 64) or NMV.RED, 7)
	end
	function Effects.NomuReward(_, data)
		local reward = tonumber(data.Reward) or 0
		task.delay(1.2, function()
			local box = NMV.banner(reward > 0 and string.format("+$%d", reward) or "NO PAY", string.format("you did %d damage - #%d of %d", tonumber(data.Damage) or 0, tonumber(data.Rank) or 0, tonumber(data.Of) or 0),
				reward > 0 and Color3.fromRGB(96, 220, 110) or NMV.RED, 3.5)
			if box then
				box.Position = UDim2.fromScale(0.5, 0.55)
			end
		end)
	end
end


---------------------------------------------------------------------------
-- (round 85) THE GAG EMOTES: EMERGENCY EXIT, REV IT UP, SHORT CIRCUIT and
-- HOLD THIS L (each in a function of its own: this script is near Luau's
-- local limit). Built on the emote kit (VFX.EMOTES: EM.beatMotion,
-- EM.beatLoop; the Emote wrapper plays each one's song) and, for Iida's
-- two, the engine kit (VFX.EngineKit). First the bits they share, on
-- EM.gag: a word at a point, a glint, and Iida's calf engines clipped onto
-- a body that hasn't got any (anyone can own his emotes).
---------------------------------------------------------------------------
;(function()
	local EM = VFX.EMOTES
	local EK = VFX.EngineKit
	local G = {}
	EM.gag = G
	-- a word over a point (a BillboardGui), rising and fading (EM.label,
	-- anywhere: EM.label always starts 4 studs over his root); in the bag if
	-- one's given, so it goes the moment the emote breaks off
	function G.word(pos, text, color, size, life, rise, bag)
		life = life or 1
		local anchor = newPart(Vector3.one * 0.1, CFrame.new(pos), Color3.new(), nil, nil, bag)
		anchor.Transparency = 1
		local bb = Instance.new("BillboardGui")
		bb.Size = UDim2.fromOffset(300, 70)
		bb.MaxDistance = 120
		bb.LightInfluence = 0
		bb.Parent = anchor
		local t = Instance.new("TextLabel")
		t.Size = UDim2.fromScale(1, 1)
		t.BackgroundTransparency = 1
		t.Font = Enum.Font.LuckiestGuy
		t.TextSize = size or 30
		t.TextColor3 = color or Color3.new(1, 1, 1)
		t.TextStrokeTransparency = 0
		t.Text = text
		t.Parent = bb
		tween(anchor, life, { CFrame = CFrame.new(pos + UP * (rise or 1.5)) })
		tween(t, 0.3, { TextTransparency = 1, TextStrokeTransparency = 1 }, nil, nil, life - 0.3)
		cleanup(anchor, life + 0.05)
		return anchor
	end
	-- a glint: a white four-point twinkle at pos (glasses, a prop), growing
	-- in and gone in `life`
	function G.glint(pos, size, life)
		life = life or 0.3
		local anchor = newPart(Vector3.one * 0.1, CFrame.new(pos), Color3.new(1, 1, 1), nil, nil)
		anchor.Transparency = 1
		local bb = Instance.new("BillboardGui")
		bb.Name = "Glint"
		bb.Size = UDim2.fromScale(0.1, 0.1)
		bb.AlwaysOnTop = true
		bb.MaxDistance = 120
		bb.LightInfluence = 0
		bb.Parent = anchor
		for _, s in { Vector2.new(1, 0.1), Vector2.new(0.1, 1), Vector2.new(0.3, 0.3) } do
			local f = Instance.new("Frame")
			f.AnchorPoint = Vector2.new(0.5, 0.5)
			f.Position = UDim2.fromScale(0.5, 0.5)
			f.Size = UDim2.fromScale(s.X, s.Y)
			f.BackgroundColor3 = Color3.new(1, 1, 1)
			f.BorderSizePixel = 0
			f.Parent = bb
			local c = Instance.new("UICorner")
			c.CornerRadius = UDim.new(0.5, 0)
			c.Parent = f
		end
		tween(bb, life * 0.35, { Size = UDim2.fromScale(size or 2, size or 2) }, Enum.EasingStyle.Back)
		tween(bb, life * 0.6, { Size = UDim2.fromScale(0, 0) }, Enum.EasingStyle.Quad, Enum.EasingDirection.In, life * 0.4)
		cleanup(anchor, life + 0.05)
		return anchor
	end
	-- take our speech bubble down when the emote breaks off
	-- (VFX.SpeechBubble puts it in the effects folder on a timer): only the
	-- one over him with this text, so a move's shout that broke it off stays.
	-- Switched off, not destroyed: its own timer still fades and clears it.
	function G.unsay(char, text)
		local head = char and (char:FindFirstChild("Head") or char:FindFirstChild("HumanoidRootPart"))
		for _, bb in folder:GetChildren() do
			if bb.Name == "SpeechBubble" and bb:IsA("BillboardGui") and bb.Adornee == head then
				local t = bb:FindFirstChildWhichIsA("TextLabel")
				if t and t.Text == text then
					bb.Enabled = false
				end
			end
		end
	end
	-- a props function that can't leave its bag behind: fn(char, token,
	-- root, bag) runs in a pcall, the bag goes whatever happens, and an
	-- error still reaches the Emote wrapper's warn
	function G.guard(fn)
		return function(char, token, root)
			local bag = EM.bag()
			local ok, err = pcall(fn, char, token, root, bag)
			bag:Destroy()
			if not ok then
				error(err, 0)
			end
		end
	end
	-- Iida's calf engines (the server's look, pared down: a silver housing,
	-- its plate, six gunmetal stubs and the gold block) welded onto the
	-- calves of a body that hasn't got real ones, in the bag (gone with the
	-- emote). Nothing on Iida himself.
	function G.engines(bag, char)
		local L = (Config.Quirks.Engine or {}).Look
		if not L or char:GetAttribute("Quirk") == "Engine" or char:FindFirstChild("Pipe", true) then
			return
		end
		for _, leg in EK.legs(char) do
			local s, side = leg.leg.Size, leg.sign
			local ky = leg.isR15 and s.Y * 0.55 or s.Y / 2
			local function at(x, y, z)
				return EK.legPoint(leg.leg, leg.isR15, x, y, z)
			end
			local function piece(size, cf, color, shape)
				local p = EM.part(bag, size, leg.leg.CFrame * cf, color, Enum.Material.Metal, shape)
				EK.weld(p, leg.leg, cf)
				return p
			end
			local H = L.Housing
			local back = H.Depth / 2 + 0.47
			piece(Vector3.new(H.Width * s.X, H.Height * ky, H.Depth * s.Z), CFrame.new(at(0, H.Y, back)), L.Metal)
			piece(Vector3.new(L.Plate.Width * s.X, L.Plate.Height * ky, 0.05), CFrame.new(at(0, H.Y, back + H.Depth / 2 + 0.02)), L.PlateColor)
			local sp, dr = math.rad(L.Splay or 0), math.rad(L.Droop or 0)
			local axis = Vector3.new(math.sin(sp) * side * math.cos(dr), -math.sin(dr), math.cos(sp) * math.cos(dr))
			local w = math.min(s.X, s.Z)
			for _, y in L.Rows do
				for col = 1, 2 do
					local len = L.StubLength * w
					local p = at((col == 1 and 1 or -1) * side * L.Column, y, L.StubBase) + axis * (len / 2)
					piece(Vector3.new(len, L.StubWidth * w, L.StubWidth * w), CFrame.lookAt(p, p + axis) * CFrame.Angles(0, math.pi / 2, 0), L.StubColor, Enum.PartType.Cylinder)
				end
			end
			local B = L.Block
			piece(Vector3.new(B.Depth, B.Height * ky, B.Width * s.Z), CFrame.new(at(side * (0.5 + B.Depth / 2 / s.X + 0.02), B.Y, B.Z)), L.Gold)
		end
	end
end)()

---------------------------------------------------------------------------
-- (round 85) EMERGENCY EXIT (Iida, Epic) to APM's "Pixieland Rag" (97 bpm,
-- from 20.13 s): his season-1 gag. The alarm's going off under a big exit
-- sign: "EVERYONE, STAY CALM!!" with his robot chop (1-2), a crouch (3),
-- the calf engines fire him up in a somersault (4) and he SLAPS flat onto
-- the sign in its running man, side on (5), running on the spot on it, a
-- stride on every beat, the arrow under him chasing (6-8); he peels off and
-- slides down it (9), lands in a heap and pops up into the class rep's
-- salute (10). The sign (lit green the moment he hits it, a door outline,
-- chevrons, EXIT, two red alarm lamps) sits on the far side of him from
-- each viewer's own camera - side on he's always in front of it - so it's
-- each client's own, like every emote prop.
---------------------------------------------------------------------------
;(function()
	local EM = VFX.EMOTES
	local EK = VFX.EngineKit
	local G = EM.gag
	local entry = EM.entry("EmergencyExit") or { Id = "EmergencyExit", Bpm = 97 }
	local B = 60 / (entry.Bpm or 97)
	local BACK, LIN, SINE = Enum.EasingStyle.Back, Enum.EasingStyle.Linear, Enum.EasingStyle.Sine
	local steps = {}
	local function add(pose, beats, style, t)
		table.insert(steps, { pose = pose, beats = beats, style = style, t = t })
	end
	-- 1-2: "EVERYONE, STAY CALM!!" - the class rep's robot chop: one arm up,
	-- one down, swapped on every half beat, his head snapping round (each
	-- arm angled out a little, so the chop reads from behind him too)
	for k = 1, 4 do
		local s = k % 2 == 1 and 1 or -1
		add({
			RightArm = s > 0 and { 150, 0, -25 } or { 40, 0, 30 }, LeftArm = s > 0 and { 40, 0, 30 } or { 150, 0, -25 },
			Waist = { 3, 0, 0 }, Neck = { 4, 18 * s, 0 },
		}, 0.5, nil, 0.06)
	end
	-- 3: turned side on to the sign (Hips yaw 90: his front is the door's
	-- way) and coiled to jump, leaning in, arms back, looking up at it. (On
	-- R6 a Hips roll leans the whole body - legs and all - in the way he
	-- faces once he's turned; a Waist pitch would tip him into the sign.)
	add({ Crouch = 0.75, Hips = { 0, 90, 16, 0, 0.15, 0 }, RightLeg = { 67, 0, 0 }, LeftLeg = { 67, 0, 0 }, RightArm = { -60, 0, 16 }, LeftArm = { -60, 0, 16 }, Neck = { 36, 0, 0 } }, 1)
	-- 4: the engines fire him up in a forward somersault in the sign's
	-- plane (in profile from every side), flailing: a quarter turn of Hips
	-- roll every quarter beat (Linear, each turn the whole step)
	local RISE = { 1.1, 2.1, 3, 3.55 }
	for q = 1, 4 do
		local odd = q % 2 == 1
		add({
			Hips = { 0, 90, 90 * q, 0, RISE[q], 0 },
			RightArm = odd and { 170, 0, 40 } or { 110, 0, 80 }, LeftArm = odd and { 120, 0, 75 } or { 175, 0, 30 },
			RightLeg = odd and { 30, 0, 18 } or { -15, 0, 10 }, LeftLeg = odd and { -20, 0, 12 } or { 35, 0, 20 },
			Neck = { -20, 0, 0 },
		}, 0.25, LIN, B * 0.25)
	end
	-- 5-8: SLAP - flat on the sign, side on, running for its door in the
	-- pictogram's stride, leaning into it (Hips roll); then running on the
	-- spot on it, the stride swapped on every beat (R6: the arms' roll 0, so
	-- they lie flat on it)
	local function runner(s)
		return {
			Hips = { 0, 90, 20, 0, 3.55, 0 }, Neck = { 8, 0, 0 },
			RightArm = s > 0 and { 68, 0, 0 } or { -55, 0, 0 }, LeftArm = s > 0 and { -55, 0, 0 } or { 68, 0, 0 },
			RightLeg = s > 0 and { 55, 0, 0 } or { -50, 0, 0 }, LeftLeg = s > 0 and { -50, 0, 0 } or { 55, 0, 0 },
		}
	end
	add(runner(1), 1, nil, 0.05)
	add(runner(-1), 1, nil, 0.1)
	add(runner(1), 1, nil, 0.1)
	add(runner(-1), 1, nil, 0.1)
	-- 9: peeled off - sagging, then sliding down the sign, arms up
	add({ Hips = { 0, 90, 6, 0, 3.2, 0 }, RightArm = { 160, 0, 0 }, LeftArm = { 150, 0, 0 }, RightLeg = { 20, 0, 0 }, LeftLeg = { -12, 0, 0 }, Neck = { -10, 0, 0 } }, 0.25, SINE, B * 0.25)
	add({ Hips = { 0, 90, 6, 0, 0.5, 0 }, RightArm = { 165, 0, 0 }, LeftArm = { 155, 0, 0 }, RightLeg = { 24, 0, 0 }, LeftLeg = { -16, 0, 0 }, Neck = { -12, 0, 0 } }, 0.75, LIN, B * 0.75)
	-- 10: in a heap on the street... and straight up into the salute
	add({ Crouch = 0.65, Hips = { 0, 30, 0, 0, 0.21, 0 }, Waist = { -22, 0, 0 }, RightArm = { 40, 0, 60 }, LeftArm = { 30, 0, 70 }, Neck = { -12, 0, 0 } }, 0.5, nil, 0.06)
	add({ RightArm = { 135, 0, -28 }, LeftArm = { 0, 0, 4 }, Waist = { 6, 0, 0 }, Neck = { 8, 0, 0 } }, 0.5, BACK, 0.14)
	MOTIONS.EmoteEmergencyExit = EM.beatMotion(entry, steps, { recover = 0.4 }) -- 2 + 1 + 1 + 4 + 1 + 1 = 10 beats

	-- the sign: W x H studs, its middle MID over his root and D behind his
	-- middle (his far arm's outside is 2 studs out); every piece { part,
	-- offset on the sign, its colour lit }
	local W, H, MID, D = 9.4, 7.4, 2.35, 2.2
	local GREEN, DARK = Color3.fromRGB(18, 182, 80), Color3.fromRGB(16, 70, 42)
	local WHITE, DIM = Color3.new(1, 1, 1), Color3.fromRGB(150, 160, 156)
	local RED, RED_OFF = Color3.fromRGB(255, 40, 30), Color3.fromRGB(90, 20, 18)
	EM.props.EmergencyExit = G.guard(function(char, token, root, bag)
		G.engines(bag, char)
		local cam = workspace.CurrentCamera
		local pieces, chevrons, lamps, words = {}, {}, {}, {}
		local function piece(size, offset, color, lit, shape)
			local p = EM.part(bag, size, root.CFrame, color, Enum.Material.SmoothPlastic, shape)
			local rec = { part = p, offset = offset, lit = lit }
			table.insert(pieces, rec)
			return p, rec
		end
		local board = piece(Vector3.new(W, H, 0.24), CFrame.new(), DARK, GREEN)
		-- a white border (0.3 thick: it shows on both faces)
		for _, e in { { W, 0.24, 0, H / 2 - 0.12 }, { W, 0.24, 0, -H / 2 + 0.12 }, { 0.24, H, W / 2 - 0.12, 0 }, { 0.24, H, -W / 2 + 0.12, 0 } } do
			piece(Vector3.new(e[1], e[2], 0.3), CFrame.new(e[3], e[4], 0), DIM, WHITE)
		end
		-- the door he's running for (at his front: his root's -X)
		local dl, dr, dt, db = -W / 2 + 0.55, -W / 2 + 1.95, 1.5, -H / 2 + 0.24
		piece(Vector3.new(0.26, dt - db, 0.3), CFrame.new(dl, (dt + db) / 2, 0), DIM, WHITE)
		piece(Vector3.new(0.26, dt - db, 0.3), CFrame.new(dr, (dt + db) / 2, 0), DIM, WHITE)
		piece(Vector3.new(dr - dl + 0.26, 0.26, 0.3), CFrame.new((dl + dr) / 2, dt, 0), DIM, WHITE)
		-- three chevrons pointing at it along the bottom (lit in turn)
		for i = 1, 3 do
			local x = 1.9 - (i - 1) * 1.15
			local set = {}
			for _, sgn in { 1, -1 } do
				local _, rec = piece(Vector3.new(0.95, 0.28, 0.3), CFrame.new(x, -H / 2 + 0.75 + sgn * 0.27, 0) * CFrame.Angles(0, 0, math.rad(sgn * 40)), DIM, WHITE)
				table.insert(set, rec)
			end
			chevrons[i] = set
		end
		-- EXIT across the top, on both faces
		for _, faceName in { "Front", "Back" } do
			local sg = Instance.new("SurfaceGui")
			sg.Name = "ExitText"
			sg.Face = Enum.NormalId[faceName]
			sg.LightInfluence = 0
			sg.SizingMode = Enum.SurfaceGuiSizingMode.PixelsPerStud
			sg.PixelsPerStud = 40
			sg.Parent = board
			local t = Instance.new("TextLabel")
			t.BackgroundTransparency = 1
			t.AnchorPoint = Vector2.new(0.5, 0)
			t.Position = UDim2.fromScale(0.5, 0.035)
			t.Size = UDim2.fromScale(0.8, 0.13)
			t.Font = Enum.Font.GothamBlack
			t.TextScaled = true
			t.TextColor3 = WHITE
			t.Text = "非常口  EXIT"
			t.Parent = sg
			table.insert(words, t)
		end
		-- two red alarm lamps on top
		for _, x in { -W / 2 + 0.7, W / 2 - 0.7 } do
			piece(Vector3.new(0.9, 0.25, 0.5), CFrame.new(x, H / 2 + 0.12, 0), Color3.fromRGB(70, 72, 78), Color3.fromRGB(70, 72, 78))
			local lamp = piece(Vector3.new(0.7, 0.7, 0.7), CFrame.new(x, H / 2 + 0.5, 0), RED_OFF, RED_OFF, Enum.PartType.Ball)
			table.insert(lamps, lamp)
		end
		local glow = Instance.new("PointLight")
		glow.Color = GREEN
		glow.Range = 16
		glow.Brightness = 0
		glow.Parent = board
		local alarm = Instance.new("PointLight")
		alarm.Color = RED
		alarm.Range = 14
		alarm.Brightness = 0
		alarm.Parent = lamps[1]

		local side, lit, slapAt, faded, stopJets = 1, false, nil, false, nil
		local function sign(t)
			-- the far side of him from this client's camera (it flips only
			-- with the camera square to his side, where the sign's edge on)
			local rel = cam and root.CFrame:PointToObjectSpace(cam.CFrame.Position) or Vector3.new(0, 0, 1)
			if rel.Z > 0.25 then
				side = 1
			elseif rel.Z < -0.25 then
				side = -1
			end
			local shove, k = 0, t - (slapAt or math.huge)
			if k >= 0 and k < 0.45 then -- (knocked back by him, springing back)
				shove = math.cos(k * 38) * (1 - k / 0.45) * 0.3
			end
