		end
		-- lit: the board bright green, the border, door and chevrons white
		local function light(on)
			lit = on
			board.Color, board.Material = on and GREEN or DARK, on and Enum.Material.Neon or Enum.Material.SmoothPlastic
			for _, rec in pieces do
				if rec.lit == WHITE then
					rec.part.Color, rec.part.Material = on and WHITE or DIM, on and Enum.Material.Neon or Enum.Material.SmoothPlastic
