				-- jets straight down on the beat he goes
				stopJets = EK.ignite(char, { len = 4.5, snap = B * 0.85, dur = B * 1.4, dir = Vector3.new(0, -1, 0) })
			elseif b == 3 then
				VFX.PlaySound("Leap", root.Position, 0.9)
				shockDisc(g + UP * 0.2, UP, 2, 9, 0.35, Color3.fromRGB(205, 220, 255))
				dustPuffs(g, 0.4, 6, Color3.fromRGB(196, 188, 176), 0.6)
			elseif b == 4 then
