				shockDisc(cf.Position + toward * 0.3, toward, 2, 11, 0.35, WHITE)
				dustPuffs(mid - toward * 1.2, 0.4, 9, Color3.fromRGB(226, 236, 230), 0.6)
				if char == Players.LocalPlayer.Character then
					VFX.Shake(1.4, 0.25)
				end
			elseif b == 5 then
				G.word(sign(0).Position + UP * (H / 2 + 1.2), "EMERGENCY EXIT!!", GREEN, 34, B * 3, 1.2, bag)
			elseif b == 8 then
				VFX.PlaySound("Skid", root.Position + UP * 3, 1)
			elseif b == 9 then
				VFX.PlaySound("PkRoll", root.Position, 1)
				dustPuffs(g, 0.35, 6, Color3.fromRGB(196, 188, 176), 0.5)
				-- the sign goes out
				faded = true
				for _, rec in pieces do
					tween(rec.part, B * 0.6, { Transparency = 1 })
				end
				for _, w in words do
					tween(w, B * 0.4, { TextTransparency = 1 })
				end
				glow.Brightness = 0
				task.delay(B * 0.5, function()
					local head = char:FindFirstChild("Head")
					if head and EM.alive(char, token, root) then
						G.glint((head.CFrame * CFrame.new(0.3, 0.15, -0.62)).Position, 2.2, 0.35)
						VFX.PlaySound("Bell", head.Position, 0.8)
					end
				end)
			end
		end, function(t, b)
			local cf = sign(t)
			for _, rec in pieces do
				rec.part.CFrame = cf * rec.offset
			end
			-- the alarm: the lamps flash and the bell rings on every half beat
			-- till he hits it
			local h = math.floor(t / (B / 2))
			if h ~= half then
				half = h
				if b < 4 then
					local on = h % 2 == 0
					lamps[1].Color, lamps[2].Color = on and RED or RED_OFF, on and RED_OFF or RED
					lamps[1].Material, lamps[2].Material = on and Enum.Material.Neon or Enum.Material.SmoothPlastic, on and Enum.Material.SmoothPlastic or Enum.Material.Neon
					alarm.Brightness = on and 3 or 0.6
					VFX.PlaySound("Bell", cf.Position, 0.7)
				elseif lamps[1].Color ~= RED_OFF then
					for _, lamp in lamps do
						lamp.Color, lamp.Material = RED_OFF, Enum.Material.SmoothPlastic
					end
					alarm.Brightness = 0
				end
				-- on the sign: the chevrons chasing toward the door
				if lit and not faded then
					for i, set in chevrons do
						for _, rec in set do
							rec.part.Transparency = (h % 3 == i - 1) and 0 or 0.65
						end
					end
				end
			end
			-- sliding down it, the sign flickers
			if b == 8 and lit and not faded then
				board.Material = (math.floor(t * 18) % 4 == 0) and Enum.Material.SmoothPlastic or Enum.Material.Neon
			end
		end)
		if stopJets then
			stopJets(ran and 0.2 or 0.05)
		end
	end)
end)()

---------------------------------------------------------------------------
-- (round 85) REV IT UP (Iida, Rare): a quick taunt, no song - the engines
-- are the music. Down into a sprinter's set; a rev (a pop out of his calf
-- pipes), a bigger one (a gear clunk, the street kicked up behind him),
-- then the third catches: fire, the switch to long cyan jets, "VRRRM!",
-- the body shaking with it; and he straightens up into a smug chop at you,
-- a backfire and a smoke ring left behind him, the pipes glowing red-hot,
-- a glint off his glasses. 1.96 s.
---------------------------------------------------------------------------
;(function()
	local EM = VFX.EMOTES
	local EK = VFX.EngineKit
	local G = EM.gag
	local BACK = Enum.EasingStyle.Back
	local TICK = 0.05 -- (the props' clock: EM.beatLoop counting 50 ms "beats")
	local clock = { Id = "RevItUp", Bpm = 60 / TICK }
	-- the set is turned 25 degrees (Hips yaw) so the back leg's jets clear
	-- his body, from in front of him and from behind; he squares up to you
	-- for the chop
	local SET = { Hips = { 0, 25, 0, 0, 0.12, 0 }, Waist = { -32, 0, 0 }, RightLeg = { -48, 0, 3 }, LeftLeg = { 42, 0, 3 }, RightArm = { -42, 0, 12 }, LeftArm = { 62, 0, 6 }, Neck = { 40, 0, 0 } }
	local REV1 = { Hips = { 0, 25, 0, 0, 0.13, 0 }, Waist = { -40, 0, 0 }, RightLeg = { -50, 0, 3 }, LeftLeg = { 44, 0, 3 }, RightArm = { -58, 0, 12 }, LeftArm = { 74, 0, 6 }, Neck = { 48, 0, 0 } }
	local REV2 = { Hips = { 0, 25, 0, 0, 0.14, 0 }, Waist = { -42, 0, 0 }, RightLeg = { -52, 0, 3 }, LeftLeg = { 46, 0, 3 }, RightArm = { -62, 0, 12 }, LeftArm = { 78, 0, 6 }, Neck = { 50, 0, 0 } }
	local STRAIN = {
		{ Hips = { 0, 25, 0, 0, 0.18, 0.15 }, Waist = { -38, 0, 2 }, RightLeg = { -52, 0, 4 }, LeftLeg = { 44, 0, 4 }, RightArm = { -66, 0, 22 }, LeftArm = { 84, 0, 4 }, Neck = { 50, 0, 3 } },
		{ Hips = { 0, 25, 0, 0, 0.12, 0.12 }, Waist = { -36, 0, -2 }, RightLeg = { -52, 0, 4 }, LeftLeg = { 44, 0, 4 }, RightArm = { -62, 0, 18 }, LeftArm = { 80, 0, 8 }, Neck = { 47, 0, -3 } },
	}
	-- the chop: stood up, the hand raised... and chopped down at you, a flat
	-- blade, chest turned into it, the other hand on his hip, chin up (the
	-- arm angled out from his shoulder, so the chop reads from in front of
	-- him and from behind, not just side on)
	local RAISE = { Waist = { 6, 14, 0 }, RightArm = { 160, 0, -30 }, LeftArm = { -14, 0, 24 }, Neck = { 12, -8, 0 }, RightLeg = { -8, 0, 3 }, LeftLeg = { 10, 0, 3 } }
	local CHOP = { Waist = { 2, 12, 0 }, RightArm = { 45, 0, 72 }, LeftArm = { -14, 0, 24 }, Neck = { 10, -16, 0 }, RightLeg = { -8, 0, 3 }, LeftLeg = { 10, 0, 3 } }
	local m = { recover = 0.35, beatClock = true }
	local function step(pose, t, hold, style)
		table.insert(m, { pose = pose, t = t, hold = hold, style = style })
	end
	step(SET, 0.16, 0.14) -- 0-0.3: down into the set
	step(REV1, 0.05, 0.12) -- 0.3: rev 1 (a jolt)
	step(SET, 0.1, 0.08)
	step(REV2, 0.05, 0.12) -- 0.65: rev 2 (a deeper one)
	step(SET, 0.1, 0.08)
	for k = 1, 5 do -- 1.0-1.35: rev 3 catches - shaking with it
		step(STRAIN[k % 2 + 1], 0.03, 0.04)
	end
	step(RAISE, 0.08, 0.07) -- 1.35: up straight, the hand raised...
	step(CHOP, 0.06, 0.4, BACK) -- 1.5-1.96: ...and chopped down at you (held)
	MOTIONS.EmoteRevItUp = m

	local VRRRM = Color3.fromRGB(120, 196, 255)
	EM.props.RevItUp = G.guard(function(char, token, root, bag)
		G.engines(bag, char)
		local stops = {}
		-- (the jets go where his pipes point: up and back off the back leg,
		-- licking along the street under the front one)
		local ran = EM.beatLoop(char, token, root, clock, 40, function(b)
			local g = groundPoint(root.Position)
			if b == 0 then
				dustPuffs(g, 0.3, 4, Color3.fromRGB(196, 188, 176), 0.5)
			elseif b == 6 then -- rev 1: a pop
				table.insert(stops, (EK.jets(char, "ignite", 0.2, { len = 1.8, intensity = 0.8 })))
				EK.backfire(char, nil, { scale = 0.7 })
			elseif b == 13 then -- rev 2: a gear clunk, a bigger pop, the street kicked up
				table.insert(stops, (EK.jets(char, "ignite", 0.24, { len = 2.8, intensity = 0.9 })))
				EK.backfire(char, nil, { scale = 1 })
				VFX.PlaySound("EngineGear", root.Position, 0.9)
				dustPuffs(g + root.CFrame.LookVector * -2.2, 0.25, 4, Color3.fromRGB(196, 188, 176), 0.5)
			elseif b == 20 then -- rev 3: it catches
				table.insert(stops, (EK.ignite(char, { len = 6, snap = 0.1, dur = 0.4 })))
				G.word(root.Position + UP * 3.4, "VRRRM!", VRRRM, 36, 0.9, 1.4, bag)
				EK.dustWall(g - root.CFrame.LookVector * 0.8, g - root.CFrame.LookVector * 7, { height = 0.7, time = 0.3, cloud = false })
				if char == Players.LocalPlayer.Character then
					VFX.Shake(0.8, 0.35)
				end
			elseif b == 27 then -- he cuts it: a last backfire and a smoke ring, the pipes red-hot
				for _, s in stops do
					s(0.12)
				end
				EK.backfire(char, nil, { scale = 1.35 })
				table.insert(stops, (EK.hotPipes(char, 1.1)))
			elseif b == 30 then -- the chop lands: a glint off his glasses
				VFX.PlaySound("Swing", root.Position, 0.8)
				local head = char:FindFirstChild("Head")
				if head then
					G.glint((head.CFrame * CFrame.new(0.3, 0.15, -0.62)).Position, 2.4, 0.4)
					VFX.PlaySound("Bell", head.Position, 0.8)
				end
			end
		end)
		for _, s in stops do
			s(ran and 0.25 or 0.05)
		end
	end)
end)()

---------------------------------------------------------------------------
-- (round 85) SHORT CIRCUIT (Kaminari, Rare) to APM's "Circus Parade (A)"
-- (126 bpm, from the top): a bolt out of the sky into him and he's zapped
-- stiff, every limb flung out, shaking on every quarter beat, flashing
-- yellow, arcs all over him (1-2); it fizzles out - slumped, a puff of black
-- smoke off his head (3) - and the famous brain-fried state: "WHEEEY~",
-- both thumbs up, derp eyes, lolling side to side on the beat under his
-- own little storm cloud with a lightning bolt hanging off it (4-6); thumbs
-- pumped and the dumbest grin to finish (7).
---------------------------------------------------------------------------
;(function()
	local EM = VFX.EMOTES
	local DK = VFX.DK
	local G = EM.gag
	local entry = EM.entry("ShortCircuit") or { Id = "ShortCircuit", Bpm = 126 }
	local B = 60 / (entry.Bpm or 126)
	local BACK, SINE = Enum.EasingStyle.Back, Enum.EasingStyle.Sine
	local steps = {}
	local function add(pose, beats, style, t)
		table.insert(steps, { pose = pose, beats = beats, style = style, t = t })
	end
	-- 1-2: zapped stiff, shaking on every quarter beat
	local ZAP = {
		{ Hips = { 0, 0, 0, 0, 0.2, 0 }, RightArm = { 10, 0, 118 }, LeftArm = { 20, 0, 100 }, RightLeg = { 0, 0, 20 }, LeftLeg = { 0, 0, 16 }, Waist = { 8, 0, 5 }, Neck = { 22, 0, 10 } },
		{ Hips = { 0, 0, 0, 0, 0.18, 0 }, RightArm = { 25, 0, 98 }, LeftArm = { 8, 0, 124 }, RightLeg = { 0, 0, 14 }, LeftLeg = { 0, 0, 22 }, Waist = { 10, 0, -5 }, Neck = { 18, 0, -10 } },
	}
	for k = 1, 8 do
		add(ZAP[k % 2 + 1], 0.25, nil, 0.035)
	end
	-- 3: fizzled out: slumped, arms dangling, head lolled over
	add({ Crouch = 0.35, Hips = { 0, 0, 0, 0, 0.13, 0 }, Waist = { -16, 0, 6 }, RightArm = { 6, 0, 6 }, LeftArm = { 4, 0, 10 }, Neck = { -24, 0, 16 } }, 1, SINE, 0.22)
	-- 4-6: WHEEEY~ - both thumbs up, lolling from side to side on the beat
	-- (big enough to read from across the street)
	for k = 1, 3 do
		local s = k % 2 == 1 and 1 or -1
		add({
			RightArm = { 80, -6, 0 }, LeftArm = { 80, 6, 0 }, Waist = { -4, 0, 15 * s }, Hips = { 0, 0, 8 * s, 0.22 * s, 0.39, 0 },
			RightLeg = { 0, 0, s > 0 and -6 or 18 }, LeftLeg = { 0, 0, s > 0 and 18 or -6 }, Neck = { -8, 0, 30 * s },
		}, 1, SINE, B * 0.8)
	end
	-- 7: thumbs pumped high, chin up, head tipped: the dumbest grin
	add({ Hips = { 0, 0, 0, 0, 0.23, 0 }, RightArm = { 125, -10, 0 }, LeftArm = { 125, 10, 0 }, Waist = { 8, 0, 10 }, RightLeg = { 0, 0, 10 }, LeftLeg = { 0, 0, 10 }, Neck = { 14, 0, 24 } }, 1, BACK, 0.14)
	MOTIONS.EmoteShortCircuit = EM.beatMotion(entry, steps, { recover = 0.4 }) -- 2 + 1 + 3 + 1 = 7 beats

	local YELLOW, WHITE = DK and DK.YELLOW or Color3.fromRGB(255, 232, 80), Color3.new(1, 1, 1)
	local CLOUD = Color3.fromRGB(62, 62, 70)
	-- where the pupils wander, a pair a beat (each eye its own way)
	local LOOKS = {
		{ Vector2.new(0.3, 0.3), Vector2.new(0.68, 0.72) }, { Vector2.new(0.7, 0.34), Vector2.new(0.3, 0.68) },
		{ Vector2.new(0.34, 0.7), Vector2.new(0.7, 0.3) }, { Vector2.new(0.68, 0.68), Vector2.new(0.32, 0.34) },
	}
	-- his own face hidden under the derp sticker (or it shows between the
	-- derp eyes) and put back when the sticker goes: counted on the decal, so
	-- two runs at once put back what was there
	local function hideFace(head, on)
		local face = head and head:FindFirstChild("face")
		if not (face and face:IsA("Decal")) then
			return
		end
		local n = face:GetAttribute("DerpHidden") or 0
		if on then
			if n == 0 then
				face:SetAttribute("DerpWas", face.Transparency)
				face.Transparency = 1
			end
			face:SetAttribute("DerpHidden", n + 1)
		elseif n > 0 then
			face:SetAttribute("DerpHidden", n - 1)
			if n == 1 then
				face.Transparency = face:GetAttribute("DerpWas") or 0
				face:SetAttribute("DerpWas", nil)
			end
		end
	end
	-- the derp face: a sticker on the front of his head (a SurfaceGui: only
	-- from the front), two big eyes with their pupils off in different
	-- directions and a wide open grin; returns the part and the two pupils
	local function derpFace(bag, head)
		local p = EM.part(bag, Vector3.new(1.15, 0.85, 0.05), head.CFrame, WHITE, nil, nil)
		p.Transparency = 1
		VFX.EngineKit.weld(p, head, CFrame.new(0, 0.05, -0.64))
		local sg = Instance.new("SurfaceGui")
		sg.Name = "DerpFace"
		sg.Face = Enum.NormalId.Front
		sg.LightInfluence = 0
		sg.CanvasSize = Vector2.new(230, 170)
		sg.Parent = p
		local function disc(parent, size, pos, color, stroke)
			local f = Instance.new("Frame")
			f.AnchorPoint = Vector2.new(0.5, 0.5)
			f.Size = size
			f.Position = pos
			f.BackgroundColor3 = color
			f.BorderSizePixel = 0
			f.Parent = parent
			local c = Instance.new("UICorner")
			c.CornerRadius = UDim.new(0.5, 0)
			c.Parent = f
			if stroke then
				local s = Instance.new("UIStroke")
				s.Thickness = stroke
				s.Parent = f
			end
			return f
		end
		local pupils = {}
		for i, x in { 0.3, 0.7 } do
			local e = disc(sg, UDim2.fromOffset(i == 1 and 92 or 78, i == 1 and 92 or 78), UDim2.fromScale(x, 0.32), WHITE, 5)
			local at = LOOKS[1][i]
			pupils[i] = disc(e, UDim2.fromScale(0.3, 0.3), UDim2.fromScale(at.X, at.Y), Color3.new(0, 0, 0))
		end
		local mouth = disc(sg, UDim2.fromOffset(136, 50), UDim2.fromScale(0.5, 0.8), Color3.fromRGB(90, 14, 20), 4)
		disc(mouth, UDim2.fromScale(0.42, 0.5), UDim2.fromScale(0.62, 0.72), Color3.fromRGB(255, 120, 140))
		return p, pupils
	end
	-- a 👍 riding just past a hand (past the end of whatever arm or hand
	-- part it's given)
	local function thumb(bag, arm)
		local p = EM.part(bag, Vector3.one * 0.2, arm.CFrame, WHITE, nil, nil)
		p.Transparency = 1
		VFX.EngineKit.weld(p, arm, CFrame.new(0, -(arm.Size.Y / 2 + 0.35), -0.1))
		local bb = Instance.new("BillboardGui")
		bb.Name = "Thumb"
		bb.Size = UDim2.fromScale(1.7, 1.7)
		bb.LightInfluence = 0
		bb.MaxDistance = 120
		bb.Parent = p
		local t = Instance.new("TextLabel")
		t.BackgroundTransparency = 1
		t.Size = UDim2.fromScale(1, 1)
		t.TextScaled = true
		t.Text = "👍"
		t.Parent = bb
		return p
	end
	-- the arcs over him and the light's flicker tick at 30 a second (15 on a
	-- low-end machine), whatever the frame rate
	local ARC_TICK = 1 / 30
	EM.props.ShortCircuit = G.guard(function(char, token, root, bag)
		local head = char:FindFirstChild("Head")
		local function headPos()
			return head and head.Position or root.Position + UP * 1.5
		end
		-- the flash: a yellow fill on him, flipped on and off while it's in him
		local flash = Instance.new("Highlight")
		flash.Name = "Zapped"
		flash.FillColor = YELLOW
		flash.OutlineColor = WHITE
		flash.FillTransparency, flash.OutlineTransparency = 1, 1
		flash.DepthMode = Enum.HighlightDepthMode.Occluded
		flash.Adornee = char
		flash.Parent = bag
		local lamp = EM.part(bag, Vector3.one * 0.2, root.CFrame, WHITE, nil, nil)
		lamp.Transparency = 1
		local light = Instance.new("PointLight")
		light.Color = YELLOW
		light.Range = 12
		light.Brightness = 0
		light.Parent = lamp
		local storm, lastWisp, lastArc, pupils, hid = nil, 0, -1, nil, false
		local tick = (VFX.EngineKit and VFX.EngineKit.lowEnd() and 2 or 1) * ARC_TICK
		local limbs = {}
		for _, n in { "Head", "Torso", "Right Arm", "Left Arm", "Right Leg", "Left Leg", "UpperTorso", "RightHand", "LeftHand" } do
			local p = char:FindFirstChild(n)
			if p and p:IsA("BasePart") then
				table.insert(limbs, p)
			end
		end
		local function onBody()
			local p = limbs[rng:NextInteger(1, math.max(#limbs, 1))]
			return p and p.CFrame * Vector3.new(rand(-0.5, 0.5), rand(-0.9, 0.9), rand(-0.5, 0.5)) or root.Position
		end
		local ran = EM.beatLoop(char, token, root, entry, 7, function(b)
			if b == 0 then
				-- a bolt out of the sky, straight into him (a thunderclap you
				-- hear down the street, not across the map: EmoteThunder)
				if DK then
					DK.zig(root.Position + Vector3.new(rand(-2, 2), 24, rand(-2, 2)), headPos() + UP * 0.6, YELLOW, 0.45, 0.34, 1)
					DK.zap(headPos(), 1.3, YELLOW)
				end
				VFX.PlaySound("EmoteThunder", root.Position, 1)
				VFX.PlaySound("ElectricZap", root.Position, 1.1)
			elseif b == 1 then
				if DK then
					DK.zap(root.Position + UP * 0.5, 1, YELLOW)
				end
				VFX.PlaySound("ElectricZap", root.Position, 0.9)
			elseif b == 2 then
				-- fizzled: a puff of black smoke off his head, a pop
				flash.FillTransparency, flash.OutlineTransparency = 1, 1
				light.Brightness = 0
				smokeBurst(headPos() + UP * 0.7, Color3.fromRGB(38, 38, 42), 1.4, 0.8, 1.1, 14)
				sparks(headPos() + UP * 0.5, 0.5, WHITE, YELLOW, 10)
				VFX.PlaySound("HairPoof", headPos(), 0.9)
				VFX.PlaySound("StaticCrackle", headPos(), 0.8)
				-- his own little storm cloud with a bolt hanging off it
				storm = {}
				for _, c in { { 0, 0, 0, 1.1 }, { -0.55, -0.1, 0.1, 0.8 }, { 0.6, -0.08, -0.1, 0.85 }, { 0.15, 0.3, 0.05, 0.75 } } do
					local puff = EM.part(bag, Vector3.one * c[4], root.CFrame, CLOUD, Enum.Material.SmoothPlastic, Enum.PartType.Ball)
					table.insert(storm, { part = puff, offset = CFrame.new(c[1], c[2], c[3]) })
				end
				for _, z in { { 0.12, -0.55, 0, -22 }, { -0.12, -0.95, 0, 28 }, { 0.1, -1.35, 0, -22 } } do
					local seg = EM.part(bag, Vector3.new(0.18, 0.55, 0.12), root.CFrame, YELLOW, Enum.Material.Neon)
					table.insert(storm, { part = seg, offset = CFrame.new(z[1], z[2], z[3]) * CFrame.Angles(0, 0, math.rad(z[4])), bolt = true })
				end
			elseif b == 3 then
				VFX.SpeechBubble(char, "WHEEEY~", 1.8)
				VFX.PlaySound("Wheey", root.Position, 1)
				if head then
					pupils = select(2, derpFace(bag, head))
					hideFace(head, true)
					hid = true
				end
				for _, n in { "Right Arm", "Left Arm" } do
					local arm = char:FindFirstChild(n) or char:FindFirstChild(n == "Right Arm" and "RightHand" or "LeftHand")
					if arm then
						thumb(bag, arm)
					end
				end
			end
			if b >= 3 then
				-- still fizzing: a little arc off his head on every beat, and
				-- the pupils wander off somewhere new
				if DK then
					local h = headPos() + UP * 0.4
					DK.arc(h, h + Vector3.new(rand(-1, 1), rand(0.4, 1), rand(-1, 1)).Unit * rand(0.9, 1.6), YELLOW, 0.06)
				end
				sparks(headPos() + UP * 0.4, 0.25, WHITE, YELLOW, 4)
				local look = LOOKS[(b - 3) % #LOOKS + 1]
				for i, pupil in pupils or {} do
					pupil.Position = UDim2.fromScale(look[i].X, look[i].Y)
				end
			end
			if b == 6 then
				G.glint(headPos() + UP * 0.2 + (head or root).CFrame.LookVector * 0.7, 2.2, 0.35)
				VFX.PlaySound("Bell", headPos(), 0.7)
			end
		end, function(t, b)
			if b < 2 then
				-- in him: the flash flips every quarter beat; arcs all over him
				-- and the light flickering, on a clock of their own
				local on = math.floor(t / (B / 4)) % 2 == 0
				flash.FillTransparency, flash.OutlineTransparency = on and 0.2 or 0.75, on and 0 or 0.6
				if t - lastArc >= tick then
					lastArc = t
					light.Brightness = rand(1, 3.2)
					lamp.CFrame = root.CFrame
					if DK then
						local a = onBody()
						DK.arc(a, rng:NextNumber() < 0.6 and onBody() or a + rng:NextUnitVector() * rand(1, 2.2), YELLOW, 0.07)
					end
				end
			end
			if storm then
				local over = CFrame.new(headPos() + UP * (2.3 + math.sin(t * 5) * 0.12)) * CFrame.Angles(0, t * 0.8, 0)
				local blink = math.floor(t * 9) % 5 ~= 0
				for _, s in storm do
					s.part.CFrame = over * s.offset
					if s.bolt then
						s.part.Transparency = blink and 0 or 0.8
					end
				end
				if t - lastWisp > B / 2 then -- a wisp of smoke rising off it
					lastWisp = t
					dustPuffs(over.Position + UP * 0.4, 0.12, 1, Color3.fromRGB(90, 90, 96), 0.8)
				end
			end
		end)
		if hid then
			pcall(hideFace, head, false)
		end
		if not ran then
			G.unsay(char, "WHEEEY~")
		end
	end)
end)()

---------------------------------------------------------------------------
-- (round 85) HOLD THIS L (Common) to APM's "Power Move (b 60)" (97 bpm,
-- from 30.11 s, its horn stabs): a glowing L on his forehead, leaning back
-- smug, and a hop to rub it in (1); then he pulls out a BIG one and holds
-- it up over his head (2) - "HOLD THIS L" - winds up and throws it down at
-- you (3): it lands standing up on the street off to his left in front of
-- him on the next beat, facing whoever's looking, and he points at it with
-- the little L back on his brow (4). It stands there a moment after, then
-- poofs (at once if he moves). 2.5 s.
---------------------------------------------------------------------------
;(function()
	local EM = VFX.EMOTES
	local G = EM.gag
	local entry = EM.entry("HoldThisL") or { Id = "HoldThisL", Bpm = 97 }
	local B = 60 / (entry.Bpm or 97)
	local BACK, SINE = Enum.EasingStyle.Back, Enum.EasingStyle.Sine
	local steps = {}
	local function add(pose, beats, style, t)
		table.insert(steps, { pose = pose, beats = beats, style = style, t = t })
	end
	-- the hand making the L on his brow (R6: the raised arm's roll brings it
	-- in over his face)
	local BROW = { 150, 0, 40 }
	-- 1: the L up on his forehead, leaning back, smug; then a hop to his
	-- right to rub it in
	add({ Hips = { 0, 0, 0, 0, 0.13, 0 }, RightArm = BROW, LeftArm = { -12, 0, 26 }, Waist = { 8, 12, 4 }, Neck = { 12, -10, 0 }, RightLeg = { 0, 0, 6 }, LeftLeg = { 6, 0, 10 } }, 0.5, BACK, 0.1)
	add({ Hips = { 0, 0, 0, 0.3, 0.6, 0 }, RightArm = BROW, LeftArm = { -12, 0, 40 }, Waist = { 6, -12, -10 }, Neck = { 6, 16, 12 }, RightLeg = { 6, 0, 26 }, LeftLeg = { 0, 0, 8 } }, 0.5, nil, 0.08)
	-- 2: out comes the big one, held up over his head in both hands
	add({ Hips = { 0, 0, 0, 0, 0.05, 0 }, RightArm = { 166, 0, 22 }, LeftArm = { 166, 0, 22 }, Waist = { 8, 0, 0 }, Neck = { 16, 0, 0 }, RightLeg = { 0, 0, 6 }, LeftLeg = { 0, 0, 6 } }, 1, BACK, 0.12)
	-- 3: wound up, leaning back... and HOLD THIS - thrown down at you with a
	-- step in, turned toward where it'll land (his left)
	add({ Hips = { 0, 0, 0, 0, 0.05, 0 }, RightArm = { 178, 0, 14 }, LeftArm = { 178, 0, 14 }, Waist = { 16, 0, 0 }, Neck = { 18, 0, 0 }, RightLeg = { 0, 0, 6 }, LeftLeg = { -10, 0, 6 } }, 0.5, SINE, 0.12)
	add({ Hips = { 0, 0, 0, 0, 0.03, -0.25 }, RightArm = { 98, 12, 0 }, LeftArm = { 98, -12, 0 }, Waist = { -12, 14, 0 }, Neck = { 4, 0, 0 }, RightLeg = { -20, 0, 3 }, LeftLeg = { 22, 0, 3 } }, 0.5, nil, 0.06)
	-- 4: it lands; a smug point at it, the little L back up on his brow
	add({ Hips = { 0, 0, 0, 0, 0.07, 0 }, RightArm = BROW, LeftArm = { 60, 0, 22 }, Waist = { 8, 18, 0 }, Neck = { 12, 10, 0 }, RightLeg = { 0, 0, 4 }, LeftLeg = { 8, 0, 14 } }, 1, BACK, 0.12)
	MOTIONS.EmoteHoldThisL = EM.beatMotion(entry, steps, { recover = 0.6 }) -- 1 + 1 + 1 + 1 = 4 beats

	local LIME, DEEP = Color3.fromRGB(120, 255, 90), Color3.fromRGB(16, 96, 40)
	-- an L of two blocks, k studs tall: { part, offset } each, the glyph
	-- read off its front (-Z) face: the upright on the reader's left (+X),
	-- the foot running right (-X); the origin at the bottom of the foot
	local function glyph(bag, k, color, material, depth, back)
		local w = 0.28 * k
		local list = {}
		for _, b in { { w, k, k * 0.31, k / 2 }, { k * 0.9, w, 0, w / 2 } } do
			local p = EM.part(bag, Vector3.new(b[1] + back * 2, b[2] + back * 2, depth), CFrame.new(), color, material)
			table.insert(list, { part = p, offset = CFrame.new(b[3], b[4], back > 0 and depth * 0.6 or 0) })
		end
		return list
	end
	local function place(list, cf)
		for _, g in list do
			g.part.CFrame = cf * g.offset
		end
	end
	EM.props.HoldThisL = G.guard(function(char, token, root, bag)
		local cam = workspace.CurrentCamera
		local head = char:FindFirstChild("Head")
		local small = glyph(bag, 1, LIME, Enum.Material.Neon, 0.16, 0)
		local big, flyFrom, landed = nil, nil, false
		-- thrown on the half beat after 3, it lands on beat 4 (the horn stab)
		local throwAt, flyTime = 2.5 * B, 0.5 * B
		local ahead = root.Position + root.CFrame.LookVector * 5 - root.CFrame.RightVector * 4.4
		local g = groundPoint(ahead)
		local function facing(pos)
			-- (turned to this client's camera, so it reads L, not ⅃)
			local c = cam and cam.CFrame.Position or pos + root.CFrame.LookVector * -10
			local flat = Vector3.new(c.X - pos.X, 0, c.Z - pos.Z)
			flat = flat.Magnitude > 0.1 and flat.Unit or -root.CFrame.LookVector
			return CFrame.lookAt(pos, pos + flat)
		end
		local function hands()
			return (handPos(char, true) + handPos(char, false)) / 2
		end
		local ran = EM.beatLoop(char, token, root, entry, 4, function(b)
			if b == 0 then
				VFX.PlaySound("Bell", root.Position + UP * 2, 0.8)
				G.word(root.Position + UP * 4.2, "L", LIME, 44, B * 1.6, 1.2, bag)
			elseif b == 1 then
				-- out comes the big one
				big = glyph(bag, 3.2, LIME, Enum.Material.Neon, 0.55, 0)
				for _, s in glyph(bag, 3.2, DEEP, Enum.Material.SmoothPlastic, 0.4, 0.2) do
					table.insert(big, s)
				end
				VFX.PlaySound("Boing", root.Position, 1)
				sparks(hands(), 0.6, Color3.new(1, 1, 1), LIME, 14)
				VFX.SpeechBubble(char, "HOLD THIS L", 1.5)
			end
		end, function(t, b)
			-- the small L at his brow, facing out of his face, while his hand's
			-- up there: beat 1 (the L) and beat 4 (the point)
			local onBrow = (t > 0.1 and t < B) or (t > 3 * B + 0.1 and t < 4 * B)
			if onBrow and head then
				local look = head.CFrame.LookVector
				local at = handPos(char, true) + look * 0.35 + UP * -0.7
				place(small, CFrame.lookAt(at, at + look) * CFrame.new(-0.2, 0, 0))
			end
			for _, s in small do
				s.part.Transparency = onBrow and 0 or 1
			end
			if big then
				local pos
				if t >= throwAt then
					-- thrown at you: it flies off his hands and lands standing up
					if not flyFrom then
						flyFrom = hands() + UP * 0.1
						VFX.PlaySound("Swing", root.Position, 0.8)
					end
					local k = math.clamp((t - throwAt) / flyTime, 0, 1)
					pos = flyFrom:Lerp(g, k) + UP * (math.sin(k * math.pi) * 1.5)
					if k >= 1 and not landed then
						landed = true
						VFX.PlaySound("PkRoll", g, 1.1)
						dustPuffs(g, 0.45, 8, Color3.fromRGB(196, 188, 176), 0.6)
						shockDisc(g + UP * 0.2, UP, 2, 8, 0.3, LIME)
					end
					pos = landed and g or pos
				else
					pos = hands() + UP * 0.1 -- (held up over his head)
				end
				local wobble = landed and 0 or math.sin(t * 14) * 0.08
				place(big, facing(pos) * CFrame.Angles(0, 0, wobble))
			end
		end)
		if not ran then
			G.unsay(char, "HOLD THIS L")
		end
		-- it stands there a moment after (gone at once if he moves)
		local t0 = os.clock()
		while ran and big and os.clock() - t0 < 0.8 and EM.alive(char, token, root) do
			task.wait(0.05)
		end
		if ran and big then
			VFX.PlaySound("HairPoof", g, 0.8)
			dustPuffs(g + UP * 1.2, 0.4, 6, Color3.fromRGB(230, 230, 230), 0.5)
		end
	end)
end)()

---------------------------------------------------------------------------
-- (round 92) EMOTES2: TEN MORE - SEAN O'PRY (the meme), CRAB RAVE, FINAL
-- FORM, K-POP IDOL, MIC DROP, BREAKDANCE, MAKE IT RAIN, MOONWALK, TUNG
-- SAHUR and BOO!. Each in a function of its own (this script is near Luau's
-- local limit), built on the emote kit (VFX.EMOTES: EM.beatMotion,
-- EM.beatLoop, EM.floor; the Emote wrapper plays each one's song from
-- SongStart) and the gag emotes' EM.gag (guard: the props' bag goes
-- whatever happens; word; unsay). First what they share, on EM.x92: props
-- that ride a body part, groups of parts that move as one, an egg-shaped
-- part, a rod, a poof, dark glasses, and things thrown along an arc.
---------------------------------------------------------------------------
;(function()
	local EM = VFX.EMOTES
	local X = {}
	EM.x92 = X
	local R15 = { ["Right Arm"] = "RightHand", ["Left Arm"] = "LeftHand", Torso = "UpperTorso", ["Right Leg"] = "RightLowerLeg", ["Left Leg"] = "LeftLowerLeg" }
	-- a body part by its R6 name (an R15 body's nearest)
	function X.limb(char, name)
		return char:FindFirstChild(name) or (R15[name] and char:FindFirstChild(R15[name])) or nil
	end
	-- a prop riding a body part: X.place puts it at limb.CFrame * offset
	-- (every frame); a limb that's gone leaves it where it was
	function X.ride(list, part, limb, offset)
		table.insert(list, { part = part, limb = limb, offset = offset or CFrame.new() })
		return part
	end
	function X.place(list)
		for _, s in list do
			if s.limb and s.limb.Parent and s.part.Parent then
				s.part.CFrame = s.limb.CFrame * s.offset
			end
		end
	end
	-- a few parts that move as one: { { part, offset } }, put at cf * offset
	function X.put(group, cf)
		for _, g in group do
			g[1].CFrame = cf * g[2]
		end
	end
	-- an egg: a ball stretched to any size (a sphere mesh)
	function X.egg(bag, size, cf, color, material)
		local p = EM.part(bag, size, cf, color, material)
		local mesh = Instance.new("SpecialMesh")
		mesh.MeshType = Enum.MeshType.Sphere
		mesh.Parent = p
		return p
	end
	-- a rod along cf's Y (a cylinder's own axis is its X)
	function X.rod(bag, length, thick, cf, color, material)
		return EM.part(bag, Vector3.new(length, thick, thick), cf * CFrame.Angles(0, 0, math.pi / 2), color, material, Enum.PartType.Cylinder)
	end
	-- a prop coming or going: a puff, sparkles and a pop
	function X.poof(pos, scale, color)
		scale = scale or 1
		dustPuffs(pos, 0.3 * scale, 6, color or Color3.fromRGB(240, 240, 246), 0.45)
		sparks(pos, 0.35 * scale, Color3.new(1, 1, 1), color or Color3.fromRGB(255, 232, 150), 10)
		VFX.PlaySound("HairPoof", pos, 0.6)
	end
	-- dark glasses on his face (riding his head)
	function X.shades(bag, char, list)
		local head = X.limb(char, "Head")
		if not head then
			return
		end
		local black = Color3.fromRGB(14, 14, 18)
		for _, s in { -1, 1 } do
			local lens = EM.part(bag, Vector3.new(0.52, 0.27, 0.06), CFrame.new(), black, Enum.Material.Glass)
			X.ride(list, lens, head, CFrame.new(0.28 * s, 0.12, -0.61))
			X.ride(list, EM.part(bag, Vector3.new(0.05, 0.05, 0.6), CFrame.new(), black, Enum.Material.Metal), head, CFrame.new(0.6 * s, 0.2, -0.32))
		end
		X.ride(list, EM.part(bag, Vector3.new(1.16, 0.07, 0.07), CFrame.new(), black, Enum.Material.Metal), head, CFrame.new(0, 0.25, -0.62))
	end
	-- something thrown: `what` (a part or a group) from -> to over dur
	-- seconds of the emote's clock from t0, along an arc `height` high,
	-- turning `spin` radians; X.flying(list, t) moves them (and calls a
	-- record's landed() when it gets there)
	function X.fly(list, what, from, to, t0, dur, height, spin)
		local f = { what = what, from = from, to = to, t0 = t0, dur = math.max(dur, 0.01), height = height or 2, spin = spin or 0 }
		table.insert(list, f)
		return f
	end
	function X.flying(list, t)
		for i = #list, 1, -1 do
			local f = list[i]
			if t >= f.t0 then
				local k = math.clamp((t - f.t0) / f.dur, 0, 1)
				local cf = CFrame.new(f.from:Lerp(f.to, k) + UP * (math.sin(k * math.pi) * f.height)) * CFrame.Angles(f.spin * k, f.spin * 0.6 * k, 0)
				if typeof(f.what) == "Instance" then
					f.what.CFrame = cf
				else
					X.put(f.what, cf)
				end
				if k >= 1 then
					table.remove(list, i)
					if f.landed then
						f.landed()
					end
				end
			end
		end
	end
	-- his own hats and hair hidden on this screen while a prop covers his
	-- head (they'd poke through the log or the pumpkin; SWING TIME's top hat
	-- does the same): returns cover(on) - call cover(true) every frame while
	-- it's on (the camera's own fading writes LocalTransparencyModifier too)
	-- and cover(false) once at the end. Ones something else already hides
	-- are left alone; ones another emote hid (tagged EmoteHidden) are taken
	-- over
	function X.headwear(char)
		local list = {}
		for _, acc in char:GetChildren() do
			local h = acc:IsA("Accessory") and acc:FindFirstChild("Handle")
			if h and h:IsA("BasePart") and ((h.LocalTransparencyModifier or 0) < 1 or h:GetAttribute("EmoteHidden")) then
				local okT, kind = pcall(function()
					return acc.AccessoryType == Enum.AccessoryType.Hat or acc.AccessoryType == Enum.AccessoryType.Hair
				end)
				if (okT and kind) or h:FindFirstChild("HatAttachment") or h:FindFirstChild("HairAttachment") then
					table.insert(list, h)
				end
			end
		end
		return function(on)
			for _, h in list do
				if h.Parent then
					h.LocalTransparencyModifier = on and 1 or 0
					if (h:GetAttribute("EmoteHidden") == true) ~= on then
						h:SetAttribute("EmoteHidden", on or nil)
					end
				end
			end
		end
	end
	-- his feet, facing his way (props laid out round him)
	function X.base(root)
		local g = groundPoint(root.Position)
		local look = root.CFrame.LookVector
		local flat = Vector3.new(look.X, 0, look.Z)
		flat = flat.Magnitude > 0.1 and flat.Unit or Vector3.new(0, 0, -1)
		return CFrame.lookAt(g, g + flat), g
	end
end)()

---------------------------------------------------------------------------
-- (round 92) SEAN O'PRY (Legendary): the meme, both halves of it. (1) "can
-- i get another mango?" - the model's 2015 mango-cutting video (Spot.ph),
-- reposted in June 2026 and overhyped on TikTok as the funniest thing ever
-- filmed; (2) his finger-snap edits - the 2015 cologne ad where a snap of
-- his fingers changed his suit, cut to a bass drop. Beats 1-8 (the song's
-- intro): a little table and a cutting board; up goes the knife, the cut -
-- botched: a splat, juice, the stone flying, half of it off the table - he
-- holds up what's left, deadpans the line at you, and another mango comes
-- flying in from his left; he catches it and throws it up... 9-16: the
-- kick comes in on a snap - the mango he threw turns gold and hangs over
-- him - and a snap on every other beat after (9, 11, 13, 15), each one a
-- flash and a new suit (black, white, gold, black), a model pose on the
-- beats between; 17-20 the runway sway under camera flashes; 21-22 a laugh
-- track and crying-laughing faces round him (the overhype); 23 the last
-- snap, in gold: it rains mangoes, and the gold one drops into his hand
-- (24): "ANOTHER MANGO.". 24 beats to APM's "Energize Me" (11.6 s).
---------------------------------------------------------------------------
;(function()
	local EM = VFX.EMOTES
	local G, X = EM.gag, EM.x92
	local entry = EM.entry("SeanOPry") or { Id = "SeanOPry", Bpm = 124 }
	local B = 60 / (entry.Bpm or 124)
	local SINE, BACK = Enum.EasingStyle.Sine, Enum.EasingStyle.Back
	local steps = {}
	local function add(pose, beats, style, t)
		table.insert(steps, { pose = pose, beats = beats, style = style, t = t })
	end
	-- 1-2: up to the board, the knife going up
	add({ RightArm = { 70, 0, 6 }, LeftArm = { 52, -18, 0 }, Waist = { -10, 0, 0 }, Neck = { -22, 0, 0 } }, 1, BACK, 0.12)
	add({ RightArm = { 125, 0, 6 }, LeftArm = { 52, -18, 0 }, Waist = { -12, 0, 0 }, Neck = { -24, 0, 0 } }, 1, SINE, B * 0.6)
	-- 3: the cut (it goes wrong)
	add({ RightArm = { 48, 8, 0 }, LeftArm = { 50, -22, 0 }, Waist = { -18, 4, 0 }, Neck = { -26, 0, 0 } }, 1, nil, 0.06)
	-- 4: holds up what's left of it, head on one side
	add({ RightArm = { 36, 0, 10 }, LeftArm = { 96, -10, 0 }, Waist = { -4, -6, 0 }, Neck = { -6, -8, 12 } }, 1, SINE, B * 0.5)
	-- 5-6: to you, deadpan: "can i get another mango?"
	add({ RightArm = { 40, 0, 22 }, LeftArm = { 40, 0, 22 }, Neck = { 2, 0, 4 } }, 2, SINE, B * 0.6)
	-- 7: the catch, out to his left
	add({ Hips = { 0, 0, 0, 0, 0.05, 0 }, RightArm = { 10, 0, 12 }, LeftArm = { 84, 0, 46 }, Waist = { 0, -14, -4 }, Neck = { 0, -24, 0 } }, 1, nil, 0.1)
	-- 8: and up it goes
	add({ RightArm = { 10, 0, 12 }, LeftArm = { 168, 0, 8 }, Waist = { 8, 0, 0 }, Neck = { 22, 0, 0 } }, 1, BACK, 0.12)
	-- 9-16: THE DROP. A snap on the beat (that hand up by his head, the
	-- other on his hip), a model pose on the beat after
	local function snap(s) -- (s: 1 the right hand, -1 the left)
		local up, hip = { 150, 0, 20 }, { -14, 0, 26 }
		return { Hips = { 0, 0, 0, 0, 0.08, 0 }, RightArm = s > 0 and up or hip, LeftArm = s > 0 and hip or up, Waist = { 4, -14 * s, -5 * s }, Neck = { 8, 16 * s, 0 } }
	end
	add(snap(1), 1, nil, 0.06)
	add({ Hips = { 0, 0, 0, 0.12, 0.08, 0 }, RightArm = { -8, 0, 10 }, LeftArm = { -14, 0, 26 }, Waist = { 2, 10, 6 }, Neck = { 14, -10, -6 } }, 1, SINE, B * 0.5) -- (chin up, a hip out)
	add(snap(-1), 1, nil, 0.06)
	add({ Hips = { 0, 0, 0, 0, 0.06, 0 }, RightArm = { 165, 0, 50 }, LeftArm = { -10, 0, 14 }, Waist = { 4, 10, 4 }, Neck = { 12, -10, -10 } }, 1, SINE, B * 0.5) -- (a hand through his hair)
	add(snap(1), 1, nil, 0.06)
	add({ RightArm = { 0, 0, 8 }, LeftArm = { -6, 0, 10 }, Waist = { 0, 32, 0 }, Neck = { 0, -36, 0 } }, 1, SINE, B * 0.5) -- (a shoulder to you, looking over it)
	add(snap(-1), 1, nil, 0.06)
	add({ RightArm = { 70, 42, 0 }, LeftArm = { 70, -42, 0 }, Waist = { 6, 0, 0 }, Neck = { 10, 0, 0 } }, 1, SINE, B * 0.4) -- (arms crossed)
	-- 17-20: the runway sway, his eyes on you the whole time
	for k = 1, 4 do
		local s = k % 2 == 1 and 1 or -1
		add({ Hips = { 0, 6 * s, 0, 0.12 * s, 0.06, 0 }, RightArm = { -16 * s, 0, 8 }, LeftArm = { 16 * s, 0, 8 }, Waist = { 0, -6 * s, 4 * s }, Neck = { 4, 0, -4 * s } }, 1, SINE, B * 0.7)
	end
	-- 21-22: the smoulder, a hand at his chin, while the laugh track goes
	add({ RightArm = { 120, 25, 0 }, LeftArm = { 40, -30, 0 }, Waist = { 0, 12, 0 }, Neck = { -8, -14, 8 } }, 1, SINE, B * 0.5)
	add({ RightArm = { 118, 25, 0 }, LeftArm = { 40, -30, 0 }, Waist = { 2, 8, 0 }, Neck = { -2, -6, 14 } }, 1, SINE, B * 0.6)
	-- 23: the last snap, high
	add({ Hips = { 0, 0, 0, 0, 0.08, 0 }, RightArm = { 168, 0, 12 }, LeftArm = { -14, 0, 26 }, Waist = { 8, -8, -4 }, Neck = { 14, 10, 0 } }, 1, nil, 0.06)
	-- 24: the gold mango in his hand by his face, chin up
	add({ Hips = { 0, 0, 0, 0, 0.06, 0 }, RightArm = { -14, 0, 26 }, LeftArm = { 140, 0, 30 }, Waist = { 6, 10, 4 }, Neck = { 12, -12, 0 } }, 1, BACK, 0.12)
	MOTIONS.EmoteSeanOPry = EM.beatMotion(entry, steps, { recover = 0.5 }) -- 8 + 8 + 4 + 2 + 1 + 1 = 24 beats

	local MANGO, BLUSH, LEAF = Color3.fromRGB(255, 178, 40), Color3.fromRGB(236, 96, 40), Color3.fromRGB(70, 160, 60)
	local GOLD = Color3.fromRGB(255, 204, 64)
	local WOOD, BOARD = Color3.fromRGB(120, 82, 52), Color3.fromRGB(216, 178, 122)
	-- the suits a snap puts on him: jacket, shirt, tie
	local SUITS = {
		{ Color3.fromRGB(24, 24, 30), Color3.fromRGB(242, 242, 246), Color3.fromRGB(18, 18, 22) }, -- black tie
		{ Color3.fromRGB(240, 240, 244), Color3.fromRGB(28, 28, 32), Color3.fromRGB(236, 236, 240) }, -- white
		{ Color3.fromRGB(214, 168, 56), Color3.fromRGB(32, 26, 18), Color3.fromRGB(255, 214, 90) }, -- gold
	}
	local SNAPS = { [8] = 1, [10] = 2, [12] = 3, [14] = 1, [22] = 3 } -- (0-based beat: the suit it puts on)
	-- a mango (an egg with a red blush and a leaf), as a group
	local function mango(bag, cf)
		local body = X.egg(bag, Vector3.new(0.8, 0.58, 0.6), cf, MANGO)
		local blush = X.egg(bag, Vector3.new(0.5, 0.46, 0.5), cf, BLUSH)
		local leaf = EM.part(bag, Vector3.new(0.26, 0.04, 0.13), cf, LEAF)
		return { { body, CFrame.new() }, { blush, CFrame.new(0.2, 0.06, 0) }, { leaf, CFrame.new(-0.32, 0.28, 0) * CFrame.Angles(0, 0, 0.5) } }
	end
	local function gild(group)
		for _, g in group do
			g[1].Color = GOLD
			g[1].Material = Enum.Material.Metal
		end
	end
	EM.props.SeanOPry = G.guard(function(char, token, root, bag)
		local rides, flights = {}, {}
		local base, g = X.base(root)
		local rightArm, leftArm, torso, head = X.limb(char, "Right Arm"), X.limb(char, "Left Arm"), X.limb(char, "Torso"), X.limb(char, "Head")
		local function hand(arm) -- (just past the end of that hand)
			return arm and (arm.CFrame * CFrame.new(0, -arm.Size.Y / 2 - 0.25, 0)) or root.CFrame
		end
		-- the table, the board and the knife (gone on the drop)
		local kit = {}
		local tableCF = base * CFrame.new(0, 0, -1.8)
		table.insert(kit, EM.part(bag, Vector3.new(2.4, 0.14, 1.3), tableCF * CFrame.new(0, 2.68, 0), WOOD, Enum.Material.Wood))
		for _, c in { { -1.05, -0.5 }, { 1.05, -0.5 }, { -1.05, 0.5 }, { 1.05, 0.5 } } do
			table.insert(kit, EM.part(bag, Vector3.new(0.14, 2.62, 0.14), tableCF * CFrame.new(c[1], 1.31, c[2]), WOOD, Enum.Material.Wood))
		end
		table.insert(kit, EM.part(bag, Vector3.new(1.3, 0.08, 0.82), tableCF * CFrame.new(0, 2.79, 0), BOARD, Enum.Material.Wood))
		local handle = EM.part(bag, Vector3.new(0.14, 0.36, 0.16), CFrame.new(), Color3.fromRGB(30, 26, 24))
		local blade = EM.part(bag, Vector3.new(0.04, 0.8, 0.22), CFrame.new(), Color3.fromRGB(214, 218, 226), Enum.Material.Metal)
		if rightArm then
			X.ride(rides, handle, rightArm, CFrame.new(0, -1.12, 0))
			X.ride(rides, blade, rightArm, CFrame.new(0, -1.7, -0.02))
		end
		table.insert(kit, handle)
		table.insert(kit, blade)
		local onBoard = tableCF * CFrame.new(0.05, 3.1, 0)
		local first = mango(bag, onBoard)
		X.put(first, onBoard)
		X.poof(onBoard.Position, 1)
		local halves, held, second, suit, rain = nil, nil, nil, nil, {}
		local hover = false
		local function dress(k)
			local colors = SUITS[k]
			if not suit and torso then
				suit = {}
				local function piece(size, limb, offset, which)
					local p = EM.part(bag, size, limb.CFrame * offset, colors[which])
					X.ride(rides, p, limb, offset)
					table.insert(suit, { p, which })
				end
				piece(Vector3.new(2.08, 2.04, 1.08), torso, CFrame.new(), 1)
				piece(Vector3.new(0.62, 1.0, 0.04), torso, CFrame.new(0, 0.46, -0.55), 2)
				piece(Vector3.new(0.2, 0.9, 0.05), torso, CFrame.new(0, 0.42, -0.58), 3)
				for _, arm in { rightArm, leftArm } do
					if arm then
						piece(Vector3.new(1.07, 1.7, 1.07), arm, CFrame.new(0, 0.17, 0), 1)
					end
				end
				X.poof(torso.Position, 1.2, colors[1])
			end
			for _, s in suit or {} do
				s[1].Color = colors[s[2]]
				s[1].Material = k == 3 and s[2] ~= 2 and Enum.Material.Metal or Enum.Material.SmoothPlastic
			end
		end
		local strobe = Instance.new("PointLight")
		strobe.Range = 18
		strobe.Brightness = 0
		strobe.Color = Color3.new(1, 1, 1)
		strobe.Parent = EM.part(bag, Vector3.one * 0.2, root.CFrame, Color3.new(), nil)
		strobe.Parent.Transparency = 1
		local function flash(color)
			local shell = EM.part(bag, Vector3.one * 6, root.CFrame, color, Enum.Material.Neon, Enum.PartType.Ball)
			shell.Transparency = 0.55
			tween(shell, 0.16, { Transparency = 1, Size = Vector3.one * 8 })
			strobe.Color = color
			strobe.Brightness = 6
			tween(strobe, 0.25, { Brightness = 0 })
		end
		local low = IceKit.lowEnd()
		local ran = EM.beatLoop(char, token, root, entry, 24, function(b)
			if b == 1 then
				VFX.PlaySound("Swing", root.Position, 0.5)
			elseif b == 2 then
				-- the cut: a splat, juice, the stone off one way and half of it
				-- off the table the other
				local at = onBoard.Position
				for _, p in first do
					p[1]:Destroy()
				end
				VFX.PlaySound("EmoteSplat", at, 1)
				sparks(at, 0.4, Color3.fromRGB(255, 226, 90), MANGO, 16)
				dustPuffs(at, 0.12, 4, Color3.fromRGB(255, 196, 70), 0.35)
				halves = { mango(bag, onBoard), mango(bag, onBoard) }
				for _, h in halves do
					for _, p in h do
						p[1].Size = Vector3.new(p[1].Size.X * 0.55, p[1].Size.Y, p[1].Size.Z)
					end
				end
				X.put(halves[1], onBoard * CFrame.new(-0.25, -0.04, 0) * CFrame.Angles(0, 0, 0.3))
				X.fly(flights, halves[2], (onBoard * CFrame.new(0.3, 0, 0)).Position, (base * CFrame.new(1.9, 0.18, -2.2)).Position, B * 2 + 0.06, B * 0.9, 0.8, 5)
				local stone = X.egg(bag, Vector3.new(0.44, 0.14, 0.3), onBoard, Color3.fromRGB(240, 226, 170))
				X.fly(flights, stone, at, (base * CFrame.new(-3.4, 0.07, -2.6)).Position, B * 2 + 0.06, B * 1.1, 2.4, 9)
			elseif b == 3 then
				held = halves and halves[1]
			elseif b == 4 then
				VFX.SpeechBubble(char, "can i get another mango?", B * 2 + 0.2)
			elseif b == 5 then
				-- another one, thrown in from his left
				second = mango(bag, base * CFrame.new(-9, 4, -1))
				local f = X.fly(flights, second, (base * CFrame.new(-9, 4, -1)).Position, hand(leftArm).Position, B * 5.5, B * 0.5, 1.6, 7)
				f.landed = function()
					held = second
					VFX.PlaySound("Bell", root.Position, 0.4)
				end
				VFX.PlaySound("Swing", root.Position, 0.5)
				if halves then -- (the half he was holding: down on the board)
					-- (round 92 review: and out of his hand - still `held`, the
					-- frame loop pulled it straight back and it hung in the air
					-- where he caught the next one until the drop)
					held = nil
					X.put(halves[1], onBoard * CFrame.new(-0.25, -0.04, 0) * CFrame.Angles(0, 0, 0.3))
				end
			elseif b == 7 then
				-- up it goes (it hangs over him once the beat drops)
				held = nil
				if second then
					X.fly(flights, second, hand(leftArm).Position, root.Position + UP * 4.4, B * 7.05, B * 0.95, 0.6, 6).landed = function()
						hover = true
					end
					VFX.PlaySound("Swing", root.Position, 0.6)
				end
			end
			if SNAPS[b] then
				-- a snap: a flash, a suit, sparks at his fingers
				local fingers = hand((b == 8 or b == 12 or b == 22) and rightArm or leftArm).Position
				VFX.PlaySound("EmoteSnap", fingers, 1)
				sparks(fingers, 0.45, Color3.new(1, 1, 1), GOLD, 14)
				shockDisc(g + UP * 0.2, UP, 2, 11, 0.3, b == 22 and GOLD or Color3.new(1, 1, 1))
				flash(SNAPS[b] == 3 and GOLD or Color3.new(1, 1, 1))
				dress(SNAPS[b])
			end
			if b == 8 then
				-- THE DROP: the kitchen's gone, the mango he threw is gold
				VFX.PlaySound("MuscleThump", root.Position, 0.35)
				for _, p in kit do
					if p.Parent then
						p:Destroy()
					end
				end
				for _, h in halves or {} do
					for _, p in h do
						p[1]:Destroy()
					end
				end
				halves = nil
				X.poof(tableCF.Position + UP * 2.6, 1.4)
				if second then
					gild(second)
					hover = true
				end
			elseif b >= 16 and b <= 19 then
				-- the runway: camera flashes
				for _ = 1, low and 1 or 2 do
					local at = (base * CFrame.new(rand(-5, 5), rand(1.5, 4.5), rand(-9, -5))).Position
					G.glint(at, 2.4, 0.3)
					VFX.PlaySound("DirectorShutter", at, 0.5)
				end
			elseif b == 20 then
				-- the overhype: a laugh track, crying-laughing faces
				VFX.PlaySound("EmoteCrowd", root.Position, 1)
				G.word(root.Position + UP * 4.6, "FUNNIEST VIDEO EVER", Color3.fromRGB(255, 236, 90), 24, B * 2, 1, bag)
			elseif b == 22 then
				-- the last snap: it rains mangoes; the gold one comes down to him
				for k = 1, low and 6 or 12 do
					local a = k / (low and 6 or 12) * math.pi * 2 + rand(-0.2, 0.2)
					local r = rand(2.2, 6)
					local m = mango(bag, CFrame.new(g + Vector3.new(math.cos(a) * r, rand(10, 15), math.sin(a) * r)))
					table.insert(rain, { group = m, pos = g + Vector3.new(math.cos(a) * r, rand(10, 15), math.sin(a) * r), vy = rand(-4, 0), spin = rand(-8, 8), bounced = false })
				end
				hover = false
				if second then
					X.fly(flights, second, root.Position + UP * 4.4, hand(leftArm).Position, B * 22.1, B * 0.9, 0.2, 4).landed = function()
						held = second
						G.glint(hand(leftArm).Position, 2.6, 0.4)
						VFX.PlaySound("Bell", root.Position, 0.8)
					end
				end
				G.word(root.Position + UP * 4.4, "ANOTHER MANGO.", GOLD, 34, B * 3, 1.4, nil)
			end
			if b >= 20 and b <= 21 then
				for _ = 1, low and 2 or 4 do
					G.word(root.Position + Vector3.new(rand(-3.5, 3.5), rand(0.5, 3.5), rand(-3.5, 3.5)), rng:NextNumber() < 0.7 and "😭" or "💀", Color3.new(1, 1, 1), 34, B * 1.6, 2.2, bag)
				end
			end
		end, function(t, _, _, dt)
			X.place(rides)
			X.flying(flights, t)
			if held and leftArm then
				X.put(held, hand(leftArm) * CFrame.Angles(0, 0, 0.4))
			end
			if hover and second then
				X.put(second, CFrame.new(root.Position + UP * (4.4 + math.sin(t * 3) * 0.25)) * CFrame.Angles(0, t * 2.2, 0.3))
			end
			for _, m in rain do
				if not m.rest then
					m.vy -= 60 * dt
					m.pos += Vector3.new(0, m.vy * dt, 0)
					if m.pos.Y <= g.Y + 0.3 then
						m.pos = Vector3.new(m.pos.X, g.Y + 0.3, m.pos.Z)
						if m.bounced or math.abs(m.vy) < 6 then
							m.rest = true
						else
							m.bounced = true
							m.vy = -m.vy * 0.35
							VFX.PlaySound("PkRoll", m.pos, 0.35)
						end
					end
					X.put(m.group, CFrame.new(m.pos) * CFrame.Angles(0, t * m.spin * (m.rest and 0 or 1), m.spin * 0.1))
				end
			end
		end)
		if not ran then
			G.unsay(char, "can i get another mango?")
		end
		if ran then -- (it all stays a moment, unless he moves)
			local t1 = os.clock()
			while os.clock() - t1 < 0.4 and EM.alive(char, token, root) do
				task.wait()
			end
		end
	end)
end)()

---------------------------------------------------------------------------
-- (round 92) CRAB RAVE (Epic) to Noisestorm - "Crab Rave" (Monstercat, 125
-- bpm): a patch of sand under him, lasers sweeping, and crabs scuttling in
-- sideways from all round (1-2) to rave with him, bobbing and snapping
-- their claws on the beat. Claws up and snapping (1-2), the crab walk -
-- two steps to his right and back (3-6), a spin (7-8), the drop: hopping
-- with the claws pumping (9-12), a low shuffle, claws out in front
-- (13-14), and claws to the sky while every crab jumps: "🦀 YOUR HP IS
-- GONE 🦀" (15-16). 7.7 s.
