	-- (a leg rolled out pivots at the hip's outer edge and sinks its foot: the
	-- Hips y lifts put both feet back on the street)
	local LIFT = { 0, 0, 0, 0, 0.14, 0 }
	add({ Hips = LIFT, RightLeg = WIDE, LeftLeg = WIDE, RightArm = { 160, 0, -25 }, LeftArm = { 160, 0, -25 }, Waist = { -4, 0, 0 }, Neck = { 10, 0, 0 } }, 1, BACK, 0.12)
	add({ Hips = LIFT, RightLeg = WIDE, LeftLeg = WIDE, RightArm = { 146, 0, -6 }, LeftArm = { 146, 0, -6 }, Waist = { -6, 0, 0 }, Neck = { 6, 0, 0 } }, 0.5, nil, 0.06)
	add({ Hips = LIFT, RightLeg = WIDE, LeftLeg = WIDE, RightArm = { 166, 0, -30 }, LeftArm = { 166, 0, -30 }, Waist = { -4, 0, 0 }, Neck = { 10, 0, 0 } }, 0.5, nil, 0.06)
	-- 3-6: the crab walk - sideways to his right and back, a claw up on
	-- each step
	for k, x in { 0.4, 0.8, 0.4, 0 } do
		local s = k % 2 == 1 and 1 or -1
		add({
			Hips = { 0, 0, 0, x, 0.12, 0 }, RightLeg = { 0, 0, s > 0 and 22 or 8 }, LeftLeg = { 0, 0, s > 0 and 8 or 22 }, Waist = { -6, 0, 3 * s },
			RightArm = { s > 0 and 170 or 140, 0, -24 }, LeftArm = { s > 0 and 140 or 170, 0, -24 }, Neck = { 6, 0, -6 * s },
		}, 1, nil, 0.1)
	end
	-- 7-8: a spin, claws up (a quarter turn every half beat)
	for q = 1, 4 do
		add({ Hips = { 0, 0, 0, 0, 0.08, 0 }, RightLeg = { 0, 0, 8 }, LeftLeg = { 0, 0, 8 }, Waist = { 0, q * 90, 0 }, RightArm = { 160, 0, -20 }, LeftArm = { 160, 0, -20 }, Neck = { 8, 0, 0 } }, 0.5, LIN, B * 0.5)
	end
	-- 9-12: THE DROP - a hop on every beat, the claws pumping turn about
	for k = 1, 4 do
		local s = k % 2 == 1 and 1 or -1
