		add({ Crouch = 0.25, Waist = { -10, 0, 0 }, RightArm = { 150, 0, -18 }, LeftArm = { 150, 0, -18 }, Neck = { 4, 0, 0 } }, 0.5, SINE, B * 0.3)
	end
	-- 13-14: down low, claws out in front, snapping
	for k = 1, 4 do
		local s = k % 2 == 1 and 1 or -1
		add({ Crouch = 0.9, Hips = { 0, 0, 0, 0, 0.17, 0 }, Waist = { -14, 0, 0 }, RightArm = { 96, -14 - 10 * s, 0 }, LeftArm = { 96, 14 + 10 * s, 0 }, Neck = { 16, 0, 0 } }, 0.5, nil, 0.06)
	end
	-- 15-16: claws to the sky
	add({ Hips = { 0, 0, 0, 0, 0.12, 0 }, RightLeg = WIDE, LeftLeg = WIDE, RightArm = { 172, 0, -22 }, LeftArm = { 172, 0, -22 }, Waist = { 8, 0, 0 }, Neck = { 22, 0, 0 } }, 2, BACK, 0.14)
	MOTIONS.EmoteCrabRave = EM.beatMotion(entry, steps, { recover = 0.4 }) -- 2 + 4 + 2 + 4 + 2 + 2 = 16 beats

	local SHELL, DARK, SAND = Color3.fromRGB(232, 86, 52), Color3.fromRGB(184, 54, 34), Color3.fromRGB(232, 212, 158)
	local RAVE = { Color3.fromRGB(255, 70, 200), Color3.fromRGB(60, 230, 255), Color3.fromRGB(150, 255, 90), Color3.fromRGB(255, 226, 60) }
	-- a crab: its shell, eyes on stalks and legs (parts), and two claws
	-- (moved on their own: up on the beat)
	local function crab(bag)
		local c = { parts = {}, claws = {} }
		local function on(p, cf)
			table.insert(c.parts, { p, cf })
		end
		on(X.egg(bag, Vector3.new(1.3, 0.56, 1.0), CFrame.new(), SHELL), CFrame.new())
		for _, s in { -1, 1 } do
			on(EM.part(bag, Vector3.new(0.08, 0.42, 0.08), CFrame.new(), DARK), CFrame.new(0.22 * s, 0.38, -0.3))
			on(X.egg(bag, Vector3.one * 0.22, CFrame.new(), Color3.new(1, 1, 1)), CFrame.new(0.22 * s, 0.62, -0.3))
			on(X.egg(bag, Vector3.one * 0.1, CFrame.new(), Color3.new(0.05, 0.05, 0.06)), CFrame.new(0.22 * s, 0.64, -0.4))
			for k = -1, 1 do
				on(EM.part(bag, Vector3.new(0.72, 0.08, 0.08), CFrame.new(), DARK), CFrame.new(0.78 * s, -0.12, 0.26 * k) * CFrame.Angles(0, 0, -0.55 * s))
			end
			table.insert(c.claws, { EM.part(bag, Vector3.new(0.14, 0.14, 0.62), CFrame.new(), SHELL), X.egg(bag, Vector3.new(0.34, 0.3, 0.52), CFrame.new(), SHELL), s })
		end
		return c
	end
	local function putCrab(c, cf, lift) -- (lift 0..1: claws up)
