		end
	end
	EM.props.CrabRave = G.guard(function(char, token, root, bag)
		local base, g = X.base(root)
		local sand = EM.part(bag, Vector3.new(0.12, 13, 13), CFrame.new(g + UP * 0.05) * CFrame.Angles(0, 0, math.pi / 2), SAND, Enum.Material.Sand, Enum.PartType.Cylinder)
		sand.Transparency = 0.15
