			lasers[i] = p
		end
		local light = Instance.new("PointLight")
		light.Range = 16
		light.Brightness = 2
		light.Color = RAVE[1]
		local lamp = EM.part(bag, Vector3.one * 0.2, CFrame.new(g + UP * 7), Color3.new(), nil)
		lamp.Transparency = 1
		light.Parent = lamp
		X.poof(g + UP * 0.6, 1.4, SAND)
		EM.beatLoop(char, token, root, entry, 16, function(b)
			light.Color = RAVE[b % #RAVE + 1]
			for i, p in lasers do
				p.Color = RAVE[(b + i) % #RAVE + 1]
			end
			if b >= 2 and b <= 5 then
				VFX.PlaySound("DirectorTick", root.Position, 0.6) -- (the claws clicking)
			elseif b == 8 then
				VFX.PlaySound("Confetti", root.Position, 0.8)
				shockDisc(g + UP * 0.2, UP, 3, 15, 0.4, RAVE[2])
				G.word(root.Position + UP * 4.6, "🦀🦀🦀", Color3.new(1, 1, 1), 40, B * 2, 1.2, bag)
			elseif b == 14 then
				VFX.PlaySound("Confetti", root.Position, 1)
				sparks(root.Position + UP * 3, 0.8, RAVE[1], RAVE[2], 22)
				shockDisc(g + UP * 0.2, UP, 3, 18, 0.45, RAVE[4])
				G.word(root.Position + UP * 4.8, "🦀 YOUR HP IS GONE 🦀", Color3.fromRGB(255, 120, 90), 28, B * 3, 1.4, nil)
			end
		end, function(t, b, frac)
			local into = math.clamp(t / (2 * B), 0, 1) -- (scuttling in over the first two beats)
			local r = 4.6 + (1 - into) ^ 2 * 10
