	local WIDE = { 0, 0, 18 }
	add({ Hips = { 0, 0, 0, 0, 0.18, 0 }, RightLeg = WIDE, LeftLeg = WIDE, RightArm = { -38, 0, 34 }, LeftArm = { -38, 0, 34 }, Waist = { 14, 0, 0 }, Neck = { 40, 0, 0 } }, 0.5, BACK, 0.12)
