		stomp = { legR = { -8, 0, 16, 4 }, legL = { 16, 0, 8, 30 }, armR = { 26, 0, 44, 10 }, armL = { 14, 0, 24, 30 }, head = { -6, 0 }, lean = -12, drop = 0.5 },
		slide = { armR = { 60, 0, 30, 20 }, armL = { -20, 0, 30, 20 }, legR = { 30, 0, 10, 40 }, legL = { -20, 0, 10, 20 }, head = { 0, 0 }, lean = -14, drop = 0.8 },
		shiver = { armR = { 34, 30, 6, 100 }, armL = { 34, 30, 6, 100 }, legR = { 0, 0, 6, 10 }, legL = { 6, 0, 6, 16 }, head = { -12, 0 }, lean = -12, drop = 0.25 },
		ignite = { armL = { 150, 0, 30, 20 }, armR = { 10, 0, 30, 30 }, legR = { -10, 0, 10, 10 }, legL = { 16, 0, 10, 20 }, head = { 18, 0 }, lean = 10, twist = 10 },
		heat = { armL = { 92, 0, 4, 0 }, armR = { -30, 0, 30, 30 }, legR = { 36, 0, 8, 50 }, legL = { -30, 0, 8, 14 }, head = { 2, -10 }, lean = -18, twist = 28, drop = 0.9 },
		flung = { armR = { 120, 0, 60, 30 }, armL = { 120, 0, 60, 30 }, legR = { 40, 0, 20, 40 }, legL = { 60, 0, 20, 60 }, head = { -30, 0 }, lean = 50, drop = 1.5 },
		down = { armR = { 100, 0, 70, 10 }, armL = { 100, 0, 70, 10 }, legR = { 10, 0, 10, 10 }, legL = { 10, 0, 10, 20 }, head = { 0, 0 }, lean = 88, drop = 3.3 },
		spent = { armR = { 8, 0, 6, 4 }, armL = { 30, 30, 10, 70 }, legR = { -10, 0, 8, 24 }, legL = { 14, 0, 8, 30 }, head = { -16, 0 }, lean = -18, drop = 0.5 },
