	-- dashes and awakenings
	QUIRK_FX.Dash.PrimeDeku = function(char, root, dir)
		afterimage(char, PV.GREEN, 0.3)
		streaks(root.Position, -dir, 6, 1.4, 6, 10, PV.GREEN, 0.25)
		bolt(root.Position, 3, PV.GREEN)
	end
	-- (round 101, awaken_e) ONE FOR ALL: PRIME on the kit (VFX.AK; his clip
	-- anim/moves_awaken_e.py's MoveAwakenPrimeDeku, his numbers
	-- Config.Awaken.PrimeDeku): crouched over a clenched fist, blackwhip
	-- curling out of his forearms - then ON THE HIT he floats up off the
	-- street, both open palms reaching out at you ((round 101 review) not
	-- flung out wide: that was Chargebolt's T from the cut-in's camera),
	-- blackwhip lashing out of them, fanned wide (none at his own lens), the
	-- eight vestiges fanned out
	-- BEHIND him, green bolts round him, a disc along the street. His aura:
	-- the rim, sparks, a green bolt off him now and then. His line (DekuAwaken,
	-- 7 s) is faded out after the release (VFX.D9.trimLine).
	function PV.awakenCfg()
		return (Config.Awaken or {}).PrimeDeku or {}
	end
	-- a blackwhip out of one of his hands to `to` (a point, or a function).
	-- ((round 101 review) a whip is ~80 parts resized every frame on every
	-- screen: one strand round its core on a low-end machine)
	function PV.lash(ctx, right, to, time, opts)
		local char = ctx.char
		if ctx.low then
			opts = table.clone(opts or {})
			opts.Strands = 1
		end
		return VFX.whipRope(function()
			return char.Parent and handPos(char, right) or nil
		end, type(to) == "function" and to or function()
			return to
		end, time, opts)
	end
	VFX.AK.FX.PrimeDeku = {
		gather = function(ctx)
			local C = PV.awakenCfg().Curls or {}
			local root = ctx.root
			local time = math.max(ctx.hit - ctx.gather, 0.06) + (C.Over or 0.05)
			-- blackwhip curling out of his forearms, close round them
			for i, right in { true, false } do
				local side = i == 1 and 1 or -1
				PV.lash(ctx, right, function()
					return root.Parent and handPos(ctx.char, right) + ctx.d:Cross(UP) * side * (C.Reach or 2.5) + UP * 0.8 or nil
				end, time, { Thick = 0.22, Wave = 1.4, Grow = 0.15 })
			end
			VFX.AK.note(ctx, "curls")
		end,
		hit = function(ctx)
			local P = PV.awakenCfg()
			local G, W = P.Ghosts or {}, P.Whips or {}
			local root, d = ctx.root, ctx.d
			local g = ctx.g or groundPoint(root.Position)
			-- the eight vestiges fanned out behind him, facing the way he does
			local n = G.Count or 8
			local spread = math.rad(G.Spread or 160)
			local back = math.atan2(-d.Z, -d.X)
			for i = 1, n do
				local a = back + (i - 0.5 - n / 2) / n * spread
				local at = g + Vector3.new(math.cos(a), 0, math.sin(a)) * (G.Radius or 9) * ctx.scale
				PV.ghost(CFrame.lookAt(at, at + d) * CFrame.new(0, -0.2, 0), i % 2 == 0 and PV.GREEN or PV.SUN, G.Life or 1.8, (G.Scale or 1.1) * ctx.scale)
			end
			VFX.AK.note(ctx, "vestiges")
			for _ = 1, ctx.low and math.ceil((P.Bolts or 10) / 2) or (P.Bolts or 10) do
				bolt(root.Position, 8, PV.GREEN)
			end
			shockDisc(g + UP * 0.5, UP, 4, P.Disc or 60, 0.5, PV.GREEN)
			-- blackwhip lashing out of both open palms, fanned forward and wide
			for i, right in { true, false } do
				local side = i == 1 and 1 or -1
				local ang = math.rad(W.Angle or 55) * side
				local dir = (d * math.cos(ang) + d:Cross(UP) * math.sin(ang) + UP * 0.15).Unit
				local tip = handPos(ctx.char, right) + dir * (W.Reach or 8) * ctx.scale
				if not VFX.AK.lens(ctx, tip, 1) then
					VFX.AK.note(ctx, "whip" .. i)
					PV.lash(ctx, right, tip, W.Time or 1, { Thick = 0.3, Wave = 0.9 })
				end
			end
		end,
		release = function(ctx)
			if VFX.D9 and VFX.D9.trimLine then
				VFX.D9.trimLine(ctx, PV.awakenCfg())
			end
		end,
		aura = function(ctx)
			local stop = VFX.AK.aura(ctx, ctx.spec.Aura or "sparks")
			local rec = VFX.AK.auras[ctx.char]
			if not rec or ctx.low then
				return stop
			end
			local A = PV.awakenCfg().Aura or {}
			task.spawn(function()
				while VFX.AK.auras[ctx.char] == rec and ctx.root.Parent do
					task.wait(A.Every or 0.6)
					if VFX.AK.auras[ctx.char] == rec and ctx.root.Parent then
						bolt(ctx.root.Position, 3 * ctx.scale, PV.GREEN)
					end
				end
			end)
			return stop
		end,
	}
	QUIRK_FX.Dash.PrimeMight = function(_char, root, dir)
		shockDisc(root.Position, dir, 2, 12, 0.25, WIND, 4)
		streaks(root.Position, -dir, 6, 1.6, 7, 12, WIND, 0.25)
	end
	-- (round 101, awaken_p) SYMBOL OF PEACE (Prime) on the awakening kit
	-- (MoveAwakenPrimeMight): a dip and a short hop up, arms up, legs tucked
	-- - and down into the superhero landing, his fist in the street: the
	-- server's crater IS the hit (and he grows on it); the gold disc flat on
	-- the street, the streaks, the sun ring, the dust blown out of the
	-- crater in a big ring, rocks
	VFX.AK.FX.PrimeMight = {
		press = function(ctx)
			-- (the push off the street at the dip)
			if not ctx.g then
				return
			end
			task.spawn(function()
				if VFX.AK.at(ctx, 0.06) then
					dustPuffs(ctx.g, 0.9 * ctx.scale, ctx.low and 3 or 6, Color3.fromRGB(206, 196, 186), 0.6, false)
					shockDisc(ctx.g + UP * 0.15, UP, 2, 10 * ctx.scale, 0.25, WIND)
				end
			end)
		end,
		hit = function(ctx)
			local C = VFX.AK.P.cfg("PrimeMight")
			local root, s = ctx.root, ctx.scale
			local g = ctx.g or (root.Position - UP * 3 * s)
			-- (flat on the street: his landing's camera is low)
			shockDisc(g + UP * 0.15, UP, 6, (C.Disc or 90) * s, 0.6, PV.GOLD)
			streaks(g, UP, ctx.low and 15 or (C.Streaks or 30), 4 * s, 20 * s, 110 * s, WIND, 0.6)
			billboardRing(root.Position + UP * 2 * s, 4, (C.Ring or 50) * s, PV.SUN, 12, 0.5)
			if ctx.g then
				local D = C.Dust or {}
				local n = math.max(math.floor((D.Count or 16) * (ctx.low and 0.5 or 1)), 4)
				for i = 1, n do
					local a = (i - 0.5) / n * math.pi * 2
					local out = Vector3.new(math.cos(a), 0, math.sin(a))
					local from = g + out * (D.From or 4) * s + UP * s
					local to = g + out * (D.To or 22) * s * rand(0.85, 1.1) + UP * 1.6 * s
					if not VFX.AK.lens(ctx, (from + to) / 2, 2.5 * s) and not VFX.AK.lens(ctx, to, 2.5 * s) then
						local puff = newPart(Vector3.one * 3 * s, CFrame.new(from), Color3.fromRGB(206, 196, 186), Enum.Material.SmoothPlastic, Enum.PartType.Ball)
						puff.Name = "AwakenCraterDust"
						puff.Transparency = 0.25
						tween(puff, 0.7, { CFrame = CFrame.new(to), Size = Vector3.new(7, 2.6, 7) * s, Transparency = 1 }, Enum.EasingStyle.Quad, Enum.EasingDirection.Out)
						cleanup(puff, 0.75)
					end
				end
				-- (rocks fly anywhere: not on his own screen, where they'd cross the lens)
				if not ctx.low and not ctx.mine then
					rocks(g, 1.6 * s, 10)
				end
			end
			VFX.AK.note(ctx, "landing")
		end,
	}
end

---------------------------------------------------------------------------
-- (round 74) DIO: THE WORLD
---------------------------------------------------------------------------
-- Stopped time on every screen: the sphere of it rolling out from him and
-- back, the colour going out of the world (negative first, then grey), a
-- clock ticking, everyone caught frozen mid-move (their pose layer held,
-- their animation tracks stopped). His hits in it hang there as gold marks
-- on them; his knives stop in the air a few studs out. When it moves again
-- the marks burst and the knives fly on.
do
	local DV = {
		GOLD = Color3.fromRGB(255, 214, 70),
		TEAL = Color3.fromRGB(70, 210, 176),
		NEG = Color3.fromRGB(150, 96, 255),
		RED = Color3.fromRGB(200, 20, 40),
		YELLOW = Color3.fromRGB(240, 196, 30),
		STEEL = Color3.fromRGB(112, 114, 120),
		BLACK = Color3.fromRGB(28, 28, 32),
		stops = setmetatable({}, { __mode = "k" }), -- [his character] = { Until, Frozen, Done }
		marks = setmetatable({}, { __mode = "k" }), -- [a stopped body] = { parts }
		rollers = setmetatable({}, { __mode = "k" }), -- [his character] = the road roller
	}
	VFX.DV = DV
	local CDV = VFX.CDV
	local Lighting = game:GetService("Lighting")

	POSES.ZaWarudo = { RightArm = { 150, 0, -30 }, LeftArm = { 40, 0, 60 }, Waist = { 16, -22, 0 }, Neck = { 22, 18, 0 }, RightLeg = { -10, 0, 12 }, LeftLeg = { 16, 0, 6 } }
	POSES.VampireHold = { RightArm = { 100, 0, -4 }, LeftArm = { 20, 0, 24 }, Waist = { -10, 12, 0 }, Neck = { -8, -10, 0 }, RightLeg = { -14, 0, 6 }, LeftLeg = { 18, 0, 4 } }
	POSES.StingyEyes = { RightArm = { 70, 0, -20 }, LeftArm = { 30, 0, 24 }, Waist = { -16, 8, 0 }, Neck = { -8, -6, 0 }, RightLeg = { -12, 0, 6 }, LeftLeg = { 16, 0, 4 } }
	POSES.Wry = { RightArm = { 150, 0, -32 }, LeftArm = { 150, 0, -32 }, Waist = { 22, 0, 0 }, Neck = { 42, 0, 0 }, RightLeg = { -6, 0, 10 }, LeftLeg = { 10, 0, 10 } }
	POSES.MudaDownR = { RightArm = { 40, 0, -6 }, LeftArm = { 120, 0, 20 }, Waist = { -44, 20, 0 }, Neck = { -16, -10, 0 }, RightLeg = { -20, 0, 8 }, LeftLeg = { 30, 0, 6 } }
	POSES.MudaDownL = { LeftArm = { 40, 0, -6 }, RightArm = { 120, 0, 20 }, Waist = { -44, -20, 0 }, Neck = { -16, 10, 0 }, RightLeg = { -20, 0, 8 }, LeftLeg = { 30, 0, 6 } }

	SHOTS.ZaWarudo = {
		{ T = 0.3, From = { V(1.6, 1.9, -3.6), V(0, 1.7, 0) }, To = { V(1.2, 1.8, -2.9), V(0, 1.7, 0) }, Fov = { 46, 36 } },
		{ T = 0.45, Cut = true, From = { V(-5, 2.5, -9), V(0, 3, 1.5) }, To = { V(-8, 5, -16), V(0, 4, 1.5) }, Fov = { 60, 78 }, Style = Enum.EasingStyle.Quad },
	}
	SHOTS.RoadRoller = {
		{ T = 0.55, Follow = true, From = { V(3, -4, -8), "root" }, To = { V(5, -8, -14), "root" }, Fov = { 60, 74 } },
		{ T = 0.4, Cut = true, Follow = true, From = { V(-16, 8, -18), "root" }, To = { V(-18, 5, -20), "root" }, Fov = { 62, 66 } },
		{ T = 1.25, Cut = true, Follow = true, From = { V(6, 3, -6), "root" }, To = { V(5, 2.4, -4.6), "root" }, Fov = { 56, 46 } },
		{ T = 0.8, Cut = true, Follow = true, From = { V(0, -1.5, -7), "root" }, To = { V(0, -2.5, -9), "root" }, Fov = { 52, 64 } },
	}

	local function me()
		return Players.LocalPlayer and Players.LocalPlayer.Character
	end

	-- is the time he stopped still stopped? (his knives wait on it)
	function DV.stoppedBy(char)
		local s = char and DV.stops[char]
		return s ~= nil and not s.Done and os.clock() < s.Until + 1.5
	end

	-- the colour of stopped time on this screen
	function DV.grade(on)
		local cc = Lighting:FindFirstChild("TimeStopCC")
		if on then
			if not cc then
				cc = Instance.new("ColorCorrectionEffect")
				cc.Name = "TimeStopCC"
				cc.Parent = Lighting
			end
			cc.Enabled = true
			-- the negative first...
			tween(cc, 0.18, { TintColor = DV.NEG, Saturation = 0.4, Contrast = 0.9, Brightness = -0.08 })
			-- ...then the world goes grey and still
			task.delay(0.55, function()
				if cc.Parent then
					tween(cc, 0.4, { TintColor = Color3.fromRGB(236, 226, 206), Saturation = -0.88, Contrast = 0.2, Brightness = -0.04 })
				end
			end)
		elseif cc then
			tween(cc, 0.18, { TintColor = DV.NEG, Saturation = 0.3, Contrast = 0.7 })
			task.delay(0.2, function()
				if cc.Parent then
					tween(cc, 0.35, { TintColor = Color3.new(1, 1, 1), Saturation = 0, Contrast = 0, Brightness = 0 })
					cleanup(cc, 0.4)
				end
			end)
		end
	end

	-- a body's animation tracks held (or let go)
	function DV.holdTracks(model, on)
		local hum = model and model:FindFirstChildOfClass("Humanoid")
		local animator = hum and hum:FindFirstChildOfClass("Animator")
		if not animator then
			return
		end
		pcall(function()
			for _, track in animator:GetPlayingAnimationTracks() do
				track:AdjustSpeed(on and 0 or 1)
			end
		end)
	end

	-- R: ZA WARUDO! (the call, and The World throwing its arms wide)
	function Effects.ZaWarudo(char, _data, isLocal)
		local root = charParts(char)
		if not root then
			return
		end
		VFX.Pose(char, "ZaWarudo", 1.2)
		local st = CDV and CDV.act(char, "rage", 1.3)
		if st then
			CDV.shout(st, "ZA WARUDO!!", 9, 1.3)
		end
		VFX.SpeechBubble(char, (Config.Voice.ZaWarudo or {}).Bubble or "ZA WARUDO!", 1.4)
		VFX.Voice("ZaWarudo", root)
		VFX.PlaySound("ZaWarudo", root.Position, 1)
		if isLocal then
			VFX.Cinematic(char, SHOTS.ZaWarudo, { Title = "ZA WARUDO!", Color = DV.GOLD, Own = true })
		end
	end

	-- time stops
	function Effects.TimeStop(char, data)
		local root = charParts(char)
		if not root then
			return
		end
		local dur = tonumber(data.Duration) or 5
		local radius = tonumber(data.Radius) or 220
		local stop = { Until = os.clock() + dur, Frozen = type(data.Frozen) == "table" and data.Frozen or {}, Done = false }
		DV.stops[char] = stop
		local c = root.Position
		-- the sphere rolls out from him... and back
		local ball = newPart(Vector3.one * 2, CFrame.new(c), DV.NEG, Enum.Material.ForceField, Enum.PartType.Ball)
		ball.Transparency = 0.1
		tween(ball, 0.5, { Size = Vector3.one * math.min(radius * 2, 400) }, Enum.EasingStyle.Quad, Enum.EasingDirection.Out)
		tween(ball, 0.35, { Size = Vector3.one * 2, Transparency = 0.6 }, Enum.EasingStyle.Quad, Enum.EasingDirection.In, 0.55)
		cleanup(ball, 0.95)
		local core = newPart(Vector3.one * 1, CFrame.new(c), Color3.new(1, 1, 1), Enum.Material.Neon, Enum.PartType.Ball)
		tween(core, 0.2, { Size = Vector3.one * 10, Transparency = 1 })
		cleanup(core, 0.25)
		billboardRing(c + UP * 2, 3, 60, DV.NEG, 12, 0.5)
		VFX.PlaySound("TimeStop", c, 1)
		-- this screen: inside it, or his
		local mine = me()
		local mr = mine and mine:FindFirstChild("HumanoidRootPart")
		local inside = mine == char or (mr ~= nil and (mr.Position - c).Magnitude <= radius)
		stop.Graded = inside
		if inside then
			DV.grade(true)
			VFX.Hooks.Callout(mine == char and "TIME HAS STOPPED" or "...TIME HAS STOPPED", DV.GOLD)
		end
		-- everyone caught, frozen mid-move
		for _, m in stop.Frozen do
			if typeof(m) == "Instance" and m.Parent then
				VFX.Hitstop(m, dur + 0.1)
				DV.holdTracks(m, true)
			end
		end
		-- the clock ticking; he counts the seconds
		task.spawn(function()
			local n = 0
			while not stop.Done and os.clock() < stop.Until do
				task.wait(1)
				if stop.Done or os.clock() > stop.Until + 0.05 then
					break
				end
				n += 1
				VFX.PlaySound("ClockTick", c, 0.9)
				if me() == char then
					VFX.Hooks.Callout(n == 1 and "1 SECOND HAS PASSED" or (n .. " SECONDS HAVE PASSED"), DV.GOLD)
				end
			end
		end)
	end

	-- ...and moves again
	function Effects.TimeResume(char, data)
		local stop = DV.stops[char]
		if stop then
			stop.Done = true
			DV.stops[char] = nil
		end
		local root = charParts(char)
		if root then
			VFX.SpeechBubble(char, (Config.Voice.TimeResume or {}).Bubble or "TOKI WA UGOKIDASU...", 1.6)
			VFX.Voice("TimeResume", root)
			VFX.PlaySound("TimeResume", root.Position, 1)
			shockDisc(root.Position, UP, 2, 60, 0.4, DV.NEG)
		end
		local still = false
		for _, s in DV.stops do
			if not s.Done and s.Graded then
				still = true
			end
		end
		if (not stop or stop.Graded) and not still then
			DV.grade(false)
		end
		for _, m in type(data.Frozen) == "table" and data.Frozen or (stop and stop.Frozen) or {} do
			if typeof(m) == "Instance" then
				DV.holdTracks(m, false)
				local list = DV.marks[m]
				DV.marks[m] = nil
				local tr = m:FindFirstChild("HumanoidRootPart")
				for _, p in list or {} do
					if p.Parent then
						sparks(p.Position, 0.7, Color3.new(1, 1, 1), DV.GOLD, 8)
						p:Destroy()
					end
				end
				if list and #list > 0 and tr then
					billboardRing(tr.Position, 2, 16, DV.GOLD, 8, 0.25)
					VFX.PlaySound("HeavyHit", tr.Position, 1)
				end
			end
		end
	end

	-- a hit on someone in stopped time: it hangs on them, gold, until it lands
	function Effects.TimeHit(_, data)
		local target = typeof(data.Target) == "Instance" and data.Target
		local tr = target and target:FindFirstChild("HumanoidRootPart")
		if not tr then
			return
		end
		local from = typeof(data.From) == "Vector3" and data.From or tr.Position + tr.CFrame.LookVector * 3
		local toward = from - tr.Position
		toward = toward.Magnitude > 0.1 and toward.Unit or tr.CFrame.LookVector
		local at = tr.Position + toward * 1.1 + Vector3.new(rand(-0.8, 0.8), rand(-0.6, 1.4), rand(-0.8, 0.8))
		local size = data.Heavy and 1.1 or 0.6
		local star = newPart(Vector3.new(size, size, 0.1), CFrame.lookAt(at, at + toward) * CFrame.Angles(0, 0, rand(0, 3)), DV.GOLD, Enum.Material.Neon)
		local star2 = newPart(Vector3.new(size * 0.4, size * 1.8, 0.08), star.CFrame * CFrame.Angles(0, 0, math.rad(45)), Color3.new(1, 1, 1), Enum.Material.Neon)
		cleanup(star, 14)
		cleanup(star2, 14)
		local list = DV.marks[target] or {}
		DV.marks[target] = list
		table.insert(list, star)
		table.insert(list, star2)
		VFX.PlaySound("Hit", at, 0.35)
	end
	function Effects.TimeHits(_, data)
		local target = typeof(data.Target) == "Instance" and data.Target
		local tr = target and target:FindFirstChild("HumanoidRootPart")
		if tr then
			sparks(tr.Position, 1.2, Color3.new(1, 1, 1), DV.GOLD, 10 + math.min(tonumber(data.Count) or 1, 20) * 2)
			shockDisc(tr.Position, UP, 2, 14, 0.25, DV.GOLD)
		end
	end

	-- 1: MUDA MUDA MUDA! (the rush, Crazy Diamond's frame in gold)
	function Effects.MudaRush(char, data, isLocal, ability)
		VFX.Pose(char, "StandUser", 0.7)
		local root = charParts(char)
		if not root or not CDV then
			return
		end
		ability = ability or {}
		local d = flatten(data.Dir, root)
		if isLocal then
			face(root, d)
		end
		local hits, interval = ability.Hits or 16, ability.Interval or 0.075
		if char:GetAttribute("UltActive") then
			hits, interval = 24, 0.06
		end
		local total = 0.15 + hits * interval
		local st = CDV.act(char, "barrage", total)
		if not st then
			return
		end
		CDV.shout(st, char:GetAttribute("UltActive") and "MUDA MUDA MUDA MUDA!!" or "MUDA MUDA MUDA!", 8, total)
		for k = 1, hits do
			task.delay(0.15 + (k - 1) * interval, function()
				if not root.Parent then
					return
				end
				VFX.PlaySound("Dora", root.Position, 0.55)
				if k % 2 == 0 then
					local front = root.Position + flatten(root.CFrame.LookVector, root) * 4.5 + UP * 0.8
					sparks(front + Vector3.new(rand(-1, 1), rand(-0.6, 1), rand(-1, 1)), 0.5, Color3.new(1, 1, 1), DV.GOLD, 5)
				end
				if k % 6 == 0 then
					CDV.shout(st, "MUDA!", 4, 0.4)
				end
			end)
		end
		task.wait(total)
		if not root.Parent then
			return
		end
		CDV.act(char, "punchR", 0.45)
		CDV.shout(st, "MUDA!!", 5, 0.8)
		local dd = flatten(root.CFrame.LookVector, root)
		local fist = root.Position + dd * 5 + UP
		VFX.PlaySound("DoraFinish", fist, 1)
		shockDisc(fist, dd, 2, 16, 0.3, WIND, 8)
		billboardRing(fist, 2, 18, DV.GOLD, 6, 0.3)
		streaks(fist, dd, 12, 2, 8, 22, WIND, 0.3)
		VFX.ShakeAt(fist, 2.4, 80, 0.3)
		if nearCamera(fist, 60) then
			VFX.ImpactFrame(0.08)
		end
	end

	-- 2: KNIVES
	function Effects.KnifeVolley(char, data, isLocal)
		local root = charParts(char)
		if root and isLocal and typeof(data.Dir) == "Vector3" then
			face(root, flatten(data.Dir, root))
		end
		VFX.Motion(char, "DaggerShot")
		if root then
			VFX.PlaySound("KnifeThrow", root.Position, 1)
		end
	end
	-- one knife: in stopped time it stops a few studs out and waits
	function Effects.DioKnife(char, data)
		local from, to = data.From, data.To
		local TWV = VFX.TW
		if typeof(from) ~= "Vector3" or typeof(to) ~= "Vector3" or not TWV then
			return
		end
		local v = to - from
		local dist = v.Magnitude
		if dist < 0.5 then
			return
		end
		local d = v.Unit
		local speed = tonumber(data.Speed) or 200
		local k = TWV.knife(CFrame.lookAt(from, to))
		task.spawn(function()
			local start = from
			if data.Stopped and DV.stoppedBy(char) then
				-- out a few studs, then it hangs there
				local stopAt = from + d * math.min(dist * 0.5, rand(3.5, 7))
				local t0 = os.clock()
				while os.clock() - t0 < 0.07 do
					k.set(CFrame.lookAt(from:Lerp(stopAt, (os.clock() - t0) / 0.07), to))
					task.wait()
				end
				k.set(CFrame.lookAt(stopAt, to))
				local held = os.clock()
				while DV.stoppedBy(char) and os.clock() - held < 12 do
					task.wait(0.05)
				end
				start = stopAt
			end
			local left = (to - start).Magnitude
			local time = math.clamp(left / speed, 0.04, 0.8)
			local t0 = os.clock()
			while os.clock() - t0 < time do
				local a = (os.clock() - t0) / time
				k.set(CFrame.lookAt(start:Lerp(to, a), to) * CFrame.Angles(0, 0, a * 20))
				task.wait()
			end
			k.set(CFrame.lookAt(to - d * 0.3, to))
			if typeof(data.Hit) == "Instance" then
				sparks(to, 0.5, Color3.new(1, 1, 1), DV.GOLD, 5)
				VFX.PlaySound("KnifeHit", to, 0.8)
				k.gone(0.1)
			else
				task.delay(1.2, k.gone, 0.3)
			end
		end)
	end

	-- ULT 2: KNIVES - NOWHERE TO RUN: a ring of them, hanging, then all in
	function Effects.KnifeRing(char, data, isLocal)
		Effects.KnifeVolley(char, data, isLocal)
	end
	function Effects.KnifeRingSet(char, data)
		local center = typeof(data.Pos) == "Vector3" and data.Pos
		local TWV = VFX.TW
		if not center or not TWV then
			return
		end
		local n, ring = tonumber(data.Count) or 20, tonumber(data.Ring) or 7
		local knives = {}
		for i = 1, n do
			local a = i / n * math.pi * 2
			local y = ({ 0.4, 1.8, -0.5 })[i % 3 + 1]
			local p = center + Vector3.new(math.cos(a) * ring, y, math.sin(a) * ring)
			task.delay(i * 0.012, function()
				local kn = TWV.knife(CFrame.lookAt(p, center + UP * y * 0.3))
				knives[i] = { k = kn, p = p }
				sparks(p, 0.2, Color3.new(1, 1, 1), DV.GOLD, 2)
			end)
		end
		VFX.PlaySound("KnifeThrow", center, 1)
		task.wait(n * 0.012 + 0.05)
		if data.Stopped and DV.stoppedBy(char) then
			local held = os.clock()
			while DV.stoppedBy(char) and os.clock() - held < 12 do
				task.wait(0.05)
			end
			task.wait(0.05)
		else
			task.wait(math.max((tonumber(data.Hang) or 0.7) - n * 0.012, 0.1))
		end
		for _, e in knives do
			local t0 = os.clock()
			task.spawn(function()
				while os.clock() - t0 < 0.12 do
					e.k.set(CFrame.lookAt(e.p:Lerp(center, (os.clock() - t0) / 0.12), center))
					task.wait()
				end
				e.k.gone(0.1)
			end)
		end
		task.wait(0.12)
		sparks(center, 1.4, Color3.new(1, 1, 1), DV.GOLD, 30)
		billboardRing(center, 2, 18, DV.GOLD, 8, 0.25)
		VFX.PlaySound("KnifeHit", center, 1.2)
		VFX.ShakeAt(center, 1.6, 60, 0.25)
	end

	-- 3: VAMPIRE
	function Effects.VampireDrain(char, data, isLocal)
		local root = charParts(char)
		if root and isLocal then
			face(root, flatten(data.Dir, root))
		end
		VFX.Pose(char, "VampireHold", 0.45)
	end
	function Effects.VampireGrab(char, data)
		local root = charParts(char)
		local target = typeof(data.Target) == "Instance" and data.Target
		if not root then
			return
		end
		if not target then
			VFX.Pose(char, "VampireHold", 0.3)
			return
		end
		local time = tonumber(data.Time) or 1.2
		VFX.Pose(char, "VampireHold", time + 0.2)
		VFX.Pose(target, "Stagger", time)
		VFX.PlaySound("Drain", root.Position, 1)
		local head = target:FindFirstChild("Head")
		local t0 = os.clock()
		while os.clock() - t0 < time and root.Parent and target.Parent do
			local from = (head and head.Position) or root.Position
			local to = handPos(char, true)
			for _ = 1, 2 do
				local drop = newPart(Vector3.one * 0.3, CFrame.new(from + rng:NextUnitVector() * 0.6), DV.RED, Enum.Material.Neon, Enum.PartType.Ball)
				tween(drop, 0.22, { CFrame = CFrame.new(to), Size = Vector3.one * 0.12 }, Enum.EasingStyle.Quad, Enum.EasingDirection.In)
				cleanup(drop, 0.24)
			end
			if rng:NextNumber() < 0.3 and VFX.BLOOD then
				VFX.BLOOD.spray(from, rng:NextUnitVector(), 3, 6, 0.4)
			end
			sparks(root.Position + UP, 0.3, DV.RED, DV.GOLD, 2)
			task.wait(0.08)
		end
	end

	-- 4: SPACE RIPPER STINGY EYES
	function DV.eyes(char)
		local head = char:FindFirstChild("Head")
		if not head then
			return nil
		end
		local cf = head.CFrame
		local s = head.Size
		return (cf * CFrame.new(-s.X * 0.18, s.Y * 0.08, -s.Z * 0.5)).Position, (cf * CFrame.new(s.X * 0.18, s.Y * 0.08, -s.Z * 0.5)).Position
	end
	function Effects.SpaceRipper(char, data, isLocal)
		local root = charParts(char)
		if not root then
			return
		end
		if isLocal then
			face(root, flatten(data.Dir, root))
		end
		VFX.Pose(char, "StingyEyes", 0.6)
		VFX.PlaySound("PlasmaCharge", root.Position, 0.6)
		local t0 = os.clock()
		while os.clock() - t0 < 0.3 and root.Parent do
			local a, b = DV.eyes(char)
			if a then
				for _, p in { a, b } do
					local glint = newPart(Vector3.one * 0.25, CFrame.new(p), Color3.fromRGB(220, 240, 255), Enum.Material.Neon, Enum.PartType.Ball)
					tween(glint, 0.06, { Size = Vector3.one * 0.5, Transparency = 1 })
					cleanup(glint, 0.08)
				end
			end
			task.wait(0.04)
		end
	end
	function Effects.SpaceRipperBeam(char, data)
		local to = typeof(data.To) == "Vector3" and data.To
		if not to then
			return
		end
		local a, b = DV.eyes(char)
		a = a or (typeof(data.From) == "Vector3" and data.From) or to
		b = b or a
		for i, from in { a, b } do
			local tip = to + (i == 1 and -1 or 1) * (to - from):Cross(UP).Unit * 0.25
			local len = (tip - from).Magnitude
			local beam = newPart(Vector3.new(0.22, 0.22, len), CFrame.lookAt((from + tip) / 2, tip), Color3.fromRGB(226, 244, 255), Enum.Material.Neon)
			tween(beam, 0.25, { Size = Vector3.new(0.04, 0.04, len), Transparency = 1 }, nil, nil, 0.08)
			cleanup(beam, 0.35)
			billboardRing(from, 0.3, 3, Color3.new(1, 1, 1), 3, 0.15)
		end
		sparks(to, 0.9, Color3.new(1, 1, 1), Color3.fromRGB(160, 210, 255), 16)
		shockDisc(to, (to - a).Unit, 1, 8, 0.2, Color3.fromRGB(200, 230, 255))
		VFX.PlaySound("EyeBeam", a, 1)
		VFX.ShakeAt(to, 1.2, 60, 0.2)
	end

	-- the road roller: a yellow body, the steel drum up front, the cab, the
	-- rear wheels (origin: the middle of it, on the street)
	function DV.roller(cf)
		local m = Instance.new("Model")
		m.Name = "RoadRoller"
		m.Parent = folder
		local parts = {}
		local function p(size, off, color, material, shape)
			local part = newPart(size, cf * off, color, material or Enum.Material.SmoothPlastic, shape, m)
			table.insert(parts, { part = part, off = off })
			return part
		end
		p(Vector3.new(9, 4, 10), CFrame.new(0, 3.6, 1.6), DV.YELLOW)
		p(Vector3.new(10.4, 6.2, 6.2), CFrame.new(0, 3.1, -5.2), DV.STEEL, Enum.Material.Metal, Enum.PartType.Cylinder)
		p(Vector3.new(10.8, 1, 1), CFrame.new(0, 3.1, -5.2), DV.BLACK, Enum.Material.Metal, Enum.PartType.Cylinder)
		p(Vector3.new(9.6, 1, 7.4), CFrame.new(0, 6.3, -4.2), DV.YELLOW)
		p(Vector3.new(6, 4.2, 5), CFrame.new(0, 7.7, 3.2), DV.YELLOW)
		p(Vector3.new(6.1, 2, 4.2), CFrame.new(0, 8.3, 3.2), DV.BLACK, Enum.Material.Glass)
		p(Vector3.new(6.6, 0.5, 5.6), CFrame.new(0, 10, 3.2), DV.BLACK)
		for side = -1, 1, 2 do
			p(Vector3.new(1.4, 5, 5), CFrame.new(side * 4.9, 2.5, 5.4), DV.BLACK, Enum.Material.SmoothPlastic, Enum.PartType.Cylinder)
		end
		p(Vector3.new(0.5, 3, 0.5), CFrame.new(2.6, 8.8, -0.6), DV.BLACK, Enum.Material.Metal)
		local plate = p(Vector3.new(0.2, 2.2, 7), CFrame.new(4.62, 3.8, 1.6), DV.YELLOW)
		local sg = Instance.new("SurfaceGui")
		sg.Face = Enum.NormalId.Right
		sg.CanvasSize = Vector2.new(560, 180)
		sg.LightInfluence = 0.3
		sg.Parent = plate
		local label = Instance.new("TextLabel")
		label.BackgroundTransparency = 1
		label.Size = UDim2.fromScale(1, 1)
		label.Font = Enum.Font.LuckiestGuy
		label.TextScaled = true
		label.Text = "ROAD ROLLER"
		label.TextColor3 = DV.BLACK
		label.Parent = sg
		local r = { model = m, parts = parts }
		function r.set(newCf)
			for _, e in parts do
				e.part.CFrame = newCf * e.off
			end
			r.cf = newCf
		end
		r.cf = cf
		return r
	end

	-- ULT 3: ROAD ROLLER DA!
	function Effects.RoadRoller(char)
		local root = charParts(char)
		if root then
			dustPuffs(groundPoint(root.Position), 1, 5, Color3.fromRGB(206, 198, 188), 0.7, true)
		end
	end
	function Effects.RoadRollerGo(char, data)
		local root = charParts(char)
		local spot = typeof(data.Pos) == "Vector3" and data.Pos
		if not root or not spot then
			return
		end
		local d = typeof(data.Dir) == "Vector3" and data.Dir or Vector3.new(0, 0, -1)
		local target = typeof(data.Target) == "Instance" and data.Target or nil
		local mine = me()
		if mine == char or mine == target then
			VFX.Cinematic(char, SHOTS.RoadRoller, { Title = "ROAD ROLLER DA!", Color = DV.GOLD, Own = mine == char })
		end
		VFX.Pose(char, "Wry", 0.9)
		local t0 = os.clock()
		local function at_(t)
			local left = t - (os.clock() - t0)
			if left > 0 then
				task.wait(left)
			end
		end
		at_(0.35)
		VFX.SpeechBubble(char, (Config.Voice.RoadRoller or {}).Bubble or "ROAD ROLLER DA!!", 1.4)
		VFX.Voice("RoadRoller", root)
		local rot = CFrame.lookAt(Vector3.zero, d)
		local roller = DV.roller(CFrame.new(spot + UP * 46) * rot * CFrame.Angles(math.rad(-20), 0, 0))
		DV.rollers[char] = roller
		at_(0.55)
		-- down, with him on it
		local from = roller.cf
		local land = CFrame.new(spot) * rot * CFrame.Angles(math.rad(-6), 0, math.rad(4))
		while os.clock() - t0 < 0.89 do
			local k = math.clamp((os.clock() - t0 - 0.55) / 0.34, 0, 1) ^ 1.8
			roller.set(from:Lerp(land, k))
			task.wait()
		end
		roller.set(land)
		shockDisc(spot + UP * 0.5, UP, 8, 60, 0.45, WIND)
		dustPuffs(spot, 2.6, 12, Color3.fromRGB(206, 196, 186), 1.4, true)
		rocks(spot, 2.4, 18)
		groundMark(spot, 9, Color3.fromRGB(52, 46, 44), 8)
		VFX.PlaySound("RoadRollerLand", spot, 1.2)
		VFX.ShakeAt(spot, 4, 200, 0.5)
		-- MUDA MUDA MUDA on it
		local st = CDV and CDV.act(char, "barrage", 1.25)
		if st then
			CDV.shout(st, "MUDA MUDA MUDA!!", 9, 1.25)
		end
		local hits = tonumber(data.Hits) or 10
		for i = 1, hits do
			if not root.Parent then
				break
			end
			VFX.Pose(char, i % 2 == 0 and "MudaDownL" or "MudaDownR", 0.1)
			local top = roller.cf * CFrame.new(rand(-3, 3), 6.4, rand(-6, 0))
			sparks(top.Position, 0.8, Color3.new(1, 1, 1), DV.GOLD, 8)
			roller.set(roller.cf * CFrame.new(0, -0.12, 0) * CFrame.Angles(math.rad(rand(-1, 1)), 0, math.rad(rand(-1, 1))))
			VFX.PlaySound("Dora", top.Position, 0.8)
			if i % 3 == 0 then
				VFX.PlaySound("MachineHit", top.Position, 0.7)
				VFX.ShakeAt(spot, 1.4, 90, 0.12)
			end
			task.wait(0.12)
		end
		if root.Parent then
			VFX.Pose(char, "Wry", 0.9)
			VFX.SpeechBubble(char, (Config.Voice.Wry or {}).Bubble or "WRYYYYYYY!!", 1.4)
			VFX.Voice("Wry", root)
		end
	end
	function Effects.RoadRollerBoom(char, data)
		local pos = typeof(data.Pos) == "Vector3" and data.Pos
		if not pos then
			return
		end
		local roller = DV.rollers[char]
		DV.rollers[char] = nil
		if roller then
			for _, e in roller.parts do
				local part = e.part
				if part.Parent then
					part.Anchored = false
					part.CanCollide = false
					part.AssemblyLinearVelocity = rng:NextUnitVector() * rand(20, 50) + UP * rand(30, 70)
					part.AssemblyAngularVelocity = rng:NextUnitVector() * 8
					tween(part, 0.6, { Transparency = 1 }, nil, nil, 0.8)
				end
			end
			cleanup(roller.model, 1.5)
		end
		toonExplosion(pos + UP * 3, 3.2)
		shockDisc(pos + UP * 0.5, UP, 8, 90, 0.55, DV.GOLD)
		billboardRing(pos + UP * 4, 4, 50, Color3.new(1, 1, 1), 12, 0.4)
		if nearCamera(pos, 180) then
			VFX.ImpactFrame(0.12)
			VFX.Hooks.Flash(Color3.fromRGB(255, 236, 190), 0.4)
		end
		VFX.PlaySound("RoadRollerBoom", pos, 1.2)
		VFX.ShakeAt(pos, 5, 260, 0.9)
	end

	-- dashes and the awakening
	QUIRK_FX.Dash.TheWorld = function(char, root, dir)
		afterimage(char, DV.GOLD, 0.25)
		streaks(root.Position, -dir, 4, 1.2, 5, 8, DV.GOLD, 0.2)
	end
	-- (round 101, awaken_p) DIO'S WORLD on the awakening kit
	-- (MoveAwakenTheWorld): a hand over his face, turned, The World looming
	-- up behind him - then WRY: the back-bend, arms flung up and out, head
	-- thrown right back, The World flinging its arms out behind him; THE
	-- NEGATIVE on his own screen (his own impact pair, a clock's tick); the
	-- NEG ring, the gold disc. (Said once: his line and the shout panel - the
	-- Stand doesn't shout it too.)
	VFX.AK.FX.TheWorld = {
		press = function(ctx)
			if CDV and CDV.loom then
				CDV.loom(ctx, (VFX.AK.P.cfg("TheWorld").Stand or {}).Loom)
			end
		end,
		impact = function(ctx)
			return VFX.AK.P.pair(ctx, VFX.AK.P.cfg("TheWorld").Negative, "ClockTick")
		end,
		hit = function(ctx)
			local root, s = ctx.root, ctx.scale
			local g = ctx.g or (root.Position - UP * 3 * s)
			if CDV then
				CDV.act(ctx.char, "rage", (VFX.AK.P.cfg("TheWorld").Stand or {}).Rage or 1.3, "awaken") -- (Josuke's awakening spot: clear of him)
				VFX.AK.note(ctx, "stand")
			end
			shockDisc(g + UP * 0.3, UP, 4, 70 * s, 0.55, DV.GOLD)
			billboardRing(root.Position + UP * 2 * s, 3, 40 * s, DV.NEG, 10, 0.45)
		end,
	}
end

---------------------------------------------------------------------------
-- (round 75) PRIME DEKU's FLASH STEP, slowed down and shot like the anime:
-- he GLITCHES out (the body flickering, a green and a magenta copy torn off
-- either side of him, scanlines through him) - and when he's behind her it
-- glitches him back in, slow: the camera walks round from the left of her
-- face to behind her shoulder where he's standing, cuts wide as the right
-- arm draws back with the lightning running up it, and the big punch
---------------------------------------------------------------------------
do
	local PV = VFX.PV
	PV.MAGENTA = Color3.fromRGB(255, 70, 210)
	PV.glitching = setmetatable({}, { __mode = "k" }) -- [char] = token

	function PV.me()
		return Players.LocalPlayer and Players.LocalPlayer.Character
	end
	function PV.setShown(char, shown)
		for _, d in char:GetDescendants() do
			if (d:IsA("BasePart") or d:IsA("Decal")) and d.Name ~= "HumanoidRootPart" then
				d.LocalTransparencyModifier = shown and 0 or 1
			end
		end
	end

	-- the big punch: drawn right back (chest turned away, eyes still on her),
	-- then thrown through - chest round, the arm dead straight
	POSES.PrimeBigPunchWind = {
		Crouch = 0.55, Waist = { -8, -40, 0 }, Neck = { -4, 32, 0 },
		RightArm = { -62, 0, 30 }, LeftArm = { 80, 0, -12 }, RightElbow = 110, LeftElbow = 20,
		RightLeg = { -30, 0, 10 }, LeftLeg = { 32, 0, 6 }, LeftKnee = 40,
	}
	POSES.PrimeBigPunch = {
		Crouch = 0.45, Waist = { -18, 44, 0 }, Neck = { -6, -34, 0 },
		RightArm = { 100, 0, -6 }, LeftArm = { -40, 0, 28 }, LeftElbow = 60,
		RightLeg = { -36, 0, 8 }, LeftLeg = { 42, 0, 4 }, LeftKnee = 50,
	}

	-- glitching: `mode` "out" (there less and less) or "in" (more and more);
	-- he's left shown at the end either way (the caller hides him)
	function PV.glitch(char, duration, mode)
		local root = charParts(char)
		if not root then
			return
		end
		local token = {}
		PV.glitching[char] = token
		local body = {}
		for _, name in { "Head", "Torso", "Left Arm", "Right Arm", "Left Leg", "Right Leg", "UpperTorso", "LowerTorso" } do
			local p = char:FindFirstChild(name)
			if p and p:IsA("BasePart") then
				table.insert(body, p)
			end
		end
		VFX.PlaySound("StaticCrackle", root.Position, 1)
		VFX.PlaySound("Blink", root.Position, 0.7)
		local t0 = os.clock()
		while os.clock() - t0 < duration and PV.glitching[char] == token and char.Parent do
			local k = (os.clock() - t0) / duration
			local there = mode == "out" and 1 - k or k
			PV.setShown(char, rng:NextNumber() < 0.2 + 0.65 * there)
			-- the colour split: a green copy torn off one way, magenta the other
			local right = root.CFrame.RightVector
			local shift = (0.25 + 0.7 * (1 - there)) * (rng:NextNumber() < 0.5 and -1 or 1)
			for _, p in body do
				for s, color in { PV.GREEN, PV.MAGENTA } do
					local g = newPart(p.Size * 1.02, p.CFrame + right * shift * (s == 1 and 1 or -1) + UP * rand(-0.12, 0.12), color, Enum.Material.Neon)
					g.Transparency = 0.5
					cleanup(g, 0.05)
				end
			end
			-- torn scanlines through him, slid sideways
			for _ = 1, 3 do
				local bar = newPart(Vector3.new(rand(1.5, 4.5), rand(0.08, 0.3), 1.3), root.CFrame * CFrame.new(rand(-1.4, 1.4), rand(-2.6, 1.8), 0), rng:NextNumber() < 0.5 and Color3.new(1, 1, 1) or PV.GREEN, Enum.Material.Neon)
				bar.Transparency = 0.2
				cleanup(bar, 0.04)
			end
			if rng:NextNumber() < 0.35 then
				bolt(root.Position, 2.5, PV.GREEN)
			end
			task.wait(0.035)
		end
		if PV.glitching[char] == token then
			PV.glitching[char] = nil
			PV.setShown(char, true)
		end
	end

	-- (target space: she's at the origin facing -Z; he appears 3.3 behind her
	-- at +Z, facing her back - so HIS left is -X.) From the left side of his
	-- face as he glitches in, round his left side to behind him, looking past
	-- his shoulder at her back - at an even pace (short Linear legs)
	function PV.orbitShots()
		local orbit = {}
		local steps, total = 6, 0.75
		local head = V(0, 1.2, 3.3) -- (crouched: his head's low)
		local function point(k)
			local phi = math.rad(50 + 155 * k)
			local r = 4.2 + 3 * k
			return head + V(-r * math.sin(phi), 0.1 + 2.4 * k, -r * math.cos(phi))
		end
		local function lookAt(k)
			local e = math.clamp((k - 0.35) / 0.65, 0, 1)
			e = e * e * (3 - 2 * e)
			return head:Lerp(V(0, 1.4, 0), e)
		end
		-- (on the left side of his face while he glitches in, easing in a little)
		table.insert(orbit, { T = 0.8, From = { point(0) + V(-0.5, 0, -0.4), lookAt(0) }, To = { point(0), lookAt(0) }, Fov = { 48, 46 } })
		for i = 1, steps do
			local a, b = (i - 1) / steps, i / steps
			table.insert(orbit, {
				T = total / steps, Style = Enum.EasingStyle.Linear,
				From = { point(a), lookAt(a) }, To = { point(b), lookAt(b) },
				Fov = { 46 + 6 * a, 46 + 6 * b },
			})
		end
		-- (holding over his shoulder: her back, his fist about to come past the camera)
		table.insert(orbit, { T = 0.1, From = { point(1), lookAt(1) }, To = { point(1) + V(0, -0.05, -0.2), lookAt(1) }, Fov = { 52, 51 } })
		-- wide, low, from his right as the arm draws back
		table.insert(orbit, { T = 0.45, Cut = true, From = { V(8.5, 1.2, 2.2), V(0, 1.9, 1.7) }, To = { V(7.6, 1.3, 2), V(0, 1.9, 1.7) }, Fov = { 56, 50 } })
		-- the punch: she's gone down the street
		table.insert(orbit, { T = 0.75, Cut = true, From = { V(16, 3.5, 5), V(0, 2, -4) }, To = { V(20, 6, -6), V(0, 3, -28) }, Fov = { 62, 76 }, Style = Enum.EasingStyle.Quad })
		return orbit
	end
	SHOTS.FlashBehind = PV.orbitShots()

	-- 1: FLASH STEP - he glitches out
	function Effects.PrimeFlashStep(char, _data, isLocal)
		local root = charParts(char)
		if not root then
			return
		end
		local g = groundPoint(root.Position)
		dustPuffs(g, 1, 6, Color3.fromRGB(200, 196, 186), 0.7, true)
		shockDisc(g + UP * 0.3, UP, 2, 16, 0.25, PV.GREEN)
		for _ = 1, 4 do
			bolt(root.Position, 4, PV.GREEN)
		end
		VFX.PlaySound("FlashStep", root.Position, 1)
		if isLocal then
			VFX.Hooks.Flash(PV.GREEN, 0.1)
		end
		PV.glitch(char, 0.24, "out")
		if PV.hidden[char] == nil and char.Parent then
			afterimage(char, PV.MAGENTA, 0.3)
			afterimage(char, PV.GREEN, 0.45)
			streaks(root.Position, UP, 10, 1.5, 6, 10, PV.GREEN, 0.25)
			PV.hideWhile(char, 4.5)
		end
	end

	-- nobody in the ring: the old landing, glitched in
	PV.landing = Effects.FlashAppear
	function Effects.FlashAppear(char, data)
		PV.landing(char, data)
		PV.glitch(char, 0.2, "in")
	end

	-- someone in the ring: BEHIND them, slow
	function Effects.FlashBehind(char, data)
		local target = typeof(data.Target) == "Instance" and data.Target
		local troot = target and target:FindFirstChild("HumanoidRootPart")
		local at = typeof(data.Pos) == "Vector3" and data.Pos
		if not troot or not at then
			return
		end
		local look = typeof(data.Look) == "Vector3" and data.Look or troot.CFrame.LookVector
		local strike = tonumber(data.Strike) or 2.1
		local place = tonumber(data.Place) or 0.34
		-- (he stays gone till the glitch brings him back, whatever the server says)
		PV.hidden[char] = nil
		PV.glitching[char] = nil
		PV.setShown(char, false)
		local mine = PV.me()
		if mine == char or mine == target then
			VFX.Cinematic(target, SHOTS.FlashBehind, { Title = data.Name or "FLASH STEP", Subtitle = "BEHIND YOU", Color = PV.GREEN, Own = mine == char, Face = troot.Position + look * 10 })
			PV.drain(strike + 0.1, 0.8)
		elseif mine then
			local mr = mine:FindFirstChild("HumanoidRootPart")
			if mr and (mr.Position - troot.Position).Magnitude < 55 then
				VFX.Cinematic(mine, witnessShots((mr.Position - troot.Position).Magnitude), { Title = data.Name or "FLASH STEP", Color = PV.GREEN, Face = troot.Position })
			end
		end
		VFX.Hitstop(target, strike - 0.05) -- (she's caught mid-step)
		VFX.PlaySound("FlashStep", at, 0.8)
		local t0 = os.clock()
		local function at_(t)
			local left = t - (os.clock() - t0)
			if left > 0 then
				task.wait(left)
			end
		end
		-- static crackling where he's going to be
		at_(0.06)
		PV.gather(at + UP * 0.5, PV.GREEN, math.max(place - 0.1, 0.08))
		at_(place)
		if char.Parent then
			VFX.Pose(char, "FlashCrouch", 0.95)
			task.spawn(PV.glitch, char, 0.36, "in")
		end
		VFX.PlaySound("FlashAppear", at, 0.7)
		at_(place + 0.45)
		if target.Parent then
			VFX.Pose(target, "LookBack", strike - place)
		end
		-- he rises out of the crouch, the right arm drawing all the way back...
		at_(1.25)
		if char.Parent then
			VFX.Pose(char, "PrimeBigPunchWind", strike - 1.25)
			VFX.PlaySound("MuscleRumble", at, 0.7)
		end
		while os.clock() - t0 < strike - 0.06 and char.Parent do
			-- ...the lightning running up it into the fist, the air drawn in
			local hand = limb(char, "RightHand", "Right Arm")
			local shoulder = char:FindFirstChild("Torso") or char:FindFirstChild("UpperTorso")
			if hand then
				local fist = hand.Position - hand.CFrame.UpVector * 0.8
				bolt(fist, 1.6, PV.GREEN)
				bolt(fist, 1, PV.CORE)
				if shoulder then
					bolt(shoulder.Position:Lerp(fist, rng:NextNumber()), 1.2, PV.GREEN)
				end
				local from = fist + rng:NextUnitVector() * rand(3, 6)
				streaks(from, (fist - from).Unit, 1, 0.5, 3, (fist - from).Magnitude, PV.CORE, 0.15)
			end
			task.wait(0.04)
		end
		-- ...and through her
		if char.Parent then
			VFX.Pose(char, "PrimeBigPunch", 0.6)
		end
	end

	-- the big punch lands
	PV.kickLands = Effects.FlashStrike
	function Effects.FlashStrike(char, data)
		PV.kickLands(char, data)
		local target = typeof(data.Target) == "Instance" and data.Target
		local troot = target and target:FindFirstChild("HumanoidRootPart")
		local d = typeof(data.Dir) == "Vector3" and data.Dir.Magnitude > 0.01 and data.Dir.Unit or UP
		local pos = troot and troot.Position or (typeof(data.Pos) == "Vector3" and data.Pos)
		if not pos then
			return
		end
		local mine = PV.me()
		if mine == char or mine == target then
			VFX.ImpactFrame(0.16)
		end
		-- a colossal fist of green light thrown on down the street after her
		local side = d:Cross(UP)
		side = side.Magnitude > 0.05 and side.Unit or Vector3.new(1, 0, 0)
		local f = PV.fist(CFrame.fromMatrix(pos - d * 2, side, -d), 4.5, PV.GREEN)
		task.spawn(function()
			local t0 = os.clock()
			while os.clock() - t0 < 0.35 do
				local k = (os.clock() - t0) / 0.35
				f.set(CFrame.fromMatrix(pos + d * (40 * k), side, -d))
				task.wait()
			end
			f.gone(0.25)
		end)
		moonArc(CFrame.lookAt(pos, pos + d), 9, PV.GREEN, 300)
		shockDisc(pos, d, 4, 44, 0.45, PV.CORE, 18)
		billboardRing(pos, 4, 40, Color3.new(1, 1, 1), 12, 0.4)
		VFX.PlaySound("DetroitImpact", pos, 1)
		VFX.ShakeAt(pos, 4, 140, 0.55)
	end
end

-- (round 76) the longer charges for the voice lines: UNITED STATES OF
-- SMASH's fist stays cocked (and the camera stays on it) through "UNITED
-- STATES OF...", and Bakugo stays coiled in Explosive Speed's crouch through
-- "I'M THE FINAL BOSS, GOT IT?"
do
	local uss = Config.FindAbilityById and Config.FindAbilityById("UnitedStatesSmash")
	local extra = math.max(((uss and uss.ChargeTime) or 0.95) - 0.95, 0)
	if extra > 0 then
		local m = MOTIONS.UnitedStatesSmash
		m[1].hold += extra * 0.7
		m[2].hold += extra * 0.3
		local shots = SHOTS.UnitedStatesSmash
		shots[1].T += extra * 0.6
		shots[2].T += extra * 0.4
	end
	local es = Config.FindAbilityById and Config.FindAbilityById("ExplosiveSpeed")
	local more = math.max(((es and es.WindUp) or 0.7) - 0.7, 0)
	if more > 0 and MOTIONS.BlitzCrouch then
		MOTIONS.BlitzCrouch[2].hold += more
	end
end

---------------------------------------------------------------------------
-- (round 78) UNITED STATES OF SMASH, the way it went against All For One at
-- Kamino (anime ep. 49 / manga ch. 94): the left is a decoy that lands on
-- his face; the last embers of One For All go into the right arm while All
-- Might ducks low; the overhand right lands on the face - an impact frame,
-- everything stops - and it drives him down into the street. A twister
-- climbs out of the crater; All Might raises his fist.
-- Its beats come from the server: the press (UnitedStatesSmash: the lunge),
-- then USSWhiff (nobody caught) or USSCatch (caught: the build, then the
-- strike Build seconds later, frozen for Freeze), then USSSlam (the street).
-- R6 bodies play the keyframed clips (ReplicatedStorage.Animations:
-- MoveUSSLunge / Whiff / Build / Smash / Victory - open them in Studio's
-- Animation Editor or Moon Animator); anything else these motions.
---------------------------------------------------------------------------
do
	local USS = {
		lunges = setmetatable({}, { __mode = "k" }), -- [char] = the lunge going (its stop())
		caught = setmetatable({}, { __mode = "k" }), -- [char] = the catch going
	}
	VFX.USS = USS

	MOTIONS.USSLunge = {
		{ pose = { Waist = { -10, 25, 0 }, LeftArm = { -30, 0, 20 }, RightArm = { 30, 0, 20 }, RightLeg = -20, LeftLeg = 25, LeftKnee = 30 }, t = 0.1, hold = 0.06 },
		{ pose = { Waist = { -25, -35, 0 }, LeftArm = 95, RightArm = { -20, 0, 30 }, RightLeg = -40, LeftLeg = 45, LeftKnee = 40 }, t = 0.07, hold = 0.4, style = Enum.EasingStyle.Back },
		recover = 0.3,
	}
	MOTIONS.USSWhiff = {
		{ pose = { Waist = { -40, -30, 0 }, LeftArm = 70, RightArm = { -30, 0, 40 }, RightLeg = -45, LeftLeg = 55, LeftKnee = 50 }, t = 0.12, hold = 0.25 },
		recover = 0.35,
	}
	MOTIONS.USSBuild = {
		{ pose = { Waist = { -15, -45, 0 }, RightArm = { 160, 0, 35 }, RightElbow = 90, LeftArm = 92, RightLeg = -35, LeftLeg = 40, LeftKnee = 55, RightKnee = 35 }, t = 0.3, hold = 1.6 },
		recover = 0.2,
	}
	MOTIONS.USSSmash = {
		{ pose = { Waist = { -30, 40, 0 }, RightArm = 80, LeftArm = { -35, 0, 30 }, RightLeg = -40, LeftLeg = 50, LeftKnee = 45 }, t = 0.06, hold = 0.1, style = Enum.EasingStyle.Back },
		{ pose = { Waist = { -50, 35, 0 }, RightArm = 30, LeftArm = { -45, 0, 40 }, RightLeg = -50, LeftLeg = 65, LeftKnee = 80, RightKnee = 20 }, t = 0.08, hold = 0.5 },
		recover = 0.35,
	}
	MOTIONS.USSVictory = {
		{ pose = { RightArm = { 175, 0, 5 }, LeftArm = { 10, 0, 15 }, Waist = { 6, 6, 0 }, Neck = { 15, 0, 0 } }, t = 0.3, hold = 1.3, style = Enum.EasingStyle.Back },
		recover = 0.35,
	}

	-- the caster's cutscene, from the catch, cut on the poses (round 79,
	-- tools/anim/moves_uss.py SHOTS): the decoy landing, from his left, until
	-- the right fist is cocked (the build's Hold key); low behind his right
	-- shoulder under the cocked fist - the embers pouring into it, the swing
	-- going over the camera; the impact frame from high over their shoulder,
	-- his fist on the upturned face; the street going; the twister climbing
	-- out of it. (round 81) Only the cut to the cocked fist whooshes, softly:
	-- the crack, the boom and the twister carry the rest (Quiet) - the old
	-- whoosh on every cut was the loudest thing on the impact frame
	function USS.shots(build, freeze, slam)
		local cock = 0.44
		return {
			{ T = cock, From = { V(-10, 2.5, -4), V(0, 0.6, -2.4) }, To = { V(-9, 2.2, -4.3), V(0, 0.8, -2.6) }, Fov = { 46, 42 } },
			{ T = math.max(build - cock, 0.3), Cut = true, CutGain = 0.35, From = { V(9.5, -1.5, 1.5), V(-0.5, 1, -3.6) }, To = { V(8.6, -1.7, 1), V(-0.5, 1.2, -3.6) }, Fov = { 50, 46 } },
			{ T = freeze, Cut = true, Quiet = true, From = { V(4.84, 4, -10.92), V(0.2, 1.2, -4.22) }, To = { V(4.34, 3.6, -10.22), V(0.2, 1.2, -4.22) }, Fov = { 44, 40 } },
			{ T = slam + 0.3, Cut = true, Quiet = true, From = { V(12, 8, -6), V(0, -2.8, -4.2) }, To = { V(13.5, 10, -6.5), V(0, -2.8, -4.2) }, Fov = { 54, 60 } },
			{ T = 1.7, Cut = true, Quiet = true, From = { V(-10, 4, 55), V(0, 15, -5) }, To = { V(-14, 40, 95), V(0, 90, -5) }, Fov = { 70, 78 }, Style = Enum.EasingStyle.Quad },
		}
	end
	SHOTS.USSCatch = USS.shots(2, 0.38, 0.12)

	-- The anime's impact frames: blown out white, stark black and white, a
	-- beat of red, then black and white held till the world moves again
	local frameToken = 0
	function USS.impactFrame(duration)
		frameToken += 1
		local token = frameToken
		local Lighting = game:GetService("Lighting")
		local cc = Lighting:FindFirstChild("USSImpactFrame")
		if not cc then
			cc = Instance.new("ColorCorrectionEffect")
			cc.Name = "USSImpactFrame"
			cc.Parent = Lighting
		end
		cc.Saturation = -1
		cc.Enabled = true
		local steps = {
			{ 0.05, 0.55, 3, Color3.new(1, 1, 1) },
			{ 0.06, -0.3, 3.2, Color3.new(1, 1, 1) },
			{ 0.06, -0.05, 2.6, Color3.fromRGB(255, 70, 50) },
			{ math.max(duration - 0.17, 0.05), 0.08, 2.2, Color3.new(1, 1, 1) },
		}
		task.spawn(function()
			for _, step in steps do
				if frameToken ~= token then
					return
				end
				cc.Brightness, cc.Contrast, cc.TintColor = step[2], step[3], step[4]
				task.wait(step[1])
			end
			if frameToken == token then
				cc.Enabled = false
				cc.TintColor = Color3.new(1, 1, 1)
			end
		end)
		VFX.Hooks.Flash(Color3.new(1, 1, 1), 0.25)
	end

	-- the dust wall the slam throws out: two-tone cel-shaded puffs rolling
	-- out in a ring
	function USS.dustWall(pos, radius)
		local model = Instance.new("Model")
		model.Name = "USSDust"
		model.Parent = folder
		local DARK, LIGHT = Color3.fromRGB(170, 156, 140), Color3.fromRGB(226, 218, 206)
		for i = 1, 22 do
			local a = i / 22 * math.pi * 2 + rand(-0.1, 0.1)
			local out = Vector3.new(math.cos(a), 0, math.sin(a))
			local size = rand(7, 12)
			celPuff(model, pos + out * 4 + UP * 2, pos + out * radius * rand(0.75, 1) + UP * size * 0.35, size, DARK, LIGHT, 0.45, rand(1.2, 1.8), rand(0, 0.06))
		end
		cleanup(model, 3)
	end

	-- (round 79) the smear: the streak the fist leaves on the frame through
	-- the swing, traced along its real arc as it goes (thin where it started,
	-- full width at the fist), held through the freeze, then gone
	function USS.smear(char, swing, freeze)
		local root = charParts(char)
		if not root then
			return
		end
		local hold = newPart(Vector3.one * 0.2, CFrame.new(root.Position), Color3.new(), nil, nil, folder)
		hold.Name = "USSSmear"
		hold.Transparency = 1
		local beams = {}
		local last, lastPos
		local t0 = os.clock()
		local function width(t)
			return 0.25 + 1.75 * math.clamp((t - t0) / math.max(swing, 0.02), 0, 1)
		end
		local lastW = width(t0)
		local function link(a, b, w0, w1)
			for _, layer in { { GOLD, 1, 0.4 }, { Color3.new(1, 1, 1), 0.35, 0.1 } } do
				local beam = Instance.new("Beam")
				beam.Attachment0, beam.Attachment1 = a, b
				beam.Width0, beam.Width1 = w0 * layer[2], w1 * layer[2]
				beam.FaceCamera = true
				beam.Segments = 1
				beam.LightEmission = 1
				beam.LightInfluence = 0
				beam.Color = ColorSequence.new(layer[1])
				beam.Transparency = NumberSequence.new(layer[3])
				beam.Parent = hold
				table.insert(beams, { beam, layer[3] })
			end
		end
		local conn
		conn = RunService.RenderStepped:Connect(function()
			local now = os.clock()
			if not char.Parent or not hold.Parent or now - t0 > swing + 0.03 then
				conn:Disconnect()
				return
			end
			local p = handPos(char, true)
			if lastPos and (p - lastPos).Magnitude < 0.08 then
				return -- (frozen on the face)
			end
			local att = Instance.new("Attachment")
			att.Position = hold.CFrame:PointToObjectSpace(p)
			att.Parent = hold
			local w = width(now)
			if last then
				link(last, att, lastW, w)
			end
			last, lastPos, lastW = att, p, w
		end)
		task.delay(swing + freeze, function()
			for i = 1, 6 do
				for _, b in beams do
					if b[1].Parent then
						b[1].Transparency = NumberSequence.new(b[2] + (1 - b[2]) * i / 6)
					end
				end
				task.wait(0.025)
			end
		end)
		cleanup(hold, swing + freeze + 0.3)
	end

	-- the lunge's push (its own, named: a catch or a whiff stops it early)
	local function push(root, velocity, time)
		for _, old in root:GetChildren() do
			if old.Name == "USSLunge" then
				old:Destroy()
			end
		end
		local att = Instance.new("Attachment")
		att.Name = "USSLunge"
		att.Parent = root
		local lv = Instance.new("LinearVelocity")
		lv.Name = "USSLunge"
		lv.Attachment0 = att
		lv.MaxForce = moverForce(root, 6000)
		lv.RelativeTo = Enum.ActuatorRelativeTo.World
		lv.VectorVelocity = velocity
		lv.Parent = root
		cleanup(lv, time)
		cleanup(att, time)
		return function()
			lv:Destroy()
			att:Destroy()
		end
	end

	-- the press: the decoy left, lunging in (his own screen carries him; it
	-- stops short of a body rather than running through it)
	function Effects.UnitedStatesSmash(char, data, isLocal, ability)
		local root, hum = charParts(char)
		if not root then
			return
		end
		ability = ability or Config.FindAbilityById("UnitedStatesSmash") or {}
		local d = flatten(data.Dir, root)
		if isLocal then
			face(root, d)
		end
		VFX.Motion(char, "USSLunge")
		local lunge = {}
		USS.lunges[char] = lunge
		task.wait(ability.LungeStartup or 0.16)
		if not root.Parent then
			return
		end
		-- (round 81) the decoy's swing is heard on every screen - even one
		-- the catch reached first (a point-blank catch: both in one frame)
		VFX.PlaySound("HeavySwing", root.Position, 1)
		if USS.lunges[char] ~= lunge then
			return
		end
		afterimage(char, GOLD, 0.3)
		streaks(root.Position + UP, -d, 6, 1.6, 8, 14, WIND, 0.3)
		if isLocal and hum then
			local time = ability.LungeTime or 0.32
			local stop = push(root, d * ((ability.Lunge or 26) / math.max(time, 0.05)), time)
			lunge.stop = stop
			local t0 = os.clock()
			while os.clock() - t0 < time and USS.lunges[char] == lunge and root.Parent do
				if bodyAhead(root, d, 4.2) then
					stop()
					root.AssemblyLinearVelocity = Vector3.new(0, root.AssemblyLinearVelocity.Y, 0)
					break
				end
				task.wait()
			end
		end
	end

	local function endLunge(char)
		local lunge = USS.lunges[char]
		USS.lunges[char] = nil
		if lunge and lunge.stop then
			lunge.stop()
		end
	end

	-- (round 81) is this catch still going? The server's USSCancel ends it
	-- (he died, or the move was cut), and a caster who's dead doesn't swing:
	-- nothing - the crack, the impact frame, the music dropping out - goes
	-- off on a timer alone
	function USS.going(char, catch)
		if USS.caught[char] ~= catch or not char.Parent then
			return false
		end
		local hum = char:FindFirstChildOfClass("Humanoid")
		return hum == nil or hum.Health > 0
	end

	-- nobody caught: he over-reaches and stumbles out of it
	function Effects.USSWhiff(char, data)
		local root = charParts(char)
		if not root then
			return
		end
		endLunge(char)
		local d = flatten(data.Dir, root)
		VFX.Motion(char, "USSWhiff")
		VFX.PlaySound("USSWhiff", root.Position, 1)
		-- (round 81) his feet: the rear one catching him (the clip's 0.4s, the
		-- dust kicked up there) and the hop back landing (0.72s)
		task.delay(0.4, function()
			if root.Parent then
				VFX.PlaySound("USSFootfall", groundPoint(root.Position), 1)
				dustPuffs(groundPoint(root.Position + d * 1.2), 1, 4, Color3.fromRGB(206, 196, 186), 0.8, true)
			end
		end)
		task.delay(0.72, function()
			if root.Parent then
				VFX.PlaySound("USSFootfall", groundPoint(root.Position), 0.6)
			end
		end)
	end

	-- caught: the decoy lands on the face, then "UNITED STATES OF..." while the
	-- last embers pour into his right arm - and the strike, Build seconds on
	function Effects.USSCatch(char, data)
		local root = charParts(char)
		if not root then
			return
		end
		local ability = Config.FindAbilityById(data.Id or "UnitedStatesSmash") or {}
		local build = tonumber(data.Build) or ability.BuildTime or 2
		local freeze = tonumber(data.Freeze) or ability.FreezeTime or 0.38
		local slam = tonumber(data.Slam) or ability.SlamTime or 0.12
		local target = typeof(data.Target) == "Instance" and data.Target or nil
		local troot = target and target:FindFirstChild("HumanoidRootPart")
		local d = flatten(data.Dir, root)
		local me = Players.LocalPlayer
		local mine = me ~= nil and me.Character == char
		endLunge(char)
		if mine then
			face(root, d)
			root.AssemblyLinearVelocity = Vector3.new(0, root.AssemblyLinearVelocity.Y, 0)
		end
		local catch = { target = target, at = os.clock() }
		USS.caught[char] = catch
		-- the decoy, on the face
		local hit = (troot and troot.Position or (root.Position + d * 4.6)) + UP * 1.4
		VFX.Hitstop(char, 0.1)
		-- (round 79) the swing starts its "Hit" key's time ahead of the strike,
		-- and their reaction clip lands its own "Hit" on it too
		local clips = Anim.MoveClips ~= false
		local swing = clips and VFX.GetClip("MoveUSSSmash")
		local swingLead = swing and swing.hit or 0.06
		local struck = clips and VFX.GetClip("MoveUSSStruck")
		local struckLead = struck and struck.hit or 0
		if target then
			VFX.Hitstop(target, 0.1)
			-- (round 79) their own reaction: the decoy snaps their head back,
			-- then they reel, held up by the face, till the strike
			local dazed = clips and VFX.GetClip("MoveUSSDazed")
			if not (dazed and VFX.Clip(target, "MoveUSSDazed", { holdFor = math.max(build - struckLead - dazed.length, 0), recover = 0.2 })) then
				VFX.Pose(target, "Stagger", build)
			end
			if struck then
				task.delay(math.max(build - struckLead, 0), function()
					if USS.going(char, catch) and target.Parent then
						VFX.Clip(target, "MoveUSSStruck", { recover = 0.3 })
					end
				end)
			end
		end
		shockDisc(hit, -d, 1.5, 12, 0.22, WIND)
		billboardRing(hit, 2, 14, Color3.new(1, 1, 1), 6, 0.2)
		-- (round 81) the decoy's own sound only: the server's Hit for it is
		-- Quiet (its generic punch played the same samples on top)
		VFX.PlaySound("USSJab", hit, 1)
		VFX.ShakeAt(hit, 1.5, 120, 0.25)
		-- the camera: his cutscene; a witness cut for anyone close by. (round
		-- 81) Quiet: no whoosh opening it - the decoy's hit is the cut
		SHOTS.USSCatch = USS.shots(build, freeze, slam)
		cinematicFor(char, "USSCatch", mine, ability.Name or "UNITED STATES OF SMASH", GOLD, { Quiet = true })
		if mine then
			VFX.Hooks.Dim(0.45, build + 0.05)
		end
		-- "UNITED STATES OF..." - "SMASH!!" lands on the punch. (round 81) The
		-- clip's SMASH is 4.3s in, so it starts part-way through the line
		-- (Config.Voice.MightUSS): eased in, not cut in mid-word
		local voice = VFX.Voice("MightUSS", root, build)
		if typeof(voice) == "Instance" and voice:IsA("Sound") then
			local full = voice.Volume
			voice.Volume = 0
			tween(voice, 0.2, { Volume = full }, Enum.EasingStyle.Sine, Enum.EasingDirection.Out)
		end
		catch.voice = voice
		-- (round 81) the 1.5x body dropping onto both feet under them (the
		-- build clip's landing: 0.08s in, after the decoy's 0.1s hitstop)
		task.delay(0.18, function()
			if USS.going(char, catch) and root.Parent then
				VFX.PlaySound("USSFootfall", groundPoint(root.Position), 1.2)
			end
		end)
		-- (round 81) the power swelling in him under "UNITED STATES OF...",
		-- gone before the swing; then the air sucked into the fist, closing
		-- on the strike (its close lands on the crack, which cuts it off)
		VFX.PlaySound("USSBuildHum", root.Position, 1)
		local suckCue = Config.Sounds and Config.Sounds.USSSuck
		task.delay(math.max(build - ((suckCue and suckCue.Lead) or 0.9), 0), function()
			if USS.going(char, catch) and root.Parent then
				VFX.PlaySound("USSSuck", handPos(char, true), 1)
			end
		end)
		-- he steps in under them, the right fist cocked high (held there - it
		-- ends just as the swing takes over)
		MOTIONS.USSBuild[1].hold = math.max(build - 0.36, 0.2)
		local buildClip = clips and VFX.GetClip("MoveUSSBuild")
		if not (buildClip and VFX.Clip(char, "MoveUSSBuild", { holdFor = math.max(build - swingLead - buildClip.length, 0), recover = 0.3 })) then
			VFX.Motion(char, "USSBuild")
		end
		-- the embers pour into the right arm; the air's drawn in to the fist
		local unswell = swell(char, { { "RightUpperArm", "Right Arm" }, { "RightLowerArm", "" }, { "RightHand", "" } }, GOLD, 1.35)
		task.spawn(function()
			local t1 = os.clock()
			while os.clock() - t1 < build and root.Parent and USS.caught[char] == catch do
				local k = (os.clock() - t1) / build
				local hand = handPos(char, true)
				bolt(hand, 2 + 2 * k, GOLD)
				bolt(hand, 1.5, Color3.new(1, 1, 1))
				if rng:NextNumber() < 0.35 + 0.4 * k then
					local from = hand + rng:NextUnitVector() * rand(10, 18)
					streaks(from, (hand - from).Unit, 1, 0.3, 4, (hand - from).Magnitude, WIND, 0.25)
				end
				-- (round 81) the crackle stops short of the strike: the last
				-- ones would still be ringing on the impact frame
				if rng:NextNumber() < 0.2 and os.clock() - t1 < build - 0.7 then
					VFX.PlaySound("Spark", hand, 0.5)
				end
				task.wait(0.04)
			end
			unswell(0.4)
		end)
		-- the overhand right: swung just before it lands (the fist leaves a
		-- smear along its arc)...
		task.delay(math.max(build - swingLead, 0), function()
			if USS.going(char, catch) and root.Parent then
				VFX.Motion(char, "USSSmash")
				USS.smear(char, swingLead, freeze)
			end
		end)
		-- ...and on the face: everything stops
		task.delay(build, function()
			if USS.going(char, catch) and root.Parent then
				USS.strike(char, target, d, freeze, ability, mine)
			end
		end)
	end

	-- (round 81) the server let them go before the strike (he died, or the
	-- move was cut): no swing, no crack, no impact frame, no slam to come -
	-- and "...SMASH!!" isn't said
	function Effects.USSCancel(char)
		local catch = USS.caught[char]
		endLunge(char)
		if not catch then
			return
		end
		USS.caught[char] = nil
		if catch.voice and catch.voice.Parent then
			tween(catch.voice, 0.15, { Volume = 0 })
			cleanup(catch.voice, 0.2)
		end
		VFX.ReleasePose(char, 0.25)
		if catch.target and catch.target.Parent then
			VFX.ReleasePose(catch.target, 0.25)
		end
		local me = Players.LocalPlayer
		if me and me.Character == char and VFX.InOwnCinematic() then
			VFX.CancelCinematic()
		end
	end

	-- the overhand right on the face: the impact frame, and the world stops
	-- for `freeze` - the ult music drops out under it and comes back after
	function USS.strike(char, target, d, freeze, ability, mine)
		local root = charParts(char)
		if not root then
			return
		end
		local troot = target and target:FindFirstChild("HumanoidRootPart")
		local at = troot and (troot.Position + UP * 1.4) or (root.Position + d * 4.6 + UP * 2)
		VFX.Hitstop(char, freeze)
		if target then
			VFX.Hitstop(target, freeze)
		end
		if nearCamera(at, 260) then
			USS.impactFrame(freeze)
			if VFX.Hooks.DuckMusic then
				VFX.Hooks.DuckMusic(ability.MusicDuck or 0.15, 0.04, freeze + 0.15, 2.8)
			end
		end
		VFX.PlaySound("USSStrike", at, 1)
		local flash = newPart(Vector3.one * 2, CFrame.new(at), Color3.new(1, 1, 1), Enum.Material.Neon, Enum.PartType.Ball)
		tween(flash, 0.1, { Size = Vector3.one * 7, Transparency = 0.2 })
		task.delay(freeze, function()
			if flash.Parent then
				tween(flash, 0.15, { Size = Vector3.one * 11, Transparency = 1 })
			end
		end)
		cleanup(flash, freeze + 0.2)
		for i = 1, 3 do
			task.delay((i - 1) * 0.04, function()
				shockDisc(at, d, 2 + i, 18 + i * 10, 0.3 + i * 0.05, i == 2 and GOLD or WIND)
			end)
		end
		streaks(at, d, 14, 2.4, 10, 30, WIND, 0.35)
		VFX.ShakeAt(at, 3, 160, 0.4)
		if mine then
			VFX.Hooks.SpeedLines(freeze + 0.3)
		end
	end

	-- down through them into the street: the crater, the wind pressure
	-- rolling out, the twister climbing out of it - then the raised fist,
	-- and "You're next."
	function Effects.USSSlam(char, data)
		local root = charParts(char)
		local ability = Config.FindAbilityById(data.Id or "UnitedStatesSmash") or {}
		local pos = typeof(data.Pos) == "Vector3" and data.Pos or (root and groundPoint(root.Position))
		if not pos then
			return
		end
		local d = typeof(data.Dir) == "Vector3" and data.Dir or Vector3.new(0, 0, -1)
		if root then
			USS.caught[char] = nil
		end
		if nearCamera(pos, 200) then
			VFX.Hooks.Flash(Color3.new(1, 1, 1), 0.4)
		end
		windBlast(pos + UP * 3, (d - UP * 1.2).Unit, 2.4)
		for i = 1, 6 do
			task.delay(i * 0.05, function()
				shockDisc(pos + UP * (0.5 + i * 0.6), UP, 12, 150, 0.8, WIND)
			end)
		end
		shockDisc(pos + UP * 0.5, UP, 8, 95, 0.55, GOLD)
		billboardRing(pos + UP * 2, 4, 60, GOLD, 12, 0.45)
		USS.dustWall(pos, ability.WindRadius or 46)
		streaks(pos, UP, 50, 12, 22, 130, WIND, 0.6)
		rocks(pos, 3.5, 30)
		groundMark(pos, 26, Color3.fromRGB(52, 46, 44), 10)
		VFX.PlaySound("MightUSSImpact", pos, 1)
		VFX.ShakeAt(pos, 4, 260, 0.9)
		-- the wind pressure becomes a twister
		twister(pos, ability.TwisterTime or 6.5, ability.TwisterTopRadius or 110, ability.TwisterHeight or 300)
		if not root then
			return
		end
		task.delay(0.75, function()
			if root.Parent then
				VFX.Motion(char, "USSVictory")
			end
		end)
		task.delay(2.9, function()
			if root.Parent then
				VFX.Motion(char, "YoureNext")
				local me = Players.LocalPlayer
				if me and me.Character == char then
					VFX.Hooks.Callout("YOU'RE NEXT.", GOLD)
				end
			end
		end)
	end
end

---------------------------------------------------------------------------
-- (round 86) HAWKS (VFX.HK): THE WING DRIVER, his feathers in the air, the
-- feather blades, the flight, and every move's effect (phase C2 dresses the
-- moves up; the interface they hook into is the functions here).
--
-- THE WINGS are built by the server (QuirkGear.HawksWings, Kit.HK.wings in
-- QuirkServer, from Config.Quirks.FierceWings.Wing). Every machine poses
-- every Hawks within Wing.Cull studs of its camera, each frame: three bone
-- joints a wing (Welds: WingJoint) and every feather's hinge (FeatherHinge),
-- written as C0s. What pose: a move's beat on this screen (HK.setWing:
-- instant, no waiting on the server), else his flight (from how he's
-- moving), else the server's WingState, else "Rest" (folded, breathing).
-- HOW MANY feathers show: his Feathers count, through Wing.Visible and the
-- hide order (Wing.Hide) - a feather that goes slides in and fades in a
-- blink, one that grows back slides out over a third of a second. The ult's
-- overgrowth row shows past 100. Your own wings fade with the camera close
-- behind you (Wing.Fade), and HIDE MY WINGS hides them (your screen only).
-- (In a function of its own, not a do block: the main chunk's at Luau's
-- 200-register limit, and a do block's locals count against it.)
---------------------------------------------------------------------------
;(function()
	local HK = {
		rigs = setmetatable({}, { __mode = "k" }), -- [char] = his wings, bound
		over = setmetatable({}, { __mode = "k" }), -- [char] = { State, Until, Rate } a move's wing beat on this screen
		flying = setmetatable({}, { __mode = "k" }), -- [char] = true: my own flight, before the server says so
		boosts = setmetatable({}, { __mode = "k" }), -- [char] = os.clock() his flight boost ends
		drawn = setmetatable({}, { __mode = "k" }), -- [char] = the feather blades in his hands
		volleys = setmetatable({}, { __mode = "k" }), -- [char] = { [volley id] = { feathers } }
		loops = setmetatable({}, { __mode = "k" }), -- [char] = { [cue] = looped Sound }
		flights = setmetatable({}, { __mode = "k" }), -- [char] = his flight's watcher
		RED = Color3.fromRGB(196, 28, 36),
		LIT = Color3.fromRGB(222, 44, 44),
		TIP = Color3.fromRGB(246, 88, 70),
		PALE = Color3.fromRGB(255, 120, 110),
		EDGE = Color3.fromRGB(255, 150, 130),
		DUST = Color3.fromRGB(214, 206, 196),
	}
	VFX.HK = HK
	local Q = Config.Quirks.FierceWings or {}
	local W = Q.Wing or {}
	local SPEC = Q.Feathers or {}
	local LAYOUT, HIDE_AT = {}, {}
	for _, f in W.Feathers or {} do
		LAYOUT[f.Row .. f.Idx] = f
	end
	for i, slot in W.Hide or {} do
		HIDE_AT[slot] = i
	end

	-- the wing maths (the server builds with the same: Kit.HK.turn / mirror)
	function HK.turn(t)
		return CFrame.Angles(0, math.rad(-t[2]), 0) * CFrame.Angles(0, 0, math.rad(t[1])) * CFrame.Angles(math.rad(t[3]), 0, 0)
	end
	function HK.mirror(cf, side)
		if side > 0 then
			return cf
		end
		local x, y, z, r00, r01, r02, r10, r11, r12, r20, r21, r22 = cf:GetComponents()
		return CFrame.new(x, y, -z, r00, r01, -r02, r10, r11, -r12, -r20, -r21, r22)
	end
	-- a state as a pose: the bones' turns and each row's fan
	local poses = {}
	function HK.pose(name)
		local p = poses[name]
		if not p then
			local st = W.States and W.States[name]
			if not st then
				return nil
			end
			p = { A = { HK.turn(st.S), HK.turn(st.E), HK.turn(st.W) }, fan = {} }
			for row, v in st.Fan do
				p.fan[row] = { v[1], v[2] }
			end
			poses[name] = p
		end
		return p
	end
	local function blendPose(a, b, w, out)
		out = out or { A = {}, fan = {} }
		for i = 1, 3 do
			out.A[i] = a.A[i]:Lerp(b.A[i], w)
		end
		for row, fa in a.fan do
			local fb = b.fan[row] or fa
			local o = out.fan[row] or {}
			o[1], o[2] = fa[1] + (fb[1] - fa[1]) * w, fa[2] + (fb[2] - fa[2]) * w
			out.fan[row] = o
		end
		return out
	end
	HK.blendPose = blendPose

	-- how many feathers show on a wing at `points` of 100 (Wing.Visible)
	function HK.visibleCount(points)
		local list = W.Visible or { { 0, 0 }, { 100, 24 } }
		local p = math.clamp(points, 0, 100)
		for i = 1, #list - 1 do
			local a, b = list[i], list[i + 1]
			if p <= b[1] then
				return a[2] + (b[2] - a[2]) * (p - a[1]) / math.max(b[1] - a[1], 1e-3)
			end
		end
		return list[#list][2]
	end
	-- each wing's count for his Feathers (the two wings take turns losing one),
	-- and the ult's overgrowth row
	function HK.counts(feathers)
		local base = SPEC.Max or 100
		local f = math.max(tonumber(feathers) or 0, 0)
		local per = HK.visibleCount(math.min(f, base) / base * 100)
		local total = math.floor(2 * per + 0.5)
		if f > 0 then
			total = math.max(total, 2)
		end
		local over = f > base and math.floor((f - base) / (W.OverPer or 8)) or 0
		return math.ceil(total / 2), math.floor(total / 2), over
	end

	---------------------------------------------------------------------
	-- binding: his wings' joints and feathers (again when the gear's rebuilt)
	---------------------------------------------------------------------
	local function setTransparency(fe, t)
		if fe.t ~= t then
			fe.t = t
			for _, p in fe.parts do
				p.Transparency = t
			end
		end
	end
	function HK.bind(char)
		local gear = char and char:FindFirstChild("QuirkGear")
		local model = gear and gear:FindFirstChild("HawksWings")
		local rig = HK.rigs[char]
		if rig and rig.model == model and model and model.Parent then
			return rig
		end
		if not model then
			HK.rigs[char] = nil
			return nil
		end
		local torso = char:FindFirstChild("Torso") or char:FindFirstChild("UpperTorso")
		-- (round 86, hawks_ult) the scale the server built them at (bigger in
		-- the ult: Wing.UltScale) - the root on his back at the body's own
		local kr = torso and torso.Size.Y / 2 or 1
		rig = {
			model = model, char = char, k = tonumber(model:GetAttribute("Scale")) or kr, kr = tonumber(model:GetAttribute("RootScale")) or kr,
			sides = { [1] = { joints = {}, feathers = {} }, [-1] = { joints = {}, feathers = {} } },
			parts = {}, beat = 0, beatKind = nil, lastBeat = 0, ltm = 0, twitchAt = os.clock() + rand(2, 4),
		}
		for _, d in model:GetDescendants() do
			if d:IsA("BasePart") then
				table.insert(rig.parts, d)
			end
		end
		for _, d in model:GetChildren() do
			local side = d:GetAttribute("Side")
			local s = side and rig.sides[side]
			if s then
				local b = tonumber(string.match(d.Name, "^WingBone(%d)$") or "")
				if b then
					s.joints[b] = d:FindFirstChild("WingJoint")
				elseif d.Name == "Feather" then
					local slot = d:GetAttribute("Slot")
					local f = slot and LAYOUT[slot]
					local hinge = d:FindFirstChild("FeatherHinge")
					if f and hinge then
						local parts = { d }
						for _, c in d:GetChildren() do
							if c:IsA("BasePart") then
								table.insert(parts, c)
							end
						end
						s.feathers[slot] = { part = d, hinge = hinge, f = f, parts = parts, shown = true, t = 0, slide = 0, slideTo = 0, tTo = 0, ext = 0, extTo = 0 }
					end
				end
			end
		end
		HK.rigs[char] = rig
		HK.refresh(char, true)
		return rig
	end

	-- which feathers show (his count; the blades in his hands take the
	-- longest primary still showing on each wing)
	function HK.refresh(char, instant)
		local rig = HK.rigs[char]
		if not rig then
			return
		end
		local right, left, over = HK.counts(char:GetAttribute("Feathers"))
		local grew = 0
		for side, n in { [1] = right, [-1] = left } do
			local s = rig.sides[side]
			local blade
			if HK.drawn[char] then
				local best
				for slot, fe in s.feathers do
					local at = HIDE_AT[slot]
					if fe.f.Row == "P" and at and at > 24 - n and (not best or fe.f.Len > best.f.Len) then
						best = fe
					end
				end
				blade = best
			end
			for slot, fe in s.feathers do
				local want
				if fe.f.Row == "O" then
					want = fe.f.Idx <= over
				else
					want = (HIDE_AT[slot] or 99) > 24 - n
				end
				if fe == blade then
					want = false
				end
				if want ~= fe.shown then
					fe.shown = want
					local home = (not instant and want) and HK.homeTo and HK.homeTo(char, side, slot, fe) or nil
					if instant then
						fe.slide, fe.slideTo = 0, 0
						setTransparency(fe, want and 0 or 1)
						fe.tTo = fe.t
						fe.goAt, fe.away = nil, nil
					elseif want then
						fe.goAt = nil
						if home == "taken" or home == "wait" then
							-- (round 86, C2) a feather that flew home takes the slot
							-- back with a click (HK.homeTo) - or the one still on its
							-- way will: it waits for it, hidden
						elseif fe.away and os.clock() < fe.away then
							-- (still out there - thrown before the count said so)
						elseif HK.homeGrow and HK.homeGrow(char, side, slot, fe) then
							-- (round 90) grown back: it flies in out of the air round him
							-- and slots in (the homecoming's spiral)
						else
							-- grown back: sliding out of the wing over a third of a second
							fe.slide = -0.45 * fe.f.Len
							fe.slideTo = 0
							setTransparency(fe, 0.85)
							fe.tTo = 0
							grew += 1
						end
					elseif not (fe.away and os.clock() < fe.away) then
						-- spent: (round 86, C2) it stays a moment - the move throws
						-- it from right here (HK.leave), so it leaves the wing as it
						-- flies - then, if nothing took it, in and gone in a blink
						-- (a blade drawn from it: at once)
						fe.goAt = os.clock() + ((fe == blade) and 0 or (HK.GRACE or 0))
					end
				end
			end
		end
		if grew > 0 and not instant then
			local root = char:FindFirstChild("HumanoidRootPart")
			if root and nearCamera(root.Position, 60) then
				VFX.PlaySound("FeatherGrow", root.Position, math.min(0.6 + grew * 0.1, 1))
			end
		end
	end

	-- a move's wing beat on this screen: `state` for `time` seconds (rate:
	-- how fast they get there; snappier than the rest)
	function HK.setWing(char, state, time, rate)
		if char and (state == "Rest" or W.States[state] or state == "Flap") then
			HK.over[char] = { State = state, Until = os.clock() + (time or 0.5), Rate = rate or 16 }
		end
	end
	function HK.localFlying(char, on)
		if char then
			HK.flying[char] = on and true or nil
		end
	end
	function HK.isFlying(char)
		return char:GetAttribute("HawksFlying") == true or HK.flying[char] == true
	end
	-- (round 90) the wing-braked fall: the server's HawksFalling (everyone
	-- sees it), or his own machine's word before it arrives (a plain table,
	-- cleared by HK.localFalling(char, false) - never weak-keyed)
	HK.falling = {}
	function HK.localFalling(char, on)
		if char then
			HK.falling[char] = (on == "Stoop" and "Stoop") or (on and true) or nil
			if on and HK.fallWatch then
				HK.fallWatch(char)
			end
		end
	end
	-- (true under the canopy, "Stoop" tucked on a long way down, else nil)
	function HK.isFalling(char)
		local mine = HK.falling[char]
		if mine ~= nil then
			return mine
		end
		local a = char:GetAttribute("HawksFalling")
		return (a == true or a == "Stoop") and a or nil
	end

	---------------------------------------------------------------------
	-- the driver: every frame, every Hawks near enough
	---------------------------------------------------------------------
	local spare = { A = {}, fan = {} }
	local spare2 = { A = {}, fan = {} }
	local function beatPose(rig, dt, kind, weak)
		local B = W.Beat or {}
		local times = (weak and B.Weak) or B[kind or "Hover"] or { 0.38, 0.26 }
		local down, up = times[1], times[2]
		local before = rig.beat
		rig.beat = (rig.beat + dt) % (down + up)
		if rig.beat < before then
			rig.lastBeat = os.clock() -- (a new downstroke starts)
			rig.jitter = weak and rand(-(B.Jitter or 6), B.Jitter or 6) or 0
		end
		-- 0 = the bottom of the stroke, 1 = the top
		local w
		if rig.beat < down then
			w = 1 - (1 - math.cos(math.pi * rig.beat / down)) / 2
		else
			w = (1 - math.cos(math.pi * (rig.beat - down) / up)) / 2
		end
		local downP, upP = HK.pose("FlapDown"), HK.pose("FlapUp")
		if kind == "Hover" then
			-- (hanging there: shallower beats round the spread)
			local spread = HK.pose("Spread")
			upP = blendPose(spread, upP, 0.78, spare2)
			downP = blendPose(spread, downP, 0.85, spare)
			return blendPose(downP, upP, w, { A = {}, fan = {} })
		end
		return blendPose(downP, upP, w, spare)
	end

	-- (round 86 review, hawks_ult) folded: the ult's longer wings fold a
	-- little higher (UltFolded), so the tips clear the street
	function HK.restName(rig)
		return (rig.k > (rig.kr or rig.k) * 1.05 and W.States.UltFolded) and "UltFolded" or "Folded"
	end
	-- what the wings should be doing now (and the body pose if he's flying)
	local function wanted(char, rig, now, dt)
		local o = HK.over[char]
		if o and now < o.Until then
			if o.State == "Flap" then
				return beatPose(rig, dt, "Climb"), o.Rate
			elseif o.State == "Rest" then
				return HK.pose(HK.restName(rig)), o.Rate
			end
			return HK.pose(o.State), o.Rate
		end
		if HK.isFlying(char) then
			local root = char:FindFirstChild("HumanoidRootPart")
			local v = root and root.AssemblyLinearVelocity or Vector3.zero
			local flat = Vector3.new(v.X, 0, v.Z).Magnitude
			local weak = (tonumber(char:GetAttribute("Feathers")) or 0) < (SPEC.Low or 20)
			if (HK.boosts[char] or 0) > now or v.Y < -45 then
				rig.flightPose = "HawksDive"
				return HK.pose("Tuck"), 14
			elseif v.Y > 8 then
				rig.flightPose = "HawksClimb"
				return beatPose(rig, dt, "Climb", weak), 30
			elseif flat > 30 and not weak then
				rig.flightPose = "HawksGlide"
				-- (one beat now and then to hold his height)
				if now - (rig.glideBeat or 0) > 3 then
					rig.glideBeat = now
					rig.beat = 0
				end
				if now - rig.glideBeat < 0.64 then
					return beatPose(rig, dt, "Hover"), 26
				end
				return HK.pose("Glide"), 10
			end
			rig.flightPose = "HawksHover"
			return beatPose(rig, dt, "Hover", weak), 30
		end
		rig.flightPose = nil
		-- (round 90) the wing-braked fall: the canopy (Brake), a beat now and
		-- then; tucked for the stoop on a long way down
		local falling = HK.isFalling(char)
		if falling == "Stoop" then
			return HK.pose("Tuck"), 12
		elseif falling then
			local F = Q.Fall or {}
			if now - (rig.brakeBeat or 0) > (F.Beat or 1.3) then
				rig.brakeBeat = now
				rig.beat = 0
			end
			if now - rig.brakeBeat < 0.5 then
				return beatPose(rig, dt, "Hover"), 24
			end
			return HK.pose("Brake"), 9
		end
		local ws = char:GetAttribute("WingState")
		if ws and ws ~= "Rest" and W.States[ws] then
			return HK.pose(ws), 12
		end
		-- (round 90) on his feet: at a run the wings fold tight (Guard); pulled
		-- up out of a run, they flutter open and settle
		local R = Q.Run or {}
		local root = char:FindFirstChild("HumanoidRootPart")
		local v = root and root.AssemblyLinearVelocity or Vector3.zero
		local flat = Vector3.new(v.X, 0, v.Z).Magnitude
		if flat > (R.RunSpeed or 26) and math.abs(v.Y) < 20 then
			rig.ranAt = now
			return HK.pose("Guard"), 7
		end
		if rig.ranAt and now - rig.ranAt < (R.StopTime or 0.35) and flat < (R.StopSpeed or 3) then
			rig.ranAt = nil
			HK.setWing(char, "Spread", (R.Flutter or 0.32) * 0.5, 20)
			task.delay((R.Flutter or 0.32) * 0.5, function()
				if char.Parent then
					HK.setWing(char, "Rest", (R.Flutter or 0.32) * 0.5, 14)
				end
			end)
			if root and nearCamera(root.Position, 60) then
				VFX.PlaySound("WingFold", root.Position, 0.55)
			end
		end
		-- at rest: folded, breathing (each wing a hair out of step)
		return HK.pose(HK.restName(rig)), 8, true
	end

	local function writeRig(rig, dt, now)
		local k = rig.k
		local cur = rig.cur
		for side, s in rig.sides do
			local A = cur.A
			local breath = 0
			if rig.resting then
				breath = math.sin(now * math.pi * 0.5 + (side > 0 and 0 or 0.7)) * 4
			end
			local a1 = breath ~= 0 and (CFrame.Angles(0, 0, math.rad(breath)) * A[1]) or A[1]
			local jit = (rig.jitter or 0) ~= 0 and CFrame.Angles(0, 0, math.rad(rig.jitter * math.sin(now * 40))) or nil
			if jit then
				a1 = jit * a1
			end
			local j1, j2, j3 = s.joints[1], s.joints[2], s.joints[3]
			if j1 then
				local kr = rig.kr or k
				j1.C0 = CFrame.new(W.Root.X * side * kr, W.Root.Y * kr, W.Root.Z * kr) * (side < 0 and CFrame.Angles(0, math.pi, 0) or CFrame.new()) * HK.mirror(a1, side)
			end
			if j2 then
				j2.C0 = HK.mirror(CFrame.new(W.Bones[1] * k, 0, 0) * a1:Inverse() * A[2], side)
			end
			if j3 then
				j3.C0 = HK.mirror(CFrame.new(W.Bones[2] * k, 0, 0) * A[2]:Inverse() * A[3], side)
			end
			local ease = 1 - math.exp(-12 * dt)
			for _, fe in s.feathers do
				-- (round 86, C2) a spent feather nothing threw: gone now; one
				-- thrown that the count never took (a refused move): back
				if fe.goAt and now >= fe.goAt then
					fe.goAt = nil
					fe.slideTo = -0.3 * fe.f.Len
					fe.tTo = 1
				end
				if fe.away and now >= fe.away then
					fe.away, fe.waitHome = nil, nil
					if fe.shown and fe.tTo > 0.5 then
						fe.slide, fe.slideTo, fe.tTo = -0.45 * fe.f.Len, 0, 0
						setTransparency(fe, 0.85)
					end
				end
				-- the slide (growing out / tucking away), the fade, a twitch
				if fe.slide ~= fe.slideTo then
					fe.slide += (fe.slideTo - fe.slide) * ease
					if math.abs(fe.slide - fe.slideTo) < 0.01 then
						fe.slide = fe.slideTo
					end
				end
				if fe.tTo ~= fe.t then
					local nt = fe.t + (fe.tTo - fe.t) * math.min(1, (fe.tTo > fe.t and 22 or 9) * dt)
					setTransparency(fe, math.abs(nt - fe.tTo) < 0.02 and fe.tTo or nt)
				end
				if fe.ext ~= fe.extTo then
					fe.ext += (fe.extTo - fe.ext) * math.min(1, 18 * dt)
					if math.abs(fe.ext - fe.extTo) < 0.01 then
						fe.ext = fe.extTo
					end
				end
				if fe.t < 0.99 then
					local f = fe.f
					local fan = cur.fan[f.Row] or cur.fan.S
					local phi = f.Phi * fan[1] + fan[2] + fe.ext * 10
					local slide = fe.slide + fe.ext * 0.25
					-- (far off, or a low-end machine posing someone else's: only a turn you'd see)
					if math.abs(phi - (fe.phi or 1e9)) > (rig.coarse or 0.15) or slide ~= fe.lastSlide then
						fe.phi, fe.lastSlide = phi, slide
						local vane = (W.Vane or 0.78) * f.Len * k
						fe.hinge.C0 = HK.mirror(CFrame.new(f.At * k, f.Y * k, f.Z * k) * CFrame.Angles(0, 0, math.rad(phi)) * CFrame.new(0, -vane / 2 + slide * k, 0), side)
					end
				end
			end
		end
	end

	-- your own wings: faded with the camera close behind you, or hidden
	local function ownFade(rig, root, dt)
		local me = Players.LocalPlayer
		local cam = workspace.CurrentCamera
		local want = 0
		if me and me:GetAttribute("HideMyWings") == true then
			want = 1
		elseif cam and root then
			local rel = cam.CFrame.Position - root.Position
			if rel.Magnitude < (W.Fade or 7) and rel:Dot(root.CFrame.LookVector) < 0.5 then
				want = 0.55
			end
		end
		rig.ltm += (want - rig.ltm) * math.min(1, 10 * dt)
		if math.abs(rig.ltm - want) < 0.01 or want >= 1 then
			rig.ltm = want -- (hidden by the setting: at once)
		end
		-- (round 86 review) whatever hides your body hides them too: the
		-- camera zoomed into your head, a marble, a vanish (hideCharacter /
		-- PV.hideWhile set it on every part of you, the wings included - and
		-- this used to write it straight back to 0)
		local body = HK.bodyHidden(rig.char)
		local out = math.max(rig.ltm, body)
		-- (written when it changes - or when something else wrote over it:
		-- the camera's own fade sets these on your body too)
		local sample = rig.parts[1]
		if out ~= rig.ltmOut or (sample and math.abs(HK.ltmOf(sample) - out) > 1e-3) then
			rig.ltmOut = out
			for _, p in rig.parts do
				p.LocalTransparencyModifier = out
			end
		end
		HK.bladeFade(rig.char, math.max(rig.ltm >= 1 and 0 or rig.ltm * 0.5, body))
	end
	-- how hidden his body is on this screen (his torso's LocalTransparencyModifier)
	local function readLtm(p)
		return p.LocalTransparencyModifier
	end
	function HK.ltmOf(p)
		local ok, v = pcall(readLtm, p) -- (the test harness has no default for it)
		return ok and tonumber(v) or 0
	end
	function HK.bodyHidden(char)
		local torso = char and (char:FindFirstChild("Torso") or char:FindFirstChild("UpperTorso"))
		return torso and HK.ltmOf(torso) or 0
	end
	-- the drawn blades (in the effects folder, not on him): as hidden as he is
	function HK.bladeFade(char, value)
		local d = HK.drawn[char]
		if d and d.ltm ~= value then
			d.ltm = value
			for _, p in d.parts do
				p.LocalTransparencyModifier = value
			end
		end
	end

	-- ambient: a covert slides out, twitches and settles (calm body, busy feathers)
	local function ambient(char, rig, now)
		if now < rig.twitchAt then
			return
		end
		rig.twitchAt = now + rand(3, 6)
		local list = {}
		for _, s in rig.sides do
			for _, fe in s.feathers do
				if fe.shown and (fe.f.Row == "C" or fe.f.Row == "S") then
					table.insert(list, fe)
				end
			end
		end
		local fe = list[rng:NextInteger(1, math.max(#list, 1))]
		if fe then
			fe.extTo = 1
			task.delay(0.22, function()
				fe.extTo = 0
			end)
		end
	end
	-- a hit on him jolts a few feathers
	function HK.jolt(char, n)
		local rig = HK.rigs[char]
		if not rig then
			return
		end
		for _ = 1, n or 4 do
			local side = rng:NextInteger(0, 1) == 1 and 1 or -1
			local list = {}
			for _, fe in rig.sides[side].feathers do
				if fe.shown then
					table.insert(list, fe)
				end
			end
			local fe = list[rng:NextInteger(1, math.max(#list, 1))]
			if fe then
				fe.extTo = 0.8
				task.delay(0.1, function()
					fe.extTo = 0
				end)
			end
		end
	end

	-- every Hawks this machine can see (players and dummies)
	local watched = setmetatable({}, { __mode = "k" }) -- [char] = his connections
	local function watch(char)
		if watched[char] then
			return
		end
		local conns = {}
		watched[char] = conns
		for _, key in { "Feathers", "FeathersMax" } do
			table.insert(conns, char:GetAttributeChangedSignal(key):Connect(function()
				HK.refresh(char, false)
			end))
		end
		-- (round 90) under his wings in a fall: the pose and the wind on every screen
		table.insert(conns, char:GetAttributeChangedSignal("HawksFalling"):Connect(function()
			if char:GetAttribute("HawksFalling") ~= nil and HK.fallWatch then
				HK.fallWatch(char)
			end
		end))
		local hum = char:FindFirstChildOfClass("Humanoid")
		if hum then
			local last = hum.Health
			table.insert(conns, hum.HealthChanged:Connect(function(h)
				if h < last - 0.5 then
					HK.jolt(char, 4)
				end
				last = h
			end))
			table.insert(conns, hum.Died:Connect(function()
				HK.stopMoves(char) -- (round 86, C2)
			end))
		end
	end
	local function unwatch(char)
		for _, c in watched[char] or {} do
			c:Disconnect()
		end
		watched[char] = nil
		HK.rigs[char] = nil
		HK.falling[char] = nil -- (round 90)
		if HK.growing then
			HK.growing[char] = nil
		end
		if HK.flocks then
			HK.flocks[char] = nil
		end
		HK.stopLoops(char)
		HK.blades(char, false, true)
		HK.stopMoves(char) -- (round 86, C2)
	end
	local list = {}
	local function scan()
		table.clear(list)
		for _, plr in Players:GetPlayers() do
			local c = plr.Character
			if c and c.Parent and c:GetAttribute("Quirk") == "FierceWings" then
				table.insert(list, c)
			end
		end
		local dummies = workspace:FindFirstChild("Dummies")
		for _, d in dummies and dummies:GetChildren() or {} do
			if d:GetAttribute("Quirk") == "FierceWings" then
				table.insert(list, d)
			end
		end
		local seen = {}
		for _, c in list do
			seen[c] = true
			watch(c)
		end
		for c in watched do
			if not seen[c] then
				unwatch(c)
			end
		end
	end
	HK.scan = scan
	local lastScan = 0
	function HK.step(dt)
		local now = os.clock()
		if now - lastScan > 0.5 then
			lastScan = now
			scan()
		end
		local cam = workspace.CurrentCamera
		local camPos = cam and cam.CFrame.Position
		local me = Players.LocalPlayer and Players.LocalPlayer.Character
		-- (round 86 review) within Cull: every frame; out to FarCull - a Hawks
		-- up in the sky, where he usually is - the bones and fans FarRate times
		-- a second (they used to freeze mid-beat past 150); a low-end machine
		-- halves it all and skips the twitches
		local low = IceKit.lowEnd()
		local nearAt = low and (W.LowCull or 80) or (W.Cull or 150)
		local farAt = low and (W.LowFarCull or 300) or (W.FarCull or 500)
		local farEvery = 1 / (low and (W.LowFarRate or 10) or (W.FarRate or 15))
		for char in watched do
			local root = char.Parent and char:FindFirstChild("HumanoidRootPart")
			local rig = root and HK.bind(char)
			local dist = rig and ((char == me or not camPos) and 0 or (camPos - root.Position).Magnitude) or math.huge
			local step = dt
			local go = dist < farAt
			if go and dist >= nearAt then
				rig.farDt = (rig.farDt or 0) + dt
				if rig.farDt < farEvery then
					go = false
				else
					step = math.min(rig.farDt, 0.25)
					rig.farDt = 0
				end
			end
			if go then
				rig.coarse = (dist >= nearAt and 1.5) or ((low and char ~= me) and 0.8) or nil
				local target, rate, resting = wanted(char, rig, now, step)
				if target then
					if not rig.cur then
						rig.cur = blendPose(target, target, 0)
					else
						blendPose(rig.cur, target, 1 - math.exp(-(rate or 12) * step), rig.cur)
					end
					rig.resting = resting == true
					writeRig(rig, step, now)
				end
				if resting and (char == me or (not low and dist < 60)) then
					ambient(char, rig, now)
				end
				if char == me then
					ownFade(rig, root, dt)
				elseif HK.drawn[char] then
					HK.bladeFade(char, HK.bodyHidden(char)) -- (hidden on this screen: his blades too)
				end
			end
		end
	end
	pcall(function()
		RunService:BindToRenderStep("HawksWings", Enum.RenderPriority.Camera.Value + 2, function(dt)
			local ok, err = pcall(HK.step, math.min(dt, 0.1))
			if not ok and not HK.warned then
				HK.warned = true
				warn("[HawksWings] " .. tostring(err))
			end
		end)
	end)

	---------------------------------------------------------------------
	-- looped beds on his body (the flight's wind, the cyclone's roar): a
	-- cue's first layer, first take, looped - its Start skipped every lap
	---------------------------------------------------------------------
	function HK.loop(char, cue, volume)
		local root = char and char:FindFirstChild("HumanoidRootPart")
		if not root then
			return nil
		end
		HK.loops[char] = HK.loops[char] or {}
		local s = HK.loops[char][cue]
		if s and s.Parent then
			return s
		end
		local layer = type(Config.Sounds[cue]) == "table" and Config.Sounds[cue][1]
		local take = layer and layer.Id
		if type(take) == "table" then
			take = take[1]
		end
		local id = type(take) == "table" and take.Id or take
		if type(id) ~= "string" or id == "" then
			return nil
		end
		s = Instance.new("Sound")
		s.Name = "HawksLoop"
		s.SoundId = id
		s.Looped = true
		s.Volume = 0
		s.PlaybackSpeed = type(layer.Speed) == "number" and layer.Speed or 1
		s.RollOffMaxDistance = 260
		s.SoundGroup = SoundService:FindFirstChild("QuirkSFX")
		local start = type(take) == "table" and take.Start or nil
		if start then
			s.TimePosition = start
			-- (round 86 review) and every lap after: a looped Sound restarts at 0
			-- otherwise, replaying the take's lead-in each time round
			pcall(function()
				s.PlaybackRegionsEnabled = true
				s.LoopRegion = NumberRange.new(start, 60000)
			end)
		end
		s.Parent = root
		pcall(function()
			s:Play()
		end)
		HK.loops[char][cue] = s
		s:SetAttribute("Full", (layer.Volume or 1) * (volume or 1))
		return s
	end
	function HK.loopVolume(char, cue, k)
		local s = HK.loops[char] and HK.loops[char][cue]
		if s and s.Parent then
			s.Volume = math.clamp((s:GetAttribute("Full") or 1) * k, 0, 8)
		end
	end
	function HK.stopLoop(char, cue, fade)
		local s = HK.loops[char] and HK.loops[char][cue]
		if s then
			HK.loops[char][cue] = nil
			tween(s, fade or 0.3, { Volume = 0 })
			task.delay((fade or 0.3) + 0.05, function()
				s:Destroy()
			end)
		end
	end
	function HK.stopLoops(char)
		for cue in HK.loops[char] or {} do
			HK.stopLoop(char, cue, 0.2)
		end
	end

	---------------------------------------------------------------------
	-- feathers as things in the air (client parts: a crimson blade, a pale
	-- edge on the tip, a short trail)
	---------------------------------------------------------------------
	function HK.feather(cf, len, trail)
		local L = len or 1.3
		local p = newPart(Vector3.new(0.24, L, 0.05), cf, HK.RED, Enum.Material.SmoothPlastic)
		p.Name = "HawksFeather"
		p.Reflectance = 0.05
		local tip = newPart(Vector3.new(0.05, L * 0.28, 0.24), cf, HK.TIP, Enum.Material.SmoothPlastic)
		tip.Name = "HawksFeather"
		local w = Instance.new("WeldConstraint")
		w.Part0, w.Part1 = p, tip
		tip.CFrame = cf * CFrame.new(0, -L * 0.62, 0)
		tip.Anchored = false
		tip.Massless = true
		w.Parent = tip
		tip.Parent = p
		if trail then
			local a0 = Instance.new("Attachment")
			a0.Position = Vector3.new(0, L * 0.4, 0)
			a0.Parent = p
			local a1 = Instance.new("Attachment")
			a1.Position = Vector3.new(0, -L * 0.4, 0)
			a1.Parent = p
			local t = Instance.new("Trail")
			t.Attachment0, t.Attachment1 = a0, a1
			t.Color = ColorSequence.new(trail == "pale" and HK.PALE or HK.LIT, Color3.new(1, 1, 1))
			t.Transparency = NumberSequence.new(0.35, 1)
			t.LightEmission = 0.6
			t.Lifetime = 0.1
			t.FaceCamera = true
			t.Parent = p
		end
		return p
	end
	-- red flecks shed off a cut, drifting down spinning
	function HK.flecks(pos, n, spread)
		for _ = 1, n or 3 do
			local p = newPart(Vector3.new(0.25, 0.06, 0.6), CFrame.new(pos) * CFrame.Angles(rand(0, 6.28), rand(0, 6.28), 0), HK.LIT, Enum.Material.SmoothPlastic)
			local to = pos + Vector3.new(rand(-1, 1), rand(-2.5, -0.5), rand(-1, 1)) * (spread or 1.5)
			tween(p, rand(0.5, 0.8), { CFrame = CFrame.new(to) * CFrame.Angles(rand(0, 6.28), rand(0, 6.28), rand(0, 6.28)), Transparency = 1 }, Enum.EasingStyle.Sine)
			cleanup(p, 0.85)
		end
	end
	-- loose cosmetic feathers puffed off the wings, spiralling down
	function HK.shed(pos, n, out)
		for _ = 1, n or 6 do
			local cf = CFrame.new(pos + Vector3.new(rand(-1, 1), rand(-0.5, 1), rand(-1, 1))) * CFrame.Angles(rand(0, 6.28), rand(0, 6.28), rand(0, 6.28))
			local f = HK.feather(cf, rand(0.6, 1), nil)
			local drift = Vector3.new(rand(-1, 1), 0, rand(-1, 1)) * (out or 4)
			local down = groundPoint(pos)
			local fall = math.max(pos.Y - down.Y - 0.2, 1)
			local t = rand(1.1, 1.8)
			tween(f, t, { CFrame = CFrame.new(pos + drift + Vector3.new(0, -math.min(fall, 6), 0)) * CFrame.Angles(rand(0, 6.28), rand(0, 6.28), rand(0, 6.28)), Transparency = 1 }, Enum.EasingStyle.Sine)
			cleanup(f, t + 0.05)
		end
	end
	-- where a slot is now (or behind his shoulder when the wings aren't built)
	function HK.slotCF(char, side, slot)
		local rig = HK.rigs[char]
		local fe = rig and rig.sides[side] and rig.sides[side].feathers[slot]
		if fe and fe.part.Parent then
			return fe.part.CFrame
		end
		local root = char and char:FindFirstChild("HumanoidRootPart")
		return root and root.CFrame * CFrame.new(side * 1.3, 1.4, 0.9) or CFrame.new()
	end
	-- the slots n feathers leave from (round 86 review: they used to leave from
	-- feathers that stayed on the wing). The server spends before the volley
	-- flies, so the wings have already thinned: the first ones leave from the
	-- slots just hidden (the newest gaps first, wings in turn); the rest - the
	-- count curve hides fewer than are thrown - peel off the edge that's still
	-- showing, each of those feathers flicking out as it throws one (Flick)
	-- (round 86, C2 review) Only a spent feather still on the wing (its grace,
	-- HK.GRACE) counts as just hidden - an old gap has nothing to throw. An
	-- edge feather that's still showing is LENT (Loan: HK.leave hides it
	-- while it's out and it flies back into its own slot - unless the count
	-- has spent it by then); past every feather showing, the rest are copies
	-- (Copy: flicked off one that stays; they always come home, with a glint)
	function HK.launchSlots(char, n)
		local out = {}
		local rig = HK.rigs[char]
		if not rig then
			for i = 1, n do
				local slot = (W.Hide or {})[math.floor((i - 1) / 2) % math.max(#(W.Hide or {}), 1) + 1] or "C10"
				table.insert(out, { side = (i % 2 == 1) and 1 or -1, slot = slot })
			end
			return out
		end
		local gone, edge = { [1] = {}, [-1] = {} }, { [1] = {}, [-1] = {} }
		local now = os.clock()
		for side in gone do
			local list = W.Hide or {}
			for i = #list, 1, -1 do
				local fe = rig.sides[side].feathers[list[i]]
				if fe and not fe.shown and fe.goAt then
					table.insert(gone[side], { side = side, slot = list[i], at = i }) -- (newest gap first)
				end
			end
			for i, slot in list do
				local fe = rig.sides[side].feathers[slot]
				if fe and fe.shown and not (fe.away and now < fe.away) then
					table.insert(edge[side], { side = side, slot = slot, at = i, Flick = true, Loan = true }) -- (the next due to go first)
				end
			end
		end
		for _, pool in { gone, edge } do
			local i = 1
			while #out < n and (#pool[1] > 0 or #pool[-1] > 0) do
				local side = (i % 2 == 1 and #pool[1] > 0) and 1 or (#pool[-1] > 0 and -1 or 1)
				table.insert(out, table.remove(pool[side], 1))
				i += 1
			end
		end
		-- (more feathers than slots: round the edge again)
		local k = 1
		while #out < n do
			local again = out[k]
			table.insert(out, again and { side = again.side, slot = again.slot, Flick = true, Copy = true } or { side = (#out % 2 == 0) and 1 or -1, slot = "C10", Flick = true, Copy = true })
			k += 1
		end
		return out
	end
	-- (round 86, C2 review) a launch slot's feather off the wing: a spent one
	-- or a lent one leaves its slot (lent: till it's back, `hold` at most);
	-- a copy flicks the feather that stays
	function HK.launch(char, s, hold)
		if s.Copy then
			HK.flick(char, s.side, s.slot)
		else
			HK.leave(char, s.side, s.slot, hold)
		end
	end
	-- is this launch slot's feather owed back - lent, and the count still
	-- shows its slot (so it flies home into it)? (a copy always comes home)
	function HK.owed(char, s)
		if not s then
			return false
		end
		if s.Copy then
			return true
		end
		local rig = HK.rigs[char]
		local fe = s.Loan and rig and rig.sides[s.side] and rig.sides[s.side].feathers[s.slot]
		return fe ~= nil and fe.shown == true and fe.waitHome ~= nil and fe.away ~= nil and os.clock() < fe.away
	end
	-- a feather still on the wing flicks out as it throws one
	function HK.flick(char, side, slot)
		local rig = HK.rigs[char]
		local fe = rig and rig.sides[side] and rig.sides[side].feathers[slot]
		if fe and fe.shown then
			fe.extTo = 1
			task.delay(0.12, function()
				fe.extTo = 0
			end)
		end
	end

	---------------------------------------------------------------------
	-- (round 86, C2) FEATHERS LEAVE AND COME HOME. A spent feather stays
	-- on the wing a moment (HK.GRACE: refresh) so a move can throw it from
	-- right there: HK.leave hides it the instant its flying copy appears.
	-- A feather flying back (HK.homeward) lands in a slot: the refund's
	-- slot takes it with a click (HK.homeTo, from refresh) - landed before
	-- the refund came, it's parked on the wing till it does; the refund
	-- first, the slot waits hidden for it. So a refund reads as feathers
	-- flying back in, never as regrowth (that one slides out slowly).
	---------------------------------------------------------------------
	HK.GRACE = 0.55
	-- his moves' leftovers go with him: dead, a new body, someone else
	-- (the cyclone ends, the carry's pins drop, parked feathers go)
	function HK.stopMoves(char)
		local c = HK.carries and HK.carries[char]
		if c then
			c.phase = "gone"
			HK.carries[char] = nil
		end
		local cyc = HK.cyclones and HK.cyclones[char]
		if cyc and cyc.finish then
			cyc.finish(true) -- (round 86, C2 review: its ring drops now - never left hanging)
		end
		local h = HK.homes[char]
		if h then
			for _, p in h.parked do
				if p.part.Parent then
					p.part:Destroy()
				end
			end
			HK.homes[char] = nil
		end
	end
	-- (his hits' stars and streaks: crimson, a cut)
	if VFX.HitTints then
		VFX.HitTints.FierceWings = Color3.fromRGB(255, 58, 54)
	end
	-- a feather in flight, point first (HK.feather's -Y is its point) along dir
	function HK.aim(p, dir)
		-- (round 90 review) never along a zero or NaN direction (a NaN CFrame):
		-- the homecoming's paths can stand still for a frame
		if dir ~= dir or dir.Magnitude < 1e-4 then
			dir = UP
		end
		-- (straight up or down: lookAt's own up is parallel to it - another one)
		local up = math.abs(dir.Y) > 0.999 * dir.Magnitude and Vector3.zAxis or UP
		return CFrame.lookAt(p, p + dir, up) * CFrame.Angles(math.rad(90), 0, 0)
	end
	-- a thin streak behind a flying feather (crimson; pale coming home)
	function HK.trail(part, kind, width, life)
		local w = (width or 0.28) / 2
		local a0 = Instance.new("Attachment")
		a0.Name = "HawksTrail"
		a0.Position = Vector3.new(w, 0, 0)
		a0.Parent = part
		local a1 = Instance.new("Attachment")
		a1.Name = "HawksTrail"
		a1.Position = Vector3.new(-w, 0, 0)
		a1.Parent = part
		local t = Instance.new("Trail")
		t.Name = "HawksTrail"
		t.Attachment0, t.Attachment1 = a0, a1
		if kind == "pale" then
			t.Color = ColorSequence.new(Color3.fromRGB(255, 238, 232), HK.PALE)
			t.LightEmission = 0.6
		else
			-- (round 86, C2 review: crimson, not salmon - red, never pink)
			t.Color = ColorSequence.new(Color3.fromRGB(255, 72, 60), Color3.fromRGB(150, 14, 24))
			t.LightEmission = 0.1
		end
		t.Transparency = NumberSequence.new({ NumberSequenceKeypoint.new(0, 0.05), NumberSequenceKeypoint.new(1, 1) })
		t.WidthScale = NumberSequence.new(1, 0.3)
		t.Lifetime = life or 0.16
		t.FaceCamera = true
		t.Parent = part
		return t
	end
	function HK.dart(cf, len, kind, life)
		local f = HK.feather(cf, len, nil)
		HK.trail(f, kind, nil, life)
		return f
	end
	HK.homes = setmetatable({}, { __mode = "k" }) -- [char] = { en route, parked = { { side, slot, part, til } } }
	function HK.leave(char, side, slot, hold)
		local rig = HK.rigs[char]
		local fe = rig and rig.sides[side] and rig.sides[side].feathers[slot]
		if fe then
			fe.goAt = nil
			fe.away = os.clock() + (hold or 1.2)
			fe.slide, fe.slideTo = -0.3 * fe.f.Len, -0.3 * fe.f.Len
			setTransparency(fe, 1)
			fe.tTo = 1
			-- (round 86, C2 review) one the count still shows is lent: its slot
			-- waits for it (HK.homeward lands it there; if it never comes, it
			-- grows back when `hold` runs out)
			if fe.shown then
				fe.waitHome = "loan"
			end
		end
	end
	local function homeOf(char)
		local h = HK.homes[char]
		if not h then
			h = { enRoute = 0, parked = {} }
			HK.homes[char] = h
		end
		return h
	end
	-- (a slot taken by one coming home: there at once, with a little kick)
	local function landIn(char, fe, quiet)
		fe.goAt, fe.away, fe.waitHome = nil, nil, nil
		fe.slide, fe.slideTo, fe.tTo = 0, 0, 0
		setTransparency(fe, 0)
		fe.ext, fe.extTo = 0.8, 0
		local h = HK.homes[char]
		-- (a cyclone's worth landing together: a click every few frames, not 30 at once)
		if not quiet and not (h and os.clock() - (h.click or 0) < 0.06) then
			if h then
				h.click = os.clock()
			end
			local root = char:FindFirstChild("HumanoidRootPart")
			if root and nearCamera(root.Position, 90) then
				VFX.PlaySound("FeatherReturn", root.Position, 0.7)
			end
		end
	end
	-- refresh: a slot is showing again (a refund) - who fills it
	function HK.homeTo(char, side, slot, fe)
		local h = HK.homes[char]
		if (HK.bladeBack and (HK.bladeBack[char] or 0) > os.clock()) and fe.f.Row == "P" then
			landIn(char, fe, true) -- (a blade back in its gap)
			return "taken"
		end
		-- (round 86, C2 review) its own feather's still out (lent): it waits for that one
		if fe.waitHome == "loan" and fe.away and os.clock() < fe.away then
			return "wait"
		end
		if not h then
			return nil
		end
		local pick
		for i, p in h.parked do
			if p.side == side and p.slot == slot then
				pick = i
				break
			end
		end
		if not pick then
			for i, p in h.parked do
				if p.side == side then
					pick = i
					break
				end
			end
		end
		pick = pick or (#h.parked > 0 and 1 or nil)
		if pick then
			local p = table.remove(h.parked, pick)
			if p.part.Parent then
				p.part:Destroy()
			end
			h.lastTaken = os.clock()
			landIn(char, fe)
			return "taken"
		end
		if h.enRoute > 0 then
			fe.away = os.clock() + 0.9 -- (the one on its way takes it; if it never comes, it grows back)
			fe.waitHome = true
			return "wait"
		end
		return nil
	end
	-- a feather on its way home: lands when `arrive` is called (part, side,
	-- slot: its own slot first). copy: one flicked off a feather that stayed
	-- - with no slot waiting it glints into the wing, it's never parked
	function HK.homeward(char, copy)
		local h = homeOf(char)
		h.enRoute += 1
		local done = false
		return function(part, side, own)
			if done then
				return
			end
			done = true
			h.enRoute = math.max(h.enRoute - 1, 0)
			local rig = HK.rigs[char]
			if not (rig and char.Parent and part and part.Parent) then
				if part and part.Parent then
					part:Destroy()
				end
				return
			end
			-- its own slot, lent and waiting for it; else a slot already waiting
			-- for one (the refund came first - not another's lent slot: that
			-- one's kept for its own feather)
			local mine = own and rig.sides[side or 1] and rig.sides[side or 1].feathers[own]
			if mine and mine.shown and mine.waitHome then
				part:Destroy()
				h.lastTaken = os.clock()
				landIn(char, mine)
				return
			end
			for _, sd in { side or 1, -(side or 1) } do
				for slot, fe in rig.sides[sd].feathers do
					if fe.shown and fe.waitHome == true then
						part:Destroy()
						h.lastTaken = os.clock()
						landIn(char, fe)
						return
					end
				end
			end
			-- else parked in the next gap to fill till the refund comes (a few at most)
			local sd = side or 1
			local best, bestAt
			for slot, fe in rig.sides[sd].feathers do
				local at = HIDE_AT[slot]
				local taken = false
				for _, p in h.parked do
					if p.side == sd and p.slot == slot then
						taken = true
					end
				end
				if at and not fe.shown and not taken and (not bestAt or at > bestAt) then
					best, bestAt = slot, at
				end
			end
			-- (a refund that's just been flown in: the rest needn't wait for one;
			-- your own wings hidden - HIDE MY WINGS, a marble: nothing to park on)
			local me = Players.LocalPlayer
			local hidden = me and me.Character == char and (me:GetAttribute("HideMyWings") == true or HK.bodyHidden(char) > 0.5)
			if not best or hidden or copy or #h.parked >= 6 or os.clock() - (h.lastTaken or 0) < 0.8 then
				-- (more home than the refund gives back: in and gone with a glint)
				local at = part.CFrame.Position
				tween(part, 0.08, { Transparency = 1 })
				cleanup(part, 0.1)
				if nearCamera(at, 60) then
					sparks(at, 0.12, HK.PALE, Color3.new(1, 1, 1), 1)
				end
				VFX.PlaySound("FeatherReturn", at, 0.4)
				return
			end
			local p = { side = sd, slot = best, part = part, til = os.clock() + 1.4 }
			table.insert(h.parked, p)
			VFX.PlaySound("FeatherReturn", part.CFrame.Position, 0.5)
			HK.run(function()
				if not part.Parent then
					return false
				end
				if os.clock() > p.til or not char.Parent then
					local i = table.find(h.parked, p)
					if i then
						table.remove(h.parked, i)
					end
					tween(part, 0.15, { Transparency = 1 })
					cleanup(part, 0.16)
					return false
				end
				part.CFrame = HK.slotCF(char, p.side, p.slot)
				return true
			end)
		end
	end
	-- (round 90) THE HOMECOMING (Config FierceWings.Home). Every feather that
	-- comes back to him flies the same last stretch: it swings round him in
	-- a spiral (Turns, from Radius in, rising Rise, in Time seconds) and
	-- slots into its gap from behind - the right wing's coming round one way,
	-- the left wing's the other, so a volley's worth home reads as two
	-- streams wrapping round him and crossing in front. Coming from far off
	-- (Flock.From studs) with others (Flock.Min or more within a blink) they
	-- fly in as a flock first: a V, Gap studs between ranks, that peels into
	-- the spiral rank by rank. On a low-end machine they dart straight in.
	local HOME = Q.Home or {}
	HK.flocks = {} -- [char] = the flock forming now (plain table, cleared as it lands)
	-- where on its spiral a feather is, u (0..1) of the way from its entry
	-- (angle a0, radius r0, height y0 over his root) to its slot, which way
	-- round (spin: +1 the right wing's, -1 the left's), the slot's own world
	-- point last. The right wing's stream arcs up over his shoulders on the
	-- way round, the left's dips round his hips (Rise), so the two cross in a
	-- double helix into his back; both start where they are (no jump)
	function HK.spiralAt(root, a0, r0, y0, spin, u, slotP)
		local turns = HOME.Turns or 1.15
		local a = a0 + spin * turns * math.pi * 2 * u
		local r = r0 * (1 - u) ^ 1.35
		local c = root.Position
		local lift = (spin > 0 and (HOME.Rise or 1.4) or -(HOME.Rise or 1.4) * 0.8) * math.sin(math.pi * u)
		local p = c + Vector3.new(math.cos(a) * r, y0 + ((slotP.Y - c.Y) - y0) * u + lift, math.sin(a) * r)
		-- (the last of it eases onto the slot itself, behind his shoulder)
		local k = math.clamp((u - 0.62) / 0.38, 0, 1)
		k = k * k * (3 - 2 * k)
		return p:Lerp(slotP, k)
	end
	-- the spiral's way in for a feather at p: the angle it's at round him,
	-- how far out and how high it is (where it is now: no jump into it)
	function HK.spiralEntry(root, p, _side)
		local rel = p - root.Position
		local flatv = Vector3.new(rel.X, 0, rel.Z)
		local a = flatv.Magnitude > 0.05 and math.atan2(flatv.Z, flatv.X) or 0
		return a, math.max(flatv.Magnitude, 0.8), rel.Y
	end
	-- the flock a far feather joins (formed by the first of them; the others
	-- within a blink take the next ranks of the V behind it)
	function HK.flockFor(char, p, speed)
		local fl = HK.flocks[char]
		local now = os.clock()
		if fl and now - fl.born < 0.18 and not fl.landed and (fl.pos - p).Magnitude < 60 then
			fl.n += 1
			return fl, fl.n
		end
		fl = { pos = p, born = now, n = 1, speed = speed, landed = false }
		HK.flocks[char] = fl
		-- the leader: straight for the spiral's way in behind him, the V on it
		HK.run(function(dt)
			local root = char.Parent and char:FindFirstChild("HumanoidRootPart")
			if not root or fl.landed then
				fl.landed = true
				return false
			end
			local look = root.CFrame.LookVector
			local entry = root.Position - Vector3.new(look.X, 0, look.Z) * (HOME.Radius or 3.4) + UP * (HOME.Rise or 1.4)
			local d = entry - fl.pos
			if d.Magnitude < 1.2 or os.clock() - fl.born > 2.2 then
				fl.landed = true
				if HK.flocks[char] == fl then
					HK.flocks[char] = nil
				end
				return false
			end
			fl.dir = d.Unit
			fl.pos += fl.dir * math.min(fl.speed * dt, d.Magnitude)
			return true
		end)
		return fl, 1
	end
	-- a feather flying home along its way (a kick out first, a flock's V from
	-- far off, the spiral round him), a pale streak, landing in its slot:
	-- land(part, side, slot) when it's there
	function HK.flyHome(char, from, side, slot, speed, kick, land, copy)
		land = land or HK.homeward(char, copy)
		local f = HK.dart(from, 1.2, "pale")
		local p0 = from.Position
		local v = (kick or Vector3.zero)
		if v.X ~= v.X or v.Y ~= v.Y or v.Z ~= v.Z then
			v = Vector3.zero -- (round 86, C2 review: a zero vector's .Unit is NaN - never fly on one)
		end
		local t0 = os.clock()
		local root0 = char:FindFirstChild("HumanoidRootPart")
		local far = root0 and (p0 - root0.Position).Magnitude or 0
		-- (at least speed; from far off - a miss 200 studs down the street -
		-- it darts back in about half a second)
		speed = math.max(speed or 160, (HK.slotCF(char, side, slot).Position - p0).Magnitude / 0.45)
		local spiral = not IceKit.lowEnd() or HOME.LowSpiral == true
		local FL = HOME.Flock or {}
		local flock, rank
		if spiral and far > (FL.From or 14) then
			flock, rank = HK.flockFor(char, p0, speed)
		end
		local phase, sp = "in", nil
		HK.run(function(dt)
			if not f.Parent then
				land(nil, side, slot)
				return false
			end
			local root = char.Parent and char:FindFirstChild("HumanoidRootPart")
			local slotCF = HK.slotCF(char, side, slot)
			local to = slotCF.Position
			if not root or os.clock() - t0 > 2.4 then
				f.CFrame = slotCF
				land(f, side, slot)
				return false
			end
			v = v * math.exp(-8 * dt)
			local prev = p0
			if phase == "in" then
				-- (the flock's place in the V, or straight for him)
				local aim = to
				if flock and not flock.landed and flock.dir and rank > 1 then
					local back = -flock.dir
					local across = flock.dir:Cross(UP)
					across = across.Magnitude > 0.05 and across.Unit or Vector3.new(1, 0, 0)
					local k = math.floor(rank / 2)
					aim = flock.pos + back * k * (FL.Gap or 1.1) + across * (rank % 2 == 0 and 1 or -1) * k * (FL.Spread or 0.7)
				elseif flock and not flock.landed then
					aim = flock.pos
				end
				local d = aim - p0
				local step = math.min(speed * dt * math.clamp((os.clock() - t0) * 6, 0.3, 1), d.Magnitude + speed * dt * 0.2)
				p0 += (d.Magnitude > 1e-3 and d.Unit * step or Vector3.zero) + v * dt
				-- (close enough: into the spiral - or, no spiral, straight in)
				local near = (p0 - root.Position)
				if Vector3.new(near.X, 0, near.Z).Magnitude < (HOME.Radius or 3.4) * 1.7 or (to - p0).Magnitude <= 0.6 then
					if spiral and (to - p0).Magnitude > 1 then
						local a0, r0, y0 = HK.spiralEntry(root, p0, side)
						sp = { a0 = a0, r0 = r0, y0 = y0, t = os.clock(), spin = side > 0 and 1 or -1 }
						phase = "spiral"
						-- (round 90 review) the stream whipping round him: FeatherHome
						-- (configured, never played) - once a flock, not every feather
						local rig = HK.rigs[char]
						if rig and os.clock() - (rig.homeWhoosh or 0) > 0.3 and nearCamera(root.Position, 90) then
							rig.homeWhoosh = os.clock()
							VFX.PlaySound("FeatherHome", root.Position, 0.8)
						end
					else
						f.CFrame = slotCF
						land(f, side, slot)
						return false
					end
				end
			end
			if phase == "spiral" then
				local u = math.clamp((os.clock() - sp.t) / (HOME.Time or 0.34), 0, 1)
				p0 = HK.spiralAt(root, sp.a0, sp.r0, sp.y0, sp.spin, u, to)
				if u >= 1 then
					f.CFrame = slotCF
					land(f, side, slot)
					return false
				end
			end
			local dv = p0 - prev
			f.CFrame = HK.aim(p0, dv.Magnitude > 1e-3 and dv.Unit or (to - p0).Unit)
			return true
		end)
		return f
	end
	-- (round 90) a blade going home (HK.blades' sheathe): a short spiral into
	-- its gap, a click as it lands
	function HK.homeArc(char, from, side, slot, time)
		local root = char:FindFirstChild("HumanoidRootPart")
		local f = HK.feather(from, 2.4, "pale")
		if not root or (IceKit.lowEnd() and HOME.LowSpiral ~= true) then
			local to = HK.slotCF(char, side, slot)
			tween(f, time or 0.25, { CFrame = to, Transparency = 0.6 }, Enum.EasingStyle.Quad, Enum.EasingDirection.In)
			cleanup(f, (time or 0.25) + 0.02)
			task.delay(time or 0.25, function()
				VFX.PlaySound("FeatherReturn", to.Position, 0.8)
			end)
			return f
		end
		local a0, r0, y0 = HK.spiralEntry(root, from.Position, side)
		local t0, p = os.clock(), from.Position
		HK.run(function()
			local slotP = HK.slotCF(char, side, slot).Position
			if not f.Parent or not root.Parent then
				if f.Parent then
					f:Destroy()
				end
				return false
			end
			local u = math.clamp((os.clock() - t0) / (time or 0.26), 0, 1)
			local q = HK.spiralAt(root, a0, r0, y0, side > 0 and 1 or -1, u, slotP)
			local dv = q - p
			p = q
			f.CFrame = HK.aim(p, dv.Magnitude > 1e-3 and dv.Unit or UP)
			if u >= 1 then
				VFX.PlaySound("FeatherReturn", slotP, 0.8)
				tween(f, 0.06, { Transparency = 1 })
				cleanup(f, 0.08)
				return false
			end
			return true
		end)
		return f
	end
	-- (round 90) REGROWTH comes home too: a feather the count grows back
	-- appears as a glint out in the air round him (Grow.Radius) and flies in
	-- on the spiral to its slot - the slot waits for it, then clicks (a soft
	-- one). At most Grow.Max in the air a Hawks; past that (or far off, on a
	-- low-end machine, your own wings hidden) it slides out of the wing as
	-- before. Returns true when it's flying one in
	HK.growing = {} -- [char] = how many are in the air
	function HK.homeGrow(char, side, slot, fe)
		local G = HOME.Grow or {}
		local root = char:FindFirstChild("HumanoidRootPart")
		if not root or IceKit.lowEnd() or (HK.growing[char] or 0) >= (G.Max or 8) or not nearCamera(root.Position, G.Cull or 140) then
			return false
		end
		local me = Players.LocalPlayer
		if me and me.Character == char and (me:GetAttribute("HideMyWings") == true or HK.bodyHidden(char) > 0.5) then
			return false
		end
		HK.growing[char] = (HK.growing[char] or 0) + 1
		-- out round him (behind him and to its own wing's side, mostly)
		local look = root.CFrame.LookVector
		local base = math.atan2(-look.Z, -look.X) -- (the angle straight behind him)
		local a = base + side * rand(0.3, 1.6)
		local R = (G.Radius or 6) * rand(0.8, 1.1)
		local p0 = root.Position + Vector3.new(math.cos(a) * R, rand(-0.4, 1) * (G.Rise or 1.5) + 1, math.sin(a) * R)
		-- the glint it comes out of
		local glint = newPart(Vector3.one * 0.3, CFrame.new(p0), Color3.fromRGB(255, 220, 210), Enum.Material.Neon, Enum.PartType.Ball)
		glint.Name = "HawksGlint"
		tween(glint, 0.16, { Size = Vector3.one * 1.1, Transparency = 1 })
		cleanup(glint, 0.18)
		local f = HK.dart(CFrame.new(p0), 1.1, "red", 0.12)
		for _, x in { f, f:FindFirstChildWhichIsA("BasePart") } do
			x.Transparency = 1
			tween(x, 0.1, { Transparency = 0 })
		end
		local a0, r0, y0 = HK.spiralEntry(root, p0, side)
		local t0, p = os.clock(), p0
		local T = G.Time or 0.5
		local function done(landed)
			HK.growing[char] = math.max((HK.growing[char] or 1) - 1, 0)
			if f.Parent then
				f:Destroy()
			end
			if landed and fe.shown and fe.waitHome == "grow" then
				fe.waitHome, fe.away = nil, nil
				fe.slide, fe.slideTo, fe.tTo = 0, 0, 0
				setTransparency(fe, 0)
				fe.ext, fe.extTo = 0.6, 0
				if nearCamera(root.Position, 60) then
					VFX.PlaySound("FeatherGrow", root.Position, 0.6)
				end
			end
		end
		HK.run(function()
			if not f.Parent or not root.Parent or not char.Parent then
				done(false)
				return false
			end
			local u = math.clamp((os.clock() - t0) / T, 0, 1)
			local slotP = HK.slotCF(char, side, slot).Position
			local q = HK.spiralAt(root, a0, r0, y0, side > 0 and 1 or -1, u, slotP)
			local dv = q - p
			p = q
			f.CFrame = HK.aim(p, dv.Magnitude > 1e-3 and dv.Unit or UP)
			if u >= 1 then
				done(true)
				return false
			end
			return true
		end)
		-- (its slot waits for it: hidden, and grown back by the old slide if it never lands)
		fe.waitHome = "grow"
		fe.away = os.clock() + T + 0.35
		fe.slide, fe.slideTo = 0, 0
		setTransparency(fe, 1)
		fe.tTo = 1
		return true
	end

	-- one shared per-frame list (everything that follows something: feathers
	-- in flight, parked ones, pins on a body); each job returns true to stay
	HK.jobs = {}
	function HK.run(job)
		table.insert(HK.jobs, job)
		if HK.jobConn then
			return
		end
		HK.jobConn = RunService.RenderStepped:Connect(function(dt)
			local now = os.clock()
			local list = HK.jobs
			HK.jobs = {}
			for _, j in list do
				local ok, more = pcall(j, math.min(dt, 0.1), now)
				if ok and more then
					table.insert(HK.jobs, j)
				elseif not ok and not HK.jobWarned then
					HK.jobWarned = true
					warn("[HawksMoves] " .. tostring(more))
				end
			end
			if #HK.jobs == 0 and HK.jobConn then
				HK.jobConn:Disconnect()
				HK.jobConn = nil
			end
		end)
	end

	-- THE CRIMSON IMPACT FRAME (the big hits): two frames - the world red
	-- and black, the bodies black cut-outs, a white slash torn across the
	-- screen through the hit; then white-hot grey - and back. Only on
	-- screens near it (or involved: in `bodies`). angle: the slash's tilt
	-- (round 86, C2 review) Involved (his screen, theirs): both frames, and
	-- the shared grey ImpactFrame doesn't stack on it. A bystander within
	-- HK.IMPACT_NEAR (45, the downslam's reach) gets the red frame alone -
	-- and nothing while a cutscene is on their screen
	HK.IMPACT_NEAR = 45
	function HK.impact(at, bodies, angle)
		if typeof(at) ~= "Vector3" then
			return
		end
		local me = Players.LocalPlayer and Players.LocalPlayer.Character
		local involved = false
		for _, b in bodies or {} do
			if b == me then
				involved = true
			end
		end
		if not involved and (VFX.InCinematic() or not nearCamera(at, HK.IMPACT_NEAR)) then
			return
		end
		HK.impactToken = (HK.impactToken or 0) + 1
		local token = HK.impactToken
		local Lighting = game:GetService("Lighting")
		-- (the grey frame a heavy hit gives the same two screens: not on top of this one)
		VFX.ImpactHeld = os.clock() + 0.15
		local grey = Lighting:FindFirstChild("ImpactFrame")
		if grey and grey:IsA("ColorCorrectionEffect") then
			grey.Enabled = false
		end
		local cc = Lighting:FindFirstChild("HawksImpact")
		if not cc then
			cc = Instance.new("ColorCorrectionEffect")
			cc.Name = "HawksImpact"
			cc.Parent = Lighting
		end
		cc.Enabled = true
		cc.Saturation, cc.Contrast, cc.Brightness, cc.TintColor = -1, 1.6, -0.06, Color3.fromRGB(255, 62, 58)
		local marks = {}
		if not IceKit.lowEnd() then
			for _, b in bodies or {} do
				if typeof(b) == "Instance" and b.Parent then
					local h = Instance.new("Highlight")
					h.Name = "HawksCutout"
					h.FillColor = Color3.new(0, 0, 0)
					h.FillTransparency = 0
					h.OutlineTransparency = 1
					h.DepthMode = Enum.HighlightDepthMode.Occluded
					h.Adornee = b
					h.Parent = folder
					table.insert(marks, h)
					cleanup(h, 0.2)
				end
			end
		end
		HK.screenSlash(at, angle or -16, involved and 0.1 or 0.07)
		task.delay(0.045, function()
			if HK.impactToken == token then
				if involved then
					cc.Saturation, cc.Contrast, cc.Brightness, cc.TintColor = -1, 2.2, 0.16, Color3.new(1, 1, 1)
				else
					cc.Enabled = false
					cc.TintColor = Color3.new(1, 1, 1)
				end
			end
			for _, h in marks do
				h:Destroy()
			end
		end)
		task.delay(0.09, function()
			if HK.impactToken == token then
				cc.Enabled = false
				cc.TintColor = Color3.new(1, 1, 1)
			end
		end)
	end
	-- the slash torn across the screen through `at`: a white core, red edges
	function HK.screenSlash(at, angle, life)
		local me = Players.LocalPlayer
		local gui = me and me:FindFirstChildOfClass("PlayerGui")
		if not gui then
			return nil
		end
		local cam = workspace.CurrentCamera
		local vs = cam and cam.ViewportSize or Vector2.new(1280, 720)
		if vs.X < 10 or vs.Y < 10 then
			vs = Vector2.new(1280, 720)
		end
		local cx, cy = 0.5, 0.45
		if cam and typeof(at) == "Vector3" then
			local ok, p = pcall(function()
				return cam:WorldToViewportPoint(at)
			end)
			if ok and typeof(p) == "Vector3" and p.Z > 0 then
				cx, cy = math.clamp(p.X / vs.X, 0.1, 0.9), math.clamp(p.Y / vs.Y, 0.1, 0.9)
			end
		end
		local sg = Instance.new("ScreenGui")
		sg.Name = "HawksSlash"
		sg.IgnoreGuiInset = true
		sg.ResetOnSpawn = false
		sg.DisplayOrder = 49
		local a = math.rad(angle)
		local function bar(thick, color, off)
			local f = Instance.new("Frame")
			f.AnchorPoint = Vector2.new(0.5, 0.5)
			f.Position = UDim2.new(cx, -math.sin(a) * off, cy, math.cos(a) * off)
			f.Size = UDim2.new(1.7, 0, 0, thick)
			f.Rotation = angle
			f.BackgroundColor3 = color
			f.BorderSizePixel = 0
			f.Parent = sg
			tween(f, life, { Size = UDim2.new(1.7, 0, 0, 1), BackgroundTransparency = 1 }, Enum.EasingStyle.Quad, Enum.EasingDirection.In)
			return f
		end
		bar(9, Color3.fromRGB(255, 60, 56), -12)
		bar(16, Color3.new(1, 1, 1), 0)
		bar(5, Color3.fromRGB(255, 60, 56), 13)
		sg.Parent = gui
		cleanup(sg, life + 0.05)
		return sg
	end
	-- a slash left hanging in the air: a crimson blade-thin plane with a
	-- white-hot core, drawn on from one end in `draw` seconds (-Z of cf along
	-- it); returns { edge, core } so a delayed cut can split it
	HK.CUT = Color3.fromRGB(255, 58, 54)
	function HK.cut(cf, len, width, draw)
		local start = cf * CFrame.new(0, 0, len / 2)
		local edge = newPart(Vector3.new(width, 0.05, 0.1), start, HK.CUT, Enum.Material.Neon)
		edge.Name = "HawksCut"
		local core = newPart(Vector3.new(width * 0.32, 0.06, 0.1), start, Color3.new(1, 1, 1), Enum.Material.Neon)
		core.Name = "HawksCut"
		for _, p in { edge, core } do
			tween(p, draw or 0.05, { Size = Vector3.new(p.Size.X, p.Size.Y, len), CFrame = cf }, Enum.EasingStyle.Quad, Enum.EasingDirection.Out)
		end
		return { edge = edge, core = core, cf = cf, len = len }
	end

	---------------------------------------------------------------------
	-- THE FEATHER BLADES: his two longest primaries out of the wings and in
	-- his hands while he swings (VFX.WeaponKit.Feather.Draw), back home
	-- Sheathe seconds after the last swing
	-- (round 90) Each blade is built along its own -Z from the grip (the
	-- fist): the bare quill behind it, the feather (its flat across X), its
	-- shaft, the point (the cutting edge on +X, a Neon line that flashes) and
	-- two attachments for its ribbon (BladeBase, BladePoint). Two grips:
	-- "M1" - his chain's (anim/moves_hawks_m1.py is posed for it): both hands,
	-- each blade M1.Grip degrees off the forearm toward the arm's front, so a
	-- swing of the arm is a swing of the blade, out past his silhouette and
	-- through them; "Sword" - his moves' (Swift Cut, Too Fast, the storm's
	-- dive were posed for it): the right blade across the fist, the left one
	-- reverse-gripped up the forearm. Drawn in one and asked for the other,
	-- they're re-gripped on the spot (HK.regrip).
	---------------------------------------------------------------------
	local M1C = Q.M1 or {}
	HK.SHEATHE = M1C.Sheathe or 1.4
	local SHAFT = Color3.fromRGB(96, 10, 18)
	function HK.gripCF(arm, mode, left)
		local y = (arm.Name == "Right Arm" or arm.Name == "Left Arm") and -arm.Size.Y / 2 + 0.15 or -0.1
		if mode == "M1" then
			return CFrame.new(0, y, 0) * CFrame.Angles(-math.rad(90 - (M1C.Grip or 40)), 0, 0)
		end
		if left then
			-- (round 86 review) the off hand's reverse grip: the quill out under
			-- the fist, the blade up along the outside of the forearm and angled
			-- off it, the point past the shoulder
			return CFrame.new(-(arm.Size.X / 2 + 0.06), -arm.Size.Y / 2 + 0.22, 0) * CFrame.Angles(0, 0, math.rad(14)) * CFrame.Angles(math.rad(90), 0, 0)
		end
		return CFrame.new(0, y, 0)
	end
	local function bladeOn(char, arm, mode, left)
		local m = Instance.new("Model")
		m.Name = "HawksBlade"
		m:SetAttribute("Grip", mode)
		local parts = {}
		local G = HK.gripCF(arm, mode, left)
		local full = M1C.Blade or 3
		local L = (mode ~= "M1" and left) and 2 or full
		local vane = L * ((M1C.Vane or 2.25) / full)
		local point = math.max(L - vane - 0.18, 0.2)
		local wid = M1C.Width or 0.42
		local function piece(class, name, size, cf, color, material)
			local p = Instance.new(class)
			p.Name = name
			p.Size = size
			p.Color = color
			p.Material = material or Enum.Material.SmoothPlastic
			p.CanCollide, p.CanQuery, p.CanTouch, p.Massless, p.CastShadow = false, false, false, true, false
			p.Anchored = false
			p.CFrame = arm.CFrame * G * cf
			local w = Instance.new("Weld")
			w.Part0, w.Part1, w.C0 = arm, p, G * cf
			w.Parent = p
			p.Parent = m
			table.insert(parts, p)
			return p
		end
		piece("Part", "HawksQuill", Vector3.new(0.09, 0.09, 0.6), CFrame.new(0, 0, 0.12), SHAFT) -- the bare quill: the grip
		local v = piece("Part", "HawksVane", Vector3.new(wid, 0.05, vane), CFrame.new(0, 0, -(0.18 + vane / 2)), HK.RED)
		v.Reflectance = 0.05
		piece("Part", "HawksShaft", Vector3.new(0.06, 0.07, vane), CFrame.new(0, 0, -(0.18 + vane / 2)), SHAFT) -- (on both faces)
		piece("WedgePart", "HawksPoint", Vector3.new(0.05, wid, point), CFrame.new(0, 0, -(0.18 + vane + point / 2)) * CFrame.Angles(0, 0, math.rad(90)), HK.TIP)
		local edge = piece("Part", "HawksEdge", Vector3.new(0.035, 0.035, L - 0.2), CFrame.new(wid / 2, 0, -(0.18 + (L - 0.2) / 2)), HK.EDGE, Enum.Material.Neon)
		edge.Transparency = 1
		-- (the ribbon runs from just past the fist to the point)
		local a0 = Instance.new("Attachment")
		a0.Name = "BladeBase"
		a0.Position = Vector3.new(0, 0, vane / 2 - 0.25)
		a0.Parent = v
		local a1 = Instance.new("Attachment")
		a1.Name = "BladePoint"
		a1.Position = Vector3.new(0, 0, -(vane / 2 + point))
		a1.Parent = v
		m.Parent = folder
		return m, parts, edge
	end
	local function build(char, d, mode)
		local r = char:FindFirstChild("Right Arm") or char:FindFirstChild("RightHand")
		local l = char:FindFirstChild("Left Arm") or char:FindFirstChild("LeftHand")
		if not r or not l then
			return nil
		end
		local mr, pr, er = bladeOn(char, r, mode, false)
		local ml, pl, el = bladeOn(char, l, mode, true)
		d.models, d.parts, d.edges, d.mode, d.ltm = { mr, ml }, {}, { er, el }, mode, nil
		for _, p in pr do
			table.insert(d.parts, p)
		end
		for _, p in pl do
			table.insert(d.parts, p)
		end
		return d
	end
	-- (round 90 review) on the move, M1.WalkOff seconds past his last swing
	-- (the chain's swings come every Config.M1.Cooldown: never mid-chain)
	function HK.walkedOff(char)
		local s = VFX.M1Kit and VFX.M1Kit.swings[char]
		local root = char:FindFirstChild("HumanoidRootPart")
		if not (s and root) or os.clock() - s.start < (M1C.WalkOff or 0.6) then
			return false
		end
		local v = root.AssemblyLinearVelocity
		return Vector3.new(v.X, 0, v.Z).Magnitude > 6
	end
	-- (round 90) the drawn blades into the other grip, on the spot
	function HK.regrip(char, d, mode)
		for _, m in d.models or {} do
			m:Destroy()
		end
		return build(char, d, mode)
	end
	function HK.blades(char, on, now, mode)
		local d = HK.drawn[char]
		mode = mode or "Sword"
		if on then
			if d then
				d.til = os.clock() + HK.SHEATHE
				if d.mode ~= mode then
					HK.regrip(char, d, mode)
				end
				return d
			end
			d = { til = os.clock() + HK.SHEATHE }
			if not build(char, d, mode) then
				return nil
			end
			HK.drawn[char] = d
			HK.refresh(char, false)
			-- drawn: the edges flash as they harden
			for _, e in d.edges do
				e.Transparency = 0.2
				tween(e, 0.1, { Transparency = 1 })
			end
			local root = char:FindFirstChild("HumanoidRootPart")
			VFX.PlaySound("FeatherDraw", root and root.Position, 0.8)
			task.spawn(function()
				while HK.drawn[char] == d and char.Parent and os.clock() < d.til do
					task.wait(0.2)
					-- (round 90 review) walked off out of the chain: the M1 grip
					-- points the blades down the line of the arm - swung in his walk
					-- they'd dip into the street - so home they go as he walks away
					-- (M1.WalkOff seconds after his last swing, on the move)
					if d.mode == "M1" and HK.drawn[char] == d and HK.walkedOff(char) then
						break
					end
				end
				if HK.drawn[char] == d then
					HK.blades(char, false)
				end
			end)
			return d
		elseif d then
			HK.drawn[char] = nil
			-- back into the wings: each blade swoops home with a pale streak and a click
			for i, m in d.models do
				local blade = m:FindFirstChild("HawksVane") or m:FindFirstChildWhichIsA("BasePart")
				if not now and blade and char.Parent then
					local from = blade.CFrame
					local side = i == 1 and 1 or -1
					-- (round 90) home the homecoming's way: a short spiral into its gap
					if HK.homeArc then
						HK.homeArc(char, from, side, "P2", 0.26)
					else
						local fl = HK.feather(from, 2.4, "pale")
						local to = HK.slotCF(char, side, "P2")
						tween(fl, 0.25, { CFrame = to, Transparency = 0.6 }, Enum.EasingStyle.Quad, Enum.EasingDirection.In)
						cleanup(fl, 0.27)
						task.delay(0.25, function()
							VFX.PlaySound("FeatherReturn", to.Position, 0.8)
						end)
					end
				end
				m:Destroy()
			end
			if char.Parent then
				-- (round 86, C2) the primaries click back into their gaps as the
				-- blades land (HK.homeTo), not grow back
				HK.bladeBack = HK.bladeBack or setmetatable({}, { __mode = "k" })
				HK.bladeBack[char] = os.clock() + 0.6
				task.delay(now and 0 or 0.22, function()
					HK.refresh(char, false)
				end)
			end
		end
		return nil
	end
	if VFX.WeaponKit and VFX.WeaponKit.Feather then
		-- (round 90) drawn in the M1 grip, the wings drawn in tight on his back
		-- for the chain (Guard: clear of the blades and of his own camera)
		VFX.WeaponKit.Feather.Draw = function(char)
			HK.blades(char, true, nil, "M1")
			HK.setWing(char, "Guard", M1C.Guard or 0.75, 20)
		end
		-- (round 90) each blade's own ribbon, base to point: a white-hot edge
		-- where it is now cooling to crimson behind - the sweep of the cut
		VFX.WeaponKit.Feather.Ribbon = function(char, finisher)
			local d = HK.drawn[char]
			if not d then
				return nil
			end
			local trails = {}
			for _, m in d.models do
				local vane = m:FindFirstChild("HawksVane")
				local a0, a1 = vane and vane:FindFirstChild("BladeBase"), vane and vane:FindFirstChild("BladePoint")
				if a0 and a1 then
					local t = Instance.new("Trail")
					t.Name = "HawksRibbon"
					t.Attachment0, t.Attachment1 = a0, a1
					t.Color = ColorSequence.new({
						ColorSequenceKeypoint.new(0, Color3.fromRGB(255, 236, 228)),
						ColorSequenceKeypoint.new(0.3, Color3.fromRGB(255, 84, 70)),
						ColorSequenceKeypoint.new(1, Color3.fromRGB(150, 14, 24)),
					})
					t.Transparency = NumberSequence.new({ NumberSequenceKeypoint.new(0, 0.05), NumberSequenceKeypoint.new(0.55, 0.4), NumberSequenceKeypoint.new(1, 1) })
					t.LightEmission = 0.75
					t.Lifetime = finisher and 0.2 or 0.14
					t.MinLength = 0
					t.FaceCamera = false
					t.Parent = vane
					table.insert(trails, t)
				end
			end
			return function(after)
				task.delay(after or 0, function()
					for _, t in trails do
						pcall(function()
							t.Enabled = false
						end)
					end
					task.wait(0.25)
					for _, t in trails do
						pcall(t.Destroy, t)
					end
				end)
			end
		end
	end
	-- (round 90) the cut left where a swing went through them: a thin crimson
	-- plane with a white-hot core, square to his look and tilted to the cut
	-- (angle: degrees from level, + rising to his left), drawn on in a blink
	-- and thinning away
	function HK.slashMark(at, look, angle, len, life, heavy)
		local cf = CFrame.lookAt(at, at + look) * CFrame.Angles(0, 0, math.rad(angle))
		local out = {}
		for i, spec in { { 0.2, HK.CUT, 1 }, { 0.07, Color3.new(1, 1, 1), 0.82 } } do
			local p = newPart(Vector3.new(len * 0.2, spec[1] * (heavy and 1.6 or 1), 0.05 + i * 0.01), cf, spec[2], Enum.Material.Neon)
			p.Name = "HawksSlash"
			tween(p, 0.035, { Size = Vector3.new(len * spec[3], p.Size.Y, p.Size.Z) })
			tween(p, life, { Size = Vector3.new(len * spec[3], 0.02, p.Size.Z), Transparency = 1 }, nil, nil, 0.04)
			cleanup(p, life + 0.08)
			table.insert(out, p)
		end
		return out
	end
	-- every hit: red flecks off the blade and the cut left in the air where
	-- it went through them; the 4th: the X-CUT - two heavy cuts crossing
	-- through them, a burst of feathers off the wings as they're thrown up
	-- (M1.Pop), a crimson star; in the air, every cut a downstroke of the
	-- wings (he holds his height in the air chain)
	-- (round 90) the angle of each cut (degrees, + rising to his left): the
	-- flat cut, the left diagonal (down to his right), the rising cut
	HK.CUT_ANGLE = { 4, -38, 42 }
	function VFX.HawksPunch(char, count, finisher, fist, look, variant)
		HK.flecks(fist, finisher and 8 or 3, finisher and 2 or 1.2)
		local root = char:FindFirstChild("HumanoidRootPart")
		if not root then
			return
		end
		-- (round 90 review) never a cut mark along a zero / NaN look (a NaN CFrame)
		if typeof(look) ~= "Vector3" or look ~= look or look.Magnitude < 0.5 then
			local lv = Vector3.new(root.CFrame.LookVector.X, 0, root.CFrame.LookVector.Z)
			look = lv.Magnitude > 0.05 and lv.Unit or Vector3.new(0, 0, -1)
		end
		local S = M1C.Slash or {}
		local at = root.Position + look * 3.3 + UP * 0.45
		if finisher then
			-- the X-cut; the launcher's two cuts rising through them in a V; the
			-- plunge's two driven down through them, lower
			local angles = (variant == "Up" and { 74, 106 }) or { 42, -42 }
			if variant == "Down" then
				at = root.Position + look * 2.6 - UP * 1.4
				angles = { 62, -62 }
			end
			for _, a in angles do
				HK.slashMark(at, look, a, S.Heavy or 8, (S.Life or 0.16) * 1.6, true)
			end
			HK.setWing(char, M1C.Pop or "Max", M1C.PopTime or 0.32, 30)
			task.delay(M1C.PopTime or 0.32, function()
				if char.Parent then
					HK.setWing(char, "Guard", 0.4, 14)
				end
			end)
			HK.shed(root.Position + UP * 1.6 - look * 0.6, IceKit.lowEnd() and 3 or 7, 3)
			if VFX.EngineKit and VFX.EngineKit.starSpark then
				VFX.EngineKit.starSpark(at, { size = 4.5, life = 0.12, color = Color3.new(1, 1, 1), color2 = HK.CUT, spikes = 4 })
			end
		else
			HK.slashMark(at, look, HK.CUT_ANGLE[math.clamp(count, 1, 3)] or 0, S.Length or 5.5, S.Life or 0.16, false)
		end
		-- (in the air: a downstroke on the cut)
		if M1C.AirBeat ~= false then
			local g = groundPoint(root.Position)
			if root.Position.Y - g.Y > 4.2 then
				HK.setWing(char, "FlapDown", 0.12, 40)
				task.delay(0.12, function()
					if char.Parent then
						HK.setWing(char, "FlapUp", 0.16, 22)
					end
				end)
				if nearCamera(root.Position, 90) then
					VFX.PlaySound("WingFlap", root.Position, 0.6)
				end
			end
		end
	end

