		{ pose = "HawksPoint", t = 0.05, hold = 0.32 },
		recover = 0.3,
	}
	MOTIONS.HawksSwiftCut = {
		{ pose = "HawksCoil", t = 0.13, hold = 0.03 },
		{ pose = { RightArm = { -40, 30, 20 }, LeftArm = { 30, 0, 30 }, Waist = { -38, 20, 0 }, RightLeg = -40, LeftLeg = 30, Hips = { 0, 0, 0, 0, -0.3, 0 } }, t = 0.06, hold = 0.12 },
		{ pose = "HawksCut", t = 0.04, hold = 0.22 },
		recover = 0.3,
	}
	MOTIONS.HawksCycloneBurst = {
		{ pose = { RightArm = { 12, 0, 104 }, LeftArm = { 12, 0, 104 }, Waist = { 8, 0, 0 } }, t = 0.05, hold = 0.28 },
		recover = 0.35,
	}
	MOTIONS.HawksCarry = {
		{ pose = { RightArm = { 24, 0, 8 }, LeftArm = { -8, 0, 8 } }, t = 0.05 },
		{ pose = "HawksFlick", t = 0.04, hold = 0.4 },
		recover = 0.3,
	}
	MOTIONS.HawksCarryDrop = {
		{ pose = { RightArm = { 34, 0, 12 }, LeftArm = { -8, 0, 8 }, Waist = { -4, 0, 0 } }, t = 0.07, hold = 0.15 },
		recover = 0.3,
	}
	POSES.HawksCarried = { RightArm = { 10, 0, 118 }, LeftArm = { 12, 0, 120 }, RightLeg = -8, LeftLeg = 10, Neck = { 20, 0, 6 } } -- (round 86, C2 review: a Y, the hands about head-high, as the clip)

	---------------------------------------------------------------------
	-- R: FIERCE WINGS - the takeoff, the flight (everyone), the landing
	---------------------------------------------------------------------
	-- the downstroke off the street: wings up, one huge beat, a disc of
	-- dust, loose feathers puffed out
	function HK.takeoff(char, root)
		HK.setWing(char, "FlapUp", 0.12, 30)
		task.delay(0.12, function()
			if char.Parent then
				HK.setWing(char, "FlapDown", 0.2, 40)
			end
		end)
		VFX.Motion(char, "HawksTakeoff")
		local g = groundPoint(root.Position)
		local near = (root.Position - g).Magnitude < 6
		task.delay(0.12, function()
			if not root.Parent then
				return
			end
			if near then
				shockDisc(g + UP * 0.3, UP, 4, 28, 0.35, Color3.fromRGB(240, 230, 220))
				dustPuffs(g, 1.1, 8, HK.DUST, 0.9, false)
				billboardRing(g + UP * 0.5, 2, 16, Color3.new(1, 1, 1), 4, 0.3)
			end
			HK.shed(root.Position + UP * 1.5, IceKit.lowEnd() and 6 or 14, 6)
			streaks(root.Position - UP * 2, -UP, 8, 2.2, 7, 14, WIND, 0.3)
			VFX.PlaySound("WingBeat", root.Position, 1)
			VFX.ShakeAt(root.Position, 0.8, 40, 0.15)
		end)
		VFX.PlaySound("HawksTakeoff", root.Position, 1)
	end
	-- (round 90) R already in the air: no crouch, no launch - the wings snap
	-- open (flared forward, air brakes) and one downstroke catches him: a
	-- ring of air thrown down off it, loose feathers, the hanging pose at once
	function HK.airCatch(char, root)
		HK.setWing(char, "Flare", 0.1, 40)
		task.delay(0.1, function()
			if char.Parent then
				HK.setWing(char, "FlapDown", 0.16, 36)
			end
		end)
		VFX.Pose(char, "HawksHover", 0.6)
		VFX.PlaySound("HawksAirCatch", root.Position, 1)
		task.delay(0.1, function()
			if not root.Parent then
				return
			end
			local under = root.Position - UP * 2.4
			shockDisc(under, UP, 2, 18, 0.3, WIND)
			billboardRing(under, 2, 13, Color3.new(1, 1, 1), 4, 0.25)
			streaks(under, -UP, 8, 2, 6, 12, WIND, 0.25)
			HK.shed(root.Position + UP, IceKit.lowEnd() and 4 or 9, 4)
			VFX.ShakeAt(root.Position, 0.5, 30, 0.12)
		end)
	end
	function Effects.FierceWings(char, data, isLocal, ability)
		local root, hum = charParts(char)
		if not root then
			return
		end
		local air = type(data) == "table" and data.Air == true
		if air then
			HK.airCatch(char, root)
		else
			HK.takeoff(char, root)
		end
		if isLocal then
			task.delay(air and 0.05 or 0.12, function()
				VFX.Hooks.SpeedLines(air and 0.25 or 0.35)
			end)
			if VFX.Hooks.HawksFly then
				VFX.Hooks.HawksFly(ability, air)
			elseif hum and not air then
				launch(root, hum, UP * ((ability and ability.Lift) or 70) * 0.5) -- (no machine to fly him: a hop)
			end
		end
	end
	-- (round 90) under his wings in a fall, on every screen: the hanging pose
	-- (PoseHawksHover, re-held while it lasts and let go as it ends), a
	-- flutter as the canopy opens, the wind rising with how fast he drops
	HK.falls = {}
	function HK.fallWatch(char)
		if HK.falls[char] then
			return
		end
		local token = {}
		HK.falls[char] = token
		task.spawn(function()
			local root = char:FindFirstChild("HumanoidRootPart")
			if not root then
				HK.falls[char] = nil
				return
			end
			local wind = HK.loop(char, "HawksFallWind", 0.8)
			local me = Players.LocalPlayer and Players.LocalPlayer.Character
			if char == me or nearCamera(root.Position, 120) then
				VFX.PlaySound("HawksBrake", root.Position, 0.8)
			end
			local posedAt, pose, lastStoop = 0, nil, nil
			while HK.falls[char] == token and root.Parent and HK.isFalling(char) and not HK.isFlying(char) do
				local now = os.clock()
				local stoop = HK.isFalling(char) == "Stoop"
				if (now - posedAt > 2.5 or stoop ~= lastStoop) and not char:GetAttribute("Ragdolled") then
					if lastStoop == true and not stoop and (char == me or nearCamera(root.Position, 120)) then
						VFX.PlaySound("HawksBrake", root.Position, 0.9) -- (the canopy flared open again)
					end
					posedAt, lastStoop = now, stoop
					VFX.Pose(char, stoop and "HawksStoop" or "HawksHover", 3)
					pose = VFX.PoseToken(char)
				end
				if wind then
					HK.loopVolume(char, "HawksFallWind", math.clamp(0.25 + math.abs(root.AssemblyLinearVelocity.Y) / 50, 0.25, 1))
				end
				task.wait(0.1)
			end
			if HK.falls[char] == token then
				HK.falls[char] = nil
			end
			HK.stopLoop(char, "HawksFallWind", 0.35)
			-- (let go of the pose, unless something else has posed him since)
			if pose and VFX.PoseToken(char) == pose and char.Parent then
				VFX.ReleasePose(char, 0.15)
			end
		end)
	end
	-- his flight, on every screen: the pose from how he's moving, a beat on
	-- every downstroke, the wind round him rising with his speed
	function HK.flight(char)
		if HK.flights[char] then
			return
		end
		local token = {}
		HK.flights[char] = token
		task.spawn(function()
			local root = char:FindFirstChild("HumanoidRootPart")
			local lastPose, posedAt, lastBeat = nil, 0, 0
			local me = Players.LocalPlayer and Players.LocalPlayer.Character
			local wind = root and HK.loop(char, "HawksWind", char == me and 0.8 or 1)
			local started = os.clock()
			while HK.flights[char] == token and root and root.Parent and HK.isFlying(char) do
				local rig = HK.rigs[char]
				local now = os.clock()
				local name = rig and rig.flightPose or "HawksHover"
				if HK.carryPose then
					name = HK.carryPose(char, name) -- (round 92, hawksair: someone on his feathers - the hover points down at them)
				end
				-- (the takeoff's crouch and launch play out first)
				if now - started > 0.45 and (name ~= lastPose or now - posedAt > 2.5) then
					lastPose, posedAt = name, now
					VFX.Pose(char, name, 3)
				end
				-- a beat you hear on each downstroke
				if rig and rig.lastBeat > lastBeat and name ~= "HawksGlide" and name ~= "HawksDive" then
					lastBeat = rig.lastBeat
					if char == me or nearCamera(root.Position, 120) then
						VFX.PlaySound("WingFlap", root.Position, name == "HawksClimb" and 1 or 0.7)
					end
				end
				if wind then
					local v = root.AssemblyLinearVelocity.Magnitude
					HK.loopVolume(char, "HawksWind", math.clamp(0.15 + v / 110, 0.15, 1.2))
				end
				task.wait(0.1)
			end
			if HK.flights[char] == token then
				HK.flights[char] = nil
			end
			HK.stopLoop(char, "HawksWind", 0.6)
		end)
	end
	function Effects.HawksFlyFX(char, data, isLocal)
		local root = charParts(char)
		if not root then
			return
		end
		local kind = data and data.Kind
		if kind == "Lift" then
			-- (the takeoff's dust is Effects.FierceWings', on every screen - round
			-- 86 review: this drew a second disc on everyone else's)
			task.delay(0.05, function()
				if char.Parent then
					HK.flight(char)
				end
			end)
		elseif kind == "Boost" then
			local d = (typeof(data.Dir) == "Vector3" and data.Dir.Magnitude > 0.01) and data.Dir.Unit or root.CFrame.LookVector
			HK.boosts[char] = os.clock() + 0.5
			HK.setWing(char, "Tuck", 0.5, 22)
			VFX.Pose(char, "HawksDive", 0.5)
			local back = root.Position - d * 2.5
			shockDisc(back, -d, 1.5, 14, 0.3, WIND, 3)
			streaks(back, -d, 8, 1.5, 9, 20, WIND, 0.25)
			afterimage(char, HK.LIT, 0.3)
			HK.shed(root.Position, 5, 2)
			VFX.PlaySound("HawksBoost", root.Position, 1)
			if isLocal then
				VFX.Hooks.SpeedLines(0.55) -- (his own screen: the rush of it)
			end
		elseif kind == "End" then
			HK.flights[char] = nil
			HK.flying[char] = nil
			HK.stopLoop(char, "HawksWind", 0.5)
			if data.Land then
				-- the wings flared as air brakes, then the crouched landing, then folded
				HK.setWing(char, "Flare", 0.22, 26)
				VFX.Motion(char, "HawksLand")
				local g = groundPoint(root.Position)
				dustPuffs(g, 0.9, 6, HK.DUST, 0.8, false)
				shockDisc(g + UP * 0.3, UP, 3, 16, 0.3, Color3.fromRGB(240, 230, 220))
				HK.shed(root.Position + UP, 3, 2)
				VFX.PlaySound("HawksLand", root.Position, 1)
				task.delay(0.3, function()
					if char.Parent then
						VFX.PlaySound("WingFold", root.Position, 0.8)
					end
				end)
			elseif data.Reason == "Hit" then
				-- (round 86 review) knocked out of the air: no pose over the hit
				-- reaction or the ragdoll - the wings just snap in and settle
				HK.setWing(char, "Tuck", 0.25, 18)
			else
				HK.setWing(char, "Spread", 0.4, 10) -- (gliding down, then they fold)
				VFX.Pose(char, "HawksHover", 0.4)
			end
		end
	end

	---------------------------------------------------------------------
	-- the feathers' own states: spent, plucked, burned
	---------------------------------------------------------------------
	local LINES_OUT = { "Out of feathers... great.", "Running thin...", "Gonna need a minute." }
	function Effects.FeathersOut(char, data)
		local root = charParts(char)
		if not root then
			return
		end
		-- (a bubble now and then, not on every press - and the sound at most
		-- every 0.4 s: mashing a key he can't pay for isn't a drum roll)
		if os.clock() - (HK.saidAt or 0) > 4 then
			HK.saidAt = os.clock()
			VFX.SpeechBubble(char, data and data.Plucked and LINES_OUT[1] or LINES_OUT[rng:NextInteger(2, 3)], 1.6)
		end
		HK.outAt = HK.outAt or setmetatable({}, { __mode = "k" })
		if os.clock() - (HK.outAt[char] or 0) >= 0.4 then
			HK.outAt[char] = os.clock()
			VFX.PlaySound("FeathersPlucked", root.Position, 0.6)
		end
	end
	function Effects.FeathersPlucked(char)
		local root = charParts(char)
		if not root then
			return
		end
		-- the last of them gone: a puff of down off the bare nubs
		for _, side in { 1, -1 } do
			local p = (root.CFrame * CFrame.new(side * 0.5, 1.4, 0.8)).Position
			for _ = 1, 6 do
				local m = newPart(Vector3.one * rand(0.1, 0.2), CFrame.new(p), Color3.fromRGB(255, 226, 220), Enum.Material.SmoothPlastic, Enum.PartType.Ball)
				tween(m, rand(0.8, 1.3), { Position = p + Vector3.new(rand(-1.5, 1.5), rand(-1, 1.5), rand(-0.5, 2)), Transparency = 1 }, Enum.EasingStyle.Sine)
				cleanup(m, 1.35)
			end
		end
		VFX.PlaySound("FeathersPlucked", root.Position, 1)
		if rng:NextNumber() < 0.6 then
			VFX.SpeechBubble(char, LINES_OUT[1], 1.6)
		end
	end
	function Effects.FeathersBurned(char, data)
		local root = charParts(char)
		if not root then
			return
		end
		local blue = data and data.Pal == "blue"
		local ember = blue and Color3.fromRGB(90, 160, 255) or Color3.fromRGB(255, 140, 40)
		-- burned feathers: black, smouldering, breaking into ash
		local n = math.clamp(math.floor((data and data.Count or 6) / 2), 2, 6)
		for _, side in { 1, -1 } do
			for _ = 1, n do
				local cf = HK.slotCF(char, side, "S" .. rng:NextInteger(1, 8)) * CFrame.new(rand(-0.3, 0.3), rand(-0.6, 0.2), 0)
				local f = HK.feather(cf, rand(0.9, 1.3), nil)
				f.Color = Color3.fromRGB(34, 24, 24)
				f.Anchored = true
				for _, c in f:GetChildren() do
					if c:IsA("BasePart") then
						c.Color = ember
						c.Material = Enum.Material.Neon
					end
				end
				local to = cf.Position + Vector3.new(rand(-1.5, 1.5), rand(-3, -1.5), rand(0.5, 2))
				tween(f, 0.7, { CFrame = CFrame.new(to) * CFrame.Angles(rand(0, 6.28), rand(0, 6.28), 0), Transparency = 1 }, Enum.EasingStyle.Sine)
				cleanup(f, 0.75)
				sparks(cf.Position, 0.25, ember, Color3.fromRGB(80, 70, 70), 3)
			end
		end
		VFX.PlaySound("FeathersBurned", root.Position, 1)
		HK.jolt(char, 6)
		if rng:NextNumber() < 0.2 then
			VFX.SpeechBubble(char, "Not the wings!", 1.4)
		end
		local me = Players.LocalPlayer and Players.LocalPlayer.Character
		if me == char and VFX.Hooks.FeathersBurned then
			VFX.Hooks.FeathersBurned(char)
		end
	end

	---------------------------------------------------------------------
	-- 1: FEATHER BARRAGE - his cue (a two-finger point, the wings snapped
	-- open), and the feathers themselves from the server (FeatherVolley:
	-- where each goes; FeatherVolleyHits: as they land or turn back)
	-- (round 86, C2) MoveHawksBarrage: the hand sweeps across his chest and
	-- out into the point - its Hit is the server's Delay, the first feather
	-- off. The wings snap open and the feathers about to go bristle out of
	-- them; each one LEAVES its slot as it's thrown (HK.leave: the wing
	-- thins feather by feather, outer to inner, wings in turn), snaps round
	-- to face them and darts off (sharp kinks, not curves), a crimson
	-- streak behind it. A hit sticks in, tilted, then breaks into flecks -
	-- the first marks them on his screen for 4 s (a red outline through
	-- walls: the feathers' echolocation). A miss turns back and flies home
	-- into the wing with a click (HK.flyHome / HK.homeTo): the refund.
	---------------------------------------------------------------------
	-- a feather on the wing (still there, or spent and about to be thrown)
	-- slid out and quivering: about to go
	function HK.bristle(char, side, slot, time)
		local rig = HK.rigs[char]
		local fe = rig and rig.sides[side] and rig.sides[side].feathers[slot]
		if fe then
			fe.extTo = 1.2
			task.delay(time or 0.4, function()
				if fe.extTo == 1.2 then
					fe.extTo = 0
				end
			end)
		end
	end
	function Effects.FeatherBarrage(char, data, isLocal, ability)
		local root = charParts(char)
		if not root then
			return
		end
		local spec = ability or Config.FindAbilityById("FeatherBarrage") or {}
		data = data or {}
		if isLocal and typeof(data.Dir) == "Vector3" then
			face(root, data.Dir)
		end
		-- (round 90) in the air (fired down at them): the legs left to hang
		-- under him, the wings beating him up as they go
		local air = data.Air == true and (root.Position - groundPoint(root.Position)).Magnitude > 4.2
		if not (air and VFX.Clip(char, "MoveHawksBarrage", { legs = false, recover = 0.375 })) then
			VFX.Motion(char, "HawksBarrage")
		end
		local delay = spec.Delay or 0.12
		HK.setWing(char, "Spread", delay + (spec.Count or 12) * (spec.Gap or 0.025) + 0.22, 34)
		if air then
			task.delay(delay, function()
				if char.Parent then
					HK.setWing(char, "FlapDown", 0.14, 40)
					VFX.PlaySound("WingFlap", root.Position, 0.8)
				end
			end)
			task.delay(delay + 0.14, function()
				if char.Parent then
					HK.setWing(char, "Spread", (spec.Count or 12) * (spec.Gap or 0.025) + 0.1, 30)
				end
			end)
		end
		VFX.PlaySound("WingSnap", root.Position, 1)
		VFX.PlaySound("FeatherBristle", root.Position, 1)
		for _, s in HK.launchSlots(char, spec.Count or 12) do
			HK.bristle(char, s.side, s.slot, delay + 0.35)
		end
		if isLocal then
			task.delay(delay, function()
				local EK = VFX.EngineKit
				if EK and EK.fovPunch and char.Parent then
					EK.fovPunch(2, 0.05, 0.2, 0.05) -- (his own screen: a breath of FOV as they go)
				end
			end)
		end
	end
	-- the feathers fly on every screen by the server's homing law: re-aimed
	-- in sharp steps every 0.08 s (Turn degrees a second), else straight
	function HK.flyVolley(char, data)
		local root = charParts(char)
		if not root then
			return
		end
		local count = math.clamp(tonumber(data.Count) or 12, 1, 40)
		local d = (typeof(data.Dir) == "Vector3" and data.Dir.Magnitude > 0.01) and data.Dir.Unit or root.CFrame.LookVector
		local target = typeof(data.Target) == "Instance" and data.Target or nil
		local speed, gap, life = tonumber(data.Speed) or 140, tonumber(data.Gap) or 0.025, tonumber(data.Life) or 1.2
		local turn = math.rad(tonumber(data.Turn) or 220)
		local slots = HK.launchSlots(char, count)
		local list = {}
		HK.volleys[char] = HK.volleys[char] or {}
		HK.volleys[char][data.Volley or 0] = list
		VFX.PlaySound("FeatherVolley", root.Position, 1)
		-- (round 86, C2 review) twelve feathers, not two beams: each wing's
		-- feathers bow out to their own side and curve in (a shown offset,
		-- back on the server's line by the time they arrive), and each homes
		-- on its own spot of the body - shoulders to knees - not one point
		local across = d:Cross(UP)
		across = across.Magnitude > 0.05 and across.Unit or root.CFrame.RightVector
		for i = 1, count do
			local s = slots[i]
			local fan = math.rad(((i % 2 == 0) and -1 or 1) * (tonumber(data.Spread) or 8) * (1.2 - math.ceil(i / 2) / math.ceil(count / 2)))
			list[i] = { i = i, s = s, side = s.side, slot = s.slot, v = (CFrame.fromAxisAngle(UP, fan) * d).Unit, launch = (i - 1) * gap, state = "wait", aimed = 0, owed = 0,
				bow = (across * s.side * 0.8 + UP * ((i % 3 == 0) and rand(-0.9, -0.4) or rand(0.1, 1))).Unit * rand(2.2, 4), off = across * rand(-0.8, 0.8) + UP * rand(-1, 1.2), flown = 0 }
		end
		-- (a lent feather is out till it's back: the volley, a stick, the way home)
		local hold = count * gap + life + 2.6
		-- where a feather shows (its bow, over the first `span` studs of its
		-- flight: the way to the target, or 40 studs) and which way it points
		local function shown(f)
			local k = math.clamp(f.flown / (f.span or 40), 0, 1)
			local q = f.p + f.bow * math.sin(math.pi * k)
			local dir = k < 1 and (f.v + f.bow * (math.pi / (f.span or 40)) * math.cos(math.pi * k)) or f.v
			return q, dir.Magnitude > 0.01 and dir.Unit or f.v
		end
		local t0 = os.clock()
		local me = Players.LocalPlayer and Players.LocalPlayer.Character
		local heard = char == me -- (a fly-by whoosh on the screens it passes - not his own)
		local WHIP = 0.045
		local function drop(f)
			if f.part then
				f.part:Destroy()
				f.part = nil
			end
		end
		HK.run(function(dt, now)
			if not char.Parent then
				for _, f in list do
					drop(f)
				end
				return false
			end
			local alive = 0
			local tr = target and target.Parent and target:FindFirstChild("HumanoidRootPart")
			local cam = workspace.CurrentCamera
			local camPos = cam and cam.CFrame.Position
			for _, f in list do
				local age = now - t0 - f.launch
				if f.state == "wait" then
					alive += 1
					if age >= 0 then
						-- off the wing: the feather leaves its slot as its copy is
						-- thrown from right there (a feather still showing on the
						-- wing - more thrown than the count hides - flicks)
						local from = HK.slotCF(char, f.side, f.slot)
						HK.launch(char, f.s, hold)
						f.from = from
						f.p = from.Position
						f.part = HK.dart(from, 1.35, "red", 0.08) -- (a short streak: twelve, never a band)
						local streak = f.part:FindFirstChildOfClass("Trail")
						if streak then
							streak.WidthScale = NumberSequence.new(0.75, 0.15)
						end
						f.state = "whip"
						f.whip = 0
						local to = tr and (tr.Position + f.off - f.p).Magnitude
						f.span = math.clamp(to or 40, 8, 40)
						-- (hardened: its edge flashes as it goes)
						local tip = f.part:FindFirstChildWhichIsA("WedgePart")
						if tip then
							tip.Material = Enum.Material.Neon
							tip.Color = HK.EDGE
							task.delay(0.08, function()
								if tip.Parent then
									tip.Material = Enum.Material.SmoothPlastic
									tip.Color = HK.TIP
								end
							end)
						end
						if f.i % 2 == 1 then
							VFX.PlaySound("FeatherThwip", f.p, 0.6)
						end
					end
				elseif f.state == "whip" then
					-- snapped round to face where it's going
					alive += 1
					f.whip += dt
					local a = math.clamp(f.whip / WHIP, 0, 1)
					local _, dir = shown(f)
					local want = HK.aim(f.p, dir)
					f.part.CFrame = f.from:Lerp(want, a * a * (3 - 2 * a))
					if a >= 1 then
						f.state = "fly"
						f.owed = WHIP * speed -- (it catches up with where the server has it)
					end
				elseif f.state == "fly" then
					alive += 1
					if tr and now - f.aimed >= 0.08 then
						f.aimed = now
						local want = tr.Position + f.off - f.p
						if want.Magnitude > 0.5 then
							local ang = math.acos(math.clamp(f.v:Dot(want.Unit), -1, 1))
							local most = turn * 0.08 * 1.5
							if ang <= most then
								f.v = want.Unit
							else
								local axis = f.v:Cross(want.Unit)
								if axis.Magnitude > 1e-4 then
									f.v = (CFrame.fromAxisAngle(axis.Unit, most) * f.v).Unit
								end
							end
						end
					end
					local catch = math.min(f.owed, speed * dt * 0.8)
					f.owed -= catch
					f.p += f.v * (speed * dt + catch)
					f.flown += speed * dt + catch
					f.spin = (f.spin or 0) + dt * 12.5
					local q, dir = shown(f)
					f.part.CFrame = HK.aim(q, dir) * CFrame.Angles(0, f.spin, 0)
					if not heard and camPos and (q - camPos).Magnitude < 14 then
						heard = true
						VFX.PlaySound("FeatherFlyby", q, 1)
					end
					if age > life + 0.6 then
						f.state = "home" -- (no word from the server: it comes home anyway)
					end
				elseif f.state == "stuck" then
					alive += 1
					if f.on and f.on.Parent and f.part then
						f.part.CFrame = f.on.CFrame * f.rel
					end
					if now > f.til then
						f.state = "done"
						if f.part then
							if HK.owed(char, f.s) and char.Parent then
								-- (round 86, C2 review) lent: it pulls out of them and flies
								-- back into its own slot - the wing is whole again
								local at = f.part.CFrame.Position
								sparks(at, 0.15, HK.EDGE, HK.RED, 1)
								drop(f)
								HK.flyHome(char, HK.aim(at, -f.v), f.side, f.slot, 150, -f.v * 10 + UP * 12, nil, f.s.Copy)
							else
								HK.flecks(f.part.CFrame.Position, 3, 1)
								drop(f)
							end
						end
					end
				end
				if f.state == "home" then
					-- it turns round (carried on a moment, then darting back) and
					-- flies home into the wing
					local at = f.part and f.part.CFrame or CFrame.new(f.p or root.Position)
					drop(f)
					HK.flyHome(char, HK.aim(at.Position, -f.v), f.side, f.slot, 160, f.v * 26, nil, f.s.Copy)
					f.state = "done"
				end
			end
			if (alive == 0 and now - t0 > count * gap + 0.1) or now - t0 > count * gap + life + 4 then
				for _, f in list do
					drop(f)
				end
				if HK.volleys[char] and HK.volleys[char][data.Volley or 0] == list then
					HK.volleys[char][data.Volley or 0] = nil
				end
				return false
			end
			return true
		end)
		return list
	end
	function Effects.FeatherVolley(char, data)
		HK.flyVolley(char, data or {})
	end
	-- (the first feather in them marks them on his screen: a red outline
	-- through walls for 4 s - he feels them through it)
	function HK.mark(char, target)
		local me = Players.LocalPlayer and Players.LocalPlayer.Character
		if char ~= me or typeof(target) ~= "Instance" or not target.Parent then
			return
		end
		HK.marks = HK.marks or setmetatable({}, { __mode = "k" })
		local old = HK.marks[target]
		if old and old.Parent then
			old:Destroy()
		end
		local h = Instance.new("Highlight")
		h.Name = "HawksMark"
		h.FillColor = Color3.fromRGB(255, 70, 60)
		h.FillTransparency = 0.85
		h.OutlineColor = Color3.fromRGB(255, 70, 60)
		h.OutlineTransparency = 0
		h.DepthMode = Enum.HighlightDepthMode.AlwaysOnTop
		h.Adornee = target
		h.Parent = folder
		HK.marks[target] = h
		tween(h, 0.6, { OutlineTransparency = 1, FillTransparency = 1 }, nil, nil, 3.4)
		cleanup(h, 4.05)
		local tr = target:FindFirstChild("HumanoidRootPart")
		VFX.PlaySound("FeatherMark", tr and tr.Position, 0.6)
	end
	function Effects.FeatherVolleyHits(char, data)
		local list = HK.volleys[char] and HK.volleys[char][data and data.Volley or 0]
		if not list then
			return
		end
		for _, h in (data.Hits or {}) do
			local f = list[h.Index]
			local tr = typeof(h.Target) == "Instance" and h.Target:FindFirstChild("HumanoidRootPart")
			if f and f.part and tr then
				-- it sticks where it hit (the spot it homed on), point in, tilted;
				-- then breaks into flecks - or, lent, pulls out and flies home
				-- (round 86, C2 review: point first, as it flew - HK.aim)
				f.state = "stuck"
				f.on = tr
				local at = (typeof(h.Pos) == "Vector3" and h.Pos or tr.Position) + (f.off or Vector3.zero) * 0.8 + Vector3.new(rand(-0.2, 0.2), rand(-0.2, 0.2), rand(-0.2, 0.2))
				f.part.CFrame = HK.aim(at - f.v * 0.95, f.v) * CFrame.Angles(math.rad(rand(-25, 25)), 0, math.rad(rand(-20, 20))) -- (the point just in, the vane standing out)
				f.rel = tr.CFrame:ToObjectSpace(f.part.CFrame)
				f.til = os.clock() + 0.6
				sparks(at, 0.25, HK.EDGE, HK.RED, 3)
				if not HK.markedVolley or HK.markedVolley ~= list then
					HK.markedVolley = list
					HK.mark(char, h.Target)
				end
			end
		end
		for _, m in (data.Misses or {}) do
			local f = list[m.Index]
			if f and (f.state == "fly" or f.state == "whip") then
				if typeof(m.Pos) == "Vector3" then
					f.p = m.Pos
					if f.part then
						f.part.CFrame = CFrame.new(m.Pos) * f.part.CFrame.Rotation
					end
				end
				f.state = "home"
			end
		end
	end

	-- (ult 1, SCARLET RAIN: VFX.HU - round 86, hawks_ult)

	---------------------------------------------------------------------
	-- 2: SWIFT CUT - his own machine carries him (the coil, then the line);
	-- everyone sees the blade, the ghosts, and the cut open (SwiftCutHit)
	---------------------------------------------------------------------
	-- ((round 90 review) `down`: a steeper limit down than up - the air stoop)
	function HK.cutDir(root, dir, aim, down)
		local d = (typeof(dir) == "Vector3" and dir.Magnitude > 0.01) and dir.Unit or root.CFrame.LookVector
		local flat = Vector3.new(d.X, 0, d.Z)
		flat = flat.Magnitude > 0.05 and flat.Unit or Vector3.new(root.CFrame.LookVector.X, 0, root.CFrame.LookVector.Z).Unit
		local pitch = math.clamp(math.asin(math.clamp(d.Y, -1, 1)), -math.rad(down or aim or 30), math.rad(aim or 30))
		return (flat * math.cos(pitch) + UP * math.sin(pitch)).Unit
	end
	-- carried along a line over `time`, through people (not walls)
	function HK.carry(root, d, range, time, air)
		rayParams.FilterDescendantsInstances = characterList()
		local hit = workspace:Raycast(root.Position, d * (range + 1.5), rayParams)
		local len = math.max((hit and hit.Distance or range + 1.5) - 1.5, 0.5)
		-- (round 90 review) the air stoop into the street ends ON it: his root
		-- its hip height over where the line meets it (it used to stop 1.5 studs
		-- short along the line - a steep one buried his legs in the street and
		-- the body popped up out of it); the server's line ends there too
		if air and hit and d.Y < -0.1 and hit.Normal.Y > 0.6 then
			len = math.max(math.min(len, (root.Position.Y - hit.Position.Y - 3) / -d.Y), 0.5)
		end
		local from = root.Position
		local to = from + d * len
		local flat = Vector3.new(d.X, 0, d.Z)
		flat = flat.Magnitude > 0.05 and flat.Unit or root.CFrame.LookVector
		local t0 = os.clock()
		local conn
		conn = RunService.Heartbeat:Connect(function()
			local a = math.clamp((os.clock() - t0) / time, 0, 1)
			-- (a hit that throws him, or the server taking him: it's over)
			if not root.Parent or root.Anchored or root:FindFirstChild("Knockback") then
				conn:Disconnect()
				return
			end
			local p = from:Lerp(to, a)
			root.CFrame = CFrame.lookAt(p, p + flat)
			root.AssemblyLinearVelocity = d * (len / time) * (1 - a)
			if a >= 1 then
				conn:Disconnect()
				root.AssemblyLinearVelocity = flat * 18
			end
		end)
		return from, to
	end
	-- (round 86, C2) SWIFT CUT, an iai dash (MoveHawksSwiftCut: the coil, the
	-- launch, the draw-cut as he goes through them - its Hit is Coil + Time,
	-- the pass - the skid, a twirl). The blades come out of his wings (a
	-- pale streak from each gap to his hands), a glint runs up the edge as it
	-- hardens; the wings tuck into the peregrine teardrop for the dash and
	-- flare forward as air brakes at the end. On the line: three red ghosts,
	-- small feathers shed, and as he goes through, the blade's arc - a
	-- crimson crescent rising from his left hip to out past his right
	-- shoulder (HK.crescent); his own screen: speed lines and a FOV kick.
	-- Then the skid, and the blades go home a beat after the twirl (unless
	-- he's swinging them)
	local function bladeParts(b, i)
		local m = b and b.models and b.models[i or 1]
		return m and m.Parent and m:GetChildren() or {}
	end
	-- the blade's point / its vane (the longest red piece) / its Neon edge
	function HK.bladeTip(b, i)
		for _, p in bladeParts(b, i) do
			if p:IsA("WedgePart") then
				return p
			end
		end
		return nil
	end
	function HK.bladeEdge(b, time)
		for i = 1, 2 do
			for _, p in bladeParts(b, i) do
				if p:IsA("BasePart") and p.Material == Enum.Material.Neon then
					p.Transparency = 0.15
					tween(p, time or 0.12, { Transparency = 1 })
				end
			end
		end
	end
	-- the feather each blade was: a pale streak from its gap to his hand
	function HK.drawFrom(char, b)
		for i, side in { 1, -1 } do
			local tip = HK.bladeTip(b, i)
			if tip then
				local from = HK.slotCF(char, side, "P2")
				local f = HK.dart(from, 2.2, "pale")
				tween(f, 0.07, { CFrame = tip.CFrame, Transparency = 0.6 }, Enum.EasingStyle.Quad, Enum.EasingDirection.In)
				task.delay(0.08, function()
					f:Destroy()
				end)
			end
		end
	end
	-- a blade's arc swept on in the air: a flat crescent ribbon in cf's YZ
	-- plane (thick in the middle, sharp at both ends), drawn on from one end
	-- (-Y) in a few hundredths of a second, then thinning away. (round 86,
	-- C2 review) The ribbon lies in that plane (its width along the radius,
	-- a sliver of depth across it), so a tilted cut stays a crescent
	function HK.crescent(cf, radius, sweep, color, thick, life)
		local n = IceKit.lowEnd() and 8 or 16
		local normal = cf.RightVector
		for i = 0, n - 1 do
			local a = math.rad(-sweep / 2 + sweep * i / n)
			local a2 = math.rad(-sweep / 2 + sweep * (i + 1) / n)
			local p1 = (cf * CFrame.new(0, math.sin(a) * radius, -math.cos(a) * radius)).Position
			local p2 = (cf * CFrame.new(0, math.sin(a2) * radius, -math.cos(a2) * radius)).Position
			local w = thick * (0.2 + 0.8 * math.sin(math.pi * (i + 0.5) / n))
			local seg = newPart(Vector3.new(w, 0.1, (p2 - p1).Magnitude + 0.15), CFrame.lookAt((p1 + p2) / 2, p2, normal), color, Enum.Material.Neon)
			seg.Name = "HawksArc"
			seg.Transparency = 1
			local d = i * 0.004
			tween(seg, 0.03, { Transparency = 0.05 }, nil, nil, d)
			tween(seg, life, { Transparency = 1, Size = Vector3.new(0.03, 0.03, seg.Size.Z) }, nil, nil, d + 0.06)
			cleanup(seg, d + life + 0.1)
		end
	end
	-- two dark streaks burned into the street where he skids
	function HK.skid(g, d)
		local flat = Vector3.new(d.X, 0, d.Z)
		flat = flat.Magnitude > 0.05 and flat.Unit or Vector3.new(0, 0, -1)
		local side = flat:Cross(UP).Unit
		for _, s in { -0.55, 0.55 } do
			local at = g + side * s + UP * 0.03 - flat * 1.6
			local m = newPart(Vector3.new(0.3, 0.05, 0.4), CFrame.lookAt(at, at + flat), Color3.fromRGB(58, 54, 54), Enum.Material.SmoothPlastic)
			m.Name = "HawksSkid"
			tween(m, 0.14, { Size = Vector3.new(0.3, 0.05, 3.6), CFrame = CFrame.lookAt(at + flat * 1.6, at + flat * 2.6) })
			tween(m, 0.6, { Transparency = 1 }, nil, nil, 0.9)
			cleanup(m, 1.55)
		end
	end
	function Effects.SwiftCut(char, data, isLocal, ability)
		local root = charParts(char)
		if not root then
			return
		end
		data = data or {}
		local spec = ability or Config.FindAbilityById("SwiftCut") or {}
		local coil, time = spec.Coil or 0.16, spec.Time or 0.22
		-- (round 90) in the air: a stoop, up to AirAim degrees down ((round 90
		-- review) and no steeper up than on the street: Aim)
		local d = HK.cutDir(root, data.Dir, spec.Aim or 30, data.Air == true and spec.AirAim or nil)
		if isLocal then
			face(root, d)
		end
		local low = IceKit.lowEnd()
		local EK = VFX.EngineKit
		-- the blades out of the wings (home after the twirl, unless he swings them)
		local had = HK.drawn[char] ~= nil
		local b = HK.blades(char, true)
		if b then
			if not had then
				HK.drawFrom(char, b)
			end
			b.til = math.min(b.til, os.clock() + coil + time + 0.62)
		end
		-- (round 90) in the air the legs hang free under the stoop
		local airCut = data.Air == true and (root.Position - groundPoint(root.Position)).Magnitude > 4.2
		if not (airCut and VFX.Clip(char, "MoveHawksSwiftCut", { legs = false, recover = 0.375 })) then
			VFX.Motion(char, "HawksSwiftCut")
		end
		HK.setWing(char, "Tuck", coil + time + 0.03, 30)
		VFX.PlaySound("FeatherDraw", root.Position, 1)
		VFX.PlaySound("SwiftCutCoil", root.Position, 1)
		local g = groundPoint(root.Position)
		if (root.Position - g).Magnitude < 4.5 then
			dustPuffs(g, 0.32, low and 2 or 5, HK.DUST, 0.45, false)
		end
		-- the edge hardens before the draw: a glint at the point
		task.delay(math.max(coil - 0.05, 0), function()
			local tip = HK.bladeTip(b, 1)
			if tip and tip.Parent and EK then
				EK.starSpark(tip.CFrame.Position, { size = 1.5, life = 0.09, color = HK.EDGE, color2 = HK.RED, spikes = 4 })
			end
			HK.bladeEdge(b, 0.14)
		end)
		task.wait(coil)
		if not root.Parent then
			return
		end
		VFX.PlaySound("SwiftCut", root.Position, 1)
		-- (his own machine carries him - while he's Hawks, not stunned or held)
		local me = Players.LocalPlayer
		if isLocal and me and me:GetAttribute("Quirk") == "FierceWings" and not char:GetAttribute("Stunned") and not char:GetAttribute("Grabbed") and not root.Anchored then
			HK.carry(root, d, spec.Range or 32, time, data.Air == true)
		end
		if isLocal then
			VFX.Hooks.SpeedLines(time + 0.2)
			if EK and EK.fovPunch then
				EK.fovPunch(7, 0.05, 0.32, time)
			end
		end
		-- the draw-cut at the end of the line: the blade's arc, a crimson
		-- crescent swept on round him (white-hot inside it) from his left hip
		-- out past his right shoulder, as his arm goes - (round 86, C2 review)
		-- tilted 22-32 degrees, so it's a crescent from every height, not a
		-- sliver edge-on at eye level
		task.delay(math.max(time - 0.05, 0), function()
			if root.Parent then
				local look = root.CFrame.LookVector
				local flat = Vector3.new(look.X, 0, look.Z)
				flat = flat.Magnitude > 0.05 and flat.Unit or Vector3.new(0, 0, -1)
				local tilt = math.rad(rand(22, 32))
				local up = flat:Cross(UP).Unit * math.cos(tilt) + UP * math.sin(tilt) -- (the sweep's end: up and out to his right)
				local cf = CFrame.fromMatrix(root.Position + UP * 0.2 + flat * 0.6, up:Cross(-flat), up, -flat)
				HK.crescent(cf, 4.4, 210, HK.CUT, 0.75, 0.24)
				if not low then
					HK.crescent(cf * CFrame.new(0.04, 0, 0), 4.2, 160, Color3.fromRGB(255, 240, 234), 0.28, 0.18)
				end
			end
		end)
		for i = 1, (low and 2 or 3) do
			task.delay((i - 1) * time / 3, function()
				if root.Parent and EK then
					EK.afterimage(char, Color3.fromRGB(230, 60, 60), 0.24, { transparency = 0.5 })
				end
			end)
		end
		for i = 1, (low and 4 or 9) do
			task.delay(i / 9 * time, function()
				if root.Parent then
					HK.shed(root.Position + UP * 0.8, 1, 1.4)
				end
			end)
		end
		streaks(root.Position + d * 2, d, low and 4 or 8, 1.2, 8, 18, WIND, 0.22)
		-- the end: the wings flared forward as air brakes, the skid
		task.delay(time + 0.02, function()
			if not root.Parent then
				return
			end
			HK.setWing(char, "Flare", 0.26, 30)
			VFX.PlaySound("WingSnap", root.Position, 0.8)
			local g2 = groundPoint(root.Position)
			if (root.Position - g2).Magnitude < 4.5 then
				dustPuffs(g2 + d * 1.5, 0.35, low and 2 or 4, HK.DUST, 0.5, false)
				HK.skid(g2, d)
				VFX.PlaySound("SwiftCutSkid", g2, 0.9)
			end
		end)
		-- the twirl: the blade flashes round in his fingers
		task.delay(time + 0.26, function()
			if root.Parent and HK.drawn[char] == b then
				HK.bladeEdge(b, 0.12)
				VFX.PlaySound("BladeTwirl", root.Position, 0.8)
			end
		end)
	end
	-- the cut: the blade's path left hanging, a white-hot line cooling to
	-- crimson; through each of them a crimson slash, and THE CRIMSON IMPACT
	-- FRAME on the screens near it (and theirs); Delay later - the cut they
	-- never saw - it splits open: the slash comes apart, flecks spray, the
	-- ring. (Too Fast's chain sends the targets of all three passes at once.)
	function Effects.SwiftCutHit(char, data)
		data = data or {}
		local from, to = typeof(data.From) == "Vector3" and data.From, typeof(data.To) == "Vector3" and data.To
		local delay = tonumber(data.Delay) or 0.25
		local root = char and char:FindFirstChild("HumanoidRootPart")
		local d = typeof(data.Dir) == "Vector3" and data.Dir.Magnitude > 0.01 and data.Dir.Unit
			or (from and to and (to - from).Magnitude > 0.5 and (to - from).Unit) or (root and root.CFrame.LookVector) or Vector3.new(0, 0, -1)
		if from and to and (to - from).Magnitude > 1 then
			local mid = (from + to) / 2 + UP * 0.6
			local len = (to - from).Magnitude
			local line = newPart(Vector3.new(0.26, 0.1, len), CFrame.lookAt(mid, mid + (to - from)), Color3.new(1, 1, 1), Enum.Material.Neon)
			line.Name = "HawksCut"
			tween(line, 0.14, { Color = HK.CUT, Size = Vector3.new(0.14, 0.07, len + 2) })
			tween(line, 0.35, { Transparency = 1, Size = Vector3.new(0.02, 0.02, len + 3) }, nil, nil, delay)
			cleanup(line, delay + 0.4)
			-- (round 86, C2 review) and a glow along it that faces every camera
			-- (the slab alone is a hair from 40 studs): white-hot, then crimson,
			-- gone with the split
			local a0, a1 = Instance.new("Attachment"), Instance.new("Attachment")
			a0.Position, a1.Position = Vector3.new(0, 0, len / 2), Vector3.new(0, 0, -len / 2)
			a0.Parent, a1.Parent = line, line
			local glow = Instance.new("Beam")
			glow.Name = "HawksCutGlow"
			glow.Attachment0, glow.Attachment1 = a0, a1
			glow.FaceCamera = true
			glow.Segments = 1
			glow.Width0, glow.Width1 = 0.32, 0.32
			glow.Color = ColorSequence.new(Color3.new(1, 1, 1))
			glow.LightEmission = 0.6
			glow.Transparency = NumberSequence.new(0.1)
			glow.Parent = line
			local t0, cooled = os.clock(), false
			HK.run(function()
				local age = os.clock() - t0
				if not glow.Parent or age > delay + 0.35 then
					return false
				end
				if age > 0.12 and not cooled then
					cooled = true
					glow.Color = ColorSequence.new(HK.CUT)
				end
				local fade = math.clamp((age - delay) / 0.3, 0, 1)
				glow.Transparency = NumberSequence.new(0.1 + 0.9 * fade, 0.25 + 0.75 * fade)
				return true
			end)
		end
		local targets = {}
		for _, t in (type(data.Targets) == "table" and data.Targets or {}) do
			local tr = typeof(t) == "Instance" and t:FindFirstChild("HumanoidRootPart")
			if tr then
				table.insert(targets, { model = t, root = tr })
			end
		end
		local flat = Vector3.new(d.X, 0, d.Z)
		flat = flat.Magnitude > 0.05 and flat.Unit or Vector3.new(0, 0, -1)
		local cuts, bodies = {}, { char }
		local across = flat:Cross(UP).Unit
		for i, t in targets do
			-- (across them, where the blade went through: it reads from his
			-- camera and theirs; the path line reads from the side)
			local p = t.root.Position + UP * 0.4
			local cf = CFrame.lookAt(p, p + across) * CFrame.Angles(0, 0, math.rad((i % 2 == 1 and 1 or -1) * rand(8, 16)))
			table.insert(cuts, HK.cut(cf, 7, 0.34, 0.05))
			local h = Instance.new("Highlight")
			h.Name = "HawksCutFlash"
			h.FillColor = Color3.new(1, 1, 1)
			h.FillTransparency = 0
			h.OutlineTransparency = 1
			h.DepthMode = Enum.HighlightDepthMode.Occluded
			h.Adornee = t.model
			h.Parent = folder
			tween(h, 0.14, { FillTransparency = 1 }, nil, nil, 0.04)
			cleanup(h, 0.2)
			table.insert(bodies, t.model)
		end
		local at = targets[1] and targets[1].root.Position or (to or from)
		if #targets > 0 then
			HK.impact(at, bodies, (flat:Cross(UP).X >= 0) and -14 or 14)
			VFX.PlaySound("SwiftCutPass", at, 1)
			VFX.ShakeAt(at, 1.1, 60, 0.16)
		end
		task.delay(delay, function()
			for _, c in cuts do
				-- it splits open: the slash's two halves come apart
				for _, s in { 1, -1 } do
					local half = newPart(Vector3.new(c.edge.Size.X * 0.5, 0.05, c.len), c.cf * CFrame.new(s * c.edge.Size.X * 0.25, 0, 0), Color3.fromRGB(255, 120, 110), Enum.Material.Neon)
					half.Name = "HawksCut"
					tween(half, 0.32, { CFrame = c.cf * CFrame.new(s * 0.35, s * 0.7, 0) * CFrame.Angles(0, 0, math.rad(s * 10)), Transparency = 1, Size = Vector3.new(0.05, 0.03, c.len * 1.1) }, Enum.EasingStyle.Quad, Enum.EasingDirection.Out)
					cleanup(half, 0.34)
				end
				-- (the core flares white across it first)
				if c.core.Parent then
					tween(c.core, 0.06, { Size = Vector3.new(0.8, 0.08, c.len * 1.15), Transparency = 0.2 })
					tween(c.core, 0.16, { Transparency = 1 }, nil, nil, 0.06)
					cleanup(c.core, 0.24)
				end
				if c.edge.Parent then
					c.edge:Destroy()
				end
			end
			local EK = VFX.EngineKit
			for _, t in targets do
				if t.root.Parent then
					local p = t.root.Position + UP * 0.4
					HK.flecks(p, IceKit.lowEnd() and 3 or 6, 1.8)
					sparks(p, 0.45, HK.EDGE, HK.RED, 6)
					if EK then
						EK.starSpark(p, { size = 2.6, life = 0.1, color = HK.CUT, color2 = Color3.new(1, 1, 1) })
					end
				end
			end
			VFX.PlaySound("SwiftCutRing", at or Vector3.zero, 1)
		end)
		for _, c in cuts do
			cleanup(c.edge, delay + 0.05)
			cleanup(c.core, delay + 0.3)
		end
	end
	-- (ult 2, TOO FAST: VFX.HU - round 86, hawks_ult)

	---------------------------------------------------------------------
	-- 3: PLUME CYCLONE / TEMPEST (held): the wings wrap round him, the
	-- feathers spin out into three rings while he holds it; the burst
	-- (round 86, C2) He crouches under the wrapped wings, arms crossed
	-- (PoseHawksMantle, held); the feathers peel off his wings one after
	-- another and spiral out of their slots onto three counter-rotating
	-- rings (the wings visibly thinner as the rings fill). Held: a red
	-- column - streaking rings, ribbons of wind whipping round ((round 92)
	-- not the two ForceField sheets: they drew the hitbox), his reach on his
	-- own screen, dust drawn in off the street, the roar, blades whirring past each
	-- other, gusts; a hit on him rings off the feathers. Let go
	-- (MoveHawksCycloneBurst: the arms thrown wide, the wings flared): a red
	-- starburst - every ring feather flung straight out - then (round 86,
	-- C2 review) the lent ones stream back into their own slots (the wings
	-- fill back up), with the refund's worth of the spent ones; the rest are
	-- torn to flecks. No burst (cancelled, he's down): they don't hang there
	---------------------------------------------------------------------
	-- how many feathers `points` more will show on his wings (a refund's worth)
	function HK.restored(char, points)
		local f = tonumber(char:GetAttribute("Feathers")) or 0
		local r0, l0 = HK.counts(f)
		local r1, l1 = HK.counts(f + (points or 0))
		return math.max(r1 + l1 - r0 - l0, 0)
	end
	-- (my own moves, for the carry's drop gesture: not over one of these)
	HK.acted = setmetatable({}, { __mode = "k" })
	function HK.cyclone(char, id, tempest, isLocal)
		local root = charParts(char)
		if not root then
			return
		end
		HK.acted[char] = os.clock()
		local spec = Config.FindAbilityById(id) or {}
		local R = spec.Radius or 7
		local low = IceKit.lowEnd()
		local n = low and 18 or math.min(spec.Count or 40, 48)
		local maxHold = spec.Hold and spec.Hold.Max or 2.5
		local rings = { { r = R * 0.57, h = 0.5 - 2.5, w = 9.4 }, { r = R * 0.79, h = 2.5 - 2.5, w = -7.9 }, { r = R, h = 4.5 - 2.5, w = 6.6 } }
		HK.setWing(char, "Mantle", maxHold + 0.5, 22)
		VFX.Pose(char, "HawksMantle", maxHold + 0.3)
		VFX.PlaySound("CycloneStart", root.Position, 1)
		VFX.PlaySound("CycloneLaunch", root.Position, 1)
		HK.loop(char, "CycloneLoop", tempest and 1.3 or 1)
		HK.loopVolume(char, "CycloneLoop", 1)
		-- the feathers: off the wings one after another, each spiralling out
		-- of its slot onto its ring
		local slots = HK.launchSlots(char, n)
		local feathers = {}
		for i = 1, n do
			feathers[i] = { i = i, ring = rings[(i - 1) % 3 + 1], a = (i / n) * math.pi * 2 * 3, s = slots[i], at = 0.1 + 0.22 * (i - 1) / n, out = 0 }
		end
		-- the wind inside: ribbons of air whipping round him ((round 92) not the
		-- two ForceField cylinders and the ForceField disc on the street any
		-- more - the shred radius drawn as a column on every screen: a hitbox.
		-- VFX.CycloneLook); on HIS screen only, a faint dashed ring at the reach
		local g0 = groundPoint(root.Position)
		local onStreet = (root.Position - g0).Magnitude < 6
		local CL = VFX.CycloneLook
		local wind = CL and CL.wind(root.Position + UP * 1.5, R, low)
		local reach = CL and CL.mine(char, isLocal) and CL.reach(root.Position, R, onStreet and g0.Y or nil)
		-- ((round 92 review) a failsafe past the job's own cap (maxHold + 0.8):
		-- HK.run drops a job that errors without its finish - the ribbons
		-- frozen in the air and his ring left on the street for good. stop()
		-- is idempotent, so the normal let-go makes this a no-op)
		if wind or reach then
			task.delay(maxHold + 1.5, function()
				if wind then
					wind.stop(0.2)
				end
				if reach then
					reach.stop(0.2)
				end
			end)
		end
		local hum = char:FindFirstChildOfClass("Humanoid")
		local lastHP = hum and hum.Health
		local t0 = os.clock()
		local nextDust, nextGust = 0.15, 0.35
		local finished = false
		-- (the burst takes this - whichever comes first on this screen, the
		-- server's let-go or the burst itself)
		local state = { feathers = feathers, id = id }
		HK.cyclones = HK.cyclones or setmetatable({}, { __mode = "k" })
		HK.cyclones[char] = state
		-- (round 86, C2 review) no burst to take them (let go without one, he's
		-- down, someone else): the ring doesn't hang there - the lent feathers
		-- fly back into their slots, the rest drop out of the air in flecks
		-- (dead: all of them, at once)
		local function release(dead)
			if state.released or state.burst then
				return
			end
			state.released = true
			if HK.cyclones and HK.cyclones[char] == state then
				HK.cyclones[char] = nil
			end
			for k, f in feathers do
				if f.part and f.part.Parent and not f.burst then
					f.burst = true
					local cf = f.part.CFrame
					if not dead and root.Parent and char.Parent and HK.owed(char, f.s) then
						f.part:Destroy()
						HK.flyHome(char, cf, f.s.side, f.s.slot, 130, Vector3.new(cf.Position.X - root.Position.X, 0, cf.Position.Z - root.Position.Z) * 2 + UP * 6, nil, f.s.Copy)
					else
						if k % 3 == 1 then
							HK.flecks(cf.Position, 1, 0.8)
						end
						tween(f.part, 0.3, { CFrame = cf + Vector3.new(0, -rand(1, 2.5), 0), Transparency = 1 }, Enum.EasingStyle.Quad, Enum.EasingDirection.In)
						cleanup(f.part, 0.32)
					end
				end
			end
		end
		local function finish(dead)
			if not finished then
				finished = true
				state.at = os.clock()
				HK.stopLoop(char, "CycloneLoop", 0.3)
				if wind then
					wind.stop(0.2)
				end
				if reach then
					reach.stop(0.2)
				end
			end
			-- (a burst on its way takes them - it comes with the let-go; the
			-- ring keeps turning a moment for it)
			if dead then
				release(true)
			end
		end
		state.finish = finish
		HK.run(function(dt, now)
			if state.burst or state.released then
				return false
			end
			local age = now - t0
			if finished then
				if now - state.at > 0.3 or not root.Parent then
					release(not root.Parent)
					return false
				end
			else
				local held = char:GetAttribute("Holding") == id
				-- (his own screen holds it from the press; the server's flag comes a beat later)
				if (age > 0.45 and not held) or age > maxHold + 0.8 or not root.Parent then
					finish(not root.Parent)
					if state.released then
						return false
					end
				end
			end
			local c = root.Position
			if not finished then
				if wind then
					wind.step(c + UP * 1.5, now)
				end
				if reach then
					reach.step(c, now)
				end
			end
			for _, f in feathers do
				if not f.part and age >= f.at and not finished then
					-- off the wing: thrown from its slot (round 86, C2 review: a
					-- spent one leaves it for good, a lent one till it's back; a
					-- copy flicks the one that stays)
					local from = HK.slotCF(char, f.s.side, f.s.slot)
					HK.launch(char, f.s, maxHold + 2.5)
					f.part = HK.feather(from, 1.2, nil)
					if not low or f.i % 2 == 0 then
						HK.trail(f.part, "red", 0.3, 0.2) -- (the rings read as streaking red bands)
					end
					f.from = from.Position
				end
				if f.part then
					f.out = math.min(f.out + dt / 0.24, 1)
					f.a += f.ring.w * dt
					local ringP = c + Vector3.new(math.cos(f.a) * f.ring.r, f.ring.h + math.sin(f.a * 2) * 0.3, math.sin(f.a) * f.ring.r)
					local e = 1 - (1 - f.out) ^ 2
					local p = f.from:Lerp(ringP, e)
					local tangent = Vector3.new(-math.sin(f.a), 0, math.cos(f.a)) * math.sign(f.ring.w)
					f.part.CFrame = HK.aim(p, tangent)
				end
			end
			if finished then
				return true -- (let go: the ring turns on a moment for the burst)
			end
			-- blades whirring past each other, gusts, the street's dust drawn in
			if rng:NextNumber() < dt * 9 then
				local a = rand(0, math.pi * 2)
				VFX.PlaySound("CycloneWhirr", c + Vector3.new(math.cos(a) * R, rand(-1, 2), math.sin(a) * R), 0.6)
			end
			if age > nextGust then
				nextGust = age + rand(0.55, 0.85)
				VFX.PlaySound("CycloneGust", c, 0.8)
			end
			if onStreet and not low and age > nextDust then
				nextDust = age + 0.1
				local a = rand(0, math.pi * 2)
				local p = Vector3.new(c.X, g0.Y, c.Z) + Vector3.new(math.cos(a), 0, math.sin(a)) * (R + rand(2, 4))
				local puff = newPart(Vector3.one * rand(0.9, 1.6), CFrame.new(p + UP * 0.4), HK.DUST, Enum.Material.SmoothPlastic, Enum.PartType.Ball)
				puff.Name = "HawksCyclone"
				puff.Transparency = 0.45
				local to = Vector3.new(c.X, g0.Y, c.Z) + Vector3.new(math.cos(a + 1.3), 0, math.sin(a + 1.3)) * R * 0.55 + UP * rand(2, 4)
				tween(puff, 0.55, { CFrame = CFrame.new(to), Size = Vector3.one * 0.4, Transparency = 1 }, Enum.EasingStyle.Sine, Enum.EasingDirection.In)
				cleanup(puff, 0.6)
			end
			-- a hit on him while they guard him rings off the feathers
			if hum then
				if lastHP and hum.Health < lastHP - 0.5 then
					local a = rand(0, math.pi * 2)
					local p = c + Vector3.new(math.cos(a) * R * 0.8, rand(-0.5, 2), math.sin(a) * R * 0.8)
					sparks(p, 0.5, Color3.new(1, 1, 1), HK.EDGE, 6)
					VFX.PlaySound("FeatherBlock", p, 0.9)
				end
				lastHP = hum.Health
			end
			return true
		end)
	end
	function Effects.PlumeCyclone(char, _, isLocal) -- ((round 92) isLocal: his screen - his reach ring)
		HK.cyclone(char, "PlumeCyclone", false, isLocal)
	end
	function Effects.PlumeTempest(char, _, isLocal)
		HK.cyclone(char, "PlumeTempest", true, isLocal)
	end
	function Effects.PlumeCycloneBurst(char, data)
		data = data or {}
		local root = charParts(char)
		local c = typeof(data.Pos) == "Vector3" and data.Pos or (root and root.Position)
		if not c then
			return
		end
		local R = tonumber(data.Radius) or 12
		local low = IceKit.lowEnd()
		if root then
			VFX.Motion(char, "HawksCycloneBurst")
			HK.setWing(char, "Flare", 0.34, 34)
		end
		HK.stopLoop(char, "CycloneLoop", 0.12)
		VFX.PlaySound("CycloneBurst", c, 1)
		VFX.ShakeAt(c, 1.3, 60, 0.22)
		shockDisc(c, UP, 4, R * 2.2, 0.3, Color3.fromRGB(255, 200, 190))
		billboardRing(c + UP, 3, R * 2, HK.LIT, 6, 0.3)
		-- a red starburst: streaks flung out from him all the way round
		for i = 1, (low and 8 or 16) do
			local a = i / (low and 8 or 16) * math.pi * 2 + rand(-0.1, 0.1)
			local dir = Vector3.new(math.cos(a), rand(-0.06, 0.2), math.sin(a)).Unit
			local s = newPart(Vector3.new(0.18, 0.18, 3.2), CFrame.lookAt(c + dir * 2, c + dir * 3), i % 3 == 0 and Color3.new(1, 1, 1) or HK.CUT, Enum.Material.Neon)
			s.Name = "HawksBurst"
			tween(s, 0.24, { CFrame = CFrame.lookAt(c + dir * (R + 2), c + dir * (R + 3)), Size = Vector3.new(0.05, 0.05, 5), Transparency = 1 }, Enum.EasingStyle.Quad, Enum.EasingDirection.Out)
			cleanup(s, 0.27)
		end
		local g = groundPoint(c)
		if (c - g).Magnitude < 6 then
			for i = 1, (low and 5 or 10) do
				local a = i / (low and 5 or 10) * math.pi * 2
				dustPuffs(g + Vector3.new(math.cos(a), 0, math.sin(a)) * R * 0.75, 0.45, 1, HK.DUST, 0.7, false)
			end
		end
		-- the ring feathers flung straight out; then (round 86, C2 review) the
		-- lent ones stream back into their own slots - the wings fill back up
		-- - and of the ones the hold spent, the refund's worth come home too;
		-- the rest are torn to flecks
		local cyc = HK.cyclones and HK.cyclones[char]
		local feathers = {}
		if cyc and not cyc.burst and not cyc.released then
			cyc.burst = true
			cyc.finish()
			feathers = cyc.feathers
		end
		if HK.cyclones then
			HK.cyclones[char] = nil
		end
		local spec = Config.FindAbilityById(data.Tempest and "PlumeTempest" or "PlumeCyclone") or {}
		local spare = math.max(HK.restored(char, spec.Refund or 8), 1)
		local live, homing = {}, {}
		for _, f in feathers do
			if f.part and f.part.Parent then
				table.insert(live, f)
				if root and HK.owed(char, f.s) then
					homing[f] = true
				elseif root and spare > 0 then
					spare -= 1
					homing[f] = true
				end
			end
		end
		local n = 0
		for _, f in live do
			f.burst = true
			local p = f.part.CFrame.Position
			local out = Vector3.new(p.X - c.X, 0, p.Z - c.Z)
			out = out.Magnitude > 0.1 and out.Unit or Vector3.new(1, 0, 0)
			local to = p + out * R
			tween(f.part, 0.18, { CFrame = HK.aim(to, out) }, Enum.EasingStyle.Quad, Enum.EasingDirection.Out)
			if homing[f] then
				n += 1
				local land = HK.homeward(char, f.s.Copy) -- (on its way: a refund before it lands waits for it)
				task.delay(0.36 + (n / #live) * 0.36, function()
					if f.part.Parent and root.Parent then
						local cf = f.part.CFrame
						f.part:Destroy()
						HK.flyHome(char, cf, f.s.side, f.s.slot, 130, nil, land)
					else
						land(nil)
					end
				end)
			else
				task.delay(0.2, function()
					if f.part.Parent then
						HK.flecks(f.part.CFrame.Position, 2, 1)
						f.part:Destroy()
					end
				end)
			end
		end
	end

	---------------------------------------------------------------------
	-- 4: FEATHER CARRY - the flick; the feathers hook them; he takes off
	-- with them. (The server carries the body: FeatherCarryLift, then
	-- Kit.HA - round 92, hawksair: no slam any more; VFX.HA hangs them under
	-- him and draws the follow-ups, HawksCarry)
	-- (round 86, C2) A lazy two-finger flick (MoveHawksCarry, its Hit at
	-- 0.08) - his body barely moves - and eight feathers leave his wings in
	-- two loose fans (each wing's swing out to its side and round), hooking
	-- into their clothes at the shoulders, back, wrists and ankles: red
	-- pins standing out of them. Reeled up under him (PoseHawksCarried:
	-- limp, the arms pulled up), the pins turned point-up and pulling,
	-- streaking, red lines up to him. Let go (a follow-up, LET GO, the
	-- landing): the pins pop out - the lent ones and the refund's worth fly
	-- home, the rest are spent
	---------------------------------------------------------------------
	-- where the pins go: { the R15 part, the R6 part, where on it (on R6's
	-- part: R15's is scaled to its own size - round 86, C2 review: its hands
	-- and feet are too small for them, so the forearms and shins) }
	local PINS = {
		{ "UpperTorso", "Torso", Vector3.new(0.72, 0.8, 0.5) }, { "UpperTorso", "Torso", Vector3.new(-0.72, 0.8, 0.5) },
		{ "UpperTorso", "Torso", Vector3.new(0.38, -0.2, 0.5) }, { "UpperTorso", "Torso", Vector3.new(-0.38, -0.2, 0.5) },
		{ "RightLowerArm", "Right Arm", Vector3.new(0, -0.8, 0.5) }, { "LeftLowerArm", "Left Arm", Vector3.new(0, -0.8, 0.5) },
		{ "RightLowerLeg", "Right Leg", Vector3.new(0, -0.8, 0.5) }, { "LeftLowerLeg", "Left Leg", Vector3.new(0, -0.8, 0.5) },
	}
	HK.carries = setmetatable({}, { __mode = "k" })
	function Effects.FeatherCarry(char, data, isLocal)
		local root = charParts(char)
		if not root then
			return
		end
		data = data or {}
		HK.acted[char] = os.clock()
		if isLocal and typeof(data.Dir) == "Vector3" then
			face(root, data.Dir)
		end
		VFX.Motion(char, "HawksCarry")
		HK.setWing(char, "Spread", 0.42, 26)
		for i = 1, 3 do
			task.delay((i - 1) * 0.03, function()
				if root.Parent then
					VFX.PlaySound("FeatherThwip", root.Position, 0.7)
				end
			end)
		end
	end
	-- the eight feathers, from his wings to their pins, then riding the body
	-- through the lift, the whirl and the slam (one job for all of it)
	function Effects.FeatherCarryHook(char, data)
		data = data or {}
		local root = charParts(char)
		if not root then
			return
		end
		local old = HK.carries[char]
		if old then
			old.phase = "gone"
		end
		local target = typeof(data.Target) == "Instance" and data.Target or nil
		local tr = target and target:FindFirstChild("HumanoidRootPart")
		local time = math.max(tonumber(data.Time) or 0.2, 0.05)
		local d = (typeof(data.Dir) == "Vector3" and data.Dir.Magnitude > 0.01) and data.Dir.Unit or root.CFrame.LookVector
		local c = { pins = {}, target = target, phase = "hook", t0 = os.clock(), time = time, dir = d }
		HK.carries[char] = c
		local slots = HK.launchSlots(char, #PINS)
		for i, pin in PINS do
			local s = slots[i]
			local from = HK.slotCF(char, s.side, s.slot)
			HK.launch(char, s, 8.5) -- (lent ones are out the whole carry: back by its end - (round 92, hawksair) the hold and a follow-up)
			local f = HK.dart(from, 1.25, "red")
			local r15 = target and target:FindFirstChild(pin[1])
			local on = r15 or (target and target:FindFirstChild(pin[2])) or nil
			local at = pin[3]
			if r15 and r15:IsA("BasePart") then
				local base = pin[2] == "Torso" and Vector3.new(2, 2, 1) or Vector3.new(1, 2, 1)
				at = at * (r15.Size / base)
			end
			local stuck = CFrame.new(at) * CFrame.Angles(math.rad(90 + rand(-28, 28)), 0, math.rad(rand(-28, 28)))
			-- (each wing's fan swings out to its own side, up, and round)
			local side = root.CFrame.RightVector * s.side
			table.insert(c.pins, { part = f, s = s, on = on, stuck = stuck, from = from.Position, bend = side * rand(4, 7) + UP * rand(1.5, 4), lag = (i - 1) * 0.012,
				miss = root.Position + d * rand(24, 30) + side * rand(1, 5) + UP * rand(0, 3) })
		end
		local hooked = false
		local function pull(p, pinCF, k)
			-- the pin standing in them (point in) -> point up (pulling) / down (driving them)
			local want
			if c.phase == "slam" then
				want = CFrame.new(pinCF.Position + UP * 0.75)
			else
				want = CFrame.new(pinCF.Position + UP * 0.75) * CFrame.Angles(math.pi, 0, 0)
			end
			return pinCF:Lerp(want, k)
		end
		HK.run(function(dt, now)
			if c.phase == "gone" or not char.Parent or now - c.t0 > 9 then -- (round 92, hawksair: a carry lasts up to ~6.5 s now)
				HK.unpull(c)
				for _, p in c.pins do
					if p.part.Parent then
						p.part:Destroy()
					end
				end
				return false
			end
			-- (round 86, C2 review) the one they hooked is gone (left, respawned)
			-- before the slam: the feathers let go and come home - not left
			-- hanging where the body was
			if c.target and not c.target.Parent and (c.phase == "hook" or c.phase == "lift") then
				c.target = nil
				c.phase = "done"
				if HK.carries[char] == c then
					HK.carries[char] = nil
				end
				HK.unpull(c)
				HK.carryHome(char, c, (Config.FindAbilityById("FeatherCarry") or {}).Refund)
				return false
			end
			-- (the pull lines' top: over their head as they rise - (round 92,
			-- hawksair) carried, just under him: they hang off his feathers)
			if c.pull and c.pull.Parent and c.phase == "lift" and tr and tr.Parent then
				local hr = c.carry and char:FindFirstChild("HumanoidRootPart")
				c.pull.CFrame = CFrame.new(hr and (hr.Position - UP * 1.3) or (tr.Position + UP * 4.5))
			end
			local age = now - c.t0
			for _, p in c.pins do
				if p.part.Parent and not p.free then
					local a = math.clamp((age - p.lag) / time, 0, 1)
					local pinCF = p.on and p.on.Parent and (p.on.CFrame * p.stuck)
					local goal = pinCF and pinCF.Position or p.miss
					if a < 1 then
						-- along a curve: out to its side, then in to the pin
						local e = a * a
						local q = (1 - e) * (1 - e) * p.from + 2 * (1 - e) * e * (p.from + p.bend) + e * e * goal
						local ahead = (1 - e) * (p.from + p.bend - p.from) + e * (goal - (p.from + p.bend))
						ahead = ahead.Magnitude > 0.01 and ahead.Unit or d
						p.part.CFrame = HK.aim(q, ahead)
					elseif pinCF then
						if not p.hit then
							p.hit = true
							sparks(pinCF.Position, 0.2, HK.EDGE, HK.RED, 2)
						end
						if c.phase == "lift" or c.phase == "slam" then
							p.k = math.min((p.k or 0) + dt / 0.14, 1)
						end
						p.part.CFrame = pull(p, pinCF, p.k or 0)
					else
						p.part.CFrame = HK.aim(goal, d)
					end
				end
			end
			if age >= time and not hooked then
				hooked = true
				if tr and tr.Parent then
					VFX.PlaySound("CarryHook", tr.Position, 1)
				end
			end
			if c.phase == "done" then
				return false
			end
			return true
		end)
	end
	-- the pins let go: (round 86, C2 review) the lent ones fly back into
	-- their own slots, and of the ones the carry spent, the refund's worth;
	-- the rest are spent (flecks). Nobody hooked: they all come home
	function HK.carryHome(char, c, refund)
		local spare = math.max(HK.restored(char, refund or 4), 1)
		local n = 0
		for _, p in c.pins do
			if p.part.Parent and not p.free then
				p.free = true
				n += 1
				local cf = p.part.CFrame
				local back = not c.target or HK.owed(char, p.s)
				if not back and spare > 0 then
					spare -= 1
					back = true
				end
				if back then
					local land = HK.homeward(char, p.s.Copy)
					-- (popped out: away from the slam's centre, up; nobody hooked
					-- there's no centre - out to its own side, round and home.
					-- round 86, C2 review: a flat zero kick's .Unit was NaN)
					local away = c.center and (cf.Position - c.center) or p.bend
					away = Vector3.new(away.X, 0, away.Z)
					if away.Magnitude < 0.05 then
						away = -(c.dir or Vector3.new(0, 0, 1))
						away = Vector3.new(away.X, 0, away.Z)
					end
					local kick = (away.Magnitude > 0.05 and away.Unit or Vector3.new(1, 0, 0)) * 18 + UP * 22
					task.delay(0.05 + n * 0.03, function()
						if p.part.Parent then
							p.part:Destroy()
						end
						if c.phase == "gone" then
							land(nil)
							return
						end
						HK.flyHome(char, cf, p.s.side, p.s.slot, 130, kick, land)
					end)
				else
					HK.flecks(cf.Position, 2, 1.2)
					p.part:Destroy()
				end
			end
		end
	end
	-- the pull lines (FeatherCarryLift) gone
	function HK.unpull(c)
		if c.pull then
			c.pull:Destroy()
			c.pull = nil
		end
		for _, p in c.pins do
			local b = p.part.Parent and p.part:FindFirstChild("HawksPull")
			if b then
				b:Destroy()
			end
		end
	end
	-- (round 92, hawksair) THE LIFT IS THE TAKEOFF now - no hoist, no slam
	-- (the owner: "have feather carry not downslam people but follow into a
	-- move in his alternate moveset while he's flying"): the pins reel them up
	-- under him as he takes off with them - the downstroke (or, up already,
	-- the wings catching him), the pins turned point-up and pulling, a line
	-- from every pin up to just under him (a puppet on strings, carried by
	-- his feathers) - and they hang there (VFX.HA hangs the body every frame
	-- before it's drawn) till a follow-up or the let go (HawksCarry). His own
	-- machine flies him up on it (HawksFly.start, opts.Carry). Nobody hooked:
	-- the feathers that flew out turn round and come home, as before
	function Effects.FeatherCarryLift(char, data)
		data = data or {}
		local c = HK.carries[char]
		local target = typeof(data.Target) == "Instance" and data.Target or nil
		local tr = target and target:FindFirstChild("HumanoidRootPart")
		local spec = Config.FindAbilityById("FeatherCarry") or {}
		if not tr then
			if c then
				c.target = nil
				HK.unpull(c)
				HK.carryHome(char, c, spec.Refund)
				c.phase = "done"
				if HK.carries[char] == c then
					HK.carries[char] = nil
				end
			end
			return
		end
		local root = char:FindFirstChild("HumanoidRootPart")
		-- (his own machine: up with them)
		local lp = Players.LocalPlayer
		if lp and lp.Character == char and VFX.Hooks.HawksFly then
			local hum = char:FindFirstChildOfClass("Humanoid")
			VFX.Hooks.HawksFly(Config.FindAbilityById("FierceWings"), hum ~= nil and hum.FloorMaterial == Enum.Material.Air, { Carry = true })
		end
		if VFX.HA then
			VFX.HA.start(target, char)
		end
		if root then
			local g = groundPoint(root.Position)
			if (root.Position - g).Magnitude < 6 then
				HK.takeoff(char, root)
			else
				HK.airCatch(char, root)
			end
			VFX.PlaySound("CarryTakeoff", root.Position, 1)
		end
		VFX.Pose(target, "HawksCarried", 1.2)
		VFX.PlaySound("CarryLift", tr.Position, 1)
		streaks(tr.Position - UP * 2, UP, IceKit.lowEnd() and 3 or 6, 1.5, 6, 12, WIND, 0.3)
		if not c then
			return
		end
		c.phase = "lift"
		c.carry = true
		for _, p in c.pins do
			local t = p.part:FindFirstChildOfClass("Trail")
			if t then
				t.Lifetime = 0.3 -- (rising: red streaks under every pin)
			end
		end
		-- (round 86, C2 review: research 9.6.3) thin red lines from every pin
		-- up to just under him - (half of them on a low-end machine)
		HK.unpull(c)
		local top = newPart(Vector3.one * 0.1, CFrame.new(root and (root.Position - UP * 1.3) or (tr.Position + UP * 4.5)), HK.CUT, nil)
		top.Name = "HawksPull"
		top.Transparency = 1
		local a1 = Instance.new("Attachment")
		a1.Parent = top
		c.pull = top
		for i, p in c.pins do
			if p.part.Parent and p.on and (i % 2 == 1 or not IceKit.lowEnd()) then
				local a0 = Instance.new("Attachment")
				a0.Name = "HawksPullAt"
				a0.Parent = p.part
				local b = Instance.new("Beam")
				b.Name = "HawksPull"
				b.Attachment0, b.Attachment1 = a0, a1
				b.FaceCamera = true
				b.Segments = 1
				b.Width0, b.Width1 = 0.09, 0.03
				b.Color = ColorSequence.new(Color3.fromRGB(220, 40, 40))
				b.LightEmission = 0.4
				b.Transparency = NumberSequence.new(0.15, 0.55)
				b.Parent = p.part
			end
		end
	end

	-- (ult 4, THE THOUSAND-FEATHER STORM: VFX.HU - round 86, hawks_ult)

	---------------------------------------------------------------------
	-- his dash (a beat of the wings and a few feathers shed)
	---------------------------------------------------------------------
	-- (round 90) every dash costs him Feathers.Dash (3): those three peel off
	-- the wings as he goes - each leaves its own slot (HK.launch: the wing
	-- thins by exactly what he paid), is flicked out behind him on the push
	-- and whips away spinning on a short crimson streak, then flutters down
	-- and breaks up - with a puff of down off the wing roots. Plucked (no
	-- feathers to give: a bare-wing dash) only the down
	HK.DASH_HOLD = 2.4 -- (a lent slot stays empty this long for the spend to land)
	function HK.dashFeathers(char, root, dir)
		local F = SPEC.Dash or 3
		local plucked = char:GetAttribute("Plucked") == true and (tonumber(char:GetAttribute("Feathers")) or 0) <= 0
		local back = -(Vector3.new(dir.X, 0, dir.Z).Magnitude > 0.05 and Vector3.new(dir.X, 0, dir.Z).Unit or root.CFrame.LookVector)
		local low = IceKit.lowEnd()
		-- the down: pale motes off the wing roots
		for _, side in { 1, -1 } do
			local p = (root.CFrame * CFrame.new(side * 0.5, 1.3, 0.7)).Position
			for _ = 1, (low and 2 or (plucked and 6 or 3)) do
				local m = newPart(Vector3.one * rand(0.1, 0.18), CFrame.new(p), Color3.fromRGB(255, 226, 220), Enum.Material.SmoothPlastic, Enum.PartType.Ball)
				tween(m, rand(0.6, 1), { Position = p + back * rand(1, 2.5) + Vector3.new(rand(-1, 1), rand(-0.6, 1.2), rand(-1, 1)), Transparency = 1 }, Enum.EasingStyle.Sine)
				cleanup(m, 1.05)
			end
		end
		if plucked then
			return 0
		end
		-- (exactly what the count will hide leaves the wing: the spend may thin
		-- the wing by fewer slots than feathers - the rest are flicked off
		-- feathers that stay. Once the count has dropped (someone else's
		-- screen) the slots it just hid are what's thrown)
		-- (round 90 review) On his own screen (before the spend) the slots lent
		-- are the ones the spend will hide ON EACH WING - the wings take turns
		-- losing one, so it may be the left's alone: lending by count alone
		-- took the right's, the left's went 0.55 s later and the right one
		-- "grew back" 2.4 s after the dash. And never more off him than he has
		local pool = HK.launchSlots(char, F * 2)
		local f = tonumber(char:GetAttribute("Feathers")) or 0
		local gone = 0
		for _, s in pool do
			if not s.Loan and not s.Copy then
				gone += 1
			end
		end
		local slots = {}
		if gone > 0 then
			for i = 1, F do
				local s = pool[i]
				if s and s.Loan then
					s.Loan, s.Copy = nil, true
				end
				table.insert(slots, s)
			end
		else
			F = math.min(F, math.max(math.floor(f), 0))
			local r1, l1 = HK.counts(f)
			local r2, l2 = HK.counts(math.max(f - F, 0))
			local need = { [1] = math.max(r1 - r2, 0), [-1] = math.max(l1 - l2, 0) }
			for _, s in pool do
				if #slots < F and s.Loan and need[s.side] > 0 then
					need[s.side] -= 1
					table.insert(slots, s)
				end
			end
			for _, s in pool do
				if #slots >= F then
					break
				end
				if not table.find(slots, s) then
					table.insert(slots, { side = s.side, slot = s.slot, Flick = true, Copy = true })
				end
			end
		end
		local side = back:Cross(UP)
		side = side.Magnitude > 0.05 and side.Unit or root.CFrame.RightVector
		for i, s in slots do
			local from = HK.slotCF(char, s.side, s.slot)
			HK.launch(char, s, HK.DASH_HOLD)
			local f = HK.dart(from, 1.2, "red", 0.1)
			local p0 = from.Position
			-- (out behind him and off to its own wing's side, a little up, spinning)
			local v = (back * rand(14, 20) + side * s.side * rand(4, 8) + UP * rand(3, 7))
			local spin = rand(10, 18) * (i % 2 == 0 and 1 or -1)
			local t0 = os.clock()
			local life = rand(0.55, 0.8)
			HK.run(function(dt)
				if not f.Parent then
					return false
				end
				local age = os.clock() - t0
				if age >= life then
					if nearCamera(f.Position, 80) then
						HK.flecks(f.Position, low and 1 or 2, 0.8)
					end
					f:Destroy()
					return false
				end
				v = v * math.exp(-4.5 * dt) + Vector3.new(0, -14 * dt, 0) -- (the drag of the air, then drifting down)
				p0 += v * dt
				local d = v.Magnitude > 0.5 and v.Unit or -UP
				f.CFrame = HK.aim(p0, d) * CFrame.Angles(0, age * spin, 0)
				if age > life * 0.6 then
					local tr = (age - life * 0.6) / (life * 0.4)
					f.Transparency = tr
					for _, c in f:GetChildren() do
						if c:IsA("BasePart") then
							c.Transparency = tr
						end
					end
				end
				return true
			end)
		end
		return #slots
	end
	QUIRK_FX.Dash.FierceWings = function(char, root, dir)
		HK.setWing(char, "Tuck", 0.28, 30)
		task.delay(0.22, function()
			if char.Parent then
				HK.setWing(char, "Flare", 0.15, 30)
			end
		end)
		HK.dashFeathers(char, root, dir)
		VFX.PlaySound("WingFlap", root.Position, 0.8)
		VFX.PlaySound("HawksDash", root.Position, 0.9)
	end
	-- (the awakening, QUIRK_FX.Ult.FierceWings: VFX.HU - round 86, hawks_ult;
	-- (round 101 review) now VFX.AK.FX.FierceWings, on the awakening kit)
end)()

---------------------------------------------------------------------------
-- (round 86, hawks_ult) HAWKS' ULT (VFX.HU): FULL PLUMAGE.
--   THE AWAKENING ((round 101) VFX.AK.FX.FierceWings on the awakening kit -
--     was QUIRK_FX.Ult.FierceWings, SHOTS.AwakeningFierceWings):
--     the wings wrap round him like a cocoon, then on the snap (0.30 s,
--     MoveHawksAwaken's Hit) they're thrown open to Max - rebuilt half again
--     as big (Wing.UltScale), the overgrowth row out - and feathers burst off
--     the edges.
--   THE LOOK IN THE ULT (HU.watch): a faint rim of light round the wings
--     (one Highlight on his HawksWings, Wing.UltRim), now and then a feather
--     drifting loose.
--   THE THOUSAND-FEATHER STORM (Effects.FeatherStorm*): one run per Hawks on
--     every screen, on the plan's clock (Beats: Crouch, Rise, Sun, Break,
--     Storm, Dive, Home - each beat fired by its event from the server, or
--     the clock if that's late): the downstroke that throws him 40 up; hung
--     against the sun, every feather on him (his own screen: a silhouette, a
--     disc of sun behind him, the warm grade, the flare); every feather off
--     him at once (his real wing feathers torn off, cloned, and a burst of
--     shards); the storm - pooled feather parts (Show.Parts) chasing a
--     funnel that tightens on them, shard emitters (Show.Swirl) and ribbons
--     of wind going round it, the ones caught in it cut to pieces; two swords
--     out of the swirl, the dive, the X-cut (a red impact frame); every
--     feather home in long pale streaks, the wings filling back in as they
