		dark = setmetatable({}, { __mode = "k" }), -- [char] = his silhouette (the rim stands aside)
		clouds = setmetatable({}, { __mode = "k" }), -- [char] = Scarlet Rain's cloud
		tempests = setmetatable({}, { __mode = "k" }), -- [char] = Tempest's extras
