	---------------------------------------------------------------------
	-- small things
	---------------------------------------------------------------------
	function HU.low()
		return IceKit.lowEnd()
	end
	-- n, halved on a low-end machine (never under 1)
	function HU.n(x)
		return math.max(math.floor((tonumber(x) or 0) * (HU.low() and 0.5 or 1) + 0.5), 1)
	end
	function HU.alive(char)
		local hum = char and char.Parent and char:FindFirstChildOfClass("Humanoid")
