		p.Transparency = 0
		p.Parent = folder
		return p
	end
	function HU.give(p)
		if not p then
			return
		end
		for _, c in p:GetChildren() do
			c:Destroy()
		end
		if #HU.pool < 320 and p.Name == "HawksStormFeather" then
			p.Parent = nil
			table.insert(HU.pool, p)
		else
