		end
		if not HU.noBulk then
			local ok = pcall(function()
				workspace:BulkMoveTo(parts, cfs, Enum.BulkMoveMode.FireCFrameChanged)
			end)
			if ok then
				HU.bulkFails = 0
				return
			end
			-- (round 86 review) only given up on after a few in a row (one
			-- bad part shouldn't cost every storm after it; a new storm tries again)
			HU.bulkFails = (HU.bulkFails or 0) + 1
			HU.noBulk = HU.bulkFails >= 3
		end
		for i, p in parts do
			p.CFrame = cfs[i]
		end
	end
	-- a shard emitter: crimson feather-knives (an elongated triangle along its
	-- flight), off `parent` (a part or an attachment)
	function HU.emitter(parent, o)
		o = o or {}
		local pe = Instance.new("ParticleEmitter")
		pe.Name = "HawksShards"
		pe.Texture = HU.SHARD
		pe.Color = CS({ CK(0, HU.TIP), CK(0.3, HU.LIT), CK(1, HU.DEEP) })
		pe.LightInfluence = 0.55
		pe.LightEmission = o.Light or 0.15
		local s = o.Size or 0.6
		pe.Size = NS({ NK(0, s), NK(1, s * 0.55) })
		pe.Squash = NS(o.Squash or 1.4)
		pe.Transparency = NS({ NK(0, 0), NK(0.75, 0.15), NK(1, 1) })
		pe.Orientation = Enum.ParticleOrientation.VelocityParallel
		pe.Lifetime = NumberRange.new(o.Life0 or 0.4, o.Life1 or 0.7)
		pe.Speed = NumberRange.new(o.Speed0 or 20, o.Speed1 or 40)
		pe.SpreadAngle = Vector2.new(o.Spread or 180, o.Spread or 180)
		pe.Drag = o.Drag or 2
		pe.Acceleration = o.Accel or Vector3.new(0, -6, 0)
