		holder.Name = "HawksShardBurst"
		holder.Transparency = 1
		local pe = HU.emitter(holder, { Speed0 = speed * 0.5, Speed1 = speed, Spread = o.Spread or 180, Drag = o.Drag or 3, Life0 = 0.45, Life1 = 0.9, Size = o.Size or 0.7, Squash = 1.6 })
