		cleanup(holder, 1.2)
		return holder
	end
	-- a thin cut in the air: a neon line through `at`, gone in `life`
	function HU.slash(at, len, life, color)
		local cf = CFrame.new(at) * CFrame.Angles(rand(0, 6.28), rand(0, 6.28), rand(0, 6.28))
		local p = newPart(Vector3.new(0.07, 0.07, len), cf, color or HU.EDGE, Enum.Material.Neon)
		p.Name = "HawksSlash"
		tween(p, life, { Transparency = 1, Size = Vector3.new(0.02, 0.02, len * 1.3) })
		cleanup(p, life + 0.05)
		return p
	end
	-- a trail of light behind a part for a while
	function HU.streak(part, color, width, life, time)
		local a0 = Instance.new("Attachment")
		a0.Name = "HawksStreak0"
		a0.Position = Vector3.new(0, width / 2, 0)
		a0.Parent = part
		local a1 = Instance.new("Attachment")
		a1.Name = "HawksStreak1"
		a1.Position = Vector3.new(0, -width / 2, 0)
		a1.Parent = part
		local t = Instance.new("Trail")
		t.Name = "HawksStreak"
		t.Attachment0, t.Attachment1 = a0, a1
		t.Color = CS(color or HU.PALE, Color3.new(1, 1, 1))
		t.Transparency = NS({ NK(0, 0.2), NK(1, 1) })
		t.LightEmission = 0.6
		t.Lifetime = life or 0.2
		t.FaceCamera = true
		t.Parent = part
		if time then
			task.delay(time, function()
				t.Enabled = false
				task.delay(life or 0.2, function()
					t:Destroy()
					a0:Destroy()
					a1:Destroy()
				end)
			end)
		end
		return t
	end

	---------------------------------------------------------------------
	-- the silhouette, the sun, the grade (the caster's cutscene only)
	---------------------------------------------------------------------
	-- him black against the light, a fiery edge round him (wings and all)
	function HU.silhouette(char, on, fade)
		local h = HU.dark[char]
		if on then
			-- (round 86 review) the ult's rim stands aside at once - never one
			-- Highlight under another (HU.watch puts it back after)
			local rim = HU.rims[char]
			if rim then
				rim.Enabled = false
			end
			if not (h and h.Parent) then
				h = Instance.new("Highlight")
				h.Name = "HawksSilhouette"
				h.FillColor = HU.INK
				h.OutlineColor = HU.RIM
				h.FillTransparency = 1
				h.OutlineTransparency = 1
				h.DepthMode = Enum.HighlightDepthMode.Occluded
				h.Adornee = char
				h.Parent = folder
				HU.dark[char] = h
			end
			tween(h, fade or 0.08, { FillTransparency = 0.04, OutlineTransparency = 0 })
		elseif h then
			HU.dark[char] = nil
			tween(h, fade or 0.1, { FillTransparency = 1, OutlineTransparency = 1 })
			task.delay((fade or 0.1) + 0.02, function()
				h:Destroy()
			end)
		end
	end
	-- the sun behind `at` seen from `eye`: a disc of light out along the line
	-- (sized to be `size` studs across where he is - the same on screen however
	-- far it's put), in front of any building that line runs into
	function HU.sun(at, eye, size)
		local gap = at - eye
		if gap.Magnitude < 0.5 then
			return nil
		end
		local dir = gap.Unit
		local dist = 240
		pcall(function()
			rayParams.FilterDescendantsInstances = characterList()
			local hit = workspace:Raycast(at + dir * 2, dir * dist, rayParams)
			if hit then
				dist = math.max(hit.Distance - 1, 18)
			end
		end)
		local anchor = newPart(Vector3.one * 0.2, CFrame.new(at + dir * dist), HU.SUN_CORE)
		anchor.Name = "HawksSun"
		anchor.Transparency = 1
		local s = size * (gap.Magnitude + dist) / gap.Magnitude
		local bb = Instance.new("BillboardGui")
		bb.Name = "HawksSunDisc"
		bb.Size = UDim2.fromScale(s, s)
		bb.LightInfluence = 0
		bb.Brightness = 2.6
		bb.AlwaysOnTop = false
		bb.MaxDistance = 6000
		bb.Adornee = anchor
		local frames = {}
		-- a wide warm glow, the bright middle, the white core; the long
		-- horizontal streak of a lens across it
		for _, spec in {
			{ 1, 1, HU.SUN_EDGE, 0.84 }, { 0.78, 0.78, HU.SUN_EDGE, 0.72 }, { 0.58, 0.58, HU.SUN_MID, 0.5 },
			{ 0.4, 0.4, HU.SUN_MID, 0.2 }, { 0.27, 0.27, HU.SUN_CORE, 0 },
			{ 2.6, 0.022, HU.SUN_MID, 0.45 }, { 1.5, 0.01, HU.SUN_CORE, 0.15 }, { 0.012, 0.9, HU.SUN_MID, 0.6 },
		} do
			local f = Instance.new("Frame")
			f.AnchorPoint = Vector2.new(0.5, 0.5)
			f.Position = UDim2.fromScale(0.5, 0.5)
			f.Size = UDim2.fromScale(spec[1], spec[2])
			f.BackgroundColor3 = spec[3]
			f.BackgroundTransparency = 1
			f.BorderSizePixel = 0
			if spec[1] == spec[2] then
				local c = Instance.new("UICorner")
				c.CornerRadius = UDim.new(0.5, 0)
				c.Parent = f
			end
			f.Parent = bb
			tween(f, 0.12, { BackgroundTransparency = spec[4] })
			table.insert(frames, f)
		end
		bb.Parent = anchor
		local sun = { part = anchor, gui = bb }
		function sun.kill(t)
			for _, f in frames do
				tween(f, t or 0.1, { BackgroundTransparency = 1 })
			end
			task.delay((t or 0.1) + 0.03, function()
				anchor:Destroy()
			end)
		end
		return sun
	end
	-- the warm, hard light of a shot into the sun (this screen's Lighting)
	function HU.grade(on, fade)
		local cc = Lighting:FindFirstChild("HawksSunGrade")
		local bloom = Lighting:FindFirstChild("HawksSunBloom")
		HU.gradeToken = (HU.gradeToken or 0) + 1
		local token = HU.gradeToken
		if on then
			if not cc then
				cc = Instance.new("ColorCorrectionEffect")
				cc.Name = "HawksSunGrade"
				cc.Parent = Lighting
			end
			cc.Enabled = true
			tween(cc, 0.1, { TintColor = Color3.fromRGB(255, 226, 196), Contrast = 0.3, Saturation = -0.14, Brightness = 0.03 })
			if not bloom then
				bloom = Instance.new("BloomEffect")
				bloom.Name = "HawksSunBloom"
				bloom.Intensity = 0
				bloom.Size = 36
				bloom.Threshold = 0.9
				bloom.Parent = Lighting
			end
			tween(bloom, 0.1, { Intensity = 0.9 })
		else
			fade = math.max(tonumber(fade) or 0.15, 0.03)
			if cc then
				tween(cc, fade, { TintColor = Color3.new(1, 1, 1), Contrast = 0, Saturation = 0, Brightness = 0 })
			end
			if bloom then
				tween(bloom, fade, { Intensity = 0 })
			end
			task.delay(fade + 0.02, function()
				if HU.gradeToken == token then
					if cc then
						cc:Destroy()
					end
					if bloom then
						bloom:Destroy()
					end
				end
			end)
		end
	end
	-- the flare's ghosts: faint rings from the sun through the middle of the
	-- screen (redrawn every frame from where the sun is on screen)
	function HU.flare(sunPart)
		local me = Players.LocalPlayer
		local pg = me and me:FindFirstChildOfClass("PlayerGui")
		if not pg or HU.low() then
			return nil
		end
		local g = Instance.new("ScreenGui")
		g.Name = "HawksSunFlare"
		g.IgnoreGuiInset = true
		g.ResetOnSpawn = false
		g.DisplayOrder = 30
		local ghosts = {}
		for i, spec in { { 0.06, HU.SUN_MID, 0.8 }, { 0.11, HU.SUN_EDGE, 0.86 }, { 0.035, HU.SUN_CORE, 0.75 }, { 0.16, HU.SUN_EDGE, 0.9 } } do
			local f = Instance.new("Frame")
			f.AnchorPoint = Vector2.new(0.5, 0.5)
			f.SizeConstraint = Enum.SizeConstraint.RelativeYY
			f.Size = UDim2.fromScale(spec[1], spec[1])
			f.BackgroundColor3 = spec[2]
			f.BackgroundTransparency = spec[3]
			f.BorderSizePixel = 0
			local c = Instance.new("UICorner")
			c.CornerRadius = UDim.new(0.5, 0)
			c.Parent = f
			f.Parent = g
			ghosts[i] = f
		end
		g.Parent = pg
		local flare = { gui = g }
		local along = { 0.55, 1.2, 1.55, 1.9 }
		function flare.step()
			local cam = workspace.CurrentCamera
			if not (cam and sunPart.Parent) then
				return
			end
			local ok, p = pcall(function()
				return cam:WorldToViewportPoint(sunPart.CFrame.Position)
			end)
			local vs = cam.ViewportSize
			if not ok or typeof(p) ~= "Vector3" or p.Z <= 0 or vs.X < 10 then
				g.Enabled = false
				return
			end
			g.Enabled = true
			local sx, sy = p.X / vs.X, p.Y / vs.Y
			for i, f in ghosts do
				local k = along[i]
				f.Position = UDim2.fromScale(sx + (0.5 - sx) * k, sy + (0.5 - sy) * k)
			end
		end
		return flare
	end

	---------------------------------------------------------------------
	-- THE AWAKENING: the cocoon, the snap, the burst
	---------------------------------------------------------------------
	-- ((round 101, awaken_m) his cutscene is the kit's two shots now
	-- (VFX.AK.shots: close on him as the wings close, cut on the snap to the
	-- cut-in's frame) - his own SHOTS.AwakeningFierceWings is retired)
	-- loose feathers torn off the wing edges, flung out and drifting down
	function HU.tornOff(char, root, n, speed)
		local slots = {}
		for _, side in { 1, -1 } do
			for _, row in { "P", "S" } do
				for i = 1, (row == "P" and 6 or 8) do
					table.insert(slots, { side, row .. i })
				end
			end
		end
		for i = 1, n do
			local s = slots[rng:NextInteger(1, #slots)]
			local cf = HK.slotCF(char, s[1], s[2])
			local f = HK.feather(cf * CFrame.new(rand(-0.3, 0.3), rand(-0.8, 0.4), 0), rand(0.8, 1.3), i % 3 == 0 and "red" or nil)
			local out = (cf.Position - root.Position)
			out = (Vector3.new(out.X, 0, out.Z).Magnitude > 0.1 and Vector3.new(out.X, 0, out.Z).Unit or root.CFrame.RightVector * s[1]) + UP * rand(0.1, 0.9)
			local to = cf.Position + out.Unit * rand(speed * 0.4, speed)
			local t = rand(0.35, 0.6)
			tween(f, t, { CFrame = HU.along(to, out, rand(0, 6)) }, Enum.EasingStyle.Quad, Enum.EasingDirection.Out)
			local down = to + Vector3.new(rand(-2, 2), -rand(4, 8), rand(-2, 2))
			tween(f, rand(0.9, 1.4), { CFrame = HU.along(down, Vector3.new(rand(-1, 1), -0.4, rand(-1, 1)), rand(0, 6)), Transparency = 1 }, Enum.EasingStyle.Sine, Enum.EasingDirection.In, t)
			cleanup(f, t + 1.5)
		end
	end
	-- the rim flares bright for a moment (the wings opening)
	function HU.rimFlash(char)
		task.delay(0.05, function()
			local h = HU.rims[char]
			if h and h.Parent then
				local R = W.UltRim or {}
				h.OutlineTransparency = 0
				h.FillTransparency = 0.45
				tween(h, 0.6, { OutlineTransparency = R.Outline or 0.4, FillTransparency = HU.low() and 1 or (R.Fill or 0.9) })
			end
		end)
	end
	-- ((round 101, awaken_m) on the awakening kit, VFX.AK.FX.FierceWings - his
	-- clip MoveHawksAwaken, retimed onto the template (gathered by 0.18,
	-- thrown open ON the shared hit at 0.30, the arms coming down proud
	-- through the hold, done by 1.54): the wings wrap round him from the press
	-- (the cocoon) with the air drawn in, and his own sound's beat lands on the
	-- hit (Config.Sounds.UltFierceWings, played from the press: his row's
	-- Sound = false); then ON the hit the wings are thrown open to Max, the
	-- feathers torn off the edges, the shard burst, the gust - the snap no
	-- longer times itself (0.28; the cut-in came 0.16 s before it). His screen
	-- takes the kit's impact frame and kick for the old flash and shake;
	-- everyone else's keeps them. QUIRK_FX.Ult.FierceWings folded in here.)
	VFX.AK.FX.FierceWings = {
		press = function(ctx)
			local root = ctx.root
			HK.setWing(ctx.char, "Mantle", math.max(ctx.hit - 0.03, 0.05), 30) -- the cocoon
			local g = ctx.g or (root.Position - UP * 3 * ctx.scale)
			shockDisc(g + UP * 0.4, UP, 30, 7, math.max(ctx.hit - 0.04, 0.05), Color3.fromRGB(255, 226, 214))
			VFX.PlaySound("UltFierceWings", root.Position, 1)
		end,
		hit = function(ctx)
			local char, root = ctx.char, ctx.root
			local g = ctx.g or (root.Position - UP * 3 * ctx.scale)
			HK.setWing(char, "Max", 1.05, 34)
			pcall(HU.watch) -- (the rim on at once: the rebuilt wings are already there)
			HU.rimFlash(char)
			HU.tornOff(char, root, HU.n(26), 16)
			HU.shards(root.CFrame * CFrame.new(0, 1.2, 0.9) * CFrame.Angles(0, math.pi, 0), HU.n(140), 75, { Spread = 120 })
			VFX.AK.note(ctx, "wingsOpen")
			shockDisc(g + UP * 0.3, UP, 6, 50, 0.5, Color3.fromRGB(255, 226, 214))
			-- (the gust off the wings: a ring, not a disc filling the close-up)
			billboardRing(root.Position + UP * 2.5, 3, 14, HU.PALE, 4, 0.3)
			billboardRing(root.Position + UP, 3, 38, HU.LIT, 8, 0.42)
			if not ctx.mine then
				-- (his own screen has the impact frame and the camera's kick)
				if nearCamera(root.Position, 80) then
					VFX.Hooks.Flash(HU.SUN_MID, 0.25)
				end
				VFX.ShakeAt(root.Position, 3, 150, 0.5)
			end
			billboardRing(root.Position + UP, 2, 24, HU.SUN_MID, 5, 0.3)
			streaks(root.Position + UP * 2, UP, HU.n(16), 3, 10, 30, HU.PALE, 0.35)
			if ctx.g then
				for i = 1, HU.n(8) do
					local a = i / 8 * math.pi * 2
					dustPuffs(g + Vector3.new(math.cos(a), 0, math.sin(a)) * 6, 0.5, 1, HK.DUST, 0.8, false)
				end
			end
		end,
		aura = function(ctx)
			return VFX.AK.aura(ctx, ctx.spec.Aura or "feathers")
		end,
	}

	---------------------------------------------------------------------
	-- THE LOOK IN THE ULT: the rim of light round the wings (a Highlight on
	-- his HawksWings), and now and then a feather drifting loose
	---------------------------------------------------------------------
	function HU.rim(char, rig, on)
		local h = HU.rims[char]
		if not on then
			if h then
				h:Destroy()
				HU.rims[char] = nil
			end
			return nil
		end
		if h and h.Parent and h.Adornee == rig.model then
			return h
		end
		if h then
			h:Destroy()
		end
		local R = W.UltRim or {}
		h = Instance.new("Highlight")
		h.Name = "HawksUltRim"
		h.OutlineColor = R.Color or HU.PALE
		h.FillColor = R.Color or HU.PALE
		h.OutlineTransparency = R.Outline or 0.4
		h.FillTransparency = HU.low() and 1 or (R.Fill or 0.9)
		h.DepthMode = Enum.HighlightDepthMode.Occluded
		h.Adornee = rig.model
		h.Parent = folder
		HU.rims[char] = h
		return h
	end
	function HU.watch()
		local cam = workspace.CurrentCamera
		local me = Players.LocalPlayer
		local mine = me and me.Character
		local now = os.clock()
		for char, rig in HK.rigs do
			local root = char.Parent and char:FindFirstChild("HumanoidRootPart")
			local on = root ~= nil and rig.model ~= nil and rig.model.Parent ~= nil and HU.ult(char) and HU.alive(char)
			local cull = HU.low() and (W.UltRimLowCull or 80) or (W.UltRimCull or 300)
			if on and cam and char ~= mine and (cam.CFrame.Position - root.Position).Magnitude > cull then
				on = false
			end
			-- (your own: never over wings you've hidden or the camera's faded -
			-- round 86 review: an outline over the faded wings traced them
			-- right across your view)
			if on and char == mine and (me:GetAttribute("HideMyWings") == true or (rig.ltmOut or 0) > 0.3) then
				on = false
			end
			local h = HU.rim(char, rig, on)
			if h then
				h.Enabled = HU.dark[char] == nil and char:GetAttribute("Feathers") ~= 0
				-- busy feathers: one works loose and drifts down now and then
				if not HU.low() and now > (rig.ultShed or 0) and cam and (cam.CFrame.Position - root.Position).Magnitude < 90 and not HU.runs[char] then
					rig.ultShed = now + rand(0.9, 1.8)
					HK.shed(root.Position + UP * rand(0.5, 2.5) + root.CFrame.LookVector * -1.2, 1, 3)
				end
			end
		end
		for char, h in HU.rims do
			if not HK.rigs[char] then
				h:Destroy()
				HU.rims[char] = nil
			end
		end
	end
	task.spawn(function()
		while true do
			task.wait(0.25)
			local ok, err = pcall(HU.watch)
			if not ok and not HU.warned then
				HU.warned = true
				warn("[HawksUlt] " .. tostring(err))
			end
		end
	end)

	---------------------------------------------------------------------
	-- THE THOUSAND-FEATHER STORM
	---------------------------------------------------------------------
	local BEATS = { "break", "storm", "blades", "dive", "cut", "home", "fold" }
	-- the beats' times off the plan (seconds from the plan)
	function HU.times(B)
		local T = {}
		local rise = tonumber(B.Rise) or 0.5
		local brk = tonumber(B.Break) or 0.6
		T.crouch = math.clamp(tonumber(B.Crouch) or 0, 0, rise * 0.5)
		T.top = rise
		T.sun = math.clamp(tonumber(B.Sun) or 0, 0, brk * 0.85)
		T["break"] = rise + T.sun
		T.storm = rise + brk
		T.dive = T.storm + (tonumber(B.Storm) or 1.6)
		T.blades = T.dive - 0.16
		T.cut = T.dive + (tonumber(B.Dive) or 0.6)
		T.home = T.cut
		T.homeTime = tonumber(B.Home) or 0.8
		T.fold = T.home + T.homeTime
		T.stormTime = tonumber(B.Storm) or 1.6
		T.diveTime = tonumber(B.Dive) or 0.6
		return T
	end
	-- where a storm feather wants to be: on one of the funnel's three arms -
	-- helixes winding up it (wide at the top, tight at the bottom), going
	-- round together so the bands read from anywhere - each feather riding a
	-- little up and down its arm; the whole thing tightening on its eye
	HU.ARMS = 3
	function HU.funnel(run, f, ts)
		local R = run.R
		local k = 1 - 0.25 * math.clamp(ts / run.T.stormTime, 0, 1)
		local eye = run.eyeAt and math.clamp((run.now - run.eyeAt) / run.T.diveTime, 0, 1) or 0
		k *= 1 - 0.6 * eye
		local H = run.H * (1 - 0.45 * eye)
		local u = math.clamp(f.h0 + 0.08 * math.sin(f.ph + ts * f.fr), 0, 1)
		local a = f.arm * (math.pi * 2 / HU.ARMS) + u * 3.4 + f.jit + f.w * ts
		local r = R * k * f.r0 * (0.32 + 0.68 * u)
		return run.center + Vector3.new(math.cos(a) * r, H * u + 0.6, math.sin(a) * r)
	end

	-- the cutscene, from the plan, in his facing as VFX.Cinematic will frame it
	-- (his root now): low in front as he's thrown up; cut to under him,
	-- looking up at him against the sun; a punch in as the wings break; cut to
	-- going round the storm; behind his shoulder, his hand directing it; cut to
	-- by the one in the middle as he dives at the camera; held on the cut;
	-- cut to low behind him, looking up past him into the sun as every feather
	-- comes home (the eyes and look-ats kept where HU.sunBeat can find them)
	-- a camera eye pulled in short of anything between it and what it's on
	-- (and how much of the way was blocked: 0 clear .. 1)
	function HU.clear(eye, on)
		local blocked = 0
		pcall(function()
			local gap = eye - on
			if gap.Magnitude > 0.5 then
				rayParams.FilterDescendantsInstances = characterList()
				local hit = workspace:Raycast(on, gap, rayParams)
				if hit then
					blocked = 1 - hit.Distance / gap.Magnitude
					eye = on + gap.Unit * math.max(hit.Distance - 0.8, math.min(1, hit.Distance * 0.5))
				end
			end
		end)
		return eye, blocked
	end
	function HU.stormShots(run)
		local root = run.root
		local look = HU.flat(root.CFrame.LookVector)
		local basis = CFrame.lookAt(root.Position, root.Position + look)
		run.basis = basis
		local function S(eye, at, on)
			eye = HU.clear(eye, on or (typeof(at) == "Vector3" and at) or run.from)
			return { basis:PointToObjectSpace(eye), at == "root" and "root" or basis:PointToObjectSpace(at) }, eye
		end
		local T = run.T
		local from, top, center, d = run.from, run.top, run.center, run.d
		local u = HU.flat(center - from, d)
		local side = u:Cross(UP)
		local right = d:Cross(UP)
		local shots = {}
		-- 1: the launch
		table.insert(shots, { T = T.top, Fov = { 60, 72 }, Style = Enum.EasingStyle.Quad, From = (S(from + d * 9 + right * 3.5 - UP * 1.6, from + UP * 2)), To = (S(from + d * 12 + right * 5 + UP * 16, "root", from)) })
		-- 2: against the sun - the real sun behind him if it's anywhere near,
		-- else straight out past him (the disc is HU.sun's)
		local view = (d * math.cos(math.rad(24)) - UP * math.sin(math.rad(24))).Unit
		local sun = IceKit.sun()
		if typeof(sun) == "Vector3" and sun.Y > 0.17 and sun.Y < 0.7 and HU.flat(sun):Dot(-d) > 0.5 then
			view = -sun.Unit
		end
		local sunAt = top + UP * 1.2
		local e1, e2 = top + view * 34, top + view * 29
		local f2, eye2 = S(e1, sunAt, top)
		table.insert(shots, { T = math.max(T["break"] - T.top, 0.05), Cut = true, CutGain = 0.5, Fov = { 64, 58 }, From = f2, To = (S(e2, sunAt, top)) })
		run.sunView = { eye = eye2, at = sunAt, size = 19 }
		-- 3: the break: a punch in
		table.insert(shots, { T = math.max(T.storm - T["break"], 0.05), Quiet = true, Fov = { 58, 48 }, Style = Enum.EasingStyle.Quad, From = (S(e2, sunAt, top)), To = (S(top + view * 21, sunAt, top)) })
		-- 4: round the storm
		local Ro = run.R + 16
		local a0 = -u * 0.5 + side * 0.87
		local a1 = (-u * 0.94 + side * 0.34).Unit
		local mid = center + UP * 7
		table.insert(shots, { T = 1.0, Cut = true, Fov = { 78, 82 }, From = (S(center + a0 * Ro + UP * 9, mid, mid)), To = (S(center + a1 * Ro + UP * 14, mid, mid)) })
		-- 5: behind his shoulder, his hand on it (round 86 review: aimed
		-- between him and the heart of the funnel - nearer him - so he's high
		-- in the frame, head and all, and the storm below him: the hand and
		-- the swords forming in shot, not cropped off the top)
		local function between(eye, h)
			return eye + ((top - eye).Unit * 1.6 + ((center + UP * h) - eye).Unit).Unit * 20
		end
		local e5a, e5b = top - u * 9 + UP * 2.4 + side * 3.6, top - u * 8.2 + UP * 2 + side * 3.2
		table.insert(shots, { T = math.max(T.dive - T.storm - 1.0, 0.05), Cut = true, Fov = { 60, 56 },
			From = (S(e5a, between(e5a, 9), top)), To = (S(e5b, between(e5b, 7), top)) })
		HU.diveShots(run, shots)
		return shots
	end
	-- the dive's three (again when the server says where it really went)
	function HU.diveShots(run, shots)
		local T = run.T
		local basis = run.basis
		local goal = run.goal or (run.center + UP * 3)
		local fall = goal - run.top
		local dFlat = HU.flat(fall, run.d)
		local side = dFlat:Cross(UP)
		local land = run.land or (goal + run.d * 4)
		-- (round 86 review) the climax's eyes kept out of the buildings: each
		-- pulled in short of a wall between it and what it's on (as the
		-- storm's are), and filmed from whichever side of the street is more
		-- open - the cut from the other side, the homecoming from in front
		-- or off to either side of it
		local function S(eye, at, on)
			eye = HU.clear(eye, on or (typeof(at) == "Vector3" and at) or goal + UP * 2)
			return { basis:PointToObjectSpace(eye), at == "root" and "root" or basis:PointToObjectSpace(at) }, eye
		end
		local function blocked(sd)
			local _, a = HU.clear(goal + sd * 17 + UP * 2 + dFlat * 13, goal + UP * 2)
			local _, b = HU.clear(goal + sd * 12 + UP * 2.4 - dFlat * 2, goal + UP)
			return a + b
		end
		if run.diveSide == nil then
			run.diveSide = blocked(-side) + 0.25 < blocked(side) and -1 or 1
		end
		side *= run.diveSide
		local front, homeOn = run.d, land + UP * 1.5
		do
			local best = math.huge
			for _, turn in { 0, 40, -40, 80, -80 } do
				local dir = CFrame.Angles(0, math.rad(turn), 0):VectorToWorldSpace(run.d)
				local _, b = HU.clear(land + dir * 15 - UP * 2 + dir:Cross(UP) * 3.5, homeOn)
				if b + math.abs(turn) / 400 < best then
					best = b + math.abs(turn) / 400
					front = dir
				end
			end
		end
		local hside = front:Cross(UP)
		local first = run.diveShot or (#shots + 1)
		run.diveShot = first
		local s8a, homeEye = S(land + front * 15 - UP * 2 + hside * 3.5, land + UP * 1.5 - front, homeOn)
		local list = {
			-- 6: by the one in the middle, as he comes down at the camera
			{ T = T.diveTime, Cut = true, Fov = { 64, 58 }, From = (S(goal + side * 17 + UP * 2 + dFlat * 13, run.top, goal + UP * 2)), To = (S(goal + side * 15 + UP * 1.4 + dFlat * 11, "root", goal + UP * 2)) },
			-- 7: held on the cut (the impact frame's over it)
			{ T = 0.16, Quiet = true, Fov = { 52, 50 }, From = (S(goal + side * 12 + UP * 2.4 - dFlat * 2, goal + UP)), To = (S(goal + side * 11.5 + UP * 2.3 - dFlat * 2, goal + UP)) },
			-- 8: low in front of him, looking up at him against the sun, as every
			-- feather comes home past him into his back (the one he cut down
			-- behind him, off the line)
			{ T = T.homeTime + 0.35, Cut = true, CutGain = 0.45, Fov = { 48, 54 }, From = s8a, To = (S(land + front * 16.5 - UP * 1.9 + hside * 4, land + UP * 1.7 - front, homeOn)) },
		}
		run.homeView = { eye = homeEye, at = land + UP * 1.5 - front, land = land, size = 13 }
		for i, s in list do
			local old = shots[first + i - 1]
			if old then
				for k, v in s do
					old[k] = v
				end
			else
				shots[first + i - 1] = s
			end
		end
	end

	-- a run's beat, once (from its event, or the clock)
	function HU.fire(run, name, data)
		if run.dead or run.did[name] then
			return
		end
		run.did[name] = true
		-- (late or early: the beats after it follow it - the server's clock
		-- from here on; the cutscene's shots keep theirs)
		local now = os.clock() - run.t0
		local due = run.T[name]
		if due then
			local after = false
			for _, b in BEATS do
				if after then
					run.T[b] += now - due
				end
				after = after or b == name
			end
			run.T[name] = now
		end
		local fn = HU.beat[name]
		if fn then
			local ok, err = pcall(fn, run, data or {})
			if not ok then
				warn("[HawksStorm] " .. name .. ": " .. tostring(err))
			end
		end
	end
	HU.beat = {}

	function HU.stormStart(char, plan)
		local root = char:FindFirstChild("HumanoidRootPart")
		if not root then
			return nil
		end
		local old = HU.runs[char]
		if old then
			HU.stop(old, "again")
		end
		local spec = Config.FindAbilityById("ThousandFeathers") or {}
		local show = spec.Show or {}
		local run = {
			char = char, root = root, plan = plan, t0 = os.clock(), now = 0, did = {}, dead = false,
			T = HU.times(type(plan.Beats) == "table" and plan.Beats or {}),
			from = plan.From, top = plan.Top, center = plan.Center, R = math.clamp(tonumber(plan.Radius) or 24, 4, 60), H = 22,
			target = typeof(plan.Target) == "Instance" and plan.Target or nil,
			feathers = {}, list = {}, cfs = {}, anchors = {}, ribbons = nil, victims = {}, landed = {}, pending = {},
			mine = HU.mine(char), low = HU.low(), show = show,
		}
		run.d = HU.flat(plan.Center - plan.From, HU.flat(root.CFrame.LookVector))
		local tr = run.target and run.target:FindFirstChild("HumanoidRootPart")
		run.goal = tr and tr.Position or nil
		HU.runs[char] = run
		-- his cutscene (the caster), a short cut for anyone close
		local title = spec.Name or "THOUSAND-FEATHER STORM"
		if run.mine then
			SHOTS.FeatherStorm = HU.stormShots(run)
			run.shots = SHOTS.FeatherStorm
			cinematicFor(char, "FeatherStorm", true, title, HU.LIT)
			run.cine = VFX.InOwnCinematic()
		else
			cinematicFor(char, "FeatherStorm", false, title, HU.LIT)
		end
		HU.noBulk, HU.bulkFails = false, 0 -- (a new storm tries BulkMoveTo again)
		-- the crouch: the wings raised high, the clip's crouch, the air drawn in
		VFX.Motion(char, "HawksStormRise")
		HK.setWing(char, "FlapUp", run.T.crouch + 0.04, 30)
		VFX.PlaySound("StormRiser", root.Position, 1)
		-- (round 86 review) a breath before the break: the riser's cut off
		-- (Config.Sounds.StormRiser) and the music ducks out under the gap,
		-- swelling back with the break
		task.delay(math.max(run.T["break"] - 0.2, 0), function()
			if not run.dead and not run.did["break"] and VFX.Hooks.DuckMusic and (run.mine or nearCamera(run.top, 200)) then
				VFX.Hooks.DuckMusic(0.12, 0.06, 0.16, 1.4)
			end
		end)
		local g = groundPoint(root.Position)
		shockDisc(g + UP * 0.3, UP, 26, 6, math.max(run.T.crouch, 0.08), Color3.fromRGB(240, 230, 220))
		task.delay(run.T.crouch, function()
			if not run.dead then
				HU.launch(run)
			end
		end)
		task.delay(run.T.top, function()
			if not run.dead then
				HU.atTop(run)
			end
		end)
		run.conn = RunService.RenderStepped:Connect(function(dt)
			local ok, err = pcall(HU.frame, run, math.min(dt, 0.1))
			if not ok then
				HU.stop(run, "error")
				warn("[HawksStorm] " .. tostring(err))
			end
		end)
		return run
	end

	-- the downstroke off the street: he's thrown 40 up; the street takes it
	function HU.launch(run)
		local char, root = run.char, run.root
		HK.setWing(char, "FlapDown", 0.14, 46)
		task.delay(0.14, function()
			if not run.dead then
				HK.setWing(char, "Spread", math.max(run.T.top - run.T.crouch - 0.24, 0.05), 18)
			end
		end)
		local g = groundPoint(run.from)
		if (run.from - g).Magnitude < 6 then
			shockDisc(g + UP * 0.3, UP, 4, 34, 0.4, Color3.fromRGB(240, 230, 220))
			billboardRing(g + UP * 0.6, 3, 22, Color3.new(1, 1, 1), 5, 0.3)
			dustPuffs(g, 1.5, HU.n(12), HK.DUST, 1.1, true)
			rocks(g, 0.8, HU.n(6))
		end
		-- loose feathers spiralling up after him
		for i = 1, HU.n(24) do
			local p0 = run.from + Vector3.new(rand(-2, 2), rand(0, 2), rand(-2, 2))
			local f = HK.feather(CFrame.new(p0) * CFrame.Angles(rand(0, 6.28), rand(0, 6.28), 0), rand(0.7, 1.1), i % 4 == 0 and "red" or nil)
			local up = rand(14, 30)
			local a = rand(0, 6.28)
			local to = run.from + Vector3.new(math.cos(a) * rand(3, 7), up, math.sin(a) * rand(3, 7))
			tween(f, rand(0.5, 0.8), { CFrame = HU.along(to, to - p0, rand(0, 6)) }, Enum.EasingStyle.Quart, Enum.EasingDirection.Out)
			tween(f, 1.2, { CFrame = CFrame.new(to + Vector3.new(rand(-2, 2), -6, rand(-2, 2))) * CFrame.Angles(rand(0, 6.28), rand(0, 6.28), 0), Transparency = 1 }, Enum.EasingStyle.Sine, Enum.EasingDirection.In, 0.7)
			cleanup(f, 2)
		end
		streaks(run.from - UP * 1.5, -UP, HU.n(10), 2.5, 9, 16, WIND, 0.3)
		VFX.PlaySound("StormLaunch", run.from, 1)
		VFX.ShakeAt(run.from, 1.6, 90, 0.25)
		if run.mine then
			VFX.Hooks.SpeedLines(0.4)
		end
	end

	-- hung at the top against the sun, every feather still on him
	function HU.atTop(run)
		local char = run.char
		VFX.Pose(char, "HawksSun", run.T.sun + 0.08)
		HK.setWing(char, "Max", run.T.sun + 0.12, 20)
		if run.T.sun > 0.05 then
			VFX.SpeechBubble(char, "Every last feather!", 1.4)
		end
		if run.mine and run.cine and VFX.InOwnCinematic() and run.sunView then
			HU.sunBeat(run, run.sunView)
		end
	end
	-- the caster's shot into the sun: him black with a fiery edge, the sun
	-- behind him, the warm grade, the flare
	function HU.sunBeat(run, view)
		HU.sunOff(run, 0)
		HU.silhouette(run.char, true, 0.06)
		run.sun = HU.sun(view.at, view.eye, view.size or 15)
		HU.grade(true)
		run.flare = run.sun and HU.flare(run.sun.part)
	end
	function HU.sunOff(run, fade)
		if run.sun then
			run.sun.kill(fade)
			run.sun = nil
		end
		if run.flare then
			run.flare.gui:Destroy()
			run.flare = nil
		end
		if HU.dark[run.char] then
			HU.silhouette(run.char, false, fade)
			HU.grade(false, fade)
		end
	end

	-- THE BREAK: every feather off him at once - his real wing feathers torn
	-- off (cloned where they are, then away), a cloud of them out of his back
	HU.beat["break"] = function(run)
		local char, root = run.char, run.root
		HU.sunOff(run, 0.05)
		VFX.Motion(char, "HawksStormBreak")
		task.delay(0.42, function()
			if not run.dead then
				VFX.Pose(char, "HawksConduct", math.max(run.T.dive - run.T["break"] - 0.42, 0.2))
			end
		end)
		local at = typeof(run.top) == "Vector3" and run.top or root.Position
		local back = root.CFrame * CFrame.new(0, 1.3, 0.9)
		-- the wing's own feathers (round 86 review: every other one on a
		-- low-end machine; and each one gone from the wing the moment its
		-- copy's torn off - hawks_moves' HK.leave where it's there, which
		-- keeps the count from showing it again for a moment)
		local rig = HK.rigs[char]
		local clones, seen = 0, 0
		for side, s in rig and rig.sides or {} do
			for slot, fe in s.feathers do
				if fe.part.Parent and fe.t < 0.98 then
					seen += 1
					local ok, c = false, nil
					if not (run.low and seen % 2 == 0) then
						ok, c = pcall(function()
							return fe.part:Clone()
						end)
					end
					if HK.leave then
						HK.leave(char, side, slot, 2)
					else
						fe.tTo = 1
					end
					if ok and c then
						local hinge = c:FindFirstChild("FeatherHinge")
						if hinge then
							hinge:Destroy()
						end
						for _, p in c:GetDescendants() do
							if p:IsA("BasePart") then
								p.Transparency = 0
								p.LocalTransparencyModifier = 0
							end
						end
						c.Name = "HawksTornFeather"
						c.Transparency = 0
						c.LocalTransparencyModifier = 0
						c.Anchored = true
						c.CFrame = fe.part.CFrame
						c.Parent = folder
						clones += 1
						table.insert(run.feathers, HU.newFeather(run, c, fe.part.CFrame.Position, side, slot, true))
					end
				end
			end
		end
		-- and the cloud out of his back
		local slots = W.Hide or { "C10" }
		for i = 1, HU.n(run.show.Parts or 150) do
			local side = i % 2 == 1 and 1 or -1
			local slot = slots[rng:NextInteger(1, #slots)]
			local cf = HK.slotCF(char, side, slot)
			local p = HU.take(i % 5 == 0 and HU.LIT or (i % 7 == 0 and HU.DEEP or HU.RED))
			local f = HU.newFeather(run, p, cf.Position + Vector3.new(rand(-0.5, 0.5), rand(-0.6, 0.6), rand(-0.5, 0.5)), side, slot, false)
			if i % 3 == 0 then
				HU.streak(p, HU.LIT, 0.22, 0.12)
			end
			table.insert(run.feathers, f)
		end
		run.clones = clones
		run.burstAt = run.now
		HU.shards(back * CFrame.Angles(0, math.pi, 0), HU.n(run.show.Burst or 360), 90, { Spread = 180, Size = 0.75 })
		billboardRing(at, 2, 34, Color3.new(1, 1, 1), 6, 0.25)
		billboardRing(at, 2, 22, HU.LIT, 4, 0.35)
		VFX.PlaySound("StormBreak", at, 1)
		VFX.ShakeAt(at, 1.8, 140, 0.3)
		if run.mine or nearCamera(at, 120) then
			VFX.Hooks.Flash(Color3.new(1, 1, 1), 0.06)
		end
	end
	-- a storm feather: where it is, its own way round the funnel, its slot home
	function HU.newFeather(run, part, at, side, slot, big)
		local out = (at - run.root.Position)
		out = (out.Magnitude > 0.1 and out.Unit or UP) + run.root.CFrame.LookVector * -0.6 + UP * rand(-0.2, 0.6)
		return {
			part = part, p = at, last = at, big = big, side = side, slot = slot,
			vel = (out.Magnitude > 0.01 and out.Unit or UP) * rand(35, 85) + Vector3.new(rand(-12, 12), rand(-6, 14), rand(-12, 12)),
			arm = rng:NextInteger(0, HU.ARMS - 1), h0 = rand(0, 1), jit = rand(-0.28, 0.28), w = rand(3.6, 4.3),
			ph = rand(0, 6.28), fr = rand(1.5, 3.5), r0 = rand(0.84, 1.06), spin = rand(0, 6.28), spinW = rand(-14, 14),
			chase = rand(5, 9),
		}
	end

	-- THE STORM: the funnel comes down on them
	HU.beat.storm = function(run, data)
		local char = run.char
		if typeof(data.Center) == "Vector3" then
			run.center = data.Center
		end
		if tonumber(data.Radius) then
			run.R = math.clamp(tonumber(data.Radius), 4, 60)
		end
		for _, v in (type(data.Victims) == "table" and data.Victims or {}) do
			if typeof(v) == "Instance" then
				table.insert(run.victims, v)
			end
		end
		if #run.victims == 0 and run.target then
			table.insert(run.victims, run.target)
		end
		run.stormAt = run.now
		local c = run.center
		local g = groundPoint(c + UP * 3)
		-- the shard emitters going round it
		for i = 1, HU.n(run.show.Swirl or 8) do
			local holder = newPart(Vector3.one * 0.2, CFrame.new(c), HU.RED)
			holder.Name = "HawksSwirl"
			holder.Transparency = 1
			local pe = HU.emitter(holder, { Rate = HU.n(run.show.Rate or 70), Speed0 = 10, Speed1 = 26, Spread = 28, Drag = 2.5, Life0 = 0.45, Life1 = 0.8, Size = 1.1, Squash = 1.6, Accel = Vector3.new(0, -4, 0) })
			table.insert(run.anchors, { part = holder, pe = pe, arm = (i - 1) % HU.ARMS, h0 = ((i - 1) // HU.ARMS + 0.5) / math.ceil(8 / HU.ARMS), jit = rand(-0.2, 0.2), w = 3.95, ph = rand(0, 6.28), fr = rand(1, 2.2), r0 = rand(0.9, 1.02) })
		end
		-- the ribbons of wind
		local holder = newPart(Vector3.one * 0.2, CFrame.new(c), HU.RED)
		holder.Name = "HawksRibbons"
		holder.Transparency = 1
		run.ribbons = { holder = holder, list = {} }
		for i = 1, HU.n(run.show.Ribbons or 8) do
			local a0 = Instance.new("Attachment")
			a0.Parent = holder
			local a1 = Instance.new("Attachment")
			a1.Parent = holder
			local b = Instance.new("Beam")
			b.Name = "HawksRibbon"
			b.Attachment0, b.Attachment1 = a0, a1
			b.Color = CS(i % 2 == 0 and HU.PALE or Color3.fromRGB(255, 236, 226), HU.RED)
			b.Transparency = NS({ NK(0, 1), NK(0.25, 0.45), NK(0.7, 0.55), NK(1, 1) })
			b.Width0, b.Width1 = rand(0.8, 1.6), rand(0.2, 0.5)
			b.LightEmission = 0.5
			b.FaceCamera = true
			b.Segments = 14
			b.Parent = holder
			table.insert(run.ribbons.list, { a0 = a0, a1 = a1, beam = b, ang = i / 8 * math.pi * 2 + rand(-0.3, 0.3), w = rand(3.4, 5), h = (i - 0.5) / 8, span = rand(0.9, 1.4) })
		end
		for i = 1, HU.n(6) do
			local a = i / 6 * math.pi * 2
			dustPuffs(g + Vector3.new(math.cos(a), 0, math.sin(a)) * run.R * 0.45, 0.8, 1, HK.DUST, 1.2, false)
		end
		billboardRing(g + UP * 1.5, run.R * 2.4, run.R * 1.1, Color3.fromRGB(255, 205, 195), 5, 0.45)
		VFX.PlaySound("StormRoar", c + UP * 6, 1)
		VFX.ShakeAt(c, 1.4, 120, run.T.stormTime)
	end
	-- two swords out of the swirl, into his hands
	HU.beat.blades = function(run)
		local hands = {}
		for _, f in run.feathers do
			if not f.big and not f.home and #hands < 10 then
				f.toHand = (#hands % 2 == 0) and "R" or "L"
				table.insert(hands, f)
			end
		end
		task.delay(0.14, function()
			if not run.dead and run.char.Parent then
				HK.blades(run.char, true)
				for _, f in hands do
					f.gone = true
				end
			end
		end)
	end
	-- THE DIVE through the eye of it
	HU.beat.dive = function(run, data)
		local char, root = run.char, run.root
		if typeof(data.To) == "Vector3" then
			run.goal = data.To
		end
		if typeof(data.Land) == "Vector3" then
			run.land = data.Land
		end
		if run.shots then
			HU.diveShots(run, run.shots)
		end
		run.eyeAt = run.now
		VFX.Motion(char, "HawksStormDive")
		HK.setWing(char, "Tuck", run.T.diveTime + 0.05, 26)
		HU.streak(root, HU.LIT, 1.4, 0.25, run.T.diveTime + 0.05)
		for i = 1, 3 do
			task.delay((i - 1) * run.T.diveTime / 3, function()
				if not run.dead and root.Parent then
					afterimage(char, Color3.fromRGB(230, 60, 60), 0.25)
				end
			end)
		end
		VFX.PlaySound("StormDive", run.goal or run.center, 1)
		if run.mine then
			VFX.Hooks.SpeedLines(run.T.diveTime)
		end
	end
	-- THE LAST CUT: the X through the one in the middle, the storm let go
	HU.beat.cut = function(run, data)
		local char, root = run.char, run.root
		local at = typeof(data.Pos) == "Vector3" and data.Pos or run.goal or (run.center + UP * 3)
		run.cutPos = at
		local look = HU.flat((run.goal or at) - run.top, run.d)
		local cf = CFrame.lookAt(at, at + look)
		for _, roll in { 45, -45 } do
			local s = newPart(Vector3.new(14, 0.5, 0.06), cf * CFrame.Angles(0, 0, math.rad(roll)), Color3.fromRGB(255, 70, 60), Enum.Material.Neon)
			s.Name = "HawksXCut"
			tween(s, 0.12, { Size = Vector3.new(18, 0.7, 0.06) }, Enum.EasingStyle.Quad, Enum.EasingDirection.Out)
			tween(s, 0.35, { Transparency = 1, Size = Vector3.new(20, 0.04, 0.06) }, Enum.EasingStyle.Quad, Enum.EasingDirection.In, 0.12)
			cleanup(s, 0.5)
			local core = newPart(Vector3.new(15, 0.12, 0.08), cf * CFrame.Angles(0, 0, math.rad(roll)), Color3.new(1, 1, 1), Enum.Material.Neon)
			core.Name = "HawksXCut"
			tween(core, 0.25, { Transparency = 1 }, Enum.EasingStyle.Quad, Enum.EasingDirection.In, 0.08)
			cleanup(core, 0.36)
		end
		-- the street under it scored with the same X
		local g = groundPoint(at)
		if (at - g).Magnitude < 8 then
			for _, roll in { 45, -45 } do
				local scar = newPart(Vector3.new(0.35, 0.06, 9), CFrame.new(g + UP * 0.04) * CFrame.Angles(0, math.atan2(-look.X, -look.Z) + math.rad(roll), 0), Color3.fromRGB(40, 24, 24), Enum.Material.SmoothPlastic)
				scar.Name = "HawksScar"
				tween(scar, 1, { Transparency = 1 }, nil, nil, 2)
				cleanup(scar, 3.1)
			end
			shockDisc(g + UP * 0.3, UP, 4, 36, 0.4, Color3.fromRGB(230, 216, 204))
			dustPuffs(g, 1.6, HU.n(12), HK.DUST, 1.2, true)
			rocks(g, 1, HU.n(8))
		end
		-- (round 86 review: in his cutscene the burst goes away from the lens)
		local cam = run.mine and run.cine and VFX.InOwnCinematic() and workspace.CurrentCamera
		local away = cam and HU.flat(at - cam.CFrame.Position)
		HU.shards(away and CFrame.lookAt(at, at + away + UP * 0.3) or cf, HU.n(160), 70, { Spread = away and 75 or 180 })
		HK.flecks(at, HU.n(14), 2.5)
		billboardRing(at, 2, 26, Color3.new(1, 1, 1), 6, 0.22)
		-- the storm let go: everything left in it thrown off the cut
		run.blastAt = run.now
		for _, f in run.feathers do
			if not f.gone then
				local away = f.p - at
				away = (away.Magnitude > 0.1 and away.Unit or UP) + UP * rand(0, 0.5)
				f.vel = away.Unit * rand(30, 70)
			end
		end
		for _, a in run.anchors do
			a.pe.Enabled = false
		end
		if run.ribbons then
			for _, r in run.ribbons.list do
				tween(r.beam, 0.15, { Width0 = 0, Width1 = 0 })
			end
		end
		VFX.PlaySound("StormCut", at, 1)
		VFX.ShakeAt(at, 2.6, 130, 0.35)
		if run.mine or nearCamera(at, 90) then
			local victim = typeof(data.Target) == "Instance" and data.Target or run.target
			HU.impactFrame(at, { char, victim })
		end
	end
	-- the red impact frame: black with a white X through the cut and red speed
	-- hatching; then the world red-and-black, the two of them cut out in ink
	function HU.impactFrame(at, bodies)
		local me = Players.LocalPlayer
		local pg = me and me:FindFirstChildOfClass("PlayerGui")
		local cam = workspace.CurrentCamera
		local cx, cy = 0.5, 0.45
		if cam then
			local ok, p = pcall(function()
				return cam:WorldToViewportPoint(at)
			end)
			local vs = cam.ViewportSize
			if ok and typeof(p) == "Vector3" and p.Z > 0 and vs.X > 10 then
				cx, cy = math.clamp(p.X / vs.X, 0.15, 0.85), math.clamp(p.Y / vs.Y, 0.15, 0.85)
			end
		end
		local aspect = 16 / 9
		pcall(function()
			aspect = cam.ViewportSize.X / math.max(cam.ViewportSize.Y, 1)
		end)
		if pg then
			local sg = Instance.new("ScreenGui")
			sg.Name = "HawksImpactFrame"
			sg.IgnoreGuiInset = true
			sg.ResetOnSpawn = false
			sg.DisplayOrder = 50
			local bg = Instance.new("Frame")
			bg.Size = UDim2.fromScale(1, 1)
			bg.BackgroundColor3 = Color3.new(0, 0, 0)
			bg.BorderSizePixel = 0
			bg.Parent = sg
			local function bar(angle, from, len, thick, color)
				local f = Instance.new("Frame")
				f.AnchorPoint = Vector2.new(0.5, 0.5)
				f.BackgroundColor3 = color
				f.BorderSizePixel = 0
				local mid = from + len / 2
				f.Position = UDim2.fromScale(cx + math.cos(angle) * mid, cy + math.sin(angle) * mid * aspect)
				f.Size = UDim2.new(len, 0, 0, thick)
				f.Rotation = math.deg(angle)
				f.Parent = bg
			end
			for _ = 1, 28 do
				bar(rand(0, math.pi * 2), rand(0.1, 0.3), rand(0.2, 0.7), rand(1, 4), Color3.fromRGB(200, 20, 30))
			end
			for _, a in { math.rad(45), math.rad(135), math.rad(225), math.rad(315) } do
				bar(a, 0, 0.9, 16, Color3.new(1, 1, 1))
				bar(a, 0, 0.5, 34, Color3.new(1, 1, 1))
			end
			sg.Parent = pg
			task.delay(0.05, function()
				sg:Destroy()
			end)
		end
		local cc = Lighting:FindFirstChild("HawksImpact")
		if not cc then
			cc = Instance.new("ColorCorrectionEffect")
			cc.Name = "HawksImpact"
			cc.Parent = Lighting
		end
		HU.impactToken = (HU.impactToken or 0) + 1
		local token = HU.impactToken
		local marks = {}
		task.delay(0.05, function()
			if HU.impactToken ~= token then
				return
			end
			cc.Enabled = true
			cc.Saturation, cc.Contrast, cc.Brightness, cc.TintColor = -1, 2.4, 0.12, Color3.fromRGB(255, 80, 70)
			for _, b in bodies do
				if typeof(b) == "Instance" and b.Parent then
					local rim = HU.rims[b]
					if rim then
						rim.Enabled = false -- (never under the cut-out; HU.watch puts it back)
					end
					local h = Instance.new("Highlight")
					h.Name = "HawksCutout"
					h.FillColor = Color3.new(0, 0, 0)
					h.FillTransparency = 0
					h.OutlineTransparency = 1
					h.DepthMode = Enum.HighlightDepthMode.Occluded
					h.Adornee = b
					h.Parent = folder
					table.insert(marks, h)
				end
			end
		end)
		task.delay(0.15, function()
			for _, h in marks do
				h:Destroy()
			end
			if HU.impactToken ~= token then
				return
			end
			tween(cc, 0.12, { Saturation = 0, Contrast = 0, Brightness = 0, TintColor = Color3.new(1, 1, 1) })
			task.delay(0.13, function()
				if HU.impactToken == token then
					cc:Destroy()
				end
			end)
		end)
		VFX.Hooks.Flash(Color3.new(1, 1, 1), 0.12)
	end
	-- (round 86 review) when each slot shows again on the way home: the
	-- server's steps (HomeLead of Home with none, then HomeSteps to the end,
	-- never over FeathersMax) run through HK.counts - a list in the order
	-- they show { side, slot, at } and [side .. slot] = at
	function HU.homeSlots(char, had, time)
		local spec = Config.FindAbilityById("ThousandFeathers") or {}
		local steps = math.max(math.floor(tonumber(spec.HomeSteps) or 1), 1)
		local lead = math.clamp(tonumber(spec.HomeLead) or 0, 0, 0.9)
		local cap = tonumber(char:GetAttribute("FeathersMax")) or had
		local hide = W.Hide or {}
		local order, when = {}, {}
		for i = 1, steps do
			local at = time * (lead + (1 - lead) * i / steps)
			local right, left, over = HK.counts(math.min(math.floor(had * i / steps + 0.5), cap))
			for _, side in { 1, -1 } do
				local n = side == 1 and right or left
				for j = #hide, math.max(#hide - n + 1, 1), -1 do
					local key = side .. hide[j]
					if not when[key] then
						when[key] = at
						table.insert(order, { side = side, slot = hide[j], at = at })
					end
				end
				for o = 1, over do
					local key = side .. "O" .. o
					if not when[key] then
						when[key] = at
						table.insert(order, { side = side, slot = "O" .. o, at = at })
					end
				end
			end
		end
		return order, when
	end
	-- a feather lands in its slot: there at once, with a little kick (a
	-- slot the count shows again; one it doesn't is left to the count)
	function HU.landIn(char, side, slot)
		local rig = HK.rigs[char]
		local fe = rig and rig.sides[side] and rig.sides[side].feathers[slot]
		if not (fe and fe.shown) then
			return false
		end
		fe.goAt, fe.away, fe.waitHome = nil, nil, nil -- (hawks_moves' timers, if they're in)
		fe.slide, fe.slideTo, fe.tTo, fe.t = 0, 0, 0, 0
		for _, p in fe.parts do
			p.Transparency = 0
		end
		fe.ext, fe.extTo = 0.8, 0
		return true
	end
	-- the wing as the count has it (a slot shown but still hidden - its
	-- feather never came, or the storm was called off - in at once)
	function HU.resync(char)
		local rig = HK.rigs[char]
		for side, s in rig and rig.sides or {} do
			for slot, fe in s.feathers do
				if fe.shown and fe.tTo > 0.5 then
					HU.landIn(char, side, slot)
				end
			end
		end
	end
	-- (with hawks_moves' kit: a slot the count shows again during the storm's
	-- homecoming waits, hidden, for the storm's own feather - HU.frame lands
	-- it - rather than growing back or taking a parked one)
	if HK.homeTo then
		local homeTo = HK.homeTo
		function HK.homeTo(char, side, slot, fe)
			local run = HU.runs[char]
			if run and run.homing and not run.dead then
				if run.landed[side .. slot] then
					HU.landIn(char, side, slot)
				else
					fe.slide, fe.slideTo, fe.tTo = 0, 0, 1
				end
				return "taken"
			end
			return homeTo(char, side, slot, fe)
		end
	end
	-- HOMECOMING: every feather streams back into the wings
	HU.beat.home = function(run, data)
		local char, root = run.char, run.root
		if typeof(data.Pos) == "Vector3" then
			run.land = data.Pos
		end
		run.homeAt = run.now
		run.homing = true
		HK.blades(char, false)
		VFX.Motion(char, "HawksHome")
		HK.setWing(char, "Spread", run.T.homeTime + 0.05, 9)
		local time = tonumber(data.Time) or run.T.homeTime
		-- (round 86 review) each lands in a slot on the very step the server
		-- shows that slot again (HU.homeSlots: the hide order backwards, the
		-- coverts first, the long primaries last); a torn-off wing feather
		-- goes back to its own slot, the cloud shares the rest out
		local order, when = HU.homeSlots(char, tonumber(data.Feathers) or 150, time)
		local k = 0
		for _, f in run.feathers do
			if not f.gone then
				local at = f.big and when[f.side .. f.slot]
				if not at and #order > 0 then
					k += 1
					local o = order[(k - 1) % #order + 1]
					f.side, f.slot, at = o.side, o.slot, o.at
				end
				at = (at or time) - rand(0, 0.04)
				local d = (HK.slotCF(char, f.side, f.slot).Position - f.p).Magnitude
				local fly = math.clamp(d / 70, 0.22, 0.42) + rand(0, 0.06)
				f.home = run.now + math.max(at - fly, 0.06)
				f.homeTime = math.max(run.now + at - f.home, 0.12)
				f.bend = UP * rand(3, 10) + Vector3.new(rand(-6, 6), 0, rand(-6, 6))
				if f.part.Name == "HawksStormFeather" and not f.trail and rng:NextInteger(1, 3) == 1 then
					f.trail = HU.streak(f.part, HU.PALE, 0.22, 0.18)
				end
			end
		end
		VFX.PlaySound("StormHome", root.Position, 1)
		-- the caster: low behind him, the sun past him once more
		task.delay(0.16, function()
			if not run.dead and run.mine and run.cine and VFX.InOwnCinematic() and run.homeView then
				HU.sunBeat(run, run.homeView)
			end
		end)
	end
	-- whole again: thrown open against the sun one last time (the cutscene
	-- ends on it), then the double beat that folds them
	-- (round 86 review: his cutscene ends 0.51 s into this - on the open
	-- wings; the double beat after the cut, the sun's grade gone with it)
	HU.beat.fold = function(run)
		local char = run.char
		HU.resync(char) -- (every slot the count shows is in by now)
		HK.setWing(char, "Max", 0.52, 22)
		local function wing(t, state, time)
			task.delay(t, function()
				-- (the beats outlive the run's "done": he only has to be here)
				if char.Parent and HU.alive(char) then
					HK.setWing(char, state, time, state == "Rest" and 10 or 40)
				end
			end)
		end
		wing(0.52, "FlapDown", 0.12)
		wing(0.64, "FlapUp", 0.1)
		wing(0.74, "FlapDown", 0.14)
		wing(0.88, "Rest", 0.4)
		task.delay(0.52, function()
			if char.Parent and HU.alive(char) then
				VFX.PlaySound("StormFold", run.root.Position, 1)
			end
		end)
		task.delay(0.47, function()
			HU.sunOff(run, 0.06)
		end)
	end

	-- every frame: the beats due on the clock, the feathers, the swirl, the
	-- ribbons, the shredding - and whether it's still on at all
	function HU.frame(run, dt)
		if run.dead then
			return
		end
		local char = run.char
		run.now = os.clock() - run.t0
		local now = run.now
		local T = run.T
		-- (over: he's down, someone else, gone - or the server let it go early)
		if not HU.alive(char) or char:GetAttribute("Quirk") ~= "FierceWings" then
			HU.stop(run, "dead")
			return
		end
		if char:GetAttribute("HawksStorm") == true then
			run.sawStorm = true
		elseif run.sawStorm and not run.did.home then
			HU.stop(run, "server")
			return
		end
		-- (a beat whose event is late: the clock's, a moment after)
		for _, name in BEATS do
			if not run.did[name] and now >= T[name] + ((name == "blades" or name == "fold") and 0 or 0.25) then
				HU.fire(run, name)
			end
		end
		-- the feathers
		local list, cfs = run.list, run.cfs
		table.clear(list)
		table.clear(cfs)
		local alive = 0
		-- (his cutscene's camera goes in among them: the ones right on it fade)
		local camAt = run.cine and VFX.InOwnCinematic() and workspace.CurrentCamera and workspace.CurrentCamera.CFrame.Position
		for _, f in run.feathers do
			if f.gone then
				if f.part then
					if f.part.Name == "HawksStormFeather" then
						HU.give(f.part)
					else
						f.part:Destroy()
					end
					f.part = nil
				end
				continue
			end
			alive += 1
			local p = f.p
			if f.home and now >= f.home then
				-- home: an arc to his wing, into its slot
				f.from = f.from or p
				local u = math.clamp((now - f.home) / f.homeTime, 0, 1)
				local e = u * u * (3 - 2 * u)
				local to = HK.slotCF(char, f.side, f.slot).Position
				local mid = (f.from + to) / 2 + f.bend
				p = (1 - e) ^ 2 * f.from + 2 * (1 - e) * e * mid + e * e * to
				-- (round 90) the homecoming's spiral round him for the last half
				-- of it (HK.spiralAt): the two wings' feathers wrapping round him
				-- opposite ways into their slots - every feather of the storm
				local hroot = HK.spiralAt and u > 0.5 and not IceKit.lowEnd() and char:FindFirstChild("HumanoidRootPart")
				if hroot then
					if not f.sp then
						local a0, r0, y0 = HK.spiralEntry(hroot, p, f.side)
						f.sp = { a0, r0, y0, f.side > 0 and 1 or -1 }
					end
					local u2 = (u - 0.5) / 0.5
					local w = math.clamp(u2 / 0.3, 0, 1)
					p = p:Lerp(HK.spiralAt(hroot, f.sp[1], f.sp[2], f.sp[3], f.sp[4], u2, to), w * w * (3 - 2 * w))
				end
				if u >= 1 then
					f.gone = true
					-- (in its slot, on the step that shows it: it clicks in)
					run.landed[f.side .. f.slot] = true
					if not HU.landIn(char, f.side, f.slot) then
						table.insert(run.pending, { f.side, f.slot }) -- (a moment before the count: in when it shows)
					end
					if rng:NextInteger(1, 2) == 1 then
						VFX.PlaySound("StormClick", to, 0.8)
					end
				end
			elseif f.toHand and now >= T.blades then
				local to = handPos(char, f.toHand == "R") -- (R6 or R15: round 86 review)
				p += (to - p) * math.min(1, 18 * dt)
			elseif run.burstAt and now >= run.burstAt + 0.08 and not run.blastAt then
				-- ripped across to the storm and round its funnel (each chasing its
				-- place: they fly in on curves, a river of them across the sky)
				local ts = now - (run.stormAt or T.storm)
				local want = HU.funnel(run, f, ts)
				local k = math.min(f.chase * math.min(1.1 + math.max(now - run.burstAt, 0) * 3, 2.2), 30)
				p += (want - p) * math.min(1, k * dt)
			else
				-- thrown: out of his back at the break, off the cut at the end
				p += f.vel * dt
				f.vel *= math.exp(-(run.blastAt and 3.2 or 2.4) * dt)
				f.vel += Vector3.new(0, -9 * dt, 0)
			end
			local v = (p - f.last) / math.max(dt, 1e-3)
			f.last = f.p
			f.p = p
			-- (round 86 review: out to 13 studs - the dive's shot was cluttered)
			local fade = (camAt and not f.toHand) and math.clamp((13 - (p - camAt).Magnitude) / 6, 0, 1) or 0
			if fade ~= (f.fade or 0) then
				f.fade = fade
				f.part.Transparency = fade
				if f.big then
					for _, c in f.part:GetChildren() do
						if c:IsA("BasePart") then
							c.Transparency = fade
						end
					end
				end
			end
			f.spin += f.spinW * dt
			table.insert(list, f.part)
			table.insert(cfs, HU.along(p, v.Magnitude > 0.5 and v or (f.lastV or UP), f.spin))
			if v.Magnitude > 0.5 then
				f.lastV = v
			end
		end
		HU.move(list, cfs)
		-- (the ones home a moment before the count showed their slot: in now)
		for i = #run.pending, 1, -1 do
			local p = run.pending[i]
			if HU.landIn(char, p[1], p[2]) then
				table.remove(run.pending, i)
			end
		end
		-- the swirl's emitters and the ribbons round the funnel
		if run.stormAt and not run.blastAt then
			local ts = now - run.stormAt
			for _, a in run.anchors do
				local pos = HU.funnel(run, a, ts)
				local off = pos - run.center
				local tangent = Vector3.new(-off.Z, -0.12 * off.Magnitude, off.X)
				a.part.CFrame = CFrame.lookAt(pos, pos + tangent)
				-- (round 86 review: in his cutscene, none spraying shards right
				-- into the lens)
				local near = camAt and (pos - camAt).Magnitude < 12
				if near ~= (a.near or false) then
					a.near = near
					a.pe.Enabled = not near
				end
			end
			local rb = run.ribbons
			if rb then
				local R = run.R * (1 - 0.25 * math.clamp(ts / T.stormTime, 0, 1)) * (run.eyeAt and (1 - 0.5 * math.clamp((now - run.eyeAt) / T.diveTime, 0, 1)) or 1)
				for _, r in rb.list do
					local a = r.ang + r.w * ts
					local h = run.H * r.h
					local rr = R * (0.45 + 0.6 * r.h)
					local span = r.span
					local p0 = Vector3.new(math.cos(a) * rr, h, math.sin(a) * rr)
					local p1 = Vector3.new(math.cos(a + span) * rr, h + 2.5, math.sin(a + span) * rr)
					r.a0.CFrame = CFrame.fromMatrix(p0, Vector3.new(-math.sin(a), 0, math.cos(a)), UP)
					r.a1.CFrame = CFrame.fromMatrix(p1, Vector3.new(-math.sin(a + span), 0, math.cos(a + span)), UP)
					local c = 4 / 3 * math.tan(span / 4) * rr
					r.beam.CurveSize0, r.beam.CurveSize1 = c, c
				end
			end
			-- the ones caught in it, cut to pieces
			if now >= (run.shredAt or 0) and not run.did.dive then
				run.shredAt = now + (run.low and 0.22 or 0.12)
				for _, v in run.victims do
					local vr = v.Parent and v:FindFirstChild("HumanoidRootPart")
					if vr then
						local at = vr.Position + Vector3.new(rand(-0.6, 0.6), rand(-1.2, 1.2), rand(-0.6, 0.6))
						HU.slash(at, rand(2, 3.4), 0.12)
						HK.flecks(at, 2, 1.2)
						VFX.PlaySound("StormShred", at, 0.8)
						if rng:NextInteger(1, 3) == 1 then
							sparks(at, 0.3, HK.EDGE, HU.RED, 3)
						end
					end
				end
				-- a hiss of blades all round it
				local a = rand(0, 6.28)
				VFX.PlaySound("StormBlades", run.center + Vector3.new(math.cos(a) * run.R * 0.7, rand(2, 14), math.sin(a) * run.R * 0.7), 0.7)
			end
		end
		if run.flare then
			run.flare.step()
		end
		-- (the sun goes with his cutscene, never past it)
		if run.sun and run.did.home and not VFX.InOwnCinematic() then
			HU.sunOff(run, 0.06)
		end
		if (run.did.home and alive == 0 and now > T.fold + 0.55) or now > T.fold + 2.5 then
			HU.stop(run, "done")
		end
	end

	-- it's over (done, or called off): everything it made goes
	function HU.stop(run, why)
		if run.dead then
			return
		end
		run.dead = true
		if run.conn then
			run.conn:Disconnect()
			run.conn = nil
		end
		for _, f in run.feathers do
			if f.part then
				if f.part.Name == "HawksStormFeather" then
					HU.give(f.part)
				else
					f.part:Destroy()
				end
				f.part = nil
			end
		end
		table.clear(run.feathers)
		for _, a in run.anchors do
			a.part:Destroy()
		end
		table.clear(run.anchors)
		if run.ribbons then
			run.ribbons.holder:Destroy()
			run.ribbons = nil
		end
		HU.sunOff(run, 0.1)
		if HU.runs[run.char] == run then
			HU.runs[run.char] = nil
		end
		if why ~= "done" and why ~= "again" then
			-- (called off: his cutscene too)
			if run.mine and run.cine and VFX.InOwnCinematic() then
				VFX.CancelCinematic()
			end
			if run.char.Parent then
				HK.over[run.char] = nil
			end
		end
		-- (the wing as the count has it: nothing left hidden that it shows)
		if run.char.Parent then
			pcall(HU.resync, run.char)
		end
	end

	-- the events: the move itself (his press), the plan, and each beat
	function Effects.ThousandFeathers(char, data, isLocal)
		local root = charParts(char)
		if not root then
			return
		end
		if isLocal and typeof(data.Dir) == "Vector3" then
			face(root, data.Dir)
		end
		HK.setWing(char, "FlapUp", 0.3, 24)
	end
	function Effects.FeatherStormPlan(char, data)
		if not (type(data) == "table" and typeof(data.From) == "Vector3" and typeof(data.Top) == "Vector3" and typeof(data.Center) == "Vector3") then
			return
		end
		HU.stormStart(char, data)
	end
	for name, beat in { FeatherStormBreak = "break", FeatherStorm = "storm", FeatherStormDive = "dive", FeatherStormCut = "cut", FeatherStormHome = "home" } do
		Effects[name] = function(char, data)
			local run = HU.runs[char]
			if run then
				if beat == "dive" then
					HU.fire(run, "blades")
				elseif beat == "home" then
					HU.fire(run, "cut", {})
				end
				HU.fire(run, beat, type(data) == "table" and data or {})
			end
		end
	end

	---------------------------------------------------------------------
	-- ult 1: SCARLET RAIN - flung up off the wings in a fountain, gathered
	-- into a ring of blades turning over the spot, then down out of the sky
	-- one by one: stuck in the street (or in them); the ones that hit nobody
	-- fly home
	---------------------------------------------------------------------
	-- (round 86 review) a rain blade: bigger than a volley feather (it has to
	-- read from 30 studs), its point glowing, a thin streak behind it
	function HU.rainBlade(cf)
		local part = HK.feather(cf, 2.2, nil)
		for _, c in part:GetChildren() do
			if c:IsA("BasePart") then
				c.Material = Enum.Material.Neon
				c.Color = HU.EDGE
			end
		end
		return part
	end
	-- stuck in the street at p, come down along `dir`: the point and a third
	-- of the vane in, the rest standing out of it
	function HU.stuck(p, dir, len)
		local d = (typeof(dir) == "Vector3" and dir.Magnitude > 1e-3) and dir.Unit or -UP
		return HU.along(p - d * (len or 2.2) * 0.42, d)
	end
	HU.rainHits = setmetatable({}, { __mode = "k" }) -- [char] = { hit = { [i] = true }, t } (the server's word on the last volley)
	function Effects.ScarletRain(char, data, isLocal, ability)
		local root = charParts(char)
		if not root then
			return
		end
		if isLocal and typeof(data.Dir) == "Vector3" then
			face(root, data.Dir)
		end
		local spec = ability or Config.FindAbilityById("ScarletRain") or {}
		VFX.Motion(char, "HawksRainCall")
		HK.setWing(char, "Tuck", 0.12, 30)
		task.delay(0.12, function()
			HK.setWing(char, "Max", 0.38, 36)
		end)
		task.delay(0.5, function()
			HK.setWing(char, "Flare", 0.25, 24)
		end)
		VFX.PlaySound("RainCall", root.Position, 1)
		local aim = typeof(data.Pos) == "Vector3" and data.Pos or root.Position + root.CFrame.LookVector * 30
		local old = HU.clouds[char]
		if old and old.stop then
			old.stop()
		end
		-- (round 86 review) the ring low enough to be in a gameplay camera's
		-- view over the spot (RingHeight; the server's Height is its roof check)
		local cloud = { center = groundPoint(aim) + UP * (spec.RingHeight or 18), feathers = {}, t0 = os.clock() }
		HU.clouds[char] = cloud
		local n = HU.n(spec.Count or 16)
		task.delay(0.14, function()
			if not root.Parent or HU.clouds[char] ~= cloud then
				return
			end
			for i, s in HK.launchSlots(char, n) do
				if s.Flick then
					HK.flick(char, s.side, s.slot)
				end
				local from = HK.slotCF(char, s.side, s.slot)
				local part = HU.rainBlade(from)
				part.Transparency = 1
				local f = { part = part, from = from.Position, born = os.clock() + i * 0.012, a = i / n * math.pi * 2, r = rand(5.5, 9), dh = rand(-1.5, 1.5) }
				table.insert(cloud.feathers, f)
			end
		end)
		local conn
		function cloud.stop()
			if conn then
				conn:Disconnect()
				conn = nil
			end
			for _, f in cloud.feathers do
				if f.part and not f.falling then
					f.part:Destroy()
				end
			end
			if HU.clouds[char] == cloud then
				HU.clouds[char] = nil
			end
		end
		conn = RunService.RenderStepped:Connect(function()
			local t = os.clock() - cloud.t0
			if t > 3 or not char.Parent then
				cloud.stop()
				return
			end
			if cloud.want then
				cloud.center = cloud.center:Lerp(cloud.want, 0.15)
			end
			for _, f in cloud.feathers do
				if f.part and not f.falling and os.clock() >= f.born then
					if not f.streak then
						f.streak = HU.streak(f.part, HU.LIT, 0.3, 0.14)
					end
					f.part.Transparency = 0
					-- up off the wing in a spiral that bends over to its place
					-- in the ring, then going round with it, point down
					local u = math.clamp((os.clock() - f.born) / 0.32, 0, 1)
					local a = f.a + t * 2.4
					local ring = cloud.center + Vector3.new(math.cos(a) * f.r, f.dh, math.sin(a) * f.r)
					local e = 1 - (1 - u) ^ 3
					local mid = f.from:Lerp(ring, 0.35) + UP * 12
					local p = (1 - e) ^ 2 * f.from + 2 * (1 - e) * e * mid + e * e * ring
					local v = u < 1 and (ring - f.from) or Vector3.new(0, -1, 0)
					f.part.CFrame = HU.along(p, u < 1 and (v + UP * 20) or v, a)
				end
			end
		end)
	end
	-- (round 86 review) which spots struck someone (the server's word): the
	-- screens break those up and fly the rest home
	function Effects.ScarletRainHits(char, data)
		local set = {}
		for _, i in (type(data) == "table" and type(data.Hit) == "table") and data.Hit or {} do
			if tonumber(i) then
				set[tonumber(i)] = true
			end
		end
		HU.rainHits[char] = { hit = set, t = os.clock() }
	end
	-- down out of the sky on the spots (the server's): a crimson ring on the
	-- street, then each one drops (a zip, a streak) and sticks in
	function Effects.ScarletRainFall(char, data)
		local center = typeof(data.Pos) == "Vector3" and data.Pos
		if not center then
			return
		end
		local spec = Config.FindAbilityById("ScarletRain") or {}
		local fall = tonumber(data.Fall) or 0.55
		local height = spec.RingHeight or tonumber(data.Height) or 18
		local radius = tonumber(data.Radius) or 12
		local t0 = os.clock()
		local cloud = HU.clouds[char]
		if cloud then
			cloud.want = center + UP * height
		end
		billboardRing(center + UP * 0.3, radius * 2.2, radius * 1.6, HU.LIT, 4, fall + 0.3)
		-- ((round 92) the red disc - the rain's whole area on the street, a
		-- hitbox - on his own screen only: Config.CycloneLook.RainDisc)
		if not VFX.CycloneLook or VFX.CycloneLook.rainDisc(char) then
			shockDisc(center + UP * 0.25, UP, radius * 2, radius * 2.1, fall + 0.35, Color3.fromRGB(255, 120, 110))
		end
		local spots = type(data.Spots) == "table" and data.Spots or {}
		for i, s in spots do
			local p = typeof(s.Pos) == "Vector3" and s.Pos
			if p then
				task.delay(tonumber(s.At) or 0, function()
					-- one from the ring if it's there, else out of the sky
					local f
					if cloud then
						for _, c in cloud.feathers do
							if c.part and not c.falling and os.clock() >= c.born then
								f = c
								break
							end
						end
					end
					local part, top
					if f then
						f.falling = true
						part = f.part
						top = part.CFrame.Position
					else
						top = p + Vector3.new(rand(-3, 3), height, rand(-3, 3))
						part = HU.rainBlade(HU.along(top, p - top))
						HU.streak(part, HU.LIT, 0.3, 0.14)
					end
					local len = part.Size.Y
					part.CFrame = HU.along(top, p - top)
					tween(part, fall, { CFrame = HU.stuck(p, p - top, len) }, Enum.EasingStyle.Quad, Enum.EasingDirection.In)
					if i % 3 == 1 then
						VFX.PlaySound("RainFall", top:Lerp(p, 0.5), 0.9)
					end
					task.delay(fall, function()
						if not part.Parent then
							return
						end
						-- stuck in, tilted; a flash of white and a ring round it,
						-- flecks, a puff, the thunk
						local dir = (p - top) + Vector3.new(rand(-6, 6), 0, rand(-6, 6))
						part.CFrame = HU.stuck(p, dir, len)
						shockDisc(p + UP * 0.12, UP, 0.5, 3.6, 0.22, HU.PALE)
						billboardRing(p + UP * 0.6, 0.6, 3.2, Color3.new(1, 1, 1), 2, 0.14)
						HK.flecks(p + UP * 0.4, 2, 0.8)
						dustPuffs(p, 0.3, 1, HK.DUST, 0.45, false)
						VFX.PlaySound("RainHit", p, 0.9)
						-- (this screen's guess for now: a blade in someone sparks)
						local guess = false
						for _, m in characterList() do
							if m:IsA("Model") and m ~= char then
								local r = m:FindFirstChild("HumanoidRootPart")
								if r and (r.Position - (p + UP * 2.5)).Magnitude < 3.2 then
									guess = true
								end
							end
						end
						if guess then
							sparks(p + UP * 2, 0.35, HK.EDGE, HU.RED, 4)
						end
						task.delay(0.5, function()
							if not part.Parent then
								return
							end
							-- (the server's word if it's come: a hit is spent, a
							-- miss is refunded - it flies home)
							local word = HU.rainHits[char]
							local hit = guess
							if word and word.t >= t0 then
								hit = word.hit[i] == true
							end
							if hit then
								HK.flecks(part.CFrame.Position, 3, 1)
								part:Destroy()
								return
							end
							local root = char:FindFirstChild("HumanoidRootPart")
							if not (root and root.Parent) then
								part:Destroy()
								return
							end
							local s = HK.launchSlots(char, 1)[1] or { side = 1, slot = "S1" }
							if HK.flyHome then
								-- (hawks_moves' kit: it flies home and clicks into the
								-- gap the refund opens)
								HK.flyHome(char, part.CFrame, s.side, s.slot, 120, UP * 18)
								part:Destroy()
								return
							end
							local to = HK.slotCF(char, s.side, s.slot)
							HU.streak(part, HU.PALE, 0.22, 0.2)
							tween(part, 0.4, { CFrame = to, Transparency = 0.5 }, Enum.EasingStyle.Quad, Enum.EasingDirection.In)
							task.delay(0.4, function()
								VFX.PlaySound("FeatherReturn", to.Position, 0.6)
								part:Destroy()
							end)
						end)
						cleanup(part, 2)
					end)
				end)
			end
		end
		task.delay(fall + 0.5, function()
			if cloud and HU.clouds[char] == cloud then
				cloud.stop()
			end
		end)
	end

	---------------------------------------------------------------------
	-- ult 2: TOO FAST - three cuts (the server carries him): each its own
	-- clip and ghosts down the line, and a hairline left hanging in the air;
	-- all of them open together at the end (SwiftCutHit, Chain)
	---------------------------------------------------------------------
	function Effects.TooFast(char, data, isLocal)
		local root = charParts(char)
		if not root then
			return
		end
		if isLocal and typeof(data.Dir) == "Vector3" then
			face(root, data.Dir)
		end
		HK.blades(char, true)
		VFX.Pose(char, "HawksCoil", 0.12)
		HK.setWing(char, "Tuck", 1.1, 30)
		VFX.PlaySound("FeatherDraw", root.Position, 1)
		local g = groundPoint(root.Position)
		if (root.Position - g).Magnitude < 4.5 then
			dustPuffs(g, 0.6, HU.n(6), HK.DUST, 0.5, false)
		end
		HU.cuts[char] = {}
		if isLocal and VFX.MANGA then
			VFX.MANGA.lines(1.1, { Kind = "stream", Colors = { HU.LIT, HU.PALE, Color3.new(1, 1, 1) }, Angle = -14, Alpha = 0.55, Count = 18 })
		end
	end
	function Effects.TooFastCut(char, data)
		local root = charParts(char)
		local from, to = typeof(data.From) == "Vector3" and data.From, typeof(data.To) == "Vector3" and data.To
		if not root or not from or not to then
			return
		end
		local k = math.clamp(math.floor(tonumber(data.Index) or 1), 1, 3)
		local time = tonumber(data.Time) or 0.16
		VFX.Motion(char, "HawksTooFast" .. k)
		HK.setWing(char, k == 3 and "Flare" or "Tuck", time + 0.1, 30)
		local span = to - from
		local len = span.Magnitude
		if len > 1 then
			local d = span.Unit
			local mid = (from + to) / 2 + UP * 0.6
			-- the hairline left hanging where the blade went
			local line = newPart(Vector3.new(0.14, 0.14, len), CFrame.lookAt(mid, mid + d), Color3.fromRGB(255, 70, 60), Enum.Material.Neon)
			line.Name = "HawksCutLine"
			line.Transparency = 1
			tween(line, time, { Transparency = 0 })
			cleanup(line, 2.2)
			HU.cuts[char] = HU.cuts[char] or {}
			table.insert(HU.cuts[char], { part = line, cf = CFrame.lookAt(mid, mid + d), len = len })
			-- the blade's sweep: a flat smear of light along it, gone at once
			local smear = newPart(Vector3.new(0.05, 2.4, len), CFrame.lookAt(mid, mid + d) * CFrame.Angles(0, 0, math.rad(k == 2 and 60 or (k == 3 and 90 or 0))), HU.EDGE, Enum.Material.Neon)
			smear.Name = "HawksCutSmear"
			smear.Transparency = 0.45
			tween(smear, 0.16, { Transparency = 1, Size = Vector3.new(0.05, 0.4, len) })
			cleanup(smear, 0.18)
			for i = 1, HU.n(4) do
				task.delay((i - 1) * time / 4, function()
					if root.Parent then
						afterimage(char, i % 2 == 0 and HU.LIT or Color3.fromRGB(255, 150, 140), 0.24)
					end
				end)
			end
			streaks(from, d, HU.n(7), 1.2, 9, len * 0.7, WIND, 0.22)
			shockDisc(from, d, 1.5, 9, 0.22, WIND, 3)
		end
		VFX.PlaySound("TooFastCut", from, 1)
	end
	-- the chain's end: every line he left opens at once
	local swiftHit = Effects.SwiftCutHit
	function Effects.SwiftCutHit(char, data, ...)
		if type(data) == "table" and data.Chain and HU.cuts[char] then
			local lines = HU.cuts[char]
			HU.cuts[char] = nil
			local delay = tonumber(data.Delay) or 0.25
			-- (round 86 review) with hawks_moves' kit in (HK.impact), its
			-- SwiftCutHit already draws the slash across each of them, the
			-- impact frame and the split for the chain's end - this only opens
			-- the lines he left hanging (one owner for each)
			local theirs = HK.impact ~= nil
			task.delay(delay, function()
				for _, c in lines do
					if c.part.Parent then
						for _, s in { 1, -1 } do
							local half = newPart(Vector3.new(0.09, 0.06, c.len), c.cf, Color3.fromRGB(255, 120, 100), Enum.Material.Neon)
							half.Name = "HawksCutLine"
							tween(half, 0.32, { CFrame = c.cf * CFrame.new(0, s * 0.7, 0) * CFrame.Angles(0, 0, math.rad(s * 9)), Transparency = 1 })
							cleanup(half, 0.34)
						end
						-- (round 86 review) a flare of light all along it as it
						-- opens (two crossed planes: it reads from any side at
						-- 30 studs), flecks shed down its length
						for _, size in { Vector3.new(1.1, 0.05, c.len), Vector3.new(0.05, 1.1, c.len) } do
							local flare = newPart(size, c.cf, Color3.new(1, 1, 1), Enum.Material.Neon)
							flare.Name = "HawksCutFlare"
							flare.Transparency = 0.1
							tween(flare, 0.12, { Transparency = 1, Size = Vector3.new(size.X * 0.1, size.Y * 0.1, c.len * 1.06) }, Enum.EasingStyle.Quad, Enum.EasingDirection.Out)
							cleanup(flare, 0.14)
						end
						local n = HU.n(4)
						for k = 1, n do
							HK.flecks((c.cf * CFrame.new(0, 0, (k / (n + 1) - 0.5) * c.len)).Position, 2, 1)
						end
						c.part:Destroy()
					end
				end
				local struck = type(data.Targets) == "table" and data.Targets or {}
				local first
				for _, t in struck do
					local tr = typeof(t) == "Instance" and t:FindFirstChild("HumanoidRootPart")
					if tr then
						first = first or tr.Position
						shockDisc(tr.Position, UP, 1, 8, 0.25, HU.EDGE)
						if not theirs then
							for _ = 1, 3 do
								HU.slash(tr.Position + Vector3.new(rand(-0.5, 0.5), rand(-1, 1), rand(-0.5, 0.5)), rand(3, 4.5), 0.2, Color3.fromRGB(255, 90, 80))
							end
						end
					end
				end
				if first then
					VFX.PlaySound("TooFastOpen", first, 1)
					if not theirs and HU.mine(char) and VFX.MANGA then
						VFX.MANGA.impact(first, 0.07, { Radius = 120 })
					end
				end
			end)
		end
		if swiftHit then
			return swiftHit(char, data, ...)
		end
	end

	---------------------------------------------------------------------
	-- ult 3: CYCLONE: TEMPEST - the cyclone (HK.cyclone), and over it: the
	-- wings thrown up to Max, his arms up conducting it, an outer ring of
	-- shards and ribbons of wind going up round it, the street's dust drawn in
	---------------------------------------------------------------------
	function Effects.PlumeTempest(char, data, isLocal)
		HK.cyclone(char, "PlumeTempest", true, isLocal) -- ((round 92) isLocal: his reach ring)
		local root = charParts(char)
		if not root then
			return
		end
		local spec = Config.FindAbilityById("PlumeTempest") or {}
		local max = (spec.Hold and spec.Hold.Max) or 2.5
		local R = spec.Radius or 9.8
		VFX.Pose(char, "HawksTempest", max + 0.2)
		HK.setWing(char, "Max", max + 0.4, 18)
		VFX.PlaySound("TempestRoar", root.Position, 1)
		local old = HU.tempests[char]
		if old then
			old.stop()
		end
		local tp = { t0 = os.clock(), anchors = {}, beams = {} }
		HU.tempests[char] = tp
		-- (round 86 review) hawks_moves' cyclone (HK.homeward: its kit is in)
		-- brings its own sheets of wind and the dust drawn in: this layer is
		-- only the outer ring then, thinner, and no dust of its own
		local theirs = HK.homeward ~= nil
		tp.theirs = theirs
		local count = HU.n(theirs and 4 or 6)
		for i = 1, count do
			local holder = newPart(Vector3.one * 0.2, root.CFrame, HU.RED)
			holder.Name = "HawksTempest"
			holder.Transparency = 1
			local pe = HU.emitter(holder, { Rate = HU.n(50), Speed0 = 10, Speed1 = 22, Spread = 25, Drag = 2.5, Life0 = 0.35, Life1 = 0.6, Size = 0.55, Accel = Vector3.new(0, 6, 0) })
			table.insert(tp.anchors, { part = holder, pe = pe, a = i / count * math.pi * 2, h = rand(0.5, 6), w = 6.5 })
		end
		local holder = newPart(Vector3.one * 0.2, root.CFrame, HU.RED)
		holder.Name = "HawksTempest"
		holder.Transparency = 1
		tp.holder = holder
		for i = 1, HU.n(4) do
			local a0, a1 = Instance.new("Attachment"), Instance.new("Attachment")
			a0.Parent, a1.Parent = holder, holder
			local b = Instance.new("Beam")
			b.Name = "HawksRibbon"
			b.Attachment0, b.Attachment1 = a0, a1
			b.Color = CS(Color3.fromRGB(255, 236, 226), HU.RED)
			b.Transparency = NS({ NK(0, 1), NK(0.3, 0.5), NK(0.75, 0.6), NK(1, 1) })
			b.Width0, b.Width1 = 1.2, 0.3
			b.LightEmission = 0.45
			b.FaceCamera = true
			b.Segments = 12
			b.Parent = holder
			table.insert(tp.beams, { a0 = a0, a1 = a1, beam = b, a = i / 4 * math.pi * 2, h = (i - 0.5) / 4 })
		end
		local conn
		function tp.stop()
			if conn then
				conn:Disconnect()
				conn = nil
			end
			for _, a in tp.anchors do
				a.pe.Enabled = false
				cleanup(a.part, 0.7)
			end
			cleanup(holder, 0.05)
			if HU.tempests[char] == tp then
				HU.tempests[char] = nil
			end
		end
		local pulse = 0
		conn = RunService.RenderStepped:Connect(function()
			local t = os.clock() - tp.t0
			local held = char:GetAttribute("Holding") == "PlumeTempest"
			if (t > 0.45 and not held) or t > max + 0.8 or not root.Parent or not HU.alive(char) then
				tp.stop()
				return
			end
			local c = root.Position
			for _, a in tp.anchors do
				local ang = a.a + a.w * t
				local p = c + Vector3.new(math.cos(ang) * R * 1.2, a.h - 2, math.sin(ang) * R * 1.2)
				a.part.CFrame = CFrame.lookAt(p, p + Vector3.new(-math.sin(ang), 0.2, math.cos(ang)))
			end
			holder.CFrame = CFrame.new(c)
			for _, b in tp.beams do
				local ang = b.a + 5.5 * t
				local rr = R * (0.8 + 0.5 * b.h)
				local h = -2 + 9 * b.h
				local span = 1.2
				b.a0.CFrame = CFrame.fromMatrix(Vector3.new(math.cos(ang) * rr, h, math.sin(ang) * rr), Vector3.new(-math.sin(ang), 0, math.cos(ang)), UP)
				b.a1.CFrame = CFrame.fromMatrix(Vector3.new(math.cos(ang + span) * rr, h + 3, math.sin(ang + span) * rr), Vector3.new(-math.sin(ang + span), 0, math.cos(ang + span)), UP)
				local cs = 4 / 3 * math.tan(span / 4) * rr
				b.beam.CurveSize0, b.beam.CurveSize1 = cs, cs
			end
			if t >= pulse and not theirs then
				pulse = t + 0.45
				local g = groundPoint(c)
				if (c - g).Magnitude < 6 then
					billboardRing(g + UP * 0.6, R * 2.8, R * 1.3, Color3.fromRGB(255, 215, 205), 3, 0.4)
					dustPuffs(g + Vector3.new(rand(-1, 1), 0, rand(-1, 1)) * R, 0.5, 1, HK.DUST, 0.6, false)
				end
			end
		end)
	end
	-- and its burst: bigger than the cyclone's - red slashes flung out round it
	local cycloneBurst = Effects.PlumeCycloneBurst
	function Effects.PlumeCycloneBurst(char, data, ...)
		if cycloneBurst then
			cycloneBurst(char, data, ...)
		end
		if type(data) == "table" and data.Tempest then
			local tp = HU.tempests[char]
			if tp then
				tp.stop()
			end
			local root = charParts(char)
			local c = typeof(data.Pos) == "Vector3" and data.Pos or (root and root.Position)
			if not c then
				return
			end
			local R = tonumber(data.Radius) or 16
			-- (round 86 review) hawks_moves' burst throws its own starburst of
			-- streaks and a ring: then only the crimson knives and the flash here
			local theirs = HK.homeward ~= nil
			for i = 1, theirs and 0 or HU.n(10) do
				local a = i / 10 * math.pi * 2 + rand(-0.15, 0.15)
				local d = Vector3.new(math.cos(a), rand(-0.05, 0.25), math.sin(a)).Unit
				local p0 = c + d * 2
				local s = newPart(Vector3.new(0.12, 0.12, 4), CFrame.lookAt(p0, p0 + d), HU.EDGE, Enum.Material.Neon)
				s.Name = "HawksSlash"
				tween(s, 0.25, { CFrame = CFrame.lookAt(c + d * R, c + d * (R + 1)), Size = Vector3.new(0.04, 0.04, 7), Transparency = 1 }, Enum.EasingStyle.Quad, Enum.EasingDirection.Out)
				cleanup(s, 0.27)
			end
			HU.shards(CFrame.new(c + UP * 2), HU.n(theirs and 60 or 120), 60, { Spread = 180 })
			if not theirs then
				billboardRing(c + UP * 2, 4, R * 2.4, HU.SUN_MID, 6, 0.3)
			end
			if nearCamera(c, 40) then
				VFX.Hooks.Flash(Color3.fromRGB(255, 220, 210), 0.08)
			end
		end
	end

