		held = {}, -- [the body on his feathers] = { victim, vroot, carrier, croot, ... } (this screen's hold)
		pressed = {}, -- [his body] = os.clock() his own key played the follow-up's clip
		drills = {}, -- [his body] = the drill in his hands / on its way
		burst = {}, -- [his body] = os.clock() his drill last burst on this screen (cleared after)
		bound = false,
		SKY = Color3.fromRGB(150, 212, 255),
		GOLD = Color3.fromRGB(255, 196, 92),
		SCRATCH = Color3.fromRGB(64, 34, 36),
	}
	VFX.HA = HA
	local function spec(id)
		return Config.FindAbilityById(id) or {}
	end
	local function low()
		return IceKit.lowEnd()
	end
	local function flatUnit(v, fallback)
		return Config.HawksAir.flatUnit(v, fallback)
	end
	local function unitOr(v, fallback)
		if typeof(v) == "Vector3" and v == v and v.Magnitude > 1e-3 then
			return v.Unit
		end
		return fallback or UP
	end
	local function isMine(char)
		local lp = Players.LocalPlayer
		return lp ~= nil and char ~= nil and lp.Character == char
	end
	-- a ring of air thrown out (the kit's shockDisc, with an up of its own
	-- when it faces straight up or down: never a lookAt along its own up)
	function HA.disc(pos, dir, fromD, toD, time, color, travel)
		dir = unitOr(dir, UP)
		local up = math.abs(dir.Y) > 0.99 and Vector3.zAxis or UP
		local base = CFrame.lookAt(pos, pos + dir, up) * CFrame.Angles(0, math.pi / 2, 0)
		local p = newPart(Vector3.new(0.5, fromD, fromD), base, color or WIND, Enum.Material.ForceField, Enum.PartType.Cylinder)
		local goal = { Size = Vector3.new(0.5, toD, toD), Transparency = 1 }
		if travel then
			goal.CFrame = base + dir * travel
		end
		tween(p, time, goal)
		cleanup(p, time + 0.05)
		return p
	end
	-- a point off the wire: a real one, or nil (never a NaN into a CFrame)
	local function vec(v)
		return (typeof(v) == "Vector3" and v == v) and v or nil
	end

